/**
 * agent-tools/content-plugins.js — C3 (M2-10): Copilot context activation
 *
 * Lets read_page / search read tutorial snippets shipped by *content plugins*.
 *
 * Content plugins (M2-9, in progress) are expected to register themselves on
 * `globalThis._petriContentPlugins` as an array of objects with at least:
 *   {
 *     id:        'deseq2-tutorial',
 *     title:     'DESeq2 差异分析教程',
 *     docs:      [ { slug:'quickstart', title:'快速上手', file:'/abs/path/quickstart.md' } ],
 *     docsDir:   '/abs/path/to/docs',           // optional, used as scan root
 *     manifest:  { ... }                         // optional plugin manifest
 *   }
 *
 * If the registry is not populated yet (M2-9 not landed), this module falls
 * back to scanning a configurable content-plugins directory on disk so the
 * Copilot can already read shipped md snippets. The scan root is resolved from
 * (in order):
 *   1. globalThis._petriContentPlugins           (M2-9 runtime registry)
 *   2. process.env.PETRI_CONTENT_PLUGINS_DIR     (explicit override)
 *   3. <repo>/content-plugins                    (convention)
 *   4. <repo>/desktop-app/resources/content-plugins
 *
 * Each discovered plugin contributes its *.md files. Files are read lazily and
 * cached for CONTENT_PLUGIN_TTL ms.
 */

const fs = require('fs');
const path = require('path');

const CONTENT_PLUGIN_TTL = 5 * 60 * 1000; // 5 min

let _cache = null; // { plugins: [...], ts: number }

// --------------------------------------------------------------
// Candidate roots for the on-disk fallback scan
// --------------------------------------------------------------
function _candidateRoots() {
  const roots = [];
  if (process.env.PETRI_CONTENT_PLUGINS_DIR) roots.push(process.env.PETRI_CONTENT_PLUGINS_DIR);
  // petri-server is at <repo>/petri-server; repo root is two levels up from this file
  const repoRoot = path.resolve(__dirname, '..', '..');
  roots.push(path.join(repoRoot, 'content-plugins'));
  // 去 submodule 后：core 内嵌在 desktop 仓根 core/ 下，content-plugins 在 desktop 仓根 resources/
  // petri-server/agent-tools/ → petri-server → core → desktop 仓根 → resources/content-plugins
  const splitPath = path.resolve(__dirname, '..', '..', '..', 'resources', 'content-plugins');
  roots.push(splitPath);
  if (process.resourcesPath) {
    roots.push(path.join(process.resourcesPath, 'content-plugins'));
  }
  return roots;
}

function _listMdFiles(dir, baseDir) {
  const out = [];
  let entries;
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch {
    return out;
  }
  for (const e of entries) {
    const full = path.join(dir, e.name);
    if (e.isDirectory()) {
      // skip node_modules / hidden dirs
      if (e.name === 'node_modules' || e.name.startsWith('.')) continue;
      out.push(..._listMdFiles(full, baseDir));
    } else if (e.isFile() && e.name.endsWith('.md')) {
      const rel = path.relative(baseDir, full).replace(/\\/g, '/');
      // Derive a slug from the relative path without extension
      const slug = rel.replace(/\.md$/i, '');
      out.push({ slug, file: full, rel });
    }
  }
  return out;
}

function _extractTitle(filePath, fallbackSlug) {
  try {
    const head = fs.readFileSync(filePath, 'utf-8').slice(0, 600);
    // 1) frontmatter `title:`
    const fm = head.match(/^---\s*\n([\s\S]*?)\n---/);
    if (fm) {
      const t = fm[1].match(/^title:\s*(.+)/m);
      if (t && t[1]) return t[1].replace(/^["']|["']$/g, '').trim();
      const sb = fm[1].match(/^sidebar_(?:label|position):\s*(.+)/m);
      if (sb && sb[1]) return sb[1].replace(/^["']|["']$/g, '').trim();
    }
    // 2) first H1
    const h1 = head.match(/^#\s+(.+)/m);
    if (h1 && h1[1]) return h1[1].trim();
  } catch {}
  return fallbackSlug;
}

function _scanDiskPlugins() {
  const plugins = [];
  for (const root of _candidateRoots()) {
    let pluginDirs;
    try {
      pluginDirs = fs.readdirSync(root, { withFileTypes: true }).filter(
        (e) => e.isDirectory() && !e.name.startsWith('.') && e.name !== 'node_modules'
      );
    } catch {
      continue;
    }
    for (const pd of pluginDirs) {
      const pluginDir = path.join(root, pd.name);
      // docs/ subdir is the convention; if absent, treat the plugin dir itself
      const docsDir = fs.existsSync(path.join(pluginDir, 'docs'))
        ? path.join(pluginDir, 'docs')
        : pluginDir;
      const files = _listMdFiles(docsDir, docsDir);
      if (files.length === 0) continue;
      const docs = files.map((f) => ({
        slug: f.slug,
        title: _extractTitle(f.file, f.slug),
        file: f.file,
      }));
      plugins.push({
        id: pd.name,
        title: pd.name,
        docsDir,
        docs,
      });
    }
    if (plugins.length > 0) break; // first root that yields plugins wins
  }
  return plugins;
}

/**
 * Return the list of content plugins (runtime registry first, disk fallback).
 * Shape: [{ id, title, docs:[{slug,title,file}], docsDir }]
 */
function getContentPlugins() {
  // 1) M2-9 runtime registry
  const registry = globalThis._petriContentPlugins;
  if (Array.isArray(registry) && registry.length > 0) {
    return registry.map((p) => ({
      id: p.id,
      title: p.title || p.id,
      docs: Array.isArray(p.docs) ? p.docs : [],
      docsDir: p.docsDir,
    }));
  }
  // 2) disk fallback (cached)
  if (_cache && Date.now() - _cache.ts < CONTENT_PLUGIN_TTL) {
    return _cache.plugins;
  }
  const plugins = _scanDiskPlugins();
  _cache = { plugins, ts: Date.now() };
  return plugins;
}

/** Invalidate the disk-scan cache (used by tests / after plugin install). */
function invalidateContentPluginCache() {
  _cache = null;
}

// --------------------------------------------------------------
// Read helpers
// --------------------------------------------------------------
const MAX_SNIPPET_CHARS = 8000;

/**
 * Read a single plugin doc by pluginId + slug.
 * Returns { kind:'plugin', pluginId, slug, title, content } or { error }.
 */
function readPluginDoc(pluginId, slug) {
  const plugins = getContentPlugins();
  const plugin = plugins.find((p) => p.id === pluginId);
  if (!plugin) return { error: 'plugin_not_found', message: '未知内容插件: ' + pluginId };
  const doc = (plugin.docs || []).find(
    (d) => d.slug === slug || d.slug === String(slug).replace(/^\//, '')
  );
  if (!doc) return { error: 'doc_not_found', message: `插件 ${pluginId} 未找到文档: ${slug}` };
  try {
    const text = fs.readFileSync(doc.file, 'utf-8');
    return {
      kind: 'plugin',
      pluginId,
      slug,
      title: doc.title || slug,
      content: text.slice(0, MAX_SNIPPET_CHARS),
    };
  } catch (e) {
    return { error: 'read_failed', message: String(e && e.message || e) };
  }
}

/**
 * Parse a plugin-scoped URL of the form /plugin/<pluginId>/<slug...> or
 * /plugins/<pluginId>/<slug...>. Returns { pluginId, slug } or null.
 */
function parsePluginUrl(url) {
  const m = String(url).match(/^\/plugins?\/([^/]+)\/?(.*)$/);
  if (!m) return null;
  return { pluginId: decodeURIComponent(m[1]), slug: m[2] || 'index' };
}

/**
 * Lexical search across plugin doc titles + first chunk of content.
 * Returns [{ kind:'plugin', pluginId, slug, title, url, summary, relevance }].
 */
function searchPluginDocs(q, topK) {
  const ql = String(q || '').toLowerCase().trim();
  if (!ql) return [];
  topK = Math.max(1, Math.min(15, topK || 5));
  const tokens = ql.split(/\s+/).filter((t) => t.length >= 2);
  if (tokens.length === 0) return [];
  const plugins = getContentPlugins();
  const results = [];
  for (const plugin of plugins) {
    for (const doc of plugin.docs || []) {
      const title = doc.title || doc.slug;
      let body = '';
      try {
        body = fs.readFileSync(doc.file, 'utf-8').slice(0, 2000);
      } catch {}
      const haystack = (title + ' ' + body).toLowerCase();
      let score = 0;
      for (const t of tokens) {
        if (haystack.includes(t)) score += 1;
      }
      if (score > 0) {
        // summarize: first non-frontmatter, non-H1 paragraph
        let summary = body
          .replace(/^---[\s\S]*?---/, '')
          .replace(/^#{1,6}\s+.*$/gm, '')
          .trim()
          .split(/\n\s*\n/)[0];
        summary = summary.replace(/\s+/g, ' ').trim().slice(0, 200);
        results.push({
          kind: 'plugin',
          pluginId: plugin.id,
          title,
          slug: doc.slug,
          url: `/plugin/${plugin.id}/${doc.slug}`,
          summary,
          relevance: score / tokens.length,
        });
      }
    }
  }
  results.sort((a, b) => (b.relevance || 0) - (a.relevance || 0));
  return results.slice(0, topK);
}

/**
 * Render a compact catalog of plugin docs for system-prompt injection.
 */
function renderContentPluginsForPrompt(maxChars) {
  const plugins = getContentPlugins();
  if (!plugins || plugins.length === 0) return '';
  maxChars = maxChars || 1200;
  let out = '\n\n=== 已装内容插件教程片段 ===\n';
  out += '注：分析现场卡住、不确定某工具/流程怎么用时，用 read_page(url="/plugin/<id>/<slug>") 或 search 查对应教程片段。\n';
  for (const plugin of plugins) {
    out += `\n[plugin:${plugin.id}]${plugin.title ? ' ' + plugin.title : ''}`;
    for (const doc of (plugin.docs || []).slice(0, 12)) {
      const line = `\n- /plugin/${plugin.id}/${doc.slug} — ${doc.title || doc.slug}`;
      if (out.length + line.length > maxChars) {
        out += '\n... (more)';
        return out;
      }
      out += line;
    }
  }
  return out;
}

module.exports = {
  getContentPlugins,
  invalidateContentPluginCache,
  readPluginDoc,
  parsePluginUrl,
  searchPluginDocs,
  renderContentPluginsForPrompt,
  MAX_SNIPPET_CHARS,
};

'use strict';

/**
 * BLOCK-85 P3 — 格物联邦 Agent 委托（D4）。
 *
 * delegate_to_petri_node：指挥席 agent 把一段工作委托给协作成员的 agent——
 * 对端 POST /api/ai/agent 开独立会话后台跑（AGENT_TASK_MODE，返回 taskId），
 * 本端轮询对端 /api/ai/agent/task/:taskId/meta 至终态，回执 = 终态状态 +
 * 对端会话最后一条 assistant 消息摘要（产物引用含其中）。真值在对端会话。
 */

const path = require('node:path');

const DELEGATE_POLL_INTERVAL_MS = 5_000;
const DELEGATE_DEFAULT_TIMEOUT_MS = 10 * 60_000;
const REQUEST_TIMEOUT_MS = 20_000;

function resolveFederationDataDir() {
  return process.env.PETRI_LOCAL_DATA_DIR
    || process.env.LOCAL_DATA_DIR
    || path.join(require('os').homedir(), 'Documents', 'Petri-Local');
}

async function peerFetch(peer, token, pathName, { method = 'GET', body = null, timeoutMs = REQUEST_TIMEOUT_MS } = {}) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const response = await fetch(`${peer.baseUrl}${pathName}`, {
      method,
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${token}`,
      },
      body: body ? JSON.stringify(body) : undefined,
      signal: controller.signal,
    });
    const data = await response.json().catch(() => ({}));
    return { status: response.status, data };
  } finally {
    clearTimeout(timer);
  }
}

const TERMINAL_AGENT_STATUSES = new Set(['completed', 'failed', 'cancelled', 'done', 'error']);

async function tool_delegate_to_petri_node(args = {}) {
  const peerId = String(args.peerId || '').trim();
  const task = String(args.task || '').trim();
  const projectId = typeof args.projectId === 'string' ? args.projectId.trim() : '';
  const timeoutMs = Math.min(Math.max(Number(args.timeoutMinutes) || 10, 1), 30) * 60_000;
  if (!peerId) return { error: 'missing_peer_id', message: '缺少 peerId（协作成员 ID，联邦面板可见）' };
  if (!task) return { error: 'missing_task', message: '缺少 task（要委托给对方 agent 的工作描述）' };

  const federation = require('../../shared-backend/federation-peers');
  const dataDir = resolveFederationDataDir();
  const peer = federation.getPeer(dataDir, peerId);
  if (!peer) return { error: 'unknown_peer', message: '协作成员不存在或已移除：' + peerId };
  const token = federation.getPeerToken(dataDir, peerId) || '';

  // 0. BLOCK-88 P3（D4）— 发现面：列本工程师在对端的被授权项目（附项目名），
  // 无 projectId 但对端有授权项目时在回执中提示（写类委托需带 projectId 重发）。
  let grantedProjects = null;
  try {
    const mine = await peerFetch(peer, token, '/federation/api/granted-projects');
    if (mine.status === 200 && mine.data?.ok) grantedProjects = mine.data.projects || [];
  } catch { /* 发现失败不阻塞委托 */ }

  // 1. 发起对端 agent 会话（后台任务模式）
  let started;
  try {
    started = await peerFetch(peer, token, '/api/ai/agent', {
      method: 'POST',
      body: {
        messages: [{ role: 'user', content: task }],
        ...(projectId ? { context: { projectId } } : {}),
      },
      timeoutMs: 60_000,
    });
  } catch (error) {
    return { error: error.name === 'AbortError' ? 'peer_timeout' : 'peer_unreachable', message: `无法连接协作成员「${peer.name}」` };
  }
  if (started.status === 401) {
    return { error: 'federation_session_invalid', message: `协作成员「${peer.name}」的会话已失效，请在联邦面板重新配对` };
  }
  if (started.status === 403) {
    return {
      error: 'federation_project_not_granted',
      message: (started.data && started.data.message) || `未被授权访问对端项目 ${projectId}（宿主默认零授权，请宿主在联邦面板逐项目授权）`,
      grantedProjects: grantedProjects || [],
    };
  }
  const taskId = started.data && (started.data.taskId || (started.data.data && started.data.data.taskId));
  if (started.status !== 200 || !taskId) {
    return { error: 'delegate_start_failed', message: `协作成员「${peer.name}」未能启动委托任务`, peerStatus: started.status, detail: started.data };
  }
  const conversationId = (started.data && started.data.conversationId) || null;

  // 2. 轮询终态
  const deadline = Date.now() + timeoutMs;
  let meta = null;
  while (Date.now() < deadline) {
    await new Promise((resolve) => setTimeout(resolve, DELEGATE_POLL_INTERVAL_MS));
    try {
      const poll = await peerFetch(peer, token, `/api/ai/agent/task/${encodeURIComponent(taskId)}/meta`);
      if (poll.status === 200 && poll.data?.ok) {
        meta = poll.data;
        if (TERMINAL_AGENT_STATUSES.has(String(meta.agentStatus || '').toLowerCase())) break;
      } else if (poll.status === 404) {
        return { error: 'delegate_task_lost', message: `协作成员「${peer.name}」上找不到委托任务（可能已重启清理）`, peerTaskId: taskId };
      }
    } catch { /* 单次轮询失败容忍，继续到 deadline */ }
  }
  if (!meta || !TERMINAL_AGENT_STATUSES.has(String(meta.agentStatus || '').toLowerCase())) {
    return {
      error: 'delegate_timeout',
      message: `委托超时（${Math.round(timeoutMs / 60_000)} 分钟）。任务仍在协作成员「${peer.name}」上运行：taskId=${taskId}${conversationId ? ` conversationId=${conversationId}` : ''}`,
      peerTaskId: taskId,
    };
  }

  // 3. 回执：终态状态 + 对端会话末条 assistant 回复摘要
  let reply = null;
  try {
    const messages = await peerFetch(peer, token, `/api/ai/conversations/${encodeURIComponent(conversationId)}/messages`);
    const list = messages.data?.messages || messages.data?.data?.messages || [];
    const lastAssistant = [...list].reverse().find((m) => m.role === 'assistant' || m.sender === 'assistant');
    if (lastAssistant) reply = String(lastAssistant.content || '').slice(0, 4000);
  } catch { /* 回执内容拿不到时诚实降级为状态回执 */ }

  return {
    // 终态命名：对端 chat.js task 模式正常完成标 'done'，部分路径标 'completed'——
    // 只认 completed 会把对端正常完成误报为 error（BLOCK-85 双真机 P3 实测踩中）。
    ok: ['completed', 'done'].includes(String(meta.agentStatus || '').toLowerCase()),
    peerName: peer.name,
    peerTaskId: taskId,
    agentStatus: meta.agentStatus,
    reply,
    projectId: projectId || null,
    // BLOCK-88 P3（D4）— 未带 projectId 时回执附被授权项目（写类委托按此重发）
    ...(projectId ? {} : { grantedProjects: grantedProjects || [] }),
    note: '任务真值保存在协作成员的会话中，可在其界面中查看完整过程',
  };
}

module.exports = {
  tool_delegate_to_petri_node,
};

'use strict';

/**
 * agent-tools/knowledge-console-tools.js — BLOCK-99 G4 空间管理会话台工具族
 *
 * /knowledge 页内嵌会话台（D3 独立轻量面）用自然语言驱动知识空间的**内容组织**：
 * 空间集合/命名/启停/文档归属/删除/重建索引/状态查询（诚实边界：不控制面板 UI
 * 布局代码本身）。与手动 UI 操作同一套 helpers 底层（双通道同一真相）。
 *
 * D7 边界：只读 + 非破坏全开；破坏性三件（删空间/清空/批量删文档）走 D4 确认门
 * —— 首调返回影响面 + 一次性 confirmToken（helpers/knowledge-confirm.js），须用户
 * 在会话中明确确认后凭 token 重调（与 run_tool ack 先例同型，但服务端硬闸校验
 * action+subject 绑定）。
 *
 * 子集绑定：context.toolSubset === 'knowledge-console' 时 run 只携带本白名单 +
 * knowledge_search/status/read 三件既有工具；其余 50+ 通用工具（exec/write/spawn
 * 等）不进入请求。policy 层（plan 模式/只读档）仍然全量生效，这里是纵深防御的
 * 最外层收窄。
 */

const ks = require('../helpers/knowledge-space');
const ingest = require('../helpers/knowledge-ingest');
const confirmStore = require('../helpers/knowledge-confirm');

const DOC_LIST_LIMIT = 50;
const GATED_ACTIONS = new Set(['knowledge_space_delete', 'knowledge_space_clear', 'knowledge_doc_delete']);

function errResult(code, message) {
  return { error: code, message };
}

// helpers 层抛 {code,message} Error → 工具层诚实错误形状（不假成功）
function fromHelperError(e, fallbackCode) {
  const code = (e && e.code) || fallbackCode || 'knowledge_error';
  return errResult(code, (e && e.message) || String(e));
}

// ── 只读 ────────────────────────────────────────────────

function tool_knowledge_space_list() {
  const spaces = ks.listSpaces();
  return {
    spaces: spaces.map((s) => ({
      id: s.id,
      name: s.name,
      enabled: !!s.enabled,
      documents: s.documents,
      chunks: s.chunks,
      isDefault: s.id === ks.SPACE_ID,
    })),
    message: spaces.map((s) => `${s.name}(${s.id})${s.enabled ? '启用' : '停用'} · 文档 ${s.documents} · 块 ${s.chunks}${s.id === ks.SPACE_ID ? ' · 默认空间' : ''}`).join('；') || '尚无空间。',
  };
}

function tool_knowledge_space_impact(args) {
  try {
    const spaceId = ks.resolveSpaceId(args && args.spaceId);
    const space = ks.getSpace(spaceId);
    return { spaceId, spaceName: space.name, isDefault: spaceId === ks.SPACE_ID, ...ks.spaceImpact(spaceId) };
  } catch (e) {
    return fromHelperError(e, 'space_not_found');
  }
}

function tool_knowledge_doc_list(args) {
  try {
    const spaceId = ks.resolveSpaceId(args && args.spaceId);
    const statusFilter = String((args && args.status) || '').trim();
    const space = ks.getSpace(spaceId);
    let docs = ks.listDocuments(spaceId);
    const total = docs.length;
    if (statusFilter) docs = docs.filter((d) => d.status === statusFilter);
    return {
      spaceId,
      spaceName: space.name,
      spaceEnabled: !!space.enabled,
      total,
      documents: docs.slice(0, DOC_LIST_LIMIT).map((d) => ({
        id: d.id,
        name: d.name,
        status: d.status,
        chunks: d.chunk_count,
        error: d.error || undefined,
      })),
      truncated: docs.length > DOC_LIST_LIMIT ? DOC_LIST_LIMIT : undefined,
      message: `空间「${space.name}」共 ${total} 篇文档。`,
    };
  } catch (e) {
    return fromHelperError(e, 'space_not_found');
  }
}

// ── 非破坏写 ────────────────────────────────────────────

function tool_knowledge_space_create(args) {
  const name = String((args && args.name) || '').trim();
  if (!name) return errResult('space_name_required', 'knowledge_space_create 需要非空 name（1..60 字符）。');
  try {
    const space = ks.createSpace(name);
    return { space: { id: space.id, name: space.name, enabled: !!space.enabled }, message: `已创建空间「${space.name}」（${space.id}，默认停用，可用 knowledge_space_enable 启用）。` };
  } catch (e) {
    return fromHelperError(e, 'space_name_invalid');
  }
}

function tool_knowledge_space_rename(args) {
  const spaceId = String((args && args.spaceId) || '').trim();
  const name = String((args && args.name) || '').trim();
  if (!spaceId || !name) return errResult('space_rename_args_required', 'knowledge_space_rename 需要 spaceId 与 name。');
  try {
    const space = ks.renameSpace(spaceId, name);
    return { space: { id: space.id, name: space.name }, message: `已改名为「${space.name}」。` };
  } catch (e) {
    return fromHelperError(e, 'space_not_found');
  }
}

function tool_knowledge_space_enable(args) {
  const enabled = args && args.enabled;
  if (typeof enabled !== 'boolean') {
    return errResult('enabled_required', 'knowledge_space_enable 需要 boolean enabled（true 启用 / false 停用）。');
  }
  try {
    const spaceId = ks.resolveSpaceId(args && args.spaceId);
    ks.setSpaceEnabled(enabled, spaceId);
    const space = ks.getSpace(spaceId);
    return { spaceId, spaceName: space.name, enabled, message: `空间「${space.name}」已${enabled ? '启用' : '停用'}。` };
  } catch (e) {
    return fromHelperError(e, 'space_not_found');
  }
}

// 绑定当前会话（ctx.conversationId 由 chat.js / agent-runner 的 toolCtx 注入）。
// 绑定默认空间 = 解绑（G3 约定：默认不落行）。
function tool_knowledge_space_bind(args, ctx) {
  const conversationId = ctx && ctx.conversationId;
  if (!conversationId) {
    return errResult('binding_conversation_required', '当前运行没有会话上下文，无法绑定空间。');
  }
  try {
    const result = ks.setSpaceBinding(conversationId, args && args.spaceId ? args.spaceId : ks.SPACE_ID);
    const space = ks.getSpace(result.spaceId);
    return {
      conversationId: result.conversationId,
      spaceId: result.spaceId,
      spaceName: space ? space.name : result.spaceId,
      message: `本会话已绑定知识空间「${space ? space.name : result.spaceId}」。`,
    };
  } catch (e) {
    return fromHelperError(e, 'space_not_found');
  }
}

function tool_knowledge_doc_move(args) {
  const docIds = args && args.docIds;
  const targetSpaceId = args && args.targetSpaceId;
  if (!Array.isArray(docIds) || docIds.length === 0) {
    return errResult('doc_ids_required', 'knowledge_doc_move 需要 docIds 数组（可经 knowledge_doc_list 获取 id）。');
  }
  if (!targetSpaceId || !String(targetSpaceId).trim()) {
    return errResult('target_space_required', 'knowledge_doc_move 需要 targetSpaceId。');
  }
  try {
    const result = ks.moveDocumentsToSpace(docIds, targetSpaceId);
    const target = ks.getSpace(result.targetSpaceId);
    return {
      moved: result.moved.length,
      missing: result.missing.length ? result.missing : undefined,
      targetSpaceId: result.targetSpaceId,
      targetSpaceName: target.name,
      message: `已将 ${result.moved.length} 篇文档移动到「${target.name}」${result.missing.length ? `；${result.missing.length} 篇未找到` : ''}。`,
    };
  } catch (e) {
    return fromHelperError(e, 'space_not_found');
  }
}

async function tool_knowledge_doc_reindex(args) {
  const docId = String((args && args.docId) || '').trim();
  if (!docId) return errResult('doc_id_required', 'knowledge_doc_reindex 需要 docId。');
  try {
    const doc = await ingest.reindexDocument(docId);
    return {
      docId: doc.id,
      name: doc.name,
      status: doc.status,
      message: doc.status === 'failed' ? `重建失败：${doc.error || '未知原因'}` : `已重新排队摄取「${doc.name}」（当前状态 ${doc.status}）。`,
    };
  } catch (e) {
    return fromHelperError(e, 'knowledge_document_not_found');
  }
}

// ── 破坏性（D4 确认门）──────────────────────────────────

// 首调（无 token）→ 返回影响面 + confirmToken + 门纪律；凭用户确认后的 token 重调才执行。
function confirmationGateResult(action, subject, impact, summary) {
  const { confirmToken, expiresInSeconds } = confirmStore.issueConfirmToken(action, subject, impact);
  return {
    confirmationRequired: true,
    action,
    impact,
    confirmToken,
    expiresInSeconds,
    message:
      `这是破坏性操作，已暂停等待用户确认。影响面：${summary}。` +
      '请向用户如实复述上述影响面，并在用户下一条消息中明确确认后才可携带本 confirmToken 重新调用本工具执行；' +
      '用户未确认前不得执行，也不得伪造或提前使用 token。若用户拒绝，请告知已取消且未做任何改动。',
  };
}

function gateDeniedResult(reason) {
  const messages = {
    confirm_token_required: '缺少 confirmToken：破坏性操作须先取得用户确认。请先向用户复述影响面（可先调本工具不带 token 获取），确认后凭 token 重调。',
    confirm_token_invalid_or_expired: 'confirmToken 无效或已过期（一次性令牌，10 分钟有效）。请重新走确认链：先向用户复述影响面，再凭新 token 执行。',
    confirm_token_subject_mismatch: 'confirmToken 与本次操作主体不匹配。请重新走确认链后再执行。',
  };
  return { error: reason, confirmationRequired: true, message: messages[reason] || '确认令牌校验未通过。' };
}

function tool_knowledge_space_delete(args) {
  try {
    const spaceId = ks.resolveSpaceId(args && args.spaceId);
    if (spaceId === ks.SPACE_ID) {
      return errResult('ks_default_undeletable', '默认空间 ks_default 不可删除（只能清空其内容或停用）。');
    }
    const space = ks.getSpace(spaceId);
    const impact = ks.spaceImpact(spaceId);
    const subject = spaceId;
    const token = args && args.confirmToken;
    if (!token) {
      return confirmationGateResult(
        'knowledge_space_delete',
        subject,
        { spaceId, spaceName: space.name, ...impact },
        `将级联删除空间「${space.name}」及其 ${impact.documents} 篇文档、${impact.chunks} 个知识块（含索引与原始文件），不可恢复；绑定该空间的会话将自动回落默认空间。`
      );
    }
    const verdict = confirmStore.consumeConfirmToken(token, 'knowledge_space_delete', subject);
    if (!verdict.ok) return gateDeniedResult(verdict.reason);
    const result = ks.deleteSpaceCascade(spaceId);
    return { ...result, message: `已删除空间「${result.name}」（${result.documents} 篇文档、${result.chunks} 个块已级联清理）。` };
  } catch (e) {
    return fromHelperError(e, 'space_not_found');
  }
}

function tool_knowledge_space_clear(args) {
  try {
    const spaceId = ks.resolveSpaceId(args && args.spaceId);
    const space = ks.getSpace(spaceId);
    const impact = ks.spaceImpact(spaceId);
    const subject = spaceId;
    const token = args && args.confirmToken;
    if (!token) {
      return confirmationGateResult(
