function cloneJson(value) {
  return JSON.parse(JSON.stringify(value));
}

function deepFreeze(value) {
  if (!value || typeof value !== 'object' || Object.isFrozen(value)) return value;
  for (const child of Object.values(value)) deepFreeze(child);
  return Object.freeze(value);
}

function getDefinitionName(definition) {
  return definition && definition.function && definition.function.name;
}

function projectProviderDefinition(definition) {
  return {
    type: 'function',
    function: {
      name: definition.function.name,
      description: definition.function.description || '',
      parameters: cloneJson(definition.function.parameters),
    },
  };
}

function validateContract(name, metadata, errors) {
  if (!metadata || typeof metadata !== 'object' || Array.isArray(metadata)) {
    errors.push(`${name}: missing contract metadata`);
    return;
  }
  if (typeof metadata.contractVersion !== 'string' || !/^\d+\.\d+\.\d+$/.test(metadata.contractVersion)) {
    errors.push(`${name}: invalid contractVersion`);
  }
  if (!CATEGORIES.has(metadata.category)) errors.push(`${name}: invalid category`);
  if (!SIDE_EFFECTS.has(metadata.sideEffect)) errors.push(`${name}: invalid sideEffect`);
  if (!RISK_TIER_SET.has(metadata.riskTier)) errors.push(`${name}: invalid riskTier`);
  if (
    !Array.isArray(metadata.resources) ||
    metadata.resources.some((resource) => typeof resource !== 'string' || resource.length === 0)
  ) {
    errors.push(`${name}: invalid resources`);
  }
  if (!Number.isInteger(metadata.estimatedDurationMs) || metadata.estimatedDurationMs < 0) {
    errors.push(`${name}: invalid estimatedDurationMs`);
  }
  if (typeof metadata.cancellable !== 'boolean') errors.push(`${name}: invalid cancellable`);
}

function buildToolRegistry(definitions, handlers = {}, contracts = {}) {
  const errors = [];
  const seen = new Set();
  const definitionNames = new Set();

  if (!Array.isArray(definitions)) {
    throw new Error('Invalid agent tool registry:\n- definitions must be an array');
  }
  if (!handlers || typeof handlers !== 'object' || Array.isArray(handlers)) {
    throw new Error('Invalid agent tool registry:\n- handlers must be an object');
  }
  if (!contracts || typeof contracts !== 'object' || Array.isArray(contracts)) {
    throw new Error('Invalid agent tool registry:\n- contracts must be an object');
  }

  for (const definition of definitions) {
    const name = getDefinitionName(definition);
    if (
      !definition ||
      definition.type !== 'function' ||
      !definition.function ||
      typeof name !== 'string' ||
      name.length === 0 ||
      !definition.function.parameters ||
      typeof definition.function.parameters !== 'object'
    ) {
      errors.push('definition: invalid OpenAI-compatible function schema');
      continue;
    }
    if (seen.has(name)) errors.push(`${name}: duplicate definition`);
    seen.add(name);
    definitionNames.add(name);
    if (typeof handlers[name] !== 'function') errors.push(`${name}: definition has no handler`);
    validateContract(name, contracts[name], errors);
  }

  for (const name of Object.keys(handlers || {})) {
    if (!definitionNames.has(name)) errors.push(`${name}: handler has no definition`);
  }
  for (const name of Object.keys(contracts || {})) {
    if (!definitionNames.has(name)) errors.push(`${name}: contract has no definition`);
  }

  if (errors.length) {
    throw new Error(`Invalid agent tool registry:\n- ${errors.join('\n- ')}`);
  }

  return Object.freeze(
    definitions.map((definition) => {
      const name = getDefinitionName(definition);
      const metadata = Object.freeze({
        ...contracts[name],
        resources: Object.freeze([...contracts[name].resources]),
      });
      return Object.freeze({
        definition: deepFreeze(cloneJson(definition)),
        handler: handlers[name],
        contract: metadata,
      });
    })
  );
}

// Module-load construction is the startup consistency check. A mismatch in a
// model definition, handler, or contract fails before an agent request starts.
const TOOL_REGISTRY = buildToolRegistry(TOOL_DEFS, HANDLERS, CONTRACTS);
const TOOL_BY_NAME = new Map(
  TOOL_REGISTRY.map((entry) => [entry.definition.function.name, entry])
);

function getProviderToolDefs() {
  return TOOL_REGISTRY.map((entry) => projectProviderDefinition(entry.definition));
}

function getToolEntry(name) {
  return TOOL_BY_NAME.get(name);
}

function getToolHandler(name) {
  const entry = getToolEntry(name);
  return entry && entry.handler;
}

function getToolContract(name) {
  const entry = TOOL_BY_NAME.get(name);
  return entry && entry.contract;
}

function getToolRegistry() {
  return TOOL_REGISTRY;
}

module.exports = {
  CONTRACT_VERSION,
  RISK_TIERS,
  buildToolRegistry,
  getProviderToolDefs,
  getToolEntry,
  getToolHandler,
  getToolContract,
  getToolRegistry,
};

'use strict';

const CONTEXT_TOKEN_PATTERN = /^[a-f0-9]{64}$/;
const { projectPublicEditPhase } = require('../../shared-backend/result-studio-context');
const CONTEXT_BOUND_TOOLS = new Set([
  'result_edit_plan_in_context',
  'result_changeset_create_in_context',
  'result_enrichment_from_context',
  'result_changeset_status_in_context',
  'result_changeset_compare_in_context',
  'result_changeset_adopt_in_context',
  'result_changeset_revert_in_context',
]);

function trimmed(value) {
  return typeof value === 'string' ? value.trim() : '';
}

function validContextToken(value) {
  return CONTEXT_TOKEN_PATTERN.test(trimmed(value));
}

/**
 * Project untrusted request context into the narrow hint accepted by
 * resolveResultStudioContext. IDs remain hints: SQLite/Artifact Truth is
 * re-read by every tool operation and the token is compared fail-closed.
 */
function projectResultStudioToolContext(context = {}) {
  const candidate = context && context.activeArtifact && typeof context.activeArtifact === 'object'
    ? context.activeArtifact
    : null;
  const jobId = trimmed(candidate && candidate.jobId);
  const name = trimmed(candidate && candidate.name);
  const revisionId = trimmed(candidate && candidate.revisionId);
  const contextToken = candidate && validContextToken(candidate.contextToken)
    ? trimmed(candidate.contextToken)
    : null;
  const projected = {
    activeArtifact: jobId && name
      ? { jobId, name, revisionId: revisionId || null }
      : null,
    resultStudioContextToken: contextToken,
  };
  // The advanced drawer's acknowledgement is a user interaction captured
  // before the provider is called.  Keep it in private tool context rather
  // than trusting a later model-supplied `scientificConfirmed` argument.
  // Omit the key entirely for ordinary chat turns so their established
  // confirmation flow remains compatible.
  const editRequest = context && context.resultEditRequest;
  if (jobId && name && contextToken && editRequest && typeof editRequest === 'object') {
    const requestedExpectation = trimmed(editRequest.completionExpectation);
    projected.resultStudioCompletionExpectation = [
      'candidate', 'result_action', 'none',
    ].includes(requestedExpectation)
      ? requestedExpectation
      : (editRequest.origin === 'manual' ? 'candidate' : 'result_action');
    projected.resultStudioScientificConfirmation = editRequest.scientificConfirmed === true;
  }
  return projected;
}

/**
 * Bind the click-time token before JSON-schema validation.
 *
 * An explicitly supplied real token always wins — even when stale — so the
 * existing guard can reject it instead of silently retargeting a write. The
 * transport redacts sensitive fields before the model sees tool output;
 * `[REDACTED]` is therefore not a presented token and is replaced by the
 * click-time bound token. This preserves capability binding without exposing
 * the opaque token to the model.
 *
 * BLOCK-10 S-002 fail-closed cross-check (minimal): when an explicit
 * presented token is valid AND the activeArtifact in ctx carries a triple
 * (jobId, name, revisionId), any of those identifiers supplied on the args
 * MUST match the active triple. A mismatch indicates the presented token
 * was issued for a different artifact (replay or prompt-injection attack),
 * so we drop the presented token and fall through to the click-time
 * bound token path. If neither path yields a token, the existing
 * `context_token_stale` guard downstream still rejects. No new error code.
 */
function bindResultStudioContextToken(name, args = {}, ctx = {}) {
  const safeArgs = args && typeof args === 'object' && !Array.isArray(args) ? args : {};
  if (!CONTEXT_BOUND_TOOLS.has(name)) return safeArgs;
  const presentedToken = trimmed(safeArgs.contextToken);
  if (validContextToken(presentedToken)) {
    // S-002 cross-check: ensure presented token's target triple matches
    // the click-time bound activeArtifact. Mismatch ⇒ ignore presented
    // token and fall through to the ctx.bind path.
    const active = ctx && ctx.activeArtifact && typeof ctx.activeArtifact === 'object'
      ? ctx.activeArtifact
      : null;
    if (active && active.jobId && active.name) {
      const tripleKeys = ['jobId', 'name', 'revisionId'];
      const mismatch = tripleKeys.some((key) => {
        const argVal = safeArgs[key];
        if (argVal === undefined) return false;
        return trimmed(String(argVal)) !== trimmed(String(active[key] || ''));
      });
      if (mismatch) {
        const stripped = { ...safeArgs };
        delete stripped.contextToken;
        if (!validContextToken(ctx.resultStudioContextToken)) return stripped;
        return { ...stripped, contextToken: trimmed(ctx.resultStudioContextToken) };
      }
    }
    return safeArgs;
  }
  if (Object.prototype.hasOwnProperty.call(safeArgs, 'contextToken')
      && presentedToken !== '[REDACTED]') return safeArgs;
  if (!validContextToken(ctx.resultStudioContextToken)) return safeArgs;
  return { ...safeArgs, contextToken: trimmed(ctx.resultStudioContextToken) };
}

/** One bounded recorder shared by task and legacy Agent paths. */
function createResultEditProgressRecorder() {
  let events = [];
  const append = (event = {}) => {
    const projected = projectPublicEditPhase(event.stage, event.status);
    const next = {
      resultEditProgressVersion: 1,
      // ChangeSet events are numbered per candidate, while intent/plan
      // events precede any candidate and retries start another local
      // sequence. Persist one monotonic public sequence for the whole turn.
      sequence: events.length > 0 ? events[events.length - 1].sequence + 1 : 1,
      changeSetId: trimmed(event.changeSetId),
      stage: trimmed(event.stage),
      status: trimmed(event.status),
      ...(trimmed(event.reason) ? { reason: trimmed(event.reason).slice(0, 500) } : {}),
      ...(trimmed(event.toolJobId) ? { toolJobId: trimmed(event.toolJobId) } : {}),
      ...(trimmed(event.revisionId) ? { revisionId: trimmed(event.revisionId) } : {}),
      ...(projected.phase ? { publicPhase: projected.phase, publicPhaseLabel: projected.label } : {}),
    };
    events = events.concat(next).slice(-30);
    return next;
  };
  return {
    record: append,
    ensureTerminal(event = {}) {
      if (events.length > 0 && events[events.length - 1].status === 'terminal') return null;
      return append({ ...event, status: 'terminal' });
    },
    snapshot() {
      return events.map((event) => ({ ...event }));
    },
  };
}

function finalizeResultEditProgress(recorder, { outcome, reason } = {}) {
  const cancelled = outcome === 'cancelled';
  const hasResultEditProgress = recorder && recorder.snapshot().length > 0;
  const terminal = hasResultEditProgress
    ? recorder.ensureTerminal({ stage: cancelled ? 'cancelled' : 'failed', reason })
    : null;
  return {
    hasResultEditProgress,
    terminal,
    assistantMessage: hasResultEditProgress
      ? (cancelled
        ? '结果修改已停止；已完成的阶段结论已保留。'
        : '结果修改未完成；已完成的阶段结论已保留，可在当前会话中继续处理。')
      : (cancelled
        ? '任务已由用户停止。已完成的阶段结论、工具记录和结果已保留，未开始的步骤不会继续执行。'
        : '本轮 Agent 请求未完成；上游模型响应异常，请稍后重试。'),
  };
}

module.exports = {
  CONTEXT_BOUND_TOOLS,
  validContextToken,
  projectResultStudioToolContext,
  bindResultStudioContextToken,
  createResultEditProgressRecorder,
  finalizeResultEditProgress,
};

