  if (job.result && typeof job.result === 'object') return job.result;
  try {
    return JSON.parse(job.result_json || '{}');
  } catch {
    return {};
  }
}

/**
 * 把插件 descriptor 的可编辑参数投影成有界列表。
 *
 * 只有插件**显式声明**过 impact 的参数才允许出现；未声明的参数不在这里
 * 变成"看起来可以安全改"的控件，交由 result_edit_plan 的保守分级处理。
 */
function projectEditableParameters(descriptor) {
  if (!descriptor || typeof descriptor !== 'object') return [];
  const parameters = descriptor.parameters && typeof descriptor.parameters === 'object' ? descriptor.parameters : {};
  const impacts = descriptor.parameterImpacts && typeof descriptor.parameterImpacts === 'object'
    ? descriptor.parameterImpacts
    : {};
  return Object.keys(parameters)
    .filter((name) => trimmed(impacts[name]))
    .sort()
    .map((name) => ({
      name,
      type: trimmed(parameters[name] && parameters[name].type) || null,
      impact: trimmed(impacts[name]),
      default: parameters[name] && parameters[name].default !== undefined ? parameters[name].default : null,
    }));
}

/**
 * 从当前 UI 状态 + 后端真相解析 ResultStudioContextEnvelope。
 *
 * @param {object} ctx Agent tool context（projectId / conversationId / activeArtifact）
 * @param {object} dependencies 可注入依赖，便于单测固定契约
 * @returns {{ ok: boolean, envelope: object|null, diagnostics: Array, repository: object|null, project: object|null }}
 */
function resolveResultStudioContext(ctx = {}, dependencies = {}) {
  const dbModule = dependencies.db || dbMod;
  const projectId = trimmed(ctx.projectId);
  if (!projectId) {
    return {
      ok: false,
      envelope: null,
      repository: null,
      project: null,
      diagnostics: [{ code: 'context_project_required', message: '需要一个当前项目才能读取结果上下文。' }],
    };
  }
  const project = dependencies.getProject ? dependencies.getProject(projectId) : dbModule.getProject(projectId);
  if (!authorizeProject(project, ctx.userId, dbModule)) {
    return {
      ok: false,
      envelope: null,
      repository: null,
      project: null,
      diagnostics: [{ code: 'context_project_forbidden', message: '当前身份无权访问该项目。' }],
    };
  }
  const repository = dependencies.repository
    || createResultStudioRepository(dbModule.db || dbModule.getDatabase());

  // 客户端线索：只用来定位候选 Revision，不作为身份来源。
  const hint = ctx.activeArtifact && typeof ctx.activeArtifact === 'object' ? ctx.activeArtifact : {};
  const hintRevisionId = trimmed(hint.revisionId);
  const hintJobId = trimmed(hint.jobId);

  let revision = hintRevisionId ? repository.getRevision(hintRevisionId) : null;
  if (revision && revision.projectId !== projectId) revision = null;
  if (!revision && hintJobId) {
    const job = dependencies.getToolJob ? dependencies.getToolJob(hintJobId) : dbModule.getToolJob(hintJobId);
    const result = parseJobResult(job);
    const artifacts = Array.isArray(result.artifacts) ? result.artifacts : [];
    const name = trimmed(hint.name);
    const matches = artifacts.filter((artifact) => artifact
      && (artifact.name === name || artifact.filename === name
        || String(artifact.path || '').split('/').pop() === name));
    if (matches.length === 1 && matches[0].id) {
      revision = repository.findRevisionByJobArtifact({
        projectId,
        toolJobId: hintJobId,
        artifactId: matches[0].id,
      });
    }
  }
  if (!revision) {
    return {
      ok: false,
      envelope: null,
      repository,
      project,
      diagnostics: [{
        code: 'context_artifact_not_open',
        message: '当前没有已建立正式版本的结果处于打开状态；请先让用户在主画布打开一个结果。',
      }],
    };
  }

  const job = dependencies.getToolJob ? dependencies.getToolJob(revision.toolJobId) : dbModule.getToolJob(revision.toolJobId);
  const result = parseJobResult(job);
  const artifactRecord = (Array.isArray(result.artifacts) ? result.artifacts : [])
    .find((artifact) => artifact && artifact.id === revision.artifactId) || null;
  const pluginId = job && (job.tool_id || job.toolId) || null;
  const manifest = pluginId
    ? (dependencies.getPluginManifest ? dependencies.getPluginManifest(pluginId) : pluginLoader.getPluginManifest(pluginId))
    : null;
  const descriptor = manifest && manifest.resultStudio ? manifest.resultStudio : null;
  const mapping = descriptor && Array.isArray(descriptor.interactionMappings)
    ? descriptor.interactionMappings.find((item) => item && item.artifactId === revision.artifactId) || null
    : null;
  const currentRevision = repository.getCurrentRevision(revision.artifactFamilyId);
  const listProjectToolJobsForWorkflow = dependencies.listProjectToolJobsForWorkflow
    || dbModule.listProjectToolJobsForWorkflow;
  const workflowProjection = typeof listProjectToolJobsForWorkflow === 'function'
    ? buildAuthoritativeWorkflowGraph({
      projectId,
      sourceToolJobId: revision.toolJobId,
      jobs: listProjectToolJobsForWorkflow(projectId),
      repository,
    })
    : { ok: false, diagnostics: [{ code: 'workflow_truth_unavailable', message: '无法读取项目 Job 真相以投影工作流。' }] };
  // Context projection itself is read-only.  A graph becomes durable only
  // when an admitted downstream execution explicitly snapshots it; merely
  // opening a result must not grant scientific-edit authority or write SQLite.
  const workflowSnapshot = workflowProjection.ok && typeof repository.findWorkflowGraph === 'function'
    ? repository.findWorkflowGraph({ projectId, sourceDigest: workflowProjection.graph.sourceDigest })
    : null;
  // 选择：从 SQLite 权威恢复，再按用户正在查看的 Revision 判定兼容性。
  // 历史查看不能借 current 的 selection，也不能把历史版本自己的 selection
  // 错判为 stale；contextToken 必须绑定 viewed revision，而不是正式 current。
  const persistedSelection = repository.findLatestSelection({
    projectId,
    conversationId: trimmed(ctx.conversationId) || null,
    artifactId: revision.artifactId,
  });
  let selectionInput = null;
  if (persistedSelection) {
    const compatibility = assessSelectionCompatibility({
      selection: persistedSelection,
      projectId,
      artifactId: revision.artifactId,
      revisionId: revision.revisionId,
      selectionDurable: persistedSelection.displayState?.durable !== false,
    });
    const summary = summarizeSelection(persistedSelection);
    selectionInput = {
      selectionId: persistedSelection.selectionId,
      entityType: summary.entityType,
      entityIdCount: summary.entityIdCount,
      truncated: summary.truncated,
      entityIdsHash: summary.entityIdsHash,
      filterHash: summary.filterHash,
      fields: Array.isArray(persistedSelection.displayState?.fields)
        ? persistedSelection.displayState.fields
        : [],
      sort: summary.sort,
      updatedAt: persistedSelection.updatedAt,
      sampleEntityIds: summary.sampleEntityIds,
      hasFilter: summary.hasFilter,
      filterDescription: describeFilterExpression(persistedSelection.filterExpression),
      compatibility: compatibility.status,
      compatibilityReason: compatibility.reason,
    };
  }

  const built = buildResultStudioContextEnvelope({
    projectId,
    conversationId: trimmed(ctx.conversationId) || null,
    artifact: {
      artifactId: revision.artifactId,
      artifactFamilyId: revision.artifactFamilyId,
      name: artifactRecord && (artifactRecord.name || artifactRecord.filename) || null,
      kind: artifactRecord && artifactRecord.type || null,
      entityType: mapping && mapping.entityType || null,
      idField: mapping && (mapping.idField || mapping.rowIdField) || null,
      interactionMode: mapping && mapping.mode || null,
    },
    job: {
      toolJobId: revision.toolJobId,
      projectId: job && (job.project_id || job.projectId) || null,
      toolId: pluginId,
      status: job && job.status || null,
      artifactTruthStatus: result.artifactTruth && result.artifactTruth.status || null,
    },
    revision: {
      revisionId: revision.revisionId,
      currentRevisionId: currentRevision ? currentRevision.revisionId : null,
      revisionOrdinal: revision.revisionOrdinal,
      isCurrent: !!currentRevision && currentRevision.revisionId === revision.revisionId,
      validationStatus: revision.validationStatus,
      reproducibilityStatus: revision.reproducibilityStatus,
    },
    script: {
      relativePath: revision.sourceScriptRef && revision.sourceScriptRef.relativePath || null,
      sha256: revision.sourceScriptRef && revision.sourceScriptRef.sha256 || null,
      language: revision.sourceScriptRef && revision.sourceScriptRef.language || null,
      origin: revision.sourceScriptRef && revision.sourceScriptRef.origin || null,
      parametersRef: revision.parametersRef,
      parametersHash: revision.parametersHash,
    },
    plugin: {
      pluginId,
      descriptorVersion: descriptor && Number.isInteger(descriptor.descriptorVersion)
        ? descriptor.descriptorVersion
        : null,
      editableParameters: projectEditableParameters(descriptor),
      actions: descriptor && Array.isArray(descriptor.actions) ? descriptor.actions : [],
    },
    selection: selectionInput,
    workflow: workflowProjection.ok
      ? {
        graphId: workflowProjection.graph.graphId,
        sourceDigest: workflowProjection.graph.sourceDigest,
        snapshotStatus: workflowSnapshot && workflowSnapshot.graphId === workflowProjection.graph.graphId
          ? 'persisted'
          : 'not_persisted',
        nodeId: `job:${revision.toolJobId}`,
        stepCount: workflowProjection.workflowPlan.steps.length,
        downstreamNodeIds: workflowProjection.workflowPlan.steps
          .filter((step) => Array.isArray(step.dependsOn) && step.dependsOn.includes(`job:${revision.toolJobId}`))
          .map((step) => step.id),
      }
      : null,
  });

  // G0-RS-P4：当前生效参数取自该 Job 的执行 provenance 归一化参数，
  // 用于剔除"提交了但与现状相同"的改动，避免生成空 ChangeSet。
  // 不回退到 descriptor 默认值：默认值不等于这次运行真正用过的值。
  const currentParameters = result.executionProvenance
    && result.executionProvenance.params
    && typeof result.executionProvenance.params.normalized === 'object'
    && result.executionProvenance.params.normalized !== null
    ? result.executionProvenance.params.normalized
    : {};

  return {
    ok: built.ok,
    envelope: built.envelope,
    diagnostics: built.diagnostics,
    repository,
    project,
    revision,
    job,
    descriptor,
    currentParameters,
    // Private server-side selection material.  It is intentionally not put in
    // the ContextEnvelope: model-visible context only receives a bounded
    // summary.  A narrowly declared presentation action may bind these stable
    // IDs itself, never by accepting a model-supplied label list.
    persistedSelection,
    workflowPlan: workflowProjection.ok ? workflowProjection.workflowPlan : null,
    workflowGraph: workflowProjection.ok ? workflowProjection.graph : null,
    workflowSnapshot: workflowSnapshot && workflowSnapshot.graphId === workflowProjection.graph?.graphId
      ? workflowSnapshot
      : null,
    workflowDiagnostics: workflowProjection.ok ? [] : workflowProjection.diagnostics || [],
  };
}

/**
 * 解析 context-bound ChangeSet。
 *
 * 优先使用当前 Artifact family 下唯一未定局的 ChangeSet；存在多个时不猜，
 * 让 Agent 显式确认，避免把用户的"采用"落到另一个候选上。
 */
function resolveContextChangeSet({ repository, projectId, artifactFamilyId, changeSetId = null }) {
  if (trimmed(changeSetId)) {
    const explicit = repository.getChangeSet(trimmed(changeSetId));
    if (!explicit || explicit.projectId !== projectId) {
      return { ok: false, error: 'change_set_not_found', message: '该修改在当前项目中不存在。' };
    }
    return { ok: true, changeSet: explicit };
  }
  const open = repository.listChangeSets({ projectId, limit: 200 })
    .filter((changeSet) => OPEN_CHANGE_SET_STATUSES.includes(changeSet.status))
    .filter((changeSet) => {
      if (!artifactFamilyId) return true;
      const revisions = repository.listRevisionsByChangeSet(changeSet.changeSetId);
      if (revisions.length === 0) return changeSet.status === 'draft' || changeSet.status === 'running';
      return revisions.some((revision) => revision.artifactFamilyId === artifactFamilyId);
    });
  if (open.length === 0) {
    return { ok: false, error: 'context_change_set_absent', message: '当前结果没有进行中的修改。' };
  }
  if (open.length > 1) {
    return {
      ok: false,
      error: 'context_change_set_ambiguous',
      message: '当前结果存在多个进行中的修改，请先确认要操作哪一个。',
      detail: { openCount: open.length },
    };
  }
  return { ok: true, changeSet: open[0] };
}

/**
 * 只读上下文工具：把当前结果坐标交给模型。
 */
function createResultStudioContextTool(options = {}) {
  return async function tool_result_studio_context(args = {}, ctx = {}) {
    const resolved = resolveResultStudioContext(ctx, options);
    if (!resolved.ok) {
      return {
        ok: false,
        error: resolved.diagnostics[0]?.code || 'context_unavailable',
        message: resolved.diagnostics[0]?.message || '无法读取当前结果上下文。',
        diagnostics: resolved.diagnostics,
        publicPhases: [...PUBLIC_EDIT_PHASES],
      };
    }
    const changeSet = resolveContextChangeSet({
      repository: resolved.repository,
      projectId: resolved.envelope.projectId,
      artifactFamilyId: resolved.envelope.artifact.artifactFamilyId,
    });
    // G0-RS-P4：控件 schema 与 Agent 看到的可编辑参数出自同一 descriptor 投影，
    // 手动面板和 AI 意图因此不可能看到两套不同的参数契约。
    const controlSchema = buildEditControlSchema(resolved.descriptor);
    return {
      ok: true,
      context: summarizeContextForAgent(resolved.envelope),
      editControls: {
        controlsVersion: controlSchema.controlsVersion,
        groups: controlSchema.groups,
        controls: controlSchema.controls,
      },
      pendingChange: changeSet.ok
        ? { status: changeSet.changeSet.status, hasCandidate: !!changeSet.changeSet.candidateCommit }
        : null,
      workflowDiagnostics: resolved.workflowDiagnostics || [],
    };
  };
}

/**
 * context-bound 写操作闸门。
 *
 * 每个写工具都先走这里：重新投影真相 → 校验模型带回的 token → 才允许继续。
 */
function guardContextOperation(ctx, args, options, { requireToken = true } = {}) {
  const resolved = resolveResultStudioContext(ctx, options);
  if (!resolved.ok) {
    return {
      ok: false,
      response: {
        ok: false,
        error: resolved.diagnostics[0]?.code || 'context_unavailable',
        message: resolved.diagnostics[0]?.message || '无法读取当前结果上下文。',
        diagnostics: resolved.diagnostics,
      },
    };
  }
  const authorized = authorizeContextOperation({
    envelope: resolved.envelope,
    presentedToken: args && args.contextToken,
    requireToken,
  });
  if (!authorized.ok) {
    return {
      ok: false,
      response: {
        ok: false,
        error: authorized.diagnostics[0].code,
        message: authorized.diagnostics[0].message,
        diagnostics: authorized.diagnostics,
        remediation: 'result_studio_context',
      },
    };
  }
  return { ok: true, resolved };
}

module.exports = {
  OPEN_CHANGE_SET_STATUSES,
  projectEditableParameters,
  resolveResultStudioContext,
  resolveContextChangeSet,
  createResultStudioContextTool,
  guardContextOperation,
  tool_result_studio_context: createResultStudioContextTool(),
};

'use strict';

const crypto = require('crypto');
const fs = require('fs');
const path = require('path');
const dbMod = require('../db');
const pluginLoader = require('../plugin-loader');
const { isPathContained } = require('../../shared-backend/project-run-layout');
const { createResultStudioRepository } = require('../../shared-backend/result-studio-repository');
const { assessSelectionCompatibility } = require('../../shared-backend/result-studio-contracts');
const { queryResultTable } = require('../../shared-backend/result-studio-table-query');
const { buildAuthoritativeWorkflowGraph } = require('../../shared-backend/result-workflow-graph');
const { bindProjectRepository } = require('../../shared-backend/git-repository-binding');
const { verifyRevisionSourceMaterial } = require('../../shared-backend/result-revision-source');

const MAX_DOWNSTREAM_ENTITY_IDS = 20_000;
const SAFE_SELECTION_ID = /^sel_[A-Za-z0-9_-]{1,160}$/;
const SHA256_PATTERN = /^[a-f0-9]{64}$/;

function sha256File(filePath) {
  const hash = crypto.createHash('sha256');
  hash.update(fs.readFileSync(filePath));
  return hash.digest('hex');
}

function csvCell(value) {
  return `"${String(value).replace(/"/g, '""')}"`;
}

function materializationPathError(code, message) {
  throw Object.assign(new Error(message), { code });
}

function ensureSelectionMaterializationDirectory(workspaceRoot, selectionId) {
  if (!SAFE_SELECTION_ID.test(selectionId)) {
    materializationPathError('selection_id_invalid', 'SelectionContext id is not path-safe.');
  }
  let anchor;
  try {
    anchor = fs.realpathSync(path.resolve(workspaceRoot));
  } catch {
    materializationPathError('selection_workspace_unavailable', 'Selection workspace is unavailable.');
  }
  if (!fs.statSync(anchor).isDirectory()) {
    materializationPathError('selection_workspace_unavailable', 'Selection workspace is not a directory.');
  }

  let current = anchor;
  for (const component of ['analysis', 'selections', selectionId]) {
    const candidate = path.join(current, component);
    if (!isPathContained(anchor, candidate) || path.dirname(candidate) !== current) {
      materializationPathError('selection_materialization_path_escape', 'Selection materialization escaped its workspace.');
    }
    let stat;
    try {
      stat = fs.lstatSync(candidate);
    } catch (error) {
      if (error?.code !== 'ENOENT') {
        materializationPathError('selection_materialization_path_unavailable', 'Selection materialization directory is unavailable.');
      }
      try {
        fs.mkdirSync(candidate, { mode: 0o700 });
      } catch (mkdirError) {
        if (mkdirError?.code !== 'EEXIST') {
          materializationPathError('selection_materialization_path_unavailable', 'Selection materialization directory could not be created.');
        }
      }
      stat = fs.lstatSync(candidate);
    }
    if (stat.isSymbolicLink() || !stat.isDirectory()) {
      materializationPathError('selection_materialization_path_unsafe', 'Selection materialization directories must be real directories.');
    }
    const canonical = fs.realpathSync(candidate);
    if (!isPathContained(anchor, canonical) || path.dirname(canonical) !== current) {
      materializationPathError('selection_materialization_path_escape', 'Selection materialization directory escaped its workspace.');
    }
    current = canonical;
  }
  const stat = fs.statSync(current);
  return { anchor, directory: current, dev: stat.dev, ino: stat.ino };
}

function atomicWriteSelectionFile(workspaceRoot, selectionId, fileName, content) {
  if (!fileName || path.basename(fileName) !== fileName || fileName.includes('\0')) {
    materializationPathError('selection_materialization_file_invalid', 'Selection materialization filename is invalid.');
  }
  const directory = ensureSelectionMaterializationDirectory(workspaceRoot, selectionId);
  const target = path.join(directory.directory, fileName);
  let existing = null;
  try { existing = fs.lstatSync(target); } catch (error) {
    if (error?.code !== 'ENOENT') {
      materializationPathError('selection_materialization_file_unavailable', 'Selection materialization file is unavailable.');
    }
  }
  if (existing && (existing.isSymbolicLink() || !existing.isFile())) {
    materializationPathError('selection_materialization_path_unsafe', 'Selection materialization target must be a regular file.');
  }

  const temporary = path.join(
    directory.directory,
    `.selection-write-${process.pid}-${crypto.randomBytes(16).toString('hex')}`,
  );
  const noFollow = Number.isInteger(fs.constants.O_NOFOLLOW) ? fs.constants.O_NOFOLLOW : 0;
  let fd = null;
  let temporaryCreated = false;
  try {
    fd = fs.openSync(
      temporary,
      fs.constants.O_WRONLY | fs.constants.O_CREAT | fs.constants.O_EXCL | noFollow,
      0o600,
    );
    temporaryCreated = true;
    fs.writeFileSync(fd, content);
    fs.fsyncSync(fd);
    fs.closeSync(fd);
    fd = null;

    const current = ensureSelectionMaterializationDirectory(workspaceRoot, selectionId);
    if (current.directory !== directory.directory
        || current.dev !== directory.dev
        || current.ino !== directory.ino) {
      materializationPathError('selection_materialization_path_changed', 'Selection materialization directory changed during the write.');
    }
    let currentTarget = null;
    try { currentTarget = fs.lstatSync(target); } catch (error) {
      if (error?.code !== 'ENOENT') throw error;
    }
    if (currentTarget && (currentTarget.isSymbolicLink() || !currentTarget.isFile())) {
      materializationPathError('selection_materialization_path_unsafe', 'Selection materialization target changed to an unsafe entry.');
    }
    fs.renameSync(temporary, target);
    temporaryCreated = false;
    const written = fs.lstatSync(target);
    const canonical = fs.realpathSync(target);
    if (written.isSymbolicLink() || !written.isFile()
        || !isPathContained(directory.directory, canonical)) {
      materializationPathError('selection_materialization_path_unsafe', 'Selection materialization file failed containment verification.');
    }
    return canonical;
  } finally {
    if (fd !== null) {
      try { fs.closeSync(fd); } catch {}
    }
    if (temporaryCreated) {
      try { fs.unlinkSync(temporary); } catch {}
    }
  }
}

function fail(error, message, detail = null) {
  return { ok: false, error, message, detail };
}

function parseJobResult(job) {
  if (!job) return {};
  if (job.result && typeof job.result === 'object') return job.result;
  try { return JSON.parse(job.result_json || '{}'); } catch { return {}; }
}

function artifactFileName(artifact) {
  const value = artifact?.filename || artifact?.name || artifact?.path || '';
  return value ? path.basename(String(value)) : '';
}

function resolveBackingArtifactTruth({ sourceJob, descriptor, mapping, backingName, sourcePath }) {
  const result = parseJobResult(sourceJob);
  if (result.artifactTruth?.status !== 'valid' || result.artifactTruth?.blocking === true) {
    return fail('selection_backing_data_untrusted', 'backing data 未进入同一 valid Artifact Truth');
  }
  const declared = Array.isArray(descriptor?.artifacts) ? descriptor.artifacts : [];
  const descriptors = mapping?.dataArtifactId
    ? declared.filter((artifact) => artifact?.id === mapping.dataArtifactId)
    : declared.filter((artifact) => artifactFileName(artifact) === backingName);
  if (descriptors.length !== 1 || !descriptors[0]?.id) {
    return fail('selection_backing_data_untrusted', 'backing data 没有唯一的插件 Artifact 声明');
  }
  const artifacts = Array.isArray(result.artifacts) ? result.artifacts : [];
  const matches = artifacts.filter((artifact) => artifact?.id === descriptors[0].id);
  if (matches.length !== 1 || artifactFileName(matches[0]) !== backingName) {
    return fail('selection_backing_data_untrusted', 'backing data 没有唯一的 Job Artifact Truth 记录');
  }
  let artifactPath;
  try { artifactPath = fs.realpathSync(matches[0].path); } catch {
    return fail('selection_backing_data_untrusted', 'backing data 的 Artifact Truth 路径不可用');
  }
  const expectedSha256 = String(matches[0].sha256 || '').trim().toLowerCase();
  if (artifactPath !== sourcePath || !SHA256_PATTERN.test(expectedSha256)) {
    return fail('selection_backing_data_untrusted', 'backing data 未精确绑定到 Job Artifact Truth');
  }
  return { ok: true, expectedSha256 };
}

function enumValue(value, allowed, fallback) {
  const candidate = String(value || fallback).trim();
  return allowed.includes(candidate) ? candidate : null;
}

function boundedNumber(value, { fallback, minimum, maximum }) {
  if (value == null || value === '') return fallback;
  const number = Number(value);
  return Number.isFinite(number) && number >= minimum && number <= maximum ? number : null;
}

function persistVerifiedWorkflowGraph({ projectId, sourceToolJobId, repository, executed, dependencies }) {
  const listProjectToolJobsForWorkflow = dependencies.listProjectToolJobsForWorkflow
    || dbMod.listProjectToolJobsForWorkflow;
  if (!executed || !executed.ok || !executed.toolJobId
      || typeof listProjectToolJobsForWorkflow !== 'function') {
    return { ok: false, diagnostics: [{ code: 'workflow_execution_truth_missing' }] };
  }
  const buildWorkflowGraph = dependencies.buildAuthoritativeWorkflowGraph
    || buildAuthoritativeWorkflowGraph;
  const graph = buildWorkflowGraph({
    projectId,
    sourceToolJobId,
    jobs: listProjectToolJobsForWorkflow(projectId),
    repository,
    requiredToolJobIds: [executed.toolJobId],
  });
  if (!graph.ok) return { ok: false, diagnostics: graph.diagnostics || [] };
  if (typeof repository.saveWorkflowGraph !== 'function') {
    return { ok: false, diagnostics: [{ code: 'workflow_graph_repository_unavailable' }] };
  }
  try {
    const saved = repository.saveWorkflowGraph(graph.graph);
    if (!saved || saved.graphId !== graph.graph.graphId || saved.sourceDigest !== graph.graph.sourceDigest
        || saved.validationStatus !== 'valid') {
      return { ok: false, diagnostics: [{ code: 'workflow_graph_persistence_mismatch' }] };
    }
    return { ok: true, graph: saved, diagnostics: [] };
  } catch (error) {
    return {
      ok: false,
      diagnostics: [{
        code: error?.code || 'workflow_graph_persistence_failed',
        message: error?.message || 'Authoritative workflow graph persistence failed.',
      }],
    };
  }
}

function failClosedWorkflowAction(executed, workflowGraph) {
  if (workflowGraph.ok) return null;
  return fail(
    'workflow_graph_persistence_failed',
    '下游 Job 已完成，但权威工作流图无法验证并持久化；本次科学动作不能视为成功。',
    {
      toolJobId: executed?.toolJobId || null,
      executionCompleted: executed?.ok === true,
      diagnostics: workflowGraph.diagnostics || [],
    }
  );
}

function verifyImmutableRevision({ projectId, project, revision, repository, sourceJob, dependencies }) {
  const verifier = dependencies.verifyRevisionSourceMaterial || verifyRevisionSourceMaterial;
  let binding = dependencies.repositoryBinding || null;
  if (!dependencies.adapter && !binding) {
    const bindRepository = dependencies.bindProjectRepository || bindProjectRepository;
    const allowExistingRepository = repository.hasExistingRepositoryConsent?.(projectId) === true;
    binding = bindRepository({
      workspaceRoot: project.workspace_path,
      projectId,
      preferManaged: false,
      allowExistingRepository,
      createManagedIfMissing: false,
    });
  }
  const adapter = dependencies.adapter || binding?.adapter || null;
  if (!adapter && dependencies.verifyRevisionSourceMaterial == null) {
    return fail(
      binding?.reason || 'revision_source_repository_unavailable',
      '正式 Revision 的不可变脚本、参数与输入快照不可用，不能启动下游重跑。'
    );
  }
  try {
    const projection = verifier({ projectId, revision }, {
      repository,
      adapter,
      gitPathPrefix: dependencies.gitPathPrefix != null
        ? dependencies.gitPathPrefix
        : binding?.mode === 'existing'
          ? binding.inspection?.existing?.workspaceRelativeToRepository
          : '',
      workspaceRoot: project.workspace_path,
      getToolJob: dependencies.getToolJob || (() => sourceJob),
    });
    if (projection?.reproduction?.inputDrift?.length > 0) {
      return fail('source_input_drift', '正式 Revision 的一个或多个输入 hash 已变化，不能启动下游重跑。');
    }
    return { ok: true, projection };
  } catch (error) {
    return fail(
      error?.code || 'revision_source_verification_failed',
      error?.message || '正式 Revision 的不可变来源材料验证失败。',
      error?.detail || null
    );
  }
}

/**
 * Continue a current DEG Revision into GO/KEGG using its immutable Artifact
 * bytes.  This intentionally takes a server-resolved revision id: a model
 * never supplies a file path, a tool id, or a lineage object.  Unlike the
 * selection route, this direct edge lets a later DEG-threshold candidate
 * truthfully invalidate and rerun enrichment from the full DEG table.
 */
async function tool_result_enrichment_from_revision(args, ctx, dependencies = {}) {
  const projectId = String(ctx?.projectId || '').trim();
  const revisionId = String(args?.revisionId || '').trim();
  if (!ctx?.userId) return fail('unauthorized', '未授权');
  if (!projectId || !revisionId) return fail('revision_and_project_required', '需要当前项目和一个受信的 DEG Revision');

  const species = enumValue(args?.species, ['human', 'mouse'], 'human');
  const geneIdType = enumValue(args?.geneIdType, ['auto', 'SYMBOL', 'ENSEMBL', 'ENTREZID'], 'auto');
  const analysisType = enumValue(args?.analysisType, ['all', 'GO', 'GO-BP', 'GO-MF', 'GO-CC', 'KEGG'], 'all');
  const padjCutoff = boundedNumber(args?.padjCutoff, { fallback: 0.05, minimum: 0, maximum: 1 });
  const lfcCutoff = boundedNumber(args?.lfcCutoff, { fallback: 1, minimum: 0, maximum: 100 });
  if (!species || !geneIdType || !analysisType || padjCutoff == null || lfcCutoff == null) {
    return fail('enrichment_parameters_invalid', 'GO/KEGG 参数不在插件声明的允许范围内');
  }

  const sqlite = dependencies.sqlite || dbMod.getDatabase();
  const repository = dependencies.repository || createResultStudioRepository(sqlite);
  const revision = repository.getRevision(revisionId);
  if (!revision || revision.projectId !== projectId || revision.artifactId !== 'deg_table') {
    return fail('deg_revision_not_found', '当前项目没有可用于富集的正式 DEG 表版本');
  }
  const currentRevision = repository.getCurrentRevision(revision.artifactFamilyId, projectId);
  if (!currentRevision || currentRevision.revisionId !== revision.revisionId) {
    return fail('deg_revision_not_current', '只允许从当前 DEG Revision 派生新的富集；历史替代方案请先恢复为新 Revision');
  }
  const project = dependencies.getProject ? dependencies.getProject(projectId) : dbMod.getProject(projectId);
  if (!project?.workspace_path) return fail('project_workspace_missing', '项目工作区不可用');
  let workspaceRoot;
  let degPath;
  try {
    workspaceRoot = fs.realpathSync(project.workspace_path);
    degPath = fs.realpathSync(path.join(workspaceRoot, revision.outputPath));
  } catch {
    return fail('deg_artifact_missing', 'DEG Artifact 已缺失，不能继续富集');
  }
  if (!isPathContained(workspaceRoot, degPath) || !fs.statSync(degPath).isFile()) {
    return fail('deg_artifact_outside_project', 'DEG Artifact 不在项目工作区内');
  }
  if (!revision.outputHash || sha256File(degPath) !== revision.outputHash) {
    return fail('deg_artifact_hash_drift', 'DEG Artifact 已偏离其正式 Revision');
  }

  const sourceJob = dependencies.getToolJob ? dependencies.getToolJob(revision.toolJobId) : dbMod.getToolJob(revision.toolJobId);
  const sourceResult = parseJobResult(sourceJob);
  const sourceArtifactMatches = (Array.isArray(sourceResult.artifacts) ? sourceResult.artifacts : [])
    .filter((artifact) => artifact && artifact.id === revision.artifactId);
  if (!sourceJob || sourceJob.status !== 'completed' || String(sourceJob.project_id || sourceJob.projectId || '') !== projectId
      || sourceResult.artifactTruth?.status !== 'valid' || sourceResult.artifactTruth?.blocking === true
      || sourceArtifactMatches.length !== 1) {
    return fail('deg_source_truth_invalid', 'DEG Revision 没有可验证的 Job/Artifact Truth 来源');
  }
  const sourcePlugin = dependencies.getPluginManifest
    ? dependencies.getPluginManifest(sourceJob.tool_id || sourceJob.toolId)
    : pluginLoader.getPluginManifest(sourceJob.tool_id || sourceJob.toolId);
  const descriptor = sourcePlugin?.resultStudio;
  const artifactDescriptor = descriptor?.artifacts?.filter((artifact) => artifact && artifact.id === 'deg_table') || [];
  const mapping = descriptor?.interactionMappings?.filter((item) => item && item.artifactId === 'deg_table') || [];
  if (!descriptor || !Array.isArray(descriptor.actions) || !descriptor.actions.includes('derive_enrichment_input')
      || artifactDescriptor.length !== 1 || mapping.length !== 1 || mapping[0].idField !== 'gene') {
    return fail('deg_enrichment_action_not_declared', '来源插件没有声明稳定 gene_id 的富集派生契约');
  }
  const sourceVerification = verifyImmutableRevision({
    projectId, project, revision, repository, sourceJob, dependencies,
  });
  if (!sourceVerification.ok) return sourceVerification;

  const runTool = dependencies.runTool || require('./learning').tool_run_tool;
  const executed = await runTool({
    op: 'run',
    toolId: 'go-kegg',
    params: {
      deg_table: degPath,
      species,
      gene_id_type: geneIdType,
      analysis_type: analysisType,
      padj_cutoff: padjCutoff,
      lfc_cutoff: lfcCutoff,
    },
  }, {
    ...ctx,
    resultStudioInputLineage: {
      deg_table: {
        lineageVersion: 1,
        kind: 'artifact',
        sourceRevisionId: revision.revisionId,
        sourceToolJobId: revision.toolJobId,
        sourceArtifactId: revision.artifactId,
        sourceOutputHash: revision.outputHash,
        materializationHash: revision.outputHash,
      },
    },
  });
  const workflowGraph = persistVerifiedWorkflowGraph({
    projectId,
    sourceToolJobId: revision.toolJobId,
    repository,
    executed,
    dependencies,
  });
  const workflowFailure = failClosedWorkflowAction(executed, workflowGraph);
  if (workflowFailure) return workflowFailure;
  return {
    ...executed,
    enrichmentAction: {
      sourceRevisionId: revision.revisionId,
      sourceArtifactId: revision.artifactId,
      geneIdField: 'gene',
      parameters: { species, geneIdType, analysisType, padjCutoff, lfcCutoff },
      executorTruth: 'run_tool → tool_job → artifact truth',
      workflowGraph: workflowGraph.ok
        ? { graphId: workflowGraph.graph.graphId, sourceDigest: workflowGraph.graph.sourceDigest, validationStatus: workflowGraph.graph.validationStatus }
        : null,
      workflowDiagnostics: workflowGraph.ok ? [] : workflowGraph.diagnostics,
    },
  };
}

async function tool_result_selection_run(args, ctx, dependencies = {}) {
  const selectionId = String(args?.selectionId || '').trim();
  const action = String(args?.action || 'go_kegg').trim();
  const projectId = String(ctx?.projectId || '').trim();
  if (!ctx?.userId) return fail('unauthorized', '未授权');
  if (!selectionId || !projectId) return fail('selection_and_project_required', '需要 selectionId 和当前 projectId');
  if (!SAFE_SELECTION_ID.test(selectionId)) return fail('selection_id_invalid', 'SelectionContext id 不能用于项目路径');
  if (action !== 'go_kegg') return fail('selection_action_unsupported', '当前只允许已声明的 GO/KEGG 下游动作');

  const sqlite = dependencies.sqlite || dbMod.getDatabase();
  const repository = dependencies.repository || createResultStudioRepository(sqlite);
  const selection = repository.getSelection(selectionId);
  if (!selection) return fail('selection_not_found', '没有找到该 SelectionContext');
  if (selection.projectId !== projectId) return fail('selection_project_mismatch', '选择不属于当前项目');
  if (selection.displayState?.durable === false) return fail('selection_not_durable', '该选择没有稳定实体映射');
  if (selection.entityType !== 'gene') return fail('selection_entity_unsupported', 'GO/KEGG 目前只接受 gene 选择');

  const revision = selection.revisionId ? repository.getRevision(selection.revisionId) : null;
  if (!revision || revision.projectId !== projectId || revision.artifactId !== selection.artifactId) {
    return fail('selection_revision_invalid', '选择无法绑定到同项目的正式 ArtifactRevision');
  }
  const currentRevision = repository.getCurrentRevision(revision.artifactFamilyId);
  const compatibility = assessSelectionCompatibility({
    selection,
    projectId,
    artifactId: revision.artifactId,
    revisionId: currentRevision?.revisionId || null,
    selectionDurable: true,
  });
  if (compatibility.status !== 'compatible') {
    return fail('selection_not_compatible', '选择已过期或不可用于当前结果', compatibility);
  }

  const project = dependencies.getProject ? dependencies.getProject(projectId) : dbMod.getProject(projectId);
  if (!project?.workspace_path) return fail('project_workspace_missing', '项目工作区不可用');
  const workspaceRoot = fs.realpathSync(project.workspace_path);
  const revisionPath = fs.realpathSync(path.join(workspaceRoot, revision.outputPath));
  if (!isPathContained(workspaceRoot, revisionPath) || !fs.statSync(revisionPath).isFile()) {
    return fail('selection_source_outside_project', '选择来源不在项目工作区内');
  }
  if (!revision.outputHash || sha256File(revisionPath) !== revision.outputHash) {
    return fail('selection_source_hash_drift', '选择来源已偏离 Artifact Truth');
  }

  const sourceJob = dependencies.getToolJob ? dependencies.getToolJob(revision.toolJobId) : dbMod.getToolJob(revision.toolJobId);
  const sourcePlugin = dependencies.getPluginManifest
    ? dependencies.getPluginManifest(sourceJob?.tool_id)
    : pluginLoader.getPluginManifest(sourceJob?.tool_id);
  const descriptor = sourcePlugin?.resultStudio;
  const artifactDescriptor = descriptor?.artifacts?.find((item) =>
    item.id === revision.artifactId || item.filename === path.basename(revision.outputPath));
  const mapping = descriptor?.interactionMappings?.find((item) => item.artifactId === artifactDescriptor?.id);
  const idField = mapping?.idField || mapping?.rowIdField;
  if (!idField || !Array.isArray(descriptor?.actions) || !descriptor.actions.includes('derive_enrichment_input')) {
    return fail('selection_action_not_declared', '来源插件没有声明稳定 gene 映射或富集派生动作');
  }
  const sourceVerification = verifyImmutableRevision({
    projectId, project, revision, repository, sourceJob, dependencies,
  });
  if (!sourceVerification.ok) return sourceVerification;
  let backingName = path.basename(revision.outputPath);
  if (mapping.dataFile) backingName = mapping.dataFile;
  else if (mapping.dataArtifactId) {
    backingName = descriptor.artifacts.find((item) => item.id === mapping.dataArtifactId)?.filename || '';
  }
  if (!backingName || path.basename(backingName) !== backingName || backingName.includes('..')) {
    return fail('selection_backing_data_invalid', '插件 backing data 声明无效');
  }
  let sourcePath;
  try { sourcePath = fs.realpathSync(path.join(path.dirname(revisionPath), backingName)); }
  catch { return fail('selection_backing_data_missing', '选择 backing data 不存在'); }
  if (!isPathContained(path.dirname(revisionPath), sourcePath) || !fs.statSync(sourcePath).isFile()) {
    return fail('selection_backing_data_outside_job', '选择 backing data 不在同一 Job 输出中');
  }
  let expectedBackingSha256 = revision.outputHash;
  if (sourcePath !== revisionPath) {
    const backingTruth = resolveBackingArtifactTruth({
      sourceJob,
      descriptor,
      mapping,
      backingName,
      sourcePath,
    });
    if (!backingTruth.ok) return backingTruth;
    expectedBackingSha256 = backingTruth.expectedSha256;
  }

  let resolved;
  try {
    resolved = queryResultTable({
      filePath: sourcePath,
      expectedSha256: expectedBackingSha256,
      idField,
      filterExpression: selection.filterExpression,
      sort: selection.sort,
      limit: 1,
      includeEntityIds: true,
    });
  } catch (error) {
    return fail(error.code || 'selection_resolution_failed', error.message);
  }
  if (sha256File(sourcePath) !== expectedBackingSha256) {
    return fail('selection_backing_data_hash_drift', '选择 backing data 已偏离 Artifact Truth');
  }
  const sourceIds = resolved.resolvedEntityIds || [];
  let selectedIds;
  if (selection.entityIdsTruncated) {
    if (selection.entityIdCount !== resolved.selectionEvidence.entityIdCount
        || selection.entityIdsHash !== resolved.selectionEvidence.entityIdsHash
        || selection.filterHash !== resolved.filterHash) {
      return fail('selection_query_evidence_drift', '筛选结果已变化，不能静默复用旧选择');
    }
    selectedIds = sourceIds;
  } else {
    const explicitHash = crypto.createHash('sha256')
      .update(JSON.stringify([...selection.entityIds].sort()))
      .digest('hex');
    if (selection.entityIdsHash !== explicitHash) {
      return fail('selection_entity_hash_drift', '显式选择的实体摘要已变化，不能继续物化');
    }
    const available = new Set(sourceIds);
    selectedIds = selection.entityIds.filter((id) => available.has(id));
    if (selectedIds.length !== selection.entityIds.length) {
      return fail('selection_entity_missing', '部分选择实体已不在当前 Artifact 中');
    }
  }
  if (selectedIds.length < 3) return fail('selection_too_small', 'GO/KEGG 至少需要 3 个基因');
  if (selectedIds.length > MAX_DOWNSTREAM_ENTITY_IDS) {
    return fail('selection_too_large', `GO/KEGG 派生选择最多允许 ${MAX_DOWNSTREAM_ENTITY_IDS} 个基因`);
  }

  const relativeDir = path.posix.join('analysis', 'selections', selectionId);
  let idsFile;
  let scriptFile;
  let geneFile;
  try {
    idsFile = atomicWriteSelectionFile(
      workspaceRoot,
      selectionId,
      'selection-ids.json',
      `${JSON.stringify({ selectionId, entityType: 'gene', entityIds: selectedIds }, null, 2)}\n`,
    );
    scriptFile = atomicWriteSelectionFile(workspaceRoot, selectionId, 'materialize-selection.R', [
      '#!/usr/bin/env Rscript',
      '# Reproduce the exact SelectionContext-derived GO/KEGG input.',
      'suppressMessages(library(jsonlite))',
      '`%||%` <- function(a, b) if (is.null(a)) b else a',
      'args <- commandArgs(trailingOnly = TRUE)',
      'root <- if (length(args)) args[[1]] else getwd()',
      'payload <- fromJSON(file.path(root, "selection-ids.json"), simplifyVector = TRUE)',
      'write.csv(data.frame(gene = payload$entityIds), file.path(root, "gene-list.csv"), row.names = FALSE)',
      '',
    ].join('\n'));
    geneFile = atomicWriteSelectionFile(
      workspaceRoot,
      selectionId,
      'gene-list.csv',
      `gene\n${selectedIds.map(csvCell).join('\n')}\n`,
    );
  } catch (error) {
    return fail(
      error?.code || 'selection_materialization_failed',
      '选择物化路径不安全，未启动下游分析。',
    );
  }

  const runTool = dependencies.runTool || require('./learning').tool_run_tool;
  const resultStudioInputLineage = {
    deg_table: {
      lineageVersion: 1,
      kind: 'selection',
      sourceRevisionId: revision.revisionId,
      sourceToolJobId: revision.toolJobId,
      sourceArtifactId: revision.artifactId,
      sourceOutputHash: revision.outputHash,
      selectionId: selection.selectionId,
      selectionHash: selection.entityIdsHash,
      materializationHash: sha256File(geneFile),
    },
  };
  const executed = await runTool({
    op: 'run',
    toolId: 'go-kegg',
    params: {
      deg_table: geneFile,
      species: args?.species || 'human',
      gene_id_type: args?.geneIdType || 'auto',
      analysis_type: args?.analysisType || 'all',
    },
  }, { ...ctx, resultStudioInputLineage });

  // Once the real downstream Job is terminal, snapshot the graph projected
  // from its persisted provenance.  A failed/partial run never gains a DAG.
  const workflowGraph = persistVerifiedWorkflowGraph({
    projectId,
    sourceToolJobId: revision.toolJobId,
    repository,
    executed,
    dependencies,
  });
  const workflowFailure = failClosedWorkflowAction(executed, workflowGraph);
  if (workflowFailure) return workflowFailure;
  return {
    ...executed,
    selectionAction: {
      selectionId,
      action,
      entityIdCount: selectedIds.length,
      entityIdsHash: selection.entityIdsHash,
      sourceRevisionId: revision.revisionId,
      materialization: {
        script: path.posix.join(relativeDir, 'materialize-selection.R'),
        parameters: path.posix.join(relativeDir, 'selection-ids.json'),
        output: path.posix.join(relativeDir, 'gene-list.csv'),
      },
      executorTruth: 'run_tool → tool_job → artifact truth',
      workflowGraph: workflowGraph.ok
        ? { graphId: workflowGraph.graph.graphId, sourceDigest: workflowGraph.graph.sourceDigest, validationStatus: workflowGraph.graph.validationStatus }
        : null,
      workflowDiagnostics: workflowGraph.ok ? [] : workflowGraph.diagnostics,
    },
  };
}

module.exports = {
  MAX_DOWNSTREAM_ENTITY_IDS,
  tool_result_selection_run,
  tool_result_enrichment_from_revision,
};

'use strict';

/**
 * BLOCK-49 — 多 Agent 派生工具面（spawn_agent / list_agents / wait_agent）
 *
 * 设计边界：
 * - 进程内直接复用既有 subagent 执行链（agent-task-store + runAgentLoop +
 *   aiTaskConcurrency*），与 routes/ai-agent/chat.js 的 HTTP 派生分支同一套
 *   校验/并发/取消语义，不走 HTTP 自调用。
 * - 权限 fail-closed：spawn_agent 声明为 state-write（R2），在 agent-tool-policy
 *   层即要求 full accessMode（read / workspace-write 一律拒绝）；子 agent 整体
 *   继承父 context（含 accessMode/projectId），不提供任何提权口。
 * - 只有 primary 主 loop 可以派生（子 agent 不允许再生子 agent）；wait_agent
 *   只允许等待当前任务（ctx.taskId）派生的子 agent，且校验 userId。
 * - runAgentLoop / db 懒加载（避免 registry 模块初始化期的 require 环），
 *   与 chat.js 路由内懒加载同一手法。
 * - 终态摘要受 token 预算截断（P2 回传协议），优先返回结构化关键字段。
 */

const agentTaskStore = require('../agent-task-store');
const agentRoles = require('./agent-roles');
const {
  getAiSettings,
  getChatModelPreset,
  getChatModelCredential,
  getChatProviderName,
} = require('../helpers/ai-settings');
const { aiTaskConcurrencyAcquire, aiTaskConcurrencyRelease } = require('../helpers/runtime');
const { getOrCreateActiveConversation, getAssistantMessageByTaskId } = require('../helpers/conversations');

const MAX_TASK_CHARS = 8000;
const MAX_INSTRUCTIONS_CHARS = 4000;
const WAIT_POLL_INTERVAL_MS = 1000;
const WAIT_DEFAULT_TIMEOUT_MS = 300000;
const WAIT_MIN_TIMEOUT_MS = 1000;
const WAIT_MAX_TIMEOUT_MS = 600000;
const SUMMARY_TOKEN_BUDGET = 4000;
const SUMMARY_FILES_LIMIT = 20;
// 终态落库与 assistant 消息落库之间存在毫秒级窗口：done 后短暂重试读摘要文本
const SUMMARY_TEXT_RETRY_MS = 2500;
const SUMMARY_TEXT_RETRY_INTERVAL_MS = 500;
// tasks.status 终态集（markAgentTaskDone 写 status='completed'；retry_pending 非终态）
const TERMINAL_TASK_STATUSES = new Set(['completed', 'failed', 'cancelled']);

function fail(error, message, extra = {}) {
  return { ok: false, error, message, ...extra };
}

function clampWaitTimeoutMs(value) {
  const n = Number(value);
  if (!Number.isFinite(n)) return WAIT_DEFAULT_TIMEOUT_MS;
  return Math.min(WAIT_MAX_TIMEOUT_MS, Math.max(WAIT_MIN_TIMEOUT_MS, Math.round(n)));
}

// 摘要 token 预算：按最坏密度 1 token/char（CJK cl100k 近似上界）折算为字符上限。
// 刻意不对大文本跑 countTokens/tiktoken——单次 60k 字符编码即 ~4s，会阻塞事件循环；
// 字符上限保证摘要 ≤ budgetTokens（英文实际占用远低于上界），父上下文预算依然成立。
function truncateToTokenBudget(text, budgetTokens = SUMMARY_TOKEN_BUDGET) {
  const out = String(text || '');
  const budget = Math.max(1, Number(budgetTokens) || SUMMARY_TOKEN_BUDGET);
  if (!out.trim()) return { text: '', truncated: false };
  if (out.length <= budget) return { text: out, truncated: false };
  return { text: out.slice(0, budget) + '\n…（摘要已按 token 预算截断）', truncated: true };
}

// 显式 model 参数按 preset.model / preset.id 精确解析；解析不到一律 fail-closed，
// 绝不静默回退到其他模型（模型是子 agent 的能力契约，不是可协商项）。
function resolvePresetByModel(modelName) {
  const target = String(modelName || '').trim().toLowerCase();
  if (!target) return null;
  let presets = [];
  try {
    presets = (getAiSettings() && getAiSettings().chat_model_presets) || [];
  } catch {}
  return (
    presets.find((p) => String(p && p.model || '').toLowerCase() === target) ||
    presets.find((p) => String(p && p.id || '').toLowerCase() === target) ||
    null
  );
}

// 与 chat.js subagent 分支同一模型解析链：显式 model → 继承父 model preset →
// 父任务参数精确合成（BLOCK-49 起 chat.js 落库 profileId/baseUrl）→ active preset
function resolveSpawnModelSettings({ explicitModel, parentParams }) {
  if (explicitModel) {
    const preset = resolvePresetByModel(explicitModel);
    if (!preset) return { error: `未找到模型「${explicitModel}」对应的已配置模型 preset，拒绝派生（fail-closed）` };
    return { preset };
  }
  const parentPreset = resolvePresetByModel(parentParams && parentParams.modelName);
  if (parentPreset) return { preset: parentPreset };
  if (parentParams && parentParams.providerName) {
    return {
      preset: {
        id: parentParams.profileId || parentParams.providerName,
        provider: parentParams.providerName,
        label: parentParams.providerLabel,
        model: parentParams.modelName,
        baseUrl: parentParams.baseUrl,
      },
    };
  }
  return { preset: getChatModelPreset() };
}

/**
 * spawn_agent — 派生子 agent（异步启动，立即返回 agentId）。
 * @param {{task: string, model?: string, instructions?: string}} args
 * @param {{userId: string, taskId: string, context?: object}} ctx 父 loop 的 toolCtx
 */
async function spawn_agent(args, ctx) {
  const taskText = String((args && args.task) || '').trim();
  if (!taskText) return fail('invalid_arguments', 'task 不能为空：请给出清晰具体的子任务描述。');
  if (taskText.length > MAX_TASK_CHARS) {
    return fail('invalid_arguments', `task 过长（${taskText.length} > ${MAX_TASK_CHARS} 字符），请拆分子任务。`);
  }
  const instructions = String((args && args.instructions) || '').trim();
  if (instructions.length > MAX_INSTRUCTIONS_CHARS) {
    return fail('invalid_arguments', `instructions 过长（> ${MAX_INSTRUCTIONS_CHARS} 字符）。`);
  }

  const parentTaskId = ctx && ctx.taskId;
  const userId = ctx && ctx.userId;
  if (!parentTaskId || !userId) {
    return fail('no_parent', 'spawn_agent 只能在主 agent 会话循环内调用。');
  }

  // 父任务校验（与 chat.js subagent 分支同一语义；loop 内调用时父任务必然 running，
  // 但仍然完整复核，不信任调用时机）
  const parentTask = agentTaskStore.getAgentTask(parentTaskId);
  if (!parentTask) return fail('parent_not_found', '父任务不存在。');
  if (parentTask.userId && parentTask.userId !== userId) {
    return fail('permission_denied', '无权以该任务派生子 agent。');
  }
  if ((parentTask.params && parentTask.params.kind || 'primary') !== 'primary') {
    return fail('parent_not_primary', '只有主 agent 会话可以派生子 agent（子 agent 不允许再生子 agent）。');
  }
  if (parentTask.status !== 'running' || parentTask.agentStatus !== 'running') {
    return fail('parent_not_running', '父任务已结束，不能再派生子 agent。');
  }

  const parentParams = parentTask.params || {};
  const parentContext = parentParams.context || {};
  // 权限继承：子 agent 整体继承父 context（accessMode/projectId 等）。
  // spawn 本身已被 policy 限制为 full accessMode，因此继承结果是确定的。
  const context = { ...parentContext };
  if (ctx.accessMode && !context.accessMode) context.accessMode = ctx.accessMode;

  const model = resolveSpawnModelSettings({ explicitModel: args && args.model, parentParams });
  if (model.error) return fail('invalid_arguments', model.error);

  // BLOCK-93 P1 — 角色专职化：role 可选参数（注册表校验，未知 fail-closed；
  // 未传＝通用缺省，零行为变化）。
  const roleCheck = agentRoles.resolveRoleOrError(args && args.role);
  if (!roleCheck.ok) return roleCheck.fail;

  const userContent = instructions ? `${taskText}\n\n${instructions}` : taskText;

  return launchSubAgent({
    parentTaskId,
    userId,
    parentParams,
    parentContext,
    userContent,
    model,
    role: roleCheck.role,
    spawnSource: 'tool:spawn_agent',
  });
}

/**
 * launchSubAgent — 创建子 agent 任务 + 并发槽 + 异步启动 loop。
 * BLOCK-49 二期：从 spawn_agent 抽取核心，spawn_agent / followup_task 共用。
 * BLOCK-93 P1：role（可选角色 key）随 params 落库 + 注册表指令片段注入 system prompt。
 * @returns {{ok:true, agentId:string, model?:string, role?:string} | {ok:false, error, message, ...}}
 */
function launchSubAgent({ parentTaskId, userId, parentParams, parentContext, userContent, model, role, spawnSource }) {
  const context = { ...(parentContext || {}) };
  if (model.accessModeHint && !context.accessMode) context.accessMode = model.accessModeHint;
  const preset = model.preset;
  const providerName = (preset && preset.provider) || parentParams.providerName || getChatProviderName();
  const providerLabel = parentParams.providerLabel || providerName;
  const modelName = (preset && preset.model) || parentParams.modelName;
  // BLOCK-93 P1 — prompt 软约束：注册表指令片段（未知 key 时 renderRoleDirective
  // 返回 null＝零注入；上游已做 fail-closed 校验，此处是纵深）
  const roleDirective = role ? agentRoles.renderRoleDirective(role) : null;

  // 会话复用：与 chat.js subagent 分支一致，子 agent 挂在父会话下
  let _activeConv = null;
  try {
    _activeConv = getOrCreateActiveConversation(userId, {
      conversationId: parentParams.conversationId,
      page: parentContext.page,
      projectId: parentContext.projectId,
    });
  } catch {}

  let taskId;
  try {
    taskId = agentTaskStore.createAgentTask({
      status: 'running',
      agentStatus: 'running',
      userId,
      params: {
        messages: [{ role: 'user', content: userContent }],
        context,
        conversationId: _activeConv && _activeConv.id,
        providerName,
        providerLabel,
        modelName,
        kind: 'subagent',
        parentTaskId,
        spawnSource,
        ...(role ? { role } : {}),
        // BLOCK-88 P2（D3）— 联邦委托派生的 subagent 继承访客归属
        //（俯瞰面板 federatedFrom 角标数据源；宿主本地派生恒 undefined）。
        ...(parentParams && parentParams.federated ? { federated: parentParams.federated } : {}),
      },
    }).taskId;
  } catch (e) {
    return { ok: false, error: 'spawn_failed', message: '创建子 agent 任务失败: ' + (e && e.message ? e.message : String(e)) };
  }

  // 并发槽（与 chat.js 同序：先建任务再 acquire；失败即标 failed 并如实回传）
  const acquired = aiTaskConcurrencyAcquire(userId, taskId, { isPrimary: false });
  if (!acquired || acquired.ok === false) {
    try { agentTaskStore.markAgentTaskFailed(taskId, '并发限制'); } catch {}
    return fail(
      'subagent_concurrency_limit',
      '子 agent 并发槽已满，请等待现有子 agent 完成后再派生（可用 list_agents 查看在跑子 agent）。',
      // 任务行已建（failed 终态），回传 agentId 供追溯
      { agentId: taskId, reason: acquired && acquired.reason }
    );
  }

  // 懒加载打断 require 环（agent-runner → agent-tools → registry → 本模块）
  const { runAgentLoop } = require('../agent-runner');
  const dbMod = require('../db');
  let parentLoopRunId = null;
  try {
    const parentLoop = dbMod.getLoopRunByTaskId(parentTaskId);
    parentLoopRunId = (parentLoop && parentLoop.loopRunId) || null;
  } catch {}

  setImmediate(() => {
    runAgentLoop({
      messages: [{ role: 'user', content: userContent }],
      context,
      userId,
      conversationId: _activeConv && _activeConv.id,
      _activeConv,
      apiKey: getChatModelCredential(preset),
      providerName,
      providerLabel,
      modelName,
      profileId: preset && preset.id,
      baseUrl: preset && preset.baseUrl,
      taskId,
      kind: 'subagent',
      parentLoopRunId,
      // BLOCK-93 P1 — 角色软约束注入（未传＝null＝零变化）
      roleDirective: roleDirective || null,
      onEvent: () => {},
      shouldAbort: () => agentTaskStore.isAgentTaskCancellationRequested(taskId),
      // BLOCK-56 P1 单级不连环：子 agent 内禁用请求级 fallback
      disableProviderFallback: true,
    }).catch((e) => {
      try { agentTaskStore.markAgentTaskFailed(taskId, e && e.message ? e.message : String(e)); } catch {}
      try { aiTaskConcurrencyRelease(userId, taskId); } catch {}
    });
  });

  return { ok: true, agentId: taskId, status: 'running', kind: 'subagent', model: modelName || undefined, ...(role ? { role } : {}) };
}

// ── BLOCK-49 二期：运行中协作三件套 ──────────────────────────

/** 事件流末尾 seq（appendAgentTaskEvent 需要显式 seq）。 */
function nextEventSeq(taskId) {
  const events = agentTaskStore.getAgentTaskEventsSince(taskId, 0, 5000) // BLOCK-102 P4 cap;
  return (events.length ? events[events.length - 1].seq : 0) + 1;
}

/** 校验 agentId 属于当前任务的子 agent，返回子任务行或 fail 响应。 */
function findOwnChildOrFail(parentTaskId, agentId) {
  if (!agentId) {
    return { error: fail('invalid_arguments', '缺少 agentId。') };
  }
  const child = agentTaskStore.listChildAgentTasks(parentTaskId).find((t) => t.taskId === agentId);
  if (!child) {
    return { error: fail('not_your_agent', '该 agentId 不属于当前任务派生的子 agent（或不存在）。') };
  }
  return { child };
}

/**
 * interrupt_agent — 中断运行中的子 agent（cancel_requested，子 loop 在下一
 * 检查点让出；级联覆盖其派生链）。已终态时幂等返回。
 */
async function interrupt_agent(args, ctx) {
  const parentTaskId = ctx && ctx.taskId;
  const userId = ctx && ctx.userId;
  if (!parentTaskId || !userId) return fail('no_parent', 'interrupt_agent 只能在 agent 会话循环内调用。');
  const { child, error } = findOwnChildOrFail(parentTaskId, String((args && args.agentId) || '').trim());
  if (error) return error;

  if (TERMINAL_TASK_STATUSES.has(child.status)) {
    return { ok: true, agentId: child.taskId, alreadyTerminal: true, status: child.status };
  }
  const dbMod = require('../db');
  const { cancelledTaskIds } = agentTaskStore.cancelAgentTaskCascade(child.taskId, { dbMod });
  try {
    agentTaskStore.appendAgentTaskEvent(
      child.taskId, nextEventSeq(child.taskId), 'interrupt_requested',
      { by: 'parent', parentTaskId, at: new Date().toISOString() },
    );
  } catch {}
  return {
    ok: true,
    agentId: child.taskId,
    agentStatus: 'cancel_requested',
    cancelledTaskIds,
    message: '中断请求已发出；子 agent 将在下一个取消检查点让出，wait_agent 会返回其终态摘要。',
  };
}

/**
 * send_message — 向子 agent 投递父消息（持久化到其事件流，followup_task
 * 续派时作为上下文注入）。运行中即时注入 loop 需改 agent-runner 核心，
 * 二期 v1 为持久化队列语义（诚实登记）。
 */
async function send_message(args, ctx) {
  const parentTaskId = ctx && ctx.taskId;
  const userId = ctx && ctx.userId;
  if (!parentTaskId || !userId) return fail('no_parent', 'send_message 只能在 agent 会话循环内调用。');
  const message = String((args && args.message) || '').trim();
  if (!message) return fail('invalid_arguments', 'message 不能为空。');
  if (message.length > MAX_TASK_CHARS) return fail('invalid_arguments', `message 过长（> ${MAX_TASK_CHARS} 字符）。`);
  const { child, error } = findOwnChildOrFail(parentTaskId, String((args && args.agentId) || '').trim());
  if (error) return error;

  if (TERMINAL_TASK_STATUSES.has(child.status)) {
    return fail('agent_terminal', '子 agent 已结束；请用 followup_task 追加任务（消息将随续派注入）。', { agentId: child.taskId, status: child.status });
  }
  try {
    agentTaskStore.appendAgentTaskEvent(
      child.taskId, nextEventSeq(child.taskId), 'parent_message',
      { message, from: 'parent', at: new Date().toISOString() },
    );
  } catch (e) {
    return fail('queue_failed', '消息入队失败: ' + (e && e.message ? e.message : String(e)));
  }
  return {
    ok: true,
    agentId: child.taskId,
    queued: true,
    note: '消息已入队（子 agent 事件流可见）。运行中即时注入需 loop 核心支持（登记候选）；'
      + '当前该消息将在 followup_task 续派该子 agent 时作为上下文注入。',
  };
}

/**
 * followup_task — 对已终态子 agent 追加任务：以前次摘要 + 队列消息为上下文
 * 续派新子 agent（复用 spawn 启动核心，模型/权限继承链一致）。
 */
async function followup_task(args, ctx) {
  const parentTaskId = ctx && ctx.taskId;
  const userId = ctx && ctx.userId;
  if (!parentTaskId || !userId) return fail('no_parent', 'followup_task 只能在 agent 会话循环内调用。');
  const taskText = String((args && args.task) || '').trim();
  if (!taskText) return fail('invalid_arguments', 'task 不能为空：请给出追加的子任务描述。');
  if (taskText.length > MAX_TASK_CHARS) return fail('invalid_arguments', `task 过长（${taskText.length} > ${MAX_TASK_CHARS} 字符）。`);
  const { child, error } = findOwnChildOrFail(parentTaskId, String((args && args.agentId) || '').trim());
  if (error) return error;
  if (!TERMINAL_TASK_STATUSES.has(child.status)) {
    return fail('agent_running', '子 agent 仍在运行；先 wait_agent 等终态，或用 interrupt_agent 中断后续派。', { agentId: child.taskId, status: child.status });
  }

  const childFull = agentTaskStore.getAgentTask(child.taskId);
  const parentTask = agentTaskStore.getAgentTask(parentTaskId);
  const parentParams = parentTask.params || {};
  const summary = await buildTerminalSummary(childFull);

  // 队列消息取出（消费即清：事件流保留审计，续派提示只带未消费语义）
  const queued = agentTaskStore.getAgentTaskEventsSince(child.taskId, 0, 1000000)
    .filter((e) => e.eventType === 'parent_message')
    .map((e) => {
      // payload 形状双兼容：store 读取已解析为对象；字符串形状防御性保留
      try {
        const raw = typeof e.payload === 'string' ? JSON.parse(e.payload || '{}') : (e.payload || {});
        return String(raw.message || '').slice(0, 500);
      } catch { return ''; }
    })
    .filter(Boolean);

  const parts = [
    `【续派任务】你此前完成了以下任务，现在基于前情继续：`,
    `原任务：${summary.task}`,
  ];
  if (summary.assistantText) parts.push('前次产出摘要：\n' + summary.assistantText);
  if (queued.length) {
    parts.push('期间收到父消息：\n' + queued.map((m) => '- ' + m).join('\n'));
  }
  parts.push(`请在此基础上继续新任务：${taskText}`);
  const userContent = parts.join('\n\n').slice(0, MAX_TASK_CHARS * 2);

  const model = resolveSpawnModelSettings({ explicitModel: args && args.model, parentParams });
  if (model.error) return fail('invalid_arguments', model.error);

  // BLOCK-93 P1 — 续派角色继承：显式 args.role 覆盖 > 原子 agent 角色 > 通用缺省
  const roleCheck = agentRoles.resolveRoleOrError(
    (args && args.role) || (childFull.params && childFull.params.role) || ''
  );
  if (!roleCheck.ok) return roleCheck.fail;

  const launched = launchSubAgent({
    parentTaskId,
    userId,
    parentParams,
    parentContext: parentParams.context || {},
    userContent,
    model,
    role: roleCheck.role,
    spawnSource: 'tool:followup_task',
  });
  if (launched.ok === false) return launched;
  return {
    ok: true,
    agentId: launched.agentId,
    followupOf: child.taskId,
    status: 'running',
    queuedMessagesInjected: queued.length,
    model: launched.model || undefined,
    ...(roleCheck.role ? { role: roleCheck.role } : {}),
  };
}

/**
 * queueUserMessage — 用户侧留言等价（BLOCK-65 P1-a）：agent 专属窗（用户操作）
 * 对运行中子 agent 留言。语义与 send_message 工具单源（持久化 parent_message
 * 事件 + 队列语义：followup_task 续派时注入）；差异仅在归属校验——工具版要求
 * 调用方是父 loop ctx，本函数面向 HTTP 用户态（子任务真实存在即可）。
 */
function queueUserMessage({ childTaskId, message }) {
  const text = String(message || '').trim();
  if (!text) return { ok: false, error: 'invalid_arguments', message: 'message 不能为空。' };
  if (text.length > MAX_TASK_CHARS) return { ok: false, error: 'invalid_arguments', message: `message 过长（> ${MAX_TASK_CHARS} 字符）。` };
  const child = agentTaskStore.getAgentTask(childTaskId);
  if (!child) return { ok: false, error: 'not_found', message: '子 agent 不存在。' };
  if (TERMINAL_TASK_STATUSES.has(child.status)) {
    return { ok: false, error: 'agent_terminal', message: '子 agent 已结束；请改用「继续派」追加任务（留言将随续派注入）。', status: child.status };
  }
  try {
    agentTaskStore.appendAgentTaskEvent(
      childTaskId, nextEventSeq(childTaskId), 'parent_message',
      { message: text, from: 'user_window', at: new Date().toISOString() },
    );
  } catch (e) {
    return { ok: false, error: 'queue_failed', message: '留言入队失败: ' + (e && e.message ? e.message : String(e)) };
  }
  return {
    ok: true,
    queued: true,
    note: '留言已入队（子 agent 事件流可见）。运行中即时注入需 loop 核心支持（登记候选）；'
      + '当前该留言将在「继续派」续派该子 agent 时作为上下文注入。',
  };
}

/**
 * launchUserFollowup — 用户侧续派等价（BLOCK-65 P1-a）：agent 专属窗在子
 * agent 终态后触发。任务组装语义与 followup_task 工具单源（前次摘要 + 队列
 * 留言 + 新任务）；父链取原任务 params.parentTaskId（模型/权限继承链一致）。
 */
async function launchUserFollowup({ childTaskId, userId, task }) {
  const taskText = String(task || '').trim();
  if (!taskText) return { ok: false, error: 'invalid_arguments', message: 'task 不能为空：请给出追加的子任务描述。' };
  if (taskText.length > MAX_TASK_CHARS) return { ok: false, error: 'invalid_arguments', message: `task 过长（${taskText.length} > ${MAX_TASK_CHARS} 字符）。` };
  const child = agentTaskStore.getAgentTask(childTaskId);
  if (!child) return { ok: false, error: 'not_found', message: '子 agent 不存在。' };
  const parentTaskId = child.params && child.params.parentTaskId;
  if (!parentTaskId) return { ok: false, error: 'no_parent', message: '该任务没有父派生链，无法续派。' };
  if (!TERMINAL_TASK_STATUSES.has(child.status)) {
    return { ok: false, error: 'agent_running', message: '子 agent 仍在运行；请先中断再续派。', status: child.status };
  }
  const parentTask = agentTaskStore.getAgentTask(parentTaskId);
  if (!parentTask) return { ok: false, error: 'parent_gone', message: '父任务已不存在，无法延续派生链。' };
  const parentParams = parentTask.params || {};
  const summary = await buildTerminalSummary(child);

  const queued = agentTaskStore.getAgentTaskEventsSince(child.taskId, 0, 1000000)
    .filter((e) => e.eventType === 'parent_message')
    .map((e) => {
      try {
        const raw = typeof e.payload === 'string' ? JSON.parse(e.payload || '{}') : (e.payload || {});
        return String(raw.message || '').slice(0, 500);
      } catch { return ''; }
    })
    .filter(Boolean);

  const parts = [
    `【续派任务】你此前完成了以下任务，现在基于前情继续：`,
    `原任务：${summary.task}`,
  ];
  if (summary.assistantText) parts.push('前次产出摘要：\n' + summary.assistantText);
  if (queued.length) {
    parts.push('期间收到消息：\n' + queued.map((m) => '- ' + m).join('\n'));
  }
  parts.push(`请在此基础上继续新任务：${taskText}`);
  const userContent = parts.join('\n\n').slice(0, MAX_TASK_CHARS * 2);

  const model = resolveSpawnModelSettings({ explicitModel: undefined, parentParams });
  if (model.error) return { ok: false, error: 'invalid_arguments', message: model.error };

  // BLOCK-93 P1 — 用户侧续派同样继承原子 agent 角色（无显式覆盖入参）
  const roleCheck = agentRoles.resolveRoleOrError((child.params && child.params.role) || '');
  if (!roleCheck.ok) return { ok: false, error: 'invalid_arguments', message: roleCheck.fail.message };

  const launched = launchSubAgent({
    parentTaskId,
    userId,
    parentParams,
    parentContext: parentParams.context || {},
    userContent,
    model,
    role: roleCheck.role,
    spawnSource: 'user:followup',
  });
  if (launched.ok === false) return launched;
  return {
    ok: true,
    agentId: launched.agentId,
    followupOf: child.taskId,
    status: 'running',
    queuedMessagesInjected: queued.length,
    model: launched.model || undefined,
    ...(roleCheck.role ? { role: roleCheck.role } : {}),
  };
}

/**
 * list_agents — 列出当前任务派生的全部子 agent（含终态）。
 */
async function list_agents(args, ctx) {
  const parentTaskId = ctx && ctx.taskId;
  if (!parentTaskId) return fail('no_parent', 'list_agents 只能在 agent 会话循环内调用。');
  const children = agentTaskStore.listChildAgentTasks(parentTaskId);
  return {
    ok: true,
    agents: children.map((t) => ({
      agentId: t.taskId,
      status: t.status,
      agentStatus: t.agentStatus,
      task: String(t.params && t.params.messages && t.params.messages[0] && t.params.messages[0].content || '').slice(0, 120),
      // BLOCK-93 P1 — 角色透出（未指定角色的历史任务不带此字段）
      ...(t.params && t.params.role ? { role: t.params.role } : {}),
      createdAt: t.createdAt,
      finishedAt: t.finishedAt || undefined,
      error: t.error || undefined,
    })),
  };
}

/**
 * wait_agent — 阻塞等待指定子 agent 终态，返回 token 预算内摘要。
 * 只允许等待当前任务派生的子 agent（parentTaskId + userId 双重校验）。
 * @param {{agentId: string, timeout?: number}} args
 */
async function wait_agent(args, ctx) {
  const parentTaskId = ctx && ctx.taskId;
  const userId = ctx && ctx.userId;
  if (!parentTaskId || !userId) return fail('no_parent', 'wait_agent 只能在 agent 会话循环内调用。');
  const agentId = String((args && args.agentId) || '').trim();
  if (!agentId) return fail('invalid_arguments', '缺少 agentId。');

  const first = agentTaskStore.getAgentTask(agentId);
  if (!first) return fail('agent_not_found', '子 agent 不存在。');
  if (first.userId && first.userId !== userId) return fail('permission_denied', '无权等待该子 agent。');
  if (!first.params || first.params.parentTaskId !== parentTaskId) {
    return fail('agent_not_child', '只能等待当前会话派生的子 agent。');
  }

  const timeoutMs = clampWaitTimeoutMs(args && args.timeout);
  const startedAt = Date.now();
  const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

  for (;;) {
    const task = agentTaskStore.getAgentTask(agentId);
    if (!task) return fail('agent_not_found', '子 agent 不存在。');
    if (TERMINAL_TASK_STATUSES.has(task.status)) {
      const summary = await buildTerminalSummary(task);
      return {
        ok: true,
        agentId,
        status: task.status,
        agentStatus: task.agentStatus,
        summary,
      };
    }
    if (Date.now() - startedAt >= timeoutMs) {
      return {
        ok: false,
        error: 'wait_timeout',
        agentId,
        status: task.status,
        message: '等待超时，子 agent 仍在运行；可稍后再次调用 wait_agent，或用 list_agents 查看状态。',
      };
    }
    // 父 loop 被取消时立即让出，不空等
    if (typeof ctx.isCancelled === 'function' && ctx.isCancelled()) {
      return { ok: false, error: 'cancelled', agentId, status: task.status, message: '父任务已请求取消。' };
    }
    await sleep(WAIT_POLL_INTERVAL_MS);
  }
}

async function buildTerminalSummary(task) {
  const base = {
    task: String(task.params && task.params.messages && task.params.messages[0] && task.params.messages[0].content || '').slice(0, 120),
    // BLOCK-93 P1 — 角色随摘要回父（父上下文可感知子 agent 专职面）
    ...(task.params && task.params.role ? { role: task.params.role } : {}),
    error: task.error || undefined,
    filesChanged: Array.isArray(task.filesChanged) ? task.filesChanged.slice(0, SUMMARY_FILES_LIMIT) : [],
    filesChangedTruncated: Array.isArray(task.filesChanged) && task.filesChanged.length > SUMMARY_FILES_LIMIT,
  };
  if (task.status !== 'completed') return { ...base, assistantText: '', truncated: false };

  // done → assistant 消息落库存在毫秒级窗口，短暂重试；仍取不到则降级为无正文摘要
  let assistantMessage = getAssistantMessageByTaskId(task.taskId);
  const deadline = Date.now() + SUMMARY_TEXT_RETRY_MS;
  while (!assistantMessage && Date.now() < deadline) {
    await new Promise((resolve) => setTimeout(resolve, SUMMARY_TEXT_RETRY_INTERVAL_MS));
    assistantMessage = getAssistantMessageByTaskId(task.taskId);
  }
  const { text, truncated } = truncateToTokenBudget(assistantMessage && assistantMessage.content);
  return { ...base, assistantText: text, truncated };
}

module.exports = {
  spawn_agent,
  interrupt_agent,
  send_message,
  followup_task,
  list_agents,
  wait_agent,
  // BLOCK-65 P1-a：用户侧（HTTP）等价——agent 专属窗留言/续派，语义与工具版单源
  queueUserMessage,
  launchUserFollowup,
  // 测试钩子（不进入 registry）
  __test: { clampWaitTimeoutMs, truncateToTokenBudget, resolvePresetByModel },
};

'use strict';

/**
 * BLOCK-33 P1 — system_info 环境自省工具（只读、零副作用）。
 *
 * 让模型在编写/执行任何平台相关命令前先获取真实环境（OS / shell / 工具链版本），
 * 避免「猜平台 → 试探 uname → Windows 报错」的浪费轮次与误判。
 * 版本查询全部 5s 超时并行，失败诚实返回 null（不猜测、不编造）。
 */

const os = require('os');
const path = require('path');
const { execFile } = require('child_process');
const { promisify } = require('util');

const execFileAsync = promisify(execFile);
const VERSION_PROBE_TIMEOUT_MS = 5000;

function firstLine(value) {
  const text = String(value || '').trim();
  return text ? text.split('\n')[0].trim() : null;
}

async function probeVersion(command, args) {
  try {
    const result = await execFileAsync(command, args, {
      timeout: VERSION_PROBE_TIMEOUT_MS,
      windowsHide: true,
    });
    return firstLine(result.stdout);
  } catch {
    return null;
  }
}

function resolveShell() {
  if (process.platform === 'win32') {
    return process.env.ComSpec || 'cmd.exe';
  }
  return process.env.SHELL && path.isAbsolute(process.env.SHELL)
    ? process.env.SHELL
    : '/bin/sh';
}

/**
 * 环境自省。ctx 仅用于读取 projectId 归属；不需要项目工作区，
 * 只读模式下同样可用（模型需要知道环境才能正确描述只读检查方案）。
 *
 * BLOCK-67 P2：SSH 远程项目的环境真相 = 远程主机（模型编写命令前须知 OS/shell
 * 在远端，指挥席本机环境对工作区操作无意义）；传输失败诚实返回 remote_probe_failed。
 */
async function tool_system_info(args = {}, ctx = {}) {
  const projectId = ctx && ctx.projectId ? String(ctx.projectId) : null;
  if (projectId) {
    try {
      const db = require('../db');
      const project = typeof db.getProject === 'function' ? db.getProject(projectId) : null;
      if (project && project.workspace_kind === 'ssh') {
        const { resolveWorkspaceBackend } = require('../helpers/workspace-gateway');
        const resolved = resolveWorkspaceBackend(project);
        if (resolved.backend && resolved.backend.kind === 'ssh') {
          try {
            const raw = await resolved.backend.exec(
              'uname -sr; uname -m; echo "shell=$SHELL"; python3 --version 2>&1 | head -1; git --version 2>&1 | head -1; node --version 2>&1 | head -1',
              resolved.root,
              20
            );
            const lines = String(raw.stdout || '').split('\n').map((l) => l.trim()).filter(Boolean);
            const env = {};
            for (const line of lines) {
              if (line.startsWith('shell=')) env.shell = line.slice(6) || '/bin/sh';
              else if (/^Python \d/.test(line)) env.python = line;
              else if (/^git version/.test(line)) env.git = line;
              else if (/^v\d/.test(line)) env.node = line;
              else if (/\w/.test(line) && !env.os) env.os = line;
              else if (env.os && !env.arch) env.arch = line;
            }
            return {
              ok: true,
              workspace: {
                kind: 'ssh',
                host: project.ssh_host,
                remotePath: project.remote_path,
              },
              os: { platform: 'linux(远程探测)', type: null, release: null, arch: env.arch || null, detail: env.os || null },
              shell: env.shell || '/bin/bash',
              pathSeparator: '/',
              toolchain: { python: env.python || null, git: env.git || null, node: env.node || null },
              projectId,
              note:
                `当前项目是 SSH 远程项目：所有 workspace_* 工具与 workspace_exec 都在远程主机 ${project.ssh_host} 的 ${project.remote_path} 上执行（Linux/bash 语义，路径分隔符 /）；本机环境信息与工作区无关。`,
            };
          } catch (error) {
            return {
              ok: false,
              code: 'remote_probe_failed',
              error: `远程环境探测失败：${error && error.message ? error.message : 'unknown'}`,
              retryable: !!(error && error.classified && error.classified.retryable),
              projectId,
              note: `当前项目是 SSH 远程项目（host=${project.ssh_host}，root=${project.remote_path}），工作区操作全部在远端执行；探测失败不代表远端不可用，可重试或用 workspace_list 验证连通。`,
            };
          }
        }
      }
    } catch { /* 项目查询失败：回落本机自省（诚实本地结果） */ }
  }
  const shell = resolveShell();
  const [nodeVersion, npmVersion, pythonVersion, gitVersion] = await Promise.all([
    probeVersion('node', ['--version']),
    probeVersion('npm', ['--version']),
    probeVersion(process.platform === 'win32' ? 'python' : 'python3', ['--version']),
    probeVersion('git', ['--version']),
  ]);
  return {
    ok: true,
    os: {
      platform: process.platform,
      type: os.type(),
      release: os.release(),
      arch: os.arch(),
    },
    shell,
    pathSeparator: path.sep,
    hostname: os.hostname(),
    toolchain: {
      node: nodeVersion,
      npm: npmVersion,
      python: pythonVersion,
      git: gitVersion,
    },
    projectId: ctx && ctx.projectId ? ctx.projectId : null,
    note:
      'workspace_exec 的工作目录固定为当前项目根目录；每条命令都是独立 shell，cd 与环境变量不跨调用持久。',
  };
}

module.exports = { tool_system_info };

'use strict';

/**
 * agent-tools/todo-tools.js — BLOCK-97 P1 任务清单（todo）维护工具
 *
 * todo_write：整单幂等写入（全量替换，无增量 diff 并发序问题）。纯状态写入：
 * 不落业务表、不触发 LLM 推理。清单快照经 agent-runner 的 emitToolResult
 * 包裹点以专用 task_todo 事件广播，随 task_events 持久化——事件重放即持久化
 * （BLOCK-97 D1/D2 定案），重启后前端经 afterSeq=0 重放可重建清单。
 *
 * 不做 ctx.userId 门：清单是任务运行内的临时 UI 态（生命周期=单次任务运行，
 * 非用户数据写入），访客会话同样可用；纪律约束由 system prompt 注入承担。
 */

const TODO_STATUSES = Object.freeze(['pending', 'in_progress', 'completed']);
const MAX_ITEMS = 20;
const MAX_CONTENT_LENGTH = 300;
const MAX_ID_LENGTH = 64;

function normalizeTodoItems(rawItems) {
  if (!Array.isArray(rawItems) || rawItems.length === 0) {
    return { error: 'missing_args', message: '需要非空 items 数组（1-20 条）' };
  }
  if (rawItems.length > MAX_ITEMS) {
    return { error: 'too_many_items', message: `清单最多 ${MAX_ITEMS} 条` };
  }
  const items = [];
  for (let i = 0; i < rawItems.length; i++) {
    const raw = rawItems[i];
    if (!raw || typeof raw !== 'object' || Array.isArray(raw)) {
      return { error: 'invalid_item', message: `items[${i}] 必须是对象` };
    }
    const content = typeof raw.content === 'string' ? raw.content.trim() : '';
    if (!content) {
      return { error: 'invalid_item', message: `items[${i}].content 不能为空` };
    }
    if (content.length > MAX_CONTENT_LENGTH) {
      return {
        error: 'invalid_item',
        message: `items[${i}].content 超过 ${MAX_CONTENT_LENGTH} 字符`,
      };
    }
    if (!TODO_STATUSES.includes(raw.status)) {
      return {
        error: 'invalid_status',
        message: `items[${i}].status 必须是 ${TODO_STATUSES.join('/')}`,
      };
    }
    const id =
      typeof raw.id === 'string' && raw.id.trim()
        ? raw.id.trim().slice(0, MAX_ID_LENGTH)
        : String(i + 1);
    items.push({ id, content, status: raw.status });
  }
  return { items };
}

async function tool_todo_write(args) {
  const normalized = normalizeTodoItems(args && args.items);
  if (normalized.error) {
    return { ok: false, error: normalized.error, message: normalized.message };
  }
  const items = normalized.items;
  const completed = items.filter((item) => item.status === 'completed').length;
  const inProgress = items.filter((item) => item.status === 'in_progress').length;
  return {
    ok: true,
    items,
    total: items.length,
    completed,
    inProgress,
    message: `清单已更新（共 ${items.length} 条，完成 ${completed}，进行中 ${inProgress}）`,
  };
}

/**
 * task_todo 专用事件发射判定（BLOCK-97 D2 定案）：todo_write 成功回执后
 * 把整单快照广播给前端。agent-runner 的 emitToolResult 包裹点调用；
 * 返回是否发射，供契约测试断言。
 */
function maybeEmitTaskTodo(evt, emit) {
  if (typeof emit !== 'function' || !evt || evt.event !== 'tool_result') return false;
  if (evt.name !== 'todo_write') return false;
  const envelope = evt.toolResult;
  if (!envelope || envelope.status !== 'success') return false;
  const data = envelope.data;
  if (!data || !Array.isArray(data.items)) return false;
  emit({ event: 'task_todo', items: data.items });
  return true;
}

module.exports = {
  TODO_STATUSES,
  MAX_ITEMS,
  MAX_CONTENT_LENGTH,
  normalizeTodoItems,
  tool_todo_write,
  maybeEmitTaskTodo,
};

'use strict';

const { redactSensitiveValue } = require('../../shared-backend/redaction');

const PUBLIC_DATA_LIMIT = 1600;

function safeJson(value) {
  try {
    return JSON.stringify(value);
  } catch {
    return String(value);
  }
}

function publicData(data) {
  const redacted = redactSensitiveValue(data);
  const serialized = safeJson(redacted);
  if (serialized.length <= PUBLIC_DATA_LIMIT) return { data: redacted, truncated: false };
  return {
    data: { preview: `${serialized.slice(0, PUBLIC_DATA_LIMIT)}…` },
    truncated: true,
  };
}

// UI-273 增补 — 写操作的逐行改动（统计 + 截断 hunks）。挂在 toolResult 顶层而非 data 内：
// data 受 PUBLIC_DATA_LIMIT 截断，超限会被整体替换为 preview 字符串，diff 必须独立存活。
const CHANGE_DIFF_LIMIT = 4000;

function boundedChangeDiff(result) {
  if (!result || typeof result !== 'object') return undefined;
  const raw = result.changeDiff;
  if (!raw || typeof raw !== 'object') return undefined;
  const added = Number.isFinite(raw.added) ? raw.added : 0;
  const removed = Number.isFinite(raw.removed) ? raw.removed : 0;
  const hunks = Array.isArray(raw.hunks) ? raw.hunks : [];
  const base = { added, removed, truncated: raw.truncated === true, hunks };
  if (safeJson(base).length <= CHANGE_DIFF_LIMIT) return base;
  // 超限：保留诚实统计，丢弃精细 hunks
  return { added, removed, truncated: true, hunks: [] };
}

function buildToolCallEvent({ name, args, traceId, callId, iteration }) {
  return {
    event: 'tool_call',
    name,
    args: redactSensitiveValue(args || {}),
    traceId,
    callId,
    ...(Number.isFinite(iteration) ? { iteration } : {}),
  };
}

function buildToolResultEvent(envelope, args = {}, options = {}) {
  const result = envelope.data;
  const published = publicData(result);
  const summary = result && typeof result === 'object'
    ? Array.isArray(result)
      ? `返回 ${result.length} 条`
      : result.error
        ? `错误: ${result.error}`
        : 'ok'
    : String(result);
  const evt = {
    event: 'tool_result',
    name: envelope.tool,
    summary,
    ...(Number.isFinite(options.iteration) ? { iteration: options.iteration } : {}),
    toolResult: {
      contractVersion: envelope.contractVersion,
      traceId: envelope.traceId,
      callId: envelope.callId,
      tool: envelope.tool,
      status: envelope.status,
      terminationReason: envelope.terminationReason,
      durationMs: envelope.durationMs,
      // `status` is the execution outcome. These flags describe bounded
      // representations of a result and must not be treated as a tool failure
      // by clients.
      sourceTruncated: Boolean(envelope.truncated),
      previewTruncated: Boolean(published.truncated),
      truncated: Boolean(envelope.truncated || published.truncated),
      sideEffects: envelope.sideEffects,
      data: published.data,
      // UI-273 — 写操作逐行改动（独立于 data，规避 publicData 截断）
      ...(boundedChangeDiff(result) ? { changeDiff: boundedChangeDiff(result) } : {}),
      // UI-315 优化 — exec 实际使用的 shell 短标签（独立于 data，规避
      // publicData 把 data 换成 preview 后丢失；前端头行展示）
      ...(result && typeof result.shell === 'string'
        ? { shellLabel: shellLabelFromPath(result.shell) }
        : {}),
    },
  };

  if (envelope.tool === 'act' && result && typeof result === 'object') {
    if (result.undoToken) evt.undoToken = result.undoToken;
    if (result.undoableUntil) evt.undoableUntil = result.undoableUntil;
    if (result.message) evt.message = result.message;
    if (result.error) evt.actError = result.error;
    if (args.type) evt.actType = args.type;
    if (result.analysisId) evt.analysisId = result.analysisId;
    if (result.taskId) evt.taskId = result.taskId;
    if (result.ackToken) evt.ackToken = result.ackToken;
    if (result.type === 'update_figcode_editor' && result.code) {
      evt.figcodeCode = result.code;
      evt.figcodeAutoRun = result.autoRun !== false;
    }
    if (result.type === 'switch_result_tab') evt.scTab = result.tab;
    if (result.type === 'focus_cluster') evt.scCluster = result.cluster;
    if (result.type === 'highlight_gene') evt.scGene = result.gene;
    if (['select_cells', 'filter_table', 'label_cells'].includes(result.type) && result.columnFilters) {
      evt.scColumnFilters = result.columnFilters;
    }
    if (result.type === 'select_cells') evt.scSubsetName = result.subsetName || null;
    if (result.type === 'label_cells') {
      evt.scLabelKey = result.labelKey;
      evt.scLabelValue = result.labelValue;
    }
    if (result.type === 'merge_datasets') {
      evt.scDatasetIds = result.datasetIds;
      evt.scMergeName = result.mergeName || null;
    }
    if (result.type === 'open_replot') evt.scOpenReplotForAnalysis = result.analysisId;
    if (result.type === 'upload_data_hint') evt.scUploadHint = true;
    if (result.type === 'open_figcode_plot') evt.figcardId = result.figcardId;
    if (result.type === 'open_tool' && result.toolId) evt.toolId = result.toolId;
  }

  if (envelope.tool === 'run_tool' && result && typeof result === 'object') {
    if (result.needApproval) {
      evt.needApproval = true;
      if (result.ackToken) evt.ackToken = result.ackToken;
      if (result.toolJobId) evt.toolJobId = result.toolJobId;
      if (result.toolId) evt.toolId = result.toolId;
      if (result.message) evt.message = result.message;
      if (result.params) evt.params = redactSensitiveValue(result.params);
    } else if (result.toolJobId) {
      evt.toolJobId = result.toolJobId;
      if (result.toolId) evt.toolId = result.toolId;
      if (result.message || result.error) evt.message = String(result.message || result.error);
    }
  }

  return redactSensitiveValue(evt);
}

function compactActivityDetail(value) {
  if (typeof value !== 'string') return undefined;
  const normalized = value.replace(/\s+/g, ' ').trim();
  if (!normalized) return undefined;
  return normalized.length > 140 ? `${normalized.slice(0, 137)}…` : normalized;
}

// ===== BLOCK-33 P3 — workspace_exec 流式输出（tool_output SSE 事件） =====

const TOOL_OUTPUT_INTERVAL_MS = 200;
// 单次工具调用流式输出的总字符封顶；超出后发一次 truncated 标记并丢弃后续增量。
const TOOL_OUTPUT_MAX_CHARS = 16000;

/**
 * 构造 tool_output SSE 事件（callId 关联到对应 tool_call / tool_result）。
 * text 已经过脱敏；事件本身再整体脱敏一次，与 tool_call/tool_result 对齐。
 */
function buildToolOutputEvent({ name, callId, traceId, iteration, text, truncated }) {
  return redactSensitiveValue({
    event: 'tool_output',
    name,
    callId,
    traceId,
    ...(Number.isFinite(iteration) ? { iteration } : {}),
    text: String(text || ''),
    ...(truncated ? { truncated: true } : {}),
  });
}

/**
 * 创建工具输出流式发射器：聚合增量、按 TOOL_OUTPUT_INTERVAL_MS 节流、
 * 总量封顶 TOOL_OUTPUT_MAX_CHARS。返回 onOutput(chunk) 回调（chunk 形如
 * { stream: 'stdout' | 'stderr', text }) 与 flush()（命令结束后冲刷剩余缓冲）。
 * 非 workspace_exec 工具或未提供 emit 时返回 no-op。
 */function createToolOutputStream({ name, callId, traceId, iteration, emit, intervalMs = TOOL_OUTPUT_INTERVAL_MS, maxChars = TOOL_OUTPUT_MAX_CHARS }) {
  if (!emit || name !== 'workspace_exec' || !callId) {
    return { onOutput: () => {}, flush: () => {} };
  }
  const limit = Math.max(256, Number(maxChars) || TOOL_OUTPUT_MAX_CHARS);
  const interval = Math.max(50, Number(intervalMs) || TOOL_OUTPUT_INTERVAL_MS);
  let buffer = '';
  let emittedChars = 0;
  let truncatedSent = false;
  let timer = null;

  const send = (text, truncated) => {
    if (!text) return;
    try {
      emit(buildToolOutputEvent({ name, callId, traceId, iteration, text, truncated }));
    } catch {
      // SSE 发送失败不阻塞工具执行
    }
  };

  const flush = () => {
    if (timer) {
      clearTimeout(timer);
      timer = null;
    }
    if (truncatedSent) return;
    if (buffer) {
      send(buffer, false);
      buffer = '';
    }
  };

  const onOutput = (chunk) => {
    if (truncatedSent || !chunk || typeof chunk.text !== 'string' || !chunk.text) return;
    if (emittedChars >= limit) return;
    buffer += chunk.text;
    emittedChars += chunk.text.length;
    if (emittedChars >= limit) {
      // 封顶：本次冲刷后发 truncated 标记，后续增量丢弃
      const room = Math.max(0, limit - (emittedChars - buffer.length));
      send(buffer.slice(0, room), false);
      buffer = '';
      truncatedSent = true;
      send('…（输出超出流式上限，已截断）', true);
      return;
    }
    if (timer) return;
    timer = setTimeout(() => {
      timer = null;
      if (truncatedSent || !buffer) return;
      send(buffer, false);
      buffer = '';
    }, interval);
  };

  return { onOutput, flush };
}

// ===== UI-384 — 只读工具结果内容镜像 =====
// workspace_read/list/find/search 是一次性返回（无流式增量），此前行详情输出块
// 恒空——模型收到了内容但前端没有任何渲染。这里把结果格式化为有界纯文本尾部，
// 由 loop-orchestrator 走与 exec 相同的 tool_output 事件 + 活动快照镜像
// （recordOutput），前端零改动点亮行详情输出块，历史会话可回放。

const RESULT_OUTPUT_TOOLS = new Set(['workspace_read', 'workspace_list', 'workspace_find', 'workspace_search']);
const RESULT_OUTPUT_MAX_CHARS = 1500;

function formatResultBytes(sizeBytes) {
  const n = Number(sizeBytes);
  if (!Number.isFinite(n) || n < 0) return '';
  if (n < 1024) return `${n} B`;
  if (n < 1024 * 1024) return `${(n / 1024).toFixed(1)} KB`;
  return `${(n / 1024 / 1024).toFixed(1)} MB`;
}

function truncateResultText(text) {
  if (text.length <= RESULT_OUTPUT_MAX_CHARS) return { text, truncated: false };
  return { text: `${text.slice(0, RESULT_OUTPUT_MAX_CHARS)}\n…（内容已截断）`, truncated: true };
}

/**
 * 把只读工具的一次性结果格式化为用户可读的输出尾部文本。
 * 返回 { text, truncated }；非目标工具 / 错误结果返回 undefined。
 */
function buildResultOutputText(name, result) {
  if (!RESULT_OUTPUT_TOOLS.has(name)) return undefined;
  if (!result || typeof result !== 'object' || result.ok !== true) return undefined;
  let body = '';
  if (name === 'workspace_read') {
    const total = Number.isFinite(result.totalLines) ? result.totalLines : '?';
    const head = `[读取 ${result.path || ''} · 第 ${result.startLine ?? '?'}-${result.endLine ?? '?'} 行 / 共 ${total} 行]`;
    const content = String(result.content ?? '');
    body = content.length > 0 ? `${head}\n${content}` : `${head}\n（空文件或空区间）`;
  } else if (name === 'workspace_list') {
    const entries = Array.isArray(result.entries) ? result.entries : [];
    const lines = entries.map((e) => {
      if (!e || typeof e !== 'object') return '';
      const size = e.type === 'file' && Number.isFinite(e.sizeBytes) ? `（${formatResultBytes(e.sizeBytes)}）` : '';
      return `- ${e.name || e.path || '?'}${e.type === 'directory' ? '/' : ''}${size}`;
    }).filter(Boolean);
    body = `[目录 ${result.path || '.'}${result.truncated ? ' · 已截断' : ''}]\n${lines.length > 0 ? lines.join('\n') : '（空目录）'}`;
  } else if (name === 'workspace_find') {
    const matches = Array.isArray(result.matches) ? result.matches : [];
    const lines = matches.map((m) => {
      if (!m || typeof m !== 'object') return '';
      const size = Number.isFinite(m.sizeBytes) ? `（${formatResultBytes(m.sizeBytes)}）` : '';
      return `- ${m.path || '?'}${size}`;
    }).filter(Boolean);
    const scanned = Number.isFinite(result.filesScanned) ? ` · 扫描 ${result.filesScanned} 个文件` : '';
    body = `[查找 ${result.pattern || '*'} · 命中 ${matches.length}${result.truncated ? '（已截断）' : ''}${scanned}]\n${lines.length > 0 ? lines.join('\n') : '（无匹配）'}`;
  } else if (name === 'workspace_search') {
    const matches = Array.isArray(result.matches) ? result.matches : [];
    const lines = matches.map((m) => {
      if (!m || typeof m !== 'object') return '';
      return `${m.path || '?'}:${m.line ?? '?'}: ${String(m.text || '').slice(0, 200)}`;
    }).filter(Boolean);
    const scanned = Number.isFinite(result.filesScanned) ? ` · 扫描 ${result.filesScanned} 个文件` : '';
    body = `[搜索 "${result.query || ''}" · 命中 ${matches.length}${result.truncated ? '（已截断）' : ''}${scanned}]\n${lines.length > 0 ? lines.join('\n') : '（无匹配）'}`;
  }
  if (!body) return undefined;
  return truncateResultText(body);
}

/**
 * UI-384 — 只读结果内容镜像发射器：buildResultOutputText 的结果走 tool_output
 * 事件 + recordOutput 快照镜像（与 exec 流式输出同一管道；前端行详情输出块
 * 点亮，随 meta 落库历史可回放）。内部 fail-safe：任何异常不阻塞工具结果下发。
 * 返回 true 表示已发射。
 */
function emitReadOnlyResultOutput({ name, result, callId, traceId, iteration, emit, recordOutput }) {
  try {
    const output = buildResultOutputText(name, result);
    if (!output || !output.text) return false;
    const evt = buildToolOutputEvent({
      name,
      callId,
      traceId,
      ...(Number.isFinite(iteration) ? { iteration } : {}),
      text: output.text,
      truncated: output.truncated === true,
    });
    emit(evt);
    if (typeof recordOutput === 'function') {
      recordOutput({ name, callId, traceId, text: evt.text, truncated: evt.truncated === true });
    }
    return true;
  } catch {
    return false;
  }
}

/** Safe, compact activity details suitable for conversation metadata. */
function summarizeToolCallForActivity(name, args = {}) {
  switch (name) {
    case 'workspace_exec':
      return { actionLabel: '已运行', actionDetail: compactActivityDetail(args.command) || '命令' };
    // BLOCK-33 P4 — 后台进程三件套
    case 'workspace_exec_background':
      return { actionLabel: '后台运行', actionDetail: compactActivityDetail(args.command) || '命令' };
    case 'process_status':
      return { actionLabel: '查询后台进程', actionDetail: compactActivityDetail(args.processId) || '全部' };
    case 'process_stop':
      return { actionLabel: '停止后台进程', actionDetail: compactActivityDetail(args.processId) || '进程' };
    case 'workspace_read': {
      const path = compactActivityDetail(args.path) || '文件';
      const start = Number.isInteger(args.startLine) ? ` · 第 ${args.startLine} 行起` : '';
      return { actionLabel: '已读取', actionDetail: `${path}${start}` };
    }
    case 'workspace_list':
      return { actionLabel: '已读取', actionDetail: `目录 ${compactActivityDetail(args.path) || '.'}` };
    case 'workspace_find':
      return { actionLabel: '已查找', actionDetail: compactActivityDetail(args.pattern) || '文件' };
    case 'workspace_search':
      return { actionLabel: '已搜索', actionDetail: compactActivityDetail(args.query) || '文本' };
    case 'workspace_write':
    case 'workspace_replace':
      return { actionLabel: '已修改', actionDetail: compactActivityDetail(args.path) || '文件' };
    case 'run_tool':
      return { actionLabel: '已运行', actionDetail: compactActivityDetail(args.toolId) || '分析工具' };
    default:
      return { actionLabel: '已调用', actionDetail: name };
  }
}

function shellLabelFromPath(executable) {
  const base = String(executable || '').split(/[\\/|]/).pop() || '';
  const lower = base.toLowerCase().replace(/\.exe$/, '');
  if (lower === 'cmd') return 'cmd';
  if (lower.startsWith('powershell') || lower === 'pwsh') return 'powershell';
  if (lower === 'wsl') return 'wsl';
  return lower.slice(0, 16);
}

function createToolActivityRecorder() {
  const items = [];

  // UI-315 — exec 类工具的完整命令（bounded），随活动快照落库供历史会话
  // 的终端块回放；非 exec 工具不记录（体积/隐私边界）。
  const EXEC_TOOL_NAMES = new Set(['workspace_exec', 'workspace_exec_background']);
  const COMMAND_SNAPSHOT_CHARS = 400;
  const OUTPUT_SNAPSHOT_CHARS = 2000;

  function recordCall({ name, args, traceId, callId, iteration }) {
    const summary = summarizeToolCallForActivity(name, args);
    const command = EXEC_TOOL_NAMES.has(name)
      && args && typeof args.command === 'string' && args.command.trim()
      ? args.command.trim().slice(0, COMMAND_SNAPSHOT_CHARS)
      : undefined;
    items.push({
      key: callId || `${traceId || 'legacy'}:${name}:${items.length + 1}`,
      callId,
      traceId,
      ...(Number.isFinite(iteration) ? { iteration } : {}),
      name,
      status: 'running',
      ...(command ? { command } : {}),
      ...summary,
    });
  }

  /**
   * UI-315 — exec 输出尾部随活动快照落库（前端 tool_output 增量的服务端
   * 镜像，cap 2000 字符对齐前端 tail）。按 callId 关联；无匹配项时忽略
   * （迟到/乱序输出）。
   */
  function recordOutput({ name, callId, traceId, text, truncated }) {
    if (!text) return;
    let index = callId ? items.findIndex((item) => item.callId === callId) : -1;
    if (index < 0) {
      for (let i = items.length - 1; i >= 0; i -= 1) {
        if (items[i].name === name && items[i].status === 'running') {
          index = i;
          break;
        }
      }
    }
    if (index < 0) return;
    const existing = items[index];
    const previous = existing.output && existing.output.tail ? existing.output.tail : '';
    let tail = previous + text;
    if (tail.length > OUTPUT_SNAPSHOT_CHARS) {
      tail = `…${tail.slice(-(OUTPUT_SNAPSHOT_CHARS - 1))}`;
    }
    existing.output = {
      tail,
      truncated: Boolean(existing.output && existing.output.truncated) || truncated === true,
    };
  }

  function recordResult(event) {
    const result = event && event.toolResult ? event.toolResult : {};
    const name = result.tool || event.name || 'tool';
    let index = result.callId
      ? items.findIndex((item) => item.callId === result.callId)
      : -1;
    if (index < 0) {
      for (let i = items.length - 1; i >= 0; i -= 1) {
        if (items[i].name === name && items[i].status === 'running') {
          index = i;
          break;
        }
      }
    }
    const existing = index >= 0 ? items[index] : null;
    // UI-382 — spawn/wait/list agent 结果携带 agentId：随活动快照落库，
    // 历史重建（5s 对账/重载）后内联实况卡与「详情窗」入口才能恢复。
    const resultAgentData = result.data && typeof result.data === 'object' ? result.data : null;
    const resultAgentRunId =
      (name === 'spawn_agent' || name === 'wait_agent' || name === 'list_agents')
      && resultAgentData && typeof resultAgentData.agentId === 'string'
        ? resultAgentData.agentId
        : undefined;
    const next = {
      key: existing ? existing.key : (result.callId || `${result.traceId || 'legacy'}:${name}:${items.length + 1}`),
      toolJobId: event.toolJobId || (existing && existing.toolJobId),
      toolId: event.toolId || (existing && existing.toolId),
      callId: result.callId || (existing && existing.callId),
      traceId: result.traceId || (existing && existing.traceId),
      iteration: Number.isFinite(event.iteration)
        ? event.iteration
        : (existing && existing.iteration),
      name,
      status: result.terminationReason === 'approval_required'
        ? 'awaiting_confirmation'
        : result.status || (event.summary && /^错误[:：]/.test(event.summary) ? 'error' : 'success'),
      durationMs: result.durationMs,
      sourceTruncated: result.sourceTruncated,
      previewTruncated: result.previewTruncated,
      truncated: result.truncated,
      terminationReason: result.terminationReason,
      sideEffects: result.sideEffects,
      // UI-273 — 写操作逐行改动随活动快照落库（历史会话展开执行记录可回看）
      changeDiff: result.changeDiff && typeof result.changeDiff === 'object'
        ? {
            added: Number.isFinite(result.changeDiff.added) ? result.changeDiff.added : 0,
            removed: Number.isFinite(result.changeDiff.removed) ? result.changeDiff.removed : 0,
            truncated: result.changeDiff.truncated === true,
            hunks: Array.isArray(result.changeDiff.hunks) ? result.changeDiff.hunks.slice(0, 20) : [],
          }
        : undefined,
      // UI-315 优化 — exec 实际使用的 shell 标签（头行展示）
      shellLabel: result.shellLabel || (existing ? existing.shellLabel : undefined),
      // UI-382 — 子智能体任务 id（展开行内联实况卡 / 详情窗入口按它渲染）
      agentRunId: resultAgentRunId || (existing ? existing.agentRunId : undefined),
      summary: event.summary,
      actionLabel: existing ? existing.actionLabel : summarizeToolCallForActivity(name).actionLabel,
      actionDetail: existing ? existing.actionDetail : summarizeToolCallForActivity(name).actionDetail,
      // UI-315 — 终端块：recordCall 捕获的完整命令 + recordOutput 累积的输出尾部
      command: existing ? existing.command : undefined,
      output: existing ? existing.output : undefined,
    };
    if (index < 0) items.push(next);
    else items[index] = next;
  }

  return {
    recordCall,
    recordOutput,
    recordResult,
    snapshot: () => items.slice(0, 100),
  };
}

module.exports = {
  TOOL_OUTPUT_INTERVAL_MS,
  TOOL_OUTPUT_MAX_CHARS,
  RESULT_OUTPUT_TOOLS,
  buildToolCallEvent,
  buildToolOutputEvent,
  buildToolResultEvent,
  buildResultOutputText,
  emitReadOnlyResultOutput,
  createToolOutputStream,
  summarizeToolCallForActivity,
  createToolActivityRecorder,
};

'use strict';

const { randomUUID } = require('node:crypto');
const { redactSensitiveValue } = require('../../shared-backend/redaction');
const { interceptAgentToolCall } = require('./agent-tool-interceptor');
const { getToolContract } = require('./registry');
const { toolTraceStore } = require('./tool-trace-store');

const TOOL_RESULT_CONTRACT_VERSION = '1.0.0';
const MODEL_RESULT_LIMIT = 6000;
const MODEL_LIST_LIMIT = 40;
const MODEL_SEARCH_LIMIT = 12;
const MODEL_SEARCH_TEXT_LIMIT = 120;
const MODEL_OUTPUT_TAIL = 1600;

function safeJson(value) {
  try {
    return JSON.stringify(value);
  } catch (error) {
    return JSON.stringify({ error: 'result_not_serializable', message: error.message });
  }
}

function classifyResult(result) {
  if (result && typeof result === 'object' && (result.error || result.ok === false)) {
    if (result.messageKey && String(result.messageKey).startsWith('agent_tool.')) {
      return {
        status: 'denied',
        terminationReason: String(result.reason || result.error || 'policy_denied'),
      };
    }
    return { status: 'error', terminationReason: 'handler_error' };
  }
  if (result && typeof result === 'object' && result.needApproval === true) {
    return { status: 'success', terminationReason: 'approval_required' };
  }
  return { status: 'success', terminationReason: 'success' };
}

function noSideEffects() {
  return { type: 'none', riskTier: 'R0', resources: [] };
}

function sideEffectSummary(name, args, contract, result, classification) {
  if (classification.status !== 'success') return noSideEffects();
  if (result && typeof result === 'object' && result.needApproval === true) {
    return result.toolJobId
      ? { type: 'state-write', riskTier: 'R1', resources: ['tool_job'] }
      : noSideEffects();
  }

  const operation = args && typeof args === 'object' ? args.op : undefined;
  if (name === 'run_tool' && operation !== 'run') return noSideEffects();
  if (name === 'plan' && (operation === 'list' || operation === 'get')) return noSideEffects();
  if (
    (name === 'workspace_write' || name === 'workspace_replace') &&
    result &&
    typeof result === 'object' &&
    result.dryRun === true
  ) {
    return noSideEffects();
  }
  if (!contract || contract.sideEffect === 'none') return noSideEffects();
  return {
    type: contract.sideEffect,
    riskTier: contract.riskTier,
    resources: [...contract.resources],
  };
}

function createCallId() {
  return `call_${randomUUID()}`;
}

function createTraceId() {
  return `trace_${randomUUID()}`;
}

function normalizeProjectId(value) {
  return value == null || String(value).trim() === '' ? null : String(value);
}

function appendTrace(envelope, args, result, ctx) {
  toolTraceStore.append({
    ...envelope,
    projectId: normalizeProjectId(ctx && ctx.projectId),
    args,
    result,
  });
}

function buildEnvelope(name, args, data, ctx, options, durationMs) {
  const classification = classifyResult(data);
  return {
    contractVersion: TOOL_RESULT_CONTRACT_VERSION,
    traceId: options.traceId || createTraceId(),
    callId: options.callId || createCallId(),
    tool: name,
    status: classification.status,
    terminationReason: classification.terminationReason,
    durationMs: Math.round(durationMs * 10) / 10,
    truncated: safeJson(data).length > MODEL_RESULT_LIMIT,
    sideEffects: sideEffectSummary(name, args, getToolContract(name), data, classification),
    data,
  };
}

function replaceToolResultData(envelope, data) {
  return {
    ...envelope,
    // `truncated` describes the raw handler result captured when the envelope
    // was created. Localizing or attaching ACK metadata must not rewrite that
    // execution-time fact; model projection tracks its own bounded size.
    truncated: envelope.truncated,
    data,
  };
}

async function executeToolCall(name, args = {}, ctx = {}, options = {}) {
  const startedAt = process.hrtime.bigint();
  let data;
  try {
    // BLOCK-33 P3 — options.onOutput（可选）透传到 handler（workspace_exec 流式输出）
    data = await interceptAgentToolCall(
      name,
      args,
      ctx,
      typeof options.onOutput === 'function' ? { onOutput: options.onOutput } : {}
    );
  } catch (error) {
    data = {
      ok: false,
      error: 'tool_failed',
      message: error && error.message ? error.message : String(error),
    };
  }
  const durationMs = Number(process.hrtime.bigint() - startedAt) / 1e6;
  const envelope = buildEnvelope(name, args, data, ctx, options, durationMs);
  appendTrace(envelope, args, data, ctx);
  return envelope;
}

function createRejectedToolResult(name, error, message, ctx = {}, options = {}) {
  const data = {
    ok: false,
    error,
    reason: error,
    message,
    messageKey: `agent_tool.${error}`,
  };
  const envelope = buildEnvelope(name, {}, data, ctx, options, 0);
  appendTrace(envelope, {}, data, ctx);
  return envelope;
}

function createModelResultState(options = {}) {
  return {
    projectId: normalizeProjectId(options.projectId),
    traceId: options.traceId || null,
    readRanges: new Map(),
  };
}

function commonData(data) {
  if (!data || typeof data !== 'object' || Array.isArray(data)) return data;
  const compact = {};
  for (const key of [
    'ok', 'error', 'reason', 'message', 'messageKey', 'needApproval', 'ackToken',
    'toolJobId', 'toolId', 'unhandled', 'dryRun',
  ]) {
    if (data[key] !== undefined) compact[key] = data[key];
  }
  return compact;
}

function tail(value, maxChars = MODEL_OUTPUT_TAIL) {
  const text = String(value == null ? '' : value);
  const limit = Math.max(1, Number(maxChars) || MODEL_OUTPUT_TAIL);
  return text.length <= limit ? text : `…${text.slice(-(limit - 1))}`;
}

function addReadRange(state, key, startLine, endLine) {
  const ranges = state.readRanges.get(key) || [];
  ranges.push([startLine, endLine]);
  ranges.sort((a, b) => a[0] - b[0]);
  const merged = [];
  for (const range of ranges) {
    const last = merged[merged.length - 1];
    if (!last || range[0] > last[1] + 1) merged.push([...range]);
    else last[1] = Math.max(last[1], range[1]);
  }
  state.readRanges.set(key, merged);
}

function rangeSeen(ranges, line) {
  return ranges.some(([start, end]) => line >= start && line <= end);
}

function projectRead(data, envelope, state) {
  const startLine = Number(data.startLine) || 1;
  const lines = String(data.content || '').split(/\r?\n/);
  const endLine = startLine + Math.max(0, lines.length - 1);
  const scopeMatches = state &&
    state.traceId === envelope.traceId &&
    state.projectId !== undefined;
  const key = scopeMatches ? `${state.projectId || '<global>'}\0${String(data.path || '')}` : null;
  const seen = key ? state.readRanges.get(key) || [] : [];
  const segments = [];
  let current = null;
  let omittedPreviouslyReadLines = 0;

  for (let index = 0; index < lines.length; index += 1) {
    const lineNumber = startLine + index;
    if (rangeSeen(seen, lineNumber)) {
      omittedPreviouslyReadLines += 1;
      current = null;
      continue;
    }
    if (!current) {
      current = { startLine: lineNumber, endLine: lineNumber, content: lines[index] };
      segments.push(current);
    } else {
      current.endLine = lineNumber;
      current.content += `\n${lines[index]}`;
    }
  }
  if (key) addReadRange(state, key, startLine, endLine);
  return {
    ...commonData(data),
    path: data.path,
    segments,
    startLine,
    endLine: data.endLine,
    totalLines: data.totalLines,
    sizeBytes: data.sizeBytes,
    sha256: data.sha256,
    truncated: data.truncated === true,
    omittedPreviouslyReadLines,
  };
}

function projectToolData(tool, data, envelope, state) {
  if (!data || typeof data !== 'object' || Array.isArray(data)) return data;
  if (envelope.status !== 'success') return commonData(data);

  if (tool === 'workspace_list') {
    const entries = Array.isArray(data.entries) ? data.entries : [];
    return {
      ...commonData(data),
      path: data.path,
      entries: entries.slice(0, MODEL_LIST_LIMIT).map((entry) => ({
        name: entry.name,
        path: entry.path,
        type: entry.type,
        ...(entry.sizeBytes !== undefined ? { sizeBytes: entry.sizeBytes } : {}),
      })),
      returnedEntries: Math.min(entries.length, MODEL_LIST_LIMIT),
      totalReturnedByTool: entries.length,
      truncated: data.truncated === true || entries.length > MODEL_LIST_LIMIT,
    };
  }
  if (tool === 'workspace_find') {
    const matches = Array.isArray(data.matches) ? data.matches : [];
    return {
      ...commonData(data),
      pattern: data.pattern,
      matches: matches.slice(0, MODEL_LIST_LIMIT).map((match) => ({
        path: match.path,
        ...(match.sizeBytes !== undefined ? { sizeBytes: match.sizeBytes } : {}),
      })),
      returnedMatches: Math.min(matches.length, MODEL_LIST_LIMIT),
      totalReturnedByTool: matches.length,
      filesScanned: data.filesScanned,
      truncated: data.truncated === true || matches.length > MODEL_LIST_LIMIT,
    };
  }
  if (tool === 'workspace_search') {
    const matches = Array.isArray(data.matches) ? data.matches : [];
    return {
      ...commonData(data),
      query: data.query,
      matches: matches.slice(0, MODEL_SEARCH_LIMIT).map((match) => ({
        path: match.path,
        line: match.line,
        text: tail(match.text, MODEL_SEARCH_TEXT_LIMIT),
      })),
      returnedMatches: Math.min(matches.length, MODEL_SEARCH_LIMIT),
      totalReturnedByTool: matches.length,
      filesScanned: data.filesScanned,
      skippedBinaryOrLarge: data.skippedBinaryOrLarge,
      truncated: data.truncated === true || matches.length > MODEL_SEARCH_LIMIT,
    };
  }
  if (tool === 'workspace_read') return projectRead(data, envelope, state);
  if (tool === 'workspace_write' || tool === 'workspace_replace') {
    return {
      ...commonData(data),
      path: data.path,
      created: data.created,
      replacements: data.replacements,
      previousSha256: data.previousSha256,
      sha256: data.sha256,
      sizeBytes: data.sizeBytes,
      changeSummary: data.changeSummary,
    };
  }
  if (tool === 'workspace_exec') {
    return {
      ...commonData(data),
      command: data.command,
      cwd: data.cwd == null ? undefined : '[project workspace]',
      exitCode: data.exitCode,
      signal: data.signal,
      timedOut: data.timedOut === true,
      stdoutTail: data.command === 'pwd' ? '[project workspace]\n' : tail(data.stdout),
      stderrTail: tail(data.stderr),
      truncated: data.truncated === true || String(data.stdout || '').length > MODEL_OUTPUT_TAIL || String(data.stderr || '').length > MODEL_OUTPUT_TAIL,
    };
  }
  // BLOCK-49 — 多 Agent 派生工具面：commonData 白名单会剥掉 agentId/status/kind，
  // 模型拿不到 agentId 就无法 wait_agent（实机回归已证实会触发重复派生异常循环）。
  // 成功与 fail（extra 携带 agentId/reason）两条路径都要保住关键字段。
  if (tool === 'spawn_agent') {
    return {
      ...commonData(data),
      agentId: data.agentId,
      status: data.status,
      kind: data.kind,
      ...(data.model !== undefined ? { model: data.model } : {}),
      ...(data.reason !== undefined ? { reason: data.reason } : {}),
    };
  }
  if (tool === 'list_agents') {
    const agents = Array.isArray(data.agents) ? data.agents : [];
    return {
      ...commonData(data),
      agents: agents.map((agent) => ({
        agentId: agent.agentId,
        status: agent.status,
        agentStatus: agent.agentStatus,
        task: tail(agent.task, 120),
        createdAt: agent.createdAt,
        ...(agent.finishedAt !== undefined ? { finishedAt: agent.finishedAt } : {}),
        ...(agent.error !== undefined ? { error: tail(agent.error, 200) } : {}),
      })),
      returnedAgents: agents.length,
      totalReturnedByTool: agents.length,
    };
  }
  if (tool === 'wait_agent') {
    return {
      ...commonData(data),
      agentId: data.agentId,
      status: data.status,
      agentStatus: data.agentStatus,
      summary: data.summary,
    };
  }
  return data;
}

function fitValidJson(value, maxChars) {
  const redacted = redactSensitiveValue(value);
  let serialized = safeJson(redacted);
  if (serialized.length <= maxChars) return serialized;

  const minimal = {
    contractVersion: redacted.contractVersion,
    traceId: redacted.traceId,
    callId: redacted.callId,
    tool: redacted.tool,
    status: redacted.status,
    terminationReason: redacted.terminationReason,
    truncated: true,
    sideEffects: redacted.sideEffects,
  };
  const dataText = safeJson(redacted.data);
  let room = Math.max(0, maxChars - safeJson({ ...minimal, dataSummary: '' }).length - 8);
  while (room >= 0) {
    serialized = safeJson({ ...minimal, dataSummary: dataText.slice(0, room) });
    if (serialized.length <= maxChars) return serialized;
    room -= Math.max(1, Math.ceil((serialized.length - maxChars) / 2));
  }
  const tiny = safeJson({ tool: redacted.tool, status: redacted.status, truncated: true });
  return tiny.length <= maxChars ? tiny : safeJson({ truncated: true });
}

function cloneModelResultState(state) {
  if (!state) return null;
  return {
    projectId: state.projectId,
    traceId: state.traceId,
    readRanges: new Map(
      [...state.readRanges.entries()].map(([key, ranges]) => [
        key,
        ranges.map((range) => [...range]),
      ])
    ),
  };
}

function serializeToolResultForModel(envelope, maxChars = MODEL_RESULT_LIMIT, options = {}) {
  const state = options.state || null;
  const limit = Math.max(32, Number(maxChars) || MODEL_RESULT_LIMIT);
  // Read deduplication is committed only when the complete structured
  // projection fits. A hard-cap dataSummary must not claim that omitted lines
  // reached the model.
  const projectionState = envelope.tool === 'workspace_read'
    ? cloneModelResultState(state)
    : state;
  const projectedData = projectToolData(envelope.tool, envelope.data, envelope, projectionState);
  const sourceChars = safeJson(redactSensitiveValue(envelope)).length;
  const projected = {
    ...envelope,
    data: projectedData,
    modelContext: {
      projection: envelope.tool,
      sourceChars,
      projectedChars: 0,
      readDeduplicated: envelope.tool === 'workspace_read' && Boolean(state),
      compacted: false,
    },
  };
  // projectedChars includes the measurement metadata itself. Iterate after
  // compacted is known so callers can compare it with the actual JSON length.
  projected.modelContext.compacted = safeJson(redactSensitiveValue(projected)).length < sourceChars;
  for (let attempt = 0; attempt < 4; attempt += 1) {
    const projectedChars = safeJson(redactSensitiveValue(projected)).length;
    if (projected.modelContext.projectedChars === projectedChars) break;
    projected.modelContext.projectedChars = projectedChars;
  }
  const serialized = safeJson(redactSensitiveValue(projected));
  if (serialized.length <= limit) {
    if (projectionState && state && envelope.tool === 'workspace_read') {
      state.readRanges = projectionState.readRanges;
    }
    return serialized;
  }
  return fitValidJson(projected, limit);
}

module.exports = {
  MODEL_RESULT_LIMIT,
  TOOL_RESULT_CONTRACT_VERSION,
  createCallId,
  createTraceId,
  createModelResultState,
  createRejectedToolResult,
  executeToolCall,
  replaceToolResultData,
  serializeToolResultForModel,
};

const dbMod = require('../db');
const sqlite = dbMod.getDatabase();

async function tool_verify_state(args, ctx) {
  const userId = ctx.userId;
  if (!userId) return {error: 'unauthorized'};
  const db = sqlite;
  const expect = args.expect || {};
  let actual = null;

  try {
    if (args.kind === 'analysis') {
      if (!args.id) return {error: 'missing_id'};
      actual = db.prepare(`SELECT a.id, a.name, a.type, a.status, a.error FROM analyses a JOIN datasets d ON a.dataset_id=d.id JOIN projects p ON d.project_id=p.id WHERE a.id=? AND p.user_id=?`).get(args.id, userId);
    } else if (args.kind === 'project') {
      if (!args.id) return {error: 'missing_id'};
      actual = db.prepare('SELECT id, name, description FROM projects WHERE id=? AND user_id=?').get(args.id, userId);
    } else if (args.kind === 'dataset') {
      if (!args.id) return {error: 'missing_id'};
      actual = db.prepare(`SELECT d.id, d.name, d.n_cells, d.n_genes FROM datasets d JOIN projects p ON d.project_id=p.id WHERE d.id=? AND p.user_id=?`).get(args.id, userId);
    } else if (args.kind === 'plan') {
      if (!args.id) return {error: 'missing_id'};
      actual = db.prepare('SELECT id, title, status FROM copilot_plans WHERE id=? AND user_id=?').get(args.id, userId);
    } else if (args.kind === 'plan_step') {
      if (!args.planId || typeof args.stepN !== 'number') return {error: 'missing_args'};
      const plan = db.prepare('SELECT id FROM copilot_plans WHERE id=? AND user_id=?').get(args.planId, userId);
      if (!plan) return {error: 'plan_not_found'};
      actual = db.prepare('SELECT plan_id, n, title, status, result FROM copilot_plan_steps WHERE plan_id=? AND n=?').get(args.planId, args.stepN);
    } else if (args.kind === 'context') {
      // Context lives in the request — we just echo what the chat handler passed
      actual = ctx.context || {};
    } else {
      return {error: 'unknown_kind'};
    }
    if (!actual) return {error: 'not_found', kind: args.kind};

    // Compare each expected key
    const mismatches = [];
    for (const k of Object.keys(expect)) {
      const want = expect[k];
      const got = actual[k];
      if (got === undefined) {
        mismatches.push({field: k, expected: want, actual: '(undefined)'});
      } else if (typeof want === 'string' && typeof got === 'string') {
        if (got !== want) mismatches.push({field: k, expected: want, actual: got});
      } else if (got !== want) {
        mismatches.push({field: k, expected: want, actual: got});
      }
    }
    return {
      ok: mismatches.length === 0,
      kind: args.kind,
      actual,
      expect,
      mismatches,
      message: mismatches.length === 0
        ? '状态符合预期'
        : '状态不符：' + mismatches.map(m => `${m.field} 应为 ${m.expected}，实际 ${m.actual}`).join('；'),
    };
  } catch (e) {
    return {error: 'verify_failed', message: e.message};
  }
}

