'use strict';

/**
 * BLOCK-85 P4 — 投影终端引擎（node-pty 会话管理器，core 侧）。
 *
 * 手机/协作成员的桌面投影里点终端 → gateway 会话门内走本模块：真 pty
 * （powershell/bash），输出 SSE 流，输入 POST。会话驻留本模块（手机锁屏
 * 断流回来可续看，环形缓冲重放），闲置 TTL 清理。上限 4 会话/实例（与
 * 桌面 terminal.js 同值）。
 */

const path = require('node:path');
const os = require('node:os');

const MAX_SESSIONS = 4;
const RING_BUFFER_BYTES = 256 * 1024;
const IDLE_TTL_MS = 30 * 60_000;

const sessions = new Map(); // id -> { pty, ring, ringLen, subscribers:Set<fn>, exited, exitCode, lastWriteAt, platform }

function shellFor(platform) {
  if (platform === 'win32') {
    return { file: `${process.env.SystemRoot || 'C:\\Windows'}\\System32\\WindowsPowerShell\\v1.0\\powershell.exe`, args: ['-NoLogo'] };
  }
  return { file: process.env.SHELL || '/bin/bash', args: ['-l'] };
}

function createTerminalEngine() {
  let ptyModule = null;
  try {
    ptyModule = require('node-pty');
  } catch (error) {
    return { available: false, reason: `node-pty unavailable: ${error.message}` };
  }

  function ringWrite(session, text) {
    const bytes = Buffer.from(text, 'utf8');
    if (bytes.length >= RING_BUFFER_BYTES) {
      session.ring = bytes.slice(bytes.length - RING_BUFFER_BYTES);
      session.ringLen = session.ring.length;
      return;
    }
    const next = Buffer.concat([session.ring, bytes]);
    session.ring = next.length > RING_BUFFER_BYTES ? next.slice(next.length - RING_BUFFER_BYTES) : next;
    session.ringLen = session.ring.length;
  }

  function broadcast(session, event, payload) {
    for (const send of session.subscribers) {
      try { send(event, payload); } catch { /* 单订阅者失败不影响其他 */ }
    }
  }

  function sweep() {
    const now = Date.now();
    for (const [id, session] of sessions) {
      if (!session.exited && now - session.lastWriteAt > IDLE_TTL_MS) {
        try { session.pty.kill(); } catch { /* already dead */ }
        session.exited = true;
      }
      if (session.exited && session.subscribers.size === 0 && now - session.lastWriteAt > IDLE_TTL_MS) {
        sessions.delete(id);
      }
    }
  }
  const sweeper = setInterval(sweep, 60_000);
  if (typeof sweeper.unref === 'function') sweeper.unref();

  return {
    available: true,

    /** 列出活跃会话（安全投影）。 */
    list() {
      return [...sessions.entries()].map(([id, s]) => ({
        sessionId: id,
        exited: s.exited,
        subscribers: s.subscribers.size,
        lastWriteAt: s.lastWriteAt,
      }));
    },

    /** 起新 pty 会话。ssh={alias,remotePath} 时挂 ssh -tt 远程会话（桌面壳 terminal.js 同款语义）。返回 { sessionId } 或 { error }。 */
    start({ cwd, ssh } = {}) {
      const live = [...sessions.values()].filter((s) => !s.exited).length;
      if (live >= MAX_SESSIONS) {
        return { error: 'too_many_sessions', message: `终端会话已达上限（${MAX_SESSIONS}），请先关闭空闲会话` };
      }
      const id = `pter_${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}`;
      const session = {
        pty: null,
        ring: Buffer.alloc(0),
        ringLen: 0,
        subscribers: new Set(),
        exited: false,
        exitCode: null,
        lastWriteAt: Date.now(),
      };
      let ptyProc;
      try {
        if (ssh && ssh.alias && ssh.remotePath) {
          // BLOCK-67/P3 桌面壳同款：Windows 下 ssh.exe 直挂 conpty 会崩
          // conpty_console_list_agent——经 cmd.exe /c 包装（console 归 cmd）。
          const alias = String(ssh.alias).replace(/[^A-Za-z0-9._-]/g, '');
          const remotePath = String(ssh.remotePath).replace(/[^A-Za-z0-9._/@ +-]/g, '');
          const sshArgv = ['-o', 'ConnectTimeout=10', '-tt', alias, `cd "${remotePath}" && exec $SHELL -l`];
          ptyProc = process.platform === 'win32'
            ? ptyModule.spawn('cmd.exe', ['/c', 'ssh', ...sshArgv], {
              name: 'xterm-256color', cols: 100, rows: 28,
              cwd: os.homedir(),
              env: { ...process.env, TERM: 'xterm-256color', COLORTERM: 'truecolor' },
            })
            : ptyModule.spawn('ssh', sshArgv, {
              name: 'xterm-256color', cols: 100, rows: 28,
              cwd: os.homedir(),
              env: { ...process.env, TERM: 'xterm-256color', COLORTERM: 'truecolor' },
            });
        } else {
          const shell = shellFor(process.platform);
          ptyProc = ptyModule.spawn(shell.file, shell.args, {
            name: 'xterm-256color',
            cols: 80,
            rows: 24,
            cwd: cwd && typeof cwd === 'string' && cwd.trim() ? cwd.trim() : os.homedir(),
            env: { ...process.env, TERM: 'xterm-256color' },
          });
        }
      } catch (error) {
        return { error: 'pty_spawn_failed', message: error.message };
      }
      session.pty = ptyProc;
      ptyProc.onData((data) => {
        session.lastWriteAt = Date.now();
        ringWrite(session, data);
        broadcast(session, 'terminal:data', { data });
      });
      ptyProc.onExit(({ exitCode }) => {
        session.exited = true;
        session.exitCode = exitCode;
        session.lastWriteAt = Date.now();
        broadcast(session, 'terminal:exit', { exitCode });
      });
      sessions.set(id, session);
      return { sessionId: id };
    },

    /** 取会话（含环形缓冲文本，供重连重放）。 */
    getSession(id) {
      return sessions.get(id) || null;
    },

    ringText(session) {
      return session.ring.toString('utf8');
    },

    write(session, data) {
      if (session.exited) return { ok: false, error: 'session_exited' };
      session.pty.write(String(data));
      session.lastWriteAt = Date.now();
      return { ok: true };
    },

    resize(session, cols, rows) {
      if (session.exited) return { ok: false };
      const c = Math.min(Math.max(Number(cols) || 80, 2), 500);
      const r = Math.min(Math.max(Number(rows) || 24, 2), 200);
      try { session.pty.resize(c, r); return { ok: true }; } catch { return { ok: false }; }
    },

    kill(session) {
      if (session.exited) return { ok: true };
      try { session.pty.kill(); } catch { /* already dead */ }
      session.exited = true;
      return { ok: true };
    },

    subscribe(session, send) {
      session.subscribers.add(send);
      return () => session.subscribers.delete(send);
    },
  };
}

module.exports = { createTerminalEngine, shellFor };

/**
 * helpers/act-tool.js — ACT_TOOL_v1_SERVER (agent_audit table + undo)
 *
 * Extracted from server.js. Pure module: depends only on ../db.
 *
 * Public API:
 *   undoAgentAct(userId, undoToken) → Promise<{ok, message, action}>
 */

const dbMod = require('../db');
const sqlite = dbMod.getDatabase();

// One-time table create (idempotent)
sqlite.exec(`
  CREATE TABLE IF NOT EXISTS agent_audit (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    undo_token TEXT UNIQUE,
    user_id TEXT NOT NULL,
    action TEXT NOT NULL,
    args TEXT,
    result TEXT,
    ts TEXT NOT NULL,
    undone INTEGER NOT NULL DEFAULT 0,
    undone_at TEXT
  );
  CREATE INDEX IF NOT EXISTS idx_agent_audit_user_ts ON agent_audit(user_id, ts DESC);

  CREATE TABLE IF NOT EXISTS copilot_settings (
    user_id TEXT PRIMARY KEY,
    agent_paused INTEGER NOT NULL DEFAULT 0,
    updated_at TEXT NOT NULL
  );
`);

/** Undo a recent act. Best-effort. */
async function undoAgentAct(userId, undoToken) {
  const row = sqlite
    .prepare('SELECT * FROM agent_audit WHERE undo_token=? AND user_id=?')
    .get(undoToken, userId);
  if (!row) return { ok: false, error: 'token_not_found' };
  if (row.undone) return { ok: false, error: 'already_undone' };
  const ageMs = Date.now() - new Date(row.ts).getTime();
  if (ageMs > 30_000) return { ok: false, error: 'undo_window_expired' };

  let _args = {};
  let result = {};
  try {
    _args = JSON.parse(row.args || '{}');
  } catch {}
  try {
    result = JSON.parse(row.result || '{}');
  } catch {}

  let undoOk = false;
  let undoMsg = '';
  try {
    if (row.action === 'rename_project' && result.projectId && result.oldName) {
      dbMod.updateProject(result.projectId, { name: result.oldName });
      undoOk = true;
      undoMsg = '已恢复原项目名';
    } else if (row.action === 'rename_dataset' && result.datasetId && result.oldName) {
      dbMod.updateDataset(result.datasetId, { name: result.oldName });
      undoOk = true;
      undoMsg = '已恢复原数据集名';
    } else if (row.action === 'rename_analysis' && result.analysisId && result.oldName) {
      dbMod.updateAnalysis(result.analysisId, { name: result.oldName });
      undoOk = true;
      undoMsg = '已恢复原分析名';
    } else if (row.action === 'update_analysis_params' && result.analysisId && result.oldParams) {
      dbMod.updateAnalysis(result.analysisId, { params: result.oldParams });
      undoOk = true;
      undoMsg = '已恢复原参数';
    } else if (
      (row.action === 'start_analysis' || row.action === 'recluster') &&
      result.analysisId
    ) {
      dbMod.deleteAnalysis(result.analysisId);
      undoOk = true;
      undoMsg = '分析已撤销（任务可能已开始执行，结果不会保留）';
    } else {
      undoMsg = 'this action is not undoable';
    }
  } catch (e) {
    undoMsg = e.message;
  }

  if (undoOk) {
    sqlite
      .prepare('UPDATE agent_audit SET undone=TRUE, undone_at=? WHERE id=?')
      .run(new Date().toISOString(), row.id);
  }
  return { ok: undoOk, message: undoMsg, action: row.action };
}

module.exports = {
  undoAgentAct,
};

'use strict';

/**
 * helpers/agent-fallback.js — BLOCK-56 P1 任务级模型降级启动器。
 *
 * 语义（plan §2.1）：agent 任务因**可降级**模型错误失败 + 用户配置了备用模型
 * → 自动切换备用 profile 续跑原任务（复用 BLOCK-38 resume 链路形态：
 * 原 task 保持 failed 不可变，同会话新建 task，params.resumeOfTaskId 溯源）。
 *
 * 单级不连环（三重闸）：
 *   1. 请求级降级已发生过（loop-orchestrator modelFallbackOccurred）→ 不再任务级
 *   2. 本任务自身已是降级/手动续跑任务（params.fallbackOfTaskId / resumeOfTaskId）→ 不再触发
 *   3. 降级续跑的新任务以 disableProviderFallback 启动（gateway 只试主 profile）
 *
 * 边界：仅 kind='primary' 的任务自动降级（subagent 失败由父 loop 协调，不自动续跑）；
 * 未配置 fallbackEnabled/bindings → 诚实失败（现行为，零回归）。
 */

const agentTaskStore = require('../agent-task-store');
const { buildProgressDigest } = require('../routes/ai-agent/resume');
const {
  classifyDegradableError,
  resolveTaskFallbackProfile,
  buildFallbackResumeMessages,
} = require('./model-fallback-policy');

/** 从 ModelProfile 推导凭据（对齐 resolveChatModelCredential 的 refId 优先级）。 */
function resolveProfileApiKey(profile) {
  try {
    const { getApiKey } = require('./ai-settings');
    const ref = String((profile && profile.credentialRef) || '');
    const refId = ref.includes(':') ? ref.slice(ref.indexOf(':') + 1) : ref;
    if (refId) {
      const secret = getApiKey(refId);
      if (secret) return secret;
    }
    if (profile && profile.provider) return getApiKey(profile.provider) || '';
  } catch {}
  return '';
}

/**
 * 判定并启动任务级降级续跑（同步判定 + 异步拉起 loop）。
 *
 * @param {object} input
 * @param {string} input.taskId 失败的原任务 id
 * @param {string|Error|null} input.error 终态错误（fatalAgentError）
 * @param {boolean} [input.modelFallbackOccurred] 本任务是否已发生过请求级降级
 * @param {string|null} [input.previousProfileId] 原任务主 profile id
 * @param {string} [input.kind] 原任务 kind
 * @param {object|null} [input._activeConv] 原会话对象
 * @param {function} [input.emit] 原任务 _emit（事件落原 task task_events + onEvent）
 * @param {object} [deps] 测试注入：runAgentLoop / gatewayConfig
 * @returns {{launched: boolean, reason: string|null, newTaskId: string|null, category: string|null, toProfileLabel: string|null}}
 */
function maybeLaunchTaskLevelFallback(input, deps = {}) {
  const outcome = { launched: false, reason: null, newTaskId: null, category: null, toProfileLabel: null };
  const {
    taskId,
    error,
    modelFallbackOccurred = false,
    previousProfileId = null,
    kind = 'primary',
    _activeConv = null,
    emit = () => {},
  } = input || {};

  // 闸 0：仅主任务自动降级
  if (kind !== 'primary') { outcome.reason = 'not_primary'; return outcome; }
  // 闸 1：本任务已发生过请求级降级 → 单级不连环
  if (modelFallbackOccurred) { outcome.reason = 'fallback_already_used'; return outcome; }

  // 闸 2：本任务自身已是降级/手动续跑任务 → 不连环
  let task = null;
  try { task = agentTaskStore.getAgentTask(taskId); } catch {}
  const params = (task && task.params && typeof task.params === 'object') ? task.params : {};
  if (params.fallbackOfTaskId || params.resumeOfTaskId) { outcome.reason = 'already_resumed'; return outcome; }

  // 分类：不可降级错误走既有失败链（零回归）
  const classified = classifyDegradableError(error);
  if (!classified.degradable) { outcome.reason = 'not_degradable'; return outcome; }

  // 配置：未启用/无有效备用 → 诚实失败（现行为）
  let profile = null;
  try {
    const { modelGateway } = require('./llm-client');
    const config = typeof deps.gatewayConfig === 'function' ? deps.gatewayConfig() : (deps.gatewayConfig || modelGateway.getConfig());
    profile = resolveTaskFallbackProfile(config, previousProfileId, 'agent');
  } catch {}
  if (!profile) { outcome.reason = 'no_fallback_profile'; return outcome; }

  const originalMessages = Array.isArray(params.messages) ? params.messages : [];
  if (originalMessages.length === 0) { outcome.reason = 'no_original_messages'; return outcome; }

  // 执行进度摘要（task_events）→ 合成恢复指令（与 BLOCK-38 resume 同构）
  let digest = '';
  try { digest = buildProgressDigest(agentTaskStore.getAgentTaskEventsSince(taskId, 0, 5000)); } catch {} // BLOCK-102 P4 cap（SSE 回读上限）
  const toProfileLabel = String(profile.label || profile.model || profile.provider || '备用模型');
  const reasonText = String(error && error.message ? error.message : error || '').slice(0, 200);
  const resumeMessages = buildFallbackResumeMessages(originalMessages, digest, { reason: reasonText, label: toProfileLabel });

  let newTaskId;
  try {
    newTaskId = agentTaskStore.createAgentTask({
      status: 'running',
      agentStatus: 'running',
      userId: task.user_id || params.userId,
      params: {
        messages: resumeMessages,
        context: params.context && typeof params.context === 'object' ? params.context : {},
        conversationId: params.conversationId || null,
        providerName: profile.provider,
        providerLabel: toProfileLabel,
        modelName: profile.model,
        kind: 'primary',
        parentTaskId: null,
        resumeOfTaskId: taskId,
        fallbackOfTaskId: taskId,
        fallbackFromProfileId: previousProfileId || null,
        fallbackReason: reasonText,
      },
    }).taskId;
  } catch (e) {
    outcome.reason = 'create_task_failed: ' + (e && e.message);
    return outcome;
  }
  outcome.newTaskId = newTaskId;
  outcome.category = classified.category;
  outcome.toProfileLabel = toProfileLabel;

  // 溯源事件落原 task（seq 由 agent-runner _emit 维护；事件同时进 task_events 与 onEvent）
  try {
    emit({
      event: 'model_fallback',
      scope: 'task_level',
      fromProfileId: previousProfileId || null,
      toProfileId: profile.id,
      toProfileLabel,
      reason: reasonText || null,
      category: classified.category,
      newTaskId,
      message: `模型调用失败，已自动降级到备用模型「${toProfileLabel}」继续执行原任务`,
    });
    emit({
      event: 'agent_status',
      phase: 'model_fallback_resumed',
      newTaskId,
      message: `已降级到「${toProfileLabel}」继续执行`,
    });
  } catch {}

  // 并发槽 + loop 拉起（对齐 resume.js：primary 槽语义）
  const { aiTaskConcurrencyAcquire, aiTaskConcurrencyRelease } = require('./runtime');
  const acquired = aiTaskConcurrencyAcquire(task.user_id || params.userId, newTaskId, { isPrimary: true });
  if (!acquired || acquired.ok === false) {
    try { agentTaskStore.markAgentTaskFailed(newTaskId, '降级续跑因并发限制未能启动'); } catch {}
    try {
      emit({ event: 'agent_status', phase: 'model_fallback_failed', message: '备用模型续跑因并发限制未能启动，请手动重试' });
    } catch {}
    outcome.launched = false;
    outcome.reason = 'concurrency_limit';
    return outcome;
  }

  let activeConv = _activeConv || null;
  try {
    if (!activeConv && params.conversationId) {
      const convSync = require('./conversations');
      activeConv = convSync.getOrCreateActiveConversation(task.user_id || params.userId, {
        conversationId: params.conversationId,
        page: params.context && params.context.page,
        projectId: params.context && params.context.projectId,
        titleHint: '降级续跑任务',
      });
    }
  } catch {}

  const runAgentLoop = typeof deps.runAgentLoop === 'function' ? deps.runAgentLoop : require('../agent-runner').runAgentLoop;
  setImmediate(() => {
    runAgentLoop({
      messages: resumeMessages,
      context: params.context && typeof params.context === 'object' ? params.context : {},
      userId: task.user_id || params.userId,
      conversationId: (activeConv && activeConv.id) || params.conversationId || null,
      _activeConv: activeConv,
      apiKey: resolveProfileApiKey(profile),
      providerName: profile.provider,
      providerLabel: toProfileLabel,
      modelName: profile.model,
      profileId: profile.id,
      baseUrl: profile.baseUrl,
      taskId: newTaskId,
      kind: 'primary',
      parentLoopRunId: null,
      // 闸 3：降级续跑任务关闭请求级 fallback（gateway 只试主 profile）
      disableProviderFallback: true,
      onEvent: () => {},
      shouldAbort: () => agentTaskStore.isAgentTaskCancellationRequested(newTaskId),
    }).catch((e) => {
      try { agentTaskStore.markAgentTaskFailed(newTaskId, e && e.message ? e.message : String(e)); } catch {}
      try { aiTaskConcurrencyRelease(task.user_id || params.userId, newTaskId); } catch {}
    });
  });

  outcome.launched = true;
  return outcome;
}

module.exports = { maybeLaunchTaskLevelFallback, resolveProfileApiKey };

'use strict';

/**
 * helpers/agent-resilience.js — BLOCK-98 Agent 长任务韧性（M1 microcompact 起步）。
 *
 * agent-runner 行数门（1250）零触碰：全部新逻辑下沉本文件，runner 只留接线。
 * 开关（D6）：PETRI_AGENT_RESILIENCE——2026-09-18 用户裁决翻默认开（feature-flags 单一真相，
 * 设置页可切换）；环境变量 =1/true 强制开、=0/false 强制关（kill-switch）。
 *
 * M1 microcompact（三层压缩第 0 层，本地零模型成本）：LLM 请求视图中旧工具结果
 * 按组折叠为占位符。触发=估算 token ≥ min(窗口×0.9, 窗口−2000)；只折叠连续
 * ≥5 条的工具结果组，保留最近 5 组；占位符带标记防重复折叠。
 * 红线：只作用于当次请求的投影副本（body.messages 换新数组），loop 运行时
 * messages 与 copilot_messages 原文永不触碰（BLOCK-95 §4 原则 1 延续）。
 */

const os = require('os');
const path = require('path');
const RESILIENCE_ENV = 'PETRI_AGENT_RESILIENCE';
const MICROCOMPACT_PLACEHOLDER = '[已折叠：旧工具结果已按上下文管理清理]';
// 组内工具结果条数下限：ZCode 原文「连续 ≥5 条」按其存储格式（工具结果连排）
// 转录；本仓运行时格式为 assistant(tool_calls)+tool 交替，语义等价适配为
// 「同一块内 ≥2 条工具结果才成组，零散单条不折」（P0 结论，回写 plan §4）。
const MIN_GROUP_TOOLS = 2;
const KEEP_RECENT_GROUPS = 5;

function isResilienceEnabled(env) {
  // BLOCK-98 灰度收编：解析权在 feature-flags（env 强制 > 设置页持久化 > 默认开）
  const { resolveFlag } = require('./feature-flags');
  return resolveFlag('agent_resilience', env);
}

function isFolded(content) {
  return typeof content === 'string' && content.startsWith(MICROCOMPACT_PLACEHOLDER);
}

function isAssistantToolCarrier(m) {
  // assistant(tool_calls) 且无正文——它只是工具结果的协议载体，与结果同组
  return Boolean(
    m && m.role === 'assistant' && Array.isArray(m.tool_calls) && m.tool_calls.length > 0 &&
    (m.content == null || m.content === '' || m.content === null)
  );
}

/**
 * 把消息流按「工具调用块」分组（assistant(tool_calls)+其后 tool 结果为一块；
 * 已折叠的 tool 不计入组）。块内工具结果 ≥MIN_GROUP_TOOLS 条才算可折叠组。
 * @returns {Array<{toolIndexes: number[]}>} 可折叠组的 tool 消息下标列表
 */
function toolGroups(messages) {
  const groups = [];
  let current = [];
  const flush = () => {
    if (current.length >= MIN_GROUP_TOOLS) groups.push({ toolIndexes: current.slice() });
    current = [];
  };
  for (let i = 0; i < messages.length; i++) {
    const m = messages[i];
    if (m && m.role === 'tool') {
      if (!isFolded(m.content)) current.push(i);
      continue;
    }
    if (isAssistantToolCarrier(m)) { flush(); continue; } // 新一批调用=新组
    flush();
  }
  flush();
  return groups;
}

/**
 * microcompact 纯函数：返回折叠后的新数组与统计（不改动输入数组）。
 * @param {Array<{role,content,name?,tool_call_id?}>} messages
 * @param {{contextWindow: number}} opts
 */
function microcompactMessages(messages, opts = {}) {
  const empty = { messages, folded: 0, clearedChars: 0, groups: 0, triggered: false };
  if (!Array.isArray(messages) || messages.length === 0) return empty;
  const window = Number(opts.contextWindow) || 0;
  const { countMessages } = require('./token-estimator');
  const estimate = countMessages(messages);
  const threshold = window > 0 ? Math.min(window * 0.9, window - 2000) : Infinity;
  // opts.force=true：reactive 裁剪路径强制折叠（不看触发阈值，keepRecentGroups 可为 0）
  if (!opts.force && estimate < threshold) return { ...empty, triggered: false };

  const groups = toolGroups(messages);
  if (groups.length === 0) return { ...empty, triggered: true };
  // 保留最近 KEEP_RECENT_GROUPS 组（组按出现顺序，取尾部）；reactive 可覆盖为全量折叠
  const keepCount = Number(opts.keepRecentGroups != null ? opts.keepRecentGroups : KEEP_RECENT_GROUPS);
  const foldTargets = groups.slice(0, Math.max(0, groups.length - keepCount));
  if (foldTargets.length === 0) return { ...empty, triggered: true, groups: groups.length };

  const foldSet = new Set();
  let clearedChars = 0;
  for (const g of foldTargets) {
    for (const i of g.toolIndexes) {
      foldSet.add(i);
      const content = messages[i].content;
      if (typeof content === 'string') clearedChars += content.length;
    }
  }
  const next = messages.map((m, i) => {
    if (!foldSet.has(i)) return m;
    const len = typeof m.content === 'string' ? m.content.length : 0;
    return {
      ...m,
      content: `${MICROCOMPACT_PLACEHOLDER}（工具 ${m.name || (m.tool_call_id || 'unknown')}，原 ${len} 字符）`,
    };
  });
  return {
    messages: next,
    folded: foldSet.size,
    clearedChars,
    groups: foldTargets.length,
    triggered: true,
  };
}

/**
 * 请求体接线（agent-runner callChatProvider 包裹点）：
 * 开关关/窗口未知/未达阈值时原样返回；折叠命中时返回带新 messages 的浅拷贝，
 * 并打 _microcompacted 标记防同请求重复折叠。
 */
function maybeMicrocompactBody(body, ctx = {}) {
  if (!body || !Array.isArray(body.messages) || body.messages.length === 0) return body;
  if (body._microcompacted) return body;
  if (!isResilienceEnabled(process.env)) return body;
  const window = Number(ctx.contextWindow) || 0;
  if (!window) return body;
  const result = microcompactMessages(body.messages, { contextWindow: window });
  if (!result.folded) return body;
  try {
    console.log(
      `[block98-microcompact] folded=${result.folded} groups=${result.groups} ` +
      `clearedChars=${result.clearedChars} window=${window}`
    );
  } catch {}
  return {
    ...body,
    messages: result.messages,
    _microcompacted: true,
    _microcompactStats: { folded: result.folded, groups: result.groups, clearedChars: result.clearedChars },
  };
}

// ── M2：auto-compact 升级（阈值公式化 + 9 章节摘要模板 + 转写路径）──────────

const MAX_OUTPUT_RESERVE_CAP = 21000;
const BUFFER_ABS = 13000;
const BUFFER_RATIO = 0.08;

/**
 * D3 阈值公式：有效窗口 = 窗口 − min(maxOutput, 21K)；压缩阈值 = 有效窗口 −
 * min(13K, 8%×有效窗口)（小窗口模型 buffer 缩放，ZCode 200K 常数不硬抄）。
 * @returns {{effectiveWindow:number, buffer:number, threshold:number}|null}
 */
function planThreshold(contextWindow, maxOutput) {
  const window = Number(contextWindow) || 0;
  if (window <= 0) return null;
  const effectiveWindow = Math.max(0, window - Math.min(Number(maxOutput) || 0, MAX_OUTPUT_RESERVE_CAP));
  const buffer = Math.min(BUFFER_ABS, Math.round(effectiveWindow * BUFFER_RATIO));
  return { effectiveWindow, buffer, threshold: Math.max(0, effectiveWindow - buffer) };
}

/** 转写文件路径（BLOCK-37 llm-transcripts 家族；id 白名单同源校验）。 */
function transcriptPathFor(conversationId, dataDir) {
  const id = String(conversationId || '');
  if (!/^[A-Za-z0-9_-]{1,128}$/.test(id)) return null;
  const dir = dataDir
    || process.env.PETRI_LOCAL_DATA_DIR
    || path.join(os.homedir(), 'Documents', 'Petri-Local');
  return path.join(dir, `${id}.jsonl`);
}

/** M2 摘要系统提示词：9 章节结构化 + 安全指令逐字保留 + 禁工具（D2）。 */
const SUMMARY_NINE_SECTION_PROMPT = [
  '你是会话上下文压缩助手。把较早的对话折叠成结构化中文摘要，供后续对话作为唯一背景继续任务。要求：',
  '1. 先输出 <analysis> 段做简短分析（不超过 150 字），再输出 <summary> 正文。',
  '2. <summary> 必须包含以下 9 个编号章节（无内容的章节写「无」）：',
  '①用户原始请求与意图；②关键技术概念与实体（文件/参数/数据集/模型名）；③文件与代码段（关键路径与片段原样保留）；④错误与修复（尤其用户纠正过的行为，逐字引用用户纠正）；⑤问题求解过程；⑥全部用户消息清单（逐条列出）；⑦待办任务（未完成项）；⑧压缩前一刻正在做什么；⑨下一步（必须与用户最近的请求直接对齐，防止任务漂移）。',
  '3. 安全相关指令（如有）必须逐字保留，不得改写或省略。',
  '4. 只输出文本，禁止调用任何工具。全文不超过 1200 字。',
].join('\n');

/** 续接纪律 + 转写指针（压缩后首条摘要消息的追加行，D2）。 */
function continuationLines(transcriptPath) {
  const lines = [];
  if (transcriptPath) lines.push(`全文模型 I/O 转写（用户与审计可回查）：${transcriptPath}`);
  lines.push('续接纪律：请从中断处直接继续当前任务——不要复述或确认本摘要，像对话从未中断一样继续。');
  return lines.join('\n');
}


// ── M3：防呆状态机 + reactive 原地重试 + M5 遥测（纯函数优先，runner 只接线）──

const CIRCUIT_FAILURE_LIMIT = 3;
const CIRCUIT_COOLDOWN_MS = 10 * 60 * 1000;
const REACTIVE_USE_LIMIT = 3;

/** 单次 agent 运行的韧性状态（runner 创建、随 run 生命周期）。 */
function createResilienceState() {
  return {
    compactionFailures: 0,
    circuitOpenUntil: 0,
    reactiveUses: 0,
    contextExceededCount: 0,
  };
}

/** 连续压缩失败 ≥3 → 熔断 10 分钟（防「压缩失败→重试」死循环）。 */
function recordCompactionFailure(state, now = Date.now()) {
  state.compactionFailures = (state.compactionFailures || 0) + 1;
  if (state.compactionFailures >= CIRCUIT_FAILURE_LIMIT) {
    state.circuitOpenUntil = now + CIRCUIT_COOLDOWN_MS;
    state.compactionFailures = 0;
  }
  return state;
}

function compactionAllowed(state, now = Date.now()) {
  return !state || (state.circuitOpenUntil || 0) <= now;
}

/** reactive（超限原地重试）单 run 最多 3 次（防「重试→再超限」循环）。 */
function recordReactiveUse(state) {
  state.reactiveUses = (state.reactiveUses || 0) + 1;
  return state;
}

function reactiveAllowed(state) {
  return !state || (state.reactiveUses || 0) < REACTIVE_USE_LIMIT;
}

/**
 * context-exceeded 错误分类：对 provider 抛错（message/Body/body 字符串）
 * 做多族模式匹配（OpenAI/Anthropic/常见网关措辞）。
 */
function classifyContextExceeded(err) {
  const text = String((err && (err.message || err.body)) || err || '');
  if (!text) return false;
  const patterns = [
    /context[_ ]length[_ ]exceeded/i,
    /maximum context length/i,
    /context window/i,
    /too many tokens/i,
    /prompt is too long/i,
    /input length and `max_tokens` exceed context limit/i,
    /request too large/i,
    /exceed[s]? (the )?(maximum|context)/i,
    /content length limit/i,
  ];
  return patterns.some((re) => re.test(text));
}

/**
 * reactive 原地裁剪：两段降载——(1) 全量折叠工具组（不看最近保留窗）；
 * (2) 仍超则从最老消息起整块丢弃（切点必须落在 user / assistant 载体上，
 * 绝不产生孤儿 tool 结果），直到 ≤ target 或只剩保底尾部。
 * @returns {{messages: Array, dropped: number, foldedAll: boolean}|null} null=无法再裁
 */
function reactiveTrim(messages, opts = {}) {
  if (!Array.isArray(messages) || messages.length < 3) return null;
  const window = Number(opts.contextWindow) || 0;
  const { countMessages, countTokens } = require('./token-estimator');
  const target = Math.max(1000, Math.floor((window || 64000) * 0.6));

  // 第 1 段：全量折叠——reactive 是兜底，不受 M1 成组约束，所有未折叠工具
  // 结果直接折叠为占位符（保留 tool_call_id/name 协议字段）。
  let foldedCount = 0;
  let current = messages.map((m) => {
    if (m && m.role === 'tool' && !isFolded(m.content)) {
      foldedCount += 1;
      const len = typeof m.content === 'string' ? m.content.length : 0;
      return { ...m, content: `${MICROCOMPACT_PLACEHOLDER}（工具 ${m.name || (m.tool_call_id || 'unknown')}，原 ${len} 字符）` };
    }
    return m;
  });
  if (foldedCount > 0 && countMessages(current) <= target) {
    return { messages: current, dropped: 0, foldedAll: true };
  }

  // 第 2 段：整块丢弃（保底至少保留 system + 最后 2 条）
  const tokens = messages.map((m) => countTokens(String(m.content || '')) + 4);
  const total = tokens.reduce((a, b) => a + b, 0);
  if (total <= target) return { messages: current, dropped: 0, foldedAll: foldedCount > 0 };
  let acc = 0;
  let cut = 1; // 跳过 system
  const minKeep = Math.min(messages.length - 1, 2);
  const limit = messages.length - minKeep;
  for (let i = 1; i <= limit; i++) {
    acc += tokens[i];
    cut = i + 1;
    if (total - acc <= target) break;
  }
  // 切点推进到合法边界（user 或 assistant 载体；不可落在 tool 结果中间）
  while (cut < messages.length && messages[cut] && messages[cut].role === 'tool') cut++;
  if (cut >= messages.length) return null;
  // system 头必须保留（切点从其后算起）；dropped 与长度差一致（system 不计入）
  return { messages: [messages[0], ...current.slice(cut)], dropped: cut - 1, foldedAll: foldedCount > 0 };
}

/** M5 遥测：reactive 重试事件落 ai_usage（additive 列）。 */
function recordRetryUsage({ userId, conversationId, model, attempt, contextExceeded, error }) {
  try {
    const { recordAiUsage } = require('./ai-usage');
    recordAiUsage({
      userId: userId || null,
      kind: 'llm_retry',
      model: model || null,
      conversationId: conversationId || null,
      errorCode: contextExceeded ? 'context_exceeded' : String(error || 'unknown').slice(0, 120),
      attempt: Number(attempt) || 0,
      retryable: 1,
      contextExceeded: contextExceeded ? 1 : 0,
    });
  } catch { /* 遥测失败不阻塞主链 */ }
}



// ── M4：输入插队队列（进程内；与 ZCode session_input 的 admitted→promoted 同型）──
// 任务运行中用户消息不拒绝而是入队，下一次模型请求边界 drain 注入。
// 队列生命周期=单次运行（任务终态由调用方清空；进程重启队列消失=诚实降级为留言）。
const pendingInputQueues = new Map();

function enqueueUserInput(taskId, text) {
  const id = String(taskId || '');
  const t = String(text || '').trim();
  if (!id || !t) return { ok: false, error: 'invalid_arguments' };
  let q = pendingInputQueues.get(id);
  if (!q) { q = []; pendingInputQueues.set(id, q); }
  if (q.length >= 20) return { ok: false, error: 'queue_full', message: '排队消息过多（>20），请稍候再发' };
  q.push(t.slice(0, 8000));
  return { ok: true, queued: true, depth: q.length };
}

function drainUserInput(taskId) {
  const id = String(taskId || '');
  const q = pendingInputQueues.get(id);
  if (!q || q.length === 0) return [];
  pendingInputQueues.delete(id);
  return q;
}

function pendingInputCount(taskId) {
  const q = pendingInputQueues.get(String(taskId || ''));
  return q ? q.length : 0;
}

module.exports = {
  RESILIENCE_ENV,
  MICROCOMPACT_PLACEHOLDER,
  MIN_GROUP_TOOLS,
  KEEP_RECENT_GROUPS,
  isResilienceEnabled,
  isFolded,
  toolGroups,
  microcompactMessages,
  maybeMicrocompactBody,
  planThreshold,
  transcriptPathFor,
  SUMMARY_NINE_SECTION_PROMPT,
  continuationLines,

  // ── M3+M5：防呆状态机 / context-exceeded 分类 / reactive 原地重试 ─────────

  createResilienceState,
  recordCompactionFailure,
  compactionAllowed,
  recordReactiveUse,
  reactiveAllowed,
  classifyContextExceeded,
  reactiveTrim,
  recordRetryUsage,

  // ── M4：输入插队队列（steering；运行中用户消息下一轮请求注入）────────────

  enqueueUserInput,
  drainUserInput,
  pendingInputCount,
};

/**
 * helpers/ai-settings.js — AI 配置本地存储（桌面版）
 *
 * 桌面版用户在设置页填入 API key，密钥由 credential-store 单独保存。
 * Web 版不使用此模块（走 process.env.DEEPSEEK_API_KEY / DASHSCOPE_API_KEY）。
 *
 * 文件位置：~/Documents/Petri-Local/ai-settings.json
 *
 * ai-settings.json 永不保存或返回明文 API key。
 */

const fs = require('fs');
const path = require('path');
const os = require('os');
const { normalizeModelConfig } = require('../../shared-backend/llm-providers/model-profile');
const { createCredentialStore, normalizeProvider } = require('./credential-store');

const SETTINGS_DIR = process.env.PETRI_LOCAL_DATA_DIR ||
  path.join(os.homedir(), 'Documents', 'Petri-Local');
const SETTINGS_FILE = path.join(SETTINGS_DIR, 'ai-settings.json');
const credentialStore = createCredentialStore({ settingsDir: SETTINGS_DIR });

let _cache = null;
let _cacheSignature = null;

function _settingsFileSignature() {
  try {
    const stat = fs.statSync(SETTINGS_FILE);
    return `${stat.mtimeMs}:${stat.size}`;
  } catch {
    return null;
  }
}

const DEFAULT_CHAT_MODEL_PRESETS = [
  {
    id: 'deepseek-chat',
    label: 'DeepSeek Chat',
    provider: 'deepseek',
    model: 'deepseek-chat',
  },
];

function _ensureDir() {
  try {
    fs.mkdirSync(SETTINGS_DIR, { recursive: true });
  } catch {}
}

/**
 * 读取 AI 设置。
 * @returns {object} - ModelProfiles, role bindings, credential status and non-secret preferences.
 */
function getAiSettings() {
  const signature = _settingsFileSignature();
  if (_cache && signature === _cacheSignature) return _cache;
  try {
    const stored = JSON.parse(fs.readFileSync(SETTINGS_FILE, 'utf8'));
    const migrated = _extractCredentialUpdates(stored);
    for (const [provider, secret] of Object.entries(migrated.credentials)) {
      credentialStore.set(provider, secret);
    }
    _cache = migrated.settings;
    if (Object.keys(migrated.credentials).length) {
      _ensureDir();
      fs.writeFileSync(SETTINGS_FILE, JSON.stringify(_cache, null, 2));
      fs.chmodSync(SETTINGS_FILE, 0o600);
    }
  } catch {
    // Another desktop process may be between truncate/write while saving.
    // Keep the last valid snapshot and retry on the next read instead of
    // briefly replacing the live Gateway configuration with defaults.
    if (_cache) return _cache;
    _cache = {};
  }
  _cache = normalizeAiSettings(_cache);
  _cacheSignature = _settingsFileSignature();
  return _cache;
}

function normalizeAiSettings(settings) {
  const next = settings && typeof settings === 'object' ? { ...settings } : {};
  const presets = Array.isArray(next.chat_model_presets)
    ? next.chat_model_presets
        .filter((p) => p && typeof p === 'object')
        .map((p) => ({
          id: String(p.id || `${p.provider || 'deepseek'}-${p.model || 'deepseek-chat'}`).trim(),
          label: String(p.label || p.model || p.id || 'DeepSeek Chat').trim(),
          provider: String(p.provider || 'deepseek').trim(),
          model: String(p.model || 'deepseek-chat').trim(),
          baseUrl: p.baseUrl ? String(p.baseUrl).trim() : undefined,
          contextWindow: typeof p.contextWindow === 'number' && p.contextWindow > 0 ? Math.round(p.contextWindow) : undefined,
        }))
        .filter((p) => p.id && p.label && p.provider && p.model)
    : [];
  next.chat_model_presets = presets.length > 0 ? presets : DEFAULT_CHAT_MODEL_PRESETS;
  if (!next.active_chat_model_id) {
    next.active_chat_model_id = next.chat_model_presets[0].id;
  }
  next.llm_provider = next.llm_provider || next.chat_provider || next.chat_model_presets[0].provider || 'deepseek';
  const modelConfig = normalizeModelConfig(next);
  next.model_profile_schema_version = modelConfig.schemaVersion;
  next.model_profiles = modelConfig.profiles;
  next.model_role_bindings = modelConfig.roleBindings;
  next.model_fallback_enabled = modelConfig.fallbackEnabled;
  next.model_fallback_bindings = modelConfig.fallbackBindings;
  next.model_config_diagnostics = modelConfig.diagnostics;
  const providers = [...new Set(modelConfig.profiles.map((profile) => {
    const ref = String(profile.credentialRef || '');
    const separator = ref.indexOf(':');
    return normalizeProvider(separator >= 0 ? ref.slice(separator + 1) : (ref || profile.provider));
  }))];
  next.credential_backend = credentialStore.backend;
  next.credential_status = Object.fromEntries(providers.map((provider) => [provider, !!getApiKey(provider)]));
  next.deepseek_configured = !!next.credential_status.deepseek;
  next.dashscope_configured = !!next.credential_status.dashscope;
  return next;
}

function _extractCredentialUpdates(input) {
  const settings = input && typeof input === 'object' ? { ...input } : {};
  const credentials = {};
  const explicit = settings.credential_updates && typeof settings.credential_updates === 'object'
    ? settings.credential_updates
    : {};
  for (const [provider, secret] of Object.entries(explicit)) {
    if (secret) credentials[normalizeProvider(provider)] = String(secret).trim();
  }
  delete settings.credential_updates;
  for (const key of Object.keys(settings)) {
    if (!key.endsWith('_api_key')) continue;
    const secret = settings[key];
    if (secret) credentials[normalizeProvider(key.slice(0, -'_api_key'.length))] = String(secret).trim();
    delete settings[key];
  }
  if (Array.isArray(settings.chat_model_presets)) {
    settings.chat_model_presets = settings.chat_model_presets.map((preset) => {
      if (!preset || typeof preset !== 'object') return preset;
      const { apiKey, ...safePreset } = preset;
      if (apiKey && safePreset.provider) {
        credentials[normalizeProvider(safePreset.provider)] = String(apiKey).trim();
      }
      return safePreset;
    });
  }
  return { settings, credentials };
}

function getChatModelPreset(id) {
  const settings = getAiSettings();
  const presets = settings.chat_model_presets || DEFAULT_CHAT_MODEL_PRESETS;
  return presets.find((p) => p.id === id) || presets.find((p) => p.id === settings.active_chat_model_id) || presets[0];
}

function resolveChatModelCredential({ preset, profiles, getCredential }) {
  const selected = preset && typeof preset === 'object' ? preset : {};
  const profile = (Array.isArray(profiles) ? profiles : [])
    .find((item) => item && item.id === selected.id);
  const ref = String(profile?.credentialRef || '');
  const refId = ref.includes(':') ? ref.slice(ref.indexOf(':') + 1) : ref;
  const candidates = [refId, selected.id, selected.provider]
    .map((value) => String(value || '').trim())
    .filter(Boolean)
    .map((value) => normalizeProvider(value));
  for (const credentialId of [...new Set(candidates)]) {
    const secret = getCredential(credentialId);
    if (secret) return secret;
  }
  return '';
}

function getChatModelCredential(preset) {
  const settings = getAiSettings();
  return resolveChatModelCredential({
    preset,
    profiles: settings.model_profiles,
    getCredential: getApiKey,
  });
}

/**
 * 获取指定 provider 的 API key。
 * 桌面版：从用户设置文件读。
 * Web 版：fallback 到 process.env。
 *
 * @param {string} provider - 'deepseek' | 'dashscope' | ...
 * @returns {string} - API key 或空字符串
 */
function getApiKey(provider) {
  const id = normalizeProvider(provider);
  const envKey = `${id.toUpperCase().replace(/[^A-Z0-9]/g, '_')}_API_KEY`;
  return credentialStore.get(id) || process.env[envKey] || '';
}

/**
 * 获取 chat provider 名称（桌面版从用户设置读，否则走环境变量）。
 */
function getChatProviderName() {
  const settings = getAiSettings();
  const preset = getChatModelPreset(settings.active_chat_model_id);
  return (preset && preset.provider) || settings.llm_provider || process.env.PETRI_LLM_PROVIDER || 'deepseek';
}

/**
 * 获取 embed provider 名称。
 */
function getEmbedProviderName() {
  const settings = getAiSettings();
  return settings.embed_provider || process.env.PETRI_EMBED_PROVIDER || 'dashscope';
}

/**
 * 保存 AI 设置（设置页调用）。
 * @param {object} settings - ordinary settings plus optional one-way credential_updates.
 */
function saveAiSettings(settings) {
  _ensureDir();
  const prev = getAiSettings();
  const extracted = _extractCredentialUpdates(settings);
  for (const [provider, secret] of Object.entries(extracted.credentials)) {
    credentialStore.set(provider, secret);
  }
  const merged = { ...prev, ...extracted.settings };
  // The Stage 1 UI still writes chat_model_presets. When it does not also send
  // model_profiles, rebuild profiles from those presets instead of retaining a
  // stale normalized snapshot from the previous read.
  if (extracted.settings && Array.isArray(extracted.settings.chat_model_presets) && !Array.isArray(extracted.settings.model_profiles)) {
    delete merged.model_profiles;
  }
  _cache = normalizeAiSettings(merged);
  fs.writeFileSync(SETTINGS_FILE, JSON.stringify(_cache, null, 2));
  fs.chmodSync(SETTINGS_FILE, 0o600);
  _cacheSignature = _settingsFileSignature();
}

/**
 * 测试 API key 连通性（设置页"测试"按钮调用）。
 */
async function testApiKey(provider, apiKey) {
  try {
    const { getProvider } = require('../../shared-backend/llm-providers');
    const { normalizeModelProfile } = require('../../shared-backend/llm-providers/model-profile');
    const profile = typeof provider === 'object'
      ? normalizeModelProfile(provider)
      : normalizeModelProfile({ provider, model: 'connection-test' });
    if (!profile) return { ok: false, message: '模型配置无效' };
    const p = getProvider(profile.provider);
    if (!p) return { ok: false, message: `Provider ${profile.provider} 未注册` };
    if (typeof p.healthCheck === 'function') {
      const ref = String(profile.credentialRef || `provider:${profile.provider.replace(/-vision$/, '')}`);
      const credentialId = ref.includes(':') ? ref.slice(ref.indexOf(':') + 1) : ref;
      const resolvedKey = apiKey || getApiKey(credentialId);
      const ok = await p.healthCheck(resolvedKey || '', {
        baseUrl: profile.baseUrl,
        model: profile.model,
        profile,
      });
      return { ok, message: ok ? '连接正常' : '连接失败' };
    }
    return { ok: true, message: 'Provider 无健康检查，跳过' };
  } catch (e) {
    return { ok: false, message: e.message };
  }
}

/**
 * 从 DeepSeek 或 OpenAI-compatible Endpoint 获取可用模型。
 * Key 仅作为一次性 IPC 参数或从凭据存储解析，不写入设置快照。
 */
async function listAvailableModels(provider, apiKey) {
  try {
    const { getProvider } = require('../../shared-backend/llm-providers');
    const { normalizeModelProfile } = require('../../shared-backend/llm-providers/model-profile');
    const input = typeof provider === 'object'
      ? { ...provider, model: provider.model || 'model-discovery' }
      : { provider, model: 'model-discovery' };
    const profile = normalizeModelProfile(input);
    if (!profile) return { ok: false, models: [], message: '模型接口配置无效' };
    const p = getProvider(profile.provider);
    if (!p) return { ok: false, models: [], message: `Provider ${profile.provider} 未注册` };
    if (typeof p.listModels !== 'function') {
      return { ok: false, models: [], message: `Provider ${profile.provider} 不支持模型列表查询` };
    }
    const ref = String(profile.credentialRef || `provider:${profile.provider.replace(/-vision$/, '')}`);
    const credentialId = ref.includes(':') ? ref.slice(ref.indexOf(':') + 1) : ref;
    const resolvedKey = apiKey || getApiKey(credentialId);
    const result = await p.listModels(resolvedKey || '', {
      baseUrl: profile.baseUrl,
      profile,
    });
    const models = Array.isArray(result && result.models)
      ? [...new Set(result.models.map((value) => String(value || '').trim()).filter(Boolean))].slice(0, 1000)
      : [];
    return {
      ok: result && result.ok === true && models.length > 0,
      models,
      message: (result && result.message) || (models.length > 0 ? `已获取 ${models.length} 个模型` : '接口未返回可用模型'),
    };
  } catch (e) {
    return { ok: false, models: [], message: e.message };
  }
}

module.exports = {
  getAiSettings,
  getApiKey,
  getChatProviderName,
  getChatModelPreset,
  getChatModelCredential,
  getEmbedProviderName,
  saveAiSettings,
  testApiKey,
  listAvailableModels,
