};

/**
 * helpers/ai-usage.js — AI_USAGE_v1 (telemetry: tokens / latency / errors)
 *
 * Extracted from server.js. Pure module: depends only on ../db.
 *
 * Public API:
 *   recordAiUsage({userId, kind, model, promptTokens, completionTokens, latencyMs, errorCode, conversationId})
 *   estimateCostCNY(model, promptTokens, completionTokens) → number (¥)
 *   AI_PRICING        — exported pricing table (¥ per 1M tokens)
 */

const dbMod = require('../db');
const sqlite = dbMod.getDatabase();

// One-time table create (idempotent)
sqlite.exec(`
  CREATE TABLE IF NOT EXISTS ai_usage (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id TEXT,
    ts TEXT NOT NULL,
    kind TEXT NOT NULL,
    model TEXT,
    prompt_tokens INTEGER DEFAULT 0,
    completion_tokens INTEGER DEFAULT 0,
    latency_ms INTEGER DEFAULT 0,
    cache_read_tokens INTEGER DEFAULT 0,
    cache_creation_tokens INTEGER DEFAULT 0,
    cost_cny REAL,
    cost_status TEXT DEFAULT 'unknown',
    error_code TEXT,
    conversation_id TEXT
  );
  CREATE INDEX IF NOT EXISTS idx_ai_usage_user_ts ON ai_usage(user_id, ts DESC);
  CREATE INDEX IF NOT EXISTS idx_ai_usage_ts ON ai_usage(ts DESC);
  CREATE INDEX IF NOT EXISTS idx_ai_usage_kind ON ai_usage(kind, ts DESC);
  CREATE INDEX IF NOT EXISTS idx_ai_usage_conv ON ai_usage(conversation_id);
`);
for (const statement of [
  'ALTER TABLE ai_usage ADD COLUMN cache_read_tokens INTEGER DEFAULT 0',
  'ALTER TABLE ai_usage ADD COLUMN cache_creation_tokens INTEGER DEFAULT 0',
  'ALTER TABLE ai_usage ADD COLUMN cost_cny REAL',
  "ALTER TABLE ai_usage ADD COLUMN cost_status TEXT DEFAULT 'unknown'",
  // BLOCK-79 P1 — 供应商归因（additive；旧行 NULL = 未归因）
  'ALTER TABLE ai_usage ADD COLUMN provider TEXT',
  // BLOCK-98 M5 — 请求韧性遥测（additive；旧行 0/NULL = 未标记）
  'ALTER TABLE ai_usage ADD COLUMN attempt INTEGER DEFAULT 0',
  'ALTER TABLE ai_usage ADD COLUMN retryable INTEGER DEFAULT 0',
  'ALTER TABLE ai_usage ADD COLUMN context_exceeded INTEGER DEFAULT 0',
  'ALTER TABLE ai_usage ADD COLUMN cancelled_by_user INTEGER DEFAULT 0',
]) {
  try { sqlite.exec(statement); } catch (_) { /* already migrated */ }
}
try { sqlite.exec('CREATE INDEX IF NOT EXISTS idx_ai_usage_provider_ts ON ai_usage(provider, ts DESC)'); } catch (_) {}
try { sqlite.exec('CREATE INDEX IF NOT EXISTS idx_ai_usage_conv ON ai_usage(conversation_id)'); } catch (_) {}

function recordAiUsage({userId, kind, model, provider, promptTokens, completionTokens, cacheReadTokens, cacheCreationTokens, latencyMs, errorCode, conversationId, costCny, costStatus, attempt, retryable, contextExceeded, cancelledByUser}) {
  try {
    const normalizedCost = Number.isFinite(Number(costCny)) ? Number(costCny) : null;
    sqlite.prepare(`INSERT INTO ai_usage (user_id, ts, kind, model, provider, prompt_tokens, completion_tokens, latency_ms, cache_read_tokens, cache_creation_tokens, cost_cny, cost_status, error_code, conversation_id, attempt, retryable, context_exceeded, cancelled_by_user)
                VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`)
      .run(
        userId || null,
        new Date().toISOString(),
        kind || 'other',
        model || null,
        provider || null,
        promptTokens|0,
        completionTokens|0,
        latencyMs|0,
        cacheReadTokens|0,
        cacheCreationTokens|0,
        normalizedCost,
        costStatus || (normalizedCost == null ? 'unknown' : 'estimated'),
        errorCode || null,
        conversationId || null,
        attempt|0,
        retryable ? 1 : 0,
        contextExceeded ? 1 : 0,
        cancelledByUser ? 1 : 0,
      );
  } catch (e) {
    console.warn('[ai-usage] insert failed:', e && e.message);
  }
}

function summarizeAiUsage({ userId = null, conversationId = null, since = null } = {}) {
  const clauses = [];
  const params = [];
  if (userId) { clauses.push('user_id = ?'); params.push(userId); }
  if (conversationId) { clauses.push('conversation_id = ?'); params.push(conversationId); }
  if (since) { clauses.push('ts >= ?'); params.push(since); }
  const where = clauses.length ? `WHERE ${clauses.join(' AND ')}` : '';
  const row = sqlite.prepare(`SELECT COUNT(*) AS calls,
    COALESCE(SUM(prompt_tokens),0) AS inputTokens,
    COALESCE(SUM(completion_tokens),0) AS outputTokens,
    COALESCE(SUM(cache_read_tokens),0) AS cacheReadTokens,
    COALESCE(SUM(cache_creation_tokens),0) AS cacheCreationTokens,
    COALESCE(SUM(cost_cny),0) AS estimatedCostCny,
    SUM(CASE WHEN cost_status = 'unknown' THEN 1 ELSE 0 END) AS unknownCostCalls,
    SUM(CASE WHEN error_code IS NOT NULL THEN 1 ELSE 0 END) AS failedCalls
    FROM ai_usage ${where}`).get(...params);
  return { ...row, cacheHitRate: row.inputTokens > 0 ? row.cacheReadTokens / row.inputTokens : 0, costStatus: row.unknownCostCalls > 0 ? 'partial' : 'estimated' };
}

/**
 * BLOCK-78 P2-② — 项目级用量聚合（读面；不改 summarizeAiUsage 契约）。
 * ai_usage 经 conversation_id JOIN copilot_conversations.project_id 归因到
 * 项目；conversation_id 为空的行（无会话上下文调用）不计入项目口径。
 */
function summarizeProjectUsage({ projectId = null, userId = null } = {}) {
  const empty = {
    calls: 0, inputTokens: 0, outputTokens: 0, cacheReadTokens: 0,
    estimatedCostCny: 0, unknownCostCalls: 0, failedCalls: 0,
    cacheHitRate: 0, costStatus: 'estimated',
  };
  if (!projectId) return empty;
  try {
    const clauses = ['c.project_id = ?'];
    const params = [projectId];
    if (userId) { clauses.push('au.user_id = ?'); params.push(userId); }
    const row = sqlite.prepare(`SELECT COUNT(*) AS calls,
      COALESCE(SUM(au.prompt_tokens),0) AS inputTokens,
      COALESCE(SUM(au.completion_tokens),0) AS outputTokens,
      COALESCE(SUM(au.cache_read_tokens),0) AS cacheReadTokens,
      COALESCE(SUM(au.cost_cny),0) AS estimatedCostCny,
      SUM(CASE WHEN au.cost_status = 'unknown' THEN 1 ELSE 0 END) AS unknownCostCalls,
      SUM(CASE WHEN au.error_code IS NOT NULL THEN 1 ELSE 0 END) AS failedCalls
      FROM ai_usage au
      JOIN copilot_conversations c ON au.conversation_id = c.id
      WHERE ${clauses.join(' AND ')}`).get(...params);
    if (!row) return empty;
    return {
      ...row,
      cacheHitRate: row.inputTokens > 0 ? row.cacheReadTokens / row.inputTokens : 0,
      costStatus: row.unknownCostCalls > 0 ? 'partial' : 'estimated',
    };
  } catch (e) {
    console.warn('[ai-usage] summarizeProjectUsage failed:', e && e.message);
    return empty;
  }
}

/**
 * BLOCK-79 P1 — 按供应商的输出速率聚合（成对口径：tokens/latency 同表求和）。
 *
 * - 口径：tokensPerSecond = SUM(completion_tokens) ÷ (SUM(latency_ms)/1000)
 *   = 端到端平均输出速率（含排队/首 token 前 prefill/网络），是真实解码
 *   速度的下限；界面禁止称「解码速度」。
 * - kind 过滤：排除 embedding（无输出 token，污染分母）；其余 LLM 文本
 *   调用（chat/chat_turn/tool_summary_retry/agent_iter…）全部计入。
 * - 不可算边界：completion_tokens=0 的调用（渠道未返回 usage）单独计数，
 *   全组皆如此时 measurable=false，前端显示「不可算」而非 0。
 * - 旧行 provider 为 NULL → 归入「(未归因)」组。
 */
function summarizeProviderUsage({ userId = null, since = null, limit = 20 } = {}) {
  try {
    const clauses = ["kind <> 'embedding'"];
    const params = [];
    if (since) { clauses.push('ts >= ?'); params.push(since); }
    if (userId) { clauses.push('user_id = ?'); params.push(userId); }
    params.push(Math.max(1, Math.min(50, Number(limit) || 20)));
    const rows = sqlite.prepare(`SELECT COALESCE(provider,'(未归因)') AS provider,
        COUNT(*) AS calls,
        COALESCE(SUM(prompt_tokens),0) AS inputTokens,
        COALESCE(SUM(completion_tokens),0) AS outputTokens,
        COALESCE(SUM(latency_ms),0) AS latencyMs,
        SUM(CASE WHEN COALESCE(completion_tokens,0) > 0 THEN 1 ELSE 0 END) AS measurableCalls,
        SUM(CASE WHEN COALESCE(completion_tokens,0) = 0 THEN 1 ELSE 0 END) AS noUsageCalls
      FROM ai_usage
      WHERE ${clauses.join(' AND ')}
      GROUP BY provider
      ORDER BY outputTokens DESC
      LIMIT ?`).all(...params);
    return rows.map((r) => ({
      ...r,
      tokensPerSecond: Number(r.latencyMs) > 0
        ? Math.round((r.outputTokens / (r.latencyMs / 1000)) * 10) / 10
        : null,
      measurable: Number(r.measurableCalls) > 0,
    }));
  } catch (e) {
    console.warn('[ai-usage] summarizeProviderUsage failed:', e && e.message);
    return [];
  }
}

// Pricing in CNY per 1M tokens.
const AI_PRICING = {  'deepseek-chat':           {input: 0.5, output: 8.0,  cacheHit: 0.1},
  'deepseek-reasoner':       {input: 0.5, output: 8.0,  cacheHit: 0.1},
  'text-embedding-v3':       {input: 0.7, output: 0.0},
};

function estimateCostCNY(model, promptTokens, completionTokens) {
  const p = AI_PRICING[model] || {input: 0.5, output: 8.0};
  const cost = (promptTokens / 1e6) * p.input + (completionTokens / 1e6) * (p.output || 0);
  return Math.round(cost * 1e6) / 1e6;
}

module.exports = {
  recordAiUsage,
  summarizeAiUsage,
  summarizeProjectUsage,
  summarizeProviderUsage,
  estimateCostCNY,
  AI_PRICING,
};

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const ARTIFACT_TRUTH_VERSION = 1;
const STAGED_INPUT_EXCLUSION_POLICY = 'server_staged_inputs_v1';
const SHA256_BUFFER_BYTES = 1024 * 1024;
const INTERNAL_FILES = new Set([
  'params.json',
  'run-script.R',
  'run-script.py',
  '_petri-theme.R',
  'report-template.html',
  'manifest.json',
  'artifact-manifest.json',
  'provenance.json',
  'delivery-manifest.json',
]);
const INTERNAL_FILE_NAMES = new Set(Array.from(INTERNAL_FILES, (name) => name.toLowerCase()));

function isSafeFlatFilename(value) {
  return typeof value === 'string'
    && value.length > 0
    && !value.includes('\0')
    && !value.includes('/')
    && !value.includes('\\')
    && value !== '.'
    && value !== '..'
    && !path.isAbsolute(value)
    && !path.win32.isAbsolute(value)
    && !/^[A-Za-z]:/.test(value)
    && path.basename(value) === value;
}

function isInternalArtifactName(value) {
  return isSafeFlatFilename(value) && INTERNAL_FILE_NAMES.has(value.toLowerCase());
}

function artifactContentTypeHint(filePath) {
  const extension = path.extname(String(filePath || '')).toLowerCase();
  return extension || 'application/octet-stream';
}

function sha256File(filePath, io = fs) {
  const fd = io.openSync(filePath, 'r');
  try {
    return sha256FileDescriptor(fd, io);
  } finally {
    io.closeSync(fd);
  }
}

function sha256FileDescriptor(fd, io = fs) {
  const hash = crypto.createHash('sha256');
  const buffer = Buffer.allocUnsafe(SHA256_BUFFER_BYTES);
  let position = 0;
  while (true) {
    const bytesRead = io.readSync(fd, buffer, 0, buffer.length, position);
    if (bytesRead === 0) break;
    hash.update(buffer.subarray(0, bytesRead));
    position += bytesRead;
  }
  return hash.digest('hex');
}

function captureStagedInputSnapshots(filePaths = []) {
  return (filePaths || []).map((filePath) => {
    const resolvedPath = fs.realpathSync(filePath);
    const stat = fs.statSync(resolvedPath);
    if (!stat.isFile()) throw new Error(`staged_input_not_regular_file:${path.basename(resolvedPath)}`);
    return {
      path: resolvedPath,
      name: path.basename(resolvedPath),
      sizeBytes: stat.size,
      sha256: sha256File(resolvedPath),
    };
  });
}

function stagedInputMutationIssues(snapshots = []) {
  return (snapshots || []).flatMap((snapshot) => {
    let currentPath = null;
    let currentSize = null;
    let currentSha256 = null;
    try {
      currentPath = fs.realpathSync(snapshot.path);
      const stat = fs.statSync(currentPath);
      if (stat.isFile()) {
        currentSize = stat.size;
        currentSha256 = sha256File(currentPath);
      }
    } catch {}
    if (currentPath === snapshot.path
        && currentSize === snapshot.sizeBytes
        && currentSha256 === snapshot.sha256) return [];
    return [{
      code: 'staged_input_mutated',
      severity: 'error',
      recoverable: true,
      required: true,
      artifactId: null,
      artifactName: snapshot.name || null,
      message: `Server-staged input ${snapshot.name || 'unknown'} changed during tool execution.`,
      suggestedFix: '插件必须把派生产物写入独立输出文件，不能覆盖、删除或修改服务器暂存输入。',
    }];
  });
}

function artifactName(item) {
  if (!item || typeof item !== 'object') return '';
  const value = item.filename || item.name || item.path;
  return value ? path.basename(String(value)) : '';
}

function artifactId(item) {
  if (!item || typeof item !== 'object') return '';
  return String(item.id || '').trim();
}

function inferArtifactType(item, name) {
  const explicit = String((item && (item.type || item.kind)) || '').toLowerCase();
  if (explicit === 'image') return 'plot';
  if (explicit === 'dataframe') return 'table';
  if (explicit === 'html') return 'report';
  if (['report', 'plot', 'table', 'text', 'json', 'data', 'file'].includes(explicit)) {
    return explicit;
  }
  const lower = String(name || '').toLowerCase();
  if (/\.html?$/.test(lower)) return 'report';
  if (/\.(png|jpg|jpeg|gif|svg|webp|pdf)$/.test(lower)) return 'plot';
  if (/\.(csv|tsv|xlsx?)$/.test(lower)) return 'table';
  if (/\.json$/.test(lower)) return 'json';
  if (/\.(txt|log|md)$/.test(lower)) return 'text';
  return 'file';
}

function artifactTypesCompatible(declaredType, detectedType) {
  if (!declaredType || declaredType === 'file' || !detectedType || detectedType === 'file') return true;
  if (declaredType === detectedType) return true;
  return new Set([declaredType, detectedType]).size === 2 &&
    ['data', 'table'].includes(declaredType) && ['data', 'table'].includes(detectedType);
}

function normalizeExcludedArtifactNames({
  resultDir,
  excludedArtifactPaths = [],
  trustedExcludedArtifactNames = [],
} = {}) {
  const names = new Set();
  const root = resultDir ? path.resolve(resultDir) : null;
  if (root) {
    for (const candidate of excludedArtifactPaths || []) {
      if (typeof candidate !== 'string' || !candidate || candidate.includes('\0')) continue;
      const resolved = path.resolve(candidate);
      if (path.dirname(resolved) !== root) continue;
      const name = path.basename(resolved);
      if (isSafeFlatFilename(name) && !isInternalArtifactName(name)) names.add(name);
    }
  }
  for (const candidate of trustedExcludedArtifactNames || []) {
    if (!isSafeFlatFilename(candidate) || isInternalArtifactName(candidate)) continue;
    names.add(candidate);
  }
  return names;
}

function listActualFiles(resultDir, excludedNames = new Set()) {
  if (!resultDir || !fs.existsSync(resultDir)) return [];
  return fs.readdirSync(resultDir, { withFileTypes: true })
    .filter((entry) =>
      entry.isFile() && !isInternalArtifactName(entry.name) && !excludedNames.has(entry.name)
    )
    .map((entry) => entry.name)
    .sort();
}

function collectDeclaredItems(result, excludedNames = new Set()) {
  const sources = [
    ['manifest.artifacts', result && result.manifest && result.manifest.artifacts],
    ['manifest.outputs', result && result.manifest && result.manifest.outputs],
    ['manifest.files', result && result.manifest && result.manifest.files],
    ['artifacts', result && result.artifacts],
    ['outputs', result && result.outputs],
    ['files', result && result.files],
  ];
  const byName = new Map();
  for (const [source, items] of sources) {
    if (!Array.isArray(items)) continue;
    for (const item of items) {
      const name = artifactName(item);
      if (!name || isInternalArtifactName(name) || excludedNames.has(name)) continue;
      const current = byName.get(name) || {};
      byName.set(name, { ...current, ...item, name, filename: name, _source: source });
    }
  }
  return Array.from(byName.values());
}

function expectedMatch(expected, declared, actualFiles) {
  const expectedName = artifactName(expected);
  const expectedId = artifactId(expected);
  if (expectedName) {
    return declared.find((item) => artifactName(item) === expectedName) ||
      (actualFiles.includes(expectedName) ? { ...expected, name: expectedName, filename: expectedName } : null);
  }
  if (!expectedId) return null;
  const byId = declared.find((item) => artifactId(item) === expectedId);
  if (byId) return byId;
  const byStem = actualFiles.find((name) => path.parse(name).name === expectedId);
  return byStem ? { ...expected, name: byStem, filename: byStem } : null;
}

function sanitizeManifest(manifest, validNames) {
  if (!manifest || typeof manifest !== 'object') return manifest || null;
  const next = { ...manifest };
  for (const key of ['artifacts', 'outputs', 'files']) {
    if (Array.isArray(next[key])) {
      next[key] = next[key].filter((item) => validNames.has(artifactName(item)));
    }
  }
  if (Array.isArray(next.sections)) {
    next.sections = next.sections
      .map((section) => {
        const names = Array.isArray(section && section.artifactNames)
          ? section.artifactNames.filter((name) => validNames.has(path.basename(String(name))))
          : [];
        return { ...section, artifactNames: names };
      })
      .filter((section) => section.artifactNames.length > 0);
  }
  return next;
}

function reconcileArtifactTruth({
  result = {},
  resultDir,
  expectedArtifacts = [],
  canonicalizePath = null,
  excludedArtifactPaths = [],
  trustedExcludedArtifactNames = [],
  stagedInputSnapshots = [],
  trustedStagedInputVerification = null,
} = {}) {
  const excludedNames = normalizeExcludedArtifactNames({
    resultDir,
    excludedArtifactPaths,
    trustedExcludedArtifactNames,
  });
  const unfilteredActualFiles = listActualFiles(resultDir);
  const unfilteredDeclared = collectDeclaredItems(result);
  const actualFiles = listActualFiles(resultDir, excludedNames);
  const actualSet = new Set(actualFiles);
  const declared = collectDeclaredItems(result, excludedNames);
  const expected = Array.isArray(expectedArtifacts) ? expectedArtifacts : [];
  const requiredNames = new Set();
  const inputMutationIssues = stagedInputSnapshots.length > 0
    ? stagedInputMutationIssues(stagedInputSnapshots)
    : trustedStagedInputVerification?.integrity === 'mutated'
      ? [{
          code: 'staged_input_mutated',
          severity: 'error',
          recoverable: true,
          required: true,
          artifactId: null,
          artifactName: null,
          message: 'A server-staged input changed during tool execution.',
          suggestedFix: '从受信执行路径重新运行任务，插件不得修改服务器暂存输入。',
        }]
      : [];
  const issues = [...inputMutationIssues];

  for (const item of expected) {
    const required = item && item.required !== false;
    const excludedMatch = expectedMatch(item, unfilteredDeclared, unfilteredActualFiles);
    const excludedName = artifactName(excludedMatch);
    if (excludedName && excludedNames.has(excludedName)) {
      issues.push({
        code: 'artifact_input_output_collision',
        severity: 'error',
        recoverable: true,
        required,
        artifactId: artifactId(item) || null,
        artifactName: excludedName,
        message: `Declared output ${excludedName} is the server-staged input file for this Job.`,
        suggestedFix: '让插件将输出写到不同文件名或独立 output 目录后重新执行任务。',
      });
      continue;
    }
    const match = expectedMatch(item, declared, actualFiles);
    if (match) {
      const name = artifactName(match);
      if (required && name) requiredNames.add(name);
      const declaredIndex = declared.findIndex((entry) => artifactName(entry) === name);
      if (declaredIndex >= 0) {
        // The runtime may discover a file before the plugin output contract is
        // applied. Preserve runtime fields, but restore the stable contract id,
        // label and type so downstream delivery coverage never depends on a
        // generated artifact_N identifier.
        declared[declaredIndex] = { ...declared[declaredIndex], ...item, name, filename: name };
      } else {
        declared.push({ ...match, ...item, name, filename: name });
      }
      continue;
    }
    if (required) {
      issues.push({
        code: 'required_artifact_missing',
        severity: 'error',
        recoverable: true,
        required: true,
        artifactId: artifactId(item) || null,
        artifactName: artifactName(item) || null,
        message: `Required artifact ${artifactId(item) || artifactName(item) || 'unknown'} was not produced.`,
        suggestedFix: '检查工具输出约定和运行日志，修复后重新执行任务。',
      });
    }
  }

  const declaredNames = new Set(declared.map(artifactName).filter(Boolean));
  for (const name of actualFiles) {
    if (!declaredNames.has(name)) declared.push({ name, filename: name, _source: 'disk' });
  }

  const validArtifacts = [];
  for (const [index, item] of declared.entries()) {
    const name = artifactName(item);
    if (!name) continue;
    const required = requiredNames.has(name) || item.required === true;
    const filePath = path.join(resultDir, name);
    if (!actualSet.has(name) || !fs.existsSync(filePath)) {
      issues.push({
        code: required ? 'required_artifact_missing' : 'artifact_missing',
        severity: required ? 'error' : 'warning',
        recoverable: true,
        required,
        artifactId: artifactId(item) || null,
        artifactName: name,
        source: item._source || null,
        message: `${required ? 'Required' : 'Declared'} artifact ${name} does not exist on disk.`,
        suggestedFix: required
          ? '检查工具输出约定和运行日志，修复后重新执行任务。'
          : '从 manifest 中移除失效声明，或重新生成该可选产物。',
      });
      continue;
    }
    let stat = null;
    try { stat = fs.statSync(filePath); } catch {}
    if (!stat || !stat.isFile() || stat.size === 0) {
      issues.push({
        code: required ? 'required_artifact_empty' : 'artifact_empty',
        severity: required ? 'error' : 'warning',
        recoverable: true,
        required,
        artifactId: artifactId(item) || null,
        artifactName: name,
        source: item._source || null,
        message: `${required ? 'Required' : 'Declared'} artifact ${name} is empty or unreadable.`,
        suggestedFix: '检查运行日志并重新生成该产物。',
      });
      continue;
    }
    const type = inferArtifactType(item, name);
    const declaredRawType = String((item && (item.type || item.kind)) || '').toLowerCase();
    const declaredType = declaredRawType ? inferArtifactType(item, '') : '';
    const detectedType = inferArtifactType(null, name);
    if (!artifactTypesCompatible(declaredType, detectedType)) {
      issues.push({
        code: 'artifact_type_mismatch',
        severity: required ? 'error' : 'warning',
        recoverable: true,
        required,
        artifactId: artifactId(item) || null,
        artifactName: name,
        source: item._source || null,
        message: `Artifact ${name} is declared as ${declaredType} but detected as ${detectedType}.`,
        suggestedFix: '修正 manifest 的 artifact type，或让工具输出符合声明类型的文件。',
      });
    }
    const label = item.label || item.title || name;
    const normalized = {
      ...item,
      id: artifactId(item) || `artifact_${index + 1}`,
      name,
      filename: name,
      type,
      label,
      title: item.title || label,
      path: filePath,
      size: stat.size,
      sha256: sha256File(filePath),
      required,
      preview: item.preview !== false,
      download: item.download !== false,
    };
    delete normalized._source;
    if (typeof canonicalizePath === 'function') {
      const rawCanonical = item.canonicalPath || canonicalizePath(filePath);
      normalized.canonicalPath =
        typeof rawCanonical === 'string' ? rawCanonical.split(path.sep).join('/') : rawCanonical;
    }
    validArtifacts.push(normalized);
  }

  const uniqueIssues = Array.from(new Map(
    issues.map((issue) => [`${issue.code}:${issue.artifactId || ''}:${issue.artifactName || ''}`, issue])
  ).values());
  const blocking = uniqueIssues.some((issue) => issue.severity === 'error');
  const validNames = new Set(validArtifacts.map((item) => item.name));
  const artifactTruth = {
    artifactTruthVersion: ARTIFACT_TRUTH_VERSION,
    status: blocking ? 'blocked' : uniqueIssues.length > 0 ? 'degraded' : 'valid',
    blocking,
    resultDir: resultDir ? path.resolve(resultDir) : null,
    declaredCount: declaredNames.size,
    actualCount: actualFiles.length,
    validCount: validArtifacts.length,
    issueCount: uniqueIssues.length,
    excludedInputCount: excludedNames.size,
    excludedInputNames: Array.from(excludedNames).sort(),
    exclusionPolicy: excludedNames.size > 0 ? STAGED_INPUT_EXCLUSION_POLICY : null,
    stagedInputSnapshotCount: stagedInputSnapshots.length > 0
      ? stagedInputSnapshots.length
      : Number(trustedStagedInputVerification?.snapshotCount || 0),
    stagedInputIntegrity: stagedInputSnapshots.length > 0
      ? inputMutationIssues.length > 0 ? 'mutated' : 'verified'
      : trustedStagedInputVerification?.integrity || null,
    checkedAt: new Date().toISOString(),
  };
  const cleanResult = {
    ...result,
    artifactSchemaVersion: result.artifactSchemaVersion || 1,
    artifactTruth,
    artifactDiagnostics: uniqueIssues,
    artifacts: validArtifacts,
    outputs: validArtifacts.map((item) => ({ ...item })),
    files: validArtifacts.map((item) => ({ ...item })),
    manifest: sanitizeManifest(result.manifest, validNames),
  };
  return { result: cleanResult, artifacts: validArtifacts, issues: uniqueIssues, artifactTruth, blocking };
}

module.exports = {
  ARTIFACT_TRUTH_VERSION,
  SHA256_BUFFER_BYTES,
  STAGED_INPUT_EXCLUSION_POLICY,
  artifactName,
  artifactContentTypeHint,
  inferArtifactType,
  artifactTypesCompatible,
  isInternalArtifactName,
  isSafeFlatFilename,
  normalizeExcludedArtifactNames,
  captureStagedInputSnapshots,
  stagedInputMutationIssues,
  sha256FileDescriptor,
  sha256File,
  reconcileArtifactTruth,
};

/**
 * Petri petri-server — chat file reference helpers (pure).
 *
 * These helpers classify and normalize references that come from model output,
 * link extraction, or the frontend fetcher payload. They intentionally do NOT
 * touch `fs`/DB/network.
 */

const path = require('path');

const INTERNAL_URI_RE = /^petri:\/\/(artifact|workspace)\/(.+)$/i;
const TOOLS_FILE_URL_RE = /^\/api\/(?:[^/]+\/)?tools\/file\/([A-Za-z0-9._-]+)\/(.+)$/i;

const DANGEROUS_PROTOCOLS = new Set(['javascript', 'data', 'vbscript', 'file', 'ftp']);

/**
 * Classify a reference string into one of the accepted shorthands.
 *
 * Returns `{kind, normalized}` or `null` when the reference is dangerous,
 * malformed, or uses an unsupported protocol. Absolute local paths are also
 * rejected because the chat renderer should never surface them.
 */
function classifyReference(reference) {
  const value = String(reference || '').trim();
  if (!value) return null;

  const normalized = normalizeWhitespace(value);
  // Reject genuinely unsafe characters. Backslashes are rejected here on
  // purpose: the chat resolver must never surface raw absolute local paths
  // (e.g. `C:\Users\...\file.csv`), which are contained only via the
  // route-level absolute_path gate on POSIX. See classifyReference contract.
  if (/[<>"|\\\x00-\x1F\x7F]/.test(normalized)) {
    return null;
  }

  const internalMatch = normalized.match(INTERNAL_URI_RE);
  if (internalMatch) {
    const kind = internalMatch[1].toLowerCase() === 'artifact' ? 'artifact' : 'workspace';
    const decoded = decodePathSegments(internalMatch[2]);
    return decoded == null ? null : { kind, normalized: decoded };
  }

  const urlMatch = normalized.match(TOOLS_FILE_URL_RE);
  if (urlMatch) {
    const decoded = decodePathSegments(urlMatch[2]);
    if (decoded == null) return null;
    return {
      kind: 'artifact_tools_url',
      jobId: urlMatch[1],
      normalized: `${urlMatch[1]}/${decoded}`,
    };
  }

  if (/^[A-Za-z][A-Za-z0-9+.-]*:\/\//.test(normalized)) {
    if (DANGEROUS_PROTOCOLS.has(normalized.split(':')[0].toLowerCase())) {
      return null;
    }
    return null;
  }

  if (/^[A-Za-z][A-Za-z0-9+.-]*:/.test(normalized)) {
    return null;
  }

  if (path.isAbsolute(normalized) || /^[A-Za-z]:[\\/]/.test(normalized)) {
    return { kind: 'absolute_path', normalized };
  }

  const trimmedLeading = normalized.replace(/^\.\/+/, '');
  const cleaned = trimmedLeading.replace(/^\/+/, '').replace(/\/{2,}/g, '/');
  const hasPathChars = /[/\\]/.test(cleaned);
  const looksLikeFile = /\.[A-Za-z0-9]+$/.test(cleaned);
  if (looksLikeFile && !hasPathChars) {
    return { kind: 'bare_filename', normalized: cleaned };
  }

  if (hasPathChars || /^\.{1,2}\//.test(normalized)) {
    return { kind: 'project_relative_path', normalized: cleaned };
  }

  return null;
}

/**
 * Normalize a classified reference into a normal form the route can resolve.
 *
 * Contract:
 * - internal URIs: decoded tail.
 * - tools file URLs: converted to `jobId/filename`.
 * - project relative-absolute paths: returned trimmed with forward slashes.
 * - bare filenames: returned as-is (caller must restrict to activeJobId).
 * - dangerous/unsupported references: return `null`.
 */
function normalizeReference(reference) {
  const classification = classifyReference(reference);
  if (!classification) return null;

  if (
    classification.kind === 'artifact' ||
    classification.kind === 'workspace' ||
    classification.kind === 'artifact_tools_url' ||
    classification.kind === 'project_relative_path' ||
    classification.kind === 'absolute_path' ||
    classification.kind === 'bare_filename'
  ) {
    return {
      reference,
      kind: classification.kind,
      normalized: classification.normalized,
      ...(classification.jobId ? { jobId: classification.jobId } : {}),
    };
  }

  return null;
}

/**
 * Return a Markdown-safe internal URI for a resolved artifact or workspace file.
 * Caller should not expose file:// or absolute local paths.
 */
function toInternalUri(resolved) {
  if (!resolved || !resolved.kind) return null;
  if (resolved.kind === 'artifact') {
    const jobId = encodeURIComponent(String(resolved.jobId || '').trim());
    const artifactName = String(resolved.artifactName || resolved.name || '')
      .split('/')
      .map((part) => encodeURIComponent(part))
      .join('/');
    return `petri://artifact/${jobId}/${artifactName}`;
  }
  if (resolved.kind === 'workspace') {
    const projectId = encodeURIComponent(String(resolved.projectId || '').trim());
    const relativePath = String(resolved.relativePath || '')
      .split('/')
      .map((part) => encodeURIComponent(part))
      .join('/');
    return `petri://workspace/${projectId}/${relativePath}`;
  }
  return null;
}

function decodePathSegments(value) {
  try {
    return String(value || '')
      .split('/')
      .map((segment) => decodeURIComponent(segment))
      .join('/');
  } catch {
    return null;
  }
}

function hasUsableArtifactTruth(result) {
  const truth = result && typeof result === 'object' ? result.artifactTruth : null;
  if (!truth || truth.blocking === true) return false;
  return truth.status === 'valid' || truth.status === 'degraded';
}

function isRealPathInsideRoot(rootPath, targetPath) {
  if (!rootPath || !targetPath) return false;
  let root = path.resolve(rootPath);
  let target = path.resolve(targetPath);
  // Windows filesystems are case-insensitive but path.resolve / realpathSync
  // can return drive-letter or directory casing that differs from the path the
  // caller created (e.g. os.tmpdir vs the on-disk entry) — compare insensitively.
  if (process.platform === 'win32') {
    root = root.toLowerCase();
    target = target.toLowerCase();
  }
  if (target === root) return false;
  const rootWithSep = root.endsWith(path.sep) ? root : root + path.sep;
  return target.startsWith(rootWithSep);
}

function normalizeWhitespace(value) {
  return String(value || '')
    .replace(/[\t\r\n ]+/g, ' ')
    .trim();
}

module.exports = {
  classifyReference,
  normalizeReference,
  toInternalUri,
  hasUsableArtifactTruth,
  isRealPathInsideRoot,
};

/**
 * helpers/chat-summary.js — CHAT_SUMMARY_v1
 *
 * Extracted from server.js (Phase 8.6 helper modularization).
 * Persists through ./db and delegates model work to the shared Gateway.
 *
 * Public API:
 *   getChatSummaryAsync(userId, projectId)            → Promise<row|null>
 *   saveChatSummaryAsync(userId, projectId, s, count) → Promise<void>
 *   deleteChatSummaryAsync(userId, projectId)         → Promise<void>
 *   summarizeMessages(userId, projectId, oldMessages, existingSummary) → Promise<void>
 *   SUMMARY_TRIGGER_AT, SUMMARY_KEEP_RECENT
 *
 * Async helpers use the Promise facade over desktop SQLite.
 */

const dbMod = require('../db');

// One-time table create (idempotent — safe to re-run on every server boot)
let _tableChecked = false;
async function _ensureTable() {
  if (_tableChecked) return;
  _tableChecked = true;
  const adb = dbMod.getAsyncDatabase();
  try {
    await adb.exec(`
      CREATE TABLE IF NOT EXISTS project_chat_summaries (
        user_id TEXT NOT NULL,
        project_id TEXT NOT NULL DEFAULT '',
        summary TEXT NOT NULL,
        msg_count INTEGER NOT NULL DEFAULT 0,
        updated_at TEXT NOT NULL,
        PRIMARY KEY (user_id, project_id)
      );
    `);
    // Legacy summaries had one row per user. Preserve them only in the
    // project-less scope; never inject them into a concrete project.
    try {
      await adb.exec(`
        INSERT OR IGNORE INTO project_chat_summaries(user_id, project_id, summary, msg_count, updated_at)
        SELECT user_id, '', summary, msg_count, updated_at FROM chat_summaries
      `);
    } catch {}
  } catch {
    /* ignore */
  }
}

function _scopeKey(projectId) {
  return projectId ? String(projectId) : '';
}

async function getChatSummaryAsync(userId, projectId = null) {
  if (!userId) return null;
  await _ensureTable();
  const adb = dbMod.getAsyncDatabase();
  const row = await adb
    .prepare('SELECT summary, msg_count, updated_at FROM project_chat_summaries WHERE user_id = ? AND project_id = ?')
    .get(userId, _scopeKey(projectId));
  return row || null;
}

async function saveChatSummaryAsync(userId, projectId, summary, msgCount) {
  if (!userId) return;
  await _ensureTable();
  const adb = dbMod.getAsyncDatabase();
  await adb
    .prepare(
      `
    INSERT INTO project_chat_summaries(user_id, project_id, summary, msg_count, updated_at)
    VALUES (?, ?, ?, ?, ?)
    ON CONFLICT(user_id, project_id) DO UPDATE SET summary=excluded.summary, msg_count=excluded.msg_count, updated_at=excluded.updated_at
  `
    )
    .run(userId, _scopeKey(projectId), summary, msgCount, new Date().toISOString());
}

async function deleteChatSummaryAsync(userId, projectId = null) {
  if (!userId) return;
  await _ensureTable();
  const adb = dbMod.getAsyncDatabase();
  await adb.prepare('DELETE FROM project_chat_summaries WHERE user_id = ? AND project_id = ?').run(userId, _scopeKey(projectId));
}

/**
 * Compress older messages into a Chinese summary using the summary role.
 * Fire-and-forget; errors swallowed.
 */
async function summarizeMessages(userId, projectId, oldMessages, existingSummary) {
  if (!userId || !Array.isArray(oldMessages) || oldMessages.length === 0) return;

  const lines = oldMessages
    .map((m) => {
      const role = m.role === 'user' ? '用户' : 'AI';
      return role + ': ' + (m.content || '');
    })
    .join('\n\n');

  const sysPrompt =
    '你是对话归档助手。把下面这段较早的对话压缩成中文要点摘要，保留：用户研究的对象、关心的问题、关键结论、用过的参数、提到过的实体（cluster id、基因名、数据集名等）。\n\n要求：\n- 不超过 500 字\n- 用 "- " 列出，每点一句话\n- 时间顺序保留\n- 如果与已有摘要有重复，合并而非简单拼接\n- 保留专有名词和数字 精确';

  const userPrompt = existingSummary
    ? '已有摘要：\n' + existingSummary + '\n\n新增对话：\n' + lines + '\n\n请输出合并后的新摘要。'
    : '请总结以下对话：\n' + lines;

  const { callModelTask } = require('./model-tasks');
  const result = await callModelTask({
    role: 'summary',
    messages: [
      { role: 'system', content: sysPrompt },
      { role: 'user', content: userPrompt },
    ],
    temperature: 0.3,
    maxTokens: 800,
    telemetry: { userId, kind: 'chat_summary' },
  });
  if (!result.text) return;
  try {
    await saveChatSummaryAsync(
      userId,
      projectId,
      result.text,
      oldMessages.length + (existingSummary ? -1 : 0)
    );
    console.log('[chat-summary] saved for scope', _scopeKey(projectId) || 'global', 'len=', result.text.length);
  } catch (e) {
    console.log('[chat-summary-err]', e && e.message);
  }
}

const SUMMARY_TRIGGER_AT = 22; // start summarizing once thread has > N msgs
const SUMMARY_KEEP_RECENT = 14; // keep this many recent msgs as raw context

// Sync wrapper for in-process callers using the same SQLite database.
function getChatSummary(userId, projectId = null) {
  if (!userId) return null;
  const sqlite = dbMod.getDatabase();
  try {
    // Guard: ensure table exists (idempotent — ignore errors from re-creating)
    sqlite.exec(`
      CREATE TABLE IF NOT EXISTS project_chat_summaries (
        user_id TEXT NOT NULL,
        project_id TEXT NOT NULL DEFAULT '',
        summary TEXT NOT NULL,
        msg_count INTEGER NOT NULL DEFAULT 0,
        updated_at TEXT NOT NULL,
        PRIMARY KEY (user_id, project_id)
      );
    `);
    const row = sqlite
      .prepare('SELECT summary, msg_count, updated_at FROM project_chat_summaries WHERE user_id = ? AND project_id = ?')
      .get(userId, _scopeKey(projectId));
    return row || null;
  } catch {
    return null;
  }
}

module.exports = {
  getChatSummaryAsync,
  getChatSummary, // SYNC_BRIDGE_v1
  saveChatSummaryAsync,
  deleteChatSummaryAsync,
  summarizeMessages,
  SUMMARY_TRIGGER_AT,
  SUMMARY_KEEP_RECENT,
};

/**
 * LLM Circuit Breaker — wraps callChatProvider with fault-tolerance.
 *
 * State machine:
 *   CLOSED → OPEN → HALF_OPEN → CLOSED (success) / OPEN (failure)
 *
 * Configuration:
 *   failureThreshold: 5  (consecutive failures to trip the breaker)
 *   recoveryTimeout: 60000 (1 minute before trying half-open)
 *   halfOpenMaxCalls: 3  (test requests allowed in half-open state)
 *
 * Usage:
 *   const { wrapChatProvider, llmCircuitBreaker, getBreakerHealth } = require('./circuit-breaker');
 *   const wrappedProvider = wrapChatProvider(callChatProvider);
 *   const result = await wrappedProvider(providerName, apiKey, body, telemetry, onEvent, options);
 */

const { CircuitBreaker: BaseCircuitBreaker } = require('./provider-reliability');
const logger = require('../../shared-backend/logger');

const STATES = { CLOSED: 'CLOSED', OPEN: 'OPEN', HALF_OPEN: 'HALF_OPEN' };

const DEFAULT_OPTIONS = {
  failureThreshold: 5,
  recoveryTimeout: 60000,
  halfOpenMaxCalls: 3,
};

class LLMCircuitBreaker extends BaseCircuitBreaker {
  constructor(options = {}) {
    super({
      failThreshold: options.failureThreshold || DEFAULT_OPTIONS.failureThreshold,
      cooldownMs: options.recoveryTimeout || DEFAULT_OPTIONS.recoveryTimeout,
    });

    this.halfOpenMaxCalls = options.halfOpenMaxCalls || DEFAULT_OPTIONS.halfOpenMaxCalls;
    this._halfOpenCalls = new Map();
    this._providerStats = new Map();
  }

  isOpen(key) {
    const entry = this.state.get(key);
    if (!entry) return false;

    const now = this.now();

    if (entry.state === STATES.HALF_OPEN) {
      const halfOpenCount = this._halfOpenCalls.get(key) || 0;
      if (halfOpenCount >= this.halfOpenMaxCalls) return true;
      return false;
    }

    if (entry.openUntil && now < entry.openUntil) return true;
    if (entry.openUntil) {
      this.state.set(key, {
        failures: 0,
        openUntil: 0,
        state: STATES.HALF_OPEN,
        halfOpenSuccesses: 0,
      });
      this._halfOpenCalls.set(key, 0);
      logger.info(`[circuit-breaker] HALF_OPEN: ${key} — recovery timeout elapsed, allowing test calls`);
    }
    return false;
  }

  /**
   * @returns {string} current state: CLOSED | OPEN | HALF_OPEN
   */
  getState(key) {
    const entry = this.state.get(key);
    if (!entry) return STATES.CLOSED;
    if (entry.openUntil && this.now() < entry.openUntil) return STATES.OPEN;
    if (entry.state === STATES.HALF_OPEN) return STATES.HALF_OPEN;
    return STATES.CLOSED;
  }

  recordFailure(key) {
    const entry = this.state.get(key) || { failures: 0, openUntil: 0, state: STATES.CLOSED };

    entry.failures += 1;

    if (entry.state === STATES.HALF_OPEN) {
      entry.openUntil = this.now() + this.cooldownMs;
      entry.state = STATES.OPEN;
      this._halfOpenCalls.set(key, 0);
      logger.warn(`[circuit-breaker] HALF_OPEN failure → OPEN: ${key} (failures: ${entry.failures})`);
      this.state.set(key, entry);
      return;
    }

    if (entry.failures >= this.failThreshold) {
      entry.openUntil = this.now() + this.cooldownMs;
      entry.state = STATES.OPEN;
      logger.warn(`[circuit-breaker] OPEN: ${key} — failure threshold reached (${entry.failures}/${this.failThreshold})`);
    }

    this.state.set(key, entry);
    this._updateStats(key, 'failure');
  }

  recordSuccess(key) {
    const entry = this.state.get(key);

    if (entry && entry.state === STATES.HALF_OPEN) {
      entry.halfOpenSuccesses = (entry.halfOpenSuccesses || 0) + 1;
      const halfOpenCount = this._halfOpenCalls.get(key) || 0;
      if (entry.halfOpenSuccesses >= this.halfOpenMaxCalls) {
        this.state.delete(key);
        this._halfOpenCalls.delete(key);
        logger.info(`[circuit-breaker] CLOSED: ${key} — recovery successful (${entry.halfOpenSuccesses} consecutive successes)`);
        this._updateStats(key, 'recovery');
        return;
      }
      this.state.set(key, entry);
      this._updateStats(key, 'success');
      return;
    }

    this.state.delete(key);
    this._updateStats(key, 'success');
  }

  _updateStats(key, event) {
    if (!this._providerStats.has(key)) {
      this._providerStats.set(key, { totalCalls: 0, successes: 0, failures: 0, recoveries: 0 });
    }
    const stats = this._providerStats.get(key);
    stats.totalCalls += 1;
    if (event === 'success') stats.successes += 1;
    else if (event === 'failure') stats.failures += 1;
    else if (event === 'recovery') stats.recoveries += 1;
  }

  recordCallStart(key) {
    const count = (this._halfOpenCalls.get(key) || 0) + 1;
    this._halfOpenCalls.set(key, count);
  }

  /**
   * Get health status for a specific provider or all providers.
   * @param {string|undefined} key - provider key, or undefined for all
   * @returns {object} health status
   */
  getHealth(key) {
    if (key) {
      const entry = this.state.get(key);
      const stats = this._providerStats.get(key);
      const state = this.getState(key);
      const failureRate = stats && stats.totalCalls > 0 ? stats.failures / stats.totalCalls : 0;
      return {
        provider: key,
        state,
        failures: entry ? entry.failures : 0,
        failureThreshold: this.failThreshold,
        recoveryTimeout: this.cooldownMs,
        halfOpenMaxCalls: this.halfOpenMaxCalls,
        halfOpenSuccesses: entry ? entry.halfOpenSuccesses : 0,
        halfOpenCallCount: this._halfOpenCalls.get(key) || 0,
        openUntil: entry && entry.openUntil ? entry.openUntil : null,
        stats: stats || null,
        failureRate: parseFloat(failureRate.toFixed(4)),
        healthy: state === STATES.CLOSED,
      };
    }

    const all = {};
    for (const [k] of this.state) {
      all[k] = this.getHealth(k);
    }
    for (const [k, v] of this._providerStats) {
      if (!all[k]) {
        all[k] = {
          provider: k,
          state: STATES.CLOSED,
          failures: 0,
          failureThreshold: this.failThreshold,
          recoveryTimeout: this.cooldownMs,
          halfOpenMaxCalls: this.halfOpenMaxCalls,
          halfOpenSuccesses: 0,
          halfOpenCallCount: 0,
          openUntil: null,
          stats: v,
          failureRate: parseFloat(((v.failures || 0) / (v.totalCalls || 1)).toFixed(4)),
          healthy: true,
        };
      }
    }
    return all;
  }

  /**
   * Reset circuit breaker state for a specific provider.
   * @param {string} key - provider key
   */
  reset(key) {
    this.state.delete(key);
    this._halfOpenCalls.delete(key);
    logger.info(`[circuit-breaker] Reset: ${key}`);
  }

  /**
   * Reset all circuit breaker state.
   */
  resetAll() {
    this.state.clear();
    this._halfOpenCalls.clear();
    this._providerStats.clear();
    logger.info('[circuit-breaker] All circuits reset');
  }
}

const llmCircuitBreaker = new LLMCircuitBreaker(DEFAULT_OPTIONS);

function wrapChatProvider(chatProviderFn, breakerOptions) {
  const breaker = breakerOptions instanceof LLMCircuitBreaker ? breakerOptions : new LLMCircuitBreaker(breakerOptions);

  return async function wrappedChatProvider(providerName, apiKey, body, telemetry, onEvent, options) {
    const key = providerName || 'default';

    if (breaker.isOpen(key)) {
      const state = breaker.getState(key);
      logger.warn(`[circuit-breaker] Service unavailable: ${key} (state: ${state})`);

      const err = new Error(`AI 服务暂时不可用 (${key})`);
      err.name = 'ServiceUnavailable';
      err.code = 'CIRCUIT_OPEN';
      err.provider = key;
      err.state = state;
      err.retryAfter = breakerOptions?.recoveryTimeout || DEFAULT_OPTIONS.recoveryTimeout;

      throw err;
    }

    breaker.recordCallStart(key);

    try {
      const result = await chatProviderFn(providerName, apiKey, body, telemetry, onEvent, options);

      if (result && result.error) {
        breaker.recordFailure(key);
        const err = new Error(result.message || `AI 服务调用失败 (${key})`);
        err.name = 'ServiceUnavailable';
        err.code = result.error || 'PROVIDER_ERROR';
        err.provider = key;
        throw err;
      }

      breaker.recordSuccess(key);
      return result;
    } catch (err) {
      if (err.name === 'ServiceUnavailable' && err.code === 'CIRCUIT_OPEN') {
        throw err;
      }
      breaker.recordFailure(key);
      throw err;
    }
  };
}

function getBreakerHealth(providerName) {
  return llmCircuitBreaker.getHealth(providerName);
}

function resetBreaker(key) {
  if (key) {
    llmCircuitBreaker.reset(key);
  } else {
    llmCircuitBreaker.resetAll();
  }
}

module.exports = {
  LLMCircuitBreaker,
  llmCircuitBreaker,
  wrapChatProvider,
  getBreakerHealth,
  resetBreaker,
  STATES,
  DEFAULT_OPTIONS,
};

