/**
 * Local AI credential store.
 *
 * macOS uses the login Keychain. Other platforms use a separate 0600 file so
 * secrets never enter ai-settings.json, renderer snapshots, or diagnostics.
 */

const fs = require('fs');
const path = require('path');
const childProcess = require('child_process');

const KEYCHAIN_SERVICE = 'com.petri.desktop.ai';

function normalizeProvider(provider) {
  const value = String(provider || '').trim().toLowerCase();
  if (!value || !/^[a-z0-9._-]+$/.test(value)) {
    throw new Error(`无效的凭据 Provider: ${provider || '(empty)'}`);
  }
  return value.replace(/-vision$/, '');
}

function createCredentialStore(options = {}) {
  const platform = options.platform || process.platform;
  const settingsDir = options.settingsDir;
  if (!settingsDir) throw new Error('Credential store requires settingsDir');
  const execFileSync = options.execFileSync || childProcess.execFileSync;
  const backend = options.backend || process.env.PETRI_CREDENTIAL_BACKEND ||
    (platform === 'darwin' ? 'keychain' : 'file');
  const filePath = path.join(settingsDir, 'ai-credentials.json');

  function readFileStore() {
    try {
      const parsed = JSON.parse(fs.readFileSync(filePath, 'utf8'));
      return parsed && typeof parsed === 'object' ? parsed : {};
    } catch {
      return {};
    }
  }

  function writeFileStore(values) {
    fs.mkdirSync(settingsDir, { recursive: true });
    const tempPath = `${filePath}.${process.pid}.tmp`;
    fs.writeFileSync(tempPath, JSON.stringify(values, null, 2), { mode: 0o600 });
    fs.chmodSync(tempPath, 0o600);
    fs.renameSync(tempPath, filePath);
    fs.chmodSync(filePath, 0o600);
  }

  function get(provider) {
    const id = normalizeProvider(provider);
    if (backend === 'keychain') {
      try {
        return String(execFileSync('/usr/bin/security', [
          'find-generic-password', '-a', id, '-s', KEYCHAIN_SERVICE, '-w',
        ], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] }) || '').trim();
      } catch {
        return '';
      }
    }
    return String(readFileStore()[id] || '');
  }

  function set(provider, secret) {
    const id = normalizeProvider(provider);
    const value = String(secret || '').trim();
    if (!value) return false;
    if (backend === 'keychain') {
      execFileSync('/usr/bin/security', [
        'add-generic-password', '-U', '-a', id, '-s', KEYCHAIN_SERVICE, '-w', value,
      ], { stdio: 'ignore' });
      return true;
    }
    const values = readFileStore();
    values[id] = value;
    writeFileStore(values);
    return true;
  }

  function remove(provider) {
    const id = normalizeProvider(provider);
    if (backend === 'keychain') {
      try {
        execFileSync('/usr/bin/security', [
          'delete-generic-password', '-a', id, '-s', KEYCHAIN_SERVICE,
        ], { stdio: 'ignore' });
      } catch {}
      return;
    }
    const values = readFileStore();
    if (!Object.prototype.hasOwnProperty.call(values, id)) return;
    delete values[id];
    writeFileStore(values);
  }

  return {
    backend,
    filePath,
    get,
    set,
    remove,
    isConfigured(provider) {
      return !!get(provider);
    },
  };
}

module.exports = { createCredentialStore, normalizeProvider, KEYCHAIN_SERVICE };

/**
 * helpers/docs-index.js — DOCS_INDEX_v1
 *
 * 桌面版优先从本地文件读取 copilot-index.json
 *   （内容同步时下载到 site 目录），fallback 到网络。
 */

const fs = require('fs');
const path = require('path');

let _docsIndexCache = null;
let _docsIndexFetchedAt = 0;
const DOCS_INDEX_TTL = 10 * 60 * 1000;
const DOCS_INDEX_URL_CANDIDATES = [
  'https://petri.com/copilot-index.json',
  'http://172.17.0.1/copilot-index.json',
  'http://localhost/copilot-index.json',
];

// 桌面版本地索引文件候选路径
function _getLocalIndexPaths() {
  const paths = [];
  // 1. PETRI_SITE_DIR 环境变量指定的 site 目录
  if (process.env.PETRI_SITE_DIR) {
    paths.push(path.join(process.env.PETRI_SITE_DIR, 'copilot-index.json'));
  }
  // 2. petri-server 同级 site 目录（Electron 打包时静态站在这里）
  paths.push(path.join(__dirname, '..', '..', 'site', 'copilot-index.json'));
  // 3. Electron resources 目录
  if (process.resourcesPath) {
    paths.push(path.join(process.resourcesPath, 'site', 'copilot-index.json'));
  }
  return paths;
}

function _readLocalIndex() {
  for (const p of _getLocalIndexPaths()) {
    try {
      if (fs.existsSync(p)) {
        const data = JSON.parse(fs.readFileSync(p, 'utf8'));
        if (data && (Array.isArray(data.docs) || Array.isArray(data.blog) || Array.isArray(data.figcode))) {
          console.log('[docs-index] loaded local from', p);
          return data;
        }
      }
    } catch {}
  }
  return null;
}

function fetchDocsIndex() {
  if (_docsIndexCache && Date.now() - _docsIndexFetchedAt < DOCS_INDEX_TTL) {
    return Promise.resolve(_docsIndexCache);
  }

  // 桌面版：先尝试本地文件，本地没有再 fallback 到网络。
  const localData = _readLocalIndex();
  if (localData) {
    _docsIndexCache = localData;
    _docsIndexFetchedAt = Date.now();
    return Promise.resolve(localData);
  }

  const urls = DOCS_INDEX_URL_CANDIDATES;
  return (async () => {
    for (const url of urls) {
      try {
        const isHttps = url.startsWith('https:');
        const lib = isHttps ? require('https') : require('http');
        const data = await new Promise((resolve) => {
          const req = lib.get(url, { timeout: 5000 }, (res) => {
            if (res.statusCode !== 200) {
              resolve(null);
              return;
            }
            let buf = '';
            res.setEncoding('utf8');
            res.on('data', (c) => (buf += c));
            res.on('end', () => {
              try {
                resolve(JSON.parse(buf));
              } catch {
                resolve(null);
              }
            });
          });
          req.on('error', () => resolve(null));
          req.on('timeout', () => {
            try {
              req.destroy();
            } catch {}
            resolve(null);
          });
        });
        if (
          data &&
          (Array.isArray(data.docs) || Array.isArray(data.blog) || Array.isArray(data.figcode))
        ) {
          _docsIndexCache = data;
          _docsIndexFetchedAt = Date.now();
          console.log('[docs-index] fetched from', url, 'docs=', data.counts && data.counts.docs);
          return data;
        }
      } catch {
        /* try next */
      }
    }
    return _docsIndexCache;
  })();
}

function getCachedDocsIndex() {
  return _docsIndexCache;
}

/** Render a compact docs/blog/figcode catalog for prompt injection. */
function renderDocsIndexForPrompt(idx, maxChars) {
  if (!idx) return '';
  maxChars = maxChars || 2200;
  let out = '\n\n=== Petri 站点内容索引（教程 / 博客 / FigCode 工具） ===\n';
  out +=
    '注：用户问"教程里讲过什么"或"FigCode 有没有 X"时，引用下面真实条目；要打开就 emit navigate action with target=external_link 或对应 url。\n';

  if (Array.isArray(idx.docs) && idx.docs.length > 0) {
    out += '\n[教程]';
    for (const d of idx.docs.slice(0, 80)) {
      let line = '\n- ' + d.title;
      if (d.url) line += ' (' + d.url + ')';
      if (d.summary) line += ' — ' + String(d.summary).slice(0, 80);
      if (out.length + line.length > maxChars - 200) {
        out += '\n... (more)';
        break;
      }
      out += line;
    }
  }

  if (Array.isArray(idx.blog) && idx.blog.length > 0) {
    out += '\n\n[博客]';
    for (const b of idx.blog.slice(0, 30)) {
      let line = '\n- ' + b.title;
      if (b.url) line += ' (' + b.url + ')';
      if (b.date) line += ' [' + b.date + ']';
      if (out.length + line.length > maxChars - 100) {
        out += '\n... (more)';
        break;
      }
      out += line;
    }
  }

  if (Array.isArray(idx.figcode) && idx.figcode.length > 0) {
    out += '\n\n[FigCode 工具]';
    for (const c of idx.figcode.slice(0, 60)) {
      let line = '\n- ' + c.title + (c.subtitle ? ' (' + c.subtitle + ')' : '');
      if (c.category) line += ' [' + c.category + ']';
      if (c.url) line += ' → ' + c.url;
      if (out.length + line.length > maxChars - 50) {
        out += '\n...';
        break;
      }
      out += line;
    }
  }
  return out;
}

module.exports = {
  fetchDocsIndex,
  renderDocsIndexForPrompt,
  getCachedDocsIndex,
};

'use strict';

/**
 * helpers/feature-flags.js — 灰度功能开关单一真相（2026-09-18 用户裁决「翻默认+设置页开关」）
 *
 * 管辖三个已实机验证的灰度开关（BLOCK-95 B1/B2 + BLOCK-98 M1-M3）：
 *   server_history_assembly  PETRI_SERVER_HISTORY_ASSEMBLY  B1 历史拼装收归后端
 *   session_compaction       PETRI_SESSION_COMPACTION       B2 会话级压缩（依赖 B1）
 *   agent_resilience         PETRI_AGENT_RESILIENCE         长任务韧性（microcompact/熔断/重试）
 *
 * 解析优先级（高→低）：
 *   1. 环境变量强制覆盖：=1/true 强制开，=0/false 强制关（kill-switch，杀进程级回滚）
 *   2. 设置页持久化选择：<dataDir>/feature-flags.json（仅存用户显式改动，删 key 即回默认）
 *   3. 默认值：全部 true（2026-09-18 裁决；此前灰度期默认关）
 */

const fs = require('fs');
const os = require('os');
const path = require('path');

const STORE_FILENAME = 'feature-flags.json';

const FLAG_DEFAULTS = Object.freeze({
  server_history_assembly: true,
  session_compaction: true,
  agent_resilience: true,
});

const FLAG_META = Object.freeze({
  server_history_assembly: {
    env: 'PETRI_SERVER_HISTORY_ASSEMBLY',
    label: '会话历史后端拼装（B1）',
    description: 'LLM 请求历史由数据库拼装（与对话记录同源），替代前端每轮全量上报。',
  },
  session_compaction: {
    env: 'PETRI_SESSION_COMPACTION',
    label: '长会话自动压缩（B2）',
    description: '超过阈值的历史轮次折叠为摘要参与模型视图，显著节省 token；数据库原文永不改动，压缩诚实可见。',
  },
  agent_resilience: {
    env: 'PETRI_AGENT_RESILIENCE',
    label: 'Agent 长任务韧性',
    description: '长任务自动清理旧工具结果（microcompact）、连续失败熔断、上下文超限原地重试。',
  },
});

function flagStorePath() {
  const root = process.env.PETRI_LOCAL_DATA_DIR || path.join(os.homedir(), 'Documents', 'Petri-Local');
  return path.join(root, STORE_FILENAME);
}

/** 读持久化选择（文件缺失/损坏 = 空选择，全走默认）。 */
function readStore() {
  try {
    const raw = fs.readFileSync(flagStorePath(), 'utf8');
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed.flags === 'object' && parsed.flags ? parsed.flags : {};
  } catch {
    return {};
  }
}

function writeStore(flags) {
  const clean = {};
  for (const key of Object.keys(FLAG_DEFAULTS)) {
    if (typeof flags[key] === 'boolean') clean[key] = flags[key];
  }
  const dir = path.dirname(flagStorePath());
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(flagStorePath(), JSON.stringify({ flags: clean, updatedAt: new Date().toISOString() }, null, 2) + '\n');
  return clean;
}

/**
 * 单开关解析：env 强制覆盖 > 持久化选择 > 默认值。
 * @param {keyof typeof FLAG_DEFAULTS} key
 * @param {object|undefined} env 可注入供测试（缺省 process.env）
 */
function resolveFlag(key, env = process.env) {
  const meta = FLAG_META[key];
  if (!meta) throw new Error(`feature_flag_unknown:${key}`);
  const raw = (env && env[meta.env]) || '';
  if (raw === '1' || raw === 'true') return true;
  if (raw === '0' || raw === 'false') return false;
  const stored = readStore()[key];
  if (typeof stored === 'boolean') return stored;
  return FLAG_DEFAULTS[key];
}

/** 全量快照（设置页投影用）：key → { enabled, envOverride, default } */
function getFlagsSnapshot(env = process.env) {
  const store = readStore();
  const flags = {};
  for (const key of Object.keys(FLAG_DEFAULTS)) {
    const meta = FLAG_META[key];
    const raw = (env && env[meta.env]) || '';
    const envOverride = raw === '1' || raw === 'true' ? true : raw === '0' || raw === 'false' ? false : null;
    const stored = typeof store[key] === 'boolean' ? store[key] : null;
    const enabled = envOverride != null ? envOverride : stored != null ? stored : FLAG_DEFAULTS[key];
    flags[key] = {
      enabled,
      envOverride,
      stored,
      default: FLAG_DEFAULTS[key],
      env: meta.env,
      label: meta.label,
      description: meta.description,
    };
  }
  return flags;
}

/** 设置页写入：仅接受三把已知开关；写持久化选择（env 强制覆盖时 UI 诚实标注不可写）。 */
function setFlag(key, enabled) {
  if (!(key in FLAG_DEFAULTS)) throw new Error(`feature_flag_unknown:${key}`);
  if (typeof enabled !== 'boolean') throw new Error('feature_flag_value_invalid');
  const store = readStore();
  store[key] = enabled;
  return writeStore(store);
}

module.exports = {
  FLAG_DEFAULTS,
  FLAG_META,
  STORE_FILENAME,
  flagStorePath,
  readStore,
  writeStore,
  resolveFlag,
  getFlagsSnapshot,
  setFlag,
};

