  return effectiveGuestPermissionsAsync();
}

module.exports = {
  SITE_KEY,
  GUEST_DEFAULT_PERMS,
  MODULE_KEYS,
  getGuestPermissionsRaw,
  getGuestPermissionsRawAsync,
  effectiveGuestPermissions,
  effectiveGuestPermissionsForApi,
  canGuest,
  canGuestAsync,
  effectiveGuestPermissionsAsync,
  setGuestPermissions,
  setGuestPermissionsAsync,
};

const EXECUTABLE_RECOVERY_ACTIONS = new Set(['reconcile_artifacts', 'retry_run']);

function createRecoveryConfirmationStore(options = {}) {
  const ttlMs = options.ttlMs || 5 * 60 * 1000;
  const now = options.now || (() => Date.now());
  const tokenFactory = options.tokenFactory || (() => `wf_${require('crypto').randomUUID()}`);
  const records = new Map();
  return {
    issue(payload) {
      const token = tokenFactory();
      const record = { ...payload, expiresAt: now() + ttlMs };
      records.set(token, record);
      return { token, ...record };
    },
    consume(token, expected = {}) {
      const record = records.get(token);
      records.delete(token);
      if (!record || record.expiresAt < now()) {
        return { ok: false, error: 'confirmation_invalid_or_expired' };
      }
      for (const [key, value] of Object.entries(expected)) {
        if (record[key] !== value) {
          return { ok: false, error: 'confirmation_invalid_or_expired' };
        }
      }
      return { ok: true, record };
    },
  };
}

function validateWorkflowRecoveryAction(job, actionId) {
  if (!job) return { ok: false, error: 'job_not_found' };
  if (!EXECUTABLE_RECOVERY_ACTIONS.has(actionId)) {
    return { ok: false, error: 'action_requires_agent' };
  }
  if (actionId === 'reconcile_artifacts') {
    const result = job.result || job.result_json;
    if (!result) return { ok: false, error: 'result_not_available' };
    return { ok: true };
  }
  if (!['failed', 'cancelled'].includes(String(job.status || '').toLowerCase())) {
    return { ok: false, error: 'job_not_retryable' };
  }
  if (!job.tool_id && !job.toolId) return { ok: false, error: 'tool_not_available' };
  return { ok: true };
}

function appendWorkflowRecoveryAudit(params, entry, maxEntries = 20) {
  const source = params && typeof params === 'object' ? params : {};
  const history = Array.isArray(source.__harnessRecovery) ? source.__harnessRecovery : [];
  return {
    ...source,
    __harnessRecovery: [...history, entry].slice(-maxEntries),
  };
}

function publicRecoveryParams(params) {
  if (!params || typeof params !== 'object') return {};
  const { __harnessRecovery, ...publicParams } = params;
  return publicParams;
}

module.exports = {
  EXECUTABLE_RECOVERY_ACTIONS,
  appendWorkflowRecoveryAudit,
  createRecoveryConfirmationStore,
  publicRecoveryParams,
  validateWorkflowRecoveryAction,
};

'use strict';

/**
 * helpers/history-assembly.js — BLOCK-95 B1 历史拼装权收归后端。
 *
 * 开关（PETRI_SERVER_HISTORY_ASSEMBLY）：2026-09-18 用户裁决翻默认开（feature-flags 单一真相，
 * 设置页可切换）；环境变量 =1/true 强制开、=0/false 强制关（kill-switch）。打开时，LLM 请求历史由
 * DB（copilot_messages）拼装，前端上报的 messages 只提供「本轮 user 原文」：
 *   - 历史轮次与 DB 完全同源（前端展示层本就 restore 自 DB；无错误轮次会话
 *     与旧链路的前端全量上报逐字一致——契约测试 block95-b1-history-assembly 锁定）；
 *   - 本轮 user 用前端原发 content 回填尾部（落库的 cleanContent 会剥开头
 *     引用行，原文才与旧链路发给 LLM 的内容一致）；
 *   - DB 异常时回退前端上报（不因拼装异常阻断会话）。
 * 这是服务端 compaction（B2）/ cache 感知（B3）的架构前提。
 */

const SERVER_HISTORY_ASSEMBLY_ENV = 'PETRI_SERVER_HISTORY_ASSEMBLY';

function isServerHistoryAssemblyEnabled(env) {
  // BLOCK-95 B1 灰度收编：解析权在 feature-flags（env 强制 > 设置页持久化 > 默认开）
  const { resolveFlag } = require('./feature-flags');
  return resolveFlag('server_history_assembly', env);
}

/**
 * @param {object} opts
 * @param {string|null} opts.conversationId 目标会话（空 = 无 DB 可拼，原样返回）
 * @param {Array<{role,content}>} opts.incomingMessages 前端上报（关开关时原样透传）
 * @param {object} opts.adb db.getAsyncDatabase() Promise facade
 * @returns {Promise<Array<{role,content}>>}
 */
async function assembleServerHistory({ conversationId, incomingMessages, adb }) {
  if (!Array.isArray(incomingMessages) || incomingMessages.length === 0) return incomingMessages;
  if (!conversationId || !adb) return incomingMessages;
  try {
    const rows = await adb.prepare(
      "SELECT role, content FROM copilot_messages WHERE conversation_id=? AND role IN ('user','assistant') ORDER BY ts ASC, rowid ASC"
    ).all(conversationId);
    if (!Array.isArray(rows) || rows.length === 0) return incomingMessages;
    const assembled = rows.map((r) => ({ role: r.role, content: String(r.content || '') }));
    // 本轮 user 三分支（健壮性：append 落库失败时也不丢本轮输入）：
    //   a) 尾部 user 与前端原文同文 → 已落库，不动；
    //   b) 尾部 user 为落库剥前缀版（cleanContent）→ 回填前端原发 content；
    //   c) 尾部非 user（本轮 append 失败）→ 追加原文。
    const incomingLastUser = [...incomingMessages].reverse().find((m) => m && m.role === 'user');
    if (incomingLastUser) {
      const original = String(incomingLastUser.content || '');
      const lastRow = assembled[assembled.length - 1];
      if (lastRow && lastRow.role === 'user') {
        if (lastRow.content !== original) {
          assembled[assembled.length - 1] = { role: 'user', content: original };
        }
      } else {
        assembled.push({ role: 'user', content: original });
      }
    }
    return assembled;
  } catch (e) {
    try { console.warn('[block95-b1] server history assembly failed, fallback to client messages:', e && e.message); } catch {}
    return incomingMessages;
  }
}

module.exports = {
  SERVER_HISTORY_ASSEMBLY_ENV,
  isServerHistoryAssemblyEnabled,
  assembleServerHistory,
};

/**
 * IP → 地区（admin 访客统计用）
 * 使用 ip-api.com 免费接口，带内存缓存；内网/本地 IP 不请求外网。
 */

const CACHE_TTL_MS = 7 * 24 * 60 * 60 * 1000;
const BATCH_SIZE = 100;
const FIELDS = 'status,message,country,regionName,city,isp,query';

/** @type {Map<string, { at: number, geo: object }>} */
const cache = new Map();

function isPrivateOrLocal(ip) {
  if (!ip || typeof ip !== 'string') return true;
  const s = ip.trim();
  if (s === '127.0.0.1' || s === '::1' || s.startsWith('fe80:')) return true;
  if (/^10\./.test(s)) return true;
  if (/^192\.168\./.test(s)) return true;
  if (/^172\.(1[6-9]|2\d|3[01])\./.test(s)) return true;
  if (/^100\.(6[4-9]|[7-9]\d|1[01]\d|12[0-7])\./.test(s)) return true; // CGNAT
  return false;
}

function formatLocation(geo) {
  if (!geo) return '-';
  if (geo.location) return geo.location;
  const parts = [geo.city, geo.region, geo.country].filter(Boolean);
  if (parts.length) return parts.join(' · ');
  if (geo.isp) return geo.isp;
  return '-';
}

function rowFromApi(item) {
  if (!item || item.status !== 'success') {
    return {
      country: null,
      region: null,
      city: null,
      isp: null,
      location: item?.message === 'private range' ? '内网' : '未知',
    };
  }
  const geo = {
    country: item.country || null,
    region: item.regionName || null,
    city: item.city || null,
    isp: item.isp || null,
    location: null,
  };
  geo.location = formatLocation(geo);
  return geo;
}

function getCached(ip) {
  const hit = cache.get(ip);
  if (!hit) return null;
  if (Date.now() - hit.at > CACHE_TTL_MS) {
    cache.delete(ip);
    return null;
  }
  return hit.geo;
}

function setCache(ip, geo) {
  cache.set(ip, { at: Date.now(), geo });
}

async function fetchBatch(ips) {
  if (!ips.length) return {};
  const url = `http://ip-api.com/batch?fields=${FIELDS}`;
  const body = ips.map((ip) => ({ query: ip }));
  const res = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
    signal: AbortSignal.timeout(15000),
  });
  if (!res.ok) throw new Error(`ip-api HTTP ${res.status}`);
  const data = await res.json();
  const out = {};
  if (!Array.isArray(data)) return out;
  for (let i = 0; i < ips.length; i++) {
    out[ips[i]] = rowFromApi(data[i]);
    setCache(ips[i], out[ips[i]]);
  }
  return out;
}

/**
 * @param {string[]} ips
 * @returns {Promise<Record<string, object>>}
 */
async function lookupIps(ips) {
  const unique = [...new Set(ips.filter((ip) => ip && !isPrivateOrLocal(ip)))];
  const result = {};

  for (const ip of ips) {
    if (!ip) continue;
    if (isPrivateOrLocal(ip)) {
      const geo = { country: null, region: null, city: null, isp: null, location: '内网' };
      result[ip] = geo;
      setCache(ip, geo);
    }
  }

  const needLookup = unique.filter((ip) => {
    const c = getCached(ip);
    if (c) {
      result[ip] = c;
      return false;
    }
    return true;
  });

  for (let i = 0; i < needLookup.length; i += BATCH_SIZE) {
    const chunk = needLookup.slice(i, i + BATCH_SIZE);
    try {
      const batch = await fetchBatch(chunk);
      Object.assign(result, batch);
    } catch (e) {
      console.warn('[ip-geo] batch lookup failed:', e.message);
      for (const ip of chunk) {
        result[ip] = { country: null, region: null, city: null, isp: null, location: '解析失败' };
      }
    }
    if (i + BATCH_SIZE < needLookup.length) {
      await new Promise((r) => setTimeout(r, 400));
    }
  }

  return result;
}

/**
 * @template T
 * @param {T[]} rows
 * @param {string} ipKey
 * @returns {Promise<(T & { geo: object, location: string })[]>}
 */
async function attachGeoToRows(rows, ipKey = 'ip') {
  const ips = rows.map((r) => r[ipKey]).filter(Boolean);
  const map = await lookupIps(ips);
  return rows.map((r) => {
    const ip = r[ipKey];
    const geo = map[ip] || { location: '-' };
    return {
      ...r,
      geo,
      location: geo.location || formatLocation(geo),
    };
  });
}

module.exports = {
  lookupIps,
  attachGeoToRows,
  formatLocation,
  isPrivateOrLocal,
};

/**
 * helpers/knowledge-ingest.js — BLOCK-69 P1 文本族摄取管道
 *
 * D2 文档状态机：uploaded → parsing → chunking → embedding → ready | failed(+error)
 * - 解析：knowledge-parsers 按扩展名路由（fail-closed）
 * - 分块：knowledge-space.chunkText（结构感知 + 尺寸上限）
 * - 嵌入：memory-vectors 通道批量编码（DashScope text-embedding-v3，batch≤10）
 * - 落库：chunks + FTS 行单事务写入，失败不落半索引（fail-closed，文档转 failed）
 * - 队列：进程内串行（P1 单机桌面场景，D8）
 *
 * Public API:
 *   createDocument({ name, buffer, size, mime }) → doc row（落原始文件 + 入队摄取）
 *   ingestDocument(docId, { embed } ) → doc row（状态机全程；embed 可注入供测试）
 *   reindexDocument(docId) → doc row（清旧块重跑管道）
 *   ingestQueueDepth()
 */

const fs = require('fs');
const path = require('path');
const { v4: uuidv4 } = require('uuid');
const ks = require('./knowledge-space');
const { parseDocument, checkSupported } = require('./knowledge-parsers');

const sqlite = require('../db').getDatabase();

const EMBED_BATCH_SIZE = 10;
const MAX_DOCUMENT_BYTES = 50 * 1024 * 1024; // P1 文本族 50MB 上限（原始大媒体文件属 P3/P4）
const MIN_CHUNK_FOR_EMBED = 1;

// 进程内串行摄取队列：promise 链即队列，reject 不断链
let _queue = Promise.resolve();
let _queueDepth = 0;

function enqueueIngest(docId, { embed } = {}) {
  _queueDepth += 1;
  _queue = _queue
    .then(() => ingestDocument(docId, { embed }))
    .catch((e) => {
      console.log('[knowledge-ingest] queue item failed:', docId, e && e.message);
    })
    .finally(() => {
      _queueDepth = Math.max(0, _queueDepth - 1);
    });
  return _queue;
}

function ingestQueueDepth() {
  return _queueDepth;
}

function safeDocFilename(originalName) {
  const basename = path.basename(String(originalName || '').normalize('NFKC'));
  const ext = path.extname(basename).toLowerCase();
  const stem = path.basename(basename, path.extname(basename))
    .replace(/[^\p{L}\p{N}._-]+/gu, '_')
    .replace(/^\.+/, '')
    .slice(0, 120);
  return `${stem || 'document'}${ext}`;
}

/**
 * 创建文档：写原始文件 + 建行（uploaded）+ 入队摄取。
 * autoIngest=false 仅供测试/迁移工具落行不排程。
 * 解析器不支持的扩展名在此 fail-closed（不建行不入队）。
 */
async function createDocument({ name, buffer, mime, autoIngest = true, spaceId }) {
  if (!name || !Buffer.isBuffer(buffer)) throw new Error('knowledge_document_fields_required');
  if (buffer.length > MAX_DOCUMENT_BYTES) throw new Error('knowledge_document_too_large');
  checkSupported(name);
  // BLOCK-99 G1 — 目标空间（缺省 ks_default；未知 fail-closed）
  const targetSpace = ks.resolveSpaceId(spaceId);
  const docId = `kdoc_${uuidv4().slice(0, 12)}`;
  const dir = ks.docDir(docId);
  fs.mkdirSync(dir, { recursive: true });
  const safeName = safeDocFilename(name);
  const rawPath = path.join(dir, safeName);
  fs.writeFileSync(rawPath, buffer);
  const ts = new Date().toISOString();
  sqlite
    .prepare(
      `INSERT INTO knowledge_documents (id, space_id, name, kind, mime, size, status, raw_path, created_at, updated_at)
       VALUES (?, ?, ?, 'text', ?, ?, 'uploaded', ?, ?, ?)`
    )
    .run(docId, targetSpace, safeName, mime || null, buffer.length, rawPath, ts, ts);
  if (autoIngest) enqueueIngest(docId);
  return ks.getDocument(docId);
}

/**
 * 摄取状态机全程。embed 可注入（测试）。任何一步失败 → failed(+error)，不落半索引。
 */
async function ingestDocument(docId, { embed } = {}) {
  const doc = ks.getDocument(docId);
  if (!doc) throw new Error('knowledge_document_not_found');

  try {
    // parsing：读原始文件 + 解析器路由（BLOCK-94 F2 起 PDF 等异步解析器，await 兼容同步解析器）
    ks.setDocumentStatus(docId, 'parsing');
    const rawPath = doc.raw_path || path.join(ks.docDir(docId), doc.name);
    const buffer = fs.readFileSync(rawPath);
    const parsed = await parseDocument(buffer, doc.name);
    if (parsed.kind && parsed.kind !== doc.kind) {
      sqlite.prepare('UPDATE knowledge_documents SET kind = ? WHERE id = ?').run(parsed.kind, docId);
    }

    // chunking：结构感知分块
    ks.setDocumentStatus(docId, 'chunking');
    const chunks = ks.chunkText(parsed.text);
    if (chunks.length === 0) {
      throw new Error('knowledge_chunk_empty（文档无有效文本内容）');
    }

    // embedding：批量编码；无 key / 失败 → failed（D7 不静默降级为无向量索引）
    ks.setDocumentStatus(docId, 'embedding');
    const embedFn = embed || ks.embedTexts;
    const texts = chunks.map((c) => c.text.slice(0, 1500));
    const vectors = new Array(chunks.length).fill(null);
    for (let i = 0; i < texts.length; i += EMBED_BATCH_SIZE) {
      const batch = texts.slice(i, i + EMBED_BATCH_SIZE);
      const vecs = await embedFn(batch, { kind: 'knowledge_ingest', docId });
      if (!Array.isArray(vecs)) {
        throw new Error('knowledge_embed_unavailable（嵌入模型不可用：请先在设置中配置 DashScope key）');
      }
      vecs.forEach((vec, j) => {
        if (vec) vectors[i + j] = vec;
      });
    }
    const embeddedCount = vectors.filter(Boolean).length;
    if (embeddedCount < Math.min(MIN_CHUNK_FOR_EMBED, chunks.length)) {
      throw new Error('knowledge_embed_failed（所有分块嵌入失败）');
    }

    // 落库：chunks + FTS 单事务（ready 才对外可见——searchKnowledge 只扫 ready 文档）
    const tx = sqlite.transaction(() => {
      // trigram FTS5 陷阱：对 UNINDEXED 列的 LIKE/GLOB 谓词会被 trigram-LIKE 优化劫持
      // 且错误恒返回空（SELECT/DELETE 皆然）——重建删除必须走等值 IN 子查询
      sqlite
        .prepare('DELETE FROM knowledge_chunks_fts WHERE chunk_id IN (SELECT id FROM knowledge_chunks WHERE doc_id = ?)')
        .run(docId);
      sqlite.prepare('DELETE FROM knowledge_chunks WHERE doc_id = ?').run(docId);
      const insertChunk = sqlite.prepare(
        `INSERT INTO knowledge_chunks (id, doc_id, space_id, seq, text, embedding, dim, model, created_at)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`
      );
      const insertFts = sqlite.prepare(
        'INSERT INTO knowledge_chunks_fts (chunk_id, text) VALUES (?, ?)'
      );
      const nowTs = new Date().toISOString();
      chunks.forEach((chunk, idx) => {
        const chunkId = `${docId}_c${chunk.seq}`;
        const vec = vectors[idx];
        insertChunk.run(
          chunkId,
          docId,
          doc.space_id, // BLOCK-99 G1 — 按文档归属空间落块（曾写死 ks.SPACE_ID 致跨空间块错标）
          chunk.seq,
          chunk.text,
          vec ? Buffer.from(vec.buffer, vec.byteOffset, vec.byteLength) : null,
          vec ? vec.length : null,
          vec ? ks.EMBEDDING_MODEL : null,
          nowTs
        );
        insertFts.run(chunkId, chunk.text);
      });
      sqlite
        .prepare('UPDATE knowledge_documents SET chunk_count = ?, updated_at = ? WHERE id = ?')
        .run(chunks.length, new Date().toISOString(), docId);
    });
    tx();
    return ks.setDocumentStatus(docId, 'ready');
  } catch (e) {
    const message = e && e.message ? e.message : String(e);
    console.log('[knowledge-ingest] failed:', docId, message);
    return ks.setDocumentStatus(docId, 'failed', { error: message });
  }
}

/** 重建索引：清旧块（含 FTS）后重跑管道。原始文件缺失 → failed。 */
async function reindexDocument(docId) {
  const doc = ks.getDocument(docId);
  if (!doc) throw new Error('knowledge_document_not_found');
  const rawPath = doc.raw_path || path.join(ks.docDir(docId), doc.name);
  if (!fs.existsSync(rawPath)) {
    return ks.setDocumentStatus(docId, 'failed', { error: 'knowledge_raw_file_missing（原始文件已不在，无法重建）' });
  }
  enqueueIngest(docId);
  return ks.getDocument(docId);
}

// ---- BLOCK-94 F1 可靠底盘：启动恢复 + 失败批量重试 ----

// 队列为进程内 promise 链：重启后 uploaded/parsing/chunking/embedding 中间态文档会永久卡住。
// 服务启动时（mountKnowledge）调用：中间态文档按 updated_at 升序（先来先摄）自动重排入队。
// 原始文件缺失的会在管道内诚实转 failed（knowledge_raw_file_missing / 读文件失败）。
// BLOCK-99 G6 — 恢复覆盖全部空间（曾写死 ks_default，多空间下 B 空间中间态文档重启即永久卡死）。
function recoverInterruptedIngest({ embed } = {}) {
  const rows = sqlite
    .prepare(
      `SELECT id FROM knowledge_documents
       WHERE status IN ('uploaded', 'parsing', 'chunking', 'embedding')
       ORDER BY updated_at ASC`
    )
    .all();
  for (const row of rows) enqueueIngest(row.id, { embed });
  if (rows.length > 0) {
    console.log(`[knowledge-ingest] boot recovery: requeued ${rows.length} interrupted document(s) across all spaces`);
  }
  return { requeued: rows.length, docIds: rows.map((r) => r.id), settled: _queue };
}

// failed 文档批量重试（含解析器就绪后的 PDF 等历史失败）。原始文件缺失的逐项诚实跳过。
// BLOCK-99 G6 — 重试同样覆盖全部空间（曾写死 ks_default，B 空间失败文档不可批量重试）。
function retryFailedDocuments({ embed } = {}) {
  const rows = sqlite
    .prepare(`SELECT id FROM knowledge_documents WHERE status = 'failed' ORDER BY updated_at ASC`)
    .all();
  const skipped = [];
  let requeued = 0;
  for (const row of rows) {
    const doc = ks.getDocument(row.id);
    const rawPath = doc ? doc.raw_path || path.join(ks.docDir(row.id), doc.name) : null;
    if (!rawPath || !fs.existsSync(rawPath)) {
      skipped.push({ id: row.id, reason: 'knowledge_raw_file_missing' });
      continue;
    }
    enqueueIngest(row.id, { embed });
    requeued += 1;
  }
  return { requeued, skipped, settled: _queue };
}

module.exports = {
  EMBED_BATCH_SIZE,
  MAX_DOCUMENT_BYTES,
  createDocument,
  ingestDocument,
  reindexDocument,
  enqueueIngest,
  ingestQueueDepth,
  recoverInterruptedIngest,
  retryFailedDocuments,
  safeDocFilename,
};

/**
 * helpers/knowledge-parsers.js — BLOCK-69 P1 文本族解析器注册表
 *
 * D2/D5：按扩展名路由的解析器注册表；P1 只收文本族（0 新依赖——全部 utf-8 文本直读）。
 * BLOCK-94 F2：PDF 经 pdfjs-dist legacy build 提取文本（依赖复用 UI-400 已裁决的 pdfjs-dist 4.10.38，
 * 见 BLOCK-94 plan §7.2 D2）；Office / 图像 / 音视频 / 数据库直读属 P4 线，未注册的扩展名 fail-closed 拒绝
 * （文档状态 failed + error，不静默当文本读）。
 *
 * 「设定特定解析工具」= 本注册表按扩展名 → 解析器映射；后续格式在此扩展。
 */

const path = require('path');

const IMAGE_EXTENSIONS = new Set(); // P4：图像经 dashscope-vision 描述化索引
const AUDIO_EXTENSIONS = new Set(); // P4：DashScope ASR

// BLOCK-94 F2：扫描件（无文本层）PDF 无 OCR 属 P4 线——提取为空按 knowledge_chunk_empty 诚实 failed
const PDF_EXTENSIONS = new Set(['.pdf']);

// BLOCK-94 F2：PDF 页数护栏（>500 页截断并在 note 诚实标注）
const PDF_MAX_PAGES = 500;

const TEXT_EXTENSIONS = new Set([
  '.txt', '.md', '.markdown', '.mdx', '.rst', '.log',
  '.csv', '.tsv', '.json', '.jsonl', '.yaml', '.yml', '.toml', '.ini', '.xml', '.html', '.htm',
  '.js', '.mjs', '.cjs', '.ts', '.tsx', '.jsx', '.py', '.r', '.rmd', '.ipynb',
  '.sh', '.bash', '.zsh', '.bat', '.ps1', '.sql', '.css', '.java', '.c', '.h', '.cpp', '.hpp',
  '.go', '.rs', '.rb', '.php', '.lua', '.pl', '.m', '.swift', '.kt', '.scala',
]);

// P4 明确登记但未实现：拒绝时给出诚实指引
const PLANNED_EXTENSIONS = new Set([
  '.docx', '.doc', '.xlsx', '.xls', '.pptx', '.ppt',
  '.png', '.jpg', '.jpeg', '.gif', '.webp', '.bmp', '.tiff',
  '.mp3', '.wav', '.m4a', '.flac', '.ogg', '.mp4', '.mov', '.avi', '.mkv',
  '.sqlite', '.db',
]);

/**
 * BLOCK-94 F2：PDF → 文本（pdfjs-dist legacy build，Node 侧动态 import）。
 * cmaps/standard_fonts 从包内目录提供（CJK 与非嵌入字体必需）。
 * 加密 PDF / 损坏 PDF：pdfjs 抛错 → 上层 fail-closed 诚实 failed。
 */
async function parsePdfBuffer(buffer) {
  const pdfjsRoot = path.dirname(require.resolve('pdfjs-dist/package.json'));
  const pdfjs = await import('pdfjs-dist/legacy/build/pdf.mjs');
  const doc = await pdfjs.getDocument({
    data: new Uint8Array(buffer),
    isEvalSupported: false,
    useSystemFonts: false,
    standardFontDataUrl: `file://${pdfjsRoot}/standard_fonts/`,
    cMapUrl: `file://${pdfjsRoot}/cmaps/`,
    cMapPacked: true,
  }).promise;
  const pageTexts = [];
  const pageCount = Math.min(doc.numPages, PDF_MAX_PAGES);
  for (let p = 1; p <= pageCount; p++) {
    const page = await doc.getPage(p);
    const content = await page.getTextContent();
    let text = '';
    for (const item of content.items) {
      if (typeof item.str !== 'string') continue;
      text += item.str;
      if (item.hasEOL) text += '\n';
      else if (item.str && !/\s$/.test(item.str)) text += ' ';
    }
    pageTexts.push(text.trim());
    page.cleanup();
  }
  const truncated = doc.numPages > PDF_MAX_PAGES;
  await doc.destroy();
  return {
    text: pageTexts.filter(Boolean).join('\n\n'),
    note: truncated ? `pdf:truncated_at_${PDF_MAX_PAGES}_pages` : undefined,
  };
}

function extOf(name) {
  const dot = String(name || '').lastIndexOf('.');
  return dot >= 0 ? String(name).slice(dot).toLowerCase() : '';
}

/**
 * 解析器注册表：扩展名 → { kind, parse }。
 * parse(buffer, { name }) → { text, kind, note? }；throw 即 fail-closed。
 * BLOCK-94 F2 起 parseDocument 为 async（PDF 解析器异步；文本解析器同步返回值兼容 await）。
 */
const PARSERS = [
  {
    kinds: ['.txt', '.log'],
    kind: 'text',
    parse: (buffer) => ({ text: buffer.toString('utf8') }),
  },
  {
    kinds: ['.md', '.markdown', '.mdx', '.rst'],
    kind: 'markdown',
    parse: (buffer) => ({ text: buffer.toString('utf8') }),
  },
  {
    kinds: ['.csv', '.tsv'],
    kind: 'tabular',
    parse: (buffer, { name }) => {
      const raw = buffer.toString('utf8');
      // 表格直读原文（表头+行）可被 FTS/向量双通道命中；不做结构化改写
      const lines = raw.split(/\r?\n/);
      return {
        text: raw,
        note: `tabular:${name || 'table'} (${lines.length} lines)`,
      };
    },
  },
  {
    kinds: ['.json', '.jsonl'],
    kind: 'json',
    parse: (buffer) => ({ text: buffer.toString('utf8') }),
  },
  {
    kinds: ['.yaml', '.yml', '.toml', '.ini', '.xml', '.html', '.htm', '.css', '.sql'],
    kind: 'structured-text',
    parse: (buffer) => ({ text: buffer.toString('utf8') }),
  },
  {
    kinds: ['.js', '.mjs', '.cjs', '.ts', '.tsx', '.jsx', '.py', '.r', '.rmd', '.ipynb',
      '.sh', '.bash', '.zsh', '.bat', '.ps1', '.java', '.c', '.h', '.cpp', '.hpp',
      '.go', '.rs', '.rb', '.php', '.lua', '.pl', '.m', '.swift', '.kt', '.scala'],
    kind: 'code',
    parse: (buffer, { name }) => ({ text: buffer.toString('utf8'), note: `code:${name || ''}` }),
  },
  {
    kinds: [...PDF_EXTENSIONS],
    kind: 'pdf',
    parse: (buffer) => parsePdfBuffer(buffer),
  },
];

/**
 * 按文件名路由解析器。未注册 → throw（fail-closed，绝不静默当文本读）。
 * @returns {Promise<{ text: string, kind: string, note?: string }>}
 */
async function parseDocument(buffer, name) {
  const ext = extOf(name);
  if (PLANNED_EXTENSIONS.has(ext)) {
    throw new Error(`knowledge_parser_planned_not_implemented:${ext}（该格式解析属 P4 线，本期未实现）`);
  }
  if (!TEXT_EXTENSIONS.has(ext) && !PDF_EXTENSIONS.has(ext)) {
    throw new Error(`knowledge_parser_unsupported:${ext || '无扩展名'}（P1 文本族 + PDF 之外）`);
  }
  for (const parser of PARSERS) {
    if (parser.kinds.includes(ext)) {
      const out = await parser.parse(buffer, { name });
      return { text: String(out.text || ''), kind: parser.kind, note: out.note };
    }
  }
  throw new Error(`knowledge_parser_missing:${ext}`);
}

function isSupportedExtension(name) {
  const ext = extOf(name);
  return (TEXT_EXTENSIONS.has(ext) || PDF_EXTENSIONS.has(ext)) && !PLANNED_EXTENSIONS.has(ext);
}

/** createDocument 入口检查：计划内未实现（P4 线）与完全不支持分别给出诚实错误。 */
function checkSupported(name) {
  const ext = extOf(name);
  if (PLANNED_EXTENSIONS.has(ext)) {
    throw new Error(`knowledge_parser_planned_not_implemented:${ext}（该格式解析属 P4 线，本期未实现）`);
  }
  if (!TEXT_EXTENSIONS.has(ext) && !PDF_EXTENSIONS.has(ext)) {
    throw new Error(`knowledge_parser_unsupported:${ext || '无扩展名'}（P1 文本族 + PDF 之外）`);
  }
}

module.exports = {
  TEXT_EXTENSIONS,
  PDF_EXTENSIONS,
  PDF_MAX_PAGES,
  PLANNED_EXTENSIONS,
  parseDocument,
  isSupportedExtension,
  checkSupported,
  extOf,
};

/**
 * helpers/knowledge-space.js — BLOCK-69 知识空间检索内核
 *
 * 第三数据域（独立于 memory_vectors 对话记忆域与项目工作区数据面）：
 * - knowledge_spaces / knowledge_documents / knowledge_chunks 由 migration 009 管理
 * - knowledge_chunks_fts：FTS5 trigram 全文虚表（关键词精确通道）
 * - 向量通道：Float32Array BLOB（编码沿用 memory-vectors 方案，独立建表不改其语义）
 *
 * 检索：双通道（向量 cosine 阈值 + FTS trigram，<3 字短词走 LIKE 兜底）→ RRF 融合。
 *
 * Public API:
 *   getSpace() / setSpaceEnabled(enabled)
 *   listDocuments() / getDocument(id)
 *   chunkText(text)
 *   searchKnowledge({ query, topK, embed })
 *   buildPromptBlock(hits, maxChars)
 *   deleteDocument(docId) / clearSpace()
 *   knowledgeRoot() — <LOCAL_DATA_DIR>/knowledge 原始文件根
 *   Constants: SPACE_ID, EMBEDDING_DIM, EMBEDDING_MODEL, VECTOR_THRESHOLD, INJECT_TOPK
 */

const fs = require('fs');
const os = require('os');
const path = require('path');
const dbMod = require('../db');
const sqlite = dbMod.getDatabase();

const SPACE_ID = 'ks_default';
const EMBEDDING_DIM = 1024;
const EMBEDDING_MODEL = 'text-embedding-v3';
// D4 轻按需：向量通道沿用 memory-vectors 0.55 阈值先例；注入上限 ≤3 块
const VECTOR_THRESHOLD = 0.55;
const VECTOR_TOPK = 6;
const FTS_TOPK = 6;
const INJECT_TOPK = 3;
const INJECT_MAX_CHARS = 1800;
// RRF 融合常数（标准 k=60）
const RRF_K = 60;
// D3 分块：结构感知 + 尺寸上限（~800 token ≈ 1600 字符混合中英），少量重叠
const CHUNK_MAX_CHARS = 1600;
const CHUNK_OVERLAP_CHARS = 120;
const CHUNK_MIN_CHARS = 40;
// 短于该长度的查询不做检索（省一次无效 embedding）
const QUERY_MIN_CHARS = 2;
// BLOCK-94 F6 规模化：向量通道为暴力全表扫描（JS cosine），chunk 数观测警戒阈值。
// 超阈值只告警不阻断（诚实观测）；sqlite-vec/ANN 引入与否属依赖裁决（plan §8 评估报告）。
const SCAN_WARN_THRESHOLD = 50000;

const DOC_STATUS = ['uploaded', 'parsing', 'chunking', 'embedding', 'ready', 'failed'];

function knowledgeRoot() {
  const root =
    process.env.PETRI_LOCAL_DATA_DIR ||
    path.join(os.homedir(), 'Documents', 'Petri-Local');
  return path.join(root, 'knowledge');
}

function docDir(docId) {
  return path.join(knowledgeRoot(), docId);
}

function now() {
  return new Date().toISOString();
}

// ---- 空间 ----

// BLOCK-99 G1 — 多空间参数化：以下函数 spaceId 缺省 = ks_default，存量调用零行为变更。
function getSpace(spaceId = SPACE_ID) {
  return sqlite.prepare('SELECT * FROM knowledge_spaces WHERE id = ?').get(spaceId) || null;
}

function setSpaceEnabled(enabled, spaceId = SPACE_ID) {
  sqlite
    .prepare('UPDATE knowledge_spaces SET enabled = ?, updated_at = ? WHERE id = ?')
    .run(enabled ? 1 : 0, now(), spaceId);
