 */

const dbMod = require('../db');
const sqlite = dbMod.getDatabase();
const {v4: uuidv4} = require('uuid');

// One-time table create (idempotent)
sqlite.exec(`
  CREATE TABLE IF NOT EXISTS memory_vectors (
