/**
 * Dynamic model context window resolution via OpenRouter /models API.
 *
 * Strategy (in getContextWindow priority order):
 *   1. Hard-coded known list  → instant sync return
 *   2. OpenRouter in-memory cache → sync LRU lookup
 *      - cache miss triggers async fetch + cache population
 *      - only fires when baseUrl contains openrouter.ai
 *   3. Unknown / other providers → 0 (frontend renders "—")
 *
 * Cache: in-process Map, TTL 1 hour, max 200 entries.
 * Designed to be called from hot request paths; async fetch is fire-and-forget
 * so first request for a new model returns 0 immediately while background fetch
 * populates the cache for subsequent requests.
 */
const { encoding_for_model: encForModel } = require('tiktoken');

// ---------------------------------------------------------------------------
// LRU cache
// ---------------------------------------------------------------------------
const MAX_ENTRIES = 200;
const TTL_MS = 60 * 60 * 1000; // 1 hour

const _cache = new Map(); // key → { value, ts }

function _cacheSet(key, value) {
  if (_cache.size >= MAX_ENTRIES) {
    // Evict oldest entry (first-inserted, not true LRU but sufficient)
    const firstKey = _cache.keys().next().value;
    _cache.delete(firstKey);
  }
  _cache.set(key, { value, ts: Date.now() });
}

function _cacheGet(key) {
  const entry = _cache.get(key);
  if (!entry) return null;
  if (Date.now() - entry.ts > TTL_MS) {
    _cache.delete(key);
    return null;
  }
  return entry.value;
}

// ---------------------------------------------------------------------------
// Hard-coded fallback (mirrors token-estimator.js known list for speed)
// ---------------------------------------------------------------------------
const HARDCODED = {
  'deepseek-chat': 64000,
  'deepseek-coder': 128000,
  'deepseek-v4-flash': 1_000_000,
  'deepseek-v4': 1_000_000,
  'gpt-4': 8192,
  'gpt-4-32k': 32768,
  'gpt-4-turbo': 128000,
  'gpt-4o': 128000,
  'gpt-3.5-turbo': 16385,
  'claude-3-5-sonnet-20241022': 200000,
  'claude-3-5-haiku-20241022': 200000,
};

// ---------------------------------------------------------------------------
// OpenRouter fetch
// ---------------------------------------------------------------------------

// BLOCK-102 P4 — 5s 超时 + in-flight 去重：缓存 miss 曾每条消息重发且失败永不
// 写缓存，慢网下挂起连接随聊天流量累积（UDP 端口耗尽事件的一类嫌疑面）。
const openRouterInflight = new Set();

/** Fire-and-forget fetch. Populates cache on success; silently ignores errors. */
function fetchOpenRouterModels({ baseUrl, apiKey }) {
  const url = `${baseUrl.replace(/\/$/, '')}/models`;
  const inflightKey = `${url}|${apiKey || ''}`;
  if (openRouterInflight.has(inflightKey)) return;
  openRouterInflight.add(inflightKey);
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 5000);
  const done = () => {
    clearTimeout(timer);
    openRouterInflight.delete(inflightKey);
  };
  fetch(url, {
    signal: controller.signal,
    headers: {
      Authorization: `Bearer ${apiKey || ''}`,
      'HTTP-Referer': 'https://petri.local',
      'X-Title': 'Petri Desktop',
    },
  })
    .then((res) => {
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      return res.json();
    })
    .then((data) => {
      if (!Array.isArray(data.data)) return;
      for (const model of data.data) {
        const ctx = model.context_length;
        if (ctx && typeof ctx === 'number') {
          _cacheSet(`openrouter:${model.id}`, ctx);
        }
      }
    })
    .catch(() => {
      // Network / auth errors: silently ignore, cache stays cold
    })
    .finally(done);
}

/** Async: returns cached value or kicks off background fetch and returns 0. */
async function getOpenRouterContextWindow(modelId, { baseUrl, apiKey }) {
  const key = `openrouter:${modelId}`;
  const cached = _cacheGet(key);
  if (cached !== null) return cached;

  // Fire-and-forget; return 0 for this request
  fetchOpenRouterModels({ baseUrl, apiKey });
  return 0;
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Resolve context window for a model.
 *
 * @param {string} modelName       - resolved model ID string
 * @param {string} providerName    - provider key e.g. 'openai', 'deepseek', 'anthropic'
 * @param {string} [baseUrl]       - API base URL from preset
 * @param {string} [apiKey]        - API key from preset
 * @returns {Promise<number>}       - context window in tokens, or 0 if unknown
 */
async function getContextWindow(modelName, providerName, baseUrl, apiKey) {
  if (!modelName) return 0;

  // 1. Hard-coded known list (sync, fastest path)
  const lower = modelName.toLowerCase();
  if (HARDCODED[lower] !== undefined) return HARDCODED[lower];

  // 2. OpenRouter: baseUrl check is sufficient (no extra API key guard needed)
  if (
    providerName === 'openai-compatible' &&
    baseUrl &&
    baseUrl.includes('openrouter.ai')
  ) {
    return await getOpenRouterContextWindow(modelName, { baseUrl, apiKey });
  }

  // 3. Everything else: unknown → 0 (frontend shows "—")
  return 0;
}

module.exports = {
  getContextWindow,
  // Exported for testing
  _cache,
  _cacheGet,
  _cacheSet,
};

'use strict';

/**
 * helpers/model-fallback-policy.js — BLOCK-56 P1 模型降级策略（纯函数）。
 *
 * 职责边界：只做分类与候选解析，不发起任何调用、不落任何状态。
 * 编排层（agent-fallback.js）消费这里的判定结果。
 *
 * 可降级类（plan §2.1）：
 *   - 超限（ContextWindowExceeded）——备用模型若 ctx 更大可吃下原任务
 *   - 服务端（ServerOverloaded / 5xx 持续 / 网络超时）
 *   - 配额（UsageLimitReached / 余额不足）
 * 不可降级类：
 *   - 参数错误（InvalidRequest，请求本身问题，换模型没用）
 *   - 鉴权/配置（no_api_key / provider_not_registered / 401 / 403）——应诚实暴露
 *   - 用户主动取消（aborted / cancelled）
 */

const DEGRADABLE_PATTERNS = [
  {
    category: 'context_window',
    re: /context (length|window)|maximum context|context_length_exceeded|context_window_exceeded|上下文(长度|窗口)(超限|过长|已满)|reduce the length/i,
  },
  {
    category: 'quota',
    re: /usage limit|usage_limit|insufficient[-_ ](balance|quota)|quota (exceeded|exhausted)|exceeded your (current )?quota|billing|arrears|余额不足|配额不足|账户.*欠费/i,
  },
  {
    category: 'server',
    re: /overloaded|server busy|model busy|server error|internal error|bad gateway|service unavailable|\b5\d\d\b|\b429\b|rate limit|rate_limit|too many requests|timeout|timed out|network|http_error|api_error|req_error|res_error|parse_error|fetch failed|econn|socket hang up/i,
  },
];

const NON_DEGRADABLE_RE = /invalid request|invalid_request|bad request|unauthorized|\b401\b|forbidden|\b403\b|no_api_key|api key|provider_not_registered|model_profile_not_found|provider_method_missing|aborted|cancelled|serialize_error|未登录|无权/i;

/**
 * 分类一次 provider 失败是否可降级。
 * @param {string|Error|null} errorText 终态错误（providerFailureReason / terminal.error）
 * @returns {{ degradable: boolean, category: 'context_window'|'quota'|'server'|null }}
 */
function classifyDegradableError(errorText) {
  const message = String((errorText && errorText.message) || errorText || '').trim();
  if (!message) return { degradable: false, category: null };
  // 超限/配额/服务端的特征词优先判定——InvalidRequest 包裹的 context length
  // （OpenAI 风格 400）仍属于可降级超限，所以先查可降级再查不可降级。
  for (const { category, re } of DEGRADABLE_PATTERNS) {
    if (re.test(message)) return { degradable: true, category };
  }
  if (NON_DEGRADABLE_RE.test(message)) return { degradable: false, category: null };
  return { degradable: false, category: null };
}

/**
 * 从 gateway 配置解析任务级备用 profile（首个有效候选，排除主 profile）。
 * @param {{fallbackEnabled: boolean, fallbackBindings: object, profiles: Array}} config normalizeModelConfig 输出
 * @param {string|null} primaryProfileId 失败任务使用的主 profile id
 * @param {string} [role] 模型角色，默认 agent
 * @returns {object|null} ModelProfile 或 null（未启用/无候选/候选均无效）
 */
function resolveTaskFallbackProfile(config, primaryProfileId, role = 'agent') {
  if (!config || config.fallbackEnabled !== true) return null;
  const bindings = (config.fallbackBindings && config.fallbackBindings[role]) || [];
  const profiles = Array.isArray(config.profiles) ? config.profiles : [];
  const byId = new Map(profiles.map((p) => [p && p.id, p]));
  for (const id of bindings) {
    if (!id || id === primaryProfileId) continue;
    const profile = byId.get(id);
    if (profile) return profile;
  }
  return null;
}

/**
 * 组装降级续跑消息：原请求历史 + 执行进度摘要 + 合成恢复指令。
 * 与 BLOCK-38 resume（routes/ai-agent/resume.js）同构，措辞换为降级语义；
 * 并要求模型在最终回答末尾附一句降级说明（plan §2.1 诚实纪律）。
 * @param {Array} originalMessages 原 task params.messages
 * @param {string} digest task_events 重建的执行进度摘要
 * @param {{reason?: string, label?: string}} [meta]
 * @returns {Array} 续跑 messages
 */
function buildFallbackResumeMessages(originalMessages, digest, meta = {}) {
  const reasonText = meta.reason ? `失败原因：${meta.reason}` : '失败原因：模型服务异常';
  const lines = [
    '=== 任务恢复（系统注入，非用户输入） ===',
    `上次执行因模型服务异常中断，系统已自动切换到备用模型「${meta.label || '备用模型'}」继续本任务。`,
    reasonText,
    '中断前的执行进度：',
    digest || '（无已记录的工具执行）',
    '请基于以上进度继续完成原任务；已完成的步骤不要重复执行。',
    meta.label
      ? `任务完成时，请在最终回答末尾用一句话注明：本次结果由备用模型「${meta.label}」降级生成。`
      : '任务完成时，请在最终回答末尾用一句话注明本次结果由备用模型降级生成。',
  ];
  return [
    ...(Array.isArray(originalMessages) ? originalMessages : []),
    { role: 'user', content: lines.join('\n') },
  ];
}

module.exports = {
  classifyDegradableError,
  resolveTaskFallbackProfile,
  buildFallbackResumeMessages,
};

/** Small task-oriented helpers on top of the Model Gateway. */

const { modelGateway } = require('./model-gateway');

function responseText(response) {
  if (!response || response.error) return '';
  const message = response.choices && response.choices[0] && response.choices[0].message;
  return String((message && message.content) || '').trim();
}

function parseJsonText(text) {
  const source = String(text || '').trim();
  if (!source) return null;
  try {
    return JSON.parse(source);
  } catch {}
  const objectMatch = source.match(/\{[\s\S]*\}/);
  if (objectMatch) {
    try {
      return JSON.parse(objectMatch[0]);
    } catch {}
  }
  const arrayMatch = source.match(/\[[\s\S]*\]/);
  if (arrayMatch) {
    try {
      return JSON.parse(arrayMatch[0]);
    } catch {}
  }
  return null;
}

async function callModelTask({
  role,
  messages,
  temperature,
  maxTokens,
  responseFormat,
  telemetry,
  profileId,
  parameters,
}) {
  const body = {
    ...(parameters || {}),
    messages: Array.isArray(messages) ? messages : [],
    stream: false,
  };
  if (temperature !== undefined) body.temperature = temperature;
  if (maxTokens !== undefined) body.max_tokens = maxTokens;
  if (responseFormat !== undefined) body.response_format = responseFormat;
  const response = await modelGateway.chat({ role, profileId, body, telemetry });
  return { response, text: responseText(response), error: response && response.error };
}

module.exports = { callModelTask, responseText, parseJsonText };

/**
 * Event-loop and request-timing probe for Result Studio performance work.
 *
 * The probe is off unless PETRI_PERF_PROBE=1. While off every exported function
 * is a no-op so production request handling keeps its current cost.
 *
 * Nothing here records result content, request bodies, query strings, absolute
 * paths or credentials: request timings are keyed by a route template only.
 */

const { monitorEventLoopDelay } = require('node:perf_hooks');

const RESOLUTION_MS = 10;
const MAX_ROUTES = 64;
const MAX_SAMPLES_PER_ROUTE = 256;
const MAX_BLOCKS = 128;

let histogram = null;
let routes = new Map();
let blocks = [];
let startedAtMs = 0;

function envEnabled() {
  return process.env.PETRI_PERF_PROBE === '1';
}

function isProbeActive() {
  return histogram !== null;
}

/** Start sampling. Idempotent; returns whether the probe is now active. */
function enableProbe({ force = false } = {}) {
  if (!force && !envEnabled()) return false;
  if (histogram) return true;
  histogram = monitorEventLoopDelay({ resolution: RESOLUTION_MS });
  histogram.enable();
  startedAtMs = Date.now();
  return true;
}

function disableProbe() {
  if (histogram) histogram.disable();
  histogram = null;
  routes = new Map();
  blocks = [];
  startedAtMs = 0;
}

function resetProbe() {
  if (!histogram) return false;
  histogram.reset();
  routes = new Map();
  blocks = [];
  startedAtMs = Date.now();
  return true;
}

/**
 * Collapse a concrete request path into a route template so job, project,
 * revision and file identifiers never reach the snapshot.
 */
function redactRoute(pathname) {
  if (typeof pathname !== 'string' || !pathname) return '/other';
  return pathname.split('/').map((segment) => {
    if (!segment) return segment;
    // Already an Express route param (e.g. :jobId): carries no identity and its
    // name is informative, so keep it rather than collapsing it to :id.
    if (segment.startsWith(':')) return segment;
    if (/^[a-z][a-z0-9-]*$/i.test(segment) && segment.length <= 24 && !/\d/.test(segment)) return segment;
    if (/\.[a-z0-9]+$/i.test(segment)) return `:file${segment.slice(segment.lastIndexOf('.'))}`;
    return ':id';
  }).join('/') || '/other';
}

function percentileOf(sorted, fraction) {
  if (!sorted.length) return null;
  const index = Math.min(sorted.length - 1, Math.max(0, Math.ceil(fraction * sorted.length) - 1));
  return Number(sorted[index].toFixed(3));
}

function summarize(samples) {
  const sorted = [...samples].sort((a, b) => a - b);
  return {
    count: sorted.length,
    p50: percentileOf(sorted, 0.5),
    p95: percentileOf(sorted, 0.95),
    max: sorted.length ? Number(sorted[sorted.length - 1].toFixed(3)) : null,
  };
}

/** Record one completed request. Called from an env-gated middleware only. */
function recordRequestTiming({ method, route, status, ttfbMs, totalMs }) {
  if (!histogram) return;
  const key = `${String(method || 'GET').toUpperCase()} ${redactRoute(route)}`;
  let entry = routes.get(key);
  if (!entry) {
    if (routes.size >= MAX_ROUTES) return;
    entry = { route: key, count: 0, statuses: {}, ttfb: [], total: [] };
    routes.set(key, entry);
  }
  entry.count += 1;
  const statusKey = String(status || 0);
  entry.statuses[statusKey] = (entry.statuses[statusKey] || 0) + 1;
  if (Number.isFinite(ttfbMs) && entry.ttfb.length < MAX_SAMPLES_PER_ROUTE) entry.ttfb.push(ttfbMs);
  if (Number.isFinite(totalMs) && entry.total.length < MAX_SAMPLES_PER_ROUTE) entry.total.push(totalMs);
}

/** Record a discrete stall observed by the tick monitor. */
function observeBlock(lagMs) {
  if (!histogram || !Number.isFinite(lagMs) || lagMs <= 0) return;
  if (blocks.length >= MAX_BLOCKS) blocks.shift();
  blocks.push({ lagMs: Number(lagMs.toFixed(1)), atMs: Date.now() - startedAtMs });
}

function snapshotProbe() {
  if (!histogram) return { enabled: false, eventLoop: null, requests: [], blocks: [] };
  // An empty histogram reports sentinel values (min is int64 max, mean is NaN)
  // rather than throwing, so report nothing instead of a fabricated sample.
  const empty = histogram.count === 0;
  const toMs = (ns) => (!empty && Number.isFinite(ns) ? Number((ns / 1e6).toFixed(3)) : null);
  return {
    enabled: true,
    windowMs: Date.now() - startedAtMs,
    eventLoop: {
      resolutionMs: RESOLUTION_MS,
      samples: histogram.count,
      minMs: toMs(histogram.min),
      meanMs: toMs(histogram.mean),
      p50Ms: toMs(histogram.percentile(50)),
      p95Ms: toMs(histogram.percentile(95)),
      p99Ms: toMs(histogram.percentile(99)),
      maxMs: toMs(histogram.max),
    },
    requests: [...routes.values()]
      .map((entry) => ({
        route: entry.route,
        count: entry.count,
        statuses: entry.statuses,
        ttfbMs: summarize(entry.ttfb),
        totalMs: summarize(entry.total),
      }))
      .sort((a, b) => (b.totalMs.max || 0) - (a.totalMs.max || 0)),
    blocks: [...blocks],
  };
}

module.exports = {
  RESOLUTION_MS,
  envEnabled,
  isProbeActive,
  enableProbe,
  disableProbe,
  resetProbe,
  redactRoute,
  recordRequestTiming,
  observeBlock,
  snapshotProbe,
};

/**
 * helpers/permissions.js — MODULE_PERMS_v1
 *
 * Per-user feature-module authorization. Replaces the old "invite code" gate
 * with admin-controlled per-user module access.
 *
 * Modules (granularity 1 — module level):
 *   - docs        教程/文档（公开，默认开）
 *   - single-cell 单细胞云平台（默认开，有 quota/次数兜底）
 *   - tools       在线分析工具 + FigCode 在线绘图（默认开）
 *   - copilot     AI 组学实践（DeepSeek，烧钱 → 默认关，管理员手动开）
 *
 * Storage: users.permissions is a JSON string (or NULL = use defaults).
 *   e.g. {"copilot": true, "tools": false}
 *   Only keys present override the default; missing keys fall back to DEFAULT_PERMS.
 *
 * Design notes:
 *   - Permissions are read from the DB on each gated request (NOT baked into the
 *     JWT) so an admin grant/revoke takes effect without forcing re-login.
 *   - admin role bypasses all gates.
 *   - Reserved field `tools_only` (array of toolIds) is parsed but not yet
 *     enforced — placeholder for future granularity-2 (per-tool) without a
 *     schema change.
 */

const dbMod = require('../db');

const MODULE_KEYS = [
  'docs',
  'blog',
  'figcode',
  'tools',
  'skills',
  'single-cell',
  'spatial',
  'copilot',
];

// Default module access for users whose permissions column is NULL or omits a key.
// Decision (2026-05-31, author): copilot 改为**默认开** —— 所有用户注册后即可用 AI 组学实践。
// 教程/博客/FigCode 仍对所有用户和游客完全公开（PUBLIC_MODULES）；
// 工具/Skills/单细胞/空间组学 默认关，由管理员按用户（未来按等级）放开。
const DEFAULT_PERMS = {
  docs: true, // 教程（公开）
  blog: true, // 博客（公开）
  figcode: true, // FigCode 绘图代码集（公开浏览/复制）
  tools: false, // 在线分析工具
  skills: false, // Skills 库
  'single-cell': false, // 单细胞云平台
  spatial: false, // 空间组学云平台
  copilot: true, // AI 组学实践（默认开放给所有登录用户）
};

// User-facing 403 / guard messages per module.
const MODULE_MSG = {
  docs: '该教程暂未对你的账号开放，如需查看请联系管理员。',
  blog: '博客暂未对你的账号开放，如需查看请联系管理员。',
  figcode: 'FigCode 暂未对你的账号开放，如需使用请联系管理员。',
  tools: '在线分析工具暂未对你的账号开放，如需使用请联系管理员。',
  skills: 'Skills 库暂未对你的账号开放，如需查看请联系管理员。',
  'single-cell': '单细胞云平台暂未对你的账号开放，如需使用请联系管理员。',
  spatial: '空间组学云平台暂未对你的账号开放，如需使用请联系管理员。',
  copilot: 'AI 组学实践功能暂未对你的账号开放，如需使用请联系管理员。',
};

function _parsePerms(userRow) {
  if (!userRow || !userRow.permissions) return {};
  try {
    const obj = JSON.parse(userRow.permissions);
    return obj && typeof obj === 'object' ? obj : {};
  } catch {
    return {};
  }
}

/**
 * Does this user (DB row) have access to a module?
 * admin → always true. Otherwise: explicit permission wins, else DEFAULT_PERMS.
 */
function can(userRow, moduleKey) {
  if (!userRow) return false;
  if (userRow.role === 'admin') return true;
  const perms = _parsePerms(userRow);
  if (Object.prototype.hasOwnProperty.call(perms, moduleKey)) return !!perms[moduleKey];
  return DEFAULT_PERMS[moduleKey] === true;
}

/** Resolve the full effective permission map for a user row (for /auth/me + admin UI). */
function effectivePermissions(userRow) {
  const out = {};
  for (const k of MODULE_KEYS) out[k] = can(userRow, k);
  return out;
}

/**
 * Normalize a permissions input (from admin UI) into a JSON string for storage,
 * or null to reset to defaults. Accepts an object, a JSON string, or null.
 */
function normalizePermissionsForStore(input) {
  if (input === null || input === undefined) return null;
  let obj = input;
  if (typeof input === 'string') {
    try {
      obj = JSON.parse(input);
    } catch {
      return null;
    }
  }
  if (!obj || typeof obj !== 'object') return null;
  const clean = {};
  for (const k of MODULE_KEYS) {
    if (Object.prototype.hasOwnProperty.call(obj, k)) clean[k] = !!obj[k];
  }
  // Preserve reserved per-tool whitelist if provided (granularity-2 placeholder).
  if (Array.isArray(obj.tools_only))
    clean.tools_only = obj.tools_only.filter((x) => typeof x === 'string');
  return Object.keys(clean).length ? JSON.stringify(clean) : null;
}

function _userIdOf(req) {
  return (req.user && (req.user.id || req.user.userId)) || null;
}

/** Core gate: look up the live DB row and enforce module access. */
function _enforce(moduleKeys, req, res, next) {
  // admin (role or legacy X-API-Token) bypasses everything.
  if (req.user && req.user.role === 'admin') return next();
  const keys = Array.isArray(moduleKeys) ? moduleKeys : [moduleKeys];
  const primary = keys[0];
  const uid = _userIdOf(req);
  if (!uid) {
    let guestOk = false;
    try {
      const gp = require('./guest-permissions');
      guestOk = keys.some((k) => gp.canGuest(k));
    } catch {
      /* ignore */
    }
    if (guestOk) return next();
    return res.status(403).json({
      status: 'error',
      error: 'module_forbidden',
      module: primary,
      message: '该功能暂未对游客开放，请登录或联系管理员。',
    });
  }
  let row = null;
  try {
    row = dbMod.getUserById(uid);
  } catch {
    /* fall through */
  }
  if (!row) return res.status(401).json({ status: 'error', error: '未登录' });
  if (keys.some((k) => can(row, k))) return next();
  return res.status(403).json({
    status: 'error',
    error: 'module_forbidden',
    module: primary,
    message: MODULE_MSG[primary] || '该功能暂未对你的账号开放。',
  });
}

/**
 * Single centralized gate middleware. Mount once after auth, before routes.
 * Maps request paths/methods to the module they belong to, then enforces.
 *
 * NOTE on coverage (static-site architecture):
 *   - Backend can only gate API-backed operations. Static content modules
 *     (docs/blog/figcode/skills) have no server route to intercept — those are
 *     guarded on the frontend (nav hide + RouteGuard). This gate covers the
 *     cost-/data-sensitive API surface: copilot / tools / single-cell / spatial.
 *   - /api/data is the shared CRUD layer for BOTH single-cell and spatial
 *     (distinguished by project.modality), so it accepts either permission.
 *   - Spatial compute runs locally inside petri-server（BLOCK-30 P1 前在独立 py-server，/api/py/*）,
 *     covered by this petri-server gate; add an equivalent check there when
 *     spatial task dispatch goes live (currently placeholder).
 */
function moduleGate(req, res, next) {
  const p = req.path;
  const m = req.method;

  const runGate = (moduleKeys) => {
    _enforce(moduleKeys, req, res, next);
  };

  // --- copilot: all /api/ai/* except health + admin ---
  if (p.startsWith('/api/ai')) {
    if (p === '/api/ai/health') return next();
    if (p.startsWith('/api/ai/admin')) return next();
    return runGate('copilot');
  }

  // --- online tool job submission → tools ---
  if (m === 'POST' && p === '/api/tools/run') {
    return runGate('tools');
  }

  // --- raw R execution (/api/run): shared by FigCode 在线绘图 + r-playground +
  //     single-cell replot. Although the FigCode *page* is public, actually
  //     RUNNING R code is a compute cost → require a compute-capable module.
  //     (Guests / view-only users can browse + copy FigCode code, just not run.)
  if (m === 'POST' && p === '/api/run') {
    return runGate(['tools', 'single-cell', 'spatial']);
  }

  // --- single-cell / spatial: shared data writes (projects/datasets/analyses/...) ---
  if (p.startsWith('/api/data/') && (m === 'POST' || m === 'PUT' || m === 'DELETE')) {
    return runGate(['single-cell', 'spatial']);
  }

  return next();
}

/** True if this request is subject to moduleGate (guest or logged-in perms). */
function routeRequiresModuleGate(req) {
  const p = req.path;
  const m = req.method;
  if (p.startsWith('/api/ai')) {
    if (p === '/api/ai/health') return false;
    if (p.startsWith('/api/ai/admin')) return false;
    return true;
  }
  if (m === 'POST' && p === '/api/tools/run') return true;
  if (m === 'POST' && p === '/api/run') return true;
  if (p.startsWith('/api/data/') && (m === 'POST' || m === 'PUT' || m === 'DELETE')) return true;
  return false;
}

module.exports = {
  MODULE_KEYS,
  DEFAULT_PERMS,
  can,
  effectivePermissions,
  normalizePermissionsForStore,
  moduleGate,
  routeRequiresModuleGate,
};

