/**
 * BLOCK-57 — 远程作业编排器（设计评审 D1/D4/D5/D7）
 *
 * 职责（P5 拆除后）：agent 部署（ensureAgent，sha256 钉扎幂等重传）+
 * 语言运行时解析（resolveRuntime，节点 probe 事实）。作业机制已由
 * ssh-direct-runner（BLOCK-76 直跑链）取代。
 *
 * 状态真相在节点侧文件；本模块只做观察与转述，绝不因传输失败改写作业终态。
 */

const {
  PETRI_AGENT_SH,
  AGENT_BIN,
  AGENT_ROOT,
  agentVersionHash,
} = require('./node-agent');
const {
  runSshOp,
} = require('./ssh-transport');

const AGENT_SCRIPT_HASH = agentVersionHash();
const LANGS = ['r', 'python'];
const TRANSPORT_RETRY_ATTEMPTS = 3;
const TRANSPORT_RETRY_DELAY_MS = 1200;

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

/**
 * 可重试传输错误（transport.network / transport.timeout / transport.unknown）
 * 的小步退避重试——本地代理/网络瞬态不应放大成操作失败；非重试类原样抛回。
 */
async function runSshOpRetry(params) {
  let last = null;
  for (let attempt = 1; attempt <= TRANSPORT_RETRY_ATTEMPTS; attempt += 1) {
    last = await runSshOp(params);
    if (last.classified.kind === 'ok' || last.classified.retryable !== true) return last;
    if (attempt < TRANSPORT_RETRY_ATTEMPTS) await sleep(TRANSPORT_RETRY_DELAY_MS * attempt);
  }
  return last;
}

function createRemoteJobRunner() {
  /** agent 脚本部署：hash 不一致即重传（幂等）。 */
  async function ensureAgent({ alias }) {
    const remoteHashCmd = `sha256sum "${AGENT_BIN}" 2>/dev/null | cut -d' ' -f1`;
    const current = await runSshOpRetry({ alias, remoteCommand: remoteHashCmd, timeoutMs: 20000 });
    if (current.classified.kind !== 'ok') {
      return { ok: false, error: current.classified };
    }
    if (current.stdout.trim().startsWith(AGENT_SCRIPT_HASH)) {
      return { ok: true, deployed: false };
    }
    const remoteCmd = `mkdir -p "${AGENT_ROOT}/bin" && cat > "${AGENT_BIN}.tmp" && mv "${AGENT_BIN}.tmp" "${AGENT_BIN}" && chmod +x "${AGENT_BIN}"`;
    const child = require('child_process').spawn(
      'ssh',
      [
        '-o', 'BatchMode=yes',
        '-o', 'ConnectTimeout=10',
        '--', alias, remoteCmd,
      ],
      { stdio: ['pipe', 'ignore', 'pipe'] }
    );
    const result = await new Promise((resolve) => {
      let stderr = '';
      child.stderr.on('data', (c) => { stderr += c; });
      const timer = setTimeout(() => child.kill('SIGKILL'), 30000);
      timer.unref?.();
      child.stdin.on('error', () => {});
      child.stdin.end(PETRI_AGENT_SH);
      child.on('close', (code) => {
        clearTimeout(timer);
        if (code === 0) return resolve({ ok: true, deployed: true });
        resolve({ ok: false, error: { kind: 'transport.deploy_failed', retryable: true, detail: stderr.trim().split('\n').pop() || `exit=${code}` } });
      });
      child.on('error', (error) => {
        clearTimeout(timer);
        resolve({ ok: false, error: { kind: 'transport.network', retryable: true, detail: error.message } });
      });
    });
    return result;
  }

  /**
   * 从 probe 信息解析语言运行时；缺失即返回 ready:false（诚实失败，不猜测）。
   */
  function resolveRuntime(probeInfo, lang) {
    const key = lang === 'r' ? 'r' : 'python';
    const bin = probeInfo && probeInfo[key];
    const versionKey = lang === 'r' ? 'rversion' : 'pythonversion';
    const version = probeInfo && probeInfo[versionKey] || null;
    if (!bin || bin === 'missing' || /[\s\r\n]/.test(bin)) {
      return { ready: false, runtimeBin: null, version: null, reason: `节点缺少 ${lang === 'r' ? 'R (Rscript)' : 'Python3'} 运行时` };
    }
    return { ready: true, runtimeBin: bin, version, reason: null };
  }

  /**
   * 提交：上传 bundle → agent start → 轮询到 active 确认。
   * bundle = 本地 jobDir 全量（排除 output/）——脚本/params/共享 helper/上传输入。
   */
  // BLOCK-76 P5 — BLOCK-57 作业机制（submit/poll/stream/cancel/manifest/pullOutputs）
  // 已拆除：SSH 直跑链（ssh-direct-runner）取代作业上传/拉回；本文件仅保留
  // agent 部署（ensureAgent）与语言运行时解析（resolveRuntime）。
  return {
    ensureAgent,
    resolveRuntime,
    LANGS,
  };
}

module.exports = { createRemoteJobRunner, AGENT_SCRIPT_HASH };

'use strict';

/**
 * BLOCK-77 P2 — 驻留任务回访循环 + 交接班摘要（R2/R3/R6）。
 *
 * 回访（仅软件运行期，默认 60s）：对全部项目 status==='running' 的意图卡做
 *   ① 进程存活（ssh: gateway processAlive / local: process.kill(pid,0)）
 *   ② 退出标记（.exit → 退出码）
 *   ③ 日志增长（连续 stall 判「疑似卡死」，只提醒不处置）
 * 四态收敛：completed / failed（进程死+.exit）/ exited（死但退出码未知）/ 疑似卡死提醒。
 * 不自动重启失败任务（R5：kill/重跑必须用户确认）。
 *
 * 交接班（R6 双通道）：
 *   A. 后端启动首个回访 tick → 每项目 running 卡 >0 → notify.custom 交接班提醒；
 *   B. agent 会话注入 → residentHandoverDigest(projectId) 供 agent-runner 拼 systemPrompt。
 */

const fs = require('fs');
const path = require('path');
const { resolveWorkspaceBackend, safeRemoteJoin } = require('../workspace-gateway');

const DEFAULT_INTERVAL_MS = 60 * 1000;
const DEAD_TICKS_TO_FAIL = 2;
const STALL_TICKS_TO_NOTIFY = 3;

function residentDirAbs(project) {
  const resolved = resolveWorkspaceBackend(project);
  if (resolved.error || !resolved.backend) return null;
  const root = resolved.root;
  const dir = safeRemoteJoin(root, '.petri/resident');
  if (!dir) return null;
  return { backend: resolved.backend, root, dir, kind: resolved.backend.kind };
}

/** 列出项目全部意图卡（损坏单卡跳过）。 */
async function listCards(ws) {
  let entries = [];
  try {
    entries = await ws.backend.list(ws.dir);
  } catch {
    return [];
  }
  const cards = [];
  for (const entry of entries.filter((x) => x.type === 'file' && x.name.endsWith('.json'))) {
    try {
      const buf = await ws.backend.read(`${ws.dir}/${entry.name}`);
      cards.push(JSON.parse(buf.toString('utf8')));
    } catch { /* 单卡损坏跳过 */ }
  }
  return cards;
}

function localAlive(pid) {
  try { process.kill(pid, 0); return true; } catch { return false; }
}

function localReadFile(abs) {
  try { return fs.readFileSync(abs); } catch { return null; }
}

/** 单卡回访：返回 {transition, note} — transition ∈ 'completed'|'failed'|null。 */
async function revisitCard(ws, project, card, state, notify) {
  if (!card.backingProcess || !Number.isFinite(card.backingProcess.pid)) {
    return { transition: null };
  }
  const pid = card.backingProcess.pid;
  const st = state.get(card.taskId) || { deadTicks: 0, stallTicks: 0, lastLogSize: null, notifiedStall: false };
  state.set(card.taskId, st);

  // ① 存活
  let alive;
  if (ws.kind === 'ssh') {
    try {
      alive = (await ws.backend.processAlive(pid)).alive === true;
    } catch {
      return { transition: null, unknown: true }; // 传输失败 ≠ 作业失败（跳过本轮）
    }
  } else {
    alive = localAlive(pid);
  }

  // ② 退出标记（start 时包装命令写入）
  let exitBuf = null;
  const exitPath = ws.kind === 'ssh'
    ? `${ws.dir}/${card.taskId}.exit`
    : path.join(ws.root, '.petri', 'resident', `${card.taskId}.exit`);
  if (ws.kind === 'ssh') {
    try { exitBuf = await ws.backend.read(exitPath); } catch { exitBuf = null; }
  } else {
    exitBuf = localReadFile(exitPath);
  }

  if (!alive && !exitBuf) {
    st.deadTicks += 1;
    if (st.deadTicks >= DEAD_TICKS_TO_FAIL) {
      // 进程死且无退出标记（包装命令未跑完即亡/被外部 kill）——诚实记 failed
      await writeCardStatus(ws, project, card, 'failed', `进程 ${pid} 已退出且无退出标记`);
      notify.custom({
        title: `⚠️ 驻留任务异常结束：${card.intent.slice(0, 40)}`,
        template: 'orange',
        dedupeKey: `resident_failed_${card.taskId}`,
        lines: [`项目：${project.name}`, `taskId：${card.taskId}`, '进程已退出且无退出标记，详情请查看 .petri/resident/ 意图卡与日志。'],
      });
      return { transition: 'failed' };
    }
    return { transition: null, retryLater: true };
  }

  // 有退出标记 → 终态
  if (exitBuf) {
    const code = parseInt(String(exitBuf).trim(), 10);
    const exitCode = Number.isFinite(code) ? code : null;
    if (exitCode === 0) {
      await writeCardStatus(ws, project, card, 'completed', `退出码 0`);
      notify.custom({
        title: `✅ 驻留任务完成：${card.intent.slice(0, 40)}`,
        template: 'blue',
        dedupeKey: `resident_done_${card.taskId}`,
        lines: [`项目：${project.name}`, `taskId：${card.taskId}`, '意图卡与产物已在项目 .petri/resident/ 与输出目录。'],
      });
      return { transition: 'completed', exitCode: 0 };
    }
    await writeCardStatus(ws, project, card, 'failed', `退出码 ${exitCode}`);
    notify.custom({
      title: `❌ 驻留任务失败：${card.intent.slice(0, 40)}`,
      template: 'orange',
      dedupeKey: `resident_failed_${card.taskId}`,
      lines: [`项目：${project.name}`, `taskId：${card.taskId}`, `退出码 ${exitCode}（不自动重启；处置预案见意图卡 failure_handling）`],
    });
    return { transition: 'failed', exitCode };
  }

  // 存活但无退出标记 = 仍在运行 → ③ 日志增长检查（卡死提醒，只提醒不处置）
  let logSize = null;
  const logPath = ws.kind === 'ssh'
    ? `${ws.dir}/${card.taskId}.log`
    : path.join(ws.root, '.petri', 'resident', `${card.taskId}.log`);
  if (ws.kind === 'ssh') {
    try { logSize = Number((await ws.backend.stat(logPath)).size || 0); } catch { logSize = null; }
  } else {
    try { logSize = fs.statSync(logPath).size; } catch { logSize = null; }
  }
  if (logSize !== null && st.lastLogSize !== null && logSize === st.lastLogSize) {
    st.stallTicks += 1;
    if (st.stallTicks >= STALL_TICKS_TO_NOTIFY && !st.notifiedStall) {
      st.notifiedStall = true;
      notify.custom({
        title: `🐌 驻留任务疑似卡死：${card.intent.slice(0, 40)}`,
        template: 'orange',
        dedupeKey: `resident_stall_${card.taskId}`,
        lines: [`项目：${project.name}`, `taskId：${card.taskId}`, `日志 ${STALL_TICKS_TO_NOTIFY} 轮无增长（回访只提醒，不自动处置）。`],
      });
    }
  } else {
    st.stallTicks = 0;
    st.notifiedStall = false;
  }
  st.lastLogSize = logSize;
  return { transition: null };
}

async function writeCardStatus(ws, project, card, status, note) {
  card.status = status;
  card.updatedAt = new Date().toISOString();
  card.lastCheckNote = String(note || '');
  const cardPath = ws.kind === 'ssh'
    ? `${ws.dir}/${card.taskId}.json`
    : path.join(ws.root, '.petri', 'resident', `${card.taskId}.json`);
  try {
    if (ws.kind === 'ssh') {
      await ws.backend.write(cardPath, Buffer.from(JSON.stringify(card, null, 2), 'utf8'));
    } else {
      fs.writeFileSync(cardPath, JSON.stringify(card, null, 2), 'utf8');
    }
  } catch { /* 状态文件写失败不影响通知 */ }
}

/** 交接班摘要（双通道 B）：agent 会话注入用文本；无 running 卡返回 null。 */
async function residentHandoverDigest(project) {
  const ws = residentDirAbs(project);
  if (!ws) return null;
  const cards = await listCards(ws);
  const running = cards.filter((c) => c.status === 'running');
  if (!running.length) return null;
  const lines = running.map((c) => `- [${c.taskId}] ${String(c.intent || '').slice(0, 80)}（日志：${c.backingProcess ? c.backingProcess.logPath : '未知'}；可用 resident_task_read 读卡）`);
  return `本项目存在 ${running.length} 个驻留任务（跨会话挂机运行中）：\n${lines.join('\n')}\n可用 resident_task_list / resident_task_read 读取详情；完成后请主动向用户汇报核对结果。`;
}

/** 交接班摘要（双通道 A）：后端启动首个 tick 的应用内提醒（notify.custom）。 */
function startResidentRevisitLoop({ dbModule, notify, intervalMs } = {}) {
  const interval = Number(intervalMs) || Number(process.env.PETRI_RESIDENT_INTERVAL_MS) || DEFAULT_INTERVAL_MS;
  let handoverNotified = false;
  let running = false;
  const stateByProject = new Map(); // projectId → Map(taskId → tick state)

  const tick = async () => {
    if (running) return;
    running = true;
    try {
      const db = dbModule.getAsyncDatabase();
      const projects = await db.prepare('SELECT id, name, workspace_kind, ssh_host, remote_path, workspace_path FROM projects').all();
      for (const project of projects) {
        const ws = residentDirAbs(project);
        if (!ws) continue;
        const cards = await listCards(ws);
        const runningCards = cards.filter((c) => c.status === 'running');
        if (!runningCards.length) continue;

        if (!handoverNotified) {
          notify.custom({
            title: `📋 交接班：${project.name} 有 ${runningCards.length} 个驻留任务进行中`,
            template: 'blue',
            dedupeKey: `resident_handover_${project.id}`,
            lines: runningCards.map((c) => `- ${String(c.intent || c.taskId).slice(0, 60)}`),
          });
        }

        const state = stateByProject.get(project.id) || new Map();
        stateByProject.set(project.id, state);
        for (const card of runningCards) {
          try {
            await revisitCard(ws, project, card, state, notify);
          } catch { /* 单卡异常不拖垮整轮 */ }
        }
      }
      handoverNotified = true;
    } catch { /* 整轮失败下轮重试 */ } finally {
      running = false;
    }
  };

  const timer = setInterval(() => { void tick(); }, interval);
  if (typeof timer.unref === 'function') timer.unref();
  void tick(); // 启动即首轮回访（含交接班提醒）
  return { stop: () => clearInterval(timer), tick };
}

/** 交接班摘要（按 projectId 查项目行后取 running 卡摘要，供 agent 会话注入）。 */
async function residentHandoverDigestByProjectId(dbModule, projectId) {
  try {
    const row = dbModule.getAsyncDatabase()
      .prepare('SELECT id, name, workspace_kind, ssh_host, remote_path, workspace_path FROM projects WHERE id = ?')
      .get(projectId);
    if (!row) return null;
    return await residentHandoverDigest(row);
  } catch {
    return null;
  }
}

module.exports = {
  startResidentRevisitLoop,
  residentHandoverDigest,
  residentHandoverDigestByProjectId,
  residentHandoverDigest,
  listCards,
  residentDirAbs,
  DEFAULT_INTERVAL_MS,
};

/**
 * BLOCK-67 加映（D1.1 性能优化）— SSH 单连接多路复用（Windows ControlMaster 替代）。
 *
 * Windows OpenSSH 不支持 ControlMaster，且 spawn ssh.exe 每次都要完整握手 +
 * 进程创建（实测每操作 ~1.1s）。本模块对每个 alias 维持**一条**长连接：
 *   ssh <alias> 'bash "$AGENT_BIN" __mux'
 * __mux 循环从 stdin 逐行读取 base64(完整 agent 命令)，执行后回送
 *   R \t <exit> \t <base64 stdout>
 * 每操作成本从 ~1.1s 降到 ~1 RTT。
 *
 * 语义与安全性：
 * - 命令仍由 remoteAgentCommand 构造（argv 白名单 + 引号），mux 仅做转发；
 * - BatchMode + ServerAliveInterval 保活（15s 心跳）；会话死亡 → 丢弃，下次操作懒重建；
 * - UI-397（用户反馈「闲置回来总要重连」）：移除空闲 5 分钟主动关闭——保活维持长连接，
 *   不主动断连；app 退出时 stdin EOF 使远端循环自然结束；
 * - PETRI_SSH_MUX=0 可整体禁用（回退 thin per-call）。
 */

const { spawn } = require('child_process');
const { AGENT_BIN } = require('./node-agent');

const DEFAULT_RUN_TIMEOUT_MS = 30000;

// PETRI_SSH_MUX_DEBUG=1 时逐事件打 stderr（写/收/解析/超时/断开），P4 实机排插桩。
const MUX_DEBUG = process.env.PETRI_SSH_MUX_DEBUG === '1';
const dbg = (session, msg) => {
  if (MUX_DEBUG) process.stderr.write(`[mux-dbg ${new Date().toISOString()} ${session.alias}#${session.id}] ${msg}\n`);
};

const sessions = new Map(); // sessionKey → session
let sessionSeq = 0;

function muxEnabled() {
  return process.env.PETRI_SSH_MUX !== '0';
}

// BLOCK-96 F1 — 会话按 别名+地址族 键控：同一别名不同 AddressFamily 注入
// 各自独立会话，互不串扰。
function sessionKey({ alias, addressFamily }) {
  return `${addressFamily || 'auto'}|${alias}`;
}

function createMuxSession({ alias, addressFamily, spawnFn }) {
  const doSpawn = spawnFn || ((args) => {
    const sshBin = process.platform === 'win32' ? 'ssh.exe' : 'ssh';
    return spawn(sshBin, args, { stdio: ['pipe', 'pipe', 'pipe'], windowsHide: true });
  });
  const child = doSpawn([
    ...(addressFamily === 'inet' || addressFamily === 'inet6'
      ? ['-o', `AddressFamily=${addressFamily}`]
      : []),
    '-o', 'BatchMode=yes',
    '-o', 'ServerAliveInterval=15',
    '-o', 'ServerAliveCountMax=2', // UI-397 — 判死 60s→30s：死连接首个请求少等一半
    '-o', 'ConnectTimeout=10',
    '--', alias,
    `bash "${AGENT_BIN}" __mux`,
  ]);

  const session = {
    alias,
    key: sessionKey({ alias, addressFamily }),
    id: ++sessionSeq,
    child,
    alive: true,
    lastActivity: Date.now(),
    buffer: '',
    inflight: Promise.resolve(),
    pending: null, // { resolve, timer }
  };
  dbg(session, `spawned pid=${child.pid}`);
  child.on('error', (e) => dbg(session, `child error: ${e.message}`));

  session.run = (command, timeoutMs = DEFAULT_RUN_TIMEOUT_MS) => {
    session.lastActivity = Date.now();
    const exec = () => new Promise((resolve, reject) => {
      if (!session.alive) {
        dbg(session, `run rejected (dead) cmd=${String(command).slice(0, 60)}...`);
        reject(muxError('会话已断开，正在重建连接'));
        return;
      }
      dbg(session, `write ${Buffer.byteLength(command)}B cmd=${String(command).slice(0, 80)}`);
      session.pending = {
        resolve: ({ code, stdout, stderr }) => { dbg(session, `resolve code=${code} stdout=${String(stdout).length}B`); session.pending = null; resolve({ ok: true, code, stdout: String(stdout), stderr: String(stderr || '') }); },
        reject: (err) => { dbg(session, `reject: ${err.message}`); session.pending = null; reject(err); },
        timer: setTimeout(() => {
          dbg(session, `TIMEOUT ${timeoutMs}ms pendingDiscarded`);
          session.pending = null;
          killSession(session);
          reject(muxError('连接超时（会话已重建，可重试）'));
        }, timeoutMs),
      };
      const line = Buffer.from(command, 'utf8').toString('base64');
      session.child.stdin.write(`${line}\n`, () => dbg(session, 'write flushed to ssh stdin'));
    });
    // 串行化：同一会话上的请求按序执行（协议无请求 id）
    const run = session.inflight.then(exec, exec);
    session.inflight = run.catch(() => {});
    return run;
  };

  session.close = () => killSession(session);

  child.stdout.on('data', (chunk) => {
    dbg(session, `stdout +${chunk.length}B head=${JSON.stringify(chunk.toString('utf8').slice(0, 60))}`);
    session.buffer += chunk.toString('utf8');
    let idx;
    while ((idx = session.buffer.indexOf('\n')) >= 0) {
      const line = session.buffer.slice(0, idx);
      session.buffer = session.buffer.slice(idx + 1);
      if (session.pending && line.startsWith('R\t')) {
        const parts = line.split('\t');
        const code = Number(parts[1]);
        // BLOCK-96 F3 — envelope R\t<code>\t<b64 stdout>\t<b64 stderr>；
        // 旧 3 字段形态（无 stderr）兼容解析。
        let stdoutB64;
        let stderrB64 = '';
        if (parts.length >= 4) {
          stdoutB64 = parts[2];
          stderrB64 = parts[3];
        } else {
          stdoutB64 = parts.slice(2).join('\t');
        }
        if (session.pending.timer) clearTimeout(session.pending.timer);
        const stdout = Buffer.from(stdoutB64 || '', 'base64').toString('utf8');
        const stderr = stderrB64 ? Buffer.from(stderrB64, 'base64').toString('utf8') : '';
        session.pending.resolve({ code, stdout, stderr });
      } else {
        dbg(session, `line discarded pending=${!!session.pending} startsR=${line.startsWith('R\t')} len=${line.length}`);
      }
    }
  });

  const die = () => {
    dbg(session, `died alive=${session.alive}`);
    session.alive = false;
    if (sessions.get(session.key) === session) sessions.delete(session.key);
    if (session.pending) {
      if (session.pending.timer) clearTimeout(session.pending.timer);
      const p = session.pending;
      session.pending = null;
      p.reject(muxError('连接已断开（可重试）'));
    }
  };
  child.on('close', (code, signal) => { dbg(session, `close code=${code} signal=${signal}`); die(); });
  child.on('exit', (code) => { dbg(session, `exit code=${code}`); die(); });
  child.stderr.on('data', (c) => { dbg(session, `stderr: ${String(c).trim().slice(0, 200)}`); });

  sessions.set(session.key, session);
  return session;
}

function muxError(message) {
  return Object.assign(new Error(`ssh_mux: ${message}`), {
    classified: { kind: 'transport.network', retryable: true },
  });
}

function killSession(session) {
  session.alive = false;
  if (sessions.get(session.key) === session) sessions.delete(session.key);
  try { session.child.kill(); } catch {}
}

/** 取（或建）alias 的会话。 */
function getMuxSession({ alias, addressFamily, spawnFn }) {
  const key = sessionKey({ alias, addressFamily });
  const existing = sessions.get(key);
  if (existing && existing.alive) return existing;
  return createMuxSession({ alias, addressFamily, spawnFn });
}

/**
 * 在复用连接上执行一条 agent 命令。
 * 返回 { ok, code, stdout, stderr }；失败抛 { classified } 形状错误（与 runSshOp 对齐）。
 * stderr 为 BLOCK-96 F3 envelope 第 4 字段（die 原因回传；旧 agent 无此字段时为空）。
 */
async function runOnMux({ alias, command, timeoutMs = DEFAULT_RUN_TIMEOUT_MS, spawnFn, addressFamily }) {
  const session = getMuxSession({ alias, addressFamily, spawnFn });
  const r = await session.run(command, timeoutMs);
  if (r.code !== 0) {
    // 远端 agent die（exit 64 等）——非 transport 错误，语义交由调用方解析 stdout/stderr
    return { ok: true, code: r.code, stdout: r.stdout, stderr: r.stderr };
  }
  return { ok: true, code: 0, stdout: r.stdout, stderr: r.stderr };
}

function closeAll() {
  for (const session of sessions.values()) killSession(session);
  sessions.clear();
}

process.on('exit', closeAll);

module.exports = {
  muxEnabled,
  getMuxSession,
  createMuxSession,
  runOnMux,
  closeAll,
};

/**
 * BLOCK-57 — 执行目标注册表（设计评审 D6/D9）
 *
 * execution_targets 表是唯一注册事实；~/.ssh/config 只读解析结果作为
 * 「可发现候选」合并进列表（不自动注册）。探测 = agent probe（一次性 ssh）。
 * 本机永远是默认目标，不入表（execution_target_id 为 NULL 即本机）。
 */

const fs = require('fs');
const os = require('os');
const path = require('path');
const crypto = require('crypto');

const { parseSshConfig, isValidHostAlias } = require('./ssh-config-parser');
const { runSshOp } = require('./ssh-transport');
const { remoteAgentCommand } = require('./node-agent');

function newTargetId(alias) {
  return 'tgt_' + crypto.createHash('sha256').update(String(alias)).digest('hex').slice(0, 12);
}

// db = petri-server 的 async facade（get/all/run 均返回 Promise）——一切访问必须 await。
// ensureAgent：可选注入（remote-job-runner.ensureAgent）——probe 是用户与节点的首次接触，
// 必须自带 agent 引导部署，否则新节点的首次探测必然失败（agent 尚不在节点上）。
function createTargetRegistry({ db, ensureAgent }) {
  async function listRegistered() {
    return db.prepare('SELECT * FROM execution_targets ORDER BY created_at').all();
  }

  /**
   * 列表 = 注册表 + ssh-config 发现候选（discovered:true，未注册）。
   */
  async function listWithDiscovery() {
    const registered = await listRegistered();
    const knownAliases = new Set(registered.map((row) => row.alias));
    let discovered = [];
    try {
      const configPath = path.join(os.homedir(), '.ssh', 'config');
      const parsed = parseSshConfig(fs.readFileSync(configPath, 'utf8'));
      discovered = parsed.hosts
        .filter((host) => isValidHostAlias(host.host) && !knownAliases.has(host.host))
        .map((host) => ({
          id: null,
          alias: host.host,
          hostName: host.hostName,
          user: host.user,
          port: host.port,
          discovered: true,
        }));
    } catch {
      // 无 ~/.ssh/config 或不可读：发现列表为空，注册表照常工作。
    }
    return { registered, discovered };
  }

  async function register({ alias, label, runtime }) {
    if (!isValidHostAlias(alias)) {
      return { ok: false, error: 'invalid_alias' };
    }
    const existing = await db.prepare('SELECT id FROM execution_targets WHERE alias=?').get(alias);
    if (existing) {
      return { ok: false, error: 'alias_already_registered', id: existing.id };
    }
    let runtimeJson = null;
    if (runtime && typeof runtime === 'object' && !Array.isArray(runtime)) {
      for (const [lang, binPath] of Object.entries(runtime)) {
        if (typeof binPath !== 'string' || /\s/.test(binPath)) {
          return { ok: false, error: 'invalid_runtime_override' };
        }
      }
      runtimeJson = JSON.stringify(runtime);
    }
    const id = newTargetId(alias);
    db.prepare(
      'INSERT INTO execution_targets (id, alias, label, created_at, status, runtime_json) VALUES (?,?,?,?,?,?)'
    ).run(id, alias, String(label || ''), Date.now(), 'unprobed', runtimeJson);
    return { ok: true, id, alias };
  }

  async function remove({ id }) {
    const result = await db.prepare('DELETE FROM execution_targets WHERE id=?').run(String(id || ''));
    return { ok: result.changes > 0 };
  }

  async function getById({ id }) {
    return db.prepare('SELECT * FROM execution_targets WHERE id=?').get(String(id || ''));
  }

  async function getByAlias({ alias }) {
    return db.prepare('SELECT * FROM execution_targets WHERE alias=?').get(String(alias || ''));
  }

  /**
   * 探测：agent probe（os / hostname / 调度器，通用面）。领域运行时探测（r/python）
   * 已随 BLOCK-96 F6 退役——运行时在位改由领域包 requires.runtimes 契约推导（BLOCK-86）。
   * 结果持久化 last_probe_json。传输失败如实返回分类结果，不猜测节点能力。
   */
  async function probe({ id }) {
    const target = await getById({ id });
    if (!target) return { ok: false, error: 'target_not_found' };
    if (typeof ensureAgent === 'function') {
      const deployed = await ensureAgent({ alias: target.alias });
      if (!deployed.ok) {
        await db.prepare("UPDATE execution_targets SET status='unreachable', last_probe_at=? WHERE id=?")
          .run(Date.now(), target.id);
        return { ok: false, error: deployed.error.kind, detail: deployed.error.detail };
      }
    }
    const startedAt = Date.now();
    const op = await runSshOp({ alias: target.alias, remoteCommand: remoteAgentCommand(['probe']), timeoutMs: 20000 });
    const handshakeMs = Date.now() - startedAt;
    if (op.classified.kind !== 'ok') {
      await db.prepare("UPDATE execution_targets SET status='unreachable', last_probe_at=? WHERE id=?")
        .run(Date.now(), target.id);
      return { ok: false, error: op.classified.kind, detail: op.classified.detail };
    }
    const info = {};
    for (const line of op.stdout.split('\n')) {
      const eq = line.indexOf('=');
      if (eq <= 0) continue;
      info[line.slice(0, eq)] = line.slice(eq + 1);
    }
    // BLOCK-96 F1 — 首连握手计时：>2s 提示疑似地址族黑洞（IPv6 ::1 先挂满超时
    // 才回落 IPv4 的典型症状，ConnectTimeout 封不住）。落 last_probe_json 供管理页提示。
    if (handshakeMs > 2000) info.handshakeMs = handshakeMs;
    await db.prepare('UPDATE execution_targets SET status=?, last_probe_json=?, last_probe_at=? WHERE id=?')
      .run('ready', JSON.stringify(info), Date.now(), target.id);
    return { ok: true, targetId: target.id, alias: target.alias, info, handshakeMs };
  }

  return {
    listRegistered,
    listWithDiscovery,
    register,
    remove,
    getById,
    getByAlias,
    probe,
  };
}

module.exports = { createTargetRegistry, newTargetId };

const fs = require('fs');
const path = require('path');

const REPORT_THEME_STYLE_ID = 'petri-report-theme';

function normalizeReportTheme(value) {
  return value === 'light' || value === 'dark' ? value : null;
}

function isHtmlFile(filename) {
  return /\.html?$/i.test(String(filename || ''));
}

function reportThemeCss(theme) {
  if (theme === 'dark') {
    return `
:root { color-scheme: dark; --text: #e6edf7; --muted: #a5b4c8; --border: #334155; --surface: #172033; --primary: #5eead4; --code-bg: #111827; --warn: #fbbf24; --info: #60a5fa; }
html, body { background: #0b1120 !important; color: var(--text) !important; }
a { color: #5eead4; }
nav, .nav-wrap, .nav-toggle, .wechat-float { background: #111a2e !important; color: var(--text) !important; border-color: var(--border) !important; }
th, td, table, pre, code, .stat-card { border-color: var(--border) !important; }
th, pre, code, .stat-card { background: var(--surface) !important; }
.callout, .callout-info, .callout-warn, .callout-tip { background: #172033 !important; color: var(--text) !important; }
.nav-wrap .nav-title { color: var(--primary) !important; }
.nav-wrap a { color: var(--muted) !important; }
.nav-wrap a:hover { color: var(--primary) !important; }
.wechat-float .info { color: var(--muted) !important; }
.wechat-float .info strong { color: var(--text) !important; }
img { background: transparent; }
`;
  }
  return `
:root { color-scheme: light; --text: #17201d; --muted: #5c6b64; --border: #dfe8e3; --surface: #f8faf9; --primary: #2e8555; --code-bg: #f4f7f5; --warn: #d97706; --info: #2563eb; }
html, body { background: #ffffff !important; color: var(--text) !important; }
a { color: #2e8555; }
nav, .nav-wrap, .nav-toggle, .wechat-float { background: #ffffff !important; color: var(--text) !important; border-color: var(--border) !important; }
th, pre, code, .stat-card { background: var(--surface) !important; }
.callout-info { background: #eff6ff !important; color: var(--text) !important; }
.callout-warn { background: #fffbeb !important; color: var(--text) !important; }
.callout-tip { background: #ecfdf5 !important; color: var(--text) !important; }
.nav-wrap .nav-title { color: var(--primary) !important; }
.nav-wrap a, .wechat-float .info { color: var(--muted) !important; }
.nav-wrap a:hover { color: var(--primary) !important; }
.wechat-float .info strong { color: var(--text) !important; }
`;
}

function injectReportTheme(html, theme) {
  const normalized = normalizeReportTheme(theme);
  if (!normalized || typeof html !== 'string') return html;
  const marker = `<style id="${REPORT_THEME_STYLE_ID}" data-theme="${normalized}">${reportThemeCss(normalized)}</style>`;
  const withoutPrevious = html.replace(
    new RegExp(`<style[^>]*id=["']${REPORT_THEME_STYLE_ID}["'][^>]*>[\\s\\S]*?<\\/style>`, 'i'),
    '',
  );
  if (/<\/head\s*>/i.test(withoutPrevious)) {
    return withoutPrevious.replace(/<\/head\s*>/i, `${marker}</head>`);
  }
  return `${marker}${withoutPrevious}`;
}

function sendThemedHtmlFile(req, res, filePath) {
  const theme = normalizeReportTheme(req?.query?.theme);
  if (!theme || !isHtmlFile(filePath)) return false;
  const html = fs.readFileSync(filePath, 'utf8');
  res.type('html').set('Cache-Control', 'private, no-store').send(injectReportTheme(html, theme));
  return true;
}

function shouldThemeUpstream(req, upstream) {
  const theme = normalizeReportTheme(req?.query?.theme);
  const contentType = upstream?.headers?.get?.('content-type') || '';
  return Boolean(theme && (isHtmlFile(req?.params?.filename) || /text\/html/i.test(contentType)));
}

module.exports = {
  REPORT_THEME_STYLE_ID,
  injectReportTheme,
  isHtmlFile,
  normalizeReportTheme,
  reportThemeCss,
  sendThemedHtmlFile,
  shouldThemeUpstream,
};

/**
 * helpers/site-snapshot.js — SITE_SNAPSHOT_v1
 *
 * Extracted from server.js. Pure module: depends only on ../db.
 *
 * Public API:
 *   buildSiteSnapshotAsync(userId, opts) → Promise<{projects, datasets, analyses}|null>
 *   renderSiteSnapshotForPrompt(snap, maxChars) → string
 *
 * Async helpers use the Promise facade over desktop SQLite.
 */
const dbMod = require('../db');

async function buildSiteSnapshotAsync(userId, opts) {
  if (!userId) return null;
  const o = opts || {};
  const maxAnalyses = o.maxAnalyses || 100;
  const maxDatasets = o.maxDatasets || 50;
  const maxProjects = o.maxProjects || 30;
  const projectId = o.projectId ? String(o.projectId) : null;

  const adb = dbMod.getAsyncDatabase();

  try {
    const projects = projectId
      ? await adb.prepare(`
      SELECT p.id, p.name, p.description, p.created_at, p.updated_at,
        (SELECT COUNT(*) FROM datasets d WHERE d.project_id = p.id) AS dataset_count,
        (SELECT COUNT(*) FROM analyses a WHERE a.dataset_id IN (SELECT id FROM datasets WHERE project_id = p.id)) AS analysis_count
      FROM projects p
      WHERE p.user_id = ? AND p.id = ?
      LIMIT 1
    `).all(userId, projectId)
      : await adb.prepare(`
      SELECT p.id, p.name, p.description, p.created_at, p.updated_at,
        (SELECT COUNT(*) FROM datasets d WHERE d.project_id = p.id) AS dataset_count,
        (SELECT COUNT(*) FROM analyses a WHERE a.dataset_id IN (SELECT id FROM datasets WHERE project_id = p.id)) AS analysis_count
      FROM projects p
      WHERE p.user_id = ?
      ORDER BY p.updated_at DESC
      LIMIT ?
    `).all(userId, maxProjects);

    if (projects.length === 0) return {projects: [], datasets: [], analyses: [], scopeProjectId: projectId};

    const projectIds = projects.map(p => p.id);
    const placeholders = projectIds.map(() => '?').join(',');

    const datasets = await adb.prepare(`
      SELECT id, project_id, name, n_cells, n_genes, size, uploaded_at, description
      FROM datasets
      WHERE project_id IN (${placeholders})
      ORDER BY uploaded_at DESC
      LIMIT ?
    `).all(...projectIds, maxDatasets);

    const datasetIds = datasets.map(d => d.id);
    let analyses = [];
    if (datasetIds.length > 0) {
      const dsPh = datasetIds.map(() => '?').join(',');
      analyses = await adb.prepare(`
        SELECT id, dataset_id, type, name, status, parent_analysis_id, summary, created_at, finished_at, error
        FROM analyses
        WHERE dataset_id IN (${dsPh})
        ORDER BY created_at DESC
        LIMIT ?
      `).all(...datasetIds, maxAnalyses);
    }

    analyses = analyses.map(a => {
      let sum = null;
      try {
        const raw = typeof a.summary === 'string' ? JSON.parse(a.summary) : a.summary;
        if (raw && typeof raw === 'object') {
          sum = {
            nCells: raw.nCells,
            nGenes: raw.nGenes,
            nClusters: raw.nClusters,
            nDEGs: raw.nDEGs,
            nGOTerms: raw.nGOTerms,
          };
          Object.keys(sum).forEach(k => sum[k] === undefined && delete sum[k]);
          if (Object.keys(sum).length === 0) sum = null;
        }
      } catch {}
      return {
        id: a.id,
        datasetId: a.dataset_id,
        type: a.type,
        name: a.name,
        status: a.status,
        parentAnalysisId: a.parent_analysis_id,
        summary: sum,
        createdAt: a.created_at,
        finishedAt: a.finished_at,
        hasError: !!a.error,
      };
    });

    return {
      projects: projects.map(p => ({
        id: p.id,
        name: p.name,
        description: p.description,
        datasetCount: p.dataset_count,
        analysisCount: p.analysis_count,
        updatedAt: p.updated_at,
      })),
      datasets: datasets.map(d => ({
        id: d.id,
        projectId: d.project_id,
        name: d.name,
        description: d.description,
        nCells: d.n_cells,
        nGenes: d.n_genes,
        sizeMB: d.size ? Math.round(d.size / 1048576) : null,
        uploadedAt: d.uploaded_at,
      })),
      analyses,
      scopeProjectId: projectId,
    };
  } catch (e) {
    console.log('[site-snapshot] err:', e.message);
    return null;
  }
}

/**
 * Render snapshot as compact text for prompt injection.
 */
function renderSiteSnapshotForPrompt(snap, maxChars) {
  if (!snap) return '';
  maxChars = maxChars || 3500;
  let out = snap.scopeProjectId
    ? '\n\n=== 当前项目资源（实时数据，仅限当前项目） ===\n'
    : '\n\n=== 用户的全部资源（实时数据，可直接引用） ===\n';
  out += '注：所有 id 都可以用于 navigate、recluster、start_analysis 等 action。优先使用这里的真实数据回答用户。\n';

  if (snap.projects.length === 0) {
    out += '\n（用户还没有项目）';
    return out;
  }

  out += '\n[项目]';
  for (const p of snap.projects) {
    out += `\n- ${p.name} (id=${p.id}, ${p.datasetCount} 数据集, ${p.analysisCount} 分析)`;
    if (p.description) out += ' — ' + String(p.description).slice(0, 80);
  }

  if (snap.datasets.length > 0) {
    out += '\n\n[数据集]';
    for (const d of snap.datasets) {
      let line = `\n- ${d.name} (id=${d.id}, projectId=${d.projectId}`;
      if (d.nCells) line += `, ${d.nCells} cells`;
      if (d.nGenes) line += `, ${d.nGenes} genes`;
      if (d.sizeMB) line += `, ${d.sizeMB}MB`;
      line += ')';
      out += line;
    }
  }

  if (snap.analyses.length > 0) {
    out += '\n\n[分析]';
    for (const a of snap.analyses) {
      let line = `\n- ${a.name} (id=${a.id}, datasetId=${a.datasetId}, type=${a.type}, status=${a.status}`;
      if (a.summary) {
        if (a.summary.nClusters) line += `, ${a.summary.nClusters} clusters`;
        if (a.summary.nDEGs) line += `, ${a.summary.nDEGs} DEGs`;
      }
      if (a.parentAnalysisId) line += ', has parent';
      line += ')';
      if (out.length + line.length > maxChars - 80) {
        out += '\n... (more truncated)';
        break;
      }
      out += line;
    }
  }
  return out;
}

