    msg: '实验设计矩阵不满秩：可能是某个分组只有 1 个样本，或分组变量有完全共线的列。请检查 coldata。',
  },
];

// BLOCK-66 P1 — runtime preflight：executor.binPath 是路径字符串（executor
// 解析失败会回退 PATH 搜索仍返回字符串），必须 existsSync 校验；R/Python
// 运行时未安装时诚实失败 + 商店指引（而非裸 spawn ENOENT）。纯函数便于测试。
function evaluateRuntimePreflight(executor, lang) {
  const binPath = executor && executor.binPath;
  const binExists = !!(binPath && require('node:fs').existsSync(binPath));
  if (executor && binPath && binExists) {
    return { runtime: lang || null, ready: true, command: binPath, reason: null };
  }
  const label = interpreterLabel(lang);
  if (!executor) {
    return { runtime: lang || null, ready: false, command: null, reason: `未找到 ${lang || 'unknown'} 执行器` };
  }
  // P3 实机实证：隔离无 R 环境下 binPath 可能为 null（PATH 搜索无果），
  // 此时同样是"运行时未安装"，必须给商店指引而非含糊的"未找到执行器"。
  const where = binPath
    ? `可执行文件不存在：${binPath}`
    : `未找到 ${missingRuntimeCommandName(lang)}`;
  return {
    runtime: lang || null,
    ready: false,
    command: null,
    reason: `${label} 分析运行时未安装（${where}）。`
      + '请在「插件商店 → 运行时」安装对应分析运行时后重试（安装后需重启应用）。',
  };
}


module.exports = {
  TOOL_LIFECYCLE,
  ZOMBIE_TIMEOUT_MS,
  HEARTBEAT_INTERVAL_MS,
  R_ERROR_TRANSLATIONS,
  evaluateRuntimePreflight,
};

'use strict';

const fs = require('fs');
const path = require('path');
const { isInternalArtifactName, isSafeFlatFilename } = require('../artifact-truth');
const { createVerifiedFileSnapshot } = require('../verified-file-snapshot');
const { parseStoredToolResult } = require('./tool-result-misc');

function declaredResultFilenames(result) {
  const names = new Set();
  const manifest = result && result.manifest;
  const sources = [
    result && result.artifacts,
    result && result.outputs,
    result && result.files,
    Array.isArray(manifest) ? manifest : null,
    manifest && manifest.artifacts,
    manifest && manifest.outputs,
    manifest && manifest.files,
  ];
  for (const items of sources) {
    if (!Array.isArray(items)) continue;
    for (const item of items) {
      const candidate = typeof item === 'string'
        ? item
        : item && typeof item === 'object'
          ? item.filename || item.name || item.file
          : null;
      if (!isSafeFlatFilename(candidate) || isInternalArtifactName(candidate)) continue;
      names.add(candidate);
    }
  }
  return names;
}

function resolveStoredArtifactTruthBinding(result, filename) {
  const truth = result && result.artifactTruth;
  if (!truth) return { ok: true, expectedSha256: null, legacy: true };
  if (truth.blocking === true || !['valid', 'degraded'].includes(truth.status)) {
    return { ok: false, error: 'artifact_truth_unavailable' };
  }
  const artifacts = Array.isArray(result.artifacts) ? result.artifacts : [];
  const matches = artifacts.filter((artifact) => {
    if (!artifact || typeof artifact !== 'object') return false;
    const name = artifact.filename || artifact.name || artifact.path;
    return isSafeFlatFilename(path.basename(String(name || '')))
      && path.basename(String(name || '')) === filename;
  });
  if (matches.length !== 1) {
    return {
      ok: false,
      error: matches.length > 1 ? 'artifact_identity_ambiguous' : 'artifact_truth_unavailable',
    };
  }
  const expectedSha256 = String(matches[0].sha256 || '').trim().toLowerCase();
  if (!/^[a-f0-9]{64}$/.test(expectedSha256)) {
    return { ok: false, error: 'artifact_truth_unavailable' };
  }
  return { ok: true, expectedSha256, legacy: false };
}

function exactLegacyResultRoots(jobId, jobsDir) {
  if (!isSafeFlatFilename(String(jobId || '')) || !jobsDir) return [];
  const toolRoot = path.resolve(jobsDir, String(jobId));
  const mcpRoot = path.resolve(path.dirname(jobsDir), 'mcp-tool-jobs', String(jobId));
  return [toolRoot, path.join(toolRoot, 'output'), mcpRoot, path.join(mcpRoot, 'output')];
}

function isRealPathInside(root, target) {
  const relative = path.relative(root, target);
  return relative !== '' && !relative.startsWith(`..${path.sep}`) && relative !== '..'
    && !path.isAbsolute(relative);
}

function expectedPhysicalResultRoot({ job, layout, jobsDir, resultDir }) {
  if (job.project_id) {
    if (!layout?.workspaceRoot || !layout.jobRoot || !layout.outputDir) return null;
    const realWorkspace = fs.realpathSync(layout.workspaceRoot);
    const realJobRoot = fs.realpathSync(layout.jobRoot);
    if (!isRealPathInside(realWorkspace, realJobRoot)) return null;
    if (resultDir === path.resolve(layout.jobRoot)) return realJobRoot;
    const realOutputDir = fs.realpathSync(layout.outputDir);
    return path.dirname(realOutputDir) === realJobRoot ? realOutputDir : null;
  }

  const legacyRoots = exactLegacyResultRoots(job.id, jobsDir);
  const index = legacyRoots.indexOf(resultDir);
  if (index === -1) return null;
  const legacyBase = index < 2
    ? path.resolve(jobsDir)
    : path.resolve(path.dirname(jobsDir), 'mcp-tool-jobs');
  const realBase = fs.realpathSync(legacyBase);
  return path.join(realBase, String(job.id), ...(index % 2 === 1 ? ['output'] : []));
}

function resultFileIdentity(stat) {
  return {
    dev: stat.dev,
    ino: stat.ino,
    size: stat.size,
    mtimeMs: stat.mtimeMs,
    ctimeMs: stat.ctimeMs,
  };
}

function hasSameResultFileIdentity(stat, identity) {
  return Boolean(
    identity
      && stat.dev === identity.dev
      && stat.ino === identity.ino
      && stat.size === identity.size
      && stat.mtimeMs === identity.mtimeMs
      && stat.ctimeMs === identity.ctimeMs,
  );
}

/**
 * Resolve a private artifact only from the current Job's persisted declaration.
 * The stored result root must be one of this Job's exact server-derived roots;
 * realpath containment prevents a declared symlink from escaping that root.
 */
function resolveAuthorizedToolResultFile({ job, filename, layout = null, jobsDir }) {
  if (!isSafeFlatFilename(filename) || isInternalArtifactName(filename)) {
    return { ok: false, error: 'bad_path' };
  }
  const result = parseStoredToolResult(job);
  if (!result || !declaredResultFilenames(result).has(filename)) {
    return { ok: false, error: 'file_not_found' };
  }
  const truthBinding = resolveStoredArtifactTruthBinding(result, filename);
  if (!truthBinding.ok) return truthBinding;

  const storedResultDir = typeof result.resultDir === 'string'
    ? result.resultDir
    : typeof result.outputDir === 'string'
      ? result.outputDir
      : null;
  if (!storedResultDir || path.resolve(storedResultDir) !== storedResultDir) {
    return { ok: false, error: 'file_not_found' };
  }

  const allowedRoots = job.project_id
    ? [layout && layout.jobRoot, layout && layout.outputDir]
      .filter(Boolean)
      .map((root) => path.resolve(root))
    : exactLegacyResultRoots(job.id, jobsDir);
  const resultDir = path.resolve(storedResultDir);
  if (!allowedRoots.includes(resultDir)) {
    return { ok: false, error: 'file_not_found' };
  }

  try {
    const realRoot = fs.realpathSync(resultDir);
    const expectedRealRoot = expectedPhysicalResultRoot({ job, layout, jobsDir, resultDir });
    if (realRoot !== expectedRealRoot || !fs.statSync(realRoot).isDirectory()) {
      return { ok: false, error: 'file_not_found' };
    }
    const candidate = path.join(resultDir, filename);
    if (path.dirname(candidate) !== resultDir) return { ok: false, error: 'bad_path' };
    const realFile = fs.realpathSync(candidate);
    const fileStat = fs.statSync(realFile);
    if (path.dirname(realFile) !== realRoot || !fileStat.isFile()) {
      return { ok: false, error: 'file_not_found' };
    }
    return {
      ok: true,
      filePath: realFile,
      resultDir,
      fileIdentity: resultFileIdentity(fileStat),
      expectedSha256: truthBinding.expectedSha256,
    };
  } catch {
    return { ok: false, error: 'file_not_found' };
  }
}

/**
 * Open exactly the file that passed the authorization realpath checks. Sending
 * the path through Express after that check would re-resolve it and allow a
 * rename/symlink race. The caller owns the returned descriptor on success.
 */
async function openVerifiedAuthorizedToolResultFile(resolved) {
  if (!resolved || !resolved.ok || !resolved.filePath || !resolved.fileIdentity) {
    return { ok: false, error: 'file_not_found' };
  }

  let fd = null;
  try {
    const noFollow = Number.isInteger(fs.constants.O_NOFOLLOW) ? fs.constants.O_NOFOLLOW : 0;
    fd = fs.openSync(resolved.filePath, fs.constants.O_RDONLY | noFollow);
    const openedStat = fs.fstatSync(fd);
    if (!openedStat.isFile() || !hasSameResultFileIdentity(openedStat, resolved.fileIdentity)) {
      fs.closeSync(fd);
      return { ok: false, error: 'file_not_found' };
    }
    const sourceFd = fd;
    fd = null;
    const snapshot = await createVerifiedFileSnapshot(sourceFd, {
      expectedIdentity: resolved.fileIdentity,
      expectedSha256: resolved.expectedSha256,
    });
    return {
      ok: true,
      fd: snapshot.fd,
      stat: snapshot.stat,
      verification: snapshot.verification,
      actualSha256: resolved.expectedSha256 ? snapshot.sha256 : null,
    };
  } catch (error) {
    if (fd !== null) {
      try { fs.closeSync(fd); } catch {}
    }
    if (error?.code === 'verified_snapshot_hash_mismatch') {
      return { ok: false, error: 'artifact_truth_drift' };
    }
    return { ok: false, error: 'file_not_found' };
  }
}

/**
 * The tools HTTP contract accepts a flat `filename -> base64` map. Tool
 * scripts resolve their inputs directly from the job root; directory uploads
 * are not part of that contract. Resolve every key before writing so a bad
 * key cannot escape the job sandbox or leave a partial upload behind.
 */
function resolveUploadedFilePath(jobDir, key) {
  if (typeof jobDir !== 'string' || !jobDir || jobDir.includes('\0')) {
    return { ok: false, error: '上传目录无效。' };
  }
  if (typeof key !== 'string' || !key || key.includes('\0')) {
    return { ok: false, error: '上传文件名无效。' };
  }

  // Reject both platform separator syntaxes. This is deliberately stricter
  // than a containment-only check because nested upload paths are unsupported.
  if (
    key.includes('/') ||
    key.includes('\\') ||
    key === '.' ||
    key === '..' ||
    path.isAbsolute(key) ||
    path.win32.isAbsolute(key) ||
    /^[A-Za-z]:/.test(key)
  ) {
    return { ok: false, error: '上传文件名不能包含路径。' };
  }
  if (isInternalArtifactName(key)) {
    return { ok: false, error: '上传文件名与任务内部控制文件冲突。' };
  }

  const root = path.resolve(jobDir);
  const filePath = path.resolve(root, key);
  if (path.dirname(filePath) !== root) {
    return { ok: false, error: '上传文件路径超出任务目录。' };
  }
  return { ok: true, filePath, key };
}

function resolveUploadedFiles(jobDir, files) {
  if (files === undefined || files === null) return { ok: true, entries: [] };
  if (typeof files !== 'object' || Array.isArray(files) || Buffer.isBuffer(files)) {
    return { ok: false, error: '上传文件必须是文件名到 Base64 内容的映射。' };
  }
  const prototype = Object.getPrototypeOf(files);
  if (prototype !== Object.prototype && prototype !== null) {
    return { ok: false, error: '上传文件必须是文件名到 Base64 内容的映射。' };
  }

  const entries = [];
  for (const [key, fileData] of Object.entries(files)) {
    const resolved = resolveUploadedFilePath(jobDir, key);
    if (!resolved.ok) return resolved;
    if (typeof fileData !== 'string') {
      return { ok: false, error: `文件 "${key}" 的上传内容无效。` };
    }
    entries.push({ ...resolved, fileData });
  }
  return { ok: true, entries };
}

function writeUploadedFiles(jobDir, files) {
  const resolved = resolveUploadedFiles(jobDir, files);
  if (!resolved.ok) return resolved;

  for (const entry of resolved.entries) {
    fs.writeFileSync(entry.filePath, Buffer.from(entry.fileData, 'base64'));
  }
  return resolved;
}

function validateUploadedFiles(toolId, jobDir, files) {
  const resolvedFiles = resolveUploadedFiles(jobDir, files);
  if (!resolvedFiles.ok) return resolvedFiles.error;
  const csvTools = [
    'deseq2',
    'go-kegg',
    'gsea',
    'km-survival',
    'lasso-cox',
    'bindea-immune',
    'wgcna',
    'complexheatmap',
  ];

  for (const { key, filePath } of resolvedFiles.entries) {
    if (!fs.existsSync(filePath)) continue;

    const fd = fs.openSync(filePath, 'r');
    const buf = Buffer.alloc(4096);
    const bytesRead = fs.readSync(fd, buf, 0, 4096, 0);
    fs.closeSync(fd);
    const head = buf.slice(0, bytesRead).toString('utf-8');

    if (csvTools.includes(toolId) && head.includes('\0')) {
      return `文件 "${key}" 似乎是二进制文件（如 Excel .xlsx），请转换为 CSV 或 TSV 格式后重新上传。提示：在 Excel 中"另存为" → 选择 CSV (UTF-8) 格式。`;
    }

    if (csvTools.includes(toolId)) {
      const lines = head.split(/\r?\n/).filter((line) => line.trim());
      if (lines.length < 2) {
        return `文件 "${key}" 内容为空或只有表头，需要至少包含 1 行数据。`;
      }
      const firstLine = lines[0];
      const sep = firstLine.includes('\t') ? '\t' : ',';
      const headerCols = firstLine.split(sep).length;
      // GO/KEGG explicitly accepts a one-column gene list (`gene` header);
      // the other CSV tools require at least two columns.
      const acceptsSingleColumnGeneList = toolId === 'go-kegg';
      if (headerCols < 2 && !acceptsSingleColumnGeneList) {
        return `文件 "${key}" 只检测到 1 列。请确认分隔符是逗号(CSV)或制表符(TSV)，不是分号或空格。`;
      }
      const dataCols = lines[1].split(sep).length;
      if (Math.abs(dataCols - headerCols) > 1) {
        return `文件 "${key}" 格式异常：表头有 ${headerCols} 列，但第一行数据有 ${dataCols} 列。请检查 CSV 格式是否正确。`;
      }
    }

    const stat = fs.statSync(filePath);
    if (
      stat.size > 100 * 1024 * 1024 &&
      toolId !== 'seurat-standard' &&
      toolId !== 'cellchat'
    ) {
      return `文件 "${key}" 大小为 ${Math.round(stat.size / 1024 / 1024)}MB，超过推荐上限(100MB)。大文件可能导致分析超时。建议：筛选基因或样本后重试。`;
    }
  }
  return null;
}

function hydrateExecutionJob(row) {
  if (!row || typeof row !== 'object') return null;
  let params = {};
  try {
    params = row.params_json
      ? (typeof row.params_json === 'string' ? JSON.parse(row.params_json) : row.params_json)
      : {};
  } catch {
    params = {};
  }
  return { ...row, params };
}

/**
 * Plugin scripts historically use either `<job>/output` or the isolated Job
 * root as their result directory. Both locations are server-owned; select one
 * only from a produced manifest or an exact declared artifact filename.
 */
function resolveProducedResultDirectory({ jobDir, outputDir, expectedArtifacts = [] }) {
  const resultRoots = [path.resolve(outputDir), path.resolve(jobDir)];
  const manifestNames = ['manifest.json', 'artifact-manifest.json'];
  for (const root of resultRoots) {
    for (const name of manifestNames) {
      const candidate = path.join(root, name);
      if (fs.existsSync(candidate) && fs.statSync(candidate).isFile()) {
        return { resultDir: root, manifestPath: candidate, reason: 'manifest' };
      }
    }
  }
  const declaredNames = expectedArtifacts
    .map((artifact) => artifact && (artifact.filename || artifact.name))
    .filter((name) => typeof name === 'string' && name === path.basename(name) && !name.includes('\0'));
  for (const root of resultRoots) {
    if (declaredNames.some((name) => {
      const candidate = path.join(root, name);
      return fs.existsSync(candidate) && fs.statSync(candidate).isFile();
    })) {
      return { resultDir: root, manifestPath: path.join(root, 'manifest.json'), reason: 'declared_artifact' };
    }
  }
  return {
    resultDir: path.resolve(outputDir),
    manifestPath: path.join(path.resolve(outputDir), 'manifest.json'),
    reason: 'standard_default',
  };
}


module.exports = {
  declaredResultFilenames,
  resolveStoredArtifactTruthBinding,
  resolveAuthorizedToolResultFile,
  openVerifiedAuthorizedToolResultFile,
  resolveUploadedFilePath,
  resolveUploadedFiles,
  writeUploadedFiles,
  validateUploadedFiles,
  hydrateExecutionJob,
  resolveProducedResultDirectory,
};

/**
 * helpers/user-facts.js — USER_FACTS_v1 (Layer 3a structured long-term memory)
 *
 * Extracted from server.js (Phase 8.6 helper modularization).
 * Pure module: depends on ../db, uuid, and process.env.DEEPSEEK_API_KEY.
 *
 * Public API:
 *   listUserFactsAsync, getUserFactAsync, upsertUserFactAsync,
 *   deleteUserFactAsync, clearUserFactsAsync
 *   buildFactsBlockAsync(userId, maxChars)
 *   extractFactsFromMessages(messages, existingFacts) → Promise<Array>
 *   backgroundExtractFacts(userId, messages)         → Promise<void>
 *   FACT_CATEGORIES, FACT_CAT_LABEL
 *
 * Async helpers use the Promise facade over desktop SQLite.
 */

const dbMod = require('../db');
const { v4: uuidv4 } = require('uuid');

// One-time table create (idempotent)
let _tableChecked = false;
async function _ensureTable() {
  if (_tableChecked) return;
  _tableChecked = true;
  const adb = dbMod.getAsyncDatabase();
  try {
    await adb.exec(`
      CREATE TABLE IF NOT EXISTS user_facts (
        id TEXT PRIMARY KEY,
        user_id TEXT NOT NULL,
        category TEXT NOT NULL,
        content TEXT NOT NULL,
        pinned INTEGER NOT NULL DEFAULT 0,
        source TEXT NOT NULL DEFAULT 'auto',
        project_id TEXT,
        created_at TEXT NOT NULL,
        updated_at TEXT NOT NULL
      );
      CREATE INDEX IF NOT EXISTS idx_user_facts_user ON user_facts(user_id, pinned DESC, updated_at DESC);
    `);
  } catch {
    /* ignore */
  }
  try { await adb.prepare('ALTER TABLE user_facts ADD COLUMN project_id TEXT').run(); } catch {}
  try { await adb.prepare('CREATE INDEX IF NOT EXISTS idx_user_facts_project ON user_facts(user_id, project_id, pinned DESC, updated_at DESC)').run(); } catch {}
}

const FACT_CATEGORIES = [
  'research_focus',
  'preference',
  'entity',
  'task_state',
  'note',
  'learning_state',
];
const FACT_CAT_LABEL = {
  research_focus: '研究方向',
  preference: '偏好',
  entity: '关键实体',
  task_state: '任务状态',
  note: '笔记',
  learning_state: '学习状态',
};

async function listUserFactsAsync(userId, limit, projectId = null) {
  if (!userId) return [];
  await _ensureTable();
  const adb = dbMod.getAsyncDatabase();
  const scopeSql = projectId ? 'project_id = ?' : "COALESCE(project_id, '') = ''";
  const args = projectId ? [userId, String(projectId)] : [userId];
  const sql = `SELECT * FROM user_facts WHERE user_id = ? AND ${scopeSql} ORDER BY pinned DESC, updated_at DESC${limit ? ' LIMIT ?' : ''}`;
  if (limit) args.push(limit);
  const rows = await adb.prepare(sql).all(...args);
  return rows || [];
}

async function getUserFactAsync(id, userId) {
  await _ensureTable();
  const adb = dbMod.getAsyncDatabase();
  return await adb
    .prepare('SELECT * FROM user_facts WHERE id = ? AND user_id = ?')
    .get(id, userId);
}

async function upsertUserFactAsync({ id, userId, projectId = null, category, content, pinned = 0, source = 'auto' }) {
  if (!userId || !content || !category) return null;
  await _ensureTable();
  const adb = dbMod.getAsyncDatabase();
  const now = new Date().toISOString();
  const pinnedVal = pinned ? 1 : 0;
  if (id) {
    const existing = await adb
      .prepare('SELECT * FROM user_facts WHERE id = ? AND user_id = ?')
      .get(id, userId);
    if (existing) {
      await adb
        .prepare(
          `UPDATE user_facts SET category=?, content=?, pinned=?, source=?, updated_at=? WHERE id=? AND user_id=?`
        )
        .run(category, content, pinnedVal, source, now, id, userId);
      return getUserFactAsync(id, userId);
    }
  }
  const newId = id || 'fact_' + uuidv4().slice(0, 12);
  await adb
    .prepare(
      `INSERT INTO user_facts(id, user_id, category, content, pinned, source, project_id, created_at, updated_at) VALUES (?,?,?,?,?,?,?,?,?)`
    )
    .run(newId, userId, category, content, pinnedVal, source, projectId ? String(projectId) : null, now, now);
  return getUserFactAsync(newId, userId);
}

async function deleteUserFactAsync(id, userId) {
  await _ensureTable();
  const adb = dbMod.getAsyncDatabase();
  await adb.prepare('DELETE FROM user_facts WHERE id = ? AND user_id = ?').run(id, userId);
}

async function clearUserFactsAsync(userId, projectId = null) {
  await _ensureTable();
  const adb = dbMod.getAsyncDatabase();
  if (projectId) {
    await adb.prepare('DELETE FROM user_facts WHERE user_id = ? AND project_id = ?').run(userId, String(projectId));
  } else {
    await adb.prepare("DELETE FROM user_facts WHERE user_id = ? AND COALESCE(project_id, '') = ''").run(userId);
  }
}

function _normFact(s) {
  return (s || '').trim().toLowerCase().replace(/\s+/g, ' ');
}

/** Build a compact text block of top facts for system prompt injection.
 *  FACTS_TTL_v1 — age-aware filter so old auto-extracted facts don't pollute current convo. */
async function buildFactsBlockAsync(userId, maxChars = 1200, projectId = null) {
  const facts = await listUserFactsAsync(userId, 80, projectId);
  if (!facts || facts.length === 0) return '';
  const now = Date.now();
  const DAY = 86400_000;
  const fresh = [];
  const aging = [];
  const old = [];
  for (const f of facts) {
    if (f.pinned) {
      fresh.push(f);
      continue;
    }
    let age = 999 * DAY;
    try {
      age = now - new Date(f.updated_at).getTime();
    } catch {}
    if (age <= 30 * DAY) fresh.push(f);
    else if (age <= 90 * DAY) aging.push(f);
    else old.push(f);
  }
  const filtered = [...fresh, ...aging];
  const byCat = {};
  for (const f of filtered) {
    if (!byCat[f.category]) byCat[f.category] = [];
    byCat[f.category].push(f);
  }
  let out = '';
  let used = 0;
  for (const cat of FACT_CATEGORIES) {
    const arr = byCat[cat];
    if (!arr || arr.length === 0) continue;
    const header = '\n【' + (FACT_CAT_LABEL[cat] || cat) + '】\n';
    let block = header;
    for (const f of arr) {
      const line = '- ' + (f.pinned ? '📌 ' : '') + f.content + '\n';
      if (used + block.length + line.length > maxChars) break;
      block += line;
    }
    if (block !== header) {
      out += block;
      used += block.length;
    }
  }
  return out;
}

// Sync wrapper for in-process callers.
function buildFactsBlock(userId, maxChars = 1200, projectId = null) {
  const _adb = dbMod.getAsyncDatabase();
  const sqlite = dbMod.getDatabase();
  let rows;
  try {
    rows = projectId
      ? sqlite.prepare('SELECT * FROM user_facts WHERE user_id = ? AND project_id = ? ORDER BY pinned DESC, updated_at DESC LIMIT 80').all(userId, String(projectId))
      : sqlite.prepare("SELECT * FROM user_facts WHERE user_id = ? AND COALESCE(project_id, '') = '' ORDER BY pinned DESC, updated_at DESC LIMIT 80").all(userId);
  } catch {
    return '';
  }
  if (!rows || rows.length === 0) return '';
  const now = Date.now();
  const DAY = 86400_000;
  const fresh = [],
    aging = [];
  for (const f of rows) {
    if (f.pinned) {
      fresh.push(f);
      continue;
    }
    let age = 999 * DAY;
    try {
      age = now - new Date(f.updated_at).getTime();
    } catch {}
    if (age <= 30 * DAY) fresh.push(f);
    else if (age <= 90 * DAY) aging.push(f);
  }
  const filtered = [...fresh, ...aging];
  const byCat = {};
  for (const f of filtered) {
    if (!byCat[f.category]) byCat[f.category] = [];
    byCat[f.category].push(f);
  }
  let out = '';
  let used = 0;
  for (const cat of FACT_CATEGORIES) {
    const arr = byCat[cat];
    if (!arr || arr.length === 0) continue;
    const header = '\n【' + (FACT_CAT_LABEL[cat] || cat) + '】\n';
    let block = header;
    for (const f of arr) {
      const line = '- ' + (f.pinned ? '📌 ' : '') + f.content + '\n';
      if (used + block.length + line.length > maxChars) break;
      block += line;
    }
    if (block !== header) {
      out += block;
      used += block.length;
    }
  }
  return out;
}

/** Extract structured facts from recent messages using the summary role.
 *  Returns array of {category, content}. Background, fail-safe. */
async function extractFactsFromMessages(messages, existingFacts) {
  if (!Array.isArray(messages) || messages.length === 0) return [];

  const lines = messages
    .slice(-12)
    .map((m) => {
      const role = m.role === 'user' ? '用户' : 'AI';
      return role + ': ' + (m.content || '').slice(0, 800);
    })
    .join('\n\n');

  const existingBlock =
    existingFacts && existingFacts.length > 0
      ? '\n\n已有的事实条目（避免重复，只新增有真正新增信息的）：\n' +
        existingFacts
          .slice(0, 30)
          .map((f) => '- [' + f.category + '] ' + f.content)
          .join('\n')
      : '';

  const sysPrompt =
    '你是用户档案抽取助手。从对话里提取关于用户的可复用事实，输出严格 JSON 数组。每条事实分类一个：' +
    'research_focus（研究方向，如"研究 PBMC 数据"）、preference（偏好，如"偏好 SCTransform"）、' +
    'entity（命名实体，如"cluster 5 = NK 细胞"）、task_state（任务进度，如"正在做 DEG 分析"）、' +
    'learning_state（学习状态，如"已学完 single-cell module01-03"、"对 DESeq2 dispersion 还有点模糊"）、note（其他笔记）。\n\n' +
    '严格规则：\n' +
    '- 只抽取关于用户本人的、跨会话仍有用的事实\n' +
    '- 不要抽取临时性问答或一般性常识\n' +
    '- 每条 ≤ 80 字，简洁可复用\n' +
    '- 如果没有值得记的，返回空数组 []\n' +
    '- 只输出 JSON 数组，不要解释，格式：[{"category":"...","content":"..."}, ...]';

  const userPrompt = '从以下对话提取用户档案事实：\n\n' + lines + existingBlock;

  const { callModelTask, parseJsonText } = require('./model-tasks');
  const result = await callModelTask({
    role: 'summary',
    messages: [
      { role: 'system', content: sysPrompt },
      { role: 'user', content: userPrompt },
    ],
    temperature: 0.2,
    maxTokens: 800,
    responseFormat: { type: 'json_object' },
    telemetry: { kind: 'user_fact_extraction' },
  });
  const parsed = parseJsonText(result.text);
  let arr = Array.isArray(parsed)
    ? parsed
    : parsed && Array.isArray(parsed.facts)
      ? parsed.facts
      : parsed && Array.isArray(parsed.data)
        ? parsed.data
        : null;
  if (!arr && parsed && typeof parsed === 'object') {
    arr = Object.values(parsed).find(Array.isArray) || [];
  }
  if (!Array.isArray(arr)) return [];
  return arr.filter(
    (fact) =>
      fact &&
      typeof fact === 'object' &&
      typeof fact.category === 'string' &&
      FACT_CATEGORIES.includes(fact.category) &&
      typeof fact.content === 'string' &&
      fact.content.trim().length > 0 &&
      fact.content.length <= 200
  );
}

/** Extract + persist (de-duped). Fire-and-forget. */
async function backgroundExtractFacts(userId, messages, projectId = null) {
  if (!userId) return;
  try {
    const existing = await listUserFactsAsync(userId, 60, projectId);
    const newFacts = await extractFactsFromMessages(messages, existing);
    if (newFacts.length === 0) return;
    const existingSet = new Set(existing.map((f) => f.category + '||' + _normFact(f.content)));
    let saved = 0;
    for (const f of newFacts) {
      const key = f.category + '||' + _normFact(f.content);
      if (existingSet.has(key)) continue;
      await upsertUserFactAsync({
        userId,
        projectId,
        category: f.category,
        content: f.content.trim(),
        source: 'auto',
      });
      existingSet.add(key);
      saved++;
    }
    if (saved > 0) console.log('[user-facts] saved', saved, 'new facts for user', userId);
  } catch (e) {
    console.log('[user-facts] extraction error:', e.message);
  }
}

module.exports = {
  listUserFactsAsync,
  getUserFactAsync,
  upsertUserFactAsync,
  deleteUserFactAsync,
  clearUserFactsAsync,
  buildFactsBlockAsync,
  buildFactsBlock, // SYNC_BRIDGE_v1 — sync wrapper
  extractFactsFromMessages,
  backgroundExtractFacts,
  FACT_CATEGORIES,
  FACT_CAT_LABEL,
};

'use strict';

const crypto = require('crypto');
const fs = require('fs');
const os = require('os');
const path = require('path');
const { Readable } = require('stream');

const SNAPSHOT_BUFFER_BYTES = 1024 * 1024;
const VERIFIED_SNAPSHOT_VERSION = 1;

function sameFileIdentity(stat, identity) {
  return Boolean(
    stat
      && identity
      && stat.dev === identity.dev
      && stat.ino === identity.ino
      && stat.size === identity.size
      && stat.mtimeMs === identity.mtimeMs
      && stat.ctimeMs === identity.ctimeMs,
  );
}

function snapshotError(code, message) {
  return Object.assign(new Error(message), { code });
}

/**
 * Copy an already-authorized descriptor into an unlinked private file before
 * delivery. Hashing a mutable source fd and then streaming that same inode
 * leaves a window where an in-place write can change the response bytes.
 * The returned fd instead owns the exact bytes that were hashed here.
 *
 * This function consumes sourceFd on both success and failure. The caller owns
 * the returned snapshot fd.
 */
function closeDescriptor(fd) {
  return new Promise((resolve, reject) => {
    fs.close(fd, (error) => (error ? reject(error) : resolve()));
  });
}

function openDescriptor(filePath, flags, mode) {
  return new Promise((resolve, reject) => {
    fs.open(filePath, flags, mode, (error, fd) => (error ? reject(error) : resolve(fd)));
  });
}

function statDescriptor(fd) {
  return new Promise((resolve, reject) => {
    fs.fstat(fd, (error, stat) => (error ? reject(error) : resolve(stat)));
  });
}

function syncDescriptor(fd) {
  return new Promise((resolve, reject) => {
    fs.fsync(fd, (error) => (error ? reject(error) : resolve()));
  });
}

function readDescriptor(fd, buffer, offset, length, position) {
  return new Promise((resolve, reject) => {
    fs.read(fd, buffer, offset, length, position, (error, bytesRead) => (
      error ? reject(error) : resolve(bytesRead)
    ));
  });
}

function writeDescriptor(fd, buffer, offset, length, position) {
  return new Promise((resolve, reject) => {
    fs.write(fd, buffer, offset, length, position, (error, bytesWritten) => (
      error ? reject(error) : resolve(bytesWritten)
    ));
  });
}

async function readExactDescriptor(fd, buffer, position) {
  let offset = 0;
  while (offset < buffer.length) {
    const bytesRead = await readDescriptor(
      fd,
      buffer,
      offset,
      buffer.length - offset,
      position + offset,
    );
    if (bytesRead <= 0) break;
    offset += bytesRead;
  }
  return offset;
}

async function writeExactDescriptor(fd, buffer, position) {
  let offset = 0;
  while (offset < buffer.length) {
    const bytesWritten = await writeDescriptor(
      fd,
      buffer,
      offset,
      buffer.length - offset,
      position + offset,
    );
    if (bytesWritten <= 0) {
      throw snapshotError(
        'verified_snapshot_write_incomplete',
        'Verified snapshot stopped accepting bytes before the source was copied.',
      );
    }
    offset += bytesWritten;
  }
}

function sha256Buffer(buffer) {
  return crypto.createHash('sha256').update(buffer).digest('hex');
}

function snapshotVerification(snapshot) {
  const verification = snapshot?.verification;
  if (!Number.isInteger(snapshot?.fd) || snapshot.fd < 0) {
    throw snapshotError(
      'verified_snapshot_descriptor_invalid',
      'Verified snapshot descriptor is unavailable.',
    );
  }
  if (!verification
      || verification.version !== VERIFIED_SNAPSHOT_VERSION
      || verification.algorithm !== 'sha256'
      || verification.blockBytes !== SNAPSHOT_BUFFER_BYTES
      || !Number.isSafeInteger(verification.size)
      || verification.size < 0
      || !Array.isArray(verification.blockHashes)) {
    throw snapshotError(
      'verified_snapshot_metadata_invalid',
      'Verified snapshot delivery metadata is invalid.',
    );
  }
  const expectedBlockCount = Math.ceil(verification.size / verification.blockBytes);
  if (verification.blockHashes.length !== expectedBlockCount
      || verification.blockHashes.some((hash) => !/^[a-f0-9]{64}$/.test(String(hash)))) {
    throw snapshotError(
      'verified_snapshot_metadata_invalid',
      'Verified snapshot block metadata is invalid.',
    );
  }
  return verification;
}

async function closeVerifiedFileSnapshot(snapshot) {
  if (!Number.isInteger(snapshot?.fd) || snapshot.fd < 0) return false;
  const fd = snapshot.fd;
  snapshot.fd = null;
  await closeDescriptor(fd);
  return true;
}

async function readVerifiedSnapshotBlock(snapshot, verification, blockIndex) {
  const position = blockIndex * verification.blockBytes;
  const expectedBytes = Math.min(verification.blockBytes, verification.size - position);
  const buffer = Buffer.allocUnsafe(expectedBytes);
  const bytesRead = await readExactDescriptor(snapshot.fd, buffer, position);
  if (bytesRead !== expectedBytes) {
    throw snapshotError(
      'verified_snapshot_delivery_short_read',
      'Verified snapshot changed before a complete delivery block could be read.',
    );
  }
  if (sha256Buffer(buffer) !== verification.blockHashes[blockIndex]) {
    throw snapshotError(
      'verified_snapshot_delivery_hash_mismatch',
      'Verified snapshot delivery block no longer matches its trusted bytes.',
    );
  }
  return buffer;
}

async function verifySnapshotDeliverySize(snapshot, verification) {
  const stat = await statDescriptor(snapshot.fd);
  if (!stat.isFile() || stat.size !== verification.size) {
    throw snapshotError(
      'verified_snapshot_delivery_size_mismatch',
      'Verified snapshot size changed before delivery completed.',
    );
  }
}

/**
 * Consume a snapshot descriptor into memory while verifying each fixed block.
 * The descriptor is closed on both success and failure.
 */
async function readVerifiedFileSnapshot(snapshot, { encoding = null } = {}) {
  const verification = snapshotVerification(snapshot);
  const chunks = [];
  try {
    for (let index = 0; index < verification.blockHashes.length; index += 1) {
      chunks.push(await readVerifiedSnapshotBlock(snapshot, verification, index));
    }
    await verifySnapshotDeliverySize(snapshot, verification);
    const bytes = Buffer.concat(chunks, verification.size);
    return encoding ? bytes.toString(encoding) : bytes;
  } finally {
    try { await closeVerifiedFileSnapshot(snapshot); } catch {}
  }
}

/**
 * Stream only buffers that have already matched their creation-time block
 * hashes. A retained writer can corrupt a future block, but that block is
 * rejected before the exact Buffer read from the descriptor is pushed.
 */
function createVerifiedSnapshotReadStream(snapshot) {
  const verification = snapshotVerification(snapshot);
  let blockIndex = 0;
  let reading = false;
  let finishing = false;

  return new Readable({
    highWaterMark: verification.blockBytes,
    read() {
      if (reading || finishing) return;
      reading = true;
      void (async () => {
        if (blockIndex >= verification.blockHashes.length) {
          await verifySnapshotDeliverySize(snapshot, verification);
          finishing = true;
          reading = false;
          await closeVerifiedFileSnapshot(snapshot);
          this.push(null);
          return;
        }

        const buffer = await readVerifiedSnapshotBlock(snapshot, verification, blockIndex);
        blockIndex += 1;
        if (blockIndex >= verification.blockHashes.length) {
          await verifySnapshotDeliverySize(snapshot, verification);
        }
        const isLastBlock = blockIndex >= verification.blockHashes.length;
        reading = false;
        if (isLastBlock) finishing = true;
        this.push(buffer);
        if (isLastBlock) {
          await closeVerifiedFileSnapshot(snapshot);
          this.push(null);
        }
      })().catch((error) => {
        reading = false;
        finishing = true;
        this.destroy(error);
      });
    },
    destroy(error, callback) {
      finishing = true;
      void closeVerifiedFileSnapshot(snapshot).then(
        () => callback(error),
        (closeError) => callback(error || closeError),
      );
    },
  });
}

/**
 * Node's `Readable.pipe()` unpipes a source when the HTTP destination closes,
 * but it does not guarantee that the source is destroyed. Bind every abnormal
 * response termination to the verified stream so its anonymous descriptor is
 * closed promptly. A normal `finish` is explicitly excluded.
 */
function pipeVerifiedSnapshotToResponse(stream, req, res) {
  if (!stream || typeof stream.pipe !== 'function' || !res || typeof res.once !== 'function') {
    throw snapshotError(
      'verified_snapshot_response_invalid',
      'Verified snapshot response binding is invalid.',
    );
  }

  let responseFinished = res.writableFinished === true;
  let cleaned = false;
  const cleanup = () => {
    if (cleaned) return;
    cleaned = true;
    res.removeListener?.('finish', onFinish);
    res.removeListener?.('close', onAbnormalTermination);
    res.removeListener?.('aborted', onAbnormalTermination);
    res.removeListener?.('error', onAbnormalTermination);
    req?.removeListener?.('aborted', onAbnormalTermination);
    stream.removeListener?.('close', cleanup);
  };
  const onFinish = () => {
    responseFinished = true;
    cleanup();
  };
  const onAbnormalTermination = () => {
    if (responseFinished || res.writableFinished === true) {
      responseFinished = true;
      cleanup();
      return;
    }
    cleanup();
    if (!stream.destroyed) stream.destroy();
  };

  res.once('finish', onFinish);
  res.once('close', onAbnormalTermination);
  res.once('aborted', onAbnormalTermination);
  res.once('error', onAbnormalTermination);
  req?.once?.('aborted', onAbnormalTermination);
  stream.once('close', cleanup);
  if (req?.aborted === true
      || res.destroyed === true
      || res.closed === true
      || (res.writableEnded === true && res.writableFinished !== true)) {
    onAbnormalTermination();
    return res;
  }
  try {
    return stream.pipe(res);
  } catch (error) {
    cleanup();
    if (!stream.destroyed) stream.destroy();
    throw error;
  }
}

async function createVerifiedFileSnapshot(sourceFd, {
  expectedIdentity = null,
  expectedSha256 = null,
  tempRoot = os.tmpdir(),
} = {}) {
  if (!Number.isInteger(sourceFd) || sourceFd < 0) {
    throw snapshotError('verified_snapshot_source_invalid', 'Verified snapshot source descriptor is invalid.');
  }
  const normalizedExpectedSha256 = expectedSha256 == null ? null : String(expectedSha256);
  if (normalizedExpectedSha256 != null && !/^[a-f0-9]{64}$/.test(normalizedExpectedSha256)) {
    try { await closeDescriptor(sourceFd); } catch {}
    throw snapshotError('verified_snapshot_hash_invalid', 'Verified snapshot hash is invalid.');
  }

  let snapshotDir = null;
  let snapshotPath = null;
  let snapshotFd = null;
  let sourceClosed = false;
  try {
    const before = await statDescriptor(sourceFd);
    if (!before.isFile()) {
      throw snapshotError('verified_snapshot_source_not_file', 'Verified snapshot source is not a regular file.');
    }
    if (expectedIdentity && !sameFileIdentity(before, expectedIdentity)) {
      throw snapshotError('verified_snapshot_source_changed', 'Verified snapshot source identity changed before copying.');
    }

    const privateTempRoot = await fs.promises.realpath(tempRoot);
    snapshotDir = await fs.promises.mkdtemp(path.join(privateTempRoot, 'petri-artifact-stream-'));
    await fs.promises.chmod(snapshotDir, 0o700);
    snapshotPath = path.join(snapshotDir, 'artifact');
    const noFollow = Number.isInteger(fs.constants.O_NOFOLLOW) ? fs.constants.O_NOFOLLOW : 0;
    snapshotFd = await openDescriptor(
      snapshotPath,
      fs.constants.O_CREAT | fs.constants.O_EXCL | fs.constants.O_RDWR | noFollow,
      0o600,
    );

    // Remove every pathname before copying a single byte. Leaving the private
    // file named until after source hashing would let another process running
    // as the same OS user open that pathname and mutate the response fd after
    // the source hash passed. Unlinking prevents new pathname-based opens; a
    // descriptor retained before unlink is handled by delivery-time block
    // verification, so changed bytes are rejected before they are emitted.
    await fs.promises.unlink(snapshotPath);
    snapshotPath = null;
    await fs.promises.rmdir(snapshotDir);
    snapshotDir = null;

    if (!Number.isSafeInteger(before.size) || before.size < 0) {
      throw snapshotError(
        'verified_snapshot_source_too_large',
        'Verified snapshot source exceeds the supported byte range.',
      );
    }

    const hash = crypto.createHash('sha256');
    const blockHashes = [];
    let copiedBytes = 0;
    while (copiedBytes < before.size) {
      const blockLength = Math.min(SNAPSHOT_BUFFER_BYTES, before.size - copiedBytes);
      const block = Buffer.allocUnsafe(blockLength);
      const bytesRead = await readExactDescriptor(sourceFd, block, copiedBytes);
      if (bytesRead !== blockLength) {
        throw snapshotError(
          'verified_snapshot_source_changed',
          'Verified snapshot source changed while it was copied.',
        );
      }
      hash.update(block);
      blockHashes.push(sha256Buffer(block));
      await writeExactDescriptor(snapshotFd, block, copiedBytes);
      copiedBytes += blockLength;
    }
    const after = await statDescriptor(sourceFd);
    if (!sameFileIdentity(after, before)) {
      throw snapshotError('verified_snapshot_source_changed', 'Verified snapshot source changed while it was copied.');
    }
    await closeDescriptor(sourceFd);
    sourceClosed = true;

    await syncDescriptor(snapshotFd);
    const snapshotStat = await statDescriptor(snapshotFd);
    if (!snapshotStat.isFile() || snapshotStat.size !== copiedBytes) {
      throw snapshotError('verified_snapshot_incomplete', 'Verified snapshot did not preserve the complete source file.');
    }
    const actualSha256 = hash.digest('hex');
    if (normalizedExpectedSha256 && actualSha256 !== normalizedExpectedSha256) {
      throw snapshotError('verified_snapshot_hash_mismatch', 'Verified snapshot bytes do not match Artifact Truth.');
    }

    const verification = Object.freeze({
      version: VERIFIED_SNAPSHOT_VERSION,
      algorithm: 'sha256',
      blockBytes: SNAPSHOT_BUFFER_BYTES,
      size: copiedBytes,
      blockHashes: Object.freeze(blockHashes),
    });
    return { fd: snapshotFd, stat: snapshotStat, sha256: actualSha256, verification };
  } catch (error) {
    if (!sourceClosed) {
      try { await closeDescriptor(sourceFd); } catch {}
    }
    if (snapshotFd !== null) {
      try { await closeDescriptor(snapshotFd); } catch {}
    }
    if (snapshotPath) {
      try { await fs.promises.unlink(snapshotPath); } catch {}
    }
    if (snapshotDir) {
      try { await fs.promises.rmdir(snapshotDir); } catch {}
    }
    throw error;
  }
}

module.exports = {
  SNAPSHOT_BUFFER_BYTES,
  VERIFIED_SNAPSHOT_VERSION,
  closeVerifiedFileSnapshot,
  createVerifiedFileSnapshot,
  createVerifiedSnapshotReadStream,
  pipeVerifiedSnapshotToResponse,
  readVerifiedFileSnapshot,
  sameFileIdentity,
};

/**
 * core/petri-server/jobs/retention-sweeper.js
 *
 * Retention sweeper for SQLite append-only tables (PR-001 closeout).
 *
 * Background:
 *   petri-server hosts append-only ledgers (loop_iterations / loop_actions /
 *   loop_evidence / loop_decisions / loop_state_snapshots in db.js, plus
 *   copilot_messages in helpers/conversations.js). Without a sweeper, long
 *   running installs accumulate rows indefinitely. We do NOT touch
 *   agent-task-store.js (task_events) here — that module is owned by an
 *   earlier work package and the sweeper would race its writers.
 *
 * Failure model:
 *   - Each table delete is wrapped in its own try/catch. A single failure
 *     MUST NOT halt the rest of the sweep. Failures are logged via
 *     console.warn so the operator sees partial progress, then re-tried
 *     on the next tick. We never swallow silently.
 *   - Concurrency: better-sqlite3 is synchronous and a single process owns
 *     the file at a time (WAL allows multiple readers + single writer), so
 *     we run deletes sequentially.
 *
 * Scheduling:
 *   - `scheduleRetentionSweep` uses a recursive setTimeout (NOT setInterval)
 *     to match the existing cacheManager pattern in core/petri-server/.
 *   - The handle is unref'd so a pending sweep never keeps the process alive
 *     during shutdown.
 *
 * NOT in scope:
 *   - Vacuum / incremental_vacuum (deferred — would need additional IO
 *     priority reasoning).
 *   - branch_db.messages / result_db.result_versions tables (those live in
 *     src/database/* which is owned by the branch+result work package).
 *   - agent_task_events (owned by agent-task-store.js — out of scope).
 */

'use strict';

const DEFAULT_INTERVAL_MS = 24 * 60 * 60 * 1000; // 24h

// Per-table retention window in days. Conservative defaults; tune only with
// accompanying product decision.
const RETENTION_DAYS = {
  copilotMessages: 90,
  loopIterations: 30,
  loopActions: 30,
  loopEvidence: 30,
  loopDecisions: 30,
  loopStateSnapshots: 30,
};

function nowIsoDate(daysAgo) {
  const ts = Date.now() - daysAgo * 24 * 60 * 60 * 1000;
  return new Date(ts).toISOString();
}

function isoDaysAgo(days) {
  return `datetime('now', '-${Math.max(1, Math.floor(days))} day')`;
}

/**
 * Run a single retention pass. Each table delete is isolated so one
 * failure does not poison the others.
 *
 * @param {object} deps
 * @param {import('better-sqlite3').Database} deps.db  petri-server main DB
 * @param {Function} [deps.warn]  logger (defaults to console.warn)
 * @returns {{ scanned: string[], deleted: Record<string,number>, failures: Array<{table: string, reason: string}> }}
 */
function runRetentionSweep({ db, warn = console.warn } = {}) {
  if (!db) {
    return { scanned: [], deleted: {}, failures: [{ table: '<sweep>', reason: 'db_not_provided' }] };
  }

  const deleted = {};
  const failures = [];
  const scanned = [];

  // ---- copilot_messages: delete rows older than RETENTION_DAYS.copilotMessages
  // whose parent conversation is not 'active'. Active conversations must keep
  // full history so the user never sees message loss.
  scanned.push('copilot_messages');
  try {
    const cutoff = isoDaysAgo(RETENTION_DAYS.copilotMessages);
    const res = db.prepare(`
      DELETE FROM copilot_messages
      WHERE ts < ${cutoff}
        AND conversation_id NOT IN (
          SELECT id FROM copilot_conversations WHERE status = 'active'
        )
    `).run();
    deleted.copilot_messages = res.changes || 0;
  } catch (e) {
    const msg = e && e.message ? e.message : String(e);
    warn(`retention-purge: failed at copilot_messages, reason=${msg}`);
    failures.push({ table: 'copilot_messages', reason: msg });
  }

  // ---- loop ledger: only sweep terminal loop_runs (completed / failed /
  // cancelled). planned / running must keep their full audit trail so a
  // multi-turn task can resume. Loop iterations / actions / evidence /
  // decisions / snapshots are deleted when their parent loop_run is
  // terminal AND the row itself is older than the window.
  const terminalLoopRunWhere = `
    loop_run_id IN (
      SELECT loop_run_id FROM loop_runs
      WHERE loop_status IN ('completed','failed','cancelled')
        AND updated_at < ${isoDaysAgo(RETENTION_DAYS.loopIterations)}
    )
  `;

  const loopTables = [
    ['loop_iterations', 'created_at'],
    ['loop_actions', 'created_at'],
    ['loop_evidence', 'created_at'],
    ['loop_decisions', 'created_at'],
    ['loop_state_snapshots', 'created_at'],
  ];

  for (const [table, tsColumn] of loopTables) {
    scanned.push(table);
    try {
      const cutoff = isoDaysAgo(RETENTION_DAYS.loopIterations);
      const res = db.prepare(`
        DELETE FROM ${table}
        WHERE ${tsColumn} < ${cutoff}
          AND ${terminalLoopRunWhere}
      `).run();
      deleted[table] = res.changes || 0;
    } catch (e) {
      const msg = e && e.message ? e.message : String(e);
      warn(`retention-purge: failed at ${table}, reason=${msg}`);
      failures.push({ table, reason: msg });
    }
  }

  return { scanned, deleted, failures };
}

let schedulerHandle = null;
let activeIntervalMs = DEFAULT_INTERVAL_MS;
let lastDbRef = null;
let lastWarnFn = console.warn;

function computeNextDelay(intervalMs) {
  // Stagger the first run ~60s after boot so we do not contend with recovery
  // sweeps (zombie job scan, etc.). Subsequent runs follow the normal interval.
  if (schedulerHandle === null) return Math.min(intervalMs, 60 * 1000);
  return intervalMs;
}

/**
 * Schedule a retention sweep that re-runs every `intervalMs` milliseconds
 * using a recursive setTimeout. The handle is unref'd so it never keeps the
 * process alive during graceful shutdown.
 *
 * @param {object} opts
 * @param {number} [opts.intervalMs]
 * @param {import('better-sqlite3').Database} opts.db
 * @param {Function} [opts.warn]
 * @param {Function} [opts.setTimeoutFn]
 * @param {Function} [opts.clearTimeoutFn]
 */
function scheduleRetentionSweep({
  intervalMs = DEFAULT_INTERVAL_MS,
  db,
  warn = console.warn,
  setTimeoutFn = setTimeout,
  clearTimeoutFn = clearTimeout,
} = {}) {
  if (!db) {
    warn('retention-purge: scheduler not started, db missing');
    return null;
  }
  if (schedulerHandle) {
    // Already running — restart with the new interval.
    clearTimeoutFn(schedulerHandle);
    schedulerHandle = null;
  }

  activeIntervalMs = intervalMs;
  lastDbRef = db;
  lastWarnFn = warn;

  function scheduleNext() {
    const delay = computeNextDelay(activeIntervalMs);
    schedulerHandle = setTimeoutFn(() => {
      try {
        const report = runRetentionSweep({ db: lastDbRef, warn: lastWarnFn });
        const total = Object.values(report.deleted).reduce((acc, n) => acc + (n || 0), 0);
        if (report.failures.length > 0) {
          warn(
            `retention-purge: partial sweep deleted=${total} tables=${report.scanned.length} failures=${report.failures.length}`
          );
        } else if (total > 0) {
          warn(`retention-purge: deleted=${total} tables=${report.scanned.length}`);
        }
      } catch (e) {
        // Top-level guard. runRetentionSweep already isolates per-table
        // failures; this catches the unexpected (e.g. db handle closed).
        const msg = e && e.message ? e.message : String(e);
        warn(`retention-purge: sweep top-level error, reason=${msg}`);
      }
      scheduleNext();
    }, delay);
    if (schedulerHandle && typeof schedulerHandle.unref === 'function') {
      schedulerHandle.unref();
    }
  }

  scheduleNext();
  return schedulerHandle;
}

function stopRetentionSweep({ clearTimeoutFn = clearTimeout } = {}) {
  if (schedulerHandle) {
    clearTimeoutFn(schedulerHandle);
    schedulerHandle = null;
  }
  lastDbRef = null;
}

module.exports = {
  runRetentionSweep,
  scheduleRetentionSweep,
  stopRetentionSweep,
  RETENTION_DAYS,
  DEFAULT_INTERVAL_MS,
};

'use strict';

/**
 * loop-orchestrator.js
 *
 * Pure agent loop state machine extracted from agent-runner.js.
 * Contains:
 * - 5 _loop* closures (_loopInit, _loopEmitIterationEvent, _loopPersistPhase,
 *   _loopSaveCheckpoint, _loopPersistProgressIteration)
 * - Loop body for-loop (MAX_AGENT_ITERS iterations)
 * - 6 loop state variables (loopState, loopRunId, loopSequence, loopIterations,
 *   loopAbortedByController, loopPublicConclusion)
 *
 * PHASE 3.1 split:
 * - NO harness-workflow-state references (avoids circular dependency)
 * - Receives dependencies via constructor/parameters
 * - Pure state machine, no system prompt or LLM client logic
 */

const {
  buildLoopRun,
