/**
 * BLOCK-70 mobile-gateway — 手机浏览器直连移动面（同 WiFi / A2 隧道共用）。
 *
 * D1 独立 Express app 实例 + 独立端口；主后端 127.0.0.1:3001 本地面零改动。
 * D4 安全边界：默认关闭；除 /m/api/pair 与静态页外全部过会话 token 鉴权；
 * 按 IP 限速；JSONL 审计（只记元数据不记内容）。
 * D3 单一真相：mountRoutes 注入既有路由模块（同进程共享 db 单例），
 * 不建第二套存储；DB 零新业务表。
 *
 * 移动 app 实例只挂载读面所需的模块注入（files/workspace/terminal 等
 * 模块不进入本实例）——v1 无文件上传/产物下载。
 */

const express = require('express');
const fs = require('node:fs');
const { readFileSync } = require('node:fs');
const path = require('node:path');
const zlib = require('node:zlib');

const { getStores } = require('./pairing');
const { sanitizeEngineerIdentity } = require('../../shared-backend/engineer-identity');
const { readConfig, resolveEnabled, resolvePort, lanAddresses } = require('./config');
const crypto = require('node:crypto');

const RATE_LIMIT_WINDOW_MS = 60 * 1000;
// BLOCK-87 实测修正：投影 SPA 自带大量轮询器（摘要卡 5s×多路、会话对账 5s、
// 偏好 15s…），且经隧道时全部设备共享 127.0.0.1 一个 IP——240/分 必然误伤
// 正常使用（用户实测「总是 rate_limited」）。限速目的（D4）是保护 API 面不被
// 爆破/刷量，不是限制页面资产：静态资源与 Vite 热更模块不计数，只计 API 面。
const RATE_LIMIT_MAX_REQUESTS = 600;
// 计入限速的 API 前缀（其余路径——/m 静态页、投影 SPA 资产、Vite 代理——
// 仍过 sessionAuth 会话门，只是不消耗限速配额）。
const RATE_LIMITED_PREFIXES = ['/api/', '/m/api/', '/federation/'];
const AUDIT_MAX_LINE_BYTES = 4 * 1024;
// 会话 cookie 长效：一次认证长期有效，除非用户主动吊销/关闭（加映 4）。
const SESSION_COOKIE_MAX_AGE = 365 * 24 * 60 * 60;
// 同名设备记录区分用短尾缀（无登录态下不做设备指纹，代价可接受）。
function pairShortId() {
  return crypto.randomBytes(2).toString('hex');
}

function createAuditWriter(auditPath) {
  return function audit(entry) {
    try {
      const line = JSON.stringify({ ts: new Date().toISOString(), ...entry });
      if (Buffer.byteLength(line, 'utf8') <= AUDIT_MAX_LINE_BYTES) {
        fs.appendFileSync(auditPath, `${line}\n`, 'utf8');
      }
    } catch {
      // 审计写失败绝不影响请求处理（fail-open 仅限审计自身）。
    }
  };
}

function createRateLimiter({ windowMs = RATE_LIMIT_WINDOW_MS, max = RATE_LIMIT_MAX_REQUESTS, now = () => Date.now() } = {}) {
  const hits = new Map(); // ip -> [timestamps]
  setInterval(() => hits.clear(), windowMs).unref?.();
  return function rateLimit(req, res, next) {
    const isApi = RATE_LIMITED_PREFIXES.some((prefix) => req.path.startsWith(prefix));
    if (!isApi) return next();
    const ip = req.ip || req.socket?.remoteAddress || 'unknown';
    const stamps = (hits.get(ip) || []).filter((ts) => now() - ts < windowMs);
    if (stamps.length >= max) {
      res.status(429).json({ ok: false, error: 'rate_limited', message: '请求过于频繁，请稍后再试' });
      return;
    }
    stamps.push(now());
    hits.set(ip, stamps);
    next();
  };
}

/**
 * 构建 mobile Express app。mountRoutes(app) 由调用方注入既有读面路由模块。
 */
function buildMobileGateway({
  dataDir,
  mountRoutes,
  auditPath = path.join(dataDir, 'mobile', 'audit.log'),
  rateLimit,
} = {}) {
  if (!dataDir) throw new Error('mobile_gateway_data_dir_required');
  const stores = getStores(dataDir);
  const audit = createAuditWriter(auditPath);
  const app = express();
  app.disable('x-powered-by');

  app.use(createRateLimiter(rateLimit ? { ...rateLimit } : {}));

  // 审计中间件：只记元数据（ip/method/path/status/时长），不记 query 与 body（D9）。
  app.use((req, res, next) => {
    const startedAt = Date.now();
    res.on('finish', () => {
      audit({
        ip: req.ip || req.socket?.remoteAddress || 'unknown',
        method: req.method,
        path: req.path,
        status: res.statusCode,
        durationMs: Date.now() - startedAt,
      });
    });
    next();
  });

  // 静态移动页（/m）。fallthrough 保持默认 true：/m/api/* 必须穿透到下方
  // API 中间件链，不能被静态中间件吞掉。
  const publicDir = path.join(__dirname, 'public');
  app.use('/m', express.static(publicDir, { index: 'index.html' }));

  app.use(express.json({ limit: '64kb' }));

  // 配对：一次性 token 换持久会话 token（无需既有会话）。
  // 加映 4：请求已带有效会话（cookie/Bearer）时直接复用，不再新建——
  // 同一手机重复扫码/重开配对链接不应堆积设备记录。
  // BLOCK-88 P1（D2）：body.identity additive——联邦指挥席配对时声明的工程师
  // 身份（displayName/device）经净化落会话；声明身份仅展示、未经验证（D1-A）。
  app.post('/m/api/pair', (req, res) => {
    const token = String(req.body?.token || '');
    const redeemed = stores.pairing.redeem(token);
    if (!redeemed) {
      res.status(401).json({ ok: false, error: 'pair_token_invalid', message: '配对码无效或已过期，请在桌面端重新生成' });
      return;
    }
    const identity = sanitizeEngineerIdentity(req.body?.identity);
    const existingToken = readCookieToken(req) || bearerToken(req);
    const existingSession = existingToken ? stores.sessions.authenticate(existingToken) : null;
    if (existingSession) {
      res.json({ ok: true, sessionId: existingSession.id, sessionToken: existingToken, reused: true });
      return;
    }
    const userAgent = String(req.headers['user-agent'] || '');
    // 指挥席 fetch 无 UA（UA 推导恒命中「移动设备」兜底）——带署名时优先以
    // 署名命名会话，「我的设备」列表与协作成员面语义一致（评审 P2 清偿）。
    const uaName = /iphone|ipad/i.test(userAgent) ? 'iOS 设备'
      : /android/i.test(userAgent) ? 'Android 设备'
        : '移动设备';
    const baseName = (identity && identity.displayName) || uaName;
    const { sessionId, sessionToken } = stores.sessions.createSession({ name: `${baseName}-${pairShortId()}`, identity });
    res.json({ ok: true, sessionId, sessionToken, identity: identity || null });
  });

  // 会话鉴权：token 来源优先级 = gw_session cookie（桌面投影 SPA 同源自动携带，
  // 其 Bearer 是无会话语义的 'desktop-local' 常量）> Bearer 头 / ?session=
  // （EventSource 与外部 API 客户端）。
  function readCookieToken(req) {
    return String((req.headers.cookie || '')
      .split(/;\s*/)
      .find((pair) => pair.startsWith('gw_session='))
      ?.split('=').slice(1).join('=') || '');
  }

  function bearerToken(req) {
    const header = String(req.headers.authorization || '');
    return header.startsWith('Bearer ') ? header.slice(7) : '';
  }

  function sessionAuth(req, res, next) {
    const token = readCookieToken(req) || bearerToken(req) || String(req.query.session || '');
    const session = stores.sessions.authenticate(token);
    if (!session) {
      res.status(401).json({ ok: false, error: 'session_invalid', message: '会话无效或已被吊销' });
      return;
    }
    req.mobileSession = { id: session.id, name: session.name, identity: session.identity || null };
    // 与桌面完全相同的身份对象（auth.js LOCAL_USER）——路由按 user_id 过滤的
    // 数据面才可能与桌面同源同门（id 必须一字不差，'local-user'）。
    req.user = require('../auth').LOCAL_USER;
    next();
  }

  // BLOCK-102 P3 — https 面签发 Secure cookie（公网 8442/8443 门）；LAN 明文
  // http 面保持可登录（Secure cookie 在 http 上不回传，会使 LAN 投影失效）。
  function issueSessionCookie(req, res, sessionToken) {
    const isHttps = req.secure || req.headers['x-forwarded-proto'] === 'https';
    const securePart = isHttps ? '; Secure' : '';
    res.setHeader('Set-Cookie', `gw_session=${sessionToken}; Path=/; HttpOnly; SameSite=Lax${securePart}; Max-Age=${SESSION_COOKIE_MAX_AGE}`);
  }

  app.get('/m/api/health', (_req, res) => {
    res.json({ ok: true, service: 'petri-mobile-gateway' });
  });

  // ── UI-357 桌面投影（用户裁决「整个软件桌面原封不动的过来」）────────
  // /app?token=<一次性配对码> → 服务端兑换会话 + 下发 cookie → 302 /app/。
  // SPA 静态服务 + index.html 注入 window.petriDesktop 身份/后端垫片；
  // /api/* 走全量路由注册表（sessionAuth 会话门内）——手机获得与桌面
  // 同源同门的完整 API。Electron 专属能力（终端/窗口控制等）经 Proxy 垫片
  // 诚实降级为 no-op。
  const desktopDist = path.join(__dirname, '..', '..', '..', 'frontend', 'dist');
  const desktopIndex = path.join(desktopDist, 'index.html');
  const desktopAvailable = () => fs.existsSync(desktopIndex);
  console.log(`[mobile-gateway] desktop projection: dist=${desktopDist} available=${desktopAvailable()}`);

  app.get('/pair', (req, res) => {
    if (!desktopAvailable()) {
      res.status(501).send('desktop projection unavailable: frontend/dist not built (npm run build:spa)');
      return;
    }
    const token = String(req.query.token || '');
    const redeemed = token ? stores.pairing.redeem(token) : null;
    if (redeemed) {
      // 加映 4：已有有效会话直接复用（刷新长效 cookie），不再每次扫码新建——
      // 同一手机重复扫码/重开配对链接不应堆积设备记录。
      const existingToken = readCookieToken(req) || bearerToken(req);
      const existingSession = existingToken ? stores.sessions.authenticate(existingToken) : null;
      if (existingSession) {
        issueSessionCookie(req, res, existingToken);
      } else {
        const { sessionToken } = stores.sessions.createSession({ name: `桌面投影-${pairShortId()}` });
        issueSessionCookie(req, res, sessionToken);
      }
    }
    const hasCookie = String(req.headers.cookie || '').includes('gw_session=');
    if (!redeemed && !hasCookie) {
      res.redirect('/m');
      return;
    }
    res.redirect('/');
  });

  // 会话鉴权：公开面（静态页 / 配对 / 健康 / app 兑换入口）之外的一切端点
  // ——包括挂载的全量 /api/* 路由——都必须持有效会话（D4）。
  app.use(sessionAuth);

  // ── BLOCK-85 格物联邦（D1/D3）：对端格物经此端点握手本机节点能力 ──
  // 会话门内（配对后才能读）；指挥席用兑换到的会话 Bearer 调用。
  // BLOCK-88 P1：回显本会话落档的工程师声明身份——指挥席可断言对端记录的
  // 署名与自己所发一致（契约面），被访端面板「协作成员」同源读取。
  const os = require('node:os');
  app.get('/federation/api/health', (req, res) => {
    let executors = { r: false, python: false };
    try {
      const { getExecutor } = require('../../shared-backend/executors');
      for (const lang of ['r', 'python']) {
        const executor = getExecutor(lang);
        executors[lang] = Boolean(executor && executor.binPath && fs.existsSync(executor.binPath));
      }
    } catch { /* 执行器探测失败诚实报 false */ }
    res.json({
      ok: true,
      service: 'petri-federation',
      protocol: 1,
      node: {
        name: os.hostname(),
        platform: process.platform,
        arch: process.arch,
      },
      petriVersion: process.env.npm_package_version || '0.0.1-rc.7',
      executors,
      session: {
        name: req.mobileSession?.name || null,
        identity: req.mobileSession?.identity || null,
      },
    });
  });

  // ── BLOCK-88 P3（D4）：访客列自己的被授权项目（「A 能看到 B 的哪些项目」）──
  // 会话门内；身份键=本会话 P1 落档的工程师声明署名；附项目名供 delegate 选参。
  const grantsMod = require('../../shared-backend/federation-grants');
  app.get('/federation/api/granted-projects', (req, res) => {
    const identity = req.mobileSession?.identity;
    if (!identity || !identity.displayName) {
      res.json({ ok: true, projects: [], note: 'session_without_engineer_identity' });
      return;
    }
    const grants = grantsMod.grantedProjectsFor(dataDir, identity.displayName);
    let projects = grants;
    try {
      const db = require('../db').getDatabase();
      const names = new Map(db.prepare('SELECT id, name FROM projects').all().map((r) => [r.id, r.name]));
      projects = grants.map((g) => ({ projectId: g.projectId, projectName: names.get(g.projectId) || null }));
    } catch { /* 项目名附不上时诚实降级为纯 id */ }
    res.json({ ok: true, engineer: identity.displayName, projects });
  });

  // ── BLOCK-85 P4 投影终端（node-pty 会话 + SSE 下行 / POST 上行）──
  // 会话门内；会话驻留 core 进程，手机锁屏断流回来可重连重放（环形缓冲）。
  const terminalEngine = require('../federation-terminal').createTerminalEngine();

  app.get('/m/api/terminal', (_req, res) => {
    if (!terminalEngine.available) {
      res.status(501).json({ ok: false, error: 'terminal_unavailable', message: terminalEngine.reason });
      return;
    }
    res.json({ ok: true, sessions: terminalEngine.list() });
  });

  app.post('/m/api/terminal/start', express.json({ limit: '8kb' }), (req, res) => {
    if (!terminalEngine.available) {
      res.status(501).json({ ok: false, error: 'terminal_unavailable', message: terminalEngine.reason });
      return;
    }
    const result = terminalEngine.start({ cwd: req.body?.cwd, ssh: req.body?.ssh });
    res.status(result.error ? 400 : 200).json({ ok: !result.error, ...result });
  });

  app.post('/m/api/terminal/:id/input', express.json({ limit: '64kb' }), (req, res) => {
    const session = terminalEngine.getSession(req.params.id);
    if (!session) {
      res.status(404).json({ ok: false, error: 'session_not_found' });
      return;
    }
    const data = req.body?.data;
    if (typeof data !== 'string') {
      res.status(400).json({ ok: false, error: 'data_required' });
      return;
    }
    res.json(terminalEngine.write(session, data));
  });

  app.post('/m/api/terminal/:id/resize', express.json({ limit: '2kb' }), (req, res) => {
    const session = terminalEngine.getSession(req.params.id);
    if (!session) {
      res.status(404).json({ ok: false, error: 'session_not_found' });
      return;
    }
    res.json(terminalEngine.resize(session, req.body?.cols, req.body?.rows));
  });

  app.post('/m/api/terminal/:id/kill', (req, res) => {
    const session = terminalEngine.getSession(req.params.id);
    if (!session) {
      res.status(404).json({ ok: false, error: 'session_not_found' });
      return;
    }
    res.json(terminalEngine.kill(session));
  });

  // SSE 下行：连接即重放环形缓冲，此后实时推送；terminal:exit 后保留至 TTL。
  app.get('/m/api/terminal/:id/stream', (req, res) => {
    const session = terminalEngine.getSession(req.params.id);
    if (!session) {
      res.status(404).json({ ok: false, error: 'session_not_found' });
      return;
    }
    res.setHeader('Content-Type', 'text/event-stream; charset=utf-8');
    res.setHeader('Cache-Control', 'no-cache, no-transform');
    res.setHeader('Connection', 'keep-alive');
    res.flushHeaders && res.flushHeaders();
    const send = (event, payload) => {
      res.write(`event: ${event}\ndata: ${JSON.stringify(payload)}\n\n`);
    };
    const replay = terminalEngine.ringText(session);
    if (replay) send('terminal:replay', { data: replay, exited: session.exited });
    const unsubscribe = terminalEngine.subscribe(session, send);
    if (session.exited) send('terminal:exit', { exitCode: session.exitCode });
    const ping = setInterval(() => {
      try { res.write(': ping\n\n'); } catch { /* closed */ }
    }, 15_000);
    req.on('close', () => {
      clearInterval(ping);
      unsubscribe();
    });
  });

  // P2 控制面窄口：批准决定（进程内直调 db.ackToolJob，权限不放大）。
  require('./control').registerMobileControl(app);

  // 既有读面/控制路由模块注入（conversations / agent tasks / SSE / tools）。
  if (typeof mountRoutes === 'function') {
    mountRoutes(app);
  }

  // 桌面投影：全量路由注册表（异步注册，落在 sessionAuth 之后=会话门内）
  // + SPA 静态服务 + 客户端路由 fallback + 身份/后端垫片注入。
  if (desktopAvailable()) {
    try { require('../routes')(app); } catch (e) {
      console.warn('[mobile-gateway] full route registry failed:', e && e.message);
    }
    const shimArr = [
      '<script>window.__errs=[];window.addEventListener("error",function(e){window.__errs.push(String(e&&e.message||e))});</script>',
      '<script>document.documentElement.setAttribute("data-projection","1");</script>',
      '<script>(function(){',
      '  var base={backendConfig:{rApiBase:"/api"},isDesktop:true,platform:"win32",__projection:true};',
      '  var mk=function(){var f=function(){return p;};var p=new Proxy(f,{get:function(t,k){if(k===Symbol.toPrimitive){return function(){return "";};}if(k==="then"){return function(res,rej){return Promise.resolve(undefined).then(res,rej);};}return p;},apply:function(){return p;}});return p;};',
      '  window.petriDesktop=new Proxy(base,{get:function(t,k){if(k in t){return t[k];}return mk();}});',
      '})();</script>',
    ];
    const shim = shimArr.join('');
    // 每次请求读盘注入（index.html 仅数 KB）：dist 重建后投影即时生效——
    // 曾因启动时一次性缓存旧 index.html，引用已删除的旧 hash 资产 → 手机
    // 投影停留在旧界面/白屏（BLOCK-85 双真机实测抓真）。
    const sendIndex = (res) => {
      try {
        res.setHeader('Cache-Control', 'no-cache, no-store, must-revalidate');
        const injected = readFileSync(desktopIndex, 'utf8').replace('<head>', '<head>' + shim);
        res.type('html').send(injected);
      } catch {
        res.status(404).send('dist index missing (npm run build:spa)');
      }
    };
    // dist 哈希资产内容寻址：永久缓存（Vite 不可达落 dist 时刷新不再全量重拉）
    app.use(express.static(desktopDist, {
      index: false,
      setHeaders: (res, filePath) => {
        if (filePath.includes(`${path.sep}assets${path.sep}`)) {
          res.setHeader('Cache-Control', 'public, max-age=31536000, immutable');
        }
      },
    }));
    // BLOCK-87 — dev 模式投影走 Vite 热更源（源码改动手机即时跟随，无需手动
    // build:spa；生产/无 Vite 时走 dist）。窄代理：只接管 /（首页 HTML，注垫片）
    // 与 Vite 专有路径（/@、/node_modules/、/src/）；/assets 构建产物不误代理。
    // BLOCK-87 实测性能修复（用户「点击频繁时刷新很慢」）：①条件请求透传——
    // 原实现对所有代理响应强制 no-store，手机每次刷新都全量重拉整张模块图
    // （数百模块 × 隧道 RTT）；现透传 If-None-Match/If-Modified-Since 让 Vite
    // 的 ETag 304 生效，未变更模块只回 tiny 304。②文本模块 gzip——隧道流量
    // 降 ~70%。HTML 仍 no-store（垫片注入必须即时新鲜）。
    const viteDevBase = process.env.PETRI_RENDERER_DEV_URL || 'http://127.0.0.1:3000';
    const isViteOwnedPath = (p) => p === '/' || p.startsWith('/@') || p.startsWith('/node_modules/') || p.startsWith('/src/');
    const acceptsGzip = (req) => String(req.headers['accept-encoding'] || '').includes('gzip');
    const isTextLike = (contentType) => /text\/|application\/(javascript|json|xml|wasm)/.test(contentType);
    app.get('*', async (req, res, next) => {
      if (req.path.startsWith('/api/') || req.path.startsWith('/m') || req.path === '/pair') return next();
      if (!isViteOwnedPath(req.path)) return next();
      try {
        const conditional = {};
        if (req.headers['if-none-match']) conditional['If-None-Match'] = req.headers['if-none-match'];
        if (req.headers['if-modified-since']) conditional['If-Modified-Since'] = req.headers['if-modified-since'];
        const upstream = await fetch(viteDevBase + req.originalUrl, {
          headers: { Accept: req.headers.accept || '*/*', ...conditional },
          signal: AbortSignal.timeout(8000),
        });
        const contentType = upstream.headers.get('content-type') || '';
        if (upstream.status === 304) {
          res.setHeader('Cache-Control', 'no-cache');
          const etag = upstream.headers.get('etag');
          if (etag) res.setHeader('ETag', etag);
          res.status(304).end();
          return;
        }
        const buf = Buffer.from(await upstream.arrayBuffer());
        res.setHeader('Content-Type', contentType);
        if (contentType.includes('text/html')) {
          res.setHeader('Cache-Control', 'no-cache, no-store');
          res.status(upstream.status).send(buf.toString('utf8').replace('<head>', '<head>' + shim));
          return;
        }
        res.setHeader('Cache-Control', upstream.headers.get('cache-control') || 'no-cache');
        const etag = upstream.headers.get('etag');
        if (etag) res.setHeader('ETag', etag);
        if (acceptsGzip(req) && isTextLike(contentType) && buf.length > 1024) {
          const gz = zlib.gzipSync(buf);
          res.setHeader('Content-Encoding', 'gzip');
          res.setHeader('Content-Length', String(gz.length));
          res.status(upstream.status).end(gz);
          return;
        }
        res.status(upstream.status).send(buf);
        return;
      } catch { /* Vite 不可达 → 落回 dist */ }
      next();
    });
    // SPA 客户端路由 fallback：非 /api、/m、/pair 的 GET 一律回 index.html
    app.get('*', (req, res, next) => {
      if (req.path.startsWith('/api/') || req.path.startsWith('/m') || req.path === '/pair') return next();
      sendIndex(res);
    });
  }

  // eslint-disable-next-line no-unused-vars
  app.use((error, req, res, next) => {
    res.status(500).json({ ok: false, error: 'mobile_gateway_error', message: '移动网关内部错误' });
  });

  return { app, stores, audit, desktopAvailable };
}

/**
 * 按配置/env 启动。默认关闭 → 返回 { started:false }（additive 红线）。
 */
function startMobileGateway({ dataDir, mountRoutes, env = process.env } = {}) {
  if (!resolveEnabled({ dataDir, env })) {
    return { started: false, reason: 'disabled' };
  }
  const port = resolvePort({ dataDir, env });
  const config = readConfig(dataDir);
  const { app, stores } = buildMobileGateway({ dataDir, mountRoutes });
  const server = app.listen(port, config.bind, () => {
    console.log(`📱 [mobile-gateway] listening on ${config.bind}:${port} (LAN: ${(lanAddresses()).join(', ') || 'N/A'})`);
  });
  server.on('error', (error) => {
    console.warn(`[mobile-gateway] listen failed on :${port}:`, error.message);
  });
  return {
    started: true,
    port,
    bind: config.bind,
    server,
    stores,
    lanAddresses: lanAddresses(),
    close: () => new Promise((resolve) => server.close(resolve)),
  };
}

module.exports = {
  buildMobileGateway,
  startMobileGateway,
  createRateLimiter,
  lanAddresses,
  readConfig,
};

'use strict';

/**
 * BLOCK-70 P3 — aliyun 反向隧道管理（A2 真远程段）。
 *
 * 桌面端主动发起出站 `ssh -N -R 127.0.0.1:<remote>:127.0.0.1:<local> <host>`，
 * 钉在远端回环（免 GatewayPorts、不开任何入站端口，D7/BLOCK-57 安全哲学同门）。
 * ssh 只用 ~/.ssh/config 的 Host 别名解析（key-only，BatchMode 失败即败）。
 *
 * 状态机：disabled → connecting → connected（进程存活超过 stableMs 视为已建立，
 * ExitOnForwardFailure 保证端口冲突会立刻退出而非假连）→ 进程退出 →
 * reconnecting（固定退避序列重试）。
 *
 * 诚实边界：connected 是「转发已建立」的强启发（ExitOnForwardFailure + 存活），
 * 不是端到端探活；端到端验证走 aliyun 回环 curl（见 block70-tunnel-live.mjs）。
 */

const fs = require('node:fs');
const path = require('node:path');
const { spawn: cpSpawn, spawnSync: cpSpawnSync } = require('node:child_process');

const TUNNEL_CONFIG_VERSION = 1;
const RECONNECT_BACKOFF_MS = Object.freeze([1000, 2000, 5000, 10000, 30000]);
const STABLE_CONNECTED_MS = 10 * 1000;
const HOST_PATTERN = /^[A-Za-z0-9._-]{1,120}$/;

function tunnelConfigPath(dataDir) {
  return path.join(dataDir, 'mobile', 'tunnel.json');
}

/**
 * 纯函数：从进程清单里挑出「命令行含本隧道签名」的孤儿 ssh pid。
 * entries = [{pid, commandline}]；excludePids = 当前管理器在册孩子，绝杀不得。
 */
function selectStaleSshPids(entries, signature, excludePids = []) {
  const exclude = new Set(excludePids);
  return (Array.isArray(entries) ? entries : [])
    .filter((entry) => entry
      && Number.isInteger(entry.pid) && entry.pid > 0
      && !exclude.has(entry.pid)
      && typeof entry.commandline === 'string'
      && entry.commandline.includes(signature))
    .map((entry) => entry.pid);
}

/**
 * 跨代清场：历史服务进程被树杀逃逸后遗留的孤儿 ssh 会一直占用远端端口，
 * 新隧道永远 bind 失败互抖——spawn 前按「-R 签名」把所有孤儿清光。
 * 只按精确签名匹配（remote:local 端口对），绝不误伤别的 ssh 用途。
 */
function killStaleTunnelProcesses(dataDir, config, excludePids = []) {
  const signature = `127.0.0.1:${config.remotePort}:127.0.0.1:${config.localPort}`;
  try {
    let entries = [];
    if (process.platform === 'win32') {
      // 随包 .ps1：免 EncodedCommand/引号转义（BLOCK-76 教训：内联 PS 必炸）
      const psPath = path.join(__dirname, 'list-ssh-pids.ps1');
      const out = require('node:child_process').execSync(
        `powershell -NoProfile -ExecutionPolicy Bypass -File "${psPath}" "${signature}"`,
        { encoding: 'utf8', timeout: 10000, stdio: ['ignore', 'pipe', 'ignore'] });
      entries = String(out).split(/\r?\n/).filter(Boolean).map((line) => ({
        pid: Number(line.trim()),
        commandline: signature,
      }));
    } else {
      const out = require('node:child_process').execSync(
        'ps -eo pid=,args=', { encoding: 'utf8', timeout: 5000, stdio: ['ignore', 'pipe', 'ignore'] });
      entries = out.split(/\r?\n/).filter(Boolean).map((line) => {
        const match = line.match(/^\s*(\d+)\s+(.*)$/);
        return match ? { pid: Number(match[1]), commandline: match[2] } : null;
      }).filter(Boolean);
    }
    const stalePids = selectStaleSshPids(entries, signature, excludePids);
    for (const pid of stalePids) {
      try { process.kill(pid); } catch { /* 已死即目标达成 */ }
    }
    return stalePids;
  } catch {
    return [];
  }
}

function normalizeTunnelConfig(raw) {
  const host = typeof raw?.host === 'string' ? raw.host.trim() : '';
  const remotePort = Number.isInteger(raw?.remotePort) && raw.remotePort > 0 && raw.remotePort < 65536
    ? raw.remotePort : 2233;
  const localPort = Number.isInteger(raw?.localPort) && raw.localPort > 0 && raw.localPort < 65536
    ? raw.localPort : 3005;
  let publicUrl = typeof raw?.publicUrl === 'string' ? raw.publicUrl.trim() : '';
  if (publicUrl && !/^https:\/\/[A-Za-z0-9.:_-]+$/.test(publicUrl)) publicUrl = '';
  // BLOCK-87 — 中转服务器档案：配过的服务器存档，切换免重填。
  let profiles = Array.isArray(raw?.profiles) ? raw.profiles : [];
  profiles = profiles
    .map((p) => ({
      name: typeof p?.name === 'string' ? p.name.trim().slice(0, 40) : '',
      host: typeof p?.host === 'string' && HOST_PATTERN.test(p.host) ? p.host : '',
      publicUrl: typeof p?.publicUrl === 'string' && /^https:\/\/[A-Za-z0-9.:_-]+$/.test(p.publicUrl.trim()) ? p.publicUrl.trim() : '',
      remotePort: Number.isInteger(p?.remotePort) && p.remotePort > 0 && p.remotePort < 65536 ? p.remotePort : 2233,
    }))
    .filter((p) => p.name && p.host);
  const seen = new Set();
  profiles = profiles.filter((p) => (seen.has(p.name) ? false : (seen.add(p.name), true)));
  return {
    enabled: raw?.enabled === true,
    host: HOST_PATTERN.test(host) ? host : '',
    remotePort,
    localPort,
    publicUrl,
    profiles,
  };
}

function readTunnelConfig(dataDir) {
  try {
    const raw = JSON.parse(fs.readFileSync(tunnelConfigPath(dataDir), 'utf8'));
    return normalizeTunnelConfig(raw);
  } catch {
    return normalizeTunnelConfig({});
  }
}

function writeTunnelConfig(dataDir, patch = {}) {
  const next = normalizeTunnelConfig({ ...readTunnelConfig(dataDir), ...patch });
  fs.mkdirSync(path.dirname(tunnelConfigPath(dataDir)), { recursive: true });
  const tmp = `${tunnelConfigPath(dataDir)}.tmp`;
  fs.writeFileSync(tmp, `${JSON.stringify(next, null, 2)}\n`, 'utf8');
  fs.renameSync(tmp, tunnelConfigPath(dataDir));
  return next;
}

/** ssh 参数构造（独立导出便于契约测试；argv 数组，无 shell）。 */
function buildSshArgs(config) {
  return [
    'ssh', '-N', '-T',
    '-o', 'BatchMode=yes',
    '-o', 'ExitOnForwardFailure=yes',
    '-o', 'ServerAliveInterval=15',
    '-o', 'ServerAliveCountMax=3',
    '-o', 'ConnectTimeout=10',
    '-R', `127.0.0.1:${config.remotePort}:127.0.0.1:${config.localPort}`,
    config.host,
  ];
}

const managersByDataDir = new Map();

/**
 * 进程级单例：主后端的 admin REST 与 boot 钩子共享同一个隧道管理器。
 * spawnProcess 可注入（测试用假进程）。
 */
function getTunnelManager(dataDir, deps = {}) {
  const key = path.resolve(dataDir);
  let manager = managersByDataDir.get(key);
  if (!manager) {
    manager = createTunnelManager({ dataDir: key, ...deps });
    managersByDataDir.set(key, manager);
  }
  return manager;
}

function resetTunnelManagersForTest() {
  managersByDataDir.clear();
}

function createTunnelManager({
  dataDir,
  now = () => Date.now(),
  spawnProcess = (args) => require('node:child_process').spawn(args[0], args.slice(1), { stdio: 'ignore' }),
  killStale = killStaleTunnelProcesses,
  backoffSteps = RECONNECT_BACKOFF_MS,
  stableConnectedMs = STABLE_CONNECTED_MS,
} = {}) {
  let config = readTunnelConfig(dataDir);
  let child = null;
  let state = config.enabled && config.host ? 'connecting' : 'disabled';
  let stateSinceTs = now();
  let lastError = '';
  let backoffIndex = 0;
  let reconnectTimer = null;
  let stopped = true;
  // 全量跟踪：Windows 上 exit 事件偶发丢失会留下活孤儿，只杀「最后一个孩子」
  // 不够——新孩子出生前必须杀光所有旧孩子，保证任一时刻至多一条隧道。
  const liveChildren = new Set();

  function killAllTracked() {
    for (const proc of liveChildren) {
      try { proc.kill(); } catch { /* 已死 */ }
    }
    liveChildren.clear();
  }

  function setState(next) {
    state = next;
    stateSinceTs = now();
  }

  // 独立同步清场（不走可注入的 spawnProcess——那是隧道 ssh 专用 mock 点）。
  // 必须阻塞等待完成：异步清场会与正式 ssh 竞态（清场未完成新连接已抢跑绑
  // 端口失败 → 255 循环）。
  function remotePortSweep() {
    if (!config.host) return;
    try {
      cpSpawnSync('ssh', [
        '-o', 'ConnectTimeout=10', '-o', 'BatchMode=yes', config.host,
        'pid=$(ss -tlnp "sport = :' + config.remotePort + '" 2>/dev/null | grep -oP "pid=\\K[0-9]+" | head -1); if [ -n "$pid" ]; then kill "$pid"; fi; sleep 1; true',
      ], { timeout: 25_000, stdio: 'ignore' });
    } catch { /* 尽力而为 */ }
  }

  function spawnTunnel() {
    const args = buildSshArgs(config);
    setState('connecting');
    killStale(dataDir, config, [...liveChildren].map((proc) => proc.pid));
    killAllTracked();
    remotePortSweep();
    const proc = spawnProcess(args);
    child = proc;
    const startedAt = now();
    liveChildren.add(proc);
    proc.on('error', (error) => {
      lastError = String(error && error.message).slice(0, 200);
    });
    proc.on('exit', (code) => {
      liveChildren.delete(proc);
      if (child === proc) child = null;
      if (stopped || !config.enabled) return;
      // Windows 上 exit 事件可能迟到/乱序：只要还有任一活孩子（哪怕不是当前
      // 指针指向的），说明隧道在它手里正常工作，绝不能触发重连去杀它。
      if (liveChildren.size > 0) return;
      lastError = `ssh exited (code=${code == null ? 'signal' : code})`;
      setState('reconnecting');
      const delay = backoffSteps[Math.min(backoffIndex, backoffSteps.length - 1)];
      backoffIndex += 1;
      reconnectTimer = setTimeout(() => {
        reconnectTimer = null;
        if (!stopped && config.enabled && liveChildren.size === 0) spawnTunnel();
      }, delay);
      if (reconnectTimer.unref) reconnectTimer.unref();
    });
  }

  function tick() {
    // connected 判定：进程存活超过 stableConnectedMs（配合 ExitOnForwardFailure）。
    if (state === 'connecting' && child && now() - stateSinceTs >= stableConnectedMs) {
      setState('connected');
      backoffIndex = 0;
    }
  }

  const manager = {
    /** 读取状态（admin REST 读取时顺带推进状态机）。 */
    status() {
      tick();
      return {
        configured: Boolean(config.host),
        enabled: config.enabled,
        state,
        host: config.host,
        remotePort: config.remotePort,
        localPort: config.localPort,
        publicUrl: config.publicUrl,
        lastError,
        pid: child ? child.pid : null,
        stateSinceTs,
      };
    },

    getConfig() {
      return { ...config };
    },

    /** 应用新配置：写盘 + 原子切换（先停旧进程再按新配置拉起）。 */
    apply(nextPatch) {
      this.stop();
      config = writeTunnelConfig(dataDir, nextPatch);
      lastError = '';
      backoffIndex = 0;
      if (config.enabled && config.host) {
        stopped = false;
        setState('connecting');
        spawnTunnel();
      } else {
        stopped = true;
        setState('disabled');
      }
      return this.status();
    },

    /** boot 恢复：按已持久化配置拉起（不重写盘）。 */
    startIfEnabled() {
      config = readTunnelConfig(dataDir);
      if (!config.enabled || !config.host) {
        stopped = true;
        setState('disabled');
        return this.status();
      }
      stopped = false;
      setState('connecting');
      spawnTunnel();
      return this.status();
    },

    stop() {
      stopped = true;
      if (reconnectTimer) { clearTimeout(reconnectTimer); reconnectTimer = null; }
      killAllTracked();
      child = null;
    },
  };

  if (config.enabled && config.host) {
    stopped = false;
    setState('connecting');
    spawnTunnel();
  } else {
    stopped = true;
    setState('disabled');
  }

  return manager;
}

module.exports = {
  TUNNEL_CONFIG_VERSION,
  RECONNECT_BACKOFF_MS,
  STABLE_CONNECTED_MS,
  HOST_PATTERN,
  tunnelConfigPath,
  normalizeTunnelConfig,
  readTunnelConfig,
  writeTunnelConfig,
  buildSshArgs,
  selectStaleSshPids,
  killStaleTunnelProcesses,
  getTunnelManager,
  resetTunnelManagersForTest,
  createTunnelManager,
};

/**
 * Petri Feishu Realtime Notifier
 *
 * Sends realtime notifications to the Feishu group via the same webhook used by
 * the daily digest. Designed to be:
 *   - Fail-silent (a webhook outage NEVER takes down the main service)
 *   - Deduped (same alert key within DEDUPE_WINDOW_MS only sent once)
 *   - Easy to gate via env var (FEISHU_REALTIME_ENABLED=false to disable)
 *
 * Usage:
 *   const notify = require('./notify-feishu');
 *   notify.toolJobFailed({jobId, toolId, username, error, durationMs});
 *   notify.smokeTest({ok: false, summary: '5/5 ✓', details: '...', duration: 12345});
 *   notify.custom({title, lines, template: 'red'});
 */

const https = require('https');
const http = require('http');

// ---- Config (read at first use, refresh per env change is not needed in pm2) ----
const WEBHOOK_URL = process.env.ALERT_WEBHOOK || '';
const ENABLED = (process.env.FEISHU_REALTIME_ENABLED || 'true').toLowerCase() !== 'false';
const SITE_URL = process.env.PETRI_SITE_URL || 'https://petri.com';
const DEDUPE_WINDOW_MS = parseInt(process.env.NOTIFY_DEDUPE_WINDOW_MS || '300000', 10); // 5 min default

// ---- Dedupe cache (in-process; pm2 restart = reset) ----
const _dedupe = new Map(); // key -> lastSentMs
const _MAX_DEDUPE_SIZE = 500;

function _shouldSkip(key) {
  if (!key) return false;
  const now = Date.now();
  const last = _dedupe.get(key);
  if (last && now - last < DEDUPE_WINDOW_MS) return true;
  _dedupe.set(key, now);
  // simple LRU pruning
  if (_dedupe.size > _MAX_DEDUPE_SIZE) {
    const cutoff = now - DEDUPE_WINDOW_MS * 2;
    for (const [k, t] of _dedupe.entries()) {
      if (t < cutoff) _dedupe.delete(k);
    }
  }
  return false;
}

// ---- Low-level send ----
function _send(payload) {
  if (!ENABLED) return;
  if (!WEBHOOK_URL) return;
  let url;
  try { url = new URL(WEBHOOK_URL); } catch { return; }
  const body = JSON.stringify(payload);
  const lib = url.protocol === 'http:' ? http : https;
  const req = lib.request({
    hostname: url.hostname,
    port: url.port || (url.protocol === 'http:' ? 80 : 443),
    path: url.pathname + url.search,
    method: 'POST',
    headers: {'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body)},
    timeout: 5000,
  }, (res) => {
    let buf = '';
    res.on('data', (c) => { buf += c.toString(); });
    res.on('end', () => {
      // Surface non-success responses (e.g. 19024 Key Words Not Found, 19002 invalid sign)
      // in pm2 logs so future webhook misconfig is debuggable.
      try {
        const j = JSON.parse(buf);
        if (j.code && j.code !== 0) {
          console.warn('[notify-feishu] webhook non-success:', j.code, j.msg, '— payload title:', payload.card?.header?.title?.content || '<no card>');
        }
      } catch {}
    });
  });
  req.on('error', (e) => { console.warn('[notify-feishu] send error:', e.message); });
  req.on('timeout', () => { try { req.destroy(); } catch {} });
  req.write(body);
  req.end();
}

// ---- Public: custom card with title + lines ----
//   template: 'green' | 'blue' | 'orange' | 'red' | 'wathet' | 'turquoise' | 'purple' | 'indigo' | 'violet' | 'carmine'
function custom({title, lines = [], template = 'blue', dedupeKey, button}) {
  if (dedupeKey && _shouldSkip(dedupeKey)) return;
  // Feishu bot security: inject the required keyword "Petri" if absent.
  // Without this, the webhook returns 19024 "Key Words Not Found" and silently drops the message.
  const KEYWORD = 'Petri';
  let safeTitle = title;
  if (!String(title).includes(KEYWORD)) {
    safeTitle = `[${KEYWORD}] ${title}`;
  }
  const elements = [];
  if (lines.length) {
    elements.push({tag: 'div', text: {tag: 'lark_md', content: lines.join('\n')}});
  }
  if (button) {
    elements.push({tag: 'hr'});
    elements.push({
      tag: 'action',
      actions: [{
        tag: 'button',
        text: {tag: 'plain_text', content: button.label || '查看详情'},
        type: button.type || 'default',
        url: button.url,
      }],
    });
  }
  _send({
    msg_type: 'interactive',
    card: {
      config: {wide_screen_mode: true},
      header: {
        title: {tag: 'plain_text', content: safeTitle},
        template,
      },
      elements,
    },
  });
}

// ---- Public: tool job failed ----
function toolJobFailed({jobId, toolId, username, error, durationMs, stage}) {
  // Truncate noisy R errors to first meaningful line + crop to 300 chars
  const errStr = String(error || '').trim();
  const firstError = errStr.split('\n').find(l => /Error|error|Permission denied/i.test(l)) || errStr.split('\n').slice(-3).join('\n');
  const errPreview = (firstError || errStr).slice(0, 300);
  const dur = durationMs ? `${(durationMs / 1000).toFixed(1)}s` : '?';
  const stageLabel = stage ? ` · ${stage}` : '';
  custom({
    title: `🚨 工具任务失败: ${toolId}`,
    template: 'red',
    dedupeKey: `tool_failed:${toolId}:${(errPreview).slice(0, 80)}`,
    lines: [
      `**${username || '<匿名>'}**${stageLabel} · 用时 ${dur}`,
      `\`${jobId}\``,
      '',
      '```',
      errPreview,
      '```',
    ],
    button: {
      label: '管理后台',
      type: 'primary',
      url: `${SITE_URL}/admin`,
    },
  });
}

// ---- Public: smoke test result (one-shot summary at end of run) ----
function smokeTest({ok, totalCount, passCount, failCount, durationMs, failures = []}) {
  const dur = durationMs ? `${(durationMs / 1000).toFixed(1)}s` : '?';
  const lines = [
    `**${passCount}/${totalCount} 通过** · 用时 ${dur}`,
  ];
  if (!ok && failures.length) {
    lines.push('');
    lines.push('**失败明细：**');
    for (const f of failures.slice(0, 5)) {
      lines.push(`· **${f.toolId}**: ${(f.error || '').slice(0, 120)}`);
    }
    if (failures.length > 5) {
      lines.push(`· ...还有 ${failures.length - 5} 个失败`);
    }
  }
  custom({
    title: ok ? `✅ Smoke Test 全部通过` : `🟥 Smoke Test 失败 (${failCount}/${totalCount})`,
    template: ok ? 'green' : 'red',
    // No dedupe — each smoke test run should always notify
    lines,
    button: {
      label: '管理后台',
      type: ok ? 'default' : 'primary',
      url: `${SITE_URL}/admin`,
    },
  });
}

// ---- Public: simple text (for quick debug; rarely use directly) ----
function text(content) {
  _send({msg_type: 'text', content: {text: content}});
}

module.exports = {
  custom,
  toolJobFailed,
  smokeTest,
  text,
  // Exposed for testing
  _internals: {_send, _shouldSkip, _dedupe},
};

/**
 * petri-server/plugin-loader.js — 服务端插件加载器
 *
 * 桌面版 Electron 启动时通过 plugin-manager.js 加载已装插件，
 * 注册到 globalThis._petriPlugins。本模块负责：
 * 1. 读取已注册插件
 * 2. 将插件工具定义注册到工具列表
 * 3. 提供脚本路径查询（工具执行时用）
 *
 * Web 版不使用此模块（工具定义硬编码在 _data.ts + tool-scripts/）。
 */

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const logger = require('../shared-backend/logger');
const { validateResultStudioDescriptor } = require('../shared-backend/result-studio-plugin-sdk');
// BLOCK-83 D3 过渡装配：凡装载带 Result Studio descriptor 的插件，即注册科学任务确认钩子——
// 核心其余层只认钩子注册表（零 RS 插件 = 零注册 = 零确认直通）。P3/P4 生信包建仓后本装配随 scientific-task-* 迁出核心。
const { registerTaskConfirmationHook } = require('../shared-backend/task-confirmation-hooks');
let scientificTaskConfirmationHookRegistered = false;
function ensureScientificTaskConfirmationHookRegistered() {
  if (scientificTaskConfirmationHookRegistered) return;
  const { createScientificTaskConfirmationHook } = require('../shared-backend/scientific-task-confirmation');
  registerTaskConfirmationHook(createScientificTaskConfirmationHook());
  scientificTaskConfirmationHookRegistered = true;
}

// 已注册插件 Map（id → { ...meta, pluginDir, scriptPath }）
let _lastPluginsDir = null;
function _getPluginsMap() {
  if (!globalThis._petriPlugins) globalThis._petriPlugins = new Map();
  return globalThis._petriPlugins;
}

function _resolveBuiltInPluginsDir() {
  return (
    process.env.PETRI_BUILT_IN_PLUGINS_DIR ||
    path.resolve(__dirname, '..', '..', 'resources', 'built-in-plugins')
  );
}

function _getCanonicalBuiltInPlugin(pluginId, builtInDir = _resolveBuiltInPluginsDir()) {
  if (!pluginId || !builtInDir) return null;
  const pluginDir = path.join(builtInDir, pluginId);
  const pluginPath = path.join(pluginDir, 'plugin.json');
  const toolDefinitionPath = path.join(pluginDir, 'tool-definition.json');
  try {
    if (!fs.existsSync(pluginPath) || !fs.existsSync(toolDefinitionPath)) return null;
    const plugin = JSON.parse(fs.readFileSync(pluginPath, 'utf8'));
    if (plugin.sourcePolicy !== 'builtin-canonical') return null;
    return {
      ...plugin,
      id: plugin.id || pluginId,
      pluginDir,
      scriptPath: path.join(pluginDir, 'scripts'),
      _builtIn: true,
      _sourceType: 'builtin',
      _fromCanonicalBuiltIn: true,
    };
  } catch {
    return null;
  }
}

/**
 * 获取已注册的所有插件。
 */
function getAllPlugins() {
  return Array.from(_getPluginsMap().values());
}

/**
 * 获取指定插件。
 */
function getPlugin(pluginId) {
  return _getPluginsMap().get(pluginId);
}

/**
 * 检查插件是否已安装。
 */
function isPluginInstalled(pluginId) {
  return _getPluginsMap().has(pluginId);
}

/**
 * 获取工具对应的脚本路径。
 * 插件 scripts/ 目录下的脚本文件（.R / .py）。
 *
 * @param {string} toolId - 工具 ID（= 插件 ID）
 * @returns {string|null} - 脚本绝对路径
 */
function getScriptForTool(toolId) {
  const plugin = getPlugin(toolId);
  if (!plugin) return null;

  const scriptDir = plugin.scriptPath;
  if (!fs.existsSync(scriptDir)) return null;

  // 根据 language 找对应扩展名的脚本
  const ext = plugin.language === 'r' ? '.R' : '.py';
  const files = fs.readdirSync(scriptDir).filter((f) => f.endsWith(ext));

  if (files.length === 0) return null;
  // 优先找和 toolId 同名的脚本
  const match = files.find((f) => f.replace(ext, '') === toolId);
  return path.join(scriptDir, match || files[0]);
}

/**
 * 获取插件的 MCP inputSchema（PL-001 配套）。
 * 工具入口在 _runPluginScript 之前调用 validateToolArgs(name, schema, args)，
 * 该函数从 tool-definition.json 的 inputs[] 派生出 JSON Schema，
 * 包含 type / required / minimum / maximum / enum。
 *
 * 插件 inputs[] 中每个元素的扩展字段：
 *   - type: 'number' | 'integer' | 'string' | 'enum'
 *   - min / max: 数值边界（number / integer 类型时生效）
 *   - enum: string[]（type='enum' 时必填）
 *   - required: boolean
 *   - default: 默认值
 *
 * @param {string} toolId - 工具 ID
 * @returns {object|null} - JSON Schema { type: 'object', properties: {...}, required: [...] }
 */
function getInputSchema(toolId) {
  const def = getToolDefinition(toolId);
  if (!def || !Array.isArray(def.inputs)) return null;
  return _inputsToInputSchema(def.inputs);
}

/**
 * 获取插件的工具定义（tool-definition.json）。
 */
function getToolDefinition(pluginId) {
  const plugin = getPlugin(pluginId);
  if (!plugin) return null;

  const defPath = path.join(plugin.pluginDir, 'tool-definition.json');
  try {
    return JSON.parse(fs.readFileSync(defPath, 'utf8'));
  } catch {
    return null;
  }
}

function _walkFiles(dir) {
  const out = [];
  if (!dir || !fs.existsSync(dir)) return out;
  const stack = [dir];
  while (stack.length) {
    const current = stack.pop();
    for (const entry of fs.readdirSync(current, { withFileTypes: true })) {
      const full = path.join(current, entry.name);
      if (entry.isDirectory()) stack.push(full);
      else if (entry.isFile()) out.push(full);
    }
  }
  return out.sort();
}

function _hashFileContents(hash, filePath) {
  try {
    hash.update(filePath);
    hash.update('\0');
    hash.update(fs.readFileSync(filePath));
    hash.update('\0');
  } catch (e) {
    hash.update(`[missing:${filePath}]`);
    hash.update('\0');
  }
}

function computePluginFingerprint(plugin, def) {
  if (!plugin || !plugin.pluginDir) return null;
  const hash = crypto.createHash('sha256');
  _hashFileContents(hash, path.join(plugin.pluginDir, 'plugin.json'));
  _hashFileContents(hash, path.join(plugin.pluginDir, 'tool-definition.json'));
  if (plugin.scriptPath) {
    for (const file of _walkFiles(plugin.scriptPath)) {
      _hashFileContents(hash, file);
    }
  }
  if (def) {
    hash.update(JSON.stringify({
      id: def.id || plugin.id || null,
      version: def.version || plugin.version || null,
      language: def.language || plugin.language || null,
    }));
  }
  return hash.digest('hex');
}

function _normalizeArtifactHint(output, index) {
  if (!output || typeof output !== 'object') return null;
  const id = String(output.id || output.name || `artifact_${index + 1}`);
  const rawType = String(output.type || output.kind || 'file').toLowerCase();
  const type =
    rawType === 'image' || rawType === 'pdf'
      ? 'plot'
      : rawType === 'dataframe'
        ? 'table'
        : ['plot', 'table', 'text', 'json', 'html', 'file', 'log'].includes(rawType)
          ? rawType
          : 'file';
  const label = output.label || output.title || id;
  return {
    id,
    type,
    title: output.title || label,
    label,
    description: output.description || output.hint || '',
    preview: output.preview !== false,
    download: output.download !== false,
    required: output.required !== false,
  };
}

function _normalizeFailureMode(mode, index) {
  if (!mode) return null;
  if (typeof mode === 'string') {
    return {
      code: mode,
      title: mode,
      description: '',
      recoverable: true,
      suggestedFix: '',
    };
  }
  if (typeof mode !== 'object') return null;
  const code = String(mode.code || mode.id || `failure_${index + 1}`);
  return {
    code,
    title: mode.title || mode.label || code,
    description: mode.description || mode.reason || '',
    recoverable: mode.recoverable !== false,
    suggestedFix: mode.suggestedFix || mode.fix || mode.repairHint || '',
    detect: mode.detect || mode.detectWhen || '',
  };
}

const GLOBAL_ARTIFACT_FAILURE_MODES = [
  {
    code: 'required_artifact_missing',
    title: '必需结果产物缺失',
    description: '工具运行结束，但声明为 required 的结果文件没有真实生成。',
    recoverable: true,
    suggestedFix: '检查运行日志和输出约定，修复工具后重新执行。',
    detect: 'required artifact missing|was not produced',
  },
  {
    code: 'required_artifact_empty',
    title: '必需结果产物为空',
    description: '工具生成了结果文件名，但文件为空或不可读取。',
    recoverable: true,
    suggestedFix: '检查运行日志、磁盘空间和写文件逻辑后重新执行。',
    detect: 'required artifact empty|empty or unreadable',
  },
  {
    code: 'artifact_type_mismatch',
    title: '结果产物类型不匹配',
    description: 'manifest 声明类型与真实文件扩展名不一致。',
    recoverable: true,
    suggestedFix: '修正 manifest 类型，或输出符合声明格式的文件。',
    detect: 'artifact type mismatch|declared as|detected as',
  },
  {
    code: 'artifact_missing',
    title: '可选结果产物缺失',
    description: 'manifest 声明了可选产物，但磁盘中不存在该文件。',
    recoverable: true,
    suggestedFix: '移除失效声明或重新生成可选产物。',
    detect: 'declared artifact missing|does not exist on disk',
  },
  {
    code: 'artifact_empty',
    title: '可选结果产物为空',
    description: '可选结果文件为空或不可读取。',
    recoverable: true,
    suggestedFix: '移除空产物或重新生成。',
    detect: 'declared artifact empty|empty or unreadable',
  },
];

/**
 * PetriPluginManifest v1 normalized view.
 *
 * Compatibility note:
 * - Existing plugins still ship `plugin.json` for install/runtime metadata and
 *   `tool-definition.json` for form/output metadata.
 * - Harness consumes this merged manifest so prompt/runtime logic no longer
 *   depends on two partially-overlapping files.
 */
function normalizePluginManifest(plugin, def) {
  if (!plugin) return null;
  const toolDef = def || {};
  const id = String(toolDef.id || plugin.id || '');
  if (!id) return null;
  const language = toolDef.language || plugin.language || null;
  const outputs = Array.isArray(toolDef.outputs) ? toolDef.outputs : [];
  const failureModes = Array.isArray(toolDef.failureModes)
    ? toolDef.failureModes
    : Array.isArray(plugin.failureModes)
      ? plugin.failureModes
      : [];
  const mergedFailureModes = [...failureModes];
  const failureCodes = new Set(mergedFailureModes.map((mode) => mode && mode.code).filter(Boolean));
  for (const mode of GLOBAL_ARTIFACT_FAILURE_MODES) {
    if (!failureCodes.has(mode.code)) mergedFailureModes.push(mode);
  }
  const resultStudioValidation = validateResultStudioDescriptor({
    plugin,
    toolDefinition: toolDef,
    pluginDir: plugin.pluginDir || null,
  });
  if (resultStudioValidation.valid) ensureScientificTaskConfirmationHookRegistered();
  return {
    pluginManifestVersion: Number(plugin.pluginManifestVersion || toolDef.pluginManifestVersion || 1),
    id,
    title: toolDef.title || plugin.title || id,
    subtitle: toolDef.subtitle || '',
    description: toolDef.description || plugin.description || '',
    category: toolDef.category || plugin.category || 'analysis',
    type: plugin.type || toolDef.type || 'analysis-plugin',
    version: plugin.version || toolDef.version || null,
    language,
    runtime: plugin.runtime || {},
    packages: plugin.packages || {},
    builtAgainst: plugin.builtAgainst || {},
    supportedPlatforms: plugin.supportedPlatforms || plugin.platform || [],
    platform: plugin.platform || plugin.supportedPlatforms || [],
    inputs: Array.isArray(toolDef.inputs) ? toolDef.inputs : [],
    outputs,
    artifactSchemaVersion: 1,
    artifacts: outputs.map(_normalizeArtifactHint).filter(Boolean),
    examples: Array.isArray(toolDef.examples)
      ? toolDef.examples
      : Array.isArray(plugin.examples)
        ? plugin.examples
        : [],
    failureModes: mergedFailureModes.map(_normalizeFailureMode).filter(Boolean),
    estimatedMinutes: toolDef.estimatedMinutes || plugin.estimatedMinutes || null,
    // BLOCK-83 D4：目录投影所需的表现层字段透传（additive；缺省由前端兜底）。
    color: toolDef.color || plugin.color || null,
    tutorialUrl: toolDef.tutorialUrl || plugin.tutorialUrl || null,
    demoDataUrl: toolDef.demoDataUrl || plugin.demoDataUrl || null,
    comingSoon: toolDef.comingSoon === true || plugin.comingSoon === true,
    // Optional Result Studio descriptor. Absence is meaningful: RS4 must then
    // classify unknown parameter edits as scientific recomputation.
    resultStudio: resultStudioValidation.valid ? resultStudioValidation.descriptor : null,
    resultStudioValidation: {
      valid: resultStudioValidation.valid,
      errors: resultStudioValidation.errors,
      warnings: resultStudioValidation.warnings,
    },
    execution: {
      scriptPath: plugin.scriptPath || null,
      pluginDir: plugin.pluginDir || null,
      scriptFingerprint: computePluginFingerprint(plugin, toolDef),
      installedFingerprint: plugin._installedFingerprint || null,
      manifestDrift: !!plugin._manifestDrift,
      driftReason: plugin._driftReason || null,
      demoDataDir: plugin.pluginDir
        ? (fs.existsSync(path.join(plugin.pluginDir, 'demo-data'))
            ? path.join(plugin.pluginDir, 'demo-data')
            : null)
        : null,
    },
    legacy: {
      pluginJson: plugin,
      toolDefinition: toolDef,
    },
  };
}

function getPluginManifest(pluginId) {
  const plugin = getPlugin(pluginId);
  if (!plugin) return null;
  return normalizePluginManifest(plugin, getToolDefinition(pluginId));
}

function getAllPluginManifests() {
  return getAllPlugins().map((plugin) => getPluginManifest(plugin.id)).filter(Boolean);
}

/**
 * 获取所有已装插件的工具定义列表（供前端工具列表渲染）。
 */
function getAllToolDefinitions() {
  const defs = [];
  for (const plugin of getAllPlugins()) {
    const def = getToolDefinition(plugin.id);
    if (def) {
      const manifest = normalizePluginManifest(plugin, def);
      defs.push({
        ...def,
        _pluginVersion: plugin.version,
        _language: plugin.language,
        _installed: true,
        _manifest: manifest,
        failureModes: manifest.failureModes,
      });
    }
  }
  return defs;
}

/**
 * 把 tool-definition.json 的 inputs[] 数组转成 MCP inputSchema
 * （JSON Schema object：{type:'object', properties:{}, required:[]}）。
 * MCP 工具调用的参数契约用 inputSchema，Petri 内部用 inputs[]。
 */
function _inputsToInputSchema(inputs) {
  const properties = {};
  const required = [];
  for (const inp of inputs || []) {
    if (!inp || !inp.id) continue;
    // 支持 number / integer / enum / string / boolean / file / directory
    let schemaType;
    if (inp.type === 'number' || inp.type === 'integer') {
      schemaType = inp.type;
    } else if (inp.type === 'enum') {
      schemaType = 'string';
    } else {
      schemaType = 'string';
    }
    const schema = { type: schemaType };
    if (inp.label) schema.description = inp.label;
    if (inp.hint) schema.description = (schema.description ? schema.description + '。' : '') + inp.hint;
    if (inp.default !== undefined) schema.default = inp.default;
    // PL-001 配套：number / integer 边界
    if (typeof inp.min === 'number') schema.minimum = inp.min;
    if (typeof inp.max === 'number') schema.maximum = inp.max;
    // enum 取值
    if (inp.type === 'enum' && Array.isArray(inp.enum)) {
      schema.enum = inp.enum;
    } else if (Array.isArray(inp.enum)) {
      schema.enum = inp.enum;
    }
    properties[inp.id] = schema;
    if (inp.required) required.push(inp.id);
  }
  return { type: 'object', properties, required };
}

/**
 * MCP 工具列表薄封装：把已装插件转成 MCP tools/list 格式。
 * 返回 [{name, description, inputSchema}]，name = 插件 id。
 */
function listToolsForMCP() {
  return getAllPluginManifests().map((manifest) => ({
    name: manifest.id,
    description: manifest.description || manifest.title || manifest.id,
    inputSchema: _inputsToInputSchema(manifest.inputs),
    outputSchema: {
      type: 'object',
      artifactSchemaVersion: manifest.artifactSchemaVersion,
      artifacts: manifest.artifacts,
    },
    failureModes: manifest.failureModes,
    // 透传元数据，供 callTool / Harness 执行时用
    _language: manifest.language,
    _pluginVersion: manifest.version,
    _inputs: manifest.inputs,
    _outputs: manifest.outputs,
    _manifest: {
      pluginManifestVersion: manifest.pluginManifestVersion,
      id: manifest.id,
      title: manifest.title,
      version: manifest.version,
      language: manifest.language,
      runtime: manifest.runtime,
      supportedPlatforms: manifest.supportedPlatforms,
      artifactSchemaVersion: manifest.artifactSchemaVersion,
      artifacts: manifest.artifacts,
      failureModes: manifest.failureModes,
      execution: manifest.execution,
    },
  }));
}

/**
 * 获取插件的 Demo 数据目录（如果存在）。
 */
function getDemoDataDir(pluginId) {
  const plugin = getPlugin(pluginId);
  if (!plugin) return null;

  const demoDir = path.join(plugin.pluginDir, 'demo-data');
  return fs.existsSync(demoDir) ? demoDir : null;
}

/**
 * 检查工具所需的所有包是否已安装。
 * @returns {{ ready: boolean, missing: string[], language: string }}
 */
function checkPluginPackages(pluginId) {
  const plugin = getPlugin(pluginId);
  if (!plugin) return { ready: false, missing: [], language: 'unknown', error: 'not_installed' };

  const { getExecutor } = require('../../shared-backend/executors');
  const executor = getExecutor(plugin.language);
  const missing = [];

  if (plugin.packages && plugin.packages[plugin.language]) {
    for (const pkgName of Object.keys(plugin.packages[plugin.language])) {
      if (!executor.checkPackageInstalled(pkgName)) {
        missing.push(pkgName);
      }
    }
  }

  return { ready: missing.length === 0, missing, language: plugin.language };
}

/**
 * 从磁盘重新加载所有插件（plugin-manager 安装新插件后调用）。
 */
function reloadAllPlugins() {
  // plugin-manager.js 已经注册到 globalThis._petriPlugins
  // 这里只做验证 + 日志
  const plugins = getAllPlugins();
  logger.info(`[plugin-loader] ${plugins.length} plugin(s) registered`);
  for (const p of plugins) {
    const check = checkPluginPackages(p.id);
    if (!check.ready) {
      logger.warn(`[plugin-loader] ${p.id}: missing packages: ${check.missing.join(', ')}`);
    }
  }
}

/**
 * 从磁盘扫描已装插件并注册（petri-server 子进程启动时调用）。
 *
 * 桌面版架构：plugin-manager.js 在 Electron 主进程里把插件注册到
 * globalThis._petriPlugins，但 petri-server 是独立子进程，globalThis 不共享。
 * 所以 petri-server 必须自己从 ~/Documents/Petri-Local/plugins/ 扫盘加载。
 *
 * 读取 installed.json → 逐个读 plugin.json → 注册到 _petriPlugins。
 */
function loadPluginsFromDisk(pluginsDir) {
  const os = require('os');
  const dir =
    pluginsDir ||
    _lastPluginsDir ||
    process.env.PETRI_PLUGINS_DIR ||
    path.join(os.homedir(), 'Documents', 'Petri-Local', 'plugins');
  _lastPluginsDir = dir;
  const installedFile = path.join(dir, 'installed.json');
  let installed = [];
  try {
    installed = JSON.parse(fs.readFileSync(installedFile, 'utf8'));
  } catch {
    return; // 无 installed.json = 没装过插件，正常
  }
  if (!Array.isArray(installed)) return;

  const map = _getPluginsMap();
  for (const [id, plug] of map.entries()) {
    if (plug && plug._fromInstalled) {
      map.delete(id);
    }
  }
  let count = 0;
  for (const plug of installed) {
    // Runtime 条目（type === 'runtime'）装在 runtimes/ 目录，不在 plugins/ 下，
    // 没有 plugin.json，跳过（由 plugin-manager.js 管理环境变量）
    if (plug.type === 'runtime') continue;

    const canonicalBuiltIn = _getCanonicalBuiltInPlugin(plug.id);
    if (canonicalBuiltIn) {
      const existing = map.get(plug.id);
      if (!existing || existing._sourceType !== 'development') {
        map.set(plug.id, canonicalBuiltIn);
      }
      logger.warn(
        `[plugin-loader] ${plug.id}: stale installed copy ignored; using builtin-canonical source`
      );
      continue;
    }

    const pluginDir = path.join(dir, plug.id);
    const metaPath = path.join(pluginDir, 'plugin.json');
    try {
      if (!fs.existsSync(metaPath)) {
        logger.warn(`[plugin-loader] ${plug.id}: plugin.json missing, skipping`);
        continue;
      }
      const meta = JSON.parse(fs.readFileSync(metaPath, 'utf8'));
      let toolDefinition = null;
      const toolDefPath = path.join(pluginDir, 'tool-definition.json');
      if (fs.existsSync(toolDefPath)) {
        try {
          toolDefinition = JSON.parse(fs.readFileSync(toolDefPath, 'utf8'));
        } catch (e) {
          logger.warn(`[plugin-loader] ${plug.id}: tool-definition.json parse failed: ${e.message}`);
        }
      }
      const currentFingerprint = computePluginFingerprint(
        { ...meta, pluginDir, scriptPath: path.join(pluginDir, 'scripts') },
        toolDefinition,
      );
      const installedFingerprint =
        plug.scriptFingerprint || plug.manifestFingerprint || plug.fingerprint || null;
      const manifestDrift = !!(installedFingerprint && currentFingerprint && installedFingerprint !== currentFingerprint);
      if (manifestDrift) {
        logger.warn(`[plugin-loader] ${meta.id}: fingerprint changed since install`);
      }
      map.set(meta.id, {
        ...meta,
        pluginDir,
        scriptPath: path.join(pluginDir, 'scripts'),
        _installedFingerprint: installedFingerprint,
        _currentFingerprint: currentFingerprint,
        _manifestDrift: manifestDrift,
        _driftReason: manifestDrift ? 'fingerprint_changed' : null,
        _fromInstalled: true,
      });
      count++;
    } catch (e) {
      logger.warn(`[plugin-loader] load ${plug.id} failed: ${e.message}`);
    }
  }
  if (count > 0) {
    logger.info(`[plugin-loader] loaded ${count} plugin(s) from disk`);
  }
}

/**
 * 扫描 built-in 插件目录并注册（MCP 自动发现，不依赖 install）。
 *
 * built-in 插件在 resources/built-in-plugins/<id>/ 下，manifest.json 列出所有
 * 可用插件。只注册"工具插件"（无 type 或 type 不是 runtime/figcode-card/
 * figcode-data/content-plugin），且 manifest url 是 "built-in://..." 的。
 *
 * 已在 _petriPlugins 里的（用户已装）跳过——已装版本优先。
 *
 * @param {string} builtInDir - built-in 插件目录（含 manifest.json + 各 <id>/ 子目录）
 */
function loadBuiltInPlugins(builtInDir) {
  if (!builtInDir || !fs.existsSync(builtInDir)) return;
  const manifestPath = path.join(builtInDir, 'manifest.json');
  let manifest;
  try {
    manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8'));
  } catch {
    return;
  }
  const map = _getPluginsMap();
  const NON_TOOL_TYPES = ['runtime', 'figcode-card', 'figcode-data', 'content-plugin'];
  let count = 0;
  for (const [id, meta] of Object.entries(manifest.plugins || {})) {
    // 只注册 built-in 工具插件：url 是 built-in:// 且非 runtime/figcode/content 类型
    if (!meta.url || !meta.url.startsWith('built-in://')) continue;
    if (meta.type && NON_TOOL_TYPES.includes(meta.type)) continue;
    const pluginDir = path.join(builtInDir, id);
    if (!fs.existsSync(path.join(pluginDir, 'plugin.json'))) continue;
    const canonicalBuiltIn = _getCanonicalBuiltInPlugin(id, builtInDir);
    const existing = map.get(id);
    // 普通内置插件保持历史优先级；builtin-canonical 可以替换历史安装副本，
    // 但显式开发者来源仍可覆盖，便于本地插件开发。
    if (
      existing &&
      !(canonicalBuiltIn && existing._sourceType !== 'development')
    ) {
      continue;
    }
    map.set(id, {
      ...meta,
      id,
      pluginDir,
      scriptPath: path.join(pluginDir, 'scripts'),
      _builtIn: true,
      _sourceType: 'builtin',
      ...(canonicalBuiltIn ? { sourcePolicy: 'builtin-canonical', _fromCanonicalBuiltIn: true } : {}),
    });
    count++;
  }
  if (count > 0) {
    logger.info(`[plugin-loader] loaded ${count} built-in plugin(s)`);
  }
}

// BLOCK-83 D4：默认插件源解析（与 server.js 启动路径同源），供目录投影等
// 非启动期消费者惰性加载使用，避免各处重复实现三源发现。
function resolveDefaultPluginSources() {
  const path = require('path');
  const os = require('os');
  const developmentDirs = String(process.env.PETRI_DEVELOPMENT_PLUGIN_DIRS || '')
    .split(path.delimiter)
    .map((item) => item.trim())
    .filter(Boolean);
  return {
    builtInDir:
      process.env.PETRI_BUILT_IN_PLUGINS_DIR ||
      path.resolve(__dirname, '..', '..', 'resources', 'built-in-plugins'),
    installedDir:
      process.env.PETRI_PLUGINS_DIR ||
      path.join(os.homedir(), 'Documents', 'Petri-Local', 'plugins'),
    developmentDirs,
  };
}

let _defaultSourcesLoaded = false;
function ensurePluginSourcesLoaded() {
  if (_defaultSourcesLoaded || getAllPluginManifests().length > 0) {
    _defaultSourcesLoaded = true;
    return getAllPluginManifests();
  }
  _defaultSourcesLoaded = true;
  try {
    loadPluginsFromSources(resolveDefaultPluginSources());
  } catch (error) {
    logger.warn('[plugin-loader] default source load failed: ' + (error && error.message));
  }
  return getAllPluginManifests();
}

/**
 * BLOCK-84：多源单次装载——任意 source 数组一次注册（避免多次调用互相清除 _fromSdkSource）。
 * sources 元素：{ type: 'builtin'|'installed'|'development', root, required? }
 */
function loadFromSourcesArray(sources) {
  const { inspectPluginSources } = require('../shared-backend/plugin-sdk');
  const result = inspectPluginSources({ sources, normalizeManifest: normalizePluginManifest });
  const map = _getPluginsMap();
  for (const [id, plugin] of map.entries()) {
    if (plugin && plugin._fromSdkSource) map.delete(id);
  }
  let count = 0;
  for (const candidate of result.candidates) {
    if (!candidate.valid || !candidate.manifest) continue;
    const existing = map.get(candidate.manifest.id);
    const canonicalBuiltIn =
      candidate.sourceType === 'builtin' &&
      candidate.plugin &&
      candidate.plugin.sourcePolicy === 'builtin-canonical';
    if (
      existing &&
      !existing._fromSdkSource &&
      candidate.sourceType === 'builtin' &&
      !(canonicalBuiltIn && existing._sourceType !== 'development')
    ) {
      continue;
    }
    const currentFingerprint = candidate.manifest.execution
      ? candidate.manifest.execution.scriptFingerprint
      : undefined;
    const installedFingerprint = candidate.plugin._installedFingerprint || null;
    const manifestDrift = !!(
      installedFingerprint && currentFingerprint && installedFingerprint !== currentFingerprint
    );
    // 与 loadPluginsFromSources 同一装配语义：必须补齐 pluginDir/scriptPath/_sourceType
    // 等运行时字段，否则 getToolDefinition 读 pluginDir 得到 undefined（catalog 投影 500）。
    map.set(candidate.manifest.id, {
      ...candidate.plugin,
      id: candidate.manifest.id,
      pluginDir: candidate.pluginDir,
      scriptPath: path.join(candidate.pluginDir, 'scripts'),
      _sourceType: candidate.sourceType,
      _installedFingerprint: installedFingerprint,
      _currentFingerprint: currentFingerprint,
      _manifestDrift: manifestDrift,
      _driftReason: manifestDrift ? 'fingerprint_changed' : null,
      _fromSdkSource: true,
    });
    count += 1;
  }
  if (count > 0) {
    logger.info(`[plugin-loader] loaded ${count} plugin(s) from source list`);
  }
  return count;
}

function loadPluginsFromSources({ builtInDir, installedDir, developmentDirs = [] } = {}) {
  const { inspectPluginSources } = require('../shared-backend/plugin-sdk');
  const sources = [];
  if (builtInDir) sources.push({ type: 'builtin', root: builtInDir });
  if (installedDir) sources.push({ type: 'installed', root: installedDir });
  for (const root of developmentDirs) sources.push({ type: 'development', root });
  const result = inspectPluginSources({ sources, normalizeManifest: normalizePluginManifest });
  const map = _getPluginsMap();
  for (const [id, plugin] of map.entries()) {
    if (plugin && plugin._fromSdkSource) map.delete(id);
  }
  for (const candidate of result.candidates) {
    if (!candidate.valid || !candidate.manifest) continue;
    const existing = map.get(candidate.manifest.id);
    const canonicalBuiltIn =
      candidate.sourceType === 'builtin' &&
      candidate.plugin &&
      candidate.plugin.sourcePolicy === 'builtin-canonical';
    if (
      existing &&
      !existing._fromSdkSource &&
      candidate.sourceType === 'builtin' &&
      !(canonicalBuiltIn && existing._sourceType !== 'development')
    ) {
      continue;
    }
    const currentFingerprint = candidate.manifest.execution.scriptFingerprint;
    const installedFingerprint = candidate.plugin._installedFingerprint || null;
    const manifestDrift = !!(
      installedFingerprint && currentFingerprint && installedFingerprint !== currentFingerprint
    );
    map.set(candidate.manifest.id, {
      ...candidate.plugin,
      id: candidate.manifest.id,
      pluginDir: candidate.pluginDir,
      scriptPath: path.join(candidate.pluginDir, 'scripts'),
      _sourceType: candidate.sourceType,
      _installedFingerprint: installedFingerprint,
      _currentFingerprint: currentFingerprint,
      _manifestDrift: manifestDrift,
      _driftReason: manifestDrift ? 'fingerprint_changed' : null,
      _fromSdkSource: true,
    });
  }
  return result;
}

