'use strict';

/**
 * routes/_helpers/storage.js — 文件存储共享 helper
 *
 * 抽自 `core/petri-server/routes/result-studio.js` PHASE 2.1a 拆分 commit。
 * 类别：文件系统读取 / hashing / 表格抽样 / 路径包含性检查。
 *   - hashFile(filePath)                              → sha256 流式哈希
 *   - resolveWorkspaceFileForRevision(workspaceRoot, revision) → 包含性检查
 *   - openVerifiedRevisionArtifact(workspaceRoot, revision)    → snapshot open
 *   - readTableSample(absolutePath, fileName)         → 表格抽样
 *   - detectDelimiter(headerLine, fileName)           → csv/tsv 嗅探
 *   - splitCsvLine(line, delimiter)                   → 简单 csv parser
 *   - ID_INFERENCE_SAMPLE_ROWS / MAX_READ_BYTES       → 上限常量
 */

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { isPathContained } = require('../../../shared-backend/project-run-layout');
const {
  createVerifiedFileSnapshot,
} = require('../../helpers/verified-file-snapshot');

/** 用于 ID 推断的抽样上限。够判定唯一性，又不至于把大文件全读进内存。 */
const ID_INFERENCE_SAMPLE_ROWS = 500;

/** 单个 artifact 的读取上限（字节）。超过则只读前缀做抽样。 */
const MAX_READ_BYTES = 8 * 1024 * 1024;

function hashFile(filePath) {
  const hash = crypto.createHash('sha256');
  const handle = fs.openSync(filePath, 'r');
  try {
    const buffer = Buffer.alloc(1024 * 1024);
    let bytesRead;
    do {
      bytesRead = fs.readSync(handle, buffer, 0, buffer.length, null);
      if (bytesRead > 0) hash.update(buffer.subarray(0, bytesRead));
    } while (bytesRead > 0);
  } finally {
    fs.closeSync(handle);
  }
  return hash.digest('hex');
}

function resolveWorkspaceFileForRevision(workspaceRoot, revision) {
  const workspace = fs.realpathSync(workspaceRoot);
  const target = fs.realpathSync(path.join(workspace, revision.outputPath));
  if (!isPathContained(workspace, target)) throw Object.assign(new Error('Revision output escaped the project.'), { code: 'revision_output_escape' });
  return target;
}

async function openVerifiedRevisionArtifact(workspaceRoot, revision, deps = {}) {
  const snapshotFactory = deps.createVerifiedFileSnapshot || createVerifiedFileSnapshot;
  let fd = null;
  try {
    const workspace = fs.realpathSync(workspaceRoot);
    const artifactPath = fs.realpathSync(path.join(workspace, revision.outputPath));
    if (!isPathContained(workspace, artifactPath)) throw new Error('artifact_path_escape');
    const noFollow = Number.isInteger(fs.constants.O_NOFOLLOW) ? fs.constants.O_NOFOLLOW : 0;
    fd = fs.openSync(artifactPath, fs.constants.O_RDONLY | noFollow);
    const stat = fs.fstatSync(fd);
    if (!stat.isFile()) throw new Error('artifact_not_file');
    if (!revision.outputHash) throw new Error('artifact_hash_mismatch');
    const sourceFd = fd;
    fd = null;
    const snapshot = await snapshotFactory(sourceFd, {
      expectedIdentity: {
        dev: stat.dev,
        ino: stat.ino,
        size: stat.size,
        mtimeMs: stat.mtimeMs,
        ctimeMs: stat.ctimeMs,
      },
      expectedSha256: revision.outputHash,
    });
    return {
      fd: snapshot.fd,
      stat: snapshot.stat,
      verification: snapshot.verification,
      artifactPath,
    };
  } catch (error) {
    if (fd !== null) {
      try { fs.closeSync(fd); } catch {}
    }
    if (error?.code === 'verified_snapshot_hash_mismatch') throw new Error('artifact_hash_mismatch');
    throw error;
  }
}

function detectDelimiter(headerLine, fileName) {
  if (/\.tsv$/i.test(fileName)) return '\t';
  const tabs = (headerLine.match(/\t/g) || []).length;
  const commas = (headerLine.match(/,/g) || []).length;
  return tabs > commas ? '\t' : ',';
}

function splitCsvLine(line, delimiter) {
  const cells = [];
  let current = '';
  let quoted = false;
  for (let index = 0; index < line.length; index += 1) {
    const char = line[index];
    if (char === '"') {
      // 连续两个引号是转义的字面引号
      if (quoted && line[index + 1] === '"') { current += '"'; index += 1; continue; }
      quoted = !quoted;
      continue;
    }
    if (char === delimiter && !quoted) { cells.push(current.trim()); current = ''; continue; }
    current += char;
  }
  cells.push(current.trim());
  return cells;
}

/**
 * 读取表格 artifact 并抽样。
 *
 * 返回真实总行数（在读全的前提下）与抽样行对象；文件被截断时明确标记，
 * 避免把"前缀里唯一"当成"整表唯一"。
 */
function readTableSample(absolutePath, fileName) {
  const stat = fs.statSync(absolutePath);
  const truncated = stat.size > MAX_READ_BYTES;
  let raw;
  if (truncated) {
    const handle = fs.openSync(absolutePath, 'r');
    try {
      const buffer = Buffer.alloc(MAX_READ_BYTES);
      const read = fs.readSync(handle, buffer, 0, MAX_READ_BYTES, 0);
      raw = buffer.slice(0, read).toString('utf8');
    } finally {
      fs.closeSync(handle);
    }
    // 丢弃末尾可能被截断的半行
    const lastBreak = raw.lastIndexOf('\n');
    if (lastBreak > 0) raw = raw.slice(0, lastBreak);
  } else {
    raw = fs.readFileSync(absolutePath, 'utf8');
  }

  const lines = raw.split(/\r?\n/).filter((line) => line.trim() !== '');
  if (lines.length === 0) return { columns: [], rows: [], rowCount: 0, truncated };

  const delimiter = detectDelimiter(lines[0], fileName);
  const columns = splitCsvLine(lines[0], delimiter);
  const dataLines = lines.slice(1);
  const rows = dataLines.slice(0, ID_INFERENCE_SAMPLE_ROWS).map((line) => {
    const cells = splitCsvLine(line, delimiter);
    const row = {};
    columns.forEach((column, index) => { row[column] = cells[index]; });
    return row;
  });

  return {
    columns,
    rows,
    // 文件被截断时行数只是下界，不能当权威总数。
    rowCount: truncated ? null : dataLines.length,
    truncated,
  };
}

module.exports = {
  hashFile,
  resolveWorkspaceFileForRevision,
  openVerifiedRevisionArtifact,
  readTableSample,
  detectDelimiter,
  splitCsvLine,
  ID_INFERENCE_SAMPLE_ROWS,
  MAX_READ_BYTES,
};

'use strict';

/**
 * routes/_helpers/workflow.js — workflow 状态机共享 helper
 *
 * 抽自 `core/petri-server/routes/result-studio.js` PHASE 2.1a 拆分 commit。
 * 类别：跨 repository / interaction / selection / context / artifact 状态机的胶水函数。
 *   - attachExistingRepositoryWithExplicitConsent(...) → 已有仓库绑定
 *   - resolveInteractionBaselineRevision(...)         → interaction baseline 选择
 *   - baselineFailureDiagnostic(error)                 → 失败诊断格式化
 *   - resolveInteractionDescriptor(...)                → plugin → artifact 映射
 *   - backingArtifactName(interaction)                 → interaction → backing file
 *   - bindAuthoritativeQuerySelection(...)             → selection 权威性重算
 *   - resolveArtifactPath(...)                         → artifact 路径解析
 *
 * 循环依赖注意点：workflow.js 依赖 repository / validate / storage；
 * 那些 helper 通过 require() 内部反向引用，不会再回到 workflow.js，避免循环。
 */

const fs = require('fs');
const path = require('path');
const db = require('../../db');
const pluginLoader = require('../../plugin-loader');
const { resolveProjectRunLayout, isPathContained } = require('../../../shared-backend/project-run-layout');
const {
  inspectBaselineArtifactCohort,
  inspectPersistedArtifactCohort,
} = require('../../../shared-backend/result-changeset-service');
const {
  queryResultTable,
} = require('../../../shared-backend/result-studio-table-query');
const {
  bindProjectRepository,
} = require('../../../shared-backend/git-repository-binding');

const repository = require('./repository');
const validate = require('./validate');
const storage = require('./storage');

function attachExistingRepositoryWithExplicitConsent(input, dependencies = {}) {
  const projectId = String(input?.projectId || '').trim();
  const workspaceRoot = String(input?.workspaceRoot || '').trim();
  const allowExistingRepository = input?.allowExistingRepository === true;
  if (!projectId || !workspaceRoot) {
    return { ok: false, status: 400, code: 'project_context_required' };
  }
  if (!allowExistingRepository) {
    return { ok: false, status: 400, code: 'explicit_existing_repository_consent_required' };
  }
  const repositoryInstance = dependencies.repository;
  const binder = dependencies.bindProjectRepository || bindProjectRepository;
  if (!repositoryInstance?.saveExistingRepositoryConsent || !repositoryInstance?.saveRepositoryBinding) {
    return { ok: false, status: 500, code: 'repository_consent_store_unavailable' };
  }
  const binding = binder({
    workspaceRoot,
    projectId,
    preferManaged: false,
    allowExistingRepository,
    createManagedIfMissing: false,
  });
  if (binding?.mode !== 'existing') {
    return {
      ok: false,
      status: 409,
      code: binding?.inspection?.managed?.exists
        ? 'managed_repository_already_initialized'
        : 'existing_repository_not_found',
    };
  }
  if (!binding.adapter) {
    return {
      ok: false,
      status: 409,
      code: binding.reason || binding.status || 'repository_binding_failed',
      bindingStatus: binding.status || null,
    };
  }
  const consent = repositoryInstance.saveExistingRepositoryConsent({
    projectId,
    allowExistingRepository,
    decisionSource: 'explicit_api',
  });
  const savedBinding = repositoryInstance.saveRepositoryBinding({
    projectId,
    mode: binding.mode,
    workspaceRoot: binding.workspaceRoot,
    gitDir: binding.adapter.gitDir,
    workTree: binding.adapter.workTree,
    managedPaths: binding.managedPaths,
    status: binding.status,
    reason: binding.reason,
    gitVersion: binding.inspection?.runtime?.versionRaw || null,
  });
  return {
    ok: binding.status === 'ready',
    status: binding.status === 'ready' ? 200 : 409,
    code: binding.status === 'ready' ? null : binding.reason || binding.status,
    bindingStatus: binding.status,
    mode: savedBinding.mode,
    consent: {
      allowExistingRepository: consent.allowExistingRepository,
      decisionSource: consent.decisionSource,
    },
  };
}

function resolveInteractionBaselineRevision({
  repository: repositoryInstance,
  projectId,
  sourceJob,
  artifactId,
  pluginDescriptor,
} = {}, dependencies = {}) {
  const existing = repositoryInstance.findRevisionByJobArtifact({
    projectId,
    toolJobId: sourceJob.id,
    artifactId,
  });
  if (!pluginDescriptor) {
    return {
      revision: existing,
      requiresEnsure: !existing,
      qualification: null,
    };
  }
  const inspectPersisted = dependencies.inspectPersistedArtifactCohort || inspectPersistedArtifactCohort;
  const persisted = inspectPersisted({
    projectId,
    sourceJob,
    artifactId,
    pluginId: sourceJob.tool_id,
    pluginDescriptor,
  }, { repository: repositoryInstance });
  if (persisted.qualified) {
    return {
      revision: persisted.revision,
      requiresEnsure: false,
      qualification: persisted,
    };
  }
  const inspect = dependencies.inspectBaselineArtifactCohort || inspectBaselineArtifactCohort;
  const qualification = inspect({
    projectId,
    sourceJob,
    artifactId,
    pluginId: sourceJob.tool_id,
    pluginDescriptor,
  }, { repository: repositoryInstance });
  return {
    revision: qualification.qualified ? qualification.revision : null,
    requiresEnsure: !qualification.qualified,
    qualification,
  };
}

function baselineFailureDiagnostic(error) {
  const diagnostic = {
    code: error && error.code || 'baseline_revision_unavailable',
    message: error && error.message || 'Baseline revision could not be registered.',
  };
  if (!String(diagnostic.code).startsWith('git_') || !error?.detail || typeof error.detail !== 'object') {
    return diagnostic;
  }
  const detail = error.detail;
  const technical = {};
  if (/^[a-z][a-z0-9-]*$/.test(String(detail.command || ''))) technical.command = detail.command;
  if (Number.isInteger(detail.status)) technical.status = detail.status;
  if (/^[A-Z][A-Z0-9_]*$/.test(String(detail.systemCode || ''))) technical.systemCode = detail.systemCode;
  if (/^SIG[A-Z0-9]+$/.test(String(detail.signal || ''))) technical.signal = detail.signal;
  if (detail.killed === true) technical.killed = true;
  if (Number.isInteger(detail.attempts) && detail.attempts > 0) technical.attempts = detail.attempts;
  if (Object.keys(technical).length > 0) diagnostic.technical = technical;
  return diagnostic;
}

function resolveInteractionDescriptor(toolId, artifactRecord, artifactName, dependencies = {}) {
  const getPluginManifest = dependencies.getPluginManifest || pluginLoader.getPluginManifest;
  const plugin = getPluginManifest(toolId);
  const descriptor = plugin?.resultStudio || null;
  if (!descriptor) return { descriptor: null, artifactDescriptor: null, mapping: null };
  const artifactDescriptor = descriptor.artifacts.find((artifact) =>
    artifact.id === artifactRecord?.id || artifact.filename === artifactName) || null;
  const mapping = artifactDescriptor
    ? descriptor.interactionMappings.find((item) => item.artifactId === artifactDescriptor.id) || null
    : null;
  return { descriptor, artifactDescriptor, mapping };
}

function backingArtifactName(interaction) {
  const { descriptor, mapping, artifactDescriptor } = interaction;
  if (!mapping) return null;
  if (mapping.dataFile) return mapping.dataFile;
  if (mapping.dataArtifactId) {
    return descriptor?.artifacts.find((artifact) => artifact.id === mapping.dataArtifactId)?.filename || null;
  }
  return artifactDescriptor?.filename || null;
}

/**
 * 把 artifact 名解析为工作区内的真实路径。
 *
 * 只允许 output/ 下的文件名，不接受路径分隔符或 `..`，
 * 再用 layout 派生的绝对路径做包含性复核。
 */
function resolveArtifactPath({ req, job, project, artifactName }, dependencies = {}) {
  if (typeof artifactName !== 'string' || artifactName.trim() === '') {
    return { error: { status: 400, code: 'artifact_required' } };
  }
  const name = artifactName.trim();
  if (name.includes('\0') || name.includes('/') || name.includes('\\') || name.includes('..')) {
    return { error: { status: 400, code: 'artifact_name_invalid' } };
  }
  const unavailable = repository.artifactTruthAvailability(job?.result);
  if (unavailable) return unavailable;
  const resolveLayout = dependencies.resolveProjectRunLayout || resolveProjectRunLayout;
  let layout;
  try {
    layout = resolveLayout({
      projectId: project.id,
      toolJobId: job.id,
      db,
      userId: validate.userId(req),
      skipPermissionCheck: validate.isAdminOrInternal(req),
      ensureDirs: false,
    });
  } catch (error) {
    return { error: { status: 409, code: 'layout_unavailable', message: error && error.message } };
  }
  const outputDir = layout.outputDir || path.join(layout.jobDir, 'output');
  // Some canonical plugins predate the unified output/ layout and persist
  // their declared artifacts directly under the Job directory.  The Job's
  // Artifact Truth already contains the authoritative path; derive from that
  // record first instead of pretending every valid artifact lives in output/.
  // The caller still supplies only an id/name (never a path), and the resolved
  // target must remain inside the canonical Job directory.
  const declared = Array.isArray(job?.result?.artifacts) ? job.result.artifacts : [];
  const declaredMatches = declared.filter((artifact) => artifact && (
    artifact.id === name
    || artifact.name === name
    || artifact.filename === name
    || path.basename(String(artifact.path || '')) === name
  ));
  if (declaredMatches.length === 0) return repository.artifactTruthError(
    'artifact_record_missing',
    'The selected file is not present in Job Artifact Truth.',
  );
  if (declaredMatches.length > 1) return repository.artifactTruthError(
    'artifact_identity_ambiguous',
    'The selected file does not resolve to one unique Artifact Truth record.',
  );
  let absolutePath;
  if (declaredMatches.length === 1 && declaredMatches[0].path) {
    try {
      const jobRoot = fs.realpathSync(layout.jobRoot || layout.jobDir);
      const declaredPath = fs.realpathSync(declaredMatches[0].path);
      if (!isPathContained(jobRoot, declaredPath) || !fs.statSync(declaredPath).isFile()) {
        return { error: { status: 400, code: 'artifact_outside_job' } };
      }
      absolutePath = declaredPath;
    } catch {
      return repository.artifactTruthError(
        'artifact_file_unavailable',
        'The selected Artifact file is unavailable.',
      );
    }
  }
  if (!absolutePath) {
    const absolute = path.resolve(outputDir, name);
    const resolvedOutput = path.resolve(outputDir);
    if (absolute !== resolvedOutput && !absolute.startsWith(resolvedOutput + path.sep)) {
      return { error: { status: 400, code: 'artifact_outside_output' } };
    }
    if (!fs.existsSync(absolute)) return repository.artifactTruthError(
      'artifact_file_unavailable',
      'The selected Artifact file is unavailable.',
    );
    absolutePath = absolute;
  }
  const binding = repository.findArtifactRecord(job.result, absolutePath, name);
  if (binding.error) return binding;
  return {
    absolutePath,
    layout,
    artifactRecord: binding.artifactRecord,
    expectedSha256: binding.expectedSha256,
  };
}

/**
 * Recompute a query-backed Selection from immutable Revision + Job Artifact
 * Truth. Browser-supplied count/hash/sample values are comparison inputs only;
 * none of them can become persisted Agent context without this exact read.
 */
function bindAuthoritativeQuerySelection({ req, project, selection, repository: repositoryInstance }, dependencies = {}) {
  if (!selection?.entityIdsTruncated || !selection.filterExpression) {
    return { selection, authoritative: false };
  }
  const reject = (code, message, status = 409) => ({ error: { status, code, message } });
  if (!selection.revisionId) {
    return reject('selection_revision_required', 'A query-backed selection requires one persisted Revision.');
  }
  const revision = repositoryInstance.getRevision(selection.revisionId);
  if (!revision
      || revision.projectId !== project.id
      || revision.artifactId !== selection.artifactId
      || !revision.toolJobId) {
    return reject('selection_revision_mismatch', 'Selection coordinates do not match persisted Revision truth.');
  }

  const getToolJob = dependencies.getToolJob || db.getToolJob;
  const storedJob = getToolJob(revision.toolJobId);
  if (!storedJob || storedJob.project_id !== project.id || storedJob.id !== revision.toolJobId) {
    return reject('selection_job_mismatch', 'Selection Revision has no matching source Job truth.');
  }
  const job = { ...storedJob, result: repository.parseToolJobResult(storedJob) };
  const resolveArtifact = dependencies.resolveArtifactPath || resolveArtifactPath;
  const selected = resolveArtifact({
    req,
    job,
    project,
    artifactName: revision.artifactId,
  });
  if (selected.error) return selected;
  if (selected.expectedSha256 !== revision.outputHash) {
    return reject('selection_revision_artifact_drift', 'Revision bytes do not match source Job Artifact Truth.');
  }

  const interaction = resolveInteractionDescriptor(
    job.tool_id,
    selected.artifactRecord,
    revision.artifactId,
    { getPluginManifest: dependencies.getPluginManifest },
  );
  const mapping = interaction.mapping;
  const idField = mapping?.idField || mapping?.rowIdField || null;
  if (!idField || !mapping?.entityType) {
    return reject('selection_mapping_unavailable', 'Source plugin has no stable entity mapping for this selection.');
  }
  if (selection.entityType !== mapping.entityType) {
    return reject('selection_entity_type_mismatch', 'Selection entity type does not match source plugin truth.');
  }

  const queryName = backingArtifactName(interaction) || revision.artifactId;
  const backing = queryName === revision.artifactId
    ? selected
    : resolveArtifact({ req, job, project, artifactName: queryName });
  if (backing.error) return backing;

  let query;
  try {
    query = (dependencies.queryResultTable || queryResultTable)({
      filePath: backing.absolutePath,
      expectedSha256: backing.expectedSha256,
      idField,
      filterExpression: selection.filterExpression,
      sort: selection.sort,
      offset: 0,
      limit: 1,
    });
  } catch (error) {
    return reject(error?.code || 'selection_query_recompute_failed', 'Selection query could not be recomputed from Artifact Truth.');
  }
  const afterRead = (dependencies.verifyArtifactRecordBytes || repository.verifyArtifactRecordBytes)(
    backing.artifactRecord,
    backing.absolutePath,
  );
  if (afterRead.error) return afterRead;

  const evidence = query?.selectionEvidence;
  const authoritativeSample = Array.isArray(evidence?.sampleEntityIds)
    ? [...new Set(evidence.sampleEntityIds.map((value) => String(value).trim()).filter(Boolean))]
    : [];
  const suppliedSample = [...new Set((selection.entityIds || []).map((value) => String(value).trim()).filter(Boolean))];
  const sameSample = JSON.stringify([...suppliedSample].sort())
    === JSON.stringify([...authoritativeSample].sort());
  if (!evidence
      || evidence.idField !== idField
      || !Number.isInteger(evidence.entityIdCount)
      || evidence.entityIdCount < 1
      || !/^[a-f0-9]{64}$/.test(String(evidence.entityIdsHash || ''))
      || selection.entityIdCount !== evidence.entityIdCount
      || selection.entityIdsHash !== evidence.entityIdsHash
      || selection.filterHash !== query.filterHash
      || !sameSample) {
    return reject(
      'selection_query_evidence_mismatch',
      'Browser selection evidence does not match the authoritative Artifact query.',
    );
  }

  return {
    authoritative: true,
    selection: {
      ...selection,
      entityIds: authoritativeSample,
      entityIdCount: evidence.entityIdCount,
      entityIdsTruncated: evidence.entityIdCount > authoritativeSample.length,
      entityIdsHash: evidence.entityIdsHash,
      filterHash: query.filterHash,
      filterExpression: query.filterExpression,
      sort: query.sort,
      displayState: {
        ...(selection.displayState || {}),
        evidenceAuthority: 'server_artifact_truth',
      },
    },
  };
}

module.exports = {
  attachExistingRepositoryWithExplicitConsent,
  resolveInteractionBaselineRevision,
  baselineFailureDiagnostic,
  resolveInteractionDescriptor,
  backingArtifactName,
  bindAuthoritativeQuerySelection,
  resolveArtifactPath,
};

/**
 * routes/ai-admin.js — admin governance, audit, AI usage stats.
 * Migrated from server.js as part of MODULES_BATCH2_v1.
 *
 * Uses the Promise facade over the desktop SQLite database so route handlers
 * can keep a consistent async control flow.
 */
const express = require('express');
const dbMod = require('../db');
const adb = dbMod.getAsyncDatabase();
const {
  isAgentGloballyPausedAsync,
  setAgentGlobalPauseAsync,
} = require('../helpers/admin-gov');

function _undoneTrue(col = 'undone') {
  return `${col}=1`;
}

function _boolFromDb(v) {
  return v === true || v === 1 || v === '1' || v === 't';
}

function _requireAdmin(req, res) {
  if (!req.user || req.user.role !== 'admin') {
    res.status(403).json({status: 'error', error: '需要管理员权限'});
    return false;
  }
  return true;
}

// async scalar: first column of first row, or null
async function _scalar(sql, ...params) {
  const r = await adb.prepare(sql).get(...params);
  return r ? Object.values(r)[0] : null;
}

module.exports = function mountAdmin(app) {

  app.get('/api/ai/admin/users-overview', async (req, res) => {
    if (!_requireAdmin(req, res)) return;
    try {
      // OPT_ADMIN_OVERVIEW_v1: 11 batch COUNT queries instead of users × 11 sequential.
      const baseUsers = await adb
        .prepare('SELECT id, username, role, created_at FROM users ORDER BY created_at DESC')
        .all();

      if (baseUsers.length === 0) return res.json({status:'ok', users: [], globalPaused: false});

      // Batch 1: conversation + message counts (JOIN-safe: group before join)
      const convCounts = await adb.prepare(`
        SELECT c.user_id,
          COUNT(DISTINCT c.id) AS conv_count,
          COUNT(m.id) AS msg_count
        FROM copilot_conversations c
        LEFT JOIN copilot_messages m ON m.conversation_id = c.id
        GROUP BY c.user_id
      `).all();
      const convMap = {};
      for (const r of convCounts) convMap[r.user_id] = r;

      // Batch 2: facts + vectors + plans + active plans
      const [factCounts, vecCounts, planCounts, actCounts] = await Promise.all([
        adb.prepare('SELECT user_id, COUNT(*) AS n FROM user_facts GROUP BY user_id').all(),
        adb.prepare('SELECT user_id, COUNT(*) AS n FROM memory_vectors GROUP BY user_id').all(),
        adb.prepare('SELECT user_id, COUNT(*) AS n, SUM(CASE WHEN status=\'active\' THEN 1 ELSE 0 END) AS active_plans FROM copilot_plans GROUP BY user_id').all(),
        adb.prepare('SELECT user_id, COUNT(*) AS n, SUM(CASE WHEN undone IS TRUE THEN 1 ELSE 0 END) AS undone_n FROM agent_audit GROUP BY user_id').all(),
      ]);
      const factMap = {}; for (const r of factCounts) factMap[r.user_id] = r;
      const vecMap = {}; for (const r of vecCounts) vecMap[r.user_id] = r;
      const planMap = {}; for (const r of planCounts) planMap[r.user_id] = r;
      const actMap = {}; for (const r of actCounts) actMap[r.user_id] = r;

      // Batch 3: last_act_at + agent_paused
      const lastActMap = {};
      const pausedMap = {};
      const lastActs = await adb.prepare('SELECT user_id, MAX(ts) AS ts FROM agent_audit GROUP BY user_id').all();
      for (const r of lastActs) lastActMap[r.user_id] = r.ts;
      const settings = await adb.prepare('SELECT user_id, agent_paused FROM copilot_settings WHERE agent_paused IS NOT NULL AND agent_paused = TRUE').all();
      for (const r of settings) pausedMap[r.user_id] = r.agent_paused;

      // Last conv timestamp per user
      const lastConvMap = {};
      const lastConvs = await adb.prepare('SELECT user_id, MAX(updated_at) AS ts FROM copilot_conversations GROUP BY user_id').all();
      for (const r of lastConvs) lastConvMap[r.user_id] = r.ts;

      const rows = baseUsers.map(u => ({
        id: u.id,
        username: u.username,
        role: u.role,
        created_at: u.created_at,
        conv_count: convMap[u.id]?.conv_count || 0,
        msg_count: convMap[u.id]?.msg_count || 0,
        fact_count: factMap[u.id]?.n || 0,
        vec_count: vecMap[u.id]?.n || 0,
        plan_count: planMap[u.id]?.n || 0,
        active_plans: planMap[u.id]?.active_plans || 0,
        act_count: actMap[u.id]?.n || 0,
        undone_count: actMap[u.id]?.undone_n || 0,
        last_act_at: lastActMap[u.id] || null,
        last_conv_at: lastConvMap[u.id] || null,
        agent_paused: _boolFromDb(pausedMap[u.id]),
      }));

      rows.sort((a, b) => {
        if (!a.last_act_at && !b.last_act_at) return 0;
        if (!a.last_act_at) return 1;
        if (!b.last_act_at) return -1;
        return String(b.last_act_at).localeCompare(String(a.last_act_at));
      });

      const globalPaused = await isAgentGloballyPausedAsync();
      res.json({status:'ok', users: rows, globalPaused});
    } catch (e) { res.status(500).json({status:'error', error: e.message}); }
  });

  app.get('/api/ai/admin/audit', async (req, res) => {
    if (!_requireAdmin(req, res)) return;
    const userId = req.query.userId;
    const limit = Math.max(1, Math.min(500, parseInt(req.query.limit) || 100));
    try {
      const rows = userId
        ? await adb.prepare('SELECT id, user_id, action, args, ts, undone, undone_at, undo_token FROM agent_audit WHERE user_id=? ORDER BY ts DESC LIMIT ?').all(userId, limit)
        : await adb.prepare('SELECT id, user_id, action, args, ts, undone, undone_at, undo_token FROM agent_audit ORDER BY ts DESC LIMIT ?').all(limit);
      const items = rows.map(r => {
        let argsParsed = null;
        try { argsParsed = JSON.parse(r.args || '{}'); } catch {}
        return {
          id: r.id, user_id: r.user_id, action: r.action, ts: r.ts,
          undone: _boolFromDb(r.undone), undone_at: r.undone_at,
          argsSummary: argsParsed ? Object.keys(argsParsed).slice(0, 6).map(k => k + '=' + String(argsParsed[k]).slice(0, 30)).join(', ') : '',
        };
      });
      res.json({status:'ok', audit: items});
    } catch (e) { res.status(500).json({status:'error', error: e.message}); }
  });

  app.post('/api/ai/admin/pause-user', express.json({limit: '4kb'}), async (req, res) => {
    if (!_requireAdmin(req, res)) return;
    const {userId, paused} = req.body || {};
    if (!userId || typeof paused !== 'boolean') return res.status(400).json({status:'error', error:'需要 userId 和 paused (boolean)'});
    try {
      const now = new Date().toISOString();
      const pausedVal = paused ? 1 : 0;
      await adb.prepare(`INSERT INTO copilot_settings(user_id, agent_paused, updated_at) VALUES (?, ?, ?)
                  ON CONFLICT(user_id) DO UPDATE SET agent_paused=excluded.agent_paused, updated_at=excluded.updated_at`)
        .run(userId, pausedVal, now);
      console.log('[admin] user-pause user=' + userId + ' paused=' + paused + ' by=' + (req.user && req.user.id));
      res.json({status:'ok'});
    } catch (e) { res.status(500).json({status:'error', error: e.message}); }
  });

  app.get('/api/ai/admin/global-pause', async (req, res) => {
    if (!_requireAdmin(req, res)) return;
    try {
      res.json({status:'ok', paused: await isAgentGloballyPausedAsync()});
    } catch (e) { res.status(500).json({status:'error', error: e.message}); }
  });

  app.post('/api/ai/admin/global-pause', express.json({limit: '4kb'}), async (req, res) => {
    if (!_requireAdmin(req, res)) return;
    const {paused} = req.body || {};
    if (typeof paused !== 'boolean') return res.status(400).json({status:'error', error:'需要 paused (boolean)'});
    try {
      await setAgentGlobalPauseAsync(paused, req.user && req.user.id);
      res.json({status:'ok', paused});
    } catch (e) { res.status(500).json({status:'error', error: e.message}); }
  });

  app.get('/api/ai/admin/usage-stats', async (req, res) => {
    if (!_requireAdmin(req, res)) return;
    const days = Math.max(1, Math.min(180, parseInt(req.query.days) || 30));
    const cutoff = new Date(Date.now() - days * 86400000).toISOString();
    const estimate = globalThis._petri && globalThis._petri.estimateCostCNY;
    const PRICING = (globalThis._petri && globalThis._petri.AI_PRICING) || {};
    if (!estimate) return res.status(500).json({status:'error', error:'helper_missing'});
    try {
      const dayExpr = 'substr(ts, 1, 10)';
      const daily = await adb.prepare(`
        SELECT ${dayExpr} AS day, kind, CAST(COUNT(*) AS INTEGER) AS calls,
               CAST(SUM(prompt_tokens) AS INTEGER) AS prompt_tokens, CAST(SUM(completion_tokens) AS INTEGER) AS completion_tokens,
               CAST(AVG(latency_ms) AS INTEGER) AS avg_latency,
               CAST(SUM(CASE WHEN error_code IS NOT NULL THEN 1 ELSE 0 END) AS INTEGER) AS errors
        FROM ai_usage WHERE ts >= ? GROUP BY ${dayExpr}, kind ORDER BY day DESC, kind
      `).all(cutoff);
      const usageByUser = await adb.prepare(`
        SELECT user_id, CAST(COUNT(*) AS INTEGER) AS calls,
               CAST(SUM(prompt_tokens) AS INTEGER) AS prompt_tokens, CAST(SUM(completion_tokens) AS INTEGER) AS completion_tokens,
               CAST(AVG(latency_ms) AS INTEGER) AS avg_latency,
               CAST(SUM(CASE WHEN error_code IS NOT NULL THEN 1 ELSE 0 END) AS INTEGER) AS errors
        FROM ai_usage WHERE ts >= ? AND user_id IS NOT NULL
        GROUP BY user_id ORDER BY (SUM(prompt_tokens) + SUM(completion_tokens)) DESC
      `).all(cutoff);
      const nameRows = await adb.prepare('SELECT id, username FROM users').all();
      const nameMap = Object.fromEntries(nameRows.map((u) => [u.id, u.username]));
      const perUser = usageByUser.map((d) => ({
        id: d.user_id,
        username: nameMap[d.user_id] || d.user_id,
        calls: d.calls,
        prompt_tokens: d.prompt_tokens,
        completion_tokens: d.completion_tokens,
        avg_latency: d.avg_latency,
        errors: d.errors,
      }));
      const dailyWithCost = daily.map(d => ({
        ...d,
        estimated_cost_cny: estimate((d.kind === 'embedding') ? 'text-embedding-v3' : 'deepseek-chat', d.prompt_tokens, d.completion_tokens),
      }));
      const perUserWithCost = perUser.map(d => ({...d, estimated_cost_cny: estimate('deepseek-chat', d.prompt_tokens, d.completion_tokens)}));
      const errorsBreakdown = await adb.prepare(`SELECT error_code, COUNT(*) AS n FROM ai_usage WHERE ts >= ? AND error_code IS NOT NULL GROUP BY error_code ORDER BY n DESC`).all(cutoff);
      const undoneCase = 'CAST(SUM(CASE WHEN undone=1 THEN 1 ELSE 0 END) AS INTEGER)';
      const topActs = await adb.prepare(`SELECT action, CAST(COUNT(*) AS INTEGER) AS n, ${undoneCase} AS undone FROM agent_audit WHERE ts >= ? GROUP BY action ORDER BY n DESC LIMIT 20`).all(cutoff);
      res.json({status:'ok', days, pricing: PRICING, daily: dailyWithCost, perUser: perUserWithCost, errors: errorsBreakdown, topActs});
    } catch (e) { res.status(500).json({status:'error', error: e.message}); }
  });

  // Aggregate per-user memory stats (kept by Phase 5 docs)
  app.get('/api/ai/admin/memory-stats', async (req, res) => {
    if (!_requireAdmin(req, res)) return;
    try {
      // OPT_ADMIN_MEMSTATS_v1: 4 batch queries instead of users × 4 sequential.
      const baseUsers = await adb.prepare('SELECT id, username FROM users').all();
      if (baseUsers.length === 0) return res.json({status: 'ok', users: []});

      const [factCounts, vecCounts, chatCounts] = await Promise.all([
        adb.prepare('SELECT user_id, COUNT(*) AS n FROM user_facts GROUP BY user_id').all(),
        adb.prepare('SELECT user_id, COUNT(*) AS n FROM memory_vectors GROUP BY user_id').all(),
        adb.prepare('SELECT user_id, COUNT(*) AS n, MAX(ts) AS last_active FROM chat_audit GROUP BY user_id').all(),
      ]);

      const factMap = {}; for (const r of factCounts) factMap[r.user_id] = r.n;
      const vecMap = {}; for (const r of vecCounts) vecMap[r.user_id] = r.n;
      const chatMap = {}; for (const r of chatCounts) { chatMap[r.user_id] = {n: r.n, last: r.last_active}; }

      const hasSummaryUsers = new Set(
        (await adb.prepare('SELECT user_id FROM chat_summaries').all()).map(r => r.user_id)
      );

      const users = baseUsers.map(u => ({
        id: u.id,
        username: u.username,
        facts: factMap[u.id] || 0,
        has_summary: hasSummaryUsers.has(u.id) || false,
        vectors: vecMap[u.id] || 0,
        chat_calls: chatMap[u.id]?.n || 0,
        last_active: chatMap[u.id]?.last || null,
      }));

      users.sort((a, b) => (b.chat_calls || 0) - (a.chat_calls || 0));
      res.json({status: 'ok', users});
    } catch (e) { res.status(500).json({status: 'error', error: e.message}); }
  });
};

