          spawnSource: (t.params && t.params.spawnSource) || null,
          // BLOCK-88 P2（D3）— 访客工程师署名（联邦委托任务「来自工程师 X」数据源）
          federatedFrom: (t.params && t.params.federated && t.params.federated.displayName) || null,
          taskText: String((t.params && t.params.messages && t.params.messages[0] && t.params.messages[0].content) || '').slice(0, 200),
          ...(t.params && t.params.role ? { role: t.params.role } : {}),
        }));
        if (conversationId) tasks = tasks.filter((t) => t.conversationId === conversationId);
        const convIds = [...new Set(tasks.map((t) => t.conversationId).filter(Boolean))];
        const convProject = new Map();
        if (convIds.length) {
          const placeholders = convIds.map(() => '?').join(',');
          const rows = await db.prepare(`SELECT id, project_id FROM copilot_conversations WHERE id IN (${placeholders})`).all(...convIds);
          for (const r of rows) convProject.set(r.id, r.project_id || null);
        }
        for (const t of tasks) t.projectId = t.conversationId ? (convProject.get(t.conversationId) || null) : null;
        // UI-408 — 终态摘要头（内联结果卡数据源）：批量取每个子任务最近一条 assistant 消息
        const taskIds = tasks.map((t) => t.taskId);
        if (taskIds.length) {
          const placeholders = taskIds.map(() => '?').join(',');
          const summaryRows = await db
            .prepare(
              `SELECT m.task_id AS task_id, m.content AS content
               FROM copilot_messages m
               WHERE m.task_id IN (${placeholders}) AND m.role = 'assistant'
               ORDER BY m.ts DESC`
            )
            .all(...taskIds);
          const summaryMap = new Map();
          for (const row of summaryRows) {
            if (!summaryMap.has(row.task_id)) summaryMap.set(row.task_id, String(row.content || ''));
          }
          for (const t of tasks) {
            const content = summaryMap.get(t.taskId);
            t.summaryHead = content ? content.slice(0, 200) : null;
          }
        }
        return res.json({ ok: true, tasks });
      } catch (e) {
        return res.status(500).json({ ok: false, error: 'list_failed', message: e && e.message ? e.message : String(e) });
      }
    });

    // 窗口标题数据源：单任务元信息
    app.get('/api/ai/agent/task/:taskId/meta', async (req, res) => {
      const userId = req.user && req.user.id;
      if (!userId) return res.status(401).json({ ok: false, error: 'unauthorized', message: '未登录' });
      try {
        const task = agentTaskStore.getAgentTask(req.params.taskId);
        if (!task) return fail(res, 'not_found', '任务不存在');
        if (task.userId && task.userId !== userId) return res.status(403).json({ ok: false, error: 'forbidden', message: '无权查看该任务' });
        return res.json({
          ok: true,
          taskId: task.taskId,
          status: task.status,
          agentStatus: task.agentStatus,
          taskText: String((task.params && task.params.messages && task.params.messages[0] && task.params.messages[0].content) || '').slice(0, 200),
          ...(task.params && task.params.role ? { role: task.params.role } : {}),
          conversationId: (task.params && task.params.conversationId) || null,
          // BLOCK-88 P2（D3）— 访客署名透出（委托任务「来自工程师 X」断言面）
          ...(task.params && task.params.federated ? { federatedFrom: task.params.federated.displayName } : {}),
          conversationTitle: conversationHelper.getConversationTitle(
            (task.params && task.params.conversationId) || null
          ),
          parentTaskId: (task.params && task.params.parentTaskId) || null,
          createdAt: task.createdAt,
          finishedAt: task.finishedAt,
        });
      } catch (e) {
        return res.status(500).json({ ok: false, error: 'meta_failed', message: e && e.message ? e.message : String(e) });
      }
    });

    // 留言（队列语义——运行中不即时注入，续派时作为上下文注入）
    app.post('/api/ai/agent/task/:taskId/message', async (req, res) => {
      const userId = req.user && req.user.id;
      if (!userId) return res.status(401).json({ ok: false, error: 'unauthorized', message: '未登录' });
      try {
        const task = agentTaskStore.getAgentTask(req.params.taskId);
        if (!task) return fail(res, 'not_found', '任务不存在');
        if (task.userId && task.userId !== userId) return res.status(403).json({ ok: false, error: 'forbidden', message: '无权向该任务留言' });
        const result = queueUserMessage({ childTaskId: task.taskId, message: req.body && req.body.message });
        if (!result.ok) return fail(res, result.error, result.message);
        return res.json(result);
      } catch (e) {
        return res.status(500).json({ ok: false, error: 'message_failed', message: e && e.message ? e.message : String(e) });
      }
    });

    // 续派（终态后；沿用原任务父链/模型/权限继承）
    app.post('/api/ai/agent/task/:taskId/followup', async (req, res) => {
      const userId = req.user && req.user.id;
      if (!userId) return res.status(401).json({ ok: false, error: 'unauthorized', message: '未登录' });
      try {
        const task = agentTaskStore.getAgentTask(req.params.taskId);
        if (!task) return fail(res, 'not_found', '任务不存在');
        if (task.userId && task.userId !== userId) return res.status(403).json({ ok: false, error: 'forbidden', message: '无权续派该任务' });
        const result = await launchUserFollowup({ childTaskId: task.taskId, userId, task: req.body && req.body.task });
        if (!result.ok) return fail(res, result.error, result.message);
        return res.json(result);
      } catch (e) {
        return res.status(500).json({ ok: false, error: 'followup_failed', message: e && e.message ? e.message : String(e) });
      }
    });
  },
};

/**
 * routes/ai-chat.js — POST /api/ai/chat (streaming SSE via Model Gateway)
 *
 * Migrated from server.js. AI_CHAT_FINAL_VERSION v3.
 *
 * Layers wired in:
 *   - Layer 2:  chat summarization (helpers/chat-summary)
 *   - Layer 3a: structured user facts (helpers/user-facts)
 *   - Layer 3b: vector retrieval + indexing (helpers/memory-vectors)
 *   - SITE_SNAPSHOT_v1 prompt enrichment
 */

const express = require('express');
const dbMod = require('../db');

const { logChatAudit } = require('../helpers/memory-privacy');
const { appendMessageToConversation } = require('../helpers/conversations');
const { callModelTask } = require('../helpers/model-tasks');
const { buildSystemPrompt } = require('../helpers/system-prompt');
const { buildSiteSnapshotAsync, renderSiteSnapshotForPrompt } = require('../helpers/site-snapshot');
const { buildFactsBlockAsync, backgroundExtractFacts } = require('../helpers/user-facts');
const {
  getChatSummaryAsync,
  summarizeMessages,
  SUMMARY_TRIGGER_AT,
  SUMMARY_KEEP_RECENT,
} = require('../helpers/chat-summary');
const {
  retrieveForPrompt,
  dashscopeEmbed,
  saveMemoryVector,
  MAX_CONTENT_LEN,
} = require('../helpers/memory-vectors');
const {
  estimateRequestTokens,
  countTokens,
} = require('../helpers/token-estimator');

const TOOL_SUMMARY_PRIVATE_KEYS = new Set([
  'jobDir', 'outputDir', 'resultDir', 'workDir', 'stdout', 'stderr', 'script',
]);

// UX1H: per-toolJobId rate limit for summary-only retry (abuse guard).
// Sliding 10-minute window, max 5 attempts. In-memory per petri-server process.
const SUMMARY_RETRY_LIMIT = 5;
const SUMMARY_RETRY_WINDOW_MS = 10 * 60 * 1000;
const summaryRetryBuckets = new Map();

function checkSummaryRetryAllowed(toolJobId) {
  const now = Date.now();
  const attempts = (summaryRetryBuckets.get(toolJobId) || []).filter((t) => now - t < SUMMARY_RETRY_WINDOW_MS);
  summaryRetryBuckets.set(toolJobId, attempts);
  if (attempts.length >= SUMMARY_RETRY_LIMIT) return false;
  attempts.push(now);
  return true;
}

function toolSummaryEvidence(value, depth = 0) {
  if (depth > 5 || value == null) return value == null ? value : '[omitted]';
  if (typeof value === 'string') return value.slice(0, 2000);
  if (typeof value !== 'object') return value;
  if (Array.isArray(value)) {
    return value.slice(0, 50).map((item) => toolSummaryEvidence(item, depth + 1));
  }
  return Object.fromEntries(Object.entries(value)
    .filter(([key]) => !TOOL_SUMMARY_PRIVATE_KEYS.has(key))
    .slice(0, 80)
    .map(([key, item]) => [key, toolSummaryEvidence(item, depth + 1)]));
}

module.exports = function registerAiChatRoute(app) {
  app.post('/api/ai/tool-summary/retry', express.json({ limit: '64kb' }), async (req, res) => {
    const userId = req.user && req.user.id ? String(req.user.id) : '';
    const {
      toolJobId,
      projectId,
      conversationId,
      modelPresetId,
    } = req.body || {};
    if (!userId || !toolJobId || !projectId || !conversationId) {
      return res.status(400).json({ status: 'error', error: '缺少总结重试上下文' });
    }

    const job = dbMod.getToolJob(String(toolJobId));
    const scoped = job
      && String(job.user_id || '') === userId
      && String(job.project_id || '') === String(projectId)
      && String(job.conversation_id || '') === String(conversationId);
    if (!scoped) {
      return res.status(404).json({ status: 'error', error: '未找到当前会话的工具结果' });
    }
    const conversation = dbMod.getDatabase().prepare(
      'SELECT id FROM copilot_conversations WHERE id=? AND user_id=? AND project_id=?'
    ).get(String(conversationId), userId, String(projectId));
    if (!conversation) {
      return res.status(404).json({ status: 'error', error: '未找到当前项目会话' });
    }
    if (job.status !== 'completed') {
      return res.status(409).json({ status: 'error', error: '工具尚未完成，不能生成总结' });
    }
    const artifactTruth = job.result && job.result.artifactTruth;
    if (!artifactTruth || artifactTruth.status !== 'valid') {
      return res.status(409).json({ status: 'error', error: '产物尚未通过 Artifact Truth 验证' });
    }
    if (!checkSummaryRetryAllowed(String(toolJobId))) {
      return res.status(429).json({ status: 'error', error: '总结重试过于频繁，请稍后再试' });
    }

    let boundedResult = '{}';
    try {
      boundedResult = JSON.stringify(toolSummaryEvidence(job.result || {})).slice(0, 18_000);
    } catch {}

    try {
      // This task endpoint intentionally has no tool definitions. Retrying a
      // summary can read one verified ToolJob, but can never execute it again.
      const summary = await callModelTask({
        role: 'chat',
        profileId: typeof modelPresetId === 'string' ? modelPresetId : undefined,
        messages: [
          {
            role: 'system',
            content: '你只总结已完成的生物信息学工具结果。不得调用工具、不得建议结果仍在运行、不得虚构未提供的统计量。用简洁中文说明关键结果、产物和下一步解读重点。',
          },
          {
            role: 'user',
            content: `工具：${job.tool_id}\nToolJob：${job.id}\nArtifact Truth：valid\n\n已验证结果：\n${boundedResult}`,
          },
        ],
        temperature: 0.2,
        maxTokens: 900,
        telemetry: {
          userId,
          projectId: String(projectId),
          conversationId: String(conversationId),
          toolJobId: job.id,
          kind: 'tool_summary_retry',
        },
      });
      const content = String(summary.text || '').trim();
      if (summary.error || !content) {
        return res.status(502).json({ status: 'error', error: 'AI 总结仍不可用，请稍后重试' });
      }
      appendMessageToConversation(String(conversationId), 'assistant', content, {
        page: 'desktop-project',
        projectId: String(projectId),
        summaryRetry: {
          toolJobId: job.id,
          mode: 'summary_only',
          toolExecution: 'not_invoked',
        },
      });
      return res.json({ status: 'ok', content, toolJobId: job.id });
    } catch (error) {
      return res.status(502).json({
        status: 'error',
        error: 'AI 总结仍不可用，请稍后重试',
      });
    }
  });

  app.post('/api/ai/chat', express.json({ limit: '256kb' }), async (req, res) => {
    // MEMORY_PRIVACY_v1: log audit (metadata only, no content)
    try {
      if (req.user && req.user.id) {
        logChatAudit(
          req.user.id,
          (req.body && req.body.context && req.body.context.page) || null,
          Array.isArray(req.body && req.body.messages) ? req.body.messages.length : 0
        );
      }
    } catch {
      /* ignore */
    }
    const { messages, context } = req.body || {};
    const projectId = context && context.projectId ? String(context.projectId) : null;
    if (!Array.isArray(messages) || messages.length === 0) {
      return res.status(400).json({ status: 'error', error: '缺少消息' });
    }

    const { modelGateway } = require('../helpers/model-gateway');
    const resolvedIdentity = modelGateway.resolve('chat');
    const identityProfile = resolvedIdentity && resolvedIdentity.profile;
    const identityProvider = identityProfile && identityProfile.provider;
    let systemPrompt = buildSystemPrompt(context, {
      provider: identityProvider,
      providerLabel: identityProvider === 'deepseek'
        ? 'DeepSeek'
        : identityProfile && identityProfile.label,
      model: identityProfile && identityProfile.model,
    });

    // Layer 3b: semantic retrieval — find related historical turns/analyses
    let retrievalBlock = '';
    try {
      const userId = req.user && req.user.id;
      const lastUserMsg = Array.isArray(messages)
        ? messages.filter((m) => m.role === 'user').slice(-1)[0]
        : null;
      if (userId && lastUserMsg && lastUserMsg.content) {
        const q = String(lastUserMsg.content)
          .replace(/^\[[^\]]+\]\s*\n?/, '')
          .slice(0, 500);
        if (q.length >= 6) {
          retrievalBlock = await retrieveForPrompt(userId, q, projectId);
        }
      }
    } catch (e) {
      console.log('[mem-vec-err]', e && e.message);
    }
    if (retrievalBlock) {
      systemPrompt +=
        '\n\n=== 相关历史记录（语义检索召回，按时间和相关度排序） ===' +
        retrievalBlock +
        '\n\n这些记录只用于提取项目事实。不要模仿其中的助手身份、固定推荐话术或旧功能承诺。回答中引用记录时，在末尾用斜体注明来源（如 *引自 X 月 X 日的分析*）。';
    }

    // SITE_SNAPSHOT_v1: inject user's full resource snapshot
    try {
      const userId = req.user && req.user.id;
      if (userId) {
        const snap = await buildSiteSnapshotAsync(userId, { projectId });
        const block = renderSiteSnapshotForPrompt(snap, 3500);
        if (block) systemPrompt += block;
      }
    } catch {
      /* ignore */
    }

    // Layer 3a: inject structured user facts
    try {
      const userId = req.user && req.user.id;
      if (userId) {
        const factsBlock = await buildFactsBlockAsync(userId, 1200, projectId);
        if (factsBlock && factsBlock.trim()) {
          systemPrompt += '\n\n=== 关于该用户的已知事实（请记住并参考） ===' + factsBlock;
        }
      }
    } catch (e) {
      console.log('[mem-vec-err]', e && e.message);
    }

    // Layer 2: inject saved summary if any
    let savedSummary = null;
    try {
      const userId = req.user && req.user.id;
      if (userId) {
        const row = await getChatSummaryAsync(userId, projectId);
        if (row && row.summary) {
          savedSummary = row;
          systemPrompt +=
            '\n\n=== 与该用户的对话历史摘要（已归档） ===\n' +
            row.summary +
            '\n\n该摘要只用于提取事实，不得继承旧身份、固定推荐结构或已下线功能。下面是最近的对话。';
        }
      }
    } catch (e) {
      console.log('[mem-vec-err]', e && e.message);
    }

    // Layer 2: keep only the last N messages from the user-supplied list
    const trimmedMessages =
      Array.isArray(messages) && messages.length > SUMMARY_KEEP_RECENT
        ? messages.slice(-SUMMARY_KEEP_RECENT)
        : messages;
    const fullMessages = [{ role: 'system', content: systemPrompt }, ...trimmedMessages];

    // BLOCK-20: token budget estimation + SSE event — fires before stream starts
    try {
      const { getContextWindow } = require('../helpers/token-estimator');
      const activeModel = identityProfile && identityProfile.model || 'deepseek-chat';
      const activeProvider = identityProvider || 'deepseek';
      const { systemPromptTokens, messagesTokens, total } = estimateRequestTokens({
        systemPrompt,
        messages: trimmedMessages,
        maxTokens: 8192,
      });
      const ctxWindow = await getContextWindow(
        activeModel,
        activeProvider,
        identityProfile && identityProfile.baseUrl,
        null,
        identityProfile && identityProfile.contextWindow,
      ).catch((e) => {
        // BLOCK-102 P1 — silent 64k fallback disabled the context fuse without a trace
        console.error('[ai-chat] context window probe failed:',
          e && e.message ? e.message : e);
        return 0;
      }) || 0;
      const pct = ctxWindow > 0 ? Math.min(100, Math.round((total / ctxWindow) * 100)) : 0;
      res.write('data: ' + JSON.stringify({
        event: 'token_budget',
        contextWindow: ctxWindow || 64000,
        messagesTokensUsed: total,
        systemPromptTokens,
        messagesTokens,
        pct,
        trimmed: total > (ctxWindow || 64000),
      }) + '\n\n');
    } catch (e) {
      console.log('[token-budget-estimation-error]', e && e.message);
    }

    // SSE response headers
    res.setHeader('Content-Type', 'text/event-stream; charset=utf-8');
    res.setHeader('Cache-Control', 'no-cache, no-transform');
    res.setHeader('Connection', 'keep-alive');
    res.setHeader('X-Accel-Buffering', 'no');
    res.flushHeaders && res.flushHeaders();

    let ended = false;
    const writeError = (msg) => {
      if (ended) return;
      try {
        res.write('data: ' + JSON.stringify({ error: msg }) + '\n\n');
      } catch {}
      try {
        res.end();
        ended = true;
      } catch {}
    };

    let assistantAcc = '';
    const finalizeAssistant = () => {
          // Layer 3b: index the just-completed (user, assistant) pair
          try {
            const userId = req.user && req.user.id;
            if (
              userId &&
              assistantAcc &&
              assistantAcc.trim().length > 20 &&
              Array.isArray(messages)
            ) {
              const lastUser = [...messages].reverse().find((m) => m.role === 'user');
              if (lastUser && lastUser.content) {
                const cleanUser = String(lastUser.content).replace(/^\[[^\]]+\]\s*\n?/, '');
                const turnText = '用户: ' + cleanUser + '\n\nAI: ' + assistantAcc.trim();
                (async () => {
                  try {
                    const vecs = await dashscopeEmbed([turnText.slice(0, MAX_CONTENT_LEN)], {
                      userId,
                      kind: 'embedding',
                    });
                    if (vecs && vecs[0]) {
                      saveMemoryVector({
                        userId,
                        projectId,
                        kind: 'chat_turn',
                        refId: null,
                        page: context && context.page,
                        pageTitle: context && context.pageTitle,
                        content: turnText.slice(0, MAX_CONTENT_LEN),
                        vec: vecs[0],
                      });
                      console.log(
                        '[mem-vec] indexed turn user=' + userId + ' len=' + turnText.length
                      );
                    }
                  } catch (e) {
                    console.log('[mem-vec-err]', e && e.message);
                  }
                })();
              }
            }
          } catch (e) {
            console.log('[mem-vec-err]', e && e.message);
          }
          // Layer 3a: extract facts on shorter threads (every 4 turns)
          try {
            const userId = req.user && req.user.id;
            if (
              userId &&
              Array.isArray(messages) &&
              messages.length >= 4 &&
              messages.length <= 22 &&
              messages.length % 4 === 0
            ) {
              backgroundExtractFacts(userId, messages, projectId).catch(() => {});
            }
          } catch (e) {
            console.log('[mem-vec-err]', e && e.message);
          }
          // Layer 2: fire-and-forget summarization if thread has grown
          try {
            const userId = req.user && req.user.id;
            if (userId && Array.isArray(messages) && messages.length > SUMMARY_TRIGGER_AT) {
              const oldMsgs = messages.slice(0, messages.length - SUMMARY_KEEP_RECENT);
              if (oldMsgs.length >= 6) {
                summarizeMessages(userId, projectId, oldMsgs, savedSummary && savedSummary.summary).catch(
                  () => {}
                );
              }
              if (messages.length % 4 === 0) {
                backgroundExtractFacts(userId, messages, projectId).catch(() => {});
              }
            }
          } catch (e) {
            console.log('[mem-vec-err]', e && e.message);
          }
    };

    const abortController = new AbortController();
    modelGateway.chat({
      role: 'chat',
      body: {
        messages: fullMessages,
        temperature: 0.5,
        max_tokens: 16384, // 方案 B：用足够大的值让模型自然停止，而不是物理截断
      },
      telemetry: {
        userId: req.user && req.user.id,
        kind: 'chat',
      },
      signal: abortController.signal,
      onEvent: (event) => {
        if (ended || event.type !== 'content_delta' || !event.content) return;
        assistantAcc += event.content;
        try {
          res.write(
            'data: ' +
              JSON.stringify({ choices: [{ delta: { content: event.content } }] }) +
              '\n\n'
          );
        } catch {}
      },
    }).then((result) => {
      if (ended) return;
      if (!result || result.error) {
        writeError((result && (result.message || result.error)) || '模型请求失败');
        return;
      }
      try {
        res.write('data: [DONE]\n\n');
        res.end();
        ended = true;
      } catch {}
      finalizeAssistant();
    }).catch((error) => writeError('模型请求失败: ' + error.message));

    req.on('aborted', () => {
      if (!ended) {
        ended = true;
        try {
          abortController.abort();
        } catch {}
      }
    });
    res.on('close', () => {
      if (!ended) {
        ended = true;
        try {
          abortController.abort();
        } catch {}
      }
    });
  });
};

/**
 * routes/ai-conversations.js — multi-conversation support endpoints.
 * Migrated from server.js as part of MODULES_BATCH1_v1.
 *
 * Uses the Promise facade over desktop SQLite for route handlers.
 */
const express = require('express');
const dbMod = require('../db');
const adb = dbMod.getAsyncDatabase();
let _projectColumnReady = null;

function _newConvId() {
  const {v4: uuidv4} = require('uuid');
  return 'conv_' + uuidv4().slice(0, 12);
}

function _projectIdFromReq(req) {
  const raw = (req.query && req.query.project_id) || (req.body && (req.body.project_id || req.body.projectId));
  if (typeof raw !== 'string') return null;
  const trimmed = raw.trim();
  return trimmed ? trimmed.slice(0, 120) : null;
}

function ensureProjectColumn() {
  if (!_projectColumnReady) {
    _projectColumnReady = (async () => {
      try { await adb.prepare('ALTER TABLE copilot_conversations ADD COLUMN project_id TEXT').run(); } catch {}
      try { await adb.prepare('CREATE INDEX IF NOT EXISTS idx_conv_project ON copilot_conversations(user_id, project_id, status, updated_at DESC)').run(); } catch {}
    })();
  }
  return _projectColumnReady;
}

module.exports = function mountConversations(app) {
  async function updateConversation(req, res) {
    const userId = req.user && req.user.id;
    if (!userId) return res.status(401).json({status:'error', error:'未授权'});
    try {
      const row = await adb.prepare('SELECT id FROM copilot_conversations WHERE id=? AND user_id=?').get(req.params.id, userId);
      if (!row) return res.status(404).json({status:'error', error:'not_found'});
      const sets = []; const values = [];
      if (req.body && typeof req.body.title === 'string') { sets.push('title=?'); values.push(req.body.title.slice(0, 100)); }
      if (req.body && (req.body.status === 'active' || req.body.status === 'archived')) { sets.push('status=?'); values.push(req.body.status); }
      if (sets.length === 0) return res.status(400).json({status:'error', error:'no_updates'});
      sets.push('updated_at=?'); values.push(new Date().toISOString());
      values.push(req.params.id, userId);
      await adb.prepare(`UPDATE copilot_conversations SET ${sets.join(', ')} WHERE id=? AND user_id=?`).run(...values);
      res.json({status:'ok'});
    } catch (e) { res.status(500).json({status:'error', error: e.message}); }
  }

  app.get('/api/ai/conversations', async (req, res) => {
    const userId = req.user && req.user.id;
    if (!userId) return res.status(401).json({status:'error', error:'未授权'});
    try {
      await ensureProjectColumn();
      const status = (req.query.status === 'archived') ? 'archived' : (req.query.status === 'all' ? null : 'active');
      const projectId = _projectIdFromReq(req);
      // BLOCK-88 P2（D3）— 默认视图隔离：联邦委托会话（origin='federation-delegation'）
      // 不混入宿主默认会话列表；?includeFederated=1 显式查看（独立可见可清理）。
      const includeFederated = req.query.includeFederated === '1';
      const cols = 'id, title, status, last_page, project_id, message_count, created_at, updated_at, last_topic_shift_at, last_topic_shift_reason, parent_id, origin';
      const where = ['user_id=?'];
      const values = [userId];
      if (status) { where.push('status=?'); values.push(status); }
      if (projectId) { where.push('project_id=?'); values.push(projectId); }
      // BLOCK-88 P3：includeFederated=1 且未指定项目时跨项目列出（含已绑定项目的
      // 联邦委托会话——它们 project_id 非空，会被下方空项目子句挡掉）。
      else if (!includeFederated) where.push("COALESCE(project_id, '')=''");
      if (!includeFederated) where.push("(origin IS NULL OR origin != 'federation-delegation')");
      const rows = await adb.prepare(`SELECT ${cols} FROM copilot_conversations WHERE ${where.join(' AND ')} ORDER BY updated_at DESC LIMIT 100`).all(...values);
      res.json({status:'ok', conversations: rows});
    } catch (e) { res.status(500).json({status:'error', error: e.message}); }
  });

  app.post('/api/ai/conversations', express.json({limit: '8kb'}), async (req, res) => {
    const userId = req.user && req.user.id;
    if (!userId) return res.status(401).json({status:'error', error:'未授权'});
    try {
      await ensureProjectColumn();
      const id = _newConvId();
      const now = new Date().toISOString();
      const title = String((req.body && req.body.title) || '新对话').slice(0, 100);
      const lastPage = (req.body && req.body.lastPage) || null;
      const projectId = _projectIdFromReq(req);
      await adb.prepare('INSERT INTO copilot_conversations(id, user_id, title, status, last_page, project_id, created_at, updated_at) VALUES (?,?,?,?,?,?,?,?)')
        .run(id, userId, title, 'active', lastPage, projectId, now, now);
      res.json({status:'ok', conversation: {id, title, status:'active', last_page: lastPage, project_id: projectId, message_count: 0, created_at: now, updated_at: now}});
    } catch (e) { res.status(500).json({status:'error', error: e.message}); }
  });

  app.get('/api/ai/conversations/:id', async (req, res) => {
    const userId = req.user && req.user.id;
    if (!userId) return res.status(401).json({status:'error', error:'未授权'});
    try {
      const row = await adb.prepare('SELECT * FROM copilot_conversations WHERE id=? AND user_id=?').get(req.params.id, userId);
      if (!row) return res.status(404).json({status:'error', error:'not_found'});
      res.json({status:'ok', conversation: row});
    } catch (e) { res.status(500).json({status:'error', error: e.message}); }
  });

  // POST update (workaround for nginx PATCH bug — same body shape as PATCH)
  app.post('/api/ai/conversations/:id/update', express.json({limit: '8kb'}), updateConversation);

  // PATCH compatibility route retained for older clients.
  app.patch('/api/ai/conversations/:id', express.json({limit: '8kb'}), updateConversation);

  app.delete('/api/ai/conversations/:id', async (req, res) => {
    const userId = req.user && req.user.id;
    if (!userId) return res.status(401).json({status:'error', error:'未授权'});
    try {
      const row = await adb.prepare('SELECT id FROM copilot_conversations WHERE id=? AND user_id=?').get(req.params.id, userId);
      if (!row) return res.status(404).json({status:'error', error:'not_found'});
      try { await adb.prepare('DELETE FROM memory_vectors WHERE conversation_id=? AND user_id=?').run(req.params.id, userId); } catch {}
      await adb.prepare('DELETE FROM copilot_messages WHERE conversation_id=?').run(req.params.id);
      await adb.prepare('DELETE FROM copilot_conversations WHERE id=? AND user_id=?').run(req.params.id, userId);
      res.json({status:'ok'});
    } catch (e) { res.status(500).json({status:'error', error: e.message}); }
  });

  app.get('/api/ai/conversations/:id/messages', async (req, res) => {
    const userId = req.user && req.user.id;
    if (!userId) return res.status(401).json({status:'error', error:'未授权'});
    try {
      const conv = await adb.prepare('SELECT id FROM copilot_conversations WHERE id=? AND user_id=?').get(req.params.id, userId);
      if (!conv) return res.status(404).json({status:'error', error:'not_found'});
      const limit = Math.max(1, Math.min(500, parseInt(req.query.limit) || 100));
      // BLOCK-95 A1 — 游标分页：默认返回最新 limit 条（修复旧语义「最旧 limit 条」
      // 导致长会话看不到最近消息）；?before=<rowid> 向上取更旧一页。
      // 游标用 rowid 而非 ts：fork 会话全部消息同 ts（同 now 批量插入），ts 游标会丢页。
      const before = req.query.before ? Math.max(1, parseInt(req.query.before, 10) || 0) : 0;
      const pageSql = 'SELECT id, role, content, meta_json, ts, rowid AS _rid FROM copilot_messages WHERE conversation_id=?'
        + (before ? ' AND rowid < ?' : '')
        + ' ORDER BY rowid DESC LIMIT ?';
      const pageArgs = before ? [req.params.id, before, limit + 1] : [req.params.id, limit + 1];
      const rows = await adb.prepare(pageSql).all(...pageArgs);
      const hasMore = rows.length > limit;
      const page = rows.slice(0, limit);
      page.reverse(); // 展示序 = 时间升序
      let windowOffset = 0;
      let nextBefore = null;
      if (page.length > 0) {
        const minRid = page[0]._rid;
        if (hasMore) nextBefore = minRid;
        const cnt = await adb.prepare('SELECT COUNT(*) AS c FROM copilot_messages WHERE conversation_id=? AND rowid < ?').get(req.params.id, minRid);
        windowOffset = cnt.c;
      }
      const items = page.map(r => {
        const { _rid, ...rest } = r;
        return {...rest, meta: r.meta_json ? (() => { try { return JSON.parse(r.meta_json); } catch { return null; } })() : null};
      });
      // BLOCK-95 B2/A5 — 压缩留痕诚实可见：会话存在 compaction 记录时随信封下发，
      // 前端在信息流展示「上下文压缩视图」标记卡（DB 原文始终可见）。
      let compaction = null;
      try {
        const cRow = await adb.prepare('SELECT summary, covers_count, source_tokens, updated_at FROM conversation_compaction WHERE conversation_id=?').get(req.params.id);
        if (cRow) {
          compaction = {
            summary: cRow.summary,
            coversCount: cRow.covers_count,
            sourceTokens: cRow.source_tokens,
            updatedAt: cRow.updated_at,
          };
        }
      } catch {}
      res.json({status:'ok', messages: items, hasMore, nextBefore, windowOffset, total: windowOffset + items.length, compaction});
    } catch (e) { res.status(500).json({status:'error', error: e.message}); }
  });

  // BLOCK-95 B2 — 手动触发会话压缩（同步等待摘要生成；开关关时诚实 409）。
  app.post('/api/ai/conversations/:id/compact', async (req, res) => {
    const userId = req.user && req.user.id;
    if (!userId) return res.status(401).json({status:'error', error:'未授权'});
    const { isSessionCompactionEnabled, compactConversationNow } = require('../helpers/conversation-compaction');
    if (!isSessionCompactionEnabled(process.env)) {
      return res.status(409).json({status:'error', error:'session compaction disabled'});
    }
    try {
      const conv = await adb.prepare('SELECT id FROM copilot_conversations WHERE id=? AND user_id=?').get(req.params.id, userId);
      if (!conv) return res.status(404).json({status:'error', error:'not_found'});
      const sqliteSync = dbMod.getDatabase();
      const result = await compactConversationNow({ userId, conversationId: req.params.id, sqlite: sqliteSync });
      if (!result.ok) {
        return res.json({status:'ok', compacted:false, reason: result.reason});
      }
      res.json({status:'ok', compacted:true, compaction: {
        summary: result.compaction.summary,
        coversCount: result.compaction.covers_count,
        sourceTokens: result.compaction.source_tokens,
        updatedAt: result.compaction.updated_at,
      }, detail: result.detail});
    } catch (e) { res.status(500).json({status:'error', error: e.message}); }
  });

  app.post('/api/ai/conversations/:id/dismiss-topic-shift', async (req, res) => {
    const userId = req.user && req.user.id;
    if (!userId) return res.status(401).json({status:'error', error:'未授权'});
    try {
      const r = await adb.prepare('UPDATE copilot_conversations SET last_topic_shift_at=NULL, last_topic_shift_reason=NULL WHERE id=? AND user_id=?').run(req.params.id, userId);
      if (r.changes === 0) return res.status(404).json({status:'error', error:'not_found'});
      res.json({status:'ok'});
    } catch (e) { res.status(500).json({status:'error', error: e.message}); }
  });

  // POST /api/ai/conversations/:id/fork — create a new conversation from an existing one
  // Optional body.untilIndex: if provided (0-based), only copy messages up to that index (inclusive).
  app.post('/api/ai/conversations/:id/fork', express.json({limit: '8kb'}), async (req, res) => {
    const userId = req.user && req.user.id;
    if (!userId) return res.status(401).json({status:'error', error:'未授权'});
    try {
      const source = await adb.prepare('SELECT * FROM copilot_conversations WHERE id=? AND user_id=?').get(req.params.id, userId);
      if (!source) return res.status(404).json({status:'error', error:'not_found'});

      const forkId = _newConvId();
      const now = new Date().toISOString();
      const title = String((req.body && req.body.title) || source.title + ' (分支)').slice(0, 100);
      const lastPage = source.last_page || null;
      const projectId = source.project_id || null;
      const parentId = source.id;

      await adb.prepare('INSERT INTO copilot_conversations(id, user_id, title, status, last_page, project_id, parent_id, created_at, updated_at) VALUES (?,?,?,?,?,?,?,?,?)')
        .run(forkId, userId, title, 'active', lastPage, projectId, parentId, now, now);

      // Copy messages — optionally limited by untilIndex (0-based, inclusive).
      // When not specified, all messages are copied (existing behaviour).
      const untilIndex = (req.body && typeof req.body.untilIndex === 'number') ? Math.max(0, Math.floor(req.body.untilIndex)) : null;
      const messages = await adb.prepare('SELECT role, content, meta_json FROM copilot_messages WHERE conversation_id=? ORDER BY ts ASC').all(req.params.id);
      const messagesToCopy = (untilIndex !== null && untilIndex < messages.length) ? messages.slice(0, untilIndex + 1) : messages;
      if (messagesToCopy.length > 0) {
        const stmt = adb.prepare('INSERT INTO copilot_messages(id, conversation_id, role, content, meta_json, ts) VALUES (?,?,?,?,?,?)');
        for (const msg of messagesToCopy) {
          const msgId = 'msg_' + require('uuid').v4().slice(0, 12);
          stmt.run(msgId, forkId, msg.role, msg.content, msg.meta_json, now);
        }
      }

      await adb.prepare('UPDATE copilot_conversations SET message_count=? WHERE id=?').run(messagesToCopy.length, forkId);

      res.json({
        status: 'ok',
        conversation: {
          id: forkId,
          title,
          status: 'active',
          last_page: lastPage,
          project_id: projectId,
          message_count: messagesToCopy.length,
          created_at: now,
          updated_at: now,
          parent_id: parentId,
        }
      });
    } catch (e) { res.status(500).json({status:'error', error: e.message}); }
  });
};

/**
 * routes/ai-legacy.js — small AI compatibility/support endpoints.
 *
 * These routes are platform-owned but remain mounted from the historical
 * petri-server route registry during the gradual backend structure convergence.
 */
const express = require('express');

const {
  lookupCellType,
  callDeepSeekSimple,
  buildInterpretPrompt,
} = require('../helpers/interpret');
const {ackActToken} = require('../agent-tools');
const dbMod = require('../db');

module.exports = function mountAiLegacy(app) {
  app.post('/api/ai/interpret', express.json({limit: '128kb'}), async (req, res) => {
    const {analysisType, summary, topMarkers} = req.body || {};
    if (!analysisType || !summary) {
      return res.status(400).json({status: 'error', error: '缺少参数'});
    }

    const localResults = {};
    if (topMarkers) {
      for (const [cluster, markers] of Object.entries(topMarkers)) {
        const cellType = lookupCellType(markers);
        if (cellType) localResults[cluster] = cellType;
      }
    }

    const prompt = buildInterpretPrompt(analysisType, summary, {topMarkers});
    let aiText = null;
    if (prompt) {
      aiText = await callDeepSeekSimple(prompt);
    }

    if (!aiText) {
      if (analysisType === 'scrna_standard' || analysisType === 'recluster') {
        const {nCells, nGenes, nClusters} = summary;
        let fallback = '✓ 分析完成：' + (nCells || 0).toLocaleString() + ' 个细胞，' + (nGenes || 0).toLocaleString() + ' 个基因，识别出 ' + (nClusters || 0) + ' 个 cluster。';
        if (Object.keys(localResults).length > 0) {
          fallback += '\n\n初步细胞类型推断（基于 marker 查表）：';
          for (const [c, t] of Object.entries(localResults)) {
            fallback += '\n- Cluster ' + c + '：' + t;
          }
        }
        fallback += '\n\n建议：使用 SingleR 做正式细胞注释，或对感兴趣的 cluster 做 DEG 分析。';
        aiText = fallback;
      } else {
        aiText = '分析已完成。请查看下方图表和数据文件了解详情。';
      }
    }

    res.json({
      status: 'ok',
      interpretation: aiText,
      cellTypeHints: localResults,
      source: aiText && !aiText.startsWith('✓') ? 'model_gateway' : 'fallback',
    });
  });

  app.post('/api/ai/act-ack/:token', express.json({limit:'8kb'}), (req, res) => {
    const userId = req.user && req.user.id;
    if (!userId) return res.status(401).json({status: 'error', error: '未授权'});
    const ok = ackActToken(req.params.token, req.body || {ok: true});
    res.json({status: 'ok', acknowledged: ok});
  });

  // TOOL_JOB_APPROVAL_v1（阶段2 Task3）：重操作 run_tool 强制确认 ack 路由。
  // 前端确认卡用户点"开始/取消"后 POST 这里，后端落 ack_status=approved/rejected。
  // agent 下次重调 run_tool(ackToken) 时读到 approved 才续跑。
  app.post('/api/ai/run-tool-ack/:token', express.json({limit:'8kb'}), (req, res) => {
    const userId = req.user && (req.user.id || req.user.userId);
    if (!userId) return res.status(401).json({status: 'error', error: '未授权'});
    const body = req.body && typeof req.body === 'object' ? req.body : {};
    if (!Object.prototype.hasOwnProperty.call(body, 'projectId')
        || !Object.prototype.hasOwnProperty.call(body, 'conversationId')) {
      return res.status(400).json({status: 'error', error: 'approval_scope_required'});
    }
    const approve = body.approve !== false;
    const projectId = typeof body.projectId === 'string' && body.projectId.trim()
      ? body.projectId.trim()
      : null;
    const conversationId = typeof body.conversationId === 'string' && body.conversationId.trim()
      ? body.conversationId.trim()
      : null;
    // Request scope is an expectation only; persisted Job identity is immutable.
    const job = dbMod.ackToolJob(req.params.token, approve, { userId, projectId, conversationId });
    if (!job) return res.status(404).json({status: 'error', error: 'token_not_found'});
    res.json({status: 'ok', ackStatus: job.ack_status, toolJobId: job.id});
  });

};

/**
 * core/petri-server/routes/ai-loop.js
 * HLE-C3: Loop REST API — durable query and recovery.
 *
 * Provides:
 *   GET  /api/loop/runs/:loopRunId           — single LoopRun with compact projection
 *   GET  /api/loop/runs?conversationId=&projectId=&limit=  — list runs for conversation
 *   GET  /api/loop/iterations/:loopRunId    — all iterations for a LoopRun
 *   GET  /api/loop/actions/:loopRunId       — all actions for a LoopRun
 *   GET  /api/loop/evidence/:loopRunId      — all evidence for a LoopRun
 *   GET  /api/loop/recovery/:loopRunId      — recovery projection with next action hint
 *
 * Auth: requires valid session userId.
 * Isolation: users can only see runs for projects they own.
 */

const express = require('express');

const db = require('../db');
const {
  getLoopRun,
  listLoopRunsForConversation,
} = db;

// HLE-C3R: project-ownership isolation. A LoopRun belongs to a project; a user
// may only read runs for projects they own (or public / ownerless legacy
// projects, or as admin). Returns true when access is allowed.
function userMayAccessProject(req, projectId) {
  if (!projectId) return true; // legacy runs without a project ref
  if (req.user && req.user.role === 'admin') return true;
  let project = null;
  try { project = db.getProject(projectId); } catch { project = null; }
  if (!project) return false;
  return Boolean(project.is_public) || !project.user_id || project.user_id === req.userId;
}

function registerAiLoopRoutes(app) {
  const router = express.Router();

  // Auth middleware — ensure userId is available
  function requireUser(req, res, next) {
    // Desktop bootstrap intentionally provides req.user only (single local
    // identity); web/test middleware may provide req.userId. Normalize both.
    req.userId = req.userId || (req.user && req.user.id) || null;
    if (!req.userId) return res.status(401).json({ ok: false, error: 'unauthenticated' });
    next();
  }

  // Load a run and enforce ownership. Sends 404 when missing, 403 when the
  // requesting user does not own the run's project. Returns the run or null.
  function loadRunAuthorized(req, res, loopRunId) {
    const run = getLoopRun(loopRunId);
    if (!run) {
      res.status(404).json({ ok: false, error: 'loop_run_not_found' });
      return null;
    }
    if (!userMayAccessProject(req, run.projectId)) {
      res.status(403).json({ ok: false, error: 'forbidden' });
      return null;
    }
    return run;
  }

  /**
   * GET /api/loop/session-summary?projectId=&conversationId=
   * One bounded projection for cold start/reopen: latest durable run, public
   * conclusions, project activity counts, recovery state and conversation
   * token/cost usage. All fields come from SQLite truth.
   */
  router.get('/session-summary', requireUser, (req, res) => {
    const projectId = String(req.query.projectId || '');
    const conversationId = String(req.query.conversationId || '');
    if (!projectId || !conversationId) {
      return res.status(400).json({ ok: false, error: 'projectId and conversationId required' });
    }
    if (!userMayAccessProject(req, projectId)) {
      return res.status(403).json({ ok: false, error: 'forbidden' });
    }
    try {
      const projectRuns = listLoopRunsForConversation(projectId, null, { limit: 100 });
      const conversationRuns = projectRuns.filter((run) => run.conversationId === conversationId);
      const run = conversationRuns[0] || null;
      let iterations = [];
      if (run) {
        iterations = (db.listLoopIterations(run.loopRunId, { limit: 200 }) || [])
          .slice()
          .sort((a, b) => (a.sequence || 0) - (b.sequence || 0))
          .map((iteration) => ({
            iterationId: iteration.iterationId,
            loopRunId: iteration.loopRunId,
            sequence: iteration.sequence,
            decision: iteration.decision,
            decisionReasonCode: iteration.decisionReasonCode,
            status: iteration.status,
            publicConclusion: iteration.publicConclusion,
            createdAt: iteration.createdAt,
          }));
      }
      const activeRuns = projectRuns.filter((item) =>
        ['planned', 'running', 'waiting_for_user'].includes(item.loopStatus)
      );
      const record = run?.record && typeof run.record === 'object' ? run.record : {};
      const usage = require('../helpers/ai-usage').summarizeAiUsage({
        userId: req.userId,
        conversationId,
      });
      res.json({
        ok: true,
        summary: {
          run: run ? {
            loopRunId: run.loopRunId,
            projectId: run.projectId,
            conversationId: run.conversationId,
            taskSpecRef: run.taskSpecRef,
            automationMode: run.automationMode,
            executionIntent: run.executionIntent,
            loopStatus: run.loopStatus,
            hash: run.hash,
            isPartial: Boolean(run.isPartial),
            partialReason: run.partialReason || null,
            recoveryRequired: Boolean(record.recovery_required),
            recoveryReason: record.recovery_reason || null,
            createdAt: run.createdAt,
            updatedAt: run.updatedAt,
          } : null,
          iterations,
          activeCount: activeRuns.length,
          backgroundCount: activeRuns.filter((item) => item.conversationId !== conversationId).length,
          usage,
        },
      });
    } catch (err) {
      return res.status(500).json({ ok: false, error: err.message });
    }
  });

  /**
   * GET /api/loop/runs/:loopRunId
   * Returns a single LoopRun with compact projection.
   * Does NOT return unbounded logs or raw full tool_results.
   */
  router.get('/runs/:loopRunId', requireUser, (req, res) => {
    const { loopRunId } = req.params;
    if (!loopRunId) return res.status(400).json({ ok: false, error: 'missing loopRunId' });

    try {
      const run = loadRunAuthorized(req, res, loopRunId);
      if (!run) return undefined;

      // Compact projection: strip raw unbounded fields
      const compact = {
        loopRunId: run.loopRunId,
        projectId: run.projectId,
        conversationId: run.conversationId,
        taskSpecRef: run.taskSpecRef,
        automationMode: run.automationMode,
        executionIntent: run.executionIntent,
        loopStatus: run.loopStatus,
        hash: run.hash,
        isPartial: Boolean(run.isPartial),
        partialReason: run.partialReason || null,
        createdAt: run.createdAt,
        updatedAt: run.updatedAt,
      };

      // HLE-C3R: optional expanded projection with durable recovery detail.
      if (req.query.expanded === '1' || req.query.expanded === 'true') {
        let iterations = [];
        let evidenceCount = 0;
        try {
          iterations = (db.listLoopIterations(loopRunId, { limit: 20 }) || []).map((it) => ({
            iterationId: it.iterationId,
            sequence: it.sequence,
            decision: it.decision,
            decisionReasonCode: it.decisionReasonCode,
            status: it.status,
            publicConclusion: it.publicConclusion,
            createdAt: it.createdAt,
          }));
        } catch {}
        try { evidenceCount = (db.listLoopEvidence(loopRunId, { limit: 500 }) || []).length; } catch {}
        const record = run.record && typeof run.record === 'object' ? run.record : {};
        compact.recoveryRequired = Boolean(record.recovery_required);
        compact.recoveryReason = record.recovery_reason || null;
        compact.abortedByUser = Boolean(record.abortedByUser);
        compact.recentIterations = iterations;
        compact.evidenceCount = evidenceCount;
      }

      res.json({ ok: true, run: compact });
    } catch (err) {
      res.status(500).json({ ok: false, error: err.message });
    }
  });

  /**
   * GET /api/loop/runs
   * Query runs by conversationId or projectId.
   * ?conversationId=...&projectId=...&limit=10
   */
  router.get('/runs', requireUser, (req, res) => {
    const { conversationId, projectId, limit = 20 } = req.query;
    const parsedLimit = Math.min(Math.max(1, parseInt(limit, 10) || 20), 100);

    if (!conversationId && !projectId) {
      return res.status(400).json({ ok: false, error: 'conversationId or projectId required' });
    }

    try {
      const runs = listLoopRunsForConversation(projectId || null, conversationId || null, { limit: parsedLimit })
        .filter((run) => userMayAccessProject(req, run.projectId));
      const compact = runs.map((run) => ({
        loopRunId: run.loopRunId,
        projectId: run.projectId,
        conversationId: run.conversationId,
        taskSpecRef: run.taskSpecRef,
        automationMode: run.automationMode,
        executionIntent: run.executionIntent,
        loopStatus: run.loopStatus,
        hash: run.loopStatusHash || run.hash,
        isPartial: Boolean(run.isPartial),
        partialReason: run.partialReason || null,
        createdAt: run.createdAt,
        updatedAt: run.updatedAt,
        // AGENT-CONCURRENCY: expose identity so the client can resume orphaned
        // sub-agent runs after a crash/refresh.
        kind: run.kind || 'primary',
        parentLoopRunId: run.parentLoopRunId || null,
        taskId: run.taskId || null,
      }));
      res.json({ ok: true, runs: compact, count: compact.length });
    } catch (err) {
      res.status(500).json({ ok: false, error: err.message });
    }
  });

  /**
   * GET /api/loop/iterations/:loopRunId
   * Returns all iterations for a LoopRun, compact projection.
   */
  router.get('/iterations/:loopRunId', requireUser, (req, res) => {
    const { loopRunId } = req.params;
    if (!loopRunId) return res.status(400).json({ ok: false, error: 'missing loopRunId' });
    if (!loadRunAuthorized(req, res, loopRunId)) return undefined;

    try {
      const { listLoopIterations } = require('../db');
      if (!listLoopIterations) {
        // Fallback: return empty list if function not exported yet
        return res.json({ ok: true, iterations: [], count: 0 });
      }
      const iterations = listLoopIterations(loopRunId, { limit: 200 });
      const compact = iterations.map((iter) => ({
        iterationId: iter.iterationId,
        loopRunId: iter.loopRunId,
        sequence: iter.sequence,
        decision: iter.decision,
        decisionReasonCode: iter.decisionReasonCode,
        status: iter.status,
        publicConclusion: iter.publicConclusion,
        hash: iter.hash,
        createdAt: iter.createdAt,
      }));
      res.json({ ok: true, iterations: compact, count: compact.length });
    } catch (err) {
      res.status(500).json({ ok: false, error: err.message });
    }
  });

  /**
   * GET /api/loop/actions/:loopRunId
   * Returns all actions for a LoopRun, compact projection.
   */
  router.get('/actions/:loopRunId', requireUser, (req, res) => {
    const { loopRunId } = req.params;
    if (!loopRunId) return res.status(400).json({ ok: false, error: 'missing loopRunId' });
    if (!loadRunAuthorized(req, res, loopRunId)) return undefined;

    try {
      const { listLoopActions } = require('../db');
      if (!listLoopActions) {
        return res.json({ ok: true, actions: [], count: 0 });
      }
      const actions = listLoopActions(loopRunId, { limit: 200 });
      const compact = actions.map((a) => ({
        actionId: a.actionId,
        loopRunId: a.loopRunId,
        sequence: a.sequence,
        actionKey: a.actionKey,
        actionType: a.actionType,
        toolId: a.toolId,
        attempt: a.attempt,
        hash: a.hash,
        createdAt: a.createdAt,
      }));
      res.json({ ok: true, actions: compact, count: compact.length });
    } catch (err) {
      res.status(500).json({ ok: false, error: err.message });
    }
  });

  /**
   * GET /api/loop/evidence/:loopRunId
   * Returns all evidence for a LoopRun, compact projection.
   */
  router.get('/evidence/:loopRunId', requireUser, (req, res) => {
    const { loopRunId } = req.params;
    if (!loopRunId) return res.status(400).json({ ok: false, error: 'missing loopRunId' });
    if (!loadRunAuthorized(req, res, loopRunId)) return undefined;

    try {
      const { listLoopEvidence } = require('../db');
      if (!listLoopEvidence) {
        return res.json({ ok: true, evidence: [], count: 0 });
      }
      const evidence = listLoopEvidence(loopRunId, { limit: 500 });
      const compact = evidence.map((e) => ({
        evidenceId: e.evidenceId,
        loopRunId: e.loopRunId,
        iterationId: e.iterationId,
        kind: e.kind,
        ref: e.ref,
        summaryDigest: e.summaryDigest,
        hash: e.hash,
        createdAt: e.createdAt,
      }));
      res.json({ ok: true, evidence: compact, count: compact.length });
    } catch (err) {
      res.status(500).json({ ok: false, error: err.message });
    }
  });

  /**
   * GET /api/loop/recovery/:loopRunId
   * Returns a recovery projection:
   *   - Current loop state
   *   - Last iteration summary
   *   - Failed/pending jobs needing recovery
   *   - Next recommended action hint
   *   - Whether the loop can be safely resumed
   */
  router.get('/recovery/:loopRunId', requireUser, (req, res) => {
    const { loopRunId } = req.params;
    if (!loopRunId) return res.status(400).json({ ok: false, error: 'missing loopRunId' });

    try {
      const run = loadRunAuthorized(req, res, loopRunId);
      if (!run) return undefined;

      // getLoopRun() returns the parsed status JSON under `record` (NOT
      // loopStatusJson — that field does not exist on the projection).
      const statusJson = (run.record && typeof run.record === 'object') ? run.record : {};

      // Determine recovery state. A server restart marks an interrupted run
      // failed(recovery_required=true); surface that as needing recovery even
      // though the status is terminal, but do NOT report it as safely resumable.
      const isTerminal = ['completed', 'failed', 'cancelled'].includes(run.loopStatus);
      const recoveryRequired = Boolean(statusJson.recovery_required);
      const needsRecovery = run.loopStatus === 'running' || recoveryRequired;

      // Get last iteration
      let lastIteration = null;
      try {
        const { listLoopIterations } = require('../db');
        if (listLoopIterations) {
          const iters = listLoopIterations(loopRunId, { limit: 1 });
          lastIteration = iters.length > 0 ? {
            iterationId: iters[0].iterationId,
            sequence: iters[0].sequence,
            decision: iters[0].decision,
            decisionReasonCode: iters[0].decisionReasonCode,
            status: iters[0].status,
            publicConclusion: iters[0].publicConclusion,
          } : null;
        }
      } catch {}

      const recovery = {
        loopRunId: run.loopRunId,
        projectId: run.projectId,
        conversationId: run.conversationId,
        loopStatus: run.loopStatus,
        automationMode: run.automationMode,
        executionIntent: run.executionIntent,
        isTerminal,
        needsRecovery,
        recoveryRequired,
        canResume: run.loopStatus === 'running' && !recoveryRequired,
        lastIteration,
        statusJson,
        recoveryHint: _buildRecoveryHint(run, lastIteration, statusJson),
      };

      res.json({ ok: true, recovery });
    } catch (err) {
      res.status(500).json({ ok: false, error: err.message });
    }
  });

  /**
   * POST /api/loop/runs/:loopRunId/abort
   * Signal the loop to abort on next pre-turn check.
   * Writes abort flag to loop_status_json.
   */
  router.post('/runs/:loopRunId/abort', requireUser, (req, res) => {
    const { loopRunId } = req.params;
    if (!loopRunId) return res.status(400).json({ ok: false, error: 'missing loopRunId' });

    try {
      const run = loadRunAuthorized(req, res, loopRunId);
      if (!run) return undefined;
      if (['completed', 'failed', 'cancelled'].includes(run.loopStatus)) {
        return res.status(409).json({ ok: false, error: 'loop_already_terminal' });
      }

      const { updateLoopRunStatus } = require('../db');
      const statusJson = { ...(run.record || {}), abortedByUser: true, abortedAt: new Date().toISOString() };
      updateLoopRunStatus(loopRunId, {
        loopStatus: run.loopStatus, // keep running
        hash: run.hash,
        json: JSON.stringify(statusJson),
        updatedAt: new Date().toISOString(),
      });
      res.json({ ok: true, loopRunId, aborted: true, updatedAt: statusJson.abortedAt });
    } catch (err) {
      res.status(500).json({ ok: false, error: err.message });
    }
  });

  // Mount at /api/loop
  app.use('/api/loop', router);
}

function _buildRecoveryHint(run, lastIteration, statusJson) {
  if (['completed', 'cancelled'].includes(run.loopStatus)) {
    return 'Loop 已终止，无恢复必要。';
  }
  if (run.loopStatus === 'failed') {
    return 'Loop 失败，请查看 iterations 和 evidence 了解失败原因。';
  }
  if (statusJson.abortedByUser) {
    return '用户已终止，可重新发起新的任务。';
  }
  if (lastIteration) {
    if (lastIteration.decision === 'block') {
      return `上一轮决策为 block（${lastIteration.decisionReasonCode}）：${lastIteration.publicConclusion || '请修复问题后重试。'}`;
    }
    if (lastIteration.decision === 'retry') {
      return `上一轮决策为 retry（${lastIteration.decisionReasonCode}）：${lastIteration.publicConclusion || '系统将自动重试。'}`;
    }
    return `上一轮决策：${lastIteration.decision}（${lastIteration.decisionReasonCode}）。`;
  }
  return 'Loop 处于 running 状态，可安全恢复。';
}

module.exports = { registerAiLoopRoutes };

/**
 * routes/ai-memory.js — facts / summary / memories / vectors / wipe.
 * Migrated from server.js as part of MODULES_BATCH1_v1.
 *
 * Uses the Promise facade over desktop SQLite for consistent async handlers.
 */
const express = require('express');
const dbMod = require('../db');
const adb = dbMod.getAsyncDatabase();
const sqlite = dbMod.getDatabase();

try { sqlite.exec('ALTER TABLE user_facts ADD COLUMN project_id TEXT'); } catch {}
try { sqlite.exec('ALTER TABLE memory_vectors ADD COLUMN project_id TEXT'); } catch {}
try { sqlite.exec('CREATE INDEX IF NOT EXISTS idx_user_facts_project ON user_facts(user_id, project_id, pinned DESC, updated_at DESC)'); } catch {}
try { sqlite.exec('CREATE INDEX IF NOT EXISTS idx_memvec_project ON memory_vectors(user_id, project_id, ts DESC)'); } catch {}
try {
  sqlite.exec(`
    UPDATE memory_vectors
    SET project_id = (
      SELECT c.project_id FROM copilot_conversations c
      WHERE c.id = memory_vectors.conversation_id
    )
    WHERE project_id IS NULL
      AND conversation_id IS NOT NULL
      AND EXISTS (
        SELECT 1 FROM copilot_conversations c
        WHERE c.id = memory_vectors.conversation_id
          AND c.project_id IS NOT NULL
      )
  `);
} catch {}
try {
  sqlite.exec(`CREATE TABLE IF NOT EXISTS project_chat_summaries (
    user_id TEXT NOT NULL,
    project_id TEXT NOT NULL DEFAULT '',
    summary TEXT NOT NULL,
    msg_count INTEGER NOT NULL DEFAULT 0,
    updated_at TEXT NOT NULL,
    PRIMARY KEY (user_id, project_id)
  )`);
} catch {}

function _projectIdFromReq(req) {
  const raw = (req.query && (req.query.project_id || req.query.projectId))
    || (req.body && (req.body.project_id || req.body.projectId));
  return typeof raw === 'string' && raw.trim() ? raw.trim().slice(0, 120) : null;
}

function _scope(projectId) {
  return projectId
    ? { clause: 'project_id=?', values: [projectId], key: projectId }
    : { clause: "COALESCE(project_id, '')=''", values: [], key: '' };
}

module.exports = function mountMemory(app) {

  // -------- facts (Layer 3a) --------
  app.get('/api/ai/facts', async (req, res) => {
    const userId = req.user && req.user.id;
    if (!userId) return res.status(401).json({status:'error', error:'未授权'});
    try {
      const projectId = _projectIdFromReq(req);
      const scope = _scope(projectId);
      const rows = await adb.prepare(`SELECT id, category, content, pinned, source, project_id, created_at, updated_at FROM user_facts WHERE user_id=? AND ${scope.clause} ORDER BY pinned DESC, updated_at DESC`).all(userId, ...scope.values);
      res.json({status:'ok', facts: rows.map(r => ({...r, pinned: !!r.pinned}))});
    } catch (e) { res.status(500).json({status:'error', error: e.message}); }
  });

  app.post('/api/ai/facts', express.json({limit: '8kb'}), async (req, res) => {
    const userId = req.user && req.user.id;
    if (!userId) return res.status(401).json({status:'error', error:'未授权'});
    try {
      const {v4: uuidv4} = require('uuid');
      const {category, content, pinned, source} = req.body || {};
      const projectId = _projectIdFromReq(req);
      const allowedCats = ['research_focus', 'preference', 'entity', 'task_state', 'note'];
      if (!allowedCats.includes(category)) return res.status(400).json({status:'error', error:'invalid_category'});
      if (!content || typeof content !== 'string') return res.status(400).json({status:'error', error:'missing_content'});
      const id = 'fact_' + uuidv4().slice(0, 12);
      const now = new Date().toISOString();
      await adb.prepare('INSERT INTO user_facts(id, user_id, category, content, pinned, source, project_id, created_at, updated_at) VALUES (?,?,?,?,?,?,?,?,?)')
        .run(id, userId, category, content.slice(0, 1000), pinned ? 1 : 0, source || 'manual', projectId, now, now);
      const fact = await adb.prepare('SELECT id, category, content, pinned, source, project_id, created_at, updated_at FROM user_facts WHERE id=?').get(id);
      res.json({status:'ok', fact: {...fact, pinned: !!fact.pinned}});
    } catch (e) { res.status(500).json({status:'error', error: e.message}); }
  });

  app.put('/api/ai/facts/:id', express.json({limit: '8kb'}), async (req, res) => {
    const userId = req.user && req.user.id;
    if (!userId) return res.status(401).json({status:'error', error:'未授权'});
    try {
      const projectId = _projectIdFromReq(req);
      const scope = _scope(projectId);
      const row = await adb.prepare(`SELECT id FROM user_facts WHERE id=? AND user_id=? AND ${scope.clause}`).get(req.params.id, userId, ...scope.values);
      if (!row) return res.status(404).json({status:'error', error:'not_found'});
      const {content, pinned, category} = req.body || {};
      const sets = []; const values = [];
      if (typeof content === 'string') { sets.push('content=?'); values.push(content.slice(0, 1000)); }
      if (typeof pinned === 'boolean') { sets.push('pinned=?'); values.push(pinned ? 1 : 0); }
      if (typeof category === 'string') { sets.push('category=?'); values.push(category); }
      if (sets.length === 0) return res.status(400).json({status:'error', error:'no_updates'});
      sets.push('updated_at=?'); values.push(new Date().toISOString());
      values.push(req.params.id, userId, ...scope.values);
      await adb.prepare(`UPDATE user_facts SET ${sets.join(', ')} WHERE id=? AND user_id=? AND ${scope.clause}`).run(...values);
      const fact = await adb.prepare('SELECT id, category, content, pinned, source, project_id, created_at, updated_at FROM user_facts WHERE id=?').get(req.params.id);
      res.json({status:'ok', fact: {...fact, pinned: !!fact.pinned}});
    } catch (e) { res.status(500).json({status:'error', error: e.message}); }
  });

  app.delete('/api/ai/facts/:id', async (req, res) => {
    const userId = req.user && req.user.id;
    if (!userId) return res.status(401).json({status:'error', error:'未授权'});
    try {
      const scope = _scope(_projectIdFromReq(req));
      const r = await adb.prepare(`DELETE FROM user_facts WHERE id=? AND user_id=? AND ${scope.clause}`).run(req.params.id, userId, ...scope.values);
      if (r.changes === 0) return res.status(404).json({status:'error', error:'not_found'});
      res.json({status:'ok'});
    } catch (e) { res.status(500).json({status:'error', error: e.message}); }
  });

  app.delete('/api/ai/facts', async (req, res) => {
    const userId = req.user && req.user.id;
    if (!userId) return res.status(401).json({status:'error', error:'未授权'});
    try {
      const scope = _scope(_projectIdFromReq(req));
      await adb.prepare(`DELETE FROM user_facts WHERE user_id=? AND ${scope.clause}`).run(userId, ...scope.values);
      res.json({status:'ok'});
    } catch (e) { res.status(500).json({status:'error', error: e.message}); }
  });

  // -------- summary (Layer 2) --------
  app.get('/api/ai/summary', async (req, res) => {
    const userId = req.user && req.user.id;
    if (!userId) return res.status(401).json({status:'error', error:'未授权'});
    try {
      const projectId = _projectIdFromReq(req);
      const row = await adb.prepare('SELECT summary, msg_count, updated_at FROM project_chat_summaries WHERE user_id=? AND project_id=?').get(userId, _scope(projectId).key);
      res.json({status:'ok', summary: row ? row.summary : null, msgCount: row ? row.msg_count : 0, updatedAt: row ? row.updated_at : null});
    } catch (e) { res.status(500).json({status:'error', error: e.message}); }
  });

  app.delete('/api/ai/summary', async (req, res) => {
    const userId = req.user && req.user.id;
    if (!userId) return res.status(401).json({status:'error', error:'未授权'});
    try {
      const projectId = _projectIdFromReq(req);
      await adb.prepare('DELETE FROM project_chat_summaries WHERE user_id=? AND project_id=?').run(userId, _scope(projectId).key);
      res.json({status:'ok'});
    } catch (e) { res.status(500).json({status:'error', error: e.message}); }
  });

  // -------- memories (Layer 3b vector store) --------
  app.get('/api/ai/memories', async (req, res) => {
    const userId = req.user && req.user.id;
    if (!userId) return res.status(401).json({status:'error', error:'未授权'});
    try {
      const scope = _scope(_projectIdFromReq(req));
      const totalRow = await adb.prepare(`SELECT COUNT(*) AS c FROM memory_vectors WHERE user_id=? AND ${scope.clause}`).get(userId, ...scope.values);
      const rows = await adb.prepare(`SELECT id, kind, page, page_title, content, ts, ref_id, project_id FROM memory_vectors WHERE user_id=? AND ${scope.clause} ORDER BY ts DESC LIMIT 50`).all(userId, ...scope.values);
      res.json({status:'ok', memories: rows, total: totalRow.c});
    } catch (e) { res.status(500).json({status:'error', error: e.message}); }
  });

  app.post('/api/ai/memories/search', express.json({limit: '8kb'}), async (req, res) => {
    const userId = req.user && req.user.id;
    if (!userId) return res.status(401).json({status:'error', error:'未授权'});
    try {
      const q = String((req.body && req.body.q) || '').trim();
      if (q.length < 3) return res.status(400).json({status:'error', error:'query_too_short'});
      const dashscopeEmbed = globalThis._petri && globalThis._petri.dashscopeEmbed;
      const cosineSim = globalThis._petri && globalThis._petri.cosineSim;
      if (!dashscopeEmbed || !cosineSim) return res.status(500).json({status:'error', error:'helpers_missing'});
      const vecs = await dashscopeEmbed([q], {userId});
      if (!vecs || !vecs[0]) return res.json({status:'ok', hits: []});
      const queryVec = vecs[0];
      const scope = _scope(_projectIdFromReq(req));
      const rows = await adb.prepare(`SELECT id, kind, page, page_title, content, embedding, ts, ref_id FROM memory_vectors WHERE user_id=? AND ${scope.clause} ORDER BY ts DESC LIMIT 1000`).all(userId, ...scope.values);
      const hits = [];
      for (const r of rows) {
        const v = new Float32Array(r.embedding.buffer, r.embedding.byteOffset, r.embedding.byteLength / 4);
        const sim = cosineSim(queryVec, v);
        hits.push({id: r.id, kind: r.kind, page: r.page, page_title: r.page_title, content: r.content, ts: r.ts, ref_id: r.ref_id, sim});
      }
      hits.sort((a, b) => b.sim - a.sim);
      res.json({status:'ok', hits: hits.slice(0, 30)});
    } catch (e) { res.status(500).json({status:'error', error: e.message}); }
  });

  app.delete('/api/ai/memories/:id', async (req, res) => {
    const userId = req.user && req.user.id;
    if (!userId) return res.status(401).json({status:'error', error:'未授权'});
    try {
      const scope = _scope(_projectIdFromReq(req));
      const r = await adb.prepare(`DELETE FROM memory_vectors WHERE id=? AND user_id=? AND ${scope.clause}`).run(req.params.id, userId, ...scope.values);
      if (r.changes === 0) return res.status(404).json({status:'error', error:'not_found'});
      res.json({status:'ok'});
    } catch (e) { res.status(500).json({status:'error', error: e.message}); }
  });

  app.delete('/api/ai/memories', async (req, res) => {
    const userId = req.user && req.user.id;
    if (!userId) return res.status(401).json({status:'error', error:'未授权'});
    try {
      const scope = _scope(_projectIdFromReq(req));
      await adb.prepare(`DELETE FROM memory_vectors WHERE user_id=? AND ${scope.clause}`).run(userId, ...scope.values);
      res.json({status:'ok'});
    } catch (e) { res.status(500).json({status:'error', error: e.message}); }
  });

  // -------- aggregate stats + wipe --------
  app.get('/api/ai/memory-stats', async (req, res) => {
    const userId = req.user && req.user.id;
    if (!userId) return res.status(401).json({status:'error', error:'未授权'});
    try {
      const projectId = _projectIdFromReq(req);
      const scope = _scope(projectId);
      const factsRow = await adb.prepare(`SELECT COUNT(*) AS c FROM user_facts WHERE user_id=? AND ${scope.clause}`).get(userId, ...scope.values);
      const hasSummary = (await adb.prepare('SELECT 1 AS x FROM project_chat_summaries WHERE user_id=? AND project_id=?').get(userId, scope.key)) ? true : false;
      const vectorsRow = await adb.prepare(`SELECT COUNT(*) AS c FROM memory_vectors WHERE user_id=? AND ${scope.clause}`).get(userId, ...scope.values);
      res.json({status:'ok', facts: factsRow.c, hasSummary, vectors: vectorsRow.c});
    } catch (e) { res.status(500).json({status:'error', error: e.message}); }
  });

  app.post('/api/ai/memory-wipe', async (req, res) => {
    const userId = req.user && req.user.id;
    if (!userId) return res.status(401).json({status:'error', error:'未授权'});
    const projectId = _projectIdFromReq(req);
    const scope = _scope(projectId);
    let removed = 0;
    try { removed += (await adb.prepare(`DELETE FROM user_facts WHERE user_id=? AND ${scope.clause}`).run(userId, ...scope.values)).changes; } catch {}
    try { removed += (await adb.prepare('DELETE FROM project_chat_summaries WHERE user_id=? AND project_id=?').run(userId, scope.key)).changes; } catch {}
    try { removed += (await adb.prepare(`DELETE FROM memory_vectors WHERE user_id=? AND ${scope.clause}`).run(userId, ...scope.values)).changes; } catch {}
    res.json({status:'ok', removed});
  });
};

/**
 * routes/feature-flags.js — 灰度功能开关 REST 面（设置页投影 + 写入）
 *
 * GET  /api/feature-flags → 三开关快照（enabled/envOverride/stored/default/label/description）
 * POST /api/feature-flags → { key, enabled } 写持久化选择（env 强制覆盖时返回 409 诚实拒绝）
 */

const express = require('express');
const featureFlags = require('../helpers/feature-flags');

module.exports = function mountFeatureFlags(app) {
  app.get('/api/feature-flags', (req, res) => {
    try {
      const flags = featureFlags.getFlagsSnapshot(process.env);
      res.json({ status: 'ok', flags });
    } catch (e) {
      res.status(500).json({ status: 'error', error: e.message });
    }
  });

  app.post('/api/feature-flags', express.json({ limit: '4kb' }), (req, res) => {
    try {
      const key = req.body && req.body.key;
      const enabled = req.body && req.body.enabled;
      const meta = featureFlags.FLAG_META[key];
      if (!meta) return res.status(400).json({ status: 'error', error: `feature_flag_unknown:${key}` });
      if (typeof enabled !== 'boolean') {
        return res.status(400).json({ status: 'error', error: 'feature_flag_value_invalid' });
      }
      // env 强制覆盖时写持久化是误导（解析结果不变）→ 诚实拒绝并指明覆盖来源
      const snapshot = featureFlags.getFlagsSnapshot(process.env);
      if (snapshot[key] && snapshot[key].envOverride != null) {
        return res.status(409).json({
          status: 'error',
          error: `feature_flag_env_locked:${meta.env}（环境变量正在强制覆盖该开关，清除环境变量后方可经设置页切换）`,
        });
      }
      featureFlags.setFlag(key, enabled);
      res.json({ status: 'ok', flags: featureFlags.getFlagsSnapshot(process.env) });
    } catch (e) {
      res.status(500).json({ status: 'error', error: e.message });
    }
  });
};

/**
 * User Feedback channel — collects in-product feedback from users (logged in or anonymous)
 * and pings Feishu in realtime so the team sees issues as they happen.
 *
 * Endpoints:
 *   POST /api/feedback         (public — anonymous OK)  → submit feedback
 *   GET  /api/feedback/admin   (admin only)             → list with filters
 *   PUT  /api/feedback/admin/:id (admin only)           → update status / notes
 */

const express = require('express');
const dbMod = require('../db');
const notify = require('../notify-feishu');
const ipGeo = require('../helpers/ip-geo');
// Keep request-path feedback operations on the async database adapter.
const _dbSync = dbMod.getDatabase(); // for CREATE TABLE (runs once at startup)
const dbAsync = dbMod.getAsyncDatabase();

// ---- Schema ----
_dbSync.exec(`
  CREATE TABLE IF NOT EXISTS feedbacks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id TEXT,                 -- nullable: anonymous feedback allowed
    username TEXT,                -- denormalized snapshot at submit time
    category TEXT DEFAULT 'other', -- bug | suggestion | content | other
    content TEXT NOT NULL,
    page_url TEXT,
    user_agent TEXT,
    ip TEXT,
    status TEXT DEFAULT 'new',    -- new | in_progress | resolved | dismissed
    admin_notes TEXT,
    created_at INTEGER NOT NULL,
    resolved_at INTEGER
  );
  CREATE INDEX IF NOT EXISTS idx_feedbacks_status ON feedbacks(status);
  CREATE INDEX IF NOT EXISTS idx_feedbacks_created ON feedbacks(created_at);
  CREATE INDEX IF NOT EXISTS idx_feedbacks_user ON feedbacks(user_id);
`);

// ---- Rate limit (per-IP, in-memory) ----
const _rateMap = new Map(); // ip -> [t1, t2, ...]
const _RATE_LIMIT = 5;       // max 5 submissions per minute per IP
const _RATE_WINDOW_MS = 60_000;

function _checkRate(ip) {
  if (!ip) return true;
  const now = Date.now();
  const arr = (_rateMap.get(ip) || []).filter(t => now - t < _RATE_WINDOW_MS);
  if (arr.length >= _RATE_LIMIT) {
    _rateMap.set(ip, arr);
    return false;
  }
  arr.push(now);
  _rateMap.set(ip, arr);
  return true;
}

function _clientIp(req) {
  return (req.headers['x-forwarded-for'] || req.ip || req.socket?.remoteAddress || '').split(',')[0].trim();
}

function _userIdFromReq(req) {
  return req.user && (req.user.id || req.user.userId) || null;
}

function _isAdmin(req) {
  return req.user && req.user.role === 'admin';
}

module.exports = function registerFeedback(app) {
  // ---- Public: submit feedback (anonymous allowed) ----
  // Use the async adapter so inserts do not block concurrent requests.
  app.post('/api/feedback', express.json({limit: '32kb'}), async (req, res) => {
    const ip = _clientIp(req);
    if (!_checkRate(ip)) {
      return res.status(429).json({status: 'error', error: '提交过于频繁，请稍后再试（1 分钟 5 条上限）'});
    }

    const {content, category, pageUrl} = req.body || {};
    if (!content || typeof content !== 'string') {
      return res.status(400).json({status: 'error', error: '请填写反馈内容'});
    }
    const trimmed = content.trim();
    if (trimmed.length < 5) {
      return res.status(400).json({status: 'error', error: '反馈内容太短（至少 5 个字）'});
    }
    if (trimmed.length > 4000) {
      return res.status(400).json({status: 'error', error: '反馈内容过长（最多 4000 字）'});
    }

    const validCategories = ['bug', 'suggestion', 'content', 'other'];
    const cat = validCategories.includes(category) ? category : 'other';

    const userId = _userIdFromReq(req);
    let username = null;
    if (userId) {
      try {
        const u = _dbSync.prepare('SELECT username FROM users WHERE id=?').get(userId);
        username = u && u.username;
      } catch {}
    }

    const userAgent = String(req.headers['user-agent'] || '').slice(0, 500);
    const url = String(pageUrl || req.headers['referer'] || '').slice(0, 500);

    // Insert through the async adapter used by request-path feedback operations.
    let feedbackId = null;
    try {
      const insertResult = await dbAsync.prepare(
        'INSERT INTO feedbacks (user_id, username, category, content, page_url, user_agent, ip, created_at) VALUES (?,?,?,?,?,?,?,?) RETURNING id'
      ).run(userId, username, cat, trimmed, url, userAgent, ip, Date.now());
      feedbackId = insertResult && insertResult.rows && insertResult.rows[0] && insertResult.rows[0].id;
    } catch (e) {
      console.error('[feedback] insert failed:', e.message);
      return res.status(500).json({status: 'error', error: '提交失败，请稍后再试'});
    }

    // Realtime Feishu notification (best-effort; never blocks the response)
    try {
      const categoryLabel = {bug: '🐛 Bug', suggestion: '💡 建议', content: '📝 内容', other: '💬 其他'}[cat] || cat;
      const userLabel = username ? `**${username}**` : '*<匿名访客>*';
      const preview = trimmed.length > 280 ? trimmed.slice(0, 280) + '...' : trimmed;
      notify.custom({
        title: `${categoryLabel} 用户反馈 #${feedbackId}`,
        template: cat === 'bug' ? 'orange' : 'blue',
        // No dedupe — every feedback should be seen
        lines: [
          `${userLabel} · 来自 \`${url || '<未提供>'}\``,
          '',
          preview,
        ],
        button: {
          label: '管理后台',
          type: 'primary',
          url: (process.env.PETRI_SITE_URL || 'https://petri.com') + '/admin#feedbacks',
        },
      });
    } catch (e) {
      console.warn('[feedback] notify failed:', e.message);
    }

    res.json({status: 'ok', id: feedbackId});
  });

  // ---- Admin: list feedbacks with filters ----
  // Async SQLite facade keeps concurrent requests from blocking the event loop.
  app.get('/api/feedback/admin', async (req, res) => {
    if (!_isAdmin(req)) return res.status(403).json({status: 'error', error: 'admin_only'});
    const status = req.query.status || '';
    const limit = Math.min(200, Math.max(1, parseInt(req.query.limit) || 50));
    let sql = 'SELECT * FROM feedbacks';
    const args = [];
    if (status) { sql += ' WHERE status = ?'; args.push(status); }
    sql += ' ORDER BY created_at DESC LIMIT ?';
    args.push(limit);
    let rows;
    try {
      rows = await dbAsync.prepare(sql).all(...args);
    } catch (e) {
      console.error('[feedback/admin] list failed:', e.message);
      return res.status(500).json({status: 'error', error: '查询失败'});
    }
    // Enrich each feedback with IP geolocation. Best-effort — ip-geo caches 7d.
    try {
      rows = await ipGeo.attachGeoToRows(rows, 'ip');
    } catch (e) {
      console.warn('[feedback] geo enrich failed:', e.message);
    }
    let counts = {};
    try {
      const countRows = await dbAsync.prepare(
        'SELECT status, COUNT(*) AS n FROM feedbacks GROUP BY status'
      ).all();
      counts = countRows.reduce((acc, r) => { acc[r.status] = r.n; return acc; }, {});
    } catch (e) {
      console.warn('[feedback] counts query failed:', e.message);
    }
    res.json({status: 'ok', items: rows, counts});
  });

  // ---- Admin: update status / notes ----
  app.put('/api/feedback/admin/:id', express.json({limit: '8kb'}), async (req, res) => {
    if (!_isAdmin(req)) return res.status(403).json({status: 'error', error: 'admin_only'});
    const id = parseInt(req.params.id);
    if (!id) return res.status(400).json({status: 'error', error: 'bad_id'});
    const {status, adminNotes} = req.body || {};
    const validStatuses = ['new', 'in_progress', 'resolved', 'dismissed'];
    const fields = [];
    const args = [];
    if (status && validStatuses.includes(status)) {
      fields.push('status = ?');
      args.push(status);
      if (status === 'resolved' || status === 'dismissed') {
        fields.push('resolved_at = ?');
        args.push(Date.now());
      }
    }
    if (typeof adminNotes === 'string') {
      fields.push('admin_notes = ?');
      args.push(adminNotes.slice(0, 2000));
    }
    if (!fields.length) return res.status(400).json({status: 'error', error: 'nothing_to_update'});
    args.push(id);
    let r;
    try {
      r = await dbAsync.prepare(`UPDATE feedbacks SET ${fields.join(', ')} WHERE id = ?`).run(...args);
    } catch (e) {
      console.error('[feedback/admin] update failed:', e.message);
      return res.status(500).json({status: 'error', error: '更新失败'});
    }
    if (r.changes === 0) return res.status(404).json({status: 'error', error: 'not_found'});
    res.json({status: 'ok'});
  });
};

/**
 * routes/files.js — 桌面版本地文件上传/读取路由。
 *
 * 提供项目工作区文件树浏览、文件读取，以及通过本地存储适配器的上传。
 */
const crypto = require('crypto');
const fs = require('fs');
const path = require('path');
const multer = require('multer');

const config = require('../config');
const { safeJoinUnder } = require('../../shared-backend/path-safe');
const { profileData } = require('../../shared-backend/data-profiler');
const { requireTrustedDesktopOrigin } = require('../helpers/local-request-boundary');
const workspaceGateway = require('../helpers/workspace-gateway');
const TEMP_DIR = config.tempDir || '/tmp/petri-tmp';

// 本地存储适配器
let _storage = null;
function getStorage() {
  if (!_storage) {
    const { getActiveStorage } = require('../../shared-backend/storage');
    _storage = getActiveStorage();
