function parseProfileIdentity(profileId) {
  const match = PROFILE_ID_RE.exec(String(profileId || '').trim());
  if (!match) return null;
  return {
    profileId: match[0],
    familyId: match[1],
    version: `v${match[2]}`,
    majorVersion: Number(match[2]),
  };
}

function validateColumns(columns, path, errors) {
  if (!Array.isArray(columns)) {
    errors.push(`${path}_must_be_array`);
    return;
  }
  const names = new Set();
  for (const [index, entry] of columns.entries()) {
    if (!entry || typeof entry !== 'object') {
      errors.push(`${path}_${index}_invalid`);
      continue;
    }
    if (typeof entry.name !== 'string' || !entry.name.trim()) errors.push(`${path}_${index}_name_required`);
    if (typeof entry.type !== 'string' || !entry.type.trim()) errors.push(`${path}_${index}_type_required`);
    if (typeof entry.nullable !== 'boolean') errors.push(`${path}_${index}_nullable_required`);
    if (names.has(entry.name)) errors.push(`${path}_${index}_duplicate_name`);
    names.add(entry.name);
  }
}

function validateProfileDefinition(profile) {
  const errors = [];
  if (!profile || typeof profile !== 'object' || Array.isArray(profile)) {
    return { valid: false, errors: ['profile_definition_required'] };
  }

  const identity = parseProfileIdentity(profile.profileId);
  if (!identity) errors.push('profile_id_invalid');
  if (identity && profile.familyId !== identity.familyId) errors.push('profile_family_mismatch');
  if (identity && profile.version !== identity.version) errors.push('profile_version_mismatch');
  if (identity && Number(profile.schemaVersion) !== identity.majorVersion) errors.push('profile_schema_version_mismatch');
  if (profile.registryContractVersion !== ARTIFACT_PROFILE_REGISTRY_VERSION) errors.push('registry_contract_version_mismatch');
  if (!PROFILE_KINDS.includes(profile.profileKind)) errors.push('profile_kind_invalid');
  for (const field of ['description', 'scientificMeaning', 'granularity', 'orientation']) {
    if (typeof profile[field] !== 'string' || !profile[field].trim()) errors.push(`${field}_required`);
  }

  validateColumns(profile.requiredColumns, 'required_columns', errors);
  validateColumns(profile.optionalColumns, 'optional_columns', errors);
  const allColumnNames = new Set([
    ...(profile.requiredColumns || []).map((entry) => entry?.name),
    ...(profile.optionalColumns || []).map((entry) => entry?.name),
  ]);
  for (const [alias, target] of Object.entries(profile.knownColumnAliases || {})) {
    if (!alias || !allColumnNames.has(target)) errors.push(`column_alias_invalid:${alias}`);
  }

  if (!Array.isArray(profile.identifierNamespaces) || profile.identifierNamespaces.length === 0) {
    errors.push('identifier_namespaces_required');
  }
  if (!Array.isArray(profile.validationRules) || profile.validationRules.length === 0) {
    errors.push('validation_rules_required');
  } else {
    const ruleIds = new Set();
    for (const entry of profile.validationRules) {
      if (!entry?.rule || !entry?.description || !['error', 'warning'].includes(entry?.severity)) {
        errors.push('validation_rule_invalid');
      }
      if (ruleIds.has(entry?.rule)) errors.push(`validation_rule_duplicate:${entry?.rule}`);
      ruleIds.add(entry?.rule);
    }
  }

  if (!profile.lifecycle || !PROFILE_LIFECYCLE_STATUSES.includes(profile.lifecycle.status)) {
    errors.push('profile_lifecycle_invalid');
  }
  if (profile.lifecycle?.status === 'deprecated' && !parseProfileIdentity(profile.lifecycle.deprecatedBy)) {
    errors.push('deprecated_profile_replacement_required');
  }
  if (!profile.compatibilityPolicy || profile.compatibilityPolicy.unknownVersion !== 'blocked') {
    errors.push('compatibility_policy_fail_closed_required');
  }
  for (const key of ['requiresParentJob', 'requiresInputHash', 'requiresScriptHash', 'requiresParamsHash']) {
    if (typeof profile.provenance?.[key] !== 'boolean') errors.push(`provenance_${key}_required`);
  }
  for (const field of ['producers', 'directProducers', 'consumers']) {
    if (!Array.isArray(profile[field])) errors.push(`${field}_must_be_array`);
  }

  return { valid: errors.length === 0, errors };
}

function registryValues(profiles) {
  if (Array.isArray(profiles)) return profiles;
  if (profiles && typeof profiles === 'object') return Object.values(profiles);
  return [];
}

function validateProfileRegistry(profiles = ARTIFACT_PROFILES) {
  const errors = [];
  const entries = registryValues(profiles);
  const identities = new Set();
  for (const profile of entries) {
    const result = validateProfileDefinition(profile);
    for (const error of result.errors) errors.push(`${profile?.profileId || 'unknown'}:${error}`);
    const identityKey = `${profile?.familyId || ''}:${profile?.schemaVersion || ''}`;
    if (identities.has(identityKey)) errors.push(`${profile?.profileId || 'unknown'}:duplicate_family_version`);
    identities.add(identityKey);
  }
  if (!Array.isArray(profiles) && profiles && typeof profiles === 'object') {
    for (const [key, profile] of Object.entries(profiles)) {
      if (key !== profile?.profileId) errors.push(`${key}:registry_key_profile_id_mismatch`);
    }
  }
  const registryDigest = sha256(entries
    .slice()
    .sort((a, b) => String(a.profileId).localeCompare(String(b.profileId))));
  return {
    valid: errors.length === 0,
    errors,
    registryVersion: ARTIFACT_PROFILE_REGISTRY_VERSION,
    profileCount: entries.length,
    registryDigest,
  };
}

function getProfile(profileId) {
  return ARTIFACT_PROFILES[profileId] || null;
}

function listProfiles() {
  return Object.keys(ARTIFACT_PROFILES).sort();
}

function isRegisteredProfile(profileId) {
  return Object.prototype.hasOwnProperty.call(ARTIFACT_PROFILES, profileId);
}

function getProfileIdentity(profileId) {
  const profile = getProfile(profileId);
  const identity = parseProfileIdentity(profileId);
  if (!profile || !identity) return null;
  return Object.freeze({
    ...identity,
    lifecycleStatus: profile.lifecycle.status,
    registryContractVersion: profile.registryContractVersion,
    contractDigest: sha256(profile),
  });
}

function sameColumnContract(left, right) {
  return canonicalStringify(left) === canonicalStringify(right);
}

function arrayContainsContracts(nextEntries, previousEntries, key) {
  const nextByKey = new Map(nextEntries.map((entry) => [entry[key], entry]));
  return previousEntries.every((entry) => sameColumnContract(nextByKey.get(entry[key]), entry));
}

function classifyProfileChange(previousProfile, nextProfile) {
  const previousValidation = validateProfileDefinition(previousProfile);
  const nextValidation = validateProfileDefinition(nextProfile);
  const base = {
    fromProfileId: previousProfile?.profileId || null,
    toProfileId: nextProfile?.profileId || null,
  };
  if (!previousValidation.valid || !nextValidation.valid) {
    return { ...base, changeClass: 'breaking', reason: 'profile_contract_invalid' };
  }

  const previousIdentity = parseProfileIdentity(previousProfile.profileId);
  const nextIdentity = parseProfileIdentity(nextProfile.profileId);
  if (previousProfile.profileId === nextProfile.profileId) {
    if (sha256(previousProfile) === sha256(nextProfile)) {
      return { ...base, changeClass: 'compatible', reason: 'contract_unchanged' };
    }
    return { ...base, changeClass: 'breaking', reason: 'profile_identity_reused_with_contract_drift' };
  }
  if (
    previousIdentity.familyId !== nextIdentity.familyId
    || nextIdentity.majorVersion <= previousIdentity.majorVersion
  ) {
    return { ...base, changeClass: 'breaking', reason: 'profile_identity_or_version_incompatible' };
  }

  for (const field of ['profileKind', 'scientificMeaning', 'granularity', 'orientation']) {
    if (previousProfile[field] !== nextProfile[field]) {
      return { ...base, changeClass: 'breaking', reason: `scientific_contract_changed:${field}` };
    }
  }
  if (!sameColumnContract(previousProfile.identifierNamespaces, nextProfile.identifierNamespaces)) {
    return { ...base, changeClass: 'breaking', reason: 'identifier_namespace_contract_changed' };
  }
  if (!sameColumnContract(previousProfile.requiredColumns, nextProfile.requiredColumns)) {
    return { ...base, changeClass: 'migration', reason: 'required_schema_changed' };
  }
  if (!arrayContainsContracts(nextProfile.optionalColumns, previousProfile.optionalColumns, 'name')) {
    return { ...base, changeClass: 'migration', reason: 'existing_optional_schema_changed' };
  }
  if (!arrayContainsContracts(nextProfile.validationRules, previousProfile.validationRules, 'rule')) {
    return { ...base, changeClass: 'migration', reason: 'validation_contract_changed' };
  }
  for (const [alias, target] of Object.entries(previousProfile.knownColumnAliases)) {
    if (nextProfile.knownColumnAliases[alias] !== target) {
      return { ...base, changeClass: 'migration', reason: 'column_alias_removed_or_changed' };
    }
  }
  return { ...base, changeClass: 'compatible', reason: 'additive_contract_change' };
}

function resolveProfileCompatibility(sourceProfileId, targetProfileId, options = {}) {
  const source = getProfile(sourceProfileId);
  const target = getProfile(targetProfileId);
  const result = {
    status: 'blocked',
    reason: 'unknown_profile',
    sourceProfileId,
    targetProfileId,
    migrationId: null,
  };
  if (!source || !target) return result;
  if (sourceProfileId === targetProfileId) {
    return { ...result, status: 'compatible', reason: 'exact_profile_match' };
  }
  if (source.familyId !== target.familyId) {
    return { ...result, reason: 'profile_family_mismatch' };
  }

  const sourceIdentity = parseProfileIdentity(sourceProfileId);
  const targetIdentity = parseProfileIdentity(targetProfileId);
  if (targetIdentity.majorVersion <= sourceIdentity.majorVersion) {
    return { ...result, reason: 'profile_downgrade_blocked' };
  }
  const migration = (options.migrations || []).find((entry) => (
    entry?.sourceProfileId === sourceProfileId
    && entry?.targetProfileId === targetProfileId
    && typeof entry?.migrationId === 'string'
    && typeof entry?.scriptRef === 'string'
  ));
  if (!migration) return { ...result, reason: 'migration_missing' };
  return {
    ...result,
    status: 'migration_required',
    reason: 'registered_migration_required',
    migrationId: migration.migrationId,
  };
}

function isProducer(profileId, pluginId) {
  const profile = getProfile(profileId);
  if (!profile) return false;
  return profile.producers.includes(pluginId) || profile.directProducers.includes(pluginId);
}

function isConsumer(profileId, pluginId) {
  const profile = getProfile(profileId);
  return !!profile && profile.consumers.includes(pluginId);
}

function resolveCanonicalColumn(profileId, columnName) {
  const profile = getProfile(profileId);
  if (!profile) return columnName;
  return profile.knownColumnAliases[columnName] || columnName;
}

function validateColumnSchema(profileId, columnNames) {
  const profile = getProfile(profileId);
  if (!profile) {
    return { valid: false, errors: [`Unknown profile: ${profileId}`], warnings: [] };
  }
  const errors = [];
  const warnings = [];
  const present = new Set(Array.isArray(columnNames) ? columnNames : []);
  for (const requiredColumn of profile.requiredColumns) {
    if (present.has(requiredColumn.name)) continue;
    const aliases = Object.entries(profile.knownColumnAliases)
      .filter(([, canonicalName]) => canonicalName === requiredColumn.name)
      .map(([alias]) => alias);
    const availableAlias = aliases.find((alias) => present.has(alias));
    if (!availableAlias) errors.push(`Missing required column '${requiredColumn.name}'`);
    else warnings.push(`Column '${availableAlias}' maps to canonical '${requiredColumn.name}'`);
  }
  return { valid: errors.length === 0, errors, warnings };
}

const registryValidation = validateProfileRegistry();
if (!registryValidation.valid) {
  throw new Error(`artifact_profile_registry_invalid:${registryValidation.errors.join(',')}`);
}

module.exports = {
  ARTIFACT_PROFILE_REGISTRY_VERSION,
  PROFILE_KINDS,
  PROFILE_LIFECYCLE_STATUSES,
  PROFILE_COMPATIBILITY_STATUSES,
  PROFILE_CHANGE_CLASSES,
  ARTIFACT_PROFILES,
  canonicalStringify,
  sha256,
  parseProfileIdentity,
  validateProfileDefinition,
  validateProfileRegistry,
  getProfile,
  listProfiles,
  isRegisteredProfile,
  getProfileIdentity,
  classifyProfileChange,
  resolveProfileCompatibility,
  isProducer,
  isConsumer,
  resolveCanonicalColumn,
  validateColumnSchema,
};

'use strict';

/**
 * Canonical JSON serialization (BLOCK-83 D1：从 scientific-task-spec 上提的通用原语).
 *
 * Domain-neutral: key-sorted deterministic stringify used for digests and
 * equality checks across contracts, manifests, provenance and replay services.
 */

function stableValue(value) {
  if (Array.isArray(value)) return value.map(stableValue);
  if (!value || typeof value !== 'object') return value;
  return Object.fromEntries(
    Object.keys(value)
      .sort()
      .map((key) => [key, stableValue(value[key])])
  );
}

function stableStringify(value) {
  return JSON.stringify(stableValue(value));
}

module.exports = { stableValue, stableStringify };

'use strict';

const fs = require('fs');
const path = require('path');
const { execFile } = require('child_process');

/**
 * Capability Bundle Registry — Stage 3 B1/B2 (single source of truth).
 *
 * A "capability bundle" is a prebuilt archive of heavyweight R/Python packages
 * (e.g. clusterProfiler + org.*.eg.db for enrichment) that a built-in analysis
 * module declares it needs via `plugin.json.requiresBundle`. Module code always
 * ships read-only inside the packaged app; bundles are fetched on demand into a
 * writable user directory by `capability-provisioning.js`.
 *
 * The gap this module closes (AUDIT-LOG §5): `plugin.json` only records a
 * `bundleId` (e.g. "r-enrichment") + `requiresBundleVersion`, but *nowhere*
 * mapped that bundleId to a concrete `{ url, sha256, sizeBytes }` descriptor.
 * This file IS that mapping — the single source of truth for "what is bundle X,
 * where does it live, and how do we verify it".
 *
 * Layering:
 *   - This module is PURE DATA + THIN ORCHESTRATION. It has no `electron`
 *     dependency and can run in core/ (petri-server, tests) and the main process.
 *   - `capability-provisioning.js` is the generic download/verify/install
 *     engine. This module supplies it descriptors and decides *whether* a
 *     bundle should be fetched.
 *   - `ensureBundlesForPlugin()` is the orchestration layer used by both real
 *     R run paths (registry.js / tools-executor.js).
 *
 * CONVENTION — `sha256 === null` means "unpublished, do not download":
 *   We never fabricate hashes. A descriptor with `sha256 === null` is treated
 *   as `status: 'unpublished'` and provisioning will NOT attempt a download for
 *   it — an unverifiable bundle must never be fetched. Published descriptors
 *   below are backfilled only from `scripts/build-r-bundle.mjs` output after
 *   their OSS objects have been uploaded and checked.
 */

const BUNDLE_HOST = 'https://petri-uploads.oss-cn-hangzhou.aliyuncs.com';
const DEFAULT_PLATFORM = 'macos-arm64';
const DEFAULT_VERSION = '1.0.0';

function bundleUrl(bundleId, version, platform) {
  return `${BUNDLE_HOST}/bundles/${bundleId}-${version}-${platform}.tar.gz`;
}

/**
 * The registry: bundleId → descriptor.
 *
 * Each descriptor:
 *   - bundleId {string}
 *   - version {string}
 *   - url {string}       download URL (host must be on provisioning allowlist)
 *   - sha256 {string|null}   null ⇒ unpublished (do not download)
 *   - sizeBytes {number|null} null ⇒ unknown (bundle not built yet)
 *   - platforms {string[]}    supported platforms for this descriptor
 *
 * sha256/sizeBytes are immutable build descriptors for the published macOS
 * arm64 archives. New platform/version builds require their own verified
 * descriptors; a requested version with no descriptor remains unpublished.
 */
const BUNDLE_REGISTRY = Object.freeze({
  'r-enrichment': Object.freeze({
    bundleId: 'r-enrichment',
    version: DEFAULT_VERSION,
    url: bundleUrl('r-enrichment', DEFAULT_VERSION, DEFAULT_PLATFORM),
    sha256: 'a857831d0d548cc6f9d856684ccec32c0241af018521c5d0641349ade0be1820',
    sizeBytes: 422094687,
    platforms: Object.freeze([DEFAULT_PLATFORM]),
  }),
  'r-wgcna': Object.freeze({
    bundleId: 'r-wgcna',
    version: DEFAULT_VERSION,
    url: bundleUrl('r-wgcna', DEFAULT_VERSION, DEFAULT_PLATFORM),
    sha256: '439273d8b9cad414d3ed32f14076ac88649ca885e6b5854e0ae91bf5e7980288',
    sizeBytes: 82367498,
    platforms: Object.freeze([DEFAULT_PLATFORM]),
  }),
});

/**
 * Classify a descriptor's publication status.
 *   - 'unknown'     — no such bundleId in the registry
 *   - 'unpublished' — registered but sha256 is null (not built/signed yet)
 *   - 'ready'       — registered and has a sha256 (verifiable, downloadable)
 */
function bundleStatus(descriptor) {
  if (!descriptor) return 'unknown';
  return descriptor.sha256 ? 'ready' : 'unpublished';
}

/**
 * Look up a bundle descriptor by id. Returns null for an unknown bundle or when
 * the descriptor does not support the requested platform.
 *
 * @param {string} bundleId
 * @param {{platform?: string, version?: string}} [opts]
 * @returns {object|null} a shallow copy of the descriptor, or null
 */
function getBundleDescriptor(bundleId, opts = {}) {
  if (!bundleId || typeof bundleId !== 'string') return null;
  const base = BUNDLE_REGISTRY[bundleId];
  if (!base) return null;

  const platform = opts.platform || DEFAULT_PLATFORM;
  if (Array.isArray(base.platforms) && !base.platforms.includes(platform)) {
    return null;
  }

  // A requested version different from the registered one is not an error here
  // (the caller may want the descriptor to compare); we surface the registered
  // descriptor and let the readiness/provisioning layer enforce version match.
  const version = opts.version || base.version;
  const platformMismatchSafe = { ...base, platforms: [...base.platforms] };
  if (version !== base.version) {
    // Re-derive the URL for the requested version so callers building a
    // per-version fetch get a consistent URL; sha256 stays null (we only have a
    // verified hash for the registered/built version).
    return {
      ...platformMismatchSafe,
      version,
      url: bundleUrl(bundleId, version, platform),
      sha256: base.version === version ? base.sha256 : null,
      sizeBytes: base.version === version ? base.sizeBytes : null,
    };
  }
  return platformMismatchSafe;
}

function normalizeRequiredBundles(pluginCfg) {
  if (!pluginCfg || !pluginCfg.requiresBundle) return [];
  const raw = Array.isArray(pluginCfg.requiresBundle)
    ? pluginCfg.requiresBundle
    : [pluginCfg.requiresBundle];
  return raw.filter((b) => typeof b === 'string' && b.length > 0);
}

/**
 * 把本地路径归一化为正斜杠形式，供 tar 命令行参数使用。
 *
 * 与 `--force-local` 配套：该标志会转义参数中的反斜杠，`C:\tmp\installed` 会被
 * tar 解析成 `C:\tmp` + `\i` + `nstalled`。正斜杠形式在 Windows bsdtar 与 POSIX
 * tar 上语义一致，且不含需要转义的字符。
 */
function toPosixPath(targetPath) {
  return String(targetPath).replace(/\\/g, '/');
}

/**
 * Extract a verified .tar.gz bundle into the library directory mounted by
 * R_LIBS_USER. The archive is trusted only after capability-provisioning has
 * matched its SHA-256 against the descriptor committed in this registry.
 *
 * A bundle-manifest.json marker is mandatory so a wrong-but-valid archive
 * cannot be recorded as a ready R library.
 */
function installTarGzBundle(archivePath, installDir, expected = {}) {
  fs.mkdirSync(installDir, { recursive: true });
  return new Promise((resolve, reject) => {
    const rejectAndClean = (failure) => {
      try { fs.rmSync(installDir, { recursive: true, force: true }); } catch {}
      reject(failure);
    };
    execFile(
      'tar',
      // Windows 下两道必需处理：
      // 1. `--force-local`：bsdtar 会把以盘符开头的路径（`C:\...`）当成远端主机规格，
      //    报 `Cannot connect to C: resolve failed`；POSIX tar 接受该标志为空操作。
      // 2. 正斜杠归一化：`--force-local` 会转义参数里的反斜杠，`...\installed` 会被
      //    解析成 `...\i` + `nstalled`，必须先把分隔符换成 `/`。
      ['--force-local', '-xzf', toPosixPath(archivePath), '-C', toPosixPath(installDir)],
      { timeout: 300000, maxBuffer: 1024 * 1024 },
      (error, _stdout, stderr) => {
        if (error) {
          const failure = new Error(
            `bundle_extract_failed: ${String(stderr || error.message).trim()}`
          );
          failure.code = 'bundle_extract_failed';
          rejectAndClean(failure);
          return;
        }
        const marker = path.join(installDir, 'bundle-manifest.json');
        if (!fs.existsSync(marker)) {
          const failure = new Error('bundle_manifest_missing');
          failure.code = 'bundle_manifest_missing';
          rejectAndClean(failure);
          return;
        }
        let manifest;
        try {
          manifest = JSON.parse(fs.readFileSync(marker, 'utf8'));
        } catch {
          const failure = new Error('bundle_manifest_invalid');
          failure.code = 'bundle_manifest_invalid';
          rejectAndClean(failure);
          return;
        }
        if (
          (expected.bundleId && manifest.bundleId !== expected.bundleId) ||
          (expected.version && manifest.bundleVersion !== expected.version)
        ) {
          const failure = new Error('bundle_manifest_mismatch');
          failure.code = 'bundle_manifest_mismatch';
          rejectAndClean(failure);
          return;
        }
        resolve(installDir);
      }
    );
  });
}

/**
 * Resolve the bundle descriptors a plugin requires, each annotated with a
 * `status` for a future wiring layer to make decisions on.
 *
 * @param {{requiresBundle?: string|string[], requiresBundleVersion?: string}} pluginCfg
 * @param {{platform?: string}} [opts]
 * @returns {Array<{bundleId:string, status:'ready'|'unpublished'|'unknown', descriptor:object|null}>}
 */
function resolveBundlesForPlugin(pluginCfg, opts = {}) {
  const bundleIds = normalizeRequiredBundles(pluginCfg);
  const version = (pluginCfg && pluginCfg.requiresBundleVersion) || undefined;
  // Call through module.exports so a test (or a future override layer) can swap
  // getBundleDescriptor and have resolve/ensure honor it.
  const lookup = module.exports.getBundleDescriptor;
  return bundleIds.map((bundleId) => {
    const descriptor = lookup(bundleId, { platform: opts.platform, version });
    return { bundleId, status: bundleStatus(descriptor), descriptor };
  });
}

/**
 * Orchestration layer: ensure every bundle a plugin requires is provisioned.
 *
 * For each required bundle:
 *   - unknown bundle           → { ok:false, status:'unknown' }        (no fetch)
 *   - unpublished (sha256=null)→ { ok:false, status:'unpublished' }    (no fetch)
 *   - already provisioned      → { ok:true,  status:'ready', alreadyReady:true }
 *   - ready + not installed    → provisionCapability(...) result
 *
 * Never throws; returns a structured aggregate. `options` are forwarded to
 * `provisionCapability` (download/hash/install/runtimesDir/onProgress can be
 * injected, e.g. by tests or the future wiring layer).
 *
 * @param {{requiresBundle?: string|string[], requiresBundleVersion?: string}} pluginCfg
 * @param {object} [options] forwarded to provisionCapability + { platform }
 * @returns {Promise<{ok:boolean, results:Array<object>}>}
 */
async function ensureBundlesForPlugin(pluginCfg, options = {}) {
  const resolved = resolveBundlesForPlugin(pluginCfg, { platform: options.platform });
  if (resolved.length === 0) {
    return { ok: true, results: [] };
  }

  let cp = null;
  try {
    cp = require('./capability-provisioning');
  } catch (e) {
    return {
      ok: false,
      results: resolved.map((r) => ({
        bundleId: r.bundleId,
        ok: false,
        status: 'provisioning_unavailable',
        message: e.message,
      })),
    };
  }

  const results = [];
  for (const { bundleId, status, descriptor } of resolved) {
    if (status === 'unknown') {
      results.push({ bundleId, ok: false, status: 'unknown' });
      continue;
    }
    if (status === 'unpublished') {
      // sha256 is null — unverifiable, must not download.
      results.push({ bundleId, ok: false, status: 'unpublished' });
      continue;
    }

    // status === 'ready': check readiness first, then provision if needed.
    const capability = {
      capabilityId: descriptor.bundleId,
      version: descriptor.version,
      url: descriptor.url,
      sha256: descriptor.sha256,
      size: descriptor.sizeBytes || undefined,
      kind: 'bundle',
    };

    let ready = { ready: false };
    try {
      ready = cp.checkCapabilityReady(capability, options);
    } catch (e) {
      results.push({ bundleId, ok: false, status: 'readiness_check_failed', message: e.message });
      continue;
    }
    if (ready.ready) {
      results.push({ bundleId, ok: true, status: 'ready', alreadyReady: true, installDir: ready.installDir });
      continue;
    }

    const provisionOptions = { ...options };
    if (
      typeof provisionOptions.install !== 'function' &&
      /\.tar\.gz(?:$|[?#])/i.test(descriptor.url)
    ) {
      provisionOptions.install = (archivePath, installDir) =>
        installTarGzBundle(archivePath, installDir, {
          bundleId: descriptor.bundleId,
          version: descriptor.version,
        });
    }
    const prov = await cp.provisionCapability(capability, provisionOptions);
    results.push({
      bundleId,
      ok: !!prov.ok,
      status: prov.ok ? 'ready' : 'provision_failed',
      alreadyReady: !!prov.alreadyReady,
      installDir: prov.installDir,
      error: prov.error,
      message: prov.message,
    });
  }

  return { ok: results.every((r) => r.ok), results };
}

module.exports = {
  BUNDLE_REGISTRY,
  getBundleDescriptor,
  resolveBundlesForPlugin,
  ensureBundlesForPlugin,
  bundleStatus,
  installTarGzBundle,
};

/**
 * Harness Capability Provisioning — Stage 3 M1 foundation.
 *
 * A "capability" is a runtime or R/Python package bundle that a built-in
 * analysis module declares it needs (e.g. an `r-enrichment` bundle for
 * GO/KEGG). Module code (`resources/built-in-plugins/<id>/`) always ships
 * read-only inside the packaged app; capabilities are the opposite: they are
 * fetched on demand into a writable user directory and are never bundled
 * into the .app itself.
 *
 * Design constraints (Stage 3 design doc §5, §D2/D5/D7/D8):
 *   - No second download/verify/install system: this module re-implements
 *     the same download + streaming SHA-256 + atomic-move steps already used
 *     by `src/plugin-manager.js`, but stays free of an `electron` dependency
 *     so it can run in `core/` (petri-server, tests) as well as the main process.
 *   - Offline-first: callers should prefer an already-provisioned capability
 *     and only reach the network when the local copy is missing or invalid
 *     (D5). This module doesn't decide *when* to fetch — callers (Harness
 *     readiness gate) do — it only makes fetching idempotent, verifiable and
 *     auditable.
 *   - Transparent, non-blocking (D8): callers get progress callbacks, never
 *     a bare silent multi-hundred-MB download.
 *   - Auditable (D2): every successful provision is recorded in a ledger
 *     file that a read-only settings view can render later.
 *
 * This module intentionally does NOT know about clusterProfiler, KEGG data,
 * or any specific bundle. It is generic infrastructure; GO/KEGG (Stage 3 M2)
 * supplies capability manifests describing what it needs.
 */

const fs = require('fs');
const path = require('path');
const os = require('os');
const crypto = require('crypto');
const https = require('https');

const LEDGER_FILE_NAME = 'harness-provisioning.json';
const TMP_DIR_NAME = '.tmp';
const CAPABILITIES_DIR_NAME = 'capabilities';

/**
 * Host allowlist for capability downloads (Stage 3 design doc §5.5, §D7;
 * AUDIT-LOG problem D). Provisioning fetches multi-hundred-MB bundles from a
 * URL carried in a capability descriptor; without a host allowlist a
 * malformed/hostile manifest could point the downloader at an arbitrary host
 * (SSRF / exfiltration surface). The current distribution source is the
 * project OSS CDN (see src/macos-oss-updater.js DEFAULT_FEED_URL), so the
 * default allowlist covers Aliyun OSS. Distribution source can move (D4/D7)
 * without touching provisioning logic by overriding the allowlist via
 * `options.allowedHosts` or the PETRI_CAPABILITY_ALLOWED_HOSTS env var.
 *
 * Entries are matched case-insensitively. An entry beginning with '.' is a
 * suffix match (e.g. '.aliyuncs.com' matches 'x.oss-cn-hangzhou.aliyuncs.com');
 * any other entry must match the host exactly.
 */
const DEFAULT_ALLOWED_HOSTS = Object.freeze([
  'petri-uploads.oss-cn-hangzhou.aliyuncs.com',
  '.aliyuncs.com',
]);

function resolveAllowedHosts(options = {}) {
  if (Array.isArray(options.allowedHosts) && options.allowedHosts.length > 0) {
    return options.allowedHosts;
  }
  const fromEnv = process.env.PETRI_CAPABILITY_ALLOWED_HOSTS;
  if (fromEnv && fromEnv.trim()) {
    return fromEnv.split(',').map((h) => h.trim()).filter(Boolean);
  }
  return DEFAULT_ALLOWED_HOSTS;
}

function _hostMatches(host, pattern) {
  const h = String(host || '').toLowerCase();
  const p = String(pattern || '').toLowerCase();
  if (!h || !p) return false;
  if (p.startsWith('.')) return h === p.slice(1) || h.endsWith(p);
  return h === p;
}

/**
 * Validate that a capability download URL is https and its host is on the
 * allowlist. Never throws; returns a structured result so callers surface a
 * clean diagnostic instead of a stack trace.
 *
 * @returns {{ok:true, host:string} | {ok:false, reason:string}}
 */
function checkUrlAllowed(url, options = {}) {
  let parsed;
  try {
    parsed = new URL(url);
  } catch {
    return { ok: false, reason: 'invalid_url' };
  }
  if (parsed.protocol !== 'https:') {
    return { ok: false, reason: 'insecure_protocol' };
  }
  const allowed = resolveAllowedHosts(options);
  const host = parsed.hostname;
  if (!allowed.some((pattern) => _hostMatches(host, pattern))) {
    return { ok: false, reason: 'host_not_allowed', host };
  }
  return { ok: true, host };
}

function defaultRuntimesDir() {
  const localDataDir = process.env.PETRI_LOCAL_DATA_DIR || path.join(os.homedir(), 'Documents', 'Petri-Local');
  return path.join(localDataDir, 'runtimes');
}

function resolveRuntimesDir(options = {}) {
  return options.runtimesDir || defaultRuntimesDir();
}

function getLedgerPath(options = {}) {
  return path.join(resolveRuntimesDir(options), LEDGER_FILE_NAME);
}

function capabilityInstallDir(capabilityId, version, options = {}) {
  return path.join(resolveRuntimesDir(options), CAPABILITIES_DIR_NAME, capabilityId, version);
}

function _ensureDir(dir) {
  fs.mkdirSync(dir, { recursive: true });
}

/**
 * Read the provisioning ledger. Never throws; a missing/corrupt ledger reads
 * as empty so a fresh install always looks like "nothing provisioned yet"
 * rather than crashing capability checks.
 */
function readLedger(options = {}) {
  const ledgerPath = getLedgerPath(options);
  try {
    const raw = JSON.parse(fs.readFileSync(ledgerPath, 'utf8'));
    return raw && typeof raw === 'object' && raw.capabilities && typeof raw.capabilities === 'object'
      ? raw
      : { schemaVersion: 1, capabilities: {} };
  } catch {
    return { schemaVersion: 1, capabilities: {} };
  }
}

function writeLedger(ledger, options = {}) {
  const runtimesDir = resolveRuntimesDir(options);
  _ensureDir(runtimesDir);
  const ledgerPath = getLedgerPath(options);
  const payload = { schemaVersion: 1, capabilities: {}, ...ledger };
  fs.writeFileSync(ledgerPath, JSON.stringify(payload, null, 2));
  return payload;
}

/**
 * List provisioned capabilities for a read-only "what has Harness set up"
 * view. Returns an array (not the raw ledger object) so the caller doesn't
 * need to know the on-disk schema.
 */
function listProvisionedCapabilities(options = {}) {
  const ledger = readLedger(options);
  return Object.values(ledger.capabilities || {}).map((entry) => ({ ...entry }));
}

function _sha256Matches(actual, expected) {
  const normalize = (value) => String(value || '').replace(/^sha256:/i, '').trim().toLowerCase();
  return normalize(actual) === normalize(expected);
}

/**
 * Streaming SHA-256 (no full-file buffering), mirroring
 * `src/plugin-manager.js#streamingSha256` so large bundles never load fully
 * into memory just to be verified.
 */
function streamingSha256(filePath) {
  return new Promise((resolve, reject) => {
    const hash = crypto.createHash('sha256');
    const stream = fs.createReadStream(filePath, { highWaterMark: 1024 * 1024 });
    stream.on('data', (chunk) => hash.update(chunk));
    stream.on('end', () => resolve(hash.digest('hex')));
    stream.on('error', reject);
  });
}

/**
 * Default download implementation: plain https + fs stream, no electron
 * dependency. Tests and Electron-side callers may inject `options.download`
 * to avoid real network calls or to reuse an existing downloader.
 */
function defaultDownload(url, destPath, onProgress) {
  return new Promise((resolve, reject) => {
    const file = fs.createWriteStream(destPath);
    const req = https.get(url, { timeout: 30000 }, (res) => {
      if (res.statusCode !== 200) {
        file.close();
        try { fs.unlinkSync(destPath); } catch {}
        reject(new Error(`download failed: HTTP ${res.statusCode}`));
        return;
      }
      const total = parseInt(res.headers['content-length'] || '0', 10);
      let received = 0;
      res.on('data', (chunk) => {
        received += chunk.length;
        if (onProgress && total > 0) onProgress({ received, total, ratio: received / total });
      });
      res.pipe(file);
      file.on('finish', () => file.close(() => resolve(destPath)));
    });
    req.on('error', (error) => {
      file.close();
      try { fs.unlinkSync(destPath); } catch {}
      reject(error);
    });
    req.on('timeout', () => {
      req.destroy();
      reject(new Error('download timed out'));
    });
  });
}

/**
 * Readiness check: is this capability already usable without touching the
 * network? Self-healing — a ledger entry alone is not trusted; the install
 * directory must still exist on disk (mirrors artifact-truth's "don't trust
 * the record, check the file").
 *
 * @param {{capabilityId:string, version:string, sha256?:string}} capability
 */
function checkCapabilityReady(capability, options = {}) {
  if (!capability || !capability.capabilityId || !capability.version) {
    return { ready: false, reason: 'invalid_capability_descriptor' };
  }
  const ledger = readLedger(options);
  const entry = ledger.capabilities[capability.capabilityId];
  const installDir = capabilityInstallDir(capability.capabilityId, capability.version, options);
  if (!entry) return { ready: false, reason: 'not_provisioned', installDir };
  if (entry.version !== capability.version) {
    return { ready: false, reason: 'version_mismatch', installDir, installedVersion: entry.version };
  }
  if (capability.sha256 && entry.sha256 && !_sha256Matches(entry.sha256, capability.sha256)) {
    return { ready: false, reason: 'sha256_mismatch', installDir };
  }
  if (!fs.existsSync(installDir)) {
    return { ready: false, reason: 'install_dir_missing', installDir };
  }
  return { ready: true, installDir, entry };
}

async function _provisionOnce(capability, options) {
  const runtimesDir = resolveRuntimesDir(options);
  const tmpDir = path.join(runtimesDir, TMP_DIR_NAME);
  _ensureDir(tmpDir);
  const installDir = capabilityInstallDir(capability.capabilityId, capability.version, options);
  const tmpFile = path.join(tmpDir, `${capability.capabilityId}-${capability.version}-${process.pid}.download`);

  const download = options.download || defaultDownload;
  await download(capability.url, tmpFile, options.onProgress);

  if (capability.sha256) {
    const actual = await (options.hash || streamingSha256)(tmpFile);
    if (!_sha256Matches(actual, capability.sha256)) {
      try { fs.unlinkSync(tmpFile); } catch {}
      const error = new Error('sha256_mismatch');
      error.code = 'sha256_mismatch';
      throw error;
    }
  }

  // Materialize into place. Bundles that need extraction (e.g. tar.gz) pass
  // an `install` function; the default treats the download as the payload
  // itself and atomically renames it into the install directory.
  _ensureDir(path.dirname(installDir));
  try { fs.rmSync(installDir, { recursive: true, force: true }); } catch {}
  if (typeof options.install === 'function') {
    await options.install(tmpFile, installDir);
  } else {
    _ensureDir(installDir);
    fs.renameSync(tmpFile, path.join(installDir, path.basename(tmpFile)));
  }
  try { fs.unlinkSync(tmpFile); } catch {}

  return installDir;
}

/**
 * Fetch, verify and materialize a capability if it isn't already ready.
 * Idempotent: repeated calls when already provisioned are a no-op disk
 * check, not a re-download. Retries a corrupted/interrupted attempt once
 * before surfacing a diagnostic — callers should not retry silently forever.
 *
 * @param {{capabilityId:string, version:string, url:string, sha256?:string, kind?:string}} capability
 * @param {object} [options]
 * @param {string} [options.runtimesDir] - override for tests/isolation.
 * @param {function} [options.download] - injectable downloader (url, destPath, onProgress) => Promise<void>.
 * @param {function} [options.hash] - injectable hasher (filePath) => Promise<string>.
 * @param {function} [options.install] - injectable installer (tmpFile, installDir) => Promise<void>, for bundles needing extraction.
 * @param {function} [options.onProgress] - progress callback for D8 transparency.
 * @param {number} [options.maxAttempts] - default 2.
 */
async function provisionCapability(capability, options = {}) {
  if (!capability || !capability.capabilityId || !capability.version || !capability.url) {
    return { ok: false, error: 'invalid_capability_descriptor' };
  }

  const already = checkCapabilityReady(capability, options);
  if (already.ready) {
    return { ok: true, alreadyReady: true, installDir: already.installDir };
  }

  // Host allowlist gate — only reached when a real network fetch is about to
  // happen (an already-provisioned capability short-circuits above and is
  // never re-validated, so tightening the allowlist can't strand installed
  // bundles). A caller-injected `options.download` (tests) still passes
  // through this gate so the allowlist is exercised uniformly; injected
  // downloaders simply must use an allowed URL.
  const urlCheck = checkUrlAllowed(capability.url, options);
  if (!urlCheck.ok) {
    return { ok: false, error: urlCheck.reason, url: capability.url, host: urlCheck.host };
  }

  const maxAttempts = Number.isInteger(options.maxAttempts) ? options.maxAttempts : 2;
  let lastError = null;
  for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
    try {
      const installDir = await _provisionOnce(capability, options);
      const ledger = readLedger(options);
      ledger.capabilities[capability.capabilityId] = {
        capabilityId: capability.capabilityId,
        kind: capability.kind || 'bundle',
        version: capability.version,
        sha256: capability.sha256 || null,
        url: capability.url,
        size: capability.size || null,
        installDir,
        installedAt: (options.now || Date.now)(),
        attempts: attempt,
      };
      writeLedger(ledger, options);
      return { ok: true, alreadyReady: false, installDir, attempts: attempt };
    } catch (error) {
      lastError = error;
    }
  }

  return {
    ok: false,
    error: (lastError && lastError.code) || 'provisioning_failed',
    message: lastError && lastError.message,
    attempts: maxAttempts,
  };
}

/**
 * Remove a provisioned capability (ledger entry + install dir). Local-disk
 * only; never touches user analysis data or project artifacts. Callers at
 * the UI layer should treat this as a confirm-first action (C-03).
 */
function removeCapability(capabilityId, options = {}) {
  const ledger = readLedger(options);
  const entry = ledger.capabilities[capabilityId];
  if (!entry) return { ok: true, removed: false };
  try {
    if (entry.installDir) fs.rmSync(entry.installDir, { recursive: true, force: true });
  } catch (error) {
    return { ok: false, error: error.message };
  }
  delete ledger.capabilities[capabilityId];
  writeLedger(ledger, options);
  return { ok: true, removed: true };
}

module.exports = {
  defaultRuntimesDir,
  resolveRuntimesDir,
  getLedgerPath,
  capabilityInstallDir,
  readLedger,
  writeLedger,
  listProvisionedCapabilities,
  checkCapabilityReady,
  provisionCapability,
  removeCapability,
  streamingSha256,
  defaultDownload,
  checkUrlAllowed,
  resolveAllowedHosts,
  DEFAULT_ALLOWED_HOSTS,
};

/**
 * shared-backend/config-helper.js — 统一读取 config 的入口（自洽版）
 *
 * 断点1（分仓前置）：斩断对 petri-server 的反向 require。
 * 调用方（petri-server/desktop）启动时调 configure({getConfig}) 注入自己的 config；
 * 未注入时从环境变量构造 fallback（保持原行为，shared-backend 仍能独立跑）。
 *
 * 历史上本模块按优先级 require petri-server/config → py-server/config（py-server 已于 BLOCK-30 P1 摘除），那是"假独立"——
 * 分仓后 ../petri-server/config 路径会断，initSharedBackend / 执行器 / 存储 / llm-providers 全炸。
 * 依赖反转后，shared-backend 真自洽，分仓安全。
 *
 * E-019 db-config closeout (BLOCK-10 PHASE 2)：
 *   同一进程打开多个 SQLite connection（petri-server/db.js + agent-task-store.js +
 *   src/database/{branch,result}-db.js）共享文件，但 busy_timeout /
 *   journal_mode 等参数历史上各自硬编码。本模块在 config-helper 内追加
 *   db-config 命名空间：getConfig / setConfig / validateVersion(version)。
 *   setConfig 用于 petri-server 与 desktop 进程启动时把 petri-server 端的
 *   `BUSY_TIMEOUT_MS=10000`、`JOURNAL_MODE='WAL'`、expected
 *   `DB_SCHEMA_VERSION='1'` 注入；validateVersion(version) 在 Schema
 *   不一致时抛 `Error('db-version-mismatch')`。该 API 不 ALTER 任何 schema，
 *   仅作为后续可能改变 db 行为的 caller 的版本护栏。
 */

let _getConfig = null; // 注入的 config 提供函数

/**
 * 注入 config 提供函数。调用方启动时调一次。
 * @param {{getConfig: () => object}} provider
 */
function configure(provider) {
  if (provider && typeof provider.getConfig === 'function') {
    _getConfig = provider.getConfig;
  }
}

function getConfig() {
  // 优先用注入的
  if (_getConfig) return _getConfig();
  // fallback：从环境变量构造（真自洽，不依赖 petri-server）
  return {
    rHome: process.env.PETRI_R_HOME || '',
    pyHome: process.env.PETRI_PY_HOME || '',
    tempDir: process.env.PETRI_TEMP_DIR || '/tmp/petri-tmp',
    localResultsDir: process.env.PETRI_LOCAL_RESULTS_DIR || '',
    localUploadsDir: process.env.PETRI_LOCAL_UPLOADS_DIR || '',
  };
}

// ============================================================
// db-config — E-019 closeout (BLOCK-10 PHASE 2)
// ============================================================
//
// The default expected schema version. Bump this when the on-disk schema
// changes shape in a way that older binaries cannot safely read. Callers
// that mutate db behavior should validate via validateVersion(clientVersion)
// before touching the file.
const DB_SCHEMA_VERSION = '1';

let _dbConfig = Object.freeze({
  busyTimeoutMs: 10000,
  journalMode: 'WAL',
  schemaVersion: DB_SCHEMA_VERSION,
});

/**
 * Returns the current db config (a frozen object). Callers must not mutate.
 * @returns {{busyTimeoutMs: number, journalMode: string, schemaVersion: string}}
 */
function getDbConfig() {
  return _dbConfig;
}

/**
 * Replace the db config. Pass a partial object; unspecified keys keep their
 * current values. Validation is intentionally minimal — we want callers
 * (petri-server boot, desktop main) to be able to set valid overrides without
 * being blocked by structural checks.
 * @param {Partial<{busyTimeoutMs: number, journalMode: string, schemaVersion: string}>} patch
 */
function setDbConfig(patch) {
  if (!patch || typeof patch !== 'object') return _dbConfig;
  const next = { ..._dbConfig, ...patch };
  if (typeof next.busyTimeoutMs !== 'number' || !Number.isFinite(next.busyTimeoutMs) || next.busyTimeoutMs < 0) {
    next.busyTimeoutMs = _dbConfig.busyTimeoutMs;
  }
  if (typeof next.journalMode !== 'string' || !next.journalMode) {
    next.journalMode = _dbConfig.journalMode;
  }
  if (typeof next.schemaVersion !== 'string' || !next.schemaVersion) {
    next.schemaVersion = _dbConfig.schemaVersion;
  }
  _dbConfig = Object.freeze(next);
  return _dbConfig;
}

/**
 * Validate a caller's claimed schema version against the expected one.
 * Throws Error('db-version-mismatch') on a mismatch so callers can fail
 * closed before any db mutation.
 *
 * @param {string} clientVersion
 * @returns {boolean}
 */
function validateDbVersion(clientVersion) {
  if (typeof clientVersion !== 'string' || !clientVersion) {
    throw new Error('db-version-mismatch');
  }
  if (clientVersion !== _dbConfig.schemaVersion) {
    throw new Error('db-version-mismatch');
  }
  return true;
}

// 向后兼容：原 module.exports 是个 Proxy，字段访问走 getConfig()。
// 现在导出一个 Proxy，对 configure/getConfig 三个方法名返回函数，其余走 getConfig()。
// 老代码的字段访问仍由 Proxy 转发到当前 config；
// 新代码 `const { configure, getConfig } = require('./config-helper')` 也 work。
//
// BLOCK-10 PHASE 1.1 (E-019 full) 增补：
//   - getBusyTimeout() 返回 getDbConfig().busyTimeoutMs，作为 SQLite 打开期
//     `PRAGMA busy_timeout` 的唯一入口。agent-task-store / branch-db /
//     result-db 全部走这里，避免再次出现"petri-server 单进程 5000 vs 10000"漂移。
//   - Proxy 把 `busyTimeout` 字段转发到 getDbConfig()，所以
//     `configHelper.busyTimeout` / `getConfig().busyTimeout` 也能读（与
//     getBusyTimeout() 同值），方便老代码无需改 import 即可拿到统一值。
function getBusyTimeout() {
  return getDbConfig().busyTimeoutMs;
}

// ============================================================
// A-010 central env reads (PHASE 1.2).
//
// The 6 core desktop path / port / runtime env keys used to be read
// from process.env directly in every consumer (config.js, db.js,
// backend-proc-manager.js, content-plugins.js, r-libs-resolver.js,
// query-tools.js, py-pool.js, …). When env-coordinator injects a
// value at desktop startup, consumers must still pick it up — and
// today they each have their own `process.env.X || default` block,
// which is fine but makes a single mutation point impossible.
//
// PHASE 1.2 only centralises the *reading* path. Two helpers:
//
//   getEnv(key, fallback)
//     — equivalent to `process.env[key] || fallback` with one twist:
//       empty string is treated as unset so a stub env injection
//       (`process.env.PETRI_DB_PATH = ''`) does not silently win
//       against the documented fallback.
//
//   getCoreEnv()
//     — returns the 6 core desktop env keys (busyTimeout + 5 path /
//       port fields) as a frozen snapshot. The keys match
//       `core/petri-server/config.js` consumers (config.rHome,
//       config.localResultsDir, config.localUploadsDir,
//       config.tempDir, config.dbPath, config.port).
//
// Consumers that want the snapshot should call getCoreEnv() at
// module load time. The behaviour is identical to the previous
// `process.env.X || default` reads — PHASE 1.2 invariant is "100%
// backward compatible". ============================================================

/**
 * Read a single env var with a fallback. Empty string is treated as
 * unset so callers can clear an env var by assigning ''.
 *
 * @param {string} key
 * @param {string|number|boolean} fallback
 * @returns {string|number|boolean}
 */
function getEnv(key, fallback) {
  const value = process.env[key];
  if (value === undefined || value === null || value === '') return fallback;
  return value;
}

/**
 * Snapshot of the 6 core desktop env keys. Returned object is frozen
 * so consumers cannot mutate the cache by accident.
 *
 * Keys:
 *   busyTimeoutMs  — PRAGMA busy_timeout; default 10000 (matches
 *                    E-019 full which routes through getBusyTimeout()).
 *   rHome          — process.env.PETRI_R_HOME || ''
 *   localResultsDir — process.env.PETRI_LOCAL_RESULTS_DIR || ''
 *   localUploadsDir — process.env.PETRI_LOCAL_UPLOADS_DIR || ''
 *   tempDir        — process.env.PETRI_TEMP_DIR || '/tmp/petri-tmp'
 *   dbPath         — process.env.PETRI_DB_PATH || ''
 *
 * (port is *not* included here — ports live in env-coordinator
 *  because Electron owns port allocation. See getBackendPort().)
 *
 * @returns {Readonly<{
 *   busyTimeoutMs: number,
 *   rHome: string,
 *   localResultsDir: string,
 *   localUploadsDir: string,
 *   tempDir: string,
 *   dbPath: string,
 * }>}
 */
function getCoreEnv() {
  return Object.freeze({
    busyTimeoutMs: getBusyTimeout(),
    rHome: getEnv('PETRI_R_HOME', ''),
    localResultsDir: getEnv('PETRI_LOCAL_RESULTS_DIR', ''),
    localUploadsDir: getEnv('PETRI_LOCAL_UPLOADS_DIR', ''),
    tempDir: getEnv('PETRI_TEMP_DIR', '/tmp/petri-tmp'),
    dbPath: getEnv('PETRI_DB_PATH', ''),
  });
}

module.exports = new Proxy(
  {
    configure,
    getConfig,
    getDbConfig,
    setDbConfig,
    validateDbVersion,
    getBusyTimeout,
    getEnv,
    getCoreEnv,
    DB_SCHEMA_VERSION,
  },
  {
    get(target, prop) {
      if (prop === 'configure') return configure;
      if (prop === 'getConfig') return getConfig;
      if (prop === 'getDbConfig') return getDbConfig;
      if (prop === 'setDbConfig') return setDbConfig;
      if (prop === 'validateDbVersion') return validateDbVersion;
      if (prop === 'getBusyTimeout') return getBusyTimeout;
      if (prop === 'getEnv') return getEnv;
      if (prop === 'getCoreEnv') return getCoreEnv;
      if (prop === 'DB_SCHEMA_VERSION') return DB_SCHEMA_VERSION;
      // db-config fields forwarded through getDbConfig so callers can do
      // `configHelper.busyTimeout` without going through getConfig().
      if (prop === 'busyTimeout') return getDbConfig().busyTimeoutMs;
      if (prop === 'journalMode') return getDbConfig().journalMode;
      if (prop === 'schemaVersion') return getDbConfig().schemaVersion;
      return getConfig()[prop];
    },
  }
);

'use strict';

/**
 * SDC-1 bounded, read-only profiler for delimited text files.
 *
 * This module deliberately reports observations and candidates.  It does not
 * bind a file to a scientific profile and it never mutates the input file.
 * The input stream is consumed once: the complete stream is hashed while a
 * bounded prefix/sample is parsed by the small CSV state machine below.
 */

const crypto = require('node:crypto');
const fs = require('node:fs');
const path = require('node:path');

const DATA_PROFILER_VERSION = 'sdc-1.data-profiler.v1';
const SNAPSHOT_VERSION = 'sdc-1.snapshot.v1';
const SUPPORTED_EXTENSIONS = Object.freeze(['.csv', '.tsv', '.txt']);

const DEFAULT_LIMITS = Object.freeze({
  maxSampleRows: 50,
  maxColumns: 256,
  maxRowBytes: 512 * 1024,
  maxCellBytes: 64 * 1024,
  maxProbeBytes: 64 * 1024,
});

const HARD_LIMITS = Object.freeze({
  maxSampleRows: 2000,
  maxColumns: 4096,
  maxRowBytes: 8 * 1024 * 1024,
  maxCellBytes: 2 * 1024 * 1024,
  maxProbeBytes: 256 * 1024,
});

const BLOCKING_CODES = new Set([
  'invalid_input',
  'unsupported_file_type',
  'file_not_found',
  'not_a_regular_file',
  'permission_denied',
  'read_error',
  'empty_file',
  'empty_dataset',
  'no_data_rows',
  'unsupported_encoding',
  'malformed_csv',
  'unterminated_quoted_field',
  'quote_in_unquoted_field',
  'characters_after_closing_quote',
  'too_wide',
  'truncated_row',
  'truncated_cell',
  'file_changed_during_read',
]);

function clampLimit(value, fallback, maximum) {
  if (value === undefined || value === null || value === '') return fallback;
  const number = Number(value);
  if (!Number.isFinite(number) || number < 1) return fallback;
  return Math.min(Math.floor(number), maximum);
}

function normalizeLimits(input = {}) {
  const options = input.options && typeof input.options === 'object' ? input.options : {};
  const limits = input.limits && typeof input.limits === 'object' ? input.limits : {};
  // Accept both an options/limits bag and direct top-level limits.  The latter
  // keeps the public call shape small for callers that only need one bound.
  const merged = { ...input, ...limits, ...options };
  return {
    maxSampleRows: clampLimit(
      merged.maxSampleRows ?? merged.sampleRows,
      DEFAULT_LIMITS.maxSampleRows,
      HARD_LIMITS.maxSampleRows,
    ),
    maxColumns: clampLimit(
      merged.maxColumns ?? merged.sampleColumns,
      DEFAULT_LIMITS.maxColumns,
      HARD_LIMITS.maxColumns,
    ),
    maxRowBytes: clampLimit(
      merged.maxRowBytes ?? merged.rowBytes,
      DEFAULT_LIMITS.maxRowBytes,
      HARD_LIMITS.maxRowBytes,
    ),
    maxCellBytes: clampLimit(
      merged.maxCellBytes ?? merged.cellBytes,
      DEFAULT_LIMITS.maxCellBytes,
      HARD_LIMITS.maxCellBytes,
    ),
    maxProbeBytes: clampLimit(
      merged.maxProbeBytes ?? merged.probeBytes,
      DEFAULT_LIMITS.maxProbeBytes,
      HARD_LIMITS.maxProbeBytes,
    ),
  };
}

function diagnostic(code, severity, message, details = {}) {
  return { code, severity, message, ...details };
}

function isBlockingDiagnostic(item) {
  return item && (item.severity === 'blocked' || BLOCKING_CODES.has(item.code));
}

function isMissingValue(value) {
  if (value === null || value === undefined) return true;
  const normalized = String(value).trim().toLowerCase();
  return normalized === '' || normalized === 'na' || normalized === 'n/a'
    || normalized === 'null' || normalized === 'none' || normalized === 'nan'
    || normalized === '.';
}

function finiteNumber(value) {
  if (isMissingValue(value)) return false;
  const text = String(value).trim();
  if (text === '' || !/^[+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?$/.test(text)) return false;
  const number = Number(text);
  return Number.isFinite(number);
}

function integerValue(value) {
  if (isMissingValue(value)) return false;
  return /^[+-]?\d+$/.test(String(value).trim());
}

function booleanValue(value) {
  if (isMissingValue(value)) return false;
  return /^(?:true|false|yes|no|0|1)$/i.test(String(value).trim());
}

function dateValue(value) {
  if (isMissingValue(value)) return false;
  const text = String(value).trim();
  if (!/^\d{4}-\d{2}-\d{2}(?:[T ][0-9]{2}:[0-9]{2}(?::[0-9]{2}(?:\.\d+)?)?(?:Z|[+-][0-9]{2}:?[0-9]{2})?)?$/.test(text)) {
    return false;
  }
  return !Number.isNaN(Date.parse(text));
}

function classifyPrimitiveCandidates(values) {
  const nonMissing = values.filter((value) => !isMissingValue(value));
  const sampleCount = values.length;
  const missingCount = sampleCount - nonMissing.length;
  const observedValues = nonMissing.length;
  const predicates = [
    ['integer', integerValue],
    ['number', finiteNumber],
    ['boolean', booleanValue],
    ['date', dateValue],
  ];
  const candidates = predicates.map(([candidate, predicate]) => {
    const matchingValues = nonMissing.filter(predicate).length;
    const confidence = observedValues === 0 ? 0 : matchingValues / observedValues;
    return {
      candidate,
      confidence: Number(confidence.toFixed(4)),
      evidence: {
        observedValues,
        matchingValues,
        missingValues: missingCount,
        sampleCount,
      },
      basis: `matched ${matchingValues}/${observedValues || 0} non-missing sampled values`,
    };
  });
  const typedMatches = new Set(
    predicates.flatMap(([candidate, predicate]) => nonMissing.filter(predicate).map(() => candidate)),
  );
  const stringMatches = nonMissing.filter((value) => {
    if (typedMatches.size === 0) return true;
    return !predicates.some(([, predicate]) => predicate(value));
  }).length;
  candidates.push({
    candidate: 'string',
    confidence: Number((observedValues === 0 ? 0 : stringMatches / observedValues).toFixed(4)),
    evidence: {
      observedValues,
      matchingValues: stringMatches,
      missingValues: missingCount,
      sampleCount,
    },
    basis: `non-missing values not matching a narrower primitive candidate: ${stringMatches}/${observedValues || 0}`,
  });
  return candidates.sort((left, right) => right.confidence - left.confidence);
}

class Utf8Validator {
  constructor() {
    this.expected = 0;
    this.codePoint = 0;
    this.minimum = 0;
    this.invalid = false;
    this.invalidByte = null;
  }

  feed(byte, offset) {
    if (this.invalid) return;
    if (this.expected === 0) {
      if (byte <= 0x7f) return;
      if (byte >= 0xc2 && byte <= 0xdf) {
        this.expected = 1;
        this.codePoint = byte & 0x1f;
        this.minimum = 0x80;
        return;
      }
      if (byte >= 0xe0 && byte <= 0xef) {
        this.expected = 2;
        this.codePoint = byte & 0x0f;
        this.minimum = 0x800;
        return;
      }
      if (byte >= 0xf0 && byte <= 0xf4) {
        this.expected = 3;
        this.codePoint = byte & 0x07;
        this.minimum = 0x10000;
        return;
      }
      this.invalid = true;
      this.invalidByte = { byte, offset };
      return;
    }
    if (byte < 0x80 || byte > 0xbf) {
      this.invalid = true;
      this.invalidByte = { byte, offset };
      return;
    }
    this.codePoint = (this.codePoint << 6) | (byte & 0x3f);
    this.expected -= 1;
    if (this.expected === 0 && (this.codePoint < this.minimum || this.codePoint > 0x10ffff
      || (this.codePoint >= 0xd800 && this.codePoint <= 0xdfff))) {
      this.invalid = true;
      this.invalidByte = { byte, offset, codePoint: this.codePoint };
    }
  }

  finish() {
    if (!this.invalid && this.expected !== 0) {
      this.invalid = true;
      this.invalidByte = { reason: 'truncated_utf8_sequence' };
    }
    return !this.invalid;
  }
}

function countDelimitersOutsideQuotes(buffer, delimiterCode) {
  let inQuotes = false;
  let count = 0;
  let rowCount = 0;
  let fieldsInRow = 1;
  let rowsWithDelimiter = 0;
  for (let index = 0; index < buffer.length; index += 1) {
    const byte = buffer[index];
    if (byte === 0x22) {
      if (inQuotes && buffer[index + 1] === 0x22) {
        index += 1;
      } else {
        inQuotes = !inQuotes;
      }
      continue;
    }
    if (inQuotes) continue;
    if (byte === delimiterCode) {
      count += 1;
      fieldsInRow += 1;
    } else if (byte === 0x0a || byte === 0x0d) {
      rowCount += 1;
      if (fieldsInRow > 1) rowsWithDelimiter += 1;
      fieldsInRow = 1;
    }
  }
  if (fieldsInRow > 1) rowsWithDelimiter += 1;
  return { count, rowCount, rowsWithDelimiter };
}

function detectDelimiter(buffer, extension, requestedDelimiter) {
  if (requestedDelimiter === ',' || requestedDelimiter === '\t') return requestedDelimiter;
  const candidates = [',', '\t', ';', '|'];
  const scores = candidates.map((delimiter) => {
    const result = countDelimitersOutsideQuotes(buffer, delimiter.charCodeAt(0));
    const extensionBonus = extension === '.tsv' && delimiter === '\t' ? 2
      : extension === '.csv' && delimiter === ',' ? 2 : 0;
    const consistency = result.rowsWithDelimiter > 0
      ? result.rowsWithDelimiter / Math.max(result.rowCount, 1) : 0;
    return {
      delimiter,
      ...result,
      score: result.count * (1 + consistency) + extensionBonus,
    };
  });
  scores.sort((left, right) => right.score - left.score || right.count - left.count);
  return scores[0].count > 0 ? scores[0].delimiter : null;
}

class DelimitedStateMachine {
  constructor(delimiter, limits) {
    this.delimiter = delimiter;
    this.delimiterCode = delimiter ? delimiter.charCodeAt(0) : null;
    this.limits = limits;
    this.quotesEnabled = delimiter !== null;
    this.inQuotes = false;
    this.quoteClosed = false;
    this.justEndedCR = false;
    this.fieldAtStart = true;
    this.fieldParts = [];
    this.fieldLength = 0;
    this.fieldTruncated = false;
    this.rowFields = [];
    this.fieldCount = 0;
    this.rowBytes = 0;
    this.rowHasBytes = false;
    this.rowTruncated = false;
    this.rows = [];
    this.totalRows = 0;
    this.minColumns = null;
    this.maxColumns = 0;
    this.tooWide = false;
    this.truncatedRow = false;
    this.truncatedCell = false;
    this.malformed = false;
    this.issueCodes = new Set();
  }

  issue(code) {
    this.issueCodes.add(code);
    if (code === 'too_wide') this.tooWide = true;
    if (code === 'truncated_row') {
      this.truncatedRow = true;
      this.rowTruncated = true;
    }
    if (code === 'truncated_cell') {
      this.truncatedCell = true;
      this.fieldTruncated = true;
    }
    if (code !== 'too_wide' && code !== 'truncated_row' && code !== 'truncated_cell') this.malformed = true;
  }

  markRowByte() {
    this.rowBytes += 1;
    if (this.rowBytes > this.limits.maxRowBytes) this.issue('truncated_row');
  }

  appendFieldByte(byte) {
    if (this.fieldLength < this.limits.maxCellBytes) {
      this.fieldParts.push(byte);
    } else {
      this.issue('truncated_cell');
    }
    this.fieldLength += 1;
  }

  finishField() {
    this.fieldCount += 1;
    if (this.fieldCount > this.limits.maxColumns) this.issue('too_wide');
    if (this.fieldCount <= this.limits.maxColumns) {
      const value = Buffer.from(this.fieldParts).toString('utf8');
      this.rowFields.push(value);
    }
    this.fieldParts = [];
    this.fieldLength = 0;
    this.fieldTruncated = false;
    this.fieldAtStart = true;
  }

  finishRow() {
    if (!this.rowHasBytes && this.fieldCount === 0 && this.fieldLength === 0) return;
    this.finishField();
    const columnCount = this.fieldCount;
    this.totalRows += 1;
    this.minColumns = this.minColumns === null ? columnCount : Math.min(this.minColumns, columnCount);
    this.maxColumns = Math.max(this.maxColumns, columnCount);
    if (this.rows.length < this.limits.maxSampleRows) {
      this.rows.push(this.rowFields.slice());
    }
    this.rowFields = [];
    this.fieldCount = 0;
    this.rowBytes = 0;
    this.rowHasBytes = false;
    this.rowTruncated = false;
    this.fieldAtStart = true;
    this.justEndedCR = false;
  }

  consume(buffer) {
    for (let index = 0; index < buffer.length; index += 1) {
      let byte = buffer[index];
      if (this.justEndedCR) {
        if (byte === 0x0a) {
          this.justEndedCR = false;
          continue;
        }
        this.justEndedCR = false;
      }

      if (this.inQuotes) {
        this.markRowByte();
        this.rowHasBytes = true;
        if (byte === 0x22) {
          this.inQuotes = false;
          this.quoteClosed = true;
        } else {
          this.appendFieldByte(byte);
        }
        continue;
      }

      if (this.quoteClosed) {
        this.markRowByte();
        this.rowHasBytes = true;
        if (this.quotesEnabled && byte === 0x22) {
          this.appendFieldByte(byte);
          this.inQuotes = true;
          this.quoteClosed = false;
          this.fieldAtStart = false;
        } else if (this.quotesEnabled && byte === this.delimiterCode) {
          this.quoteClosed = false;
          this.finishField();
        } else if (this.quotesEnabled && byte === 0x0a) {
          this.quoteClosed = false;
          this.finishRow();
        } else if (this.quotesEnabled && byte === 0x0d) {
          this.quoteClosed = false;
          this.finishRow();
          this.justEndedCR = true;
        } else {
          this.issue('characters_after_closing_quote');
          this.quoteClosed = false;
          this.fieldAtStart = false;
          this.appendFieldByte(byte);
        }
        continue;
      }

      this.markRowByte();
      this.rowHasBytes = true;
      if (byte === 0x0a) {
        this.finishRow();
      } else if (byte === 0x0d) {
        this.finishRow();
        this.justEndedCR = true;
      } else if (this.quotesEnabled && byte === this.delimiterCode) {
        this.finishField();
      } else if (this.quotesEnabled && byte === 0x22) {
        if (this.fieldAtStart) {
          this.inQuotes = true;
          this.fieldAtStart = false;
        } else {
          this.issue('quote_in_unquoted_field');
          this.appendFieldByte(byte);
          this.fieldAtStart = false;
        }
      } else {
        this.appendFieldByte(byte);
        this.fieldAtStart = false;
      }
    }
  }

  finish() {
    if (this.inQuotes) this.issue('unterminated_quoted_field');
    if (this.quoteClosed) this.quoteClosed = false;
    if (this.rowHasBytes || this.fieldCount > 0 || this.fieldLength > 0) this.finishRow();
    return this;
  }
}

function candidate(candidateName, confidence, evidence, basis) {
  return {
    candidate: candidateName,
    confidence: Number(Math.max(0, Math.min(1, confidence)).toFixed(4)),
    evidence,
    basis,
  };
}

function ratio(numerator, denominator) {
  return denominator > 0 ? numerator / denominator : 0;
}

function buildObservation(machine, limits, delimiter, diagnostics) {
  const rawRows = machine.rows;
  const firstRow = rawRows[0] || [];
  const secondRow = rawRows[1] || [];
  const firstNonMissing = firstRow.filter((value) => !isMissingValue(value));
  const firstStringish = firstNonMissing.filter((value) => !finiteNumber(value)).length;
  const secondNonMissing = secondRow.filter((value) => !isMissingValue(value));
  const secondNumeric = secondNonMissing.filter(finiteNumber).length;
  const width = machine.maxColumns || firstRow.length || 0;
  const firstHeaderNames = firstRow.filter((value) => /(?:^|[_ .-])(id|name|gene|sample|group|condition|value|count|status|type)(?:$|[_ .-])/i.test(String(value)));
  const oneRowHeaderSignal = firstNonMissing.length > 0 && (
    firstHeaderNames.length > 0 || ratio(firstStringish, firstNonMissing.length) >= 0.5
  );
  const likelyHeader = firstRow.length > 0 && (
    (rawRows.length < 2 && oneRowHeaderSignal)
      || (ratio(firstStringish, firstNonMissing.length) >= 0.5 && (
        ratio(secondNumeric, secondNonMissing.length) >= 0.5
        || ratio(firstHeaderNames.length, firstNonMissing.length) >= 0.5
      ))
  );
  const rawHeaders = firstRow.map((value) => String(value ?? ''));
  const headers = firstRow.map((value, index) => {
    const text = String(value ?? '');
    return text.trim() === '' ? `column_${index + 1}` : text;
  });
  const projectedHeaders = likelyHeader
    ? headers
    : firstRow.map((_, index) => `column_${index + 1}`);
  const dataRows = likelyHeader ? rawRows.slice(1) : rawRows;
  const sampledDataRows = dataRows.slice(0, limits.maxSampleRows);
  const maxSampleColumns = sampledDataRows.reduce((max, row) => Math.max(max, row.length), 0);

  const headerNames = new Map();
  const duplicateSignals = [];
  (likelyHeader ? headers : []).forEach((header, index) => {
    const normalized = header.trim().toLowerCase();
    if (!normalized) return;
    const previous = headerNames.get(normalized);
    if (previous !== undefined) {
      duplicateSignals.push(candidate(
        'duplicate_header_names',
        1,
        { columnIndexes: [previous, index], header },
        'the sampled header row contains the same normalized name more than once',
      ));
    } else {
      headerNames.set(normalized, index);
    }
  });

  const primitiveTypeCandidates = [];
  const primitiveTypeCandidatesByColumn = {};
  const primitiveTypeCandidatesByHeader = {};
  const missingSignals = [];
  for (let columnIndex = 0; columnIndex < width; columnIndex += 1) {
    const values = sampledDataRows.map((row) => row[columnIndex] ?? '');
    const missingCount = values.filter(isMissingValue).length;
    const nonMissingValues = values.filter((value) => !isMissingValue(value));
    const header = projectedHeaders[columnIndex] || `column_${columnIndex + 1}`;
    const typeCandidates = classifyPrimitiveCandidates(values);
    const typeEntry = {
      columnIndex,
      header,
      candidates: typeCandidates,
    };
    primitiveTypeCandidates.push(typeEntry);
    primitiveTypeCandidatesByColumn[String(columnIndex)] = typeCandidates;
    primitiveTypeCandidatesByHeader[header] = typeCandidates;
    missingSignals.push(candidate(
      'missing_values_present',
      ratio(missingCount, values.length),
      {
        columnIndex,
        header,
        sampledValues: values.length,
        missingValues: missingCount,
        nonMissingValues: nonMissingValues.length,
      },
      `missing-like tokens matched ${missingCount}/${values.length} sampled values`,
    ));

    const seen = new Map();
    let duplicateCount = 0;
    for (const value of nonMissingValues) {
      const key = String(value);
      if (seen.has(key)) duplicateCount += 1;
      else seen.set(key, true);
    }
    if (duplicateCount > 0) {
      duplicateSignals.push(candidate(
        'duplicate_values',
        ratio(duplicateCount, nonMissingValues.length),
        {
          columnIndex,
          header,
          sampledValues: nonMissingValues.length,
          duplicateValues: duplicateCount,
          uniqueValues: seen.size,
        },
        'exact duplicate values were observed in the sampled column',
      ));
    }
  }

  const totalCells = sampledDataRows.reduce((sum, row) => sum + row.length, 0);
  const numericCells = sampledDataRows.reduce(
    (sum, row) => sum + row.filter((value) => !isMissingValue(value) && finiteNumber(value)).length,
    0,
  );
  const firstColumnValues = sampledDataRows.map((row) => row[0]).filter((value) => !isMissingValue(value));
  const firstColumnUnique = new Set(firstColumnValues.map((value) => String(value))).size;
  const consistentRows = rawRows.filter((row) => row.length === width).length;
  const numericRatio = ratio(numericCells, totalCells);
  const numericValues = sampledDataRows.flatMap((row) => row.filter((value) => !isMissingValue(value) && finiteNumber(value)));
  const integerCells = numericValues.filter(integerValue).length;
  const integerRatio = ratio(integerCells, numericValues.length);
  const uniquenessRatio = ratio(firstColumnUnique, firstColumnValues.length);
  const normalizedHeaders = projectedHeaders.map((header) => String(header).trim().toLowerCase());
  const featureHeaderCount = normalizedHeaders.filter((header) => /(?:^|[_ .-])(gene|feature|transcript|ensembl|symbol|identifier|id)(?:$|[_ .-])/.test(header)).length;
  const sampleHeaderCount = normalizedHeaders.filter((header) => /(?:^|[_ .-])(sample|subject|patient|cell)(?:$|[_ .-])/.test(header)
    || /^s(?:ample)?[_ .-]?\d+$/i.test(header)
    || /^[a-z][a-z0-9.-]*[_-]\d+$/i.test(header)).length;
  const metadataHeaderCount = normalizedHeaders.filter((header) => /(?:^|[_ .-])(sample|subject|patient|group|condition|treatment|status|batch|pair|replicate)(?:$|[_ .-])/.test(header)).length;
  const featureHeaderRatio = ratio(featureHeaderCount, Math.max(width, 1));
  const sampleHeaderRatio = ratio(sampleHeaderCount, Math.max(width, 1));
  const metadataHeaderRatio = ratio(metadataHeaderCount, Math.max(width, 1));
  const rowWidthStability = ratio(consistentRows, rawRows.length);
  const rowToColumnRatio = ratio(dataRows.length, Math.max(width, 1));
  const matrixDimensionSignal = Math.min(1, rowToColumnRatio);
  const orientationCandidates = [
    candidate(
      'rows_are_records',
      ratio(consistentRows, rawRows.length),
      {
        sampledRows: rawRows.length,
        consistentWidthRows: consistentRows,
        observedColumnCount: width,
      },
      'candidate based on stable row width; this is a structural observation only',
    ),
    candidate(
      'rows_are_features_columns_samples',
      Math.min(1, numericRatio * 0.6 + uniquenessRatio * 0.25 + (rawRows.length >= width ? 0.15 : 0)),
      {
        sampledRows: dataRows.length,
        observedColumns: width,
        numericCellRatio: Number(numericRatio.toFixed(4)),
        firstColumnUniquenessRatio: Number(uniquenessRatio.toFixed(4)),
      },
      'candidate for a feature-by-sample matrix; no scientific meaning is asserted',
    ),
    candidate(
      'rows_are_samples_columns_features',
      Math.min(1, numericRatio * 0.6 + (width > dataRows.length ? 0.25 : 0) + (uniquenessRatio * 0.1)),
      {
        sampledRows: dataRows.length,
        observedColumns: width,
        numericCellRatio: Number(numericRatio.toFixed(4)),
        firstColumnUniquenessRatio: Number(uniquenessRatio.toFixed(4)),
      },
      'candidate for a sample-by-feature matrix; no scientific meaning is asserted',
    ),
  ].sort((left, right) => right.confidence - left.confidence);

  // These are file-shape hypotheses only.  The evidence intentionally stays
  // within the profiler's structural boundary: headers, numeric/integer
  // ratios, dimensions and stable row width.  No scientific profile is bound.
  const fileRoleEvidence = {
    headers: {
      observedColumns: width,
      featureHeaderCount,
      sampleHeaderCount,
      metadataHeaderCount,
    },
    sampledDataRows: dataRows.length,
    numericCellRatio: Number(numericRatio.toFixed(4)),
    integerCellRatioAmongNumeric: Number(integerRatio.toFixed(4)),
    rowToColumnRatio: Number(rowToColumnRatio.toFixed(4)),
    rowWidthStability: Number(rowWidthStability.toFixed(4)),
  };
  const fileRoleCandidates = [
    candidate(
      'counts_matrix',
      featureHeaderRatio * 0.3
        + numericRatio * 0.15
        + integerRatio * 0.35
        + sampleHeaderRatio * 0.1
        + rowWidthStability * 0.05
        + matrixDimensionSignal * 0.05,
      fileRoleEvidence,
      'candidate from feature/sample-like headers, numeric and integer ratios, matrix dimensions, and stable row width; scientific meaning is unresolved',
    ),
    candidate(
      'expression_matrix',
      featureHeaderRatio * 0.3
        + numericRatio * 0.35
        + (1 - integerRatio) * 0.25
        + rowWidthStability * 0.05
        + matrixDimensionSignal * 0.05,
      fileRoleEvidence,
      'candidate from feature-like headers, numeric values that are not exclusively integer-like, matrix dimensions, and stable row width; scale/normalization is unresolved',
    ),
    candidate(
      'sample_metadata',
      metadataHeaderRatio * 0.45
        + (1 - numericRatio) * 0.2
        + rowWidthStability * 0.15
        + matrixDimensionSignal * 0.2,
      fileRoleEvidence,
      'candidate from sample/condition-like headers, non-numeric value ratio, table dimensions, and stable row width; experimental design is unresolved',
    ),
  ].sort((left, right) => right.confidence - left.confidence);

  const firstHeader = String(projectedHeaders[0] || '').toLowerCase();
  const featureNameSignal = /gene|feature|transcript|ensembl|symbol|id/.test(firstHeader);
  const sampleNameSignal = /sample|subject|patient|cell/.test(firstHeader);
  const roleCandidates = [
    candidate(
      'feature_identifier_column',
      Math.min(1, uniquenessRatio * 0.55 + (featureNameSignal ? 0.4 : 0)),
      {
        firstColumnHeader: projectedHeaders[0] || null,
        firstColumnUniquenessRatio: Number(uniquenessRatio.toFixed(4)),
        namePatternMatched: featureNameSignal,
      },
      'candidate from first-column uniqueness and a header name pattern; identifier namespace is unresolved',
    ),
    candidate(
      'sample_identifier_column',
      Math.min(1, uniquenessRatio * 0.55 + (sampleNameSignal ? 0.4 : 0)),
      {
        firstColumnHeader: projectedHeaders[0] || null,
        firstColumnUniquenessRatio: Number(uniquenessRatio.toFixed(4)),
        namePatternMatched: sampleNameSignal,
      },
      'candidate from first-column uniqueness and a header name pattern; sample role is unresolved',
    ),
    candidate(
      'tabular_records',
      ratio(consistentRows, rawRows.length),
      { consistentWidthRows: consistentRows, sampledRows: rawRows.length, observedColumns: width },
      'candidate based on structural row/column regularity only',
    ),
  ].sort((left, right) => right.confidence - left.confidence);

  const sampleRows = rawRows.map((row) => row.slice());
  const observation = {
    profilerVersion: DATA_PROFILER_VERSION,
    version: DATA_PROFILER_VERSION,
    schemaVersion: 1,
    sample: {
      rows: sampleRows,
      dataRows: sampledDataRows.map((row) => row.slice()),
      rowCount: sampleRows.length,
      totalRowCount: machine.totalRows,
      dataRowCount: Math.max(0, machine.totalRows - (likelyHeader ? 1 : 0)),
      columnCount: width,
      bounds: {
        rows: { min: 0, max: limits.maxSampleRows, observed: sampleRows.length, truncated: machine.totalRows > limits.maxSampleRows },
        columns: { min: 0, max: limits.maxColumns, observed: maxSampleColumns, truncated: machine.maxColumns > limits.maxColumns },
      },
    },
    sampleRows,
    sampleRowCount: sampleRows.length,
    sampledRowCount: sampleRows.length,
    totalRowCount: machine.totalRows,
    sampleBounds: {
      rows: { min: 0, max: limits.maxSampleRows, observed: sampleRows.length, truncated: machine.totalRows > limits.maxSampleRows },
      columns: { min: 0, max: limits.maxColumns, observed: maxSampleColumns, truncated: machine.maxColumns > limits.maxColumns },
    },
    rowBounds: {
      min: machine.totalRows === 0 ? 0 : 1,
      max: machine.totalRows,
      observed: machine.totalRows,
      sampled: sampleRows.length,
    },
    columnBounds: {
      min: machine.minColumns || 0,
      max: machine.maxColumns,
      observed: width,
      sampled: maxSampleColumns,
    },
    headers: projectedHeaders,
    rawHeaders,
    headerCandidate: candidate(
      'header_present',
      likelyHeader ? (rawRows.length > 1 ? 0.85 : 0.55) : 0.25,
      {
        firstRowNonMissing: firstNonMissing.length,
        firstRowStringish: firstStringish,
        secondRowNumeric: secondNumeric,
        sampledRows: rawRows.length,
      },
      'candidate inferred from the first two sampled rows; it is not a semantic fact',
    ),
    primitiveTypeCandidates,
    primitiveTypes: primitiveTypeCandidates,
    primitiveTypeCandidatesByColumn,
    primitiveTypeCandidatesByHeader,
    missingSignals,
    missingnessSignals: missingSignals,
    duplicateSignals,
    duplicateValueSignals: duplicateSignals,
    orientationCandidates,
    orientation: orientationCandidates,
    fileRoleCandidates,
    roleCandidates,
    roles: roleCandidates,
    diagnostics: diagnostics.slice(),
  };
  return observation;
}

function validateInput(input) {
  const value = input && typeof input === 'object' ? input : {};
  const projectId = typeof value.projectId === 'string' ? value.projectId.trim() : '';
  const relativePath = typeof value.relativePath === 'string' ? value.relativePath.trim() : '';
  const absolutePath = typeof value.absolutePath === 'string' ? value.absolutePath : '';
  const errors = [];
  if (!projectId) errors.push('projectId is required');
  if (!relativePath || path.posix.isAbsolute(relativePath) || path.win32.isAbsolute(relativePath)
    || relativePath.split(/[\\/]/).includes('..')) {
    errors.push('relativePath must be a non-empty project-relative path');
  }
  if (!absolutePath || !path.isAbsolute(absolutePath)) errors.push('absolutePath must be an absolute path');
  return { value, projectId, relativePath, absolutePath, errors };
}

function baseSnapshot(projectId, relativePath, stat = null, fields = {}) {
  return {
    projectId: projectId || null,
    relativePath: relativePath || null,
    size: stat ? stat.size : null,
    mtime: stat ? stat.mtimeMs : null,
    mtimeIso: stat ? stat.mtime.toISOString() : null,
    modifiedAt: stat ? stat.mtimeMs : null,
    hash: null,
    sha256: null,
    version: SNAPSHOT_VERSION,
    schemaVersion: 1,
    encoding: 'unknown',
    delimiter: null,
    ...fields,
  };
}

function emptyObservation(diagnostics = []) {
  return {
    profilerVersion: DATA_PROFILER_VERSION,
    version: DATA_PROFILER_VERSION,
    schemaVersion: 1,
    sample: { rows: [], dataRows: [], rowCount: 0, totalRowCount: 0, dataRowCount: 0, columnCount: 0, bounds: {
      rows: { min: 0, max: 0, observed: 0, truncated: false },
      columns: { min: 0, max: 0, observed: 0, truncated: false },
    } },
    sampleRows: [],
    sampleRowCount: 0,
    sampledRowCount: 0,
    totalRowCount: 0,
    sampleBounds: { rows: { min: 0, max: 0, observed: 0, truncated: false }, columns: { min: 0, max: 0, observed: 0, truncated: false } },
    rowBounds: { min: 0, max: 0, observed: 0, sampled: 0 },
    columnBounds: { min: 0, max: 0, observed: 0, sampled: 0 },
    headers: [],
    headerCandidate: null,
    primitiveTypeCandidates: [],
    primitiveTypes: [],
    primitiveTypeCandidatesByColumn: {},
    primitiveTypeCandidatesByHeader: {},
    missingSignals: [],
    missingnessSignals: [],
    duplicateSignals: [],
    duplicateValueSignals: [],
    orientationCandidates: [],
    orientation: [],
    fileRoleCandidates: [],
    roleCandidates: [],
    roles: [],
    diagnostics: diagnostics.slice(),
  };
}

function resultForFailure(projectId, relativePath, diagnostics, stat = null, fields = {}) {
  const allDiagnostics = diagnostics.map((item) => ({ ...item }));
  const snapshot = baseSnapshot(projectId, relativePath, stat, fields);
  return {
    status: 'blocked',
    blocked: true,
    snapshot,
    observation: emptyObservation(allDiagnostics),
    diagnostics: allDiagnostics,
    diagnosticCodes: allDiagnostics.map((item) => item.code),
  };
}

async function profileData(input, runtimeOptions = undefined) {
  const request = input && typeof input === 'object' ? { ...input } : {};
  if (runtimeOptions && typeof runtimeOptions === 'object') {
    request.options = { ...(request.options || {}), ...runtimeOptions };
  }
  const validation = validateInput(request);
  const { projectId, relativePath, absolutePath } = validation;
  if (validation.errors.length > 0) {
    return resultForFailure(projectId, relativePath, [
      diagnostic('invalid_input', 'blocked', validation.errors.join('; '), { fields: validation.errors }),
    ]);
  }

  const extension = path.extname(relativePath).toLowerCase();
  let stat;
  try {
    stat = await fs.promises.stat(absolutePath);
  } catch (error) {
    const code = error && error.code === 'ENOENT' ? 'file_not_found'
      : error && (error.code === 'EACCES' || error.code === 'EPERM') ? 'permission_denied' : 'read_error';
    return resultForFailure(projectId, relativePath, [
      diagnostic(code, 'blocked', `Unable to inspect input file: ${error.message}`, { errno: error.code || null }),
    ]);
  }
  if (!stat.isFile()) {
    return resultForFailure(projectId, relativePath, [
      diagnostic('not_a_regular_file', 'blocked', 'absolutePath does not identify a regular file'),
    ], stat);
  }
  if (!SUPPORTED_EXTENSIONS.includes(extension)) {
    return resultForFailure(projectId, relativePath, [
      diagnostic('unsupported_file_type', 'blocked', `Only CSV, TSV and TXT inputs are supported: ${extension || '(no extension)'}`, {
        supportedExtensions: SUPPORTED_EXTENSIONS.slice(),
      }),
    ], stat);
  }

  const limits = normalizeLimits(request);
  const hash = crypto.createHash('sha256');
  const utf8 = new Utf8Validator();
  const probeParts = [];
  let probeLength = 0;
  let parser = null;
  let readBytes = 0;
  let streamError = null;
  let byteOffset = 0;
  let zeroByteCount = 0;
  const stream = fs.createReadStream(absolutePath, { highWaterMark: 64 * 1024 });
  const requestedDelimiter = request.options && request.options.delimiter
    ? request.options.delimiter : request.delimiter;

  function initializeParser(buffer) {
    const hasUtf8Bom = buffer.length >= 3 && buffer[0] === 0xef && buffer[1] === 0xbb && buffer[2] === 0xbf;
    const delimiter = detectDelimiter(
      hasUtf8Bom ? buffer.subarray(3) : buffer,
      extension,
      requestedDelimiter,
    );
    parser = new DelimitedStateMachine(delimiter, limits);
    parser.consume(hasUtf8Bom ? buffer.subarray(3) : buffer);
    return hasUtf8Bom;
  }

  let hasUtf8Bom = false;
  try {
    for await (const chunk of stream) {
      hash.update(chunk);
      readBytes += chunk.length;
      for (let index = 0; index < chunk.length; index += 1) {
        if (chunk[index] === 0) zeroByteCount += 1;
      }
      for (let index = 0; index < chunk.length; index += 1) {
        utf8.feed(chunk[index], byteOffset);
        byteOffset += 1;
      }
      if (parser) {
        parser.consume(chunk);
        continue;
      }
      const remaining = limits.maxProbeBytes - probeLength;
      if (remaining > 0) {
        const part = chunk.subarray(0, remaining);
        probeParts.push(part);
        probeLength += part.length;
      }
      if (probeLength >= limits.maxProbeBytes) {
        hasUtf8Bom = initializeParser(Buffer.concat(probeParts, probeLength));
        const consumed = Math.min(chunk.length, remaining);
        if (chunk.length > consumed) parser.consume(chunk.subarray(consumed));
      }
    }
  } catch (error) {
    streamError = error;
  }

  const probe = Buffer.concat(probeParts, probeLength);
  if (!parser) hasUtf8Bom = initializeParser(probe);
  parser.finish();
  const digest = streamError ? null : hash.digest('hex');
  if (streamError) {
    const code = streamError.code === 'EACCES' || streamError.code === 'EPERM' ? 'permission_denied' : 'read_error';
    return resultForFailure(projectId, relativePath, [
      diagnostic(code, 'blocked', `Unable to read input file: ${streamError.message}`, { errno: streamError.code || null, bytesRead: readBytes }),
    ], stat, { hash: digest, sha256: digest });
  }

  const diagnostics = [];
  let encoding = 'utf-8';
  let bom = hasUtf8Bom;
  if (probe.length >= 2 && ((probe[0] === 0xff && probe[1] === 0xfe) || (probe[0] === 0xfe && probe[1] === 0xff))) {
    encoding = 'unsupported';
    diagnostics.push(diagnostic('unsupported_encoding', 'blocked', 'UTF-16 byte-order marks are not supported; expected UTF-8', {
      detectedBom: probe.subarray(0, 2).toString('hex'),
    }));
  } else if (!utf8.finish()) {
    encoding = 'unsupported';
    diagnostics.push(diagnostic('unsupported_encoding', 'blocked', 'Input is not valid UTF-8', {
      invalidByte: utf8.invalidByte,
    }));
  } else if (readBytes > 0 && zeroByteCount / readBytes > 0.05) {
    // UTF-16 without a BOM often survives byte-level UTF-8 validation because
    // NUL bytes are legal ASCII.  A high NUL ratio is therefore an encoding
    // candidate, never a semantic fact, and is blocked for safe handling.
    encoding = 'unsupported';
    diagnostics.push(diagnostic('unsupported_encoding', 'blocked', 'Input contains a high NUL-byte ratio consistent with an unsupported text encoding', {
      zeroByteCount,
      bytesRead: readBytes,
    }));
  }
  if (readBytes !== stat.size) {
    diagnostics.push(diagnostic('file_changed_during_read', 'blocked', 'File size changed while it was being profiled', {
      statSize: stat.size,
      bytesRead: readBytes,
    }));
  }
  if (readBytes === 0) diagnostics.push(diagnostic('empty_file', 'blocked', 'Input file is empty'));
  if (parser.totalRows === 0 && readBytes > 0) diagnostics.push(diagnostic('empty_dataset', 'blocked', 'No delimited rows were observed'));
  if (parser.issueCodes.has('too_wide')) diagnostics.push(diagnostic('too_wide', 'blocked', `A row exceeded the ${limits.maxColumns}-column bound`, {
    maxColumns: limits.maxColumns,
  }));
  if (parser.issueCodes.has('truncated_row')) diagnostics.push(diagnostic('truncated_row', 'blocked', `A row exceeded the ${limits.maxRowBytes}-byte bound`, {
    maxRowBytes: limits.maxRowBytes,
  }));
  if (parser.issueCodes.has('truncated_cell')) diagnostics.push(diagnostic('truncated_cell', 'blocked', `A cell exceeded the ${limits.maxCellBytes}-byte bound`, {
    maxCellBytes: limits.maxCellBytes,
  }));
  if (parser.issueCodes.has('unterminated_quoted_field')) diagnostics.push(diagnostic('unterminated_quoted_field', 'blocked', 'A quoted field was not closed before end of file'));
  if (parser.issueCodes.has('quote_in_unquoted_field')) diagnostics.push(diagnostic('quote_in_unquoted_field', 'blocked', 'A quote appeared inside an unquoted field'));
  if (parser.issueCodes.has('characters_after_closing_quote')) diagnostics.push(diagnostic('characters_after_closing_quote', 'blocked', 'Unexpected characters followed a closing quote'));
  if (parser.totalRows === 1 && parser.rows[0] && parser.rows[0].every((value) => isMissingValue(value))) {
    diagnostics.push(diagnostic('empty_dataset', 'blocked', 'Only an empty row was observed'));
  }
  if (parser.totalRows > limits.maxSampleRows) {
    diagnostics.push(diagnostic('sample_truncated', 'warning', `Only the first ${limits.maxSampleRows} rows were retained`, {
      totalRows: parser.totalRows,
      sampledRows: parser.rows.length,
    }));
  }
  if (parser.maxColumns > limits.maxColumns) {
    // Keep the diagnostic generated above as the authoritative blocked signal.
    if (!diagnostics.some((item) => item.code === 'too_wide')) diagnostics.push(diagnostic('too_wide', 'blocked', 'Observed columns exceeded the configured bound'));
  }
  if (parser.malformed && !diagnostics.some((item) => item.code === 'malformed_csv')) {
    diagnostics.push(diagnostic('malformed_csv', 'blocked', 'CSV/TSV quoting rules were not satisfied'));
  }
  if (parser.totalRows > 0 && parser.maxColumns === 1 && parser.delimiter === null) {
    diagnostics.push(diagnostic('delimiter_not_detected', 'warning', 'No supported delimiter was observed; treating each line as one field'));
  }

  const delimiter = parser.delimiter;
  const observation = buildObservation(parser, limits, delimiter, diagnostics);
  if (parser.totalRows > 0 && observation.sample.dataRowCount === 0
    && observation.headerCandidate && observation.headerCandidate.confidence >= 0.5) {
    const noDataRows = diagnostic('no_data_rows', 'blocked', 'A header-like row was observed but no data rows were available', {
      headerColumns: observation.headers.length,
    });
    diagnostics.push(noDataRows);
    observation.diagnostics.push(noDataRows);
  }
  const snapshot = baseSnapshot(projectId, relativePath, stat, {
    hash: digest,
    sha256: digest,
    encoding,
    bom,
    encodingDetails: {
      candidate: encoding,
      confidence: encoding === 'utf-8' ? 1 : 0,
      evidence: { utf8Validator: encoding === 'utf-8', bom },
      basis: encoding === 'utf-8' ? 'complete stream passed the UTF-8 validator' : 'stream failed the supported UTF-8 checks',
      bom,
    },
    delimiter,
    delimiterDetails: {
      candidate: delimiter,
      confidence: delimiter === null ? 0 : 1,
      evidence: { extension, sampledBytes: probe.length, quoteAware: true },
      basis: delimiter === null ? 'no supported delimiter observed in the bounded probe' : 'quote-aware delimiter observation in the bounded probe',
    },
  });
  const blocked = diagnostics.some(isBlockingDiagnostic);
  return {
    status: blocked ? 'blocked' : 'ok',
    blocked,
    snapshot,
    observation,
    diagnostics,
    diagnosticCodes: diagnostics.map((item) => item.code),
  };
}

module.exports = {
  DATA_PROFILER_VERSION,
  SNAPSHOT_VERSION,
  SUPPORTED_EXTENSIONS,
  DEFAULT_LIMITS,
  profileData,
  profileDataFile: profileData,
  profileDataSnapshot: profileData,
  createDataProfile: profileData,
};

'use strict';

/**
 * BLOCK-88 P1 工程师声明身份（D1-A 轻量声明身份）。
 *
 * 配对握手 additive identity：访客工程师自带 displayName/device 标注，存被访端
 * gateway 会话（sessions.json）与本端 peers 注册表；对端仅展示、不建账号体系
 * （auth.js 单管理员设计零触碰）。信任模型 = 配对 token + 熟人网络，面板须诚实
 * 标注「声明身份，未经验证」（plan §6 风险 1）。
 *
 * 展示字段不信任输入方：剥离控制字符 + 截断封顶；三处消费方共用本定义，
 * 避免各写一份截断/净化规则漂移（gateway 配对 / peers 注册表 / 契约测试）。
 */

const FIELD_MAX = 40;

function cleanField(value) {
  return typeof value === 'string'
    ? value.replace(/[\u0000-\u001f\u007f]/g, '').trim().slice(0, FIELD_MAX)
    : '';
}

/**
 * 任意输入 → 安全身份对象；无有效字段返回 null（调用方据此不落 identity 键，
 * 存量无身份会话/节点的投影键集保持不变）。
 */
function sanitizeEngineerIdentity(raw) {
  if (!raw || typeof raw !== 'object') return null;
  const displayName = cleanField(raw.displayName);
  const device = cleanField(raw.device);
  if (!displayName && !device) return null;
  const identity = {};
  if (displayName) identity.displayName = displayName;
  if (device) identity.device = device;
  return identity;
}

module.exports = { sanitizeEngineerIdentity, FIELD_MAX };

const path = require('path');

const EXECUTION_CONTEXT_VERSION = 2;

function normalizeSlashPath(value) {
  return (
    String(value || '')
      .replace(/\\/g, '/')
      .replace(/\/+$/, '') || '/'
  );
}

function createPathMapper({ localRoot, canonicalRoot = '/work/petri' } = {}) {
  const resolvedLocalRoot = localRoot ? path.resolve(String(localRoot)) : null;
  const normalizedLocalRoot = resolvedLocalRoot ? normalizeSlashPath(resolvedLocalRoot) : null;
  const normalizedCanonicalRoot = normalizeSlashPath(canonicalRoot);

  function canonicalize(localPath) {
    if (!localPath) return null;
    const raw = normalizeSlashPath(localPath);
    if (raw === normalizedCanonicalRoot || raw.startsWith(normalizedCanonicalRoot + '/')) {
      return raw;
    }
    const resolved = normalizeSlashPath(path.resolve(String(localPath)));
    if (!normalizedLocalRoot) return resolved;
    if (resolved === normalizedLocalRoot) return normalizedCanonicalRoot;
    if (resolved.startsWith(normalizedLocalRoot + '/')) {
      return normalizeSlashPath(
        path.posix.join(normalizedCanonicalRoot, resolved.slice(normalizedLocalRoot.length + 1))
      );
    }
    return resolved;
  }

  return {
    localRoot: resolvedLocalRoot,
    canonicalRoot: normalizedCanonicalRoot,
    canonicalize,
  };
}

function runtimeReadiness({ runtime, runtimeCommand, runtimeReady } = {}) {
  return (
    runtimeReady ||
    (runtimeCommand
      ? { runtime: runtime || null, ready: true, command: runtimeCommand, reason: null }
      : {
          runtime: runtime || null,
          ready: false,
          command: null,
          reason: 'runtime command unavailable',
        })
  );
}

function createExecutionContext(options = {}) {
  const {
    jobId,
    toolId,
    platform,
    runtime,
    runtimeCommand,
    runtimeReady,
    workDir,
    jobDir,
    executionWorkDir,
    outputDir,
    resultDir,
    workerId,
    localRoot,
    canonicalRoot,
  } = options;
  const mapper = createPathMapper({ localRoot, canonicalRoot });
  const localWorkDir = workDir || jobDir || null;
  const targetWorkDir = executionWorkDir || localWorkDir;
  const context = {
    executionContextVersion: EXECUTION_CONTEXT_VERSION,
    adapter: {
      kind: 'local',
      workerId: workerId || null,
    },
    platform: platform || null,
    jobId: jobId || null,
    toolId: toolId || null,
    runtime: runtime || null,
    runtimeReady: runtimeReadiness({ runtime, runtimeCommand, runtimeReady }),
    workDir: localWorkDir ? path.resolve(String(localWorkDir)) : null,
    canonicalWorkDir: mapper.canonicalize(localWorkDir),
    executionWorkDir: targetWorkDir ? normalizeSlashPath(targetWorkDir) : null,
  };
  if (outputDir) {
    context.outputDir = path.resolve(String(outputDir));
    context.canonicalOutputDir = mapper.canonicalize(outputDir);
  }
  if (resultDir) {
    context.resultDir = path.resolve(String(resultDir));
    context.canonicalResultDir = mapper.canonicalize(resultDir);
  }
  return { context, canonicalizePath: mapper.canonicalize, mapper };
}

function attachExecutionMetadata(result = {}, context) {
  const enriched = { ...result, execution: context };
  const localRoot = context?.resultDir || context?.outputDir || context?.workDir;
  const canonicalRoot =
    context?.canonicalResultDir || context?.canonicalOutputDir || context?.canonicalWorkDir;
  for (const key of ['artifacts', 'outputs', 'files']) {
    if (!Array.isArray(enriched[key])) continue;
    enriched[key] = enriched[key].map((item) => {
      if (!item || typeof item !== 'object') return item;
      const filename = item.filename || item.name || item.path;
      if (!filename) return item;
      const name = path.basename(String(filename));
      return {
        ...item,
        // Serialize with forward slashes so the value is stable across
        // platforms (Windows path.join emits backslashes / drive prefixes).
        path: item.path || (localRoot ? normalizeSlashPath(path.join(localRoot, name)) : null),
        canonicalPath:
          item.canonicalPath ||
          (canonicalRoot ? normalizeSlashPath(path.posix.join(canonicalRoot, name)) : null),
      };
    });
  }
  return enriched;
}

module.exports = {
  EXECUTION_CONTEXT_VERSION,
  normalizeSlashPath,
  createPathMapper,
  createExecutionContext,
  attachExecutionMetadata,
};

'use strict';

const crypto = require('crypto');
const fs = require('fs');
const path = require('path');
const { stableStringify } = require('./canonical-json');
const { isSafeRelativePath } = require('./result-studio-contracts');

const EXECUTION_PROVENANCE_VERSION = 1;

function sha256Buffer(buffer) { return crypto.createHash('sha256').update(buffer).digest('hex'); }
function hashFile(filePath) {
  if (!filePath || !fs.existsSync(filePath)) return null;
  return sha256Buffer(fs.readFileSync(filePath));
}

function executionProvenancePayload(provenance) {
  if (!provenance || typeof provenance !== 'object' || Array.isArray(provenance)) return null;
  const { provenanceHash: _provenanceHash, ...payload } = provenance;
  return payload;
}

function computeExecutionProvenanceHash(provenance) {
  const payload = executionProvenancePayload(provenance);
  return payload == null
    ? null
    : sha256Buffer(Buffer.from(stableStringify(payload)));
}

function verifyExecutionProvenance(provenance) {
  const actualHash = typeof provenance?.provenanceHash === 'string'
    ? provenance.provenanceHash.trim()
    : '';
  const expectedHash = computeExecutionProvenanceHash(provenance);
  return {
    ok: /^[a-f0-9]{64}$/.test(actualHash) && actualHash === expectedHash,
    actualHash: actualHash || null,
    expectedHash,
  };
}

function isContained(root, target) {
  return target === root || target.startsWith(`${root}${path.sep}`);
}

function containedRegularFile(root, candidate) {
  if (!candidate) return null;
  try {
    const target = fs.realpathSync(candidate);
    return isContained(root, target) && fs.statSync(target).isFile() ? target : null;
  } catch {
    return null;
  }
}

function resolveExecutionInputPath({ workspaceRoot, input, sourceParams = {}, provenance = null } = {}) {
  let root;
  try { root = fs.realpathSync(workspaceRoot); } catch {
    return { path: null, source: null, reason: 'workspace_unavailable' };
  }
  const inputId = typeof input?.id === 'string' ? input.id.trim() : '';
  const relativePath = typeof input?.relativePath === 'string' ? input.relativePath.trim() : '';
  if (!/^[A-Za-z0-9][A-Za-z0-9._-]*$/.test(inputId)
      || !isSafeRelativePath(relativePath)) {
    return { path: null, source: null, reason: 'input_identity_invalid' };
  }

  const supplied = sourceParams && typeof sourceParams[inputId] === 'string'
    ? sourceParams[inputId]
    : null;
  if (supplied) {
    if (path.isAbsolute(supplied)) {
      const target = containedRegularFile(root, supplied);
      return target
        ? { path: target, source: 'explicit_parameter', reason: null }
        : { path: null, source: null, reason: 'explicit_parameter_unavailable' };
    }
    if (!isSafeRelativePath(supplied)) {
      return { path: null, source: null, reason: 'explicit_parameter_unsafe' };
    }
  }

  const logicalPath = path.resolve(root, relativePath);
  if (isContained(root, logicalPath)) {
    const target = containedRegularFile(root, logicalPath);
    if (target) return { path: target, source: 'logical_relative_path', reason: null };
  }

  const snapshot = containedRegularFile(root, provenance?.script?.snapshotPath);
  if (!snapshot) return { path: null, source: null, reason: 'snapshot_unavailable' };
  const jobRoot = path.dirname(snapshot);
  if (supplied) {
    const target = containedRegularFile(root, path.resolve(jobRoot, supplied));
    if (target) return { path: target, source: 'explicit_parameter', reason: null };
  }
  const expectedName = path.basename(relativePath);
  const fromDirectory = (directory, source) => {
    let entries;
    try { entries = fs.readdirSync(directory, { withFileTypes: true }); } catch { return null; }
    const exact = entries.find((entry) => entry.isFile() && entry.name === expectedName);
    if (exact) {
      const target = containedRegularFile(root, path.join(directory, exact.name));
      return target ? { path: target, source, reason: null } : null;
    }
    const matches = entries
      .filter((entry) => entry.isFile() && (entry.name === inputId || entry.name.startsWith(`${inputId}.`)))
      .map((entry) => containedRegularFile(root, path.join(directory, entry.name)))
      .filter(Boolean);
    if (matches.length === 1) return { path: matches[0], source, reason: null };
    if (matches.length > 1) return { path: null, source: null, reason: 'snapshot_input_ambiguous' };
    return null;
  };
  const canonical = fromDirectory(path.join(jobRoot, 'inputs', inputId), 'job_canonical_input');
  if (canonical) return canonical;
  const legacy = fromDirectory(jobRoot, 'job_compatibility_input');
  if (legacy) return legacy;
  return { path: null, source: null, reason: 'snapshot_input_missing' };
}

function createExecutionProvenance({
  toolJobId, projectId, scientificTask = null, plugin = {}, params = {},
  runtime = {}, runScriptPath = null, command = null, artifacts = [], inputs = [], startedAt = null, completedAt = null,
} = {}) {
  if (!toolJobId) throw new Error('provenance_tool_job_id_required');
  const scriptHash = hashFile(runScriptPath);
  const taskSpec = scientificTask?.spec || null;
  const inputSnapshots = ((taskSpec?.inputs && taskSpec.inputs.length > 0) ? taskSpec.inputs : inputs).map((input) => ({
    id: input.id || null,
    role: input.role || null,
    relativePath: input.relativePath,
    sha256: input.sha256,
    sizeBytes: input.sizeBytes,
    sourceArtifactRef: input.sourceArtifactRef || null,
    lineage: input.lineage && typeof input.lineage === 'object' && !Array.isArray(input.lineage)
      ? { ...input.lineage }
      : null,
  }));
  const normalizedParams = { ...params };
  for (const input of inputSnapshots) {
    if (input.id) {
      normalizedParams[input.id] = { inputRef: input.relativePath, sha256: input.sha256 };
    }
  }
  const language = plugin.language || null;
  const record = {
    executionProvenanceVersion: EXECUTION_PROVENANCE_VERSION,
    toolJobId,
    projectId: projectId || null,
    task: scientificTask ? { taskId: scientificTask.task_id, version: scientificTask.version, specHash: scientificTask.spec_hash, confirmationVersion: scientificTask.confirmation?.confirmationVersion || null } : null,
    plugin: { id: plugin.id || null, version: plugin.version || null, language, manifestFingerprint: plugin.execution?.scriptFingerprint || plugin._currentFingerprint || null, packageConstraints: plugin.packages?.[language] || {} },
    runtime: { name: runtime.name || runtime.runtime || plugin.language || null, command: runtime.command || null, version: runtime.version || plugin.builtAgainst?.[plugin.language] || null, versionSource: runtime.version ? 'runtime_probe' : plugin.builtAgainst?.[plugin.language] ? 'plugin_built_against' : null, readiness: runtime.ready ?? null },
    params: { normalized: normalizedParams, sha256: sha256Buffer(Buffer.from(stableStringify(normalizedParams))) },
    inputs: inputSnapshots,
    script: { snapshotPath: runScriptPath ? path.resolve(runScriptPath) : null, sha256: scriptHash, entryPoint: plugin.entryPoint || null },
    command: command ? { executable: command.executable || null, args: Array.isArray(command.args) ? command.args : [], cwd: command.cwd || null } : null,
    startedAt,
    completedAt,
    artifacts: (artifacts || []).map((artifact) => ({ id: artifact.id || null, filename: artifact.filename || artifact.name || null, type: artifact.type || null, sha256: hashFile(artifact.path), reproductionTarget: artifact.id || artifact.filename || artifact.name || null })),
  };
  return { ...record, provenanceHash: computeExecutionProvenanceHash(record) };
}

function attachProvenanceToResult(result, provenance, provenancePath = null) {
  const ref = { provenanceHash: provenance.provenanceHash, path: provenancePath, toolJobId: provenance.toolJobId };
  const artifacts = (result.artifacts || []).map((artifact) => ({ ...artifact, provenance: { ...ref, reproductionTarget: artifact.id || artifact.filename || artifact.name || null } }));
  return { ...result, executionProvenance: provenance, provenanceRef: ref, artifacts, outputs: artifacts.map((item) => ({ ...item })), files: artifacts.map((item) => ({ ...item })) };
}

module.exports = {
  EXECUTION_PROVENANCE_VERSION,
  hashFile,
  computeExecutionProvenanceHash,
  verifyExecutionProvenance,
  resolveExecutionInputPath,
  createExecutionProvenance,
  attachProvenanceToResult,
};

/**
 * Python Executor — Python 语言执行器实现
 *
 * 桌面版直接调内嵌 Python（本地执行）。
 *
 * 与 RExecutor 对称，实现同一 LanguageExecutor 接口。
 */

const path = require('path');
const fs = require('fs');
const { execFileSync, spawn } = require('child_process');
const logger = require('../logger');
const {
  getPythonRuntimeExecutable,
  getPythonSitePackagesDir,
  findExecutableOnPath,
} = require('../runtime-paths');

// 从 config-helper 读取配置（断点1：斩断对 py-server/config 的反向 require）
// 调用方启动时通过 require('shared-backend').configure({getConfig}) 注入；
// 未注入时 config-helper 走 env fallback，仍能独立跑。
const configHelper = require('../config-helper');
function getPyConfig() {
  return configHelper.getConfig();
}

class PythonExecutor {
  get name() {
    return 'python';
  }

  /** Python 可执行文件路径（内嵌 Python）。 */
  get binPath() {
    const cfg = getPyConfig();
    // BLOCK-30 P1: py-server/Python dev fallback removed with py-server;
    // empty runtimeHome → getPythonRuntimeExecutable null → system PATH fallback.
    const runtimeHome = cfg.pyHome || '';
    return getPythonRuntimeExecutable(runtimeHome) || findExecutableOnPath(getPythonExecutableNames());
  }

  /**
   * 构造运行 Python 脚本的完整命令参数。
   * @param {string} scriptPath - Python 脚本绝对路径
   * @param {string} workDir - 工作目录
   * @param {object} params - 工具参数（写入 params.json 供 Python 读取）
   * @returns {string[]} spawn 参数数组（不含可执行文件本身）
   */
  buildRunArgs(scriptPath, workDir, params) {
    const paramFile = path.join(workDir, 'params.json');
    fs.writeFileSync(paramFile, JSON.stringify(params));
    return [scriptPath, '--params', paramFile];
  }

  /**
   * 构造完整的 spawn 命令（含可执行文件）。
   * ['/path/to/python3', script.py, --params, params.json]
   * @returns {{cmd: string, args: string[], env: object}}
   */
  buildSpawnCommand(scriptPath, workDir, params) {
    const cfg = getPyConfig();
    const scriptArgs = this.buildRunArgs(scriptPath, workDir, params);
    const env = { ...process.env };
    // 确保 site-packages 在 PYTHONPATH 里
    const siteDir = getPythonSitePackagesDir(cfg.pyHome || '');
    if (fs.existsSync(siteDir)) {
      env.PYTHONPATH = siteDir + (env.PYTHONPATH ? path.delimiter + env.PYTHONPATH : '');
    }
    return { cmd: this.binPath, args: scriptArgs, env };
  }

  /** 创建进程池 worker（常驻 Python 进程）。 */
  buildPoolWorker() {
    const cfg = getPyConfig();
    const pyBin = this.binPath;
    const siteDir = getPythonSitePackagesDir(cfg.pyHome || '');
    const env = { ...process.env };
    if (fs.existsSync(siteDir)) {
      env.PYTHONPATH = siteDir + (env.PYTHONPATH ? path.delimiter + env.PYTHONPATH : '');
    }
    return spawn(pyBin, ['-u', '-i'], { env });
  }

  /** 检查 Python 包是否已安装（site-packages/<pkg>）。 */
  checkPackageInstalled(pkgName) {
    const cfg = getPyConfig();
    const normalized = pkgName.replace(/-/g, '_');
    const siteDir = getPythonSitePackagesDir(cfg.pyHome || '');
    // Python 包目录可能是 pkg_name/ 或 pkg_name.egg-info/ 或 pkg.dist-info/
    return (
      fs.existsSync(path.join(siteDir, normalized)) ||
      fs.existsSync(path.join(siteDir, `${normalized}.egg-info`)) ||
      fs.existsSync(path.join(siteDir, `${normalized}.dist-info`))
    );
  }

  /**
   * 安装插件带来的预编译 Python 包。
   * Python 包（conda-pack 产出）解压到 site-packages/ 即可。
   */
  installPackages(pkgDir, targetDir) {
    const cfg = getPyConfig();
    const siteDir = targetDir || getPythonSitePackagesDir(cfg.pyHome || '');
    if (!fs.existsSync(pkgDir)) {
      logger.warn(`[py-executor] 包目录不存在: ${pkgDir}`);
      return;
    }
    fs.mkdirSync(siteDir, { recursive: true });
    const entries = fs.readdirSync(pkgDir);
    for (const entry of entries) {
      const src = path.join(pkgDir, entry);
      const dst = path.join(siteDir, entry);
      if (fs.existsSync(dst)) {
        fs.rmSync(dst, { recursive: true, force: true });
      }
      copyDirRecursive(src, dst);
      logger.info(`[py-executor] 安装包: ${entry}`);
    }
  }

  /**
   * 校验 Python 版本是否满足要求。
   * @param {string} required - 如 ">=3.11"
   */
  checkRuntimeVersion(required) {
    const current = this._getPyVersion();
    return satisfiesVersion(current, required);
  }

  /** 返回本次实际可执行文件的 Python 版本，供 provenance 固化。 */
  getRuntimeVersion() {
    return this._getPyVersion();
  }

  /**
   * 校验插件包的 builtAgainst 与当前 Python 的 major.minor 是否兼容。
   * Python C 扩展在 X.Y 编译，加载到 X.Z（不同 minor）会 ABI 不兼容。
   * @param {string} builtAgainst - 如 "3.11" 或 "3.11.x"
   * @returns {{ok: boolean, current: string, required: string}}
   */
  checkBuiltAgainst(builtAgainst) {
    const current = this._getPyVersion();
    const curMM = current.split('.').slice(0, 2).join('.');
    const reqMM = String(builtAgainst).split('.').slice(0, 2).join('.');
    return { ok: curMM === reqMM, current, required: builtAgainst };
  }

  _getPyVersion() {
    try {
      const pyBin = this.binPath;
      const out = execFileSync(pyBin, ['--version'], { encoding: 'utf8', timeout: 5000 });
      return out.match(/Python (\d+\.\d+\.\d+)/)?.[1] || '0.0.0';
    } catch {
      return '0.0.0';
    }
  }
}

// ── helpers ──────────────────────────────────────────────────

function copyDirRecursive(src, dst) {
  if (!fs.existsSync(src)) return;
  const stat = fs.statSync(src);
  if (stat.isDirectory()) {
    fs.mkdirSync(dst, { recursive: true });
    for (const entry of fs.readdirSync(src)) {
      copyDirRecursive(path.join(src, entry), path.join(dst, entry));
    }
  } else {
    fs.copyFileSync(src, dst);
  }
}

function parseVersion(v) {
  return v.split('.').map((x) => parseInt(x, 10) || 0);
}

function compareVersions(a, b) {
  const pa = parseVersion(a);
  const pb = parseVersion(b);
  for (let i = 0; i < Math.max(pa.length, pb.length); i++) {
    const da = pa[i] || 0;
    const db = pb[i] || 0;
    if (da > db) return 1;
    if (da < db) return -1;
  }
  return 0;
}

function satisfiesVersion(current, requirement) {
  // requirement: ">=3.11" 或 "3.11.9" 或 ">=3.11.0"
  const match = requirement.match(/^(>=|>|<=|<|==)?\s*(\d+(?:\.\d+){0,2})$/);
  if (!match) return true;
  const [, op, required] = match;
  const cmp = compareVersions(current, required);
  switch (op) {
    case '>=':
      return cmp >= 0;
    case '>':
      return cmp > 0;
    case '<=':
      return cmp <= 0;
    case '<':
      return cmp < 0;
    case '==':
      return cmp === 0;
    default:
      return cmp >= 0;
  }
}

module.exports = { PythonExecutor };

function getPythonExecutableNames() {
  return process.platform === 'win32'
    ? ['python.exe', 'python3.exe', 'python3.11.exe']
    : ['python3', 'python'];
}

