const canonical = (value) => value === null || typeof value !== 'object'
  ? JSON.stringify(value)
  : Array.isArray(value) ? `[${value.map(canonical).join(',')}]`
    : `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${canonical(value[key])}`).join(',')}}`;
const digest = (value) => crypto.createHash('sha256').update(canonical(value)).digest('hex');

function validateCompression({ beforeFacts = [], afterFacts = [], trigger, sourceCheckpointHash } = {}) {
  const before = new Map(beforeFacts.map((item) => [item.factId, item]));
  const after = new Map(afterFacts.map((item) => [item.factId, item]));
  const missing = [...before.keys()].filter((id) => !after.has(id));
  const changed = [...before.keys()].filter((id) => after.has(id) && digest(before.get(id)) !== digest(after.get(id)));
  const validTrigger = contract.compressionTriggers.includes(trigger);
  const result = {
    modelMemoryCostVersion: MODEL_MEMORY_COST_VERSION,
    valid: validTrigger && Boolean(sourceCheckpointHash) && missing.length === 0 && changed.length === 0,
    trigger: validTrigger ? trigger : 'invalid',
    sourceCheckpointHash: sourceCheckpointHash || null,
    missing,
    changed,
  };
  return Object.freeze({ ...result, validationHash: digest(result) });
}

function buildCacheIdentity(fields = {}) {
  const missing = contract.cacheFingerprintFields.filter((field) => fields[field] == null);
  return Object.freeze({
    valid: missing.length === 0,
    missing,
    cacheKey: missing.length ? null : digest(fields),
    projectId: fields.project || null,
  });
}

function aggregateUsage(entries = []) {
  const totals = entries.reduce((sum, item) => ({
    inputTokens: sum.inputTokens + Number(item.inputTokens || 0),
    outputTokens: sum.outputTokens + Number(item.outputTokens || 0),
    cacheReadTokens: sum.cacheReadTokens + Number(item.cacheReadTokens || 0),
    cacheWriteTokens: sum.cacheWriteTokens + Number(item.cacheWriteTokens || 0),
    cost: sum.cost + Number(item.cost || 0),
  }), { inputTokens: 0, outputTokens: 0, cacheReadTokens: 0, cacheWriteTokens: 0, cost: 0 });
  const currencies = [...new Set(entries.map((item) => item.currency).filter(Boolean))];
  return Object.freeze({ ...totals, currency: currencies.length === 1 ? currencies[0] : currencies.length ? 'mixed' : null, entryCount: entries.length });
}

function evaluateProviderFallback({ capabilityCompatible, policyAllowed, auditRecorded, scientificGatesUnchanged } = {}) {
  const checks = { capabilityCompatible, policyAllowed, auditRecorded, scientificGatesUnchanged };
  const failed = Object.entries(checks).filter(([, value]) => value !== true).map(([key]) => key);
  return Object.freeze({ allowed: failed.length === 0, failed, silent: auditRecorded !== true });
}

module.exports = { MODEL_MEMORY_COST_VERSION, contract, validateCompression, buildCacheIdentity, aggregateUsage, evaluateProviderFallback };

'use strict';

const crypto = require('crypto');
const contract = require('./g0/reproducibility-lab.json');

const REPRODUCIBILITY_LAB_VERSION = 1;

function canonical(value) {
  if (value === null || typeof value !== 'object') return JSON.stringify(value);
  if (Array.isArray(value)) return `[${value.map(canonical).join(',')}]`;
  return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${canonical(value[key])}`).join(',')}}`;
}

function digest(value) {
  return crypto.createHash('sha256').update(canonical(value)).digest('hex');
}

function validateReplayCorpus(cases = []) {
  const issues = [];
  const ids = new Set();
  const kinds = new Set();
  for (const entry of cases) {
    if (!entry?.caseId || ids.has(entry.caseId)) issues.push(`case_id_invalid:${entry?.caseId || 'missing'}`);
    ids.add(entry?.caseId);
    kinds.add(entry?.kind);
    if (!contract.corpusCaseKinds.includes(entry?.kind)) issues.push(`case_kind_invalid:${entry?.caseId || 'missing'}`);
    for (const field of contract.requiredFingerprintFields) {
      if (!(field in (entry?.fingerprints || {}))) issues.push(`fingerprint_missing:${entry?.caseId || 'missing'}:${field}`);
    }
    if (!Array.isArray(entry?.artifacts) || entry.artifacts.length === 0) issues.push(`artifacts_missing:${entry?.caseId || 'missing'}`);
  }
  for (const kind of contract.corpusCaseKinds) {
    if (!kinds.has(kind)) issues.push(`corpus_kind_missing:${kind}`);
  }
  return Object.freeze({ ok: issues.length === 0, issues: Object.freeze(issues), caseCount: cases.length });
}

function compareArtifact(expected = {}, actual = {}) {
  const mode = expected.comparisonMode;
  if (!contract.artifactComparisonModes.includes(mode)) {
    return Object.freeze({ mode: mode || null, matched: false, driftKind: 'unknown', reason: 'comparison_mode_invalid' });
  }
  if (mode === 'deterministic') {
    const matched = Boolean(expected.sha256 && actual.sha256 && expected.sha256 === actual.sha256);
    return Object.freeze({ mode, matched, driftKind: matched ? null : 'artifact_drift' });
  }
  if (mode === 'tolerance_based') {
    const expectedValues = expected.values || [];
    const actualValues = actual.values || [];
    if (expectedValues.length !== actualValues.length || expectedValues.some((value) => !Number.isFinite(value)) || actualValues.some((value) => !Number.isFinite(value))) {
      return Object.freeze({ mode, matched: false, driftKind: 'unknown', reason: 'numeric_shape_or_value_invalid' });
    }
    const absolute = Number(expected.tolerance?.absolute ?? 0);
    const relative = Number(expected.tolerance?.relative ?? 0);
    const deltas = expectedValues.map((value, index) => Math.abs(actualValues[index] - value));
    const matched = deltas.every((delta, index) => delta <= Math.max(absolute, Math.abs(expectedValues[index]) * relative));
    return Object.freeze({ mode, matched, driftKind: matched ? null : 'artifact_drift', maxAbsoluteDelta: deltas.length ? Math.max(...deltas) : 0 });
  }
  const expectedClaims = [...new Set((expected.claims || []).map((item) => `${item.claimId}:${item.evidenceRef}`))].sort();
  const actualClaims = [...new Set((actual.claims || []).map((item) => `${item.claimId}:${item.evidenceRef}`))].sort();
  const matched = canonical(expectedClaims) === canonical(actualClaims);
  return Object.freeze({ mode, matched, driftKind: matched ? null : 'scientific_conclusion_drift', wordingIgnored: true });
}

function classifyDrift(drifts = []) {
  if (drifts.length === 0) return 'compatible';
  if (drifts.some((item) => contract.scientificallyMaterialKinds.includes(item.kind) || item.scientificallyMaterial === true)) return 'scientifically_material';
  if (drifts.some((item) => item.kind === 'unknown' || item.classification === 'unknown')) return 'unknown';
  if (drifts.every((item) => item.expected === true)) return 'expected';
  return 'compatible';
}

function buildDriftReport({
  replayCaseId,
  sourceDigest,
  targetDigest,
  contextDrifts = [],
  artifactComparisons = [],
} = {}) {
  const artifactDrifts = artifactComparisons
    .filter((item) => item?.matched === false)
    .map((item) => ({ kind: item.driftKind || 'unknown', artifactId: item.artifactId || null }));
  const drifts = [...contextDrifts, ...artifactDrifts];
  const report = {
    reproducibilityLabVersion: REPRODUCIBILITY_LAB_VERSION,
    replayCaseId: replayCaseId || null,
    sourceDigest: sourceDigest || null,
    targetDigest: targetDigest || null,
    classification: classifyDrift(drifts),
    reviewRequired: classifyDrift(drifts) === 'scientifically_material' || classifyDrift(drifts) === 'unknown',
    contextDrifts,
    artifactComparisons,
  };
  return Object.freeze({ ...report, reportHash: digest(report) });
}

module.exports = {
  REPRODUCIBILITY_LAB_VERSION,
  contract,
  validateReplayCorpus,
  compareArtifact,
  classifyDrift,
  buildDriftReport,
};

'use strict';

const crypto = require('crypto');
const contract = require('./g0/scientific-accuracy.json');

const SCIENTIFIC_ACCURACY_VERSION = 1;

function canonical(value) {
  if (value === null || typeof value !== 'object') return JSON.stringify(value);
  if (Array.isArray(value)) return `[${value.map(canonical).join(',')}]`;
  return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${canonical(value[key])}`).join(',')}}`;
}

function digest(value) {
  return crypto.createHash('sha256').update(canonical(value)).digest('hex');
}

function finding(code, severity, detail = {}) {
  return Object.freeze({ code, severity, ...detail });
}

function classifyScientificChange(changedFields = []) {
  const scientific = changedFields.filter((field) => contract.scientificDesignFields.includes(field));
  const engineering = changedFields.filter((field) => contract.engineeringRepairFields.includes(field));
  const unknown = changedFields.filter((field) => !scientific.includes(field) && !engineering.includes(field));
  const classification = scientific.length
    ? 'scientific_design_change'
    : unknown.length ? 'requires_review'
      : engineering.length ? 'engineering_repair'
        : 'no_change';
  return Object.freeze({
    classification,
    confirmationRequired: classification === 'scientific_design_change' || classification === 'requires_review',
    scientific,
    engineering,
    unknown,
  });
}

function validateScientificAccuracyContract() {
  const issues = [];
  const outcomes = Object.entries(contract.outcomes || {});
  if (contract.schemaVersion !== 1 || contract.contractVersion !== SCIENTIFIC_ACCURACY_VERSION) issues.push('contract_version_invalid');
  if (outcomes.length < 7) issues.push('outcomes_incomplete');
  for (const [id, value] of outcomes) {
    if (!['passed', 'needs_review', 'blocked'].includes(value.truthStatus)) issues.push(`truth_status_invalid:${id}`);
    if (typeof value.blocking !== 'boolean') issues.push(`blocking_invalid:${id}`);
  }
  if (!contract.prohibited.includes('retry_until_significant')) issues.push('scientific_integrity_prohibition_missing');
  return Object.freeze({ ok: issues.length === 0, issues: Object.freeze(issues) });
}

function evaluateScientificAccuracy({
  method = null,
  assumptions = [],
  evidenceLevel = null,
  sampleMatch = null,
  statistics = null,
  contradictoryEvidence = [],
  power = null,
} = {}) {
  const findings = [];
  if (!method?.id || method.applicable === false) findings.push(finding('method_not_applicable', 'error'));
  if (!method?.design || !method?.contrast) findings.push(finding('design_information_missing', 'error'));

  for (const assumption of assumptions || []) {
    if (assumption?.satisfied === false) findings.push(finding('method_assumption_violated', 'error', { assumptionId: assumption.id || null }));
    else if (assumption?.satisfied == null) findings.push(finding('method_assumption_unverified', 'warning', { assumptionId: assumption?.id || null }));
  }
  if (sampleMatch !== true) findings.push(finding('sample_identity_mismatch_or_unverified', 'error'));
  if (!contract.evidenceLevels.includes(evidenceLevel)) findings.push(finding('evidence_level_invalid', 'error'));

  const adjustedP = statistics?.adjustedP;
  const alpha = statistics?.alpha ?? 0.05;
  if (
    !statistics
    || !Number.isFinite(adjustedP)
    || adjustedP < 0
    || adjustedP > 1
    || !Number.isFinite(alpha)
    || alpha <= 0
    || alpha >= 1
    || !statistics.multipleTesting
  ) findings.push(finding('statistical_semantics_invalid', 'error'));
  if (!statistics?.unit) findings.push(finding('unit_missing', 'error'));
  if (!['increase', 'decrease', 'none', 'mixed'].includes(statistics?.direction)) findings.push(finding('direction_invalid', 'error'));
  if (power?.status === 'low') findings.push(finding('low_statistical_power', 'warning'));
  if ((contradictoryEvidence || []).length > 0) findings.push(finding('contradictory_evidence', 'warning', { count: contradictoryEvidence.length }));

  let outcome = 'valid';
  if (findings.some((item) => item.code === 'design_information_missing')) outcome = 'missing_design';
  else if (findings.some((item) => item.code === 'method_not_applicable' || item.code === 'method_assumption_violated')) outcome = 'assumption_violation';
  else if (findings.some((item) => item.severity === 'error')) outcome = 'invalid_statistics';
  else if (findings.some((item) => item.code === 'contradictory_evidence')) outcome = 'contradictory';
  else if (findings.some((item) => item.code === 'low_statistical_power')) outcome = 'low_power';
  else if (adjustedP >= alpha) outcome = 'not_significant';

  const policy = contract.outcomes[outcome];
  const evidence = {
    scientificAccuracyVersion: SCIENTIFIC_ACCURACY_VERSION,
    method: method ? { id: method.id || null, version: method.version || null, design: method.design || null, contrast: method.contrast || null } : null,
    evidenceLevel,
    statistics: statistics ? {
      adjustedP,
      alpha,
      multipleTesting: statistics.multipleTesting || null,
      unit: statistics.unit || null,
      direction: statistics.direction || null,
    } : null,
    outcome,
    status: policy.truthStatus === 'passed' ? 'valid' : policy.truthStatus === 'needs_review' ? 'degraded' : 'blocked',
    truthStatus: policy.truthStatus,
    blocking: policy.blocking,
    findings,
    conclusionCode: outcome === 'not_significant' ? 'no_supported_effect_at_declared_threshold' : outcome,
  };
  return Object.freeze({ ...evidence, evidenceHash: digest(evidence) });
}

module.exports = {
  SCIENTIFIC_ACCURACY_VERSION,
  contract,
  classifyScientificChange,
  validateScientificAccuracyContract,
  evaluateScientificAccuracy,
};

'use strict';

const crypto = require('crypto');
const truthContract = require('./g0/truth-lattice.json');

const TRUTH_PROJECTION_VERSION = 1;
const TERMINAL = new Set(['completed', 'blocked', 'failed', 'cancelled', 'needs_review', 'recovery_required']);

function canonical(value) {
  if (value === null || typeof value !== 'object') return JSON.stringify(value);
  if (Array.isArray(value)) return `[${value.map(canonical).join(',')}]`;
  return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${canonical(value[key])}`).join(',')}}`;
}

function digest(value) {
  return crypto.createHash('sha256').update(canonical(value)).digest('hex');
}

function parse(value, fallback = {}) {
  if (!value) return fallback;
  if (typeof value === 'object') return value;
  try { return JSON.parse(value); } catch { return fallback; }
}

function layer(id, status, authority, evidence = []) {
  return Object.freeze({ id, status, authority, evidence: [...new Set(evidence.filter(Boolean))].sort() });
}

function normalizeJobStatus(value) {
  const status = String(value || 'pending').toLowerCase();
  return ['pending', 'queued'].includes(status) ? 'pending'
    : status === 'running' ? 'running'
      : ['completed', 'failed', 'cancelled'].includes(status) ? status
        : 'blocked';
}

function buildTruthProjection({ job = {}, deliveryManifest = null, scientificValidation = null, presentation = null } = {}) {
  const result = parse(job.result_json || job.result, {});
  const jobStatus = normalizeJobStatus(job.status);
  const recovery = String(job.error || '').includes('recovery_required');
  const artifact = result.artifactTruth || null;
  const scientific = scientificValidation || result.scientificValidation || null;
  const delivery = deliveryManifest || result.deliveryManifest || null;
  const jobLayer = layer('job', recovery ? 'recovery_required' : jobStatus, 'tool_jobs', [job.id]);
  const artifactStatus = artifact
    ? artifact.blocking === true || artifact.status === 'blocked' ? 'blocked'
      : artifact.status === 'degraded' ? 'needs_review'
        : artifact.status === 'valid' ? 'completed' : 'pending'
    : 'pending';
  const artifactLayer = layer('artifact', artifactStatus, 'artifactTruth', [
    result.executionProvenance?.provenanceHash,
    result.artifactManifest?.manifestHash,
  ]);
  const scientificState = scientific?.truthStatus || scientific?.status;
  const scientificStatus = scientific
    ? scientific.blocking === true || scientificState === 'blocked' ? 'blocked'
      : ['valid', 'not_applicable', 'passed'].includes(scientificState) ? 'completed'
        : ['degraded', 'needs_review'].includes(scientificState) ? 'needs_review' : 'pending'
    : artifactStatus === 'completed' ? 'pending' : artifactStatus;
  const scientificLayer = layer('scientific', scientificStatus, 'validatorEvidence', [
    scientific?.evidenceHash,
  ]);
  const deliveryStatus = delivery
    ? delivery.status === 'valid' ? 'completed'
      : delivery.status === 'degraded' ? 'needs_review' : 'blocked'
    : 'pending';
  const deliveryLayer = layer('delivery', deliveryStatus, 'DeliveryManifest', [
    delivery?.manifestHash,
  ]);
  const upstream = [jobLayer, artifactLayer, scientificLayer, deliveryLayer];
  const precedence = truthContract.precedence;
  const aggregate = precedence.find((status) => upstream.some((item) => item.status === status)) || 'pending';
  const completionAllowed = upstream.every((item) => item.status === 'completed');
  const publicStatus = completionAllowed ? 'completed' : aggregate;
  const presentationLayer = layer(
    'presentation',
    presentation?.status === 'completed' && !completionAllowed ? publicStatus : publicStatus,
    'derived_projection_only',
    [presentation?.evidenceHash],
  );
  const projection = {
    truthProjectionVersion: TRUTH_PROJECTION_VERSION,
    subject: { jobId: job.id || null, toolId: job.tool_id || job.toolId || null },
    status: publicStatus,
    completionAllowed,
    terminal: TERMINAL.has(publicStatus),
    layers: [...upstream, presentationLayer],
    invalidationFingerprint: result.invalidationFingerprint || null,
    derivedAt: job.updated_at || job.completed_at || job.created_at || null,
  };
  return Object.freeze({ ...projection, projectionHash: digest(projection) });
}

function evaluateInvalidation({ recorded, current } = {}) {
  if (!recorded || !current) return Object.freeze({ status: 'unknown', invalidated: true, changed: ['fingerprint_missing'] });
  const fields = truthContract.invalidationFingerprintFields;
  const changed = fields.filter((field) => canonical(recorded[field] ?? null) !== canonical(current[field] ?? null));
  return Object.freeze({
    status: changed.length ? 'invalidated' : 'current',
    invalidated: changed.length > 0,
    changed,
    recordedDigest: digest(recorded),
    currentDigest: digest(current),
  });
}

function reduceTruthEvents(events = []) {
  const unique = new Map();
  for (const event of events) {
    if (!event?.eventId) continue;
    const existing = unique.get(event.eventId);
    if (!existing || canonical(existing) === canonical(event)) unique.set(event.eventId, event);
  }
  const ordered = [...unique.values()].sort((a, b) =>
    Number(a.sequence || 0) - Number(b.sequence || 0)
    || String(a.occurredAt || '').localeCompare(String(b.occurredAt || ''))
    || String(a.eventId).localeCompare(String(b.eventId))
  );
  return Object.freeze({
    events: Object.freeze(ordered.map((item) => Object.freeze({ ...item }))),
    eventDigest: digest(ordered),
    duplicateCount: Math.max(0, events.length - unique.size),
  });
}

module.exports = {
  TRUTH_PROJECTION_VERSION,
  buildTruthProjection,
  evaluateInvalidation,
  reduceTruthEvents,
};

'use strict';

const { execFileSync } = require('child_process');
const { randomUUID } = require('crypto');
const fs = require('fs');
const path = require('path');
const pathModule = path;
// BLOCK-92 Wave C-9 — git 运行时探测/诊断脱敏/pathspec 校验/porcelain 解析/
// unified-diff 反演已外迁 ./git-adapter/runtime.js（纯搬运零行为变化）；
// 本文件保留 createGitAdapter 工厂闭包（同 tools-executor 先例）。
const {
  GIT_ADAPTER_VERSION,
  MINIMUM_GIT_VERSION,
  FORBIDDEN_PATHSPECS,
  GitAdapterError,
  redactGitDiagnostic,
  parseGitVersion,
  baseEnv,
  resetGitRuntimeCache,
  detectGitRuntime,
  assertSafePathspecs,
  assertSafeRef,
  parsePorcelainZ,
