      const child = execFile(
        command[0],
        command.slice(1),
        {
          encoding: 'utf8',
          cwd: remoteSsh ? undefined : (fs.existsSync(resolvedWorkTree) ? resolvedWorkTree : undefined),
          env: { ...env, ...(runOptions.env || {}) },
          timeout: runOptions.timeout || 60000,
          maxBuffer: 32 * 1024 * 1024,
          killSignal: 'SIGKILL',
        },
        (error, stdout, stderr) => {
