          resolve({
            ok: false,
            command: args[0] || null,
            stdout: stdout ? String(stdout) : '',
            stderr: redactGitDiagnostic(stderr ? String(stderr) : (error && error.message) || '', scope),
            status: typeof error.code === 'number' ? error.code : null,
