  return {
    gitAdapterVersion: GIT_ADAPTER_VERSION,
    gitDir: resolvedGitDir,
    workTree: resolvedWorkTree,
    gitBin,

    run,

    /** 该 gitDir 是否已经是一个仓库。 */
