      };
      return {
        gitAdapterVersion: GIT_ADAPTER_VERSION,
        initialized: fs.existsSync(path.join(resolvedGitDir, 'HEAD')),
        // getter：读到才 fork。属性访问语义与原来完全一致，
        // 既有读取方（result-changeset-service.js:242、test/git-adapter.test.mjs:208/:344）无需改动。
