        scope: 'paths',
        paths: safe,
        ...parsed,
        dirty: parsed.entries.some((entry) => !entry.untracked),
        hasUntracked: parsed.entries.some((entry) => entry.untracked),
        hasConflict: parsed.entries.some((entry) => entry.conflicted),
