const https = require('https');
const logger = require('../logger');

const EMBEDDING_DIM = 1024;
const EMBEDDING_MODEL = 'text-embedding-v3';
const MAX_CONTENT_LEN = 1500;

// 断点1：ai-usage 经注入式 helper 获取，斩断对 petri-server/helpers/ai-usage 的反向 require
const aiUsageHelper = require('../ai-usage-helper');
function getRecordAiUsage() {
  return aiUsageHelper.recordAiUsage;
}

class DashScopeEmbedProvider {
  get name() {
    return 'dashscope';
  }
  get capabilities() {
    return 'embedding';
  }

  /**
   * 文本向量化。
   * @param {string} apiKey - DashScope API key
   * @param {string[]} texts - 待向量化的文本数组
   * @param {object} telemetry - {userId?, conversationId?, kind?}
   * @returns {Promise<Float32Array[] | null>} - 向量数组，失败返回 null
   */
  async embed(apiKey, texts, _telemetry, options) {
    if (!apiKey) {
      logger.warn('[dashscope] API key 未配置，embedding 跳过');
      return { error: 'no_api_key', message: 'DashScope API key 未配置' };
    }
    if (!Array.isArray(texts) || texts.length === 0) return [];

    const _t = _telemetry || {};
    const _start = Date.now();
    const recordAiUsage = getRecordAiUsage();

    const truncated = texts.map((t) => (t || '').slice(0, MAX_CONTENT_LEN));
    const _approxTokens = truncated.reduce((s, t) => s + Math.ceil((t || '').length * 0.7), 0);
    const model = (options && options.model) || EMBEDDING_MODEL;
    const body = JSON.stringify({
      model,
      input: { texts: truncated },
      ...((options && options.parameters) || {}),
    });

    return new Promise((resolve) => {
      let buf = '';
      const r = https.request(
        {
          hostname: 'dashscope.aliyuncs.com',
          port: 443,
          path: '/api/v1/services/embeddings/text-embedding/text-embedding',
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            Authorization: 'Bearer ' + apiKey,
            'Content-Length': Buffer.byteLength(body),
          },
          agent: false,
          timeout: 30000,
        },
        (res) => {
          res.setEncoding('utf8');
          res.on('data', (c) => (buf += c));
          res.on('end', () => {
            try {
              if (res.statusCode !== 200) {
                logger.warn(`[dashscope] HTTP ${res.statusCode}: ${buf.slice(0, 200)}`);
                recordAiUsage({
                  userId: _t.userId,
                  kind: _t.kind || 'embedding',
                  model,
                  promptTokens: _approxTokens,
                  latencyMs: Date.now() - _start,
                  errorCode: 'http_' + res.statusCode,
                  conversationId: _t.conversationId,
                });
                resolve({ error: 'http_error', message: `HTTP ${res.statusCode}`, status: res.statusCode });
                return;
              }
              const j = JSON.parse(buf);
              const arr = j?.output?.embeddings;
              if (!Array.isArray(arr)) {
                resolve({ error: 'api_error', message: 'Embedding 响应缺少向量数据' });
                return;
              }
              arr.sort((a, b) => (a.text_index || 0) - (b.text_index || 0));
              const out = arr.map((e) => Float32Array.from(e.embedding));
              recordAiUsage({
                userId: _t.userId,
                kind: _t.kind || 'embedding',
                model,
                promptTokens: _approxTokens,
                latencyMs: Date.now() - _start,
                conversationId: _t.conversationId,
              });
              resolve(out);
            } catch (e) {
              logger.warn(`[dashscope] parse err: ${e.message}`);
              resolve({ error: 'parse_error', message: e.message });
            }
          });
          res.on('error', (e) => resolve({ error: 'res_error', message: e.message }));
        }
      );
      r.on('error', (e) => {
        logger.warn(`[dashscope] req err: ${e.message}`);
        resolve({ error: 'req_error', message: e.message });
      });
      r.on('timeout', () => {
        try {
          r.destroy();
        } catch {}
        resolve({ error: 'timeout', message: 'Embedding 请求超时' });
      });
      r.write(body);
      r.end();
    });
  }

  /**
   * 健康检查（简单调一次 embedding 测试）。
   */
  async healthCheck(apiKey) {
    if (!apiKey) return false;
    const result = await this.embed(apiKey, ['test'], {});
    return result !== null && Array.isArray(result) && result.length > 0;
  }
}

module.exports = { DashScopeEmbedProvider, EMBEDDING_DIM, EMBEDDING_MODEL };

/**
 * OpenAI-compatible provider transport, with DeepSeek-compatible defaults.
 */

const http = require('http');
const https = require('https');
const aiUsageHelper = require('../ai-usage-helper');
const { stripLeakedToolMarkup, createDsmlStreamGuard } = require('./dsml-guard');

const DEFAULT_BASE_URL = 'https://api.deepseek.com';
const CHAT_PATH = '/chat/completions';

function getRecordAiUsage() {
  return aiUsageHelper.recordAiUsage;
}

function resolveEndpoint(baseUrl, pathname, defaultBaseUrl = DEFAULT_BASE_URL) {
  const url = new URL(baseUrl || defaultBaseUrl);
  const prefix = url.pathname.replace(/\/$/, '');
  url.pathname = `${prefix}${pathname}`;
  return url;
}

function buildRequestOptions(endpoint, apiKey, data, accept) {
  const headers = {
    'Content-Type': 'application/json',
    Accept: accept,
    'Content-Length': Buffer.byteLength(data),
  };
  if (apiKey) headers.Authorization = 'Bearer ' + apiKey;
  return {
    protocol: endpoint.protocol,
    hostname: endpoint.hostname,
    port: endpoint.port || undefined,
    path: endpoint.pathname + endpoint.search,
    method: 'POST',
    headers,
    agent: false,
    timeout: 90000,
  };
}

function requestModule(endpoint) {
  return endpoint.protocol === 'http:' ? http : https;
}

// BLOCK-95 B3 — cache 字段提取（兼容原始/归一 usage 形状）
const { extractCacheFields: cacheFieldsOf } = require('./protocol-usage');

function usageArgs(telemetry, body, startedAt, usage, errorCode) {
  const u = usage || {};
  return {
    userId: telemetry.userId,
    kind: telemetry.kind || 'agent_iter',
    model: (body && body.model) || 'deepseek-chat',
    // BLOCK-79 P1 — 供应商归因（网关注入 telemetry.provider）
    provider: (telemetry && telemetry.provider) || null,
    promptTokens: u.prompt_tokens || 0,
    completionTokens: u.completion_tokens || 0,
    // BLOCK-95 B3 — prompt cache 字段落库（原恒 0 断链，见 protocol-usage.extractCacheFields）
    ...(cacheFieldsOf(usage)),
    latencyMs: Date.now() - startedAt,
    errorCode: errorCode || null,
    conversationId: telemetry.conversationId,
  };
}

function appendToolCall(target, delta) {
  const index = Number.isInteger(delta.index) ? delta.index : 0;
  if (!target[index]) {
    target[index] = { id: '', type: 'function', function: { name: '', arguments: '' } };
  }
  const current = target[index];
  if (delta.id) current.id += delta.id;
  if (delta.type) current.type = delta.type;
  if (delta.function) {
    if (delta.function.name) current.function.name += delta.function.name;
    if (delta.function.arguments) current.function.arguments += delta.function.arguments;
  }
}

// BLOCK-82: 思考段字段归一——reasoning_content 优先（DeepSeek 系），
// 缺失时兜底 reasoning（sensenova 等网关的字段名）；只在 OpenAI 兼容解析入口做，
// 下游事件/记录面保持 reasoning_content 单一形状。
function pickReasoningText(source) {
  if (!source || typeof source !== 'object') return undefined;
  if (typeof source.reasoning_content === 'string' && source.reasoning_content) return source.reasoning_content;
  if (typeof source.reasoning === 'string' && source.reasoning) return source.reasoning;
  return undefined;
}

class DeepSeekProvider {
  constructor(options = {}) {
    this.providerName = options.name || 'deepseek';
    this.defaultBaseUrl = options.defaultBaseUrl || DEFAULT_BASE_URL;
    this.requiresApiKey = options.requiresApiKey !== false;
    this.providerLabel = options.label || this.providerName;
  }

  get name() {
    return this.providerName;
  }

  get capabilities() {
    return 'chat';
  }

  get supportsStreaming() {
    return true;
  }

  async listModels(apiKey, options) {
    if (this.requiresApiKey && !apiKey) {
      return { ok: false, models: [], message: `${this.providerLabel} API key 未配置` };
    }

    return new Promise((resolve) => {
      const endpoint = resolveEndpoint(options && options.baseUrl, '/models', this.defaultBaseUrl);
      const headers = { Accept: 'application/json' };
      if (apiKey) headers.Authorization = 'Bearer ' + apiKey;
      let settled = false;
      let buffer = '';
      const finish = (result) => {
        if (settled) return;
        settled = true;
        resolve(result);
      };
      const req = requestModule(endpoint).request(
        {
          protocol: endpoint.protocol,
          hostname: endpoint.hostname,
          port: endpoint.port || undefined,
          path: endpoint.pathname + endpoint.search,
          method: 'GET',
          headers,
          agent: false,
          timeout: 10000,
        },
        (res) => {
          res.setEncoding('utf8');
          res.on('data', (chunk) => {
            buffer += chunk;
            if (buffer.length > 2 * 1024 * 1024) {
              req.destroy();
              finish({ ok: false, models: [], message: '模型列表响应过大' });
            }
          });
          res.on('end', () => {
            if (settled) return;
            let parsed;
            try {
              parsed = buffer ? JSON.parse(buffer) : {};
            } catch {
              finish({ ok: false, models: [], message: `模型列表响应不是有效 JSON（HTTP ${res.statusCode || 0}）` });
              return;
            }
            if ((res.statusCode || 0) < 200 || (res.statusCode || 0) >= 300) {
              const remoteMessage = parsed && parsed.error && parsed.error.message;
              finish({
                ok: false,
                models: [],
                message: remoteMessage || `获取模型列表失败（HTTP ${res.statusCode || 0}）`,
              });
              return;
            }
            const rows = Array.isArray(parsed.data)
              ? parsed.data
              : Array.isArray(parsed.models)
                ? parsed.models
                : [];
            const models = [...new Set(rows
              .map((row) => typeof row === 'string' ? row : row && (row.id || row.name || row.model))
              .map((value) => String(value || '').trim())
              .filter(Boolean))]
              .sort((a, b) => a.localeCompare(b));
            finish(models.length > 0
              ? { ok: true, models, message: `已获取 ${models.length} 个模型` }
              : { ok: false, models: [], message: '接口未返回可用模型' });
          });
          res.on('error', (error) => {
            finish({ ok: false, models: [], message: error.message || '读取模型列表失败' });
          });
        }
      );
      req.on('error', (error) => {
        finish({ ok: false, models: [], message: error.message || '模型列表请求失败' });
      });
      req.on('timeout', () => {
        req.destroy();
        finish({ ok: false, models: [], message: '获取模型列表超时' });
      });
      req.end();
    });
  }

  async chat(apiKey, body, telemetry, options) {
    if (this.requiresApiKey && !apiKey) {
      return { error: 'no_api_key', message: `${this.providerLabel} API key 未配置` };
    }

    const t = telemetry || {};
    const startedAt = Date.now();
    const recordAiUsage = getRecordAiUsage();
    let data;
    try {
      data = JSON.stringify(body);
      if (typeof data !== 'string') throw new Error('request body is not serializable');
    } catch (error) {
      recordAiUsage(usageArgs(t, body, startedAt, null, 'serialize_error'));
      return { error: 'serialize_error', message: error.message };
    }

    return new Promise((resolve) => {
      const endpoint = resolveEndpoint(options && options.baseUrl, CHAT_PATH, this.defaultBaseUrl);
      let settled = false;
      let buffer = '';
      const finish = (result, errorCode, usage) => {
        if (settled) return;
        settled = true;
        recordAiUsage(usageArgs(t, body, startedAt, usage, errorCode));
        resolve(result);
      };
      const req = requestModule(endpoint).request(
        buildRequestOptions(endpoint, apiKey, data, 'application/json'),
        (res) => {
          res.setEncoding('utf8');
          res.on('data', (chunk) => (buffer += chunk));
          res.on('end', () => {
            try {
              const parsed = JSON.parse(buffer);
              if (res.statusCode < 200 || res.statusCode >= 300) {
                const message = (parsed.error && parsed.error.message) || `HTTP ${res.statusCode}`;
                finish({ error: 'http_error', message, status: res.statusCode }, 'http_error');
                return;
              }
              // DSML 泄漏防护（非流式路径）：assistant 正文中的内部工具调用
              // 标记永不合法，返回前清洗，避免泄漏进持久化历史。
              const envelopeChoice = parsed && parsed.choices && parsed.choices[0];
              if (envelopeChoice && envelopeChoice.message && typeof envelopeChoice.message.content === 'string') {
                envelopeChoice.message.content = stripLeakedToolMarkup(envelopeChoice.message.content);
              }
              finish(parsed, parsed && parsed.error ? 'api_error' : null, parsed && parsed.usage);
            } catch (error) {
              const status = Number(res.statusCode);
              finish({
                error: status >= 400 ? 'http_error' : 'parse_error',
                message: status >= 400 ? (buffer || `HTTP ${status}`) : error.message,
                ...(Number.isFinite(status) ? { status } : {}),
              }, status >= 400 ? 'http_error' : 'parse_error');
            }
          });
          res.on('error', (error) =>
            finish({ error: 'res_error', message: error.message }, 'res_error')
          );
        }
      );
      req.on('error', (error) =>
        finish({ error: 'req_error', message: error.message }, 'req_error')
      );
      req.on('timeout', () => {
        req.destroy();
        finish({ error: 'timeout', message: '请求超时' }, 'timeout');
      });
      req.write(data);
      req.end();
    });
  }

  /**
   * Streams normalized events and resolves to an OpenAI-compatible aggregate response.
   * onEvent receives content_delta, tool_call_delta, usage, done, or error.
   */
  async chatStream(apiKey, body, telemetry, onEvent, options) {
    if (this.requiresApiKey && !apiKey) {
      return { error: 'no_api_key', message: `${this.providerLabel} API key 未配置` };
    }

    const t = telemetry || {};
    const startedAt = Date.now();
    const recordAiUsage = getRecordAiUsage();
    const profileProvider = options && options.profile && options.profile.provider;
    const streamBody = {
      ...(body || {}),
      stream: true,
      // `stream_options` is a DeepSeek/OpenAI extension and is rejected by
      // several otherwise-compatible gateways. Keep usage streaming for the
      // native DeepSeek path, but use the portable OpenAI-compatible shape for
      // custom channels, Ollama, LM Studio, and vLLM.
      ...(!profileProvider || profileProvider === 'deepseek'
        ? { stream_options: { include_usage: true } }
        : {}),
    };
    let data;
    try {
      data = JSON.stringify(streamBody);
    } catch (error) {
      recordAiUsage(usageArgs(t, body, startedAt, null, 'serialize_error'));
      return { error: 'serialize_error', message: error.message };
    }

    return new Promise((resolve) => {
      const endpoint = resolveEndpoint(options && options.baseUrl, CHAT_PATH, this.defaultBaseUrl);
      const contentParts = [];
      // DSML 泄漏防护：模型偶发把内部工具调用标记当正文输出（UI-265 实机观察），
      // 增量与最终聚合都在 provider 层清洗，保证 SSE 与持久化历史一致干净。
      const dsmlGuard = createDsmlStreamGuard();
      const toolCalls = [];
      let usage = null;
      let finishReason = null;
      let sseBuffer = '';
      let errorBuffer = '';
      let sawChoice = false;
      let settled = false;
      let req; // eslint-disable-line prefer-const

      const emit = (event) => {
        try {
          if (typeof onEvent === 'function') onEvent(event);
        } catch {}
      };
      const finish = (result, errorCode) => {
        if (settled) return;
        settled = true;
        if (options && options.signal) options.signal.removeEventListener('abort', abortRequest);
        recordAiUsage(usageArgs(t, body, startedAt, usage, errorCode));
        resolve(result);
      };
      const fail = (code, message, details) => {
        const result = { error: code, message, ...(details || {}) };
        emit({ type: 'error', error: code, message });
        finish(result, code);
      };
      const complete = () => {
        if (!sawChoice) {
          fail('parse_error', '模型响应未包含可识别的 choices');
          return;
        }
        const flushedTail = dsmlGuard.flush();
        if (flushedTail) contentParts.push(flushedTail);
        emit({ type: 'done', usage });
        finish({
          choices: [
            {
              finish_reason: finishReason,
              message: {
                role: 'assistant',
                content: contentParts.join(''),
                ...(toolCalls.length ? { tool_calls: toolCalls.filter(Boolean) } : {}),
              },
            },
          ],
          usage: usage || undefined,
        });
      };
      const processPayload = (payload) => {
        if (payload === '[DONE]') {
          complete();
          return;
        }
        let parsed;
        try {
          parsed = JSON.parse(payload);
        } catch (error) {
          fail('parse_error', `无效的 SSE 数据: ${error.message}`);
          req.destroy();
          return;
        }
        if (parsed.error) {
          fail('api_error', parsed.error.message || String(parsed.error));
          req.destroy();
          return;
        }
        if (parsed.usage) {
          usage = parsed.usage;
          emit({ type: 'usage', usage });
        }
        const choice = parsed.choices && parsed.choices[0];
        if (!choice) return;
        sawChoice = true;
        if (choice.finish_reason) finishReason = choice.finish_reason;

        // Some OpenAI-compatible gateways advertise streaming but return a
        // regular chat-completions JSON envelope. Accept that shape instead
        // of silently completing with an empty assistant message.
        if (choice.message && typeof choice.message === 'object') {
          const message = choice.message;
          // UI-272: 非流式信封也可能携带思考内容（reasoning_content；BLOCK-82: sensenova 系为 reasoning，归一兜底）
          const envelopeReasoning = pickReasoningText(message);
          if (envelopeReasoning) {
            emit({ type: 'reasoning_delta', content: envelopeReasoning });
          }
          if (typeof message.content === 'string' && message.content) {
            const cleanContent = stripLeakedToolMarkup(message.content);
            if (cleanContent) {
              contentParts.push(cleanContent);
              emit({ type: 'content_delta', content: cleanContent });
            }
          }
          if (Array.isArray(message.tool_calls)) {
            for (let index = 0; index < message.tool_calls.length; index += 1) {
              const toolCall = { ...message.tool_calls[index], index };
              appendToolCall(toolCalls, toolCall);
              emit({ type: 'tool_call_delta', delta: toolCall });
            }
          }
          complete();
          return;
        }
        const delta = choice.delta || {};
        // UI-272: 模型思考过程（DeepSeek reasoning_content）— 此前被直接丢弃，
        // 导致会话内无法回看工具调用之间的衔接思路
        // BLOCK-82: sensenova 系思考段字段名为 reasoning，归一兜底（reasoning_content 优先）
        const reasoningText = pickReasoningText(delta);
        if (reasoningText) {
          emit({ type: 'reasoning_delta', content: reasoningText });
        }
        if (typeof delta.content === 'string' && delta.content) {
          const cleanDelta = dsmlGuard.push(delta.content);
          if (cleanDelta) {
            contentParts.push(cleanDelta);
            emit({ type: 'content_delta', content: cleanDelta });
          }
        }
        if (Array.isArray(delta.tool_calls)) {
          for (const toolDelta of delta.tool_calls) {
            appendToolCall(toolCalls, toolDelta);
            emit({ type: 'tool_call_delta', delta: toolDelta });
          }
        }
      };
      const processFrames = () => {
        sseBuffer = sseBuffer.replace(/\r\n/g, '\n');
        let boundary;
        while ((boundary = sseBuffer.indexOf('\n\n')) !== -1 && !settled) {
          const frame = sseBuffer.slice(0, boundary);
          sseBuffer = sseBuffer.slice(boundary + 2);
          const payload = frame
            .split('\n')
            .filter((line) => line.startsWith('data:'))
            .map((line) => line.slice(5).trimStart())
            .join('\n');
          if (payload) processPayload(payload);
        }
      };
      const abortRequest = () => {
        if (settled) return;
        req.destroy();
        fail('aborted', '请求已取消');
      };

      req = requestModule(endpoint).request(
        buildRequestOptions(endpoint, apiKey, data, 'text/event-stream'),
        (res) => {
          res.setEncoding('utf8');
          const isSuccess = res.statusCode >= 200 && res.statusCode < 300;
          res.on('data', (chunk) => {
            if (isSuccess) {
              sseBuffer += chunk;
              processFrames();
            } else {
              errorBuffer += chunk;
            }
          });
          res.on('end', () => {
            if (settled) return;
            if (!isSuccess) {
              let message = errorBuffer || `HTTP ${res.statusCode}`;
              try {
                const parsed = JSON.parse(errorBuffer);
                message = (parsed.error && parsed.error.message) || message;
              } catch {}
              fail('http_error', message, { status: res.statusCode });
              return;
            }
            processFrames();
            if (!settled && sseBuffer.trim()) {
              const payload = sseBuffer.replace(/^data:\s*/, '').trim();
              if (payload) processPayload(payload);
            }
            if (!settled) complete();
          });
          res.on('error', (error) => fail('res_error', error.message));
        }
      );
      req.on('error', (error) => {
        if (!settled) fail('req_error', error.message);
      });
      req.on('timeout', () => {
        req.destroy();
        fail('timeout', '请求超时');
      });
      if (options && options.signal) {
        if (options.signal.aborted) return abortRequest();
        options.signal.addEventListener('abort', abortRequest, { once: true });
      }
      req.write(data);
      req.end();
    });
  }

  async healthCheck(apiKey, options) {
    if (this.requiresApiKey && !apiKey) return false;
    return new Promise((resolve) => {
      const endpoint = resolveEndpoint(options && options.baseUrl, '/models', this.defaultBaseUrl);
      const headers = {};
      if (apiKey) headers.Authorization = 'Bearer ' + apiKey;
      const req = requestModule(endpoint).request(
        {
          protocol: endpoint.protocol,
          hostname: endpoint.hostname,
          port: endpoint.port || undefined,
          path: endpoint.pathname + endpoint.search,
          method: 'GET',
          headers,
          agent: false,
          timeout: 10000,
        },
        (res) => resolve(res.statusCode === 200)
      );
      req.on('error', () => resolve(false));
      req.on('timeout', () => {
        req.destroy();
        resolve(false);
      });
      req.end();
    });
  }

  async embed(apiKey, texts, telemetry, options) {
    if (this.requiresApiKey && !apiKey) return null;
    if (!Array.isArray(texts) || texts.length === 0) return [];
    const body = {
      ...((options && options.parameters) || {}),
      model: (options && options.model) || '',
      input: texts,
    };
    const data = JSON.stringify(body);
    const endpoint = resolveEndpoint(options && options.baseUrl, '/embeddings', this.defaultBaseUrl);
    const startedAt = Date.now();
    const recordAiUsage = getRecordAiUsage();
    return new Promise((resolve) => {
      let buffer = '';
      const req = requestModule(endpoint).request(
        buildRequestOptions(endpoint, apiKey, data, 'application/json'),
        (res) => {
          res.setEncoding('utf8');
          res.on('data', (chunk) => (buffer += chunk));
          res.on('end', () => {
            try {
              const parsed = JSON.parse(buffer);
              if (res.statusCode < 200 || res.statusCode >= 300 || !Array.isArray(parsed.data)) {
                resolve(null);
                return;
              }
              const rows = [...parsed.data].sort((a, b) => (a.index || 0) - (b.index || 0));
              const vectors = rows.map((row) => Float32Array.from(row.embedding || []));
              const usage = parsed.usage || {};
              recordAiUsage({
                userId: telemetry && telemetry.userId,
                kind: (telemetry && telemetry.kind) || 'embedding',
                model: body.model,
                promptTokens: usage.prompt_tokens || usage.total_tokens || 0,
                latencyMs: Date.now() - startedAt,
                conversationId: telemetry && telemetry.conversationId,
              });
              resolve(vectors);
            } catch {
              resolve(null);
            }
          });
          res.on('error', () => resolve(null));
        }
      );
      req.on('error', () => resolve(null));
      req.on('timeout', () => {
        req.destroy();
        resolve(null);
      });
      req.write(data);
      req.end();
    });
  }
}

module.exports = { DeepSeekProvider, OpenAICompatibleProvider: DeepSeekProvider };

/**
 * llm-providers/dsml-guard.js — 模型内部工具调用标记泄漏清洗。
 *
 * 背景（UI-265 实机观察 + 复验）：DeepSeek 偶发把内部 DSML 工具调用标记
 * 当正文 content 输出，而不是走 tool_calls 通道，导致标记原文泄漏到聊天区
 * 与持久化历史。实测出现过两种变体：
 *   - 半角：`<|DSML|>` / `<|/DSML|>`
 *   - 全角：`｜｜DSML｜｜`（U+FF5C FULLWIDTH VERTICAL LINE，tokenizer 变体）
 * 这类标记永远不是合法的用户可见内容，因此在 provider 层单点清洗：
 *
 * - stripLeakedToolMarkup(text)：一次性清洗——从首个 DSML 标记起整段截断
 *   （泄漏块之后不会恢复合法正文，整块都是模型内部格式噪音）。
 * - createDsmlStreamGuard()：流式增量清洗器——标记可能跨 chunk 分裂，扣留
 *   尾部可能是标记前缀的字符待下一个 chunk 判定；一旦确认命中泄漏，后续
 *   所有 delta 全部吞掉（poisoned）。flush() 在流结束时只放安全正文。
 */

// 标记形态：开/闭边界字符（< 或 ｜）+ 1~2 个竖线（| 或 ｜）+ 可选 / + DSML
// + 1~2 个竖线 + 尾边界（> 或 ｜）。覆盖 <|DSML|>、<|/DSML|>、｜｜DSML｜｜、
// <｜DSML｜> 等半角/全角混合变体。
const DSML_MARK_RE = /(?:<|[｜])[|｜]{1,2}\/?DSML[|｜]{1,2}(?:>|[｜])/;
// 标记可能由这些字符组成（用于识别「部分前缀」）
const DSML_MARK_CHARS = /[<|｜>/DSML]/;
// 最长形态 ｜｜/DSML｜｜ = 10 字符；扣留上限取 11，保证「部分前缀」永不构成完整标记
const HOLD_BACK_MAX = 11;

function stripLeakedToolMarkup(text) {
  const s = String(text == null ? '' : text);
  const match = s.search(DSML_MARK_RE);
  return match === -1 ? s : s.slice(0, match);
}

// 尾部若为某个标记的前缀（如 "<"、"<|"、"｜"、"｜｜DS"、"｜｜/DSML｜"），返回该后缀长度。
// 只有以 < 或 ｜ 开头的候选才可能是标记前缀，避免误扣 "DSL"、"SM" 等普通字母组合。
function trailingPartialMarkLength(s) {
  let keep = 0;
  const start = Math.max(0, s.length - HOLD_BACK_MAX);
  for (let i = s.length - 1; i >= start; i -= 1) {
    if (!DSML_MARK_CHARS.test(s[i])) break;
    keep = s.length - i;
  }
  if (!keep) return 0;
  const tail = s.slice(s.length - keep);
  return /^[<｜]/.test(tail) ? keep : 0;
}

function createDsmlStreamGuard() {
  let pending = '';
  let poisoned = false;
  return {
    push(delta) {
      if (poisoned) return '';
      pending += String(delta == null ? '' : delta);
      const hit = pending.search(DSML_MARK_RE);
      if (hit !== -1) {
        const head = pending.slice(0, hit);
        pending = '';
        poisoned = true;
        return head;
      }
      const keep = trailingPartialMarkLength(pending);
      const head = keep ? pending.slice(0, pending.length - keep) : pending;
      pending = keep ? pending.slice(pending.length - keep) : '';
      return head;
    },
    flush() {
      if (poisoned) return '';
      const rest = pending;
      pending = '';
      const hit = rest.search(DSML_MARK_RE);
      if (hit !== -1) {
        poisoned = true;
        return rest.slice(0, hit);
      }
      const keep = trailingPartialMarkLength(rest);
      return keep ? rest.slice(0, rest.length - keep) : rest;
    },
  };
}

module.exports = { stripLeakedToolMarkup, createDsmlStreamGuard };

/**
 * llm-providers/io-transcript.js — 模型 I/O 信息流落盘（BLOCK-37 P1）。
 *
 * 覆盖「所有模型调用」的请求与响应完整原文持久化：
 * - 按会话分文件追加 JSONL（<dataDir>/llm-transcripts/<conversationId>.jsonl），
 *   无 conversationId 的调用归 unattributed.jsonl。
 * - 每条记录 = 一次真实模型交互：请求 messages 全量 + 响应聚合全文
 *   （content / reasoning_content / tool_calls / finish_reason / usage）+ delta 帧样本。
 * - 截断纪律（诚实标记）：单条硬上限 8MB——超限先丢 delta 帧（保聚合响应完整），
 *   再折叠 request.messages 中段（保首尾 + messagesTruncated 计数），
 *   仍超限则逐条截断单条 message 内容。
 * - 文件轮转：活跃文件超 64MB 先改名留存再开新文件。
 * - 本模块绝不抛错：写失败静默（调用方 fire-and-forget），不影响模型调用主链路。
 */

const fs = require('fs');
const path = require('path');

const MAX_RECORD_BYTES_DEFAULT = 8 * 1024 * 1024; // 8MB
const MAX_FRAMES_DEFAULT = 2000;
const MAX_FILE_BYTES_DEFAULT = 64 * 1024 * 1024; // 64MB
const UNATTRIBUTED = 'unattributed';
const MESSAGE_KEEP_HEAD = 4;
const MESSAGE_KEEP_TAIL = 16;
const MESSAGE_CONTENT_CLIP = 2000;

function safeStringify(value) {
  const seen = new WeakSet();
  try {
    return JSON.stringify(value, (key, val) => {
      if (typeof val === 'object' && val !== null) {
        if (seen.has(val)) return '[Circular]';
        seen.add(val);
      }
      return val;
    });
  } catch {
    return 'null';
  }
}

function safeIdPart(value) {
  const raw = String(value || '');
  // 路径安全：只留字母数字、连字符、下划线；空值归 unattributed
  const cleaned = raw.replace(/[^A-Za-z0-9_-]+/g, '_').replace(/^_+|_+$/g, '');
  return cleaned || UNATTRIBUTED;
}

function stampId(now = () => new Date()) {
  return `rt_${now().getTime()}_${Math.random().toString(36).slice(2, 8)}`;
}

/** 从 provider 聚合结果中提取响应全文（诚实保留 reasoning / tool_calls / usage）。 */
function normalizeResponse(result) {
  if (!result || typeof result !== 'object') return null;
  if (result.error) return null;
  const choice = result.choices && result.choices[0];
  const message = choice && choice.message ? choice.message : {};
  return {
    content: typeof message.content === 'string' ? message.content : '',
    // BLOCK-82: reasoning_content 优先，缺失时兜底 reasoning（sensenova 系字段名）
    reasoningContent: pickReasoningContent(message),
    toolCalls: Array.isArray(message.tool_calls) ? message.tool_calls : undefined,
    finishReason: choice ? choice.finish_reason : undefined,
    usage: result.usage && typeof result.usage === 'object' ? result.usage : undefined,
  };
}

// BLOCK-82: reasoning_content 优先（DeepSeek 系）；非字符串时兜底 reasoning（sensenova 系）。
// reasoning_content 为字符串（含空串）时行为与既有契约完全一致。
function pickReasoningContent(message) {
  if (typeof message.reasoning_content === 'string') return message.reasoning_content;
  if (typeof message.reasoning === 'string') return message.reasoning;
  return undefined;
}

function clipMessageForBudget(message) {
  const next = { ...message };
  if (typeof next.content === 'string' && next.content.length > MESSAGE_CONTENT_CLIP) {
    next.content = `${next.content.slice(0, MESSAGE_CONTENT_CLIP)}…[BLOCK-37 截断]`;
  }
  if (Array.isArray(next.content)) {
    // 多模态 content 数组：文本片段逐段截断
    next.content = next.content.map((part) => {
      if (part && typeof part === 'object' && typeof part.text === 'string' && part.text.length > MESSAGE_CONTENT_CLIP) {
        return { ...part, text: `${part.text.slice(0, MESSAGE_CONTENT_CLIP)}…[BLOCK-37 截断]` };
      }
      return part;
    });
  }
  if (typeof next.reasoning_content === 'string' && next.reasoning_content.length > MESSAGE_CONTENT_CLIP) {
    next.reasoning_content = `${next.reasoning_content.slice(0, MESSAGE_CONTENT_CLIP)}…[BLOCK-37 截断]`;
  }
  return next;
}

/** 三级截断（仅在超限时逐级触发）：丢帧 → 折叠 messages 中段 → 逐条截断内容。全部诚实标记。 */
function applyTruncation(record, maxBytes) {
  const size = () => safeStringify(record).length;
  if (size() <= maxBytes) return record;
  record.truncated = true;

  // 第一级：丢 delta 帧（聚合响应保持完整）
  if (record.frames && record.frames.length > 0) {
    record.frames = [];
    record.framesTruncated = true;
  }
  if (size() <= maxBytes) return record;

  // 第二级：折叠 request.messages 中段（保首尾）
  const messages = Array.isArray(record.request && record.request.messages)
    ? record.request.messages
    : null;
  if (messages && messages.length > MESSAGE_KEEP_HEAD + MESSAGE_KEEP_TAIL) {
    const head = messages.slice(0, MESSAGE_KEEP_HEAD);
    const tail = messages.slice(-MESSAGE_KEEP_TAIL);
    const dropped = messages.length - MESSAGE_KEEP_HEAD - MESSAGE_KEEP_TAIL;
    record.request.messages = [
      ...head,
      { role: 'system', content: `[BLOCK-37 截断：中段 ${dropped} 条消息未存盘]` },
      ...tail,
    ];
    record.messagesTruncated = dropped;
  }
  if (size() <= maxBytes) return record;

  // 第三级：逐条截断 message 内容（含已保留的首尾与响应聚合）
  if (messages) {
    record.request.messages = record.request.messages.map(clipMessageForBudget);
  }
  if (record.response) {
    if (typeof record.response.content === 'string' && record.response.content.length > MESSAGE_CONTENT_CLIP) {
      record.response.content = `${record.response.content.slice(0, MESSAGE_CONTENT_CLIP)}…[BLOCK-37 截断]`;
    }
    if (typeof record.response.reasoningContent === 'string' && record.response.reasoningContent.length > MESSAGE_CONTENT_CLIP) {
      record.response.reasoningContent = `${record.response.reasoningContent.slice(0, MESSAGE_CONTENT_CLIP)}…[BLOCK-37 截断]`;
    }
  }
  return record;
}

/**
 * 创建落盘 sink。
 * @param {object} options
 * @param {string} options.dataDir 本地数据根目录（PETRI_LOCAL_DATA_DIR 同源解析）
 * @param {number} [options.maxRecordBytes] 单条记录上限（默认 8MB）
 * @param {number} [options.maxFrames] 单条记录保留的 delta 帧上限（默认 2000）
 * @param {number} [options.maxFileBytes] 单文件轮转阈值（默认 64MB）
 * @param {object} [options.fs] 可注入 fs（测试用）
 * @param {() => Date} [options.now] 可注入时钟（测试用）
 */
function createIoTranscriptSink(options = {}) {
  const dataDir = String(options.dataDir || '');
  if (!dataDir) throw new Error('createIoTranscriptSink requires dataDir');
  const dir = path.join(dataDir, 'llm-transcripts');
  const maxRecordBytes = Number.isFinite(options.maxRecordBytes) ? options.maxRecordBytes : MAX_RECORD_BYTES_DEFAULT;
  const maxFrames = Number.isFinite(options.maxFrames) ? options.maxFrames : MAX_FRAMES_DEFAULT;
  const maxFileBytes = Number.isFinite(options.maxFileBytes) ? options.maxFileBytes : MAX_FILE_BYTES_DEFAULT;
  const fsMod = options.fs || fs;
  const now = options.now || (() => new Date());

  function ensureDir() {
    try {
      fsMod.mkdirSync(dir, { recursive: true });
    } catch {
      // 已存在或不可创建——后续 appendFileSync 自会失败并被吞掉
    }
  }

  function targetFile(conversationId) {
    return path.join(dir, `${safeIdPart(conversationId)}.jsonl`);
  }

  /** 活跃文件超阈值时轮转留存（重命名后开新文件）。 */
  function rotateIfNeeded(file) {
    try {
      const stat = fsMod.statSync(file);
      if (stat && stat.size >= maxFileBytes) {
        fsMod.renameSync(file, `${file.slice(0, -6)}.${now().getTime()}.jsonl`);
      }
    } catch {
      // 文件不存在等情况直接忽略
    }
  }

  /**
   * 记录一次模型交互。fire-and-forget：同步段吞错，不向调用方抛任何异常。
   * @param {object} entry
   * @param {object} [entry.telemetry] {userId?, conversationId?, kind?, traceId?}
   * @param {object} [entry.requestBody] OpenAI 兼容请求体（messages 全量）
   * @param {object} [entry.result] provider 聚合结果（成功或 {error}）
   * @param {Array} [entry.frames] 流式 delta 帧样本（已按 maxFrames 截取）
   * @param {boolean} [entry.framesTruncated] 帧是否超上限被截
   * @param {string} [entry.provider] provider 名
   * @param {string} [entry.profileId] 模型配置 id
   * @param {string} [entry.role] gateway 角色（chat/agent/vision…）
   * @param {number} [entry.attemptIndex] fallback 尝试序号（0 = 首选）
   * @param {number} [entry.durationMs] 调用耗时
   */
  function record(entry) {
    try {
      const src = entry || {};
      const telemetry = src.telemetry && typeof src.telemetry === 'object' ? src.telemetry : {};
      const response = normalizeResponse(src.result);
      const record_ = {
        id: stampId(now),
        ts: now().toISOString(),
        conversationId: telemetry.conversationId || null,
        kind: telemetry.kind || 'chat',
        traceId: telemetry.traceId || undefined,
        userId: telemetry.userId || undefined,
        role: src.role || 'chat',
        provider: src.provider || undefined,
        profileId: src.profileId || undefined,
        attemptIndex: Number.isFinite(src.attemptIndex) ? src.attemptIndex : 0,
        model: src.model || undefined,
        durationMs: Number.isFinite(src.durationMs) ? src.durationMs : undefined,
        request: {
          messages: Array.isArray(src.requestBody && src.requestBody.messages) ? src.requestBody.messages : [],
          params: safeStringify({ ...(src.requestBody || {}), messages: undefined }),
        },
        response,
        error: src.result && src.result.error
          ? (typeof src.result.error === 'string' ? src.result.error : String(src.result.error.code || src.result.error.type || 'api_error'))
          : null,
        frames: Array.isArray(src.frames) ? src.frames : undefined,
        framesCount: Number.isFinite(src.framesCount) ? src.framesCount : (Array.isArray(src.frames) ? src.frames.length : 0),
        framesTruncated: src.framesTruncated === true,
        truncated: false,
        messagesTruncated: 0,
      };

      const sized = applyTruncation(record_, maxRecordBytes);
      const line = safeStringify(sized);
      if (!line || line === 'null') return;

      ensureDir();
      const file = targetFile(sized.conversationId);
      rotateIfNeeded(file);
      fsMod.appendFileSync(file, `${line}\n`);
    } catch {
      // 落盘永不影响主链路
    }
  }

  return { record, dir };
}

/**
 * BLOCK-38 P1 — 取证读取：会话信息流末条（中断续跑前的「中断前最后状态」摘要来源）。
 * 只读；活跃文件为空/不存在时回退最近的轮转留存文件（<id>.<ts>.jsonl 按名字取最新）。
 * 任何失败返回 null（诚实空态），绝不抛错。
 */
function readLastRecord(conversationId, options = {}) {
  try {
    const dataDir = String(options.dataDir || '');
    if (!dataDir) return null;
    const fsMod = options.fs || fs;
    const dir = path.join(dataDir, 'llm-transcripts');
    const stem = safeIdPart(conversationId);
    const active = path.join(dir, `${stem}.jsonl`);

    let lines = [];
    try {
      lines = fsMod.readFileSync(active, 'utf8').split('\n').filter((line) => line.trim());
    } catch {}
    if (lines.length === 0) {
      // 回退轮转留存文件：按文件名取时间戳后缀最大的
      try {
        const archived = fsMod
          .readdirSync(dir)
          .filter((name) => name.startsWith(`${stem}.`) && name.endsWith('.jsonl'))
          .sort();
        for (let i = archived.length - 1; i >= 0 && lines.length === 0; i--) {
          try {
            lines = fsMod
              .readFileSync(path.join(dir, archived[i]), 'utf8')
              .split('\n')
              .filter((line) => line.trim());
          } catch {}
        }
      } catch {}
    }
    if (lines.length === 0) return null;
    const parsed = JSON.parse(lines[lines.length - 1]);
    return parsed && typeof parsed === 'object' ? parsed : null;
  } catch {
    return null;
  }
}

module.exports = {
  createIoTranscriptSink,
  normalizeResponse,
  applyTruncation,
  readLastRecord,
  safeIdPart,
  UNATTRIBUTED,
  MAX_RECORD_BYTES_DEFAULT,
  MAX_FRAMES_DEFAULT,
};

/**
 * Model Gateway — the single provider dispatch boundary.
 *
 * Callers choose a task role (or an explicit profile id). The gateway resolves
 * the ModelProfile, validates capabilities, obtains the referenced credential,
 * and invokes one registered transport adapter. It never owns conversation,
 * tool-job, or artifact state.
 */

const { normalizeModelConfig, resolveModelProfile } = require('./model-profile');
// BLOCK-81 P1 — 思考档位：中性档位→上游参数的单一映射点 + 去参重试判据
const { thinkingParamsFor, isUnknownParameterError } = require('./thinking-level');

function gatewayError(error, message, details) {
  return { error, message, ...(details || {}) };
}

const RETRYABLE_ERROR_CODES = new Set([
  'network_error',
  'req_error',
  'res_error',
  'timeout',
  'parse_error',
  'http_error',
  'api_error',
]);

function errorCode(result) {
  if (!result || !result.error) return '';
  if (typeof result.error === 'string') return result.error;
  return String(result.error.code || result.error.type || 'api_error');
}

function isRetryableProviderError(result) {
  const code = errorCode(result);
  if (!code || code === 'aborted' || code === 'no_api_key' || code === 'serialize_error') return false;
  const status = Number(result && (result.status || result.statusCode));
  if (Number.isFinite(status)) {
    return status === 408 || status === 409 || status === 425 || status === 429 || status >= 500;
  }
  return RETRYABLE_ERROR_CODES.has(code);
}

function routingReason(result) {
  const status = Number(result && (result.status || result.statusCode));
  return {
    code: errorCode(result) || 'provider_failure',
    ...(Number.isFinite(status) ? { status } : {}),
  };
}

// BLOCK-37 — 单条 transcript 保留的 delta 帧样本上限（超限诚实计数，聚合响应不受影响）
const MAX_TRANSCRIPT_FRAMES = 2000;

class ModelGateway {
  constructor({ getSettings, getCredential, getProvider, recordRouting, recordTranscript }) {
    if (typeof getSettings !== 'function') throw new Error('ModelGateway requires getSettings');
    if (typeof getCredential !== 'function') throw new Error('ModelGateway requires getCredential');
    if (typeof getProvider !== 'function') throw new Error('ModelGateway requires getProvider');
    this._getSettings = getSettings;
    this._getCredential = getCredential;
    this._getProvider = getProvider;
    this._recordRouting = typeof recordRouting === 'function' ? recordRouting : () => {};
    // BLOCK-37 — 模型 I/O 信息流落盘（fire-and-forget，绝不影响调用主链路）
    this._recordTranscript = typeof recordTranscript === 'function' ? recordTranscript : null;
  }

  /** BLOCK-37 — 一次 provider 交互的 transcript 组装与提交（含 fallback 的每次 attempt 独立记录）。 */
  _emitTranscript({
    role, attemptIndex, profile, requestBody, telemetry, result, frames, framesCount, framesTruncated, durationMs,
  }) {
    if (!this._recordTranscript) return;
    try {
      this._recordTranscript({
        telemetry: telemetry || {},
        requestBody: requestBody || {},
        result,
        frames,
        framesCount,
        framesTruncated,
        provider: profile.provider,
        profileId: profile.id,
        role,
        attemptIndex,
        model: requestBody && requestBody.model,
        durationMs,
      });
    } catch {
      // transcript 永不影响调用主链路
    }
  }

  getConfig() {
    return normalizeModelConfig(this._getSettings() || {});
  }

  resolve(role, profileId) {
    return resolveModelProfile(this.getConfig(), role, profileId);
  }

  _prepare(role, profileId, apiKeyOverride) {
    const resolved = this.resolve(role, profileId);
    if (resolved.error) return resolved;
    const profile = resolved.profile;
    const provider = this._getProvider(profile.provider);
    if (!provider) {
      return gatewayError(
        'provider_not_registered',
        `模型 Provider 未注册: ${profile.provider}`,
        { profileId: profile.id, provider: profile.provider }
      );
    }
    const apiKey = apiKeyOverride || this._getCredential(profile.credentialRef, profile) || '';
    return { profile, provider, apiKey };
  }

  _fallbackProfileIds(role, primaryId) {
    const config = this.getConfig();
    if (!config.fallbackEnabled) return [];
    const candidates = config.fallbackBindings[role] || [];
    return candidates.filter((id) => id !== primaryId);
  }

  _withRouting(result, role, profileId, fallbackFrom, reason) {
    if (!result || typeof result !== 'object') return result;
    return {
      ...result,
      modelRouting: {
        role,
        profileId,
        ...(fallbackFrom ? { fallbackFrom, fallbackReason: reason } : {}),
      },
    };
  }

  _recordFallback(role, fromProfileId, toProfileId, reason) {
    const event = { role, fromProfileId, toProfileId, reason };
    try {
      this._recordRouting({ type: 'model_fallback', ...event });
    } catch {}
    return event;
  }

  async chat({ role = 'chat', profileId, modelOverride, body, telemetry, onEvent, signal, apiKeyOverride, fallbackWhen, disableFallback, thinkingLevel, __dropThinking = false } = {}) {
    const primary = this._prepare(role, profileId, apiKeyOverride);
    if (primary.error) return primary;
    // BLOCK-56 P1 — 任务级降级续跑的任务传 disableFallback: true：
    // 降级任务已是「单级降级」的最后一搏，请求级 fallback 必须关闭，防止 A→B→C 连环。
    const attempts = disableFallback
      ? [primary.profile.id]
      : [primary.profile.id, ...this._fallbackProfileIds(role, primary.profile.id)];
    let lastResult;
    let previousProfileId;
    let previousReason;
    for (let index = 0; index < attempts.length; index += 1) {
      const prepared = index === 0 ? primary : this._prepare(role, attempts[index]);
      if (prepared.error) {
        lastResult = prepared;
        continue;
      }
      const { profile, provider, apiKey } = prepared;
      // BLOCK-79 P1 — 供应商归因注入：遥测携带「本次实际 attempt」的 provider，
      // 经 provider 层 usageArgs 落 ai_usage.provider（fallback 换档即换归因）。
      if (telemetry && typeof telemetry === 'object' && !telemetry.provider) {
        telemetry.provider = profile.provider;
      }
      const canStream = typeof onEvent === 'function' && typeof provider.chatStream === 'function';
      if (typeof provider.chat !== 'function' && !canStream) {
        lastResult = gatewayError('provider_method_missing', `Provider ${profile.provider} 不支持 chat`, {
          profileId: profile.id,
        });
        continue;
      }
      if (index > 0 && typeof onEvent === 'function') {
        const fallback = this._recordFallback(role, previousProfileId, profile.id, previousReason);
        onEvent({
          type: 'model_fallback',
          ...fallback,
        });
      } else if (index > 0) {
        this._recordFallback(role, previousProfileId, profile.id, previousReason);
      }
      // BLOCK-81 P1 / D3 双保险①：仅当 profile 声明 capabilities.reasoning 且档位
      // 非 standard 时才发思考参数（thinkingParamsFor 内部门控）→ 未启用渠道零行为变化。
      // __dropThinking：去参重试时置真，跳过注入。
      const thinkingParams = __dropThinking
        ? {}
        : thinkingParamsFor({
          level: thinkingLevel,
          protocol: profile.protocol,
          capabilities: profile.capabilities,
        });
      const requestBody = {
        ...(profile.parameters || {}),
        ...thinkingParams,
        ...(body || {}),
        model: index === 0 && modelOverride ? modelOverride : profile.model,
      };
      const options = { baseUrl: profile.baseUrl, signal, profile };
      let emittedOutput = false;
      let result;
      // BLOCK-37 — 流式分支 tee delta 帧（上限内保留样本，超限诚实计数）
      const transcriptFrames = [];
      let framesOverflow = 0;
      const startedAt = Date.now();
      if (canStream) {
        result = await provider.chatStream(apiKey, requestBody, telemetry || {}, (event) => {
          if (event && (event.type === 'content_delta' || event.type === 'tool_call_delta')) emittedOutput = true;
          // Hold a failed attempt's terminal error until the gateway decides
          // whether it will switch. Output and successful events remain live.
          if (!event || event.type !== 'error') {
            if (event && transcriptFrames.length < MAX_TRANSCRIPT_FRAMES) transcriptFrames.push(event);
            else if (event) framesOverflow += 1;
            onEvent(event);
          }
        }, options);
      } else {
        result = await provider.chat(apiKey, requestBody, telemetry || {}, options);
      }
      this._emitTranscript({
        role,
        attemptIndex: index,
        profile,
        requestBody,
        telemetry,
        result,
        frames: transcriptFrames.length > 0 ? transcriptFrames : undefined,
        framesCount: transcriptFrames.length + framesOverflow,
        framesTruncated: framesOverflow > 0,
        durationMs: Date.now() - startedAt,
      });
      // BLOCK-81 P1 / D3 双保险②：上游 400 且文案是「未知/非法参数」且本轮确实
      // 注入了思考参数 → **去参重试一次**（同 profile、禁用 fallback，优先于换档 fallback）。
      // 覆盖面：网关不认 reasoning_effort / thinking / enable_thinking 的严格实现。
      const status400 = Number(result && (result.status || result.statusCode)) === 400;
      if (
        !emittedOutput
        && Object.keys(thinkingParams).length > 0
        && status400
        && isUnknownParameterError(result && (result.message || result.error))
      ) {
        const stripped = await this.chat({
          role,
          profileId: profile.id,
          modelOverride,
          body,
          telemetry,
          onEvent,
          signal,
          apiKeyOverride,
          fallbackWhen,
          disableFallback: true,
          __dropThinking: true,
        });
        return this._withRouting(stripped, role, profile.id, index > 0 ? previousProfileId : undefined, previousReason);
      }
      let resultFallbackReason = null;
      if (!emittedOutput && typeof fallbackWhen === 'function') {
        try {
          resultFallbackReason = fallbackWhen(result) || null;
        } catch {}
      }
      const canFallback = !emittedOutput && (
        isRetryableProviderError(result) || resultFallbackReason
      ) && index < attempts.length - 1;
      if (canFallback) {
        previousProfileId = profile.id;
        previousReason = resultFallbackReason || routingReason(result);
        lastResult = result;
        continue;
      }
      if (typeof onEvent === 'function' && result && result.error) {
        onEvent({ type: 'error', error: errorCode(result), message: result.message });
      } else if (typeof onEvent === 'function' && result && !result.error && typeof provider.chatStream !== 'function') {
        const content = result.choices && result.choices[0] && result.choices[0].message
          ? result.choices[0].message.content || ''
          : '';
        if (content) onEvent({ type: 'content_delta', content });
        onEvent({ type: 'done', usage: result.usage });
      }
      return this._withRouting(result, role, profile.id, index > 0 ? previousProfileId : undefined, previousReason);
    }
    return lastResult;
  }

  async vision({ profileId, body, telemetry, apiKeyOverride, onEvent } = {}) {
    const primary = this._prepare('vision', profileId, apiKeyOverride);
    if (primary.error) return primary;
    const attempts = [primary.profile.id, ...this._fallbackProfileIds('vision', primary.profile.id)];
    let previousProfileId;
    let previousReason;
    let lastResult;
    for (let index = 0; index < attempts.length; index += 1) {
      const prepared = index === 0 ? primary : this._prepare('vision', attempts[index]);
      if (prepared.error) {
        lastResult = prepared;
        continue;
      }
      const { profile, provider, apiKey } = prepared;
      if (typeof provider.chat !== 'function') {
        lastResult = gatewayError('provider_method_missing', `Provider ${profile.provider} 不支持 vision`, {
          profileId: profile.id,
        });
        continue;
      }
      if (index > 0) {
        const fallback = this._recordFallback('vision', previousProfileId, profile.id, previousReason);
        if (typeof onEvent === 'function') onEvent({ type: 'model_fallback', ...fallback });
      }
      const visionBody = { ...(body || {}), model: profile.model };
      const startedAt = Date.now();
      const result = await provider.chat(
        apiKey,
        visionBody,
        telemetry || {},
        { baseUrl: profile.baseUrl, profile }
      );
      this._emitTranscript({
        role: 'vision',
        attemptIndex: index,
        profile,
        requestBody: visionBody,
        telemetry,
        result,
        durationMs: Date.now() - startedAt,
      });
      if (isRetryableProviderError(result) && index < attempts.length - 1) {
        previousProfileId = profile.id;
        previousReason = routingReason(result);
        lastResult = result;
        continue;
      }
      return this._withRouting(result, 'vision', profile.id, index > 0 ? previousProfileId : undefined, previousReason);
    }
    return lastResult;
  }

  async embed({ profileId, texts, telemetry, apiKeyOverride, onEvent } = {}) {
    const primary = this._prepare('embedding', profileId, apiKeyOverride);
    if (primary.error) return primary;
    const attempts = [primary.profile.id, ...this._fallbackProfileIds('embedding', primary.profile.id)];
    let previousProfileId;
    let previousReason;
    let lastResult;
    for (let index = 0; index < attempts.length; index += 1) {
      const prepared = index === 0 ? primary : this._prepare('embedding', attempts[index]);
      if (prepared.error) {
        lastResult = prepared;
        continue;
      }
      const { profile, provider, apiKey } = prepared;
      if (typeof provider.embed !== 'function') {
        lastResult = gatewayError('provider_method_missing', `Provider ${profile.provider} 不支持 embedding`, {
          profileId: profile.id,
        });
        continue;
      }
      if (index > 0) {
        const fallback = this._recordFallback('embedding', previousProfileId, profile.id, previousReason);
        if (typeof onEvent === 'function') onEvent({ type: 'model_fallback', ...fallback });
      }
      const result = await provider.embed(apiKey, texts, telemetry || {}, {
        baseUrl: profile.baseUrl,
        model: profile.model,
        parameters: profile.parameters,
        profile,
      });
      if (isRetryableProviderError(result) && index < attempts.length - 1) {
        previousProfileId = profile.id;
        previousReason = routingReason(result);
        lastResult = result;
        continue;
      }
      return result && result.error ? null : result;
    }
    return lastResult && lastResult.error ? null : lastResult;
  }

  async healthCheck(profileId, apiKeyOverride) {
    const config = this.getConfig();
    const profile = config.profiles.find((candidate) => candidate.id === profileId);
    if (!profile) return gatewayError('model_profile_not_found', `模型配置不存在: ${profileId}`);
    const provider = this._getProvider(profile.provider);
    if (!provider) return gatewayError('provider_not_registered', `模型 Provider 未注册: ${profile.provider}`);
    if (typeof provider.healthCheck !== 'function') {
      return gatewayError('health_check_unsupported', `Provider ${profile.provider} 不支持连通性测试`);
    }
    const apiKey = apiKeyOverride || this._getCredential(profile.credentialRef, profile) || '';
    const ok = await provider.healthCheck(apiKey, { baseUrl: profile.baseUrl, model: profile.model, profile });
    return { ok: !!ok, profileId: profile.id, provider: profile.provider, model: profile.model };
  }
}

module.exports = { ModelGateway, gatewayError, isRetryableProviderError };

/**
 * ModelProfile v1 contract.
 *
 * This module is intentionally transport-agnostic. It normalizes persisted
 * configuration and resolves task roles before the Model Gateway chooses a
 * provider adapter. Execution jobs and artifact persistence do not depend on
 * this contract.
 */

const MODEL_PROFILE_SCHEMA_VERSION = 1;

const MODEL_CAPABILITIES = Object.freeze([
  'chat',
  'streaming',
  'tools',
  'vision',
  'embedding',
  'reasoning',
]);

const MODEL_ROLES = Object.freeze([
  'chat',
  'agent',
  'planner',
  'vision',
  'embedding',
  'summary',
  'report',
  'explanation',
]);

const ROLE_CAPABILITY = Object.freeze({
  chat: 'chat',
  agent: 'tools',
  planner: 'chat',
  vision: 'vision',
  embedding: 'embedding',
  summary: 'chat',
  report: 'chat',
  explanation: 'chat',
});

const DEFAULT_MODEL_PROFILES = Object.freeze([
  Object.freeze({
    schemaVersion: MODEL_PROFILE_SCHEMA_VERSION,
    id: 'deepseek-chat',
    label: 'DeepSeek Chat',
    provider: 'deepseek',
    protocol: 'openai-compatible',
    model: 'deepseek-chat',
    credentialRef: 'provider:deepseek',
    capabilities: Object.freeze(['chat', 'streaming', 'tools']),
    roles: Object.freeze(['chat', 'agent', 'planner', 'summary', 'report', 'explanation']),
    parameters: Object.freeze({}),
  }),
  Object.freeze({
    schemaVersion: MODEL_PROFILE_SCHEMA_VERSION,
    id: 'dashscope-vision',
    label: 'Qwen VL Max',
    provider: 'dashscope-vision',
    protocol: 'dashscope-native',
    model: 'qwen-vl-max',
    credentialRef: 'provider:dashscope',
    capabilities: Object.freeze(['vision']),
    roles: Object.freeze(['vision']),
    parameters: Object.freeze({}),
  }),
  Object.freeze({
    schemaVersion: MODEL_PROFILE_SCHEMA_VERSION,
    id: 'dashscope-embedding',
    label: 'DashScope Embedding',
    provider: 'dashscope',
    protocol: 'dashscope-native',
    model: 'text-embedding-v3',
    credentialRef: 'provider:dashscope',
    capabilities: Object.freeze(['embedding']),
    roles: Object.freeze(['embedding']),
    parameters: Object.freeze({}),
  }),
]);

const DEFAULT_MODEL_ROLE_BINDINGS = Object.freeze({
  chat: 'deepseek-chat',
  agent: 'deepseek-chat',
  planner: 'deepseek-chat',
  vision: 'dashscope-vision',
  embedding: 'dashscope-embedding',
  summary: 'deepseek-chat',
  report: 'deepseek-chat',
  explanation: 'deepseek-chat',
});

function _cleanString(value) {
  return typeof value === 'string' && value.trim() ? value.trim() : undefined;
}

function _uniqueKnown(values, known) {
  if (!Array.isArray(values)) return [];
  return [...new Set(values.map(_cleanString).filter((value) => value && known.includes(value)))];
}

function inferProtocol(provider) {
  if (provider === 'dashscope' || provider === 'dashscope-vision') return 'dashscope-native';
  if (provider === 'anthropic') return 'anthropic-messages';
  return 'openai-compatible';
}

function inferCapabilities(provider) {
  if (provider === 'dashscope') return ['embedding'];
  if (provider === 'dashscope-vision') return ['vision'];
  return ['chat', 'streaming', 'tools'];
}

function normalizeModelProfile(input, index = 0) {
  if (!input || typeof input !== 'object') return null;
  const provider = _cleanString(input.provider) || 'deepseek';
  const model = _cleanString(input.model);
  if (!model) return null;
  const defaultModel = _cleanString(input.defaultModel) || model;
  const id = _cleanString(input.id) || `${provider}-${model}-${index + 1}`;
  const inferredCapabilities = inferCapabilities(provider);
  const capabilities = _uniqueKnown(input.capabilities, MODEL_CAPABILITIES);
  const roles = _uniqueKnown(input.roles, MODEL_ROLES);
  const parameters = input.parameters && typeof input.parameters === 'object' && !Array.isArray(input.parameters)
    ? { ...input.parameters }
    : {};
  const normalized = {
    schemaVersion: MODEL_PROFILE_SCHEMA_VERSION,
    id,
    label: _cleanString(input.label) || model,
    provider,
    protocol: _cleanString(input.protocol) || inferProtocol(provider),
    model,
    defaultModel,
    credentialRef: _cleanString(input.credentialRef) || `provider:${provider.replace(/-vision$/, '')}`,
    capabilities: capabilities.length ? capabilities : inferredCapabilities,
    roles,
    parameters,
  };
  const baseUrl = _cleanString(input.baseUrl);
  if (baseUrl) normalized.baseUrl = baseUrl.replace(/\/$/, '');
  const contextWindow = typeof input.contextWindow === 'number' && input.contextWindow > 0
    ? Math.round(input.contextWindow)
    : undefined;
  if (contextWindow !== undefined) normalized.contextWindow = contextWindow;
  return normalized;
}

function legacyPresetToProfile(preset, index = 0) {
  if (!preset || typeof preset !== 'object') return null;
  return normalizeModelProfile(
    {
      ...preset,
      protocol: preset.protocol || inferProtocol(preset.provider),
      capabilities: preset.capabilities || inferCapabilities(preset.provider),
    },
    index
  );
}

function normalizeModelProfiles(settings) {
  const source = settings && typeof settings === 'object' ? settings : {};
  const supplied = Array.isArray(source.model_profiles) ? source.model_profiles : [];
  const legacy = Array.isArray(source.chat_model_presets) ? source.chat_model_presets : [];
  const candidates = supplied.length ? supplied : legacy.map(legacyPresetToProfile);
  const profiles = [];
  const ids = new Set();
  for (const candidate of candidates) {
    const profile = normalizeModelProfile(candidate, profiles.length);
    if (!profile || ids.has(profile.id)) continue;
    profiles.push(profile);
    ids.add(profile.id);
  }
  // Defaults are a first-run / legacy migration aid only. Once a caller saves
  // explicit ModelProfiles, that list is authoritative: silently adding cloud
  // models would make the model-management UI lie about what is configured.
  if (supplied.length) return profiles;
  for (const defaultProfile of DEFAULT_MODEL_PROFILES) {
    const capability = defaultProfile.capabilities[0];
    if (!profiles.some((profile) => profile.capabilities.includes(capability))) {
      profiles.push(normalizeModelProfile(defaultProfile));
      ids.add(defaultProfile.id);
    }
  }
  return profiles;
}

function normalizeRoleBindings(settings, profiles) {
  const source = settings && typeof settings === 'object' ? settings : {};
  const supplied = source.model_role_bindings && typeof source.model_role_bindings === 'object'
    ? source.model_role_bindings
    : {};
  const activeChatId = _cleanString(source.active_chat_model_id);
  const byId = new Map(profiles.map((profile) => [profile.id, profile]));
  const bindings = {};
  for (const role of MODEL_ROLES) {
    const requested = _cleanString(supplied[role]) || (role === 'chat' ? activeChatId : undefined);
    const capability = ROLE_CAPABILITY[role];
    const requestedProfile = requested && byId.get(requested);
    // An explicit binding is configuration truth, even when invalid. Preserve
    // it so resolution returns a visible diagnostic instead of silently using
    // another model for the task.
    if (requested) {
      bindings[role] = requested;
      continue;
    }
    const defaultId = DEFAULT_MODEL_ROLE_BINDINGS[role];
    const defaultProfile = byId.get(defaultId);
    const fallback = defaultProfile && defaultProfile.capabilities.includes(capability)
      ? defaultProfile
      : profiles.find((profile) => profile.capabilities.includes(capability));
    if (fallback) bindings[role] = fallback.id;
  }
  return bindings;
}

function normalizeFallbackBindings(settings) {
  const source = settings && typeof settings === 'object' ? settings : {};
  const supplied = source.model_fallback_bindings && typeof source.model_fallback_bindings === 'object'
    ? source.model_fallback_bindings
    : {};
  const bindings = {};
  for (const role of MODEL_ROLES) {
    const values = Array.isArray(supplied[role]) ? supplied[role] : [];
    const ids = [...new Set(values.map(_cleanString).filter(Boolean))];
    if (ids.length) bindings[role] = ids;
  }
  return bindings;
}

function normalizeModelConfig(settings) {
  const profiles = normalizeModelProfiles(settings);
  const config = {
    schemaVersion: MODEL_PROFILE_SCHEMA_VERSION,
    profiles,
    roleBindings: normalizeRoleBindings(settings, profiles),
    fallbackEnabled: settings && settings.model_fallback_enabled === true,
    fallbackBindings: normalizeFallbackBindings(settings),
  };
  return { ...config, diagnostics: validateModelConfig(config) };
}

function validateModelConfig(config) {
  const diagnostics = [];
  const profiles = config && Array.isArray(config.profiles) ? config.profiles : [];
  const roleBindings = config && config.roleBindings && typeof config.roleBindings === 'object'
    ? config.roleBindings
    : {};
  const fallbackBindings = config && config.fallbackBindings && typeof config.fallbackBindings === 'object'
    ? config.fallbackBindings
    : {};
  const byId = new Map(profiles.map((profile) => [profile.id, profile]));

  for (const role of MODEL_ROLES) {
    const profileId = _cleanString(roleBindings[role]);
    if (!profileId) {
      diagnostics.push({
        code: 'model_role_unbound',
        role,
        message: `模型角色尚未绑定: ${role}`,
      });
      continue;
    }
    const profile = byId.get(profileId);
    if (!profile) {
      diagnostics.push({
        code: 'model_profile_not_found',
        role,
        profileId,
        message: `模型角色 ${role} 绑定了不存在的配置: ${profileId}`,
      });
      continue;
    }
    const capability = ROLE_CAPABILITY[role];
    if (!profile.capabilities.includes(capability)) {
      diagnostics.push({
        code: 'model_capability_mismatch',
        role,
        profileId,
        requiredCapability: capability,
        message: `模型 ${profile.label} 不支持 ${capability} 能力（任务角色: ${role}）`,
      });
    }

    for (const fallbackId of fallbackBindings[role] || []) {
      const fallback = byId.get(fallbackId);
      if (fallbackId === profileId) {
        diagnostics.push({
          code: 'model_fallback_matches_primary',
          role,
          profileId: fallbackId,
          message: `模型角色 ${role} 的 fallback 与主模型相同: ${fallbackId}`,
        });
      } else if (!fallback) {
        diagnostics.push({
          code: 'model_fallback_not_found',
          role,
          profileId: fallbackId,
          message: `模型角色 ${role} 的 fallback 不存在: ${fallbackId}`,
        });
      } else if (!fallback.capabilities.includes(capability)) {
        diagnostics.push({
          code: 'model_fallback_capability_mismatch',
          role,
          profileId: fallbackId,
          requiredCapability: capability,
          message: `Fallback 模型 ${fallback.label} 不支持 ${capability} 能力（任务角色: ${role}）`,
        });
      }
    }
  }
  return diagnostics;
}

function resolveModelProfile(config, role, requestedId) {
  if (!MODEL_ROLES.includes(role)) {
    return { error: 'unknown_model_role', message: `未知模型角色: ${role}` };
  }
  const profiles = config && Array.isArray(config.profiles) ? config.profiles : [];
  const id = _cleanString(requestedId) || (config && config.roleBindings && config.roleBindings[role]);
  const profile = profiles.find((candidate) => candidate.id === id);
  if (!profile) {
    return { error: 'model_profile_not_found', message: `模型配置不存在: ${id || role}` };
  }
  const required = ROLE_CAPABILITY[role];
  if (!profile.capabilities.includes(required)) {
    return {
      error: 'model_capability_mismatch',
      message: `模型 ${profile.label} 不支持 ${required} 能力（任务角色: ${role}）`,
      profile,
      requiredCapability: required,
    };
  }
  return { profile, requiredCapability: required };
}

module.exports = {
  MODEL_PROFILE_SCHEMA_VERSION,
  MODEL_CAPABILITIES,
  MODEL_ROLES,
  ROLE_CAPABILITY,
  DEFAULT_MODEL_PROFILES,
  DEFAULT_MODEL_ROLE_BINDINGS,
  inferProtocol,
  inferCapabilities,
  normalizeModelProfile,
  legacyPresetToProfile,
  normalizeFallbackBindings,
  normalizeModelConfig,
  validateModelConfig,
  resolveModelProfile,
};

/** SSE aggregators adapted from api-failover-proxy (MIT). */

const { normalizeUsage } = require('./protocol-usage');

function extractSseFrames(state, chunk) {
  state.buffer = (state.buffer + String(chunk || '')).replace(/\r\n/g, '\n');
  const frames = [];
  let index;
  while ((index = state.buffer.indexOf('\n\n')) !== -1) {
    const raw = state.buffer.slice(0, index);
    state.buffer = state.buffer.slice(index + 2);
    let eventType = 'data';
    const data = [];
    for (const line of raw.split('\n')) {
      if (line.startsWith('event:')) eventType = line.slice(6).trim();
      if (line.startsWith('data:')) data.push(line.slice(5).trimStart());
    }
    if (!data.length) continue;
    const payload = data.join('\n');
    if (payload === '[DONE]') frames.push({ done: true, type: eventType });
    else {
      try {
        frames.push({ type: eventType, json: JSON.parse(payload) });
      } catch {}
    }
  }
  return frames;
}

class OpenAIStreamAggregator {
  constructor(model) {
    this.model = model || '';
    this.state = { buffer: '' };
    this.toolCalls = [];
    this.result = {
      id: '',
      object: 'chat.completion',
      choices: [{ index: 0, message: { role: 'assistant', content: '' }, finish_reason: null }],
      usage: { prompt_tokens: 0, completion_tokens: 0, total_tokens: 0 },
    };
  }

  feed(chunk) {
    for (const frame of extractSseFrames(this.state, chunk)) {
      if (frame.done) continue;
      const json = frame.json;
      if (!this.result.id && json.id) this.result.id = json.id;
      if (!this.model && json.model) this.model = json.model;
      if (json.usage) {
        const usage = normalizeUsage(json.usage);
        this.result.usage.prompt_tokens = usage.input;
        this.result.usage.completion_tokens = usage.output;
        this.result.usage.cache_read_tokens = usage.cacheRead;
        this.result.usage.cache_creation_tokens = usage.cacheCreation;
      }
      const choice = json.choices && json.choices[0];
      if (!choice) continue;
      const delta = choice.delta || {};
      if (typeof delta.content === 'string') this.result.choices[0].message.content += delta.content;
      for (const toolDelta of delta.tool_calls || []) {
        const index = Number.isInteger(toolDelta.index) ? toolDelta.index : 0;
        if (!this.toolCalls[index]) {
          this.toolCalls[index] = { id: '', type: 'function', function: { name: '', arguments: '' } };
        }
        if (toolDelta.id) this.toolCalls[index].id += toolDelta.id;
        if (toolDelta.function && toolDelta.function.name) this.toolCalls[index].function.name += toolDelta.function.name;
        if (toolDelta.function && toolDelta.function.arguments) this.toolCalls[index].function.arguments += toolDelta.function.arguments;
      }
      if (choice.finish_reason) this.result.choices[0].finish_reason = choice.finish_reason;
    }
  }

  getResult() {
    this.result.model = this.model;
    if (this.toolCalls.length) this.result.choices[0].message.tool_calls = this.toolCalls.filter(Boolean);
    this.result.usage.total_tokens = this.result.usage.prompt_tokens + this.result.usage.completion_tokens;
    return this.result;
  }
}

class AnthropicStreamAggregator {
  constructor() {
    this.state = { buffer: '' };
    this.blocks = new Map();
    this.inputBuffers = new Map();
    this.result = {
      id: '', type: 'message', role: 'assistant', content: [], model: '',
      stop_reason: null, stop_sequence: null,
      usage: { input_tokens: 0, output_tokens: 0 },
    };
  }

  feed(chunk) {
    for (const frame of extractSseFrames(this.state, chunk)) {
      if (frame.done || !frame.json) continue;
      const json = frame.json;
      const type = json.type || frame.type;
      if (type === 'message_start') {
        const message = json.message || {};
        this.result.id = message.id || '';
        this.result.model = message.model || '';
        this._setUsage(message.usage);
      }
      if (type === 'content_block_start') {
        const block = { ...(json.content_block || {}) };
        if (block.type === 'text') block.text = block.text || '';
        if (block.type === 'tool_use') this.inputBuffers.set(json.index, '');
        this.blocks.set(json.index, block);
      }
      if (type === 'content_block_delta') {
        const block = this.blocks.get(json.index);
        const delta = json.delta || {};
        if (block && delta.type === 'text_delta') block.text += delta.text || '';
        if (block && delta.type === 'input_json_delta') {
          this.inputBuffers.set(json.index, (this.inputBuffers.get(json.index) || '') + (delta.partial_json || ''));
        }
      }
      if (type === 'content_block_stop') {
        const block = this.blocks.get(json.index);
        if (block) {
          if (block.type === 'tool_use') {
            try { block.input = JSON.parse(this.inputBuffers.get(json.index) || '{}'); } catch { block.input = {}; }
          }
          this.result.content.push(block);
          this.blocks.delete(json.index);
          this.inputBuffers.delete(json.index);
        }
      }
      if (type === 'message_delta') {
        const delta = json.delta || {};
        if (delta.stop_reason) this.result.stop_reason = delta.stop_reason;
        if (delta.stop_sequence !== undefined) this.result.stop_sequence = delta.stop_sequence;
        this._setUsage(json.usage);
      }
    }
  }

  _setUsage(raw) {
    if (!raw) return;
    const usage = normalizeUsage(raw);
    if (usage.input) this.result.usage.input_tokens = usage.input;
    if (usage.output) this.result.usage.output_tokens = usage.output;
    if (usage.cacheRead) this.result.usage.cache_read_input_tokens = usage.cacheRead;
    if (usage.cacheCreation) this.result.usage.cache_creation_input_tokens = usage.cacheCreation;
  }

  getResult() {
    return this.result;
  }
}

module.exports = { extractSseFrames, OpenAIStreamAggregator, AnthropicStreamAggregator };

/**
 * Petri shared backend — Structured Logger
 *
 * Canonical logger implementation shared by petri-server（及 BLOCK-30 前的 py-server）。
 * JSON-formatted logs in production; pretty console in development.
 */

const isDev = process.env.NODE_ENV !== 'production';

const LEVELS = { debug: 0, info: 1, warn: 2, error: 3 };
const minLevel = LEVELS[process.env.LOG_LEVEL || (isDev ? 'debug' : 'info')];

function formatLog(level, msg, meta) {
  if (isDev) {
    const prefix = { debug: '🔍', info: '✅', warn: '⚠️', error: '❌' }[level];
    const metaStr = meta ? ` ${JSON.stringify(meta)}` : '';
    return `${prefix} [${new Date().toISOString()}] ${msg}${metaStr}`;
  }
  return JSON.stringify({
    ts: new Date().toISOString(),
    level,
    msg,
    ...meta,
  });
}

function log(level, msg, meta) {
  if (LEVELS[level] < minLevel) return;
  const line = formatLog(level, msg, meta);
  if (level === 'error') {
    process.stderr.write(line + '\n');
  } else {
    process.stdout.write(line + '\n');
  }
}

/**
 * Create a child logger that automatically includes requestId in all log entries.
 * Usage: const rlog = logger.child(req.requestId); rlog.info('...');
 */
function child(requestId) {
  return {
    debug: (msg, meta) => log('debug', msg, { ...meta, rid: requestId }),
    info: (msg, meta) => log('info', msg, { ...meta, rid: requestId }),
    warn: (msg, meta) => log('warn', msg, { ...meta, rid: requestId }),
    error: (msg, meta) => log('error', msg, { ...meta, rid: requestId }),
  };
}

module.exports = {
  debug: (msg, meta) => log('debug', msg, meta),
  info: (msg, meta) => log('info', msg, meta),
  warn: (msg, meta) => log('warn', msg, meta),
  error: (msg, meta) => log('error', msg, meta),
  child,
};

'use strict';

/**
 * Loop Checkpoint, ContextEnvelope, BudgetPolicy, and SessionStageView — HLE-5.
 *
 * Pure functions: no I/O, no DB, no network.
 *
 * HLE-5 scope:
 *  - IterationCheckpoint: durable snapshot of loop state at end of each iteration.
 *  - LoopContextEnvelope: model-switch-safe context reconstruction from checkpoints.
 *  - LoopBudgetPolicy: token/cost/time soft limits and projection.
 *  - SessionStageView: compact and expanded user-facing summaries.
 *
 * NOT in scope (handled by integration layer):
 *  - Actual persistence of checkpoints (calls db.saveContextCheckpoint)
 *  - Recovery orchestration (calls reconcile on startup)
 *  - Budget enforcement (called by agent-runner before each action)
 *  - UI rendering (returns serializable data, UI renders it)
 *
 * Design principles:
 *  - No raw inputs/params/trace enter the checkpoint
 *  - ContextEnvelope is deterministic given the same checkpoints
 *  - Budget projections are honest: unavailable metrics show as null
 *  - SessionStageView is safe to display; no secrets, no raw code
 */

const crypto = require('crypto');
const { REASON_CODES } = require('./loop-contract');

// ---------------------------------------------------------------------------
// IterationCheckpoint
// ---------------------------------------------------------------------------

const CHECKPOINT_VERSION = 1;

/**
 * Build a LoopIterationCheckpoint for persistence.
 * Called by integration layer at end of each iteration.
 *
 * @param {Object} ctx
 * @returns {Object} frozen IterationCheckpoint
 */
function buildIterationCheckpoint({
  loopRunId,
  loopRunHash,
  sequence,
  observedStateDigest,
  goalGapIds,
  decision,
  decisionReasonCode,
  publicConclusion,
  status,
  proposedActionHash,
  validatorResults = [],
  repairAttempt = null,
  toolJobId = null,
  artifactIds = [],
  costSnapshot = null,
}) {
  const checkpoint = {
    schemaVersion: CHECKPOINT_VERSION,
    checkpointId: deriveCheckpointId({ loopRunId, loopRunHash, sequence }),
    loopRunId,
    loopRunHash,
    sequence,
    observedStateDigest,
    goalGapIds: Object.freeze([...goalGapIds]),
    decision,
    decisionReasonCode,
    publicConclusion: redactPublicConclusion(publicConclusion),
    status,
    proposedActionHash: proposedActionHash || null,
    validatorResults: Object.freeze([...(validatorResults || [])].map(sanitizeValidatorResult)),
    repairAttempt: repairAttempt ? sanitizeRepairAttempt(repairAttempt) : null,
    toolJobId: toolJobId || null,
    artifactIds: Object.freeze([...(artifactIds || [])]),
    costSnapshot: costSnapshot ? Object.freeze({ ...costSnapshot }) : null,
    createdAt: new Date().toISOString(),
  };
  return Object.freeze(checkpoint);
}

/**
 * Derive a stable checkpoint ID from loop identity + sequence.
 */
function deriveCheckpointId({ loopRunId, loopRunHash, sequence }) {
  const input = `${loopRunId}:${loopRunHash}:${sequence}:checkpoint:v${CHECKPOINT_VERSION}`;
  return `cp_${crypto.createHash('sha256').update(input, 'utf8').digest('hex').slice(0, 16)}`;
}

// ---------------------------------------------------------------------------
// LoopContextEnvelope
// ---------------------------------------------------------------------------

const ENVELOPE_VERSION = 1;

/**
 * Build a LoopContextEnvelope from a sequence of checkpoints.
 * Used to reconstruct loop state after model switch or app restart.
 *
 * The envelope is deterministic: same checkpoints → same envelope.
 * It does NOT contain raw inputs/params/actionKeys.
 *
 * @param {Object} ctx
 * @returns {Object} frozen LoopContextEnvelope
 */
function buildLoopContextEnvelope({
  loopRunId,
  checkpoints = [],
  currentModelProfileId = null,
  currentModelProfileLabel = null,
}) {
  if (!checkpoints || checkpoints.length === 0) {
    return buildEmptyEnvelope({ loopRunId, currentModelProfileId, currentModelProfileLabel });
  }

  // Latest checkpoint = current state
  const latest = checkpoints[checkpoints.length - 1];
  // Prior checkpoint = previous state for comparison
  const prior = checkpoints.length >= 2 ? checkpoints[checkpoints.length - 2] : null;

  // Compute unresolved gap from latest checkpoint
  const unresolvedGaps = computeUnresolvedGaps(checkpoints);

  // Compute next candidate actions from latest decision
  const nextActions = computeNextCandidateActions(latest, unresolvedGaps);

  // Failure/repair history from all checkpoints
  const failureHistory = collectFailureHistory(checkpoints);

  // Budget projection from all cost snapshots
  const budgetProjection = projectBudget(checkpoints);

  const envelope = {
    schemaVersion: ENVELOPE_VERSION,
    envelopeId: deriveEnvelopeId({ loopRunId, checkpoints }),
    loopRunId,
    version: ENVELOPE_VERSION,
    createdAt: new Date().toISOString(),
    loopState: Object.freeze({
      loopRunHash: latest.loopRunHash,
      currentSequence: latest.sequence,
      currentDigest: latest.observedStateDigest,
      currentDecision: latest.decision,
      currentDecisionReasonCode: latest.decisionReasonCode,
      currentStatus: latest.status,
      publicConclusion: latest.publicConclusion,
      goalGapIds: latest.goalGapIds,
    }),
    unresolvedGaps,
    nextActions,
    failureHistory,
    budgetProjection,
    modelContext: Object.freeze({
      currentModelProfileId: currentModelProfileId || null,
      currentModelProfileLabel: currentModelProfileLabel || null,
      windowCheckpointCount: checkpoints.length,
      // Original source range is NOT included here; it lives in ConversationContextEnvelope
    }),
    recoveryHint: buildRecoveryHint(latest, unresolvedGaps, nextActions),
  };

  return Object.freeze(envelope);
}

/**
 * Build an empty envelope for a loop with no checkpoints yet.
 */
function buildEmptyEnvelope({ loopRunId, currentModelProfileId, currentModelProfileLabel }) {
  return Object.freeze({
    schemaVersion: ENVELOPE_VERSION,
    envelopeId: `env_empty_${loopRunId.slice(0, 16)}`,
    loopRunId,
    version: ENVELOPE_VERSION,
    createdAt: new Date().toISOString(),
    loopState: Object.freeze({
      loopRunHash: null,
      currentSequence: 0,
      currentDigest: null,
      currentDecision: null,
      currentDecisionReasonCode: null,
      currentStatus: 'planned',
      publicConclusion: null,
      goalGapIds: [],
    }),
    unresolvedGaps: [],
    nextActions: [],
    failureHistory: [],
    budgetProjection: null,
    modelContext: Object.freeze({
      currentModelProfileId: currentModelProfileId || null,
      currentModelProfileLabel: currentModelProfileLabel || null,
      windowCheckpointCount: 0,
    }),
    recoveryHint: Object.freeze({
      action: 'wait_for_first_iteration',
      message: 'Loop 已初始化，等待首次迭代。',
    }),
  });
}

/**
 * Compute unresolved gaps from checkpoint history.
 * A gap is unresolved if it appeared in a checkpoint but was never
 * followed by a 'complete' decision.
 */
function computeUnresolvedGaps(checkpoints) {
  if (!checkpoints || checkpoints.length === 0) return [];

  const resolved = new Set();
  const unresolved = [];

  for (const cp of checkpoints) {
    if (cp.decision === 'complete' && Array.isArray(cp.goalGapIds)) {
      cp.goalGapIds.forEach((g) => resolved.add(g));
    }
  }

  const latest = checkpoints[checkpoints.length - 1];
  if (Array.isArray(latest.goalGapIds)) {
    for (const g of latest.goalGapIds) {
      if (!resolved.has(g)) unresolved.push(g);
    }
  }

  return unresolved;
}

/**
 * Compute next candidate actions from latest checkpoint.
 */
function computeNextCandidateActions(latest, unresolvedGaps) {
  if (!latest) return [];

  const { decision, decisionReasonCode, repairAttempt } = latest;

  if (decision === 'complete') {
    return [{ action: 'none', message: 'Loop 已完成。' }];
  }
  if (decision === 'cancel') {
    return [{ action: 'none', message: 'Loop 已取消。' }];
  }
  if (decision === 'block') {
    if (unresolvedGaps.length > 0) {
      return [{
        action: 'wait',
        message: latest.publicConclusion || '任务被阻断，等待人工介入。',
        reasonCode: decisionReasonCode,
      }];
    }
    return [{ action: 'wait', message: '任务被阻断。', reasonCode: decisionReasonCode }];
  }
  if (decision === 'wait') {
    return [{ action: 'wait', message: latest.publicConclusion || '等待用户确认。', reasonCode: decisionReasonCode }];
  }
  if (decision === 'continue') {
    return [{ action: 'wait', message: latest.publicConclusion || '任务执行中。' }];
  }
  if (decision === 'retry') {
    if (repairAttempt) {
      return [{
        action: 'repair',
        strategyId: repairAttempt.strategyId || null,
        message: repairAttempt.publicMessage || '自动修复中。',
        reasonCode: decisionReasonCode,
        parentJobId: repairAttempt.parentLineage?.parentJobId || null,
      }];
    }
    return [{ action: 'retry', message: '重试中。', reasonCode: decisionReasonCode }];
  }
  // Default: propose action for first unresolved gap
  if (unresolvedGaps.length > 0) {
    return [{
      action: 'propose',
      gapIds: unresolvedGaps,
      message: latest.publicConclusion || '继续推进目标。',
      reasonCode: decisionReasonCode,
    }];
  }
  return [{ action: 'unknown', message: latest.publicConclusion || '状态未知。' }];
}

/**
 * Collect failure and repair history from checkpoints.
 */
function collectFailureHistory(checkpoints) {
  if (!checkpoints || checkpoints.length === 0) return [];

  const history = [];
  for (const cp of checkpoints) {
    if (cp.decision === 'block' || cp.decision === 'retry') {
      history.push({
        sequence: cp.sequence,
        decision: cp.decision,
        reasonCode: cp.decisionReasonCode,
        publicConclusion: cp.publicConclusion,
        repairAttempt: cp.repairAttempt
          ? { strategyId: cp.repairAttempt.strategyId, parentJobId: cp.repairAttempt.parentLineage?.parentJobId }
          : null,
        validatorResults: cp.validatorResults
          ? cp.validatorResults.map((r) => ({ validatorId: r.validatorId, status: r.status }))
          : [],
      });
    }
  }
  return Object.freeze(history);
}

/**
 * Derive envelope ID deterministically.
 */
function deriveEnvelopeId({ loopRunId, checkpoints }) {
  if (!checkpoints || checkpoints.length === 0) {
    return `env_${loopRunId.slice(0, 16)}_empty`;
  }
  const latest = checkpoints[checkpoints.length - 1];
  const input = `${loopRunId}:${latest.loopRunHash}:${latest.sequence}:v${ENVELOPE_VERSION}`;
  return `env_${crypto.createHash('sha256').update(input, 'utf8').digest('hex').slice(0, 16)}`;
}

/**
 * Build a recovery hint for the integration layer.
 */
function buildRecoveryHint(latest, unresolvedGaps, nextActions) {
  if (!latest) {
    return Object.freeze({ action: 'wait', message: '无检查点历史。' });
  }
  if (latest.decision === 'complete') {
    return Object.freeze({ action: 'none', message: 'Loop 已完成，无需恢复。' });
  }
  if (latest.decision === 'block') {
    if (unresolvedGaps.length === 0) {
      return Object.freeze({ action: 'recovery_required', message: '状态未知，需人工确认。' });
    }
    return Object.freeze({
      action: 'wait_for_user',
      message: latest.publicConclusion || '阻断中，等待用户。',
      unresolvedGaps,
    });
  }
  if (latest.decision === 'retry' && nextActions.length > 0 && nextActions[0].action === 'repair') {
    return Object.freeze({
      action: 'auto_repair',
      strategyId: nextActions[0].strategyId,
      message: nextActions[0].message,
      parentJobId: nextActions[0].parentJobId || null,
    });
  }
  if (latest.decision === 'wait') {
    return Object.freeze({ action: 'wait_for_user', message: latest.publicConclusion || '等待用户。' });
  }
  return Object.freeze({ action: 'resume', message: '可继续推进目标。' });
}

// ---------------------------------------------------------------------------
// LoopBudgetPolicy
// ---------------------------------------------------------------------------

/**
 * @typedef {Object} BudgetSnapshot
 * @property {number|null} inputTokens   - total input tokens used so far
 * @property {number|null} outputTokens - total output tokens used so far
 * @property {number|null} costUsd       - estimated cost in USD
 * @property {number|null} elapsedMs     - wall-clock elapsed milliseconds
 * @property {number|null} cpuMs         - CPU milliseconds (if available)
 * @property {number|null} memoryMbPeak  - peak memory MB (if available)
 * @property {number|null} diskMbUsed    - disk usage MB
 * @property {number}      iterationCount - number of iterations
 */

/**
 * @typedef {Object} BudgetLimits
 * @property {number|null} maxInputTokens
 * @property {number|null} maxOutputTokens
 * @property {number|null} maxCostUsd
 * @property {number|null} maxElapsedMs
 * @property {number|null} maxIterations
 * @property {string}      whenExceed  - 'continue' | 'warn' | 'pause' | 'require_user'
 */

/**
 * @typedef {Object} BudgetProjection
 * @property {BudgetSnapshot} current
 * @property {BudgetLimits}   limits
 * @property {string}          status     - 'ok' | 'warning' | 'exceeded' | 'unavailable'
 * @property {number|null}    usagePct   - overall usage percentage (null if unavailable)
 * @property {string|null}    exhaustedResource - which resource hit the limit
 * @property {string|null}    projectedExhaustionMs - estimated ms until budget exhausted
 * @property {BudgetAdvice}   advice
 */

/**
 * @typedef {Object} BudgetAdvice
 * @property {string} action     - 'continue' | 'pause' | 'require_user' | 'stop'
 * @property {string} message
 * @property {string[]} warnings
 */

const DEFAULT_BUDGET_LIMITS = Object.freeze({
  maxInputTokens: null,
  maxOutputTokens: null,
  maxCostUsd: null,
  maxElapsedMs: null,
  maxIterations: null,
  whenExceed: 'warn',
});

/**
 * Project budget from a sequence of cost snapshots.
 *
 * @param {BudgetSnapshot[]} snapshots  - one per iteration
 * @param {BudgetLimits}    [limits]
 * @returns {BudgetProjection|null}
 */
function projectBudget(snapshots = [], limits = DEFAULT_BUDGET_LIMITS) {
  if (!snapshots || snapshots.length === 0) {
    return null;
  }

  const latest = snapshots[snapshots.length - 1];
  const effectiveLimits = { ...DEFAULT_BUDGET_LIMITS, ...limits };

  // Current snapshot
  const current = {
    inputTokens: latest.inputTokens || null,
    outputTokens: latest.outputTokens || null,
    costUsd: latest.costUsd || null,
    elapsedMs: latest.elapsedMs || null,
    cpuMs: latest.cpuMs || null,
    memoryMbPeak: latest.memoryMbPeak || null,
    diskMbUsed: latest.diskMbUsed || null,
    iterationCount: latest.iterationCount || snapshots.length,
  };

  // Check each resource
  const checks = [
    { name: 'inputTokens', value: latest.inputTokens, limit: effectiveLimits.maxInputTokens },
    { name: 'outputTokens', value: latest.outputTokens, limit: effectiveLimits.maxOutputTokens },
    { name: 'costUsd', value: latest.costUsd, limit: effectiveLimits.maxCostUsd },
    { name: 'elapsedMs', value: latest.elapsedMs, limit: effectiveLimits.maxElapsedMs },
    { name: 'iterations', value: snapshots.length, limit: effectiveLimits.maxIterations },
  ];

  const exceeded = checks.filter(
    (c) => c.value !== null && c.limit !== null && c.value >= c.limit,
  );
  const warnings = checks.filter(
    (c) =>
      c.value !== null &&
      c.limit !== null &&
      c.value >= c.limit * 0.8 &&
      c.value < c.limit,
  );

  let status = 'ok';
  let exhaustedResource = null;
  let usagePct = null;

  if (exceeded.length > 0) {
    status = 'exceeded';
    exhaustedResource = exceeded[0].name;
    usagePct = 100;
  } else if (warnings.length > 0) {
    status = 'warning';
    exhaustedResource = warnings[0].name;
    usagePct = Math.round((warnings[0].value / warnings[0].limit) * 100);
  } else {
    // Compute overall usage if any resource has a limit
    const firstWithLimit = checks.find((c) => c.limit !== null);
    if (firstWithLimit && firstWithLimit.value !== null) {
      usagePct = Math.round((firstWithLimit.value / firstWithLimit.limit) * 100);
    }
  }

  // Project exhaustion time from rate of change
  let projectedExhaustionMs = null;
  if (exceeded.length === 0 && latest.elapsedMs !== null && snapshots.length >= 2) {
    const first = snapshots[0];
    if (first.elapsedMs !== null) {
      const deltaMs = latest.elapsedMs - first.elapsedMs;
      const deltaIters = snapshots.length - 1;
      if (deltaMs > 0 && deltaIters > 0) {
        const msPerIter = deltaMs / deltaIters;
        if (latest.elapsedMs && effectiveLimits.maxElapsedMs) {
          const remaining = effectiveLimits.maxElapsedMs - latest.elapsedMs;
          if (remaining > 0) {
            projectedExhaustionMs = Math.round(remaining + msPerIter);
          }
        }
      }
    }
  }

  const advice = buildBudgetAdvice({
    status,
    exceeded,
    warnings,
    exhaustedResource,
    whenExceed: effectiveLimits.whenExceed,
  });

  return Object.freeze({
    current,
    limits: Object.freeze({ ...effectiveLimits }),
    status,
    usagePct,
    exhaustedResource,
    projectedExhaustionMs,
    advice,
  });
}

/**
 * Build budget advice based on status and limits policy.
 */
function buildBudgetAdvice({ status, exceeded, warnings, exhaustedResource, whenExceed }) {
  const warnings_list = warnings.map(
    (w) => `${w.name} 使用已达 ${Math.round((w.value / w.limit) * 100)}%`,
  );

  if (status === 'exceeded') {
    const action = whenExceed || 'pause';
    return Object.freeze({
      action,
      message:
        action === 'require_user'
          ? `预算已超限（${exhaustedResource}），请确认是否继续。`
          : `预算已超限（${exhaustedResource}）。`,
      warnings: warnings_list,
    });
  }

  if (status === 'warning') {
    return Object.freeze({
      action: 'warn',
      message: `${exhaustedResource} 使用超过 80%，接近预算上限。`,
      warnings: warnings_list,
    });
  }

  return Object.freeze({
    action: 'continue',
    message: '预算使用正常。',
    warnings: warnings_list,
  });
}

// ---------------------------------------------------------------------------
// SessionStageView — compact and expanded summaries
// ---------------------------------------------------------------------------

/**
 * Build a compact SessionStageView for the default (collapsed) UI.
 *
 * @param {Object} ctx
 * @returns {Object} frozen SessionStageView (compact)
 */
function buildSessionStageView({ loopRun, latestCheckpoint, budgetProjection }) {
  if (!loopRun && !latestCheckpoint) {
    return buildDefaultStageView();
  }

  const status = latestCheckpoint?.status || loopRun?.loopStatus || 'planned';
  const decision = latestCheckpoint?.decision || null;
  const conclusion = latestCheckpoint?.publicConclusion || loopRun?.metadata?.publicConclusion || null;
  const sequence = latestCheckpoint?.sequence || 0;
  const unresolvedGaps = latestCheckpoint?.goalGapIds || [];

  // Determine stage label from decision
  const stageLabel = deriveStageLabel({ status, decision, sequence });
  const stageIcon = deriveStageIcon({ status, decision });

  // Determine next hint from budget projection
  const budgetStatus = budgetProjection?.status || 'ok';
  const budgetAdvice = budgetProjection?.advice?.message || null;

  const compact = {
    schemaVersion: ENVELOPE_VERSION,
    viewType: 'compact',
    stage: Object.freeze({
      label: stageLabel,
      icon: stageIcon,
      sequence: sequence > 0 ? `${sequence}次迭代` : '初始化',
      status: deriveDisplayStatus({ status, decision }),
    }),
    conclusion: conclusion ? truncate(conclusion, 120) : null,
    nextHint: buildNextHint({ latestCheckpoint, budgetProjection }),
    budgetStatus,
    unresolvedCount: unresolvedGaps.length,
    recoveryHint: buildRecoveryHint(
      latestCheckpoint,
      unresolvedGaps,
      computeNextCandidateActions(latestCheckpoint, unresolvedGaps),
    ),
    generatedAt: new Date().toISOString(),
  };

  return Object.freeze(compact);
}

/**
 * Build an expanded SessionStageView for the detail panel.
 */
function buildExpandedSessionStageView({ loopRun, checkpoints = [], budgetProjection, failureHistory = [] }) {
  const latest = checkpoints.length > 0 ? checkpoints[checkpoints.length - 1] : null;
  const unresolvedGaps = latest ? computeUnresolvedGaps(checkpoints) : [];
  const nextActions = latest ? computeNextCandidateActions(latest, unresolvedGaps) : [];

  const expanded = {
    schemaVersion: ENVELOPE_VERSION,
    viewType: 'expanded',
    loopState: latest
      ? Object.freeze({
          loopRunId: loopRun?.loopRunId || latest.loopRunId,
          sequence: latest.sequence,
          status: latest.status,
          decision: latest.decision,
          reasonCode: latest.decisionReasonCode,
          publicConclusion: latest.publicConclusion,
          goalGapIds: latest.goalGapIds,
          validatorResults: latest.validatorResults || [],
          repairAttempt: latest.repairAttempt || null,
        })
      : null,
    unresolvedGaps,
    nextActions,
    failureHistory: Object.freeze([...(failureHistory || [])]),
    budgetProjection: budgetProjection || null,
    iterationCount: checkpoints.length,
    generatedAt: new Date().toISOString(),
  };

  return Object.freeze(expanded);
}

/**
 * Build the default view for a loop with no state yet.
 */
function buildDefaultStageView() {
  return Object.freeze({
    schemaVersion: ENVELOPE_VERSION,
    viewType: 'compact',
    stage: Object.freeze({
      label: '初始化',
      icon: 'loop',
      sequence: '',
      status: 'planned',
    }),
    conclusion: null,
    nextHint: Object.freeze({ action: 'wait', message: 'Loop 已创建，等待开始。' }),
    budgetStatus: 'ok',
    unresolvedCount: 0,
    recoveryHint: Object.freeze({ action: 'start', message: 'Loop 已初始化。' }),
    generatedAt: new Date().toISOString(),
  });
}

/**
 * Derive human-readable stage label from loop status + decision.
 * Decision takes priority over status for active states.
 */
function deriveStageLabel({ status, decision, sequence }) {
  if (decision === 'complete')  return '已完成';
  if (decision === 'retry')     return '自动修复';
  if (decision === 'block')     return '阻断';
  if (decision === 'wait')      return '等待确认';
  if (decision === 'cancel')    return '已取消';

  if (status === 'completed')  return '已完成';
  if (status === 'failed')     return '失败';
  if (status === 'cancelled')  return '已取消';
  if (status === 'blocked')    return '阻断';
  if (status === 'running')     return sequence > 0 ? '执行中' : '运行中';
  return '初始化';
}

/**
 * Derive icon name from decision first, then status.
 */
function deriveStageIcon({ status, decision }) {
  if (decision === 'complete') return 'check_circle';
  if (decision === 'retry')    return 'refresh';
  if (decision === 'block')     return 'warning';
  if (decision === 'wait')      return 'help';
  if (decision === 'cancel')    return 'cancel';

  if (status === 'completed') return 'check_circle';
  if (status === 'failed')    return 'error';
  if (status === 'cancelled') return 'cancel';
  if (status === 'blocked')   return 'block';
  if (status === 'running')   return 'sync';
  return 'loop';
}

/**
 * Derive display status string for compact view.
 */
function deriveDisplayStatus({ status, decision }) {
  if (decision === 'complete') return 'completed';
  if (decision === 'block')    return 'blocked';
  if (decision === 'wait')      return 'waiting';
  if (decision === 'retry')    return 'repairing';
  if (decision === 'cancel')    return 'cancelled';

  if (status === 'running')   return 'running';
  if (status === 'blocked')   return 'blocked';
  if (status === 'completed')  return 'completed';
  if (status === 'failed')    return 'failed';
  if (status === 'cancelled') return 'cancelled';
  return status || 'unknown';
}

/**
 * Build next hint from latest checkpoint and budget.
 * Budget status ALWAYS takes priority over decision-based hints.
 */
function buildNextHint({ latestCheckpoint, budgetProjection }) {
  const bp = budgetProjection;
  // Budget exceeded always surfaces first, then warning
  if (bp && bp.status === 'exceeded') {
    return Object.freeze({
      action: bp.advice?.action || 'pause',
      message: bp.advice?.message || '预算已超限。',
    });
  }
  if (bp && bp.status === 'warning') {
    return Object.freeze({
      action: 'warn',
      message: bp.advice?.message || '接近预算上限。',
    });
  }
  if (!latestCheckpoint) {
    return Object.freeze({ action: 'wait', message: '等待开始。' });
  }
  const { decision, publicConclusion } = latestCheckpoint;
  if (decision === 'complete') {
    return Object.freeze({ action: 'none', message: '任务已完成。' });
  }
  if (decision === 'block') {
    return Object.freeze({ action: 'wait', message: publicConclusion || '阻断中。' });
  }
  if (decision === 'wait') {
    return Object.freeze({ action: 'wait', message: publicConclusion || '等待确认。' });
  }
  if (decision === 'retry') {
    return Object.freeze({ action: 'repair', message: '自动修复中。' });
  }
  if (decision === 'cancel') {
    return Object.freeze({ action: 'none', message: '任务已取消。' });
  }
  // 'continue' and unknown
  return Object.freeze({ action: 'proceed', message: publicConclusion || '继续。' });
}

// ---------------------------------------------------------------------------
// Sanitization helpers (no secrets, no raw code enter checkpoints)
// ---------------------------------------------------------------------------

function redactPublicConclusion(conclusion) {
  if (!conclusion) return null;
  return truncate(conclusion, 500);
}

function sanitizeValidatorResult(result) {
  return Object.freeze({
    validatorId: result.validatorId,
    status: result.status,
    version: result.version,
    findings: Object.freeze(
      (result.findings || []).map((f) =>
        Object.freeze({
          code: f.code || 'UNKNOWN',
          message: truncate(f.message || '', 200),
          severity: f.severity || 'warning',
        }),
      ),
    ),
    detail: result.detail ? truncate(result.detail, 200) : null,
  });
}

/**
 * Truncate a string to maxLen, appending "…" if truncated.
 */
function truncate(str, maxLen) {
  if (!str || str.length <= maxLen) return str;
  return str.slice(0, maxLen) + '…';
}

function sanitizeRepairAttempt(attempt) {
  return Object.freeze({
    strategyId: attempt.strategyId,
    strategyVersion: attempt.strategyVersion,
    safetyLevel: attempt.safetyLevel,
    costMultiplier: attempt.costMultiplier,
    isActionable: !!attempt.isActionable,
    requiresUserAuth: !!attempt.requiresUserAuth,
    publicMessage: truncate(attempt.publicMessage || '', 300),
    parentLineage: attempt.parentLineage
      ? Object.freeze({
          parentJobId: attempt.parentLineage.parentJobId || null,
          repairReason: attempt.parentLineage.repairReason || null,
        })
      : null,
    replacementJobId: attempt.replacementJobId || null,
    repaired: attempt.repaired === true,
    invalidatedArtifactIds: Object.freeze([...(attempt.invalidatedArtifactIds || [])]),
    preservedArtifactIds: Object.freeze([...(attempt.preservedArtifactIds || [])]),
  });
}

function truncate(str, maxLen) {
  if (!str || str.length <= maxLen) return str;
  return str.slice(0, maxLen) + '…';
}

// ---------------------------------------------------------------------------
// Utilities
// ---------------------------------------------------------------------------

/**
 * Merge a new cost snapshot into accumulated budget.
 */
function mergeCostSnapshot(accumulated, newSnapshot) {
  return {
    inputTokens: sum(accumulated?.inputTokens, newSnapshot?.inputTokens),
    outputTokens: sum(accumulated?.outputTokens, newSnapshot?.outputTokens),
    costUsd: sum(accumulated?.costUsd, newSnapshot?.costUsd),
    elapsedMs: newSnapshot?.elapsedMs || accumulated?.elapsedMs || null,
    cpuMs: max(accumulated?.cpuMs, newSnapshot?.cpuMs),
    memoryMbPeak: max(accumulated?.memoryMbPeak, newSnapshot?.memoryMbPeak),
    diskMbUsed: max(accumulated?.diskMbUsed, newSnapshot?.diskMbUsed),
    iterationCount: (accumulated?.iterationCount || 0) + 1,
  };
}

function sum(a, b) {
  if (a === null || a === undefined) return b;
  if (b === null || b === undefined) return a;
  return a + b;
}

function max(a, b) {
  if (a === null || a === undefined) return b;
  if (b === null || b === undefined) return a;
  return a > b ? a : b;
}

module.exports = {
  CHECKPOINT_VERSION,
  ENVELOPE_VERSION,
  buildIterationCheckpoint,
  deriveCheckpointId,
  buildLoopContextEnvelope,
  buildEmptyEnvelope,
  computeUnresolvedGaps,
  computeNextCandidateActions,
  collectFailureHistory,
  deriveEnvelopeId,
  buildRecoveryHint,
  projectBudget,
  buildBudgetAdvice,
  buildSessionStageView,
  buildExpandedSessionStageView,
  buildDefaultStageView,
  mergeCostSnapshot,
  DEFAULT_BUDGET_LIMITS,
};

'use strict';

/**
 * Loop Contract v1 — versioned, immutable, hashable.
 *
 * The Loop is the durable record of how an agent (or any controller)
 * advanced toward a goal on a single conversation. Every step is an
 * Iteration that contains a Decision and (optionally) an Action and
 * Evidence. Snapshots are compressed state used for replay and recovery.
 *
 * Invariants:
 *  - Every persisted record carries a stable SHA-256 `hash` derived from
 *    a canonical JSON serialization of its semantic fields. Fields like
 *    `createdAt` and `id` are NOT included in the hash, so semantically
 *    identical records hash identically across processes and restarts.
 *  - `actionKey` is the idempotency key for a proposed action. Two
 *    iterations with the same `actionKey` on the same `loopRunId` must
 *    be deduplicated; never executed twice.
 *  - All free-text payloads (publicConclusion, observationDigest,
 *    decisionReasonCode, evidenceRef) pass through `redactSensitiveValue`
 *    BEFORE serialization to the database. Raw Provider responses and
 *    stack traces NEVER enter the Loop ledger.
 *  - Status transitions are a finite-state machine. Invalid transitions
 *    throw; they do not silently mutate state.
 *
 * This module is pure (no I/O, no db, no network). The persistence
 * layer (SQLite) lives in `core/petri-server/db.js`. The route layer
 * (`/api/loop/iterate`) lives in `core/petri-server/routes/harness.js`.
 *
 * HLE-1 scope: schema + canonicalize + hash + reason codes + redaction.
 * HLE-2 scope: controller (observe → decide → validate → execute →
 *              record → evaluate exit).
 */

const crypto = require('crypto');
const { redactSensitiveValue } = require('./redaction');

const LOOP_CONTRACT_VERSION = 1;

const LOOP_RUN_STATUSES = Object.freeze([
  'planned',
  'running',
  'waiting_for_user',
  'blocked',
  'completed',
  'failed',
  'cancelled',
]);

/**
 * How independently the Loop may act. This is deliberately separate from
 * executionIntent: a trusted run may execute a task, while a guided run may
 * still be a draft-only turn. Keeping the two axes distinct prevents UI access
 * modes and task classification from corrupting the durable contract.
 */
const LOOP_AUTOMATION_MODES = Object.freeze(['guided', 'confirm', 'trusted']);
const LOOP_EXECUTION_INTENTS = Object.freeze(['task_draft', 'task_execute']);

const ITERATION_STATUSES = Object.freeze([
  'pending',
  'running',
  'succeeded',
  'failed',
  'blocked',
  'skipped',
]);

const ACTION_TYPES = Object.freeze([
  'plan',
  'run_tool',
  'wait_for_user',
  'verify',
  'repair',
  'finalize',
  'cancel',
]);

const DECISION_OUTCOMES = Object.freeze([
  'continue',
  'retry',
  'block',
  'wait',
  'complete',
  'cancel',
]);

const EVIDENCE_KINDS = Object.freeze([
  'tool_output',
  'artifact_pointer',
  'user_input',
  'checkpoint',
  'plan_step',
  'observation',
]);

const REASON_CODES = Object.freeze({
  // plan / decide
  NORMAL_PLAN_GENERATED: 'NORMAL_PLAN_GENERATED',
  PLAN_REVISED: 'PLAN_REVISED',
  PLAN_OSCILLATION_DETECTED: 'PLAN_OSCILLATION_DETECTED',
  NO_PROGRESS_CYCLE_DETECTED: 'NO_PROGRESS_CYCLE_DETECTED',
  // tool execution
  VALID_INPUTS_CONFIRMED: 'VALID_INPUTS_CONFIRMED',
  INPUT_FORMAT_MISMATCH: 'INPUT_FORMAT_MISMATCH',
  INVALID_ARGUMENTS: 'INVALID_ARGUMENTS',
  TOOL_RUNTIME_NOT_READY: 'TOOL_RUNTIME_NOT_READY',
  METHOD_NOT_APPLICABLE: 'METHOD_NOT_APPLICABLE',
  TRANSIENT_RUNTIME_RETRY: 'TRANSIENT_RUNTIME_RETRY',
  TOOL_SUCCEEDED: 'TOOL_SUCCEEDED',
  TOOL_VERIFIED: 'TOOL_VERIFIED',
  // termination
  ALL_NODES_VERIFIED: 'ALL_NODES_VERIFIED',
  // BLOCK-83 D1/D12：词表中性化——「阻塞等待用户输入」才是中立语义。
  USER_INPUT_REQUIRED: 'USER_INPUT_REQUIRED',
  // 兼容别名（一版后移除）：同值，旧引用自动产出新值。
  SCIENTIFIC_DESIGN_MISSING: 'USER_INPUT_REQUIRED',
  USER_CANCELLED: 'USER_CANCELLED',
  GOAL_ACHIEVED: 'GOAL_ACHIEVED',
  // recovery
  RECOVERY_REQUIRED: 'RECOVERY_REQUIRED',
  STALLED_JOB_RECOVERED: 'STALLED_JOB_RECOVERED',
  // HLE-3: artifact validation
  ARTIFACT_VALIDATION_FAILED: 'ARTIFACT_VALIDATION_FAILED',
  ARTIFACT_VALIDATION_WARNING: 'ARTIFACT_VALIDATION_WARNING',
});

const TERMINAL_LOOP_STATUSES = new Set(['completed', 'failed', 'cancelled']);

const LOOP_STATUS_TRANSITIONS = Object.freeze({
  planned: new Set(['running', 'cancelled']),
  running: new Set(['waiting_for_user', 'blocked', 'completed', 'failed', 'cancelled']),
  waiting_for_user: new Set(['running', 'blocked', 'completed', 'failed', 'cancelled']),
  blocked: new Set(['running', 'completed', 'failed', 'cancelled']),
  completed: new Set(),
  failed: new Set(['running', 'cancelled']),
  cancelled: new Set(),
});

const ITERATION_STATUS_TRANSITIONS = Object.freeze({
  pending: new Set(['running', 'skipped']),
  running: new Set(['succeeded', 'failed', 'blocked', 'skipped']),
  succeeded: new Set(),
  failed: new Set(['running', 'skipped']),
  blocked: new Set(['running', 'skipped']),
  skipped: new Set(),
});

const SEMANTIC_FIELD_KEYS = Object.freeze({
  loopRun: Object.freeze([
    'loopRunId',
    'projectId',
    'conversationId',
    'taskSpecRef',
    'automationMode',
    'executionIntent',
    'loopStatus',
    'createdAt',
    'updatedAt',
    'metadata',
  ]),
  iteration: Object.freeze([
    'loopRunId',
    'sequence',
    'observedStateDigest',
    'goalGapIds',
    'decision',
    'decisionReasonCode',
    'publicConclusion',
    'status',
  ]),
  action: Object.freeze([
    'actionKey',
    'actionType',
    'toolId',
    'inputs',
    'params',
    'expectedArtifactKinds',
    'attempt',
  ]),
  evidence: Object.freeze([
    'evidenceId',
    'kind',
    'ref',
    'summaryDigest',
    'createdAt',
  ]),
  decision: Object.freeze([
    'decision',
    'decisionReasonCode',
    'confidence',
    'notes',
  ]),
});

function canonicalize(value) {
  if (value === null || typeof value !== 'object') {
    return JSON.stringify(value);
  }
  if (Array.isArray(value)) {
    return `[${value.map(canonicalize).join(',')}]`;
  }
  if (value instanceof Date) {
    return JSON.stringify(value.toISOString());
  }
  const keys = Object.keys(value).sort();
  const parts = keys.map((k) => `${JSON.stringify(k)}:${canonicalize(value[k])}`);
  return `{${parts.join(',')}}`;
}

function canonicalStringify(value) {
  return canonicalize(value);
}

function sha256Hex(input) {
  return crypto.createHash('sha256').update(input, 'utf8').digest('hex');
}

function stableHash(semanticFields) {
  return sha256Hex(canonicalStringify(semanticFields));
}

function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function requireKeys(obj, keys, label) {
  if (!isPlainObject(obj)) {
    throw new TypeError(`${label} must be an object`);
  }
  const missing = keys.filter((k) => obj[k] === undefined || obj[k] === null || obj[k] === '');
  if (missing.length > 0) {
    throw new TypeError(`${label} missing required keys: ${missing.join(', ')}`);
  }
}

function requireEnum(value, enumValues, label) {
  if (!enumValues.includes(value)) {
    throw new TypeError(
      `${label} must be one of [${enumValues.join(', ')}]; got ${JSON.stringify(value)}`,
    );
  }
}

function generateId(prefix) {
  return `${prefix}_${crypto.randomBytes(12).toString('hex')}`;
}

function generateActionKey(parts) {
  const joined = [
    parts.loopRunId || '',
    String(parts.sequence ?? ''),
    parts.actionType || '',
    parts.toolId || '',
    stableHash({
      inputs: parts.inputs || null,
      params: parts.params || null,
      expectedArtifactKinds: parts.expectedArtifactKinds || null,
      attempt: parts.attempt || 1,
    }),
  ].join('|');
  return sha256Hex(joined);
}

function nowIso() {
  return new Date().toISOString();
}

function validateLoopRun(input, { allowPartial = false } = {}) {
  const required = ['loopRunId', 'projectId', 'conversationId', 'loopStatus'];
  requireKeys(input, required, 'loopRun');
  requireEnum(input.loopStatus, LOOP_RUN_STATUSES, 'loopRun.loopStatus');
  if (typeof input.loopRunId !== 'string' || !input.loopRunId) {
    throw new TypeError('loopRun.loopRunId must be a non-empty string');
  }
  if (typeof input.projectId !== 'string' || !input.projectId) {
    throw new TypeError('loopRun.projectId must be a non-empty string');
  }
  if (typeof input.conversationId !== 'string' || !input.conversationId) {
    throw new TypeError('loopRun.conversationId must be a non-empty string');
  }
  if (!allowPartial) {
    if (!input.taskSpecRef || typeof input.taskSpecRef !== 'string') {
      throw new TypeError('loopRun.taskSpecRef must be a non-empty string');
    }
    if (input.automationMode) {
      requireEnum(input.automationMode, LOOP_AUTOMATION_MODES, 'loopRun.automationMode');
    }
    if (input.executionIntent) {
      requireEnum(input.executionIntent, LOOP_EXECUTION_INTENTS, 'loopRun.executionIntent');
    }
  }
  return input;
}

/**
 * Read compatibility for rows written before automationMode and
 * executionIntent were separated. New writes must always use buildLoopRun.
 */
function normalizeLoopAutomationMode(value, fallback = 'guided') {
  if (LOOP_AUTOMATION_MODES.includes(value)) return value;
  if (value === 'task_execute') return 'trusted';
  if (value === 'task_draft') return 'guided';
  return LOOP_AUTOMATION_MODES.includes(fallback) ? fallback : 'guided';
}

function normalizeLoopExecutionIntent(value, legacyAutomationMode = null) {
  if (LOOP_EXECUTION_INTENTS.includes(value)) return value;
  if (LOOP_EXECUTION_INTENTS.includes(legacyAutomationMode)) return legacyAutomationMode;
  return null;
}

function validateIteration(input, { allowPartial = false } = {}) {
  const required = [
    'loopRunId',
    'sequence',
    'observedStateDigest',
    'decision',
    'decisionReasonCode',
    'status',
  ];
  requireKeys(input, required, 'iteration');
  if (!Number.isInteger(input.sequence) || input.sequence < 1) {
    throw new TypeError('iteration.sequence must be a positive integer');
  }
  requireEnum(input.decision, DECISION_OUTCOMES, 'iteration.decision');
  requireEnum(input.status, ITERATION_STATUSES, 'iteration.status');
  if (typeof input.observedStateDigest !== 'string') {
    throw new TypeError('iteration.observedStateDigest must be a string');
  }
  if (typeof input.decisionReasonCode !== 'string' || !input.decisionReasonCode) {
    throw new TypeError('iteration.decisionReasonCode must be a non-empty string');
  }
  if (input.publicConclusion !== undefined && typeof input.publicConclusion !== 'string') {
    throw new TypeError('iteration.publicConclusion must be a string when present');
  }
  if (input.goalGapIds !== undefined && !Array.isArray(input.goalGapIds)) {
    throw new TypeError('iteration.goalGapIds must be an array when present');
  }
  if (input.proposedAction !== undefined && input.proposedAction !== null) {
    validateAction(input.proposedAction, { allowPartial: true });
  }
  if (!allowPartial) {
    if (typeof input.publicConclusion !== 'string' || input.publicConclusion.length === 0) {
      throw new TypeError('iteration.publicConclusion must be a non-empty string');
    }
  }
  return input;
}

function validateAction(input, { allowPartial = false } = {}) {
  if (input === null || input === undefined) {
    return null;
  }
  if (!isPlainObject(input)) {
    throw new TypeError('action must be an object');
  }
  requireEnum(input.actionType, ACTION_TYPES, 'action.actionType');
  if (input.actionType === 'run_tool') {
    if (!input.toolId || typeof input.toolId !== 'string') {
      throw new TypeError('action.toolId is required when actionType=run_tool');
    }
  }
  return input;
}

function validateEvidence(input, { allowPartial = false } = {}) {
  if (input === null || input === undefined) {
    return null;
  }
  requireKeys(input, ['evidenceId', 'kind', 'ref'], 'evidence');
  requireEnum(input.kind, EVIDENCE_KINDS, 'evidence.kind');
  return input;
}

function validateDecision(input) {
  requireKeys(input, ['decision', 'decisionReasonCode'], 'decision');
  requireEnum(input.decision, DECISION_OUTCOMES, 'decision.decision');
  return input;
}

function checkStatusTransition(fromStatus, toStatus, transitions) {
  if (fromStatus === toStatus) return true;
  const allowed = transitions[fromStatus];
  if (!allowed) {
    throw new TypeError(`Unknown source status: ${fromStatus}`);
  }
  if (!allowed.has(toStatus)) {
    throw new TypeError(
      `Invalid status transition: ${fromStatus} -> ${toStatus}`,
    );
  }
  return true;
}

function checkLoopStatusTransition(fromStatus, toStatus) {
  return checkStatusTransition(fromStatus, toStatus, LOOP_STATUS_TRANSITIONS);
}

function checkIterationStatusTransition(fromStatus, toStatus) {
  return checkStatusTransition(fromStatus, toStatus, ITERATION_STATUS_TRANSITIONS);
}

function isTerminalLoopStatus(status) {
  return TERMINAL_LOOP_STATUSES.has(status);
}

function buildLoopRun(input) {
  const base = {
    loopRunId: input.loopRunId || generateId('loop'),
    projectId: input.projectId,
    conversationId: input.conversationId,
    taskSpecRef: input.taskSpecRef || null,
    automationMode: normalizeLoopAutomationMode(input.automationMode),
    executionIntent: normalizeLoopExecutionIntent(
      input.executionIntent,
      input.automationMode,
    ),
    loopStatus: input.loopStatus || 'planned',
    kind: input.kind || 'primary',
    parentLoopRunId: input.parentLoopRunId || null,
    createdAt: input.createdAt || nowIso(),
    updatedAt: input.updatedAt || nowIso(),
    metadata: redactSensitiveValue(input.metadata || {}),
  };
  validateLoopRun(base);
  const hash = stableHash(pickSemanticFields(base, SEMANTIC_FIELD_KEYS.loopRun));
  return { ...base, hash };
}

function buildIteration(input, options = {}) {
  const { allowPartial = true, ...extra } = options;
  const base = {
    iterationId: input.iterationId || generateId('iter'),
    loopRunId: input.loopRunId,
    sequence: input.sequence,
    observedStateDigest: redactSensitiveValue(input.observedStateDigest || ''),
    goalGapIds: Array.isArray(input.goalGapIds) ? input.goalGapIds.slice() : [],
    proposedAction: input.proposedAction
      ? buildAction(input.proposedAction, { partial: true })
      : null,
    decision: input.decision,
    decisionReasonCode: input.decisionReasonCode,
    confidence: typeof input.confidence === 'number' ? input.confidence : null,
    notes: redactSensitiveValue(input.notes || null),
    publicConclusion: redactSensitiveValue(input.publicConclusion || ''),
    status: input.status || 'pending',
    createdAt: input.createdAt || nowIso(),
    parentIterationHash: input.parentIterationHash || null,
    // HLE-5: extended fields
    validatorResults: extra.validatorResults
      ? Object.freeze([...extra.validatorResults])
      : null,
    repairAttempt: extra.repairAttempt || null,
    costSnapshot: extra.costSnapshot
      ? Object.freeze({ ...extra.costSnapshot })
      : null,
  };
  validateIteration(base, { allowPartial });
  const hash = stableHash(pickSemanticFields(base, SEMANTIC_FIELD_KEYS.iteration));
  return { ...base, hash };
}

function buildAction(input, { partial = false } = {}) {
  if (!input) return null;
  const actionId = input.actionId || generateId('action');
  const attempt = Number.isInteger(input.attempt) ? input.attempt : 1;
  const base = {
    actionId,
    actionKey:
      input.actionKey ||
      generateActionKey({
        loopRunId: input.loopRunId || null,
        sequence: input.sequence || null,
        actionType: input.actionType,
        toolId: input.toolId || null,
        inputs: input.inputs || null,
        params: input.params || null,
        expectedArtifactKinds: input.expectedArtifactKinds || null,
        attempt,
      }),
    actionType: input.actionType,
    toolId: input.toolId || null,
    inputs: redactSensitiveValue(input.inputs || null),
    params: redactSensitiveValue(input.params || null),
    expectedArtifactKinds: Array.isArray(input.expectedArtifactKinds)
      ? input.expectedArtifactKinds.slice()
      : [],
    attempt,
  };
  validateAction(base, { allowPartial: partial });
  const hash = stableHash(pickSemanticFields(base, SEMANTIC_FIELD_KEYS.action));
  return { ...base, hash };
}

function buildEvidence(input) {
  if (!input) return null;
  const base = {
    evidenceId: input.evidenceId || generateId('evid'),
    loopRunId: input.loopRunId || null,
    iterationId: input.iterationId || null,
    kind: input.kind,
    ref: redactSensitiveValue(input.ref),
    summaryDigest: redactSensitiveValue(input.summaryDigest || ''),
    createdAt: input.createdAt || nowIso(),
    parentEvidenceHash: input.parentEvidenceHash || null,
  };
  validateEvidence(base);
  const hash = stableHash(pickSemanticFields(base, SEMANTIC_FIELD_KEYS.evidence));
  return { ...base, hash };
}

function buildDecision(input) {
  const base = {
    decision: input.decision,
    decisionReasonCode: input.decisionReasonCode,
    confidence: typeof input.confidence === 'number' ? input.confidence : null,
    notes: redactSensitiveValue(input.notes || null),
  };
  validateDecision(base);
  const hash = stableHash(pickSemanticFields(base, SEMANTIC_FIELD_KEYS.decision));
  return { ...base, hash };
}

function pickSemanticFields(obj, keys) {
  const out = {};
  for (const k of keys) {
    out[k] = obj[k] === undefined ? null : obj[k];
  }
  return out;
}

function deriveIterationHash(semanticFields) {
  return stableHash(semanticFields);
}

function projectLoopRunPartial(loopRun) {
  return {
    loopRunId: loopRun.loopRunId,
    loopStatus: loopRun.loopStatus || 'planned',
    isPartial: true,
    partialReason: 'legacy_no_loop_data',
    taskSpecRef: loopRun.taskSpecRef || null,
    projectId: loopRun.projectId,
    conversationId: loopRun.conversationId,
  };
}

module.exports = {
  LOOP_CONTRACT_VERSION,
  LOOP_RUN_STATUSES,
  LOOP_AUTOMATION_MODES,
  LOOP_EXECUTION_INTENTS,
  ITERATION_STATUSES,
  ACTION_TYPES,
  DECISION_OUTCOMES,
  EVIDENCE_KINDS,
  REASON_CODES,
  TERMINAL_LOOP_STATUSES,
  LOOP_STATUS_TRANSITIONS,
  ITERATION_STATUS_TRANSITIONS,
  SEMANTIC_FIELD_KEYS,
  canonicalStringify,
  sha256Hex,
  stableHash,
  generateId,
  generateActionKey,
  validateLoopRun,
  normalizeLoopAutomationMode,
  normalizeLoopExecutionIntent,
  validateIteration,
  validateAction,
  validateEvidence,
  validateDecision,
  checkLoopStatusTransition,
  checkIterationStatusTransition,
  isTerminalLoopStatus,
  buildLoopRun,
  buildIteration,
  buildAction,
  buildEvidence,
  buildDecision,
  pickSemanticFields,
  deriveIterationHash,
  projectLoopRunPartial,
  redactSensitiveValue,
};

'use strict';

/**
 * Loop Controller v1 — centralized observe → decide → validate → record → evaluate exit.
 *
 * Pure functions: no I/O, no DB, no network. All side effects (persisting iterations,
 * executing tools, updating conversation state) live in the integration layer.
 *
 * HLE-2 scope:
 *  - Derive observedStateDigest from conversation + job state (deterministic hash).
 *  - Compute goalGapIds by diffing DAG progress against previous iterations.
 *  - Detect no-progress cycles (same gap IDs observed repeatedly).
 *  - Detect repeated-action (same actionKey observed previously in this loop).
 *  - Detect oscillation (A↔B plan revision ping-pong).
 *  - Decide: continue / retry / wait / block / complete / cancel.
 *  - Validate: inputs completeness, tool readiness, parameter sanity.
 *  - Record: build a complete Iteration record via loop-contract.js.
 *  - Evaluate: should the loop exit? (all gaps resolved, or terminal error).
 *
 * NOT in scope (HLE-1: already done; HLE-3: validators; HLE-4: repair strategies):
 *  - Actually executing a tool (tool_executor lives in petri-server).
 *  - Replaying a session from disk.
 *  - Re-routing around a failed node (HLE-4 repair strategy).
 *
 * Integration contract (HLE-3+):
 *  - Controller produces a "proposedAction" with actionKey.
 *  - Integration layer calls db.persistLoopIteration() then tool_executor().
 *  - After execution, integration layer calls controller.evaluate() again
 *    with the execution result embedded in observedStateDigest.
 */

const { redactSensitiveValue } = require('./redaction');

const {
  ACTION_TYPES,
  DECISION_OUTCOMES,
  REASON_CODES,
  EVIDENCE_KINDS,
  LOOP_RUN_STATUSES,
  stableHash,
  deriveIterationHash,
  pickSemanticFields,
  SEMANTIC_FIELD_KEYS,
  buildAction,
  buildIteration,
  buildEvidence,
  buildDecision,
  isTerminalLoopStatus,
} = require('./loop-contract');

const TOOL_STATES = Object.freeze(['pending', 'queued', 'running', 'completed', 'failed', 'blocked']);

// ---------------------------------------------------------------------------
// Observed state — derived deterministically from conversation + job facts.
// ---------------------------------------------------------------------------

/**
 * Derive a deterministic digest of the current conversation + job state.
 * Two calls with identical inputs always produce the same digest.
 * @param {Object} facts - { toolJobs, conversationSummary, dagProgress, lastIteration }
 * @returns {string} SHA-256 hex digest
 */
function deriveObservedStateDigest(facts) {
  const { toolJobs = [], conversationSummary = '', dagProgress = {} } = facts;
  const jobDigest = deriveJobsDigest(toolJobs);
  const progressDigest = deriveProgressDigest(dagProgress);
  const summaryDigest = stableHash({ conversationSummary, jobDigest, progressDigest });
  return summaryDigest;
}

function deriveJobsDigest(jobs) {
  if (!jobs || jobs.length === 0) return stableHash({ count: 0 });
  const summaries = (jobs)
    .slice()
    .sort((a, b) => String(a.id || '').localeCompare(b.id || ''))
    .map((j) => ({
      id: j.id || j.tool_job_id || null,
      status: j.status || null,
      error: j.error ? 'has_error' : 'no_error',
      finished: j.finished_at || j.completed_at ? 'finished' : 'incomplete',
    }));
  return stableHash({ jobs: summaries });
}

function deriveProgressDigest(progress) {
  if (!progress || typeof progress !== 'object') return stableHash({});
  const nodeStatuses = Object.keys(progress)
    .sort()
    .map((k) => `${k}:${String(progress[k])}`);
  return stableHash({ nodes: nodeStatuses });
}

// ---------------------------------------------------------------------------
// Goal gap analysis — which DAG gaps remain unresolved?
// ---------------------------------------------------------------------------

/**
 * Compute goal gap IDs by comparing DAG progress against previous iterations.
 * @param {Object} dag           - { nodes: [{ id, status }] }
 * @param {Array}  iterations   - previous iterations (most recent last)
 * @returns {Array<string>}     - IDs of unresolved gaps
 */
function computeGoalGapIds(dag, iterations = []) {
  if (!dag || !Array.isArray(dag.nodes)) return [];
  // Accumulate all resolved (previously proposed) gap IDs from every iteration.
  // This correctly handles multi-node proposals: if it1 proposed [n1,n2,n3],
  // all three are resolved, even if only n1 finished.
  const resolved = new Set();
  for (const it of iterations || []) {
    if (it && Array.isArray(it.goalGapIds)) {
      for (const id of it.goalGapIds) resolved.add(id);
    }
  }
  const incomplete = dag.nodes
    .filter((n) => !resolved.has(n.id))
    .map((n) => n.id);

  if (incomplete.length > 0) return incomplete;

  // All nodes resolved — check delivery
  if (dag.expectedDeliverables) {
    const pendingDeliverables = (dag.expectedDeliverables || [])
      .filter((d) => !d.delivered);
    if (pendingDeliverables.length > 0) {
      return ['pending_deliverables'];
    }
  }

  return [];
}

/**
 * Compute which goal gap IDs were resolved in this iteration vs the last.
 * @param {Array<string>} currentGapIds  - from computeGoalGapIds
 * @param {Array}        iterations     - previous iterations (most recent last)
 * @returns {Array<string>} IDs that are new (not in last iteration's gaps)
 */
function computeResolvedGapIds(currentGapIds, iterations = []) {
  if (!iterations || iterations.length === 0) return currentGapIds;
  const last = iterations[iterations.length - 1];
  if (!last || !Array.isArray(last.goalGapIds)) return currentGapIds;
  const prevGaps = new Set(last.goalGapIds);
  return currentGapIds.filter((id) => !prevGaps.has(id));
}

// ---------------------------------------------------------------------------
// Detection: no-progress / repeated-action / oscillation
// ---------------------------------------------------------------------------

/**
 * Detect no-progress cycles: the same set of goal gaps observed for N consecutive
 * iterations with no newly resolved gaps.
 * @param {Array<string>}   currentGapIds  - from computeGoalGapIds
 * @param {Array}          iterations     - previous iterations (in order)
 * @param {number}         threshold      - number of repeats to trigger (default 3)
 * @returns {{ detected: boolean, reason: string|null, cycleCount: number }}
 */
function detectNoProgress(currentGapIds, iterations = [], threshold = 3) {
  if (!iterations || iterations.length === 0) {
    return { detected: false, reason: null, cycleCount: 0 };
  }
  if (currentGapIds.length === 0) {
    return { detected: false, reason: null, cycleCount: 0 };
  }
  const currentSet = new Set(currentGapIds);
  let cycleCount = 0;
  for (let i = iterations.length - 1; i >= 0; i--) {
    const prev = iterations[i];
    if (!prev || !Array.isArray(prev.goalGapIds)) break;
    const prevSet = new Set(prev.goalGapIds);
    if (
      prevSet.size === currentSet.size &&
      [...currentSet].every((id) => prevSet.has(id))
    ) {
      cycleCount += 1;
    } else {
      break;
    }
  }
  const detected = cycleCount >= threshold;
  return {
    detected,
    reason: detected ? REASON_CODES.NO_PROGRESS_CYCLE_DETECTED : null,
    cycleCount,
  };
}

/**
 * Detect repeated-action: the same actionKey appeared in a previous iteration
 * of this loop run (dedupe signal).
 *
 * Self-match guard: if a prior iteration's proposedAction is the exact same
 * object reference as currentProposedAction (unit-test artifact), skip it.
 * This avoids false positives when the "current action" is manually included
 * in the iterations array for testing purposes.
 * In production, the current action is NOT in the iterations array yet —
 * iterations only contain PRIOR completed iterations.
 *
 * @param {string}          actionKey             - from buildAction().actionKey
 * @param {Array}          iterations           - prior iterations
 * @param {Object|null}    currentProposedAction - current proposed action (self-guard)
 * @returns {{ detected: boolean, previousIterationId: string|null }}
 */
function detectRepeatedAction(actionKey, iterations = [], currentProposedAction = null) {
  if (!actionKey || !iterations || iterations.length === 0) {
    return { detected: false, previousIterationId: null };
  }
  for (let i = iterations.length - 1; i >= 0; i--) {
    const prev = iterations[i];
    if (!prev || !prev.proposedAction) continue;
    // Self-match guard: skip if it's the same object reference as currentProposedAction.
    // In production, currentProposedAction is not in the iterations array at all
    // (iterations only contain PRIOR completed iterations).
    if (currentProposedAction && prev.proposedAction === currentProposedAction) continue;
    if (prev.proposedAction.actionKey === actionKey) {
      return { detected: true, previousIterationId: prev.iterationId || null };
    }
  }
  return { detected: false, previousIterationId: null };
}

/**
 * Detect oscillation: the last two iterations proposed conflicting plan revisions
 * (A then B then A, or same goalGapIds with different proposedAction.toolId).
 * @param {Array} iterations   - previous iterations (most recent last)
 * @param {string} currentToolId - proposed toolId in this iteration
 * @returns {{ detected: boolean, reason: string|null }}
 */
function detectOscillation(iterations = [], currentToolId) {
  if (!iterations || iterations.length < 2) {
    return { detected: false, reason: null };
  }
  const recent = iterations.slice(-2); // last two
  const [prev1, prev2] = recent;
  if (
    prev1?.proposedAction?.actionType === 'plan' &&
    prev2?.proposedAction?.actionType === 'plan'
  ) {
    const sameToolId = prev1.proposedAction.toolId === currentToolId;
    const prev1Has = prev1.proposedAction.params?.toolId || prev1.proposedAction.toolId || null;
    const prev2Has = prev2.proposedAction.params?.toolId || prev2.proposedAction.toolId || null;
    if (prev1Has && prev2Has && prev1Has === prev2Has && sameToolId) {
      return { detected: true, reason: REASON_CODES.PLAN_OSCILLATION_DETECTED };
    }
  }
  return { detected: false, reason: null };
}

// ---------------------------------------------------------------------------
// Validation: check proposed action before execution
// ---------------------------------------------------------------------------

/**
 * Validate a proposed action before it is executed.
 * Returns null if valid; returns an error object if not.
 *
 * @param {Object} action     - built via buildAction()
 * @param {Object} context    - { dag, toolMetadata, runtimeReady }
 * @returns {{ ok: boolean, error: string|null, reasonCode: string|null }}
 */
function validateAction(action, context = {}) {
  if (!action || !action.actionType) {
    return { ok: false, error: 'action_missing', reasonCode: REASON_CODES.INVALID_ARGUMENTS };
  }

  if (action.actionType === 'run_tool') {
    if (!action.toolId || typeof action.toolId !== 'string') {
      return { ok: false, error: 'tool_id_required', reasonCode: REASON_CODES.INVALID_ARGUMENTS };
    }

    // Check inputs completeness
    if (context.dag) {
      const node = (context.dag.nodes || []).find((n) => n.toolId === action.toolId);
      if (node) {
        const missing = (node.requiredInputs || []).filter(
          (inputId) => !action.inputs || !(inputId in action.inputs),
        );
        if (missing.length > 0) {
          return {
            ok: false,
            error: `missing_required_inputs:${missing.join(',')}`,
            reasonCode: REASON_CODES.INPUT_FORMAT_MISMATCH,
          };
        }
      }
    }

    // Check runtime readiness
    if (context.runtimeReady === false) {
      return {
        ok: false,
        error: 'runtime_not_ready',
        reasonCode: REASON_CODES.TOOL_RUNTIME_NOT_READY,
      };
    }

    // Check method applicability
    if (context.dag && action.toolId) {
      const node = (context.dag.nodes || []).find((n) => n.toolId === action.toolId);
      if (node && node.methodNotApplicable) {
        return {
          ok: false,
          error: 'method_not_applicable',
          reasonCode: REASON_CODES.METHOD_NOT_APPLICABLE,
        };
      }
    }
  }

  if (action.actionType === 'wait_for_user') {
    // Always valid
  }

  if (action.actionType === 'cancel') {
    if (!action.reason && !action.params?.reason) {
      return {
        ok: false,
        error: 'cancel_requires_reason',
        reasonCode: REASON_CODES.INVALID_ARGUMENTS,
      };
    }
  }

  return { ok: true, error: null, reasonCode: null };
}

// ---------------------------------------------------------------------------
// Decision: select next action based on observed state + detections
// ---------------------------------------------------------------------------

/**
 * Decide the next action and decision outcome given current state.
 * This is the "brain" — all branching lives here, not in tool executors.
 *
 * Priority order (first match wins):
 *  1. Oscillation detected → block, ask user
 *  2. Repeated action detected → block, return wait
 *  3. Action validation failed → block, report reason
 *  4. All gaps resolved → complete
 *  5. No-progress cycle detected → block, suggest repair
 *  6. User confirmation required → wait_for_user
 *  7. Active jobs running → continue observing
 *  8. Next gap available → propose action
 *  9. No gaps, no action → complete
 *  10. Catch-all → continue
 *
 * @param {Object}  ctx
 * @param {string}  ctx.observedStateDigest
 * @param {Array<string>} ctx.goalGapIds
 * @param {Array}   ctx.iterations    - previous iterations (most recent last)
 * @param {Object}  ctx.loopRunStatus - current loop status
 * @param {Array}   ctx.activeJobs    - currently running tool jobs
 * @param {Object}  ctx.dag           - DAG definition
 * @param {Object}  ctx.toolMetadata  - { toolId → { inputs, readiness } }
 * @param {Object}  ctx.runtimeReady  - boolean
 * @returns {{ decision, decisionReasonCode, proposedAction, publicConclusion }}
 */
function decideNextAction(ctx) {
  const {
    observedStateDigest,
    goalGapIds = [],
    iterations = [],
    loopRunStatus = 'running',
    activeJobs = [],
    dag = null,
    toolMetadata = {},
    runtimeReady = true,
    userConfirmationRequired = false,
    validatorResults = [],
    failedJob = null,
  } = ctx;

  const currentGapSet = new Set(goalGapIds);
  const resolvedGaps = computeResolvedGapIds(goalGapIds, iterations);

  // Oscillation
  const pendingToolId = goalGapIds.length > 0 ? goalGapIds[0] : null;
  const osc = detectOscillation(iterations, pendingToolId);
  if (osc.detected) {
    return {
      decision: 'block',
      decisionReasonCode: osc.reason,
      proposedAction: null,
      publicConclusion:
        '检测到计划振荡（反复尝试同一工具），请确认设计或参数后继续。',
    };
  }

  // Validator results — block on blocked/delivery artifacts before proposing new actions
  if (validatorResults.length > 0 && goalGapIds.length > 0) {
    const blocked = validatorResults.filter((r) => r.status === 'blocked');
    if (blocked.length > 0) {
      const findings = blocked.flatMap((r) => r.findings || []);
      const summary = findings.length > 0
        ? findings.map((f) => f.code).join(', ')
        : `${blocked.length} 个验证器报告 blocked`;
      return {
        decision: 'block',
        decisionReasonCode: REASON_CODES.ARTIFACT_VALIDATION_FAILED,
        proposedAction: null,
        publicConclusion: `验证失败：${summary}。请修复后再继续。`,
      };
    }
    const degraded = validatorResults.filter((r) => r.status === 'degraded');
    if (degraded.length > 0) {
      const summary = degraded.flatMap((r) => r.findings || []).map((f) => f.code).join(', ');
      return {
        decision: 'continue',
        decisionReasonCode: REASON_CODES.ARTIFACT_VALIDATION_WARNING,
        proposedAction: null,
        publicConclusion: `验证警告：${summary}。任务可继续但结果可能受影响。`,
      };
    }
  }

  // HLE-4: Repair decision — classify failure and propose repair action
  // Integration: integration layer passes failedJob when decision='block' from prior iteration
  if (failedJob && (failedJob.status === 'failed' || failedJob.status === 'blocked')) {
    // Import lazily to avoid circular require
    // eslint-disable-next-line @typescript-eslint/no-var-requires
    const { diagnoseFailure } = require('./loop-failure-diagnoser');
    const { selectRepairStrategy } = require('./loop-repair-strategy');

    const diagnosis = diagnoseFailure(failedJob, {
      toolId: failedJob.tool_id || null,
      artifactValidationResults: validatorResults,
    });

    if (diagnosis.defaultBehavior === 'auto_repair' || diagnosis.defaultBehavior === 'auto_retry') {
      const context = {
        parentJobId: failedJob.id || failedJob.tool_job_id || null,
        originalToolId: failedJob.tool_id || null,
        originalParams: failedJob.params || null,
        originalInputs: failedJob.inputs || null,
        parentArtifactIds: failedJob.artifact_ids || [],
        dag,
        fallbackProvider: null,
      };
      const repairAttempt = selectRepairStrategy(diagnosis, context);
      if (repairAttempt && repairAttempt.isActionable) {
        return {
          decision: 'retry',
          decisionReasonCode: REASON_CODES.TRANSIENT_RUNTIME_RETRY,
          proposedAction: repairAttempt.isActionable
            ? buildAction({
                actionType: 'repair',
                toolId: repairAttempt.newToolId || failedJob.tool_id || null,
                inputs: repairAttempt.newInputs,
                params: { ...(repairAttempt.newParams || {}), _repairStrategyId: repairAttempt.strategyId },
              })
            : null,
          publicConclusion: `自动修复（${diagnosis.faultType}）：${repairAttempt.publicMessage}`,
          repairDiagnosis: diagnosis,
          repairAttempt,
        };
      }
    }

    if (diagnosis.defaultBehavior === 'require_user' || diagnosis.defaultBehavior === 'block') {
      return {
        decision: 'block',
        decisionReasonCode: REASON_CODES.TRANSIENT_RUNTIME_RETRY,
        proposedAction: null,
        publicConclusion: `故障类型：${diagnosis.faultType}。${diagnosis.message}。需人工介入。`,
        repairDiagnosis: diagnosis,
      };
    }
  }

  // Repeated action
  if (goalGapIds.length > 0) {
    const proposedAction = buildProposedAction(goalGapIds[0], dag, activeJobs);
    const repeated = detectRepeatedAction(
      proposedAction?.actionKey,
      iterations,
      proposedAction, // pass current action to skip it
    );
    if (repeated.detected) {
      return {
        decision: 'block',
        decisionReasonCode: REASON_CODES.TRANSIENT_RUNTIME_RETRY,
        proposedAction: null,
        publicConclusion:
          `检测到重复工具调用（actionKey=${proposedAction?.actionKey?.slice(0, 8)}…），请检查运行时状态或等待恢复。`,
      };
    }
  }

  // Action validation from previous iteration's attempt
  // (Checked in integration layer before calling decideNextAction again)

  // All gaps resolved
  if (goalGapIds.length === 0) {
    return {
      decision: 'complete',
      decisionReasonCode: REASON_CODES.ALL_NODES_VERIFIED,
      proposedAction: null,
      publicConclusion: '所有 DAG 节点已完成，交付物已就绪。',
    };
  }

  // No-progress cycle
  const noProgress = detectNoProgress(goalGapIds, iterations);
  if (noProgress.detected) {
    return {
      decision: 'block',
      decisionReasonCode: REASON_CODES.NO_PROGRESS_CYCLE_DETECTED,
      proposedAction: null,
      publicConclusion:
        `连续 ${noProgress.cycleCount} 次迭代未推进目标（gap IDs: ${goalGapIds.join(', ')}），请检查参数或设计后继续。`,
    };
  }

  // User confirmation required
  if (userConfirmationRequired) {
    return {
      decision: 'wait',
      decisionReasonCode: REASON_CODES.NORMAL_PLAN_GENERATED,
      proposedAction: buildAction({
        actionType: 'wait_for_user',
        params: { reason: 'user_decision_required', goalGapIds },
      }),
      publicConclusion: '等待用户确认参数或设计。',
    };
  }

  // Active jobs running
  if (activeJobs.length > 0) {
    return {
      decision: 'continue',
      decisionReasonCode: REASON_CODES.TOOL_SUCCEEDED,
      proposedAction: null,
      publicConclusion: `${activeJobs.length} 个任务执行中，等待结果。`,
    };
  }

  // Next gap → propose action
  const firstGap = goalGapIds[0];
  if (firstGap) {
    const proposedAction = buildProposedAction(firstGap, dag, activeJobs);
    const validation = validateAction(proposedAction, { dag, runtimeReady });
    if (!validation.ok) {
      return {
        decision: 'block',
        decisionReasonCode: validation.reasonCode,
        proposedAction: null,
        publicConclusion: `行动验证失败：${validation.error}（${validation.reasonCode}）`,
      };
    }
    return {
      decision: resolvedGaps.length > 0 ? 'continue' : 'continue',
      decisionReasonCode: resolvedGaps.length > 0
        ? REASON_CODES.NORMAL_PLAN_GENERATED
        : REASON_CODES.NORMAL_PLAN_GENERATED,
      proposedAction,
      publicConclusion: `推进目标节点：${firstGap}`,
    };
  }

  // No gap, no action
  return {
    decision: 'complete',
    decisionReasonCode: REASON_CODES.GOAL_ACHIEVED,
    proposedAction: null,
    publicConclusion: '所有目标已完成。',
  };
}

function buildProposedAction(gapId, dag, activeJobs) {
  const node = dag?.nodes?.find((n) => n.id === gapId || n.toolId === gapId);
  const toolId = node?.toolId || gapId;
  const inputs = (node?.inputs || {}) || {};

  return buildAction({
    actionType: node?.actionType || 'run_tool',
    toolId,
    inputs,
    params: { goalGapId: gapId, ...(node?.params || {}) },
    expectedArtifactKinds: node?.expectedArtifactKinds || [],
    attempt: 1,
  });
}

// ---------------------------------------------------------------------------
// Build iteration record — combines observe + decide into a DB-ready record
// ---------------------------------------------------------------------------

/**
 * Build a full iteration record for persistence.
 * Calls loop-contract.js buildIteration() to produce a stable-hashed record.
 *
 * @param {Object} ctx            - same as decideNextAction
 * @param {string} ctx.loopRunId
 * @param {number} ctx.sequence   - 1-based iteration sequence
 * @param {string} [ctx.parentIterationHash]
 * @param {Array}  [ctx.validatorResults] - optional ValidatorResult[] from validateArtifact/validateDelivery
 * @returns {Object} full iteration record (not yet persisted)
 */
function buildControllerIteration(ctx) {
  const {
    loopRunId,
    sequence,
    parentIterationHash = null,
    observedStateDigest,
    goalGapIds = [],
    iterations = [],
    loopRunStatus = 'running',
    activeJobs = [],
    dag = null,
    toolMetadata = {},
    runtimeReady = true,
    userConfirmationRequired = false,
    validatorResults = [],
    failedJob = null,
    costSnapshot = null,
  } = ctx;

  const decision = decideNextAction({
    observedStateDigest,
    goalGapIds,
    iterations,
    loopRunStatus,
    activeJobs,
    dag,
    toolMetadata,
    runtimeReady,
    userConfirmationRequired,
    validatorResults,
    failedJob,
  });

  return buildIteration({
    loopRunId,
    sequence,
    observedStateDigest,
    goalGapIds,
    proposedAction: decision.proposedAction,
    decision: decision.decision,
    decisionReasonCode: decision.decisionReasonCode,
    publicConclusion: decision.publicConclusion,
    status: mapDecisionToIterationStatus(decision.decision),
    parentIterationHash,
    createdAt: new Date().toISOString(),
  }, {
    validatorResults,
    repairAttempt: decision.repairAttempt || null,
    costSnapshot: costSnapshot || null,
  });
}

function mapDecisionToIterationStatus(decision) {
  switch (decision) {
    case 'continue': return 'succeeded';
    case 'retry':    return 'failed';
    case 'block':    return 'blocked';
    case 'wait':     return 'pending';
    case 'complete': return 'succeeded';
    case 'cancel':   return 'skipped';
    default:         return 'pending';
  }
}

// ---------------------------------------------------------------------------
// Evaluate exit — should the loop stop?
// ---------------------------------------------------------------------------

/**
 * Evaluate whether the loop should exit based on current state.
 * Returns { shouldExit, loopStatus, publicConclusion }.
 *
 * @param {Object} ctx
 * @returns {{ shouldExit: boolean, loopStatus: string, publicConclusion: string }}
 */
function evaluateExit(ctx) {
  const { decision, goalGapIds = [], iterations = [], loopRunStatus = 'running' } = ctx;

  if (isTerminalLoopStatus(loopRunStatus)) {
    return {
      shouldExit: true,
      loopStatus: loopRunStatus,
      publicConclusion: 'Loop 已处于终止状态。',
    };
  }

  if (decision === 'complete') {
    return {
      shouldExit: true,
      loopStatus: 'completed',
      publicConclusion: '所有目标节点已完成，Loop 正常结束。',
    };
  }

  if (decision === 'cancel') {
    return {
      shouldExit: true,
      loopStatus: 'cancelled',
      publicConclusion: '用户取消了任务。',
    };
  }

  if (decision === 'block') {
    const noProgress = detectNoProgress(goalGapIds, iterations);
    const osc = detectOscillation(iterations, goalGapIds.length > 0 ? goalGapIds[0] : null);
    if (
      noProgress.detected ||
      osc.detected
    ) {
      return {
        shouldExit: true,
        loopStatus: 'blocked',
        publicConclusion:
          noProgress.detected
            ? `连续 ${noProgress.cycleCount} 次无进展，需人工介入。`
            : '检测到计划振荡，需人工介入。',
      };
    }
    // Other blocks (validation failure) — keep loop alive, wait for user/repair
    return {
      shouldExit: false,
      loopStatus: 'running',
      publicConclusion: '行动验证失败，等待修复或人工决策。',
    };
  }

  return {
    shouldExit: false,
    loopStatus: 'running',
    publicConclusion: 'Loop 继续推进。',
  };
}

// ---------------------------------------------------------------------------
// Reconciliation: reconcile tool job state into observed digest
// ---------------------------------------------------------------------------

/**
 * Reconcile a tool job's result back into the observed state digest.
 * After a job completes, call this to produce the next observed digest
 * that feeds into the next decideNextAction call.
 *
 * @param {string} oldDigest    - digest from before execution
 * @param {Object} job          - tool job row from DB
 * @param {Object} dag         - DAG definition
 * @returns {string} new digest
 */
function reconcileJobResult(oldDigest, job, dag = {}) {
  if (!job) return oldDigest;
  const { id, status, error, finished_at: finishedAt } = job;
  return stableHash({
    prevDigest: oldDigest,
    jobSummary: {
      id,
      status,
      error: error ? 'has_error' : 'no_error',
      finished: finishedAt ? 'finished' : 'incomplete',
    },
  });
}

// ---------------------------------------------------------------------------
// Provider-safe structured decision — for MCP/agent consumption
// ---------------------------------------------------------------------------

/**
 * Build a Provider-safe structured decision object (safe to send to LLM).
 * Contains no internal IDs, no raw stack traces, no API keys.
 *
 * @param {Object} iteration  - from buildControllerIteration
 * @returns {Object} sanitized decision
 */
function toStructuredDecision(iteration) {
  if (!iteration) return null;
  return {
    decision: iteration.decision,
    reasonCode: iteration.decisionReasonCode,
    publicConclusion: redactSensitiveValue(iteration.publicConclusion || ''),
    proposedAction: iteration.proposedAction
      ? {
          actionType: iteration.proposedAction.actionType,
          toolId: iteration.proposedAction.toolId,
          expectedArtifactKinds: iteration.proposedAction.expectedArtifactKinds,
          attempt: iteration.proposedAction.attempt,
          // Never expose actionKey or raw inputs/params to Provider
        }
      : null,
    iterationId: iteration.iterationId,
    sequence: iteration.sequence,
    hash: iteration.hash,
  };
}

module.exports = {
  TOOL_STATES,
  deriveObservedStateDigest,
  deriveJobsDigest,
  deriveProgressDigest,
  computeGoalGapIds,
  computeResolvedGapIds,
  detectNoProgress,
  detectRepeatedAction,
  detectOscillation,
  validateAction,
  decideNextAction,
  buildProposedAction,
  buildControllerIteration,
  buildAction,
  mapDecisionToIterationStatus,
  evaluateExit,
  reconcileJobResult,
  toStructuredDecision,
};

'use strict';

/**
 * Loop Failure Diagnoser v1 — classifies tool_job failures into stable fault types.
 *
 * Pure functions: no I/O, no DB, no network.
 *
 * HLE-4 scope:
 *  - Classify a failed tool_job + error into one of 10 fault types.
 *  - Attach machine-readable code, human message, evidence, and suggested repair strategies.
 *  - Each classification is deterministic: same inputs → same output.
 *
 * NOT in scope:
 *  - Actually executing repair strategies (live in integration layer)
 *  - Provider-level retry logic (live in agent-runner)
 *  - Capability provisioning (live in capability-provisioning.js)
 *
 * Integration:
 *  - Integration layer calls diagnoseFailure(job, context) after tool execution fails.
 *  - Result drives RepairStrategy selection in loop-repair-strategy.js.
 *  - Diagnosed type is stored as LoopEvidence (kind: 'failure_diagnosis').
 */

const {
  REASON_CODES,
} = require('./loop-contract');

// ---------------------------------------------------------------------------
// Fault type definitions
// ---------------------------------------------------------------------------

/**
 * All 10 fault types with their default behavior and suggested strategies.
 * Keyed by lowercase faultType for O(1) lookup.
 */
const FAULT_TYPES = {
  transient_runtime: {
    faultType: 'transient_runtime',
    defaultBehavior: 'auto_retry',
    repairStrategies: ['retry_with_reconcile', 'retry_same_params'],
    message: 'Temporary runtime condition (file lock, brief process error)',
  },
  transient_provider: {
    faultType: 'transient_provider',
    defaultBehavior: 'auto_retry',
    repairStrategies: ['provider_backoff_retry', 'fallback_provider'],
    message: 'Transient provider condition (rate limit, gateway timeout, connection reset)',
  },
  invalid_arguments: {
    faultType: 'invalid_arguments',
    defaultBehavior: 'auto_repair',
    repairStrategies: ['fix_schema_violation', 'fix_enum_or_range'],
    message: 'Invalid tool arguments (schema violation, out-of-range, wrong type)',
  },
  input_format: {
    faultType: 'input_format',
    defaultBehavior: 'auto_repair',
    repairStrategies: ['transform_input_format', 'validate_input_schema'],
    message: 'Input file format problem (column name mismatch, encoding, matrix orientation)',
  },
  runtime_not_ready: {
    faultType: 'runtime_not_ready',
    defaultBehavior: 'auto_repair',
    repairStrategies: ['ensure_capability', 'provision_runtime'],
    message: 'Runtime or capability not ready (R/Python missing, package absent)',
  },
  artifact_invalid: {
    faultType: 'artifact_invalid',
    defaultBehavior: 'auto_repair',
    repairStrategies: ['rerun_upstream', 'reconcile_artifact', 'repair_artifact_content'],
    message: 'Artifact validation failed (missing file, wrong hash, invalid structure)',
  },
  method_not_applicable: {
    faultType: 'method_not_applicable',
    defaultBehavior: 'require_user',
    repairStrategies: ['replan_subgraph', 'compare_method_candidates'],
    message: 'Method preconditions not met (requires redesign or alternative)',
  },
  user_input_required: {
    faultType: 'user_input_required',
    defaultBehavior: 'require_user',
    repairStrategies: ['ask_user_design'],
    message: 'Blocked pending user input',
  },
  resource_pressure: {
    faultType: 'resource_pressure',
    defaultBehavior: 'auto_repair',
    repairStrategies: ['reduce_resource_request', 'chunk_workflow', 'suggest_alternative'],
    message: 'Resource constraint (memory, disk, or compute risk)',
  },
  external_side_effect: {
    faultType: 'external_side_effect',
    defaultBehavior: 'block',
    repairStrategies: ['require_user_authorization'],
    message: 'External side effect attempted (upload, publish, paid operation outside workspace)',
  },
};

Object.freeze(FAULT_TYPES);

// ---------------------------------------------------------------------------
// Diagnosis rules — pattern matching on error + reason code
// ---------------------------------------------------------------------------

/**
 * Pattern: [regexOrString, faultType, extraStrategies[], message]
 * Evaluated in order; first match wins.
 */
const DIAGNOSIS_RULES = [
  // TRANSIENT_RUNTIME
  [/ENOENT|no such file|file not found/i, 'transient_runtime', ['validate_input_schema'], 'File not found during execution'],
  [/ETXTBSY|text file busy/i, 'transient_runtime', ['retry_with_reconcile'], 'Text file busy — temporary lock'],
  [/EBUSY|resource busy/i, 'transient_runtime', ['retry_with_reconcile'], 'Resource busy — temporary lock'],
  [/EAGAIN|resource temporarily unavailable/i, 'transient_runtime', ['retry_same_params'], 'Temporary resource unavailable'],
  [/child process exited with code (1|2|127)/i, 'transient_runtime', ['retry_with_reconcile'], 'Child process failed'],

  // TRANSIENT_PROVIDER
  [/429|rate.limit|too many requests/i, 'transient_provider', ['provider_backoff_retry'], 'Provider rate limit hit'],
  [/502|503|504|gateway.timeout|bad gateway|service unavailable/i, 'transient_provider', ['provider_backoff_retry', 'fallback_provider'], 'Provider gateway error'],
  [/connection reset|connection refused|ECONNRESET|ECONNREFUSED/i, 'transient_provider', ['provider_backoff_retry', 'fallback_provider'], 'Connection error to provider'],
  [/timeout|timed.out|ETIMEDOUT/i, 'transient_provider', ['provider_backoff_retry'], 'Provider request timed out'],
  [/upstream connect error|handshake failed/i, 'transient_provider', ['provider_backoff_retry'], 'Provider handshake/connect error'],

  // INVALID_ARGUMENTS — more specific patterns before broader ones
  [REASON_CODES.INVALID_ARGUMENTS, 'invalid_arguments', [], 'Argument validation failed'],
  [/missing required argument|required.*argument|argument.*required/i, 'invalid_arguments', ['fix_schema_violation'], 'Missing required argument'],
  [/invalid type|type mismatch(?!.*matrix)/i, 'invalid_arguments', ['fix_schema_violation'], 'Invalid argument type'],
  [/out of range|not in allowed values/i, 'invalid_arguments', ['fix_enum_or_range'], 'Out-of-range or invalid enum'],
  [/enumerated value.*not allowed|value.*not in enum/i, 'invalid_arguments', ['fix_enum_or_range'], 'Invalid enumerated value'],

  // INPUT_FORMAT — before INVALID_ARGUMENTS broad patterns
  [REASON_CODES.INPUT_FORMAT_MISMATCH, 'input_format', [], 'Input format mismatch'],
  [/column.*not found|missing column|no such column/i, 'input_format', ['transform_input_format'], 'Required input column missing'],
  [/encoding error|invalid utf|byte.*invalid/i, 'input_format', ['transform_input_format'], 'File encoding error'],
  [/dimension mismatch|expected matrix|rows.*columns.*mismatch/i, 'input_format', ['transform_input_format'], 'Matrix dimension mismatch'],

  // RUNTIME_NOT_READY
  [REASON_CODES.TOOL_RUNTIME_NOT_READY, 'runtime_not_ready', [], 'Runtime not ready'],
  [/package.*not found|no package|namespace.*not loaded/i, 'runtime_not_ready', ['ensure_capability'], 'R/Python package not installed'],
  [/\binterpreter not found|\bR\b.*not found|\bPython\b.*not found/i, 'runtime_not_ready', ['provision_runtime'], 'Language interpreter not available'],
  [/capability.*not ready|capability.*missing/i, 'runtime_not_ready', ['ensure_capability'], 'Required capability not ready'],

  // ARTIFACT_INVALID — more specific before runtime_not_ready (both have "not found")
  [REASON_CODES.ARTIFACT_VALIDATION_FAILED, 'artifact_invalid', [], 'Artifact validation failed'],
  [/artifact.*not found|artifact.*missing|cannot find artifact/i, 'artifact_invalid', ['reconcile_artifact', 'rerun_upstream'], 'Artifact referenced but not found'],
  [/hash mismatch|sha256.*mismatch|checksum.*fail/i, 'artifact_invalid', ['reconcile_artifact'], 'Artifact hash mismatch'],
  [/required artifact missing/i, 'artifact_invalid', ['rerun_upstream'], 'Required artifact missing'],

  // METHOD_NOT_APPLICABLE
  [REASON_CODES.METHOD_NOT_APPLICABLE, 'method_not_applicable', [], 'Method not applicable'],
  [/method.*precondition|precondition.*not met|assumptions.*violated/i, 'method_not_applicable', ['compare_method_candidates'], 'Method preconditions not met'],
  [/insufficient.*(samples|data|replicates|cells)|not enough.*(data|samples|replicates)|requires.*(samples|cells|replicates)/i, 'method_not_applicable', ['replan_subgraph'], 'Insufficient data for method'],

  // USER_INPUT_REQUIRED（原 SCIENTIFIC_DESIGN_MISSING，BLOCK-83 D12 中性化）
  [REASON_CODES.USER_INPUT_REQUIRED, 'user_input_required', [], 'Scientific design ambiguous'],
  [/contrast.*not specified|contrast.*missing|define.*contrast/i, 'user_input_required', ['ask_user_design'], 'Contrast not specified'],
  [/batch.*effect|batch.*confound|paired.*missing/i, 'user_input_required', ['ask_user_design'], 'Batch effect or pairing design ambiguous'],

  // RESOURCE_PRESSURE
  [/out of memory|OOM|memory limit|killed.*memory/i, 'resource_pressure', ['reduce_resource_request', 'chunk_workflow'], 'Out of memory'],
  [/disk full|no space left|ENOSPC/i, 'resource_pressure', ['reduce_resource_request'], 'Disk space exhausted'],
  [/CPU limit|cpu.*exceeded|process.*timeout/i, 'resource_pressure', ['chunk_workflow', 'suggest_alternative'], 'CPU or time limit exceeded'],

  // EXTERNAL_SIDE_EFFECT
  [/upload.*blocked|download.*blocked|external.*write/i, 'external_side_effect', ['require_user_authorization'], 'External operation attempted'],
  [/paid.*operation|billing.*error|charge.*failed/i, 'external_side_effect', ['require_user_authorization'], 'Paid operation attempted'],
];

// ---------------------------------------------------------------------------
// Main diagnosis function
// ---------------------------------------------------------------------------

/**
 * Classify a tool_job failure into a fault type.
 *
 * @param {Object} job
 * @param {Object} [context]
 * @param {string} [context.error]    - error message override
 * @param {string} [context.toolId]    - tool ID for additional context
 * @param {Array}  [context.artifactValidationResults] - ValidatorResult[] from HLE-3
 * @returns {Object} diagnosis result
 */
function diagnoseFailure(job, context = {}) {
  const jobError = job?.error || context.error || '';
  const reasonCode = job?.reason_code || job?.failure_reason_code || context.reasonCode || null;
  const toolId = job?.tool_id || context.toolId || null;

  // Step 1: Reason code mapping (highest priority — explicit codes are deterministic)
  if (reasonCode) {
    const mapped = mapReasonCodeToFaultType(reasonCode, jobError, context);
    if (mapped) return mapped;
  }

  // Step 2: Artifact validation results (HLE-3 integration)
  if (context.artifactValidationResults && context.artifactValidationResults.length > 0) {
    const avResult = diagnoseFromValidationResults(context.artifactValidationResults);
    if (avResult) return avResult;
  }

  // Step 3: Pattern matching on error string
  for (const rule of DIAGNOSIS_RULES) {
    const [pattern, faultType, extraStrategies, message] = rule;
    const matches = typeof pattern === 'string'
      ? jobError.includes(pattern)
      : pattern.test(jobError);

    if (matches) {
      const ft = FAULT_TYPES[faultType];
      if (!ft) continue; // should not happen
      return buildDiagnosis({
        faultType,
        defaultBehavior: ft.defaultBehavior,
        strategies: [...ft.repairStrategies, ...(extraStrategies || [])],
        message: message || ft.message,
        reasonCode,
        jobError,
        toolId,
        classificationMethod: 'pattern_match',
        confidence: classifyConfidence(faultType, jobError),
      });
    }
  }

  // Step 4: Fallback
  return buildDiagnosis({
    faultType: 'unknown_failure',
    defaultBehavior: 'require_user',
    strategies: ['ask_user_design'],
    message: `Unknown failure: ${truncate(jobError, 100)}`,
    reasonCode,
    jobError,
    toolId,
    classificationMethod: 'fallback',
    confidence: 0.1,
  });
}

/**
 * Map explicit REASON_CODEs to fault types deterministically.
 */
function mapReasonCodeToFaultType(reasonCode, error, context) {
  const map = {
    [REASON_CODES.INVALID_ARGUMENTS]: 'invalid_arguments',
    [REASON_CODES.INPUT_FORMAT_MISMATCH]: 'input_format',
    [REASON_CODES.TOOL_RUNTIME_NOT_READY]: 'runtime_not_ready',
    [REASON_CODES.TRANSIENT_RUNTIME_RETRY]: 'transient_runtime',
    [REASON_CODES.ARTIFACT_VALIDATION_FAILED]: 'artifact_invalid',
    [REASON_CODES.METHOD_NOT_APPLICABLE]: 'method_not_applicable',
    [REASON_CODES.USER_INPUT_REQUIRED]: 'user_input_required',
    // 存量兼容：BLOCK-83 之前持久化的任务记录仍带旧值。
    SCIENTIFIC_DESIGN_MISSING: 'user_input_required',
  };

  const faultType = map[reasonCode];
  if (!faultType) return null;

  const ft = FAULT_TYPES[faultType];
  if (!ft) return null; // should not happen

  return buildDiagnosis({
    faultType,
    defaultBehavior: ft.defaultBehavior,
    strategies: ft.repairStrategies,
    message: `${ft.message} (reasonCode: ${reasonCode})`,
    reasonCode,
    jobError: error,
    toolId: context.toolId || null,
    classificationMethod: 'reason_code',
    confidence: 1.0,
  });
}

/**
 * Diagnose from HLE-3 validator results embedded in context.
 */
function diagnoseFromValidationResults(validatorResults) {
  if (!validatorResults || validatorResults.length === 0) return null;

  const blocked = validatorResults.filter((r) => r.status === 'blocked');
  const unavailable = validatorResults.filter((r) => r.status === 'unavailable');

  if (blocked.some((r) => r.validatorId === 'input-snapshot')) {
    return buildDiagnosis({
      faultType: 'artifact_invalid',
      defaultBehavior: 'auto_repair',
      strategies: ['reconcile_artifact'],
      message: 'Input artifact file missing or invalid (input-snapshot validator)',
      classificationMethod: 'validator_result',
      confidence: 0.95,
    });
  }
  if (blocked.some((r) => r.validatorId === 'counts-matrix')) {
    return buildDiagnosis({
      faultType: 'input_format',
      defaultBehavior: 'auto_repair',
      strategies: ['transform_input_format'],
      message: 'Counts matrix structure invalid (counts-matrix validator)',
      classificationMethod: 'validator_result',
      confidence: 0.9,
    });
  }
  if (blocked.some((r) => r.validatorId === 'de-results')) {
    return buildDiagnosis({
      faultType: 'method_not_applicable',
      defaultBehavior: 'require_user',
      strategies: ['replan_subgraph', 'compare_method_candidates'],
      message: 'DE results invalid — method preconditions may not be met',
      classificationMethod: 'validator_result',
      confidence: 0.8,
    });
  }
  if (blocked.some((r) => r.validatorId === 'delivery-integrity')) {
    return buildDiagnosis({
      faultType: 'artifact_invalid',
      defaultBehavior: 'auto_repair',
      strategies: ['rerun_upstream'],
      message: 'Delivery manifest incomplete — upstream artifacts missing',
      classificationMethod: 'validator_result',
      confidence: 0.95,
    });
  }
  if (unavailable.length > 0 && blocked.length === 0) {
    return buildDiagnosis({
      faultType: 'unknown_failure',
      defaultBehavior: 'require_user',
      strategies: ['ask_user_design'],
      message: 'Validation unavailable — cannot determine root cause',
      classificationMethod: 'validator_result',
      confidence: 0.3,
    });
  }
  return null;
}

/**
 * Build a diagnosis result object.
 */
function buildDiagnosis({ faultType, defaultBehavior, strategies, message, reasonCode, jobError, toolId, classificationMethod, confidence }) {
  const findings = [];
  if (jobError) findings.push({ code: 'ERROR_MESSAGE', message: truncate(jobError, 200), severity: 'error' });
  if (reasonCode) findings.push({ code: 'REASON_CODE', message: reasonCode, severity: 'warning' });
  if (toolId) findings.push({ code: 'TOOL_ID', message: toolId, severity: 'info' });

  return Object.freeze({
    faultType,
    defaultBehavior,
    repairStrategies: Object.freeze([...(new Set(strategies))]), // dedupe
    message,
    classificationMethod,
    confidence: Math.max(0, Math.min(1, confidence)),
    findings: Object.freeze(findings),
    reasonCode: reasonCode || null,
  });
}

/**
 * Classify confidence based on fault type and error characteristics.
 */
function classifyConfidence(faultType, error) {
  if (faultType === 'unknown_failure') return 0.1;
  if (faultType === 'external_side_effect') return 0.95;
  if (/timeout|rate.limit|429|502|503|504/i.test(error)) return 0.9;
  if (/memory|killed|OOM|ENOSPC/i.test(error)) return 0.95;
  if (/not found|ENOENT/i.test(error)) return 0.7;
  return 0.6;
}

/**
 * Truncate a string to maxLen.
 */
function truncate(str, maxLen) {
  if (!str || str.length <= maxLen) return str;
  return str.slice(0, maxLen) + '…';
}

/**
 * List all known fault types.
 */
function listFaultTypes() {
  return Object.values(FAULT_TYPES).map((ft) => ({
    faultType: ft.faultType,
    defaultBehavior: ft.defaultBehavior,
    repairStrategies: ft.repairStrategies,
    message: ft.message,
  }));
}

/**
 * Get a fault type definition.
 */
function getFaultType(faultType) {
  return FAULT_TYPES[faultType] || null;
}

module.exports = {
  FAULT_TYPES,
  diagnoseFailure,
  mapReasonCodeToFaultType,
  diagnoseFromValidationResults,
  listFaultTypes,
  getFaultType,
  classifyConfidence,
};

'use strict';

/**
 * Loop Repair Strategy v1 — lineage-safe repair planning from diagnosed failures.
 *
 * Pure functions: no I/O, no DB, no network.
 *
 * HLE-4 scope:
 *  - selectRepairStrategy() — pick best repair strategy from diagnosis + context
 *  - buildRepairAttempt() — produce a repair plan with parent lineage preserved
 *  - 12 repair strategies with applicability rules, cost estimates, and safety levels
 *
 * NOT in scope:
 *  - Actually executing repair actions (live in integration layer)
 *  - User authorization for unsafe strategies (handled by integration layer)
 *  - Scientific design questions (delegated to user via wait_for_user)
 *
 * Key invariants:
 *  - Original script/params/artifact are NEVER mutated
 *  - Every repair creates a new Job version with parent reference
 *  - Invalidation boundaries mark what changed
 *  - Unsafe strategies require explicit user authorization
 *  - Scientific design changes never bypass user confirmation
 *
 * Integration contract:
 *  - Integration layer calls diagnoseFailure() first
 *  - Then calls selectRepairStrategy() with diagnosis + context
 *  - Then calls buildRepairAttempt() to produce repair plan
 *  - Repair plan is stored as LoopEvidence (kind: 'repair_attempt')
 *  - Integration layer decides whether to auto-proceed or wait for user
 */

const { REASON_CODES } = require('./loop-contract');

// ---------------------------------------------------------------------------
// HLE-C5R: Strict Repair Boundary
// Defines what automatic repair CAN and CANNOT do.
// These rules are enforced BEFORE any isActionable check.
// ---------------------------------------------------------------------------

/**
 * Explicit ALLOWED automatic repair actions (safe parameter/infrastructure fixes).
 * Anything not on this list requires explicit user authorization or is blocked.
 */
const REPAIR_BOUNDARY_ALLOW = new Set([
  // Safe automatic repairs (deterministic, non-destructive)
  'metadata_to_coldata_mapping',     // metadata.csv → coldata parameter alias
  'column_name_mapping',             // known alias mapping (log2FC → log2FoldChange)
  'path_resolution',                  // relative → absolute path within project
  'runtime_readiness',               // R/Python/package missing → provisioning
  'retry_same_params',               // transient failure, same params
  'retry_with_reconcile',            // transient + state reconciliation
  'provider_backoff_retry',         // rate limit, exponential backoff
  'fix_schema_violation',            // missing optional field with known default
  'fix_enum_or_range',               // enum/range fix from known valid values
  'transform_input_format',           //无损格式转换（TSV↔CSV、编码）
  'ensure_capability',               // bundle/capability provisioning
  'rerun_upstream',                  // upstream failed, rerun first verified node
  'reduce_resource_request',         // OOM/disk-full: lower resource request (safe)
  'chunk_workflow',                  // split large workflow into smaller chunks
]);

/**
 * EXPLICITLY BLOCKED automatic repair actions.
 * These require explicit user authorization or must block.
 * No strategy may set isActionable=true for these fault types.
 */
const REPAIR_BOUNDARY_BLOCK = new Set([
  // Data fabrication — NEVER auto-generate data
  'fabricate_gene_data',             // adding genes to make results significant
  'fabricate_sample_data',            // creating fake samples
  'pad_data_to_reach_threshold',      // padding data to reach minimum counts

  // Scientific design changes
  'change_contrast',                 // modifying comparison groups
  'change_design_formula',           // changing statistical model
  'change_statistical_method',       // DESeq2 → limma without user consent
  'downgrade_significance_threshold', // lowering padj cutoff to get sig results
  'change_p_value_adjustment',       // BH → Bonferroni without user consent

  // Data manipulation
  'delete_outlier_samples',          // removing "bad" samples to improve results
  'impute_missing_values',           // filling in data without user consent
  'filter_genes_to_subset',         // narrowing gene set to make results look better

  // Plugin source modification
  'modify_plugin_source',            // changing plugin R/Python scripts
  'inject_workspace_external',        // writing outside project directory
  'suppress_validation_error',       // hiding validator failures

  // Irreversible operations
  'delete_artifacts',                // deleting existing results
  'overwrite_input_hash',           // modifying source data hash
  'replay_with_modified_params',    // rerunning with undeclared parameter changes
]);

/**
 * Check if a strategyId or faultType is allowed for automatic repair.
 * @returns {{ allowed: boolean, reason?: string }}
 */
function repairBoundaryCheck(strategyId, faultType, actionDescription) {
  // HLE-C5R: 需用户输入时禁止数据/方法被自动修改（BLOCK-83 D12 中性化 faultType）
  if (faultType === 'user_input_required') {
    const prohibited = [
      'replan_subgraph',       // changes contrast/method
      'substitute_data',       // generates/replaces data
      'padj_threshold_relax',  // lowers thresholds
      'lfc_threshold_relax',   // adjusts fold change
      'delete_outliers',       // removes samples
      'add_samples',           // adds synthetic data
      'augment_samples',       // modifies sample counts
      'method_substitution',    // swaps statistical method
    ];
    if (prohibited.includes(strategyId)) {
      return {
        allowed: false,
        reason: `Scientific design/contrast decision requires user. Strategy '${strategyId}' would modify scientific method or data.`,
        blockedStrategy: strategyId,
      };
    }
  }

  // Block explicitly forbidden strategies or fault types
  if (REPAIR_BOUNDARY_BLOCK.has(strategyId) || REPAIR_BOUNDARY_BLOCK.has(faultType)) {
    return {
      allowed: false,
      reason: `Repair boundary block: strategy '${strategyId}' or fault '${faultType}' is explicitly forbidden for automatic repair. Requires user authorization.`,
    };
  }
  // Strategy must be in allow list
  if (!REPAIR_BOUNDARY_ALLOW.has(strategyId)) {
    return {
      allowed: false,
      reason: `Repair boundary: strategy '${strategyId}' is not on the automatic repair allowlist. Requires user authorization.`,
    };
  }
  return { allowed: true };
}

