'use strict';

/**
 * Loop Validator Registry v1 — centralized artifact and delivery verification.
 *
 * Pure functions: no I/O, no DB, no network.
 * All actual validation logic lives in registered validator functions.
 *
 * HLE-3 scope:
 *  - Validator Contract: four-state result (valid / degraded / blocked / unavailable)
 *  - Registry: register / dispatch / list / versioned resolution
 *  - Plugin hook: connect manifest fields to module-specific validators
 *  - Built-in validators: input-snapshot, metadata, counts-matrix, DE-table,
 *    heatmap-data, enrichment-statistics, delivery-integrity
 *  - Hook into Loop Controller: after tool execution, validators run before
 *    iteration completes; results feed into loop's evidence/decision
 *
 * NOT in scope:
 *  - Actually executing validators (tool_executor lives in petri-server)
 *  - Writing validator results to DB (done by integration layer)
 *  - Replacing existing artifact-truth.js (different concern: tool execution vs loop evidence)
 *
 * Integration contract:
 *  - After tool execution completes, integration layer calls:
 *      validateArtifact(artifact, context) → ValidatorResult
 *      validateDelivery(deliveryRecord) → ValidatorResult
 *  - Results are appended as LoopEvidence and feed into Loop Controller's
 *    evaluateExit() for completion decision.
 */

const { stableHash, redactSensitiveValue } = require('./loop-contract');

// ---------------------------------------------------------------------------
// Validator result contract
// ---------------------------------------------------------------------------

/**
 * @typedef {Object} ValidatorFinding
 * @property {string} code       - Machine-readable finding code (e.g. 'COLUMN_COUNT_MISMATCH')
 * @property {string} message   - Human-readable message (may be shown to user)
 * @property {'error'|'warning'} severity
 * @property {Object} [context] - Additional structured context
 */

/**
 * @typedef {Object} ValidatorResult
 * @property {'valid'|'degraded'|'blocked'|'unavailable'} status
 * @property {string} validatorId
 * @property {string} version
 * @property {string[]} applicableKinds   - artifact kinds this validator handles
 * @property {string[]} findings
 * @property {string} [detail]   - Optional explanation for degraded/blocked
 */

/**
 * @typedef {Object} ValidationContext
 * @property {Object} artifact       - The artifact being validated
 * @property {Object} [jobRecord]   - Tool job record (if available)
 * @property {Object} [provenance]  - Provenance record (if available)
 * @property {Object} [dagNode]    - DAG node definition (toolId, inputs, etc.)
 * @property {Object} [toolMetadata] - Tool capability metadata
 */

// ---------------------------------------------------------------------------
// Validator types
// ---------------------------------------------------------------------------

const VALIDATOR_TYPES = Object.freeze({
  INPUT_SNAPSHOT: 'input-snapshot',
  ARTIFACT_SCHEMA: 'artifact-schema',
  DELIVERY_INTEGRITY: 'delivery-integrity',
  STATISTICAL: 'statistical',
  SCIENTIFIC: 'scientific',
  LINEAGE: 'lineage',
});

const VALIDATOR_STATUSES = Object.freeze({
  VALID: 'valid',
  DEGRADED: 'degraded',
  BLOCKED: 'blocked',
  UNAVAILABLE: 'unavailable',
});

const FINDING_SEVERITIES = Object.freeze({
  ERROR: 'error',
  WARNING: 'warning',
});

// ---------------------------------------------------------------------------
// Internal registry
// ---------------------------------------------------------------------------

const _registry = new Map();
let _pluginHooks = [];

/**
 * Register a validator.
 *
 * @param {Object} def
 * @param {string} def.id            - Unique validator ID (e.g. 'counts-matrix')
 * @param {string} def.name          - Display name
 * @param {string} def.version       - Semantic version
 * @param {string} def.type          - One of VALIDATOR_TYPES
 * @param {string[]} def.applicableKinds - Artifact kinds (e.g. ['table', 'json'])
 * @param {Function} def.validate    - (artifact, context) => ValidatorResult
 * @param {Object} [def.pluginManifest] - Optional plugin manifest to link
 */
function registerValidator(def) {
  if (!def || typeof def.id !== 'string' || !def.id) {
    throw new TypeError('validator.id must be a non-empty string');
  }
  if (!def.version || typeof def.version !== 'string') {
    throw new TypeError('validator.version must be a non-empty string');
  }
  if (!Array.isArray(def.applicableKinds) || def.applicableKinds.length === 0) {
    throw new TypeError('validator.applicableKinds must be a non-empty array');
  }
  if (typeof def.validate !== 'function') {
    throw new TypeError('validator.validate must be a function');
  }

  const entry = {
    id: def.id,
    name: def.name || def.id,
    version: def.version,
    type: def.type || VALIDATOR_TYPES.ARTIFACT_SCHEMA,
    applicableKinds: Object.freeze([...def.applicableKinds]),
    applicableArtifactTypes: Object.freeze([...(def.applicableArtifactTypes || [])]),
    pluginManifest: def.pluginManifest || null,
    validate: def.validate,
    enabled: def.enabled !== false,
    priority: typeof def.priority === 'number' ? def.priority : 0,
  };

  _registry.set(def.id, entry);
  return def.id;
}

/**
 * Override the enabled state of a validator.
 * @param {string} validatorId
 * @param {boolean} enabled
 */
function setValidatorEnabled(validatorId, enabled) {
  const entry = _registry.get(validatorId);
  if (!entry) return false;
  entry.enabled = !!enabled;
  return true;
}

/**
 * Dispatch a validator by ID.
 * @param {string} validatorId
 * @param {ValidationContext} context
 * @returns {ValidatorResult|null}
 */
function dispatchValidator(validatorId, context) {
  const entry = _registry.get(validatorId);
  if (!entry || !entry.enabled) return null;
  try {
    return entry.validate(context.artifact, context);
  } catch (err) {
    return buildUnavailableResult(validatorId, entry.version, String(err.message));
  }
}

/**
 * Find validators applicable to an artifact by kind.
 * @param {string} artifactKind
 * @returns {Object[]} sorted by priority DESC
 */
function findValidatorsForKind(artifactKind) {
  if (!artifactKind) return [];
  const kind = String(artifactKind).toLowerCase();
  return [..._registry.values()]
    .filter((e) => e.enabled && e.applicableKinds.map((k) => String(k).toLowerCase()).includes(kind))
    .sort((a, b) => b.priority - a.priority);
}

/**
 * Find validators applicable to an artifact by type.
 * @param {string} artifactType
 * @returns {Object[]}
 */
function findValidatorsForType(artifactType) {
  if (!artifactType) return [];
  const type = String(artifactType).toLowerCase();
  return [..._registry.values()]
    .filter((e) => e.enabled && e.applicableArtifactTypes.map((t) => String(t).toLowerCase()).includes(type))
    .sort((a, b) => b.priority - a.priority);
}

/**
 * Validate an artifact against all applicable validators.
 * Returns an aggregate result.
 *
 * @param {Object} artifact
 * @param {ValidationContext} context
 * @returns {{ results: ValidatorResult[], overallStatus: string }}
 */
function validateArtifact(artifact, context = {}) {
  if (!artifact || typeof artifact !== 'object') {
    return {
      results: [],
      overallStatus: VALIDATOR_STATUSES.UNAVAILABLE,
      findings: [{ code: 'ARTIFACT_MISSING', message: 'No artifact provided', severity: 'error' }],
    };
  }

  const kind = String(artifact.kind || artifact.type || '').toLowerCase();
  const type = String(artifact.type || '').toLowerCase();
  const validators = [
    ...findValidatorsForKind(kind),
    ...findValidatorsForType(type),
  ].filter((v, i, arr) => arr.findIndex((x) => x.id === v.id) === i); // dedupe

  if (validators.length === 0) {
    return {
      results: [],
      overallStatus: VALIDATOR_STATUSES.UNAVAILABLE,
      findings: [{ code: 'NO_APPLICABLE_VALIDATOR', message: `No validator for kind=${kind}`, severity: 'warning' }],
    };
  }

  const results = [];
  for (const validator of validators) {
    const result = dispatchValidator(validator.id, { ...context, artifact });
    if (result) results.push(result);
  }

  const findings = results.flatMap((r) => r.findings || []);
  const overallStatus = aggregateStatus(results.map((r) => r.status));

  return { results, overallStatus, findings };
}

/**
 * Validate a delivery record (delivery manifest / task completion).
 * @param {Object} deliveryRecord
 * @returns {ValidatorResult}
 */
function validateDelivery(deliveryRecord) {
  const validatorId = 'delivery-integrity';
  const entry = _registry.get(validatorId);
  if (!entry || !entry.enabled) {
    return buildUnavailableResult(validatorId, '1.0.0', 'delivery-integrity validator not registered');
  }
  try {
    return entry.validate(deliveryRecord, {});
  } catch (err) {
    return buildUnavailableResult(validatorId, entry.version, String(err.message));
  }
}

/**
 * Aggregate a list of statuses into a single status.
 * blocked > degraded > valid > unavailable
 *
 * @param {string[]} statuses
 * @returns {string}
 */
function aggregateStatus(statuses) {
  if (!statuses || statuses.length === 0) return VALIDATOR_STATUSES.UNAVAILABLE;
  if (statuses.includes(VALIDATOR_STATUSES.BLOCKED)) return VALIDATOR_STATUSES.BLOCKED;
  if (statuses.includes(VALIDATOR_STATUSES.DEGRADED)) return VALIDATOR_STATUSES.DEGRADED;
  // VALID > UNAVAILABLE: if all statuses are VALID or UNAVAILABLE → VALID
  if (statuses.every((s) => s === VALIDATOR_STATUSES.VALID || s === VALIDATOR_STATUSES.UNAVAILABLE)) {
    return statuses.includes(VALIDATOR_STATUSES.VALID) ? VALIDATOR_STATUSES.VALID : VALIDATOR_STATUSES.UNAVAILABLE;
  }
  return VALIDATOR_STATUSES.UNAVAILABLE;
}

// ---------------------------------------------------------------------------
// Result builders
// ---------------------------------------------------------------------------

function buildResult({ validatorId, version = '1.0.0', status, findings = [], detail = null }) {
  const findingsArray = findings.map(normalizeFinding);
  return Object.freeze({
    validatorId,
    version,
    status,
    findings: Object.freeze(findingsArray),
    detail: detail ? redactSensitiveValue(detail) : null,
  });
}

function buildUnavailableResult(validatorId, version, reason) {
  return buildResult({
    validatorId,
    version,
    status: VALIDATOR_STATUSES.UNAVAILABLE,
    findings: [
      {
        code: 'VALIDATOR_UNAVAILABLE',
        message: String(reason),
        severity: FINDING_SEVERITIES.ERROR,
      },
    ],
  });
}

function buildValidResult(validatorId, version) {
  return buildResult({ validatorId, version, status: VALIDATOR_STATUSES.VALID, findings: [] });
}

function normalizeFinding(finding) {
  if (typeof finding === 'string') {
    return Object.freeze({ code: 'INFO', message: finding, severity: FINDING_SEVERITIES.WARNING });
  }
  return Object.freeze({
    code: finding.code || 'UNKNOWN',
    message: finding.message || String(finding),
    severity: finding.severity || FINDING_SEVERITIES.WARNING,
    context: finding.context || null,
  });
}

// ---------------------------------------------------------------------------
// Plugin manifest hook
// ---------------------------------------------------------------------------

/**
 * Register a plugin manifest hook.
 * @param {Object} manifest - plugin manifest with validatorId field
 */
function registerPluginManifest(manifest) {
  if (!manifest || !manifest.id) return;
  _pluginHooks.push({ id: manifest.id, manifest: Object.freeze({ ...manifest }) });
}

/**
 * Get the plugin-specific validator ID for a plugin.
 * @param {string} pluginId
 * @returns {string|null}
 */
function getPluginValidatorId(pluginId) {
  const hook = _pluginHooks.find((h) => h.id === pluginId);
  return hook ? hook.manifest.validatorId || null : null;
}

// ---------------------------------------------------------------------------
// Listing
// ---------------------------------------------------------------------------

function listValidators({ enabledOnly = true } = {}) {
  return [..._registry.values()]
    .filter((e) => !enabledOnly || e.enabled)
    .sort((a, b) => {
      if (b.priority !== a.priority) return b.priority - a.priority;
      return String(a.id).localeCompare(b.id);
    })
    .map((e) => ({
      id: e.id,
      name: e.name,
      version: e.version,
      type: e.type,
      applicableKinds: e.applicableKinds,
      enabled: e.enabled,
    }));
}

function getValidatorInfo(validatorId) {
  const e = _registry.get(validatorId);
  if (!e) return null;
  return { id: e.id, name: e.name, version: e.version, type: e.type, applicableKinds: e.applicableKinds, enabled: e.enabled };
}

function clearRegistry() {
  _registry.clear();
  _pluginHooks = [];
}

module.exports = {
  VALIDATOR_TYPES,
  VALIDATOR_STATUSES,
  FINDING_SEVERITIES,
  registerValidator,
  setValidatorEnabled,
  dispatchValidator,
  findValidatorsForKind,
  findValidatorsForType,
  validateArtifact,
  validateDelivery,
  aggregateStatus,
  buildResult,
  buildUnavailableResult,
  buildValidResult,
  normalizeFinding,
  registerPluginManifest,
  getPluginValidatorId,
  listValidators,
  getValidatorInfo,
  clearRegistry,
};

'use strict';

/**
 * Built-in Loop Validator Definitions v1.
 *
 * Each validator is a pure function: (artifact, context) => ValidatorResult.
 * No I/O, no DB, no network. All file/hash checks are done by the integration layer
 * which passes pre-fetched facts via context.
 *
 * Built-in validators:
 *  1. input-snapshot        — verify input files exist, hash matches, size non-zero
 *  2. metadata-consistency  — verify metadata columns match expected schema
 *  3. counts-matrix         — verify counts matrix dimensions and non-negative values
 *  4. de-results            — verify DE results have required columns and statistics
 *  5. heatmap-data          — verify heatmap input has required matrix + row/col annotations
 *  6. enrichment-statistics — verify enrichment results have required columns and p-values
 *  7. delivery-integrity    — verify delivery manifest completeness
 *
 * Validator result status semantics:
 *  - valid:       artifact is structurally sound and meets all checks
 *  - degraded:    artifact has warnings (e.g. low sample count, missing optional fields)
 *  - blocked:     artifact has errors (missing required files, wrong columns, invalid values)
 *  - unavailable: cannot validate (missing context, validator not applicable)
 */

const vr = require('./loop-validator-registry');

const {
  VALIDATOR_TYPES,
  VALIDATOR_STATUSES,
  FINDING_SEVERITIES,
  registerValidator,
  buildResult,
  buildUnavailableResult,
} = vr;

// ---------------------------------------------------------------------------
// 1. input-snapshot validator
// ---------------------------------------------------------------------------

const INPUT_SNAPSHOT_DEF = {
  id: 'input-snapshot',
  name: 'Input File Snapshot Validator',
  version: '1.0.0',
  type: VALIDATOR_TYPES.INPUT_SNAPSHOT,
  applicableKinds: ['file', 'data'],
  applicableArtifactTypes: [],
  priority: 20,

  validate(artifact, context) {
    const { dagNode } = context;
    const findings = [];

    if (!artifact || typeof artifact !== 'object') {
      return buildUnavailableResult('input-snapshot', '1.0.0', 'no_artifact');
    }

    const filename = artifact.filename || artifact.name || artifact.id || '';
    const sizeBytes = artifact.sizeBytes || artifact.size || 0;
    const sha256 = artifact.sha256 || artifact.hash || null;

    if (sizeBytes === 0) {
      findings.push({ code: 'INPUT_FILE_EMPTY', message: `Input file '${filename}' is empty (0 bytes)`, severity: FINDING_SEVERITIES.ERROR });
    }

    if (sha256 !== null) {
      if (typeof sha256 !== 'string' || sha256.length !== 64 || !/^[a-f0-9]{64}$/i.test(sha256)) {
        findings.push({ code: 'INPUT_HASH_INVALID', message: `Input hash for '${filename}' is not a valid SHA-256 hex (64 chars)`, severity: FINDING_SEVERITIES.ERROR });
      }
    }

    if (dagNode && Array.isArray(dagNode.requiredInputs)) {
      const requiredInputs = dagNode.requiredInputs.map(String);
      const artifactInputName = String(artifact.inputRole || artifact.id || filename).toLowerCase();
      const matches = requiredInputs.some(
        (req) => artifactInputName.includes(req.toLowerCase()) || req.toLowerCase().includes(artifactInputName),
      );
      if (!matches && requiredInputs.length > 0) {
        findings.push({
          code: 'INPUT_NOT_IN_REQUIRED_LIST',
          message: `Input artifact '${artifactInputName}' does not match any declared required input: ${requiredInputs.join(', ')}`,
          severity: FINDING_SEVERITIES.WARNING,
          context: { requiredInputs, artifactInputName },
        });
      }
    }

    const status = findings.some((f) => f.severity === FINDING_SEVERITIES.ERROR)
      ? VALIDATOR_STATUSES.BLOCKED
      : findings.length > 0
        ? VALIDATOR_STATUSES.DEGRADED
        : VALIDATOR_STATUSES.VALID;

    return buildResult({
      validatorId: 'input-snapshot',
      version: '1.0.0',
      status,
      findings,
      detail: findings.length > 0 ? findings.map((f) => f.message).join('; ') : null,
    });
  },
};

// ---------------------------------------------------------------------------
// 2. metadata-consistency validator
// ---------------------------------------------------------------------------

const METADATA_CONSISTENCY_DEF = {
  id: 'metadata-consistency',
  name: 'Metadata Schema Consistency Validator',
  version: '1.0.0',
  type: VALIDATOR_TYPES.ARTIFACT_SCHEMA,
  applicableKinds: ['metadata'],
  applicableArtifactTypes: [],
  priority: 30,

  validate(artifact, context) {
    const findings = [];
    if (!artifact || typeof artifact !== 'object') {
      return buildUnavailableResult('metadata-consistency', '1.0.0', 'no_artifact');
    }

    const filename = artifact.filename || artifact.name || '';
    const rows = artifact.rows || artifact.data || artifact.content || null;
    const columns = artifact.columns || artifact.header || null;

    let colNames = Array.isArray(columns) ? columns : null;
    if (!colNames && Array.isArray(rows) && rows.length > 0) {
      if (Array.isArray(rows[0])) colNames = rows[0].map((_, i) => `col_${i}`);
      else if (typeof rows[0] === 'object') colNames = Object.keys(rows[0]);
    }

    if (!colNames || colNames.length === 0) {
      findings.push({
        code: 'METADATA_NO_COLUMNS',
        message: `Metadata '${filename}' has no identifiable columns`,
        severity: FINDING_SEVERITIES.ERROR,
      });
      return buildResult({ validatorId: 'metadata-consistency', version: '1.0.0', status: VALIDATOR_STATUSES.BLOCKED, findings });
    }

    const REQUIRED_META_COLS = ['sample_id', 'sample', 'sampleName'];
    const lowerCols = colNames.map((c) => String(c).toLowerCase());
    const hasSampleId = REQUIRED_META_COLS.some((r) => lowerCols.includes(r));
    if (!hasSampleId) {
      findings.push({
        code: 'METADATA_MISSING_SAMPLE_ID',
        message: `Metadata '${filename}' lacks a sample ID column. Expected one of: ${REQUIRED_META_COLS.join(', ')}`,
        severity: FINDING_SEVERITIES.ERROR,
        context: { columns: colNames },
      });
    }

    const seen = new Set();
    for (const col of colNames) {
      const key = String(col).toLowerCase();
      if (seen.has(key)) {
        findings.push({ code: 'METADATA_DUPLICATE_COLUMNS', message: `Metadata has duplicate column name: '${col}'`, severity: FINDING_SEVERITIES.ERROR });
      }
      seen.add(key);
    }

    if (Array.isArray(rows) && rows.length < 2) {
      findings.push({ code: 'METADATA_TOO_FEW_ROWS', message: `Metadata '${filename}' has fewer than 2 rows`, severity: FINDING_SEVERITIES.WARNING });
    }

    if (context.expectedColumns && Array.isArray(context.expectedColumns)) {
      for (const expCol of context.expectedColumns) {
        if (!lowerCols.includes(String(expCol).toLowerCase())) {
          findings.push({
            code: 'METADATA_MISSING_EXPECTED_COLUMN',
            message: `Metadata '${filename}' is missing expected column: '${expCol}'`,
            severity: FINDING_SEVERITIES.WARNING,
            context: { expectedColumn: expCol },
          });
        }
      }
    }

    const status = findings.some((f) => f.severity === FINDING_SEVERITIES.ERROR)
      ? VALIDATOR_STATUSES.BLOCKED
      : findings.length > 0
        ? VALIDATOR_STATUSES.DEGRADED
        : VALIDATOR_STATUSES.VALID;

    return buildResult({
      validatorId: 'metadata-consistency',
      version: '1.0.0',
      status,
      findings,
      detail: findings.length > 0 ? findings.map((f) => f.message).join('; ') : null,
    });
  },
};

// ---------------------------------------------------------------------------
// 3. counts-matrix validator
// ---------------------------------------------------------------------------

const COUNTS_MATRIX_DEF = {
  id: 'counts-matrix',
  name: 'Counts Matrix Validator',
  version: '1.0.0',
  type: VALIDATOR_TYPES.ARTIFACT_SCHEMA,
  applicableKinds: ['counts'],
  applicableArtifactTypes: [],
  priority: 40,

  validate(artifact, context) {
    const findings = [];
    if (!artifact || typeof artifact !== 'object') {
      return buildUnavailableResult('counts-matrix', '1.0.0', 'no_artifact');
    }

    const filename = artifact.filename || artifact.name || '';
    const data = artifact.data || artifact.values || artifact.matrix || artifact.content || null;

    if (!Array.isArray(data)) {
      findings.push({ code: 'COUNTS_NO_DATA', message: `Counts matrix '${filename}' has no data array`, severity: FINDING_SEVERITIES.ERROR });
      return buildResult({ validatorId: 'counts-matrix', version: '1.0.0', status: VALIDATOR_STATUSES.BLOCKED, findings });
    }

    const nRows = data.length;
    if (nRows < 10) {
      findings.push({ code: 'COUNTS_TOO_FEW_ROWS', message: `Counts matrix '${filename}' has fewer than 10 rows (${nRows})`, severity: FINDING_SEVERITIES.WARNING });
    }

    if (nRows > 0) {
      const nCols = Array.isArray(data[0]) ? data[0].length : typeof data[0] === 'object' ? Object.keys(data[0]).length : 0;
      if (nCols < 2) {
        findings.push({ code: 'COUNTS_TOO_FEW_COLUMNS', message: `Counts matrix '${filename}' has fewer than 2 columns`, severity: FINDING_SEVERITIES.ERROR });
      }

      for (let i = 0; i < Math.min(nRows, 100); i++) {
        const row = data[i];
        if (Array.isArray(row)) {
          for (let j = 0; j < row.length; j++) {
            const val = row[j];
            if (val !== null && val !== undefined && isNaN(Number(val))) {
              findings.push({ code: 'COUNTS_NON_NUMERIC', message: `Non-numeric value at [${i},${j}]: ${val}`, severity: FINDING_SEVERITIES.ERROR });
            } else if (Number(val) < 0) {
              findings.push({ code: 'COUNTS_NEGATIVE_VALUE', message: `Negative count at [${i},${j}]: ${val}`, severity: FINDING_SEVERITIES.ERROR });
            }
          }
        }
      }
    }

    if (context.expectedGenes && Number(context.expectedGenes) > 0 && nRows < Number(context.expectedGenes) * 0.8) {
      findings.push({ code: 'COUNTS_ROW_COUNT_LOW', message: `Counts matrix has fewer rows (${nRows}) than expected (${context.expectedGenes})`, severity: FINDING_SEVERITIES.WARNING });
    }

    const status = findings.some((f) => f.severity === FINDING_SEVERITIES.ERROR)
      ? VALIDATOR_STATUSES.BLOCKED
      : findings.length > 0
        ? VALIDATOR_STATUSES.DEGRADED
        : VALIDATOR_STATUSES.VALID;

    return buildResult({
      validatorId: 'counts-matrix',
      version: '1.0.0',
      status,
      findings,
      detail: findings.length > 0 ? findings.slice(0, 5).map((f) => f.message).join('; ') : null,
    });
  },
};

