const DEFAULT_PREVIEW_INPUT_MEMORY_MULTIPLIER = 4;
const DEFAULT_PREVIEW_OUTPUT_DISK_MULTIPLIER = 2;
const PREVIEW_METADATA_RESERVE_BYTES = 8 * 1024 * 1024;
const MAX_RESOURCE_MODEL_MULTIPLIER = 64;

function trustedPreviewResourceModel(descriptor) {
  const raw = descriptor?.previewResourceModel;
  if (raw == null) {
    return {
      baseMemoryBytes: DEFAULT_PREVIEW_BASE_MEMORY_BYTES,
      inputMemoryMultiplier: DEFAULT_PREVIEW_INPUT_MEMORY_MULTIPLIER,
      outputDiskMultiplier: DEFAULT_PREVIEW_OUTPUT_DISK_MULTIPLIER,
      raster: null,
    };
  }
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) {
    throw new ResultChangeSetError('preview_resource_model_invalid', 'The trusted plugin preview resource model is invalid.');
  }
  const baseMemoryBytes = resourceNumber(raw.baseMemoryBytes, { minimum: 1 });
  const inputMemoryMultiplier = resourceNumber(raw.inputMemoryMultiplier, {
    minimum: 0,
    maximum: MAX_RESOURCE_MODEL_MULTIPLIER,
  });
  const outputDiskMultiplier = resourceNumber(raw.outputDiskMultiplier, {
    minimum: 1,
    maximum: MAX_RESOURCE_MODEL_MULTIPLIER,
  });
  if (baseMemoryBytes == null || inputMemoryMultiplier == null || outputDiskMultiplier == null) {
    throw new ResultChangeSetError('preview_resource_model_invalid', 'The trusted plugin preview resource model has invalid numeric bounds.');
  }
  let raster = null;
  if (raw.raster != null) {
    const candidate = raw.raster;
    const parameterIds = ['widthParameter', 'heightParameter', 'dpiParameter'];
    const bytesPerPixel = resourceNumber(candidate?.bytesPerPixel, { minimum: 1, maximum: 32 });
    const workingSetMultiplier = resourceNumber(candidate?.workingSetMultiplier, {
      minimum: 1,
      maximum: MAX_RESOURCE_MODEL_MULTIPLIER,
    });
    if (!candidate || typeof candidate !== 'object' || Array.isArray(candidate)
        || parameterIds.some((key) => !/^[A-Za-z0-9][A-Za-z0-9._-]*$/.test(String(candidate[key] || ''))
          || !descriptor?.parameters?.[candidate[key]])
        || bytesPerPixel == null || workingSetMultiplier == null) {
      throw new ResultChangeSetError('preview_resource_model_invalid', 'The trusted plugin raster resource model is invalid.');
    }
    raster = {
      widthParameter: candidate.widthParameter,
      heightParameter: candidate.heightParameter,
      dpiParameter: candidate.dpiParameter,
      bytesPerPixel,
      workingSetMultiplier,
    };
  }
  return { baseMemoryBytes, inputMemoryMultiplier, outputDiskMultiplier, raster };
}

function deriveTrustedPreviewResourceEstimate({
  descriptor,
  sourceJob,
  sourceResult,
  workspaceRoot,
  trustedExecution,
  sourceOutputPath,
  sourceRevision,
  proposedParameterPatch = {},
  downstreamPlan = [],
} = {}) {
  const model = trustedPreviewResourceModel(descriptor);
  const provenanceInputs = Array.isArray(sourceResult?.executionProvenance?.inputs)
    ? sourceResult.executionProvenance.inputs
    : [];
  let inputBytes = 0;
  for (const input of provenanceInputs) {
    const inputId = safeSegment(input?.id, 'source_input_id');
    const physical = trustedExecution?.runtime?.[inputId];
    if (typeof physical !== 'string' || !path.isAbsolute(physical)) {
      throw new ResultChangeSetError('preview_resource_estimate_unavailable', 'A verified source input is unavailable for resource estimation.');
    }
    inputBytes += trustedFileSize(workspaceRoot, physical, 'preview_resource_estimate_unavailable');
  }

  const descriptorArtifactIds = Array.isArray(descriptor?.artifacts)
    ? descriptor.artifacts.map((artifact) => String(artifact?.id || '').trim()).filter(Boolean)
    : [];
  const selectedOutputBytes = trustedFileSize(workspaceRoot, sourceOutputPath, 'preview_resource_estimate_unavailable');
  let sourceOutputBytes = selectedOutputBytes;
  let sourceOutputMeasurement = 'selected_revision_artifact';
  if (descriptorArtifactIds.length > 0) {
    const descriptorArtifacts = descriptorArtifactIds.map((artifactId) => exactArtifact(sourceResult, artifactId));
    // Historical Revisions may predate complete formal-output cohort registration.
    // Their selected Revision has already passed the exact physical hash check
    // above, so it is a trusted conservative floor. Only use all descriptor
    // outputs when every one has a concrete current physical path; a partial
    // list must never manufacture an estimate from missing artifacts.
    if (descriptorArtifacts.every((artifact) => artifact?.path)) {
      sourceOutputBytes = descriptorArtifacts.reduce((total, artifact) => total + trustedFileSize(
        workspaceRoot,
        artifact.path,
        'preview_resource_estimate_unavailable',
      ), 0);
      sourceOutputMeasurement = 'complete_descriptor_artifacts';
    }
  }
  const downstreamOutputBytes = (Array.isArray(downstreamPlan) ? downstreamPlan : [])
    .reduce((total, entry) => total + trustedFileSize(
      workspaceRoot,
      entry.sourceOutputPath,
      'preview_resource_estimate_unavailable',
    ), 0);

  const usage = sourceResult?.resourceUsage;
  const historicalRssBytes = Number(usage?.sampling?.processSampleCount) > 0
    ? resourceNumber(usage?.peak?.rssBytes, { minimum: 1 })
    : null;
  const inputWorkingSet = boundedResourceProduct(inputBytes, model.inputMemoryMultiplier);
  let memoryBytes = Math.max(
    model.baseMemoryBytes + inputWorkingSet,
    historicalRssBytes == null ? 0 : boundedResourceProduct(historicalRssBytes, 1.25),
  );
  let rasterBytes = 0;
  let rasterParameterSource = null;
  if (model.raster) {
    const parameters = { ...(trustedExecution?.normalized || {}), ...(proposedParameterPatch || {}) };
    const defaultParameter = (parameterId) => resourceNumber(
      descriptor?.parameters?.[parameterId]?.default,
      { minimum: 1 },
    );
    const exactWidth = resourceNumber(parameters[model.raster.widthParameter], { minimum: 1 });
    const exactHeight = resourceNumber(parameters[model.raster.heightParameter], { minimum: 1 });
    const exactDpi = resourceNumber(parameters[model.raster.dpiParameter], { minimum: 1 });
    const width = exactWidth ?? defaultParameter(model.raster.widthParameter);
    const height = exactHeight ?? defaultParameter(model.raster.heightParameter);
    const dpi = exactDpi ?? defaultParameter(model.raster.dpiParameter);
    if (width != null && height != null && dpi != null) {
      rasterParameterSource = exactWidth != null && exactHeight != null && exactDpi != null
        ? 'trusted_execution_parameters'
        : 'trusted_descriptor_defaults_for_legacy_revision';
      rasterBytes = boundedResourceProduct(width, dpi, height, dpi, model.raster.bytesPerPixel);
      memoryBytes = Math.max(memoryBytes, boundedResourceProduct(rasterBytes, model.raster.workingSetMultiplier));
    } else {
      // A pre-descriptor historical revision has no user-provided dimensions to
      // trust. The base/input/output model remains a deterministic server-side
      // guard while the response records that no raster term was available.
      rasterParameterSource = 'not_available_in_legacy_revision';
    }
  }
  const diskBytes = Math.max(
    PREVIEW_METADATA_RESERVE_BYTES,
    boundedResourceProduct(sourceOutputBytes + downstreamOutputBytes, model.outputDiskMultiplier)
      + rasterBytes + PREVIEW_METADATA_RESERVE_BYTES,
  );
  if (!Number.isSafeInteger(memoryBytes) || memoryBytes <= 0
      || !Number.isSafeInteger(diskBytes) || diskBytes <= 0) {
    throw new ResultChangeSetError('preview_resource_estimate_unavailable', 'A finite trusted preview resource estimate could not be derived.');
  }
  return {
    estimateVersion: 1,
    source: 'server_job_descriptor_input_truth',
    memoryBytes,
    diskBytes,
    inputBytes,
    sourceOutputBytes,
    sourceOutputMeasurement,
    selectedRevisionId: sourceRevision?.revisionId || null,
    downstreamOutputBytes,
    historicalRssBytes,
    rasterBytes,
    rasterParameterSource,
  };
}

module.exports = {
  trustedPreviewResourceModel,
  deriveTrustedPreviewResourceEstimate,
};

'use strict';

const crypto = require('crypto');
const fs = require('fs');
const path = require('path');
const { isPathContained } = require('./project-run-layout');
const { stableStringify } = require('./canonical-json');
const { buildResultEditCheckpoint } = require('./result-changeset-service');
const { compareScientificTables } = require('./result-scientific-compare');
const { buildResultStudioTaskResourceSummary } = require('./result-studio-resource-summary');
const { executeDurableRefTransaction } = require('./result-ref-transaction');
const { removePrivatePathSync } = require('./result-studio-private-path');
const {
  validateRestoreWorkflowScope,
  rebindWorkflowGraphForEquivalentRestore,
} = require('./result-workflow-graph');

const RESULT_COMPARE_SERVICE_VERSION = 1;
const ZERO_OID = '0'.repeat(40);
const MAX_PATCH_CHARS = 200000;
const MAX_JSON_FIELDS = 500;
const MAX_TABLE_BYTES = 4 * 1024 * 1024;
const MAX_TABLE_SAMPLE_ROWS = 20;
const PUBLIC_INTERNAL_ID = /^(?:rev|cs|tj|sel|conv|p)_[a-z0-9_-]{6,}$/i;
const PUBLIC_INTERNAL_ID_EMBEDDED = /\b(?:rev|cs|tj|sel|conv|p)_[a-z0-9_-]{6,}\b/gi;
const PUBLIC_SENSITIVE_FIELD = /(?:api.?key|access.?token|secret|password|credential|private.?key)/i;

class ResultCompareError extends Error {
  constructor(code, message, detail = null) {
    super(message);
    this.name = 'ResultCompareError';
    this.code = code;
    this.detail = detail;
  }
}

function sha256(value) {
  return crypto.createHash('sha256').update(value).digest('hex');
}

function randomId(prefix) {
  return `${prefix}_${crypto.randomUUID().replace(/-/g, '')}`;
}

function stableJson(value) {
  return `${JSON.stringify(JSON.parse(stableStringify(value)), null, 2)}\n`;
}

function projectGitPath(relativePath, gitPathPrefix = '') {
  const prefix = String(gitPathPrefix || '').replace(/^\/+|\/+$/g, '');
  return prefix ? path.posix.join(prefix, relativePath) : relativePath;
}

function boundedText(value, limit = 2000) {
  const text = String(value == null ? '' : value);
  return text.length <= limit ? text : `${text.slice(0, limit)}…`;
}

function publicComparisonValue(value, field = '') {
  if (PUBLIC_SENSITIVE_FIELD.test(field)) return '[redacted]';
  if (typeof value === 'string') {
    if (path.isAbsolute(value)) return '[project file]';
    if (PUBLIC_INTERNAL_ID.test(value)) return '[internal reference]';
    return value.replace(PUBLIC_INTERNAL_ID_EMBEDDED, '[internal reference]');
  }
  if (Array.isArray(value)) return value.map((item) => publicComparisonValue(item, field));
  if (value && typeof value === 'object') {
    return Object.fromEntries(Object.entries(value)
      .map(([key, child]) => [key, publicComparisonValue(child, key)]));
  }
  return value;
}

function redactWindowsCoordinates(value) {
  let output = '';
  let index = 0;
  while (index < value.length) {
    const code = value.charCodeAt(index);
    const startsCoordinate = ((code >= 65 && code <= 90) || (code >= 97 && code <= 122))
      && value[index + 1] === ':' && value.charCodeAt(index + 2) === 92;
    if (!startsCoordinate) {
      output += value[index];
      index += 1;
      continue;
    }
    const quote = index > 0 && (value[index - 1] === '"' || value[index - 1] === "'")
      ? value[index - 1]
      : null;
    let end = index + 3;
    while (end < value.length) {
      const character = value[end];
      if (character === '\r' || character === '\n'
          || (quote ? character === quote : /\s|["'`<>]/.test(character))) break;
      end += 1;
    }
    output += '[project file]';
    index = end;
  }
  return output;
}

function publicPatch(rawPatch) {
  return redactWindowsCoordinates(String(rawPatch || '')
    .replace(/^diff --git a\/(.+) b\/(.+)$/gm,
      (_line, before, after) => `diff ${path.posix.basename(before)} -> ${path.posix.basename(after)}`)
    .replace(/^--- (?:a\/)?(.+)$/gm, (_line, file) => `--- ${path.posix.basename(file)}`)
    .replace(/^\+\+\+ (?:b\/)?(.+)$/gm, (_line, file) => `+++ ${path.posix.basename(file)}`)
    .replace(/(["'])(?:\/Users\/|\/home\/)[^"'\r\n]*\1/g, '$1[project file]$1')
    .replace(/(?:\/Users\/|\/home\/)[^\s"'`<>]*/g, '[project file]')
    .replace(PUBLIC_INTERNAL_ID_EMBEDDED, '[internal reference]'));
}

function countPatch(patch) {
  let additions = 0;
  let deletions = 0;
  for (const line of String(patch || '').split('\n')) {
    if (line.startsWith('+') && !line.startsWith('+++')) additions += 1;
    if (line.startsWith('-') && !line.startsWith('---')) deletions += 1;
  }
  return { additions, deletions };
}

function flattenJson(value, prefix = '', output = {}, state = { truncated: false }) {
  if (Object.keys(output).length >= MAX_JSON_FIELDS) {
    state.truncated = true;
    return { fields: output, truncated: true };
  }
  if (Array.isArray(value)) {
    value.slice(0, 100).forEach((entry, index) => flattenJson(entry, `${prefix}[${index}]`, output, state));
    if (value.length > 100) state.truncated = true;
    return { fields: output, truncated: state.truncated };
  }
  if (value && typeof value === 'object') {
    const keys = Object.keys(value).sort();
    if (keys.length === 0 && prefix) output[prefix] = {};
    for (const key of keys) {
      if (Object.keys(output).length >= MAX_JSON_FIELDS) { state.truncated = true; break; }
      flattenJson(value[key], prefix ? `${prefix}.${key}` : key, output, state);
    }
    return { fields: output, truncated: state.truncated };
  }
  if (prefix) output[prefix] = typeof value === 'string' ? boundedText(value, 500) : value;
  return { fields: output, truncated: state.truncated };
}

function compareJsonValues(beforeText, afterText, relativePath) {
  let before;
  let after;
  try {
    before = beforeText == null ? null : JSON.parse(beforeText);
    after = afterText == null ? null : JSON.parse(afterText);
  } catch {
    return { relativePath, status: 'unavailable', reason: 'json_parse_failed', changes: [], truncated: false };
  }
  const left = flattenJson(before);
  const right = flattenJson(after);
  const keys = [...new Set([...Object.keys(left.fields), ...Object.keys(right.fields)])].sort();
  const changes = [];
  for (const key of keys) {
    const a = left.fields[key];
    const b = right.fields[key];
    if (stableStringify(a) === stableStringify(b)) continue;
    changes.push({
      field: key,
      changeType: !(key in left.fields) ? 'added' : !(key in right.fields) ? 'removed' : 'changed',
      before: a === undefined ? null : publicComparisonValue(a, key),
      after: b === undefined ? null : publicComparisonValue(b, key),
    });
    if (changes.length >= MAX_JSON_FIELDS) break;
  }
  return {
    relativePath,
    status: 'available',
    changes,
    truncated: left.truncated || right.truncated || changes.length >= MAX_JSON_FIELDS,
  };
}

function splitDelimitedLine(line, delimiter) {
  const cells = [];
  let current = '';
  let quoted = false;
  for (let index = 0; index < line.length; index += 1) {
    const char = line[index];
    if (char === '"') {
      if (quoted && line[index + 1] === '"') { current += '"'; index += 1; continue; }
      quoted = !quoted;
      continue;
    }
    if (char === delimiter && !quoted) { cells.push(current); current = ''; continue; }
    current += char;
  }
  cells.push(current);
  return cells;
}

function readTableSummary(filePath) {
  const stat = fs.statSync(filePath);
  const truncated = stat.size > MAX_TABLE_BYTES;
  const length = Math.min(stat.size, MAX_TABLE_BYTES);
  const handle = fs.openSync(filePath, 'r');
  let raw;
  try {
    const buffer = Buffer.alloc(length);
    const read = fs.readSync(handle, buffer, 0, length, 0);
    raw = buffer.subarray(0, read).toString('utf8');
  } finally {
    fs.closeSync(handle);
  }
  if (truncated) raw = raw.slice(0, Math.max(0, raw.lastIndexOf('\n')));
  const lines = raw.split(/\r?\n/).filter((line) => line.trim() !== '');
  const delimiter = /\.tsv$/i.test(filePath)
    ? '\t'
    : ((lines[0]?.match(/\t/g) || []).length > (lines[0]?.match(/,/g) || []).length ? '\t' : ',');
  const columns = lines[0] ? splitDelimitedLine(lines[0], delimiter).map((cell) => cell.trim()) : [];
  const rows = lines.slice(1, 1 + MAX_TABLE_SAMPLE_ROWS).map((line) => splitDelimitedLine(line, delimiter));
  return {
    columns,
    rowCount: Math.max(0, lines.length - 1),
    rowCountIsLowerBound: truncated,
    sampleRows: rows,
    bytes: stat.size,
    truncated,
  };
}

function compareTables(beforePath, afterPath) {
  const before = readTableSummary(beforePath);
  const after = readTableSummary(afterPath);
  const beforeColumns = new Set(before.columns);
  const afterColumns = new Set(after.columns);
  const sampleChanges = [];
  const limit = Math.min(MAX_TABLE_SAMPLE_ROWS, Math.max(before.sampleRows.length, after.sampleRows.length));
  for (let index = 0; index < limit; index += 1) {
    const left = before.sampleRows[index] || null;
    const right = after.sampleRows[index] || null;
    if (stableStringify(left) !== stableStringify(right)) sampleChanges.push({ row: index + 1, before: left, after: right });
  }
  return {
    status: 'available',
    before: { columns: before.columns, rowCount: before.rowCount, rowCountIsLowerBound: before.rowCountIsLowerBound, bytes: before.bytes },
    after: { columns: after.columns, rowCount: after.rowCount, rowCountIsLowerBound: after.rowCountIsLowerBound, bytes: after.bytes },
    addedColumns: after.columns.filter((column) => !beforeColumns.has(column)),
    removedColumns: before.columns.filter((column) => !afterColumns.has(column)),
    sampleChanges,
    truncated: before.truncated || after.truncated,
  };
}

function resolveRevisionFile(workspaceRoot, revision) {
  const workspace = fs.realpathSync(workspaceRoot);
  const file = fs.realpathSync(path.join(workspace, revision.outputPath));
  if (!isPathContained(workspace, file)) throw new ResultCompareError('artifact_path_escape', 'Revision Artifact escaped the project.');
  const actualHash = sha256(fs.readFileSync(file));
  if (!revision.outputHash || actualHash !== revision.outputHash) {
    throw new ResultCompareError('artifact_hash_mismatch', 'Revision Artifact hash no longer matches its immutable record.');
  }
  return file;
}

function revisionParametersForComparison(revision, adapter, gitPathPrefix) {
  if (!revision?.sourceCommit || !revision.parametersRef || !revision.parametersHash) return null;
  const text = adapter.showFile({
    ref: revision.sourceCommit,
    filePath: projectGitPath(revision.parametersRef, gitPathPrefix),
  });
  if (text == null || sha256(text) !== revision.parametersHash) return null;
  try {
    const parsed = JSON.parse(text);
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : null;
  } catch {
    return null;
  }
}

function compareResultChangeSet(input = {}, dependencies = {}) {
  const { repository, adapter } = dependencies;
  if (!repository || !adapter) throw new ResultCompareError('compare_dependencies_missing', 'Repository and Git adapter are required.');
  const changeSet = repository.getChangeSet(input.changeSetId);
  if (!changeSet || changeSet.projectId !== input.projectId) throw new ResultCompareError('change_set_not_found', 'ChangeSet was not found in the active project.');
  const revisions = repository.listRevisionsByChangeSet(changeSet.changeSetId);
  const changedPaths = changeSet.changedPaths.map((entry) => entry.relativePath).filter(Boolean);
  // Structured JSON changes are projected below with path/identifier
  // redaction. Keeping their raw Git patch would duplicate that view and leak
  // staged absolute input coordinates into the ordinary Compare surface.
  const gitPaths = changedPaths
    .filter((relativePath) => !/\.json$/i.test(relativePath))
    .map((relativePath) => projectGitPath(relativePath, dependencies.gitPathPrefix));
  let rawPatch = '';
  if (changeSet.candidateCommit && changeSet.baseCommit && gitPaths.length > 0) {
    rawPatch = adapter.diff({ paths: gitPaths, fromRef: changeSet.baseCommit, toRef: changeSet.candidateCommit }).patch;
  }
  const patchCounts = countPatch(rawPatch);
  const safePatch = publicPatch(rawPatch);
  const patchTruncated = safePatch.length > MAX_PATCH_CHARS;
  const patch = patchTruncated ? `${safePatch.slice(0, MAX_PATCH_CHARS)}\n…[truncated]` : safePatch;
  const jsonDiffs = [];
  for (const relativePath of changedPaths.filter((item) => /\.json$/i.test(item))) {
    const gitPath = projectGitPath(relativePath, dependencies.gitPathPrefix);
    const before = changeSet.baseCommit ? adapter.showFile({ ref: changeSet.baseCommit, filePath: gitPath }) : null;
    const after = changeSet.candidateCommit ? adapter.showFile({ ref: changeSet.candidateCommit, filePath: gitPath }) : null;
    jsonDiffs.push(compareJsonValues(before, after, relativePath));
  }

  const artifacts = [];
  for (const revision of revisions) {
    if (revision.projectId !== input.projectId) {
      throw new ResultCompareError('revision_project_mismatch', 'ChangeSet contains a Revision from another project.');
    }
    const parent = revision.parentRevisionIds.map((id) => repository.getRevision(id)).find(Boolean) || null;
    const ext = path.extname(revision.outputPath).toLowerCase();
    const kind = ['.csv', '.tsv'].includes(ext)
      ? 'table'
      : ['.png', '.jpg', '.jpeg', '.gif', '.webp', '.svg'].includes(ext) ? 'visual' : 'binary';
    const entry = {
      artifactId: revision.artifactId,
      artifactFamilyId: revision.artifactFamilyId,
      kind,
      beforeRevisionId: parent?.revisionId || null,
      afterRevisionId: revision.revisionId,
      beforeHash: parent?.outputHash || null,
      afterHash: revision.outputHash,
      validationStatus: revision.validationStatus,
      table: null,
      scientific: null,
    };
    if (kind === 'table' && parent) {
      try {
        const beforePath = resolveRevisionFile(input.workspaceRoot, parent);
        const afterPath = resolveRevisionFile(input.workspaceRoot, revision);
        entry.table = compareTables(
          beforePath,
          afterPath
        );
        if (['deg_table', 'classified_table', 'go_bp_results', 'kegg_results'].includes(revision.artifactId)) {
          entry.scientific = compareScientificTables({
            artifactId: revision.artifactId,
            beforePath,
            afterPath,
            beforeParameters: revisionParametersForComparison(parent, adapter, dependencies.gitPathPrefix),
            afterParameters: revisionParametersForComparison(revision, adapter, dependencies.gitPathPrefix),
          });
        }
      } catch (error) {
        entry.table = { status: 'unavailable', reason: error.code || 'table_compare_failed' };
        if (['deg_table', 'classified_table', 'go_bp_results', 'kegg_results'].includes(revision.artifactId)) {
          entry.scientific = { status: 'unavailable', kind: 'unavailable', reason: error.code || 'scientific_compare_failed' };
        }
      }
    }
    artifacts.push(entry);
  }
  const histories = revisions.map((revision) => ({
    artifactFamilyId: revision.artifactFamilyId,
    revisions: repository.listRevisions({ artifactFamilyId: revision.artifactFamilyId, projectId: input.projectId, limit: 100 }),
    currentRevisionId: repository.getCurrentRevision(revision.artifactFamilyId, input.projectId)?.revisionId || null,
  }));
  const jobs = [...new Set(changeSet.jobRefs || [])]
    .map((jobId) => typeof dependencies.getToolJob === 'function' ? dependencies.getToolJob(jobId) : null)
    .filter((job) => job && String(job.project_id || job.projectId || '') === input.projectId);
  return {
    resultCompareServiceVersion: RESULT_COMPARE_SERVICE_VERSION,
    changeSet,
    summary: {
      status: changeSet.status,
      createdBy: changeSet.createdBy,
      changedFileCount: changedPaths.length,
      additions: patchCounts.additions,
      deletions: patchCounts.deletions,
      candidateRevisionCount: revisions.length,
      validationStatus: revisions.some((revision) => revision.validationStatus === 'blocked')
        ? 'blocked'
        : revisions.some((revision) => revision.validationStatus === 'degraded') ? 'degraded' : 'valid',
    },
    textDiff: { patch, truncated: patchTruncated, ...patchCounts },
    jsonDiffs,
    artifacts,
    histories,
    resourceSummary: buildResultStudioTaskResourceSummary({ jobs }),
    git: {
      baseCommit: changeSet.baseCommit,
      candidateCommit: changeSet.candidateCommit,
      workingBranchRef: changeSet.workingBranchRef,
    },
  };
}

function verifyRevisionForAdoption({ revision, parent, workspaceRoot, adapter, gitPathPrefix, getToolJob, candidateCommit }) {
  if (!parent) throw new ResultCompareError('parent_revision_missing', 'Candidate Revision has no recoverable parent.');
  if (revision.projectId !== parent.projectId || revision.artifactFamilyId !== parent.artifactFamilyId) {
    throw new ResultCompareError('parent_revision_mismatch', 'Candidate Revision parent belongs to another project or Artifact family.');
  }
  if (!candidateCommit || revision.sourceCommit !== candidateCommit) {
    throw new ResultCompareError('candidate_source_commit_mismatch', 'Candidate Revision is not bound to the ChangeSet candidate commit.');
  }
  resolveRevisionFile(workspaceRoot, revision);
  const sourcePath = projectGitPath(revision.sourceScriptRef?.relativePath, gitPathPrefix);
  const sourceText = revision.sourceCommit && sourcePath
    ? adapter.showFile({ ref: revision.sourceCommit, filePath: sourcePath })
    : null;
  if (sourceText == null || sha256(sourceText) !== revision.sourceScriptRef?.sha256) {
    throw new ResultCompareError('candidate_script_hash_mismatch', 'Candidate script does not match its Git commit.');
  }
  const parametersPath = revision.parametersRef ? projectGitPath(revision.parametersRef, gitPathPrefix) : null;
  const parametersText = revision.sourceCommit && parametersPath
    ? adapter.showFile({ ref: revision.sourceCommit, filePath: parametersPath })
    : null;
  if (parametersText == null || !revision.parametersHash || sha256(parametersText) !== revision.parametersHash) {
    throw new ResultCompareError('candidate_parameters_hash_mismatch', 'Candidate parameters do not match their Git commit.');
  }
  const job = typeof getToolJob === 'function' ? getToolJob(revision.toolJobId) : null;
  if (!job || job.status !== 'completed' || String(job.project_id || job.projectId || '') !== revision.projectId
    || job.result?.artifactTruth?.status !== 'valid' || job.result?.artifactTruth?.blocking === true) {
    throw new ResultCompareError('candidate_job_truth_invalid', 'Candidate Job or Artifact Truth is not adoptable.');
  }
}

function planCurrentRefUpdates({ adapter, revisions, expectedCommit, nextCommit }) {
  return revisions.map((revision) => {
    const ref = `refs/heads/petri/current/${revision.artifactFamilyId}`;
    const existing = adapter.revParse(ref);
    const expected = expectedCommit(revision);
    if (existing && expected && existing !== expected) {
      throw new ResultCompareError(
        'current_git_ref_stale',
        'Current Git ref does not match the persisted Revision.',
        { ref },
      );
    }
    const newOid = nextCommit(revision);
    if (!newOid) {
      throw new ResultCompareError('current_git_ref_target_missing', 'Target Revision has no source commit.');
    }
    return { ref, expectedOld: existing || ZERO_OID, newOid };
  });
}

function currentRevisionIdsAfter({ repository, projectId, targetRevisions }) {
  const affectedFamilies = new Set(targetRevisions.map((revision) => revision.artifactFamilyId));
  return [
    ...repository.listCurrentRevisions(projectId)
      .filter((revision) => !affectedFamilies.has(revision.artifactFamilyId))
      .map((revision) => revision.revisionId),
    ...targetRevisions.map((revision) => revision.revisionId),
  ].sort();
}

function durableTransitionCheckpoint({
  repository,
  changeSet,
  targetStatus,
  targetCurrentRevisionIds,
}) {
  return buildResultEditCheckpoint({
    repository,
    projectId: changeSet.projectId,
    conversationId: changeSet.conversationId,
    changeSet,
    candidateCommit: changeSet.candidateCommit,
    changeSetStatus: targetStatus,
    currentRevisionIds: targetCurrentRevisionIds,
    stage: targetStatus,
    recovery: null,
  });
}

function sameStringSet(left, right) {
  if (!Array.isArray(left) || !Array.isArray(right) || left.length !== right.length) return false;
  const leftSet = new Set(left);
  const rightSet = new Set(right);
  return leftSet.size === left.length
    && rightSet.size === right.length
    && [...leftSet].every((value) => rightSet.has(value));
}

function assertAdoptedCohortIsCurrent({ repository, changeSet, projectId }) {
  const revisions = repository.listRevisionsByChangeSet(changeSet.changeSetId);
  const revisionIds = revisions.map((revision) => revision.revisionId);
  const candidateArtifactRefs = changeSet.candidateArtifactRefs;
  if (revisions.length === 0
      || !Array.isArray(candidateArtifactRefs)
      || (candidateArtifactRefs.length > 0
        && !sameStringSet(candidateArtifactRefs, revisionIds))) {
    throw new ResultCompareError(
      'adoption_cohort_incoherent',
      'The adopted ChangeSet no longer resolves to one complete candidate Revision cohort.',
      {
        changeSetId: changeSet.changeSetId,
        candidateArtifactRefs,
        persistedRevisionIds: revisionIds,
      }
    );
  }
  const stale = revisions.filter((revision) => {
    const current = repository.getCurrentRevision(revision.artifactFamilyId, projectId);
    return !revision.isCurrent || !current || current.revisionId !== revision.revisionId;
  });
  if (stale.length > 0) {
    throw new ResultCompareError(
      'adoption_not_current',
      'The adopted ChangeSet has been superseded and cannot be adopted idempotently.',
      {
        changeSetId: changeSet.changeSetId,
        staleRevisionIds: stale.map((revision) => revision.revisionId),
        currentRevisionIds: revisions.map((revision) => (
          repository.getCurrentRevision(revision.artifactFamilyId, projectId)?.revisionId || null
        )),
      }
    );
  }
  return revisions;
}

function adoptResultChangeSet(input = {}, dependencies = {}) {
  const { repository, adapter, getToolJob } = dependencies;
  if (!repository || !adapter) throw new ResultCompareError('adopt_dependencies_missing', 'Repository and Git adapter are required.');
  const changeSet = repository.getChangeSet(input.changeSetId);
  if (!changeSet || changeSet.projectId !== input.projectId) throw new ResultCompareError('change_set_not_found', 'ChangeSet was not found in the active project.');
  if (changeSet.status === 'adopted') {
    const revisions = assertAdoptedCohortIsCurrent({ repository, changeSet, projectId: input.projectId });
    return { ...repository.adoptChangeSet({ changeSetId: changeSet.changeSetId }), currentRevisions: revisions };
  }
  if (changeSet.status !== 'preview_ready' || !changeSet.candidateCommit) {
    throw new ResultCompareError('change_set_not_adoptable', 'Only a validated preview can be adopted.');
  }
  if (adapter.revParse(changeSet.workingBranchRef) !== changeSet.candidateCommit) {
    throw new ResultCompareError('candidate_git_ref_mismatch', 'Candidate Git ref no longer matches the ChangeSet.');
  }
  const revisions = repository.listRevisionsByChangeSet(changeSet.changeSetId);
  if (revisions.length === 0) throw new ResultCompareError('change_set_has_no_revision', 'ChangeSet has no candidate Revision.');
  const parents = new Map();
  for (const revision of revisions) {
    if (revision.projectId !== input.projectId) {
      throw new ResultCompareError('revision_project_mismatch', 'ChangeSet contains a Revision from another project.');
    }
    const parent = revision.parentRevisionIds.map((id) => repository.getRevision(id)).find(Boolean) || null;
    const current = repository.getCurrentRevision(revision.artifactFamilyId, input.projectId);
    if (!parent || !current || current.revisionId !== parent.revisionId) {
      throw new ResultCompareError('adoption_base_stale', 'Current result changed after this preview was created.');
    }
    verifyRevisionForAdoption({
      revision,
      parent,
      workspaceRoot: input.workspaceRoot,
      adapter,
      gitPathPrefix: dependencies.gitPathPrefix,
      getToolJob,
      candidateCommit: changeSet.candidateCommit,
    });
    parents.set(revision.revisionId, parent);
  }
  const refUpdates = planCurrentRefUpdates({
    adapter,
    revisions,
    expectedCommit: (revision) => parents.get(revision.revisionId)?.sourceCommit || null,
    nextCommit: () => changeSet.candidateCommit,
  });
  const targetCurrentRevisionIds = currentRevisionIdsAfter({
    repository,
    projectId: input.projectId,
    targetRevisions: revisions,
  });
  executeDurableRefTransaction({
    operationId: randomId('rft'),
    projectId: changeSet.projectId,
    changeSetId: changeSet.changeSetId,
    operationKind: 'adopt',
    sourceStatus: 'preview_ready',
    targetStatus: 'adopted',
    refUpdates,
    targetRevisionIds: revisions.map((revision) => revision.revisionId),
    checkpoint: durableTransitionCheckpoint({
      repository,
      changeSet,
      targetStatus: 'adopted',
      targetCurrentRevisionIds,
    }),
  }, {
    repository,
    adapter,
    afterRefsApplied: dependencies.afterRefsApplied,
  });
  const currentRevisions = revisions.map((revision) => repository.getRevision(revision.revisionId));
  return {
    changeSet: repository.getChangeSet(changeSet.changeSetId),
    adoptedRevisionIds: revisions.map((revision) => revision.revisionId),
    idempotent: false,
    currentRevisions,
  };
}

function revertResultChangeSet(input = {}, dependencies = {}) {
  const { repository, adapter } = dependencies;
  if (!repository || !adapter) throw new ResultCompareError('revert_dependencies_missing', 'Repository and Git adapter are required.');
  const changeSet = repository.getChangeSet(input.changeSetId);
  if (!changeSet || changeSet.projectId !== input.projectId) throw new ResultCompareError('change_set_not_found', 'ChangeSet was not found in the active project.');
  const intentRef = String(changeSet.intentRef || '');
  if (intentRef.startsWith('baseline:') || intentRef.startsWith('baseline-cohort:')) {
    throw new ResultCompareError('baseline_revert_forbidden', 'The root baseline cannot be reverted; restore or adopt another Revision instead.');
  }
  if (changeSet.status === 'reverted') return repository.revertChangeSet({ changeSetId: changeSet.changeSetId, reason: input.reason || null });
  const revisions = repository.listRevisionsByChangeSet(changeSet.changeSetId);
  let restoredRevisions = [];
  if (changeSet.status === 'adopted') {
    for (const revision of revisions) {
      const current = repository.getCurrentRevision(revision.artifactFamilyId, input.projectId);
      if (!current || current.revisionId !== revision.revisionId) {
        throw new ResultCompareError('revert_not_current', 'A newer Revision is current; restore history instead of reverting this ChangeSet.');
      }
      const sameFamilyParents = revision.parentRevisionIds
        .map((revisionId) => repository.getRevision(revisionId))
        .filter((parent) => parent
          && parent.projectId === revision.projectId
          && parent.artifactFamilyId === revision.artifactFamilyId
          && parent.validationStatus !== 'blocked');
      if (sameFamilyParents.length !== 1 || !sameFamilyParents[0].sourceCommit) {
        throw new ResultCompareError(
          'revert_parent_unavailable',
          'Revert requires exactly one valid same-family parent with a source commit.',
          { revisionId: revision.revisionId },
        );
      }
      restoredRevisions.push(sameFamilyParents[0]);
    }
  }
  const targetCurrentRevisionIds = changeSet.status === 'adopted'
    ? currentRevisionIdsAfter({
      repository,
      projectId: input.projectId,
      targetRevisions: restoredRevisions,
    })
    : repository.listCurrentRevisions(input.projectId).map((revision) => revision.revisionId).sort();
  const checkpoint = durableTransitionCheckpoint({
    repository,
    changeSet,
    targetStatus: 'reverted',
    targetCurrentRevisionIds,
  });
  if (changeSet.status === 'adopted') {
    const restoredByFamily = new Map(
      restoredRevisions.map((revision) => [revision.artifactFamilyId, revision]),
    );
    executeDurableRefTransaction({
      operationId: randomId('rft'),
      projectId: changeSet.projectId,
      changeSetId: changeSet.changeSetId,
      operationKind: 'revert_adopted',
      sourceStatus: 'adopted',
      targetStatus: 'reverted',
      refUpdates: planCurrentRefUpdates({
        adapter,
        revisions,
        expectedCommit: () => changeSet.candidateCommit,
        nextCommit: (revision) => restoredByFamily.get(revision.artifactFamilyId)?.sourceCommit || null,
      }),
      targetRevisionIds: restoredRevisions.map((revision) => revision.revisionId),
      checkpoint,
      statusReason: input.reason || 'user_reverted',
    }, {
      repository,
      adapter,
      afterRefsApplied: dependencies.afterRefsApplied,
    });
  } else {
    const existing = adapter.revParse(changeSet.workingBranchRef);
    if (existing && changeSet.candidateCommit && existing !== changeSet.candidateCommit) {
      throw new ResultCompareError('candidate_git_ref_mismatch', 'Candidate Git ref changed before discard.');
    }
    if (existing) {
      executeDurableRefTransaction({
        operationId: randomId('rft'),
        projectId: changeSet.projectId,
        changeSetId: changeSet.changeSetId,
        operationKind: 'discard_preview',
        sourceStatus: changeSet.status,
        targetStatus: 'reverted',
        refUpdates: [{ ref: changeSet.workingBranchRef, expectedOld: existing, newOid: ZERO_OID }],
        targetRevisionIds: [],
        checkpoint,
        statusReason: input.reason || 'user_reverted',
      }, {
        repository,
        adapter,
        afterRefsApplied: dependencies.afterRefsApplied,
      });
    } else {
      repository.transitionChangeSetWithCheckpoint({
        transition: {
          changeSetId: changeSet.changeSetId,
          to: 'reverted',
          reason: input.reason || 'user_reverted',
        },
        checkpoint,
      });
    }
  }
  if (changeSet.status !== 'adopted' && input.workspaceRoot) {
    try {
      removePrivatePathSync(
        input.workspaceRoot,
        ['.petri', 'revision', changeSet.changeSetId],
        { recursive: true, force: true, kind: 'directory' },
      );
    } catch { /* unsafe or changed staging is preserved for RS8 lifecycle inspection */ }
  }
  return {
    changeSet: repository.getChangeSet(changeSet.changeSetId),
    restoredRevisionIds: restoredRevisions.map((revision) => revision.revisionId),
    idempotent: false,
  };
}

function restoreArtifactRevision(input = {}, dependencies = {}) {
  const { repository, adapter, getToolJob } = dependencies;
  if (!repository || !adapter) throw new ResultCompareError('restore_dependencies_missing', 'Repository and Git adapter are required.');
  if (typeof repository.resolveRestorableRevision !== 'function') {
    throw new ResultCompareError('restore_qualification_unavailable', 'Historical restore qualification is unavailable.');
  }
  let resolved;
  try {
    resolved = repository.resolveRestorableRevision({
      revisionId: input.revisionId,
      projectId: input.projectId,
    });
  } catch (error) {
    throw new ResultCompareError(
      error.code || 'revision_not_restorable',
      error.message || 'Revision is not eligible for historical restore.',
      error.detail || null,
    );
  }
  const target = resolved.revision;
  const sourceCohort = [...resolved.cohort]
    .sort((left, right) => `${left.artifactFamilyId}:${left.artifactId}`.localeCompare(`${right.artifactFamilyId}:${right.artifactId}`));
  const validationSummary = resolved.changeSet.validationSummary || {};
  if (!Number.isInteger(validationSummary.formalArtifactCount)
      || validationSummary.formalArtifactCount !== sourceCohort.length) {
    throw new ResultCompareError(
      'restore_formal_artifact_count_mismatch',
      'Historical restore requires an exact formal Artifact count for the source cohort.',
      { expected: sourceCohort.length, actual: validationSummary.formalArtifactCount ?? null },
    );
  }
  const sourceToolJobIds = [...new Set(sourceCohort.map((revision) => revision.toolJobId))];
  const rawValidatorIds = validationSummary.validatorIds;
  const sourceValidatorIds = Array.isArray(rawValidatorIds)
    ? rawValidatorIds.map((value) => typeof value === 'string' ? value.trim() : '')
    : [];
  if (!Array.isArray(rawValidatorIds) || sourceValidatorIds.length === 0
      || sourceValidatorIds.length !== sourceToolJobIds.length
      || sourceValidatorIds.some((value, index) => !value || value !== rawValidatorIds[index])
      || new Set(sourceValidatorIds).size !== sourceValidatorIds.length
      || (Object.prototype.hasOwnProperty.call(validationSummary, 'validatorId')
        && (sourceValidatorIds.length !== 1 || validationSummary.validatorId !== sourceValidatorIds[0]))) {
    throw new ResultCompareError(
      'restore_validator_proof_missing',
      'Historical restore requires unique, nonblank validator proof for every source Job.'
    );
  }
  const sourceFamilyIds = sourceCohort.map((revision) => revision.artifactFamilyId);
  if (new Set(sourceFamilyIds).size !== sourceFamilyIds.length) {
    throw new ResultCompareError('restore_cohort_family_duplicate', 'Historical ChangeSet contains more than one Revision for an Artifact family.');
  }
  const sourceGraphRef = resolved.changeSet.validationSummary?.workflowGraph || null;
  let sourceWorkflowGraph = null;
  const hasSourceGraphRef = Boolean(sourceGraphRef?.graphId || sourceGraphRef?.sourceDigest);
  if (hasSourceGraphRef) {
    if (!sourceGraphRef?.graphId || !sourceGraphRef?.sourceDigest || typeof repository.getWorkflowGraph !== 'function') {
      throw new ResultCompareError(
        'restore_workflow_graph_invalid',
        'Historical replay metadata does not identify one complete authoritative workflow graph.'
      );
    }
    sourceWorkflowGraph = repository.getWorkflowGraph(sourceGraphRef.graphId);
    if (!sourceWorkflowGraph || sourceWorkflowGraph.projectId !== input.projectId
        || sourceWorkflowGraph.sourceDigest !== sourceGraphRef.sourceDigest
        || sourceWorkflowGraph.validationStatus !== 'valid') {
      throw new ResultCompareError(
        'restore_workflow_graph_invalid',
        'Historical workflow graph is missing, stale, or not valid for this project.'
      );
    }
    const graphScope = validateRestoreWorkflowScope({
      graph: sourceWorkflowGraph,
      sourceRevisions: sourceCohort,
    });
    if (!graphScope.ok) {
      throw new ResultCompareError(
        graphScope.diagnostic?.code || 'restore_workflow_graph_scope_mismatch',
        graphScope.diagnostic?.message || 'Historical workflow graph does not cover the source cohort and only its immutable ancestors.',
        graphScope.diagnostic?.detail || null,
      );
    }
  } else if (sourceToolJobIds.length > 1) {
    throw new ResultCompareError(
      'restore_workflow_graph_missing',
      'A multi-Job historical cohort cannot be restored without its persisted authoritative workflow graph.'
    );
  }
  if (typeof dependencies.getResultStudioDescriptor === 'function') {
    const expectedValidatorIds = sourceToolJobIds.map((toolJobId) => {
      const graphNode = sourceWorkflowGraph?.nodes.find((node) => node.toolJobId === toolJobId) || null;
      const job = typeof getToolJob === 'function' ? getToolJob(toolJobId) : null;
      const toolId = graphNode?.toolId || job?.tool_id || job?.toolId || null;
      const rawDescriptor = toolId ? dependencies.getResultStudioDescriptor(toolId) : null;
      const descriptor = rawDescriptor?.resultStudio || rawDescriptor;
      return typeof descriptor?.validator?.id === 'string' ? descriptor.validator.id.trim() : '';
    });
    if (expectedValidatorIds.some((value) => !value)
        || !sameStringSet(sourceValidatorIds, expectedValidatorIds)) {
      throw new ResultCompareError(
        'restore_validator_proof_mismatch',
        'Historical validator proof does not match the currently trusted plugin descriptors.',
        { sourceToolJobIds },
      );
    }
  }
  const currentByFamily = new Map();
  for (const sourceRevision of sourceCohort) {
    if (sourceRevision.validationStatus === 'blocked') {
      throw new ResultCompareError('revision_not_restorable', 'A blocked Revision cannot become the formal result.');
    }
    const current = repository.getCurrentRevision(sourceRevision.artifactFamilyId, input.projectId);
    if (!current || current.projectId !== input.projectId) {
      throw new ResultCompareError('current_revision_missing', 'Every historical Artifact family must have an exact current Revision.');
    }
    currentByFamily.set(sourceRevision.artifactFamilyId, current);
  }
  const selectedCurrent = currentByFamily.get(target.artifactFamilyId);
  if (sourceCohort.every((revision) => currentByFamily.get(revision.artifactFamilyId)?.revisionId === revision.revisionId)) {
    return { restored: false, idempotent: true, revision: target, cohortRevisions: sourceCohort };
  }
  const restoreIntentRef = `restore:cohort:${resolved.changeSet.changeSetId}`;
  const currentChangeSetIds = new Set([...currentByFamily.values()].map((revision) => revision.changeSetId));
  if (currentChangeSetIds.size === 1) {
    const [currentChangeSetId] = currentChangeSetIds;
    const currentChangeSet = repository.getChangeSet(currentChangeSetId);
    const restoredCohort = currentChangeSet?.status === 'adopted' && currentChangeSet.intentRef === restoreIntentRef
      ? repository.listRevisionsByChangeSet(currentChangeSetId)
      : [];
    const restoredFamilies = new Set(restoredCohort.map((revision) => revision.artifactFamilyId));
    if (restoredCohort.length === sourceCohort.length
        && restoredFamilies.size === sourceCohort.length
        && sourceFamilyIds.every((familyId) => restoredFamilies.has(familyId))
        && restoredCohort.every((revision) => currentByFamily.get(revision.artifactFamilyId)?.revisionId === revision.revisionId)) {
      return {
        restored: false,
        idempotent: true,
        revision: restoredCohort.find((revision) => revision.artifactFamilyId === target.artifactFamilyId),
        cohortRevisions: restoredCohort,
        changeSet: currentChangeSet,
      };
    }
  }

  const changeSetId = randomId('cs');
  const cohortRevisionIds = sourceCohort.map((revision) => revision.revisionId);
  const rows = sourceCohort.map((sourceRevision) => {
    const current = currentByFamily.get(sourceRevision.artifactFamilyId);
    resolveRevisionFile(input.workspaceRoot, sourceRevision);
    const sourceGitPath = sourceRevision.sourceScriptRef?.relativePath
      ? projectGitPath(sourceRevision.sourceScriptRef.relativePath, dependencies.gitPathPrefix)
      : null;
    const parametersGitPath = sourceRevision.parametersRef
      ? projectGitPath(sourceRevision.parametersRef, dependencies.gitPathPrefix)
      : null;
    const sourceContent = sourceRevision.sourceCommit && sourceGitPath
      ? adapter.showFile({ ref: sourceRevision.sourceCommit, filePath: sourceGitPath })
      : null;
    const parametersContent = sourceRevision.sourceCommit && parametersGitPath
      ? adapter.showFile({ ref: sourceRevision.sourceCommit, filePath: parametersGitPath })
      : null;
    if (sourceContent == null || sha256(sourceContent) !== sourceRevision.sourceScriptRef?.sha256
        || parametersContent == null || !sourceRevision.parametersHash
        || sha256(parametersContent) !== sourceRevision.parametersHash) {
      throw new ResultCompareError('restore_material_unavailable', 'Every historical script and parameter snapshot must verify in Git.');
    }
    const revisionId = randomId('rev');
    const extension = path.extname(sourceRevision.sourceScriptRef.relativePath) || '.R';
    const base = path.posix.join('analysis/scripts', sourceRevision.artifactFamilyId, revisionId);
    const scriptRelativePath = path.posix.join(base, `run-script${extension}`);
    const parametersRelativePath = path.posix.join(base, 'parameters.json');
    const manifestRelativePath = path.posix.join(base, 'materialization.json');
    const scriptHash = sha256(sourceContent);
    const parametersHash = sha256(parametersContent);
    const manifestContent = stableJson({
      resultStudioMaterializationVersion: 1,
      restore: true,
      cohort: true,
      changeSetId,
      revisionId,
      restoredFromChangeSetId: resolved.changeSet.changeSetId,
      restoredFromRevisionId: sourceRevision.revisionId,
      restoredCohortRevisionIds: cohortRevisionIds,
      selectedSourceRevisionId: target.revisionId,
      parentRevisionId: current.revisionId,
      artifactFamilyId: sourceRevision.artifactFamilyId,
      artifactId: sourceRevision.artifactId,
      scriptRelativePath,
      scriptSha256: scriptHash,
      parametersRelativePath,
      parametersSha256: parametersHash,
    });
    return {
      sourceRevision,
      current,
      revisionId,
      sourceContent,
      parametersContent,
      scriptRelativePath,
      parametersRelativePath,
      manifestRelativePath,
      manifestContent,
      scriptHash,
      parametersHash,
    };
  });
  const workingBranchRef = `refs/heads/petri/changeset/${changeSetId}`;
  repository.createChangeSet({
    changeSetId,
    projectId: input.projectId,
    conversationId: input.conversationId || null,
    intentRef: restoreIntentRef,
    baseCommit: selectedCurrent.sourceCommit,
    workingBranchRef,
    createdBy: input.createdBy === 'agent' ? 'agent' : 'user',
    parentArtifactRefs: rows.map((row) => row.current.revisionId),
  });
  repository.transitionChangeSet({ changeSetId, to: 'running' });
  try {
    const files = rows.flatMap((row) => [
      { path: row.scriptRelativePath, content: row.sourceContent },
      { path: row.parametersRelativePath, content: row.parametersContent },
      { path: row.manifestRelativePath, content: row.manifestContent },
    ]).map((file) => ({ ...file, path: projectGitPath(file.path, dependencies.gitPathPrefix) }));
    const candidate = adapter.commitVirtualFiles({
      parentCommit: selectedCurrent.sourceCommit,
      ref: workingBranchRef,
      expectedOld: ZERO_OID,
      message: `Petri restore cohort ${resolved.changeSet.changeSetId} (${rows.length} outputs)`,
      files,
    });
    const revisionInputs = rows.map((row) => ({
      revisionId: row.revisionId,
      projectId: input.projectId,
      artifactFamilyId: row.sourceRevision.artifactFamilyId,
      artifactId: row.sourceRevision.artifactId,
      parentRevisionIds: [row.current.revisionId],
      sourceCommit: candidate.commit,
      sourceScriptRef: {
        ...row.sourceRevision.sourceScriptRef,
        relativePath: row.scriptRelativePath,
        sha256: row.scriptHash,
        entryPoint: path.posix.basename(row.scriptRelativePath),
        origin: 'project_materialized',
      },
      inputArtifactRefs: row.sourceRevision.inputArtifactRefs,
      parametersRef: row.parametersRelativePath,
      parametersHash: row.parametersHash,
      toolJobId: row.sourceRevision.toolJobId,
      outputPath: row.sourceRevision.outputPath,
      outputHash: row.sourceRevision.outputHash,
      validationStatus: row.sourceRevision.validationStatus,
      reproducibilityStatus: 'available',
      changeSetId,
    }));
    let restoredWorkflowGraph = null;
    if (sourceWorkflowGraph) {
      const rebound = rebindWorkflowGraphForEquivalentRestore({
        graph: sourceWorkflowGraph,
        sourceRevisions: sourceCohort,
        restoredRevisions: revisionInputs,
        resolveRevision: (revisionId) => repository.getRevision(revisionId),
        resolveSelection: (selectionId) => repository.getSelection(selectionId),
      });
      if (!rebound.ok || !rebound.graph) {
        throw new ResultCompareError(
          rebound.diagnostic?.code || 'restore_workflow_graph_invalid',
          rebound.diagnostic?.message || 'Historical workflow graph cannot be rebound to the restored cohort.',
          rebound.diagnostic?.detail || null,
        );
      }
      restoredWorkflowGraph = rebound.graph;
    }
    const batch = repository.appendRevisionBatch({
      revisions: revisionInputs,
      workflowGraph: restoredWorkflowGraph,
      transition: {
        changeSetId,
        to: 'preview_ready',
        candidateCommit: candidate.commit,
        changedPaths: rows.flatMap((row) => [
          { relativePath: row.scriptRelativePath, changeType: 'added', beforeHash: row.current.sourceScriptRef?.sha256 || null, afterHash: row.scriptHash },
          { relativePath: row.parametersRelativePath, changeType: 'added', beforeHash: row.current.parametersHash, afterHash: row.parametersHash },
          { relativePath: row.manifestRelativePath, changeType: 'added', beforeHash: null, afterHash: sha256(row.manifestContent) },
        ]),
        jobRefs: [...new Set(rows.map((row) => row.sourceRevision.toolJobId))],
        candidateArtifactRefs: revisionInputs.map((revision) => revision.revisionId),
        validationSummary: {
          restore: true,
          cohort: true,
          restoredFromChangeSetId: resolved.changeSet.changeSetId,
          restoredFromRevisionId: target.revisionId,
          restoredCohortRevisionIds: cohortRevisionIds,
          artifactTruthStatus: rows.some((row) => row.sourceRevision.validationStatus === 'degraded') ? 'degraded' : 'valid',
          intentSummary: `恢复历史结果组（${rows.length} 个正式产物）为新的正式版本`,
          impactLevel: 'version_restore',
          affectedScope: rows.length === 1 ? 'current_result_only' : 'historical_changeset_cohort',
          requiresJob: false,
          affectedNodeCount: 0,
          formalArtifactCount: rows.length,
          validatorIds: sourceValidatorIds,
          workflowGraph: restoredWorkflowGraph
            ? { graphId: restoredWorkflowGraph.graphId, sourceDigest: restoredWorkflowGraph.sourceDigest }
            : null,
          sourceWorkflowGraph: sourceWorkflowGraph
            ? { graphId: sourceWorkflowGraph.graphId, sourceDigest: sourceWorkflowGraph.sourceDigest }
            : null,
          restoredWorkflowGraph: restoredWorkflowGraph
            ? { graphId: restoredWorkflowGraph.graphId, sourceDigest: restoredWorkflowGraph.sourceDigest }
            : null,
        },
      },
    });
    const adopted = adoptResultChangeSet({
      projectId: input.projectId,
      workspaceRoot: input.workspaceRoot,
      changeSetId,
    }, { ...dependencies, getToolJob });
    const cohortRevisions = batch.revisions.map((revision) => repository.getRevision(revision.revisionId));
    return {
      restored: true,
      idempotent: false,
      changeSet: adopted.changeSet,
      revision: cohortRevisions.find((revision) => revision.artifactFamilyId === target.artifactFamilyId),
      cohortRevisions,
    };
  } catch (error) {
    const changeSet = repository.getChangeSet(changeSetId);
    if (changeSet?.status === 'running') {
      try { repository.transitionChangeSet({ changeSetId, to: 'validation_failed', reason: error.code || 'restore_failed' }); } catch { /* recovery scan */ }
    }
    throw error;
  }
}

module.exports = {
  RESULT_COMPARE_SERVICE_VERSION,
  ResultCompareError,
  countPatch,
  compareJsonValues,
  compareTables,
  compareResultChangeSet,
  adoptResultChangeSet,
  revertResultChangeSet,
  restoreArtifactRevision,
};

'use strict';

/**
 * G0-RS-P4 — Schema 驱动的编辑控件投影与统一 Patch 归一化。
 *
 * 设计边界（不建第二条编辑链）：
 * - 控件**只**由插件 descriptor 的 `parameters` + `parameterImpacts` 投影而来，
 *   不为任何插件手写孤立结果页；descriptor 没声明的参数不会出现控件。
 * - 手动控件与 AI 意图产出**同一种** `parameterPatch`，随后都走既有
 *   `classifyParameterPatch → planResultEdit → ChangeSet`，
 *   因此 validation / preview / compare / adopt / revert 只有一条路径。
 * - 影响分级只能由受信 descriptor 提升，不能被调用方降级；未知参数保守
 *   落到 `scientific_recompute`（由 result-edit-intent 负责），这里不猜。
 * - 越界或类型不符的值 fail-closed 拒绝，不静默 clamp 成"看起来成功"。
 *   R 脚本里的 clamp 是运行时最后防线，不是本层的借口。
 */

const {
  RESULT_EDIT_CLASSES,
  classifyParameterPatch,
} = require('./result-edit-intent');

const RESULT_EDIT_CONTROLS_VERSION = 1;

/** descriptor 声明的 impact → 控件分组。分组只影响呈现顺序与解释文案。 */
const CONTROL_GROUPS = Object.freeze({
  view: 'presentation',
  presentation: 'presentation',
  data: 'data',
  scientific: 'scientific',
  workflow: 'workflow',
});

const GROUP_ORDER = Object.freeze(['presentation', 'data', 'scientific', 'workflow']);

const GROUP_LABELS = Object.freeze({
  presentation: '外观与导出',
  data: '数据呈现',
  scientific: '科学参数',
  workflow: '方法与流程',
});

/** 控件类型只从 descriptor 的参数类型派生，不猜测语义。 */
const SUPPORTED_CONTROL_TYPES = Object.freeze(['number', 'text', 'select', 'color', 'boolean']);

/** 名称模式 → color 控件。仅影响输入部件，不改变 impact 或校验规则。 */
const COLOR_NAME_PATTERN = /(^|_)(color|colour|palette)(_|$)/i;
const HEX_COLOR_PATTERN = /^#[0-9a-fA-F]{6}$/;

function trimmed(value) {
  return typeof value === 'string' ? value.trim() : '';
}

function diagnostic(code, message, detail = null) {
  return { code, message, ...(detail == null ? {} : { detail }) };
}

/**
 * 判定控件部件类型。
 *
 * `color` 是 `text` 的一个更严格子集：仍然是字符串参数，但必须是 #rrggbb，
 * 且 UI 可以给取色器。它不改变 impact，也不放宽校验。
 */
function resolveControlType(name, parameter) {
  const declared = trimmed(parameter && parameter.type);
  if (declared === 'select') return 'select';
  if (declared === 'number') return 'number';
  if (declared === 'boolean') return 'boolean';
  if (declared === 'text') {
    const defaultValue = parameter && parameter.default;
    if (COLOR_NAME_PATTERN.test(name) && (typeof defaultValue !== 'string' || HEX_COLOR_PATTERN.test(defaultValue))) {
      return 'color';
    }
    return 'text';
  }
  return null;
}

/**
 * 把插件 descriptor 投影成有界控件列表。
 *
 * 只有同时声明了 `parameters[name]` 与 `parameterImpacts[name]` 的参数才成为
 * 控件——缺 impact 的参数无法判断改动后果，让它可编辑等于默认它安全。
 *
 * @param {object} descriptor 已通过 Plugin SDK lint 的 resultStudio descriptor
 * @returns {{ controlsVersion: number, controls: Array, groups: Array, diagnostics: Array }}
 */
function buildEditControlSchema(descriptor) {
  const diagnostics = [];
  if (!descriptor || typeof descriptor !== 'object' || Array.isArray(descriptor)) {
    return {
      controlsVersion: RESULT_EDIT_CONTROLS_VERSION,
      controls: [],
      groups: [],
      diagnostics: [diagnostic('control_descriptor_missing', '插件没有可信的 Result Studio descriptor，无法生成参数控件。')],
    };
  }
  const parameters = descriptor.parameters && typeof descriptor.parameters === 'object' ? descriptor.parameters : {};
  const impacts = descriptor.parameterImpacts && typeof descriptor.parameterImpacts === 'object'
    ? descriptor.parameterImpacts
    : {};

  const controls = [];
  for (const name of Object.keys(parameters).sort()) {
    const parameter = parameters[name];
    const impact = trimmed(impacts[name]);
    if (!impact) {
      // 缺 impact 不是"默认安全"，而是不可编辑。
      diagnostics.push(diagnostic('control_impact_undeclared', `参数 ${name} 没有声明影响级别，因此不提供控件。`, { parameter: name }));
      continue;
    }
    const group = CONTROL_GROUPS[impact];
    if (!group) {
      diagnostics.push(diagnostic('control_impact_unknown', `参数 ${name} 的影响级别无法识别。`, { parameter: name, impact }));
      continue;
    }
    const controlType = resolveControlType(name, parameter);
    if (!controlType) {
      diagnostics.push(diagnostic('control_type_unsupported', `参数 ${name} 的类型不支持可视化编辑。`, { parameter: name }));
      continue;
    }
    const control = {
      name,
      controlType,
      impact,
      group,
      default: parameter && parameter.default !== undefined ? parameter.default : null,
      required: parameter && parameter.required === true,
    };
    if (controlType === 'number') {
      control.minimum = Number.isFinite(parameter.minimum) ? parameter.minimum : null;
      control.maximum = Number.isFinite(parameter.maximum) ? parameter.maximum : null;
    }
    if (controlType === 'select') {
      const options = Array.isArray(parameter.options)
        ? parameter.options.filter((option) => typeof option === 'string' && option.trim())
        : [];
      if (options.length === 0) {
        diagnostics.push(diagnostic('control_options_missing', `参数 ${name} 声明为选择项但没有可选值。`, { parameter: name }));
        continue;
      }
      control.options = options;
    }
    // 只有 presentation 分组才允许在 UI 上标注"不改变科学结论"。
    control.scientificallyNeutral = group === 'presentation';
    controls.push(control);
  }

  const groups = GROUP_ORDER
    .filter((group) => controls.some((control) => control.group === group))
    .map((group) => ({
      group,
      label: GROUP_LABELS[group],
      parameterNames: controls.filter((control) => control.group === group).map((control) => control.name),
    }));

  return { controlsVersion: RESULT_EDIT_CONTROLS_VERSION, controls, groups, diagnostics };
}

/**
 * 校验单个参数值是否符合 descriptor 契约。
 *
 * fail-closed：越界、类型不符、非法枚举值一律拒绝并说明原因，
 * 不做静默修正——静默修正会让用户以为改动生效了。
 */
function validateControlValue(control, value) {
  if (!control) return { ok: false, diagnostics: [diagnostic('control_unknown_parameter', '该参数不在插件声明的可编辑范围内。')] };
  const diagnostics = [];
  if (value === null || value === undefined) {
    return { ok: false, diagnostics: [diagnostic('control_value_required', `参数 ${control.name} 需要一个值。`, { parameter: control.name })] };
  }
  switch (control.controlType) {
    case 'number': {
      const numeric = typeof value === 'number' ? value : Number(value);
      if (!Number.isFinite(numeric)) {
        diagnostics.push(diagnostic('control_value_not_number', `参数 ${control.name} 必须是数字。`, { parameter: control.name }));
        break;
      }
      if (control.minimum !== null && numeric < control.minimum) {
        diagnostics.push(diagnostic('control_value_below_minimum', `参数 ${control.name} 不能小于 ${control.minimum}。`, { parameter: control.name, minimum: control.minimum }));
      }
      if (control.maximum !== null && numeric > control.maximum) {
        diagnostics.push(diagnostic('control_value_above_maximum', `参数 ${control.name} 不能大于 ${control.maximum}。`, { parameter: control.name, maximum: control.maximum }));
      }
      if (diagnostics.length === 0) return { ok: true, diagnostics: [], value: numeric };
      break;
    }
    case 'select': {
      const normalized = trimmed(value);
      if (!control.options.includes(normalized)) {
        diagnostics.push(diagnostic('control_value_not_allowed', `参数 ${control.name} 只能是声明的可选值之一。`, { parameter: control.name, options: control.options }));
        break;
      }
      return { ok: true, diagnostics: [], value: normalized };
    }
    case 'color': {
      const normalized = trimmed(value);
      if (!HEX_COLOR_PATTERN.test(normalized)) {
        diagnostics.push(diagnostic('control_value_not_color', `参数 ${control.name} 必须是 #RRGGBB 形式的颜色。`, { parameter: control.name }));
        break;
      }
      return { ok: true, diagnostics: [], value: normalized.toLowerCase() };
    }
    case 'boolean': {
      if (typeof value !== 'boolean') {
        diagnostics.push(diagnostic('control_value_not_boolean', `参数 ${control.name} 必须是布尔值。`, { parameter: control.name }));
        break;
      }
      return { ok: true, diagnostics: [], value };
    }
    case 'text': {
      if (typeof value !== 'string') {
        diagnostics.push(diagnostic('control_value_not_text', `参数 ${control.name} 必须是文本。`, { parameter: control.name }));
        break;
      }
      const normalized = value.trim();
      if (normalized.length > 200) {
        diagnostics.push(diagnostic('control_value_too_long', `参数 ${control.name} 超过 200 字符。`, { parameter: control.name }));
        break;
      }
      return { ok: true, diagnostics: [], value: normalized };
    }
    default:
      diagnostics.push(diagnostic('control_type_unsupported', `参数 ${control.name} 的类型不支持编辑。`, { parameter: control.name }));
  }
  return { ok: false, diagnostics };
}

/**
 * 把手动控件输入或 AI 提议归一化为同一个受信 patch。
 *
 * 两个来源共用本函数，因此不存在"AI 走一条校验、手动走另一条"的分叉。
 * `origin` 只用于审计与解释文案，不影响任何校验强度。
 *
 * @param {object} params
 * @param {object} params.descriptor 受信插件 descriptor
 * @param {object} params.proposedValues 参数名 → 值
 * @param {'manual'|'agent'} [params.origin]
 * @param {object} [params.currentValues] 当前生效参数，用于剔除无变化项
 * @returns {{ ok: boolean, patch: object, changed: Array, unchanged: Array, rejected: Array, diagnostics: Array, classification: object|null, origin: string }}
 */
function normalizeEditSubmission({
  descriptor,
  proposedValues = {},
  origin = 'manual',
  currentValues = {},
} = {}) {
  const normalizedOrigin = origin === 'agent' ? 'agent' : 'manual';
  const schema = buildEditControlSchema(descriptor);
  const byName = new Map(schema.controls.map((control) => [control.name, control]));
  const diagnostics = [];
  const patch = {};
  const changed = [];
  const unchanged = [];
  const rejected = [];

  const values = proposedValues && typeof proposedValues === 'object' && !Array.isArray(proposedValues)
    ? proposedValues
    : {};

  for (const name of Object.keys(values).sort()) {
    const control = byName.get(name);
    if (!control) {
      // 未声明参数不进 patch：既不静默丢弃也不假装接受，明确记为 rejected。
      rejected.push(name);
      diagnostics.push(diagnostic(
        'control_unknown_parameter',
        `参数 ${name} 不在插件声明的可编辑范围内，已拒绝。`,
        { parameter: name }
      ));
      continue;
    }
    const validated = validateControlValue(control, values[name]);
    if (!validated.ok) {
      rejected.push(name);
      diagnostics.push(...validated.diagnostics);
      continue;
    }
    const currentValue = Object.prototype.hasOwnProperty.call(currentValues, name) ? currentValues[name] : undefined;
    if (currentValue !== undefined && currentValue === validated.value) {
      unchanged.push(name);
      continue;
    }
    patch[name] = validated.value;
    changed.push(name);
  }

  // 分级永远由受信 descriptor 决定；调用方不能声明自己的 editClass。
  const classification = Object.keys(patch).length > 0
    ? classifyParameterPatch({
      proposedParameterPatch: patch,
      parameterImpactRules: descriptor && descriptor.parameterImpacts,
    })
    : null;

  return {
    ok: rejected.length === 0 && Object.keys(patch).length > 0,
    patch,
    changed,
    unchanged,
    rejected,
    diagnostics,
    classification,
    origin: normalizedOrigin,
  };
}

/**
 * 生成执行前的人类可读影响说明。
 *
 * 只陈述受信分级得出的后果，不承诺"很快"或"没有风险"。
 */
function explainEditImpact(classification, { affectedNodeIds = [], affectedScope = 'none' } = {}) {
  if (!classification) {
    return {
      editClass: null,
      headline: '没有需要执行的参数变化。',
      requiresJob: false,
      requiresScientificConfirmation: false,
      rerunsScience: false,
      affectedNodeCount: 0,
      affectedScope: 'none',
      parameterImpacts: [],
    };
  }
  const editClass = classification.editClass;
  const rerunsScience = editClass === 'scientific_recompute' || editClass === 'workflow_replan';
  const headline = editClass === 'presentation_rerender'
    ? '只改变结果的呈现方式，不重新计算科学结论。'
    : editClass === 'data_transform'
      ? '改变结果的数据呈现范围，需要重新生成该产物。'
      : editClass === 'scientific_recompute'
        ? '改变科学参数，需要重新计算并确认结论变化。'
        : editClass === 'workflow_replan'
          ? '改变方法或流程，需要重新规划下游步骤并确认。'
          : '仅查看，不产生新版本。';
  return {
    editClass,
    headline,
    requiresJob: classification.requiresJob === true,
    requiresScientificConfirmation: classification.requiresScientificConfirmation === true,
    rerunsScience,
    usedConservativeFallback: classification.usedConservativeFallback === true,
    affectedNodeCount: Array.isArray(affectedNodeIds) ? affectedNodeIds.length : 0,
    affectedScope: ['current_result_only', 'workflow_subgraph'].includes(affectedScope)
      ? affectedScope
      : 'none',
    parameterImpacts: Array.isArray(classification.parameterImpacts) ? classification.parameterImpacts : [],
  };
}

module.exports = {
  RESULT_EDIT_CONTROLS_VERSION,
  RESULT_EDIT_CLASSES,
  CONTROL_GROUPS,
  GROUP_ORDER,
  GROUP_LABELS,
  SUPPORTED_CONTROL_TYPES,
  buildEditControlSchema,
  validateControlValue,
  normalizeEditSubmission,
  explainEditImpact,
};

'use strict';

const crypto = require('node:crypto');
const { isAuthoritativeWorkflowPlan } = require('./result-workflow-graph');
const { verifyExecutionProvenance } = require('./execution-provenance');

const RESULT_EDIT_INTENT_VERSION = 1;
const RESULT_EDIT_CLASSES = Object.freeze([
  'view_only',
  'presentation_rerender',
  'data_transform',
  'scientific_recompute',
  'workflow_replan',
]);
const IMPACT_ALIASES = Object.freeze({
  view: 'view_only',
  presentation: 'presentation_rerender',
  data: 'data_transform',
  scientific: 'scientific_recompute',
  workflow: 'workflow_replan',
});
const CLASS_RANK = new Map(RESULT_EDIT_CLASSES.map((value, index) => [value, index]));
const SCIENTIFIC_FIELDS = new Set([
  'design', 'design_formula', 'formula', 'contrast', 'contrast_ref', 'contrast_treat',
]);
const WORKFLOW_FIELDS = new Set([
  'method', 'algorithm', 'tool', 'tool_id', 'plugin', 'plugin_id', 'workflow',
]);

function trimmed(value) {
  return typeof value === 'string' ? value.trim() : '';
}

function stableValue(value) {
  if (Array.isArray(value)) return value.map(stableValue);
  if (!value || typeof value !== 'object') return value;
  return Object.fromEntries(Object.keys(value).sort().map((key) => [key, stableValue(value[key])]));
}

function digest(value) {
  return crypto.createHash('sha256').update(JSON.stringify(stableValue(value))).digest('hex');
}

function diagnostic(code, message, detail = null) {
  return { code, message, ...(detail == null ? {} : { detail }) };
}

function normalizeImpact(value) {
  const normalized = trimmed(value);
  if (RESULT_EDIT_CLASSES.includes(normalized)) return normalized;
  return IMPACT_ALIASES[normalized] || null;
}

function normalizeRules(rules) {
  if (!rules || typeof rules !== 'object' || Array.isArray(rules)) return {};
  const normalized = {};
  for (const [parameter, impact] of Object.entries(rules)) {
    const value = normalizeImpact(impact);
    if (trimmed(parameter) && value) normalized[parameter] = value;
  }
  return normalized;
}

function classifyParameterPatch({ proposedParameterPatch = {}, parameterImpactRules = {}, requestedEditClass = null } = {}) {
  const patch = proposedParameterPatch && typeof proposedParameterPatch === 'object' && !Array.isArray(proposedParameterPatch)
    ? proposedParameterPatch
    : {};
  const rules = normalizeRules(parameterImpactRules);
  const fields = Object.keys(patch).sort();
  const parameterImpacts = [];
  let editClass = fields.length === 0 ? normalizeImpact(requestedEditClass) || 'view_only' : 'view_only';
  let usedConservativeFallback = false;

  for (const field of fields) {
    const normalizedField = field.trim().toLowerCase().replace(/[.\s-]+/g, '_');
    // 保护字段是**下限**，不是覆盖：它保证 `design`、`method` 这类字段永远不会
    // 被当成样式改动，但当受信 descriptor 声明了更高影响时（例如 DESeq2 把
    // `design` 声明为 workflow），必须采用更高的那个。此前的 if/else 链让保护
    // 字段抢先命中并把已声明的 workflow_replan 降级成 scientific_recompute，
    // 等于让"重新规划下游"被静默说成"只重算本节点"。
    let floorImpact = null;
    let floorSource = null;
    if (WORKFLOW_FIELDS.has(normalizedField)) {
      floorImpact = 'workflow_replan';
      floorSource = 'protected_workflow_field';
    } else if (SCIENTIFIC_FIELDS.has(normalizedField)) {
      floorImpact = 'scientific_recompute';
      floorSource = 'protected_scientific_field';
    }
    const declaredImpact = rules[field] || null;
    let impact;
    let source;
    if (declaredImpact && floorImpact) {
      // 取两者中更保守（rank 更高）的一个，绝不向下取。
      if (CLASS_RANK.get(declaredImpact) >= CLASS_RANK.get(floorImpact)) {
        impact = declaredImpact;
        source = 'declared_parameter_impact';
      } else {
        impact = floorImpact;
        source = floorSource;
      }
    } else if (floorImpact) {
      impact = floorImpact;
      source = floorSource;
    } else if (declaredImpact) {
      impact = declaredImpact;
      source = 'declared_parameter_impact';
    } else {
      impact = 'scientific_recompute';
      source = 'conservative_unknown_parameter';
      usedConservativeFallback = true;
    }
    if (CLASS_RANK.get(impact) > CLASS_RANK.get(editClass)) editClass = impact;
    parameterImpacts.push({ parameter: field, impact, source });
  }

  const requested = normalizeImpact(requestedEditClass);
  if (requested && CLASS_RANK.get(requested) > CLASS_RANK.get(editClass)) editClass = requested;
  const requiresScientificConfirmation =
    usedConservativeFallback || ['scientific_recompute', 'workflow_replan'].includes(editClass);

  return {
    editClass,
    parameterImpacts,
    usedConservativeFallback,
    requiresJob: editClass !== 'view_only',
    requiresScientificConfirmation,
    classificationReason: parameterImpacts.length
      ? parameterImpacts.map((item) => `${item.parameter}:${item.impact}(${item.source})`).join('; ')
      : `explicit:${editClass}`,
  };
}

function parseJobResult(job) {
  if (!job) return {};
  if (job.result && typeof job.result === 'object') return job.result;
  if (job.result_json && typeof job.result_json === 'object') return job.result_json;
  try {
    return JSON.parse(job.result_json || '{}');
  } catch {
    return {};
  }
}

function exactArtifact(result, artifactId) {
  const artifacts = Array.isArray(result.artifacts) ? result.artifacts : [];
  const matches = artifacts.filter((artifact) => artifact && artifact.id === artifactId);
  return matches.length === 1 ? matches[0] : null;
}

function hasStructuredInputLineage(input) {
  const lineage = input?.lineage;
  if (!lineage || typeof lineage !== 'object' || Array.isArray(lineage)
      || lineage.lineageVersion !== 1 || !['artifact', 'selection'].includes(lineage.kind)) return false;
  const sha256 = /^[a-f0-9]{64}$/;
  if (!trimmed(lineage.sourceRevisionId) || !trimmed(lineage.sourceToolJobId)
      || !trimmed(lineage.sourceArtifactId) || !sha256.test(trimmed(lineage.sourceOutputHash))
      || !sha256.test(trimmed(lineage.materializationHash))
      || trimmed(input?.sha256) !== trimmed(lineage.materializationHash)) return false;
  return lineage.kind === 'artifact'
    ? trimmed(lineage.materializationHash) === trimmed(lineage.sourceOutputHash)
    : Boolean(trimmed(lineage.selectionId) && sha256.test(trimmed(lineage.selectionHash)));
}

function locateResultSource({ toolJob, artifactId, projectId } = {}) {
  const diagnostics = [];
  if (!toolJob) return { ok: false, diagnostics: [diagnostic('source_job_not_found', 'Source tool job was not found.')] };
  const jobProjectId = trimmed(toolJob.project_id || toolJob.projectId);
  if (!trimmed(projectId) || jobProjectId !== trimmed(projectId)) {
    return { ok: false, diagnostics: [diagnostic('source_project_mismatch', 'Source job does not belong to the active project.')] };
  }
  if (toolJob.status !== 'completed') {
    diagnostics.push(diagnostic('source_job_not_completed', `Source job status is ${toolJob.status || 'unknown'}.`));
  }
  const result = parseJobResult(toolJob);
  if (!result.artifactTruth || result.artifactTruth.status !== 'valid' || result.artifactTruth.blocking === true) {
    diagnostics.push(diagnostic('source_artifact_truth_invalid', 'Source job has no valid, non-blocking artifact truth.'));
  }
  const artifact = exactArtifact(result, artifactId);
  if (!artifact) {
    diagnostics.push(diagnostic('source_artifact_not_found', 'Artifact id was not found exactly once in the source job; filenames are not used as identity.'));
  }
  const provenance = result.executionProvenance || null;
  if (!provenance || provenance.toolJobId !== toolJob.id) {
    diagnostics.push(diagnostic('source_provenance_missing', 'Execution provenance is missing or does not bind to the source job.'));
  }
  if (provenance && !verifyExecutionProvenance(provenance).ok) {
    diagnostics.push(diagnostic('source_provenance_integrity_invalid', 'Execution provenance no longer matches its server-issued digest.'));
  }
  if (provenance && trimmed(provenance.projectId) && trimmed(provenance.projectId) !== trimmed(projectId)) {
    diagnostics.push(diagnostic('source_provenance_project_mismatch', 'Execution provenance belongs to another project.'));
  }
  const provenanceArtifact = provenance && Array.isArray(provenance.artifacts)
    ? provenance.artifacts.filter((item) => item && item.id === artifactId)
    : [];
  if (provenance && provenanceArtifact.length !== 1) {
    diagnostics.push(diagnostic('source_artifact_provenance_missing', 'Artifact is not uniquely bound by id in execution provenance.'));
  }
  const script = provenance && provenance.script;
  if (!script || !trimmed(script.snapshotPath) || !trimmed(script.sha256)) {
    diagnostics.push(diagnostic('source_script_missing', 'A reproducible source script snapshot and hash are required.'));
  }
  const inputs = provenance && Array.isArray(provenance.inputs) ? provenance.inputs : [];
  if (inputs.length === 0 || inputs.some((input) => !input || !trimmed(input.relativePath) || !trimmed(input.sha256))) {
    diagnostics.push(diagnostic('source_inputs_missing', 'Hashed execution inputs are required to plan a reproducible edit.'));
  }

  return {
    ok: diagnostics.length === 0,
    diagnostics,
    source: {
      toolJobId: toolJob.id,
      toolId: toolJob.tool_id || toolJob.toolId || null,
      artifact: artifact ? { id: artifact.id, type: artifact.type || null } : null,
      provenanceHash: provenance && provenance.provenanceHash || null,
      script: script ? {
        snapshotPath: script.snapshotPath,
        sha256: script.sha256,
        entryPoint: script.entryPoint || null,
      } : null,
      inputs: inputs.map((input) => ({
        id: input.id || null,
        role: input.role || null,
        relativePath: input.relativePath,
        sha256: input.sha256,
        sourceArtifactRef: input.sourceArtifactRef || null,
        hasStructuredLineage: hasStructuredInputLineage(input),
        lineageKind: hasStructuredInputLineage(input) ? input.lineage.kind : null,
      })),
    },
  };
}

function validateWorkflow(workflowPlan) {
  const steps = workflowPlan && Array.isArray(workflowPlan.steps) ? workflowPlan.steps : null;
  // Preserve the useful distinction between "there is no graph" and
  // "someone supplied an invented graph".  Both are fail-closed for science,
  // but only the latter is an authority violation.
  if (!steps || steps.length === 0) {
    return { ok: false, diagnostics: [diagnostic('workflow_dag_missing', 'A real workflow DAG is required for affected-subgraph planning.')] };
  }
  if (!isAuthoritativeWorkflowPlan(workflowPlan)) {
    return {
      ok: false,
      diagnostics: [diagnostic(
        'workflow_dag_not_authoritative',
        'Scientific impact requires a workflow graph projected from persisted SQLite Job, Artifact and Selection Truth.'
      )],
    };
  }
  const ids = steps.map((step) => trimmed(step && step.id));
  if (ids.some((id) => !id) || new Set(ids).size !== ids.length) {
    return { ok: false, diagnostics: [diagnostic('workflow_node_ambiguous', 'Workflow node ids must be present and unique.')] };
  }
  const idSet = new Set(ids);
  const downstream = new Map(ids.map((id) => [id, []]));
  for (const step of steps) {
    const dependencies = Array.isArray(step.dependsOn) ? step.dependsOn : [];
    for (const dependency of dependencies) {
      if (!idSet.has(dependency)) {
        return { ok: false, diagnostics: [diagnostic('workflow_dependency_missing', `Workflow dependency does not exist: ${dependency}`)] };
      }
      downstream.get(dependency).push(step.id);
    }
  }
  const visiting = new Set();
  const visited = new Set();
  function visit(id) {
    if (visiting.has(id)) return false;
    if (visited.has(id)) return true;
    visiting.add(id);
    for (const child of downstream.get(id)) if (!visit(child)) return false;
    visiting.delete(id);
    visited.add(id);
    return true;
  }
  if (!ids.every(visit)) {
    return { ok: false, diagnostics: [diagnostic('workflow_cycle_detected', 'Workflow DAG contains a cycle.')] };
  }
  return { ok: true, steps, downstream, diagnostics: [] };
}

function computeResultAffectedSubgraph({ workflowPlan, sourceToolJobId, sourceNodeId, editClass } = {}) {
  if (editClass === 'view_only') {
    return { ok: true, sourceNodeId: null, affectedNodeIds: [], affectedScope: 'none', diagnostics: [] };
  }
  const workflowSteps = workflowPlan && Array.isArray(workflowPlan.steps) ? workflowPlan.steps : null;
  // A presentation-only rerender has a truthful bounded scope even when this
  // historical Job was not created from a persisted workflow DAG: it affects
  // the current result only. Scientific/data/workflow changes still require a
  // real DAG so downstream impact can never be guessed away.
  if (editClass === 'presentation_rerender' && (!workflowSteps || workflowSteps.length === 0)) {
    return {
      ok: true,
      sourceNodeId: null,
      affectedNodeIds: [],
      affectedScope: 'current_result_only',
      diagnostics: [],
    };
  }
  const validated = validateWorkflow(workflowPlan);
  if (!validated.ok) {
    return {
      ok: false, sourceNodeId: null, affectedNodeIds: [], affectedScope: 'unknown', diagnostics: validated.diagnostics,
    };
  }
  let matches = [];
  if (trimmed(sourceNodeId)) matches = validated.steps.filter((step) => step.id === sourceNodeId);
  else matches = validated.steps.filter((step) => (step.toolJobId || step.tool_job_id) === sourceToolJobId);
  if (matches.length !== 1) {
    return {
      ok: false,
      sourceNodeId: null,
      affectedNodeIds: [],
      affectedScope: 'unknown',
      diagnostics: [diagnostic('source_workflow_node_ambiguous', 'The source job must map to exactly one workflow node.')],
    };
  }
  const root = matches[0].id;
  if (editClass === 'presentation_rerender') {
    return {
      ok: true, sourceNodeId: root, affectedNodeIds: [root], affectedScope: 'current_result_only', diagnostics: [],
    };
  }
  const affected = [];
  const queue = [root];
  const seen = new Set();
  while (queue.length) {
    const id = queue.shift();
    if (seen.has(id)) continue;
    seen.add(id);
    affected.push(id);
    queue.push(...validated.downstream.get(id));
  }
  return {
    ok: true, sourceNodeId: root, affectedNodeIds: affected, affectedScope: 'workflow_subgraph', diagnostics: [],
  };
}

function validateResultEditIntent(intent) {
  const errors = [];
  if (!intent || typeof intent !== 'object' || Array.isArray(intent)) {
    return { ok: false, errors: [diagnostic('intent_invalid', 'Intent must be an object.')] };
  }
  if (intent.contractVersion !== String(RESULT_EDIT_INTENT_VERSION)) errors.push(diagnostic('intent_version_unsupported', 'Unsupported intent contract version.'));
  if (!trimmed(intent.intentId)) errors.push(diagnostic('intent_id_required', 'intentId is required.'));
  if (!intent.artifactRef || !trimmed(intent.artifactRef.artifactId) || !trimmed(intent.artifactRef.revisionId)) errors.push(diagnostic('artifact_ref_incomplete', 'artifactId and revisionId are required.'));
  if (!RESULT_EDIT_CLASSES.includes(intent.editClass)) errors.push(diagnostic('edit_class_invalid', 'Unknown edit class.'));
  if (!Array.isArray(intent.affectedNodeIds)) errors.push(diagnostic('affected_nodes_invalid', 'affectedNodeIds must be an array.'));
  // Additive P4R-3 field: historical persisted/test intents without it remain
  // valid, while newly planned intents always carry an explicit honest scope.
  if (intent.affectedScope != null
      && !['none', 'current_result_only', 'workflow_subgraph'].includes(intent.affectedScope)) {
    errors.push(diagnostic('affected_scope_invalid', 'affectedScope must describe the truthful impact boundary.'));
  }
  const graph = intent.workflowGraph;
  if (graph != null && (!graph || typeof graph !== 'object' || Array.isArray(graph)
      || !trimmed(graph.graphId).startsWith('wfg_') || !/^[a-f0-9]{64}$/.test(trimmed(graph.sourceDigest)))) {
    errors.push(diagnostic('workflow_graph_ref_invalid', 'workflowGraph must reference a source-bound authoritative graph.'));
  }
  if (['data_transform', 'scientific_recompute', 'workflow_replan'].includes(intent.editClass)
      && (!graph || !trimmed(graph.graphId).startsWith('wfg_') || !/^[a-f0-9]{64}$/.test(trimmed(graph.sourceDigest)))) {
    errors.push(diagnostic('workflow_graph_ref_required', 'Scientific, data and workflow edits require an authoritative persisted workflow graph reference.'));
  }
  if (typeof intent.requiresJob !== 'boolean') errors.push(diagnostic('requires_job_invalid', 'requiresJob must be boolean.'));
  if (typeof intent.requiresScientificConfirmation !== 'boolean') errors.push(diagnostic('scientific_confirmation_invalid', 'requiresScientificConfirmation must be boolean.'));
  if (!trimmed(intent.requestedOutcome)) errors.push(diagnostic('requested_outcome_required', 'requestedOutcome is required.'));
  return { ok: errors.length === 0, errors };
}

function planResultEdit(input = {}) {
  const classification = classifyParameterPatch(input);
  const source = locateResultSource({
    toolJob: input.toolJob,
    artifactId: input.artifactId,
    projectId: input.projectId,
  });
  const graph = computeResultAffectedSubgraph({
    workflowPlan: input.workflowPlan,
    sourceToolJobId: input.toolJob && input.toolJob.id,
    sourceNodeId: input.sourceNodeId,
    editClass: classification.editClass,
  });
  const diagnostics = [...source.diagnostics, ...graph.diagnostics];
  if (source.ok && graph.ok && graph.sourceNodeId && input.workflowPlan) {
    const sourceStep = input.workflowPlan.steps.find((step) => step.id === graph.sourceNodeId);
    const hasUpstreamDependency = sourceStep && Array.isArray(sourceStep.dependsOn) && sourceStep.dependsOn.length > 0;
    const hasExplicitArtifactLineage = source.source.inputs.some((item) =>
      trimmed(item.sourceArtifactRef) || item.hasStructuredLineage === true);
    if (hasUpstreamDependency && !hasExplicitArtifactLineage) {
      diagnostics.push(diagnostic(
        'source_lineage_missing',
        'A source node with upstream dependencies requires signed structured lineage or an explicit sourceArtifactRef; filenames are never used to infer lineage.'
      ));
    }
  }
  if (!trimmed(input.revisionId)) diagnostics.push(diagnostic('source_revision_missing', 'A persisted source revision id is required.'));
  if (!trimmed(input.requestedOutcome)) diagnostics.push(diagnostic('requested_outcome_required', 'requestedOutcome is required.'));
  const blocked = diagnostics.length > 0;
  const intentCore = {
    contractVersion: String(RESULT_EDIT_INTENT_VERSION),
    artifactRef: { artifactId: trimmed(input.artifactId), revisionId: trimmed(input.revisionId) },
    ...(trimmed(input.userMessageId) ? { userMessageId: trimmed(input.userMessageId) } : {}),
    ...(trimmed(input.selectionId) ? { selectionRef: trimmed(input.selectionId) } : {}),
    requestedOutcome: trimmed(input.requestedOutcome),
    editClass: classification.editClass,
    proposedParameterPatch: input.proposedParameterPatch && typeof input.proposedParameterPatch === 'object' && !Array.isArray(input.proposedParameterPatch)
      ? input.proposedParameterPatch
      : {},
    affectedNodeIds: blocked ? [] : graph.affectedNodeIds,
    affectedScope: blocked ? 'unknown' : graph.affectedScope,
    requiresJob: classification.requiresJob,
    requiresScientificConfirmation: classification.requiresScientificConfirmation,
    classificationReason: classification.classificationReason,
    ...(graph.ok && isAuthoritativeWorkflowPlan(input.workflowPlan)
      ? { workflowGraph: { graphId: input.workflowPlan.graphId, sourceDigest: input.workflowPlan.sourceDigest } }
      : {}),
  };
  const intent = { ...intentCore, intentId: `rei_${digest(intentCore).slice(0, 24)}` };
  const validation = validateResultEditIntent(intent);
  return {
    ok: !blocked && validation.ok,
    status: blocked || !validation.ok ? 'blocked' : classification.requiresScientificConfirmation ? 'confirmation_required' : 'ready',
    intent,
    source: source.source || null,
    sourceNodeId: graph.sourceNodeId,
    parameterImpacts: classification.parameterImpacts,
    diagnostics: [...diagnostics, ...validation.errors],
    execution: { performed: false, toolJobCreated: false, changeSetCreated: false },
  };
}

module.exports = {
  RESULT_EDIT_INTENT_VERSION,
  RESULT_EDIT_CLASSES,
  classifyParameterPatch,
  locateResultSource,
  computeResultAffectedSubgraph,
  validateResultEditIntent,
  planResultEdit,
};

'use strict';

/**
 * Result Studio candidate validation is descriptor-driven and fail-closed.
 * Artifact Truth proves that declared files exist; this module additionally
 * proves their exact bytes and the scientific invariants named by the plugin.
 */

const crypto = require('node:crypto');
const fs = require('node:fs');
const path = require('node:path');
const { isPathContained } = require('./project-run-layout');
const { resolveExecutionInputPath } = require('./execution-provenance');

const RESULT_PLUGIN_VALIDATOR_VERSION = 1;
const MAX_SEMANTIC_BYTES = 64 * 1024 * 1024;
const MAX_SEMANTIC_ROWS = 500_000;
const SHA256 = /^[a-f0-9]{64}$/;
const SUPPORTED_CHECKS = new Set([
  'artifact_truth_valid',
  'script_sha256',
  'input_sha256',
  'output_sha256',
  'stable_gene_id',
  'stable_term_id',
  'empty_result_is_valid',
  'finite_statistics',
  'symmetric_matrix',
]);

function hashFile(filePath) {
  return crypto.createHash('sha256').update(fs.readFileSync(filePath)).digest('hex');
}

function trimmed(value) {
  return typeof value === 'string' ? value.trim() : '';
}

function diagnostic(code, message, detail = null) {
  return { code, message, ...(detail == null ? {} : { detail }) };
}

function resultOf(job) {
  if (!job) return {};
  if (job.result && typeof job.result === 'object') return job.result;
  try { return JSON.parse(job.result_json || '{}'); } catch { return {}; }
}

function detectDelimiter(raw) {
  let quoted = false;
  let commas = 0;
  let tabs = 0;
  for (let index = 0; index < raw.length; index += 1) {
    const char = raw[index];
    if (char === '"') {
      if (quoted && raw[index + 1] === '"') index += 1;
      else quoted = !quoted;
    } else if (!quoted && (char === '\n' || char === '\r')) break;
    else if (!quoted && char === ',') commas += 1;
    else if (!quoted && char === '\t') tabs += 1;
  }
  return tabs > commas ? '\t' : ',';
}

function parseDelimitedRecords(raw, delimiter) {
  const records = [];
  let record = [];
  let cell = '';
  let quoted = false;
  let quoteClosed = false;
  const pushRecord = () => {
    record.push(cell);
    records.push(record);
    record = [];
    cell = '';
    quoteClosed = false;
  };
  for (let index = 0; index < raw.length; index += 1) {
    const char = raw[index];
    if (quoted) {
      if (char === '"' && raw[index + 1] === '"') { cell += '"'; index += 1; }
      else if (char === '"') { quoted = false; quoteClosed = true; }
      else cell += char;
      continue;
    }
    if (quoteClosed) {
      if (char === delimiter) { record.push(cell); cell = ''; quoteClosed = false; continue; }
      if (char === '\n' || char === '\r') {
        if (char === '\r' && raw[index + 1] === '\n') index += 1;
        pushRecord();
        continue;
      }
      return { ok: false, reason: 'characters_after_closing_quote' };
    }
    if (char === '"') {
      if (cell.length > 0) return { ok: false, reason: 'quote_inside_unquoted_cell' };
      quoted = true;
    } else if (char === delimiter) {
      record.push(cell);
      cell = '';
    } else if (char === '\n' || char === '\r') {
      if (char === '\r' && raw[index + 1] === '\n') index += 1;
      pushRecord();
    } else cell += char;
  }
  if (quoted) return { ok: false, reason: 'unterminated_quote' };
  if (cell.length > 0 || record.length > 0 || quoteClosed) pushRecord();
  while (records.length > 0 && records[records.length - 1].every((value) => value === '')) records.pop();
  return { ok: true, records };
}

function normalizeColumns(values) {
  const columns = values.map((value, index) => {
    const normalized = String(value || '').replace(/^\uFEFF/, '').trim();
    return normalized || (index === 0 ? 'row_id' : '');
  });
  if (columns.length === 0 || columns.some((value) => !value)) return null;
  const folded = columns.map((value) => value.toLowerCase());
  return new Set(folded).size === folded.length ? columns : null;
}

function readExactTable(filePath) {
  const stat = fs.statSync(filePath);
  if (!stat.isFile()) return { ok: false, reason: 'semantic_output_not_file' };
  if (stat.size > MAX_SEMANTIC_BYTES) return { ok: false, reason: 'semantic_output_too_large' };
  const raw = fs.readFileSync(filePath, 'utf8');
  const parsed = parseDelimitedRecords(raw, detectDelimiter(raw));
  if (!parsed.ok) return parsed;
  if (parsed.records.length === 0) return { ok: false, reason: 'semantic_table_empty_file' };
  if (parsed.records.length - 1 > MAX_SEMANTIC_ROWS) return { ok: false, reason: 'semantic_table_row_limit' };
  const columns = normalizeColumns(parsed.records[0]);
  if (!columns) return { ok: false, reason: 'semantic_table_header_invalid' };
  const rows = [];
  for (const values of parsed.records.slice(1)) {
    if (values.length !== columns.length) return { ok: false, reason: 'semantic_table_row_shape_invalid' };
    rows.push(Object.fromEntries(columns.map((column, index) => [column, values[index]])));
  }
  return { ok: true, columns, rows };
}

function exactProjectFile(workspaceRoot, filePath) {
  if (!workspaceRoot || !filePath || !path.isAbsolute(filePath)) return null;
  try {
    const root = fs.realpathSync(workspaceRoot);
    const target = fs.realpathSync(filePath);
    return isPathContained(root, target) && fs.statSync(target).isFile() ? target : null;
  } catch { return null; }
}

function collectFormalArtifacts({ descriptor, result, workspaceRoot, diagnostics }) {
  const formal = [];
  const descriptors = Array.isArray(descriptor?.artifacts) ? descriptor.artifacts : [];
  const descriptorIds = new Set();
  for (const artifactDescriptor of descriptors) {
    const artifactId = trimmed(artifactDescriptor && artifactDescriptor.id);
    if (!artifactId || descriptorIds.has(artifactId)) {
      diagnostics.push(diagnostic('validator_artifact_descriptor_invalid', 'Plugin formal Artifact ids must be non-empty and unique.'));
      continue;
    }
    descriptorIds.add(artifactId);
    const artifacts = (Array.isArray(result.artifacts) ? result.artifacts : [])
      .filter((artifact) => artifact && artifact.id === artifactId);
    if (artifacts.length === 0) {
      if (artifactDescriptor.required !== false) {
        diagnostics.push(diagnostic(
          'validator_formal_artifact_missing',
          'A required descriptor formal Artifact is absent from the completed Job.',
          { artifactId }
        ));
      }
      continue;
    }
    const provenanceArtifacts = (Array.isArray(result.executionProvenance?.artifacts)
      ? result.executionProvenance.artifacts : [])
      .filter((artifact) => artifact && artifact.id === artifactId);
    if (artifacts.length !== 1 || provenanceArtifacts.length !== 1) {
      diagnostics.push(diagnostic(
        'validator_formal_artifact_ambiguous',
        'A produced formal Artifact must occur exactly once in result and provenance.',
        { artifactId }
      ));
      continue;
    }
    const filePath = exactProjectFile(workspaceRoot, artifacts[0].path);
    const recordedHash = trimmed(provenanceArtifacts[0].sha256);
    if (!filePath || !SHA256.test(recordedHash)) {
      diagnostics.push(diagnostic(
        'validator_formal_artifact_untrusted',
        'A produced formal Artifact lacks a contained file or provenance hash.',
        { artifactId }
      ));
      continue;
    }
    const expectedFilename = trimmed(artifactDescriptor.filename);
    if (expectedFilename && path.basename(filePath) !== expectedFilename) {
      diagnostics.push(diagnostic(
        'validator_formal_artifact_filename_mismatch',
        'A formal Artifact path does not match the descriptor filename.',
        { artifactId, expectedFilename, actualFilename: path.basename(filePath) }
      ));
      continue;
    }
    const sha256 = hashFile(filePath);
    if (sha256 !== recordedHash) {
      diagnostics.push(diagnostic(
        'validator_output_hash_mismatch',
        'A formal Artifact no longer matches execution provenance.',
        { artifactId }
      ));
      continue;
    }
    formal.push({
      artifactId,
      type: trimmed(artifactDescriptor.type) || trimmed(artifacts[0].type) || null,
      filename: trimmed(artifactDescriptor.filename) || path.basename(filePath),
      path: filePath,
      sha256,
    });
  }
  if (formal.length === 0) {
    diagnostics.push(diagnostic('validator_formal_artifacts_missing', 'The Job produced no formal Result Studio Artifact.'));
  }
  return formal;
}

function validateScriptHash({ result, expectedScriptSha256, diagnostics }) {
  const actual = trimmed(result.executionProvenance?.script?.sha256);
  if (!SHA256.test(trimmed(expectedScriptSha256)) || actual !== expectedScriptSha256) {
    diagnostics.push(diagnostic('validator_script_hash_mismatch', 'Executed script bytes do not match the materialized candidate source.'));
  }
}

function validateInputHashes({ descriptor, result, rawParams, workspaceRoot, diagnostics }) {
  const inputs = Array.isArray(result.executionProvenance?.inputs) ? result.executionProvenance.inputs : [];
  const byId = new Map();
  for (const input of inputs) {
    const inputId = trimmed(input && input.id);
    if (!inputId || byId.has(inputId) || !SHA256.test(trimmed(input && input.sha256))) {
      diagnostics.push(diagnostic('validator_input_provenance_invalid', 'Execution inputs require unique ids and SHA-256 hashes.', { inputId: inputId || null }));
      continue;
    }
    byId.set(inputId, input);
    const normalized = result.executionProvenance?.params?.normalized?.[inputId];
    if (!normalized || typeof normalized !== 'object' || normalized.sha256 !== input.sha256) {
      diagnostics.push(diagnostic('validator_normalized_input_hash_mismatch', 'Normalized parameters do not bind the exact input hash.', { inputId }));
    }
    const suppliedPath = rawParams && typeof rawParams[inputId] === 'string'
      ? rawParams[inputId]
      : null;
    const trustedInput = suppliedPath && path.isAbsolute(suppliedPath)
      ? {
        path: exactProjectFile(workspaceRoot, suppliedPath),
        source: 'explicit_parameter',
        reason: 'explicit_parameter_unavailable',
      }
      : resolveExecutionInputPath({
        workspaceRoot,
        input,
        sourceParams: rawParams || {},
        provenance: result.executionProvenance,
      });
    const filePath = trustedInput.path;
    if (!filePath || hashFile(filePath) !== input.sha256) {
      diagnostics.push(diagnostic('validator_input_hash_mismatch', 'A candidate input file changed or escaped the project.', {
        inputId,
        source: trustedInput.source || trustedInput.reason,
      }));
    }
  }
  for (const binding of Array.isArray(descriptor?.inputBindings) ? descriptor.inputBindings : []) {
    if (binding?.required === true && !byId.has(trimmed(binding.inputId))) {
      diagnostics.push(diagnostic('validator_required_input_missing', 'A required descriptor input is absent from execution provenance.', { inputId: trimmed(binding.inputId) || null }));
    }
  }
}

function artifactTable(artifactId, formalById, tableCache, diagnostics) {
  if (tableCache.has(artifactId)) return tableCache.get(artifactId);
  const artifact = formalById.get(artifactId);
  if (!artifact) return null;
  let table;
  try { table = readExactTable(artifact.path); }
  catch { table = { ok: false, reason: 'semantic_table_unreadable' }; }
  if (!table.ok) {
    diagnostics.push(diagnostic('validator_semantic_table_invalid', 'A semantic table cannot be parsed exactly.', { artifactId, reason: table.reason }));
    tableCache.set(artifactId, null);
    return null;
  }
  tableCache.set(artifactId, table);
  return table;
}

function validateStableIds({ descriptor, kind, allowEmpty, formalById, tableCache, diagnostics }) {
  const expectedEntity = kind === 'gene' ? 'gene' : 'pathway';
  const mappings = (Array.isArray(descriptor?.interactionMappings) ? descriptor.interactionMappings : [])
    .filter((mapping) => mapping?.mode === 'table' && mapping.entityType === expectedEntity);
  let checked = 0;
  for (const mapping of mappings) {
    if (!formalById.has(mapping.artifactId)) continue;
    const table = artifactTable(mapping.artifactId, formalById, tableCache, diagnostics);
    if (!table) continue;
    const idField = trimmed(mapping.idField || mapping.rowIdField);
    if (!idField || !table.columns.includes(idField)) {
      diagnostics.push(diagnostic('validator_stable_id_field_missing', 'The declared stable identifier column is absent.', { artifactId: mapping.artifactId, idField: idField || null }));
      continue;
    }
    if (table.rows.length === 0 && allowEmpty) { checked += 1; continue; }
    const ids = table.rows.map((row) => trimmed(row[idField]));
    if (ids.some((value) => !value) || new Set(ids).size !== ids.length) {
      diagnostics.push(diagnostic('validator_stable_id_invalid', 'Stable entity identifiers must be non-empty and unique.', { artifactId: mapping.artifactId, idField }));
      continue;
    }
    checked += 1;
  }
  if (checked === 0) diagnostics.push(diagnostic('validator_stable_id_artifact_missing', `No formal ${kind} table was available for stable-id validation.`));
}

function validateFiniteStatistics({ descriptor, formalById, tableCache, diagnostics }) {
  const fields = descriptor?.entity?.fields && typeof descriptor.entity.fields === 'object'
    ? descriptor.entity.fields : {};
  const numericFields = Object.entries(fields)
    .filter(([, type]) => String(type).startsWith('number'));
  let checked = 0;
  for (const artifact of formalById.values()) {
    if (artifact.type !== 'table') continue;
    const table = artifactTable(artifact.artifactId, formalById, tableCache, diagnostics);
    if (!table) continue;
    const present = numericFields.filter(([field]) => table.columns.includes(field));
    if (present.length === 0) continue;
    for (const row of table.rows) {
      for (const [field, type] of present) {
        const raw = String(row[field] ?? '').trim();
        // R serializes an NA scalar as the literal `NA` in CSV by default.
        // Treat it as null only when the descriptor explicitly admits null;
        // required numerics and other non-finite spellings remain fail-closed.
        if ((!raw || raw === 'NA') && String(type).includes('|null')) continue;
        if (!raw) {
          diagnostics.push(diagnostic('validator_statistic_missing', 'A required declared numeric statistic is missing.', { artifactId: artifact.artifactId, field }));
          continue;
        }
        const value = Number(raw);
        if (!Number.isFinite(value)) {
          diagnostics.push(diagnostic('validator_statistic_not_finite', 'A declared numeric statistic is missing or non-finite.', { artifactId: artifact.artifactId, field }));
          continue;
        }
        if (/(?:^|_)(?:pvalue|padj|p_adjust)$|^significance$/i.test(field) && (value < 0 || value > 1)) {
          diagnostics.push(diagnostic('validator_probability_out_of_range', 'A declared probability statistic is outside [0, 1].', { artifactId: artifact.artifactId, field }));
        }
      }
    }
    checked += 1;
  }
  if (checked === 0) diagnostics.push(diagnostic('validator_statistics_artifact_missing', 'No formal table exposed the descriptor-declared numeric statistics.'));
}

function validateSymmetricMatrices({ descriptor, formalById, tableCache, diagnostics }) {
  const mappings = Array.isArray(descriptor?.interactionMappings) ? descriptor.interactionMappings : [];
  const targets = new Map();
  for (const mapping of mappings.filter((entry) => entry?.mode === 'matrix')) {
    const artifactId = trimmed(mapping.dataArtifactId || mapping.artifactId);
    if (artifactId && formalById.get(artifactId)?.type === 'table') targets.set(artifactId, mapping);
  }
  let checked = 0;
  for (const [artifactId, mapping] of targets) {
    const table = artifactTable(artifactId, formalById, tableCache, diagnostics);
    if (!table) continue;
    const rowIdField = trimmed(mapping.rowIdField) || 'row_id';
    if (!table.columns.includes(rowIdField)) {
      diagnostics.push(diagnostic('validator_matrix_row_id_missing', 'The symmetric matrix row identifier is absent.', { artifactId, rowIdField }));
      continue;
    }
    const columns = table.columns.filter((column) => column !== rowIdField);
    const rowIds = table.rows.map((row) => trimmed(row[rowIdField]));
    if (columns.length === 0 || table.rows.length !== columns.length
        || rowIds.some((value) => !value) || new Set(rowIds).size !== rowIds.length
        || new Set(columns).size !== columns.length
        || columns.some((column) => !rowIds.includes(column))) {
      diagnostics.push(diagnostic('validator_matrix_shape_invalid', 'A symmetric matrix must be square with identical unique row and column ids.', { artifactId }));
      continue;
    }
    const rowsById = new Map(table.rows.map((row) => [trimmed(row[rowIdField]), row]));
    let valid = true;
    for (const rowId of rowIds) {
      for (const columnId of columns) {
        const left = Number(rowsById.get(rowId)[columnId]);
        const right = Number(rowsById.get(columnId)[rowId]);
        const scale = Math.max(1, Math.abs(left), Math.abs(right));
        if (!Number.isFinite(left) || !Number.isFinite(right) || Math.abs(left - right) > 1e-10 * scale) {
          valid = false;
          break;
        }
      }
      if (!valid) break;
    }
    if (!valid) {
      diagnostics.push(diagnostic('validator_matrix_not_symmetric', 'Matrix values are non-finite or not symmetric within exact numeric tolerance.', { artifactId }));
      continue;
    }
    checked += 1;
  }
  if (checked === 0) diagnostics.push(diagnostic('validator_symmetric_matrix_missing', 'No formal descriptor-declared symmetric matrix was validated.'));
}

function validateResultStudioCandidate({
  descriptor,
  job,
  workspaceRoot,
  expectedScriptSha256,
  rawParams = null,
} = {}) {
  const diagnostics = [];
  const validator = descriptor?.validator;
  const checks = Array.isArray(validator?.checks) ? [...new Set(validator.checks.map(trimmed).filter(Boolean))] : [];
  if (!trimmed(validator?.id) || checks.length === 0) {
    diagnostics.push(diagnostic('validator_descriptor_missing', 'The plugin does not declare an executable Result Studio validator.'));
  }
  for (const check of checks) {
    if (!SUPPORTED_CHECKS.has(check)) diagnostics.push(diagnostic('validator_check_unsupported', 'The plugin requested an unsupported validation check.', { check }));
  }
  const result = resultOf(job);
  if (!job || job.status !== 'completed') diagnostics.push(diagnostic('validator_job_incomplete', 'Only a completed candidate Job can be validated.'));
  if (checks.includes('artifact_truth_valid')
      && (result.artifactTruth?.status !== 'valid' || result.artifactTruth?.blocking === true)) {
    diagnostics.push(diagnostic('validator_artifact_truth_invalid', 'Candidate Artifact Truth is not valid.'));
  }
  const formalArtifacts = collectFormalArtifacts({ descriptor, result, workspaceRoot, diagnostics });
  if (checks.includes('script_sha256')) validateScriptHash({ result, expectedScriptSha256, diagnostics });
  if (checks.includes('input_sha256')) {
    validateInputHashes({ descriptor, result, rawParams: rawParams || job?.params || {}, workspaceRoot, diagnostics });
  }
  const formalById = new Map(formalArtifacts.map((artifact) => [artifact.artifactId, artifact]));
  const tableCache = new Map();
  const allowEmpty = checks.includes('empty_result_is_valid');
  if (checks.includes('stable_gene_id')) {
    validateStableIds({ descriptor, kind: 'gene', allowEmpty: false, formalById, tableCache, diagnostics });
  }
  if (checks.includes('stable_term_id')) {
    validateStableIds({ descriptor, kind: 'term', allowEmpty, formalById, tableCache, diagnostics });
  }
  if (checks.includes('finite_statistics')) {
    validateFiniteStatistics({ descriptor, formalById, tableCache, diagnostics });
  }
  if (checks.includes('symmetric_matrix')) {
    validateSymmetricMatrices({ descriptor, formalById, tableCache, diagnostics });
  }
  const ok = diagnostics.length === 0;
  return {
    resultPluginValidatorVersion: RESULT_PLUGIN_VALIDATOR_VERSION,
    ok,
    status: ok ? 'valid' : 'blocked',
    validatorId: trimmed(validator?.id) || null,
    checks,
    diagnostics,
    formalArtifacts,
    validationStatus: ok ? 'valid' : 'invalid',
    // A semantic validator proves the candidate, not an independent replay.
    // Repository code may upgrade this only after exact ReplayPackage proof.
    reproducibilityStatus: 'available',
    exactReplayVerified: false,
  };
}

module.exports = {
  RESULT_PLUGIN_VALIDATOR_VERSION,
  MAX_SEMANTIC_BYTES,
  MAX_SEMANTIC_ROWS,
  SUPPORTED_CHECKS,
  validateResultStudioCandidate,
};

'use strict';

const crypto = require('crypto');

const RESULT_REF_TRANSACTION_VERSION = 1;
const RESULT_REF_TRANSACTION_MIGRATION_VERSION = 3;

const RESULT_REF_TRANSACTION_SCHEMA_STATEMENTS = Object.freeze([
  `CREATE TABLE IF NOT EXISTS result_ref_transactions (
  operation_id TEXT PRIMARY KEY,
  contract_version INTEGER NOT NULL DEFAULT 1,
  project_id TEXT NOT NULL,
  change_set_id TEXT NOT NULL,
  operation_kind TEXT NOT NULL,
  state TEXT NOT NULL,
  source_status TEXT NOT NULL,
  target_status TEXT NOT NULL,
  ref_updates_json TEXT NOT NULL,
  target_revision_ids_json TEXT NOT NULL DEFAULT '[]',
  checkpoint_json TEXT NOT NULL,
  owner_lease_json TEXT NOT NULL,
  intent_hash TEXT NOT NULL,
  status_reason TEXT,
  failure_reason TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  completed_at TEXT
)`,
  'CREATE INDEX IF NOT EXISTS idx_rs_ref_transactions_project_state ON result_ref_transactions(project_id, state)',
  `CREATE UNIQUE INDEX IF NOT EXISTS uq_rs_ref_transactions_active_project
ON result_ref_transactions(project_id)
WHERE state IN ('prepared', 'refs_applied')`,
]);

const RESULT_REF_TRANSACTION_MIGRATION_HEADER = `-- G0-RS-P6 - durable Git ref and SQLite transition journal (migration 003)
--
-- This file is generated from core/shared-backend/result-ref-transaction-schema.js.
-- It records the exact compare-and-swap ref cohort and final SQLite checkpoint
-- so an owned-process crash can deterministically resume the transition.`;

function canonicalStringify(value) {
  if (value === null || typeof value !== 'object') return JSON.stringify(value);
  if (Array.isArray(value)) return `[${value.map(canonicalStringify).join(',')}]`;
  return `{${Object.keys(value).sort().map((key) => (
    `${JSON.stringify(key)}:${canonicalStringify(value[key])}`
  )).join(',')}}`;
}

function computeResultRefTransactionHash(intent = {}) {
  const immutableIntent = {
    contractVersion: intent.contractVersion,
    operationId: intent.operationId,
    projectId: intent.projectId,
    changeSetId: intent.changeSetId,
    operationKind: intent.operationKind,
    sourceStatus: intent.sourceStatus,
    targetStatus: intent.targetStatus,
    refUpdates: intent.refUpdates,
    targetRevisionIds: intent.targetRevisionIds,
    checkpoint: intent.checkpoint,
    ownerLease: intent.ownerLease,
    statusReason: intent.statusReason ?? null,
    createdAt: intent.createdAt,
  };
  return crypto.createHash('sha256').update(canonicalStringify(immutableIntent)).digest('hex');
}

function buildResultRefTransactionMigrationSql() {
  const body = RESULT_REF_TRANSACTION_SCHEMA_STATEMENTS
    .map((statement) => `${statement};`)
    .join('\n\n');
  return `${RESULT_REF_TRANSACTION_MIGRATION_HEADER}\n\n${body}\n`;
}

function ensureResultRefTransactionSchema(db) {
  if (!db || typeof db.exec !== 'function') throw new Error('result_ref_transaction_db_required');
  for (const statement of RESULT_REF_TRANSACTION_SCHEMA_STATEMENTS) db.exec(statement);
  return { version: RESULT_REF_TRANSACTION_VERSION, table: 'result_ref_transactions' };
}

module.exports = {
  RESULT_REF_TRANSACTION_VERSION,
  RESULT_REF_TRANSACTION_MIGRATION_VERSION,
  RESULT_REF_TRANSACTION_SCHEMA_STATEMENTS,
  buildResultRefTransactionMigrationSql,
  computeResultRefTransactionHash,
  ensureResultRefTransactionSchema,
};

'use strict';

const { computeResultRefTransactionHash } = require('./result-ref-transaction-schema');
const {
  getResultStudioRuntimeLease,
  isResultStudioRuntimeLease,
  isResultStudioRuntimeLeaseOwnerAlive,
} = require('./result-studio-runtime-lease');

const ZERO_OID = '0'.repeat(40);

class ResultRefTransactionError extends Error {
  constructor(code, message, detail = null) {
    super(message);
    this.name = 'ResultRefTransactionError';
    this.code = code;
    this.detail = detail;
  }
}

function currentRefOid(adapter, ref) {
  return adapter.readRefExact(ref) || ZERO_OID;
}

function classifyRefTransaction(intent, adapter) {
  const observations = intent.refUpdates.map((entry) => ({
    ref: entry.ref,
    actual: currentRefOid(adapter, entry.ref),
    expectedOld: entry.expectedOld,
    newOid: entry.newOid,
  }));
  const allOld = observations.every((entry) => entry.actual === entry.expectedOld);
  const allNew = observations.every((entry) => entry.actual === entry.newOid);
  return {
    status: allOld ? 'all_old' : allNew ? 'all_new' : 'conflict',
    observations,
  };
}

function reverseUpdates(updates) {
  return [...updates].reverse().map((entry) => ({
    ref: entry.ref,
    expectedOld: entry.newOid,
    newOid: entry.expectedOld,
  }));
}

function hasValidIntentHash(intent) {
  return /^[a-f0-9]{64}$/.test(String(intent?.intentHash || ''))
    && computeResultRefTransactionHash(intent) === intent.intentHash;
}

function assertIntentIntegrity(intent) {
  if (!hasValidIntentHash(intent)) {
    throw new ResultRefTransactionError(
      'ref_transaction_integrity_failed',
      'The durable ref transition journal failed its immutable intent hash.'
    );
  }
}

function recoveryOwnership(intent, runtimeLease, ownerAlive = isResultStudioRuntimeLeaseOwnerAlive) {
  if (!isResultStudioRuntimeLease(runtimeLease) || !isResultStudioRuntimeLease(intent.ownerLease)) {
    return 'unproven';
  }
  if (intent.ownerLease.instanceId === runtimeLease.instanceId) return 'current';
  return ownerAlive(intent.ownerLease) === false ? 'stale' : 'external';
}

function requireDependencies(repository, adapter) {
  if (!repository || typeof repository.prepareRefTransaction !== 'function'
      || typeof repository.finalizeRefTransaction !== 'function'
      || !adapter || typeof adapter.updateRefsCas !== 'function'
      || typeof adapter.readRefExact !== 'function') {
    throw new ResultRefTransactionError(
      'ref_transaction_dependencies_missing',
      'Durable ref transitions require the canonical Repository and atomic Git adapter.'
    );
  }
}

function executeDurableRefTransaction(input = {}, dependencies = {}) {
  const { repository, adapter } = dependencies;
  requireDependencies(repository, adapter);
  const intent = repository.prepareRefTransaction({
    ...input,
    ownerLease: input.ownerLease || getResultStudioRuntimeLease(),
  });
  let refsApplied = false;
  try {
    adapter.updateRefsCas({ updates: intent.refUpdates });
    refsApplied = true;
    if (typeof dependencies.afterRefsApplied === 'function') {
      dependencies.afterRefsApplied(intent);
    }
    const acknowledgement = classifyRefTransaction(intent, adapter);
    if (acknowledgement.status !== 'all_new') {
      throw new ResultRefTransactionError(
        'ref_transaction_git_postcondition_failed',
        'The atomic Git ref cohort did not remain at its exact target state.',
        { observations: acknowledgement.observations },
      );
    }
    repository.markRefTransactionRefsApplied(intent.operationId);
    const completed = repository.finalizeRefTransaction(intent.operationId);
    return { intent: completed, recovered: false };
  } catch (error) {
    const current = repository.getRefTransaction(intent.operationId);
    if (current && ['prepared', 'refs_applied'].includes(current.state)) {
      let classification = null;
      try {
        assertIntentIntegrity(current);
        classification = classifyRefTransaction(current, adapter);
      } catch {
        throw error;
      }
      if (!refsApplied && classification.status === 'all_new') {
        try {
          repository.markRefTransactionRefsApplied(intent.operationId);
          const completed = repository.finalizeRefTransaction(intent.operationId);
          return { intent: completed, recovered: true, acknowledgementRecovered: true };
        } catch {
          throw error;
        }
      }
      if (refsApplied && classification.status === 'all_new') {
        try { adapter.updateRefsCas({ updates: reverseUpdates(current.refUpdates) }); } catch {}
      }
      let afterRollback = null;
      try { afterRollback = classifyRefTransaction(current, adapter); } catch {}
      if (afterRollback?.status === 'all_old') {
        try { repository.abortRefTransaction(intent.operationId, error.code || 'ref_transition_failed'); } catch {}
      }
    }
    throw error;
  }
}

function recoverActiveRefTransactions({
  projectId,
  runtimeLease = getResultStudioRuntimeLease(),
} = {}, dependencies = {}) {
  const { repository, adapter } = dependencies;
  requireDependencies(repository, adapter);
  const repaired = [];
  const blocked = [];
  for (const intent of repository.listActiveRefTransactions(projectId)) {
    try {
      assertIntentIntegrity(intent);
      const ownership = recoveryOwnership(
        intent,
        runtimeLease,
        dependencies.isOwnerAlive || isResultStudioRuntimeLeaseOwnerAlive,
      );
      if (ownership === 'external' || ownership === 'unproven') {
        throw new ResultRefTransactionError(
          'ref_transaction_owner_active',
          'Another live runtime still owns the durable ref transition.'
        );
      }
      let classification = classifyRefTransaction(intent, adapter);
      if (classification.status === 'conflict') {
        throw new ResultRefTransactionError(
          'ref_transaction_git_conflict',
          'The durable ref transition encountered a third-value Git ref.'
        );
      }
      if (classification.status === 'all_old') {
        try { adapter.updateRefsCas({ updates: intent.refUpdates }); } catch {}
        classification = classifyRefTransaction(intent, adapter);
        if (classification.status !== 'all_new') {
          throw new ResultRefTransactionError(
            'ref_transaction_git_postcondition_failed',
            'The atomic Git ref cohort did not reach its exact target state.'
          );
        }
        repaired.push({ repair: 'ref_transaction_refs_resumed' });
      }
      classification = classifyRefTransaction(intent, adapter);
      if (classification.status !== 'all_new') {
        throw new ResultRefTransactionError(
          'ref_transaction_git_postcondition_failed',
          'The atomic Git ref cohort did not reach its exact target state.'
        );
      }
      repository.markRefTransactionRefsApplied(intent.operationId);
      repository.finalizeRefTransaction(intent.operationId);
      repaired.push({ repair: 'ref_transaction_sqlite_finalized' });
    } catch (error) {
      blocked.push({
        operationId: intent.operationId,
        changeSetId: intent.changeSetId,
        kind: error.code || 'ref_transaction_recovery_failed',
      });
    }
  }
  return { repaired, blocked };
}

module.exports = {
  ZERO_OID,
  ResultRefTransactionError,
  classifyRefTransaction,
  executeDurableRefTransaction,
  hasValidIntentHash,
  recoveryOwnership,
  recoverActiveRefTransactions,
  reverseUpdates,
};

