class ResultReplayError extends Error {
  constructor(code, message, status = 409, detail = null) {
    super(message);
    this.name = 'ResultReplayError';
    this.code = code;
    this.status = status;
    this.detail = detail;
  }
}

function fail(code, message, status = 409, detail = null) {
  throw new ResultReplayError(code, message, status, detail);
}

function object(value) {
  return value && typeof value === 'object' && !Array.isArray(value) ? value : null;
}

function cloneJson(value) {
  return JSON.parse(JSON.stringify(value));
}

function stableHash(value) {
  return sha256(stableStringify(value));
}

function assertAllowedReplayRequest(body) {
  if (!object(body)) fail('replay_request_invalid', 'Replay request must be an object.', 400);
  const rejected = Object.keys(body).filter((field) => !REQUEST_FIELDS.has(field)).sort();
  if (rejected.length > 0) {
    fail(
      'replay_request_field_not_allowed',
      'Replay execution does not accept caller-supplied plans, parameters, scripts or commands.',
      400,
      { rejectedFields: rejected }
    );
  }
  return body;
}

function safeIdentifier(value, field) {
  const normalized = String(value || '').trim();
  if (!SAFE_ID.test(normalized)) fail(`${field}_invalid`, `${field} is invalid.`, 400);
  return normalized;
}

function expectedInputMap(value) {
  if (value == null) return null;
  if (!object(value)) fail('expected_input_hashes_invalid', 'expectedInputHashes must be an object.', 400);
  const entries = Object.entries(value).sort(([left], [right]) => left.localeCompare(right));
  if (entries.some(([id, digest]) => !SAFE_ID.test(id) || !SHA256.test(String(digest || '')))) {
    fail('expected_input_hashes_invalid', 'expectedInputHashes must map safe input ids to sha256 digests.', 400);
  }
  return Object.fromEntries(entries);
}

function hashFile(filePath) {
  return sha256(fs.readFileSync(filePath));
}

function resolveIntactInput(workspaceRoot, input, sourceParams = {}, provenance = null) {
  const relativePath = String(input && input.relativePath || '').trim();
  const expectedHash = String(input && input.sha256 || '').trim();
  if (!relativePath || path.isAbsolute(relativePath) || !SHA256.test(expectedHash)) {
    fail('replay_input_ref_invalid', 'Replay input reference is incomplete.');
  }
  const resolved = resolveExecutionInputPath({
    workspaceRoot,
    input,
    sourceParams,
    provenance,
  });
  const target = resolved.path;
  if (!target) {
    fail('source_input_drift', 'A replay input is missing.', 409, { inputId: input.id || null });
  }
  if (hashFile(target) !== expectedHash) {
    fail('source_input_drift', 'A replay input hash changed.', 409, { inputId: input.id || null });
  }
  return target;
}

function projectSourceJobParams(sourceJob) {
  const params = object(sourceJob && sourceJob.params);
  if (params) return cloneJson(params);
  const raw = sourceJob && sourceJob.params_json;
  if (typeof raw !== 'string') fail('replay_source_params_missing', 'Source Job parameters are unavailable.');
  try {
    const parsed = JSON.parse(raw);
    if (!object(parsed)) throw new Error('not_object');
    return parsed;
  } catch {
    fail('replay_source_params_invalid', 'Source Job parameters are invalid.');
  }
}

/**
 * Rehydrate executable params without trusting an old absolute path.
 *
 * Provenance normalized every file input into {inputRef, sha256}. We derive a
 * fresh contained absolute path for execution, then normalize it back and
 * require byte-for-byte semantic equality with the parameters committed for
 * the selected Revision. This proves that no input or non-file parameter was
 * silently rebound.
 */
function buildReplayExecutionParams({ sourceJob, sourceProjection, workspaceRoot } = {}) {
  const rawValues = sourceProjection?.parameters?.rawValues;
  if (!object(rawValues)) fail('replay_parameters_missing', 'Exact persisted Revision parameters are required.');
  const runtimeParams = projectSourceJobParams(sourceJob);
  const normalized = cloneJson(runtimeParams);
  const sourceProvenance = parseJobResult(sourceJob).executionProvenance || null;
  const provenanceInputs = Array.isArray(sourceProvenance?.inputs)
    ? sourceProvenance.inputs
    : [];
  const seenIds = new Set();
  for (const input of provenanceInputs) {
    const inputId = safeIdentifier(input && input.id, 'replay_input_id');
    if (seenIds.has(inputId)) fail('replay_input_identity_ambiguous', 'Replay input identity is duplicated.');
    seenIds.add(inputId);
    const target = resolveIntactInput(workspaceRoot, input, runtimeParams, sourceProvenance);
    runtimeParams[inputId] = target;
    normalized[inputId] = { inputRef: input.relativePath, sha256: input.sha256 };
  }
  if (stableStringify(normalized) !== stableStringify(rawValues)) {
    fail('replay_parameters_drift', 'Source Job parameters no longer match the selected Revision.');
  }
  return runtimeParams;
}

function assertExpectedHashes({ sourceProjection, sourceJob, expectedSourceSha256, expectedParametersHash, expectedInputHashes }) {
  if (expectedSourceSha256 != null) {
    if (!SHA256.test(String(expectedSourceSha256)) || expectedSourceSha256 !== sourceProjection.sha256) {
      fail('replay_source_expectation_stale', 'Expected source hash does not match the selected Revision.');
    }
  }
  const actualParametersHash = sourceProjection.parameters?.sha256 || null;
  if (expectedParametersHash != null) {
    if (!SHA256.test(String(expectedParametersHash)) || expectedParametersHash !== actualParametersHash) {
      fail('replay_parameters_expectation_stale', 'Expected parameters hash does not match the selected Revision.');
    }
  }
  const expected = expectedInputMap(expectedInputHashes);
  if (expected) {
    const sourceResult = parseJobResult(sourceJob);
    const actual = Object.fromEntries(
      (sourceResult.executionProvenance?.inputs || [])
        .filter((input) => input?.id)
        .map((input) => [input.id, input.sha256])
        .sort(([left], [right]) => String(left).localeCompare(String(right)))
    );
    if (stableStringify(expected) !== stableStringify(actual)) {
      fail('replay_inputs_expectation_stale', 'Expected input hashes do not match the selected Revision.');
    }
  }
}

function assertRevisionOutput({ revision, workspaceRoot }) {
  if (!revision?.outputPath || !SHA256.test(String(revision.outputHash || ''))) {
    fail('replay_artifact_ref_invalid', 'Revision Artifact reference is incomplete.');
  }
  let root;
  let target;
  try {
    root = fs.realpathSync(workspaceRoot);
    target = fs.realpathSync(path.join(root, revision.outputPath));
  } catch {
    fail('replay_artifact_missing', 'Revision Artifact is missing.');
  }
  if (!isPathContained(root, target) || !fs.statSync(target).isFile()) {
    fail('replay_artifact_outside_project', 'Revision Artifact escaped the project.');
  }
  if (hashFile(target) !== revision.outputHash) {
    fail('replay_artifact_hash_drift', 'Revision Artifact hash changed.');
  }
}

function parseJobResult(job) {
  if (job?.result && typeof job.result === 'object') return job.result;
  try { return JSON.parse(job?.result_json || '{}'); } catch { return {}; }
}

/**
 * Exact replay means the complete formal output cohort is byte-identical, not
 * merely that the selected preview Artifact exists. The package is the source
 * expectation and the replay Job's Artifact Truth plus physical hashes are the
 * independent observation.
 */
function verifyReplayOutputCohort({ replay, job, workspaceRoot } = {}) {
  const result = parseJobResult(job);
  const provenance = result.executionProvenance;
  if (!job || job.status !== 'completed' || result.artifactTruth?.status !== 'valid'
      || result.artifactTruth?.blocking === true || !provenance) {
    fail('replay_output_truth_invalid', 'Replay Job did not produce valid Artifact Truth.');
  }
  if (replay?.script?.sha256 !== provenance.script?.sha256) {
    fail('replay_output_script_drift', 'Replay Job did not execute the packaged script hash.');
  }
  if (replay?.plugin?.id !== provenance.plugin?.id
      || String(replay?.plugin?.version || '') !== String(provenance.plugin?.version || '')) {
    fail('replay_output_plugin_drift', 'Replay Job plugin identity differs from the ReplayPackage.');
  }
  const expected = (Array.isArray(replay?.artifacts) ? replay.artifacts : []).map((artifact) => ({
    artifactId: String(artifact?.sourceArtifactId || artifact?.artifactId || '').trim(),
    sha256: String(artifact?.expected?.sha256 || '').trim(),
  }));
  if (expected.length === 0 || expected.some((artifact) => !artifact.artifactId || !SHA256.test(artifact.sha256))) {
    fail('replay_output_expectation_invalid', 'ReplayPackage output expectations are incomplete.');
  }
  const expectedIds = new Set(expected.map((artifact) => artifact.artifactId));
  if (expectedIds.size !== expected.length) {
    fail('replay_output_expectation_ambiguous', 'ReplayPackage output identities are duplicated.');
  }
  const producedArtifacts = Array.isArray(result.artifacts) ? result.artifacts : [];
  const formalArtifacts = producedArtifacts.filter((artifact) => expectedIds.has(String(artifact?.id || '').trim()));
  const formalIds = formalArtifacts.map((artifact) => String(artifact?.id || '').trim()).filter(Boolean);
  if (formalIds.length !== expected.length || new Set(formalIds).size !== formalIds.length
      || formalIds.some((artifactId) => !expectedIds.has(artifactId))) {
    fail('replay_output_cohort_mismatch', 'Replay Job formal output cohort differs from the ReplayPackage.', 409, {
      expectedArtifactIds: [...expectedIds].sort(),
      actualArtifactIds: formalIds.sort(),
    });
  }
  let realWorkspace;
  try { realWorkspace = fs.realpathSync(workspaceRoot); } catch {
    fail('replay_workspace_missing', 'Replay workspace is unavailable.');
  }
  const verified = expected.map((expectation) => {
    const artifacts = formalArtifacts.filter((artifact) => artifact?.id === expectation.artifactId);
    const provenanceArtifacts = (Array.isArray(provenance.artifacts) ? provenance.artifacts : [])
      .filter((artifact) => artifact?.id === expectation.artifactId);
    if (artifacts.length !== 1 || provenanceArtifacts.length !== 1) {
      fail('replay_output_identity_ambiguous', 'Replay output is not uniquely represented in Artifact and provenance truth.', 409, {
        artifactId: expectation.artifactId,
      });
    }
    let outputPath;
    try { outputPath = fs.realpathSync(artifacts[0].path); } catch {
      fail('replay_output_missing', 'Replay output file is unavailable.', 409, { artifactId: expectation.artifactId });
    }
    if (!isPathContained(realWorkspace, outputPath) || !fs.statSync(outputPath).isFile()) {
      fail('replay_output_outside_project', 'Replay output escaped the project.', 409, { artifactId: expectation.artifactId });
    }
    const actualHash = hashFile(outputPath);
    if (actualHash !== expectation.sha256 || provenanceArtifacts[0].sha256 !== expectation.sha256) {
      fail('replay_output_hash_mismatch', 'Replay output is not byte-identical to the packaged adopted output.', 409, {
        artifactId: expectation.artifactId,
        expectedHash: expectation.sha256,
        actualHash,
      });
    }
    return { artifactId: expectation.artifactId, sha256: actualHash, exactMatch: true };
  }).sort((left, right) => left.artifactId.localeCompare(right.artifactId));
  return {
    exactMatch: true,
    artifactCount: verified.length,
    outputCohortHash: stableHash(verified),
    outputs: verified,
  };
}

function buildRevisionReplayProofs({ sourceRevisions, replayRevisions } = {}) {
  if (!Array.isArray(sourceRevisions) || sourceRevisions.length === 0 || !Array.isArray(replayRevisions)) {
    fail('replay_revision_cohort_missing', 'Replay Revision cohorts are unavailable.');
  }
  return sourceRevisions.map((source) => {
    const matches = replayRevisions.filter((replay) => replay.artifactFamilyId === source.artifactFamilyId
      && replay.artifactId === source.artifactId
      && replay.parentRevisionIds.includes(source.revisionId));
    if (matches.length !== 1) {
      fail('replay_revision_cohort_mismatch', 'Replay Revision cohort does not map one-to-one to the adopted source cohort.', 409, {
        sourceRevisionId: source.revisionId,
        replayRevisionIds: matches.map((revision) => revision.revisionId),
      });
    }
    const replay = matches[0];
    return {
      sourceRevisionId: source.revisionId,
      replayRevisionId: replay.revisionId,
      replayToolJobId: replay.toolJobId,
      sourceOutputHash: source.outputHash,
      replayOutputHash: replay.outputHash,
    };
  });
}

function projectReplayExecutionCohort({ sourceRevisions, selectedRevision, workflowGraph, getToolJob } = {}) {
  if (!Array.isArray(sourceRevisions) || sourceRevisions.length === 0 || !selectedRevision
      || typeof getToolJob !== 'function') {
    fail('replay_source_cohort_missing', 'Replay source cohort is unavailable.');
  }
  const byJob = new Map();
  for (const revision of sourceRevisions) {
    if (!revision?.toolJobId || revision.projectId !== selectedRevision.projectId) {
      fail('replay_source_cohort_invalid', 'Replay source cohort contains an invalid Revision.');
    }
    if (!byJob.has(revision.toolJobId)) byJob.set(revision.toolJobId, []);
    byJob.get(revision.toolJobId).push(revision);
  }
  if (!sourceRevisions.some((revision) => revision.revisionId === selectedRevision.revisionId)) {
    fail('replay_source_cohort_invalid', 'Selected Revision is absent from its adopted replay cohort.');
  }
  const groupFor = (toolJobId) => {
    const revisions = (byJob.get(toolJobId) || [])
      .slice()
      .sort((left, right) => left.artifactId.localeCompare(right.artifactId));
    const job = getToolJob(toolJobId);
    if (revisions.length === 0 || !job || job.status !== 'completed'
        || String(job.project_id || job.projectId || '') !== selectedRevision.projectId) {
      fail('replay_source_job_cohort_invalid', 'A ReplayPackage source Job is missing or invalid.', 409, { toolJobId });
    }
    return {
      sourceToolJobId: toolJobId,
      toolId: String(job.tool_id || job.toolId || '').trim(),
      job,
      revisions,
      formalArtifactIds: revisions.map((revision) => revision.artifactId),
    };
  };
  if (!workflowGraph || workflowGraph.validationStatus !== 'valid'
      || workflowGraph.projectId !== selectedRevision.projectId
      || !Array.isArray(workflowGraph.nodes) || !Array.isArray(workflowGraph.edges)) {
    fail('replay_workflow_graph_missing', 'Scientific replay requires its persisted authoritative workflow graph.');
  }
  const integrity = verifyWorkflowGraphIntegrity(workflowGraph);
  if (!integrity.ok) {
    fail('replay_workflow_graph_stale', 'Persisted authoritative workflow graph failed integrity validation.', 409, {
      diagnostics: integrity.diagnostics,
    });
  }
  if (workflowGraph.nodes.length !== byJob.size
      || workflowGraph.nodes.some((node) => !byJob.has(node.toolJobId))) {
    fail('replay_workflow_graph_stale', 'Persisted workflow graph no longer matches the adopted Job cohort.');
  }
  const groups = workflowGraph.nodes.map((node) => {
    const group = groupFor(node.toolJobId);
    const provenance = parseJobResult(group.job).executionProvenance || null;
    const provenanceIntegrity = verifyExecutionProvenance(provenance);
    const artifactIds = [...new Set((Array.isArray(provenance?.artifacts) ? provenance.artifacts : [])
      .map((artifact) => String(artifact?.id || '').trim())
      .filter(Boolean))].sort();
    if (!provenanceIntegrity.ok
        || provenance.provenanceHash !== node.provenanceHash
        || group.toolId !== node.toolId
        || stableStringify(artifactIds) !== stableStringify(node.artifactIds)
        || group.formalArtifactIds.some((artifactId) => !artifactIds.includes(artifactId))) {
      fail('replay_workflow_graph_stale', 'Persisted workflow graph no longer matches current Job and Artifact provenance.', 409, {
        toolJobId: node.toolJobId,
      });
    }
    return group;
  });
  const rootToolJobId = String(workflowGraph.rootToolJobId || '').trim();
  const rootNodeId = `job:${rootToolJobId}`;
  if (!byJob.has(rootToolJobId)) {
    fail('replay_workflow_graph_stale', 'Persisted workflow root is absent from the adopted Job cohort.');
  }
  if (byJob.size === 1) {
    if (workflowGraph.nodes.length !== 1 || workflowGraph.edges.length !== 0
        || selectedRevision.toolJobId !== rootToolJobId) {
      fail('replay_workflow_graph_stale', 'Single-Job replay graph no longer identifies the selected source Job.');
    }
    return {
      rootRevision: selectedRevision,
      groups,
      authoritativeSubgraph: null,
      affectedNodeIds: [rootNodeId],
    };
  }
  if (workflowGraph.nodes.length !== 2 || workflowGraph.edges.length !== 1 || byJob.size !== 2) {
    fail('replay_workflow_graph_unsupported', 'Only one verified direct affected-subgraph edge can currently be replayed exactly.');
  }
  const edge = workflowGraph.edges[0];
  const childToolJobId = String(edge?.toNodeId || '').replace(/^job:/, '');
  const childNode = workflowGraph.nodes.find((node) => node.id === edge?.toNodeId);
  const rootRevisionMatches = sourceRevisions.filter((revision) => revision.revisionId === edge?.sourceRevisionId
    && revision.toolJobId === rootToolJobId && revision.artifactId === edge?.sourceArtifactId);
  const childRevisionMatches = sourceRevisions.filter((revision) => revision.toolJobId === childToolJobId
    && revision.artifactId === 'go_bp_results');
  if (edge?.fromNodeId !== rootNodeId || edge.kind !== 'artifact' || edge.inputId !== 'deg_table'
      || edge.sourceToolJobId !== rootToolJobId || !childNode || childNode.toolId !== 'go-kegg'
      || rootRevisionMatches.length !== 1 || childRevisionMatches.length !== 1
      || !byJob.has(rootToolJobId) || !byJob.has(childToolJobId)) {
    fail('replay_workflow_graph_unsupported', 'Persisted workflow graph is not the exact supported DEG to GO/KEGG subgraph.');
  }
  const rootRevision = rootRevisionMatches[0];
  const childRevision = childRevisionMatches[0];
  if (groups[0].sourceToolJobId !== rootToolJobId || groups[1].sourceToolJobId !== childToolJobId) {
    fail('replay_workflow_graph_stale', 'Persisted workflow node order no longer follows the authoritative root.');
  }
  if (!groups[0].toolId || groups[0].toolId !== 'deseq2' || groups[1].toolId !== 'go-kegg') {
    fail('replay_workflow_tool_drift', 'Persisted workflow Jobs no longer match the supported affected subgraph.');
  }
  return {
    rootRevision,
    groups,
    affectedNodeIds: [rootNodeId, edge.toNodeId],
    authoritativeSubgraph: {
      authority: 'sqlite_job_artifact_truth',
      graphId: workflowGraph.graphId,
      sourceDigest: workflowGraph.sourceDigest,
      rootNodeId,
      rootToolJobId,
      rootRevisionId: rootRevision.revisionId,
      children: [{
        nodeId: edge.toNodeId,
        toolId: childNode.toolId,
        inputId: edge.inputId,
        edgeKind: edge.kind,
        sourceToolJobId: rootToolJobId,
        sourceRevisionId: rootRevision.revisionId,
        sourceArtifactId: rootRevision.artifactId,
        sourceOutputHash: rootRevision.outputHash,
        childToolJobId,
        childRevisionId: childRevision.revisionId,
      }],
    },
  };
}

function replayCohortFingerprint({ sourceChangeSet, sourceRevisions, workflowGraph, execution } = {}) {
  return stableHash({
    sourceChangeSetId: sourceChangeSet?.changeSetId || null,
    candidateCommit: sourceChangeSet?.candidateCommit || null,
    revisions: (sourceRevisions || []).map((revision) => ({
      revisionId: revision.revisionId,
      sourceCommit: revision.sourceCommit,
      toolJobId: revision.toolJobId,
      artifactFamilyId: revision.artifactFamilyId,
      artifactId: revision.artifactId,
      outputHash: revision.outputHash,
    })).sort((left, right) => left.revisionId.localeCompare(right.revisionId)),
    workflowGraph: workflowGraph ? {
      graphId: workflowGraph.graphId,
      sourceDigest: workflowGraph.sourceDigest,
      rootToolJobId: workflowGraph.rootToolJobId,
    } : null,
    executionRootRevisionId: execution?.rootRevision?.revisionId || null,
    executionJobIds: (execution?.groups || []).map((group) => group.sourceToolJobId),
  });
}

function hasExactFields(value, fields) {
  if (!object(value)) return false;
  const actual = Object.keys(value).sort();
  const expected = [...fields].sort();
  return actual.length === expected.length && actual.every((field, index) => field === expected[index]);
}

function isSafeIdentifier(value) {
  return typeof value === 'string' && SAFE_ID.test(value);
}

function isSafeCohortRelativePath(value) {
  if (typeof value !== 'string' || !value || value.includes('\0') || value.includes('\\')) return false;
  if (path.posix.isAbsolute(value) || path.win32.isAbsolute(value)) return false;
  const segments = value.split('/');
  return !segments.some((segment) => !segment || segment === '.' || segment === '..')
    && path.posix.normalize(value) === value;
}

function isStrictlyContainedPath(root, target) {
  const relative = path.relative(root, target);
  return Boolean(relative) && relative !== '..' && !relative.startsWith(`..${path.sep}`) && !path.isAbsolute(relative);
}

function isSafeWorkflowNodeId(value) {
  return typeof value === 'string' && value.startsWith('job:') && isSafeIdentifier(value.slice(4));
}

function validUniqueIdentifiers(value, { allowEmpty = false, requireSorted = false } = {}) {
  if (!Array.isArray(value) || (!allowEmpty && value.length === 0)) return false;
  if (value.some((item) => !isSafeIdentifier(item))) return false;
  if (new Set(value).size !== value.length) return false;
  return !requireSorted || value.every((item, index) => index === 0 || value[index - 1].localeCompare(item) < 0);
}

function readRegularJsonInside(root, relativePath) {
  if (!isSafeCohortRelativePath(relativePath)) return null;
  const target = path.resolve(root, relativePath);
  if (!isStrictlyContainedPath(root, target)) return null;
  try {
    const stat = fs.lstatSync(target);
    if (stat.isSymbolicLink() || !stat.isFile()) return null;
    const realTarget = fs.realpathSync(target);
    if (!isStrictlyContainedPath(root, realTarget)) return null;
    const parsed = JSON.parse(fs.readFileSync(realTarget, 'utf8'));
    return object(parsed) ? parsed : null;
  } catch {
    return null;
  }
}

function resolveCohortChildDirectory(root, relativePath) {
  if (!isSafeCohortRelativePath(relativePath)) return null;
  const target = path.resolve(root, relativePath);
  if (!isStrictlyContainedPath(root, target)) return null;
  try {
    const stat = fs.lstatSync(target);
    if (stat.isSymbolicLink() || !stat.isDirectory()) return null;
    const realTarget = fs.realpathSync(target);
    return isStrictlyContainedPath(root, realTarget) ? realTarget : null;
  } catch {
    return null;
  }
}

function validateCohortPackageRoot({ root, sourceToolJobIds, diagnostics }) {
  let rootEntries;
  try {
    rootEntries = fs.readdirSync(root, { withFileTypes: true });
  } catch {
    diagnostics.push({ code: 'replay_cohort_inventory_unreadable' });
    return;
  }
  const names = new Set(rootEntries.map((entry) => entry.name));
  for (const entry of rootEntries) {
    if (entry.name !== 'cohort-manifest.json' && entry.name !== 'jobs') {
      diagnostics.push({ code: 'replay_cohort_root_entry_unexpected', path: entry.name });
    }
    if (entry.isSymbolicLink()) diagnostics.push({ code: 'replay_cohort_root_symlink', path: entry.name });
  }
  if (!names.has('jobs')) {
    diagnostics.push({ code: 'replay_cohort_jobs_directory_missing' });
    return;
  }
  const jobsDirectory = path.join(root, 'jobs');
  try {
    const stat = fs.lstatSync(jobsDirectory);
    if (stat.isSymbolicLink() || !stat.isDirectory()) throw new Error('jobs_not_directory');
    if (fs.realpathSync(jobsDirectory) !== jobsDirectory) throw new Error('jobs_symlinked_parent');
  } catch {
    diagnostics.push({ code: 'replay_cohort_jobs_directory_invalid' });
    return;
  }
  let entries;
  try {
    entries = fs.readdirSync(jobsDirectory, { withFileTypes: true });
  } catch {
    diagnostics.push({ code: 'replay_cohort_jobs_inventory_unreadable' });
    return;
  }
  const expected = new Set(sourceToolJobIds);
  for (const entry of entries) {
    if (!expected.has(entry.name)) {
      diagnostics.push({ code: 'replay_cohort_job_directory_unexpected', sourceToolJobId: entry.name });
      continue;
    }
    if (entry.isSymbolicLink() || !entry.isDirectory()) {
      diagnostics.push({ code: 'replay_cohort_job_directory_invalid', sourceToolJobId: entry.name });
    }
  }
  for (const sourceToolJobId of expected) {
    if (!entries.some((entry) => entry.name === sourceToolJobId)) {
      diagnostics.push({ code: 'replay_cohort_job_directory_missing', sourceToolJobId });
    }
  }
}

function validateCohortWorkflowGraph({ workflowGraph, jobsById, revisionsById, diagnostics }) {
  if (!hasExactFields(workflowGraph, COHORT_WORKFLOW_FIELDS)) {
    diagnostics.push({ code: 'replay_cohort_workflow_schema_invalid' });
    return;
  }
  if (workflowGraph.contractVersion !== 1 || workflowGraph.validationStatus !== 'valid'
      || !isSafeIdentifier(workflowGraph.projectId) || !isSafeIdentifier(workflowGraph.rootToolJobId)
      || !SHA256.test(workflowGraph.sourceDigest) || !isSafeIdentifier(workflowGraph.graphId)) {
    diagnostics.push({ code: 'replay_cohort_workflow_identity_invalid' });
  }
  if (workflowGraph.graphId !== `wfg_${String(workflowGraph.sourceDigest || '').slice(0, 24)}`) {
    diagnostics.push({ code: 'replay_cohort_workflow_graph_id_mismatch' });
  }
  if (!jobsById.has(workflowGraph.rootToolJobId)) {
    diagnostics.push({ code: 'replay_cohort_workflow_root_job_missing', sourceToolJobId: workflowGraph.rootToolJobId || null });
  }
  if (!Array.isArray(workflowGraph.nodes) || workflowGraph.nodes.length === 0) {
    diagnostics.push({ code: 'replay_cohort_workflow_nodes_invalid' });
    return;
  }
  if (!Array.isArray(workflowGraph.edges) || workflowGraph.edges.length === 0) {
    diagnostics.push({ code: 'replay_cohort_workflow_edges_invalid' });
    return;
  }

  const nodesById = new Map();
  for (const node of workflowGraph.nodes) {
    if (!hasExactFields(node, COHORT_WORKFLOW_NODE_FIELDS)) {
      diagnostics.push({ code: 'replay_cohort_workflow_node_schema_invalid' });
      continue;
    }
    const expectedNodeId = isSafeIdentifier(node.toolJobId) ? `job:${node.toolJobId}` : null;
    const job = jobsById.get(node.toolJobId) || null;
    if (!isSafeWorkflowNodeId(node.id) || !expectedNodeId || node.id !== expectedNodeId
        || !job || node.toolId !== job.toolId || !SHA256.test(node.provenanceHash)
        || !validUniqueIdentifiers(node.artifactIds, { requireSorted: true })
        || !Array.isArray(node.dependsOn) || node.dependsOn.some((dependency) => !isSafeWorkflowNodeId(dependency))
        || new Set(node.dependsOn).size !== node.dependsOn.length
        || !node.dependsOn.every((dependency, index) => index === 0 || node.dependsOn[index - 1].localeCompare(dependency) < 0)) {
      diagnostics.push({ code: 'replay_cohort_workflow_node_invalid', nodeId: node.id || null });
      continue;
    }
    if (nodesById.has(node.id)) {
      diagnostics.push({ code: 'replay_cohort_workflow_node_duplicate', nodeId: node.id });
      continue;
    }
    nodesById.set(node.id, node);
  }
  for (const sourceToolJobId of jobsById.keys()) {
    if (!nodesById.has(`job:${sourceToolJobId}`)) {
      diagnostics.push({ code: 'replay_cohort_workflow_job_node_missing', sourceToolJobId });
    }
  }
  if (nodesById.size !== jobsById.size) {
    diagnostics.push({ code: 'replay_cohort_workflow_node_cohort_mismatch' });
  }

  const children = new Map([...nodesById.keys()].map((nodeId) => [nodeId, new Set()]));
  const incoming = new Map([...nodesById.keys()].map((nodeId) => [nodeId, new Set()]));
  const edgeKeys = new Set();
  for (const edge of workflowGraph.edges) {
    if (!hasExactFields(edge, COHORT_WORKFLOW_EDGE_FIELDS)) {
      diagnostics.push({ code: 'replay_cohort_workflow_edge_schema_invalid' });
      continue;
    }
    const source = revisionsById.get(edge.sourceRevisionId) || null;
    const sourceNode = nodesById.get(edge.fromNodeId) || null;
    const targetNode = nodesById.get(edge.toNodeId) || null;
    const selectionValid = edge.kind === 'artifact'
      ? edge.selectionId === null && edge.selectionHash === null
      : edge.kind === 'selection' && isSafeIdentifier(edge.selectionId) && SHA256.test(edge.selectionHash);
    if (!selectionValid || !isSafeWorkflowNodeId(edge.fromNodeId) || !isSafeWorkflowNodeId(edge.toNodeId)
        || edge.fromNodeId === edge.toNodeId || !isSafeIdentifier(edge.sourceToolJobId)
        || !isSafeIdentifier(edge.sourceRevisionId) || !isSafeIdentifier(edge.sourceArtifactId)
        || !SHA256.test(edge.sourceOutputHash)
        || (edge.inputId !== null && !isSafeIdentifier(edge.inputId))
        || !sourceNode || !targetNode || !source
        || edge.sourceToolJobId !== sourceNode.toolJobId
        || source.toolJobId !== edge.sourceToolJobId
        || source.artifactId !== edge.sourceArtifactId
        || source.outputHash !== edge.sourceOutputHash) {
      diagnostics.push({ code: 'replay_cohort_workflow_edge_invalid', sourceRevisionId: edge.sourceRevisionId || null });
      continue;
    }
    const edgeKey = stableStringify(edge);
    if (edgeKeys.has(edgeKey)) {
      diagnostics.push({ code: 'replay_cohort_workflow_edge_duplicate', sourceRevisionId: edge.sourceRevisionId });
      continue;
    }
    edgeKeys.add(edgeKey);
    children.get(edge.fromNodeId).add(edge.toNodeId);
    incoming.get(edge.toNodeId).add(edge.fromNodeId);
  }

  const rootNodeId = `job:${workflowGraph.rootToolJobId}`;
  if (incoming.get(rootNodeId)?.size > 0) {
    diagnostics.push({ code: 'replay_cohort_workflow_root_has_parent', sourceToolJobId: workflowGraph.rootToolJobId });
  }
  for (const [nodeId, node] of nodesById.entries()) {
    const expectedDependencies = [...(incoming.get(nodeId) || [])].sort();
    if (stableStringify(node.dependsOn) !== stableStringify(expectedDependencies)) {
      diagnostics.push({ code: 'replay_cohort_workflow_dependencies_mismatch', nodeId });
    }
  }
  const visited = new Set();
  const visiting = new Set();
  let cyclic = false;
  const visit = (nodeId) => {
    if (visiting.has(nodeId)) { cyclic = true; return; }
    if (visited.has(nodeId)) return;
    visiting.add(nodeId);
    for (const child of children.get(nodeId) || []) visit(child);
    visiting.delete(nodeId);
    visited.add(nodeId);
  };
  if (nodesById.has(rootNodeId)) visit(rootNodeId);
  if (cyclic) diagnostics.push({ code: 'replay_cohort_workflow_cycle_detected' });
  if (visited.size !== nodesById.size) diagnostics.push({ code: 'replay_cohort_workflow_disconnected' });

  const expectedDigest = workflowGraphDigest(workflowGraph);
  if (workflowGraph.sourceDigest !== expectedDigest) {
    diagnostics.push({ code: 'replay_cohort_workflow_digest_mismatch' });
  }
}

function validateCohortChildPackage({ root, entry, revisions, projectId, diagnostics }) {
  const sourceToolJobId = entry?.sourceToolJobId || null;
  const expectedPath = isSafeIdentifier(sourceToolJobId) ? `jobs/${sourceToolJobId}` : null;
  if (!expectedPath || entry.relativePath !== expectedPath) {
    diagnostics.push({ code: 'replay_cohort_job_path_noncanonical', sourceToolJobId });
    return;
  }
  const child = resolveCohortChildDirectory(root, entry.relativePath);
  if (!child) {
    diagnostics.push({ code: 'replay_cohort_job_path_invalid', sourceToolJobId });
    return;
  }
  const validation = validateScientificReplayPackage(child);
  if (!validation.ok || validation.manifest?.packageDigest !== entry.packageDigest
      || validation.manifest?.status !== entry.status) {
    diagnostics.push({ code: 'replay_cohort_job_package_invalid', sourceToolJobId });
    return;
  }
  const jobManifest = readRegularJsonInside(child, 'job-manifest.json');
  const replay = readRegularJsonInside(child, 'replay.json');
  if (!jobManifest || jobManifest.id !== sourceToolJobId || jobManifest.toolId !== entry.toolId
      || jobManifest.projectId !== projectId || !replay || !object(replay.plugin)
      || replay.plugin.id !== entry.toolId || !Array.isArray(replay.artifacts)) {
    diagnostics.push({ code: 'replay_cohort_job_binding_invalid', sourceToolJobId });
    return;
  }
  const artifactsById = new Map();
  for (const artifact of replay.artifacts) {
    const artifactId = artifact?.sourceArtifactId || artifact?.artifactId;
    const outputHash = artifact?.expected?.sha256;
    if (!isSafeIdentifier(artifactId) || !SHA256.test(outputHash) || artifactsById.has(artifactId)) {
      diagnostics.push({ code: 'replay_cohort_job_artifact_binding_invalid', sourceToolJobId, artifactId: artifactId || null });
      continue;
    }
    artifactsById.set(artifactId, outputHash);
  }
  if (artifactsById.size !== entry.formalArtifactIds.length
      || entry.formalArtifactIds.some((artifactId) => !artifactsById.has(artifactId))) {
    diagnostics.push({ code: 'replay_cohort_job_artifact_cohort_mismatch', sourceToolJobId });
  }
  for (const revision of revisions) {
    if (artifactsById.get(revision.artifactId) !== revision.outputHash) {
      diagnostics.push({
        code: 'replay_cohort_job_artifact_hash_mismatch',
        sourceToolJobId,
        revisionId: revision.revisionId,
        artifactId: revision.artifactId,
      });
    }
  }
}

function validateResultChangeSetReplayPackage(packageDir) {
  let root;
  let manifest;
  try {
    root = fs.realpathSync(packageDir);
    if (!fs.statSync(root).isDirectory()) throw new Error('not_directory');
    const manifestPath = path.join(root, 'cohort-manifest.json');
    const stat = fs.lstatSync(manifestPath);
    if (stat.isSymbolicLink() || !stat.isFile()) throw new Error('not_regular');
    manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8'));
  } catch {
    return { ok: false, diagnostics: [{ code: 'replay_cohort_manifest_missing' }] };
  }

  const diagnostics = [];
  if (!hasExactFields(manifest, COHORT_MANIFEST_FIELDS)) {
    diagnostics.push({ code: 'replay_cohort_manifest_schema_invalid' });
  }
  const { packageDigest, ...payload } = object(manifest) ? manifest : {};
  if (!SHA256.test(packageDigest) || stableHash(payload) !== packageDigest) {
    diagnostics.push({ code: 'replay_cohort_manifest_hash_mismatch' });
  }
  if (!object(manifest) || manifest.resultChangeSetReplayPackageVersion !== RESULT_CHANGESET_REPLAY_PACKAGE_VERSION
      || !isSafeIdentifier(manifest.sourceChangeSetId) || !GIT_COMMIT.test(manifest.sourceCandidateCommit)
      || !isSafeIdentifier(manifest.selectedSourceRevisionId) || !isSafeIdentifier(manifest.executionRootRevisionId)) {
    diagnostics.push({ code: 'replay_cohort_manifest_identity_invalid' });
  }

  const jobsById = new Map();
  if (!Array.isArray(manifest?.jobs) || manifest.jobs.length < 2) {
    diagnostics.push({ code: 'replay_cohort_jobs_missing' });
  } else {
    for (const entry of manifest.jobs) {
      const sourceToolJobId = entry?.sourceToolJobId || null;
      if (!hasExactFields(entry, COHORT_JOB_FIELDS)
          || !isSafeIdentifier(sourceToolJobId) || !isSafeIdentifier(entry.toolId)
          || !validUniqueIdentifiers(entry.formalArtifactIds, { requireSorted: true })
          || !isSafeCohortRelativePath(entry.relativePath) || !SHA256.test(entry.packageDigest)
          || !REPLAY_PACKAGE_STATUSES.has(entry.status)) {
        diagnostics.push({ code: 'replay_cohort_job_schema_invalid', sourceToolJobId });
        continue;
      }
      if (jobsById.has(sourceToolJobId)) {
        diagnostics.push({ code: 'replay_cohort_job_duplicate', sourceToolJobId });
        continue;
      }
      jobsById.set(sourceToolJobId, entry);
    }
    if (jobsById.size !== manifest.jobs.length) {
      diagnostics.push({ code: 'replay_cohort_job_cohort_mismatch' });
    }
  }

  const revisionsById = new Map();
  const revisionsByJobArtifact = new Map();
  if (!Array.isArray(manifest?.revisions) || manifest.revisions.length === 0) {
    diagnostics.push({ code: 'replay_cohort_revisions_missing' });
  } else {
    for (const revision of manifest.revisions) {
      const revisionId = revision?.revisionId || null;
      if (!hasExactFields(revision, COHORT_REVISION_FIELDS)
          || !isSafeIdentifier(revisionId) || !isSafeIdentifier(revision.toolJobId)
          || !isSafeIdentifier(revision.artifactFamilyId) || !isSafeIdentifier(revision.artifactId)
          || !SHA256.test(revision.outputHash)) {
        diagnostics.push({ code: 'replay_cohort_revision_schema_invalid', revisionId });
        continue;
      }
      const identity = `${revision.toolJobId}\u0000${revision.artifactId}`;
      if (revisionsById.has(revisionId) || revisionsByJobArtifact.has(identity)) {
        diagnostics.push({ code: 'replay_cohort_revision_duplicate', revisionId });
        continue;
      }
      revisionsById.set(revisionId, revision);
      revisionsByJobArtifact.set(identity, revision);
    }
    if (revisionsById.size !== manifest.revisions.length) {
      diagnostics.push({ code: 'replay_cohort_revision_cohort_mismatch' });
    }
  }

  for (const [sourceToolJobId, entry] of jobsById.entries()) {
    for (const artifactId of entry.formalArtifactIds) {
      if (!revisionsByJobArtifact.has(`${sourceToolJobId}\u0000${artifactId}`)) {
        diagnostics.push({ code: 'replay_cohort_formal_artifact_revision_missing', sourceToolJobId, artifactId });
      }
    }
  }
  for (const revision of revisionsById.values()) {
    const entry = jobsById.get(revision.toolJobId) || null;
    if (!entry || !entry.formalArtifactIds.includes(revision.artifactId)) {
      diagnostics.push({
        code: 'replay_cohort_revision_formal_artifact_mismatch',
        revisionId: revision.revisionId,
        sourceToolJobId: revision.toolJobId,
        artifactId: revision.artifactId,
      });
    }
  }
  if (!revisionsById.has(manifest?.selectedSourceRevisionId)
      || !revisionsById.has(manifest?.executionRootRevisionId)) {
    diagnostics.push({ code: 'replay_cohort_selected_revision_missing' });
  }

  validateCohortWorkflowGraph({
    workflowGraph: manifest?.workflowGraph,
    jobsById,
    revisionsById,
    diagnostics,
  });
  const rootRevision = revisionsById.get(manifest?.executionRootRevisionId) || null;
  if (rootRevision && rootRevision.toolJobId !== manifest?.workflowGraph?.rootToolJobId) {
    diagnostics.push({ code: 'replay_cohort_execution_root_mismatch', revisionId: rootRevision.revisionId });
  }

  validateCohortPackageRoot({ root, sourceToolJobIds: [...jobsById.keys()], diagnostics });
  const projectId = manifest?.workflowGraph?.projectId;
  for (const [sourceToolJobId, entry] of jobsById.entries()) {
    const revisions = [...revisionsById.values()]
      .filter((revision) => revision.toolJobId === sourceToolJobId)
      .sort((left, right) => left.artifactId.localeCompare(right.artifactId));
    validateCohortChildPackage({ root, entry, revisions, projectId, diagnostics });
  }

  return {
    ok: diagnostics.length === 0,
    packageDigest: packageDigest || null,
    diagnostics,
    manifest,
  };
}


module.exports = {
  SHA256,
  CONTROLLED_REPLAY_VERSION,
  DEFAULT_CONFIRMATION_TTL_MS,
  GIT_COMMIT,
  SAFE_ID,
  RESULT_CHANGESET_REPLAY_PACKAGE_VERSION,
  REPLAY_PACKAGE_STATUSES,
  COHORT_MANIFEST_FIELDS,
  COHORT_WORKFLOW_FIELDS,
  COHORT_WORKFLOW_NODE_FIELDS,
  COHORT_WORKFLOW_EDGE_FIELDS,
  COHORT_REVISION_FIELDS,
  COHORT_JOB_FIELDS,
  REQUEST_FIELDS,
  ResultReplayError,
  fail,
  object,
  cloneJson,
  stableHash,
  assertAllowedReplayRequest,
  safeIdentifier,
  expectedInputMap,
  hashFile,
  resolveIntactInput,
  projectSourceJobParams,
  buildReplayExecutionParams,
  assertExpectedHashes,
  assertRevisionOutput,
  parseJobResult,
  verifyReplayOutputCohort,
  buildRevisionReplayProofs,
  projectReplayExecutionCohort,
  replayCohortFingerprint,
  hasExactFields,
  isSafeIdentifier,
  isSafeCohortRelativePath,
  isStrictlyContainedPath,
  isSafeWorkflowNodeId,
  validUniqueIdentifiers,
  readRegularJsonInside,
  resolveCohortChildDirectory,
  validateCohortPackageRoot,
  validateCohortWorkflowGraph,
  validateCohortChildPackage,
  validateResultChangeSetReplayPackage,
};

'use strict';

const crypto = require('node:crypto');
const fs = require('node:fs');
const path = require('node:path');
const { isPathContained } = require('./project-run-layout');
const { isSafeRelativePath } = require('./result-studio-contracts');
const { stableStringify } = require('./canonical-json');
const { resolveExecutionInputPath } = require('./execution-provenance');

const MAX_SOURCE_BYTES = 2 * 1024 * 1024;
const MAX_PARAMETERS_BYTES = 1024 * 1024;
const SHA256 = /^[a-f0-9]{64}$/;
const COMMIT = /^[a-f0-9]{40}$/;
const SENSITIVE_KEY = /(?:api.?key|access.?token|secret|password|credential|private.?key)/i;

class ResultRevisionSourceError extends Error {
  constructor(code, message, status = 409, detail = null) {
    super(message);
    this.name = 'ResultRevisionSourceError';
    this.code = code;
    this.status = status;
    this.detail = detail;
  }
}

function sha256(value) {
  return crypto.createHash('sha256').update(value).digest('hex');
}

function fail(code, message, status = 409, detail = null) {
  throw new ResultRevisionSourceError(code, message, status, detail);
}

function safeRef(value, field, required = false) {
  const normalized = typeof value === 'string' ? value.trim() : '';
  if (!normalized && !required) return null;
  if (!normalized || !isSafeRelativePath(normalized)) {
    fail(`${field}_invalid`, `${field} is not a safe project-relative path.`);
  }
  return normalized;
}

function parseJsonObject(text, code) {
  try {
    const value = JSON.parse(text);
    if (!value || typeof value !== 'object' || Array.isArray(value)) fail(code, 'Parameters must be a JSON object.');
    return value;
  } catch (error) {
    if (error instanceof ResultRevisionSourceError) throw error;
    fail(code, 'Parameters JSON is invalid.');
  }
}

function sanitizeValue(value, key = '') {
  if (SENSITIVE_KEY.test(key)) return '[redacted]';
  if (typeof value === 'string' && path.isAbsolute(value)) return '[redacted-path]';
  if (Array.isArray(value)) return value.map((item) => sanitizeValue(item));
  if (value && typeof value === 'object') {
    return Object.fromEntries(Object.entries(value).map(([childKey, child]) => [childKey, sanitizeValue(child, childKey)]));
  }
  return value;
}

function parseResult(job) {
  if (!job) return {};
  if (job.result && typeof job.result === 'object') return job.result;
  try { return JSON.parse(job.result_json || '{}'); } catch { return {}; }
}

function exactArtifact(result, artifactId) {
  const matches = (Array.isArray(result?.artifacts) ? result.artifacts : [])
    .filter((artifact) => artifact && artifact.id === artifactId);
  return matches.length === 1 ? matches[0] : null;
}

function projectGitPath(relativePath, gitPathPrefix = '') {
  const safe = safeRef(relativePath, 'sourceScriptRef.relativePath', true);
  const prefix = String(gitPathPrefix || '').replace(/^\/+|\/+$/g, '');
  return prefix ? path.posix.join(prefix, safe) : safe;
}

function verifyCommit(adapter, sourceCommit) {
  if (!COMMIT.test(String(sourceCommit || ''))) fail('source_commit_invalid', 'Revision source commit is invalid.');
  // `git rev-parse --verify <40-hex>` accepts a syntactically complete object
  // id even when the object is absent. Peeling to a commit forces the object
  // lookup, so an expired/pruned Revision cannot fall through to a generic
  // missing-file response or, worse, a nearby worktree fallback.
  if (adapter.revParse(`${sourceCommit}^{commit}`) !== sourceCommit) {
    fail('source_commit_unavailable', 'Revision source commit is unavailable.');
  }
}

function classifyScope(sourceScriptRef) {
  if (sourceScriptRef?.origin === 'project_materialized') return 'artifact_specific_materialization';
  if (sourceScriptRef?.origin === 'execution_snapshot') return 'job_shared_execution_snapshot';
  if (sourceScriptRef?.origin === 'canonical_plugin') return 'canonical_plugin_shared';
  return 'unknown_legacy';
}

function inputStatus({ workspaceRoot, inputs, params = {}, provenance = null }) {
  const statuses = [];
  for (const input of Array.isArray(inputs) ? inputs : []) {
    let status = 'unavailable';
    try {
      safeRef(input?.relativePath, 'input.relativePath', true);
      const resolved = resolveExecutionInputPath({
        workspaceRoot,
        input,
        sourceParams: params,
        provenance,
      });
      if (!resolved.path) status = 'missing';
      else status = sha256(fs.readFileSync(resolved.path)) === input.sha256 ? 'intact' : 'hash_drift';
    } catch {
      status = 'missing';
    }
    statuses.push({ artifactId: input?.sourceArtifactRef || input?.id || null, role: input?.role || null, sha256: input?.sha256 || null, status });
  }
  return statuses;
}

function projectRevisionSource(input = {}, dependencies = {}) {
  const projectId = String(input.projectId || '').trim();
  const repository = dependencies.repository;
  const adapter = dependencies.adapter;
  const getToolJob = dependencies.getToolJob;
  if (!projectId || !repository || !adapter || typeof getToolJob !== 'function') fail('projection_dependencies_missing', 'Revision source projection dependencies are incomplete.', 500);
  const revision = input.revision || repository.getRevision(String(input.revisionId || '').trim());
  if (!revision || revision.projectId !== projectId) fail('revision_not_found', 'Revision is not available in this project.', 404);
  const changeSet = revision.changeSetId ? repository.getChangeSet(revision.changeSetId) : null;
  if (!changeSet || changeSet.projectId !== projectId || changeSet.candidateCommit !== revision.sourceCommit) {
    fail('revision_lineage_invalid', 'Revision lineage is not bound to this project and source commit.');
  }
  const sourceRef = revision.sourceScriptRef;
  if (!sourceRef || !sourceRef.relativePath || !SHA256.test(sourceRef.sha256 || '')
    || sourceRef.artifactId !== revision.artifactId || !sourceRef.rendererId || !sourceRef.language) {
    fail('source_ref_invalid', 'Revision source reference is incomplete.');
  }
  const sourcePath = projectGitPath(sourceRef.relativePath, dependencies.gitPathPrefix);
  verifyCommit(adapter, revision.sourceCommit);
  let content;
  try {
    content = adapter.showFile({ ref: revision.sourceCommit, filePath: sourcePath });
  } catch {
    fail('source_unavailable', 'Revision source content is unavailable or exceeds the safe limit.');
  }
  if (typeof content !== 'string' || Buffer.byteLength(content) > MAX_SOURCE_BYTES || content.includes('\0')) {
    fail('source_unavailable', 'Revision source content is unavailable or exceeds the safe limit.');
  }
  if (sha256(content) !== sourceRef.sha256) fail('source_hash_mismatch', 'Revision source content does not match its recorded hash.');
  if (input.expectSha256 && (!SHA256.test(input.expectSha256) || input.expectSha256 !== sourceRef.sha256)) {
    fail('source_expectation_stale', 'The requested source hash no longer matches this Revision.');
  }

  const parametersPath = safeRef(revision.parametersRef, 'parametersRef');
  let parameters = null;
  if (parametersPath) {
    if (!SHA256.test(revision.parametersHash || '')) fail('parameters_hash_invalid', 'Revision parameters hash is invalid.');
    let parametersText;
    try {
      parametersText = adapter.showFile({ ref: revision.sourceCommit, filePath: projectGitPath(parametersPath, dependencies.gitPathPrefix) });
    } catch {
      fail('parameters_unavailable', 'Revision parameters are unavailable or too large.');
    }
    if (typeof parametersText !== 'string' || Buffer.byteLength(parametersText) > MAX_PARAMETERS_BYTES) fail('parameters_unavailable', 'Revision parameters are unavailable or too large.');
    if (sha256(parametersText) !== revision.parametersHash) fail('parameters_hash_mismatch', 'Revision parameters do not match their recorded hash.');
    parameters = { text: parametersText, values: parseJsonObject(parametersText, 'parameters_invalid'), sha256: revision.parametersHash, relativePath: parametersPath };
  }

  const job = getToolJob(revision.toolJobId);
  const result = parseResult(job);
  const provenance = result.executionProvenance;
  if (!job || String(job.project_id || job.projectId || '') !== projectId || job.status !== 'completed') fail('source_job_invalid', 'Revision is not backed by a completed Job in this project.');
  if (!provenance || provenance.toolJobId !== job.id || String(provenance.projectId || '') !== projectId) fail('source_provenance_invalid', 'Revision execution provenance is not bound to its Job and project.');
  if (provenance.script?.sha256 !== sourceRef.sha256) fail('source_provenance_script_mismatch', 'Job provenance does not match the Revision source hash.');
  if (result.artifactTruth?.status !== 'valid' || result.artifactTruth.blocking === true) fail('source_artifact_truth_invalid', 'Revision Job has invalid Artifact Truth.');
  const artifact = exactArtifact(result, revision.artifactId);
  const provenanceArtifact = (Array.isArray(provenance.artifacts) ? provenance.artifacts : []).filter((item) => item?.id === revision.artifactId);
  if (!artifact || provenanceArtifact.length !== 1 || (revision.outputHash && provenanceArtifact[0].sha256 !== revision.outputHash)) fail('source_artifact_provenance_invalid', 'Revision Artifact is not uniquely bound by Job provenance.');

  const inputs = inputStatus({
    workspaceRoot: dependencies.workspaceRoot,
    inputs: provenance.inputs,
    params: job.params,
    provenance,
  });
  const inputDrift = inputs.filter((item) => item.status !== 'intact');
  let openableRelativePath = null;
  if (sourceRef.origin === 'project_materialized' && dependencies.workspaceRoot) {
    try {
      const root = fs.realpathSync(dependencies.workspaceRoot);
      const target = fs.realpathSync(path.join(root, sourceRef.relativePath));
      if (isPathContained(root, target) && fs.statSync(target).isFile() && sha256(fs.readFileSync(target)) === sourceRef.sha256) openableRelativePath = sourceRef.relativePath;
    } catch { /* Virtual Git sources normally have no worktree file. */ }
  }
  const runtime = provenance.runtime || {};
  return {
    revisionId: revision.revisionId,
    artifactId: revision.artifactId,
    revisionOrdinal: revision.revisionOrdinal,
    relativePath: sourceRef.relativePath,
    entryPoint: sourceRef.entryPoint || path.posix.basename(sourceRef.relativePath),
    language: sourceRef.language,
    origin: sourceRef.origin || 'unknown_legacy',
    rendererId: sourceRef.rendererId,
    scope: classifyScope(sourceRef),
    content,
    sha256: sourceRef.sha256,
    openableRelativePath,
    parameters: parameters ? {
      relativePath: parameters.relativePath,
      sha256: parameters.sha256,
      values: sanitizeValue(parameters.values),
      // Only trusted in-process execution services may request the exact
      // persisted values. The HTTP source projection never sets this flag, so
      // absolute paths and secret-shaped values remain absent from ordinary
      // Code/Result responses.
      ...(dependencies.allowRawParameters === true ? { rawValues: parameters.values } : {}),
    } : null,
    reproduction: {
      status: inputDrift.length === 0 ? revision.reproducibilityStatus : 'unavailable',
      requiresConfirmation: true,
      inputDrift,
      inputs,
      runtime: { name: runtime.name || null, version: runtime.version || null, readiness: runtime.readiness ?? null },
      plugin: { id: provenance.plugin?.id || job.tool_id || null, version: provenance.plugin?.version || null, language: provenance.plugin?.language || sourceRef.language, packageConstraints: sanitizeValue(provenance.plugin?.packageConstraints || {}) },
      replayable: inputDrift.length === 0 && Boolean(parameters),
    },
  };
}

function verifyRevisionSourceMaterial(input, dependencies) {
  const projection = projectRevisionSource(input, dependencies);
  if (projection.reproduction.inputDrift.length > 0) fail('source_input_drift', 'One or more reproducibility inputs changed or are unavailable.');
  return projection;
}

module.exports = { MAX_SOURCE_BYTES, ResultRevisionSourceError, projectRevisionSource, verifyRevisionSourceMaterial, sha256 };

'use strict';

/**
 * G0-RS-P5 — bounded, schema-declared scientific comparison.
 *
 * This module never guesses a biological conclusion from an arbitrary CSV.
 * Only the formal artifact identities and schemas declared by the built-in
 * Result Studio contracts are interpreted.  Any missing schema, duplicate
 * stable identifier, malformed numeric value or oversized table becomes an
 * explicit `unavailable` result rather than a plausible-looking statistic.
 */

const fs = require('fs');

const SCIENTIFIC_COMPARE_VERSION = 1;
const MAX_BYTES = 4 * 1024 * 1024;
const MAX_KEY_ENTITIES = 20;

function unavailable(kind, reason) {
  return { scientificComparisonVersion: SCIENTIFIC_COMPARE_VERSION, status: 'unavailable', kind, reason };
}

function splitDelimitedLine(line, delimiter) {
  const cells = [];
  let current = '';
  let quoted = false;
  for (let index = 0; index < line.length; index += 1) {
    const char = line[index];
    if (char === '"') {
      if (quoted && line[index + 1] === '"') { current += '"'; index += 1; continue; }
      quoted = !quoted;
      continue;
    }
    if (char === delimiter && !quoted) { cells.push(current); current = ''; continue; }
    current += char;
  }
  cells.push(current);
  return cells;
}

function readExactTable(filePath) {
  const stat = fs.statSync(filePath);
  if (stat.size > MAX_BYTES) return { ok: false, reason: 'scientific_table_exceeds_exact_bound' };
  const raw = fs.readFileSync(filePath, 'utf8');
  const lines = raw.split(/\r?\n/).filter((line) => line.trim() !== '');
  if (lines.length === 0) return { ok: false, reason: 'scientific_table_empty' };
  const delimiter = (lines[0].match(/\t/g) || []).length > (lines[0].match(/,/g) || []).length ? '\t' : ',';
  const columns = splitDelimitedLine(lines[0], delimiter).map((value) => value.trim());
  if (columns.length === 0 || columns.some((value) => !value)) return { ok: false, reason: 'scientific_table_header_invalid' };
  if (new Set(columns.map((value) => value.toLowerCase())).size !== columns.length) {
    return { ok: false, reason: 'scientific_table_header_ambiguous' };
  }
  const rows = [];
  for (const line of lines.slice(1)) {
    const values = splitDelimitedLine(line, delimiter);
    if (values.length !== columns.length) return { ok: false, reason: 'scientific_table_row_shape_invalid' };
    rows.push(Object.fromEntries(columns.map((column, index) => [column, values[index]])));
  }
  return { ok: true, columns, rows };
}

function findColumn(columns, aliases) {
  const byLower = new Map(columns.map((column) => [column.toLowerCase(), column]));
  for (const alias of aliases) if (byLower.has(alias.toLowerCase())) return byLower.get(alias.toLowerCase());
  return null;
}

function number(value) {
  if (value == null || String(value).trim() === '') return null;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
}

function stableRows(table, idColumn) {
  const rows = new Map();
  for (const row of table.rows) {
    const id = String(row[idColumn] || '').trim();
    if (!id || rows.has(id)) return null;
    rows.set(id, row);
  }
  return rows;
}

function bounded(values) {
  return [...values].sort().slice(0, MAX_KEY_ENTITIES);
}

function setChanges(before, after) {
  const gained = [];
  const lost = [];
  const retained = [];
  for (const id of after) (before.has(id) ? retained : gained).push(id);
  for (const id of before) if (!after.has(id)) lost.push(id);
  return {
    gainedCount: gained.length,
    lostCount: lost.length,
    retainedCount: retained.length,
    gained: bounded(gained),
    lost: bounded(lost),
  };
}

function degThresholds(params) {
  const padj = number(params?.padj_cutoff ?? params?.padj_threshold);
  const lfc = number(params?.lfc_cutoff ?? params?.lfc_threshold);
  return padj != null && padj >= 0 && padj <= 1 && lfc != null && lfc >= 0
    ? { padjCutoff: padj, lfcCutoff: lfc }
    : null;
}

function classifyDeg(table, thresholds) {
  const geneColumn = findColumn(table.columns, ['gene', 'gene_id']);
  const lfcColumn = findColumn(table.columns, ['log2FoldChange', 'log2FC']);
  const padjColumn = findColumn(table.columns, ['padj', 'p_adjust']);
  if (!geneColumn || !lfcColumn || !padjColumn) return null;
  const rows = stableRows(table, geneColumn);
  if (!rows) return null;
  const significant = new Set();
  let up = 0;
  let down = 0;
  for (const [gene, row] of rows) {
    const lfc = number(row[lfcColumn]);
    const padj = number(row[padjColumn]);
    if (lfc == null || padj == null || padj < 0 || padj > 1) return null;
    // Match the admitted DESeq2/go-kegg producers exactly. Boundary values
    // are not significant because both scripts use strict cutoffs.
    if (padj < thresholds.padjCutoff && Math.abs(lfc) > thresholds.lfcCutoff) {
      significant.add(gene);
      if (lfc > 0) up += 1;
      if (lfc < 0) down += 1;
    }
  }
  return { significant, summary: { significantCount: significant.size, upCount: up, downCount: down } };
}

function compareDeg(before, after, beforeParams, afterParams) {
  const beforeThresholds = degThresholds(beforeParams);
  const afterThresholds = degThresholds(afterParams);
  if (!beforeThresholds || !afterThresholds) return unavailable('differential_expression', 'scientific_thresholds_unavailable');
  const left = classifyDeg(before, beforeThresholds);
  const right = classifyDeg(after, afterThresholds);
  if (!left || !right) return unavailable('differential_expression', 'deg_schema_or_stable_gene_id_invalid');
  return {
    scientificComparisonVersion: SCIENTIFIC_COMPARE_VERSION,
    status: 'available',
    kind: 'differential_expression',
    thresholds: { before: beforeThresholds, after: afterThresholds },
    significantGenes: { before: left.summary, after: right.summary, membership: setChanges(left.significant, right.significant) },
  };
}

function classifyVolcano(table) {
  const geneColumn = findColumn(table.columns, ['gene', 'gene_id']);
  const statusColumn = findColumn(table.columns, ['sig']);
  if (!geneColumn || !statusColumn) return null;
  const rows = stableRows(table, geneColumn);
  if (!rows) return null;
  const significant = new Set();
  const summary = { upCount: 0, downCount: 0, nonSignificantCount: 0 };
  for (const [gene, row] of rows) {
    const status = String(row[statusColumn] || '').trim().toLowerCase();
    if (status === 'up') { summary.upCount += 1; significant.add(gene); }
    else if (status === 'down') { summary.downCount += 1; significant.add(gene); }
    else if (status === 'ns') summary.nonSignificantCount += 1;
    else return null;
  }
  return { significant, summary: { ...summary, significantCount: significant.size } };
}

function compareVolcano(before, after) {
  const left = classifyVolcano(before);
  const right = classifyVolcano(after);
  if (!left || !right) return unavailable('volcano_classification', 'volcano_schema_or_stable_gene_id_invalid');
  return {
    scientificComparisonVersion: SCIENTIFIC_COMPARE_VERSION,
    status: 'available',
    kind: 'volcano_classification',
    classifications: { before: left.summary, after: right.summary, membership: setChanges(left.significant, right.significant) },
  };
}

function rankTerms(table) {
  const idColumn = findColumn(table.columns, ['ID', 'term_id']);
  const adjustedColumn = findColumn(table.columns, ['p.adjust', 'p_adjust', 'padj']);
  const directionColumn = findColumn(table.columns, ['direction', 'regulation']);
  if (!idColumn || !adjustedColumn) return null;
  const rows = stableRows(table, idColumn);
  if (!rows) return null;
  const ranked = [];
  for (const [id, row] of rows) {
    const adjusted = number(row[adjustedColumn]);
    if (adjusted == null || adjusted < 0 || adjusted > 1) return null;
    const direction = directionColumn ? String(row[directionColumn] || '').trim() : null;
    if (directionColumn && !['up', 'down', 'mixed', 'unresolved', 'unavailable_without_signed_deg'].includes(direction)) {
      return null;
    }
    ranked.push({ id, adjusted, direction });
  }
  ranked.sort((left, right) => left.adjusted - right.adjusted || left.id.localeCompare(right.id));
  return {
    ranked,
    directionStatus: !directionColumn
      ? { status: 'unavailable', reason: 'enrichment_table_has_no_declared_direction_column' }
      : ranked.some((item) => item.direction === 'unavailable_without_signed_deg')
        ? { status: 'unavailable', reason: 'enrichment_direction_unavailable_without_signed_deg' }
        : { status: 'available' },
  };
}

function compareEnrichment(before, after) {
  const leftResult = rankTerms(before);
  const rightResult = rankTerms(after);
  if (!leftResult || !rightResult) return unavailable('functional_enrichment', 'enrichment_schema_or_stable_term_id_invalid');
  const left = leftResult.ranked;
  const right = rightResult.ranked;
  const leftIds = new Set(left.map((item) => item.id));
  const rightIds = new Set(right.map((item) => item.id));
  const directionAvailable = leftResult.directionStatus.status === 'available'
    && rightResult.directionStatus.status === 'available';
  const rightById = new Map(right.map((item) => [item.id, item]));
  const directionChanges = directionAvailable
    ? left
      .filter((item) => rightById.has(item.id) && rightById.get(item.id).direction !== item.direction)
      .map((item) => ({ id: item.id, before: item.direction, after: rightById.get(item.id).direction }))
      .sort((a, b) => a.id.localeCompare(b.id))
      .slice(0, MAX_KEY_ENTITIES)
    : [];
  return {
    scientificComparisonVersion: SCIENTIFIC_COMPARE_VERSION,
    status: 'available',
    kind: 'functional_enrichment',
    terms: {
      beforeCount: left.length,
      afterCount: right.length,
      membership: setChanges(leftIds, rightIds),
      topBefore: left.slice(0, 10).map((item, index) => ({ rank: index + 1, id: item.id, adjustedPValue: item.adjusted })),
      topAfter: right.slice(0, 10).map((item, index) => ({ rank: index + 1, id: item.id, adjustedPValue: item.adjusted })),
    },
    direction: directionAvailable
      ? {
        status: 'available',
        before: left.slice(0, 10).map((item) => ({ id: item.id, direction: item.direction })),
        after: right.slice(0, 10).map((item) => ({ id: item.id, direction: item.direction })),
        changedCount: directionChanges.length,
        changes: directionChanges,
      }
      : {
        status: 'unavailable',
        reason: leftResult.directionStatus.status === 'unavailable'
          ? leftResult.directionStatus.reason
          : rightResult.directionStatus.reason,
      },
  };
}

function compareScientificTables({ artifactId, beforePath, afterPath, beforeParameters = null, afterParameters = null } = {}) {
  const type = artifactId === 'deg_table'
    ? 'differential_expression'
    : artifactId === 'classified_table'
      ? 'volcano_classification'
      : ['go_bp_results', 'kegg_results'].includes(artifactId)
        ? 'functional_enrichment'
        : 'unrecognized';
  if (type === 'unrecognized') return unavailable(type, 'scientific_schema_not_declared_for_artifact');
  let before;
  let after;
  try { before = readExactTable(beforePath); after = readExactTable(afterPath); }
  catch { return unavailable(type, 'scientific_table_unreadable'); }
  if (!before.ok) return unavailable(type, before.reason);
  if (!after.ok) return unavailable(type, after.reason);
  if (type === 'differential_expression') return compareDeg(before, after, beforeParameters, afterParameters);
  if (type === 'volcano_classification') return compareVolcano(before, after);
  return compareEnrichment(before, after);
}

module.exports = {
  SCIENTIFIC_COMPARE_VERSION,
  compareScientificTables,
};

'use strict';

const SCIENTIFIC_RERUN_VERSION = 1;

const DEG_DIRECT_CHILD_PRIMARY_ARTIFACTS = Object.freeze({
  'go-kegg': 'go_bp_results',
  'volcano-plot': 'volcano',
});

const DEG_THRESHOLD_PARAMETER_ALIASES = Object.freeze({
  adjusted_p_value_cutoff: Object.freeze(['padj_cutoff', 'padj_threshold']),
  absolute_log2_fold_change_cutoff: Object.freeze(['lfc_cutoff', 'lfc_threshold', 'fc_threshold']),
});

function own(object, key) {
  return !!object && Object.prototype.hasOwnProperty.call(object, key);
}

function cloneObject(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return null;
  try { return JSON.parse(JSON.stringify(value)); } catch { return null; }
}

function parameterNames(descriptor, aliases) {
  const parameters = descriptor?.parameters && typeof descriptor.parameters === 'object'
    ? descriptor.parameters : {};
  return aliases.filter((name) => own(parameters, name));
}

function validDescriptorValue(specification, value) {
  if (!specification || typeof specification !== 'object') return false;
  if (specification.type === 'number') {
    return typeof value === 'number' && Number.isFinite(value)
      && (specification.minimum == null || value >= Number(specification.minimum))
      && (specification.maximum == null || value <= Number(specification.maximum));
  }
  return false;
}

function failure(code, message, detail = null) {
  return { ok: false, code, message, ...(detail == null ? {} : { detail }) };
}

/**
 * Project scientific DEG threshold changes into a downstream descriptor.
 * Both descriptors must name exactly one alias for a changed semantic value;
 * preserving an old child value or guessing an undeclared name is forbidden.
 */
function propagateDegThresholds({
  sourceDescriptor,
  downstreamDescriptor,
  sourceParameterPatch,
  downstreamNormalizedParams,
  downstreamRawParams,
} = {}) {
  const normalized = cloneObject(downstreamNormalizedParams);
  const raw = cloneObject(downstreamRawParams);
  if (!normalized || !raw || !sourceParameterPatch || typeof sourceParameterPatch !== 'object'
      || Array.isArray(sourceParameterPatch)) {
    return failure('downstream_parameter_context_invalid', 'Downstream scientific parameters are not safely serializable objects.');
  }
  const propagated = [];
  for (const [semantic, aliases] of Object.entries(DEG_THRESHOLD_PARAMETER_ALIASES)) {
    const sourceNames = parameterNames(sourceDescriptor, aliases)
      .filter((name) => own(sourceParameterPatch, name));
    if (sourceNames.length === 0) continue;
    if (sourceNames.length !== 1) {
      return failure('source_parameter_mapping_ambiguous', 'A DEG threshold patch maps to more than one declared source parameter.', { semantic, sourceNames });
    }
    const downstreamNames = parameterNames(downstreamDescriptor, aliases);
    if (downstreamNames.length !== 1) {
      return failure('downstream_parameter_mapping_missing', 'A changed DEG threshold has no unique declared downstream parameter.', { semantic, downstreamNames });
    }
    const sourceName = sourceNames[0];
    const downstreamName = downstreamNames[0];
    const value = sourceParameterPatch[sourceName];
    if (!validDescriptorValue(downstreamDescriptor.parameters[downstreamName], value)) {
      return failure('downstream_parameter_value_invalid', 'A propagated DEG threshold violates the downstream descriptor.', { semantic, downstreamName });
    }
    normalized[downstreamName] = value;
    raw[downstreamName] = value;
    propagated.push({ semantic, sourceName, downstreamName, value });
  }
  return {
    ok: true,
    scientificRerunVersion: SCIENTIFIC_RERUN_VERSION,
    normalizedParams: normalized,
    rawParams: raw,
    propagated,
  };
}

module.exports = {
  SCIENTIFIC_RERUN_VERSION,
  DEG_DIRECT_CHILD_PRIMARY_ARTIFACTS,
  DEG_THRESHOLD_PARAMETER_ALIASES,
  propagateDegThresholds,
};

'use strict';

const path = require('path');
const { execFile } = require('child_process');
const { fork } = require('child_process');

const DEFAULT_TIMEOUT_MS = 120000;
const WRITE_COMPLETION_GRACE_MS = 60000;
const TERMINATION_GRACE_MS = 2000;
const IDLE_SHUTDOWN_MS = 10000;
const MAX_PENDING = 32;
const childPath = path.join(__dirname, 'result-studio-background-child.js');

let generationSequence = 0;
let requestSequence = 0;
let currentGeneration = null;
const pending = new Map();

class ResultStudioBackgroundError extends Error {
  constructor(code, message, detail = null) {
    super(message);
    this.name = 'ResultStudioBackgroundError';
    this.code = code;
    this.detail = detail;
  }
}

const errorOf = (code, message) => new ResultStudioBackgroundError(code, message);
const isWriteOperation = (operation) => operation === 'ensure-baseline' || operation === 'recover-workspace';

function settleClient(task, method, value) {
  if (task.clientSettled) return;
  task.clientSettled = true;
  task[method](value);
}

function clearTaskTimers(task) {
  if (task.timer) clearTimeout(task.timer);
  if (task.finalTimer) clearTimeout(task.finalTimer);
  task.timer = null;
  task.finalTimer = null;
}

function removeQueued(generation, requestId) {
  const index = generation.queue.indexOf(requestId);
  if (index >= 0) generation.queue.splice(index, 1);
}

function removeTask(task) {
  pending.delete(task.requestId);
  removeQueued(task.generation, task.requestId);
  if (task.generation.activeRequestId === task.requestId) {
    task.generation.activeRequestId = null;
  }
  clearTaskTimers(task);
}

function terminateProcessTree(child, signal = 'SIGTERM') {
  if (!child || !child.pid) return;
  if (process.platform === 'win32') {
    // taskkill /T includes descendants. Arguments are fixed and never pass
    // through a shell.
    execFile('taskkill.exe', ['/pid', String(child.pid), '/t', '/f'], {
      windowsHide: true,
      timeout: TERMINATION_GRACE_MS,
    }, () => {});
    return;
  }
  try {
    // The helper is forked detached on POSIX, so its Git descendants share this
    // private process group and cannot survive as orphans.
    process.kill(-child.pid, signal);
  } catch {
    try { child.kill(signal); } catch { /* already exited */ }
  }
  if (signal === 'SIGTERM') {
    const hardKill = setTimeout(() => {
      try { process.kill(-child.pid, 'SIGKILL'); } catch {
        try { child.kill('SIGKILL'); } catch { /* already exited */ }
      }
    }, TERMINATION_GRACE_MS);
    hardKill.unref?.();
  }
}

function rejectQueued(generation, error) {
  for (const requestId of [...generation.queue]) {
    const task = pending.get(requestId);
    if (!task || task === pending.get(generation.activeRequestId)) continue;
    removeTask(task);
    settleClient(task, 'reject', error);
  }
}

function finishGeneration(generation) {
  if (currentGeneration === generation) currentGeneration = null;
  if (generation.idleTimer) clearTimeout(generation.idleTimer);
  generation.idleTimer = null;
  if (!generation.closeRequested) {
    generation.child.unref();
    generation.child.channel?.unref?.();
  }
  try { generation.child.disconnect(); } catch { /* already disconnected */ }
}

function failGeneration(generation, error, { terminate = false } = {}) {
  if (currentGeneration === generation) currentGeneration = null;
  if (generation.idleTimer) clearTimeout(generation.idleTimer);
  generation.idleTimer = null;
  for (const task of [...pending.values()]) {
    if (task.generation !== generation) continue;
    removeTask(task);
    settleClient(task, 'reject', error);
  }
  if (terminate) terminateProcessTree(generation.child);
}

function scheduleIdleShutdown(generation) {
  if (generation.activeRequestId || generation.queue.length > 0 || generation.draining) return;
  if (generation.idleTimer) clearTimeout(generation.idleTimer);
  generation.child.unref();
  generation.child.channel?.unref?.();
  generation.idleTimer = setTimeout(() => {
    generation.idleTimer = null;
    if (generation.activeRequestId || generation.queue.length > 0 || generation.draining) return;
    finishGeneration(generation);
  }, IDLE_SHUTDOWN_MS);
  generation.idleTimer.unref?.();
}

function dispatchNext(generation) {
  if (generation !== currentGeneration || generation.draining || generation.activeRequestId) return;
  const requestId = generation.queue.shift();
  if (!requestId) {
    scheduleIdleShutdown(generation);
    return;
  }
  const task = pending.get(requestId);
  if (!task) {
    dispatchNext(generation);
    return;
  }
  generation.activeRequestId = requestId;
  generation.child.ref();
  generation.child.channel?.ref?.();
  generation.child.send({
    requestId,
    operation: task.operation,
    payload: task.payload,
  }, (error) => {
    if (!error) return;
    if (!pending.has(requestId)) return;
    failGeneration(generation, errorOf(
      'background_child_send_failed',
      error.message || 'Result Studio background child could not receive work.',
    ), { terminate: true });
  });
}

function handleTimeout(task) {
  if (!pending.has(task.requestId)) return;
  const generation = task.generation;
  const timeoutError = errorOf(
    'background_timeout',
    'Result Studio background work exceeded its bounded timeout.',
  );

  if (generation.activeRequestId !== task.requestId) {
    // Work not yet sent has no side effects and can be removed safely.
    removeTask(task);
    settleClient(task, 'reject', timeoutError);
    return;
  }

  if (!isWriteOperation(task.operation)) {
    // Read-only Git/hash work has no canonical mutation to complete. Kill the
    // private process group so synchronous Git descendants cannot become orphans.
    failGeneration(generation, timeoutError, { terminate: true });
    return;
  }

  // A canonical write that has begun is never killed at its request timeout.
  // Isolate the generation, reject unsent work, and let the service reach its
  // own transaction/finally boundary. Only a separate, bounded final watchdog
  // may terminate the whole private process group.
  generation.draining = true;
  settleClient(task, 'reject', timeoutError);
  rejectQueued(generation, errorOf(
    'background_generation_draining',
    'Result Studio background generation is completing a timed-out canonical write.',
  ));
  task.finalTimer = setTimeout(() => {
    if (!pending.has(task.requestId)) return;
    failGeneration(generation, errorOf(
      'background_write_final_timeout',
      'Timed-out Result Studio write did not reach a canonical completion boundary.',
    ), { terminate: true });
  }, WRITE_COMPLETION_GRACE_MS);
  task.finalTimer.unref?.();
}

function backgroundChildForkOptions(env = process.env, electronVersion = process.versions.electron) {
  return {
    stdio: ['ignore', 'ignore', 'ignore', 'ipc'],
    detached: process.platform !== 'win32',
    // In a packaged Electron process child_process.fork() reuses the Electron
    // executable. Without this flag it launches another app instance instead
    // of executing the CommonJS worker as Node.
    env: electronVersion ? { ...env, ELECTRON_RUN_AS_NODE: '1' } : { ...env },
  };
}

function startGeneration() {
  if (currentGeneration && currentGeneration.child.connected) return currentGeneration;
  const child = fork(childPath, [], backgroundChildForkOptions());
  const generation = {
    id: ++generationSequence,
    child,
    queue: [],
    activeRequestId: null,
    draining: false,
    closeRequested: false,
    idleTimer: null,
  };
  currentGeneration = generation;
  child.unref();
  child.channel?.unref?.();

  child.on('message', (message) => {
    const task = pending.get(message && message.requestId);
    if (!task || task.generation !== generation) return;
    const wasDraining = generation.draining;
    removeTask(task);
    if (!task.clientSettled) {
      if (message && message.ok === true) {
        settleClient(task, 'resolve', message.result);
      } else {
        const error = message && message.error || {};
        settleClient(task, 'reject', new ResultStudioBackgroundError(
          error.code || 'result_studio_background_failed',
          error.message || 'Result Studio background work failed.',
          error.detail ?? null,
        ));
      }
    }
    if (wasDraining) {
      // Do not reuse a generation that exceeded a write deadline. It completed
      // cooperatively, so disconnecting now is safe and leaves no queued work.
      finishGeneration(generation);
    } else {
      dispatchNext(generation);
    }
  });
  child.once('error', (error) => {
    failGeneration(generation, errorOf(
      'background_child_failed',
      error && error.message || 'Result Studio background child failed.',
    ));
  });
  child.once('exit', (code, signal) => {
    failGeneration(generation, errorOf(
      'background_child_exited',
      `Result Studio background child exited before completing work (${signal || code}).`,
    ));
  });
  return generation;
}

function runResultStudioBackground(operation, payload, options = {}) {
  if (pending.size >= MAX_PENDING) {
    return Promise.reject(errorOf(
      'background_queue_full',
      `Result Studio background queue reached its ${MAX_PENDING}-request limit.`,
    ));
  }
  if (currentGeneration?.draining) {
    return Promise.reject(errorOf(
      'background_generation_draining',
      'Result Studio background generation is completing a timed-out canonical write.',
    ));
  }
  const timeoutMs = Number.isFinite(options.timeoutMs) && options.timeoutMs > 0
    ? options.timeoutMs
    : DEFAULT_TIMEOUT_MS;
  const generation = startGeneration();
  if (generation.idleTimer) clearTimeout(generation.idleTimer);
  generation.idleTimer = null;
  const requestId = `${process.pid}-${++requestSequence}`;

  return new Promise((resolve, reject) => {
    const task = {
      requestId,
      operation,
      payload,
      generation,
      resolve,
      reject,
      clientSettled: false,
      timer: null,
      finalTimer: null,
    };
    task.timer = setTimeout(() => handleTimeout(task), timeoutMs);
    task.timer.unref?.();
    pending.set(requestId, task);
    generation.queue.push(requestId);
    dispatchNext(generation);
  });
}

function createDeduplicatedBackgroundRunner(run = runResultStudioBackground) {
  const work = new Map();
  return {
    run(key, operation, payload, options) {
      const stableKey = String(key);
      const active = work.get(stableKey);
      if (active) return active;
      const pendingWork = run(operation, payload, options);
      work.set(stableKey, pendingWork);
      pendingWork.finally(() => {
        if (work.get(stableKey) === pendingWork) work.delete(stableKey);
      }).catch(() => {});
      return pendingWork;
    },
    get size() {
      return work.size;
    },
  };
}

function closeResultStudioBackground() {
  const generation = currentGeneration;
  if (!generation) return Promise.resolve();
  if (generation.activeRequestId) {
    const active = pending.get(generation.activeRequestId);
    if (active && isWriteOperation(active.operation)) {
      generation.draining = true;
      generation.closeRequested = true;
      generation.child.ref();
      generation.child.channel?.ref?.();
      settleClient(active, 'reject', errorOf(
        'background_closed',
        'Result Studio background child is closing after its canonical write completes.',
      ));
      rejectQueued(generation, errorOf(
        'background_closed',
        'Result Studio background child was closed.',
      ));
      active.finalTimer = setTimeout(() => {
        if (!pending.has(active.requestId)) return;
        failGeneration(generation, errorOf(
          'background_write_final_timeout',
          'Closing Result Studio write did not reach a canonical completion boundary.',
        ), { terminate: true });
      }, WRITE_COMPLETION_GRACE_MS);
      active.finalTimer.unref?.();
      return new Promise((resolve) => {
        generation.child.once('exit', resolve);
      });
    }
  }
  failGeneration(generation, errorOf(
    'background_closed',
    'Result Studio background child was closed.',
  ), { terminate: true });
  return new Promise((resolve) => {
    if (generation.child.exitCode != null || generation.child.signalCode != null) resolve();
    else generation.child.once('exit', resolve);
  });
}

module.exports = {
  backgroundChildForkOptions,
  DEFAULT_TIMEOUT_MS,
  IDLE_SHUTDOWN_MS,
  MAX_PENDING,
  ResultStudioBackgroundError,
  TERMINATION_GRACE_MS,
  WRITE_COMPLETION_GRACE_MS,
  closeResultStudioBackground,
  createDeduplicatedBackgroundRunner,
  runResultStudioBackground,
};

'use strict';

/**
 * G0-RS-P3 — ResultStudioContextEnvelope v1
 *
 * 目的：用户只表达目标，Harness 自己补齐工程坐标。模型不再手写
 * toolJobId / artifactId / revisionId / changeSetId / artifactFamilyId /
 * selectionId 这些内部 ID —— 它们必须由后端真相投影出来。
 *
 * 设计边界（与 RS0～RS2 的既有真相保持一条链，不建第二套状态）：
 * - Envelope 只是**投影**：每个字段都能追到 tool_jobs / artifact_revisions /
 *   result_selection_contexts / 插件 descriptor 之一，本模块不发明任何 ID。
 * - `contextToken` 绑定当前 Revision 与选择证据。陈旧上下文上的写操作
 *   必须 fail-closed 拒绝，而不是"尽力猜"一个新目标。
 * - 只有 `compatible` 选择进入 Envelope；stale/invalid 只保留状态与原因，
 *   让 Agent 得到可行动的修复路径，而不是把旧行号映射到新结果。
 * - 归因只能到 Job（没有 per-artifact 脚本/来源）时诚实阻断，不伪造脚本坐标。
 */

const crypto = require('crypto');
const { stableStringify } = require('./canonical-json');

const RESULT_STUDIO_CONTEXT_VERSION = 1;

/**
 * 对外公开的编辑阶段词表。
 *
 * 产品层只允许展示这五个阶段结论，不展示模型隐藏推理链，也不把
 * Git/staging 这类工程细节当作主线进度。
 */
const PUBLIC_EDIT_PHASES = Object.freeze([
  'understand_intent',
  'assess_impact',
  'execute_or_recompute',
  'validate',
  'candidate_comparable',
]);

const PUBLIC_EDIT_PHASE_LABELS = Object.freeze({
  understand_intent: '理解意图',
  assess_impact: '判断影响',
  execute_or_recompute: '执行/重算',
  validate: '验证',
  candidate_comparable: '候选可比较',
});

/**
 * 工程阶段 → 公开阶段。
 *
 * `result-changeset-service` 内部仍然使用 change_set/materialize/commit/job/
 * revision/preview 这套精确工程词表（恢复扫描依赖它）。这里只做**投影**，
 * 不改写内部阶段，也不为公开层新增一套持久状态。
 */
const ENGINEERING_STAGE_TO_PUBLIC_PHASE = Object.freeze({
  intent: 'understand_intent',
  plan: 'assess_impact',
  change_set: 'assess_impact',
  materialize: 'execute_or_recompute',
  commit: 'execute_or_recompute',
  job: 'execute_or_recompute',
  revision: 'validate',
  preview: 'candidate_comparable',
});

const SHA256_PATTERN = /^[a-f0-9]{64}$/;
const SELECTION_COMPATIBILITIES = Object.freeze(['compatible', 'stale', 'invalid']);

function sha256Hex(value) {
  return crypto.createHash('sha256').update(value).digest('hex');
}

function trimmed(value) {
  return typeof value === 'string' ? value.trim() : '';
}

function nullableTrimmed(value) {
  return trimmed(value) || null;
}

function diagnostic(code, message, detail = null) {
  return { code, message, ...(detail == null ? {} : { detail }) };
}

/**
 * 把内部工程阶段投影成公开阶段。未知阶段不猜测。
 *
 * @param {string} stage 内部阶段名
 * @param {string} [status] 内部状态（running/completed/ready/terminal）
 * @returns {{ phase: string|null, label: string|null, terminal: boolean }}
 */
function projectPublicEditPhase(stage, status = null) {
  const normalizedStage = trimmed(stage);
  const normalizedStatus = trimmed(status);
  if (normalizedStage === 'failed' || normalizedStage === 'cancelled' || normalizedStatus === 'terminal') {
    return { phase: null, label: null, terminal: true };
  }
  const phase = ENGINEERING_STAGE_TO_PUBLIC_PHASE[normalizedStage] || null;
  return {
    phase,
    label: phase ? PUBLIC_EDIT_PHASE_LABELS[phase] : null,
    terminal: false,
  };
}

/**
 * 计算 contextToken。
 *
 * 覆盖：契约版本、项目/会话、Artifact 身份、当前 Revision、来源 Job、
 * 脚本与参数摘要、选择证据。任意一项变化都会让旧 token 失效。
 */
function computeContextToken(envelope) {
  return sha256Hex(stableStringify({
    contextVersion: envelope.contextVersion,
    projectId: envelope.projectId,
    conversationId: envelope.conversationId,
    artifactId: envelope.artifact && envelope.artifact.artifactId,
    artifactFamilyId: envelope.artifact && envelope.artifact.artifactFamilyId,
    revisionId: envelope.revision && envelope.revision.revisionId,
    currentRevisionId: envelope.revision && envelope.revision.currentRevisionId,
    toolJobId: envelope.job && envelope.job.toolJobId,
    sourceScriptSha256: envelope.script && envelope.script.sha256,
    parametersHash: envelope.script && envelope.script.parametersHash,
    selectionId: envelope.selection && envelope.selection.selectionId,
    selectionEntityIdsHash: envelope.selection && envelope.selection.entityIdsHash,
    selectionFilterHash: envelope.selection && envelope.selection.filterHash,
    selectionFields: envelope.selection && envelope.selection.fields,
    selectionSort: envelope.selection && envelope.selection.sort,
    selectionUpdatedAt: envelope.selection && envelope.selection.updatedAt,
    workflowGraphId: envelope.workflow && envelope.workflow.graphId,
    workflowSourceDigest: envelope.workflow && envelope.workflow.sourceDigest,
  }));
}

/**
 * 规范化并校验一个 Envelope 投影。
 *
 * 调用方必须提供已经从真实后端读出的字段；本函数不访问数据库，
 * 因此可以在纯单测中固定契约。
 *
 * @returns {{ ok: boolean, diagnostics: Array, envelope: object|null }}
 */
function buildResultStudioContextEnvelope(input = {}) {
  const diagnostics = [];
  const projectId = trimmed(input.projectId);
  if (!projectId) diagnostics.push(diagnostic('context_project_required', 'An active project is required to build a Result Studio context.'));

  const artifactInput = input.artifact || {};
  const jobInput = input.job || {};
  const revisionInput = input.revision || {};
  const scriptInput = input.script || {};
  const selectionInput = input.selection || null;
  const workflowInput = input.workflow || null;
  const pluginInput = input.plugin || {};

  const artifactId = trimmed(artifactInput.artifactId);
  const toolJobId = trimmed(jobInput.toolJobId);
  const revisionId = trimmed(revisionInput.revisionId);
  if (!artifactId) diagnostics.push(diagnostic('context_artifact_required', 'No result artifact is open; ask the user to open a result first.'));
  if (!toolJobId) diagnostics.push(diagnostic('context_job_required', 'The open artifact is not bound to a real tool job.'));
  if (!revisionId) {
    diagnostics.push(diagnostic('context_revision_missing', 'The open artifact has no persisted ArtifactRevision yet.'));
  }
  if (trimmed(jobInput.projectId) && trimmed(jobInput.projectId) !== projectId) {
    diagnostics.push(diagnostic('context_project_mismatch', 'The open artifact belongs to another project.'));
  }
  if (jobInput.status && jobInput.status !== 'completed') {
    diagnostics.push(diagnostic('context_job_not_completed', `Source job status is ${jobInput.status}.`));
  }
  if (jobInput.artifactTruthStatus && jobInput.artifactTruthStatus !== 'valid') {
    diagnostics.push(diagnostic('context_artifact_truth_invalid', 'The open artifact does not have valid artifact truth.'));
  }

  // 归因只能到 Job：没有 per-artifact 脚本坐标时诚实阻断。
  const scriptSha256 = trimmed(scriptInput.sha256);
  const scriptRelativePath = trimmed(scriptInput.relativePath);
  if (!scriptSha256 || !scriptRelativePath) {
    diagnostics.push(diagnostic(
      'context_attribution_job_only',
      'Attribution reaches only the job: this artifact has no reproducible per-artifact script reference, so an edit cannot be planned.'
    ));
  } else if (!SHA256_PATTERN.test(scriptSha256)) {
    diagnostics.push(diagnostic('context_script_hash_invalid', 'Source script hash must be a lowercase sha256 digest.'));
  }

  let selection = null;
  if (selectionInput) {
    const compatibility = trimmed(selectionInput.compatibility);
    if (!SELECTION_COMPATIBILITIES.includes(compatibility)) {
      diagnostics.push(diagnostic('context_selection_compatibility_invalid', 'Selection compatibility must be compatible, stale or invalid.'));
    } else if (compatibility === 'compatible') {
      selection = {
        selectionId: trimmed(selectionInput.selectionId),
        entityType: trimmed(selectionInput.entityType) || null,
        entityIdCount: Number.isInteger(selectionInput.entityIdCount) ? selectionInput.entityIdCount : 0,
        truncated: selectionInput.truncated === true,
        entityIdsHash: nullableTrimmed(selectionInput.entityIdsHash),
        filterHash: nullableTrimmed(selectionInput.filterHash),
        fields: Array.isArray(selectionInput.fields)
          ? selectionInput.fields.map((item) => trimmed(item)).filter(Boolean)
          : [],
        sort: Array.isArray(selectionInput.sort)
          ? selectionInput.sort
            .filter((item) => item && trimmed(item.field))
            .map((item) => ({ field: trimmed(item.field), direction: item.direction === 'desc' ? 'desc' : 'asc' }))
          : [],
        updatedAt: nullableTrimmed(selectionInput.updatedAt),
        sampleEntityIds: Array.isArray(selectionInput.sampleEntityIds)
          ? selectionInput.sampleEntityIds.slice(0, 12).map((item) => trimmed(item)).filter(Boolean)
          : [],
        hasFilter: selectionInput.hasFilter === true,
        filterDescription: nullableTrimmed(selectionInput.filterDescription),
        compatibility: 'compatible',
        compatibilityReason: nullableTrimmed(selectionInput.compatibilityReason),
      };
      if (!selection.selectionId) {
        diagnostics.push(diagnostic('context_selection_identity_missing', 'A compatible selection must carry a persisted selectionId.'));
        selection = null;
      }
    }
    // stale/invalid 选择不进入 Agent 上下文，只作为可行动状态回报。
  }
  const selectionState = selectionInput
    ? {
      present: true,
      compatibility: trimmed(selectionInput.compatibility) || 'invalid',
      reason: nullableTrimmed(selectionInput.compatibilityReason),
      usableByAgent: selection !== null,
    }
    : { present: false, compatibility: null, reason: null, usableByAgent: false };

  const envelope = {
    contextVersion: RESULT_STUDIO_CONTEXT_VERSION,
    projectId,
    conversationId: nullableTrimmed(input.conversationId),
    artifact: {
      artifactId,
      artifactFamilyId: nullableTrimmed(artifactInput.artifactFamilyId),
      name: nullableTrimmed(artifactInput.name),
      kind: nullableTrimmed(artifactInput.kind),
      entityType: nullableTrimmed(artifactInput.entityType),
      idField: nullableTrimmed(artifactInput.idField),
      interactionMode: nullableTrimmed(artifactInput.interactionMode),
    },
    job: {
      toolJobId,
      toolId: nullableTrimmed(jobInput.toolId),
      status: nullableTrimmed(jobInput.status),
      artifactTruthStatus: nullableTrimmed(jobInput.artifactTruthStatus),
    },
    revision: {
      revisionId,
      currentRevisionId: nullableTrimmed(revisionInput.currentRevisionId),
      revisionOrdinal: Number.isInteger(revisionInput.revisionOrdinal) ? revisionInput.revisionOrdinal : null,
      isCurrent: revisionInput.isCurrent === true,
      validationStatus: nullableTrimmed(revisionInput.validationStatus),
      reproducibilityStatus: nullableTrimmed(revisionInput.reproducibilityStatus),
    },
    script: {
      relativePath: scriptRelativePath || null,
      sha256: scriptSha256 || null,
      language: nullableTrimmed(scriptInput.language),
      origin: nullableTrimmed(scriptInput.origin),
      parametersRef: nullableTrimmed(scriptInput.parametersRef),
      parametersHash: nullableTrimmed(scriptInput.parametersHash),
    },
    plugin: {
      pluginId: nullableTrimmed(pluginInput.pluginId),
      descriptorVersion: Number.isInteger(pluginInput.descriptorVersion) ? pluginInput.descriptorVersion : null,
      editableParameters: Array.isArray(pluginInput.editableParameters)
        ? pluginInput.editableParameters
          .filter((item) => item && trimmed(item.name))
          .map((item) => ({
            name: trimmed(item.name),
            type: nullableTrimmed(item.type),
            impact: nullableTrimmed(item.impact),
            default: item.default === undefined ? null : item.default,
          }))
        : [],
      actions: Array.isArray(pluginInput.actions) ? pluginInput.actions.map((item) => trimmed(item)).filter(Boolean) : [],
    },
    selection,
    selectionState,
    workflow: workflowInput
      ? {
        available: true,
        graphId: nullableTrimmed(workflowInput.graphId),
        sourceDigest: nullableTrimmed(workflowInput.sourceDigest),
        snapshotStatus: ['persisted', 'not_persisted'].includes(workflowInput.snapshotStatus)
          ? workflowInput.snapshotStatus
          : 'not_persisted',
        nodeId: nullableTrimmed(workflowInput.nodeId),
        stepCount: Number.isInteger(workflowInput.stepCount) ? workflowInput.stepCount : null,
        downstreamNodeIds: Array.isArray(workflowInput.downstreamNodeIds)
          ? workflowInput.downstreamNodeIds.map((item) => trimmed(item)).filter(Boolean)
          : [],
      }
      : { available: false, graphId: null, sourceDigest: null, snapshotStatus: 'not_persisted', nodeId: null, stepCount: null, downstreamNodeIds: [] },
    validation: {
      artifactTruthStatus: nullableTrimmed(jobInput.artifactTruthStatus),
      revisionValidationStatus: nullableTrimmed(revisionInput.validationStatus),
    },
    reproducibility: {
      status: nullableTrimmed(revisionInput.reproducibilityStatus),
      scriptAvailable: !!scriptSha256,
    },
    publicPhases: [...PUBLIC_EDIT_PHASES],
    capturedAt: nullableTrimmed(input.capturedAt) || new Date().toISOString(),
  };

  if (diagnostics.length > 0) {
    return { ok: false, diagnostics, envelope: null };
  }
  envelope.contextToken = computeContextToken(envelope);
  return { ok: true, diagnostics: [], envelope };
}

/**
 * 校验一个已经构造好的 Envelope 是否结构完整且 token 自洽。
 */
function validateResultStudioContextEnvelope(envelope) {
  const diagnostics = [];
  if (!envelope || typeof envelope !== 'object' || Array.isArray(envelope)) {
    return { ok: false, diagnostics: [diagnostic('context_envelope_missing', 'A Result Studio context envelope is required.')] };
  }
  if (envelope.contextVersion !== RESULT_STUDIO_CONTEXT_VERSION) {
    diagnostics.push(diagnostic('context_version_unsupported', 'Only Result Studio context envelope v1 is trusted.'));
  }
  for (const [path, message] of [
    ['projectId', 'projectId is required.'],
    ['artifact.artifactId', 'artifact.artifactId is required.'],
    ['job.toolJobId', 'job.toolJobId is required.'],
    ['revision.revisionId', 'revision.revisionId is required.'],
    ['script.sha256', 'script.sha256 is required.'],
  ]) {
    const value = path.split('.').reduce((acc, key) => (acc == null ? acc : acc[key]), envelope);
    if (!trimmed(value)) diagnostics.push(diagnostic('context_envelope_incomplete', message, { field: path }));
  }
  if (!trimmed(envelope.contextToken) || !SHA256_PATTERN.test(trimmed(envelope.contextToken))) {
    diagnostics.push(diagnostic('context_token_invalid', 'contextToken must be a lowercase sha256 digest.'));
  } else {
    const { contextToken, ...rest } = envelope;
    if (computeContextToken(rest) !== contextToken) {
      diagnostics.push(diagnostic('context_token_invalid', 'contextToken does not match the envelope contents.'));
    }
  }
  return { ok: diagnostics.length === 0, diagnostics };
}

/**
 * 服务端上下文闸门。
 *
 * 用于每一次 context-bound 写操作：模型带回来的 token 必须与当前真相
 * 重新投影出的 Envelope 一致，否则拒绝。这样"用户切了结果/结果被重算/
 * 选择被清空"之后的陈旧调用不会落到错误实体上。
 *
 * @param {object} params
 * @param {object} params.envelope 当前真相重新投影出的 Envelope
 * @param {string|null} params.presentedToken 模型/前端带来的 token
 * @param {boolean} [params.requireToken] 写操作必须带 token
 * @returns {{ ok: boolean, diagnostics: Array }}
 */
function authorizeContextOperation({ envelope, presentedToken = null, requireToken = true } = {}) {
  const structural = validateResultStudioContextEnvelope(envelope);
  if (!structural.ok) return structural;
  const token = trimmed(presentedToken);
  if (!token) {
    if (!requireToken) return { ok: true, diagnostics: [] };
    return {
      ok: false,
      diagnostics: [diagnostic('context_token_required', 'This operation requires the contextToken returned by result_studio_context.')],
    };
  }
  if (token !== envelope.contextToken) {
    return {
      ok: false,
      diagnostics: [diagnostic(
        'context_token_stale',
        'The current result, revision or selection changed after this context was captured; re-read result_studio_context and re-plan before retrying.'
      )],
    };
  }
  return { ok: true, diagnostics: [] };
}

/**
 * 给 Agent 的紧凑上下文视图。
 *
 * 有界：不含完整实体 ID 列表、绝对路径、URL 或结果值。
 */
function summarizeContextForAgent(envelope) {
  if (!envelope) return null;
  return {
    contextVersion: envelope.contextVersion,
    contextToken: envelope.contextToken || null,
    artifact: {
      name: envelope.artifact.name,
      kind: envelope.artifact.kind,
      entityType: envelope.artifact.entityType,
      interactionMode: envelope.artifact.interactionMode,
    },
    tool: envelope.job.toolId,
    revisionOrdinal: envelope.revision.revisionOrdinal,
    isCurrent: envelope.revision.isCurrent,
    validation: envelope.validation,
    reproducibility: envelope.reproducibility,
    selection: envelope.selection
      ? {
        entityType: envelope.selection.entityType,
        entityIdCount: envelope.selection.entityIdCount,
        truncated: envelope.selection.truncated,
        sampleEntityIds: envelope.selection.sampleEntityIds,
        hasFilter: envelope.selection.hasFilter,
        filterDescription: envelope.selection.filterDescription,
        fields: envelope.selection.fields,
        sort: envelope.selection.sort,
      }
      : null,
    selectionState: envelope.selectionState,
    editableParameters: envelope.plugin.editableParameters.map((item) => ({
      name: item.name,
      type: item.type,
      impact: item.impact,
    })),
    actions: envelope.plugin.actions,
    workflow: envelope.workflow,
    publicPhases: envelope.publicPhases,
  };
}

module.exports = {
  RESULT_STUDIO_CONTEXT_VERSION,
  PUBLIC_EDIT_PHASES,
  PUBLIC_EDIT_PHASE_LABELS,
  ENGINEERING_STAGE_TO_PUBLIC_PHASE,
  projectPublicEditPhase,
  computeContextToken,
  buildResultStudioContextEnvelope,
  validateResultStudioContextEnvelope,
  authorizeContextOperation,
  summarizeContextForAgent,
};

'use strict';

/**
 * shared-backend/result-studio-contracts.js
 *
 * G0-RS2 — Result Studio 的四个持久化契约与状态机。
 *
 * 契约：
 * - ChangeSet v1（原 ScientificChangeSet，BLOCK-83 D1 改名）  — 一次原子修改
 * - ArtifactRevision v1     — 一个产物版本
 * - SelectionContext v1     — 用户在结果上的结构化选择
 * - WorkspaceCheckpoint v1  — 可恢复的工作台状态
 *
 * 决策来源：docs/g0-rs0-result-studio-audit.md
 * - ADR-RS-1：Git 管文本版本，Artifact Truth 管科学有效性，SQLite 只做索引与投影。
 * - 审计缺陷 1：计划 §6.5 把 `validationStatus` 写成
 *   `valid|degraded|blocked|unavailable`，混了两套词汇。本模块拆成
 *   `validationStatus`（来自 reconcileArtifactTruth）与
 *   `reproducibilityStatus`（来自 delivery-manifest），不新造第三套词表。
 *
 * 不变量：
 * - 本模块只做结构与状态合法性判断，不判定科学有效性。
 *   `validationStatus` 必须由 `reconcileArtifactTruth()` 产出后传入，
 *   任何调用方都不得在这里"升级"一个结果的可信状态。
 * - 状态机只允许显式声明的迁移；`adopted` / `reverted` / `abandoned` 为终态。
 * - adopt / revert 幂等：对已处于目标终态的 ChangeSet 重复调用不报错、不改状态。
 */

const crypto = require('crypto');
const path = require('path');
const { stableStringify } = require('./canonical-json');

const RESULT_STUDIO_CONTRACT_VERSION = 1;

/** ChangeSet 生命周期。与计划 §6.4 一致。 */
const CHANGE_SET_STATUSES = Object.freeze([
  'draft',
  'running',
  'preview_ready',
  'validation_failed',
  'adopted',
  'reverted',
  'abandoned',
]);

/**
 * 允许的状态迁移。
 *
 * 说明：
 * - `validation_failed → draft` 允许重试同一个 ChangeSet（改参数再跑）。
 * - `adopted → reverted` 是"撤销已采用版本"。按计划 §7.4，撤销在 Git 上用**新
 *   commit** 表达，不改写已发布历史；这里只记录 ChangeSet 的终态流转。
 * - 终态不再外流，避免"部分采用"的混合状态。
 */
const CHANGE_SET_TRANSITIONS = Object.freeze({
  draft: Object.freeze(['running', 'abandoned']),
  running: Object.freeze(['preview_ready', 'validation_failed', 'abandoned']),
  preview_ready: Object.freeze(['adopted', 'reverted', 'abandoned']),
  validation_failed: Object.freeze(['draft', 'reverted', 'abandoned']),
  adopted: Object.freeze(['reverted']),
  reverted: Object.freeze([]),
  abandoned: Object.freeze([]),
});

/**
 * 完全关闭：不存在任何向外迁移。
 *
 * `adopted` 不在其中——撤销一次已采用的修改是真实的用户动作
 * （计划 §4.5 的 [撤销]），因此 `adopted → reverted` 合法。
 * 把 adopted 当成"完全关闭"会与迁移表自相矛盾。
 */
const CHANGE_SET_CLOSED_STATUSES = Object.freeze(['reverted', 'abandoned']);

/**
 * 已定局：不再处于进行中，不参与中断恢复扫描。
 * 包含 `adopted`，但它仍可被撤销。
 */
const CHANGE_SET_SETTLED_STATUSES = Object.freeze(['adopted', 'reverted', 'abandoned']);

/** 来自 reconcileArtifactTruth()。不含 `unavailable`。 */
const VALIDATION_STATUSES = Object.freeze(['valid', 'degraded', 'blocked']);

/** 来自 delivery-manifest 的 artifact 级 reproducibility。 */
const REPRODUCIBILITY_STATUSES = Object.freeze(['unavailable', 'available', 'verified']);
const SOURCE_SCRIPT_ORIGINS = Object.freeze(['canonical_plugin', 'execution_snapshot', 'project_materialized']);

const CHANGE_SET_ORIGINS = Object.freeze(['user', 'agent']);

const BINDING_PERSIST_MODES = Object.freeze(['managed', 'existing']);

/** 选择实体类型。允许插件扩展，因此校验只要求非空字符串。 */
const KNOWN_ENTITY_TYPES = Object.freeze([
  'row', 'column', 'gene', 'sample', 'feature', 'plot-mark', 'region',
]);

/**
 * 超过该数量的选择不再逐个持久化实体 ID，改为保留 filter + hash + 计数。
 * 计划 §6.2 要求 10 万行表格仍可用；把百万 ID 塞进会话既拖慢 UI 也污染 prompt。
 */
const MAX_PERSISTED_ENTITY_IDS = 2000;

const SHA256_PATTERN = /^[a-f0-9]{64}$/;
const COMMIT_PATTERN = /^[a-f0-9]{7,40}$/;

function sha256Hex(value) {
  return crypto.createHash('sha256').update(value).digest('hex');
}

function isNonEmptyString(value) {
  return typeof value === 'string' && value.trim() !== '';
}

function trimmed(value, fallback = '') {
  return typeof value === 'string' ? value.trim() : fallback;
}

function nullableTrimmed(value) {
  const normalized = trimmed(value);
  return normalized || null;
}

function stringArray(value) {
  if (!Array.isArray(value)) return [];
  return [...new Set(value.map((item) => trimmed(item)).filter(Boolean))];
}

/**
 * 受管理的相对路径校验：拒绝绝对路径、`..` 逃逸与 NUL。
 * 与 git-adapter 的 pathspec 校验同源，但这里作用于持久化记录。
 */
function isSafeRelativePath(value) {
  if (typeof value !== 'string' || value === '') return false;
  if (value.includes('\0')) return false;
  const normalized = value.replace(/\\/g, '/');
  if (normalized.startsWith('/') || /^[A-Za-z]:\//.test(normalized)) return false;
  if (normalized.split('/').includes('..')) return false;
  return path.posix.normalize(normalized) === normalized;
}

function fail(errors, code, message) {
  errors.push({ code, message });
}

// ---------------------------------------------------------------------------
// ChangeSet v1
// ---------------------------------------------------------------------------

/**
 * 规范化并校验一个 ChangeSet。
 *
 * @param {object} input
 * @returns {{ ok: boolean, errors: Array, changeSet: object|null }}
 */
function validateChangeSet(input) {
  const errors = [];
  if (!input || typeof input !== 'object' || Array.isArray(input)) {
    return { ok: false, errors: [{ code: 'change_set_invalid', message: 'ChangeSet must be an object.' }], changeSet: null };
  }

  const changeSetId = trimmed(input.changeSetId);
  const projectId = trimmed(input.projectId);
  const baseCommit = trimmed(input.baseCommit);
  const workingBranchRef = trimmed(input.workingBranchRef);
  const status = trimmed(input.status);
  const createdBy = trimmed(input.createdBy);

  if (!isNonEmptyString(changeSetId)) fail(errors, 'change_set_id_required', 'changeSetId is required.');
  if (!isNonEmptyString(projectId)) fail(errors, 'project_id_required', 'projectId is required.');
  if (!COMMIT_PATTERN.test(baseCommit)) fail(errors, 'base_commit_invalid', 'baseCommit must be a git object id.');
  if (!isNonEmptyString(workingBranchRef)) fail(errors, 'working_branch_required', 'workingBranchRef is required.');
  if (!CHANGE_SET_STATUSES.includes(status)) {
    fail(errors, 'status_invalid', `status must be one of: ${CHANGE_SET_STATUSES.join(', ')}.`);
  }
  if (!CHANGE_SET_ORIGINS.includes(createdBy)) {
    fail(errors, 'created_by_invalid', `createdBy must be one of: ${CHANGE_SET_ORIGINS.join(', ')}.`);
  }

  const candidateCommit = nullableTrimmed(input.candidateCommit);
  if (candidateCommit && !COMMIT_PATTERN.test(candidateCommit)) {
    fail(errors, 'candidate_commit_invalid', 'candidateCommit must be a git object id.');
  }
  // 已采用必须有不可变 candidate commit，否则"采用"无法恢复。
  if (status === 'adopted' && !candidateCommit) {
    fail(errors, 'adopted_requires_candidate_commit', 'An adopted ChangeSet requires candidateCommit.');
  }

  const changedPaths = [];
  const rawChangedPaths = Array.isArray(input.changedPaths) ? input.changedPaths : [];
  for (const entry of rawChangedPaths) {
    const relativePath = typeof entry === 'string' ? trimmed(entry) : trimmed(entry && entry.relativePath);
    if (!isSafeRelativePath(relativePath)) {
      fail(errors, 'changed_path_invalid', `changedPaths contains an unsafe path: ${relativePath || '<empty>'}`);
      continue;
    }
    const changeType = typeof entry === 'object' && entry ? trimmed(entry.changeType, 'modified') : 'modified';
    changedPaths.push({
      relativePath,
      changeType: ['added', 'modified', 'deleted', 'renamed'].includes(changeType) ? changeType : 'modified',
      beforeHash: typeof entry === 'object' && entry ? nullableTrimmed(entry.beforeHash) : null,
      afterHash: typeof entry === 'object' && entry ? nullableTrimmed(entry.afterHash) : null,
    });
  }

  const changeSet = {
    contractVersion: RESULT_STUDIO_CONTRACT_VERSION,
    changeSetId,
    projectId,
    conversationId: nullableTrimmed(input.conversationId),
    intentRef: nullableTrimmed(input.intentRef),
    baseCommit,
    candidateCommit,
    workingBranchRef,
    status,
    statusReason: nullableTrimmed(input.statusReason),
    changedPaths,
    parentArtifactRefs: stringArray(input.parentArtifactRefs),
    candidateArtifactRefs: stringArray(input.candidateArtifactRefs),
    jobRefs: stringArray(input.jobRefs),
    validationSummary: input.validationSummary && typeof input.validationSummary === 'object'
      ? input.validationSummary
      : null,
    createdBy,
    createdAt: nullableTrimmed(input.createdAt) || new Date().toISOString(),
    updatedAt: nullableTrimmed(input.updatedAt) || new Date().toISOString(),
    adoptedAt: nullableTrimmed(input.adoptedAt),
    revertedAt: nullableTrimmed(input.revertedAt),
  };

  return { ok: errors.length === 0, errors, changeSet: errors.length === 0 ? changeSet : null };
}

/**
 * 判断状态迁移是否合法。
 *
 * @returns {{ allowed: boolean, idempotent: boolean, reason: string|null }}
 */
function canTransitionChangeSet(from, to) {
  if (!CHANGE_SET_STATUSES.includes(from)) {
    return { allowed: false, idempotent: false, reason: 'unknown_source_status' };
  }
  if (!CHANGE_SET_STATUSES.includes(to)) {
    return { allowed: false, idempotent: false, reason: 'unknown_target_status' };
  }
  // 幂等：重复 adopt 一个已 adopted、或重复 revert 一个已 reverted 的 ChangeSet
  // 不是错误，调用方按同一结果返回。
  if (from === to) {
    return { allowed: true, idempotent: true, reason: null };
  }
  const allowed = CHANGE_SET_TRANSITIONS[from].includes(to);
  return {
    allowed,
    idempotent: false,
    reason: allowed ? null : 'transition_forbidden',
  };
}

// ---------------------------------------------------------------------------
// ArtifactRevision v1
// ---------------------------------------------------------------------------

/**
 * 规范化并校验一个 ArtifactRevision。
 *
 * 重要：`validationStatus` 必须来自 `reconcileArtifactTruth()`，
 * `reproducibilityStatus` 必须来自 delivery-manifest 的 artifact 级判定。
 * 本函数不推导、不放宽这两个字段。
 */
function validateArtifactRevision(input) {
  const errors = [];
  if (!input || typeof input !== 'object' || Array.isArray(input)) {
    return { ok: false, errors: [{ code: 'revision_invalid', message: 'Revision must be an object.' }], revision: null };
  }

  const revisionId = trimmed(input.revisionId);
  const projectId = trimmed(input.projectId);
  const artifactFamilyId = trimmed(input.artifactFamilyId);
  const artifactId = trimmed(input.artifactId);
  const changeSetId = trimmed(input.changeSetId);
  const outputPath = trimmed(input.outputPath);
  const validationStatus = trimmed(input.validationStatus);
  const reproducibilityStatus = trimmed(input.reproducibilityStatus, 'unavailable');

  if (!isNonEmptyString(revisionId)) fail(errors, 'revision_id_required', 'revisionId is required.');
  if (!isNonEmptyString(projectId)) fail(errors, 'project_id_required', 'projectId is required.');
  if (!isNonEmptyString(artifactFamilyId)) fail(errors, 'artifact_family_required', 'artifactFamilyId is required.');
  if (!isNonEmptyString(artifactId)) fail(errors, 'artifact_id_required', 'artifactId is required.');
  if (!isNonEmptyString(changeSetId)) fail(errors, 'change_set_id_required', 'changeSetId is required.');
  if (!isSafeRelativePath(outputPath)) {
    fail(errors, 'output_path_invalid', 'outputPath must be a safe project-relative path.');
  }
  if (!VALIDATION_STATUSES.includes(validationStatus)) {
    fail(errors, 'validation_status_invalid',
      `validationStatus must come from artifact truth (${VALIDATION_STATUSES.join(', ')}); "unavailable" belongs to reproducibilityStatus.`);
  }
  if (!REPRODUCIBILITY_STATUSES.includes(reproducibilityStatus)) {
    fail(errors, 'reproducibility_status_invalid',
      `reproducibilityStatus must be one of: ${REPRODUCIBILITY_STATUSES.join(', ')}.`);
  }

  const outputHash = nullableTrimmed(input.outputHash);
  if (outputHash && !SHA256_PATTERN.test(outputHash)) {
    fail(errors, 'output_hash_invalid', 'outputHash must be a lowercase sha256 hex digest.');
  }
  const sourceCommit = nullableTrimmed(input.sourceCommit);
  if (sourceCommit && !COMMIT_PATTERN.test(sourceCommit)) {
    fail(errors, 'source_commit_invalid', 'sourceCommit must be a git object id.');
  }

  // 一个 valid 版本必须能说明它是怎么来的，否则无法复现也无法比较。
  if (validationStatus === 'valid' && !input.toolJobId) {
    fail(errors, 'valid_revision_requires_job', 'A valid revision must reference the tool_job that produced it.');
  }
  // verified 强于 available：必须已有脚本与输出哈希才能声称已验证复现。
  if (reproducibilityStatus === 'verified' && !outputHash) {
    fail(errors, 'verified_requires_output_hash', 'A verified revision requires outputHash.');
  }

  const inputArtifactRefs = [];
  for (const entry of Array.isArray(input.inputArtifactRefs) ? input.inputArtifactRefs : []) {
    if (!entry || typeof entry !== 'object') continue;
    const refId = trimmed(entry.artifactId);
    const hash = nullableTrimmed(entry.hash);
    if (!refId) {
      fail(errors, 'input_ref_invalid', 'inputArtifactRefs entries require artifactId.');
      continue;
    }
    if (hash && !SHA256_PATTERN.test(hash)) {
      fail(errors, 'input_ref_hash_invalid', `inputArtifactRefs hash must be sha256: ${refId}`);
      continue;
    }
    inputArtifactRefs.push({ artifactId: refId, hash, role: nullableTrimmed(entry.role) });
  }

  const revisionOrdinal = Number(input.revisionOrdinal);
  if (!Number.isInteger(revisionOrdinal) || revisionOrdinal < 1) {
    fail(errors, 'revision_ordinal_invalid', 'revisionOrdinal must be a positive integer.');
  }

  let sourceScriptRef = null;
  if (input.sourceScriptRef && typeof input.sourceScriptRef === 'object') {
    sourceScriptRef = {
      relativePath: nullableTrimmed(input.sourceScriptRef.relativePath),
      sha256: nullableTrimmed(input.sourceScriptRef.sha256),
      entryPoint: nullableTrimmed(input.sourceScriptRef.entryPoint),
      artifactId: nullableTrimmed(input.sourceScriptRef.artifactId),
      rendererId: nullableTrimmed(input.sourceScriptRef.rendererId),
      language: nullableTrimmed(input.sourceScriptRef.language),
      origin: nullableTrimmed(input.sourceScriptRef.origin),
    };
    if (sourceScriptRef.relativePath && !isSafeRelativePath(sourceScriptRef.relativePath)) {
      fail(errors, 'source_script_path_invalid', 'sourceScriptRef.relativePath must be project-relative and path-safe.');
    }
    if (sourceScriptRef.sha256 && !SHA256_PATTERN.test(sourceScriptRef.sha256)) {
      fail(errors, 'source_script_hash_invalid', 'sourceScriptRef.sha256 must be a lowercase sha256 digest.');
    }
    if (sourceScriptRef.artifactId && sourceScriptRef.artifactId !== artifactId) {
      fail(errors, 'source_script_artifact_mismatch', 'sourceScriptRef.artifactId must match the revision artifactId.');
    }
    if (sourceScriptRef.origin && !SOURCE_SCRIPT_ORIGINS.includes(sourceScriptRef.origin)) {
      fail(errors, 'source_script_origin_invalid', `sourceScriptRef.origin must be one of: ${SOURCE_SCRIPT_ORIGINS.join(', ')}.`);
    }
    if (sourceScriptRef.origin === 'project_materialized'
      && (!sourceScriptRef.relativePath || !sourceScriptRef.sha256 || !sourceScriptRef.artifactId || !sourceScriptRef.rendererId)) {
      fail(errors, 'materialized_script_ref_incomplete', 'A project-materialized sourceScriptRef requires path, hash, artifactId and rendererId.');
    }
  }

  const revision = {
    contractVersion: RESULT_STUDIO_CONTRACT_VERSION,
    revisionId,
    projectId,
    artifactFamilyId,
    artifactId,
    parentRevisionIds: stringArray(input.parentRevisionIds),
    sourceCommit,
    sourceScriptRef,
    inputArtifactRefs,
    parametersRef: nullableTrimmed(input.parametersRef),
    parametersHash: nullableTrimmed(input.parametersHash),
    toolJobId: nullableTrimmed(input.toolJobId),
    outputPath,
    outputHash,
    validationStatus,
    reproducibilityStatus,
    changeSetId,
    revisionOrdinal: Number.isInteger(revisionOrdinal) && revisionOrdinal >= 1 ? revisionOrdinal : 1,
    isCurrent: input.isCurrent === true,
    createdAt: nullableTrimmed(input.createdAt) || new Date().toISOString(),
  };

  if (revision.parametersRef && !isSafeRelativePath(revision.parametersRef)) {
    fail(errors, 'parameters_path_invalid', 'parametersRef must be project-relative and path-safe.');
  }
  if (revision.parametersHash && !SHA256_PATTERN.test(revision.parametersHash)) {
    fail(errors, 'parameters_hash_invalid', 'parametersHash must be a lowercase sha256 digest.');
  }
  if ((revision.parametersRef && !revision.parametersHash) || (!revision.parametersRef && revision.parametersHash)) {
    fail(errors, 'parameters_ref_incomplete', 'parametersRef and parametersHash must be provided together.');
  }

  return { ok: errors.length === 0, errors, revision: errors.length === 0 ? revision : null };
}

// ---------------------------------------------------------------------------
// SelectionContext v1
// ---------------------------------------------------------------------------

/**
 * 规范化并校验一个 SelectionContext。
 *
 * 大型选择不逐个持久化 ID：超过 MAX_PERSISTED_ENTITY_IDS 时保留
 * filter + 计数 + 全量 ID 的稳定 hash，并标记 truncated。
 * 这样 Agent 上下文拿到的是有界摘要，但仍能校验选择是否变化。
 */
function validateSelectionContext(input) {
  const errors = [];
  if (!input || typeof input !== 'object' || Array.isArray(input)) {
    return { ok: false, errors: [{ code: 'selection_invalid', message: 'Selection must be an object.' }], selection: null };
  }

  const selectionId = trimmed(input.selectionId);
  const projectId = trimmed(input.projectId);
  const artifactId = trimmed(input.artifactId);
  const entityType = trimmed(input.entityType);

  if (!isNonEmptyString(selectionId)) fail(errors, 'selection_id_required', 'selectionId is required.');
  if (!isNonEmptyString(projectId)) fail(errors, 'project_id_required', 'projectId is required.');
  if (!isNonEmptyString(artifactId)) fail(errors, 'artifact_id_required', 'artifactId is required.');
  if (!isNonEmptyString(entityType)) fail(errors, 'entity_type_required', 'entityType is required.');

  const allEntityIds = stringArray(input.entityIds);
  const suppliedCount = Number(input.entityIdCount);
  const authoritativeCount = Number.isInteger(suppliedCount) && suppliedCount >= allEntityIds.length
    ? suppliedCount
    : allEntityIds.length;
  const suppliedHash = nullableTrimmed(input.entityIdsHash);
  const filterHash = nullableTrimmed(input.filterHash);
  const explicitIdsHash = allEntityIds.length > 0
    ? sha256Hex(stableStringify([...allEntityIds].sort()))
    : null;
  const queryBacked = authoritativeCount > allEntityIds.length;

  if (suppliedHash && !SHA256_PATTERN.test(suppliedHash)) {
    fail(errors, 'entity_ids_hash_invalid', 'entityIdsHash must be a lowercase sha256 digest.');
  }
  if (filterHash && !SHA256_PATTERN.test(filterHash)) {
    fail(errors, 'filter_hash_invalid', 'filterHash must be a lowercase sha256 digest.');
  }
  if (queryBacked && !input.filterExpression) {
    fail(errors, 'query_selection_requires_filter', 'A query-backed selection requires filterExpression.');
  }
  if (queryBacked && (!suppliedHash || !filterHash)) {
    fail(errors, 'query_selection_requires_evidence', 'A query-backed selection requires entityIdsHash and filterHash.');
  }
  if (!queryBacked && suppliedHash && explicitIdsHash && suppliedHash !== explicitIdsHash) {
    fail(errors, 'entity_ids_hash_mismatch', 'entityIdsHash does not match the explicit entity ID set.');
  }

  const truncated = authoritativeCount > MAX_PERSISTED_ENTITY_IDS || queryBacked;
  const persistedEntityIds = truncated ? allEntityIds.slice(0, MAX_PERSISTED_ENTITY_IDS) : allEntityIds;
  // Query 选择的全量 hash 由权威表查询器计算；显式小选择则在这里重算，
  // 永不信任浏览器为显式 ID 集合自报的摘要。
  const entityIdsHash = queryBacked ? suppliedHash : explicitIdsHash;

  if (truncated && !input.filterExpression) {
    // 没有 filter 就无法在截断后重建完整选择 → 选择将不可复现。
    fail(errors, 'large_selection_requires_filter',
      `A selection larger than ${MAX_PERSISTED_ENTITY_IDS} entities requires filterExpression to stay reproducible.`);
  }

  const selection = {
    contractVersion: RESULT_STUDIO_CONTRACT_VERSION,
    selectionId,
    projectId,
    conversationId: nullableTrimmed(input.conversationId),
    artifactId,
    revisionId: nullableTrimmed(input.revisionId),
    entityType,
    entityIds: persistedEntityIds,
    entityIdCount: authoritativeCount,
    entityIdsTruncated: truncated,
    entityIdsHash,
    filterHash,
    filterExpression: input.filterExpression && typeof input.filterExpression === 'object' ? input.filterExpression : null,
    sort: Array.isArray(input.sort)
      ? input.sort
        .filter((item) => item && isNonEmptyString(item.field))
        .map((item) => ({ field: trimmed(item.field), direction: item.direction === 'desc' ? 'desc' : 'asc' }))
      : [],
    viewport: input.viewport && typeof input.viewport === 'object' ? input.viewport : null,
    displayState: input.displayState && typeof input.displayState === 'object' ? input.displayState : null,
    createdAt: nullableTrimmed(input.createdAt) || new Date().toISOString(),
    updatedAt: nullableTrimmed(input.updatedAt) || new Date().toISOString(),
  };

  return { ok: errors.length === 0, errors, selection: errors.length === 0 ? selection : null };
}

/**
 * 判断一个持久 SelectionContext 是否仍能用于当前 Artifact/Revision。
 *
 * - compatible：同一 Revision，或跨 Revision 但权威 filter/entity hash 完全一致；
 * - stale：Artifact 相同但 Revision/内容证据发生变化，可展示、不可自动交给 Agent；
 * - invalid：跨项目/跨 Artifact、缺稳定身份或选择本身不可持久。
 */
function assessSelectionCompatibility({
  selection,
  projectId,
  artifactId,
  revisionId = null,
  entityIdsHash = null,
  filterHash = null,
  selectionDurable = true,
} = {}) {
  if (!selection || typeof selection !== 'object') {
    return { status: 'invalid', reason: 'selection_missing' };
  }
  if (selection.projectId !== projectId) {
    return { status: 'invalid', reason: 'project_mismatch' };
  }
  if (selection.artifactId !== artifactId) {
    return { status: 'invalid', reason: 'artifact_mismatch' };
  }
  if (!selectionDurable || selection.displayState?.durable === false) {
    return { status: 'invalid', reason: 'selection_not_durable' };
  }
  const hasIdentity = selection.entityIdCount > 0
    ? SHA256_PATTERN.test(selection.entityIdsHash || '')
    : Array.isArray(selection.displayState?.fields) && selection.displayState.fields.length > 0;
  if (!hasIdentity) return { status: 'invalid', reason: 'selection_identity_missing' };

  const sameRevision = (selection.revisionId || null) === (revisionId || null);
  const entityMatches = !entityIdsHash || selection.entityIdsHash === entityIdsHash;
  const filterMatches = !selection.filterHash || !filterHash || selection.filterHash === filterHash;
  if (sameRevision && entityMatches && filterMatches) {
    return { status: 'compatible', reason: 'same_revision' };
  }
  if (!sameRevision
      && entityIdsHash && selection.entityIdsHash === entityIdsHash
      && (!selection.filterHash || (filterHash && selection.filterHash === filterHash))) {
    return { status: 'compatible', reason: 'equivalent_entity_evidence' };
  }
  return {
    status: 'stale',
    reason: sameRevision ? 'selection_evidence_changed' : 'revision_changed',
  };
}

/**
 * 供 Agent 上下文使用的紧凑摘要。永不返回完整 ID 列表。
 */
function summarizeSelection(selection, { maxSampleIds = 12 } = {}) {
  if (!selection) return null;
  return {
    selectionId: selection.selectionId,
    artifactId: selection.artifactId,
    revisionId: selection.revisionId || null,
    entityType: selection.entityType,
    entityIdCount: selection.entityIdCount,
    truncated: selection.entityIdsTruncated === true,
    sampleEntityIds: (selection.entityIds || []).slice(0, maxSampleIds),
    entityIdsHash: selection.entityIdsHash || null,
    filterHash: selection.filterHash || null,
    hasFilter: !!selection.filterExpression,
    sort: selection.sort || [],
  };
}

// ---------------------------------------------------------------------------
// WorkspaceCheckpoint v1
// ---------------------------------------------------------------------------

/**
 * 计算 checkpoint 的稳定 hash。恢复时用它与 Git / SQLite / Artifact 三方核对。
 */
function computeCheckpointHash(checkpoint) {
  return sha256Hex(stableStringify({
    projectId: checkpoint.projectId,
    conversationId: checkpoint.conversationId,
    baseCommit: checkpoint.baseCommit,
    candidateCommit: checkpoint.candidateCommit,
    changeSetId: checkpoint.changeSetId,
    changeSetStatus: checkpoint.changeSetStatus,
    currentRevisionIds: checkpoint.currentRevisionIds,
    selectionId: checkpoint.selectionId,
    pendingPreview: checkpoint.pendingPreview,
    jobRefs: checkpoint.jobRefs,
    loopRefs: checkpoint.loopRefs,
  }));
}

function validateWorkspaceCheckpoint(input) {
  const errors = [];
  if (!input || typeof input !== 'object' || Array.isArray(input)) {
    return { ok: false, errors: [{ code: 'checkpoint_invalid', message: 'Checkpoint must be an object.' }], checkpoint: null };
  }

  const checkpointId = trimmed(input.checkpointId);
  const projectId = trimmed(input.projectId);
  if (!isNonEmptyString(checkpointId)) fail(errors, 'checkpoint_id_required', 'checkpointId is required.');
  if (!isNonEmptyString(projectId)) fail(errors, 'project_id_required', 'projectId is required.');

  const changeSetStatus = nullableTrimmed(input.changeSetStatus);
  if (changeSetStatus && !CHANGE_SET_STATUSES.includes(changeSetStatus)) {
    fail(errors, 'checkpoint_status_invalid', 'changeSetStatus must be a known ChangeSet status.');
  }

  const base = {
    contractVersion: RESULT_STUDIO_CONTRACT_VERSION,
    checkpointId,
    projectId,
    conversationId: nullableTrimmed(input.conversationId),
    baseCommit: nullableTrimmed(input.baseCommit),
    candidateCommit: nullableTrimmed(input.candidateCommit),
    changeSetId: nullableTrimmed(input.changeSetId),
    changeSetStatus,
    currentRevisionIds: stringArray(input.currentRevisionIds),
    selectionId: nullableTrimmed(input.selectionId),
    pendingPreview: input.pendingPreview && typeof input.pendingPreview === 'object' ? input.pendingPreview : null,
    jobRefs: stringArray(input.jobRefs),
    loopRefs: stringArray(input.loopRefs),
    createdAt: nullableTrimmed(input.createdAt) || new Date().toISOString(),
    updatedAt: nullableTrimmed(input.updatedAt) || new Date().toISOString(),
  };

  const checkpoint = { ...base, checkpointHash: computeCheckpointHash(base) };
  return { ok: errors.length === 0, errors, checkpoint: errors.length === 0 ? checkpoint : null };
}

/**
 * 恢复时的三方一致性判定。
 *
 * 不自动"修复"漂移：只分类并给出可解释状态，由上层决定阻断或重建。
 * 计划 §3.2：软件异常退出不能留下"部分采用"的混合状态。
 */
function assessCheckpointConsistency({ checkpoint, gitHeadCommit, changeSetStatus, currentRevisionIds } = {}) {
  if (!checkpoint) {
    return { status: 'unavailable', drift: [], recoverable: false };
  }
  const drift = [];
  if (checkpoint.changeSetId && changeSetStatus && checkpoint.changeSetStatus !== changeSetStatus) {
    drift.push({
      kind: 'change_set_status_drift',
      expected: checkpoint.changeSetStatus,
      actual: changeSetStatus,
    });
  }
  if (checkpoint.candidateCommit && gitHeadCommit && !gitHeadCommit.startsWith(checkpoint.candidateCommit)
    && !checkpoint.candidateCommit.startsWith(gitHeadCommit)) {
    drift.push({ kind: 'git_commit_drift', expected: checkpoint.candidateCommit, actual: gitHeadCommit });
  }
  if (Array.isArray(currentRevisionIds)) {
    const expected = [...checkpoint.currentRevisionIds].sort();
    const actual = [...stringArray(currentRevisionIds)].sort();
    if (stableStringify(expected) !== stableStringify(actual)) {
      drift.push({ kind: 'revision_set_drift', expected, actual });
    }
  }
  // 采用中途崩溃的特征：checkpoint 记着 adopted，但 ChangeSet 仍停在 running。
  const partialAdopt = checkpoint.changeSetStatus === 'adopted' && changeSetStatus === 'running';
  return {
    status: drift.length === 0 ? 'consistent' : partialAdopt ? 'partial_adopt_detected' : 'drifted',
    drift,
    recoverable: !partialAdopt,
  };
}

module.exports = {
  RESULT_STUDIO_CONTRACT_VERSION,
  CHANGE_SET_STATUSES,
  CHANGE_SET_TRANSITIONS,
  CHANGE_SET_CLOSED_STATUSES,
  CHANGE_SET_SETTLED_STATUSES,
  CHANGE_SET_ORIGINS,
  VALIDATION_STATUSES,
  REPRODUCIBILITY_STATUSES,
  SOURCE_SCRIPT_ORIGINS,
  BINDING_PERSIST_MODES,
  KNOWN_ENTITY_TYPES,
  MAX_PERSISTED_ENTITY_IDS,
  sha256Hex,
  isSafeRelativePath,
  validateChangeSet,
  // BLOCK-83 D1 兼容别名（一版后移除）：
  validateScientificChangeSet: validateChangeSet,
  canTransitionChangeSet,
  validateArtifactRevision,
  validateSelectionContext,
  assessSelectionCompatibility,
  summarizeSelection,
  computeCheckpointHash,
  validateWorkspaceCheckpoint,
  assessCheckpointConsistency,
};

'use strict';

const crypto = require('node:crypto');
const fs = require('node:fs');
const path = require('node:path');

const BUNDLE_SCHEMA_VERSION = 1;
const FACT_PACKAGE_SCHEMA_VERSION = 1;
const SHA256 = /^[a-f0-9]{64}$/;
const COMMIT = /^[a-f0-9]{40}$/;

const REQUIRED_FACT_ROLES = Object.freeze([
  'conversation.record',
  'ui.open_artifact',
  'ui.selection_or_manual_edit',
  'environment.repository',
  'agent.context_envelope',
  'provider.result_tool_roundtrip',
  'sqlite.intent',
  'sqlite.changeset',
  'git.changeset',
  'sqlite.job',
  'artifact.formal_output_cohort',
  'validator.cohort',
  'sqlite.candidate_revision_cohort',
  'git.candidate_revision_cohort',
  'ui.compare',
  'sqlite.lifecycle',
  'git.lifecycle',
  'restart.reopen',
  'replay.exact',
]);
const DERIVED_INVARIANTS = Object.freeze([
  'source_data_preserved',
  'artifact_history_preserved',
  'unrelated_git_wip_preserved',
  'no_false_success',
  'no_partial_adopt',
  'no_silent_loss',
  'independent_replayable_scripts',
]);

function sha256Bytes(value) {
  return crypto.createHash('sha256').update(value).digest('hex');
}

function stable(value) {
  if (Array.isArray(value)) return value.map(stable);
  if (!value || typeof value !== 'object') return value;
  return Object.fromEntries(Object.keys(value).sort().map((key) => [key, stable(value[key])]));
}

function stableHash(value) {
  return sha256Bytes(Buffer.from(JSON.stringify(stable(value))));
}

function withoutKey(value, key) {
  return Object.fromEntries(Object.entries(value || {}).filter(([name]) => name !== key));
}

function sortedUniqueStrings(value) {
  if (!Array.isArray(value) || value.some((item) => typeof item !== 'string' || item.length === 0)) return null;
  const result = [...new Set(value)].sort();
  return result.length === value.length ? result : null;
}

function sameStringSet(left, right) {
  const a = sortedUniqueStrings(left);
  const b = sortedUniqueStrings(right);
  return Boolean(a && b && JSON.stringify(a) === JSON.stringify(b));
}

function addIssue(issues, condition, code) {
  if (!condition) issues.push(code);
}

function inspectPrivateProjection(value, issues, location = '$') {
  if (Array.isArray(value)) {
    value.forEach((item, index) => inspectPrivateProjection(item, issues, `${location}[${index}]`));
    return;
  }
  if (value && typeof value === 'object') {
    for (const [key, item] of Object.entries(value)) {
      if (/^(?:api_?key|authorization|credential|bearer|raw_?request|raw_?response|endpoint_?url)$/i.test(key)) {
        issues.push(`private_projection_forbidden_key:${location}.${key}`);
      }
      inspectPrivateProjection(item, issues, `${location}.${key}`);
    }
    return;
  }
  if (typeof value !== 'string') return;
  if (/https?:\/\//i.test(value) || /Bearer\s+/i.test(value) || /sk-[A-Za-z0-9]{12,}/.test(value)
      || /\/Users\/[^/]+\//.test(value) || /\/home\/[^/]+\//.test(value)) {
    issues.push(`private_projection_forbidden_value:${location}`);
  }
}

function isSafeRelativePath(value) {
  const text = String(value || '');
  if (!text || text.length > 512 || text.includes('\0') || text.includes('\\')) return false;
  if (path.posix.isAbsolute(text) || /^[A-Za-z]:\//.test(text)) return false;
  const normalized = path.posix.normalize(text);
  return normalized === text && normalized !== '..' && !normalized.startsWith('../');
}

function walkFiles(root, relative = '') {
  const directory = path.join(root, relative);
  const files = [];
  for (const entry of fs.readdirSync(directory, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name))) {
    const child = relative ? `${relative}/${entry.name}` : entry.name;
    if (entry.isSymbolicLink()) throw new Error(`p7_evidence_symlink_forbidden:${child}`);
    if (entry.isDirectory()) files.push(...walkFiles(root, child));
    else if (entry.isFile()) files.push(child);
    else throw new Error(`p7_evidence_special_file_forbidden:${child}`);
  }
  return files;
}

function buildBundleManifest(root, { exclude = ['manifest.json'] } = {}) {
  const excluded = new Set(exclude);
  const files = walkFiles(root).filter((relative) => !excluded.has(relative)).map((relative) => {
    const bytes = fs.readFileSync(path.join(root, relative));
    return { path: relative, sha256: sha256Bytes(bytes), bytes: bytes.length };
  });
  return {
    schemaVersion: BUNDLE_SCHEMA_VERSION,
    files,
    bundleDigest: stableHash(files),
  };
}

function verifyBundleManifest(root, manifest) {
  const issues = [];
  if (!manifest || manifest.schemaVersion !== BUNDLE_SCHEMA_VERSION) issues.push('bundle_schema_version_invalid');
  const declared = Array.isArray(manifest?.files) ? manifest.files : [];
  const paths = declared.map((entry) => entry?.path).filter(Boolean);
  if (paths.length !== declared.length || paths.length !== new Set(paths).size) issues.push('bundle_paths_invalid_or_duplicate');
  for (const entry of declared) {
    if (!isSafeRelativePath(entry?.path)) {
      issues.push(`bundle_path_unsafe:${entry?.path || ''}`);
      continue;
    }
    const absolute = path.join(root, entry.path);
    let stat;
    try { stat = fs.lstatSync(absolute); } catch { issues.push(`bundle_file_missing:${entry.path}`); continue; }
    if (!stat.isFile() || stat.isSymbolicLink()) {
      issues.push(`bundle_file_not_regular:${entry.path}`);
      continue;
    }
    const bytes = fs.readFileSync(absolute);
    if (!SHA256.test(String(entry.sha256 || '')) || sha256Bytes(bytes) !== entry.sha256) {
      issues.push(`bundle_file_hash_mismatch:${entry.path}`);
    }
    if (!Number.isInteger(entry.bytes) || entry.bytes !== bytes.length) issues.push(`bundle_file_size_mismatch:${entry.path}`);
  }
  let actual = [];
  try { actual = walkFiles(root).filter((relative) => relative !== 'manifest.json'); } catch (error) {
    issues.push(error.message);
  }
  if (JSON.stringify([...paths].sort()) !== JSON.stringify(actual.sort())) issues.push('bundle_file_set_mismatch');
  if (!SHA256.test(String(manifest?.bundleDigest || '')) || stableHash(declared) !== manifest.bundleDigest) {
    issues.push('bundle_digest_mismatch');
  }
  return { valid: issues.length === 0, issues: [...new Set(issues)] };
}

function decodePointerToken(value) {
  return value.replaceAll('~1', '/').replaceAll('~0', '~');
}

function resolveJsonPointer(value, pointer) {
  if (pointer === '') return value;
  if (!pointer.startsWith('/')) throw new Error('p7_evidence_json_pointer_invalid');
  let current = value;
  for (const raw of pointer.slice(1).split('/')) {
    const token = decodePointerToken(raw);
    if (!current || typeof current !== 'object' || !Object.prototype.hasOwnProperty.call(current, token)) {
      throw new Error('p7_evidence_json_pointer_missing');
    }
    current = current[token];
  }
  return current;
}

function resolveEvidenceRef(root, sourceRef) {
  const raw = String(sourceRef || '');
  const separator = raw.indexOf('#');
  const relative = separator === -1 ? raw : raw.slice(0, separator);
  const pointer = separator === -1 ? null : raw.slice(separator + 1);
  if (!isSafeRelativePath(relative)) throw new Error('p7_evidence_ref_unsafe');
  const absolute = path.join(root, relative);
  const stat = fs.lstatSync(absolute);
  if (!stat.isFile() || stat.isSymbolicLink()) throw new Error('p7_evidence_ref_not_regular');
  const bytes = fs.readFileSync(absolute);
  if (pointer == null) return { relative, bytes, value: null, digest: sha256Bytes(bytes) };
  if (path.extname(relative).toLowerCase() !== '.json') throw new Error('p7_evidence_pointer_requires_json');
  const value = resolveJsonPointer(JSON.parse(bytes.toString('utf8')), pointer);
  return { relative, bytes, value, digest: stableHash(value) };
}

function parsePngSize(bytes) {
  const buffer = Buffer.from(bytes || []);
  if (buffer.length < 24 || !buffer.subarray(0, 8).equals(Buffer.from('89504e470d0a1a0a', 'hex'))
      || buffer.subarray(12, 16).toString('ascii') !== 'IHDR') {
    throw new Error('p7_evidence_png_invalid');
  }
  const width = buffer.readUInt32BE(16);
  const height = buffer.readUInt32BE(20);
  if (width <= 0 || height <= 0) throw new Error('p7_evidence_png_dimensions_invalid');
  return { width, height };
}

function validateFactPackage(value) {
  const issues = [];
  const factPackage = value && typeof value === 'object' && !Array.isArray(value) ? value : {};
  addIssue(issues, factPackage.schemaVersion === FACT_PACKAGE_SCHEMA_VERSION, 'fact_package_schema_version_invalid');
  addIssue(issues, typeof factPackage.packageId === 'string' && factPackage.packageId.length >= 8,
    'fact_package_id_invalid');
  addIssue(issues, typeof factPackage.journeyId === 'string' && factPackage.journeyId.length >= 8,
    'fact_package_journey_id_invalid');
  addIssue(issues, typeof factPackage.taskId === 'string' && factPackage.taskId.length >= 8,
    'fact_package_task_id_invalid');
  addIssue(issues, SHA256.test(String(factPackage.projectRefHash || '')), 'fact_package_project_ref_invalid');
  addIssue(issues, SHA256.test(String(factPackage.conversationRefHash || '')), 'fact_package_conversation_ref_invalid');
  addIssue(issues, SHA256.test(String(factPackage.primaryOperationDigest || '')),
    'fact_package_primary_operation_invalid');
  const startedAt = Date.parse(factPackage.startedAt || '');
  const completedAt = Date.parse(factPackage.completedAt || '');
  addIssue(issues, Number.isFinite(startedAt), 'fact_package_started_at_invalid');
  addIssue(issues, Number.isFinite(completedAt) && completedAt >= startedAt, 'fact_package_completed_at_invalid');

  const facts = factPackage.facts && typeof factPackage.facts === 'object' && !Array.isArray(factPackage.facts)
    ? factPackage.facts : {};
  const roles = new Map();
  for (const [id, fact] of Object.entries(facts)) {
    if (!fact || typeof fact !== 'object' || Array.isArray(fact)) {
      issues.push(`fact_not_object:${id}`);
      continue;
    }
    addIssue(issues, fact.id === id, `fact_id_mismatch:${id}`);
    addIssue(issues, typeof fact.kind === 'string' && fact.kind.length > 0, `fact_kind_invalid:${id}`);
    addIssue(issues, typeof fact.role === 'string' && fact.role.length > 0, `fact_role_invalid:${id}`);
    addIssue(issues, fact.taskId === factPackage.taskId, `fact_task_scope_mismatch:${id}`);
    addIssue(issues, fact.journeyId === factPackage.journeyId, `fact_journey_scope_mismatch:${id}`);
    addIssue(issues, fact.scopeDigest === factPackage.primaryOperationDigest, `fact_operation_scope_mismatch:${id}`);
    const observedAt = Date.parse(fact.observedAt || '');
    addIssue(issues, Number.isFinite(observedAt) && observedAt >= startedAt && observedAt <= completedAt,
      `fact_observed_at_outside_package:${id}`);
    addIssue(issues, fact.payload && typeof fact.payload === 'object' && !Array.isArray(fact.payload),
      `fact_payload_invalid:${id}`);
    if (typeof fact.role === 'string') {
      if (roles.has(fact.role)) issues.push(`fact_role_duplicate:${fact.role}`);
      else roles.set(fact.role, fact);
    }
  }
  for (const role of REQUIRED_FACT_ROLES) if (!roles.has(role)) issues.push(`fact_role_missing:${role}`);

  const context = roles.get('agent.context_envelope')?.payload || {};
  const repository = roles.get('environment.repository')?.payload || {};
  const provider = roles.get('provider.result_tool_roundtrip')?.payload || {};
  const intent = roles.get('sqlite.intent')?.payload || {};
  const changeSet = roles.get('sqlite.changeset')?.payload || {};
  const gitChangeSet = roles.get('git.changeset')?.payload || {};
  const jobCohort = roles.get('sqlite.job')?.payload || {};
  const jobs = Array.isArray(jobCohort.jobs) ? jobCohort.jobs : [];
  const artifact = roles.get('artifact.formal_output_cohort')?.payload || {};
  const validator = roles.get('validator.cohort')?.payload || {};
  const revisions = roles.get('sqlite.candidate_revision_cohort')?.payload || {};
  const gitRevisions = roles.get('git.candidate_revision_cohort')?.payload || {};
  const compare = roles.get('ui.compare')?.payload || {};
  const lifecycle = roles.get('sqlite.lifecycle')?.payload || {};
  const gitLifecycle = roles.get('git.lifecycle')?.payload || {};
  const restart = roles.get('restart.reopen')?.payload || {};
  const replay = roles.get('replay.exact')?.payload || {};

  addIssue(issues, ['managed', 'existing'].includes(repository.mode)
    && ['non_git', 'clean', 'dirty'].includes(repository.initialState)
    && (repository.mode !== 'existing' || repository.consentObserved === true)
    && SHA256.test(String(repository.snapshotBefore || ''))
    && repository.snapshotAfter === repository.snapshotBefore,
  'fact_repository_environment_invalid');
  addIssue(issues, SHA256.test(String(context.contextRef || ''))
    && SHA256.test(String(context.selectionRef || ''))
    && SHA256.test(String(context.sourceRevisionRef || '')), 'fact_context_binding_invalid');
  addIssue(issues, provider.transport === 'real_network' && provider.toolCallObserved === true
    && provider.toolResultObserved === true && provider.expectedJsonEmbeddedInPrompt === false
    && typeof provider.toolName === 'string' && provider.toolName.startsWith('result_'),
  'fact_provider_roundtrip_invalid');
  addIssue(issues, intent.contextRef === context.contextRef && intent.selectionRef === context.selectionRef
    && intent.sourceRevisionRef === context.sourceRevisionRef && SHA256.test(String(intent.intentRef || '')),
  'fact_intent_context_join_invalid');
  addIssue(issues, changeSet.intentRef === intent.intentRef && SHA256.test(String(changeSet.changeSetRef || '')),
    'fact_changeset_intent_join_invalid');
  addIssue(issues, gitChangeSet.changeSetRef === changeSet.changeSetRef && COMMIT.test(String(gitChangeSet.commit || '')),
    'fact_changeset_git_join_invalid');
  addIssue(issues, jobs.length > 0 && jobs.every((job) => job.changeSetRef === changeSet.changeSetRef
    && SHA256.test(String(job.jobRef || '')) && job.status === 'completed' && job.falseSuccessAbsent === true),
    'fact_job_changeset_join_invalid');
  const jobRefs = jobs.map((job) => job.jobRef);
  const formalArtifactRefs = jobs.flatMap((job) => job.formalArtifactRefs || []);
  const outputRevisionRefs = jobs.flatMap((job) => job.outputRevisionRefs || []);
  addIssue(issues, sameStringSet(changeSet.jobRefs, jobRefs), 'fact_changeset_job_set_mismatch');
  addIssue(issues, sameStringSet(jobCohort.jobRefs, jobRefs), 'fact_job_cohort_set_mismatch');
  addIssue(issues, artifact.changeSetRef === changeSet.changeSetRef && sameStringSet(artifact.jobRefs, jobRefs),
    'fact_artifact_job_join_invalid');
  addIssue(issues, sameStringSet(formalArtifactRefs, artifact.artifactRefs), 'fact_formal_artifact_set_mismatch');
  addIssue(issues, sameStringSet(outputRevisionRefs, revisions.revisionRefs), 'fact_job_revision_set_mismatch');
  addIssue(issues, sameStringSet(changeSet.candidateRevisionRefs, revisions.revisionRefs),
    'fact_changeset_revision_set_mismatch');
  addIssue(issues, revisions.changeSetRef === changeSet.changeSetRef
    && sameStringSet(revisions.artifactRefs, artifact.artifactRefs), 'fact_revision_artifact_join_invalid');
  addIssue(issues, validator.valid === true && sameStringSet(validator.revisionRefs, revisions.revisionRefs),
    'fact_validator_cohort_mismatch');
  addIssue(issues, sameStringSet(artifact.revisionRefs, revisions.revisionRefs)
    && sameStringSet(Object.keys(artifact.declaredHashes || {}), artifact.artifactRefs)
    && sameStringSet(Object.keys(artifact.scriptHashes || {}), artifact.artifactRefs)
    && Object.values(artifact.scriptHashes || {}).every((digest) => SHA256.test(String(digest || '')))
    && JSON.stringify(stable(artifact.declaredHashes || {})) === JSON.stringify(stable(artifact.provenanceHashes || {}))
    && JSON.stringify(stable(artifact.declaredHashes || {})) === JSON.stringify(stable(artifact.physicalHashes || {})),
  'fact_artifact_hash_truth_mismatch');
  addIssue(issues, gitRevisions.changeSetRef === changeSet.changeSetRef
    && gitRevisions.commit === gitChangeSet.commit
    && sameStringSet(gitRevisions.revisionRefs, revisions.revisionRefs), 'fact_revision_git_join_invalid');
  addIssue(issues, sameStringSet(compare.sourceRevisionRefs, changeSet.sourceRevisionRefs)
    && sameStringSet(compare.candidateRevisionRefs, revisions.revisionRefs)
    && compare.postconditionObserved === true, 'fact_compare_binding_invalid');
  addIssue(issues, lifecycle.changeSetRef === changeSet.changeSetRef
    && sameStringSet(lifecycle.revisionRefs, revisions.revisionRefs)
    && ['adopt', 'revert'].includes(lifecycle.operation) && lifecycle.completeCohort === true,
  'fact_lifecycle_cohort_invalid');
  addIssue(issues, gitLifecycle.changeSetRef === changeSet.changeSetRef
    && gitLifecycle.commit === gitChangeSet.commit
    && sameStringSet(gitLifecycle.revisionRefs, revisions.revisionRefs), 'fact_lifecycle_git_join_invalid');
  addIssue(issues, restart.oldProcessExited === true && restart.packagedAppReopened === true
    && restart.activeTaskInterrupted === true && restart.literalOsRebootObserved === true
    && restart.bootSessionChanged === true
    && restart.historyDigestBefore === restart.historyDigestAfter
    && restart.sourceDataDigestBefore === restart.sourceDataDigestAfter
    && restart.artifactSetDigestBefore === restart.artifactSetDigestAfter,
  'fact_restart_readback_invalid');
  addIssue(issues, sameStringSet(replay.sourceRevisionRefs, revisions.revisionRefs)
    && replay.exactMatch === true && replay.graphExact === true
    && SHA256.test(String(replay.packageDigest || '')) && SHA256.test(String(replay.outputCohortHash || '')),
  'fact_replay_task_binding_invalid');

  const expectedDigest = stableHash(withoutKey(factPackage, 'packageDigest'));
  addIssue(issues, factPackage.packageDigest === expectedDigest, 'fact_package_digest_mismatch');
  return Object.freeze({
    valid: issues.length === 0,
    issues: Object.freeze([...new Set(issues)]),
    expectedDigest,
    roles,
  });
}

function deriveFactPackageInvariants(factPackage, roles) {
  const repository = roles.get('environment.repository')?.payload || {};
  const jobCohort = roles.get('sqlite.job')?.payload || {};
  const jobs = Array.isArray(jobCohort.jobs) ? jobCohort.jobs : [];
  const artifact = roles.get('artifact.formal_output_cohort')?.payload || {};
  const lifecycle = roles.get('sqlite.lifecycle')?.payload || {};
  const restart = roles.get('restart.reopen')?.payload || {};
  const replay = roles.get('replay.exact')?.payload || {};
  const checks = {
    source_data_preserved: SHA256.test(String(restart.sourceDataDigestBefore || ''))
      && restart.sourceDataDigestBefore === restart.sourceDataDigestAfter,
    artifact_history_preserved: SHA256.test(String(restart.historyDigestBefore || ''))
      && restart.historyDigestBefore === restart.historyDigestAfter,
    unrelated_git_wip_preserved: SHA256.test(String(repository.snapshotBefore || ''))
      && repository.snapshotBefore === repository.snapshotAfter,
    no_false_success: jobs.length > 0
      && jobs.every((job) => job.status === 'completed' && job.falseSuccessAbsent === true),
    no_partial_adopt: lifecycle.completeCohort === true,
    no_silent_loss: SHA256.test(String(restart.artifactSetDigestBefore || ''))
      && restart.artifactSetDigestBefore === restart.artifactSetDigestAfter,
    independent_replayable_scripts: sameStringSet(Object.keys(artifact.scriptHashes || {}), artifact.artifactRefs)
      && Object.values(artifact.scriptHashes || {}).every((digest) => SHA256.test(String(digest || '')))
      && replay.exactMatch === true && replay.graphExact === true,
  };
  return Object.freeze({
    valid: DERIVED_INVARIANTS.every((id) => checks[id] === true),
    checks: Object.freeze(checks),
    taskId: factPackage.taskId,
  });
}

function verifyQualificationEvidence(root, report, manifest) {
  const issues = [];
  const manifestVerdict = verifyBundleManifest(root, manifest);
  issues.push(...manifestVerdict.issues);
  const packages = new Map();
  const primaryOperations = new Set();
  const replaySources = new Set();
  const screenshotDigests = new Set();
  const environmentTags = new Set();
  const providerClasses = new Set();
  const invariantChecks = {};
  const traces = Array.isArray(report?.productTraces) ? report.productTraces : [];

  for (const entry of Array.isArray(manifest?.files) ? manifest.files : []) {
    if (path.extname(entry?.path || '').toLowerCase() !== '.json') continue;
    try {
      inspectPrivateProjection(JSON.parse(fs.readFileSync(path.join(root, entry.path), 'utf8')), issues,
        `bundle:${entry.path}`);
    } catch {
      issues.push(`bundle_json_invalid:${entry?.path || 'unknown'}`);
    }
  }

  for (const trace of traces) {
    const traceId = trace?.traceId || 'unknown';
    let resolvedPackage;
    try { resolvedPackage = resolveEvidenceRef(root, trace?.factPackageRef); } catch (error) {
      issues.push(`trace_fact_package_unresolvable:${traceId}:${error.message}`);
      continue;
    }
    if (!resolvedPackage.value || typeof resolvedPackage.value !== 'object') {
      issues.push(`trace_fact_package_not_json_pointer:${traceId}`);
      continue;
    }
    const verdict = validateFactPackage(resolvedPackage.value);
    issues.push(...verdict.issues.map((issue) => `trace_fact_package_invalid:${traceId}:${issue}`));
    const factPackage = resolvedPackage.value;
    const derivedInvariants = deriveFactPackageInvariants(factPackage, verdict.roles);
    invariantChecks[traceId] = derivedInvariants.checks;
    for (const id of DERIVED_INVARIANTS) {
      if (derivedInvariants.checks[id] !== true) issues.push(`trace_invariant_failed:${traceId}:${id}`);
    }
    addIssue(issues, trace.taskId === factPackage.taskId, `trace_fact_package_task_mismatch:${traceId}`);
    addIssue(issues, trace.projectRefHash === factPackage.projectRefHash, `trace_fact_package_project_mismatch:${traceId}`);
    addIssue(issues, trace.conversationRefHash === factPackage.conversationRefHash,
      `trace_fact_package_conversation_mismatch:${traceId}`);
    addIssue(issues, trace.primaryOperationDigest === factPackage.primaryOperationDigest,
      `trace_primary_operation_mismatch:${traceId}`);
    if (primaryOperations.has(factPackage.primaryOperationDigest)) issues.push(`trace_primary_operation_reused:${traceId}`);
    primaryOperations.add(factPackage.primaryOperationDigest);
    const replay = verdict.roles.get('replay.exact')?.payload || {};
    const replayKey = stableHash(replay.sourceRevisionRefs || []);
    if (replaySources.has(replayKey)) issues.push(`trace_replay_source_reused:${traceId}`);
    replaySources.add(replayKey);
    packages.set(traceId, factPackage);
    const provider = verdict.roles.get('provider.result_tool_roundtrip')?.payload || {};
    if (provider.providerClass !== trace.providerClass) issues.push(`trace_provider_class_mismatch:${traceId}`);
    else if (typeof provider.providerClass === 'string') providerClasses.add(provider.providerClass);
    const repository = verdict.roles.get('environment.repository')?.payload || {};
    if (repository.mode === 'managed' && repository.initialState === 'non_git') environmentTags.add('managed_non_git');
    if (repository.mode === 'existing' && repository.initialState === 'clean' && repository.consentObserved === true) {
      environmentTags.add('existing_clean_git');
    }
    if (repository.mode === 'existing' && repository.initialState === 'dirty' && repository.consentObserved === true) {
      environmentTags.add('existing_dirty_git');
    }
    const restart = verdict.roles.get('restart.reopen')?.payload || {};
    if (restart.activeTaskInterrupted === true && restart.literalOsRebootObserved === true
        && restart.bootSessionChanged === true && restart.packagedAppReopened === true) {
      environmentTags.add('restart_and_interruption');
      environmentTags.add('literal_os_reboot');
    }
    const imported = verdict.roles.get('environment.imported_user_data')?.payload || {};
    if (imported.userUploadObserved === true && SHA256.test(String(imported.uploadSha256 || ''))
        && imported.executionInputSha256 === imported.uploadSha256) environmentTags.add('imported_user_data');
    const providerRecovery = verdict.roles.get('recovery.provider_transport')?.payload || {};
    const executionRecovery = verdict.roles.get('recovery.execution')?.payload || {};
    if (providerRecovery.controlledFailureObserved === true && providerRecovery.realProviderRecoveryObserved === true
        && providerRecovery.falseSuccessAbsent === true && executionRecovery.failedTerminalObserved === true
        && executionRecovery.recoveryCompleted === true && executionRecovery.falseSuccessAbsent === true) {
      environmentTags.add('provider_and_execution_failure');
    }

    for (const item of Array.isArray(trace.evidence) ? trace.evidence : []) {
      let resolved;
      try { resolved = resolveEvidenceRef(root, item.sourceRef); } catch (error) {
        issues.push(`trace_evidence_unresolvable:${traceId}:${item.id || 'unknown'}:${error.message}`);
        continue;
      }
      if (resolved.digest !== item.digest) issues.push(`trace_evidence_digest_mismatch:${traceId}:${item.id || 'unknown'}`);
      if (resolved.value && resolved.value.taskId !== undefined && resolved.value.taskId !== trace.taskId) {
        issues.push(`trace_evidence_task_mismatch:${traceId}:${item.id || 'unknown'}`);
      }
    }

  }

  const reportEvidence = Array.isArray(report?.evidence) ? report.evidence : [];
  const reportEvidenceById = new Map(reportEvidence.map((item) => [item?.id, item]));
  for (const item of reportEvidence) {
    if (!item?.id || reportEvidenceById.get(item.id) !== item) issues.push('qualification_evidence_id_invalid_or_duplicate');
    try {
      const resolved = resolveEvidenceRef(root, item?.sourceRef);
      if (resolved.digest !== item?.digest) issues.push(`qualification_evidence_digest_mismatch:${item?.id || 'unknown'}`);
    } catch (error) {
      issues.push(`qualification_evidence_unresolvable:${item?.id || 'unknown'}:${error.message}`);
    }
  }
  const matrix = Array.isArray(report?.responsiveMatrix) ? report.responsiveMatrix : [];
  const validCells = new Set();
  for (const cell of matrix) {
      const cellKey = `${cell?.theme}:${cell?.width}`;
      const evidence = reportEvidenceById.get(cell?.screenshotEvidenceId);
      if (!evidence || evidence.kind !== 'screenshot') {
        issues.push(`qualification_responsive_screenshot_missing:${cellKey}`);
        continue;
      }
      let screenshot;
      try { screenshot = resolveEvidenceRef(root, evidence.sourceRef); } catch (error) {
        issues.push(`qualification_responsive_screenshot_unresolvable:${cellKey}:${error.message}`);
        continue;
      }
      if (screenshot.value !== null || screenshot.digest !== evidence.digest) {
        issues.push(`qualification_responsive_screenshot_digest_mismatch:${evidence.id}`);
        continue;
      }
      try {
        const size = parsePngSize(screenshot.bytes);
        if (size.width !== evidence.width || size.height !== evidence.height) {
          issues.push(`qualification_responsive_screenshot_dimensions_mismatch:${evidence.id}`);
        }
      } catch (error) {
        issues.push(`qualification_responsive_screenshot_invalid:${evidence.id}:${error.message}`);
      }
      if (evidence.theme !== cell.theme || evidence.viewportWidth !== cell.width) {
        issues.push(`qualification_responsive_screenshot_cell_mismatch:${evidence.id}`);
      }
      if (screenshotDigests.has(evidence.digest)) issues.push(`qualification_responsive_screenshot_reused:${evidence.id}`);
      screenshotDigests.add(evidence.digest);
      if (cell?.canvasVisible === true && cell?.operationCompleted === true
          && cell?.operationPostconditionObserved === true && cell?.horizontalOverflow === false
          && Number.isFinite(cell?.firstCanvasMs) && cell.firstCanvasMs >= 0 && cell.firstCanvasMs <= 1000) {
        validCells.add(cellKey);
      }
  }
  for (const theme of ['light', 'dark']) {
    for (const width of [1440, 1024, 820]) {
      const key = `${theme}:${width}`;
      if (!validCells.has(key)) issues.push(`qualification_responsive_cell_missing:${key}`);
      else {
        environmentTags.add(`${theme}_theme`);
        environmentTags.add(width === 1440 ? 'viewport_wide' : `viewport_${width}`);
      }
    }
  }

  return Object.freeze({
    valid: issues.length === 0 && packages.size === traces.length,
    issues: Object.freeze([...new Set(issues)]),
    packageCount: packages.size,
    primaryOperationCount: primaryOperations.size,
    screenshotCount: screenshotDigests.size,
    environmentTags: Object.freeze([...environmentTags].sort()),
    providerClasses: Object.freeze([...providerClasses].sort()),
    privacyClean: !issues.some((issue) => issue.startsWith('private_projection_')),
    invariantChecks: Object.freeze(invariantChecks),
  });
}

