      failures.push({ code: 'package_manifest_required_files_invalid' });
    }
    const manifestFiles = Array.isArray(manifest.files) ? manifest.files : null;
    if (!manifestFiles) failures.push({ code: 'package_manifest_files_invalid' });
    else {
      const seenPaths = new Set();
      for (const item of manifestFiles) {
        if (!isPlainObject(item) || Object.keys(item).length !== 3 || Object.keys(item).some((key) => !['relativePath', 'sha256', 'sizeBytes'].includes(key))
            || !isSafeRelativePath(item.relativePath) || item.relativePath === 'package-manifest.json'
            || seenPaths.has(item.relativePath) || !isSha256(item.sha256)
            || !Number.isSafeInteger(item.sizeBytes) || item.sizeBytes < 0) {
          failures.push({ code: 'package_manifest_file_entry_invalid', path: item && item.relativePath || null });
          continue;
        }
        seenPaths.add(item.relativePath);
        const inspected = inspectFile(item.relativePath);
        if (!inspected.ok) failures.push({ code: inspected.code, path: item.relativePath });
      }
      const inventory = collectInventory();
      for (const item of inventory.unsupported) failures.push({ code: 'package_inventory_unsupported_entry', path: item.relativePath, kind: item.kind });
      if (stableStringify(inventory.files) !== stableStringify(manifestFiles)) failures.push({ code: 'package_file_inventory_mismatch' });
    }
    for (const requiredFile of Array.isArray(manifest.requiredFiles) ? manifest.requiredFiles : []) {
      const inspected = inspectFile(requiredFile);
      if (!inspected.ok) failures.push({ code: 'required_file_' + inspected.code, path: requiredFile });
    }
    const digestPayload = {
      replayPackageVersion: manifest.replayPackageVersion,
      status: manifest.status,
      sourceDigest: manifest.sourceDigest,
      privacyMode: manifest.privacyMode,
      requiredFiles: manifest.requiredFiles,
      files: manifest.files,
      generatedAt: manifest.generatedAt,
    };
    if (!isSha256(manifest.packageDigest) || sha256(stableStringify(digestPayload)) !== manifest.packageDigest) {
      failures.push({ code: 'package_digest_mismatch' });
    }
}
let replay = {};
try { replay = JSON.parse(fs.readFileSync(path.join(root, 'replay.json'), 'utf8')); }
catch { failures.push({ code: 'replay_manifest_invalid' }); }
const artifact = requested ? (replay.artifacts || []).find((item) => item.artifactId === requested) : null;
if (requested && !artifact) failures.push({ code: 'artifact_unknown', artifactId: requested });
const response = {
  ok: failures.length === 0,
  packageDigest: manifest && manifest.packageDigest || null,
  artifact: artifact || null,
  failures,
  nextAction: failures.length ? 'repair_package' : 'submit_to_petri_controlled_replay',
  requiresConfirmation: true,
};
process.stdout.write(JSON.stringify(response, null, 2) + '\\n');
process.exitCode = failures.length ? 1 : 0;
`;
}

function buildScientificReplayPackage({
  taskRecord,
  job,
  projectRoot,
  packageDir,
  contextCheckpoint = null,
  workflowPlan = null,
  includeFixtureInputs = false,
  inputSources = {},
  privacyMode = 'references_only',
  formalArtifactIds = null,
} = {}) {
  if (!taskRecord?.spec || !job || !projectRoot || !packageDir) throw new Error('replay_package_fields_required');
  if (relativeInside(projectRoot, packageDir) == null) throw new Error('replay_package_path_outside_project');
  const result = parseJson(job.result_json || job.result, {});
  if (job.status !== 'completed' || result.artifactTruth?.status !== 'valid') throw new Error('replay_package_requires_valid_artifact_truth');
  const provenance = result.executionProvenance;
  const delivery = result.deliveryManifest;
  if (!provenance?.provenanceHash || !delivery?.manifestHash) throw new Error('replay_package_delivery_provenance_required');
  if (!provenance.script?.snapshotPath || !fs.existsSync(provenance.script.snapshotPath)) throw new Error('replay_package_script_snapshot_missing');
  if (hashFile(provenance.script.snapshotPath) !== provenance.script.sha256) throw new Error('replay_package_script_snapshot_drift');
  if (!PACKAGE_PRIVACY_MODES.has(privacyMode)) throw new Error('replay_package_privacy_mode_invalid');
  if (includeFixtureInputs && !['repository_demo_data_only', 'project_bound_private'].includes(privacyMode)) {
    throw new Error('replay_package_fixture_input_policy_denied');
  }
  const requestedArtifactIds = Array.isArray(formalArtifactIds) && formalArtifactIds.length > 0
    ? [...new Set(formalArtifactIds.map((id) => String(id || '').trim()).filter(Boolean))]
    : null;
  const deliveryArtifacts = Array.isArray(delivery.artifacts) ? delivery.artifacts : [];
  const replayArtifacts = requestedArtifactIds
    ? deliveryArtifacts.filter((artifact) => requestedArtifactIds.includes(String(artifact?.id || '').trim()))
    : deliveryArtifacts;
  if (requestedArtifactIds && (replayArtifacts.length !== requestedArtifactIds.length
      || new Set(replayArtifacts.map((artifact) => String(artifact?.id || '').trim())).size !== requestedArtifactIds.length)) {
    throw new Error('replay_package_formal_output_cohort_incomplete');
  }

  let checkpoint = null;
  if (contextCheckpoint) {
    const validated = validateContextCheckpoint(contextCheckpoint);
    if (!validated.ok) throw new Error('replay_package_context_checkpoint_invalid');
    if (validated.checkpoint.projectId !== taskRecord.project_id || validated.checkpoint.conversationId !== taskRecord.conversation_id) throw new Error('replay_package_context_checkpoint_scope_mismatch');
    checkpoint = validated.checkpoint;
  }

  fs.mkdirSync(packageDir, { recursive: true });
  const inputs = (taskRecord.spec.inputs || []).map((input) => ({
    role: input.role,
    relativePath: input.relativePath,
    sha256: input.sha256,
    sizeBytes: input.sizeBytes,
    sourceArtifactRef: input.sourceArtifactRef || null,
    packagedPath: includeFixtureInputs ? `inputs/${input.relativePath}` : null,
  }));
  if (includeFixtureInputs) {
    for (const input of inputs) {
      const source = inputSources[input.role];
      if (!source || !fs.existsSync(source)) throw new Error(`replay_package_fixture_input_missing:${input.role}`);
      if (hashFile(source) !== input.sha256) throw new Error(`replay_package_fixture_input_drift:${input.role}`);
      const target = path.join(packageDir, input.packagedPath);
      if (relativeInside(packageDir, target) == null) throw new Error('replay_package_fixture_path_escape');
      fs.mkdirSync(path.dirname(target), { recursive: true });
      fs.copyFileSync(source, target);
    }
  }

  const scriptExtension = path.extname(provenance.script.snapshotPath) || '.txt';
  const packagedScriptPath = `repro/scripts/run-script${scriptExtension}`;
  fs.mkdirSync(path.dirname(path.join(packageDir, packagedScriptPath)), { recursive: true });
  fs.copyFileSync(provenance.script.snapshotPath, path.join(packageDir, packagedScriptPath));

  const params = sanitizeParams(provenance.params?.normalized || parseJson(job.params_json, {}), inputs, includeFixtureInputs);
  const paramsHash = sha256Buffer(Buffer.from(stableStringify(params)));
  const artifacts = replayArtifacts.map((artifact) => {
    const artifactId = safeSegment(artifact.id || artifact.label || artifact.relativePath, 'artifact');
    const provenanceArtifact = (provenance.artifacts || []).find((item) => item.id === artifact.id || item.filename === path.basename(artifact.relativePath || ''));
    const entry = {
      replayArtifactVersion: 1,
      artifactId,
      sourceArtifactId: artifact.id || null,
      type: artifact.type,
      label: artifact.label,
      expected: {
        relativePath: artifact.relativePath,
        sha256: artifact.sha256 || provenanceArtifact?.sha256 || null,
      },
      producer: { toolId: job.tool_id, toolJobId: job.id, pluginVersion: provenance.plugin?.version || null },
      scriptRef: packagedScriptPath,
      inputRefs: inputs,
      paramsRef: 'params.json',
      paramsHash,
      deterministic: provenance.runtime?.seed == null,
      seed: provenance.runtime?.seed ?? null,
      tolerance: provenance.runtime?.tolerance ?? null,
      comparisonMode: provenance.runtime?.tolerance
        ? 'tolerance_based'
        : ['markdown', 'text', 'report'].includes(String(artifact.type || '').toLowerCase())
          ? 'narrative'
          : 'deterministic',
      controlledReplay: { requiresConfirmation: true, target: artifact.id || artifactId },
    };
    writeJson(path.join(packageDir, 'repro', 'artifacts', `${artifactId}.json`), entry);
    return {
      artifactId,
      sourceArtifactId: artifact.id || null,
      entrypoint: `repro/artifacts/${artifactId}.json`,
      expected: entry.expected,
    };
  });

  const taskSpec = stripSensitiveKeys(taskRecord.spec);
  writeJson(path.join(packageDir, 'task-spec.json'), taskSpec);
  writeJson(path.join(packageDir, 'params.json'), params);
  writeJson(path.join(packageDir, 'context-checkpoint.json'), checkpoint || {
    status: 'unavailable',
    reason: 'no_persisted_context_checkpoint',
    projectId: taskRecord.project_id,
    conversationId: taskRecord.conversation_id,
  });
  const exportedWorkflowPlan = stripSensitiveKeys(workflowPlan || {
    workflowPlanVersion: 1,
    status: 'completed',
    steps: [{ id: 'step-1', toolId: job.tool_id, toolJobId: job.id, dependsOn: [], artifactIds: artifacts.map((item) => item.artifactId) }],
  });
  writeJson(path.join(packageDir, 'workflow-plan.json'), exportedWorkflowPlan);
  writeJson(path.join(packageDir, 'job-manifest.json'), stripSensitiveKeys({
    id: job.id,
    toolId: job.tool_id,
    status: job.status,
    projectId: job.project_id,
    createdAt: job.created_at,
    completedAt: job.completed_at,
    artifactTruth: result.artifactTruth,
    artifactDiagnostics: result.artifactDiagnostics || [],
  }));
  writeJson(path.join(packageDir, 'artifact-manifest.json'), stripSensitiveKeys({
    artifactSchemaVersion: result.artifactSchemaVersion || 1,
    artifacts: replayArtifacts.map((artifact) => ({
      id: artifact.id,
      type: artifact.type,
      label: artifact.label,
      relativePath: artifact.relativePath,
      sizeBytes: artifact.sizeBytes,
      sha256: artifact.sha256,
      reproducibility: artifact.reproducibility,
    })),
  }));
  writeJson(path.join(packageDir, 'delivery-manifest.json'), stripSensitiveKeys(delivery));
  writeJson(path.join(packageDir, 'provenance.json'), stripSensitiveKeys({
    ...provenance,
    params: { normalized: params, sha256: paramsHash },
    inputs,
    runtime: {
      ...provenance.runtime,
      command: provenance.runtime?.command ? path.basename(provenance.runtime.command) : null,
    },
    script: { ...provenance.script, snapshotPath: packagedScriptPath },
    command: provenance.command ? {
      ...provenance.command,
      executable: provenance.command.executable ? path.basename(provenance.command.executable) : null,
      args: (provenance.command.args || []).map((arg) => typeof arg === 'string' && path.isAbsolute(arg) ? path.basename(arg) : arg),
      cwd: 'replay-workdir',
    } : null,
  }));
  const sourceDigest = sha256Buffer(Buffer.from(stableStringify({
    taskSpecHash: taskRecord.spec_hash,
    contextSourceDigest: checkpoint?.sourceDigest || null,
    provenanceHash: provenance.provenanceHash,
    deliveryManifestHash: delivery.manifestHash,
  })));
  const replay = {
    replayManifestVersion: 1,
    privacyMode,
    task: { taskId: taskRecord.task_id, version: taskRecord.version, taskSpecHash: taskRecord.spec_hash },
    sourceDigest,
    inputs,
    params: { relativePath: 'params.json', sha256: paramsHash },
    runtime: stripSensitiveKeys(provenance.runtime || {}),
    plugin: stripSensitiveKeys(provenance.plugin || {}),
    script: { relativePath: packagedScriptPath, sha256: provenance.script.sha256 },
    artifacts,
    replayPolicy: {
      fixtureOfflineAllowed: includeFixtureInputs && privacyMode === 'repository_demo_data_only',
      packagedProjectInputs: includeFixtureInputs && privacyMode === 'project_bound_private',
      realTaskRequiresConfirmation: true,
      createsToolJob: true,
      directShellExecutionAllowed: false,
    },
    driftKinds: REPLAY_DRIFT_KINDS,
  };
  writeJson(path.join(packageDir, 'replay.json'), replay);
  writeText(path.join(packageDir, 'repro', 'reproduce.mjs'), replayWrapperSource());
  writeText(path.join(packageDir, 'HANDOFF.md'), `# Petri scientific task handoff\n\n- Task: ${taskRecord.task_id} v${taskRecord.version}\n- Job: ${job.id}\n- Tool: ${job.tool_id}\n- Source digest: ${sourceDigest}\n- History checkpoint: ${checkpoint ? 'included' : 'unavailable; see context-checkpoint.json'}\n- Verify: \`node repro/reproduce.mjs\`\n- Prepare one artifact: \`node repro/reproduce.mjs --artifact <artifactId>\`\n\nThe wrapper verifies package integrity and prepares a controlled replay request. It never runs scientific code directly. Real replay must be confirmed and recorded as a Petri replay Job.\n`);

  const files = collectPackageFiles(packageDir, new Set(['package-manifest.json']));
  const packageManifest = {
    replayPackageVersion: REPLAY_PACKAGE_VERSION,
    status: checkpoint ? 'complete' : 'partial_history',
    packageDigest: null,
    sourceDigest,
    privacyMode,
    requiredFiles: [...REQUIRED_PACKAGE_FILES],
    files,
    generatedAt: new Date().toISOString(),
  };
  packageManifest.packageDigest = packageManifestDigest(packageManifest);
  writeJson(path.join(packageDir, 'package-manifest.json'), packageManifest);
  const validation = validateScientificReplayPackage(packageDir);
  if (!validation.ok) throw new Error(`replay_package_validation_failed:${validation.issues.map((item) => item.code).join(',')}`);
  return { packageDir: path.resolve(packageDir), packageManifest, replay, validation };
}

function validateScientificReplayPackage(packageDir) {
  const issues = [];
  let root;
  let manifest;
  try {
    root = fs.realpathSync(packageDir);
    if (!fs.statSync(root).isDirectory()) throw new Error('not_directory');
  } catch {
    return { ok: false, issues: [{ code: 'package_directory_missing' }] };
  }
  const manifestPath = path.join(root, 'package-manifest.json');
  try {
    const manifestStat = fs.lstatSync(manifestPath);
    if (manifestStat.isSymbolicLink() || !manifestStat.isFile()) throw new Error('not_regular');
    manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8'));
  } catch {
    return { ok: false, issues: [{ code: 'package_manifest_missing_or_invalid' }] };
  }

  const schema = validatePackageManifestSchema(manifest);
  issues.push(...schema.issues);
  if (!isPlainObject(manifest)) return { ok: false, manifest, issues };
  let inventory = { files: [], unsupported: [] };
  try {
    inventory = collectPackageTree(root, new Set(['package-manifest.json']));
  } catch {
    issues.push({ code: 'package_inventory_unreadable' });
  }
  for (const item of inventory.unsupported) {
    issues.push({ code: 'package_inventory_unsupported_entry', path: item.relativePath, kind: item.kind });
  }

  if (Array.isArray(manifest.requiredFiles)) {
    for (const required of manifest.requiredFiles) {
      const inspected = inspectPackagedRegularFile(root, required);
      if (!inspected.ok) issues.push({ code: `required_file_${inspected.code}`, path: required || null });
    }
  }
  if (Array.isArray(manifest.files)) {
    for (const item of manifest.files) {
      if (!isPlainObject(item) || !isSafePackageRelativePath(item.relativePath)
          || item.relativePath === 'package-manifest.json') continue;
      const inspected = inspectPackagedRegularFile(root, item.relativePath);
      if (!inspected.ok) {
        issues.push({ code: inspected.code, path: item.relativePath || null });
      } else {
        if (Number.isSafeInteger(item.sizeBytes) && item.sizeBytes >= 0 && inspected.stat.size !== item.sizeBytes) {
          issues.push({ code: 'package_file_size_mismatch', path: item.relativePath });
        }
        if (SHA256_HEX.test(String(item.sha256 || '')) && hashFile(inspected.target) !== item.sha256) {
          issues.push({ code: 'package_file_hash_mismatch', path: item.relativePath });
        }
      }
    }
    if (stableStringify(inventory.files) !== stableStringify(manifest.files)) {
      issues.push({
        code: 'package_file_inventory_mismatch',
        expectedCount: manifest.files.length,
        actualCount: inventory.files.length,
      });
    }
  }
  if (isPlainObject(manifest)
      && PACKAGE_MANIFEST_FIELDS.every((field) => Object.prototype.hasOwnProperty.call(manifest, field))) {
    if (packageManifestDigest(manifest) !== manifest.packageDigest) {
      issues.push({ code: 'package_digest_mismatch' });
    }
  }
  for (const item of collectPackageFiles(root)) {
    if (!/\.(?:json|md|mjs|r|py|txt|csv|tsv)$/i.test(item.relativePath)) continue;
    try {
      const text = fs.readFileSync(path.join(root, item.relativePath), 'utf8');
      if (SECRET_VALUE.test(text)) issues.push({ code: 'secret_value_detected', path: item.relativePath });
      if (/\b(?:Authorization|api[_-]?key|access[_-]?token)\b/i.test(text)) issues.push({ code: 'sensitive_field_detected', path: item.relativePath });
    } catch {
      issues.push({ code: 'package_text_file_unreadable', path: item.relativePath });
    }
  }
  return { ok: issues.length === 0, manifest, issues };
}

function assessReplayReadiness({
  packageDir,
  inputSources = {},
  currentPluginFingerprint = null,
  currentParams = null,
  currentRuntimeVersion = null,
  executionResult = null,
  artifactSources = {},
} = {}) {
  const validation = validateScientificReplayPackage(packageDir);
  if (!validation.ok) return { ok: false, status: 'blocked', drift: [{ kind: 'artifact_drift', details: validation.issues }] };
  const replay = parseJson(fs.readFileSync(path.join(packageDir, 'replay.json'), 'utf8'), {});
  const drift = [];
  for (const input of replay.inputs || []) {
    const source = inputSources[input.role] || (input.packagedPath ? path.join(packageDir, input.packagedPath) : null);
    if (!source || hashFile(source) !== input.sha256) drift.push({ kind: 'input_drift', role: input.role, expected: input.sha256, actual: hashFile(source) });
  }
  if (currentPluginFingerprint != null && replay.plugin?.manifestFingerprint !== currentPluginFingerprint) drift.push({ kind: 'plugin_drift', expected: replay.plugin?.manifestFingerprint || null, actual: currentPluginFingerprint });
  if (currentParams != null) {
    const actual = sha256Buffer(Buffer.from(stableStringify(currentParams)));
    if (actual !== replay.params?.sha256) drift.push({ kind: 'parameter_drift', expected: replay.params?.sha256, actual });
  }
  if (currentRuntimeVersion != null && replay.runtime?.version && replay.runtime.version !== currentRuntimeVersion) drift.push({ kind: 'environment_drift', expected: replay.runtime.version, actual: currentRuntimeVersion });
  if (executionResult && executionResult.exitCode !== 0) drift.push({ kind: 'execution_failure', exitCode: executionResult.exitCode, stderr: String(executionResult.stderr || '').slice(-1000) });
  if (executionResult && executionResult.exitCode === 0) {
    for (const artifact of replay.artifacts || []) {
      const source = artifactSources[artifact.artifactId];
      if (source && artifact.expected?.sha256 && hashFile(source) !== artifact.expected.sha256) drift.push({ kind: 'artifact_drift', artifactId: artifact.artifactId, expected: artifact.expected.sha256, actual: hashFile(source) });
    }
  }
  const driftReport = buildDriftReport({
    replayCaseId: replay.task?.taskId || null,
    sourceDigest: replay.sourceDigest || null,
    targetDigest: sha256Buffer(Buffer.from(stableStringify({
      plugin: currentPluginFingerprint,
      params: currentParams,
      runtime: currentRuntimeVersion,
    }))),
    contextDrifts: drift.map((item) => ({
      ...item,
      scientificallyMaterial: ['input_drift', 'parameter_drift'].includes(item.kind),
    })),
  });
  return {
    ok: drift.length === 0,
    status: drift.length ? 'blocked' : 'ready_for_confirmation',
    requiresConfirmation: true,
    drift,
    driftReport,
  };
}

module.exports = {
  REPLAY_PACKAGE_VERSION,
  REPLAY_DRIFT_KINDS,
  hashFile,
  relativeInside,
  sanitizeParams,
  selectReplayContextCheckpoint,
  buildResultRevisionReplayPackage,
  buildScientificReplayPackage,
  validateScientificReplayPackage,
  assessReplayReadiness,
};

'use strict';

const crypto = require('crypto');
const {
  normalizeScientificTaskSpec,
  validateScientificTaskSpec,
  hashScientificTaskSpec,
  transitionScientificTaskSpec,
  stableStringify,
} = require('./scientific-task-spec');

function digest(value) {
  return crypto.createHash('sha256').update(JSON.stringify(value)).digest('hex');
}

function confirmationIssues(spec, plan, confirmation = {}) {
  const issues = [];
  if (!plan || typeof plan !== 'object') issues.push({ code: 'plan_required', message: '必须提供 HRT-2 候选计划。' });
  if (plan && plan.status !== 'ready_for_confirmation') issues.push({ code: 'plan_not_ready', message: `计划状态为 ${plan.status || 'unknown'}，不能进入确认。` });
  if (spec.status !== 'ready_for_confirmation') issues.push({ code: 'task_not_ready', message: `TaskSpec 状态为 ${spec.status}，不能确认。` });
  if (!confirmation.userId) issues.push({ code: 'confirming_user_required', message: '确认人不能为空。' });
  if (confirmation.riskAcknowledged !== true) issues.push({ code: 'risk_not_acknowledged', message: '用户必须明确确认风险和失败边界。' });
  const expectedHashes = Object.fromEntries((spec.inputs || []).map((input) => [input.relativePath, input.sha256]));
  const actualHashes = confirmation.inputHashes && typeof confirmation.inputHashes === 'object' ? confirmation.inputHashes : {};
  for (const [relativePath, sha256] of Object.entries(expectedHashes)) {
    if (!sha256) issues.push({ code: 'input_hash_missing', path: relativePath, message: '确认前必须锁定输入 SHA-256。' });
    else if (actualHashes[relativePath] !== sha256) issues.push({ code: 'input_hash_mismatch', path: relativePath, message: '确认时输入哈希与 TaskSpec 不一致。' });
  }
  if (!confirmation.method || confirmation.method !== spec.method.category) issues.push({ code: 'method_mismatch', message: '确认的方法必须与 TaskSpec 方法类别一致。' });
  if (!Array.isArray(confirmation.requestedDeliverables) || confirmation.requestedDeliverables.length === 0) issues.push({ code: 'deliverables_required', message: '确认必须包含预期交付物。' });
  return issues;
}

function createScientificTaskConfirmationPreview({ taskSpec, plan, evidence = [], estimatedResources = null } = {}) {
  const spec = normalizeScientificTaskSpec(taskSpec);
  const validation = validateScientificTaskSpec(spec, { normalized: true });
  if (!validation.ok) return { ok: false, error: 'scientific_task_spec_invalid', issues: validation.issues };
  const taskSpecHash = hashScientificTaskSpec(spec);
  return {
    ok: true,
    status: spec.status,
    taskSpecHash,
    preview: {
      taskId: spec.taskId,
      projectId: spec.projectId,
      conversationId: spec.conversationId,
      originalRequest: spec.originalRequest,
      inputs: spec.inputs.map((input) => ({ relativePath: input.relativePath, sha256: input.sha256, sizeBytes: input.sizeBytes, role: input.role })),
      method: spec.method,
      requestedDeliverables: spec.requestedDeliverables,
      evidence,
      plan: plan || null,
      estimatedResources,
      sideEffects: { createsToolJob: false, writesWorkspace: false },
      confirmationRequired: true,
    },
  };
}

function confirmScientificTask({ taskSpec, plan, confirmation = {} } = {}) {
  const spec = normalizeScientificTaskSpec(taskSpec);
  const validation = validateScientificTaskSpec(spec, { normalized: true });
  if (!validation.ok) return { ok: false, error: 'scientific_task_spec_invalid', issues: validation.issues };
  const issues = confirmationIssues(spec, plan, confirmation);
  if (issues.length) return { ok: false, error: 'confirmation_rejected', issues, taskSpecHash: hashScientificTaskSpec(spec) };
  const transitioned = transitionScientificTaskSpec(spec, 'confirmed');
  if (!transitioned.ok) return transitioned;
  const record = {
    confirmationVersion: 1,
    confirmedAt: confirmation.confirmedAt || new Date().toISOString(),
    userId: String(confirmation.userId),
    taskSpecHash: transitioned.specHash,
    planHash: plan.planHash || digest(plan),
    selectedToolId: plan.recommendation?.toolId || null,
    inputHashes: { ...confirmation.inputHashes },
    method: confirmation.method,
    params: confirmation.params && typeof confirmation.params === 'object' ? confirmation.params : {},
    requestedDeliverables: [...confirmation.requestedDeliverables],
    riskAcknowledged: true,
  };
  return { ok: true, spec: transitioned.spec, taskSpecHash: transitioned.specHash, confirmation: record, createsToolJob: false };
}

function validateScientificTaskExecution({ persistedTask, projectId, toolId, params = {} } = {}) {
  if (!persistedTask) return { ok: false, error: 'scientific_task_not_found' };
  if (persistedTask.status !== 'confirmed' || !persistedTask.confirmation) return { ok: false, error: 'scientific_task_not_confirmed' };
  if (!projectId || persistedTask.project_id !== projectId) return { ok: false, error: 'scientific_task_project_mismatch' };
  if (persistedTask.tool_job_id) return { ok: false, error: 'scientific_task_already_bound', toolJobId: persistedTask.tool_job_id };
  if (persistedTask.confirmation.selectedToolId && persistedTask.confirmation.selectedToolId !== toolId) {
    return { ok: false, error: 'scientific_task_tool_changed', expected: persistedTask.confirmation.selectedToolId, actual: toolId };
  }
  const expectedParams = persistedTask.confirmation.params || {};
  const actualParams = params || {};
  if (stableStringify(expectedParams) !== stableStringify(actualParams)) return { ok: false, error: 'scientific_task_params_changed' };
  return { ok: true, taskId: persistedTask.task_id, version: persistedTask.version, specHash: persistedTask.spec_hash };
}

// BLOCK-83 D3：领域钩子适配器——经 task-confirmation-hooks 注册表进入，不再被核心层直接 require。
function createScientificTaskConfirmationHook() {
  return {
    id: 'scientific-task-confirmation',
    validateTaskExecution: validateScientificTaskExecution,
    // BLOCK-83 D12：领域错误码由域包声明，核心不再硬编码这些名字。
    userInputErrorCodes: [
      'scientific_task_not_confirmed',
      'scientific_task_params_changed',
      'scientific_task_tool_changed',
    ],
  };
}

module.exports = { confirmationIssues, createScientificTaskConfirmationPreview, confirmScientificTask, validateScientificTaskExecution, createScientificTaskConfirmationHook };

'use strict';

/**
 * HRT-2: translate a normalized ScientificTaskSpec into bounded evidence and
 * method candidates. This module is deliberately side-effect free: it never
 * creates a tool_job and never executes a plugin.
 */

const path = require('path');

const STATUS = Object.freeze({
  READY: 'ready_for_confirmation',
  NEEDS_DECISION: 'requires_user_decision',
  CANNOT_ANSWER: 'cannot_reliably_answer',
  NO_METHOD: 'no_matching_method',
});

function text(value) { return typeof value === 'string' ? value.trim() : ''; }

function normalizeEvidence(item) {
  const source = item && typeof item === 'object' ? item : {};
  return {
    relativePath: text(source.relativePath || source.path) || null,
    sha256: text(source.sha256).toLowerCase() || null,
    sizeBytes: Number.isFinite(Number(source.sizeBytes)) ? Number(source.sizeBytes) : null,
    kind: text(source.kind || source.fileType) || 'unknown',
    headers: Array.isArray(source.headers) ? source.headers.map(text).filter(Boolean) : [],
    sampleIds: Array.isArray(source.sampleIds) ? source.sampleIds.map(text).filter(Boolean) : [],
    rows: Number.isFinite(Number(source.rows)) ? Number(source.rows) : null,
    columns: Number.isFinite(Number(source.columns)) ? Number(source.columns) : null,
    source: text(source.source) || 'bounded_probe',
  };
}

function hasHeader(evidence, names) {
  const headers = new Set(evidence.flatMap((item) => item.headers.map((h) => h.toLowerCase())));
  return names.some((name) => headers.has(name));
}

// HLE-C5R: Detect contrast metadata column from evidence headers
function detectContrastLevels(evidence) {
  const headers = new Set((evidence || []).flatMap((item) => item.headers.map((h) => h.toLowerCase())));
  const contrastKeywords = ['condition', 'group', 'treatment', 'control', 'status', 'genotype', 'stage'];
  for (const h of headers) {
    for (const kw of contrastKeywords) {
      if (h.includes(kw)) return h;
    }
  }
  return null;
}

function inputEvidence(taskSpec, evidence) {
  const byPath = new Map(evidence.map((item) => [item.relativePath, item]));
  return (taskSpec.inputs || []).map((input) => {
    const relativePath = input.relativePath || null;
    return {
      role: input.role || 'unknown',
      relativePath,
      snapshot: byPath.get(relativePath) || null,
      evidenceStatus: byPath.has(relativePath) ? 'observed' : 'missing',
    };
  });
}

function candidateFor(manifest, reason, prerequisites, risk = []) {
  return {
    toolId: manifest.id,
    title: manifest.title || manifest.id,
    category: manifest.category || null,
    entryPoint: manifest.entryPoint || manifest.execution?.entryPoint || null,
    pluginVersion: manifest.version || null,
    rationale: reason,
    prerequisites,
    risks: risk,
    supportedPlatforms: manifest.supportedPlatforms || [],
    inputs: (manifest.inputs || []).map((input) => input.id),
  };
}

function evidenceFromIndex(index = {}) {
  return (Array.isArray(index.entries) ? index.entries : []).map((entry) => ({
    relativePath: entry.relativePath || null,
    sha256: entry.hash?.sha256 || entry.sha256 || null,
    sizeBytes: entry.size,
    kind: entry.kind,
    headers: entry.table?.headers || [],
    rows: entry.table?.rowCount ?? null,
    columns: entry.table?.columnCount ?? entry.table?.headers?.length ?? null,
    source: 'harness-file-index',
  }));
}

function planScientificTask({ taskSpec, evidence = [], plugins = [], runtime = null } = {}) {
  if (!taskSpec || typeof taskSpec !== 'object') throw new Error('taskSpec is required');
  const observed = evidence.map(normalizeEvidence);
  const mappedInputs = inputEvidence(taskSpec, observed);
  const counts = mappedInputs.find((item) => item.role === 'counts');
  const metadata = mappedInputs.find((item) => item.role === 'metadata');
  const normalizedPlugins = Array.isArray(plugins) ? plugins.filter((item) => item && item.id) : [];
  const diagnostics = [];
  const gaps = [];

  if (mappedInputs.some((item) => item.evidenceStatus === 'missing')) {
    gaps.push({ code: 'input_evidence_missing', message: '至少一个输入文件尚未获得可审阅的结构证据。' });
  }
  if (!counts) gaps.push({ code: 'counts_input_missing', message: '没有识别到 counts 表。' });
  // HLE-C5R: Explicit contrast detection for Bulk RNA coldata binding
  let coldataBinding = null;
  if (metadata?.snapshot && !hasHeader([metadata.snapshot], ['condition', 'group', 'treatment', 'control'])) {
    gaps.push({ code: 'contrast_column_missing', message: 'metadata 中没有可识别的处理/对照分组列，不能可靠推断 contrast。' });
  } else if (metadata?.snapshot && counts) {
    const contrastCol = detectContrastLevels([metadata.snapshot]);
    if (contrastCol) {
      coldataBinding = {
        metadataFile: metadata.relativePath,
        coldataFile: metadata.relativePath,
        designColumn: contrastCol,
        note: `DESeq2 coldata 来自 metadata 文件 '${metadata.relativePath}'，design 列 '${contrastCol}'。contrast_ref/contrast_treat 具体值必须来自 sample-metadata-validator 验证结果，禁止 Agent 自行推断。`,
        requiredValidator: 'sample-metadata-validator',
      };
    }
  }
  const unresolved = Array.isArray(taskSpec.requiresUserDecision)
    ? taskSpec.requiresUserDecision.filter((item) => item && item.required !== false && item.status === 'unresolved')
    : [];
  if (unresolved.length) {
    gaps.push(...unresolved.map((item) => ({ code: 'user_decision_required', message: item.question, decisionId: item.id })));
  }

  const candidates = [];
  const add = (id, reason, prerequisites, risk) => {
    const manifest = normalizedPlugins.find((item) => item.id === id);
    if (manifest) candidates.push(candidateFor(manifest, reason, prerequisites, risk));
  };
  if (counts) add('sample-metadata-validator', '先验证 counts 与 metadata 的样本对齐、分组和重复数，避免把文件名当作实验设计。', ['counts', 'metadata', 'contrast'], ['分组列缺失时必须阻断']);
  if (counts) add('expression-qc', 'counts 结构已被定位，先做有界质量检查，再决定是否进入差异分析。', ['counts'], ['QC 不会自动删除样本']);
  if (counts && (taskSpec.question?.questionType === 'differential_expression' || taskSpec.method?.category === 'bulk RNA-seq' || taskSpec.originalRequest)) {
    add('deseq2', '用户目标涉及处理组与对照组的差异，且 counts 是适合该模块的输入；正式运行前仍需确认 contrast。', ['validated_metadata', 'qc_summary', 'contrast'], ['结果显著性必须来自实际结果表，不能由规划器推断', 'contrast_ref/contrast_treat 来自 sample-metadata-validator，不来自 Agent 猜测']);
  }
  const downstream = normalizedPlugins.filter((item) => ['go-kegg', 'gsea', 'volcano-plot', 'pca-explorer'].includes(item.id));
  for (const manifest of downstream) {
    candidates.push(candidateFor(manifest, '作为差异结果或 QC artifact 的下游展示/功能解释模块，必须绑定已验证上游 Artifact。', ['verified_upstream_artifact'], ['不能直接消费聊天文本或未验证文件']));
  }

  let status = STATUS.READY;
  if (gaps.some((gap) => ['contrast_column_missing', 'counts_input_missing'].includes(gap.code))) status = STATUS.CANNOT_ANSWER;
  else if (gaps.length) status = STATUS.NEEDS_DECISION;
  if (!candidates.length) status = STATUS.NO_METHOD;

  const recommendation = candidates[0] || null;
  return {
    schemaVersion: 1,
    planner: 'scientific-task-planner',
    status,
    taskRef: { taskId: taskSpec.taskId || null, projectId: taskSpec.projectId || null, conversationId: taskSpec.conversationId || null },
    evidence: mappedInputs,
    runtime: runtime ? { status: text(runtime.status) || 'unknown', version: text(runtime.version) || null, source: text(runtime.source) || 'runtime_probe' } : null,
    candidates,
    recommendation,
    coldataBinding, // HLE-C5R: explicit metadata→coldata binding
    gaps,
    diagnostics,
    execution: { createsToolJob: false, requiresConfirmation: status === STATUS.READY || status === STATUS.NEEDS_DECISION },
    next: status === STATUS.CANNOT_ANSWER ? '补充分组/contrast 或可识别的 metadata 证据后重新规划。' : status === STATUS.NO_METHOD ? '安装或开发声明了该输入/产物契约的插件。' : '审阅推荐方案、输入快照和风险后再进入确认门。',
  };
}

function planScientificTaskFromIndex({ taskSpec, index, manifests = [], runtime = null } = {}) {
  return planScientificTask({
    taskSpec,
    evidence: evidenceFromIndex(index),
    plugins: manifests,
    runtime,
  });
}

module.exports = { STATUS, normalizeEvidence, evidenceFromIndex, planScientificTask, planScientificTaskFromIndex };

'use strict';

const crypto = require('crypto');
const { stableValue, stableStringify } = require('./canonical-json');
const path = require('path');
const { redactSensitiveValue } = require('./redaction');

const SCIENTIFIC_TASK_SPEC_VERSION = 1;
const CONVERSATION_CONTEXT_ENVELOPE_VERSION = 1;
const CONTEXT_CHECKPOINT_VERSION = 1;

const TASK_STATUSES = Object.freeze([
  'draft',
  'requires_user_decision',
  'ready_for_confirmation',
  'confirmed',
  'running',
  'completed',
  'blocked',
  'cancelled',
]);
const INTERACTION_MODES = Object.freeze([
  'conversation',
  'context_assist',
  'task_draft',
  'task_execute',
  'replay',
]);
// BLOCK-56 P2 — 新增 'workspace-write' 中间档（additive：read/full 原值不变）。
// 语义矩阵见 docs/block-56-reliability-depth-plan.md 附录 A：
//   read = 只读；workspace-write = 项目内写 + 前台命令（黑名单+cwd 限项目根）；
//   full = 完全访问（含后台进程/插件委托/系统写面）。
const ACCESS_MODES = Object.freeze(['read', 'workspace-write', 'full']);
const AUTOMATION_MODES = Object.freeze(['guided', 'confirm', 'trusted']);
const EXPLANATION_LEVELS = Object.freeze(['concise', 'guided', 'technical']);
const CONFIDENCE_LEVELS = Object.freeze(['unknown', 'low', 'medium', 'high']);

const STATUS_TRANSITIONS = Object.freeze({
  draft: Object.freeze(['requires_user_decision', 'ready_for_confirmation', 'cancelled']),
  requires_user_decision: Object.freeze(['draft', 'ready_for_confirmation', 'cancelled']),
  ready_for_confirmation: Object.freeze(['requires_user_decision', 'confirmed', 'cancelled']),
  confirmed: Object.freeze(['running', 'cancelled']),
  running: Object.freeze(['completed', 'blocked', 'cancelled']),
  blocked: Object.freeze(['draft', 'requires_user_decision', 'cancelled']),
  completed: Object.freeze([]),
  cancelled: Object.freeze([]),
});

const PRIVATE_REASONING_KEYS = new Set([
  'chainOfThought',
  'chain_of_thought',
  'privateReasoning',
  'private_reasoning',
  'hiddenThoughts',
  'hidden_thoughts',
]);

function sha256(value) {
  return crypto.createHash('sha256').update(value).digest('hex');
}

// BLOCK-83 D1：stableStringify/stableValue 上提至通用模块 canonical-json（原位 re-export 保持兼容）。

function stringValue(value, fallback = '') {
  return typeof value === 'string' ? value.trim() : fallback;
}

function nullableString(value) {
  const normalized = stringValue(value);
  return normalized || null;
}

function finiteNumber(value, fallback = 0) {
  const number = Number(value);
  return Number.isFinite(number) ? number : fallback;
}

function positiveInteger(value, fallback = 1) {
  const number = Number(value);
  return Number.isInteger(number) && number > 0 ? number : fallback;
}

function uniqueStrings(values, { sort = true } = {}) {
  const output = [...new Set((Array.isArray(values) ? values : []).map((item) => stringValue(item)).filter(Boolean))];
  return sort ? output.sort() : output;
}

function normalizeRelativePath(value) {
  const raw = stringValue(value).replace(/\\/g, '/');
  if (!raw) return '';
  if (/^[A-Za-z]:\//.test(raw) || raw.startsWith('/')) return raw;
  const normalized = path.posix.normalize(raw);
  return normalized === '.' ? '' : normalized.replace(/^\.\//, '');
}

function isSafeRelativePath(value) {
  if (typeof value !== 'string' || !value) return false;
  if (value.includes('\0') || value.startsWith('/') || /^[A-Za-z]:[\\/]/.test(value)) return false;
  const normalized = value.replace(/\\/g, '/');
  return !normalized.split('/').includes('..') && path.posix.normalize(normalized) === normalized;
}

function normalizeDecision(value, index = 0) {
  if (typeof value === 'string') {
    return {
      id: `decision_${index + 1}`,
      question: value.trim(),
      reason: '',
      required: true,
      options: [],
      status: 'unresolved',
      answer: null,
    };
  }
  const item = value && typeof value === 'object' ? value : {};
  return {
    id: stringValue(item.id, `decision_${index + 1}`),
    question: stringValue(item.question),
    reason: stringValue(item.reason),
    required: item.required !== false,
    options: uniqueStrings(item.options),
    status: ['unresolved', 'confirmed', 'rejected'].includes(item.status) ? item.status : 'unresolved',
    answer: item.answer == null ? null : redactSensitiveValue(item.answer),
  };
}

function normalizeInput(value) {
  const item = value && typeof value === 'object' ? value : {};
  return {
    id: nullableString(item.id),
    role: nullableString(item.role),
    relativePath: normalizeRelativePath(item.relativePath),
    sha256: nullableString(item.sha256)?.toLowerCase() || null,
    sizeBytes: Math.max(0, finiteNumber(item.sizeBytes, 0)),
    schemaSummary: item.schemaSummary && typeof item.schemaSummary === 'object'
      ? redactSensitiveValue(item.schemaSummary)
      : {},
    sourceArtifactRef: nullableString(item.sourceArtifactRef),
  };
}

function unresolvedDecisions(spec) {
  return [
    ...(spec.design?.unresolved || []),
    ...(spec.requiresUserDecision || []).filter((item) => item.required && item.status === 'unresolved'),
  ];
}

function deriveScientificTaskStatus(spec) {
  if (unresolvedDecisions(spec).length > 0) return 'requires_user_decision';
  if (spec.status && TASK_STATUSES.includes(spec.status)) return spec.status;
  return 'draft';
}

function normalizeScientificTaskSpec(input = {}) {
  const source = redactSensitiveValue(input && typeof input === 'object' ? input : {});
  const normalized = {
    schemaVersion: SCIENTIFIC_TASK_SPEC_VERSION,
    taskId: stringValue(source.taskId),
    projectId: stringValue(source.projectId),
    conversationId: stringValue(source.conversationId),
    originalRequest: stringValue(source.originalRequest),
    question: {
      domain: stringValue(source.question?.domain),
      analysisUnit: stringValue(source.question?.analysisUnit),
      questionType: stringValue(source.question?.questionType),
    },
    inputs: (Array.isArray(source.inputs) ? source.inputs : [])
      .map(normalizeInput)
      .sort((left, right) => `${left.relativePath}:${left.role || ''}`.localeCompare(`${right.relativePath}:${right.role || ''}`)),
    design: {
      groups: uniqueStrings(source.design?.groups),
      contrast: source.design?.contrast && typeof source.design.contrast === 'object'
        ? stableValue(redactSensitiveValue(source.design.contrast))
        : {},
      covariates: uniqueStrings(source.design?.covariates),
      replicates: source.design?.replicates && typeof source.design.replicates === 'object'
        ? stableValue(redactSensitiveValue(source.design.replicates))
        : {},
      assumptions: uniqueStrings(source.design?.assumptions),
      unresolved: uniqueStrings(source.design?.unresolved),
    },
    method: {
      category: stringValue(source.method?.category),
      candidateToolIds: uniqueStrings(source.method?.candidateToolIds),
      selectionReason: stringValue(source.method?.selectionReason),
    },
    requestedDeliverables: uniqueStrings(source.requestedDeliverables),
    acceptanceCriteria: uniqueStrings(source.acceptanceCriteria),
    requiresUserDecision: (Array.isArray(source.requiresUserDecision) ? source.requiresUserDecision : [])
      .map(normalizeDecision)
      .sort((left, right) => left.id.localeCompare(right.id)),
    clarification: {
      questionsAsked: uniqueStrings(source.clarification?.questionsAsked, { sort: false }),
      confidence: CONFIDENCE_LEVELS.includes(source.clarification?.confidence)
        ? source.clarification.confidence
        : 'unknown',
      userDecisions: Array.isArray(source.clarification?.userDecisions)
        ? redactSensitiveValue(source.clarification.userDecisions)
        : [],
    },
    execution: {
      accessMode: ACCESS_MODES.includes(source.execution?.accessMode) ? source.execution.accessMode : 'read',
      automationMode: AUTOMATION_MODES.includes(source.execution?.automationMode)
        ? source.execution.automationMode
        : 'guided',
      decisionPolicyVersion: positiveInteger(source.execution?.decisionPolicyVersion, 1),
      resourcePolicyVersion: positiveInteger(source.execution?.resourcePolicyVersion, 1),
      resourceSnapshotRef: nullableString(source.execution?.resourceSnapshotRef),
    },
    presentation: {
      language: stringValue(source.presentation?.language, 'zh-CN'),
      explanationLevel: EXPLANATION_LEVELS.includes(source.presentation?.explanationLevel)
        ? source.presentation.explanationLevel
        : 'guided',
    },
    status: TASK_STATUSES.includes(source.status) ? source.status : 'draft',
  };
  normalized.status = deriveScientificTaskStatus(normalized);
  return normalized;
}

function diagnostic(code, pathValue, message) {
  return { code, path: pathValue, message };
}

function privateReasoningPaths(value, prefix = '', ancestors = new WeakSet()) {
  if (!value || typeof value !== 'object' || ancestors.has(value)) return [];
  ancestors.add(value);
  try {
    const paths = [];
    for (const [key, child] of Object.entries(value)) {
      const childPath = prefix ? `${prefix}.${key}` : key;
      if (PRIVATE_REASONING_KEYS.has(key)) paths.push(childPath);
      paths.push(...privateReasoningPaths(child, childPath, ancestors));
    }
    return paths;
  } finally {
    ancestors.delete(value);
  }
}

function validateScientificTaskSpec(input, options = {}) {
  const raw = input && typeof input === 'object' ? input : {};
  const spec = options.normalized === true ? input : normalizeScientificTaskSpec(input);
  const issues = [];
  const requireText = (value, field) => {
    if (typeof value !== 'string' || value.length === 0) issues.push(diagnostic('required', field, `${field} is required`));
  };
  requireText(spec.taskId, 'taskId');
  requireText(spec.projectId, 'projectId');
  requireText(spec.conversationId, 'conversationId');
  requireText(spec.originalRequest, 'originalRequest');
  requireText(spec.question.domain, 'question.domain');
  requireText(spec.question.analysisUnit, 'question.analysisUnit');
  requireText(spec.question.questionType, 'question.questionType');
  requireText(spec.method.category, 'method.category');
  if (raw.schemaVersion !== SCIENTIFIC_TASK_SPEC_VERSION) issues.push(diagnostic('schema_version_unsupported', 'schemaVersion', 'ScientificTaskSpec schemaVersion must be 1'));
  if (raw.status !== undefined && !TASK_STATUSES.includes(raw.status)) issues.push(diagnostic('task_status_invalid', 'status', 'Unknown task status'));
  if (raw.execution?.accessMode !== undefined && !ACCESS_MODES.includes(raw.execution.accessMode)) issues.push(diagnostic('access_mode_invalid', 'execution.accessMode', 'Unknown access mode'));
  if (raw.execution?.automationMode !== undefined && !AUTOMATION_MODES.includes(raw.execution.automationMode)) issues.push(diagnostic('automation_mode_invalid', 'execution.automationMode', 'Unknown automation mode'));
  if (!Array.isArray(spec.inputs) || spec.inputs.length === 0) issues.push(diagnostic('inputs_required', 'inputs', 'At least one input snapshot is required'));
  for (const [index, item] of (Array.isArray(raw.inputs) ? raw.inputs : []).entries()) {
    if (!Number.isFinite(Number(item?.sizeBytes)) || Number(item.sizeBytes) < 0) issues.push(diagnostic('input_size_invalid', `inputs[${index}].sizeBytes`, 'sizeBytes must be an explicit non-negative number'));
  }
  for (const [index, item] of spec.inputs.entries()) {
    if (!isSafeRelativePath(item.relativePath)) issues.push(diagnostic('input_path_invalid', `inputs[${index}].relativePath`, 'Input paths must be normalized repository/project-relative paths'));
    if (item.sha256 !== null && !/^[a-f0-9]{64}$/.test(item.sha256)) issues.push(diagnostic('input_hash_invalid', `inputs[${index}].sha256`, 'sha256 must be 64 lowercase hex or null'));
    if (!Number.isFinite(item.sizeBytes) || item.sizeBytes < 0) issues.push(diagnostic('input_size_invalid', `inputs[${index}].sizeBytes`, 'sizeBytes must be non-negative'));
  }
  if (!TASK_STATUSES.includes(spec.status)) issues.push(diagnostic('task_status_invalid', 'status', 'Unknown task status'));
  const pending = unresolvedDecisions(spec);
  if (pending.length > 0 && !['draft', 'requires_user_decision', 'blocked'].includes(spec.status)) {
    issues.push(diagnostic('unresolved_decision_blocks_execution', 'status', 'Unresolved scientific decisions prevent confirmation or execution'));
  }
  if (spec.status === 'requires_user_decision' && pending.length === 0) {
    issues.push(diagnostic('decision_status_without_decision', 'status', 'requires_user_decision needs at least one unresolved decision'));
  }
  if (['confirmed', 'running', 'completed'].includes(spec.status)) {
    for (const [index, item] of spec.inputs.entries()) {
      if (!item.sha256) issues.push(diagnostic('confirmed_input_hash_required', `inputs[${index}].sha256`, 'Confirmed tasks require immutable input hashes'));
    }
  }
  for (const reasoningPath of privateReasoningPaths(raw)) issues.push(diagnostic('private_reasoning_forbidden', reasoningPath, 'Private reasoning must not be persisted in ScientificTaskSpec'));
  return { ok: issues.length === 0, spec, issues };
}

function hashScientificTaskSpec(input) {
  const result = validateScientificTaskSpec(input);
  if (!result.ok) {
    const error = new Error('scientific_task_spec_invalid');
    error.code = 'scientific_task_spec_invalid';
    error.issues = result.issues;
    throw error;
  }
  return sha256(stableStringify(result.spec));
}

function transitionScientificTaskSpec(input, nextStatus) {
  const result = validateScientificTaskSpec(input);
  if (!result.ok) return { ok: false, error: 'scientific_task_spec_invalid', issues: result.issues };
  if (!TASK_STATUSES.includes(nextStatus)) return { ok: false, error: 'task_status_invalid', from: result.spec.status, to: nextStatus };
  const allowed = STATUS_TRANSITIONS[result.spec.status] || [];
  if (!allowed.includes(nextStatus)) return { ok: false, error: 'task_transition_not_allowed', from: result.spec.status, to: nextStatus, allowed: [...allowed] };
  const candidate = { ...result.spec, status: nextStatus };
  const normalized = normalizeScientificTaskSpec(candidate);
  if (normalized.status !== nextStatus) {
    return { ok: false, error: 'unresolved_decision_blocks_execution', from: result.spec.status, to: nextStatus, status: normalized.status };
  }
  const validated = validateScientificTaskSpec(normalized, { normalized: true });
  if (!validated.ok) return { ok: false, error: 'scientific_task_spec_invalid', issues: validated.issues };
  return { ok: true, spec: normalized, from: result.spec.status, to: nextStatus, specHash: hashScientificTaskSpec(normalized) };
}

function shouldCreateScientificTaskSpec(context = {}) {
  return ['task_draft', 'task_execute', 'replay'].includes(context.interactionMode) && context.explicitTaskIntent === true;
}

function normalizeEvidence(value) {
  const item = value && typeof value === 'object' ? value : {};
  return {
    source: stringValue(item.source),
    relativePath: normalizeRelativePath(item.relativePath),
    startLine: Math.max(1, positiveInteger(item.startLine, 1)),
    endLine: Math.max(1, positiveInteger(item.endLine, 1)),
    sha256: nullableString(item.sha256)?.toLowerCase() || null,
    capturedAt: nullableString(item.capturedAt),
    truncated: item.truncated === true,
  };
}

function normalizeConversationContextEnvelope(input = {}) {
  const source = redactSensitiveValue(input && typeof input === 'object' ? input : {});
  return {
    schemaVersion: CONVERSATION_CONTEXT_ENVELOPE_VERSION,
    projectId: stringValue(source.projectId),
    conversationId: stringValue(source.conversationId),
    interactionMode: INTERACTION_MODES.includes(source.interactionMode) ? source.interactionMode : 'conversation',
    currentIntent: stringValue(source.currentIntent),
    explicitFileRefs: uniqueStrings(source.explicitFileRefs).map(normalizeRelativePath),
    recentMessageIds: uniqueStrings(source.recentMessageIds, { sort: false }),
    conversationSummaryRef: nullableString(source.conversationSummaryRef),
    taskRef: nullableString(source.taskRef),
    activePlanRef: nullableString(source.activePlanRef),
    activeJobRef: nullableString(source.activeJobRef),
    activeArtifactRef: nullableString(source.activeArtifactRef),
    unresolvedDecisions: (Array.isArray(source.unresolvedDecisions) ? source.unresolvedDecisions : []).map(normalizeDecision),
    evidence: (Array.isArray(source.evidence) ? source.evidence : []).map(normalizeEvidence),
    modelContext: {
      profileId: stringValue(source.modelContext?.profileId),
      contextWindow: Math.max(0, finiteNumber(source.modelContext?.contextWindow, 0)),
      maxOutput: Math.max(0, finiteNumber(source.modelContext?.maxOutput, 0)),
      capabilitySnapshotHash: nullableString(source.modelContext?.capabilitySnapshotHash)?.toLowerCase() || null,
      estimatorVersion: positiveInteger(source.modelContext?.estimatorVersion, 1),
    },
    contextBudget: {
      maxUnits: Math.max(0, finiteNumber(source.contextBudget?.maxUnits, 0)),
      usedUnits: Math.max(0, finiteNumber(source.contextBudget?.usedUnits, 0)),
      reservedOutput: Math.max(0, finiteNumber(source.contextBudget?.reservedOutput, 0)),
      safetyMargin: Math.max(0, finiteNumber(source.contextBudget?.safetyMargin, 0)),
    },
    invalidation: {
      projectVersion: nullableString(source.invalidation?.projectVersion),
      conversationVersion: nullableString(source.invalidation?.conversationVersion),
      taskSpecHash: nullableString(source.invalidation?.taskSpecHash)?.toLowerCase() || null,
      evidenceDigest: nullableString(source.invalidation?.evidenceDigest)?.toLowerCase() || null,
    },
    accessMode: ACCESS_MODES.includes(source.accessMode) ? source.accessMode : 'read',
    automationMode: AUTOMATION_MODES.includes(source.automationMode) ? source.automationMode : 'guided',
  };
}

function validateConversationContextEnvelope(input, options = {}) {
  const raw = input && typeof input === 'object' ? input : {};
  const envelope = options.normalized === true ? input : normalizeConversationContextEnvelope(input);
  const issues = [];
  if (raw.schemaVersion !== CONVERSATION_CONTEXT_ENVELOPE_VERSION) issues.push(diagnostic('schema_version_unsupported', 'schemaVersion', 'ConversationContextEnvelope schemaVersion must be 1'));
  if (raw.interactionMode !== undefined && !INTERACTION_MODES.includes(raw.interactionMode)) issues.push(diagnostic('interaction_mode_invalid', 'interactionMode', 'Unknown interaction mode'));
  if (raw.accessMode !== undefined && !ACCESS_MODES.includes(raw.accessMode)) issues.push(diagnostic('access_mode_invalid', 'accessMode', 'Unknown access mode'));
  if (raw.automationMode !== undefined && !AUTOMATION_MODES.includes(raw.automationMode)) issues.push(diagnostic('automation_mode_invalid', 'automationMode', 'Unknown automation mode'));
  if (!envelope.projectId) issues.push(diagnostic('required', 'projectId', 'projectId is required'));
  if (!envelope.conversationId) issues.push(diagnostic('required', 'conversationId', 'conversationId is required'));
  if (!INTERACTION_MODES.includes(envelope.interactionMode)) issues.push(diagnostic('interaction_mode_invalid', 'interactionMode', 'Unknown interaction mode'));
  if (envelope.interactionMode === 'conversation' && envelope.taskRef !== null) issues.push(diagnostic('conversation_task_ref_forbidden', 'taskRef', 'Ordinary conversation must not create or attach a new task'));
  for (const [index, ref] of envelope.explicitFileRefs.entries()) {
    if (!isSafeRelativePath(ref)) issues.push(diagnostic('file_ref_invalid', `explicitFileRefs[${index}]`, 'File references must be relative'));
  }
  for (const [index, item] of envelope.evidence.entries()) {
    if (!item.source) issues.push(diagnostic('evidence_source_required', `evidence[${index}].source`, 'Evidence source is required'));
    if (!isSafeRelativePath(item.relativePath)) issues.push(diagnostic('evidence_path_invalid', `evidence[${index}].relativePath`, 'Evidence paths must be relative'));
    if (!item.sha256 || !/^[a-f0-9]{64}$/.test(item.sha256)) issues.push(diagnostic('evidence_hash_invalid', `evidence[${index}].sha256`, 'Evidence requires a SHA-256'));
    if (item.endLine < item.startLine) issues.push(diagnostic('evidence_range_invalid', `evidence[${index}]`, 'endLine must not precede startLine'));
    if (!item.capturedAt || Number.isNaN(Date.parse(item.capturedAt))) issues.push(diagnostic('evidence_time_invalid', `evidence[${index}].capturedAt`, 'capturedAt must be an ISO timestamp'));
  }
  const budget = envelope.contextBudget;
  if (budget.maxUnits <= 0) issues.push(diagnostic('context_budget_required', 'contextBudget.maxUnits', 'A positive context budget is required'));
  if (budget.usedUnits + budget.reservedOutput + budget.safetyMargin > budget.maxUnits) issues.push(diagnostic('context_budget_exceeded', 'contextBudget', 'Used, reserved, and safety units exceed maxUnits'));
  if (envelope.modelContext.contextWindow <= 0) issues.push(diagnostic('model_context_window_required', 'modelContext.contextWindow', 'A positive model context window is required'));
  if (!envelope.modelContext.profileId) issues.push(diagnostic('model_profile_required', 'modelContext.profileId', 'Model profile is required'));
  for (const [field, value] of [
    ['modelContext.capabilitySnapshotHash', envelope.modelContext.capabilitySnapshotHash],
    ['invalidation.taskSpecHash', envelope.invalidation.taskSpecHash],
    ['invalidation.evidenceDigest', envelope.invalidation.evidenceDigest],
  ]) {
    if (value !== null && !/^[a-f0-9]{64}$/.test(value)) issues.push(diagnostic('context_hash_invalid', field, `${field} must be a SHA-256 or null`));
  }
  return { ok: issues.length === 0, envelope, issues };
}

function hashConversationContextEnvelope(input) {
  const result = validateConversationContextEnvelope(input);
  if (!result.ok) {
    const error = new Error('conversation_context_envelope_invalid');
    error.code = 'conversation_context_envelope_invalid';
    error.issues = result.issues;
    throw error;
  }
  return sha256(stableStringify(result.envelope));
}

function sourceMessageDigest(messages = []) {
  const normalized = (Array.isArray(messages) ? messages : []).map((item) => ({
    id: stringValue(item?.id),
    role: stringValue(item?.role),
    contentSha256: sha256(String(item?.content || '')),
  }));
  return sha256(stableStringify(normalized));
}

function normalizeContextCheckpoint(input = {}) {
  const source = redactSensitiveValue(input && typeof input === 'object' ? input : {});
  const normalizeRefList = (value) => uniqueStrings(value);
  return {
    schemaVersion: CONTEXT_CHECKPOINT_VERSION,
    checkpointId: stringValue(source.checkpointId),
    projectId: stringValue(source.projectId),
    conversationId: stringValue(source.conversationId),
    sourceMessageRange: {
      firstId: stringValue(source.sourceMessageRange?.firstId),
      lastId: stringValue(source.sourceMessageRange?.lastId),
      count: Math.max(0, finiteNumber(source.sourceMessageRange?.count, 0)),
    },
    sourceDigest: nullableString(source.sourceDigest)?.toLowerCase() || null,
    policyVersion: positiveInteger(source.policyVersion, 1),
    generatedBy: {
      mode: ['deterministic', 'deterministic+summary'].includes(source.generatedBy?.mode)
        ? source.generatedBy.mode
        : 'deterministic',
      modelProfileId: nullableString(source.generatedBy?.modelProfileId),
      rulesVersion: positiveInteger(source.generatedBy?.rulesVersion, 1),
    },
    summary: stringValue(source.summary),
    taskRefs: normalizeRefList(source.taskRefs),
    confirmedDecisions: Array.isArray(source.confirmedDecisions) ? redactSensitiveValue(source.confirmedDecisions) : [],
    rejectedOptions: Array.isArray(source.rejectedOptions) ? redactSensitiveValue(source.rejectedOptions) : [],
    unresolvedDecisions: (Array.isArray(source.unresolvedDecisions) ? source.unresolvedDecisions : []).map(normalizeDecision),
    constraints: Array.isArray(source.constraints) ? redactSensitiveValue(source.constraints) : [],
    evidenceRefs: normalizeRefList(source.evidenceRefs),
    toolTraceRefs: normalizeRefList(source.toolTraceRefs),
    jobRefs: normalizeRefList(source.jobRefs),
    artifactRefs: normalizeRefList(source.artifactRefs),
    editManifestRefs: normalizeRefList(source.editManifestRefs),
    supersedes: nullableString(source.supersedes),
    coverage: {
      requiredFieldsPresent: source.coverage?.requiredFieldsPresent === true,
      missing: uniqueStrings(source.coverage?.missing),
    },
    createdAt: nullableString(source.createdAt),
  };
}

function validateContextCheckpoint(input, options = {}) {
  const raw = input && typeof input === 'object' ? input : {};
  const checkpoint = options.normalized === true ? input : normalizeContextCheckpoint(input);
  const issues = [];
  if (raw.schemaVersion !== CONTEXT_CHECKPOINT_VERSION) issues.push(diagnostic('schema_version_unsupported', 'schemaVersion', 'ContextCheckpoint schemaVersion must be 1'));
  if (raw.generatedBy?.mode !== undefined && !['deterministic', 'deterministic+summary'].includes(raw.generatedBy.mode)) issues.push(diagnostic('checkpoint_generator_mode_invalid', 'generatedBy.mode', 'Unknown checkpoint generator mode'));
  for (const field of ['checkpointId', 'projectId', 'conversationId']) {
    if (!checkpoint[field]) issues.push(diagnostic('required', field, `${field} is required`));
  }
  if (!checkpoint.sourceMessageRange.firstId || !checkpoint.sourceMessageRange.lastId || !Number.isInteger(checkpoint.sourceMessageRange.count) || checkpoint.sourceMessageRange.count <= 0) issues.push(diagnostic('source_message_range_invalid', 'sourceMessageRange', 'A non-empty integer source message range is required'));
  if (!checkpoint.sourceDigest || !/^[a-f0-9]{64}$/.test(checkpoint.sourceDigest)) issues.push(diagnostic('source_digest_invalid', 'sourceDigest', 'sourceDigest must be a SHA-256'));
  if (checkpoint.generatedBy.mode === 'deterministic+summary' && !checkpoint.generatedBy.modelProfileId) issues.push(diagnostic('summary_model_profile_required', 'generatedBy.modelProfileId', 'Summary-assisted checkpoints must identify the model profile'));
  if (checkpoint.supersedes === checkpoint.checkpointId) issues.push(diagnostic('checkpoint_self_supersede', 'supersedes', 'A checkpoint cannot supersede itself'));
  if (checkpoint.coverage.requiredFieldsPresent && checkpoint.coverage.missing.length > 0) issues.push(diagnostic('checkpoint_coverage_inconsistent', 'coverage', 'Coverage cannot be complete while fields are missing'));
  if (!checkpoint.createdAt || Number.isNaN(Date.parse(checkpoint.createdAt))) issues.push(diagnostic('checkpoint_time_invalid', 'createdAt', 'createdAt must be an ISO timestamp'));
  return { ok: issues.length === 0, checkpoint, issues };
}

function validateCheckpointSupersession(currentInput, previousInput) {
  const current = validateContextCheckpoint(currentInput);
  const previous = validateContextCheckpoint(previousInput);
  if (!current.ok || !previous.ok) return { ok: false, error: 'checkpoint_invalid', issues: [...current.issues, ...previous.issues] };
  if (current.checkpoint.projectId !== previous.checkpoint.projectId || current.checkpoint.conversationId !== previous.checkpoint.conversationId) return { ok: false, error: 'checkpoint_scope_mismatch' };
  if (current.checkpoint.supersedes !== previous.checkpoint.checkpointId) return { ok: false, error: 'checkpoint_supersedes_mismatch' };
  if (current.checkpoint.sourceMessageRange.count < previous.checkpoint.sourceMessageRange.count) return { ok: false, error: 'checkpoint_source_range_regression' };
  if (Date.parse(current.checkpoint.createdAt) < Date.parse(previous.checkpoint.createdAt)) return { ok: false, error: 'checkpoint_time_regression' };
  return { ok: true, checkpoint: current.checkpoint };
}

function shouldRereadCheckpointSource(request = {}) {
  return request.requiresExactEvidence === true || ['exact_quote', 'exact_parameter', 'exact_file_content', 'tool_failure_detail'].includes(request.questionType);
}

module.exports = {
  stableStringify,
  stableValue,
  SCIENTIFIC_TASK_SPEC_VERSION,
  CONVERSATION_CONTEXT_ENVELOPE_VERSION,
  CONTEXT_CHECKPOINT_VERSION,
  TASK_STATUSES,
  STATUS_TRANSITIONS,
  INTERACTION_MODES,
  ACCESS_MODES,
  AUTOMATION_MODES,
  normalizeScientificTaskSpec,
  validateScientificTaskSpec,
  hashScientificTaskSpec,
  deriveScientificTaskStatus,
  transitionScientificTaskSpec,
  shouldCreateScientificTaskSpec,
  normalizeConversationContextEnvelope,
  validateConversationContextEnvelope,
  hashConversationContextEnvelope,
  sourceMessageDigest,
  normalizeContextCheckpoint,
  validateContextCheckpoint,
  validateCheckpointSupersession,
  shouldRereadCheckpointSource,
  stableStringify,
  isSafeRelativePath,
};

/**
 * shared-backend/skill-registry.js — Skills 注册与发现机制
 *
 * 实现四层架构中的 Layer 4: Skills 层的注册与发现能力。
 * 支持三来源发现：built-in(10) / installed(20) / marketplace(30)
 *
 * 设计依据：
 * - docs/skills-architecture.md — 四层架构设计
 * - docs/skills-registry.md — 注册与发现机制详细设计
 * - docs/skills-schema.md — Skill Manifest Schema
 */

const fs = require('fs');
const path = require('path');

// ── 常量定义 ────────────────────────────────────────────────────────────────

/** Skill 来源优先级（数值越小优先级越高） */
const SOURCE_PRIORITY = {
  'built-in': 10,
  'installed': 20,
  'marketplace': 30,
};

/** Skill Manifest 版本 */
const SKILL_MANIFEST_VERSION = 1;

/** 可选的参数类型 */
const PARAM_TYPES = new Set(['select', 'number', 'string', 'boolean', 'file']);

/** 可选的输出类型 */
const OUTPUT_TYPES = new Set(['plot', 'table', 'html', 'json', 'text', 'file']);

// ── 内存注册表 ─────────────────────────────────────────────────────────────

/** @type {Map<string, SkillEntry>} */
const _registry = new Map();

/** @type {Map<string, string>} skillId → source */
const _sourceMap = new Map();

/** 缓存的 marketplace manifest */
let _marketplaceCache = null;
let _marketplaceCacheTime = 0;
const MARKETPLACE_CACHE_TTL = 24 * 60 * 60 * 1000; // 24 小时

// ── 内置 Skill 清单（来自 resources/skills/manifest.json） ────────────────────

/** 内置 Skill 目录 */
const BUILT_IN_SKILLS_DIR = path.join(__dirname, '..', '..', 'resources', 'skills');

/** 内置 manifest 路径 */
const BUILT_IN_MANIFEST_PATH = path.join(BUILT_IN_SKILLS_DIR, 'manifest.json');

// ── 工具函数 ────────────────────────────────────────────────────────────────

/**
 * 读取并解析 JSON 文件
 * @param {string} filePath - 文件路径
 * @returns {object|null}
 */
function readJson(filePath) {
  try {
    if (!fs.existsSync(filePath)) return null;
    return JSON.parse(fs.readFileSync(filePath, 'utf8'));
  } catch (e) {
    console.warn(`[skill-registry] Failed to read JSON from ${filePath}: ${e.message}`);
    return null;
  }
}

/**
 * 深度合并对象
 * @param {object} target - 目标对象
 * @param {object} source - 源对象
 * @returns {object}
 */
function deepMerge(target, source) {
  const result = { ...target };
  for (const key of Object.keys(source)) {
    if (source[key] && typeof source[key] === 'object' && !Array.isArray(source[key])) {
      result[key] = deepMerge(result[key] || {}, source[key]);
    } else {
      result[key] = source[key];
    }
  }
  return result;
}

/**
 * 检查字符串是否符合 semver 格式
 * @param {string} version
 * @returns {boolean}
 */
function isValidSemver(version) {
  return /^\d+\.\d+\.\d+(-[a-z0-9.]+)?$/.test(version);
}

/**
 * 规范化 Skill ID（kebab-case）
 * @param {string} id
 * @returns {boolean}
 */
function isValidSkillId(id) {
  return /^[a-z][a-z0-9-]*$/.test(id);
}

// ── Manifest 解析与校验 ────────────────────────────────────────────────────

/**
 * 解析 Skill Manifest
 * @param {object} manifest - 原始 manifest 对象
 * @param {string} source - 来源类型
 * @param {string} baseDir - 基础目录
 * @returns {SkillEntry|null}
 */
function parseSkillManifest(manifest, source, baseDir) {
  if (!manifest || manifest.skillManifestVersion !== SKILL_MANIFEST_VERSION) {
    return null;
  }

  const { id, name, version, description, category, tags = [], capabilities = [],
    plugins = {}, workflows = {}, prompts = {}, parameters = {},
    recovery_strategies = [], outputs = {}, metadata = {} } = manifest;

  // 基本字段校验
  if (!id || !name || !version || !description) {
    return null;
  }

  // ID 格式校验
  if (!isValidSkillId(id)) {
    console.warn(`[skill-registry] Invalid skill ID format: ${id}`);
    return null;
  }

  // 解析 Prompt 模板文件（如果存在）
  const parsedPrompts = { ...prompts };
  if (prompts.system_file && baseDir) {
    const systemPath = path.join(baseDir, prompts.system_file);
    if (fs.existsSync(systemPath)) {
      parsedPrompts.system = fs.readFileSync(systemPath, 'utf8');
    }
  }

  return {
    id,
    name,
    version,
    source,
    category: category || 'general',
    tags: Array.isArray(tags) ? tags : [],
    description,
    capabilities: Array.isArray(capabilities) ? capabilities : [],
    plugins: {
      required: Array.isArray(plugins.required) ? plugins.required : [],
      optional: Array.isArray(plugins.optional) ? plugins.optional : [],
    },
    workflows: {
      default: workflows.default || null,
      variants: Array.isArray(workflows.variants) ? workflows.variants : [],
    },
    prompts: parsedPrompts,
    parameters: {
      required: Array.isArray(parameters.required) ? parameters.required : [],
      optional: parameters.optional || {},
    },
    recoveryStrategies: Array.isArray(recovery_strategies) ? recovery_strategies : [],
    outputs: {
      primary: Array.isArray(outputs.primary) ? outputs.primary : [],
      secondary: Array.isArray(outputs.secondary) ? outputs.secondary : [],
    },
    metadata: {
      author: metadata.author || 'Petri Team',
      license: metadata.license || 'MIT',
      source: metadata.source || source,
      created: metadata.created || new Date().toISOString().split('T')[0],
      updated: metadata.updated || new Date().toISOString().split('T')[0],
      compatibility: metadata.compatibility || {},
    },
    _baseDir: baseDir,
  };
}

/**
 * 校验 Skill Manifest 完整性
 * @param {SkillEntry} skill
 * @returns {{ ok: boolean, errors: string[] }}
 */
function validateSkillManifest(skill) {
  const errors = [];

  if (!skill.id) errors.push('Missing required field: id');
  if (!skill.name) errors.push('Missing required field: name');
  if (!skill.version) errors.push('Missing required field: version');
  if (!skill.description) errors.push('Missing required field: description');

  if (skill.id && !isValidSkillId(skill.id)) {
    errors.push(`Invalid ID format: ${skill.id} (must be kebab-case)`);
  }

  if (skill.version && !isValidSemver(skill.version)) {
    errors.push(`Invalid version format: ${skill.version} (must be semver)`);
  }

  if (!Array.isArray(skill.plugins?.required)) {
    errors.push('plugins.required must be an array');
  }

  // 校验可选参数定义
  for (const [key, spec] of Object.entries(skill.parameters?.optional || {})) {
    if (!spec.type || !PARAM_TYPES.has(spec.type)) {
      errors.push(`Invalid parameter type for ${key}: ${spec.type}`);
    }
    if (spec.type === 'select' && !Array.isArray(spec.options)) {
      errors.push(`Select parameter ${key} must have options array`);
    }
    if (spec.type === 'number') {
      if (spec.min !== undefined && spec.max !== undefined && spec.min > spec.max) {
        errors.push(`Invalid range for parameter ${key}: min > max`);
      }
    }
  }

  // 校验输出定义
  for (const output of [...(skill.outputs?.primary || []), ...(skill.outputs?.secondary || [])]) {
    if (!output.id) errors.push('Output missing id field');
    if (output.type && !OUTPUT_TYPES.has(output.type)) {
      errors.push(`Invalid output type: ${output.type}`);
    }
  }

  return { ok: errors.length === 0, errors };
}

// ── 发现与加载 ──────────────────────────────────────────────────────────────

/**
 * 扫描目录下的所有 Skill 子目录
 * @param {string} dir - 父目录
 * @returns {string[]}
 */
function scanSkillDirs(dir) {
  if (!fs.existsSync(dir)) return [];
  return fs.readdirSync(dir, { withFileTypes: true })
    .filter(entry => entry.isDirectory())
    .map(entry => path.join(dir, entry.name));
}

/**
 * 从目录加载单个 Skill
 * @param {string} skillDir - Skill 目录
 * @param {string} source - 来源类型
 * @returns {SkillEntry|null}
 */
function loadSkillFromDir(skillDir, source) {
  const manifestPath = path.join(skillDir, 'skill.json');
  const manifest = readJson(manifestPath);
  if (!manifest) return null;

  return parseSkillManifest(manifest, source, skillDir);
}

/**
 * 加载内置 Skills
 * @returns {SkillEntry[]}
 */
function loadBuiltInSkills() {
  const skills = [];

  // 首先尝试加载 manifest.json
  const manifest = readJson(BUILT_IN_MANIFEST_PATH);
  if (manifest && manifest.skills) {
    // 从 manifest 声明的目录加载
    for (const [id, info] of Object.entries(manifest.skills)) {
      const skillDir = path.join(BUILT_IN_SKILLS_DIR, id);
      const skill = loadSkillFromDir(skillDir, 'built-in');
      if (skill) skills.push(skill);
    }
  } else {
    // 回退：扫描目录
    for (const skillDir of scanSkillDirs(BUILT_IN_SKILLS_DIR)) {
      const skill = loadSkillFromDir(skillDir, 'built-in');
      if (skill) skills.push(skill);
    }
  }

  return skills;
}

/**
 * 获取用户数据目录下的 installed Skills 目录
 * @returns {string}
 */
function getInstalledSkillsDir() {
  // 优先使用环境变量指定的路径
  const envPath = process.env.PETRI_USER_DATA_DIR;
  if (envPath) {
    return path.join(envPath, 'skills');
  }
  // 回退到 common 用户数据路径
  const os = require('os');
  return path.join(os.homedir(), '.petri', 'skills');
}

/**
 * 加载已安装的 Skills
 * @returns {SkillEntry[]}
 */
function loadInstalledSkills() {
  const installedDir = getInstalledSkillsDir();
  const manifestPath = path.join(installedDir, 'manifest.json');
  const manifest = readJson(manifestPath);

  if (!manifest || !manifest.skills) return [];

  const skills = [];
  for (const [id, info] of Object.entries(manifest.skills)) {
    // 跳过已被 built-in 占用的
    if (_registry.has(id)) continue;

    const skillDir = path.join(installedDir, id);
    const skill = loadSkillFromDir(skillDir, 'installed');
    if (skill) skills.push(skill);
  }

  return skills;
}

/**
 * 加载 marketplace Skills（仅元数据，不下载）
 * @param {string} marketplaceUrl - 市场 URL
 * @returns {SkillEntry[]}
 */
async function loadMarketplaceSkills(marketplaceUrl = 'https://marketplace.petri.com/skills/manifest.json') {
  // 检查缓存
  const now = Date.now();
  if (_marketplaceCache && (now - _marketplaceCacheTime) < MARKETPLACE_CACHE_TTL) {
    return _marketplaceCache;
  }

  try {
    // 尝试从网络加载（实际实现中可能需要 http 请求）
    // 这里先返回空数组，待 MCP 层实现网络请求
    const skills = [];

    // 缓存结果
    _marketplaceCache = skills;
    _marketplaceCacheTime = now;

    return skills;
  } catch (e) {
    console.warn(`[skill-registry] Failed to load marketplace manifest: ${e.message}`);
    return [];
  }
}

/**
 * 发现并加载所有可用 Skills
 * @returns {SkillEntry[]}
 */
function discoverSkills() {
  const skills = [];

  // 1. 内置 Skills（最高优先级）
  const builtIn = loadBuiltInSkills();
  for (const skill of builtIn) {
    skills.push(skill);
    _registry.set(skill.id, skill);
    _sourceMap.set(skill.id, 'built-in');
  }

  // 2. 已安装 Skills
  const installed = loadInstalledSkills();
  for (const skill of installed) {
    skills.push(skill);
    _registry.set(skill.id, skill);
    _sourceMap.set(skill.id, 'installed');
  }

  return skills;
}

// ── SkillRegistry 类 ────────────────────────────────────────────────────────

/**
 * Skill 注册表类
 * 提供 Skills 的发现、查询、依赖验证等能力
 */
class SkillRegistry {
  constructor() {
    this._initialized = false;
  }

  /**
   * 初始化注册表（惰性加载）
   */
  _ensureInitialized() {
    if (!this._initialized) {
      discoverSkills();
      this._initialized = true;
    }
  }

  /**
   * 发现所有可用 Skills
   * @returns {SkillEntry[]} 所有已注册的 Skills
   */
  discover() {
    this._ensureInitialized();
    return Array.from(_registry.values());
  }

  /**
   * 按 ID 获取 Skill
   * @param {string} id - Skill ID
   * @returns {SkillEntry|null}
   */
  get(id) {
    this._ensureInitialized();
    return _registry.get(id) || null;
  }

  /**
   * 按标签搜索 Skills
   * @param {string} query - 搜索关键词（匹配 name、description、tags）
   * @returns {SkillEntry[]}
   */
  search(query) {
    this._ensureInitialized();
    const q = query.toLowerCase();
    return Array.from(_registry.values()).filter(skill => {
      return (
        skill.id.toLowerCase().includes(q) ||
        skill.name.toLowerCase().includes(q) ||
        skill.description.toLowerCase().includes(q) ||
        skill.tags.some(tag => tag.toLowerCase().includes(q)) ||
        skill.category.toLowerCase().includes(q)
      );
    });
  }

  /**
   * 按类别筛选 Skills
   * @param {string} category - 类别（支持前缀匹配，如 "bioinformatics"）
   * @returns {SkillEntry[]}
   */
  filterByCategory(category) {
    this._ensureInitialized();
    if (!category) return this.discover();
    const cat = category.toLowerCase();
    return Array.from(_registry.values()).filter(skill =>
      skill.category.toLowerCase() === cat ||
      skill.category.toLowerCase().startsWith(cat + '/')
    );
  }

  /**
   * 按来源筛选 Skills
   * @param {string} source - 来源类型
   * @returns {SkillEntry[]}
   */
  filterBySource(source) {
    this._ensureInitialized();
    if (!source) return this.discover();
    return Array.from(_registry.values()).filter(skill => skill.source === source);
  }

  /**
   * 按插件依赖筛选 Skills
   * @param {string} pluginId - 插件 ID
   * @returns {SkillEntry[]}
   */
  filterByPlugin(pluginId) {
    this._ensureInitialized();
    return Array.from(_registry.values()).filter(skill =>
      skill.plugins.required.includes(pluginId) ||
      skill.plugins.optional.includes(pluginId)
    );
  }

  /**
   * 按能力筛选 Skills
   * @param {string} capability - 能力 ID
   * @returns {SkillEntry[]}
   */
  filterByCapability(capability) {
    this._ensureInitialized();
    return Array.from(_registry.values()).filter(skill =>
      skill.capabilities.includes(capability)
    );
  }

  /**
   * 检查 Skill 依赖是否满足
   * @param {string|SkillEntry} skillOrId - Skill ID 或 Skill 对象
   * @param {object} context - 执行上下文（包含可用的 plugins、capabilities）
   * @returns {{ can: boolean, missing: { plugins: string[], capabilities: string[] } }}
   */
  canExecute(skillOrId, context = {}) {
    this._ensureInitialized();
    const skill = typeof skillOrId === 'string' ? this.get(skillOrId) : skillOrId;
    if (!skill) {
      return { can: false, missing: { plugins: [], capabilities: [], reason: 'Skill not found' } };
    }

    const availablePlugins = new Set(context.availablePlugins || []);
    const availableCapabilities = new Set(context.availableCapabilities || []);

    const missingPlugins = skill.plugins.required.filter(p => !availablePlugins.has(p));
    const missingCapabilities = skill.capabilities.filter(c => !availableCapabilities.has(c));

    return {
      can: missingPlugins.length === 0 && missingCapabilities.length === 0,
      missing: {
        plugins: missingPlugins,
        capabilities: missingCapabilities,
      },
    };
  }

  /**
   * 注册新 Skill（用于动态注册）
   * @param {SkillEntry} skill
   * @returns {{ ok: boolean, error?: string }}
   */
  register(skill) {
    if (!skill || !skill.id) {
      return { ok: false, error: 'Invalid skill object' };
    }

    const validation = validateSkillManifest(skill);
    if (!validation.ok) {
      return { ok: false, error: `Validation failed: ${validation.errors.join(', ')}` };
    }

    const existing = _registry.get(skill.id);
    if (existing && SOURCE_PRIORITY[existing.source] <= SOURCE_PRIORITY[skill.source]) {
      return { ok: false, error: `Skill ${skill.id} already registered with higher priority source` };
    }

    _registry.set(skill.id, skill);
    _sourceMap.set(skill.id, skill.source);
    return { ok: true };
  }

  /**
   * 获取注册统计
   * @returns {{ total: number, bySource: object, byCategory: object }}
   */
  getStats() {
    this._ensureInitialized();
    const bySource = {};
    const byCategory = {};

    for (const skill of _registry.values()) {
      bySource[skill.source] = (bySource[skill.source] || 0) + 1;
      byCategory[skill.category] = (byCategory[skill.category] || 0) + 1;
    }

    return {
      total: _registry.size,
      bySource,
      byCategory,
    };
  }

  /**
   * 获取所有唯一类别
   * @returns {string[]}
   */
  getCategories() {
    this._ensureInitialized();
    const categories = new Set();
    for (const skill of _registry.values()) {
      categories.add(skill.category);
    }
    return Array.from(categories).sort();
  }

  /**
   * 获取所有唯一标签
   * @returns {string[]}
   */
  getTags() {
    this._ensureInitialized();
    const tags = new Set();
    for (const skill of _registry.values()) {
      for (const tag of skill.tags) {
        tags.add(tag);
      }
    }
    return Array.from(tags).sort();
  }

  /**
   * 导出符合 MCP 工具格式的 Skills 列表
   * @returns {object[]}
   */
  toMcpToolList() {
    this._ensureInitialized();
    return Array.from(_registry.values()).map(skill => ({
      name: skill.id,
      description: skill.description,
      inputSchema: {
        type: 'object',
        properties: {
          id: { type: 'string', description: `Skill ID: ${skill.id}` },
          params: {
            type: 'object',
            description: 'Skill 执行参数',
            properties: skill.parameters.optional,
          },
          workflow: {
            type: 'string',
            description: '指定执行的 workflow（可选，默认使用 default）',
          },
        },
        required: skill.parameters.required,
      },
      _skill: skill,
    }));
  }

  /**
   * 清除所有注册（主要用于测试）
   */
  clear() {
    _registry.clear();
    _sourceMap.clear();
    _marketplaceCache = null;
    _marketplaceCacheTime = 0;
    this._initialized = false;
  }
}

