/**
 * Local File Storage — 本地文件存储适配器
 *
 * 桌面版默认存储后端。所有文件操作走本地文件系统，
 * URL 返回 /api/files/<key> 路由路径，由 petri-server 的 files-local 路由提供下载。
 */

const path = require('path');
const fs = require('fs');
const logger = require('../logger');
const { safeJoinUnder } = require('../path-safe');

// 从 config-helper 读取配置（断点1：斩断对 petri-server/config 的反向 require）
const configHelper = require('../config-helper');
function getRConfig() {
  return configHelper.getConfig();
}

function _getResultsDir() {
  const cfg = getRConfig();
  return (
    cfg.localResultsDir || path.join(require('os').homedir(), 'Documents', 'Petri-Local', 'results')
  );
}

function _resolveKey(key, { mustExist = false } = {}) {
  if (typeof key !== 'string' || key.length === 0 || key.includes('\0')) return null;
  const resultsDir = path.resolve(_getResultsDir());
  const target = safeJoinUnder(resultsDir, key);
  if (!target) return null;
  if (mustExist && !fs.existsSync(target)) return null;
  try {
    const realRoot = fs.realpathSync(resultsDir);
    const realTarget = fs.realpathSync(target);
    if (realTarget !== realRoot && !realTarget.startsWith(realRoot + path.sep)) return null;
  } catch (error) {
    if (mustExist || error.code !== 'ENOENT') return null;
    const existingParent = fs.realpathSync(path.dirname(target));
    const realRoot = fs.realpathSync(resultsDir);
    if (existingParent !== realRoot && !existingParent.startsWith(realRoot + path.sep)) return null;
  }
  return target;
}

class LocalFileStorage {
  get name() {
    return 'local';
  }

  /**
   * 上传文件（本地 = 复制到 results 目录）。
   * @param {string} localPath - 源文件路径
   * @param {string} key - 存储键（如 results/job123/volcano.png）
   * @returns {Promise<string>} - 可访问的 URL 路径
   */
  async upload(localPath, key) {
    const resultsDir = _getResultsDir();
    fs.mkdirSync(resultsDir, { recursive: true });
    const candidate = safeJoinUnder(path.resolve(resultsDir), key);
    if (!candidate) throw new Error('invalid_storage_key');
    fs.mkdirSync(path.dirname(candidate), { recursive: true });
    const target = _resolveKey(key);
    if (!target) throw new Error('invalid_storage_key');
    fs.copyFileSync(localPath, target);
    logger.debug(`[local-storage] uploaded: ${key}`);
    return this.getUrl(key);
  }

  /**
   * 生成文件访问 URL。
   * 桌面版返回 /api/files/<key>，由本地文件路由处理。
   */
  getUrl(key) {
    return `/api/files/${key}`;
  }

  /**
   * 下载文件（本地 = 从 results 目录复制到指定路径）。
   */
  async download(key, localPath) {
    const resultsDir = _getResultsDir();
    const src = _resolveKey(key, { mustExist: true });
    if (!src) throw new Error(`文件不存在或路径非法: ${key}`);
    if (!fs.existsSync(src)) {
      throw new Error(`文件不存在: ${key}`);
    }
    fs.mkdirSync(path.dirname(localPath), { recursive: true });
    fs.copyFileSync(src, localPath);
  }

  /**
   * 删除文件。
   */
  async delete(key) {
    const resultsDir = _getResultsDir();
    const target = _resolveKey(key, { mustExist: true });
    if (!target) throw new Error('invalid_storage_key');
    try {
      fs.unlinkSync(target);
      logger.debug(`[local-storage] deleted: ${key}`);
    } catch (e) {
      // 文件不存在不算错误
      if (e.code !== 'ENOENT') throw e;
    }
  }

  /**
   * 生成上传目标 URL。
   * 桌面版：前端直接 POST /api/upload，multer 存到本地 uploads 目录。
   * 不需要 OSS 签名。
   */
  getUploadUrl(key) {
    return '/api/upload';
  }

  /**
   * 检查文件是否存在。
   */
  exists(key) {
    const resultsDir = _getResultsDir();
    return !!_resolveKey(key, { mustExist: true });
  }

  /**
   * 读取文件内容（Buffer）。
   */
  read(key) {
    const resultsDir = _getResultsDir();
    const target = _resolveKey(key, { mustExist: true });
    if (!target) throw new Error('invalid_storage_key');
    return fs.readFileSync(target);
  }
}

module.exports = { LocalFileStorage, resolveLocalStorageKey: _resolveKey };

'use strict';

const fs = require('fs');
const path = require('path');
const { execFile } = require('child_process');
const { createRuntimeResourceSnapshot } = require('./runtime-resource-snapshot');

const DEFAULT_INTERVAL_MS = 500;
const MAX_DIRECTORY_ENTRIES = 20_000;

function finiteNonNegative(value) {
  if (value == null || typeof value === 'boolean'
      || (typeof value === 'string' && value.trim() === '')) return null;
  const number = Number(value);
  return Number.isFinite(number) && number >= 0 ? number : null;
}

async function directoryBytes(root, maxEntries = MAX_DIRECTORY_ENTRIES) {
  let bytes = 0;
  let entries = 0;
  let readErrors = 0;
  let statErrors = 0;
  const queue = [path.resolve(root)];
  while (queue.length > 0 && entries < maxEntries) {
    const current = queue.pop();
    let children;
    try {
      children = await fs.promises.readdir(current, { withFileTypes: true });
    } catch {
      readErrors += 1;
      continue;
    }
    for (const child of children) {
      entries += 1;
      if (entries > maxEntries) break;
      const target = path.join(current, child.name);
      if (child.isDirectory()) queue.push(target);
      else if (child.isFile()) {
        try { bytes += (await fs.promises.stat(target)).size; } catch { statErrors += 1; }
      }
    }
  }
  const truncated = entries >= maxEntries;
  return {
    bytes,
    entries,
    truncated,
    readErrors,
    statErrors,
    complete: !truncated && readErrors === 0 && statErrors === 0,
  };
}

function diskSnapshot(target) {
  try {
    const stat = fs.statfsSync(target, { bigint: true });
    const blockSize = stat.bsize;
    const totalBytes = Number(stat.blocks * blockSize);
    const availableBytes = Number(stat.bavail * blockSize);
    return {
      totalBytes,
      availableBytes,
      usePercent: totalBytes > 0 ? ((totalBytes - availableBytes) / totalBytes) * 100 : 0,
    };
  } catch {
    return null;
  }
}

function samplePosixProcess(pid, exec = execFile) {
  if (!Number.isInteger(pid) || pid <= 0 || process.platform === 'win32') {
    return Promise.resolve(null);
  }
  return new Promise((resolve) => {
    exec('ps', ['-o', '%cpu=,rss=', '-p', String(pid)], {
      timeout: 1_000,
      maxBuffer: 16 * 1024,
      windowsHide: true,
    }, (error, stdout) => {
      if (error) return resolve(null);
      const match = String(stdout || '').trim().match(/^([0-9.]+)\s+([0-9]+)$/);
      if (!match) return resolve(null);
      resolve({ cpuPercent: Number(match[1]), rssBytes: Number(match[2]) * 1024 });
    });
  });
}

function createToolResourceSampler(options = {}) {
  const pid = Number(options.pid);
  const jobDir = path.resolve(String(options.jobDir || '.'));
  const intervalMs = Math.max(100, Number(options.intervalMs) || DEFAULT_INTERVAL_MS);
  const readProcess = options.sampleProcess || ((targetPid) => samplePosixProcess(targetPid));
  const readDirectory = options.sampleDirectory || ((target) => directoryBytes(target));
  const readDisk = options.sampleDisk || diskSnapshot;
  const activeJobs = typeof options.activeJobs === 'function' ? options.activeJobs : () => 0;
  const snapshot = options.createSnapshot || createRuntimeResourceSnapshot;
  let timer = null;
  let pending = null;
  let stopped = false;
  const peak = {
    cpuPercent: null,
    rssBytes: null,
    outputBytes: null,
    activeJobs: null,
    minimumAvailableMemoryBytes: null,
    minimumAvailableDiskBytes: null,
  };
  const sampling = {
    status: 'unavailable',
    intervalMs,
    sampleCount: 0,
    processSampleCount: 0,
    outputSampleCount: 0,
    systemSampleCount: 0,
    directoryTruncated: false,
    directoryReadErrors: 0,
    directoryStatErrors: 0,
    outputMeasurementStatus: 'unavailable',
  };

  const keepMaximum = (field, value) => {
    const measured = finiteNonNegative(value);
    if (measured == null) return;
    peak[field] = peak[field] == null ? measured : Math.max(peak[field], measured);
  };
  const keepMinimum = (field, value) => {
    const measured = finiteNonNegative(value);
    if (measured == null) return;
    peak[field] = peak[field] == null ? measured : Math.min(peak[field], measured);
  };

  async function observe() {
    if (pending) return pending;
    pending = (async () => {
      const [processSample, outputSample] = await Promise.all([
        Promise.resolve(readProcess(pid)).catch(() => null),
        Promise.resolve(readDirectory(jobDir)).catch(() => null),
      ]);
      const disk = readDisk(jobDir);
      const system = snapshot({ disk, activeJobs: activeJobs(), observedAt: new Date().toISOString() });
      sampling.sampleCount += 1;
      sampling.status = 'measured';
      if (processSample) {
        sampling.processSampleCount += 1;
        keepMaximum('cpuPercent', processSample.cpuPercent);
        keepMaximum('rssBytes', processSample.rssBytes);
      }
      if (outputSample) {
        sampling.outputSampleCount += 1;
        keepMaximum('outputBytes', outputSample.bytes);
        sampling.directoryTruncated ||= outputSample.truncated === true;
        sampling.directoryReadErrors += Number(outputSample.readErrors || 0);
        sampling.directoryStatErrors += Number(outputSample.statErrors || 0);
        const complete = outputSample.complete !== false
          && outputSample.truncated !== true
          && Number(outputSample.readErrors || 0) === 0
          && Number(outputSample.statErrors || 0) === 0;
        sampling.outputMeasurementStatus = complete
          && sampling.outputMeasurementStatus !== 'partial'
          ? 'measured'
          : 'partial';
      }
      sampling.systemSampleCount += 1;
      keepMaximum('activeJobs', system.activeJobs);
      keepMinimum('minimumAvailableMemoryBytes', system.memory?.availableBytes);
      keepMinimum('minimumAvailableDiskBytes', system.disk?.availableBytes);
    })().finally(() => { pending = null; });
    return pending;
  }

  function start() {
    if (timer || stopped) return;
    void observe();
    timer = setInterval(() => { void observe(); }, intervalMs);
    timer.unref?.();
  }

  async function stop() {
    if (timer) clearInterval(timer);
    timer = null;
    if (!stopped) {
      if (pending) await pending;
      await observe();
      stopped = true;
    }
    return {
      peak: { ...peak },
      sampling: { ...sampling },
      peakStatus: sampling.processSampleCount > 0
        ? 'measured'
        : sampling.sampleCount > 0 ? 'partial_process_peak_unavailable' : 'unavailable',
    };
  }

  return { start, stop, sample: observe };
}

module.exports = {
  DEFAULT_INTERVAL_MS,
  createToolResourceSampler,
  directoryBytes,
  diskSnapshot,
  samplePosixProcess,
};

/**
 * shared-backend/workflow-engine.js — Petri Desktop Workflow Engine
 *
 * 工作流执行引擎：在 Skills 之上提供流程编排能力。
 *
 * 职责：
 * 1. 加载并解析 Workflow 定义
 * 2. 按 step 顺序执行，支持 condition、错误处理、状态持久化
 * 3. 在 step 之间传递上下文和输出
 * 4. 支持 checkpoint / resume
 *
 * 设计参考：
 * - skill-runtime.js — 单 Skill 执行
 * - skill-registry.js — Skill 发现
 * - agent-workflow.js — 现有工作流模式
 */

'use strict';

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

// ---------------------------------------------------------------------------
// Workflow 状态常量
// ---------------------------------------------------------------------------

const WORKFLOW_STATES = Object.freeze({
  CREATED: 'created',
  RUNNING: 'running',
  PAUSED: 'paused',
  COMPLETE: 'complete',
  FAILED: 'failed',
  CANCELLED: 'cancelled',
});

const STEP_STATES = Object.freeze({
  PENDING: 'pending',
  SKIPPED: 'skipped',
  RUNNING: 'running',
  COMPLETE: 'complete',
  FAILED: 'failed',
});

const ERROR_POLICIES = Object.freeze({
  FAIL: 'fail',
  WARN_CONTINUE: 'warn_continue',
  SKIP_CONTINUE: 'skip_continue',
});

const CONDITION_TYPES = Object.freeze({
  ALWAYS: 'always',
  EXPR: 'expr',
  STEP_SUCCESS: 'step_success',
});

const WORKFLOW_MANIFEST_VERSION = 1;

// ---------------------------------------------------------------------------
// 工具函数
// ---------------------------------------------------------------------------

function readJson(filePath) {
  try {
    if (!fs.existsSync(filePath)) return null;
    return JSON.parse(fs.readFileSync(filePath, 'utf8'));
  } catch (e) {
    return null;
  }
}

function generateId(prefix = 'wf') {
  return `${prefix}_${crypto.randomBytes(8).toString('hex')}`;
}

function deepGet(obj, path) {
  if (!obj || !path) return undefined;
  const parts = path.split('.');
  let current = obj;
  for (const part of parts) {
    if (current == null) return undefined;
    current = current[part];
  }
  return current;
}

// ---------------------------------------------------------------------------
// Workflow — 内部执行单元
// ---------------------------------------------------------------------------

/**
 * 单 Workflow 执行实例
 */
class Workflow {
  /**
   * @param {object} manifest — Workflow Manifest
   * @param {object} options
   * @param {SkillsSDK} options.sdk — SkillsSDK 实例
   * @param {object} [options.executor] — 自定义执行器（用于 mock / 测试）
   */
  constructor(manifest, options = {}) {
    this.manifest = manifest;
    this.sdk = options.sdk;
    this.executor = options.executor || null;

    this.id = generateId('wfe');
    this.status = WORKFLOW_STATES.CREATED;
    this.createdAt = new Date().toISOString();
    this.startedAt = null;
    this.completedAt = null;

    /** @type {Map<string, object>} stepId -> StepExecution */
    this.steps = new Map();
    /** step 输出上下文 */
    this.context = {
      params: {},
      user_context: {},
      step_outputs: {},
      groups: [],
    };
  }

  /**
   * 执行整个 workflow
   * @param {object} params
   * @param {object} [userContext]
   * @returns {Promise<object>}
   */
  async execute(params = {}, userContext = {}) {
    this.context.params = { ...params };
    this.context.user_context = { ...userContext };

    // 初始化 step 状态
    for (const step of this.manifest.steps || []) {
      this.steps.set(step.id, {
        id: step.id,
        skill: step.skill,
        status: STEP_STATES.PENDING,
        started_at: null,
        completed_at: null,
        output: null,
        error: null,
      });
    }

    this.status = WORKFLOW_STATES.RUNNING;
    this.startedAt = new Date().toISOString();

    try {
      for (const step of this.manifest.steps || []) {
        const stepExec = this.steps.get(step.id);

        // 1. 评估 condition
        if (!this._evaluateCondition(step.condition)) {
          stepExec.status = STEP_STATES.SKIPPED;
          continue;
        }

        // 2. 解析 inputs
        const resolvedInputs = this._resolveInputs(step.inputs || {}, step.id);

        // 3. 执行 step
        stepExec.status = STEP_STATES.RUNNING;
        stepExec.started_at = new Date().toISOString();

        const result = await this._executeStep(step, resolvedInputs);

        // 4. 收集 outputs
        if (result.success) {
          stepExec.status = STEP_STATES.COMPLETE;
          stepExec.output = result;
          stepExec.completed_at = new Date().toISOString();

          if (step.outputs) {
            this._collectOutputs(step.id, result, step.outputs);
          }
        } else {
          // 错误处理
          stepExec.error = result.error;
          const policy = this._getErrorPolicy(step.id);

          if (policy === ERROR_POLICIES.SKIP_CONTINUE) {
            stepExec.status = STEP_STATES.SKIPPED;
          } else if (policy === ERROR_POLICIES.WARN_CONTINUE) {
            stepExec.status = STEP_STATES.COMPLETE;
            this.context.warnings = this.context.warnings || [];
            this.context.warnings.push({
              step: step.id,
              error: result.error,
            });
          } else {
            // FAIL
            stepExec.status = STEP_STATES.FAILED;
            stepExec.completed_at = new Date().toISOString();
            this.status = WORKFLOW_STATES.FAILED;
            this.completedAt = new Date().toISOString();

            return this._buildResult(false);
          }
        }
      }

      this.status = WORKFLOW_STATES.COMPLETE;
      this.completedAt = new Date().toISOString();
      return this._buildResult(true);
    } catch (error) {
      this.status = WORKFLOW_STATES.FAILED;
      this.completedAt = new Date().toISOString();
      this._lastError = {
        message: error.message,
        stack: error.stack,
      };
      return this._buildResult(false);
    }
  }

  /**
   * 评估 step condition
   * @param {string|undefined} condition
   * @returns {boolean}
   * @private
   */
  _evaluateCondition(condition) {
    if (!condition || condition === 'always') return true;

    const condDef = (this.manifest.conditions || {})[condition];
    if (!condDef) {
      // 未知 condition — 保守执行
      return true;
    }

    if (condDef.type === CONDITION_TYPES.ALWAYS) return true;

    if (condDef.type === CONDITION_TYPES.STEP_SUCCESS) {
      const depStep = this.steps.get(condDef.step);
      return depStep && depStep.status === STEP_STATES.COMPLETE;
    }

    if (condDef.type === CONDITION_TYPES.EXPR) {
      return this._evalExpr(condDef.expr);
    }

    return true;
  }

  /**
   * 求值简单表达式 — 仅支持白名单操作避免 eval 风险
   * @param {string} expr
   * @returns {boolean}
   * @private
   */
  _evalExpr(expr) {
    try {
      // 限制：只允许 context.* / params.* / 数字 / 比较运算符
      const safe = String(expr).trim();
      // 拒绝任何包含函数调用或赋值的表达式
      if (/[;{}()]|=|\beval\b|\bfunction\b/i.test(safe)) {
        return false;
      }
      // eslint-disable-next-line no-new-func
      const fn = new Function('context', 'params', `return (${safe});`);
      return Boolean(fn(this.context, this.context.params));
    } catch (e) {
      return false;
    }
  }

  /**
   * 解析 step inputs — 支持引用上游输出
   * @param {object} inputMap
   * @param {string} stepId
   * @returns {object}
   * @private
   */
  _resolveInputs(inputMap, stepId) {
    const resolved = {};
    for (const [key, value] of Object.entries(inputMap)) {
      resolved[key] = this._resolveValue(value, stepId);
    }
    return resolved;
  }

  /**
   * 解析单个引用值
   * 支持格式：
   *   "params.dataset"        — 顶层参数
   *   "user_context.user_id"  — 用户上下文
   *   "<step_id>.output"      — 上游 step 输出
   *   "<step_id>.output.<key>" — 上游 step 输出字段
   *   其他：字面值
   * @param {*} value
   * @param {string} stepId
   * @returns {*}
   * @private
   */
  _resolveValue(value, stepId) {
    if (typeof value !== 'string') return value;
    if (!value.includes('.')) return value;

    const parts = value.split('.');
    const head = parts[0];

    if (head === 'params') {
      return deepGet(this.context.params, parts.slice(1).join('.'));
    }
    if (head === 'user_context' || head === 'userContext') {
      return deepGet(this.context.user_context, parts.slice(1).join('.'));
    }

    // 引用 step 输出
    if (this.steps.has(head)) {
      const stepExec = this.steps.get(head);
      if (!stepExec || !stepExec.output) return undefined;
      return deepGet(stepExec.output, parts.slice(1).join('.'));
    }

    return value;
  }

  /**
   * 收集 step 输出到 context
   * @param {string} stepId
   * @param {object} result
   * @param {object} outputs
   * @private
   */
  _collectOutputs(stepId, result, outputs) {
    this.context.step_outputs[stepId] = result;

    for (const [alias, source] of Object.entries(outputs)) {
      // source 可以是字符串路径或简单 alias
      const value =
        typeof source === 'string' && source.includes('.')
          ? deepGet(result, source)
          : deepGet(result, source);
      this.context[alias] = value;
    }
  }

  /**
   * 获取错误处理策略
   * @param {string} stepId
   * @returns {string}
   * @private
   */
  _getErrorPolicy(stepId) {
    const overrides = this.manifest.error_handling?.step_overrides || {};
    return overrides[stepId]?.on_error || this.manifest.error_handling?.default || ERROR_POLICIES.FAIL;
  }

  /**
   * 执行单个 step
   * @param {object} step
   * @param {object} inputs
   * @returns {Promise<object>}
   * @private
   */
  async _executeStep(step, inputs) {
    if (this.executor) {
      // 自定义执行器（用于 mock / 测试）
      return this.executor(step, inputs, this.context);
    }

    if (!this.sdk) {
      return {
        success: false,
        error: { code: 'SDK_NOT_AVAILABLE', message: 'SkillsSDK not configured' },
      };
    }

    return this.sdk.executeSkill(step.skill, inputs, {
      workflowName: step.workflow,
      userContext: this.context.user_context,
      stepId: step.id,
    });
  }

  /**
   * 构建执行结果
   * @param {boolean} success
   * @returns {object}
   * @private
   */
  _buildResult(success) {
    return {
      success,
      workflowId: this.id,
      workflowManifestId: this.manifest.id,
      status: this.status,
      startedAt: this.startedAt,
      completedAt: this.completedAt,
      duration: this.startedAt && this.completedAt
        ? new Date(this.completedAt).getTime() - new Date(this.startedAt).getTime()
        : null,
      steps: Array.from(this.steps.values()),
      outputs: { ...this.context.step_outputs },
      params: { ...this.context.params },
      warnings: this.context.warnings || [],
      error: this._lastError || null,
    };
  }
}

// ---------------------------------------------------------------------------
// WorkflowEngine — 主类
// ---------------------------------------------------------------------------

/**
 * Workflow Engine
 *
 * 加载、执行、追踪 Workflow 的主入口。
 * 不强制持久化；执行历史保留在内存中以便查询。
 */
class WorkflowEngine {
  /**
   * @param {object} options
   * @param {SkillsSDK} options.sdk — SkillsSDK 实例（必需）
   * @param {string} [options.workflowsDir] — 内置 Workflow 定义目录
   */
  constructor(options = {}) {
    if (!options.sdk) {
      throw new Error('WorkflowEngine requires SkillsSDK instance');
    }
    this.sdk = options.sdk;
    this.workflowsDir = options.workflowsDir || null;

    /** @type {Map<string, object>} workflowId -> Workflow Manifest */
    this._workflows = new Map();
    /** @type {Map<string, Workflow>} executionId -> Workflow 实例 */
    this._executions = new Map();
  }

  // ── 加载 / 注册 ────────────────────────────────────────────────────────

  /**
   * 加载单个 Workflow Manifest
   * @param {object} manifest
   * @returns {object|null}
   */
  loadWorkflow(manifest) {
    if (!manifest || manifest.workflowManifestVersion !== WORKFLOW_MANIFEST_VERSION) {
      return null;
    }
    if (!manifest.id || !manifest.steps || !Array.isArray(manifest.steps)) {
      return null;
    }

    const normalized = this._normalizeManifest(manifest);
    this._workflows.set(manifest.id, normalized);
    return normalized;
  }

  /**
   * 从文件加载 Workflow Manifest
   * @param {string} filePath
   * @returns {object|null}
   */
  loadWorkflowFromFile(filePath) {
    const manifest = readJson(filePath);
    if (!manifest) return null;
    return this.loadWorkflow(manifest);
  }

  /**
   * 从目录加载所有 Workflow
   * @param {string} dir
   * @returns {object[]}
   */
  loadWorkflowsFromDir(dir) {
    if (!fs.existsSync(dir)) return [];
    const loaded = [];
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
      if (!entry.isDirectory()) continue;
      const wfPath = path.join(dir, entry.name, 'workflow.json');
      const wf = this.loadWorkflowFromFile(wfPath);
      if (wf) loaded.push(wf);
    }
    return loaded;
  }

  /**
   * 注册已加载的 Workflow
   * @param {string} id
   * @param {object} manifest
   * @returns {boolean}
   */
  registerWorkflow(id, manifest) {
    const normalized = this.loadWorkflow({ ...manifest, id });
    return normalized !== null;
  }

  /**
   * 列出所有已加载的 Workflow
   * @returns {object[]}
   */
  listWorkflows() {
    return Array.from(this._workflows.values());
  }

  /**
   * 按 ID 获取 Workflow Manifest
   * @param {string} id
   * @returns {object|null}
   */
  getWorkflow(id) {
    return this._workflows.get(id) || null;
  }

  // ── 执行 ────────────────────────────────────────────────────────────────

  /**
   * 执行 Workflow
   * @param {string} workflowId
   * @param {object} params
   * @param {object} [context]
   * @returns {Promise<object>}
   */
  async execute(workflowId, params = {}, context = {}) {
    let manifest = this._workflows.get(workflowId);

    if (!manifest) {
      // 支持 "skill:workflow" 复合 ID 解析
      if (workflowId.includes(':')) {
        const [skillId, wfName] = workflowId.split(':');
        manifest = this._buildSkillInlineWorkflow(skillId, wfName);
      }
    }

    if (!manifest) {
      return {
        success: false,
        error: {
          code: 'WORKFLOW_NOT_FOUND',
          message: `Workflow not found: ${workflowId}`,
        },
        workflowId,
      };
    }

    const workflow = new Workflow(manifest, {
      sdk: this.sdk,
      executor: context.executor,
    });

    this._executions.set(workflow.id, workflow);
    const result = await workflow.execute(params, context.userContext || {});

    return result;
  }

  /**
   * 执行单步（不依赖 Workflow Manifest）
   * @param {string} skillId
   * @param {object} context
   * @returns {Promise<object>}
   */
  async step(skillId, context = {}) {
    return this.sdk.executeSkill(skillId, context.params || {}, context);
  }

  /**
   * 取消正在执行的 Workflow
   * @param {string} executionId
   * @returns {boolean}
   */
  cancel(executionId) {
    const wf = this._executions.get(executionId);
    if (!wf) return false;
    wf.status = WORKFLOW_STATES.CANCELLED;
    wf.completedAt = new Date().toISOString();
    return true;
  }

  /**
   * 获取执行实例状态
   * @param {string} executionId
   * @returns {object|null}
   */
  getExecution(executionId) {
    const wf = this._executions.get(executionId);
    if (!wf) return null;
    return {
      id: wf.id,
      status: wf.status,
      startedAt: wf.startedAt,
      completedAt: wf.completedAt,
      steps: Array.from(wf.steps.values()),
    };
  }

  // ── 工具方法 ────────────────────────────────────────────────────────────

  /**
   * 规范化 Workflow Manifest
   * @param {object} manifest
   * @returns {object}
   * @private
   */
  _normalizeManifest(manifest) {
    return {
      workflowManifestVersion: WORKFLOW_MANIFEST_VERSION,
      id: manifest.id,
      name: manifest.name || manifest.id,
      version: manifest.version || '1.0.0',
      description: manifest.description || '',
      category: manifest.category || 'general',
      source: manifest.source || 'built-in',
      steps: (manifest.steps || []).map((s) => ({
        id: s.id,
        skill: s.skill,
        description: s.description || '',
        condition: s.condition || 'always',
        inputs: s.inputs || {},
        outputs: s.outputs || {},
        workflow: s.workflow,
      })),
      conditions: manifest.conditions || {},
      error_handling: manifest.error_handling || { default: ERROR_POLICIES.FAIL },
      metadata: manifest.metadata || {},
    };
  }

  /**
   * 从 Skill Manifest 内联构建 Workflow
   * 用于 "skill:workflow" 复合 ID 解析
   * @param {string} skillId
   * @param {string} workflowName
   * @returns {object|null}
   * @private
   */
  _buildSkillInlineWorkflow(skillId, workflowName) {
    const skill = this.sdk.getSkill(skillId);
    if (!skill) return null;

    return {
      workflowManifestVersion: WORKFLOW_MANIFEST_VERSION,
      id: `${skillId}:${workflowName}`,
      name: `${skill.name} (${workflowName})`,
      version: skill.version,
      description: skill.description,
      category: skill.category,
      source: skill.source,
      steps: [
        {
          id: 'main',
          skill: skillId,
          condition: 'always',
          workflow: workflowName,
          inputs: {},
        },
      ],
      error_handling: { default: ERROR_POLICIES.FAIL },
    };
  }
}

// ---------------------------------------------------------------------------
// 工厂函数
// ---------------------------------------------------------------------------

/**
 * 创建 WorkflowEngine 实例
 * @param {object} options
 * @returns {WorkflowEngine}
 */
function createWorkflowEngine(options = {}) {
  return new WorkflowEngine(options);
}

// ---------------------------------------------------------------------------
// 导出
// ---------------------------------------------------------------------------

module.exports = {
  // 主类
  WorkflowEngine,
  Workflow,

  // 工厂
  createWorkflowEngine,

  // 常量
  WORKFLOW_STATES,
  STEP_STATES,
  ERROR_POLICIES,
  CONDITION_TYPES,
  WORKFLOW_MANIFEST_VERSION,
};

// Petri 桌面版原生 shell — App 根组件
// 路由出口 + 首次启动引导

