/** Lives inside WorkspacePanelsProvider. */
function AppShell(): React.ReactElement {
  const { isOpen, open, close } = useCommandPalette();
  const location = useLocation();
  const panels = useWorkspacePanelsContext();
  // (/project/:id/results) 与其余路由维持原状。归一化尾斜杠后取 :id 后的子段判定。
  // BLOCK-62 P0 — 列体化壳：仅 ProjectWorkspace 路由（/project/:id/*）走「列容器
  // 占满视口 + 列内让位固定顶栏」新地基，main 不再 paddingTop 让位；ResultStudio
  // (/project/:id/results) 与其余路由维持原状。归一化尾斜杠后取 :id 后的子段判定。
  const isColumnizedWorkspace = (() => {
    const path = location.pathname.replace(/\/+$/, '') || '/';
    const m = path.match(/^\/project\/[^/]+(?:\/(.*))?$/);
    return !!m && m[1] !== 'results';
  })();
  // BLOCK-87 L3 — 投影+窄屏（手机浏览器）：壳层 AppRail 转抽屉浮层。
  // L3-2（用户裁决「左上角的左侧展开栏就直接控制左侧栏的展开和收缩」）：
  // 撤掉独立 ☰ 浮层按钮——标题栏左上「展开/收起左侧栏」（panels.toggleLeft）
  // 直接开合抽屉，leftOpen 在该形态下即抽屉开合单一真相；leftOpen 初始值
  // 已由 useWorkspacePanels 在投影窄屏下置 false（手机首屏不被抽屉盖住）。
  // 桌面端恒 false 不受影响（UI-341 常驻裁决仅针对桌面窗口）。
  const projectionMobile = isProjectionMobile();
  const { setLeftOpen } = panels;
  useEffect(() => {
    // 路由变化即收起抽屉（点导航项跳转后不残留遮罩；含挂载首帧的兜底收起）
    if (projectionMobile) setLeftOpen(false);
  }, [projectionMobile, setLeftOpen, location.pathname]);

  return (
    <>
      {/* BLOCK-62 P1b — 列体化路由的顶栏归 ProjectWorkspace 自持（regular=列内
          ColumnHeader，loading/error/compact=fixed 条），AppShell 不再渲染全局条，
          避免与列内 header 双份。其余路由照旧。 */}
      {!isColumnizedWorkspace && <TitleBar />}
      <CopilotContextProvider>
        {/* BLOCK-42 — pending-scroll 全局 Provider：页面级写入端（ProjectWorkspace
            事件 relay）与消费端（WorkspaceFilePreviewBridge / dev bridge / 未来
            ChatCardLinkBridge）必须在同一 Context 实例内，否则写入端拿到 FALLBACK
            no-op 静默丢弃。Provider 仅一个 useState，全局挂载零副作用。 */}
        <PendingScrollProvider>
        {/* UI-341 加映三（档 2）——左栏上提为壳层 AppRail：所有主窗页面常驻，
            不再随 /project/:id 路由消失。main 为 flex 兄弟（高度 100%）。 */}
        <div style={{ display: 'flex', height: '100vh', overflow: 'hidden' }}>
        {projectionMobile && panels.leftOpen && (
          <>
            <button
              type="button"
              aria-label="关闭导航"
              onClick={() => setLeftOpen(false)}
              style={{ position: 'fixed', inset: 0, zIndex: 78, background: 'rgba(24,24,27,0.4)', border: 'none', cursor: 'default' }}
            />
            <div
              style={{
                position: 'fixed', top: 0, bottom: 0, left: 0, zIndex: 79,
                width: 'min(300px, 86vw)', overflowY: 'auto', height: '100%',
                background: 'var(--petri-bg-surface)', boxShadow: 'var(--petri-shadow-menu)',
              }}
              data-testid="projection-rail-overlay"
            >
              <AppRail />
            </div>
          </>
        )}
        {(!projectionMobile) && <AppRail />}
        <main
          className="petri-spa-main"
          style={{
            flex: 1,
            minWidth: 0,
            marginTop: 0,
            paddingTop: isColumnizedWorkspace ? 0 : 'var(--petri-titlebar-height)',
            transition: 'margin-left 0.25s ease',
          }}
        >
          {/* dev mode passes through here just like production: deep-linkable
              /project/:id/<mode> and /skills routes are intentionally reachable.
              Only the dev-home skip-auto-navigate logic lives in pages/home.tsx. */}
          <Routes>
            {/* BLOCK-80 — / 为欢迎页（问候+项目/分支+首问直发）；原工作台（项目卡+创建流）退役至 /projects 项目管理 */}
            <Route path="/" element={<WelcomePage />} />
            <Route path="/projects" element={<HomePage />} />
            {/* Skills management page */}
            <Route path="/skills" element={<SkillsPage />} />
            {/* UI-364 — 插件商店独立页（设备级能力，不绑项目；与 /skills 同形态） */}
            <Route path="/plugins" element={<PluginsPage />} />
            {/* UI-365 — 设置独立页（设备级能力，不绑项目；与 /skills 同形态） */}
            <Route path="/settings" element={<SettingsPage />} />
            {/* BLOCK-72 / UI-320 → UI-366 — 知识空间保留全局页；「后端」页退役，
                诊断并入设置「运行时与诊断」分区 */}
            <Route path="/knowledge" element={<KnowledgePage />} />
            {/* BLOCK-28 — main-area code review mode (VS Code SCM style) */}
            <Route path="/review" element={<ReviewModePage />} />
            {/* Result Studio — standalone results view with branch tabs in TitleBar */}
            {/* MUST come before the wildcard /* route, otherwise it never matches */}
            <Route path="/project/:projectId/results" element={<ResultStudioPage />} />
            {/* T85: `*` splat lets `/project/:projectId/<mode>` resolve to the
                same workspace; mode is read from the sub-path, not `?mode=`. */}
            <Route path="/project/:projectId/*" element={<ProjectWorkspace />} />
            {/* Legacy pages (tools, admin, docs, figcode) removed - all workflows now use Agent */}
            <Route path="*" element={<Navigate to="/" replace />} />
          </Routes>
        </main>
        </div>
        <TestInstanceBadge />
        <CommandPalette
          open={isOpen}
          onClose={close}
          commands={[]}
          recentConversations={[]}
        />
        {/* BLOCK-22 P4.6: DEV ONLY — do NOT use in production */}
        <Suspense fallback={null}>
          <PetriOpenFileDevBridge />
        </Suspense>
        </PendingScrollProvider>
      </CopilotContextProvider>
    </>
  );
}

export default function App(): React.ReactElement {
  const location = useLocation();
  const isWindowSurface = location.pathname.startsWith('/window/');

  useEffect(() => {
    const html = document.documentElement;
    html.classList.add('petri-desktop');
    html.classList.remove('petri-desktop-dock-collapsed');
    document.body.style.paddingLeft = '0';
    document.body.style.boxSizing = 'border-box';
  }, []);

  // BLOCK-64 P2-d — 指挥中心快捷键入口（Ctrl/Cmd+Shift+C）。仅主窗生效；
  // popOut 语义 = 单例窗已开即聚焦（同内容禁双开契约），重复按无害。
  useEffect(() => {
    if (isWindowSurface) return undefined;
    const onKeyDown = (e: KeyboardEvent) => {
      if (!(e.ctrlKey || e.metaKey) || !e.shiftKey) return;
      if (e.key.toLowerCase() !== 'c') return;
      e.preventDefault();
      void getBridge('windowManager')?.popOut('command-center');
    };
    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  }, [isWindowSurface]);

  // BLOCK-59 P1 — 独立窗（弹出结果窗/终端窗/指挥中心）加载同一 SPA 的
  // /window/* 路由：只挂 WindowShell 级 chrome，不挂主窗 Provider 树
  // （窗口永不持有 canonical state，plan §10 治理红线）。
  if (isWindowSurface) {
    return (
      <Routes>
        <Route path="/window/terminal/:sessionId" element={<TerminalWindowPage />} />
        <Route path="/window/command-center" element={<CommandCenterPage />} />
        <Route path="/window/rail" element={<RailPage />} />
        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>
    );
  }

  return (
    <BackendStatusProvider>
      <AppRailProvider>
        <WorkspacePanelsProvider>
          <AppShell />
        </WorkspacePanelsProvider>
      </AppRailProvider>
    </BackendStatusProvider>
  );
}

// M1-1 后端就绪感知层 — 全局 Context + 5s 轮询
// 挂在 App 根，下游用 useBackendStatus() 消费。
// petri-server 不通时由摘要概览显示降级提示。
//
// （BLOCK-30 P2：曾有的 Gateway 健康聚合随 gateway 摘除）
import React, { createContext, useContext, useEffect, useState, useCallback } from 'react';
import type { BackendStatus } from '@/lib/electron';
import { getPlatformApiPrefix } from '@/lib/env';
import { getToken } from '@/lib/authClient';

// 增强的后端状态类型（BLOCK-30 P2：gateway 字段随 gateway 摘除，回归 BackendStatus 本体）
export type EnhancedBackendStatus = BackendStatus;

// 初始态：检测中
const INITIAL_STATUS: EnhancedBackendStatus = {
  rRuntime: false,
  pyRuntime: false,
  rServerUp: false,
  serverUp: false,
  isReady: false,
  downReason: '',
  loaded: false,
};

const Ctx = createContext<EnhancedBackendStatus>(INITIAL_STATUS);

async function probeHealth(url: string): Promise<boolean> {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), 2000);
  try {
    return await fetch(url, { signal: controller.signal }).then((response) => response.ok);
  } catch {
    return false;
  } finally {
    clearTimeout(timeoutId);
  }
}

// /api/runtime/status 响应形状（与投影桥 projectionDataBridges.runtimeBridge 同源）。
export interface RuntimeStatusPayload {
  ok?: boolean;
  runtime?: {
    r?: { installed?: boolean };
    python?: { installed?: boolean };
  };
}

/** 把 /api/runtime/status 载荷 + health 探测结果映射为 BackendStatus。
 *  诚实语义：installed 只有 true/false 两种回答；载荷不可达 = null（未知），
 *  消费端（useRuntimeDemandBanner 等）以 `=== false` 判缺失，未知不弹横幅。 */
export function mapRuntimeStatusPayload(
  payload: RuntimeStatusPayload | null,
  serverUp: boolean,
): EnhancedBackendStatus {
  const rInstalled = payload?.runtime?.r?.installed;
  const pyInstalled = payload?.runtime?.python?.installed;
  return {
    rRuntime: typeof rInstalled === 'boolean' ? rInstalled : null,
    pyRuntime: typeof pyInstalled === 'boolean' ? pyInstalled : null,
    rServerUp: serverUp,
    serverUp,
    isReady: serverUp,
    downReason: serverUp ? null : '本地分析服务尚未就绪',
    loaded: true,
  };
}

async function fetchRuntimeStatus(base: string): Promise<RuntimeStatusPayload | null> {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), 3000);
  try {
    const headers: Record<string, string> = {};
    const token = getToken();
    if (token) headers.Authorization = `Bearer ${token}`;
    const response = await fetch(`${base}/runtime/status`, { headers, signal: controller.signal });
    return (await response.json()) as RuntimeStatusPayload;
  } catch {
    return null;
  } finally {
    clearTimeout(timeoutId);
  }
}

async function readBackendStatus(): Promise<EnhancedBackendStatus | null> {
  const desktopStatus = await window.petriDesktop?.backend?.status();
  if (desktopStatus) {
    return { ...desktopStatus };
  }
  // Vite's renderer-only development mode has no preload bridge（含投影：手机
  // 浏览器里 shim 调用 resolve undefined，走此分支）。经平台前缀打 REST——
  // 投影 = /api（gateway 同源），桌面 dev renderer = http://localhost:3001/api。
  // packaged builds never use this.
  if (!import.meta.env.DEV) return null;
  // UI-406 修复：曾把 health 探测结果当作 rRuntime、pyRuntime 写死 false
  //（BLOCK-30 P1 py-server 摘除后的遗产）——手机投影里 127.0.0.1 探针恒不通，
  // 工作台假弹「R 与 Python 运行时均未安装」。现消费 /api/runtime/status
  //（BLOCK-86 权威探测，与桌面 IPC backend:status 同源真相）。
  const base = getPlatformApiPrefix();
  const [serverUp, payload] = await Promise.all([
    probeHealth(`${base}/health`),
    fetchRuntimeStatus(base),
  ]);
  return mapRuntimeStatusPayload(payload, serverUp);
}

export function useBackendStatus(): EnhancedBackendStatus {
  return useContext(Ctx);
}

export function BackendStatusProvider({
  children,
}: {
  children: React.ReactNode;
}): React.ReactElement {
  const [status, setStatus] = useState<EnhancedBackendStatus>(INITIAL_STATUS);
  const [loaded, setLoaded] = useState(false);

  const tick = useCallback(async () => {
    try {
      const s = await readBackendStatus();
      if (s) {
        setStatus(s);
        setLoaded(true);
      }
    } catch {
      // IPC 失败时保持上次状态，不闪烁
    }
  }, []);

  useEffect(() => {
    let alive = true;
    let timeoutId: ReturnType<typeof setTimeout> | undefined;
    // 启动期高频探测（1s）：后端双服务稳态 ~2.6s 就绪，高频能让 UI 尽快
    // 感知就绪、避免"后端已起但引导页还在转圈"的体感延迟；就绪后降频到
    // 5s 仅作健康保活，避免无谓 IPC 占用。
    const safeTick = async () => {
      let nextDelay = 1000;
      try {
        const s = await readBackendStatus();
        if (alive && s) {
          setStatus(s);
          setLoaded(true);
          nextDelay = s.isReady ? 5000 : 1000;
        }
      } catch {
        // 忽略
      } finally {
        if (alive) timeoutId = setTimeout(safeTick, nextDelay);
      }
    };
    void safeTick();
    return () => {
      alive = false;
      if (timeoutId) clearTimeout(timeoutId);
    };
  }, []);

  return <Ctx.Provider value={{ ...status, loaded }}>{children}</Ctx.Provider>;
}

// ============================================================
// BranchTabs — Branch switcher component for TitleBar center area
//
// Phase 1: Branch Tab UI
// Displays as horizontal tabs in the TitleBar center, left of the result picker.
// Features:
//   - Horizontal branch tabs with active state highlight
//   - + button to create new branch
//   - Right-click context menu: rename, delete
//   - Branch switch triggers IPC call + store update
// ============================================================

import React, { useCallback, useEffect, useRef, useState } from 'react';
import { Icon } from '@/components/icons/Icon';
import type { Branch } from '@/types/branch.types';
import styles from './BranchTabs.module.css';

interface BranchTabsProps {
  branches: Branch[];
  activeBranchId: string | null;
  onSwitch: (branchId: string) => Promise<void>;
  onCreate: (name: string, parentBranchId?: string) => Promise<Branch | null>;
  onRename: (branchId: string, newName: string) => Promise<boolean>;
  onDelete: (branchId: string) => Promise<boolean>;
  loading?: boolean;
}

interface ContextMenuState {
  branchId: string;
  x: number;
  y: number;
}

export function BranchTabs({
  branches,
  activeBranchId,
  onSwitch,
  onCreate,
  onRename,
  onDelete,
  loading = false,
}: BranchTabsProps): React.ReactElement {
  const [contextMenu, setContextMenu] = useState<ContextMenuState | null>(null);
  const [renaming, setRenaming] = useState<string | null>(null);
  const [renameValue, setRenameValue] = useState('');
  const [creating, setCreating] = useState(false);
  const [newBranchName, setNewBranchName] = useState('');

  const contextMenuRef = useRef<HTMLDivElement>(null);
  const renameInputRef = useRef<HTMLInputElement>(null);
  const newBranchInputRef = useRef<HTMLInputElement>(null);

  // Close context menu on outside click
  useEffect(() => {
    if (!contextMenu) return;
    const handleClickOutside = (e: MouseEvent) => {
      if (contextMenuRef.current && !contextMenuRef.current.contains(e.target as Node)) {
        setContextMenu(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [contextMenu]);

  // Close context menu on Escape
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        setContextMenu(null);
        setRenaming(null);
        setCreating(false);
      }
    };
    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, []);

  // Focus rename input when entering rename mode
  useEffect(() => {
    if (renaming && renameInputRef.current) {
      renameInputRef.current.focus();
      renameInputRef.current.select();
    }
  }, [renaming]);

  // Focus new branch input when creating
  useEffect(() => {
    if (creating && newBranchInputRef.current) {
      newBranchInputRef.current.focus();
    }
  }, [creating]);

  const handleContextMenu = useCallback((e: React.MouseEvent, branchId: string) => {
    e.preventDefault();
    e.stopPropagation();
    setContextMenu({ branchId, x: e.clientX, y: e.clientY });
  }, []);

  const handleRename = useCallback(
    async (branchId: string) => {
      const trimmed = renameValue.trim();
      if (!trimmed) {
        setRenaming(null);
        return;
      }
      setRenaming(null);
      await onRename(branchId, trimmed);
    },
    [renameValue, onRename]
  );

  const handleCreate = useCallback(async () => {
    const trimmed = newBranchName.trim();
    if (!trimmed) {
      setCreating(false);
      setNewBranchName('');
      return;
    }
    setCreating(false);
    setNewBranchName('');
    await onCreate(trimmed, activeBranchId || undefined);
  }, [newBranchName, activeBranchId, onCreate]);

  const handleDelete = useCallback(
    async (branchId: string) => {
      setContextMenu(null);
      await onDelete(branchId);
    },
    [onDelete]
  );

  const startRename = useCallback((branch: Branch) => {
    setContextMenu(null);
    setRenaming(branch.id);
    setRenameValue(branch.name);
  }, []);

  if (branches.length === 0 && !loading) {
    return (
      <div className={styles.branchTabs}>
        <button
          type="button"
          className={styles.addButton}
          onClick={() => setCreating(true)}
          title="创建分支"
          aria-label="创建分支"
        >
          <Icon name="plus" size={14} />
        </button>
        {creating && (
          <div className={styles.newBranchInput}>
            <input
              ref={newBranchInputRef}
              type="text"
              value={newBranchName}
              onChange={(e) => setNewBranchName(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter') void handleCreate();
                if (e.key === 'Escape') {
                  setCreating(false);
                  setNewBranchName('');
                }
              }}
              onBlur={() => void handleCreate()}
              placeholder="分支名称"
              className={styles.input}
              maxLength={64}
            />
          </div>
        )}
      </div>
    );
  }

  return (
    <div className={styles.branchTabs}>
      {branches.map((branch) => (
        <div
          key={branch.id}
          className={`${styles.branchTab} ${branch.id === activeBranchId ? styles.branchTabActive : ''}`}
          onContextMenu={(e) => handleContextMenu(e, branch.id)}
        >
          {renaming === branch.id ? (
            <input
              ref={renameInputRef}
              type="text"
              value={renameValue}
              onChange={(e) => setRenameValue(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter') void handleRename(branch.id);
                if (e.key === 'Escape') setRenaming(null);
              }}
              onBlur={() => void handleRename(branch.id)}
              className={styles.renameInput}
              maxLength={64}
            />
          ) : (
            <button
              type="button"
              className={styles.branchTabButton}
              onClick={() => onSwitch(branch.id)}
              title={branch.name}
              aria-pressed={branch.id === activeBranchId}
            >
              <Icon name="git-branch" size={12} />
              <span className={styles.branchTabText}>{branch.name}</span>
            </button>
          )}
        </div>
      ))}

      <button
        type="button"
        className={styles.addButton}
        onClick={() => setCreating(true)}
        title="创建新分支"
        aria-label="创建新分支"
      >
        <Icon name="plus" size={14} />
      </button>

      {creating && (
        <div className={styles.newBranchInput}>
          <input
            ref={newBranchInputRef}
            type="text"
            value={newBranchName}
            onChange={(e) => setNewBranchName(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === 'Enter') void handleCreate();
              if (e.key === 'Escape') {
                setCreating(false);
                setNewBranchName('');
              }
            }}
            onBlur={() => void handleCreate()}
            placeholder="分支名称"
            className={styles.input}
            maxLength={64}
          />
        </div>
      )}

      {contextMenu && (
        <>
          <button
            type="button"
            className={styles.contextMenuOverlay}
            onClick={() => setContextMenu(null)}
            aria-label="关闭菜单"
          />
          <div
            ref={contextMenuRef}
            className={styles.contextMenu}
            style={{ left: contextMenu.x, top: contextMenu.y }}
            role="menu"
          >
            <button
              type="button"
              className={styles.contextMenuItem}
              onClick={() => {
                const branch = branches.find((b) => b.id === contextMenu.branchId);
                if (branch) startRename(branch);
              }}
              role="menuitem"
            >
              <Icon name="more-horizontal" size={13} />
              <span>重命名</span>
            </button>
            <button
              type="button"
              className={`${styles.contextMenuItem} ${styles.contextMenuItemDanger}`}
              onClick={() => void handleDelete(contextMenu.branchId)}
              role="menuitem"
            >
              <Icon name="trash" size={13} />
              <span>删除</span>
            </button>
          </div>
        </>
      )}
    </div>
  );
}

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { render, screen, fireEvent, act, cleanup } from '@testing-library/react';
import { ToastProvider, useToast } from './ToastProvider';

function Harness({ onReady }: { onReady: (api: ReturnType<typeof useToast>) => void }) {
  onReady(useToast());
  return null;
}

describe('ToastProvider', () => {
  beforeEach(() => {
    vi.useFakeTimers();
  });
  afterEach(() => {
    cleanup();
    vi.useRealTimers();
  });

  it('throws when useToast is used outside the provider', () => {
    const spy = vi.spyOn(console, 'error').mockImplementation(() => undefined);
    expect(() => render(<Harness onReady={() => undefined} />)).toThrow(
      /useToast must be used inside ToastProvider/,
    );
    spy.mockRestore();
  });

  it('shows a toast when show() is called and auto-dismisses after the default duration', () => {
    let api!: ReturnType<typeof useToast>;
    render(
      <ToastProvider>
        <Harness onReady={(a) => { api = a; }} />
      </ToastProvider>,
    );

    act(() => {
      api.show({ message: 'Analysis saved', variant: 'success' });
    });
    expect(screen.queryByText('Analysis saved')).not.toBeNull();

    act(() => {
      vi.advanceTimersByTime(4000);
    });
    expect(screen.queryByText('Analysis saved')).toBeNull();
  });

  it('supports sticky toasts (duration <= 0) that do not auto-dismiss', () => {
    let api!: ReturnType<typeof useToast>;
    render(
      <ToastProvider>
        <Harness onReady={(a) => { api = a; }} />
      </ToastProvider>,
    );

    act(() => {
      api.show({ message: 'Pinned notice', variant: 'info', duration: 0 });
    });
    act(() => {
      vi.advanceTimersByTime(10000);
    });
    expect(screen.queryByText('Pinned notice')).not.toBeNull();
  });

  it('renders an error toast inside an assertive live region', () => {
    let api!: ReturnType<typeof useToast>;
    render(
      <ToastProvider>
        <Harness onReady={(a) => { api = a; }} />
      </ToastProvider>,
    );

    act(() => {
      api.error('Runtime failed to start');
    });
    const region = screen.getByText('Runtime failed to start').closest('[role="status"]') as HTMLElement | null;
    expect(region).not.toBeNull();
    expect(region?.getAttribute('aria-live')).toBe('assertive');
  });

  it('removes a toast immediately when its dismiss button is clicked', () => {
    let api!: ReturnType<typeof useToast>;
    render(
      <ToastProvider>
        <Harness onReady={(a) => { api = a; }} />
      </ToastProvider>,
    );

    act(() => {
      api.info('Heads up');
    });
    const dismiss = screen.getByRole('button', { name: /dismiss/i });
    act(() => {
      fireEvent.click(dismiss);
    });
    expect(screen.queryByText('Heads up')).toBeNull();
  });

  it('stacks multiple toasts and dismisses by id', () => {
    let api!: ReturnType<typeof useToast>;
    render(
      <ToastProvider>
        <Harness onReady={(a) => { api = a; }} />
      </ToastProvider>,
    );

    let firstId = '';
    act(() => {
      firstId = api.warning('First');
      api.warning('Second');
    });
    expect(screen.queryByText('First')).not.toBeNull();
    expect(screen.queryByText('Second')).not.toBeNull();

    act(() => {
      api.dismiss(firstId);
    });
    expect(screen.queryByText('First')).toBeNull();
    expect(screen.queryByText('Second')).not.toBeNull();
  });
});

import { act, cleanup, render, screen } from '@testing-library/react';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

import { ChatScrollbar } from './ChatScrollbar';

// UI-269 — ChatScrollbar：溢出渲染 / 无溢出不渲染 / scroll 事件更新 thumb 位置

type ScrollableRef = { current: HTMLDivElement | null };

function stubScrollBox(opts: { clientH: number; scrollH: number }): HTMLDivElement {
  const el = document.createElement('div');
  Object.defineProperty(el, 'clientHeight', { configurable: true, value: opts.clientH });
  Object.defineProperty(el, 'scrollHeight', { configurable: true, value: opts.scrollH });
  Object.defineProperty(el, 'scrollTop', {
    configurable: true,
    value: 0,
    writable: true,
  });
  return el;
}

describe('ChatScrollbar', () => {
  let roCb: ResizeObserverCallback;
  const roObserve = vi.fn();
  const roDisconnect = vi.fn();

  beforeEach(() => {
    vi.stubGlobal(
      'ResizeObserver',
      class {
        constructor(cb: ResizeObserverCallback) {
          roCb = cb;
        }
        observe = roObserve;
        unobserve = vi.fn();
        disconnect = roDisconnect;
      }
    );
    vi.stubGlobal(
      'MutationObserver',
      class {
        observe = vi.fn();
        disconnect = vi.fn();
      }
    );
  });

  afterEach(() => {
    cleanup();
    vi.unstubAllGlobals();
  });

  it('renders nothing when content does not overflow', () => {
    const ref: ScrollableRef = { current: stubScrollBox({ clientH: 900, scrollH: 800 }) };
    const { container } = render(<ChatScrollbar containerRef={ref} />);
    expect(container.querySelector('[class*=track]')).toBeNull();
  });

  it('renders a persistent track and thumb when content overflows', () => {
    const ref: ScrollableRef = { current: stubScrollBox({ clientH: 900, scrollH: 1800 }) };
    const { container } = render(<ChatScrollbar containerRef={ref} />);
    expect(container.querySelector('[class*=track]')).toBeTruthy();
    expect(container.querySelector('[class*=thumb]')).toBeTruthy();
    // UI-270 增补 — 导轨线已按用户裁决移除，仅保留 thumb
    expect(container.querySelector('[class*=line]')).toBeNull();
  });

  it('repositions the thumb on scroll events', () => {
    const box = stubScrollBox({ clientH: 900, scrollH: 1800 });
    const ref: ScrollableRef = { current: box };
    const { container } = render(<ChatScrollbar containerRef={ref} />);
    const thumb = container.querySelector<HTMLElement>('[class*=thumb]');
    expect(thumb).toBeTruthy();
    const topBefore = thumb!.style.top;

    act(() => {
      box.scrollTop = 450; // maxScroll = 900 → 中点
      box.dispatchEvent(new Event('scroll'));
    });
    const topAfter = container.querySelector<HTMLElement>('[class*=thumb]')!.style.top;
    expect(topAfter).not.toBe(topBefore);
  });

  it('hides the scrollbar when overflow disappears after a resize', () => {
    const box = stubScrollBox({ clientH: 900, scrollH: 1800 });
    const ref: ScrollableRef = { current: box };
    const { container } = render(<ChatScrollbar containerRef={ref} />);
    expect(container.querySelector('[class*=track]')).toBeTruthy();

    act(() => {
      Object.defineProperty(box, 'scrollHeight', { configurable: true, value: 900 });
      roCb([] as unknown as ResizeObserverEntry[], {} as ResizeObserver);
    });
    expect(container.querySelector('[class*=track]')).toBeNull();
  });
});

