                      <div style={{
                        width: `${Math.min(catPct, 100)}%`,
                        height: '100%',
                        background: color,
                        borderRadius: '2px',
                      }} />
                    </div>
                    <span style={{ width: '45px', fontSize: 'var(--petri-font-size-xs)', fontFamily: 'monospace', textAlign: 'right', color: 'var(--petri-text)', flexShrink: 0 }}>
                      {formatTokens(catValue)}
                    </span>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

