  useComposerFocus({ taRef, ownsCopilotAsk, accessMenuOpen, modelMenuOpen });

  // 能力位门控（D3 双保险①的 UI 侧）：仅当当前渠道声明 reasoning 才渲染档位控件，
  // 避免对不支持的渠道出现「假开关」。后端仍会二次门控。
  const reasoningSupported = Array.isArray(activeModel?.capabilities)
