import React, { useCallback, useRef, useState } from 'react';
import { Icon } from '@/components/icons/Icon';
import { previewAgentTaskResume, type ResumeLastModelCall } from '../copilotClient';

/**
 * BLOCK-38 P2 / UI-275 — 「继续执行」入口。
 *
 * 仅服务中断（后端启动清扫标记 interrupted_at）的任务显示；点击后拉取
 * GET resume 只读预览，弹出轻量确认层（中断时间 + 中断前最后一次模型
 * 调用摘要 + 执行进度摘要），确认后由父组件调 resume 端点续跑。
 * 非中断失败任务不走此入口（诚实区分，走既有 retry 链路）。
 */

function formatTime(iso: string | null | undefined): string {
  if (!iso) return '—';
  const t = Date.parse(iso);
  if (!Number.isFinite(t)) return iso;
  return new Date(t).toLocaleString();
}

function formatFinishReason(reason: string | null | undefined): string {
  if (!reason) return '—';
  const labels: Record<string, string> = {
    stop: '完成回复',
    tool_calls: '准备调用工具',
    length: '长度截断',
    content_filter: '内容过滤',
  };
  return labels[reason] || reason;
}

interface ResumePreviewData {
  resumable: boolean;
  interruptedAt: string | null;
  lastModelCall: ResumeLastModelCall | null;
  progressDigest: string | null;
}

export function ResumePrompt({
  taskId,
  onConfirm,
}: {
  taskId: string;
  onConfirm: () => Promise<void>;
}): React.ReactElement {
  const [open, setOpen] = useState(false);
  const [preview, setPreview] = useState<ResumePreviewData | null>(null);
  const [loadingPreview, setLoadingPreview] = useState(false);
  const [previewError, setPreviewError] = useState<string | null>(null);
  const [confirming, setConfirming] = useState(false);
  const [confirmError, setConfirmError] = useState<string | null>(null);
  const wrapRef = useRef<HTMLDivElement | null>(null);

  const openPopover = useCallback(async () => {
    setOpen(true);
    setConfirmError(null);
    if (preview || loadingPreview) return;
    setLoadingPreview(true);
    setPreviewError(null);
    try {
      setPreview(await previewAgentTaskResume(taskId));
    } catch (err) {
      setPreviewError(err instanceof Error ? err.message : String(err));
    } finally {
      setLoadingPreview(false);
    }
  }, [taskId, preview, loadingPreview]);

  const handleConfirm = useCallback(async () => {
    setConfirming(true);
    setConfirmError(null);
    try {
      await onConfirm();
      setOpen(false);
    } catch (err) {
      setConfirmError(err instanceof Error ? err.message : String(err));
    } finally {
      setConfirming(false);
    }
  }, [onConfirm]);

  const last = preview?.lastModelCall || null;

  return (
    <div className="sc-resume-wrap" ref={wrapRef}>
      <button
        type="button"
        className="sc-resume-btn"
        onClick={() => void openPopover()}
        title="上次执行因服务重启中断，可从既有进度继续"
      >
        <Icon name="play" size={13} />
        继续执行
      </button>

      {open && (
        <div className="sc-resume-popover" role="dialog" aria-label="继续执行确认">
          <div className="sc-resume-popover-title">继续执行 · 中断恢复</div>

          <div className="sc-resume-row">
            <span className="sc-resume-label">中断时间</span>
            <span className="sc-resume-value">{formatTime(preview?.interruptedAt)}</span>
          </div>

          <div className="sc-resume-section">
            <div className="sc-resume-label">中断前最后状态</div>
            {loadingPreview && <div className="sc-resume-value">正在读取取证摘要…</div>}
            {previewError && <div className="sc-resume-error">{previewError}</div>}
            {!loadingPreview && !previewError && (
              <>
                {last ? (
                  <>
                    <div className="sc-resume-row">
                      <span className="sc-resume-label">模型</span>
                      <span className="sc-resume-value">{last.model || '—'}</span>
                    </div>
                    <div className="sc-resume-row">
                      <span className="sc-resume-label">调用时间</span>
                      <span className="sc-resume-value">{formatTime(last.ts)}</span>
                    </div>
                    <div className="sc-resume-row">
                      <span className="sc-resume-label">结束原因</span>
                      <span className="sc-resume-value">{formatFinishReason(last.finishReason)}</span>
                    </div>
                    {last.toolCallNames && last.toolCallNames.length > 0 && (
                      <div className="sc-resume-row">
                        <span className="sc-resume-label">待执行工具</span>
                        <span className="sc-resume-value">{last.toolCallNames.join('、')}</span>
                      </div>
                    )}
                    {last.error && <div className="sc-resume-error">{last.error}</div>}
                  </>
                ) : (
                  <div className="sc-resume-value">（无已记录的模型调用）</div>
                )}
                {preview?.progressDigest && (
                  <pre className="sc-resume-digest">{preview.progressDigest}</pre>
                )}
              </>
            )}
          </div>

          {confirmError && <div className="sc-resume-error">{confirmError}</div>}

          <div className="sc-resume-actions">
            <button
              type="button"
              className="sc-resume-cancel"
              onClick={() => setOpen(false)}
              disabled={confirming}
            >
              取消
            </button>
            <button
              type="button"
              className="sc-resume-confirm"
              onClick={() => void handleConfirm()}
              disabled={confirming || loadingPreview || Boolean(previewError)}
            >
              {confirming ? '正在恢复…' : '确认继续'}
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

// ============================================================
// attachmentUpload.ts — BLOCK-91 附件真实接入发送管线
//
// 附件（拖入/粘贴）在发送前上传到项目工作区 `.chat-attachments/`
// （复用 BLOCK-90 fs/upload 分片上传，local/ssh 双后端同构），
// 消息文本追加引用行，模型/agent 按路径读取——与 imageRefs 同构。
// ============================================================

import { MAX_ATTACHMENT_BYTES, validateAttachmentSize, type AttachmentFile } from './attachments';

/** 附件落盘目录（工作区相对路径）。 */
export const ATTACHMENT_DIR = '.chat-attachments';
/** fs/upload 分片大小（64KB 二进制，b64 后 <128KB argv 上限，与 BLOCK-90 对齐）。 */
const UPLOAD_CHUNK = 64 * 1024;

export interface UploadedAttachmentRef {
  name: string;
  /** 工作区相对路径（.chat-attachments/…）。 */
  path: string;
  size: number;
  type: string;
}

function getApiBase(): string {
  // 与 copilotClient.getApiPrefix 同源（避免跨层 import pages/ 的 fileOps）。
  // dev 下后端固定 :3001；生产同源相对 /api。
  if (import.meta.env.DEV) return 'http://localhost:3001/api';
  return '/api';
}

/** base64 → 二进制（渲染层无 node Buffer，用 Uint8Array 承载）。 */
function base64ToBytes(dataB64: string): Uint8Array {
  const bin = atob(dataB64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i += 1) bytes[i] = bin.charCodeAt(i);
  return bytes;
}

async function fileToBase64(file: File): Promise<string> {
  let out = '';
  for (let offset = 0; offset < file.size; offset += UPLOAD_CHUNK) {
    const buf = new Uint8Array(await file.slice(offset, offset + UPLOAD_CHUNK).arrayBuffer());
    for (let i = 0; i < buf.length; i += 0x8000) {
      out += String.fromCharCode(...buf.subarray(i, i + 0x8000));
    }
  }
  return btoa(out);
}

function dataUrlToBase64(dataUrl: string): string {
  const comma = dataUrl.indexOf(',');
  return comma >= 0 ? dataUrl.slice(comma + 1) : dataUrl;
}

async function uploadChunk(projectId: string, toPath: string, dataB64: string, offset: number): Promise<void> {
  const resp = await fetch(
    `${getApiBase()}/workspaces/${encodeURIComponent(projectId)}/fs/upload`,
    {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ toPath, dataB64, offset }),
    },
  );
  const data = await resp.json().catch(() => ({ ok: false, error: `请求失败（${resp.status}）` }));
  if (!resp.ok || !data?.ok) {
    throw new Error(String(data?.error || `附件上传失败（${resp.status}）`));
  }
}

/**
 * 上传单个附件到工作区 `.chat-attachments/`，返回引用描述。
 * 内容来源：优先 File 句柄（拖入），否则 dataUrl（粘贴图片）。
 */
export async function uploadAttachment(
  projectId: string,
  att: AttachmentFile,
): Promise<UploadedAttachmentRef> {
  const sizeError = validateAttachmentSize(att.size, att.name);
  if (sizeError) throw new Error(sizeError);

  const sanitized = (att.name || 'attachment').replace(/[\\/]/g, '_');
  const toPath = `${ATTACHMENT_DIR}/${Date.now()}-${sanitized}`;

  const dataB64 = att.file
    ? await fileToBase64(att.file)
    : att.dataUrl
      ? dataUrlToBase64(att.dataUrl)
      : null;
  if (dataB64 === null) throw new Error(`${att.name} 无可上传内容`);

  const binary = base64ToBytes(dataB64);
  if (binary.length === 0) {
    await uploadChunk(projectId, toPath, '', 0);
  }
  for (let offset = 0; offset < binary.length; offset += UPLOAD_CHUNK) {
    const slice = binary.subarray(offset, offset + UPLOAD_CHUNK);
    let chunkB64 = '';
    for (let i = 0; i < slice.length; i += 0x8000) {
      chunkB64 += String.fromCharCode(...slice.subarray(i, i + 0x8000));
    }
    await uploadChunk(projectId, toPath, btoa(chunkB64), offset);
  }
  return { name: att.name, path: toPath, size: att.size, type: att.type || 'application/octet-stream' };
}

/** 引用行块：追加到消息文本尾部，模型按工作区路径读取附件。 */
export function composeAttachmentReferenceLines(refs: UploadedAttachmentRef[]): string {
  if (refs.length === 0) return '';
  const lines = refs.map((ref) => {
    const sizeLabel = ref.size > 0 ? `（${(ref.size / 1024).toFixed(1)}KB）` : '';
    return `[附件: ${ref.path}${sizeLabel}]`;
  });
  return `\n\n${lines.join('\n')}`;
}

// BLOCK-92 Wave A-3 — SimpleChat 消息列表派生纯函数（自主组件平移，零行为变化）。
// baseDisplayMessages / displayMessages / railItems 三个渲染期派生逻辑由此承载，
// 主组件只做调用与 memo 编排。
import type { MessageRailItem } from '../MessageRail';
import { resolveToolSummaryPresentation } from '../toolSummaryPresentation';
import {
  getConversationFallbackNotice,
  getChildFinishedNotices,
  type ConversationLoopState,
  type ConversationRunSnapshot,
} from '../conversationRunStore';
import type { SimpleMessage } from './types';

export function buildBaseDisplayMessages(options: {
  activeRun: ConversationRunSnapshot | null;
  conversationId: string | null;
  messages: SimpleMessage[];
  durableLoop: { loop: ConversationLoopState | null };
}): SimpleMessage[] {
  const { activeRun, conversationId, messages, durableLoop } = options;
  if (!activeRun || activeRun.conversationId !== conversationId) {
    if (!durableLoop.loop) return messages;
    let lastAssistantIndex = -1;
    for (let index = messages.length - 1; index >= 0; index -= 1) {
      if (messages[index].role === 'assistant') {
        lastAssistantIndex = index;
        break;
      }
    }
    if (lastAssistantIndex < 0) return messages;
    const next = messages.slice();
    next[lastAssistantIndex] = { ...next[lastAssistantIndex], loop: durableLoop.loop };
    return next;
  }
  const next = messages.slice();
  const lastUser = [...next].reverse().find((message) => message.role === 'user');
  const runUserPersisted =
    lastUser?.content === activeRun.userContent &&
    lastUser.ts !== activeRun.historyLastUserTs;
  if (activeRun.userContent && !runUserPersisted) {
    next.push({
      role: 'user',
      content: activeRun.userContent,
      ts: activeRun.userTs,
    });
  }
  const lastAssistant = next[next.length - 1];
  const assistantAlreadyPersisted =
    lastAssistant?.role === 'assistant' &&
    Boolean(activeRun.assistantContent) &&
    lastAssistant.content === activeRun.assistantContent &&
    Boolean(lastAssistant.ts && Date.parse(lastAssistant.ts) >= activeRun.startedAt);
  if (!assistantAlreadyPersisted) {
    const summaryPresentation = resolveToolSummaryPresentation({
      assistantContent: activeRun.assistantContent,
      assistantError: activeRun.assistantError,
      statusMessage: activeRun.statusMessage,
      toolActivities: activeRun.toolActivities,
    });

    next.push({
      role: 'assistant',
      content: summaryPresentation.content,
      pending: activeRun.assistantPending,
      error: summaryPresentation.error,
      ts: activeRun.assistantTs,
      toolActivities: activeRun.toolActivities,
      reasoningByIteration: activeRun.reasoningByIteration,
      processingDurationMs: activeRun.processingDurationMs,
      statusMessage: summaryPresentation.statusMessage,
      summaryUnavailable: summaryPresentation.summaryUnavailable,
      retryToolJobId: summaryPresentation.retryToolJobId,
      progressUpdates: activeRun.progressUpdates,
      resultEditProgress: activeRun.resultEditProgress,
      loop: durableLoop.loop || activeRun.loop,
      // UI-AGENTWB-### / chat-error-rendering: forward the raw stack
      // + error code stored by conversationRunStore.finish so the
      // ErrorBanner "查看详情" disclosure becomes reachable. Without
      // these the user only ever sees the humanised "发生未知错误".
      technicalDetails: activeRun.technicalDetails,
      errorCode: activeRun.errorCode,
      // BLOCK-38 P2 / UI-275 — 服务中断可续跑：转发标记 + taskId 供「继续执行」入口
      resumable: activeRun.resumable,
      interruptedAt: activeRun.interruptedAt,
      taskId: activeRun.taskId,
      // BLOCK-56 P1 — 模型降级提示（任务条持久显示「已降级到 X 模型」）
      modelFallbackNotice: activeRun.modelFallbackNotice,
    });
  }
  return next;
}

// BLOCK-56 P1 / UI-287 — 降级提示附着到最后一条助手消息（覆盖全部构建路径）。
// 请求级降级常与任务终态同批到达：run 终态对账（clearConversationRun）会清掉
// run 快照且持久化消息不携带该字段，因此除 activeRun 外还兜底读会话级 notice
// （store 模块级保留，下一次 run 开始才清除），否则提示存活 <300ms 用户不可见。
export function applyConversationNotices(options: {
  base: SimpleMessage[];
  activeRun: ConversationRunSnapshot | null;
  conversationId: string | null;
}): SimpleMessage[] {
  const { base, activeRun, conversationId } = options;
  const fallbackNotice = activeRun?.modelFallbackNotice
    || (conversationId ? getConversationFallbackNotice(conversationId) : null);
  const childNotices = conversationId ? getChildFinishedNotices(conversationId) : [];
  if (!fallbackNotice && childNotices.length === 0) return base;
  const next = base.slice();
  const lastMsg = next[next.length - 1];
  if (lastMsg && lastMsg.role === 'assistant') {
    if (fallbackNotice && !lastMsg.modelFallbackNotice) {
      next[next.length - 1] = { ...lastMsg, modelFallbackNotice: fallbackNotice };
    }
    if (childNotices.length > 0 && !lastMsg.childFinishedNotices) {
      next[next.length - 1] = {
        ...next[next.length - 1],
        childFinishedNotices: childNotices.map((n) => ({
          childTaskId: n.childTaskId,
          status: n.status,
          summaryHead: n.summaryHead,
        })),
      };
    }
  }
  return next;
}

// UI-262 — 左缘用户消息导航条：当前会话每条用户消息一个刻度，
// 附紧随其后的 AI 回复摘要供悬浮预览。
export function buildRailItems(displayMessages: SimpleMessage[]): MessageRailItem[] {
  const items: MessageRailItem[] = [];
  displayMessages.forEach((m, i) => {
    if (m.role !== 'user' || !m.content) return;
    let reply: string | undefined;
    for (let j = i + 1; j < displayMessages.length; j++) {
      if (displayMessages[j].role === 'assistant') {
        reply = displayMessages[j].content;
        break;
      }
    }
    items.push({ key: m.ts ? `${m.ts}-${i}` : `idx-${i}`, content: m.content, reply });
  });
  return items;
}

// ============================================================
// formatHarness.ts — SimpleChat harness payload formatting helpers
//
// Extracted from SimpleChat.tsx by BLOCK-9.2 PHASE 4 (commit 2). These
// helpers convert raw harness payloads (repairs / warnings / diagnostics)
// into the human-readable strings rendered inside the ApprovalRepairHint
// block. They are pure (no React, no hooks, no closures over component
// state), so they can live in their own module and be consumed by both
// the SimpleChat main component (stringifyParamValue) and the inline
// ApprovalRepairHint sub-component (formatHarnessRepair / Warning /
// DiagnosticIssue).
//
// 5 functions exported:
//   - stringifyParamValue(value): JSON.stringify with safe fallbacks.
//   - shortValue(value): truncate stringifyParamValue output to ≤64 chars.
//   - formatHarnessRepair(item): repair payload → user-facing sentence.
//   - formatHarnessWarning(item): warning payload → user-facing sentence.
//   - formatHarnessDiagnosticIssue(issue): diagnostic issue → sentence.
//
// The original call sites in SimpleChat.tsx are preserved verbatim;
// only the import source moves from local-scope helpers to this module.
// ApprovalCard / ApprovalRepairHint stay nested inside SimpleChat.tsx
// (P3-3 deferred per survey §4.4), but they consume these helpers via
// the same import path as the main component, which keeps the split
// simple and avoids touching the sub-component boundaries in this
// commit.
// ============================================================

import type { HarnessDiagnosticIssue } from '@/lib/harness-client';

export function stringifyParamValue(value: unknown): string {
  if (typeof value === 'string') return value;
  if (value == null) return '';
  try {
    return JSON.stringify(value);
  } catch {
    return String(value);
  }
}

export function shortValue(value: unknown): string {
  const text = stringifyParamValue(value);
  return text.length > 64 ? `${text.slice(0, 61)}…` : text;
}

export function formatHarnessRepair(item: Record<string, unknown>): string {
  const code = String(item.code || '');
  const inputId = String(item.inputId || '参数');
  if (code === 'file_input_prefilled') {
    return `已为 ${inputId} 选择候选文件：${shortValue(item.value)}`;
  }
  if (code === 'column_alias_mapped') {
    return `已识别 ${inputId} 的关键列别名：${shortValue(item.mappings)}`;
  }
  if (code === 'number_param_clamped') {
    return item.confirmationRequired
      ? `建议将 ${inputId} 从 ${shortValue(item.from)} 调整为 ${shortValue(item.to)}（需确认）`
      : `已将 ${inputId} 从 ${shortValue(item.from)} 调整为 ${shortValue(item.to)}`;
  }
  if (code === 'number_default_filled') {
    return `已补齐 ${inputId} 默认值：${shortValue(item.to)}`;
  }
  return `${inputId}: ${shortValue(item)}`;
}

export function formatHarnessWarning(item: Record<string, unknown>): string {
  const code = String(item.code || '');
  const inputId = String(item.inputId || '参数');
  if (code === 'missing_required_columns') {
    return `${inputId} 可能缺少必要列：${shortValue(item.missing)}`;
  }
  return `${inputId}: ${shortValue(item)}`;
}

export function formatHarnessDiagnosticIssue(issue: HarnessDiagnosticIssue): string {
  const inputId = issue.inputId ? `${String(issue.inputId)}：` : '';
  const message = String(issue.message || issue.code || '诊断问题');
  const detail = issue.detail ? `（${String(issue.detail)}）` : '';
  return `${inputId}${message}${detail}`;
}

// ============================================================
// helpers.ts — SimpleChat pure helper functions + sub-components
//
// Extracted from SimpleChat.tsx by BLOCK-9.2 PHASE 4. These helpers don't
// depend on SimpleChat's local state (useState/useRef/useEffect). The
// MessageMeta / ExamplePrompts / compactStageConclusion functions are
// self-contained; everything they read comes from props / imports.
// ============================================================

import React, { useEffect, useState } from 'react';
import { Icon } from '@/components/icons/Icon';
import { getBridge } from '@/lib/desktopBridge';
import { formatRelativeTime } from '@/lib/format';
import type {
  ExamplePromptsProps,
  ExamplePrompt,
} from './types';

// DEFAULT_EXAMPLE_PROMPTS canonical 定义在 ./types（通用三卡 + 领域注册表
// DOMAIN_EXAMPLE_PROMPTS）；此处 re-export 仅为向后兼容旧内部导入路径。
// 2026-09-18 曾在此文件与 types.ts 各存一份拷贝（双维护陷阱），已收编单源。
import { DEFAULT_EXAMPLE_PROMPTS, DOMAIN_EXAMPLE_PROMPTS } from './types';
export { DEFAULT_EXAMPLE_PROMPTS } from './types';

/**
 * T83 — small header shown on every AI message: 模型名。
 * （UI-271 增补：回复时间移至底部操作行「创建分支」右侧，由 MessageTime 渲染）
 */
export function MessageMeta({ modelName }: { modelName?: string; ts?: string }): React.ReactElement | null {
  if (!modelName) return null;
  return (
    <div className="sc-msg-meta" aria-label="回复信息">
      <span className="sc-msg-meta-model">{modelName}</span>
    </div>
  );
}

/**
 * UI-271 增补 — 回复时间（底部操作行内）。
 * 时间渐进格式化（刚刚 → HH:MM → MM-DD HH:MM），30s 定时器让时间标签随时间自刷新。
 */
export function MessageTime({ ts }: { ts?: string }): React.ReactElement | null {
  const [, setTick] = useState(0);
  useEffect(() => {
    const timer = window.setInterval(() => setTick((n) => n + 1), 30000);
    return () => window.clearInterval(timer);
  }, []);
  if (!ts) return null;
  const time = formatRelativeTime(ts);
  if (!time) return null;
  return <span className="sc-msg-action-time">{time}</span>;
}

// 2026-09-18 历史残留清理 — 领域感知示例卡：默认渲染通用卡，后台查已装领域
// 包（桌面 IPC packs.listInstalled / 投影 HTTP 桥同形）按 DOMAIN_EXAMPLE_PROMPTS
// 注册表追加领域卡。桥缺失/查询失败一律停留在通用卡（无包不提领域，BLOCK-86
// 哲学同款）；查询失败静默降级不弹错。
export function useDomainExamplePrompts(): ExamplePrompt[] {
  const [prompts, setPrompts] = useState<ExamplePrompt[]>(DEFAULT_EXAMPLE_PROMPTS);
  useEffect(() => {
    let alive = true;
    (async () => {
      try {
        const packsBridge = getBridge('packs') as
          | { listInstalled?: () => Promise<unknown> }
          | null;
        const result = await packsBridge?.listInstalled?.();
        // L4-2 形状勘误同款：桌面 IPC pack:list-installed 返回 { ok, packs } 信封
        //（非裸数组），双形状兼容防信封误判成「无包」。
        const packs = Array.isArray(result)
          ? result
          : (result as { packs?: Array<{ packId?: string }> } | null)?.packs;
        if (!alive || !Array.isArray(packs)) return;
        const extra = packs.flatMap(
          (pack) => DOMAIN_EXAMPLE_PROMPTS[String(pack?.packId || '')] || [],
        );
        if (extra.length > 0) setPrompts([...DEFAULT_EXAMPLE_PROMPTS, ...extra]);
      } catch {
        // 桥缺失/查询失败 = 通用卡兜底，不打扰用户
      }
    })();
    return () => {
      alive = false;
    };
  }, []);
  return prompts;
}

export function ExamplePrompts({ prompts, onSelect }: ExamplePromptsProps): React.ReactElement {
  return (
    <div className="sc-example-prompts">
      {prompts.map((item, index) => (
        <button
          type="button"
          key={index}
          className="sc-example-card"
          onClick={() => onSelect(item.prompt)}
          title="点击使用"
          aria-label={item.title}
        >
          <div className="sc-example-icon">
            <Icon name={item.icon} size={18} />
          </div>
          <div className="sc-example-content">
            <span className="sc-example-title">{item.title}</span>
            <span className="sc-example-desc">{item.description}</span>
          </div>
        </button>
      ))}
    </div>
  );
}

/**
 * Compact a verbose stage conclusion into a single-sentence lead.
 * Used by LoopStatusPanel / ResultEditProgressList for header summaries.
 */
export function compactStageConclusion(content: string, maxLength = 240): string {
  const normalized = String(content || '')
    .trim()
    .replace(/^(?:好的?|可以)[，,：:]\s*/u, '')
    .replace(/\s+/gu, ' ');
  if (!normalized) return '';

  const sentenceEnd = normalized.search(/[。！？]/u);
  const firstSentence = sentenceEnd >= 0
    ? normalized.slice(0, sentenceEnd + 1)
    : normalized;
  if (firstSentence.length <= maxLength) return firstSentence;
  return `${firstSentence.slice(0, Math.max(1, maxLength - 1)).trimEnd()}…`;
}

