import { useCallback, useEffect, useLayoutEffect, useRef, useState, type Dispatch, type RefObject, type SetStateAction } from 'react';
import type { ChatMessage } from '@/components/copilot/copilotClient';
import { useConversationResume } from './useConversationResume';
import { useConversationRun } from '../../conversationRunStore';
import { useDurableConversationLoop } from '@/hooks/useDurableConversationLoop';

/** BLOCK-95 A1+A3 — 会话区滚动守卫：距顶 <360px 触发向上补页（prepend 后恢复视口）、
 *  跟随态（atBottom）与回底浮标（>600px 显现）。
 *  BLOCK-92 三波拆分 — 自 SimpleChat.tsx 591-642 连续段原样平移（调用点原位保持
 *  hook 顺序；atBottomRef 仍由组件持有——send 路径也写它，经参数注入）。 */
export function useScrollGuard({
  scrollRef,
  atBottomRef,
  older,
  activeRun,
  durableLoop,
  messages,
  conversationId,
}: {
  scrollRef: RefObject<HTMLDivElement | null>;
  atBottomRef: { current: boolean };
  older: ReturnType<typeof useConversationResume>['older'];
  activeRun: ReturnType<typeof useConversationRun>;
  durableLoop: ReturnType<typeof useDurableConversationLoop>;
  messages: ChatMessage[];
  conversationId: string | null | undefined;
}): {
  showJumpToBottom: boolean;
  setShowJumpToBottom: Dispatch<SetStateAction<boolean>>;
  scrollToBottom: (smooth?: boolean) => void;
  handleMessagesScroll: () => void;
} {
  const [showJumpToBottom, setShowJumpToBottom] = useState(false);
  // BLOCK-95 A1 — 向上补页时记录滚动高度，prepend 渲染后恢复视口位置。
  const prependAnchorRef = useRef<number | null>(null);
  // older 每次渲染都是新对象，onScroll 高频路径经 ref 读取。
  const olderRef = useRef(older);
  olderRef.current = older;

  const scrollToBottom = useCallback((smooth = false) => {
    const el = scrollRef.current;
    if (!el) return;
    atBottomRef.current = true;
    setShowJumpToBottom(false);
    el.scrollTo({ top: el.scrollHeight, behavior: smooth ? 'smooth' : 'auto' });
  }, []);

  useEffect(() => {
    if (scrollRef.current && atBottomRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [activeRun, durableLoop.loop, messages]);

  // 切换会话：重置跟随态（新会话加载完成后自动滚到底）。
  useEffect(() => {
    atBottomRef.current = true;
    setShowJumpToBottom(false);
  }, [conversationId]);

  // BLOCK-95 A1+A3 — 会话区滚动：距顶 <360px 触发向上补页（prepend 后恢复视口），
  // 同时更新跟随态与回底浮标。
  const handleMessagesScroll = useCallback(() => {
    const el = scrollRef.current;
    if (!el) return;
    const distToBottom = el.scrollHeight - el.scrollTop - el.clientHeight;
    atBottomRef.current = distToBottom < 120;
    setShowJumpToBottom(distToBottom > 600);
    const olderState = olderRef.current;
    if (el.scrollTop < 360 && olderState.hasMore && !olderState.loadingMore) {
      prependAnchorRef.current = el.scrollHeight;
      void olderState.loadOlder();
    }
  }, []);

  // BLOCK-95 A1 — prepend 后恢复视口：useLayoutEffect 在 DOM commit 后、绘制前
  // 同步执行（rAF 会早于 commit，delta 恒 0）；非补页路径 anchor 为 null 零开销。
  useLayoutEffect(() => {
    const anchor = prependAnchorRef.current;
    if (anchor == null) return;
    const el = scrollRef.current;
    if (!el) return;
    prependAnchorRef.current = null;
    el.scrollTop += el.scrollHeight - anchor;
  }, [messages, scrollRef]);

  return { showJumpToBottom, setShowJumpToBottom, scrollToBottom, handleMessagesScroll };
}

// ============================================================
// useSummaryRetry — AI 总结重试状态簇（UI-305 P0.2）
//
// 从 SimpleChat.tsx 整簇平移（原 297-303 的 5 个 useState + retrySummary
// useCallback + UX1H 冷却 tick effect），簇内 hook 相对顺序保持原样，
// 零行为变化。重试走 retryToolSummary：成功追加 assistant 消息并清计数/
// 冷却，失败按 RETRY_BACKOFF_MS 退避，MAX_SUMMARY_RETRIES 次后放弃。
// retryTick 仅作冷却期重渲染触发器（让「冷却中 Ns」标签秒级刷新）。
// ============================================================
import { useCallback, useEffect, useState } from 'react';
import { retryToolSummary } from '../../copilotClient';
import { clearConversationRun } from '../../conversationRunStore';
import type { ChatModelPreset } from '@/hooks/useAiSettings';
import type { SimpleMessage } from '../types';

const MAX_SUMMARY_RETRIES = 3;
const RETRY_BACKOFF_MS = [2000, 4000, 8000];

export interface SummaryRetryController {
  retrySummary: (toolJobId: string) => Promise<void>;
  summaryRetryState: Record<string, 'running' | 'done'>;
  summaryRetryErrors: Record<string, string>;
  summaryRetryAttempts: Record<string, number>;
  summaryRetryCooldownUntil: Record<string, number>;
  MAX_SUMMARY_RETRIES: number;
  retryTick: number;
}

export function useSummaryRetry({
  conversationId,
  projectId,
  activeModel,
  activeModelId,
  refreshConversations,
  appendAssistantMessage,
}: {
  conversationId: string | null;
  projectId: string;
  activeModel: ChatModelPreset | null;
  activeModelId: string;
  refreshConversations: () => Promise<void>;
  appendAssistantMessage: (message: SimpleMessage) => void;
}): SummaryRetryController {
  const [summaryRetryState, setSummaryRetryState] = useState<Record<string, 'running' | 'done'>>({});
  const [summaryRetryErrors, setSummaryRetryErrors] = useState<Record<string, string>>({});
  const [summaryRetryAttempts, setSummaryRetryAttempts] = useState<Record<string, number>>({});
  const [summaryRetryCooldownUntil, setSummaryRetryCooldownUntil] = useState<Record<string, number>>({});
  const [retryTick, setRetryTick] = useState(0);

  const retrySummary = useCallback(async (toolJobId: string) => {
    const attempts = summaryRetryAttempts[toolJobId] ?? 0;
    if (!conversationId) return;
    if (summaryRetryState[toolJobId] === 'running') return;
    if (attempts >= MAX_SUMMARY_RETRIES) return;
    if (Date.now() < (summaryRetryCooldownUntil[toolJobId] ?? 0)) return;
    setSummaryRetryState((current) => ({ ...current, [toolJobId]: 'running' }));
    setSummaryRetryErrors((current) => {
      const next = { ...current };
      delete next[toolJobId];
      return next;
    });
    try {
      const content = await retryToolSummary({
        toolJobId,
        projectId,
        conversationId,
        modelPresetId: activeModel?.endpointProfileId || activeModelId,
      });
      appendAssistantMessage({
        role: 'assistant',
        content,
        ts: new Date().toISOString(),
      });
      clearConversationRun(conversationId);
      setSummaryRetryState((current) => ({ ...current, [toolJobId]: 'done' }));
      setSummaryRetryAttempts((current) => {
        const next = { ...current };
        delete next[toolJobId];
        return next;
      });
      setSummaryRetryCooldownUntil((current) => {
        const next = { ...current };
        delete next[toolJobId];
        return next;
      });
      await refreshConversations();
    } catch (error) {
      const nextAttempts = attempts + 1;
      setSummaryRetryAttempts((current) => ({ ...current, [toolJobId]: nextAttempts }));
      setSummaryRetryState((current) => {
        const next = { ...current };
        delete next[toolJobId];
        return next;
      });
      setSummaryRetryErrors((current) => ({
        ...current,
        [toolJobId]: error instanceof Error ? error.message : 'AI 总结仍不可用，请稍后重试',
      }));
      if (nextAttempts < MAX_SUMMARY_RETRIES) {
        const backoff = RETRY_BACKOFF_MS[nextAttempts - 1] ?? 8000;
        setSummaryRetryCooldownUntil((current) => ({ ...current, [toolJobId]: Date.now() + backoff }));
      }
    }
  }, [activeModel, activeModelId, appendAssistantMessage, conversationId, projectId, refreshConversations, summaryRetryState, summaryRetryAttempts, summaryRetryCooldownUntil]);

  // UX1H: tick while any summary-retry cooldown is active so the "冷却中 Ns"
  // label and re-enable update without a full external re-render.
  useEffect(() => {
    const now = Date.now();
    const active = Object.values(summaryRetryCooldownUntil).filter((until) => until > now);
    if (active.length === 0) return;
    const minUntil = Math.min(...active);
    const timer = window.setTimeout(() => setRetryTick((t) => t + 1), Math.max(250, minUntil - Date.now()));
    return () => window.clearTimeout(timer);
  }, [summaryRetryCooldownUntil, retryTick]);

  return {
    retrySummary,
    summaryRetryState,
    summaryRetryErrors,
    summaryRetryAttempts,
    summaryRetryCooldownUntil,
    MAX_SUMMARY_RETRIES,
    retryTick,
  };
}

import { useEffect, useState } from 'react';
import { getPlatformApiPrefix } from '@/lib/authClient';
import type { SubAgentCardData } from '../../SubAgentResultCard';

/** UI-405 — 会话终态子智能体结果（服务端真相轮询 5s；失败静默保留上次数据）。
 *  BLOCK-92 三波拆分 — 自 SimpleChat.tsx 尾部原样平移（调用点原位，零行为变化）。 */
export function useTerminalSubAgentResults(projectId: string | null | undefined, conversationId: string | null | undefined): SubAgentCardData[] {
  const [rows, setRows] = useState<SubAgentCardData[]>([]);
  useEffect(() => {
    if (!conversationId) return;
    let alive = true;
    const load = () => {
      // BLOCK-102 P4 — 页面隐藏时跳过轮询（回到可见即由下个 tick 恢复）
      if (typeof document !== 'undefined' && document.hidden) return;
      fetch(`${getPlatformApiPrefix()}/ai/agent/tasks?limit=50&conversationId=${encodeURIComponent(conversationId)}`, {
        headers: { Authorization: 'Bearer desktop-local' },
      })
        .then((resp) => resp.json())
        .then((body) => {
          if (!alive || !body || body.ok !== true) return;
          const terminal = (body.tasks || [])
            .filter((t: { status?: string }) => t.status && t.status !== 'running')
            .slice(-2)
            .map((t: { taskId: string; taskText?: string; status: string; createdAt?: string; finishedAt?: string; summaryHead?: string | null }) => ({
              taskId: String(t.taskId || ''),
              taskText: String(t.taskText || ''),
              status: String(t.status || ''),
              createdAt: t.createdAt || null,
              finishedAt: t.finishedAt || null,
              summaryHead: t.summaryHead || null,
            }));
          setRows(terminal);
        })
        .catch(() => {});
    };
    load();
    const timer = window.setInterval(load, 5000);
    return () => {
      alive = false;
      window.clearInterval(timer);
    };
  }, [projectId, conversationId]);
  return rows;
}

