// ============================================================
// ansi — UI-315 终端块输出 ANSI 解析（零依赖，SGR 子集）。
//
// 真实命令输出（git diff --color、ls --color、构建工具）常带 ANSI
// 转义序列：裸显示会是一堆乱码文本。这里把 SGR 颜色/字重/下划线
// 解析为带 class 的文本片段（CSS 上色），其余转义序列（光标移动、
// OSC 标题等）直接剥除。
// ============================================================

export interface AnsiSpan {
  text: string;
  /** 组合的样式 class（term-bold / term-ul / term-dim / term-c0..term-c15），空串表示无样式 */
  cls: string;
}

/** 16 色 ANSI → 终端块色板（与 .sc-tool-term 的暗色底协调）。 */
const FG_CLASSES = [
  'term-c0', 'term-c1', 'term-c2', 'term-c3',
  'term-c4', 'term-c5', 'term-c6', 'term-c7',
  'term-c8', 'term-c9', 'term-c10', 'term-c11',
  'term-c12', 'term-c13', 'term-c14', 'term-c15',
];

// CSI 终止字节范围；SGR 是以 m 结尾的序列。
const CSI_RE = /\x1b\[([0-9;:?<=>\s]*[ -/]*[@-~])/g;
const OSC_RE = /\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)?/g;
const SINGLE_ESC_RE = /\x1b[@-Z\\-_]/g;

interface TermStyle {
  fg: number | null; // 0-15（已折算 30-37/90-97），null = 默认
  bold: boolean;
  dim: boolean;
  underline: boolean;
}

function styleToClass(style: TermStyle): string {
  const parts: string[] = [];
  if (style.bold) parts.push('term-bold');
  if (style.dim) parts.push('term-dim');
  if (style.underline) parts.push('term-ul');
  if (style.fg !== null) parts.push(FG_CLASSES[style.fg]);
  return parts.join(' ');
}

/** 应用一段 SGR 参数到当前样式（就地修改）。 */
function applySgr(style: TermStyle, paramsText: string): void {
  // 38;5;n / 38;2;r;g;b / 48 系列等扩展色本终端块不支持，跳过整个参数组。
  const raw = paramsText.split(/[:;]/).map((v) => Number.parseInt(v, 10));
  const params = raw.map((v) => (Number.isFinite(v) ? v : 0));
  let i = 0;
  while (i < params.length) {
    const code = params[i];
    if (code === 0) {
      style.fg = null; style.bold = false; style.dim = false; style.underline = false;
    } else if (code === 1) style.bold = true;
    else if (code === 2) style.dim = true;
    else if (code === 4) style.underline = true;
    else if (code === 22) { style.bold = false; style.dim = false; }
    else if (code === 23) style.underline = false; // 非 ITALIC（本终端不用斜体）
    else if (code === 24) style.underline = false;
    else if (code === 39) style.fg = null;
    else if (code >= 30 && code <= 37) style.fg = code - 30;
    else if (code >= 90 && code <= 97) style.fg = code - 90 + 8;
    else if (code === 38 || code === 48) {
      // 扩展色：38;5;n / 38;2;r;g;b —— 前景跳过参数组（背景一律忽略）
      if (code === 38) {
        if (params[i + 1] === 5) i += 3;
        else if (params[i + 1] === 2) i += 5;
        else i += 1;
      }
    }
    i += 1;
  }
}

/**
 * 把带 ANSI 转义的终端文本解析为带样式 class 的片段。
 * 非颜色类转义（光标移动/OSC）直接剥除；纯文本输入返回单片段。
 */
export function parseAnsiToSpans(text: string): AnsiSpan[] {
  if (!text) return [];
  // 先剥 OSC 与非 SGR 的 CSI/单字符转义
  const cleaned = text
    .replace(OSC_RE, '')
    .replace(CSI_RE, (match, body: string) => (body.endsWith('m') ? `\x1b[${body}` : ''))
    .replace(SINGLE_ESC_RE, '');
  if (!cleaned.includes('\x1b')) return [{ text: cleaned, cls: '' }];

  const spans: AnsiSpan[] = [];
  const style: TermStyle = { fg: null, bold: false, dim: false, underline: false };
  let buffer = '';
  const flush = () => {
    if (buffer) {
      const cls = styleToClass(style);
      spans.push({ text: buffer, cls });
      buffer = '';
    }
  };
  const re = /\x1b\[([0-9;:?<=>\s]*[ -/]*[@-~])/g;
  let lastIndex = 0;
  for (let m = re.exec(cleaned); m !== null; m = re.exec(cleaned)) {
    // 转义序列之前的文本按当前（旧）样式成段；随后新样式才对后续文本生效
    buffer += cleaned.slice(lastIndex, m.index);
    lastIndex = m.index + m[0].length;
    flush();
    if (m[1].endsWith('m')) applySgr(style, m[1].slice(0, -1));
  }
  buffer += cleaned.slice(lastIndex);
  flush();
  return spans.filter((span) => span.text.length > 0);
}

/**
 * BLOCK-34 P3 — 后台进程浮窗客户端
 *
 * 只读查询 petri-server 的 background-processes 路由（数据源为
 * workspace-tools 内存进程表，per conversation 隔离）：
 *   - listBackgroundProcesses: 列出本会话后台进程（含日志尾部摘要）
 *   - fetchProcessLogTail: 读单个进程日志尾部（浮窗 1s 轮询用）
 */

import { getApiPrefix, getAuthHeader } from './copilotClient';

export type BackgroundProcessStatus =
  | 'running'
  | 'exited'
  | 'stopped'
  | 'failed'
  | 'orphaned';

export interface BackgroundProcessView {
  processId: string;
  pid: number;
  status: BackgroundProcessStatus;
  command: string;
  cwd?: string;
  shell?: string;
  startedAtIso: string;
  durationMs: number;
  exitCode?: number | null;
  signal?: string | null;
  logPath?: string;
  logTail?: string;
  logTruncated?: boolean;
  logSizeBytes?: number;
  spawnError?: string;
}

async function requestJson<T>(url: string): Promise<T> {
  const resp = await fetch(url, { headers: { ...getAuthHeader() } });
  let body: (T & { status?: string; error?: string }) | null = null;
  try {
    body = await resp.json();
  } catch {
    // 非 JSON 响应按 HTTP 状态处理
  }
  if (!resp.ok || !body) {
    throw new Error(body?.error || `HTTP ${resp.status}`);
  }
  return body;
}

/** 列出本会话的后台进程（每项含日志尾部摘要）。 */
export async function listBackgroundProcesses(
  conversationId: string,
  projectId?: string | null
): Promise<BackgroundProcessView[]> {
  const params = new URLSearchParams({ conversationId });
  if (projectId) params.set('projectId', projectId);
  const body = await requestJson<{ count: number; processes: BackgroundProcessView[] }>(
    `${getApiPrefix()}/ai/agent/background-processes?${params.toString()}`
  );
  return Array.isArray(body.processes) ? body.processes : [];
}

/** 读取单个进程的状态与日志尾部。进程不存在或属于其他会话时抛错。 */
export async function fetchProcessLogTail(
  processId: string,
  conversationId: string,
  projectId?: string | null,
  bytes?: number
): Promise<BackgroundProcessView> {
  const params = new URLSearchParams({ conversationId });
  if (projectId) params.set('projectId', projectId);
  if (Number.isFinite(bytes)) params.set('bytes', String(bytes));
  const body = await requestJson<{ process: BackgroundProcessView }>(
    `${getApiPrefix()}/ai/agent/background-processes/${encodeURIComponent(
      processId
    )}/log?${params.toString()}`
  );
  return body.process;
}

import { describe, expect, it } from 'vitest'
import {
  INITIAL_NAV_STATE,
  stepHistoryNavigation,
  type HistoryNavState,
} from './chatHistoryNav'

// history 约定：最新在末尾，调用方会反序传入，故此处 index 越大越新。
const history = ['first', 'second', 'third']

describe('stepHistoryNavigation', () => {
  it('history 为空时原样返回输入，不改变导航态', () => {
    const { state, value } = stepHistoryNavigation([], INITIAL_NAV_STATE, 'up', 'draft')
    expect(state).toEqual(INITIAL_NAV_STATE)
    expect(value).toBe('draft')
  })

  it('未导航且输入非空时按 ↑ 不触发（保护草稿）', () => {
    const { state, value } = stepHistoryNavigation(history, INITIAL_NAV_STATE, 'up', 'my draft')
    expect(state).toEqual(INITIAL_NAV_STATE)
    expect(value).toBe('my draft')
  })

  it('空输入按 ↑ 从最新一条已发送消息开始回溯', () => {
    const { state, value } = stepHistoryNavigation(history, INITIAL_NAV_STATE, 'up', '')
    expect(state.index).toBe(2) // 'third'
    expect(value).toBe('third')
  })

  it('重复按 ↑ 向更旧走', () => {
    let state: HistoryNavState = { index: 2, draft: '' }
    let r = stepHistoryNavigation(history, state, 'up', 'third')
    expect(r.state.index).toBe(1)
    expect(r.value).toBe('second')
    r = stepHistoryNavigation(history, r.state, 'up', 'second')
    expect(r.state.index).toBe(0)
    expect(r.value).toBe('first')
  })

  it('已是最旧再按 ↑ 不再前进', () => {
    const state: HistoryNavState = { index: 0, draft: '' }
    const r = stepHistoryNavigation(history, state, 'up', 'first')
    expect(r.state.index).toBe(0)
    expect(r.value).toBe('first')
  })

  it('按 ↓ 向更新走，越过最新项还原草稿并退出导航', () => {
    let state: HistoryNavState = { index: 0, draft: 'my draft' }
    let r = stepHistoryNavigation(history, state, 'down', 'first')
    expect(r.state.index).toBe(1)
    expect(r.value).toBe('second')
    r = stepHistoryNavigation(history, r.state, 'down', 'second')
    expect(r.state.index).toBe(2)
    expect(r.value).toBe('third')
    r = stepHistoryNavigation(history, r.state, 'down', 'third')
    expect(r.state).toEqual(INITIAL_NAV_STATE)
    expect(r.value).toBe('my draft')
  })

  it('未导航时按 ↓ 无操作', () => {
    const { state, value } = stepHistoryNavigation(history, INITIAL_NAV_STATE, 'down', 'draft')
    expect(state).toEqual(INITIAL_NAV_STATE)
    expect(value).toBe('draft')
  })
})

// 聊天输入框的键盘历史回溯（纯逻辑，便于单测）。
//
// 行为约定（参考终端 / 常见聊天框的 ↑/↓ 历史）：
// - 历史源是「已发送的用户消息」，由调用方从会话消息里过滤 role==='user' 后反序传入
//   （最新在前）。本模块不持有历史，只负责在给定 history 数组上做索引导航。
// - 空输入或未处于导航态时按 ↑：从该会话最新一条已发送消息开始回溯（先保存当前草稿）。
// - 非空且未导航时按 ↑：不打断正在编辑的多行草稿，放行光标（默认行为）。
// - 导航态下 ↑ 向更旧走，↓ 向更新走；↓ 越过最新项时还原进入导航前保存的草稿。
// - 到达最旧项再按 ↑ 不再前进；未导航态按 ↓ 无操作。

export interface HistoryNavState {
  /** null = 未进入导航（输入框即实时草稿）；否则为 history 数组下标 */
  index: number | null
  /** 进入导航时捕获的实时草稿，离开历史（↓ 越界）时还原 */
  draft: string
}

export const INITIAL_NAV_STATE: HistoryNavState = { index: null, draft: '' }

export function stepHistoryNavigation(
  history: string[],
  state: HistoryNavState,
  direction: 'up' | 'down',
  currentInput: string,
): { state: HistoryNavState; value: string } {
  const len = history.length
  if (len === 0) return { state, value: currentInput }

  if (direction === 'up') {
    // 未在导航态：仅当输入为空才进入导航，保护正在编辑的草稿不被 ↑ 覆盖。
    if (state.index === null) {
      if (currentInput.trim() !== '') return { state, value: currentInput }
      const idx = len - 1
      return { state: { index: idx, draft: currentInput }, value: history[idx] }
    }
    if (state.index <= 0) return { state, value: currentInput } // 已是最旧
    const idx = state.index - 1
    return { state: { index: idx, draft: state.draft }, value: history[idx] }
  }

  // direction === 'down'
  if (state.index === null) return { state, value: currentInput } // 未导航，无操作
  const idx = state.index + 1
  if (idx >= len) {
    // 越过最新项 → 还原进入导航前保存的草稿，退出导航态。
    return { state: INITIAL_NAV_STATE, value: state.draft }
  }
  return { state: { index: idx, draft: state.draft }, value: history[idx] }
}

// ============================================================
// conversationChangesStore — BLOCK-31 P2 会话级改动索引
//
// 记录「哪个会话改了哪些文件」：
//   - 运行中：conversationRunStore.onToolResult 实时记录成功的
//     workspace_write / workspace_replace（per-conversation 维度）
//   - 任务收尾：订阅 petri:agent-task-done，用后端权威 filesChanged
//     清单（task_events 回放聚合产物）按 conversationId 对账合并
//
// 消费方：AgentChangesCard（默认只显示当前会话的改动）。
// git working tree 仍是 diff/统计的事实源；本 store 只负责「路径归属」。
// ============================================================

import { petriEvents, subscribePetriEvent } from '@/lib/events';
import { getApiPrefix } from '@/lib/env';

export interface ConversationFileChange {
  path: string;
  status: 'created' | 'modified';
  /** 最近一次改动的 epoch ms（用于排序） */
  lastChangedAt: number;
  /** UI-273 — 执行步骤归属：改动发生时的 agent 迭代号（未知时缺省） */
  iteration?: number;
  /** UI-273 — 产生改动的工具名（workspace_write / workspace_replace） */
  tool?: string;
}

type ChangeListener = () => void;

const changesByConversation = new Map<string, Map<string, ConversationFileChange>>();
// useSyncExternalStore 的 getSnapshot 必须返回稳定引用：每次变更后使缓存失效，
// 读取时按需重建并缓存。
const snapshotCache = new Map<string, ConversationFileChange[]>();
const EMPTY: ConversationFileChange[] = [];
const listeners = new Set<ChangeListener>();

let subscribed = false;

function invalidateSnapshot(conversationId: string): void {
  snapshotCache.delete(conversationId);
}

function ensureSubscribed(): void {
  if (subscribed || typeof window === 'undefined') return;
  subscribed = true;
  // 权威对账：任务收尾时用后端清单覆盖该会话的归属（保留 live 记录中
  // 权威清单之外的路径，兼容 workspace_exec 等盲区与多任务并发）。
  subscribePetriEvent(petriEvents.agentTaskDone, (detail) => {
    if (!detail?.conversationId || !Array.isArray(detail.filesChanged)) return;
    const authoritative = detail.filesChanged.filter(
      (item) => item && typeof item.path === 'string'
    );
    if (authoritative.length === 0) return;
    const bucket = changesByConversation.get(detail.conversationId) ?? new Map();
    const now = Date.now();
    for (const item of authoritative) {
      const existing = bucket.get(item.path);
      bucket.set(item.path, {
        path: item.path,
        status: item.status === 'created' ? 'created' : 'modified',
        lastChangedAt: existing?.lastChangedAt ?? now,
        // UI-273 — 权威清单携带执行步骤归属（旧格式清单无此字段则保留 live 值）
        iteration:
          typeof item.iteration === 'number' ? item.iteration : existing?.iteration,
        tool: typeof item.tool === 'string' ? item.tool : existing?.tool,
      });
    }
    // 权威清单之外的 live 记录保留（exec 盲区 / 并发任务），不删除
    changesByConversation.set(detail.conversationId, bucket);
    invalidateSnapshot(detail.conversationId);
    emitChange();
  });
}

function emitChange(): void {
  for (const listener of listeners) {
    try {
      listener();
    } catch {}
  }
}

/** 运行中实时记录（workspace_write / workspace_replace 成功结果）。 */
export function recordConversationFileChange(
  conversationId: string | undefined | null,
  path: string,
  status: 'created' | 'modified',
  /** UI-273 — 执行步骤归属（迭代号 + 工具名），未知时缺省 */
  attribution?: { iteration?: number; tool?: string }
): void {
  if (!conversationId || !path) return;
  ensureSubscribed();
  const bucket = changesByConversation.get(conversationId) ?? new Map();
  bucket.set(path, {
    path,
    status,
    lastChangedAt: Date.now(),
    iteration: attribution?.iteration,
    tool: attribution?.tool,
  });
  changesByConversation.set(conversationId, bucket);
  invalidateSnapshot(conversationId);
  emitChange();
}

/** 读取某会话的改动文件（按最近改动倒序）。返回缓存引用，勿直接修改。 */
export function getConversationFileChanges(
  conversationId: string | undefined | null
): ConversationFileChange[] {
  if (!conversationId) return EMPTY;
  const cached = snapshotCache.get(conversationId);
  if (cached) return cached;
  const bucket = changesByConversation.get(conversationId);
  const snapshot = bucket
    ? Array.from(bucket.values()).sort((a, b) => b.lastChangedAt - a.lastChangedAt)
    : EMPTY;
  snapshotCache.set(conversationId, snapshot);
  return snapshot;
}

/** React useSyncExternalStore 订阅。 */
export function subscribeConversationChanges(listener: ChangeListener): () => void {
  ensureSubscribed();
  listeners.add(listener);
  return () => listeners.delete(listener);
}

/** 会话改动清空（提交/还原后由调用方触发全量刷新用不到此函数时勿滥用）。 */
export function clearConversationFileChanges(conversationId: string): void {
  if (changesByConversation.delete(conversationId)) {
    invalidateSnapshot(conversationId);
    emitChange();
  }
}

// ============================================================
// BLOCK-40 P2 — reload 后会话改动水合
//
// 数据源：GET /api/ai/agent/conversation-changes?conversationId=
// （tasks.files_changed_json 权威清单跨任务合并，见 routes/ai-agent/
// conversation-changes.js）。纪律：
//   - 只填充 live/已有记录缺失的路径（live 记录与权威对账优先，不覆盖）
//   - in-flight 去重 + 每会话每页面生命周期只拉取一次
//   - 失败静默：维持现状全量视图回退，不新增报错面
// ============================================================

/** 权威清单端点返回的单条改动（后端 camelCase 字段）。 */
interface HydratedChangeItem {
  path?: unknown;
  status?: unknown;
  iteration?: unknown;
  tool?: unknown;
  lastChangedAt?: unknown;
}

/** epoch ms 解析：ISO 字符串 / 数字均可，不可解析时回退 Date.now()。 */
function toEpochMs(value: unknown): number {
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  if (typeof value === 'string') {
    const ms = Date.parse(value);
    if (Number.isFinite(ms)) return ms;
  }
  return Date.now();
}

/** 把权威清单条目合并进内存索引（只填充缺失路径，不覆盖已有记录）。 */
export function mergeConversationFileChanges(
  conversationId: string | undefined | null,
  items: HydratedChangeItem[]
): void {
  if (!conversationId || !Array.isArray(items)) return;
  const valid = items.filter(
    (item): item is { path: string } & HydratedChangeItem =>
      Boolean(item) && typeof item.path === 'string' && item.path.length > 0
  );
  if (valid.length === 0) return;
  ensureSubscribed();
  const bucket = changesByConversation.get(conversationId) ?? new Map();
  for (const item of valid) {
    if (bucket.has(item.path)) continue; // live / 已有记录优先，不覆盖
    bucket.set(item.path, {
      path: item.path,
      status: item.status === 'created' ? 'created' : 'modified',
      lastChangedAt: toEpochMs(item.lastChangedAt),
      iteration: typeof item.iteration === 'number' ? item.iteration : undefined,
      tool: typeof item.tool === 'string' ? item.tool : undefined,
    });
  }
  changesByConversation.set(conversationId, bucket);
  invalidateSnapshot(conversationId);
  emitChange();
}

const hydrateInFlight = new Map<string, Promise<void>>();
const hydratedOnce = new Set<string>();

/**
 * 从后端权威清单水合某会话的改动归属（挂载/切会话时调用）。
 * 同会话只拉取一次（含并发去重）；失败静默维持全量回退。
 */
export function hydrateConversationFileChanges(
  conversationId: string | undefined | null
): Promise<void> {
  if (!conversationId) return Promise.resolve();
  if (hydratedOnce.has(conversationId)) return Promise.resolve();
  const inFlight = hydrateInFlight.get(conversationId);
  if (inFlight) return inFlight;
  const promise = (async () => {
    try {
      const res = await fetch(
        `${getApiPrefix()}/ai/agent/conversation-changes?conversationId=${encodeURIComponent(conversationId)}`
      );
      if (res.ok) {
        const data = (await res.json()) as { changes?: HydratedChangeItem[] };
        mergeConversationFileChanges(
          conversationId,
          Array.isArray(data?.changes) ? data.changes : []
        );
      }
      // 非 2xx（400 校验失败 / 500 查询失败）— 诚实回退现状全量视图
    } catch {
      // 网络失败静默：不新增报错面
    } finally {
      hydrateInFlight.delete(conversationId);
      hydratedOnce.add(conversationId);
    }
  })();
  hydrateInFlight.set(conversationId, promise);
  return promise;
}

