 * （免刷新自动亮「继续执行」的核心判据）；fetch 网络拒绝退避重连；重试耗尽
 * 如实上抛；HTTP 4xx 不重试；用户停止（abort）不重试且不触发 onError。
 */
import { afterEach, describe, expect, it, vi } from 'vitest';
