export interface StreamChatOptions {
  messages: ChatMessage[];
  context?: CopilotContext;
  signal?: AbortSignal;
  /** Active conversation id; server will create one if absent */
  conversationId?: string;
  /** Desktop workspace selected chat model preset id */
  modelPresetId?: string;
  /** Model id discovered from the selected provider Endpoint. */
  modelName?: string;
  /** AGENT-CONCURRENCY: spawn this run as a sub-agent child of an existing primary task. */
  kind?: 'primary' | 'subagent';
  /** Parent primary taskId when kind === 'subagent' (server validates ownership). */
  parentTaskId?: string;
  /**
   * BLOCK-81 P1 — 思考档位（中性三档）。缺省/undefined＝不发任何思考参数
   * （服务端按 profile 能力位门控后映射上游参数）。P2 起由 composer 档位控件提供。
   */
  thinkingLevel?: 'off' | 'standard' | 'high';
  onDelta: (delta: string) => void;
  /** UI-272 — 模型思考段增量（reasoning_content），按迭代聚合由调用方处理 */
  onReasoning?: (delta: string) => void;
  onDone?: () => void;
  /** BLOCK-38 P2: info.resumable = 服务中断清扫标记的任务（可续跑），interruptedAt 为中断时间。
   *  BLOCK-56 P1: info.fallbackTaskId = 后端已自动切备用模型新建的续跑任务，前端应切换订阅。 */
  onError?: (
    err: Error,
    info?: {
      resumable?: boolean;
      interruptedAt?: string | null;
      fallbackTaskId?: string | null;
      fallbackLabel?: string | null;
    }
  ) => void;
  /** BLOCK-49 加映 — proactive：子 agent 终态通知（child_finished 事件）。 */
  onChildFinished?: (info: {
    childTaskId: string;
    status: string;
    summaryHead: string;
  }) => void;
  /** BLOCK-56 P1 — 模型降级事件（请求级/任务级），info.message 为用户可读文案。 */
  onModelFallback?: (info: {
    scope?: 'request_level' | 'task_level' | string;
    fromProfileId?: string | null;
    toProfileId?: string | null;
    toProfileLabel?: string | null;
    reason?: string | null;
    newTaskId?: string | null;
    message?: string | null;
  }) => void;
  /** BLOCK-39: 订阅断线进入第 attempt 次重连（afterSeq=lastSeq 续传），nextRetryMs 后重试。 */
  onStreamReconnecting?: (info: { taskId: string; attempt: number; lastSeq: number; nextRetryMs: number }) => void;
  /** Agent iteration started (1-indexed) */
  onIter?: (n: number) => void;
  /** Agent runtime status that should be visible while no answer text is available. */
  onAgentStatus?: (status: {
    phase: string;
    message: string;
    attempt?: number;
    maxAttempts?: number;
    reason?: string;
  }) => void;
  /** Model-authored, user-facing progress emitted before a tool batch. */
  onAgentProgress?: (progress: { iteration: number; content: string }) => void;
  /** RS5: durable ChangeSet materialization / Job / Revision stage progress. */
  onResultEditProgress?: (progress: ResultEditProgressEvent) => void;
  /** Tool call started */
  onToolCall?: (e: ToolCallEvent) => void;
  /** BLOCK-33 P3 — workspace_exec 增量输出（节流聚合后的文本块） */
  onToolOutput?: (e: ToolOutputEvent) => void;
  /** Tool call returned */
  onToolResult?: (e: ToolResultEvent) => void;
  /** BLOCK-97 — todo_write 成功回执后的整单清单快照（task_todo 事件） */
  onTaskTodo?: (items: AgentTaskTodoItem[]) => void;
  /** BLOCK-94 / UI-402 — 知识溯源条（自动召回注入的块清单，诚实可见） */
  onKnowledgeCitations?: (info: { citations: KnowledgeCitation[] }) => void;
  /** BLOCK-98 M4 — 用户消息插队入队通知（运行中 steer） */
  onInputQueued?: (info: { text: string; depth: number }) => void;
  /** Server announces (or creates) the active conversation */
  onConversation?: (info: { conversationId: string; title?: string }) => void;
  /** Server detected the user has pivoted to a new topic mid-conversation */
  onTopicShift?: (info: { conversationId: string; reason: string }) => void;
  /** HLE-C4: Loop Controller phase change (started / cancelled / blocked / completed) */
  onLoopPhase?: (info: { phase: string; loopRunId?: string; publicConclusion?: string; reason?: string; automationMode?: string; executionIntent?: 'task_draft' | 'task_execute' }) => void;
  /** HLE-C4: Loop Controller iteration recorded after each agent turn */
  onLoopIteration?: (info: { loopRunId: string; iterationId: string; sequence: number; decision: string; decisionReasonCode: string; publicConclusion: string; status: string; proposedActionKey: string | null; actionKeyHash: string | null }) => void;
  /** Background task created for this run. Used by the UI to request a real cancellation. */
  onTaskStarted?: (taskId: string) => void;
}

// ============================================================
// Conversation API client
// ============================================================

import { getApiPrefix } from './copilotClient';

function getAuthHeader(): Record<string, string> {
  if (typeof window === 'undefined') return {};
  try {
    const token = localStorage.getItem('petri_token');
    return token ? { Authorization: `Bearer ${token}` } : {};
  } catch {
    return {};
  }
}

export type ConversationStatus = 'active' | 'archived';

export interface ConversationSummary {
  id: string;
  title: string;
  status: ConversationStatus;
  last_page: string | null;
  message_count: number;
  created_at: string;
  updated_at: string;
  last_topic_shift_at?: string | null;
  last_topic_shift_reason?: string | null;
  project_id?: string | null;
  /** Branch support: ID of the parent conversation this was forked from */
  parent_id?: string | null;
  /** Branch support: visual color identifier for the branch line */
  branch_color?: string | null;
  /** BLOCK-88 P2（D3）：会话来源标记；'federation-delegation'=访客工程师委托会话 */
  origin?: string | null;
}

export interface ConversationMessage {
  id: string;
  role: 'user' | 'assistant' | 'system';
  content: string;
  ts: string;
  meta?: Record<string, unknown> | null;
}

export async function listConversations(
  status: ConversationStatus | 'all' = 'active',
  projectId?: string,
  opts?: { includeFederated?: boolean }
): Promise<ConversationSummary[]> {
  try {
    let url = getApiPrefix() + '/ai/conversations?status=' + status;
    if (projectId) url += '&project_id=' + encodeURIComponent(projectId);
    // BLOCK-88 P2（D3）：显式查看联邦委托会话（服务端默认视图隔离）
    if (opts && opts.includeFederated) url += '&includeFederated=1';
    const resp = await fetch(url, {
      headers: getAuthHeader(),
    });
    if (!resp.ok) return [];
    const data = await resp.json();
    return data.status === 'ok' ? data.conversations || [] : [];
  } catch {
    return [];
  }
}

export async function createConversation(
  title?: string,
  lastPage?: string,
  projectId?: string | null
): Promise<ConversationSummary | null> {
  try {
    const resp = await fetch(getApiPrefix() + '/ai/conversations', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', ...getAuthHeader() },
      body: JSON.stringify({ title: title || '新对话', lastPage: lastPage || null, project_id: projectId || null }),
    });
    if (!resp.ok) return null;
    const data = await resp.json();
    return data.status === 'ok' ? data.conversation : null;
  } catch {
    return null;
  }
}

export async function getConversationMessages(
  id: string,
  limit = 100
): Promise<ConversationMessage[]> {
  try {
    const resp = await fetch(
      getApiPrefix() + '/ai/conversations/' + encodeURIComponent(id) + '/messages?limit=' + limit,
      { headers: getAuthHeader() }
    );
    if (!resp.ok) return [];
    const data = await resp.json();
    return data.status === 'ok' ? data.messages || [] : [];
  } catch {
    return [];
  }
}

/** BLOCK-99 G4 — 会话存在性校验（管理台复用独立 conversation；404/离线 → null）。 */
export async function getConversation(
  id: string
): Promise<ConversationSummary | null> {
  try {
    const resp = await fetch(
      getApiPrefix() + '/ai/conversations/' + encodeURIComponent(id),
      { headers: getAuthHeader() }
    );
    if (!resp.ok) return null;
    const data = await resp.json();
    return data.status === 'ok' ? data.conversation : null;
  } catch {
    return null;
  }
}

/** BLOCK-95 B2/A5 — 会话压缩留痕（诚实可见；DB 原文始终可见）。 */
export interface ConversationCompactionInfo {
  summary: string;
  coversCount: number;
  sourceTokens: number;
  updatedAt: string;
}

/** BLOCK-95 A1 — 分页信封：最新窗口 + 向上游标。before=上一页响应的 nextBefore。 */
export interface ConversationMessagesPage {
  messages: ConversationMessage[];
  hasMore: boolean;
  nextBefore: number | null;
  /** 本批第一条（最旧）在全量消息中的 0-based 序号；fork-from-message 的
   *  untilIndex 由「窗口内 index」换算为「全量 index」时使用。 */
  windowOffset: number;
  /** BLOCK-95 B2/A5 — 会话压缩视图留痕（无压缩为 null）。 */
  compaction?: ConversationCompactionInfo | null;
}

export async function getConversationMessagesPage(
  id: string,
  limit = 200,
  before?: number | null
): Promise<ConversationMessagesPage | null> {
  try {
    let url =
      getApiPrefix() + '/ai/conversations/' + encodeURIComponent(id) + '/messages?limit=' + limit;
    if (before) url += '&before=' + before;
    const resp = await fetch(url, { headers: getAuthHeader() });
    if (!resp.ok) return null;
    const data = await resp.json();
    if (data.status !== 'ok') return null;
    return {
      messages: data.messages || [],
      hasMore: Boolean(data.hasMore),
      nextBefore: typeof data.nextBefore === 'number' ? data.nextBefore : null,
      windowOffset: typeof data.windowOffset === 'number' ? data.windowOffset : 0,
      compaction: data.compaction || null,
    };
  } catch {
    return null;
  }
}

export async function renameConversation(id: string, title: string): Promise<boolean> {
  try {
    const resp = await fetch(
      getApiPrefix() + '/ai/conversations/' + encodeURIComponent(id) + '/update',
      {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', ...getAuthHeader() },
        body: JSON.stringify({ title }),
      }
    );
    return resp.ok;
  } catch {
    return false;
  }
}

export async function archiveConversation(id: string, archive: boolean): Promise<boolean> {
  try {
    const resp = await fetch(
      getApiPrefix() + '/ai/conversations/' + encodeURIComponent(id) + '/update',
      {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', ...getAuthHeader() },
        body: JSON.stringify({ status: archive ? 'archived' : 'active' }),
      }
    );
    return resp.ok;
  } catch {
    return false;
  }
}

export async function deleteConversation(id: string): Promise<boolean> {
  try {
    const resp = await fetch(getApiPrefix() + '/ai/conversations/' + encodeURIComponent(id), {
      method: 'DELETE',
      headers: getAuthHeader(),
    });
    return resp.ok;
  } catch {
    return false;
  }
}

export async function dismissTopicShift(id: string): Promise<boolean> {
  try {
    const resp = await fetch(
      getApiPrefix() + '/ai/conversations/' + encodeURIComponent(id) + '/dismiss-topic-shift',
      {
        method: 'POST',
        headers: getAuthHeader(),
      }
    );
    return resp.ok;
  } catch {
    return false;
  }
}

/**
 * Fork an existing conversation — creates a new conversation with messages copied.
 * @param id - source conversation id
 * @param title - optional new conversation title
 * @param untilIndex - optional 0-based message index; if provided, only messages up to that index (inclusive) are copied.
 */
export async function forkConversation(
  id: string,
  title?: string,
  untilIndex?: number
): Promise<ConversationSummary | null> {
  try {
    const body: Record<string, unknown> = {};
    if (title !== undefined) body.title = title;
    if (untilIndex !== undefined) body.untilIndex = untilIndex;
    const resp = await fetch(
      getApiPrefix() + '/ai/conversations/' + encodeURIComponent(id) + '/fork',
      {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', ...getAuthHeader() },
        body: JSON.stringify(body),
      }
    );
    if (!resp.ok) return null;
    const data = await resp.json();
    return data.status === 'ok' ? data.conversation : null;
  } catch {
    return null;
  }
}

import React from 'react';
import { cleanup, fireEvent, render, screen, waitFor } from '@testing-library/react';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { CopilotMarkdown } from './copilotMarkdown';
import { __resetFileReferenceCache, type ResolveResponse } from '@/lib/chat-file-references';

describe('CopilotMarkdown file references', () => {
  beforeEach(() => {
    __resetFileReferenceCache();
  });

  afterEach(() => {
    cleanup();
    vi.restoreAllMocks();
    vi.unstubAllGlobals();
    __resetFileReferenceCache();
  });

  it('turns a verified inline-code filename into a direct-open link', async () => {
    const fetchMock = vi.fn(async () => ({
      ok: true,
      status: 200,
      json: async () => ({
        ok: true,
        results: [{
          reference: 'report.html',
          resolved: {
            kind: 'artifact',
            jobId: 'job-1',
            artifactName: 'report.html',
            projectId: 'proj-1',
          },
        }],
      }) satisfies ResolveResponse,
    } as Response));
    vi.stubGlobal('fetch', fetchMock);
    const onFileReferenceClick = vi.fn();

    render(
      <CopilotMarkdown
        text="查看 `report.html`"
        resolveContext={{ projectId: 'proj-1', activeJobId: 'job-1' }}
        onFileReferenceClick={onFileReferenceClick}
      />,
    );

    const link = await screen.findByRole('link', { name: 'report.html' });
    expect(link.className).toContain('cp-file-ref-code');
    fireEvent.click(link);
    expect(onFileReferenceClick).toHaveBeenCalledWith(expect.objectContaining({
      raw: 'report.html',
      kind: 'artifact',
      resolved: expect.objectContaining({ jobId: 'job-1', artifactName: 'report.html' }),
    }));
  });

  it('auto-links a verified source filename in assistant prose', async () => {
    const fetchMock = vi.fn(async () => ({
      ok: true,
      status: 200,
      json: async () => ({
        ok: true,
        results: [{
          reference: 'model-registry.ts',
          resolved: {
            kind: 'workspace',
            projectId: 'proj-1',
            relativePath: 'frontend/src/model-registry.ts',
            name: 'model-registry.ts',
          },
        }],
      }) satisfies ResolveResponse,
    } as Response));
    vi.stubGlobal('fetch', fetchMock);
    const onFileReferenceClick = vi.fn();

    render(
      <CopilotMarkdown
        text="已更新 model-registry.ts，请点击查看。"
        resolveContext={{ projectId: 'proj-1' }}
        onFileReferenceClick={onFileReferenceClick}
      />,
    );

    const link = await screen.findByRole('link', { name: 'model-registry.ts' });
    fireEvent.click(link);
    expect(onFileReferenceClick).toHaveBeenCalledWith(expect.objectContaining({
      raw: 'model-registry.ts',
      kind: 'workspace',
      resolved: expect.objectContaining({ relativePath: 'frontend/src/model-registry.ts' }),
    }));
  });

  it('auto-links a verified path with spaces in prose', async () => {
    const fetchMock = vi.fn(async () => ({
      ok: true,
      status: 200,
      json: async () => ({
        ok: true,
        results: [{
          reference: 'results/final report.html',
          resolved: {
            kind: 'workspace',
            projectId: 'proj-1',
            relativePath: 'results/final report.html',
            name: 'final report.html',
          },
        }],
      }) satisfies ResolveResponse,
    } as Response));
    vi.stubGlobal('fetch', fetchMock);
    const onFileReferenceClick = vi.fn();

    render(
      <CopilotMarkdown
        text={'打开 "results/final report.html" 查看报告。'}
        resolveContext={{ projectId: 'proj-1' }}
        onFileReferenceClick={onFileReferenceClick}
      />,
    );

    const link = await screen.findByRole('link', { name: 'results/final report.html' });
    fireEvent.click(link);
    expect(onFileReferenceClick).toHaveBeenCalledWith(expect.objectContaining({
      raw: 'results/final report.html',
      resolved: expect.objectContaining({ relativePath: 'results/final report.html' }),
    }));
  });

  it('auto-links a verified binary data file inside a table cell', async () => {
    const fetchMock = vi.fn(async () => ({
      ok: true,
      status: 200,
      json: async () => ({
        ok: true,
        results: [{
          reference: 'Fig5_intermediate.RData',
          resolved: {
            kind: 'workspace',
            projectId: 'proj-1',
            relativePath: 'data/Fig5_intermediate.RData',
            name: 'Fig5_intermediate.RData',
          },
        }],
      }) satisfies ResolveResponse,
    } as Response));
    vi.stubGlobal('fetch', fetchMock);

    render(
      <CopilotMarkdown
        text={'| 文件 | 类型 |\n| --- | --- |\n| Fig5_intermediate.RData | R 工作区数据 |'}
        resolveContext={{ projectId: 'proj-1' }}
      />,
    );

    expect(await screen.findByRole('link', { name: 'Fig5_intermediate.RData' })).toBeTruthy();
    expect(fetchMock).toHaveBeenCalledTimes(1);
  });

  it('leaves unresolved inline code inert', async () => {
    const fetchMock = vi.fn(async () => ({
      ok: true,
      status: 200,
      json: async () => ({ ok: true, results: [] }) satisfies ResolveResponse,
    } as Response));
    vi.stubGlobal('fetch', fetchMock);

    render(
      <CopilotMarkdown
        text={'运行 `read.csv("missing.csv")`，结果是 `missing.csv`'}
        resolveContext={{ projectId: 'proj-1', activeJobId: 'job-1' }}
      />,
    );

    await waitFor(() => expect(fetchMock).toHaveBeenCalledTimes(1));
    expect(screen.queryByRole('link', { name: 'missing.csv' })).toBeNull();
    expect(screen.getAllByText(/missing\.csv/)).toHaveLength(2);
  });

  it('reruns the resolver when resolveNonce changes', async () => {
    __resetFileReferenceCache();
    const fetchMock = vi.fn(async () => ({
      ok: true,
      status: 200,
      json: async () => ({
        ok: true,
        results: [{
          reference: 'report.html',
          resolved: {
            kind: 'artifact',
            jobId: 'job-1',
            artifactName: 'report.html',
            projectId: 'proj-1',
          },
        }],
      }) satisfies ResolveResponse,
    } as Response));
    vi.stubGlobal('fetch', fetchMock);

    const { rerender } = render(
      <CopilotMarkdown
        text={'查看 `report.html`'}
        resolveContext={{ projectId: 'proj-1', activeJobId: 'job-1' }}
        resolveNonce={0}
      />,
    );
    await waitFor(() => expect(fetchMock).toHaveBeenCalledTimes(1));

    __resetFileReferenceCache();
    rerender(
      <CopilotMarkdown
        text={'查看 `report.html`'}
        resolveContext={{ projectId: 'proj-1', activeJobId: 'job-1' }}
        resolveNonce={1}
      />,
    );
    await waitFor(() => expect(fetchMock).toHaveBeenCalledTimes(2));
    expect(screen.getByRole('link', { name: 'report.html' })).toBeTruthy();
  });

  it('delegates fenced code highlighting to the host renderer', () => {
    const highlightCode = vi.fn((code: string, language?: string) => (
      <code data-language={language}>{code}</code>
    ));
    render(
      <CopilotMarkdown
        text={'```python\nprint("hello")\n```'}
        highlightCode={highlightCode}
      />,
    );

    expect(highlightCode).toHaveBeenCalledWith('print("hello")', 'python');
    expect(screen.getByText('print("hello")').getAttribute('data-language')).toBe('python');
    expect(screen.getByRole('button', { name: '复制代码' })).toBeTruthy();
    expect(screen.getByText('python').closest('.cp-code-head')).not.toBeNull();
  });

  it('renders text and tree fences without a language header', () => {
    const { container } = render(
      <CopilotMarkdown text={'```text\nsrc/\n  index.ts\n```'} />,
    );

    expect(screen.queryByText('text')).toBeNull();
    expect(container.querySelector('.cp-code-head')).toBeNull();
    expect(container.querySelector('.cp-code-block-plain')).not.toBeNull();
    expect(container.querySelector('.cp-code-plain-action button')).not.toBeNull();
  });

  it('renders status marks neutrally and provides table copy', async () => {
    const writeText = vi.fn().mockResolvedValue(undefined);
    vi.stubGlobal('navigator', { clipboard: { writeText } });
    render(
      <CopilotMarkdown
        text={'## 结果\n\n| 文件 | 状态 |\n| --- | --- |\n| Fig1 | ✅ 完成 |\n| Fig8 | ❌ 未完成 |'}
      />,
    );

    expect(screen.getByLabelText('✅').textContent).toBe('✓');
    expect(screen.getByLabelText('❌').textContent).toBe('×');
    const copyButton = screen.getByRole('button', { name: '复制' });
    expect(screen.queryByText('表格')).toBeNull();
    expect(copyButton.closest('.cp-table-figure')).not.toBeNull();
    expect(copyButton.closest('table')).toBeNull();
    expect(copyButton.closest('.cp-table-tools')).not.toBeNull();
    fireEvent.click(copyButton);
    await waitFor(() => expect(writeText).toHaveBeenCalledWith('文件\t状态\nFig1\t✅ 完成\nFig8\t❌ 未完成'));
    expect(screen.getByRole('button', { name: '已复制' })).toBeTruthy();
  });
});

