/**
 * BLOCK-22 P3 桥接层 (UI-194) — ChatCardLinkBridge smoke test
 *
 * 验证范围：
 * - mount 不抛错
 * - 点击触发 usePendingScroll().setPendingRequest 调用，载荷含 filePath / line / column / timestamp
 * - 点击触发带 diffRevision 的请求时，载荷含 diffRevision
 * - variant=floating 渲染对应 CSS class
 * - variant=inline 渲染对应 CSS class
 * - 默认 aria-label 由 filePath + line 拼接
 *
 * 设计要点：
 * - 使用 PendingScrollProvider 在测试中显式挂载，避免依赖 WorkspaceFilePreviewBridge
 * - 通过 usePendingScroll().setPendingRequest spy 验证 click 副作用
 */

import React from 'react';
import { cleanup, render, fireEvent, act } from '@testing-library/react';
import { afterEach, describe, expect, it, vi } from 'vitest';

import { ChatCardLinkBridge } from '../ChatCardLinkBridge';
import {
  PendingScrollProvider,
  usePendingScroll,
} from '../../../../lib/pendingScrollContext';

afterEach(() => {
  cleanup();
  vi.restoreAllMocks();
});

interface Capture {
  setPendingRequest: ReturnType<typeof usePendingScroll>['setPendingRequest'] | null;
  pendingRequest: ReturnType<typeof usePendingScroll>['pendingRequest'] | null;
}

function CaptureConsumer({ capture }: { capture: Capture }): React.ReactElement {
  const ctx = usePendingScroll();
  capture.setPendingRequest = ctx.setPendingRequest;
  capture.pendingRequest = ctx.pendingRequest;
  return <span data-testid="capture-consumer" />;
}

describe('ChatCardLinkBridge (P3 smoke)', () => {
  it('mounts without throwing', () => {
    const capture: Capture = { setPendingRequest: null, pendingRequest: null };
    const { container } = render(
      <PendingScrollProvider>
        <CaptureConsumer capture={capture} />
        <ChatCardLinkBridge filePath="/workspace/foo.py" line={1}>
          Open
        </ChatCardLinkBridge>
      </PendingScrollProvider>,
    );
    expect(container.querySelector('[data-bf3-chat-card-link]')).toBeTruthy();
  });

  it('click invokes setPendingRequest with correct payload (filePath / line / column / pulseMs)', () => {
    const capture: Capture = { setPendingRequest: null, pendingRequest: null };
    const { container } = render(
      <PendingScrollProvider>
        <CaptureConsumer capture={capture} />
        <ChatCardLinkBridge
          filePath="/workspace/click.py"
          line={12}
          column={4}
          pulseMs={2000}
        >
          click me
        </ChatCardLinkBridge>
      </PendingScrollProvider>,
    );

    const btn = container.querySelector(
      '[data-bf3-chat-card-link]',
    ) as HTMLButtonElement;
    expect(btn).toBeTruthy();

    const before = Date.now();
    fireEvent.click(btn);
    const after = Date.now();

    // capture.pendingRequest 应被设置
    const req = capture.pendingRequest;
    expect(req).not.toBeNull();
    expect(req?.filePath).toBe('/workspace/click.py');
    expect(req?.line).toBe(12);
    expect(req?.column).toBe(4);
    expect(req?.pulseMs).toBe(2000);
    expect(typeof req?.timestamp).toBe('number');
    expect(req!.timestamp).toBeGreaterThanOrEqual(before);
    expect(req!.timestamp).toBeLessThanOrEqual(after);
  });

  it('click payload includes diffRevision when prop provided', () => {
    const capture: Capture = { setPendingRequest: null, pendingRequest: null };
    const { container } = render(
      <PendingScrollProvider>
        <CaptureConsumer capture={capture} />
        <ChatCardLinkBridge
          filePath="/workspace/diff.py"
          line={3}
          diffRevision={{
            filePath: '/workspace/diff.py',
            originalText: 'a\n',
            modifiedText: 'b\n',
          }}
        >
          diff link
        </ChatCardLinkBridge>
      </PendingScrollProvider>,
    );

    const btn = container.querySelector(
      '[data-bf3-chat-card-link]',
    ) as HTMLButtonElement;
    fireEvent.click(btn);

    const req = capture.pendingRequest;
    expect(req).not.toBeNull();
    expect(req?.diffRevision).toBeDefined();
    expect(req?.diffRevision?.filePath).toBe('/workspace/diff.py');
    expect(req?.diffRevision?.originalText).toBe('a\n');
    expect(req?.diffRevision?.modifiedText).toBe('b\n');
  });

  it('variant="inline" renders data attribute and CSS class', () => {
    const capture: Capture = { setPendingRequest: null, pendingRequest: null };
    const { container } = render(
      <PendingScrollProvider>
        <CaptureConsumer capture={capture} />
        <ChatCardLinkBridge filePath="/x.py" line={1} variant="inline">
          inline
        </ChatCardLinkBridge>
      </PendingScrollProvider>,
    );
    const btn = container.querySelector(
      '[data-bf3-chat-card-link-variant="inline"]',
    );
    expect(btn).toBeTruthy();
  });

  it('variant="floating" renders data attribute and CSS class', () => {
    const capture: Capture = { setPendingRequest: null, pendingRequest: null };
    const { container } = render(
      <PendingScrollProvider>
        <CaptureConsumer capture={capture} />
        <ChatCardLinkBridge filePath="/x.py" line={1} variant="floating">
          floating
        </ChatCardLinkBridge>
      </PendingScrollProvider>,
    );
    const btn = container.querySelector(
      '[data-bf3-chat-card-link-variant="floating"]',
    );
    expect(btn).toBeTruthy();
  });

  it('aria-label defaults to "Open <path>:<line>"', () => {
    const capture: Capture = { setPendingRequest: null, pendingRequest: null };
    const { container } = render(
      <PendingScrollProvider>
        <CaptureConsumer capture={capture} />
        <ChatCardLinkBridge filePath="/workspace/lab.py" line={42}>
          label-test
        </ChatCardLinkBridge>
      </PendingScrollProvider>,
    );
    const btn = container.querySelector(
      '[data-bf3-chat-card-link]',
    ) as HTMLButtonElement;
    expect(btn.getAttribute('aria-label')).toBe('Open /workspace/lab.py:42');
  });

  it('custom ariaLabel wins when provided', () => {
    const capture: Capture = { setPendingRequest: null, pendingRequest: null };
    const { container } = render(
      <PendingScrollProvider>
        <CaptureConsumer capture={capture} />
        <ChatCardLinkBridge filePath="/workspace/lab.py" line={1} ariaLabel="自定义">
          custom-label
        </ChatCardLinkBridge>
      </PendingScrollProvider>,
    );
    const btn = container.querySelector(
      '[data-bf3-chat-card-link]',
    ) as HTMLButtonElement;
    expect(btn.getAttribute('aria-label')).toBe('自定义');
  });
});

/**
 * BLOCK-37 P3 — 模型 I/O 信息流客户端（UI-274）
 *
 * 只读查询 petri-server 的 llm-transcripts 路由（数据源为
 * io-transcript.js 落盘的 <PETRI_LOCAL_DATA_DIR>/llm-transcripts/<conversationId>.jsonl）：
 *   - listLlmTranscripts: 会话级调用索引（不含正文）
 *   - fetchLlmTranscriptRecord: 单条完整记录（请求 messages 全量 + 响应聚合 + delta 帧）
 */

import { getApiPrefix, getAuthHeader } from './copilotClient';

export interface LlmTranscriptIndexEntry {
  id: string;
  ts: string;
  conversationId: string | null;
  kind: string;
  role: string;
  traceId?: string;
  provider?: string;
  profileId?: string;
  model?: string;
  attemptIndex: number;
  durationMs?: number;
  finishReason?: string;
  usage?: { prompt_tokens?: number; completion_tokens?: number; total_tokens?: number };
  messagesCount: number;
  framesCount: number;
  framesTruncated: boolean;
  truncated: boolean;
  messagesTruncated: number;
  error: string | null;
  sizeBytes: number;
}

export interface LlmTranscriptMessage {
  role?: string;
  content?: unknown;
  tool_calls?: unknown;
  [key: string]: unknown;
}

export interface LlmTranscriptRecord {
  id: string;
  ts: string;
  conversationId: string | null;
  kind: string;
  role: string;
  traceId?: string;
  provider?: string;
  profileId?: string;
  attemptIndex: number;
  model?: string;
  durationMs?: number;
  request: { messages: LlmTranscriptMessage[]; params?: string };
  response: {
    content?: string;
    reasoningContent?: string;
    toolCalls?: unknown[];
    finishReason?: string;
    usage?: { prompt_tokens?: number; completion_tokens?: number; total_tokens?: number };
  } | null;
  error: string | null;
  frames?: unknown[];
  framesCount: number;
  framesTruncated: boolean;
  truncated: boolean;
  messagesTruncated: number;
}

async function requestJson<T>(url: string): Promise<T> {
  const resp = await fetch(url, { headers: { ...getAuthHeader() } });
  let body: (T & { status?: string; error?: string }) | null = null;
  try {
    body = await resp.json();
  } catch {
    // 非 JSON 响应按 HTTP 状态处理
  }
  if (!resp.ok || !body) {
    throw new Error(body?.error || `HTTP ${resp.status}`);
  }
  return body;
}

/** 列出会话全部模型调用索引（后端按 ts 升序返回；查看器内自行倒序展示）。 */
export async function listLlmTranscripts(conversationId: string): Promise<LlmTranscriptIndexEntry[]> {
  const params = new URLSearchParams({ conversationId });
  const body = await requestJson<{ count: number; records: LlmTranscriptIndexEntry[] }>(
    `${getApiPrefix()}/ai/agent/llm-transcripts?${params.toString()}`
  );
  return Array.isArray(body.records) ? body.records : [];
}

/** 读取单条完整记录。未命中时后端返回 404，此处抛错。 */
export async function fetchLlmTranscriptRecord(
  conversationId: string,
  id: string
): Promise<LlmTranscriptRecord> {
  const params = new URLSearchParams({ conversationId, id });
  const body = await requestJson<{ record: LlmTranscriptRecord }>(
    `${getApiPrefix()}/ai/agent/llm-transcripts/record?${params.toString()}`
  );
  return body.record;
}

// BLOCK-55 — 计划模式批准链路的 REST 封装（ai-plans 路由）。
// 复用 llmTranscripts.ts 的 requestJson 形状：getApiPrefix + getAuthHeader。
import { getApiPrefix, getAuthHeader } from './copilotClient';
import type { PlanApprovalAction, PlanApprovalCardPlan } from './SimpleChat/PlanApprovalCard';

export interface PlanListEntry extends PlanApprovalCardPlan {
  status: string;
  conversation_id?: string | null;
  pending_revision_no?: number | null;
  total_steps?: number;
  done_steps?: number;
}

async function requestJson<T>(url: string, init?: RequestInit): Promise<T> {
  const resp = await fetch(url, {
    ...init,
    headers: { ...getAuthHeader(), ...(init?.body ? { 'Content-Type': 'application/json' } : {}) },
  });
  let body: (T & { status?: string; error?: string }) | null = null;
  try {
    body = await resp.json();
  } catch {
    // 非 JSON 响应按 HTTP 状态处理
  }
  if (!resp.ok || !body) {
    throw new Error(body?.error || `HTTP ${resp.status}`);
  }
  return body;
}

/** 后端行（snake_case）→ 批准卡形状（PlanApprovalCardPlan，camelCase）。 */
type PlanRowPayload = PlanListEntry & { spec_md?: string | null; steps?: PlanApprovalCardPlan['steps'] };
function mapPlanRow(row: PlanRowPayload): PlanListEntry {
  return {
    ...row,
    specMd: row.specMd ?? row.spec_md ?? null,
    steps: Array.isArray(row.steps) ? row.steps : [],
  };
}

/** 拉取当前会话的 draft 计划（批准卡数据源）。 */
export async function fetchDraftPlansForConversation(conversationId: string): Promise<PlanListEntry[]> {
  const params = new URLSearchParams({ conversationId, status: 'draft' });
  const body = await requestJson<{ plans: PlanListEntry[] }>(
    `${getApiPrefix()}/ai/plans?${params.toString()}`
  );
  return (Array.isArray(body.plans) ? body.plans : []).map(mapPlanRow);
}

/** 拉取当前会话有待批准修订案的 active 计划（P3 replan 批准条数据源）。 */
export async function fetchPlansWithPendingRevision(conversationId: string): Promise<PlanListEntry[]> {
  const params = new URLSearchParams({ conversationId, status: 'active' });
  const body = await requestJson<{ plans: PlanListEntry[] }>(
    `${getApiPrefix()}/ai/plans?${params.toString()}`
  );
  const plans = Array.isArray(body.plans) ? body.plans : [];
  return plans.map(mapPlanRow).filter((p) => typeof p.pending_revision_no === 'number');
}

/** 批准三选一。 */
export async function approvePlan(
  planId: string,
  action: PlanApprovalAction
): Promise<{ ok: boolean }> {
  await requestJson<{ status: string }>(`${getApiPrefix()}/ai/plans/${encodeURIComponent(planId)}/approve`, {
    method: 'POST',
    body: JSON.stringify({ action }),
  });
  return { ok: true };
}

/** 批准修订案（P3：applied → 步骤表替换）。 */
export async function approvePlanRevision(planId: string, revNo: number): Promise<{ ok: boolean }> {
  await requestJson<{ status: string }>(
    `${getApiPrefix()}/ai/plans/${encodeURIComponent(planId)}/revisions/${revNo}/approve`,
    { method: 'POST' }
  );
  return { ok: true };
}

/** 「批准并清上下文执行」的首 turn 文案：仅凭 spec + 步骤表自包含。 */
export function buildFreshPlanTurn(plan: PlanApprovalCardPlan): string {
  const stepsText = (plan.steps || [])
    .map((s) => {
      const assignee = s.assignee === 'subagent' ? '（派子智能体执行）' : '';
      const hint = s.hint ? ` — ${s.hint}` : '';
      return `${s.n}. ${s.title}${assignee}${hint}`;
    })
    .join('\n');
  return [
    `计划「${plan.title}」已批准（planId: ${plan.id}）。以下是完整计划，请仅依据它执行，不要依赖之前的对话内容。`,
    plan.specMd ? `\n## 计划正文\n\n${plan.specMd}` : '',
    stepsText ? `\n## 步骤\n\n${stepsText}` : '',
    '\n请从第一个 pending 步骤开始执行；完成后用 plan(op="update_step") 写回状态。',
  ]
    .filter(Boolean)
    .join('\n');
}

import { cleanup, fireEvent, render, screen } from '@testing-library/react';
import { afterEach, describe, expect, it } from 'vitest';
import type { ResultNode } from '../types';
import { ChartRenderer } from './ChartRenderer';

function makeBarNode(): ResultNode {
  return {
    id: 'chart-p2-bar',
    type: 'chart',
    title: 'Expression per gene',
    subtitle: 'RNA-seq · counts',
    meta: '4 genes · 2 series',
    payload: {
      kind: 'bar',
      labels: ['TP53', 'BRCA1', 'MYC', 'EGFR'],
      series: [
        { name: 'control', values: [10, 20, 30, 40] },
        { name: 'treated', values: [12, 18, 35, 45] },
      ],
    },
    createdAt: '2026-08-15T10:00:00Z',
  };
}

function makeLineNode(): ResultNode {
  return {
    id: 'chart-p2-line',
    type: 'chart',
    title: 'Timecourse',
    subtitle: 'qPCR',
    meta: '4 timepoints · 2 series',
    payload: {
      kind: 'line',
      xLabels: ['0h', '6h', '12h', '24h'],
      series: [
        { name: 'control', values: [10, 12, 14, 16] },
        { name: 'treated', values: [8, 10, 12, 14] },
      ],
    },
    createdAt: '2026-08-15T10:00:00Z',
  };
}

afterEach(() => {
  cleanup();
});

describe('ChartRenderer — P2 interaction + a11y layer', () => {
  it('renders a <desc> element on the SVG root containing the series summary', () => {
    render(<ChartRenderer node={makeBarNode()} />);

    const desc = screen.getByTestId('result-renderer-chart-desc');
    expect(desc).toBeTruthy();
    // The <desc> text content is the human-readable summary
    // that screen readers announce instead of "Chart: bar".
    const text = desc.textContent ?? '';
    expect(text).toContain('Bar chart with 2 series');
    expect(text).toContain('control');
    expect(text).toContain('treated');
    expect(text).toContain('10, 20, 30, 40');
    expect(text).toContain('12, 18, 35, 45');
    expect(text).toContain("'TP53'");
    expect(text).toContain("'EGFR'");
  });

  it('renders a <desc> summary for a line chart with xLabels', () => {
    render(<ChartRenderer node={makeLineNode()} />);

    const desc = screen.getByTestId('result-renderer-chart-desc');
    const text = desc.textContent ?? '';
    expect(text).toContain('Line chart with 2 series');
    expect(text).toContain("'0h'");
    expect(text).toContain("'24h'");
    expect(text).toContain('10, 12, 14, 16');
  });

  it('attaches aria-label and tabIndex=0 to every bar data point', () => {
    render(<ChartRenderer node={makeBarNode()} />);

    // 2 series × 4 labels = 8 bars. Each must carry an
    // aria-label "{series} at {label}: {value}" so screen
    // readers can announce it, plus tabIndex=0 so keyboard
    // users can reach the point.
    for (let seriesIdx = 0; seriesIdx < 2; seriesIdx++) {
      const seriesName = seriesIdx === 0 ? 'control' : 'treated';
      const values = seriesIdx === 0
        ? [10, 20, 30, 40]
        : [12, 18, 35, 45];
      for (let slotIdx = 0; slotIdx < 4; slotIdx++) {
        const point = screen.getByTestId(
          `result-renderer-chart-bar-${seriesIdx}-${slotIdx}`,
        );
        expect(point.getAttribute('aria-label')).toBe(
          `${seriesName} at TP53, BRCA1, MYC, EGFR`.split(', ')[slotIdx] ===
            undefined
            ? ''
            : `${seriesName} at ${
                ['TP53', 'BRCA1', 'MYC', 'EGFR'][slotIdx]
              }: ${values[slotIdx]}`,
        );
        expect(point.getAttribute('tabindex')).toBe('0');
        // Default aria-selected=false before any click.
        expect(point.getAttribute('aria-selected')).toBe('false');
      }
    }
  });

  it('attaches aria-label and tabIndex=0 to every line-chart dot', () => {
    render(<ChartRenderer node={makeLineNode()} />);

    const labels = ['0h', '6h', '12h', '24h'];
    const values = [10, 12, 14, 16];
    for (let idx = 0; idx < labels.length; idx++) {
      const dot = screen.getByTestId(
        `result-renderer-chart-dot-0-${idx}`,
      );
      expect(dot.getAttribute('aria-label')).toBe(
        `control at ${labels[idx]}: ${values[idx]}`,
      );
      expect(dot.getAttribute('tabindex')).toBe('0');
    }
  });

  it('shows the tooltip on bar hover (series + x label + value)', () => {
    render(<ChartRenderer node={makeBarNode()} />);

    // Hovering a bar should surface the tooltip with the
    // expected series/x/value triple. The tooltip is a real
    // DOM <div> outside the <svg> with role="status".
    const bar = screen.getByTestId('result-renderer-chart-bar-0-1');
    fireEvent.mouseEnter(bar);

    const tooltip = screen.getByTestId('result-renderer-chart-tooltip');
    expect(tooltip).toBeTruthy();
    expect(tooltip.getAttribute('data-series-name')).toBe('control');
    expect(tooltip.getAttribute('data-x-label')).toBe('BRCA1');
    expect(tooltip.getAttribute('data-value')).toBe('20');
    // role=status + aria-live=polite so screen readers
    // announce the new value without stealing focus.
    expect(tooltip.getAttribute('role')).toBe('status');
  });

  it('shows the tooltip on line-chart hover', () => {
    render(<ChartRenderer node={makeLineNode()} />);

    const dot = screen.getByTestId('result-renderer-chart-dot-1-2');
    fireEvent.mouseEnter(dot);

    const tooltip = screen.getByTestId('result-renderer-chart-tooltip');
    expect(tooltip.getAttribute('data-series-name')).toBe('treated');
    expect(tooltip.getAttribute('data-x-label')).toBe('12h');
    expect(tooltip.getAttribute('data-value')).toBe('12');
  });

  it('hides the tooltip when the hovered bar loses pointer', () => {
    render(<ChartRenderer node={makeBarNode()} />);

    const bar = screen.getByTestId('result-renderer-chart-bar-0-0');
    fireEvent.mouseEnter(bar);
    expect(
      screen.queryByTestId('result-renderer-chart-tooltip'),
    ).not.toBeNull();

    fireEvent.mouseLeave(bar);
    expect(
      screen.queryByTestId('result-renderer-chart-tooltip'),
    ).toBeNull();
  });

  it('treats keyboard focus as equivalent to hover for the tooltip', () => {
    render(<ChartRenderer node={makeBarNode()} />);

    const bar = screen.getByTestId('result-renderer-chart-bar-1-3');
    // Focus the bar via tab/focus — no mouse involved.
    fireEvent.focus(bar);
    const tooltip = screen.getByTestId('result-renderer-chart-tooltip');
    expect(tooltip.getAttribute('data-series-name')).toBe('treated');
    expect(tooltip.getAttribute('data-x-label')).toBe('EGFR');
    expect(tooltip.getAttribute('data-value')).toBe('45');

    fireEvent.blur(bar);
    expect(
      screen.queryByTestId('result-renderer-chart-tooltip'),
    ).toBeNull();
  });

  it('clicking a legend button hides that series and flips aria-pressed', () => {
    render(<ChartRenderer node={makeBarNode()} />);

    const legend0 = screen.getByTestId('result-renderer-chart-legend-0');
    // Initially every series is visible and aria-pressed=false.
    expect(legend0.getAttribute('aria-pressed')).toBe('false');
    expect(
      screen.queryByTestId('result-renderer-chart-bar-0-0'),
    ).not.toBeNull();

    // Toggle the "control" series off.
    fireEvent.click(legend0);

    // aria-pressed flipped + every bar in series 0 must be gone
    // from the DOM. Series 1 must still be rendered.
    expect(legend0.getAttribute('aria-pressed')).toBe('true');
    expect(
      screen.queryByTestId('result-renderer-chart-bar-0-0'),
    ).toBeNull();
    expect(
      screen.queryByTestId('result-renderer-chart-bar-0-3'),
    ).toBeNull();
    expect(
      screen.queryByTestId('result-renderer-chart-bar-1-0'),
    ).not.toBeNull();

    // Click again — series comes back, aria-pressed restored.
    fireEvent.click(legend0);
    expect(legend0.getAttribute('aria-pressed')).toBe('false');
    expect(
      screen.queryByTestId('result-renderer-chart-bar-0-0'),
    ).not.toBeNull();
  });

  it('treats keyboard Enter / Space on the legend as equivalent to click', () => {
    render(<ChartRenderer node={makeBarNode()} />);

    const legend1 = screen.getByTestId('result-renderer-chart-legend-1');
    // Enter on the legend must toggle the "treated" series.
    fireEvent.keyDown(legend1, { key: 'Enter' });
    expect(legend1.getAttribute('aria-pressed')).toBe('true');
    expect(
      screen.queryByTestId('result-renderer-chart-bar-1-0'),
    ).toBeNull();

    fireEvent.keyDown(legend1, { key: ' ' });
    expect(legend1.getAttribute('aria-pressed')).toBe('false');
    expect(
      screen.queryByTestId('result-renderer-chart-bar-1-0'),
    ).not.toBeNull();
  });

  it('clicking a bar selects it (aria-selected=true + selected stroke class)', () => {
    render(<ChartRenderer node={makeBarNode()} />);

    const bar = screen.getByTestId('result-renderer-chart-bar-0-2');
    // Initial selection state.
    expect(bar.getAttribute('aria-selected')).toBe('false');

    fireEvent.click(bar);
    // The DOM node now reflects aria-selected=true.
    expect(bar.getAttribute('aria-selected')).toBe('true');

    // The selected stroke emphasis is applied as a CSS Module
    // class. The className token is hashed by Vite so we cannot
    // compare exact strings — but the class attribute must grow
    // (selected class is appended) AND must include a token
    // distinct from the baseline `.bar` class.
    const cls = bar.getAttribute('class') ?? '';
    const tokens = cls.split(/\s+/).filter(Boolean);
    expect(tokens.length).toBeGreaterThanOrEqual(2);
    expect(tokens.some((t) => t !== tokens[0])).toBe(true);
  });

  it('clicking the same bar a second time clears the selection', () => {
    render(<ChartRenderer node={makeBarNode()} />);

    const bar = screen.getByTestId('result-renderer-chart-bar-0-0');
    fireEvent.click(bar);
    expect(bar.getAttribute('aria-selected')).toBe('true');

    fireEvent.click(bar);
    expect(bar.getAttribute('aria-selected')).toBe('false');
  });

  it('hovering another point does not override the selected stroke', () => {
    render(<ChartRenderer node={makeBarNode()} />);

    const selected = screen.getByTestId('result-renderer-chart-bar-0-1');
    fireEvent.click(selected);
    expect(selected.getAttribute('aria-selected')).toBe('true');

    // Hover a different bar — the selected bar must still be
    // aria-selected=true (hover never overrides the selection
    // attribute, the selection class never flips back).
    const other = screen.getByTestId('result-renderer-chart-bar-1-2');
    fireEvent.mouseEnter(other);

    expect(selected.getAttribute('aria-selected')).toBe('true');
    expect(other.getAttribute('aria-selected')).toBe('false');
    // The tooltip just swaps to the new point.
    const tooltip = screen.getByTestId('result-renderer-chart-tooltip');
    expect(tooltip.getAttribute('data-series-name')).toBe('treated');
    expect(tooltip.getAttribute('data-x-label')).toBe('MYC');
  });

  it('keyboard Enter / Space on a data point toggles its selection', () => {
    render(<ChartRenderer node={makeBarNode()} />);

    const bar = screen.getByTestId('result-renderer-chart-bar-0-3');
    fireEvent.keyDown(bar, { key: 'Enter' });
    expect(bar.getAttribute('aria-selected')).toBe('true');

    fireEvent.keyDown(bar, { key: ' ' });
    expect(bar.getAttribute('aria-selected')).toBe('false');
  });

  it('does not attach interaction handlers to the fail-soft fallback path', () => {
    // Every P1.3 malformed payload must still render the JSON
    // fallback with NO <svg>, NO interactive <button>, NO
    // <desc>, NO tooltip — proving the interaction layer is
    // strictly scoped to the validated chart payload.
    const malformedPayloads: Array<{ name: string; payload: unknown }> = [
      { name: 'unknown-kind', payload: { kind: 'pie', labels: ['a'], series: [] } },
      { name: 'missing-series', payload: { kind: 'bar', labels: ['a', 'b'] } },
      { name: 'empty-labels', payload: { kind: 'bar', labels: [], series: [{ name: 's', values: [] }] } },
      { name: 'non-numeric-values', payload: { kind: 'line', xLabels: ['a'], series: [{ name: 's', values: ['x'] }] } },
      { name: 'not-an-object', payload: 'this is not a chart' },
    ];

    for (const { name, payload } of malformedPayloads) {
      const node: ResultNode = {
        id: `bad-${name}`,
        type: 'chart',
        title: `Bad (${name})`,
        payload,
        createdAt: '2026-08-15T10:00:00Z',
      };
      const { container } = render(<ChartRenderer node={node} />);

      const fallback = screen.getByTestId(
        'result-renderer-chart-fallback',
      );
      expect(fallback).toBeTruthy();
      // No interaction layer leaks into the fallback DOM.
      expect(container.querySelector('svg')).toBeNull();
      expect(container.querySelector('button')).toBeNull();
      expect(container.querySelector('[data-testid="result-renderer-chart-tooltip"]')).toBeNull();
      expect(container.querySelector('[data-testid="result-renderer-chart-desc"]')).toBeNull();
      expect(container.querySelector('[data-testid="result-renderer-chart-legend"]')).toBeNull();

      cleanup();
    }
  });
});

// ============================================================
// ChartRenderer — `chart` ResultNode renderer.
//
// Payload contract (strict; type-guard below):
//   { kind: 'bar';
//     labels: string[];
//     series: Array<{ name: string; values: number[] }> }
//   | { kind: 'line';
//       xLabels: string[];
//       series: Array<{ name: string; values: number[] }> }
//
// Behaviour:
//   - When payload matches the contract, render a native <svg>
//     viewBox="0 0 600 320" bar chart or line chart with a
//     single-color legend + per-series names. All values use
//     --petri-* design tokens so light/dark themes stay aligned
//     with ResultCard.module.css.
//   - When payload is malformed (unknown kind, missing series,
//     empty labels, non-numeric value, etc.), fail-soft to a
//     labelled JSON dump so a bad upstream payload never crashes
//     the card chrome (mirrors TableRenderer's graceful fallback
//     but stays inside ChartRenderer's own scope).
//   - Bar: equal-width columns with top value labels; Line:
//     polyline + node dots. Auto-scale to data min/max so the
//     placeholder chart stays readable across small payloads.
//
// P2 interaction + a11y layer (2026-08-15, UI-AGENTWB-005):
//   - Hover/focus on a data point shows a <div> tooltip with
//     series name + x label + numeric value. Default absolute
//     values (no percentage switch in P2 — that toggle was
//     explicitly out of scope).
//   - Legend entries are <button>s; clicking toggles the
//     series' UI visibility (UI-only, no data deletion).
//     Toggle state is component-local (useState): a fresh
//     chart always starts with all series visible.
//   - Clicking a data point selects it (stroke emphasis);
//     clicking the same point again clears the selection.
//     Hover never overrides the selected stroke — once a point
//     is selected, hovering other points only swaps the
//     tooltip text but never replaces the stroke emphasis.
//   - <svg> carries a <desc> element with the full series
//     summary so SR users can hear "Bar chart with 2 series:
//     control (10, 12, 14, 16), treated (8, 10, 12, 14)
//     across labels ..." instead of just "Chart: bar".
//   - Every data point (<rect>/<circle>) carries an aria-label
//     ("{series} at {x}: {value}") + tabIndex={0} + aria-selected.
//   - Legend <button>s carry aria-pressed for the toggle state.
//   - Fail-soft fallback path is unchanged: 5 kinds of malformed
//     payloads still render <pre data-testid="result-renderer-
//     chart-fallback"> with no interaction layer.
//
// This renderer is intentionally a pure presentational component
// that owns its own ephemeral interaction state via useState (no
// reducer, no zustand, no new dependency).
// ============================================================

import { useCallback, useMemo, useState } from 'react';
import type { ReactNode } from 'react';
import type { ResultNode } from '../types';
import styles from './ChartRenderer.module.css';

type Series = { name: string; values: number[] };

type BarPayload = { kind: 'bar'; labels: string[]; series: Series[] };
type LinePayload = { kind: 'line'; xLabels: string[]; series: Series[] };
type ChartPayload = BarPayload | LinePayload;

const VIEWBOX_W = 600;
const VIEWBOX_H = 320;
const PADDING = { top: 28, right: 16, bottom: 48, left: 44 };

function isStringArray(value: unknown): value is string[] {
  return Array.isArray(value) && value.every((v) => typeof v === 'string');
}

function isFiniteNumberArray(value: unknown): value is number[] {
  return (
    Array.isArray(value) &&
    value.every((v) => typeof v === 'number' && Number.isFinite(v))
  );
}

function isSeries(value: unknown): value is Series {
  if (value === null || typeof value !== 'object') return false;
  const candidate = value as { name?: unknown; values?: unknown };
  if (typeof candidate.name !== 'string') return false;
  if (!isFiniteNumberArray(candidate.values)) return false;
  return true;
}

function isSeriesArray(value: unknown): value is Series[] {
  return Array.isArray(value) && value.every(isSeries);
}

function isBarPayload(value: unknown): value is BarPayload {
  if (value === null || typeof value !== 'object') return false;
  const candidate = value as { kind?: unknown; labels?: unknown; series?: unknown };
  if (candidate.kind !== 'bar') return false;
  if (!isStringArray(candidate.labels)) return false;
  if (!isSeriesArray(candidate.series)) return false;
  // Reject when the bar chart is structurally empty (no labels
  // or no series). Avoids an empty SVG with just axis lines.
  if (candidate.labels.length === 0) return false;
  if (candidate.series.length === 0) return false;
  return true;
}

function isLinePayload(value: unknown): value is LinePayload {
  if (value === null || typeof value !== 'object') return false;
  const candidate = value as { kind?: unknown; xLabels?: unknown; series?: unknown };
  if (candidate.kind !== 'line') return false;
  if (!isStringArray(candidate.xLabels)) return false;
  if (!isSeriesArray(candidate.series)) return false;
  if (candidate.xLabels.length === 0) return false;
  if (candidate.series.length === 0) return false;
  return true;
}

function isChartPayload(value: unknown): value is ChartPayload {
  return isBarPayload(value) || isLinePayload(value);
}

function tryStringify(payload: unknown): string {
  try {
    return JSON.stringify(payload, null, 2);
  } catch {
    return String(payload);
  }
}

function range(values: number[]): [number, number] {
  let min = values[0] ?? 0;
  let max = values[0] ?? 1;
  for (const v of values) {
    if (v < min) min = v;
    if (v > max) max = v;
  }
  if (min === max) {
    // Avoid divide-by-zero when all values are identical; pad
    // symmetrically so the column/line sits visibly off the axis.
    return [min - 1, max + 1];
  }
  return [min, max];
}

function plotBox() {
  return {
    x0: PADDING.left,
    y0: PADDING.top,
    x1: VIEWBOX_W - PADDING.right,
    y1: VIEWBOX_H - PADDING.bottom,
  };
}

function yScale(value: number, min: number, max: number): number {
  const { y0, y1 } = plotBox();
  const span = max - min || 1;
  const ratio = (value - min) / span;
  return y1 - ratio * (y1 - y0);
}

function joinWithAnd(items: string[]): string {
  if (items.length === 0) return '';
  if (items.length === 1) return items[0] ?? '';
  if (items.length === 2) return `${items[0]} and ${items[1]}`;
  return `${items.slice(0, -1).join(', ')}, and ${items[items.length - 1]}`;
}

function buildChartSummary(payload: ChartPayload): string {
  // Build a single human-readable sentence that lists every
  // series with its numeric values + the chart's x axis labels.
  // Goes inside <desc> so screen readers announce the full
  // content instead of just "Chart: bar".
  const labels = payload.kind === 'bar' ? payload.labels : payload.xLabels;
  const labelClause = joinWithAnd(labels.map((l) => `'${l}'`));
  const seriesClause = payload.series
    .map(
      (s) =>
        `${s.name} (${s.values.map((v) => String(v)).join(', ')})`,
    )
    .join('; ');
  return `${payload.kind === 'bar' ? 'Bar' : 'Line'} chart with ${
    payload.series.length
  } series: ${seriesClause} across labels ${labelClause}`;
}

type SelectedPoint = { seriesIdx: number; pointIdx: number } | null;

export function ChartRenderer({ node }: { node: ResultNode }) {
  const payload = node.payload;

  if (!isChartPayload(payload)) {
    return (
      <div
        data-testid="result-renderer-chart-fallback"
        data-result-id={node.id}
        role="region"
        aria-label={`${node.title}（图表数据无效，已降级为 JSON）`}
      >
        <p className={styles.fallbackNote}>
          图表数据格式无法解析，已降级为原始 JSON（fail-soft）：
        </p>
        <pre className={styles.fallback}>{tryStringify(payload)}</pre>
      </div>
    );
  }

  return <ChartRendererValid node={node} payload={payload} />;
}

function ChartRendererValid({
  node,
  payload,
}: {
  node: ResultNode;
  payload: ChartPayload;
}) {
  const kind = payload.kind;
  const title = `${node.title} (${kind})`;

  // All interaction state is local to the renderer so a fresh
  // chart always starts with all series visible and no selection.
  const [hiddenSeries, setHiddenSeries] = useState<Set<number>>(
    () => new Set<number>(),
  );
  const [selectedPoint, setSelectedPoint] = useState<SelectedPoint>(null);
  const [hoverPoint, setHoverPoint] = useState<SelectedPoint>(null);

  const toggleSeries = useCallback((seriesIdx: number) => {
    setHiddenSeries((prev) => {
      const next = new Set(prev);
      if (next.has(seriesIdx)) {
        next.delete(seriesIdx);
      } else {
        next.add(seriesIdx);
      }
      return next;
    });
  }, []);

  const handlePointClick = useCallback(
    (seriesIdx: number, pointIdx: number) => {
      setSelectedPoint((prev) => {
        if (
          prev !== null &&
          prev.seriesIdx === seriesIdx &&
          prev.pointIdx === pointIdx
        ) {
          return null;
        }
        return { seriesIdx, pointIdx };
      });
    },
    [],
  );

  const handlePointEnter = useCallback(
    (seriesIdx: number, pointIdx: number) => {
      setHoverPoint({ seriesIdx, pointIdx });
    },
    [],
  );

  const handlePointLeave = useCallback(() => {
    setHoverPoint(null);
  }, []);

  // Tooltip data is derived from hoverPoint so the tooltip
  // simply disappears when nothing is hovered/focused.
  const tooltipData = useMemo(() => {
    if (hoverPoint === null) return null;
    const { seriesIdx, pointIdx } = hoverPoint;
    if (seriesIdx < 0 || seriesIdx >= payload.series.length) return null;
    const s = payload.series[seriesIdx];
    if (!s) return null;
    const value = s.values[pointIdx];
    if (value === undefined) return null;
    const labels =
      payload.kind === 'bar' ? payload.labels : payload.xLabels;
    const xLabel = labels[pointIdx] ?? '';
    return {
      seriesName: s.name,
      xLabel,
      value,
    };
  }, [hoverPoint, payload]);

  return (
    <div
      className={styles.wrapper}
      data-testid="result-renderer-chart"
      data-result-id={node.id}
      data-chart-kind={kind}
      data-series-count={
        payload.series.length /* series/label count lives in JSON for full audit */
      }
      data-hidden-series-count={hiddenSeries.size}
      role="img"
      aria-label={`Chart: ${kind}`}
    >
      <svg
        className={styles.svg}
        viewBox={`0 0 ${VIEWBOX_W} ${VIEWBOX_H}`}
        preserveAspectRatio="xMidYMid meet"
        focusable="false"
      >
        <desc data-testid="result-renderer-chart-desc">
          {buildChartSummary(payload)}
        </desc>
        {kind === 'bar'
          ? renderBarChart(payload, title, {
              hiddenSeries,
              selectedPoint,
              onPointClick: handlePointClick,
              onPointEnter: handlePointEnter,
              onPointLeave: handlePointLeave,
            })
          : renderLineChart(payload, title, {
              hiddenSeries,
              selectedPoint,
              onPointClick: handlePointClick,
              onPointEnter: handlePointEnter,
              onPointLeave: handlePointLeave,
            })}
      </svg>
      {/* Hover/focus tooltip lives outside the <svg> so screen
          readers do not treat it as part of the graphic. Pointer
          events disabled — the tooltip never intercepts clicks. */}
      {tooltipData !== null && (
        <div
          className={styles.tooltip}
          data-testid="result-renderer-chart-tooltip"
          data-series-name={tooltipData.seriesName}
          data-x-label={tooltipData.xLabel}
          data-value={tooltipData.value}
          role="status"
          aria-live="polite"
        >
          <span className={styles.tooltipSeries}>
            {tooltipData.seriesName}
          </span>
          <span className={styles.tooltipX}>{tooltipData.xLabel}</span>
          <span className={styles.tooltipValue}>{tooltipData.value}</span>
        </div>
      )}
      <Legend
        payload={payload}
        hiddenSeries={hiddenSeries}
        onToggle={toggleSeries}
      />
    </div>
  );
}

function Legend({
  payload,
  hiddenSeries,
  onToggle,
}: {
  payload: ChartPayload;
  hiddenSeries: Set<number>;
  onToggle: (seriesIdx: number) => void;
}) {
  // Render legend as DOM <button>s outside the <svg> so each
  // entry is a real keyboard-accessible toggle, not a <text>
  // inside the graphic.
  return (
    <div
      className={styles.legend}
      data-testid="result-renderer-chart-legend"
      role="group"
      aria-label="Chart series toggle"
    >
      {payload.series.map((s, idx) => {
        const hidden = hiddenSeries.has(idx);
        return (
          <button
            key={`legend-btn-${idx}`}
            type="button"
            className={`${styles.legendButton}${hidden ? ` ${styles.legendButtonHidden}` : ''}`}
            data-testid={`result-renderer-chart-legend-${idx}`}
            data-series-name={s.name}
            data-hidden={hidden ? 'true' : 'false'}
            aria-pressed={hidden}
            aria-label={`${hidden ? 'Show' : 'Hide'} series ${s.name}`}
            onClick={() => onToggle(idx)}
            onKeyDown={(e) => {
              if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                onToggle(idx);
              }
            }}
          >
            <span className={styles.legendSwatch} aria-hidden="true" />
            <span className={styles.legendText}>{s.name}</span>
          </button>
        );
      })}
    </div>
  );
}

type InteractionHandlers = {
  hiddenSeries: Set<number>;
  selectedPoint: SelectedPoint;
  onPointClick: (seriesIdx: number, pointIdx: number) => void;
  onPointEnter: (seriesIdx: number, pointIdx: number) => void;
  onPointLeave: () => void;
};

function isPointSelected(
  selected: SelectedPoint,
  seriesIdx: number,
  pointIdx: number,
): boolean {
  return (
    selected !== null &&
    selected.seriesIdx === seriesIdx &&
    selected.pointIdx === pointIdx
  );
}

function pointAriaLabel(seriesName: string, xLabel: string, value: number): string {
  return `${seriesName} at ${xLabel}: ${value}`;
}

function renderBarChart(
  payload: BarPayload,
  title: string,
  handlers: InteractionHandlers,
): ReactNode {
  const { labels, series } = payload;
  const { x0, x1, y0, y1 } = plotBox();

  const allValues = series.flatMap((s) => s.values);
  const [min, max] = range(allValues);
  const slotCount = labels.length;
  const slotWidth = (x1 - x0) / Math.max(slotCount, 1);
  const groupWidth = slotWidth * 0.78;
  const barWidth = groupWidth / Math.max(series.length, 1);

  return (
    <g>
      {/* Y axis baseline */}
      <line
        x1={x0}
        x2={x1}
        y1={y1}
        y2={y1}
        className={styles.axis}
      />
      {/* X axis */}
      <line
        x1={x0}
        x2={x0}
        y1={y0}
        y2={y1}
        className={styles.axis}
      />
      {labels.map((label, slotIdx) => {
        const slotX = x0 + slotIdx * slotWidth + (slotWidth - groupWidth) / 2;
        return series.map((s, seriesIdx) => {
          const value = s.values[slotIdx];
          if (value === undefined) return null;
          const isHidden = handlers.hiddenSeries.has(seriesIdx);
          if (isHidden) return null;
          const bx = slotX + seriesIdx * barWidth;
          const by = yScale(value, min, max);
          const bh = y1 - by;
          const selected = isPointSelected(
            handlers.selectedPoint,
            seriesIdx,
            slotIdx,
          );
          return (
            <g key={`bar-${slotIdx}-${seriesIdx}`}>
              <rect
                x={bx}
                y={by}
                width={Math.max(barWidth - 1, 1)}
                height={Math.max(bh, 0)}
                className={`${styles.bar}${selected ? ` ${styles.barSelected}` : ''}`}
                rx={1.5}
                role="button"
                tabIndex={0}
                aria-label={pointAriaLabel(s.name, label, value)}
                aria-selected={selected}
                data-testid={`result-renderer-chart-bar-${seriesIdx}-${slotIdx}`}
                onClick={() => handlers.onPointClick(seriesIdx, slotIdx)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault();
                    handlers.onPointClick(seriesIdx, slotIdx);
                  }
                }}
                onMouseEnter={() =>
                  handlers.onPointEnter(seriesIdx, slotIdx)
                }
                onMouseLeave={handlers.onPointLeave}
                onFocus={() => handlers.onPointEnter(seriesIdx, slotIdx)}
                onBlur={handlers.onPointLeave}
              >
                <title>{`${label} · ${s.name}: ${value}`}</title>
              </rect>
              {barWidth >= 18 && (
                <text
                  x={bx + barWidth / 2}
                  y={by - 3}
                  className={styles.barLabel}
                  textAnchor="middle"
                >
                  {value}
                </text>
              )}
            </g>
          );
        });
      })}
      {labels.map((label, slotIdx) => {
        const cx = x0 + slotIdx * slotWidth + slotWidth / 2;
        return (
          <text
            key={`xt-${slotIdx}`}
            x={cx}
            y={y1 + 14}
            className={styles.tickLabel}
            textAnchor="middle"
          >
            {label}
          </text>
        );
      })}
      {/* In-SVG legend text mirrors the interactive DOM <button>
          legend. The DOM buttons carry the real a11y + keyboard
          behaviour; these <text>s keep series names discoverable
          inside the <svg> so screen readers that walk the
          graphic still see them. Marked aria-hidden so SR does
          not double-announce. */}
      <g
        transform={`translate(${x0}, ${VIEWBOX_H - 16})`}
        aria-hidden="true"
        data-testid="result-renderer-chart-legend-svg"
      >
        {series.map((s, idx) => (
          <g key={`legend-svg-${idx}`} transform={`translate(${idx * 110}, 0)`}>
            <rect
              x={0}
              y={-8}
              width={10}
              height={10}
              className={styles.legendSwatch}
              rx={1.5}
            />
            <text x={14} y={0} className={styles.legendText}>
              {s.name}
            </text>
          </g>
        ))}
      </g>
      <title>{title}</title>
    </g>
  );
}

function renderLineChart(
  payload: LinePayload,
  title: string,
  handlers: InteractionHandlers,
): ReactNode {
  const { xLabels, series } = payload;
  const { x0, x1, y0, y1 } = plotBox();

  const allValues = series.flatMap((s) => s.values);
  const [min, max] = range(allValues);
  const pointCount = xLabels.length;
  const dx = (x1 - x0) / Math.max(pointCount - 1, 1);

  return (
    <g>
      {/* X axis */}
      <line
        x1={x0}
        x2={x1}
        y1={y1}
        y2={y1}
        className={styles.axis}
      />
      {/* Y axis */}
      <line
        x1={x0}
        x2={x0}
        y1={y0}
        y2={y1}
        className={styles.axis}
      />
      {series.map((s, seriesIdx) => {
        const isHidden = handlers.hiddenSeries.has(seriesIdx);
        if (isHidden) {
          // Render nothing for a hidden series so its polyline
          // and dots are not visible at all. Its legend button
          // remains so the user can re-enable it.
          return null;
        }
        const points = s.values.map((v, idx) => {
          const px = x0 + idx * dx;
          const py = yScale(v, min, max);
          return { px, py, v, label: xLabels[idx] ?? '' };
        });
        const polyline = points.map((p) => `${p.px},${p.py}`).join(' ');
        return (
          <g key={`line-${seriesIdx}`}>
            <polyline
              points={polyline}
              className={styles.line}
              fill="none"
            />
            {points.map((p, idx) => {
              const selected = isPointSelected(
                handlers.selectedPoint,
                seriesIdx,
                idx,
              );
              return (
                <circle
                  key={`dot-${seriesIdx}-${idx}`}
                  cx={p.px}
                  cy={p.py}
                  r={selected ? 4.5 : 2.5}
                  className={`${styles.dot}${selected ? ` ${styles.dotSelected}` : ''}`}
                  role="button"
                  tabIndex={0}
                  aria-label={pointAriaLabel(s.name, p.label, p.v)}
                  aria-selected={selected}
                  data-testid={`result-renderer-chart-dot-${seriesIdx}-${idx}`}
                  onClick={() => handlers.onPointClick(seriesIdx, idx)}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter' || e.key === ' ') {
                      e.preventDefault();
                      handlers.onPointClick(seriesIdx, idx);
                    }
                  }}
                  onMouseEnter={() =>
                    handlers.onPointEnter(seriesIdx, idx)
                  }
                  onMouseLeave={handlers.onPointLeave}
                  onFocus={() => handlers.onPointEnter(seriesIdx, idx)}
                  onBlur={handlers.onPointLeave}
                >
                  <title>{`${p.label} · ${s.name}: ${p.v}`}</title>
                </circle>
              );
            })}
          </g>
        );
      })}
      {xLabels.map((label, idx) => {
        const cx = x0 + idx * dx;
        return (
          <text
            key={`xt-${idx}`}
            x={cx}
            y={y1 + 14}
            className={styles.tickLabel}
            textAnchor="middle"
          >
            {label}
          </text>
        );
      })}
      {/* In-SVG legend text mirrors the interactive DOM <button>
          legend. The DOM buttons carry the real a11y + keyboard
          behaviour; these <text>s keep series names discoverable
          inside the <svg> so screen readers that walk the
          graphic still see them. Marked aria-hidden so SR does
          not double-announce. */}
      <g
        transform={`translate(${x0}, ${VIEWBOX_H - 16})`}
        aria-hidden="true"
        data-testid="result-renderer-chart-legend-svg"
      >
        {series.map((s, idx) => (
          <g key={`legend-svg-${idx}`} transform={`translate(${idx * 110}, 0)`}>
            <rect
              x={0}
              y={-8}
              width={10}
              height={10}
              className={styles.legendSwatch}
              rx={1.5}
            />
            <text x={14} y={0} className={styles.legendText}>
              {s.name}
            </text>
          </g>
        ))}
      </g>
      <title>{title}</title>
    </g>
  );
}

// ============================================================
// TableRenderer — P1.5 export action bar (UI-AGENTWB-006)
//
// Tests cover:
//   - Both buttons render for a valid table (CSV / Markdown)
//   - All five malformed payloads render the fallback path
//     with no action bar / no download buttons
//   - CSV byte format: BOM prefix, comma/semicolon escapes,
//     null cells become empty strings, numeric cells unquoted
//   - CSV MIME type from the Blob construction
//   - CSV filename: title slug + ISO timestamp segment
//   - Markdown format: `| col |`, `| --- |`, null cells empty
//   - Markdown MIME type
//   - Markdown filename mirrors the CSV slug
//   - Button aria-labels match the spec
//   - Download uses Blob + URL.createObjectURL + revokeObjectURL
//
// Pure helpers (`buildCsv`, `buildMarkdown`, `buildFilename`)
// are exported as top-level functions from the renderer so the
// byte-format tests do not need to mount React.
// ============================================================

import { cleanup, fireEvent, render, screen } from '@testing-library/react';
import { afterEach, describe, expect, it, vi } from 'vitest';
import type { ResultNode } from '../types';
import {
  buildCsv,
  buildFilename,
  buildMarkdown,
  TableRenderer,
} from './TableRenderer';

function makeValidNode(): ResultNode {
  return {
    id: 'table-p1-5',
    type: 'table',
    title: 'Cell counts',
    payload: {
      columns: ['gene', 'control', 'treated'],
      rows: [
        ['TP53', 10, 12],
        ['BRCA1', 20, 18],
        ['MYC', null, 35],
      ],
    },
    createdAt: '2026-08-15T07:30:00Z',
  };
}

type CapturedDownload = {
  blob: Blob;
  filename: string;
  anchor: HTMLAnchorElement;
};

function captureDownload(node: ResultNode, testId: string): CapturedDownload {
  const captured: CapturedDownload = {
    // Sentinel — replaced by the actual Blob created inside
    // the production path. The placeholder lets the type
    // stay non-null while the spy installs.
    blob: undefined as unknown as Blob,
    filename: '',
    anchor: undefined as unknown as HTMLAnchorElement,
  };

  const originalCreate = URL.createObjectURL;
  const originalRevoke = URL.revokeObjectURL;
  // Track the revocations so we can assert them on the spy.
  const revoked: string[] = [];
  const urlSpy = vi.fn((blob: Blob) => {
    captured.blob = blob;
    return 'blob:mock-table-renderer-url';
  });
  const revokeSpy = vi.fn((url: string) => {
    revoked.push(url);
  });
  URL.createObjectURL = urlSpy as unknown as typeof URL.createObjectURL;
  URL.revokeObjectURL = revokeSpy as unknown as typeof URL.revokeObjectURL;

  // Spy on the anchor click so the production path's
  // `anchor.click()` does not actually navigate happy-dom.
  const clickSpy = vi
    .spyOn(HTMLAnchorElement.prototype, 'click')
    .mockImplementation(function mockClick(this: HTMLAnchorElement) {
      captured.anchor = this;
      captured.filename = this.download;
    });

  try {
    render(<TableRenderer node={node} />);
    fireEvent.click(screen.getByTestId(testId));
    // Expose the revocation log via the captured object.
    (captured as CapturedDownload & { revoked: string[] }).revoked = revoked;
    return captured;
  } finally {
    URL.createObjectURL = originalCreate;
    URL.revokeObjectURL = originalRevoke;
    clickSpy.mockRestore();
  }
}

afterEach(() => {
  cleanup();
  vi.restoreAllMocks();
});

describe('TableRenderer — P1.5 CSV / Markdown export rows', () => {
  it('renders both CSV and Markdown buttons for a valid table', () => {
    render(<TableRenderer node={makeValidNode()} />);

    expect(
      screen.getByTestId('result-renderer-table-download-csv'),
    ).toBeTruthy();
    expect(
      screen.getByTestId('result-renderer-table-download-markdown'),
    ).toBeTruthy();
    expect(screen.getByLabelText('Download CSV')).toBeTruthy();
    expect(screen.getByLabelText('Download Markdown')).toBeTruthy();
  });

  it('does not render the CSV / Markdown buttons on the fallback path', () => {
    const malformedPayloads: Array<{ name: string; payload: unknown }> = [
      { name: 'missing-columns', payload: { rows: [] } },
      { name: 'wrong-column-type', payload: { columns: [1, 2, 3], rows: [] } },
      { name: 'wrong-row-shape', payload: { columns: ['g'], rows: [[true]] } },
      { name: 'empty-columns', payload: { columns: [], rows: [] } },
      { name: 'not-an-object', payload: 'this is not a table' },
    ];

    for (const { name, payload } of malformedPayloads) {
      const node: ResultNode = {
        id: `bad-${name}`,
        type: 'table',
        title: `Bad (${name})`,
        payload,
        createdAt: '2026-08-15T07:30:00Z',
      };
      const { container } = render(<TableRenderer node={node} />);

      expect(
        screen.getByTestId('result-renderer-table-fallback'),
      ).toBeTruthy();
      expect(screen.queryByLabelText('Download CSV')).toBeNull();
      expect(screen.queryByLabelText('Download Markdown')).toBeNull();
      expect(container.querySelectorAll('button').length).toBe(0);
      cleanup();
    }
  });
});

describe('TableRenderer — CSV format', () => {
  it('builds CSV with a UTF-8 BOM, header row, and numeric cells unquoted', () => {
    const csv = buildCsv(
      ['gene', 'control', 'treated'],
      [
        ['TP53', 10, 12],
        ['BRCA1', 20, 18],
      ],
    );

    // BOM prefix is mandatory for Excel / UTF-8 robustness.
    expect(csv.charCodeAt(0)).toBe(0xfeff);
    expect(csv).toContain('gene,control,treated');
    // Numeric cells remain unquoted — values are preserved as-is.
    expect(csv).toContain('TP53,10,12');
    expect(csv).toContain('BRCA1,20,18');
  });

  it('escapes cells containing commas, double quotes, and newlines', () => {
    const csv = buildCsv(['note'], [['has, comma']]);
    expect(csv).toContain('"has, comma"');

    const csvQuote = buildCsv(['note'], [['has "quote" inside']]);
    expect(csvQuote).toContain('"has ""quote"" inside"');

    const csvNewline = buildCsv(['note'], [['line one\nline two']]);
    expect(csvNewline).toContain('"line one\nline two"');
  });

  it('emits an empty string for null cells', () => {
    const csv = buildCsv(['gene', 'value'], [['TP53', null]]);
    const lines = csv.replace(/^\uFEFF/, '').split('\n');
    expect(lines[0]).toBe('gene,value');
    // After the comma, the row should end with nothing (no `null`,
    // no `—`, no quoted empty cell).
    expect(lines[1]).toBe('TP53,');
  });
});

describe('TableRenderer — Markdown format', () => {
  it('builds Markdown with header, separator, and body rows', () => {
    const md = buildMarkdown(
      ['gene', 'control', 'treated'],
      [
        ['TP53', 10, 12],
        ['BRCA1', 20, 18],
      ],
    );

    const lines = md.split('\n');
    expect(lines[0]).toBe('| gene | control | treated |');
    expect(lines[1]).toBe('| --- | --- | --- |');
    expect(lines[2]).toBe('| TP53 | 10 | 12 |');
    expect(lines[3]).toBe('| BRCA1 | 20 | 18 |');
  });

  it('emits empty cells for null values in Markdown', () => {
    const md = buildMarkdown(['gene', 'value'], [['MYC', null]]);
    // The boundary between the cell and the closing pipe must be
    // two spaces surrounding an empty cell, never `—` or `null`.
    expect(md).toContain('| MYC |  |');
    expect(md).not.toContain('—');
    expect(md).not.toContain('null');
  });
});

describe('TableRenderer — filename', () => {
  it('uses a kebab-case title slug plus an ISO timestamp segment', () => {
    const csvName = buildFilename(
      'Cell counts',
      '2026-08-15T07:30:00Z',
      'csv',
    );
    expect(csvName).toBe('cell-counts-2026-08-15T07-30.csv');

    const mdName = buildFilename(
      'Cell counts',
      '2026-08-15T07:30:00Z',
      'md',
    );
    expect(mdName).toBe('cell-counts-2026-08-15T07-30.md');
  });

  it('falls back to `table-` prefix when the title is empty', () => {
    const csvName = buildFilename('', '2026-08-15T07:30:00Z', 'csv');
    expect(csvName).toMatch(/^table-2026-08-15T07-30\.csv$/);
  });

  it('strips unsafe characters from the title slug', () => {
    const csvName = buildFilename(
      'My / Weird * Title?',
      '2026-08-15T07:30:00Z',
      'csv',
    );
    // The slug should retain only word characters and dashes.
    expect(csvName).toBe('my-weird-title-2026-08-15T07-30.csv');
  });
});

