                    {peer.petriVersion ? ` · v${peer.petriVersion}` : ''}
                    {probeOk && peer.lastProbe?.latencyMs != null ? ` · ${peer.lastProbe.latencyMs}ms` : ''}
                    {probeBad ? ` · ${peer.lastProbe?.error || '离线'}` : ''}
                  </span>
                </div>
                <button
