// ============================================================
// DesktopSettingsPanel — Trash management section
//
// Extracted from src/components/desktop/DesktopSettingsPanel.tsx
// by BLOCK-9.2 PHASE 1. Original location: lines 512-653.
//
// Lists archived projects + conversations; restore / permanently delete
// / empty trash. Uses project-store + copilotConversationsClient.
// ============================================================

import React, { useCallback, useEffect, useState } from 'react';
import { Icon } from '@/components/icons/Icon';
import { deleteProject, listProjects, setProjectStatus } from '@/lib/project-store';
import type { Project } from '@/lib/project-types';
import {
  archiveConversation,
  deleteConversation,
  listConversations,
  type ConversationSummary,
} from '@/components/copilot/copilotConversationsClient';

export function TrashManagement(): React.ReactElement {
  const [projects, setProjects] = useState<Project[]>([]);
  const [conversations, setConversations] = useState<ConversationSummary[]>([]);
  const [loading, setLoading] = useState(true);
  const [busyId, setBusyId] = useState<string | null>(null);

  const loadTrash = useCallback(async () => {
    setLoading(true);
    try {
      const [activeProjects, archivedProjects] = await Promise.all([
        listProjects(),
        listProjects(undefined, 'archived'),
      ]);
      const allProjects = [...activeProjects, ...archivedProjects];
      const archivedConversations = await Promise.all(
        allProjects.map((project) => listConversations('archived', project.id))
      );
      setProjects(archivedProjects);
      setConversations(archivedConversations.flat());
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void loadTrash();
  }, [loadTrash]);

  const restoreProject = async (projectId: string) => {
    setBusyId(projectId);
    try {
      await setProjectStatus(projectId, 'active');
      await loadTrash();
    } finally {
      setBusyId(null);
    }
  };

  const restoreConversation = async (conversationId: string) => {
    setBusyId(conversationId);
    try {
      await archiveConversation(conversationId, false);
      await loadTrash();
    } finally {
      setBusyId(null);
    }
  };

  const permanentlyDeleteProject = async (projectId: string) => {
    if (!window.confirm('永久删除这个项目记录及其应用内数据？外部工作目录不会被删除。此操作无法撤销。')) return;
    setBusyId(projectId);
    try {
      await deleteProject(projectId);
      await loadTrash();
    } finally {
      setBusyId(null);
    }
  };

  const permanentlyDeleteConversation = async (conversationId: string) => {
    if (!window.confirm('永久删除这个会话及其消息？此操作无法撤销。')) return;
    setBusyId(conversationId);
    try {
      await deleteConversation(conversationId);
      await loadTrash();
    } finally {
      setBusyId(null);
    }
  };

  const emptyTrash = async () => {
    if (projects.length + conversations.length === 0) return;
    if (!window.confirm('永久清空回收站？项目记录、会话和消息将无法恢复；外部工作目录不会被删除。')) return;
    setBusyId('all');
    try {
      // Delete conversations first. Project deletion cascades its remaining
      // conversations, so avoiding concurrent requests keeps the operation
      // deterministic when both appear in the recycle bin.
      for (const conversation of conversations) {
        await deleteConversation(conversation.id);
      }
      for (const project of projects) {
        await deleteProject(project.id);
      }
      await loadTrash();
    } finally {
      setBusyId(null);
    }
  };

  const projectNameById = new Map(
    projects.map((project) => [project.id, project.name])
  );
  const count = projects.length + conversations.length;

  return (
    <div className="petri-trash-section">
      <div className="petri-trash-section__header">
        <div>
          <strong>回收站</strong>
          <p>移除的项目和会话会保留在这里，清理后才会永久删除。</p>
        </div>
        <button
          type="button"
          className="petri-btn petri-btn--danger-ghost petri-btn--sm"
          onClick={() => void emptyTrash()}
          disabled={loading || count === 0 || busyId !== null}
        >
          清空回收站{count > 0 ? ` (${count})` : ''}
        </button>
      </div>
      {loading ? (
        <div className="petri-trash-empty">正在读取回收站…</div>
      ) : count === 0 ? (
        <div className="petri-trash-empty">回收站为空</div>
      ) : (
        <div className="petri-trash-list">
          {projects.map((project) => (
            <div key={project.id} className="petri-trash-item">
              <Icon name="folder" size={14} />
              <div><strong>{project.name}</strong><small>项目</small></div>
              <button className="petri-btn petri-btn--ghost petri-btn--sm" type="button" onClick={() => void restoreProject(project.id)} disabled={busyId !== null}>恢复</button>
              <button type="button" className="danger" onClick={() => void permanentlyDeleteProject(project.id)} disabled={busyId !== null}>永久删除</button>
            </div>
          ))}
          {conversations.map((conversation) => (
            <div key={conversation.id} className="petri-trash-item">
              <Icon name="message-circle" size={14} />
              <div>
                <strong>{conversation.title}</strong>
                <small>会话{conversation.project_id ? ` · ${projectNameById.get(conversation.project_id) || '现有项目'}` : ''}</small>
              </div>
              <button className="petri-btn petri-btn--ghost petri-btn--sm" type="button" onClick={() => void restoreConversation(conversation.id)} disabled={busyId !== null}>恢复</button>
              <button type="button" className="danger" onClick={() => void permanentlyDeleteConversation(conversation.id)} disabled={busyId !== null}>永久删除</button>
            </div>
          ))}
        </div>
      )}
      <p className="petri-field__hint">永久清理只删除 Petri 内的项目记录、会话和关联消息，不会删除你选择的外部工作目录。</p>
    </div>
  );
}

import React from 'react';
import { cleanup, render, screen } from '@testing-library/react';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

import { UpdateChecker } from './UpdateChecker';

const useAutoUpdateMock = vi.fn();

vi.mock('@/hooks/useAutoUpdate', () => ({
  useAutoUpdate: () => useAutoUpdateMock(),
}));

type DesktopGlobal = { petriDesktop?: { updater?: unknown } };

function autoUpdateState() {
  return {
    checking: false,
    available: false,
    availableVersion: '',
    downloading: false,
    progress: null,
    downloaded: false,
    error: '',
    upToDate: false,
    installing: false,
    check: vi.fn(),
    download: vi.fn(),
    install: vi.fn(),
  };
}

describe('UpdateChecker hooks order', () => {
  beforeEach(() => {
    useAutoUpdateMock.mockReset();
    useAutoUpdateMock.mockReturnValue(autoUpdateState());
    delete (window as unknown as DesktopGlobal).petriDesktop;
  });

  afterEach(() => {
    cleanup();
    delete (window as unknown as DesktopGlobal).petriDesktop;
  });

  // 回归门：useAutoUpdate() 必须无条件调用。修复前它排在 `if (!updater) return null`
  // 之后——桥在两次渲染间出现/消失时 hook 数量变化，React 卸载整棵树。
  it('桥缺失时仍调用 useAutoUpdate（hook 调用无条件）并渲染为空', () => {
    const { container } = render(<UpdateChecker />);
    expect(useAutoUpdateMock).toHaveBeenCalledTimes(1);
    expect(container.textContent).toBe('');
  });

  it('桥在位时渲染更新区块', () => {
    (window as unknown as DesktopGlobal).petriDesktop = { updater: { check: vi.fn() } };
    const { container } = render(<UpdateChecker />);
    expect(useAutoUpdateMock).toHaveBeenCalledTimes(1);
    expect(container.querySelector('.petri-update-section')).toBeTruthy();
    expect(screen.getAllByRole('button').length).toBeGreaterThan(0);
  });
});

// ============================================================
// DesktopSettingsPanel — Update checker section
//
// Extracted from src/components/desktop/DesktopSettingsPanel.tsx
// by BLOCK-9.2 PHASE 1. Original location: lines 162-207.
//
// Wraps useAutoUpdate hook into a 4-state UI (idle / checking /
// downloading / available / downloaded). Pure delegated component.
// ============================================================

import React from 'react';
import { useAutoUpdate } from '@/hooks/useAutoUpdate';

export function UpdateChecker(): React.ReactElement | null {
  // hooks 顺序纪律：useAutoUpdate() 必须无条件调用（它自身对桥缺失有守卫），
  // 早退只能放在 hook 之后——条件在两次渲染间翻转时提前 return 会让 hook 数量变化，
  // React 抛「Rendered more hooks than during the previous render」并卸载整棵树。
  // （同类实例：DesktopOnboarding 首启整页空白，P6 渲染层实机抓真。）
  const { checking, available, availableVersion, downloading, progress, downloaded, error, upToDate, installing, check, download, install } =
    useAutoUpdate();

  if (!window.petriDesktop?.updater) return null;

  const pct = progress !== null ? Math.round(progress * 100) : 0;

  return (
    <div className="petri-update-section">
      {downloaded ? (
        <button
          type="button"
          className="petri-btn petri-btn--primary petri-btn--sm"
          onClick={install}
          disabled={installing}
        >
          {installing ? '正在打开…' : '打开安装包'}
        </button>
      ) : downloading ? (
        <span className="petri-update-progress">下载中 {pct}%</span>
      ) : available ? (
        <button
          type="button"
          className="petri-btn petri-btn--primary petri-btn--sm"
          onClick={download}
        >
          下载 v{availableVersion}
        </button>
      ) : (
        <button
          type="button"
          className="petri-btn petri-btn--ghost petri-btn--sm"
          onClick={check}
          disabled={checking}
        >
          {checking ? '检查中…' : '检查更新'}
        </button>
      )}
      {upToDate && !error && (
        <span className="petri-field__hint">当前已是最新版本</span>
      )}
      {error && <span className="petri-field__hint">{error}</span>}
    </div>
  );
}

// ============================================================
// DesktopSettingsPanel — Usage & Resource panel section
//
// Extracted from src/components/desktop/DesktopSettingsPanel.tsx
// by BLOCK-9.2 PHASE 1. Original location: lines 84-125.
//
// 30-day usage aggregation + runtime resource snapshot. Self-contained
// (uses useRuntimeResourceSnapshot + getPlatformApiPrefix + getToken).
// BLOCK-79 P2 — 按供应商的输出速率统一展示面（统一在此一处，不散落）；
// 速率口径 = 端到端平均输出速率（含排队/首 token 前处理/网络，是真实解码
// 速度的下限，禁止称「解码速度」）；渠道未返回 usage 时显示「不可算」。
// ============================================================

import React, { useEffect, useState } from 'react';
import { useRuntimeResourceSnapshot } from '@/hooks/useRuntimeResourceSnapshot';
import { getPlatformApiPrefix, getToken } from '@/lib/authClient';
import { formatMetricBytes } from '../helpers';
import type { UsageSummary, ProviderUsageRow } from '../types';

export function UsageResourcePanel(): React.ReactElement {
  const { snapshot, loading, error, refresh } = useRuntimeResourceSnapshot();
  const [usage, setUsage] = useState<UsageSummary | null>(null);
  const [usageError, setUsageError] = useState('');
  useEffect(() => {
    const token = getToken();
    void fetch(`${getPlatformApiPrefix()}/ai/usage-mine?days=30`, {
      headers: token ? { Authorization: `Bearer ${token}` } : undefined,
    }).then(async (response) => {
      const data = await response.json();
      if (!response.ok || data?.status !== 'ok') throw new Error(data?.error || '用量不可用');
      setUsage(data);
      setUsageError('');
    }).catch((reason) => setUsageError(reason instanceof Error ? reason.message : String(reason)));
  }, []);
  const resourceLabel = snapshot?.state === 'ready' ? '资源正常' : snapshot?.state === 'warning' ? '需要注意' : snapshot ? '资源不足' : '检查中';
  const providers: ProviderUsageRow[] = Array.isArray(usage?.providers) ? usage!.providers : [];
  const formatLatency = (ms: number | undefined) =>
    ms != null && Number.isFinite(Number(ms)) ? `${(Number(ms) / 1000).toFixed(2)} s` : '—';
  return (
    <div className="petri-usage-resource">
      <div className="petri-metric-grid">
        <div><small>30 天调用</small><strong>{usage?.calls ?? '—'}</strong></div>
        <div><small>输入 / 输出 Token</small><strong>{usage ? `${usage.prompt_tokens || 0} / ${usage.completion_tokens || 0}` : '—'}</strong></div>
        <div><small>缓存命中</small><strong>{usage ? `${((usage.cache_hit_rate || 0) * 100).toFixed(1)}%` : '—'}</strong></div>
        <div><small>估算成本</small><strong>{usage ? `¥${Number(usage.estimated_cost_cny || 0).toFixed(4)}` : '—'}</strong></div>
      </div>
      <p className="petri-field__hint">
        {usageError || (usage?.cost_status === 'partial' ? `${usage.unknown_cost_calls} 次调用缺少可靠价格，金额仅为部分估算。` : '成本来自已知价格表；供应商未返回价格时不会伪造金额。')}
      </p>
      {/* BLOCK-79 — 按供应商的输出速率（统一展示面） */}
      <div className="petri-resource-heading">
        <div><strong>供应商速率（30 天）</strong><p>输出 tokens/s = 端到端平均输出速率（含首 token 前处理与网络，为解码速度下限）</p></div>
      </div>
      {providers.length === 0 ? (
        <p className="petri-field__hint">暂无可统计的调用记录。</p>
      ) : (
        <div className="petri-metric-grid">
          {providers.map((row) => {
            const speed = row.measurable && row.tokensPerSecond != null
              ? `${row.tokensPerSecond} tok/s`
              : '不可算（未返回用量）';
            return (
              <div key={row.provider}>
                <small>{row.provider} · {row.calls} 次调用</small>
                <strong title="端到端平均输出速率 = 输出 token 总数 ÷ 总墙钟时间">{speed}</strong>
                <small>输出 {row.outputTokens.toLocaleString()} tok · 平均延迟 {formatLatency(row.latencyMs > 0 ? row.latencyMs / Math.max(1, row.calls) : undefined)}</small>
              </div>
            );
          })}
          <div>
            <small>全部供应商 · 平均延迟</small>
            <strong>{usage ? formatLatency(usage.avg_latency) : '—'}</strong>
            <small>{usage ? `${Math.round(Number(usage.avg_latency || 0))} ms / 次（含 embedding）` : ''}</small>
          </div>
        </div>
      )}
      <hr className="petri-section-divider" />
      <div className="petri-resource-heading">
        <div><strong>{resourceLabel}</strong><p>{snapshot ? `${snapshot.platform} · 观测于 ${new Date(snapshot.observedAt).toLocaleTimeString()}` : error || '正在读取机器状态'}</p></div>
        <button type="button" className="petri-btn petri-btn--ghost petri-btn--sm" disabled={loading} onClick={() => void refresh()}>刷新</button>
      </div>
      <div className="petri-metric-grid">
        <div><small>CPU</small><strong>{snapshot ? `${snapshot.cpu.logicalCores} 核 · ${snapshot.cpu.load1m?.toFixed(2) ?? '—'}` : '—'}</strong></div>
        <div><small>可用内存</small><strong>{formatMetricBytes(snapshot?.memory.availableBytes)}</strong></div>
        <div><small>可用磁盘</small><strong>{formatMetricBytes(snapshot?.disk.availableBytes)}</strong></div>
        <div><small>活跃 Job</small><strong>{snapshot?.activeJobs ?? '—'}</strong></div>
      </div>
      <p className="petri-field__hint">资源快照每 10 秒刷新、30 秒失效。GPU 仅在运行时能够可靠探测时展示。</p>
    </div>
  );
}

import { useCallback, useEffect, useRef, useState } from 'react';
import type { Dispatch, MutableRefObject, SetStateAction } from 'react';
import {
  useAiSettings,
  type ChatModelPreset,
} from '@/hooks/useAiSettings';
import {
  inferUserModelProvider,
  isUserConfigurableModelProvider,
  modelProviderCredentialRef,
  modelProviderProtocol,
  modelProviderRequiresCredential,
  normalizeLegacyUserModelProfile,
  type UserModelProvider,
  validateUserModelProfile,
} from '@/lib/model-provider-options';
import {
  exportEndpointProfilesCsv,
  exportEndpointProfilesJson,
  parseEndpointProfiles,
} from '@/lib/model-endpoint-transfer';
import { credentialId } from './model-types';
import { MODEL_ROLES, providerDefaults, type ModelRole } from './model-types';
import { getBridge } from '@/lib/desktopBridge';

/**
 * BLOCK-92 Wave B-4 — API Endpoint（模型渠道）编辑器状态簇外迁
 * （原 DesktopSettingsPanel.tsx 内联，纯搬运零行为变化）：
 * 渠道 profiles / 角色绑定 / 容错绑定 / 凭据输入与状态 / 连通性测试 /
 * 上下文窗口草稿 / 导入导出全部由此承载；主组件只做 JSX 渲染与保存按钮。
 */
export function useEndpointProfilesEditor(): {
  settings: Record<string, unknown>;
  setSettings: Dispatch<SetStateAction<Record<string, unknown>>>;
  loadingModels: Record<string, boolean>;
  availableModels: Record<string, string[]>;
  testResult: Record<string, { ok: boolean; message: string }>;
  saving: boolean;
  saved: boolean;
  modelProfiles: ChatModelPreset[];
  roleBindings: Partial<Record<ModelRole, string>>;
  setRoleBindings: Dispatch<SetStateAction<Partial<Record<ModelRole, string>>>>;
  fallbackEnabled: boolean;
  setFallbackEnabled: Dispatch<SetStateAction<boolean>>;
  fallbackBindings: Partial<Record<ModelRole, string[]>>;
  setFallbackBindings: Dispatch<SetStateAction<Partial<Record<ModelRole, string[]>>>>;
  credentialInputs: Record<string, string>;
  setCredentialInputs: Dispatch<SetStateAction<Record<string, string>>>;
  credentialStatus: Record<string, boolean>;
  visibleCredentialIds: Record<string, boolean>;
  copiedCredentialId: string | null;
  profileErrors: Record<string, string>;
  credentialBackend: string;
  endpointTransferMessage: string | null;
  contextWindowDrafts: Record<string, string>;
  setContextWindowDrafts: Dispatch<SetStateAction<Record<string, string>>>;
  endpointImportRef: MutableRefObject<HTMLInputElement | null>;
  userModelProfiles: ChatModelPreset[];
  telemetryEnabled: boolean;
  setTelemetryEnabled: Dispatch<SetStateAction<boolean>>;
  loadSettings: () => Promise<void>;
  handleSave: () => Promise<void>;
  discoverModels: (profile: ChatModelPreset, apiKey?: string, silent?: boolean) => Promise<void>;
  clearProfileRuntimeState: (id: string) => void;
  updateProfile: (id: string, patch: Partial<ChatModelPreset>) => void;
  updateProfileBaseUrl: (profile: ChatModelPreset, baseUrl: string | undefined) => void;
  updateProfileProvider: (currentProfile: ChatModelPreset, provider: UserModelProvider) => void;
  addProfile: () => void;
  removeProfile: (id: string) => void;
  revealCredential: (id: string) => Promise<void>;
  copyCredential: (id: string) => Promise<void>;
  exportEndpoints: (format: 'json' | 'csv') => Promise<void>;
  importEndpoints: (file: File) => Promise<void>;
} {
  const [settings, setSettings] = useState<Record<string, unknown>>({});
  const [loadingModels, setLoadingModels] = useState<Record<string, boolean>>({});
  const [availableModels, setAvailableModels] = useState<Record<string, string[]>>({});
  const [testResult, setTestResult] = useState<Record<string, { ok: boolean; message: string }>>(
    {}
  );
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState(false);

  const [modelProfiles, setModelProfiles] = useState<ChatModelPreset[]>([]);
  const [roleBindings, setRoleBindings] = useState<Partial<Record<ModelRole, string>>>({});
  const [fallbackEnabled, setFallbackEnabled] = useState(false);
  const [fallbackBindings, setFallbackBindings] = useState<Partial<Record<ModelRole, string[]>>>({});
  const [credentialInputs, setCredentialInputs] = useState<Record<string, string>>({});
  const [credentialStatus, setCredentialStatus] = useState<Record<string, boolean>>({});
  const [visibleCredentialIds, setVisibleCredentialIds] = useState<Record<string, boolean>>({});
  const [copiedCredentialId, setCopiedCredentialId] = useState<string | null>(null);
  const [profileErrors, setProfileErrors] = useState<Record<string, string>>({});
  const [credentialBackend, setCredentialBackend] = useState('local');
  const [endpointTransferMessage, setEndpointTransferMessage] = useState<string | null>(null);
  const [contextWindowDrafts, setContextWindowDrafts] = useState<Record<string, string>>({});
  const endpointImportRef = useRef<HTMLInputElement | null>(null);
  const modelDiscoveryGeneration = useRef<Record<string, number>>({});
  const modelProfilesRef = useRef<ChatModelPreset[]>([]);
  const { refresh: refreshAiSettings } = useAiSettings();
  // M2-3：错误遥测开关（默认关闭）
  const [telemetryEnabled, setTelemetryEnabled] = useState(false);

  useEffect(() => {
    loadSettings();
  }, []);

  useEffect(() => {
    modelProfilesRef.current = modelProfiles;
  }, [modelProfiles]);

  async function loadSettings() {
    // BLOCK-87 L4-2 收尾：走 getBridge 而非直引 window.petriDesktop——投影
    // 环境下切 HTTP 桥（直引经 shim Proxy 拿到 undefined 会 TypeError）。
    const settingsBridge = getBridge('aiSettings');
    if (!settingsBridge) return;
    const s = await settingsBridge.get();
    setSettings(s);
    const profiles = Array.isArray(s.model_profiles)
      ? (s.model_profiles as ChatModelPreset[])
          .filter((profile) => profile?.id && profile?.model)
          .map(normalizeLegacyUserModelProfile)
          .map((profile) => ({ ...profile, defaultModel: profile.defaultModel || profile.model }))
      : [];
    const statuses = (s.credential_status as Record<string, boolean>) || {};
    setModelProfiles(profiles);
    setRoleBindings((s.model_role_bindings as Partial<Record<ModelRole, string>>) || {});
    setFallbackEnabled(s.model_fallback_enabled === true);
    setFallbackBindings((s.model_fallback_bindings as Partial<Record<ModelRole, string[]>>) || {});
    setCredentialStatus(statuses);
    setCredentialBackend(String(s.credential_backend || 'local'));
    await refreshAiSettings();
    setTelemetryEnabled(s.telemetry_enabled === true);
    profiles
      .filter((profile) =>
        isUserConfigurableModelProvider(profile.provider) &&
        ((modelProviderRequiresCredential(profile.provider) && statuses[credentialId(profile)]) ||
          (!modelProviderRequiresCredential(profile.provider) && Boolean(profile.baseUrl)))
      )
      .forEach((profile) => void discoverModels(profile, '', true));
  }

  async function handleSave() {
    const settingsBridge = getBridge('aiSettings');
    if (!settingsBridge) return;
    setSaving(true);
    setSaved(false);
    const nextProfileErrors = Object.fromEntries(
      modelProfiles
        .filter((profile) => isUserConfigurableModelProvider(profile.provider))
        .map((profile) => [profile.id, validateUserModelProfile(profile)])
        .filter((entry): entry is [string, string] => Boolean(entry[1]))
    );
    if (Object.keys(nextProfileErrors).length > 0) {
      setProfileErrors(nextProfileErrors);
      setSaving(false);
      return;
    }
    setProfileErrors({});
    const profiles = modelProfiles
      .filter((profile) => profile.id.trim() && profile.model.trim())
      .map((profile) => ({
        ...profile,
        defaultModel: profile.defaultModel || profile.model,
        roles: MODEL_ROLES.filter((role) => roleBindings[role.id] === profile.id).map((role) => role.id),
      }));
    const chatProfile = profiles.find((profile) => profile.id === roleBindings.chat);
    const embedProfile = profiles.find((profile) => profile.id === roleBindings.embedding);
    await settingsBridge.save({
      model_profiles: profiles,
      model_role_bindings: roleBindings,
      model_fallback_enabled: fallbackEnabled,
      model_fallback_bindings: fallbackBindings,
      credential_updates: Object.fromEntries(Object.entries(credentialInputs).filter(([, value]) => value.trim())),
      // Compatibility snapshot for older renderer builds. The Gateway only
      // reads ModelProfiles and role bindings.
      chat_model_presets: profiles.filter((profile) => profile.capabilities?.includes('chat')).map(({ id, label, provider, model, defaultModel, baseUrl, contextWindow }) => ({ id, label, provider, model, defaultModel, baseUrl, contextWindow })),
      active_chat_model_id: roleBindings.chat,
      llm_provider: chatProfile?.provider,
      embed_provider: embedProfile?.provider,
      telemetry_enabled: telemetryEnabled,
    });
    setSaving(false);
    setSaved(true);
    setCredentialInputs({});
    setTimeout(() => setSaved(false), 3000);
    loadSettings();
  }

  async function discoverModels(profile: ChatModelPreset, apiKey = '', silent = false) {
    const settingsBridge = getBridge('aiSettings');
    if (!settingsBridge) return;
    const generation = (modelDiscoveryGeneration.current[profile.id] || 0) + 1;
    modelDiscoveryGeneration.current[profile.id] = generation;
    setLoadingModels((current) => ({ ...current, [profile.id]: true }));
    try {
      const result = await settingsBridge.listModels(
        profile as unknown as Record<string, unknown>,
        apiKey
      );
      if (modelDiscoveryGeneration.current[profile.id] !== generation) return;
      if (result.ok && result.models.length > 0) {
        setAvailableModels((current) => ({ ...current, [profile.id]: result.models }));
        setModelProfiles((profiles) => profiles.map((candidate) =>
          candidate.id === profile.id
                ? {
                ...candidate,
                model: result.models.includes(candidate.model) ? candidate.model : result.models[0],
                defaultModel: result.models.includes(candidate.defaultModel || candidate.model)
                  ? (candidate.defaultModel || candidate.model)
                  : result.models[0],
              }
            : candidate
        ));
      }
      if (!silent || result.ok) {
        setTestResult((prev) => ({
          ...prev,
          [profile.id]: { ok: result.ok, message: result.message },
        }));
      }
    } catch (error) {
      if (modelDiscoveryGeneration.current[profile.id] !== generation) return;
      if (!silent) {
        setTestResult((current) => ({
          ...current,
          [profile.id]: {
            ok: false,
            message: error instanceof Error ? error.message : '模型列表请求失败',
          },
        }));
      }
    } finally {
      if (modelDiscoveryGeneration.current[profile.id] === generation) {
        setLoadingModels((current) => ({ ...current, [profile.id]: false }));
      }
    }
  }

  function invalidateModelDiscovery(id: string) {
    modelDiscoveryGeneration.current[id] = (modelDiscoveryGeneration.current[id] || 0) + 1;
    setLoadingModels((current) => ({ ...current, [id]: false }));
  }

  function clearProfileRuntimeState(id: string) {
    invalidateModelDiscovery(id);
    setAvailableModels((current) => ({ ...current, [id]: [] }));
    setTestResult((current) => {
      const next = { ...current };
      delete next[id];
      return next;
    });
    setProfileErrors((current) => {
      const next = { ...current };
      delete next[id];
      return next;
    });
  }

  function clearCredentialUi(id: string) {
    setCredentialInputs((current) => {
      const next = { ...current };
      delete next[id];
      return next;
    });
    setCredentialStatus((current) => ({ ...current, [id]: false }));
    setVisibleCredentialIds((current) => {
      const next = { ...current };
      delete next[id];
      return next;
    });
  }

  function updateProfile(id: string, patch: Partial<ChatModelPreset>) {
    setModelProfiles((profiles) => profiles.map((profile) => {
      if (profile.id !== id) return profile;
      const next = { ...profile, ...patch, id };
      return next;
    }));
  }

  function updateProfileBaseUrl(profile: ChatModelPreset, baseUrl: string | undefined) {
    setModelProfiles((profiles) => profiles.map((candidate) => candidate.id === profile.id
      ? {
          ...candidate,
          baseUrl,
        }
      : candidate));
    clearProfileRuntimeState(profile.id);
  }

  function updateProfileProvider(currentProfile: ChatModelPreset, provider: UserModelProvider) {
    const nextCredentialRef = modelProviderCredentialRef(provider, currentProfile.id);
    const providerDefaultsForProvider = providerDefaults(provider, currentProfile.id);
    setModelProfiles((profiles) => profiles.map((profile) => {
      if (profile.id !== currentProfile.id) return profile;
      return {
        ...profile,
        ...providerDefaultsForProvider,
        id: currentProfile.id,
        provider,
        protocol: modelProviderProtocol(provider),
        // UI-038: 切换供应商时保留用户已手选的模型/默认模型，不再清空；
        // 仅当原手选为空时回落到该渠道默认值，满足「带入默认模型」意图。
        model: profile.model || providerDefaultsForProvider.model || '',
        defaultModel: profile.defaultModel || profile.model || '',
        roles: profile.roles || [],
        parameters: profile.parameters || {},
      };
    }));
    clearProfileRuntimeState(currentProfile.id);
    if (currentProfile.provider !== 'deepseek') clearCredentialUi(credentialId(currentProfile));
    clearCredentialUi(nextCredentialRef.slice(nextCredentialRef.indexOf(':') + 1));
  }

  function addProfile() {
    const id = `model-${Date.now()}`;
    setModelProfiles((profiles) => [...profiles, {
      id,
      label: '自定义 API',
      provider: 'openai-compatible',
      model: '',
      defaultModel: '',
      ...providerDefaults('openai-compatible', id),
      roles: [],
      parameters: {},
    }]);
  }

  function removeProfile(id: string) {
    setModelProfiles((profiles) => profiles.filter((profile) => profile.id !== id));
    setRoleBindings((bindings) => Object.fromEntries(Object.entries(bindings).filter(([, value]) => value !== id)));
    setFallbackBindings((bindings) => Object.fromEntries(Object.entries(bindings).map(([role, ids]) => [role, (ids || []).filter((value) => value !== id)])));
  }

  function downloadEndpointFile(filename: string, content: string, type: string) {
    const blob = new Blob([content], { type });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = filename;
    anchor.click();
    URL.revokeObjectURL(url);
  }

  async function readCredential(id: string): Promise<string> {
    const inline = credentialInputs[id]?.trim();
    if (inline) return inline;
    // 投影桥恒 ok:false（凭据明文不过投影 HTTP）→ 返回空串走既有降级提示。
    const result = await getBridge('aiSettings')?.getCredential(id);
    return result?.ok ? result.apiKey : '';
  }

  async function revealCredential(id: string) {
    const value = await readCredential(id);
    if (!value) {
      setEndpointTransferMessage('当前渠道没有可读取的 Key，请重新填写后保存。');
      return;
    }
    setCredentialInputs((current) => ({ ...current, [id]: value }));
    setVisibleCredentialIds((current) => ({ ...current, [id]: true }));
  }

  async function copyCredential(id: string) {
    const value = await readCredential(id);
    if (!value) {
      setEndpointTransferMessage('当前渠道没有可复制的 Key，请重新填写后保存。');
      return;
    }
    await navigator.clipboard.writeText(value);
    setCopiedCredentialId(id);
    setTimeout(() => setCopiedCredentialId((current) => current === id ? null : current), 1600);
  }

  const userModelProfiles = modelProfiles.filter((profile) =>
    isUserConfigurableModelProvider(profile.provider)
  );

  async function exportEndpoints(format: 'json' | 'csv') {
    if (!getBridge('aiSettings')?.getCredential) return;
    if (!window.confirm('导出文件将包含 API Key 明文。请仅保存到安全位置，确定继续吗？')) return;
    const apiKeys: Record<string, string> = {};
    await Promise.all(userModelProfiles.map(async (profile) => {
      const value = await readCredential(credentialId(profile));
      if (value) apiKeys[profile.id] = value;
    }));
    const content = format === 'json'
      ? exportEndpointProfilesJson(userModelProfiles, apiKeys)
      : exportEndpointProfilesCsv(userModelProfiles, apiKeys);
    downloadEndpointFile(
      `petri-api-endpoints.${format}`,
      content,
      format === 'json' ? 'application/json;charset=utf-8' : 'text/csv;charset=utf-8'
    );
    setEndpointTransferMessage(`已导出 ${userModelProfiles.length} 个渠道（含 ${Object.keys(apiKeys).length} 个 Key）`);
  }

  async function importEndpoints(file: File) {
    try {
      const format = file.name.toLowerCase().endsWith('.csv') ? 'csv' : 'json';
      const parsed = parseEndpointProfiles(await file.text(), format);
      const imported = parsed.profiles;
      const importedCredentials: Record<string, string> = {};
      const changedProviderCredentialIds = new Set<string>();
      const importedProfileIds = new Set<string>();
      const next = [...modelProfilesRef.current];
      imported.forEach((item) => {
          const existingIndex = next.findIndex((profile) =>
            (item.id && profile.id === item.id) ||
            (profile.baseUrl && profile.baseUrl.replace(/\/$/, '') === item.baseUrl)
          );
          const existing = existingIndex >= 0 ? next[existingIndex] : undefined;
          const id = existing?.id || item.id || `model-${Date.now()}-${next.length}`;
          const provider = isUserConfigurableModelProvider(item.provider || '')
            ? item.provider as UserModelProvider
            : inferUserModelProvider({ label: item.supplier, baseUrl: item.baseUrl });
          const profile: ChatModelPreset = {
            ...(existing || providerDefaults(provider, id)),
            id,
            label: item.supplier,
            provider,
            protocol: modelProviderProtocol(provider),
            baseUrl: item.baseUrl,
            model: existing?.model || item.defaultModel,
            defaultModel: item.defaultModel,
            credentialRef: existing?.provider === provider && existing.credentialRef
              ? existing.credentialRef
              : modelProviderCredentialRef(provider, id),
            capabilities: existing?.capabilities || ['chat', 'streaming', 'tools'],
            roles: existing?.roles || [],
            parameters: existing?.parameters || {},
          };
          importedProfileIds.add(id);
          if (existing && existing.provider !== provider) {
            changedProviderCredentialIds.add(credentialId(existing));
            changedProviderCredentialIds.add(credentialId(profile));
          }
          if (item.apiKey) importedCredentials[credentialId(profile)] = item.apiKey;
          if (existingIndex >= 0) next[existingIndex] = profile;
          else next.push(profile);
      });
      setModelProfiles(next);
      importedProfileIds.forEach((id) => clearProfileRuntimeState(id));
      changedProviderCredentialIds.forEach((id) => clearCredentialUi(id));
      if (Object.keys(importedCredentials).length > 0) {
        setCredentialInputs((current) => ({ ...current, ...importedCredentials }));
      }
      const warning = parsed.warnings.length ? `；${parsed.warnings.join(' ')}` : '';
      setEndpointTransferMessage(`已导入 ${imported.length} 个渠道，已合并现有配置${warning}`);
    } catch (error) {
      setEndpointTransferMessage(`导入失败：${error instanceof Error ? error.message : String(error)}`);
    } finally {
      if (endpointImportRef.current) endpointImportRef.current.value = '';
    }
  }

  return {
    settings,
    setSettings,
    loadingModels,
    availableModels,
    testResult,
    saving,
    saved,
    modelProfiles,
    roleBindings,
    setRoleBindings,
    fallbackEnabled,
    setFallbackEnabled,
    fallbackBindings,
    setFallbackBindings,
    credentialInputs,
    setCredentialInputs,
    credentialStatus,
    visibleCredentialIds,
    copiedCredentialId,
    profileErrors,
    credentialBackend,
    endpointTransferMessage,
    contextWindowDrafts,
    setContextWindowDrafts,
    endpointImportRef,
    userModelProfiles,
    telemetryEnabled,
    setTelemetryEnabled,
    loadSettings,
    handleSave,
    discoverModels,
    clearProfileRuntimeState,
    updateProfile,
    updateProfileBaseUrl,
    updateProfileProvider,
    addProfile,
    removeProfile,
    revealCredential,
    copyCredential,
    exportEndpoints,
    importEndpoints,
  };
}

// ============================================================
// FolderPicker — UI-259 应用内文件夹选择器
//
// 系统目录面板对"文件共享"标记路径会禁用「打开」按钮，导致部分
// 路径无法选定。此组件经 file:list-directory IPC 在应用内直接
// 浏览文件夹：面包屑导航 + 一级子目录列表 + 「选择此文件夹」。
// 选中的路径由调用方写回各自的路径输入框（不直接创建/保存）。
// ============================================================

import React, { useCallback, useEffect, useState } from 'react';
import { Icon } from '@/components/icons/Icon';
import styles from './FolderPicker.module.css';

interface DirEntry {
  name: string;
  path: string;
}

interface ListResult {
  ok: boolean;
  data?: { path: string; parent: string | null; home: string; dirs: DirEntry[] };
  error?: string;
}

export function FolderPicker({
  initialPath,
  pickLabel = '选择此文件夹',
  onPick,
  onCancel,
}: {
  /** 初始浏览位置；空串/非法路径时回退到用户主目录 */
  initialPath?: string;
  pickLabel?: string;
  onPick: (path: string) => void;
  onCancel: () => void;
}): React.ReactElement {
  const [cur, setCur] = useState('');
  const [home, setHome] = useState('');
  const [dirs, setDirs] = useState<DirEntry[]>([]);
  const [parent, setParent] = useState<string | null>(null);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const load = useCallback(async (target: string) => {
    const list = window.petriDesktop?.files?.listDirectory;
    if (typeof list !== 'function') {
      setError('当前运行环境不支持文件夹浏览（请在 Petri 桌面应用中使用）。');
      return;
    }
    setLoading(true);
    setError('');
    try {
      const res: ListResult = await list(target);
      if (!res.ok || !res.data) {
        setError(res.error || '无法读取该文件夹');
        return;
      }
      setCur(res.data.path);
      setHome(res.data.home);
      setParent(res.data.parent);
      setDirs(res.data.dirs);
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void load(initialPath || '');
  }, [initialPath, load]);

  // 面包屑：按 / 切分累计拼接，点击跳到对应层级；home 段显示为 ~
  const segments = cur ? cur.split('/').filter(Boolean) : [];
  const crumbs: Array<{ label: string; path: string }> = [{ label: '/', path: '/' }];
  segments.forEach((seg, i) => {
    const p = '/' + segments.slice(0, i + 1).join('/');
    crumbs.push({ label: home && p === home ? '~' : seg, path: p });
  });

  return (
    <div className={styles.picker} data-testid="folder-picker">
      <div className={styles.crumbBar}>
        {crumbs.map((crumb, i) => (
          <span key={crumb.path} className={styles.crumbItem}>
            {i > 0 && <span className={styles.crumbSep}>/</span>}
            <button
              type="button"
              className={styles.crumbBtn}
              onClick={() => void load(crumb.path)}
              disabled={loading}
              title={crumb.path}
            >
              {crumb.label}
            </button>
          </span>
        ))}
        {parent && (
          <button
            type="button"
            className={styles.upBtn}
            onClick={() => parent && void load(parent)}
            disabled={loading}
            title="上一级"
            aria-label="上一级"
          >
            <Icon name="arrow-up" size={13} />
          </button>
        )}
      </div>
      {error ? (
        <p className={styles.error} role="alert">{error}</p>
      ) : (
        <ul className={styles.dirList}>
          {loading && <li className={styles.empty}>读取中…</li>}
          {!loading && dirs.length === 0 && <li className={styles.empty}>此文件夹下没有子文件夹</li>}
          {!loading && dirs.map((d) => (
            <li key={d.path}>
              <button
                type="button"
                className={styles.dirRow}
                onClick={() => void load(d.path)}
                title={d.path}
              >
                <Icon name="folder" size={14} />
                <span className={styles.dirName}>{d.name}</span>
                <Icon name="chevron-right" size={12} />
              </button>
            </li>
          ))}
        </ul>
      )}
      <div className={styles.actions}>
        <button
          type="button"
          className="petri-btn petri-btn--sm"
          onClick={() => onPick(cur)}
          disabled={loading || !cur}
          title={cur}
        >
          <Icon name="check" size={13} /> {pickLabel}
        </button>
        <button type="button" className="petri-btn petri-btn--ghost petri-btn--sm" onClick={onCancel}>
          收起
        </button>
      </div>
    </div>
  );
}

