/**
 * PluginStorePanel — 插件商店浮动面板（从左下角 dock 弹出）
 *
 * 内容与 PluginStoreModal 相同，但渲染为浮动面板而非全屏遮罩模态。
 * 左侧分类导航 + 右侧卡片网格。
 *
 * BLOCK-86 P2 (UI-374) — 商店改版：pack 卡片成为唯一领域入口——
 *   ① 独立「运行时」分类收编进包视图（运行时作为包卡片的可展开子项渲染）；
 *   ② 包卡片展开显示功能模块清单（分析插件/脚本/演示数据计数）与运行时子项
 *      （状态/体积/进度），子项安装进度走 pack:install-progress 订阅；
 *   ③ 卸载走三档确认弹层（uninstallPlan 数据源：运行时回收体积/共享保留/
 *      包源目录默认保留可选删；用户数据永不触碰）；
 *   ④ 包交付的插件在「分析工具」分类可见并标注来源包；
 *   ⑤ 「必需」提示只在「包已装而运行时缺」时出现（无包不提运行时）。
 */

import React, { useState, useCallback, useMemo } from 'react';
import { Icon } from '@/components/icons/Icon';
import { getBridge } from '@/lib/desktopBridge';
// UI-347 — 返回按钮复用定时分析面的同款样式类（工作区模式面统一返回风格）
import backStyles from '@/pages/project-workspace.module.css';
import {
  usePluginStore,
} from '@/hooks/usePluginStore';
// BLOCK-92 Wave B-5 — 类型/分类常量与领域包簇外迁（./PluginStorePanel/，纯搬运零行为变化）。
import {
  CATEGORIES,
  formatSize,
  getCategoryIcon,
  type AvailablePack,
  type CategoryId,
  type Props,
} from './PluginStorePanel/types';
import { useDomainPacks } from './PluginStorePanel/useDomainPacks';

export function PluginStorePanel({ onClose, backLabel = '返回' }: Props): React.ReactElement {
  const {
    installed,
    remote,
    runtimeStatus,
    updates,
    checkingUpdates,
    install: hookInstall,
    uninstall: hookUninstall,
    checkUpdates: hookCheckUpdates,
  } = usePluginStore();
  const [installing, setInstalling] = useState<string | null>(null);
  const [installProgress, setInstallProgress] = useState<
    Record<string, { ratio: number; received: number; total: number }>
  >({});
  const [uninstalling, setUninstalling] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [runtimeJustInstalled, setRuntimeJustInstalled] = useState<string | null>(null);
  const [activeCategory, setActiveCategory] = useState<CategoryId>('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [updatingId, setUpdatingId] = useState<string | null>(null);

  // BLOCK-92 Wave B-5 — 领域包装/卸状态簇外迁（./PluginStorePanel/useDomainPacks.ts：
  // BLOCK-84 记录制 + BLOCK-86 契约展开态 + UI-374 三档确认与运行时进度，纯搬运零行为变化）。
  const {
    availablePacks,
    installedPacks,
    packBusy,
    setPackBusy,
    setPackNotice,
    packNotice,
    expandedPackId,
    setExpandedPackId,
    packRuntimeProgress,
    setPackRuntimeProgress,
    confirmPack,
    setConfirmPack,
    confirmPlan,
    setConfirmPlan,
    confirmDeleteRuntimes,
    setConfirmDeleteRuntimes,
    confirmDeletePackSource,
    setConfirmDeletePackSource,
    refreshPacks,
    handlePackInstall,
    beginPackUninstall,
    handlePackUninstall,
    runtimeTitleOf,
    runtimeSizeLabelOf,
    packsRequiringRuntimes,
  } = useDomainPacks({ remote });

  // Use useMemo from the hook perspective: the hook already
  // memoizes via useState snapshot; useMemo only needed for
  // derived values like filteredEntries below.
  const checkForUpdates = useCallback(async () => {
    await hookCheckUpdates();
  }, [hookCheckUpdates]);

  // Updates the same way as the legacy impl — install via bridge,
  // track progress for the spinner UX, refresh on success.
  async function handleUpdate(pluginId: string) {
    const info = remote.plugins?.[pluginId];
    const isRuntime = info?.type === 'runtime';
    setUpdatingId(pluginId);
    setError(null);
    setInstallProgress((prev) => ({ ...prev, [pluginId]: { ratio: 0, received: 0, total: 0 } }));
    try {
      const result = await hookInstall(pluginId, (data) => {
        if (data) {
          setInstallProgress((prev) => ({ ...prev, [pluginId]: data }));
        }
      });
      if (result.ok) {
        if (isRuntime) setRuntimeJustInstalled(pluginId);
      } else {
        setError(result.error || '更新失败');
      }
    } catch (e) {
      setError(e instanceof Error ? e.message : '更新失败');
    } finally {
      setUpdatingId(null);
      setInstallProgress((prev) => {
        const next = { ...prev };
        delete next[pluginId];
        return next;
      });
    }
  }

  async function handleInstall(pluginId: string, isRuntime?: boolean) {
    setInstalling(pluginId);
    setInstallProgress((prev) => ({ ...prev, [pluginId]: { ratio: 0, received: 0, total: 0 } }));
    setError(null);
    try {
      const result = await hookInstall(pluginId, (data) => {
        if (data) {
          setInstallProgress((prev) => ({ ...prev, [pluginId]: data }));
        }
      });
      if (result.ok) {
        if (isRuntime) setRuntimeJustInstalled(pluginId);
      } else {
        setError(result.error || '安装失败');
      }
    } catch (e) {
      setError(e instanceof Error ? e.message : '安装失败');
    } finally {
      setInstalling(null);
      setInstallProgress((prev) => {
        const next = { ...prev };
        delete next[pluginId];
        return next;
      });
    }
  }

  async function handleUninstall(pluginId: string) {
    if (!confirm(`确定卸载 ${pluginId}？`)) return;
    setUninstalling(pluginId);
    setError(null);
    try {
      const result = await hookUninstall(pluginId);
      if (!result.ok) setError(result.error || '卸载失败');
    } catch (e) {
      setError(e instanceof Error ? e.message : '卸载失败');
    } finally {
      setUninstalling(null);
    }
  }

  const remotePlugins = remote.plugins || {};
  const remoteEntries = Object.entries(remotePlugins);
  const installedIds = new Set(installed.map((p) => p.id));
  const installedById = new Map(installed.map((p) => [p.id, p]));
  const driftedIds = new Set(installed.filter((p) => p.manifestDrift).map((p) => p.id));
  const updateMap = new Map(updates.map((u) => [u.id, u]));
  const hasUpdates = updates.length > 0;

  const rRuntimeInstalled = runtimeStatus
    ? runtimeStatus.r.installed
    : installedIds.has('petri-r-runtime');
  const pyRuntimeInstalled = runtimeStatus
    ? runtimeStatus.python.installed
    : installedIds.has('petri-py-runtime');
  // UI-374 — 缺失提示领域感知：只在「包已装而运行时缺」时出现（无包不提运行时），
  // 文案挂包名。runtimeStatus 为 null（检测未知）时维持既有语义：不提示。
  // packsRequiringRuntimes 已随 useDomainPacks 外迁。
  const missingRuntimeNames = runtimeStatus
    ? [
        !runtimeStatus.r.installed ? 'R' : null,
        !runtimeStatus.python.installed ? 'Python' : null,
      ].filter((v): v is string => Boolean(v))
    : [];
  const needRuntimeHint = missingRuntimeNames.length > 0 && packsRequiringRuntimes.length > 0;

  const categoryCounts = useMemo(() => {
    const counts: Record<CategoryId, number> = { all: 0, tool: 0 };
    for (const [id, info] of remoteEntries) {
      counts.all++;
      for (const cat of CATEGORIES) {
        if (cat.id !== 'all' && cat.filter(id, info)) counts[cat.id]++;
      }
    }
    return counts;
  }, [remoteEntries]);

  const filteredEntries = useMemo(() => {
    const cat = CATEGORIES.find((c) => c.id === activeCategory);
    if (!cat) return [];
    const q = searchQuery.trim().toLowerCase();
    return remoteEntries.filter(([id, info]) => {
      if (!cat.filter(id, info)) return false;
      if (q) {
        const title = (info.title || id).toLowerCase();
        const desc = (info.description || '').toLowerCase();
        if (!title.includes(q) && !desc.includes(q) && !id.toLowerCase().includes(q)) return false;
      }
      return true;
    });
  }, [remoteEntries, activeCategory, searchQuery]);

  // UI-374 — 包交付的插件（已装包），在「分析工具」分类可见并标注来源包
  const packDeliveredPlugins = useMemo(() => {
    const q = searchQuery.trim().toLowerCase();
    const rows: Array<{ id: string; language: string | null; version: string | null; fromPack: string }> = [];
    for (const pack of installedPacks) {
      for (const plugin of pack.contents?.plugins ?? []) {
        if (q) {
          const hit = plugin.id.toLowerCase().includes(q);
          if (!hit) continue;
        }
        rows.push({ ...plugin, fromPack: pack.name || pack.packId });
      }
    }
    return rows;
  }, [installedPacks, searchQuery]);

  const installedCount = installed.length;
  const availableCount = remoteEntries.filter(([id]) => !installedIds.has(id)).length;

  function isPluginInstalled(pluginId: string): boolean {
    if (pluginId === 'petri-r-runtime') return rRuntimeInstalled;
    if (pluginId === 'petri-py-runtime') return pyRuntimeInstalled;
    return installedIds.has(pluginId);
  }

  // UI-374 — 运行时在位判定：安装记录不可信（运行时可由链外供给——手动放置/
  // 系统解析，plugin installed.json 里没有记录），以 runtimeStatus 的目录+
  // 可执行探测为准，经清单 language 映射。
  function isRuntimePresent(pluginId: string): boolean {
    const info = remote.plugins?.[pluginId];
    if (runtimeStatus) {
      if (info?.language === 'r') return runtimeStatus.r.installed;
      if (info?.language === 'python') return runtimeStatus.python.installed;
    }
    return installedIds.has(pluginId);
  }

  function isPluginDrifted(pluginId: string): boolean {
    if (pluginId === 'petri-r-runtime' || pluginId === 'petri-py-runtime') {
      return !!installedById.get(pluginId)?.manifestDrift;
    }
    return driftedIds.has(pluginId);
  }

  return (
    <div
      className="petri-desktop-panel petri-plugin-store-panel"
      role="dialog"
      aria-label="插件商店"
    >
      {/* Header */}
      <div className="petri-plugin-store__header">
        {/* UI-347 — 返回风格与其它页面对齐（定时分析面同款左上角文字按钮，
            替代原右上角 × 关闭） */}
        <button
          type="button"
          className={backStyles.scheduledWorkspaceBack}
          onClick={onClose}
          title={backLabel}
          aria-label={backLabel}
        >
          <Icon name="arrow-left" size={14} />
          <span>{backLabel}</span>
        </button>
        <span className="petri-plugin-store__icon">
          <Icon name="puzzle" size={18} />
        </span>
        <h2 className="petri-plugin-store__title">插件商店</h2>
        <div className="petri-plugin-store__search">
          <input
            type="text"
            placeholder="搜索插件…"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>
      </div>

      {/* Body: sidebar + content */}
      <div className="petri-plugin-store__body">
        {/* Sidebar */}
        <nav className="petri-plugin-store__sidebar">
          {CATEGORIES.map((cat) => (
            <button
              key={cat.id}
              type="button"
              className={`petri-plugin-store__nav-item ${activeCategory === cat.id ? 'active' : ''}`}
              onClick={() => setActiveCategory(cat.id)}
            >
              <Icon name={cat.icon} size={16} />
              <span className="petri-plugin-store__nav-label">{cat.label}</span>
              <span className="petri-plugin-store__nav-count">{categoryCounts[cat.id]}</span>
            </button>
          ))}
        </nav>

        {/* Content */}
        <div className="petri-plugin-store__content">
          {error && (
            <div
              className="petri-field__result petri-field__result--err"
              style={{ marginBottom: 14 }}
            >
              ✗ {error}
            </div>
          )}

          {runtimeJustInstalled && (
            <div
              className="petri-field__result petri-field__result--ok"
              style={{ marginBottom: 14 }}
            >
              ✓ {runtimeJustInstalled} 安装成功，<strong>重启应用后生效</strong>。
            </div>
          )}

          {/* UI-374 — 有包缺运行时才提示，且文案挂包名；无包不提运行时 */}
          {needRuntimeHint && (
            <div className="petri-plugin-store__hint">
              ⚠️ 已安装领域包 {packsRequiringRuntimes.map((n) => `「${n}」`).join('、')} 需要
              {' '}{missingRuntimeNames.join(' 与 ')} 运行时——请在本页领域包卡片内补装，否则对应分析工具无法使用。
            </div>
          )}

          {/* BLOCK-84：领域包分区——整包一键装/卸（记录制，重启生效）
              UI-374：pack 卡片 = 唯一领域入口（运行时子项收编进卡片） */}
          {(availablePacks.length > 0 || installedPacks.length > 0) && (activeCategory === 'all') && (
            <div className="petri-plugin-store__packs" data-testid="domain-packs-section">
              <div className="petri-plugin-store__packs-header">
                <strong>领域包</strong>
                <span style={{ fontSize: 'var(--petri-font-size-caption, 12px)', color: 'var(--petri-text-tertiary)' }}>
                  整包安装/卸载一组领域能力（分析插件 + 脚本 + 运行时）；装/卸后需重启应用生效
                </span>
              </div>
              {packNotice && (
                <div role="status" style={{ padding: '6px 0', color: 'var(--petri-text-secondary)' }}>{packNotice}</div>
              )}
              {(() => {
                const packBridge = getBridge('packs');
                return packBridge ? (
                  <button
                    type="button"
                    className="petri-btn petri-btn--primary"
                    style={{ marginBottom: 8 }}
                    disabled={packBusy !== null}
                    onClick={async () => {
                      setPackBusy('__dialog__');
                      setPackNotice(null);
                      setPackRuntimeProgress({});
                      try {
                        const result = await packBridge.installFromDialog();
                        if (result?.canceled) return;
                        if (result?.ok) setPackNotice('已安装——重启应用后生效');
                        else if (result?.error) setPackNotice(`安装失败：${result.error}`);
                        await refreshPacks();
                      } finally {
                        setPackBusy(null);
                        setPackRuntimeProgress({});
                      }
                    }}
                  >
                    从目录安装领域包…
                  </button>
                ) : null;
              })()}
              {(() => {
                const knownById = new Map<string, AvailablePack>();
                for (const p of availablePacks) knownById.set(p.packId, p);
                for (const p of installedPacks) {
                  if (!knownById.has(p.packId)) {
                    knownById.set(p.packId, {
                      packId: p.packId, name: p.name || p.packId, version: p.version,
                      description: '', packRoot: p.packRoot, installed: true,
                      requiresRuntimes: p.requiresRuntimes,
                      contents: p.contents,
                    });
                  }
                }
                return [...knownById.values()].map((pack) => {
                  const expanded = expandedPackId === pack.packId;
                  const requiredRuntimes = pack.requiresRuntimes ?? [];
                  const contents = pack.contents;
                  return (
                    <div
                      key={pack.packId}
                      className="petri-plugin-store__pack-card"
                      data-testid={`domain-pack-${pack.packId}`}
                      style={{ border: '1px solid var(--petri-border, rgba(128,128,128,0.25))', borderRadius: 8, marginBottom: 8 }}
                    >
                      <div style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '10px 12px' }}>
                        <button
                          type="button"
                          aria-expanded={expanded}
                          aria-label={expanded ? `收起 ${pack.name} 详情` : `展开 ${pack.name} 详情`}
                          onClick={() => setExpandedPackId(expanded ? null : pack.packId)}
                          style={{ background: 'none', border: 'none', cursor: 'pointer', padding: 4, color: 'var(--petri-text-tertiary)', display: 'flex' }}
                        >
                          <Icon name={expanded ? 'chevron-up' : 'chevron-down'} size={14} />
                        </button>
                        <div style={{ flex: 1, minWidth: 0 }}>
                          <div style={{ fontWeight: 600 }}>
                            {pack.name} <span style={{ color: 'var(--petri-text-tertiary)', fontWeight: 400 }}>v{pack.version}</span>
                            {pack.installed && (
                              <span style={{ marginLeft: 8, fontSize: 'var(--petri-font-size-caption, 12px)', color: 'var(--petri-accent, #3b82f6)' }}>已安装</span>
                            )}
                          </div>
                          <div style={{ color: 'var(--petri-text-tertiary)', fontSize: 'var(--petri-font-size-caption, 12px)' }}>
                            {contents
                              ? `${contents.pluginCount} 个分析插件 · ${contents.scriptCount} 个脚本模块 · ${contents.demoDataCount} 个演示数据集`
                              : (pack.description || pack.packId)}
                          </div>
                        </div>
                        {pack.installed ? (
                          <button
                            type="button"
                            className="petri-btn"
                            disabled={packBusy !== null}
                            onClick={() => void beginPackUninstall(pack)}
                          >
                            {packBusy === pack.packId ? '处理中…' : '卸载'}
                          </button>
                        ) : (
                          <button
                            type="button"
                            className="petri-btn petri-btn--primary"
                            disabled={packBusy !== null}
                            onClick={() => void handlePackInstall(pack)}
                          >
                            {packBusy === pack.packId ? '处理中…' : '一键安装'}
                          </button>
                        )}
                      </div>
                      {/* UI-374 — 展开区：运行时子项（状态/体积/进度）随契约渲染 */}
                      {expanded && requiredRuntimes.length > 0 && (
                        <div style={{ borderTop: '1px dashed var(--petri-border, rgba(128,128,128,0.25))', padding: '8px 12px 10px 36px' }} data-testid={`pack-runtimes-${pack.packId}`}>
                          <div style={{ fontSize: 'var(--petri-font-size-caption, 12px)', color: 'var(--petri-text-tertiary)', marginBottom: 6 }}>
                            运行时基础环境（随包安装）
                          </div>
                          {requiredRuntimes.map((req) => {
                            const rtInstalled = isRuntimePresent(req.pluginId);
                            const sizeLabel = runtimeSizeLabelOf(req.pluginId);
                            const prog = pack.installed
                              ? packRuntimeProgress[req.pluginId]
                              : undefined;
                            const missingButRequired = pack.installed && !rtInstalled;
                            return (
                              <div key={req.pluginId} style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '4px 0' }}>
                                <Icon name="cpu" size={14} />
                                <span style={{ flex: 1, minWidth: 0 }}>
                                  {runtimeTitleOf(req.pluginId)}
                                  <span style={{ color: 'var(--petri-text-tertiary)', marginLeft: 8, fontSize: 'var(--petri-font-size-caption, 12px)' }}>
                                    {sizeLabel}
                                    {req.version ? ` · ${req.version}` : ''}
                                  </span>
                                  {rtInstalled && (
                                    <span style={{ color: 'var(--petri-text-tertiary)', marginLeft: 8, fontSize: 'var(--petri-font-size-caption, 12px)' }}>✓ 已安装</span>
                                  )}
                                  {missingButRequired && (
                                    <span style={{ color: 'var(--petri-warning, #d97706)', marginLeft: 8, fontSize: 'var(--petri-font-size-caption, 12px)' }}>
                                      必需 · 缺失
                                    </span>
                                  )}
                                </span>
                                {pack.installed && !rtInstalled && (
                                  <button
                                    type="button"
                                    className="petri-btn petri-btn--primary petri-btn--sm"
                                    disabled={installing === req.pluginId}
                                    onClick={() => void handleInstall(req.pluginId, true)}
                                  >
                                    {installing === req.pluginId ? '安装中…' : '补装'}
                                  </button>
                                )}
                                {pack.installed && !rtInstalled && prog && prog.total > 0 && (
                                  <div className="petri-plugin-store__progress" style={{ width: 120 }}>
                                    <div className="petri-plugin-store__progress-text">
                                      {(prog.ratio * 100).toFixed(0)}%
                                    </div>
                                    <div className="petri-plugin-store__progress-bar">
                                      <div style={{ width: `${prog.ratio * 100}%` }} />
                                    </div>
                                  </div>
                                )}
                              </div>
                            );
                          })}
                        </div>
                      )}
                    </div>
                  );
                });
              })()}
            </div>
          )}

          {/* UI-374 — 卸载三档确认弹层（uninstallPlan 契约推导数据源） */}
          {confirmPack && confirmPlan && (
            <div
              role="dialog"
              aria-label="确认卸载领域包"
              data-testid="pack-uninstall-confirm"
              style={{
                position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.35)',
                display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 10,
              }}
            >
              <div style={{
                background: 'var(--petri-bg, #fff)', borderRadius: 10, padding: 18,
                width: 'min(520px, 92%)', border: '1px solid var(--petri-border, rgba(128,128,128,0.25))',
                boxShadow: '0 12px 32px rgba(15,23,42,0.18)',
              }}>
                <div style={{ fontWeight: 600, marginBottom: 8 }}>卸载「{confirmPack.name}」</div>
                <div style={{ fontSize: 'var(--petri-font-size-caption, 12px)', color: 'var(--petri-text-secondary)', marginBottom: 10 }}>
                  卸载后需重启应用生效。请确认以下处置（可逐项勾选）：
                </div>
                <label style={{ display: 'flex', gap: 8, alignItems: 'flex-start', padding: '6px 0', cursor: 'pointer' }}>
                  <input
                    type="checkbox"
                    checked={confirmDeleteRuntimes}
                    onChange={(e) => setConfirmDeleteRuntimes(e.target.checked)}
                  />
                  <span>
                    删除运行时基础环境
                    {(confirmPlan.runtimes?.removable ?? []).filter((r) => r.installed).length > 0 && (
                      <span style={{ color: 'var(--petri-text-tertiary)' }}>
                        （{confirmPlan.runtimes!.removable.filter((r) => r.installed).map((r) => runtimeTitleOf(r.pluginId)).join('、')}
                        {(() => {
                          const total = confirmPlan.runtimes!.removable.reduce((acc, r) => acc + (r.sizeBytes || 0), 0);
                          const label = formatSize(total);
                          return label ? `，约回收 ${label}` : '';
                        })()}
                        ）
                      </span>
                    )}
                    {(confirmPlan.runtimes?.removable ?? []).length === 0 && (
                      <span style={{ color: 'var(--petri-text-tertiary)' }}>（本包契约未声明运行时）</span>
                    )}
                    {(confirmPlan.runtimes?.retained ?? []).length > 0 && (
                      <span style={{ color: 'var(--petri-text-tertiary)' }}>
                        ；{confirmPlan.runtimes!.retained.map((r) => `${runtimeTitleOf(r.pluginId)} 被其他包共享，将保留`).join('；')}
                      </span>
                    )}
                  </span>
                </label>
                <label style={{ display: 'flex', gap: 8, alignItems: 'flex-start', padding: '6px 0', cursor: 'pointer' }}>
                  <input
                    type="checkbox"
                    checked={confirmDeletePackSource}
                    onChange={(e) => setConfirmDeletePackSource(e.target.checked)}
                  />
                  <span>
                    同时删除包源目录
                    {confirmPlan.packSource?.dir && (
                      <span style={{ color: 'var(--petri-text-tertiary)', wordBreak: 'break-all' }}>
                        （{confirmPlan.packSource.dir}
                        {confirmPlan.packSource.sizeBytes ? `，约 ${formatSize(confirmPlan.packSource.sizeBytes)}` : ''}）
                      </span>
                    )}
                    <div style={{ color: 'var(--petri-text-tertiary)' }}>内含分析插件、脚本与演示数据；默认保留</div>
                  </span>
                </label>
                <div style={{ padding: '8px 0', color: 'var(--petri-text-secondary)', fontSize: 'var(--petri-font-size-caption, 12px)' }}>
                  {confirmPlan.userDataPolicy || 'results、项目文件与数据库不受影响'}——用户数据永不删除。
                </div>
                <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 8 }}>
                  <button
                    type="button"
                    className="petri-btn"
                    onClick={() => { setConfirmPack(null); setConfirmPlan(null); }}
                  >
                    取消
                  </button>
                  <button
                    type="button"
                    className="petri-btn petri-btn--danger-ghost"
                    disabled={packBusy !== null}
                    data-testid="pack-uninstall-confirm-execute"
                    onClick={async () => {
                      const pack = confirmPack;
                      const options = { deleteRuntimes: confirmDeleteRuntimes, deletePackSource: confirmDeletePackSource };
                      setConfirmPack(null);
                      setConfirmPlan(null);
                      if (pack) await handlePackUninstall(pack, options);
                    }}
                  >
                    确认卸载
                  </button>
                </div>
              </div>
            </div>
          )}

          {filteredEntries.length === 0 && packDeliveredPlugins.length === 0 && !error && (
            <div className="petri-empty">
              {searchQuery ? `没有匹配「${searchQuery}」的插件` : '此分类暂无插件'}
            </div>
          )}

          {/* 非 Runtime 插件用卡片网格（UI-374：运行时不再单独渲染，收编进包卡片） */}
          {(() => {
            const cardEntries = filteredEntries.filter(([, info]) => info.type !== 'runtime');
            if (cardEntries.length === 0) return null;
            return (
              <div className="petri-plugin-store__grid">
                {cardEntries.map(([id, info]) => {
                  const isInstalled = isPluginInstalled(id);
                  const isInstalling = installing === id;
                  const isUpdating = updatingId === id;
                  const prog = installProgress[id];
                  const hasUpdate = updateMap.has(id);
                  return (
                    <div
                      key={id}
                      className={`petri-plugin-card ${isInstalled ? 'installed' : ''} ${hasUpdate ? 'has-update' : ''}`}
                    >
                      <div className="petri-plugin-card__top">
                        <span className="petri-plugin-card__icon">
                          <Icon name={getCategoryIcon(info)} size={20} />
                        </span>
                        <div className="petri-plugin-card__name" title={info.title || id}>
                          {info.title || id}
                        </div>
                        {isInstalled && <span className="petri-plugin-card__badge">✓</span>}
                        {isInstalled && isPluginDrifted(id) && (
                          <span
                            className="petri-plugin-card__badge-drift"
                            title="安装后脚本或清单已发生变化"
                          >
                            已变更
                          </span>
                        )}
                        {hasUpdate && (
                          <span
                            className="petri-plugin-card__badge-update"
                            title={`有新版本 v${updateMap.get(id)!.latestVersion}`}
                          >
                            ↑
                          </span>
                        )}
                      </div>
                      <div className="petri-plugin-card__desc" title={info.description}>
                        {info.description || '—'}
                      </div>
                      <div className="petri-plugin-card__meta">
                        {info.version && <span>v{info.version}</span>}
                        {info.language && (
                          <span className={`lang-${info.language}`}>{info.language}</span>
                        )}
                        {info.size ? <span>{formatSize(info.size)}</span> : <span>—</span>}
                        {info.type === 'data' && <span className="tag-data">数据包</span>}
                        {info.optional && <span className="tag-optional">可选</span>}
                      </div>
                      <div className="petri-plugin-card__action">
                        {isInstalled ? (
                          <div className="petri-plugin-store__action-stack">
                            {hasUpdate && (
                              <button
                                type="button"
                                className="petri-btn petri-btn--primary petri-btn--sm"
                                onClick={() => handleUpdate(id)}
                                disabled={isUpdating}
                              >
                                {isUpdating ? '更新中…' : '更新'}
                              </button>
                            )}
                            {(isUpdating || isInstalling) && prog && prog.total > 0 && (
                              <div className="petri-plugin-store__progress">
                                <div className="petri-plugin-store__progress-text">
                                  {(prog.ratio * 100).toFixed(0)}% ·{' '}
                                  {(prog.received / 1024 / 1024).toFixed(0)}/
                                  {(prog.total / 1024 / 1024).toFixed(0)}MB
                                </div>
                                <div className="petri-plugin-store__progress-bar">
                                  <div style={{ width: `${prog.ratio * 100}%` }} />
                                </div>
                              </div>
                            )}
                            <button
                              type="button"
                              className="petri-btn petri-btn--danger-ghost petri-btn--sm"
                              onClick={() => handleUninstall(id)}
                              disabled={uninstalling === id}
                            >
                              {uninstalling === id ? '卸载中…' : '卸载'}
                            </button>
                          </div>
                        ) : isInstalling && prog && prog.total > 0 ? (
                          <div className="petri-plugin-store__progress">
                            <div className="petri-plugin-store__progress-text">
                              {(prog.ratio * 100).toFixed(0)}% ·{' '}
                              {(prog.received / 1024 / 1024).toFixed(0)}/
                              {(prog.total / 1024 / 1024).toFixed(0)}MB
                            </div>
                            <div className="petri-plugin-store__progress-bar">
                              <div style={{ width: `${prog.ratio * 100}%` }} />
                            </div>
                          </div>
                        ) : (
                          <button
                            type="button"
                            className="petri-btn petri-btn--primary petri-btn--sm"
                            onClick={() => handleInstall(id)}
                            disabled={isInstalling}
                          >
                            {isInstalling ? '安装中…' : '安装'}
                          </button>
                        )}
                      </div>
                    </div>
                  );
                })}
              </div>
            );
          })()}

          {/* UI-374 — 包交付的插件：标注来源包，随包装卸（无独立安装按钮） */}
          {packDeliveredPlugins.length > 0 && (
            <div style={{ marginTop: 14 }} data-testid="pack-delivered-plugins">
              <div style={{ fontSize: 'var(--petri-font-size-caption, 12px)', color: 'var(--petri-text-tertiary)', marginBottom: 6 }}>
                来自已安装领域包（随包装卸，重启生效）
              </div>
              <div className="petri-plugin-store__grid">
                {packDeliveredPlugins.map((plugin) => (
                  <div key={`${plugin.fromPack}:${plugin.id}`} className="petri-plugin-card installed">
                    <div className="petri-plugin-card__top">
                      <span className="petri-plugin-card__icon">
                        <Icon name="bar-chart" size={20} />
                      </span>
                      <div className="petri-plugin-card__name" title={plugin.id}>
                        {plugin.id}
                      </div>
                      <span className="petri-plugin-card__badge">✓</span>
                    </div>
                    <div className="petri-plugin-card__desc">来源包：{plugin.fromPack}</div>
                    <div className="petri-plugin-card__meta">
                      {plugin.version && <span>v{plugin.version}</span>}
                      {plugin.language && (
                        <span className={`lang-${plugin.language}`}>{plugin.language}</span>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Footer */}
      <div className="petri-plugin-store__footer">
        <span className="petri-plugin-store__footer-info">
          已安装 {installedCount} 个 · 可安装 {availableCount} 个
          {hasUpdates && (
            <span className="petri-plugin-store__footer-updates">
              {' · '}
              <button
                type="button"
                className="petri-plugin-store__refresh-btn"
                onClick={checkForUpdates}
                disabled={checkingUpdates}
              >
                {checkingUpdates ? '检查中…' : `${updates.length} 个可更新`}
              </button>
            </span>
          )}
        </span>
      </div>
    </div>
  );
}

export default PluginStorePanel;

import { useCallback, useEffect, useState } from 'react';
import type { Dispatch, SetStateAction } from 'react';
import { getBridge } from '@/lib/desktopBridge';
import type { RemotePlugin } from '@/hooks/usePluginStore';
import { formatSize, type AvailablePack, type InstalledPack, type UninstallPlan } from './types';

// BLOCK-92 Wave B-5 — 领域包装/卸状态簇外迁（原 PluginStorePanel.tsx 内联，纯搬运零行为变化）。
// BLOCK-84 记录制装/卸 + BLOCK-86 P1/P2 契约与展开态 + UI-374 三档卸载确认与运行时进度。

interface UseDomainPacksOptions {
  /** 运行时标题/体积查询源（usePluginStore 的 remote 清单）。 */
  remote: { plugins?: Record<string, RemotePlugin> };
}

export function useDomainPacks(options: UseDomainPacksOptions): {
  availablePacks: AvailablePack[];
  installedPacks: InstalledPack[];
  packBusy: string | null;
  setPackBusy: (busy: string | null) => void;
  setPackNotice: (notice: string | null) => void;
  packNotice: string | null;
  expandedPackId: string | null;
  setExpandedPackId: (id: string | null) => void;
  packRuntimeProgress: Record<string, { ratio: number; received: number; total: number }>;
  setPackRuntimeProgress: Dispatch<SetStateAction<Record<string, { ratio: number; received: number; total: number }>>>;
  confirmPack: AvailablePack | null;
  setConfirmPack: (pack: AvailablePack | null) => void;
  confirmPlan: UninstallPlan | null;
  setConfirmPlan: (plan: UninstallPlan | null) => void;
  confirmDeleteRuntimes: boolean;
  setConfirmDeleteRuntimes: (next: boolean) => void;
  confirmDeletePackSource: boolean;
  setConfirmDeletePackSource: (next: boolean) => void;
  refreshPacks: () => Promise<void>;
  handlePackInstall: (pack: AvailablePack) => Promise<void>;
  beginPackUninstall: (pack: AvailablePack) => Promise<void>;
  handlePackUninstall: (pack: AvailablePack, options: { deleteRuntimes?: boolean; deletePackSource?: boolean }) => Promise<void>;
  runtimeTitleOf: (pluginId: string) => string;
  runtimeSizeLabelOf: (pluginId: string) => string;
  packsRequiringRuntimes: string[];
} {
  const { remote } = options;
  // BLOCK-84：领域包
  const [availablePacks, setAvailablePacks] = useState<AvailablePack[]>([]);
  const [installedPacks, setInstalledPacks] = useState<InstalledPack[]>([]);
  const [packBusy, setPackBusy] = useState<string | null>(null);
  const [packNotice, setPackNotice] = useState<string | null>(null);
  // UI-374 — 包卡片展开态 + 包安装的运行时进度（pack:install-progress）+ 卸载三档确认
  const [expandedPackId, setExpandedPackId] = useState<string | null>(null);
  const [packRuntimeProgress, setPackRuntimeProgress] = useState<
    Record<string, { ratio: number; received: number; total: number }>
  >({});
  const [confirmPack, setConfirmPack] = useState<AvailablePack | null>(null);
  const [confirmPlan, setConfirmPlan] = useState<UninstallPlan | null>(null);
  const [confirmDeleteRuntimes, setConfirmDeleteRuntimes] = useState(true);
  const [confirmDeletePackSource, setConfirmDeletePackSource] = useState(false);

  // IPC 契约（src/ipc/pack.js）：list-installed / list-available 统一返回
  // `{ ok, packs: [...] }`，不是裸数组。早期实现按裸数组解包，导致 state 被塞进
  // 一个普通对象（.length === undefined），`length > 0` 恒为 false，
  // 「领域包」分区因此永不渲染——数据链路全通却看不见卡片（P2 实机抓真）。
  const unpackPacks = <T,>(payload: unknown): T[] => {
    if (Array.isArray(payload)) return payload as T[];
    const env = payload as { ok?: boolean; packs?: T[] } | null;
    return env && Array.isArray(env.packs) ? env.packs : [];
  };

  const refreshPacks = useCallback(async () => {
    try {
      // BLOCK-87 L4-2：桥解析走 getBridge 单点——桌面=IPC 桥，投影=gateway
      // HTTP 桥（手机端领域包/运行时与桌面同源）；普通 web 无桥返回 null。
      // 直接读 window.petriDesktop 在投影下拿到的是垫片 Proxy（解析为
      // undefined），曾是手机端领域包分区空白的根因之一。
      const bridge = getBridge('packs');
      if (!bridge) return;
      const [inst, avail] = await Promise.all([bridge.listInstalled(), bridge.listAvailable()]);
      setInstalledPacks(unpackPacks<InstalledPack>(inst));
      setAvailablePacks(unpackPacks<AvailablePack>(avail));
    } catch {
      // 桥缺失（web shim）时整区不渲染，由 availablePacks 空态兜底
    }
  }, []);

  useEffect(() => { void refreshPacks(); }, [refreshPacks]);

  // UI-374 — 包安装的运行时下载进度（主进程 → pack:install-progress → 这里）
  useEffect(() => {
    const bridge = getBridge('packs');
    if (!bridge?.onInstallProgress) return undefined;
    return bridge.onInstallProgress((payload) => {
      setPackRuntimeProgress((prev) => ({ ...prev, [payload.pluginId]: payload.progress }));
    });
  }, []);

  function runtimeTitleOf(pluginId: string): string {
    const info = remote.plugins?.[pluginId];
    return info?.title || pluginId;
  }

  function runtimeSizeLabelOf(pluginId: string): string {
    const size = remote.plugins?.[pluginId]?.size;
    const label = formatSize(size);
    return label ? `约 ${label}` : '';
  }

  async function handlePackInstall(pack: AvailablePack) {
    setPackBusy(pack.packId);
    setPackNotice(null);
    setPackRuntimeProgress({});
    try {
      const result = await getBridge('packs')?.installPath(pack.packRoot);
      if (result?.ok) {
        const runtimeResults = result.runtimes ?? [];
        const failed = runtimeResults.filter((r) => !r.ok);
        const installedNow = runtimeResults.filter((r) => r.ok && !r.skipped);
        let notice = `「${pack.name}」已安装`;
        if (installedNow.length > 0) {
          notice += `；运行时 ${installedNow.map((r) => runtimeTitleOf(r.pluginId)).join('、')} 已就绪`;
        }
        if (failed.length > 0) {
          notice += `；运行时 ${failed.map((r) => runtimeTitleOf(r.pluginId)).join('、')} 安装失败（${failed.map((r) => r.error || '未知错误').join('；')}），可稍后在包卡片内补装`;
        }
        setPackNotice(`${notice}——重启应用后生效`);
      } else {
        setPackNotice(`安装失败：${result?.error ?? '未知错误'}`);
      }
      await refreshPacks();
      setExpandedPackId(pack.packId);
    } finally {
      setPackBusy(null);
      setPackRuntimeProgress({});
    }
  }

  // UI-374 — 卸载两段式：先取契约推导的影响预览（三档数据源），确认后执行
  async function beginPackUninstall(pack: AvailablePack) {
    setPackNotice(null);
    const bridge = getBridge('packs');
    if (!bridge?.uninstallPlan) {
      // 投影桥（HTTP）未提供 plan 通道：退化为直接卸载（记录级，零破坏性）
      await handlePackUninstall(pack, {});
      return;
    }
    const plan = await bridge.uninstallPlan(pack.packId);
    if (!plan?.ok) {
      setPackNotice(`获取卸载方案失败：${plan?.error ?? '未知错误'}`);
      return;
    }
    setConfirmDeleteRuntimes(true);
    setConfirmDeletePackSource(false);
    setConfirmPlan(plan);
    setConfirmPack(pack);
  }

  async function handlePackUninstall(pack: AvailablePack, options: { deleteRuntimes?: boolean; deletePackSource?: boolean }) {
    setPackBusy(pack.packId);
    setPackNotice(null);
    try {
      const result = await getBridge('packs')?.uninstall(pack.packId, options);
      if (result?.ok) {
        const removedRuntimeTitles = (result.removed?.runtimes ?? [])
          .filter((r) => r.ok && !r.skipped)
          .map((r) => runtimeTitleOf(r.pluginId));
        const keptDir = result.kept?.packSourceDir;
        let notice = `「${pack.name}」已卸载`;
        if (removedRuntimeTitles.length > 0) {
          notice += `；已释放运行时 ${removedRuntimeTitles.join('、')}`;
        }
        if (result.removed?.packSourceDir) {
          notice += '；包源目录已删除';
        } else if (keptDir) {
          notice += `；包源目录保留在 ${keptDir}`;
        }
        setPackNotice(`${notice}——重启应用后回到纯通用态`);
      } else {
        setPackNotice(`卸载失败：${result?.error ?? '未知错误'}`);
      }
      await refreshPacks();
    } finally {
      setPackBusy(null);
    }
  }

  // UI-374 — 缺失提示领域感知：只在「包已装而运行时缺」时出现（无包不提运行时），
  // 文案挂包名。runtimeStatus 为 null（检测未知）时维持既有语义：不提示。
  const packsRequiringRuntimes = (() => {
    const byId = new Map<string, string>();
    for (const p of [...installedPacks, ...availablePacks.map(({ packId, name }) => ({ packId, name }))] as Array<{ packId: string; name?: string }>) {
      if (!byId.has(p.packId)) byId.set(p.packId, p.name || p.packId);
    }
    return installedPacks
      .filter((p) => Array.isArray(p.requiresRuntimes) && p.requiresRuntimes.length > 0)
      .map((p) => byId.get(p.packId) || p.packId);
  })();

  return {
    availablePacks,
    installedPacks,
    packBusy,
    setPackBusy,
    setPackNotice,
    packNotice,
    expandedPackId,
    setExpandedPackId,
    packRuntimeProgress,
    setPackRuntimeProgress,
    confirmPack,
    setConfirmPack,
    confirmPlan,
    setConfirmPlan,
    confirmDeleteRuntimes,
    setConfirmDeleteRuntimes,
    confirmDeletePackSource,
    setConfirmDeletePackSource,
    refreshPacks,
    handlePackInstall,
    beginPackUninstall,
    handlePackUninstall,
    runtimeTitleOf,
    runtimeSizeLabelOf,
    packsRequiringRuntimes,
  };
}

import React, { useCallback, useEffect, useRef, useState } from 'react';
import { Icon, type IconName } from '@/components/icons/Icon';
import { type ThemePreference, useTheme } from '@/themes/ThemeProvider';
import './theme-control.css';

const options: Array<{ value: ThemePreference; label: string; icon: IconName }> = [
  { value: 'system', label: '跟随系统', icon: 'cpu' },
  { value: 'light', label: '日间模式', icon: 'sun' },
  { value: 'dark', label: '夜间模式', icon: 'moon' },
];

export function ThemeControl({
  compact = false,
  menuPlacement = 'top',
}: {
  compact?: boolean;
  menuPlacement?: 'top' | 'bottom';
}): React.ReactElement {
  const { preference, resolvedTheme, setPreference } = useTheme();
  const [open, setOpen] = useState(false);
  const rootRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const optionRefs = useRef<Array<HTMLButtonElement | null>>([]);
  const current = options.find((option) => option.value === preference) || options[0];

  const close = useCallback(() => {
    setOpen(false);
    triggerRef.current?.focus();
  }, []);

  useEffect(() => {
    if (!open) return;
    const onPointerDown = (event: MouseEvent) => {
      if (!rootRef.current?.contains(event.target as Node)) setOpen(false);
    };
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        event.preventDefault();
        close();
      }
    };
    window.addEventListener('mousedown', onPointerDown);
    document.addEventListener('keydown', onKeyDown);
    return () => {
      window.removeEventListener('mousedown', onPointerDown);
      document.removeEventListener('keydown', onKeyDown);
    };
  }, [open, close]);

  // Move focus into the menu on open (to the active/checked option).
  useEffect(() => {
    if (!open) return;
    const activeIndex = options.findIndex((option) => option.value === preference);
    optionRefs.current[activeIndex === -1 ? 0 : activeIndex]?.focus();
  }, [open, preference]);

  const moveFocus = (offset: number) => {
    const count = options.length;
    const currentIndex = optionRefs.current.findIndex((node) => node === document.activeElement);
    const base = currentIndex === -1 ? 0 : currentIndex;
    const nextIndex = (base + offset + count) % count;
    optionRefs.current[nextIndex]?.focus();
  };

  const onMenuKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    if (event.key === 'ArrowDown') {
      event.preventDefault();
      moveFocus(1);
    } else if (event.key === 'ArrowUp') {
      event.preventDefault();
      moveFocus(-1);
    } else if (event.key === 'Home') {
      event.preventDefault();
      optionRefs.current[0]?.focus();
    } else if (event.key === 'End') {
      event.preventDefault();
      optionRefs.current[options.length - 1]?.focus();
    }
  };

  return (
    <div
      className={`petri-theme-control ${compact ? 'petri-theme-control--compact' : ''} ${menuPlacement === 'bottom' ? 'petri-theme-control--menu-bottom' : ''}`}
      ref={rootRef}
    >
      {open && (
        <div
          className="petri-theme-control__menu"
          role="menu"
          aria-label="选择外观主题"
          onKeyDown={onMenuKeyDown}
        >
          {options.map((option, index) => (
            <button
              key={option.value}
              ref={(node) => {
                optionRefs.current[index] = node;
              }}
              type="button"
              role="menuitemradio"
              aria-checked={preference === option.value}
              tabIndex={preference === option.value ? 0 : -1}
              className="petri-theme-control__option"
              onClick={() => {
                setPreference(option.value);
                close();
              }}
            >
              <Icon name={option.icon} size={15} />
              <span>{option.label}</span>
              {preference === option.value && <Icon name="check" size={14} />}
            </button>
          ))}
        </div>
      )}
      <button
        type="button"
        ref={triggerRef}
        className="petri-theme-control__trigger"
        onClick={() => setOpen((value) => !value)}
        onKeyDown={(event) => {
          if (event.key === 'ArrowDown' && !open) {
            event.preventDefault();
            setOpen(true);
          }
        }}
        aria-haspopup="menu"
        aria-expanded={open}
        title={`${current.label}（当前${resolvedTheme === 'dark' ? '夜间' : '日间'}）`}
      >
        <Icon name={current.icon} size={16} />
        {!compact && <span>{current.label}</span>}
        {!compact && <Icon name="chevron-up" size={13} />}
      </button>
    </div>
  );
}

import React from 'react';
import { readFile } from 'node:fs/promises';
import { resolve } from 'node:path';
import { act, cleanup, fireEvent, render, screen, waitFor } from '@testing-library/react';
import { MemoryRouter } from 'react-router-dom';
import { afterEach, describe, expect, it, vi } from 'vitest';
import type { TitleBarResultItem } from '@/hooks/useWorkspacePanels';
import { WorkspacePanelsProvider, useWorkspacePanelsContext } from './WorkspacePanelsContext';
import { TitleBar } from './TitleBar';

type DesktopWindow = NonNullable<Window['petriDesktop']>['window'];
type DesktopBridge = NonNullable<Window['petriDesktop']>;

function makeBridge(overrides: Partial<DesktopWindow> = {}): DesktopBridge {
  const windowApi: DesktopWindow = {
    minimize: vi.fn(),
    maximize: vi.fn(),
    close: vi.fn(),
    isMaximized: vi.fn().mockResolvedValue(false),
    onMaximizeChanged: vi.fn(() => vi.fn()),
    isFullScreen: vi.fn().mockResolvedValue(false),
    toggleFullScreen: vi.fn(),
    onFullScreenChanged: vi.fn(() => vi.fn()),
    // UI-411 — 测试实例窗口管理方法（mock 补齐满足 bridge 类型契约）
    setAlwaysOnTop: vi.fn().mockResolvedValue({ ok: true }),
    setIgnoreMouseEvents: vi.fn().mockResolvedValue({ ok: true }),
    onTestManageModeChanged: vi.fn(() => vi.fn()),
    ...overrides,
  };
  return {
    isDesktop: true,
    // mac 分支才渲染交通灯窗口控件；缺这个字段会导致相关用例全部找不到按钮。
    platform: 'darwin',
    window: windowApi,
  } as DesktopBridge;
}

function renderTitleBar() {
  return render(
    <MemoryRouter>
      <WorkspacePanelsProvider>
        <TitleBar />
      </WorkspacePanelsProvider>
    </MemoryRouter>,
  );
}

function ResultStateHarness({
  resultItems,
  activeResultId,
  onSelectResult,
}: {
  resultItems: TitleBarResultItem[];
  activeResultId: string | null;
  onSelectResult: ((id: string) => void) | null;
}) {
  const { updateTitleBar } = useWorkspacePanelsContext();

  React.useEffect(() => {
    updateTitleBar({ resultItems, activeResultId, onSelectResult });
  }, [activeResultId, onSelectResult, resultItems, updateTitleBar]);

  return null;
}

function renderTitleBarWithResults(
  resultItems: TitleBarResultItem[],
  activeResultId: string | null,
  onSelectResult: (id: string) => void,
) {
  // UI-376 — 结果选择器是工作区语境（欢迎页已 bare），渲染在工作区路由
  return render(
    <MemoryRouter initialEntries={['/project/p1/chat']}>
      <WorkspacePanelsProvider>
        <ResultStateHarness
          resultItems={resultItems}
          activeResultId={activeResultId}
          onSelectResult={onSelectResult}
        />
        <TitleBar />
      </WorkspacePanelsProvider>
    </MemoryRouter>,
  );
}

function deferred<T>() {
  let resolve!: (value: T | PromiseLike<T>) => void;
  let reject!: (reason?: unknown) => void;
  const promise = new Promise<T>((resolvePromise, rejectPromise) => {
    resolve = resolvePromise;
    reject = rejectPromise;
  });
  return { promise, resolve, reject };
}

afterEach(() => {
  cleanup();
  vi.unstubAllGlobals();
  vi.clearAllMocks();
});

describe('TitleBar desktop window controls', () => {
  it('renders the three mac traffic controls with labels and the expected icons', () => {
    const bridge = makeBridge();
    vi.stubGlobal('petriDesktop', bridge);
    renderTitleBar();

    const close = screen.getByRole('button', { name: '关闭窗口' });
    const minimize = screen.getByRole('button', { name: '最小化窗口' });
    const fullscreen = screen.getByRole('button', { name: '全屏' });

    expect(close.getAttribute('title')).toBe('关闭');
    expect(minimize.getAttribute('title')).toBe('最小化');
    expect(fullscreen.getAttribute('title')).toBe('全屏');
    for (const btn of [close, minimize, fullscreen]) {
      expect(btn.querySelector('svg[aria-hidden="true"]')).toBeTruthy();
    }
  });

  it('routes close, minimize, and fullscreen clicks to the desktop bridge', () => {
    const bridge = makeBridge();
    vi.stubGlobal('petriDesktop', bridge);
    renderTitleBar();

    fireEvent.click(screen.getByRole('button', { name: '关闭窗口' }));
    fireEvent.click(screen.getByRole('button', { name: '最小化窗口' }));
    fireEvent.click(screen.getByRole('button', { name: '全屏' }));

    expect(bridge.window.close).toHaveBeenCalledTimes(1);
    expect(bridge.window.minimize).toHaveBeenCalledTimes(1);
    expect(bridge.window.toggleFullScreen).toHaveBeenCalledTimes(1);
  });

  // 回归：mac 交通灯窗口控件是 DOM 里最靠前的可聚焦元素。若它们参与键盘焦点，
  // 页面加载后焦点会默认落在「关闭窗口」上，用户击键被按钮吞掉（空格/回车还会误触关闭）。
  it('keeps window controls out of the keyboard focus order', async () => {
    const source = await readFile(
      resolve(process.cwd(), 'src/components/desktop/titlebar/TitleBarLeftZone.tsx'),
      'utf8',
    );
    const controlBlocks = source
      .split('<button')
      .filter((block) => /aria-label=(?:"关闭窗口"|"最小化窗口"|"全屏")/.test(block));

    expect(controlBlocks.length).toBe(3);
    for (const block of controlBlocks) {
      expect(block).toContain('tabIndex={-1}');
    }
  });

  // mac 交通灯没有最大化态标签，但 useDesktopWindowControls 仍需订阅最大化事件
  // （供非 mac 双击手势与状态 hydration 使用），并在卸载时注销监听。
  it('hydrates window state, follows changes, and unregisters the listener', async () => {
    let onMaximizeChanged: ((isMaximized: boolean) => void) | undefined;
    const unsubscribe = vi.fn();
    const bridge = makeBridge({
      isMaximized: vi.fn().mockResolvedValue(true),
      onMaximizeChanged: vi.fn((callback: (isMaximized: boolean) => void) => {
        onMaximizeChanged = callback;
        return unsubscribe;
      }),
    });
    vi.stubGlobal('petriDesktop', bridge);
    const view = renderTitleBar();

    await waitFor(() => {
      expect(bridge.window.isMaximized).toHaveBeenCalledTimes(1);
      expect(bridge.window.onMaximizeChanged).toHaveBeenCalledTimes(1);
    });
    expect(typeof onMaximizeChanged).toBe('function');

    act(() => onMaximizeChanged?.(false));
    act(() => onMaximizeChanged?.(true));
    expect(screen.getByRole('button', { name: '全屏' })).toBeTruthy();

    view.unmount();
    expect(unsubscribe).toHaveBeenCalledTimes(1);
  });

  it('subscribes to live state before issuing the initial maximize query', async () => {
    const order: string[] = [];
    const bridge = makeBridge({
      onMaximizeChanged: vi.fn((callback: (isMaximized: boolean) => void) => {
        order.push('subscribe');
        return vi.fn();
      }),
      isMaximized: vi.fn(() => {
        order.push('query');
        return Promise.resolve(false);
      }),
    });
    vi.stubGlobal('petriDesktop', bridge);
    renderTitleBar();

    await waitFor(() => expect(bridge.window.isMaximized).toHaveBeenCalledTimes(1));
    expect(order).toEqual(['subscribe', 'query']);
  });

  // BLOCK-87 L3-2 — 投影环境（手机/平板浏览器）下的顶栏适配
  describe('TitleBar projection environment', () => {
  it('hides desktop window controls when the page is a phone projection', () => {
    // 手机投影（data-projection 垫片标志）：Windows 窗口控件（最小化/最大化/
    // 关闭）在浏览器里是垫片 no-op 死按钮，必须整体隐藏。
    document.documentElement.setAttribute('data-projection', '1');
    try {
      const bridge = { ...makeBridge(), platform: 'win32' } as DesktopBridge;
      vi.stubGlobal('petriDesktop', bridge);
      renderTitleBar();
      expect(screen.queryByRole('button', { name: '最小化' })).toBeNull();
      expect(screen.queryByRole('button', { name: '关闭' })).toBeNull();
    } finally {
      document.documentElement.removeAttribute('data-projection');
    }
  });

  it('keeps window controls on a real Windows desktop (no projection flag)', () => {
    const bridge = { ...makeBridge(), platform: 'win32' } as DesktopBridge;
    vi.stubGlobal('petriDesktop', bridge);
    renderTitleBar();
    expect(screen.getByRole('button', { name: '最小化' })).toBeTruthy();
    expect(screen.getByRole('button', { name: '关闭' })).toBeTruthy();
  });

  it('isProjectionMobile only fires with the projection flag and a narrow viewport', async () => {
    const { isProjectionMobile } = await import('./titlebar/shared');
    // jsdom 无 matchMedia：无投影标志时短路 false（不触 matchMedia）；
    // 有标志 + matchMedia 窄屏命中才为 true；matchMedia 缺失 fail-closed 回 false。
    expect(isProjectionMobile()).toBe(false);
    document.documentElement.setAttribute('data-projection', '1');
    try {
      const original = window.matchMedia;
      window.matchMedia = ((query: string) => ({ matches: query.includes('767'), media: query, onchange: null, addEventListener: vi.fn(), removeEventListener: vi.fn(), addListener: vi.fn(), removeListener: vi.fn(), dispatchEvent: vi.fn() })) as unknown as typeof window.matchMedia;
      expect(isProjectionMobile()).toBe(true);
      window.matchMedia = ((query: string) => ({ matches: false, media: query, onchange: null, addEventListener: vi.fn(), removeEventListener: vi.fn(), addListener: vi.fn(), removeListener: vi.fn(), dispatchEvent: vi.fn() })) as unknown as typeof window.matchMedia;
      expect(isProjectionMobile()).toBe(false);
      delete (window as { matchMedia?: unknown }).matchMedia;
      expect(isProjectionMobile()).toBe(false);
      window.matchMedia = original;
    } finally {
      document.documentElement.removeAttribute('data-projection');
    }
  });
});

  it('keeps live maximize events authoritative over a late initial query result', async () => {
    let onMaximizeChanged: ((isMaximized: boolean) => void) | undefined;
    const initialQuery = deferred<boolean>();
    const bridge = makeBridge({
      isMaximized: vi.fn(() => initialQuery.promise),
      onMaximizeChanged: vi.fn((callback: (isMaximized: boolean) => void) => {
        onMaximizeChanged = callback;
        return vi.fn();
      }),
    });
    vi.stubGlobal('petriDesktop', bridge);
    renderTitleBar();

    await waitFor(() => {
      expect(bridge.window.isMaximized).toHaveBeenCalledTimes(1);
      expect(bridge.window.onMaximizeChanged).toHaveBeenCalledTimes(1);
    });

    // 迟到的初始查询不得覆盖更新的 live 事件结果（状态由 hook 内部持有），
    // 这里验证流程不抛错且 UI 保持可渲染。
    await act(async () => {
      onMaximizeChanged?.(true);
      initialQuery.resolve(false);
      await initialQuery.promise;
    });
    expect(screen.getByRole('button', { name: '全屏' })).toBeTruthy();
  });

  it('keeps the safe unmaximized default when the initial query rejects', async () => {
    const initialQuery = deferred<boolean>();
    const bridge = { ...makeBridge({ isMaximized: vi.fn(() => initialQuery.promise) }), platform: 'win32' } as DesktopBridge;
    vi.stubGlobal('petriDesktop', bridge);
    renderTitleBar();

    await waitFor(() => {
      expect(bridge.window.isMaximized).toHaveBeenCalledTimes(1);
    });
    // 查询挂起/拒绝时 WindowControls 保持未最大化默认（最大化按钮，非「还原」）。
    expect(screen.getByRole('button', { name: '最大化' })).toBeTruthy();

    await act(async () => {
      initialQuery.reject(new Error('window state unavailable'));
      await Promise.resolve();
    });
    expect(screen.getByRole('button', { name: '最大化' })).toBeTruthy();
  });

  it('keeps the safe default when an older bridge throws before returning a query promise', async () => {
    // 保持 darwin：win32 的 WindowControls 会在 effect 里同步调用 isMaximized，
    // 同步 throw 会让 React root 崩溃；hook 路径经 Promise.resolve().then 包裹，可安全兜底。
    const bridge = makeBridge({
      isMaximized: vi.fn(() => {
        throw new Error('window state unavailable');
      }),
    });
    vi.stubGlobal('petriDesktop', bridge);
    renderTitleBar();

    await act(async () => {
      await Promise.resolve();
    });
    expect(screen.getByRole('button', { name: '全屏' })).toBeTruthy();
  });

  // 双击标题栏切换全屏只在非 mac 生效：mac 上该手势由系统处理，
  // 组件显式设置 onDoubleClick={!isMac ? ... : undefined}。
  it('toggles fullscreen on a blank header double-click but ignores buttons and role=button children', () => {
    const bridge = { ...makeBridge(), platform: 'win32' } as DesktopBridge;
    vi.stubGlobal('petriDesktop', bridge);
    renderTitleBar();
    const header = screen.getByRole('banner');

    fireEvent.doubleClick(header);
    expect(bridge.window.toggleFullScreen).toHaveBeenCalledTimes(1);

    // 非 mac 走 WindowControls，其 aria-label 是「最小化」（mac 交通灯才是「最小化窗口」）。
    fireEvent.doubleClick(screen.getByRole('button', { name: '最小化' }));
    expect(bridge.window.toggleFullScreen).toHaveBeenCalledTimes(1);

    const roleButton = document.createElement('div');
    roleButton.setAttribute('role', 'button');
    header.appendChild(roleButton);
    fireEvent.doubleClick(roleButton);
    expect(bridge.window.toggleFullScreen).toHaveBeenCalledTimes(1);
  });

  it('uses the fixed collapsed left rail width after toggling the left panel', () => {
    vi.stubGlobal('petriDesktop', undefined);
    renderTitleBar();
    const header = screen.getByRole('banner');
    expect(header.getAttribute('style')).toContain('--titlebar-left-span: 241px');

    fireEvent.click(screen.getByRole('button', { name: '收起左侧栏' }));

    // 非 mac（无 desktop bridge）收起后为 collapsedLeftRail=146；mac 为 180。
    expect(header.style.getPropertyValue('--titlebar-left-span')).toBe('146px');
  });
});

