import React, { useEffect, useRef, useState } from 'react';
import { useLocation } from 'react-router-dom';
import { Icon } from '@/components/icons/Icon';
import { useWorkspacePanelsContext } from '../WorkspacePanelsContext';
import { BranchTabsWrapper } from '@/components/branch/BranchTabsWrapper';
import styles from '../TitleBar.module.css';
import { getFallbackTitle, isProjectionMobile, isStandalonePagePath, modeUsesSummaryCard, parseWorkspaceRoute } from './shared';

/**
 * BLOCK-62 P1a — TitleBar 中区片段（标题 + 分支 tabs + 结果选择器 + 摘要概览开关）。
 *
 * 容器无关：既被 fixed 整条 [TitleBar.tsx](../TitleBar.tsx) 复用，也被 P1b
 * 列级 header-slot 复用。结果菜单的开合状态内聚在本组件——同一时刻只有一个
 * 宿主（fixed 条或列级片段）渲染它，不存在双份状态。逻辑与提取前一致。
 *
 * UI-334 — 会话选择器（convSelector）整体移除：左栏项目树下已有完整会话
 * 列表（含分支标识），标题栏下拉为重复入口（用户裁决「除掉这部分」）。
 */
export function TitleBarCenterZone(): React.ReactElement {
  const location = useLocation();
  const panels = useWorkspacePanelsContext();
  const {
    title,
    resultItems,
    activeResultId,
    onSelectResult,
  } = panels.titleBar;

  const [resultMenuOpen, setResultMenuOpen] = useState(false);
  const resultTriggerRef = useRef<HTMLButtonElement>(null);
  const resultMenuItemsRef = useRef<Record<string, HTMLButtonElement | null>>({});
  const activeResult = resultItems.find((item) => item.id === activeResultId) || resultItems[0] || null;

  const closeResultMenu = () => {
    setResultMenuOpen(false);
    resultTriggerRef.current?.focus();
  };

  const selectResult = (id: string) => {
    onSelectResult?.(id);
    closeResultMenu();
  };

  useEffect(() => {
    if (resultItems.length < 2 && resultMenuOpen) {
      setResultMenuOpen(false);
    }
  }, [resultItems.length, resultMenuOpen]);

  useEffect(() => {
    if (!resultMenuOpen || resultItems.length < 2 || !activeResult) return;
    resultMenuItemsRef.current[activeResult.id]?.focus();
  }, [activeResult, resultItems, resultMenuOpen]);

  useEffect(() => {
    if (!resultMenuOpen) return undefined;

    const handleResultMenuDocumentKeyDown = (event: KeyboardEvent) => {
      if (event.key !== 'Escape') return;
      event.preventDefault();
      closeResultMenu();
    };
    const handleWindowResize = () => setResultMenuOpen(false);

    document.addEventListener('keydown', handleResultMenuDocumentKeyDown);
    window.addEventListener('resize', handleWindowResize);
    return () => {
      document.removeEventListener('keydown', handleResultMenuDocumentKeyDown);
      window.removeEventListener('resize', handleWindowResize);
    };
  }, [resultMenuOpen]);

  const moveResultFocus = (currentIndex: number, offset: number) => {
    if (resultItems.length === 0) return;
    const nextIndex = (currentIndex + offset + resultItems.length) % resultItems.length;
    resultMenuItemsRef.current[resultItems[nextIndex].id]?.focus();
  };

  const handleResultMenuItemKeyDown = (
    event: React.KeyboardEvent<HTMLButtonElement>,
    itemId: string,
    itemIndex: number,
  ) => {
    if (event.key === 'ArrowDown') {
      event.preventDefault();
      moveResultFocus(itemIndex, 1);
    } else if (event.key === 'ArrowUp') {
      event.preventDefault();
      moveResultFocus(itemIndex, -1);
    } else if (event.key === 'Home') {
      event.preventDefault();
      resultMenuItemsRef.current[resultItems[0].id]?.focus();
    } else if (event.key === 'End') {
      event.preventDefault();
      resultMenuItemsRef.current[resultItems[resultItems.length - 1].id]?.focus();
    } else if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      selectResult(itemId);
    }
  };

  // UI-348 — 全局独立页（/skills /knowledge /backend）不渲染品牌 chip 与分区
  // 分隔线：页面自带「返回+标题」页头，顶栏只留可拖拽区与窗口控件。
  if (isStandalonePagePath(location.pathname)) {
    return <div className={`${styles.centerTitle} ${styles.centerTitleBare}`} aria-hidden="true" />;
  }

  // UI-360 — 摘要概览开关只在工作区路由的 chat / scheduled 模式渲染
  // （摘要卡 showPinnedSummary 同口径）；欢迎页 / 独立页与 plugins/settings
  // 等全屏工作面无摘要卡，开关是死开关。
  const summaryToggleAvailable = (() => {
    const ws = parseWorkspaceRoute(location.pathname);
    return !!ws && modeUsesSummaryCard(ws.mode);
  })();

  // UI-377 — 中区右缘分隔线只在「右栏真的在场」时渲染（工作区路由 + 右栏开 +
  // 非投影手机）。此前只看全局 rightOpen 偏好：欢迎页/独立页右栏并不在场，
  // 一条悬空分隔线挂在标题区右缘（用户截图指认「灰色分隔线多余」）。
  const rightRailPresent =
    !!parseWorkspaceRoute(location.pathname) && panels.rightOpen && !isProjectionMobile();

  const displayTitle = title || getFallbackTitle(location.pathname);

  return (
    <div className={`${styles.centerTitle} ${!rightRailPresent ? styles.centerTitleNoDivider : ''}`}>
      <div className={styles.centerTitleMain}>
        <Icon name="folder" size={15} />
        <span className={styles.centerTitleText}>{displayTitle}</span>
      </div>
      <BranchTabsWrapper />
      {/* UI-334 — 会话选择器已移除：左栏项目树下即完整会话列表（含分支） */}
      {activeResult && (
        <div className={styles.resultPicker}>
          <button
            type="button"
            className={styles.resultPrimary}
            onClick={() => selectResult(activeResult.id)}
            title={`打开${activeResult.label}`}
          >
            <span>结果 {resultItems.length}</span>
          </button>
          {resultItems.length > 1 && (
            <button
              type="button"
              ref={resultTriggerRef}
              className={styles.resultMenuTrigger}
              onClick={() => setResultMenuOpen((open) => !open)}
              onKeyDown={(event) => {
                if (event.key === 'ArrowDown') {
                  event.preventDefault();
                  setResultMenuOpen(true);
                }
              }}
              title="展开结果列表"
              aria-label={resultMenuOpen ? '收起结果列表' : '展开结果列表'}
              aria-haspopup="menu"
              aria-expanded={resultMenuOpen}
              aria-controls="titlebar-result-menu"
            >
              <Icon name="chevron-down" size={13} />
            </button>
          )}
          {resultMenuOpen && resultItems.length > 1 && (
            <>
              <button
                type="button"
                className={styles.resultMenuOverlay}
                onClick={closeResultMenu}
                aria-label="关闭结果菜单"
              />
              <div
                id="titlebar-result-menu"
                className={styles.resultMenu}
                role="menu"
                aria-label="结果列表"
              >
                {resultItems.map((item, itemIndex) => {
                  const isActive = item.id === activeResult.id;
                  return (
                    <button
                      key={item.id}
                      type="button"
                      ref={(node) => {
                        resultMenuItemsRef.current[item.id] = node;
                      }}
                      className={`${styles.resultMenuItem} ${isActive ? styles.resultMenuItemActive : ''}`}
                      role="menuitem"
                      aria-current={isActive ? 'true' : undefined}
                      tabIndex={isActive ? 0 : -1}
                      data-result-id={item.id}
                      onClick={() => selectResult(item.id)}
                      onKeyDown={(event) => handleResultMenuItemKeyDown(event, item.id, itemIndex)}
                    >
                      <span className={styles.resultMenuItemLabel}>{item.label}</span>
                      <span className={styles.resultMenuItemStatus} data-status={item.status}>
                        {item.status}
                      </span>
                      {isActive && <Icon name="check" size={13} />}
                    </button>
                  );
                })}
              </div>
            </>
          )}
        </div>
      )}
      {/* UI-360 — 摘要概览开关只在工作区路由的 chat / scheduled 模式渲染
          （摘要卡 showPinnedSummary 同口径）；欢迎页 / 独立页与 plugins/settings
          等全屏工作面无摘要卡，开关是死开关。 */}
      {summaryToggleAvailable && (
        <button
          type="button"
          className={styles.iconBtn}
          onClick={panels.toggleSummary}
          title={panels.summaryOpen ? '收起摘要概览' : '展开摘要概览'}
          aria-label={panels.summaryOpen ? '收起摘要概览' : '展开摘要概览'}
          aria-pressed={panels.summaryOpen}
        >
          <Icon name="list-details" size={15} />
        </button>
      )}
    </div>
  );
}

import React, { useEffect, useState } from 'react';
import { getBridge } from '@/lib/desktopBridge';
import { BRAND } from '@/lib/brand';
import { Icon } from '@/components/icons/Icon';
import { segmentToMode, type WorkspaceMode } from '@/hooks/useWorkspaceRouting';
import styles from '../TitleBar.module.css';

/**
 * BLOCK-62 P1a — TitleBar 列体化共享层。
 *
 * 这些纯函数 / 钩子 / 组件从 [TitleBar.tsx](../TitleBar.tsx) 原样提取，供
 * 三处复用：fixed 整条 TitleBar（非列体化路由：home/skills/review/result-studio）
 * 与列级 header 片段（ProjectWorkspace 左/中/右列）。提取是行为保持的：
 * 逻辑与依赖一字不动，只是换了宿主文件，避免 P1b 布局翻转时重复实现。
 */

// 惰性求值（不要提成模块级常量）：模块级常量在 import 时就固化，测试里通过
// vi.stubGlobal 注入 window.petriDesktop 发生在 import 之后，会导致这两个判定
// 永远为 false、窗口控件根本不渲染，整个测试文件集体失败。
export function getIsMac(): boolean {
  return typeof window !== 'undefined' && window.petriDesktop?.platform === 'darwin';
}

export function getIsDesktop(): boolean {
  return typeof window !== 'undefined' && window.petriDesktop?.isDesktop === true;
}

/**
 * BLOCK-87 — 投影环境（手机/平板浏览器经 gateway 投影访问）。标志由投影垫片
 * 在 <head> 最前同步设置（先于 React 挂载，勿用 window 标志——React 挂载后
 * 读不到）。此形态下桌面窗口控件（最小化/最大化/关闭）是死按钮，一律隐藏。
 */
export function getIsProjection(): boolean {
  return typeof document !== 'undefined'
    && document.documentElement.getAttribute('data-projection') === '1';
}

/**
 * BLOCK-87 L3 — 投影 + 窄屏（≤767px 手机浏览器）：壳层 AppRail 转抽屉浮层，
 * 标题栏左上「展开/收起左侧栏」按钮直接开合（L3-2 用户裁决：撤掉独立 ☰，
 * 左上唯一入口）。jsdom 无 matchMedia 时 fail-closed 回 false（桌面语义）。
 */
export function isProjectionMobile(): boolean {
  try {
    return getIsProjection() && window.matchMedia('(max-width: 767px)').matches;
  } catch {
    return false;
  }
}

/**
 * UI-359/360 — 工作区路由解析（`/project/:id/*` 单一事实源）。
 *
 * 返回 null = 工作区面板不存在的路由：非 project 路由（/、/projects、/skills、
 * /knowledge、/backend）与 `/project/:id/results`（独立 ResultStudio 页）。
 * mode 经 segmentToMode 解析（chat 为默认落地模式，未知段 fail-closed 回 chat），
 * 供顶栏各 zone 按模式裁剪只在对应模式存在的控件（死开关治理）。
 */
export function parseWorkspaceRoute(pathname: string): { mode: WorkspaceMode } | null {
  const path = pathname.replace(/\/+$/, '') || '/';
  const m = path.match(/^\/project\/[^/]+(?:\/(.*))?$/);
  if (!m || m[1] === 'results') return null;
  return { mode: segmentToMode(m[1]) };
}

/**
 * UI-360 — 该工作区模式是否有摘要概览卡消费：摘要卡只在 chat / scheduled
 * 会话布局内渲染（project-workspace `showPinnedSummary` 同口径），顶栏的
 * 「展开摘要概览」开关在其余模式/路由是死开关。
 * UI-365 — modeUsesRightRail 随 settings 模式退役而移除：工作区模式
 * （chat/scheduled/结果族）全部有右栏消费，右栏开合只由路由与用户偏好决定。
 */
export function modeUsesSummaryCard(mode: WorkspaceMode): boolean {
  return mode === 'chat' || mode === 'scheduled';
}

/**
 * UI-348 — 全局独立页判定（/skills /knowledge /backend）：这些页面自带
 * 「返回 + 图标 + 标题」页头，fixed 顶栏不再渲染品牌 chip 与分区分隔线
 * （此前顶栏左区分隔线与壳层左栏宽度错位 24px，叠出「多一条线」的布局冲突）。
 * UI-364 — /plugins 插件商店独立页并入同形态。
 * UI-365 — /settings 设置独立页并入同形态。
 * UI-376 — / 欢迎页并入同形态：页面自带「返回 + 问候」页头，顶栏的品牌回退
 * 标题（「Petri」）与左区分隔线（与左栏边缘错位 ~13px 的悬空线）均无意义
 * （用户截图指认「Petri 和旁边的灰色分隔线没有实际意义」）。
 */
export function isStandalonePagePath(pathname: string): boolean {
  return pathname === '/' || /^\/(skills|knowledge|backend|plugins|settings)\/?$/.test(pathname);
}

export function getFallbackTitle(pathname: string): string {
  if (pathname.startsWith('/project/')) return '梳理开发进展';
  if (pathname.startsWith('/tools')) return '分析结果';
  if (pathname.startsWith('/admin')) return '管理';
  return BRAND.APP_NAME;
}

export interface DesktopWindowControls {
  isMaximized: boolean;
  minimize: () => void;
  toggleFullScreen: () => void;
  close: () => void;
  onTitleBarDoubleClick: (event: React.MouseEvent<HTMLElement>) => void;
}

/**
 * 顶栏双击 → 切换全屏。纯函数（不订阅 maximize 状态）：fixed 整条 TitleBar 只需要
 * 这个动作，用完整 useDesktopWindowControls 会和交通灯所在片段各订阅一次
 * onMaximizeChanged（双份查询/订阅）。订阅归交通灯片段（唯一消费者）持有。
 */
export function handleTitleBarDoubleClick(event: React.MouseEvent<HTMLElement>): void {
  const target = event.target as Element | null;
  if (target?.closest?.('button, a, input, select, textarea, [role="button"]')) {
    return;
  }
  const bridge = typeof window !== 'undefined' ? window.petriDesktop : undefined;
  const desktopWindow = bridge?.isDesktop === true ? bridge.window : undefined;
  desktopWindow?.toggleFullScreen?.();
}

export function useDesktopWindowControls(): DesktopWindowControls {
  const bridge = typeof window !== 'undefined' ? window.petriDesktop : undefined;
  const desktopWindow = bridge?.isDesktop === true ? bridge.window : undefined;
  const [isMaximized, setIsMaximized] = useState<boolean>(false);

  useEffect(() => {
    if (!desktopWindow) return undefined;

    let active = true;
    let receivedLiveState = false;
    let unsubscribe: (() => void) | undefined;

    try {
      // Subscribe before hydrating from the query. A maximize event can arrive
      // between these operations, and the live event is the newer truth.
      unsubscribe = desktopWindow.onMaximizeChanged?.((value) => {
        receivedLiveState = true;
        if (active) setIsMaximized(value === true);
      });
    } catch {
      // A partially available preload bridge should leave the safe default in
      // place instead of preventing the title bar from rendering.
      unsubscribe = undefined;
    }

    if (desktopWindow.isMaximized) {
      // Promise.resolve().then(...) also catches a bridge that throws before it
      // can return its Promise (for example, an older preload implementation).
      void Promise.resolve()
        .then(() => desktopWindow.isMaximized?.())
        .then((value) => {
          // A live maximize/unmaximize event is newer than the initial query.
          // Never let a late query response overwrite that state.
          if (active && !receivedLiveState) setIsMaximized(value === true);
        })
        .catch(() => {
          // Older or partially available desktop bridges keep the safe default.
        });
    }

    return () => {
      active = false;
      try {
        unsubscribe?.();
      } catch {
        // Cleanup must remain safe even if an older bridge has a fragile
        // unsubscribe implementation.
      }
    };
  }, [desktopWindow?.isMaximized, desktopWindow?.onMaximizeChanged]);

  return {
    isMaximized,
    minimize: () => desktopWindow?.minimize?.(),
    toggleFullScreen: () => desktopWindow?.toggleFullScreen?.(),
    close: () => desktopWindow?.close?.(),
    onTitleBarDoubleClick: (event) => {
      const target = event.target as Element | null;
      if (target?.closest?.('button, a, input, select, textarea, [role="button"]')) {
        return;
      }
      desktopWindow?.toggleFullScreen?.();
    },
  };
}

/**
 * Custom frameless window controls (minimize / maximize-restore / close).
 * Rendered ONLY on non-macOS. Calls the existing `window` IPC bridge that
 * the preload already exposes (`minimize`, `maximize` [toggles], `close`,
 * `isMaximized`).
 */
export function WindowControls({ divider = true }: { divider?: boolean } = {}): React.ReactElement {
  const bridge = getBridge('window');
  const [isMaximized, setIsMaximized] = useState<boolean>(false);

  useEffect(() => {
    if (!bridge) return;
    let cancelled = false;
    bridge
      .isMaximized()
      .then((maximized) => {
        if (!cancelled) setIsMaximized(maximized);
      })
      .catch(() => {});
    return () => {
      cancelled = true;
    };
  }, [bridge]);

  if (!bridge) return <></>;

  return (
    <div className={`${styles.windowControls} ${!divider ? styles.windowControlsNoDivider : ''}`}>
      <button
        type="button"
        className={styles.winBtn}
        onClick={() => bridge.minimize()}
        title="最小化"
        aria-label="最小化"
      >
        <Icon name="minus" size={14} />
      </button>
      <button
        type="button"
        className={styles.winBtn}
        onClick={() => {
          bridge.maximize();
          setIsMaximized((prev) => !prev);
        }}
        title={isMaximized ? '还原' : '最大化'}
        aria-label={isMaximized ? '还原' : '最大化'}
      >
        <Icon name={isMaximized ? 'restore' : 'square'} size={14} />
      </button>
      <button
        type="button"
        className={`${styles.winBtn} ${styles.winBtnClose}`}
        onClick={() => bridge.close()}
        title="关闭"
        aria-label="关闭"
      >
        <Icon name="x" size={14} />
      </button>
    </div>
  );
}

