    );
    expect(screen.getByRole('status').textContent).toContain('正在绑定');
    expect((screen.getByRole('button', { name: '交给 Agent' }) as HTMLButtonElement).disabled).toBe(true);

    rerender(
      <ResultAgentComposer
        context={{ status: 'blocked', contextToken: null, reason: '缺少正式 Revision' }}
        draft="调整配色"
        onDraftChange={() => undefined}
        onSubmit={() => undefined}
      />,
    );
    expect(screen.getByText(/缺少正式 Revision/)).toBeTruthy();
    expect((screen.getByRole('button', { name: '交给 Agent' }) as HTMLButtonElement).disabled).toBe(true);

    rerender(
      <ResultAgentComposer
        context={{ status: 'ready', contextToken: 'not-a-token' }}
        draft="调整配色"
        onDraftChange={() => undefined}
        onSubmit={() => undefined}
      />,
    );
    expect(screen.getByRole('status').textContent).toContain('上下文不完整');
    expect((screen.getByRole('button', { name: '交给 Agent' }) as HTMLButtonElement).disabled).toBe(true);
  });

  it('选择过期或不可用时保留可见安全边界，但不重复就绪说明', () => {
    const { rerender } = render(
      <ResultAgentComposer
        context={{ status: 'ready', contextToken: TOKEN_A, selectionCompatibility: 'stale' }}
        draft="调整配色"
        onDraftChange={() => undefined}
        onSubmit={() => undefined}
      />,
    );
    expect(screen.getByRole('status').textContent).toContain('选择已过期');
    expect(screen.getByRole('status').textContent).toContain('不会交给 Agent');

    rerender(
      <ResultAgentComposer
        context={{ status: 'ready', contextToken: TOKEN_A, selectionCompatibility: 'invalid' }}
        draft="调整配色"
        onDraftChange={() => undefined}
        onSubmit={() => undefined}
      />,
    );
    expect(screen.getByRole('status').textContent).toContain('选择不可用');
  });

  it('上下文刷新后只提交最新 token，旧 token 不会被复用', () => {
    const onSubmit = vi.fn();
    const { rerender } = render(
      <ResultAgentComposer
        context={{ status: 'ready', contextToken: TOKEN_A }}
        draft="加大标签"
        onDraftChange={() => undefined}
        onSubmit={onSubmit}
      />,
    );
    rerender(
      <ResultAgentComposer
        context={{ status: 'ready', contextToken: TOKEN_B }}
        draft="加大标签"
        onDraftChange={() => undefined}
        onSubmit={onSubmit}
      />,
    );
    fireEvent.click(screen.getByRole('button', { name: '交给 Agent' }));
    expect(onSubmit.mock.calls[0][0].contextToken).toBe(TOKEN_B);
  });

  it('Cmd/Ctrl+Enter 可发送，但普通 Enter 只换行', () => {
    const onSubmit = vi.fn();
    render(
      <ResultAgentComposer
        context={{ status: 'ready', contextToken: TOKEN_A }}
        draft="修改图例"
        onDraftChange={() => undefined}
        onSubmit={onSubmit}
      />,
    );
    const input = screen.getByLabelText('描述你希望当前结果发生什么变化');
    fireEvent.keyDown(input, { key: 'Enter' });
    expect(onSubmit).not.toHaveBeenCalled();
    fireEvent.keyDown(input, { key: 'Enter', metaKey: true });
    expect(onSubmit).toHaveBeenCalledTimes(1);
  });

  it('宿主拒绝提交时保留草稿，不把并发运行误报成已发送', () => {
    const onDraftChange = vi.fn();
    render(
      <ResultAgentComposer
        context={{ status: 'ready', contextToken: TOKEN_A }}
        draft="不要丢掉我"
        onDraftChange={onDraftChange}
        onSubmit={() => false}
      />,
    );
    fireEvent.click(screen.getByRole('button', { name: '交给 Agent' }));
    expect(onDraftChange).not.toHaveBeenCalledWith('');
  });

  it('只渲染后端投影的公开阶段，并保留停止/失败结论', () => {
    render(
      <ResultAgentComposer
        context={{ status: 'ready', contextToken: TOKEN_A }}
        draft=""
        onDraftChange={() => undefined}
        onSubmit={() => undefined}
        progress={[
          {
            resultEditProgressVersion: 1, sequence: 1, changeSetId: '',
            stage: 'intent', status: 'completed',
            publicPhase: 'understand_intent', publicPhaseLabel: '理解意图',
          },
          {
            resultEditProgressVersion: 1, sequence: 2, changeSetId: '',
            stage: 'plan', status: 'completed',
            publicPhase: 'assess_impact', publicPhaseLabel: '判断影响',
          },
          {
            resultEditProgressVersion: 1, sequence: 3, changeSetId: 'cs_1',
            stage: 'materialize', status: 'completed',
            publicPhase: 'execute_or_recompute', publicPhaseLabel: '执行/重算',
          },
          {
            resultEditProgressVersion: 1, sequence: 4, changeSetId: 'cs_1',
            stage: 'revision', status: 'completed',
            publicPhase: 'validate', publicPhaseLabel: '验证',
          },
          {
            resultEditProgressVersion: 1, sequence: 5, changeSetId: 'cs_1',
            stage: 'preview', status: 'ready',
            publicPhase: 'candidate_comparable', publicPhaseLabel: '候选可比较',
          },
          {
            resultEditProgressVersion: 1, sequence: 6, changeSetId: 'cs_1',
            stage: 'failed', status: 'terminal', reason: 'validator blocked',
          },
        ]}
      />,
    );
    for (const label of ['理解意图', '判断影响', '执行/重算', '验证', '候选可比较']) {
      expect(screen.getByText(label)).toBeTruthy();
    }
    expect(screen.getAllByText('已完成').length).toBeGreaterThan(0);
    expect(screen.getByText('修改未完成')).toBeTruthy();
    expect(screen.queryByText(/validator blocked/)).toBeNull();
    expect(screen.queryByText('materialize')).toBeNull();
  });
});

import React from 'react';
import { cleanup, fireEvent, render, screen } from '@testing-library/react';
import { afterEach, describe, expect, it, vi } from 'vitest';
import { ResultEditAdvancedDrawer, ResultEditPanel } from './ResultEditPanel';
import type { ResultStudioEditControls } from '@/lib/result-studio-interaction-client';

afterEach(cleanup);

function schema(overrides: Partial<ResultStudioEditControls> = {}): ResultStudioEditControls {
  return {
    controlsVersion: 1,
    groups: [
      { group: 'presentation', label: '外观与导出', parameterNames: ['color_up', 'point_size', 'legend_position'] },
      { group: 'scientific', label: '科学参数', parameterNames: ['fc_threshold'] },
    ],
    controls: [
      {
        name: 'color_up', controlType: 'color', impact: 'presentation', group: 'presentation',
        default: '#dc2626', required: false, scientificallyNeutral: true,
      },
      {
        name: 'point_size', controlType: 'number', impact: 'presentation', group: 'presentation',
        default: 1.8, required: false, minimum: 0.2, maximum: 6, scientificallyNeutral: true,
      },
      {
        name: 'legend_position', controlType: 'select', impact: 'presentation', group: 'presentation',
        default: 'right', required: false, options: ['right', 'left', 'top', 'bottom', 'none'],
        scientificallyNeutral: true,
      },
      {
        name: 'fc_threshold', controlType: 'number', impact: 'scientific', group: 'scientific',
        default: 1, required: false, minimum: 0, maximum: null, scientificallyNeutral: false,
      },
    ],
    diagnostics: [],
    currentValues: { color_up: '#dc2626', point_size: 1.8, legend_position: 'right', fc_threshold: 1 },
    ...overrides,
  };
}

describe('G0-RS-P4 Schema 驱动统一编辑面板', () => {
  it('控件完全来自 descriptor 投影，未声明参数不出现', () => {
    render(<ResultEditPanel editControls={schema()} onSubmit={() => undefined} />);
    expect(screen.getByText('color_up')).toBeTruthy();
    expect(screen.getByText('fc_threshold')).toBeTruthy();
    expect(screen.queryByText('secret_flag')).toBeNull();
  });

  it('没有可编辑参数时如实说明，不伪造控件', () => {
    render(
      <ResultEditPanel
        editControls={schema({ groups: [], controls: [], currentValues: {} })}
        onSubmit={() => undefined}
      />,
    );
    expect(screen.getByText(/没有声明可编辑参数/)).toBeTruthy();
  });

  it('无改动时不能提交，避免生成空候选版本', () => {
    render(<ResultEditPanel editControls={schema()} onSubmit={() => undefined} />);
    const submit = screen.getByRole('button', { name: /生成候选版本/ });
    expect((submit as HTMLButtonElement).disabled).toBe(true);
  });

  it('仅改呈现参数时声明不重新计算科学结论，且无需科学确认', () => {
    const onSubmit = vi.fn();
    render(<ResultEditPanel editControls={schema()} onSubmit={onSubmit} />);
    fireEvent.change(screen.getByLabelText('point_size'), { target: { value: '3' } });
    const status = screen.getByRole('status');
    expect(status.getAttribute('data-science')).toBe('false');
    expect(status.textContent).toContain('不重新计算科学结论');
    expect(screen.queryByText(/确认继续/)).toBeNull();
    fireEvent.click(screen.getByRole('button', { name: /生成候选版本/ }));
    expect(onSubmit).toHaveBeenCalledTimes(1);
    const submission = onSubmit.mock.calls[0][0];
    expect(submission.origin).toBe('manual');
    expect(submission.parameterPatch).toEqual({ point_size: 3 });
    expect(submission.scientificConfirmed).toBe(false);
  });

  it('改科学参数必须显式确认才能提交，UI 不代替用户确认', () => {
    const onSubmit = vi.fn();
    render(<ResultEditPanel editControls={schema()} onSubmit={onSubmit} />);
    fireEvent.change(screen.getByLabelText('fc_threshold'), { target: { value: '2' } });
    const status = screen.getByRole('status');
    expect(status.getAttribute('data-science')).toBe('true');
    expect(status.textContent).toContain('需要重新计算');
    const submit = screen.getByRole('button', { name: /生成候选版本/ }) as HTMLButtonElement;
    expect(submit.disabled).toBe(true);
    fireEvent.click(screen.getByRole('checkbox', { name: /确认继续/ }));
    expect(submit.disabled).toBe(false);
    fireEvent.click(submit);
    expect(onSubmit.mock.calls[0][0].scientificConfirmed).toBe(true);
  });

  it('把值改回当前生效值后视为无改动，不进入 patch', () => {
    render(<ResultEditPanel editControls={schema()} onSubmit={() => undefined} />);
    const input = screen.getByLabelText('point_size');
    fireEvent.change(input, { target: { value: '3' } });
    expect((screen.getByRole('button', { name: /生成候选版本/ }) as HTMLButtonElement).disabled).toBe(false);
    fireEvent.change(input, { target: { value: '1.8' } });
    expect((screen.getByRole('button', { name: /生成候选版本/ }) as HTMLButtonElement).disabled).toBe(true);
  });

  it('上下文阻断时禁用手动提交并显示原因', () => {
    render(
      <ResultEditPanel
        editControls={schema()}
        disabledReason="归因只能到 Job，缺少可复现的单产物脚本。"
        onSubmit={() => undefined}
      />,
    );
    expect(screen.getByText(/归因只能到 Job/)).toBeTruthy();
    fireEvent.change(screen.getByLabelText('point_size'), { target: { value: '3' } });
    expect((screen.getByRole('button', { name: /生成候选版本/ }) as HTMLButtonElement).disabled).toBe(true);
  });

  it('作为高级精调抽屉时默认折叠，展开后仍提交同一种手动 patch', () => {
    const onSubmit = vi.fn();
    render(<ResultEditAdvancedDrawer editControls={schema()} onSubmit={onSubmit} />);

    const drawer = document.querySelector('details[aria-label="高级精细调整"]') as HTMLDetailsElement;
    expect(drawer).toBeTruthy();
    expect(drawer.hasAttribute('open')).toBe(false);

    drawer.setAttribute('open', '');
    fireEvent.change(screen.getByLabelText('point_size'), { target: { value: '3' } });
    fireEvent.click(screen.getByRole('button', { name: /生成候选版本/ }));

    expect(onSubmit).toHaveBeenCalledWith(expect.objectContaining({
      origin: 'manual',
      completionExpectation: 'candidate',
      parameterPatch: { point_size: 3 },
    }));
    expect(screen.queryByText(/或者直接描述/)).toBeNull();
  });

  it('放弃改动清空草稿与科学确认', () => {
    render(<ResultEditPanel editControls={schema()} onSubmit={() => undefined} />);
    fireEvent.change(screen.getByLabelText('fc_threshold'), { target: { value: '2' } });
    fireEvent.click(screen.getByRole('checkbox', { name: /确认继续/ }));
    fireEvent.click(screen.getByRole('button', { name: '放弃改动' }));
    expect((screen.getByRole('button', { name: /生成候选版本/ }) as HTMLButtonElement).disabled).toBe(true);
    expect(screen.queryByRole('status')).toBeNull();
  });
});

import React from 'react';
import { Icon } from '@/components/icons/Icon';
import type {
  ResultStudioEditControl,
  ResultStudioEditControls,
} from '@/lib/result-studio-interaction-client';
import styles from './ResultEditPanel.module.css';

/**
 * G0-RS-P4 — Schema 驱动的统一编辑面板。
 *
 * 不为任何插件手写结果页：控件全部来自后端投影的 descriptor schema，
 * 插件没声明的参数不会出现在这里。P4R-3 后本组件只承担高级精调；
 * 默认入口是结果焦点区的自然语言 Composer。两者产出的 parameterPatch
 * 仍进入同一条 ResultEditIntent → ChangeSet 链。
 *
 * 诚实边界：
 * - 只有 `scientificallyNeutral` 为真的分组才允许标注"不改变科学结论"。
 * - 科学/流程参数必须显式勾选确认才可提交，UI 不代替用户确认。
 * - 面板不写文件、不覆盖 current Revision：提交只产生候选版本请求。
 */

export type EditSubmissionOrigin = 'manual' | 'agent';
export type ResultEditCompletionExpectation = 'candidate' | 'result_action' | 'none';

export interface ResultEditSubmission {
  origin: EditSubmissionOrigin;
  completionExpectation: ResultEditCompletionExpectation;
  requestedOutcome: string;
  parameterPatch: Record<string, unknown>;
  scientificConfirmed: boolean;
  /** P4R-3：只由结果焦点 Composer 携带；不渲染、不写进用户消息。 */
  contextToken?: string | null;
}

const GROUP_HINTS: Record<string, string> = {
  presentation: '只影响呈现，不重新计算科学结论',
  data: '改变数据呈现范围，会重新生成该产物',
  scientific: '改变科学参数，需要重新计算并确认结论变化',
  workflow: '改变方法或流程，需要重新规划下游步骤',
};

function valueOf(
  control: ResultStudioEditControl,
  draft: Record<string, unknown>,
  currentValues: Record<string, unknown>,
): unknown {
  if (Object.prototype.hasOwnProperty.call(draft, control.name)) return draft[control.name];
  if (Object.prototype.hasOwnProperty.call(currentValues, control.name)) return currentValues[control.name];
  return control.default;
}

function isChanged(
  control: ResultStudioEditControl,
  draft: Record<string, unknown>,
  currentValues: Record<string, unknown>,
): boolean {
  if (!Object.prototype.hasOwnProperty.call(draft, control.name)) return false;
  const baseline = Object.prototype.hasOwnProperty.call(currentValues, control.name)
    ? currentValues[control.name]
    : control.default;
  return draft[control.name] !== baseline;
}

export function ResultEditControlField({
  control,
  value,
  onChange,
}: {
  control: ResultStudioEditControl;
  value: unknown;
  onChange: (next: unknown) => void;
}): React.ReactElement {
  const inputId = `rs-edit-${control.name}`;
  if (control.controlType === 'select') {
    return (
      <select
        id={inputId}
        value={String(value ?? '')}
        onChange={(event) => onChange(event.target.value)}
      >
        {(control.options || []).map((option) => (
          <option key={option} value={option}>{option}</option>
        ))}
      </select>
    );
  }
  if (control.controlType === 'boolean') {
    return (
      <input
        id={inputId}
        type="checkbox"
        checked={value === true}
        onChange={(event) => onChange(event.target.checked)}
      />
    );
  }
  if (control.controlType === 'color') {
    return (
      <input
        id={inputId}
        type="color"
        value={typeof value === 'string' && /^#[0-9a-fA-F]{6}$/.test(value) ? value : '#000000'}
        onChange={(event) => onChange(event.target.value.toLowerCase())}
      />
    );
  }
  if (control.controlType === 'number') {
    return (
      <input
        id={inputId}
        type="number"
        value={value === null || value === undefined ? '' : String(value)}
        {...(control.minimum === null || control.minimum === undefined ? {} : { min: control.minimum })}
        {...(control.maximum === null || control.maximum === undefined ? {} : { max: control.maximum })}
        step="any"
        onChange={(event) => {
          const raw = event.target.value;
          onChange(raw === '' ? null : Number(raw));
        }}
      />
    );
  }
  return (
    <input
      id={inputId}
      type="text"
      value={value === null || value === undefined ? '' : String(value)}
      onChange={(event) => onChange(event.target.value)}
    />
  );
}

export function ResultEditPanel({
  editControls,
  disabledReason = null,
  submitting = false,
  onSubmit,
}: {
  editControls: ResultStudioEditControls | null;
  disabledReason?: string | null;
  submitting?: boolean;
  onSubmit: (submission: ResultEditSubmission) => void;
}): React.ReactElement | null {
  const [draft, setDraft] = React.useState<Record<string, unknown>>({});
  const [outcome, setOutcome] = React.useState('');
  const [confirmed, setConfirmed] = React.useState(false);

  const controls = editControls?.controls ?? [];
  const currentValues = editControls?.currentValues ?? {};
  const byName = React.useMemo(
    () => new Map(controls.map((control) => [control.name, control])),
    [controls],
  );

  const changedNames = controls.filter((control) => isChanged(control, draft, currentValues)).map((c) => c.name);
  const patch: Record<string, unknown> = {};
  for (const name of changedNames) patch[name] = draft[name];

  // 影响级别由 descriptor 声明的分组决定，前端不自行推断也不降级。
  const touchesScience = changedNames.some((name) => {
    const group = byName.get(name)?.group;
    return group === 'scientific' || group === 'workflow';
  });
  const needsConfirm = touchesScience;
  const canSubmit = !disabledReason && !submitting && changedNames.length > 0 && (!needsConfirm || confirmed);

  if (!editControls) return null;

  return (
    <section className={styles.panel} aria-label="结果编辑">
      <header className={styles.header}>
        <span>调整这个结果</span>
        {disabledReason && <span className={styles.disabled}>{disabledReason}</span>}
      </header>

      {controls.length === 0 ? (
        <p className={styles.empty}>该插件没有声明可编辑参数，因此这里不提供控件。</p>
      ) : (
        (editControls.groups || []).map((group) => (
          <fieldset key={group.group} className={styles.group} data-group={group.group}>
            <legend>
              {group.label}
              <span className={styles.groupHint}>{GROUP_HINTS[group.group] || ''}</span>
            </legend>
            {group.parameterNames.map((name) => {
              const control = byName.get(name);
              if (!control) return null;
              const value = valueOf(control, draft, currentValues);
              return (
                <label key={name} className={styles.field} data-changed={isChanged(control, draft, currentValues)}>
                  <span className={styles.fieldName}>{name}</span>
                  <ResultEditControlField
                    control={control}
                    value={value}
                    onChange={(next) => setDraft((prev) => ({ ...prev, [name]: next }))}
                  />
                </label>
              );
            })}
          </fieldset>
        ))
      )}

      <label className={styles.outcome}>
        <span>这次修改想达到什么效果</span>
        <input
          type="text"
          value={outcome}
          placeholder="例如：把上调基因换成更深的红色"
          onChange={(event) => setOutcome(event.target.value)}
        />
      </label>

      {changedNames.length > 0 && (
        <p className={styles.impact} role="status" data-science={touchesScience}>
          {touchesScience
            ? `将修改 ${changedNames.length} 个参数，其中包含科学或流程参数，需要重新计算并确认结论变化。`
            : `将修改 ${changedNames.length} 个参数，只影响呈现，不重新计算科学结论。`}
        </p>
      )}

      {needsConfirm && (
        <label className={styles.confirm}>
          <input
            type="checkbox"
            checked={confirmed}
            onChange={(event) => setConfirmed(event.target.checked)}
          />
          <span>我已理解这会改变科学结论，确认继续</span>
        </label>
      )}

      <div className={styles.actions}>
        <button className="petri-btn petri-btn--ghost petri-btn--sm"
          type="button"
          disabled={!canSubmit}
          onClick={() => onSubmit({
            origin: 'manual',
            completionExpectation: 'candidate',
            requestedOutcome: outcome.trim() || `调整 ${changedNames.join('、')}`,
            parameterPatch: patch,
            scientificConfirmed: needsConfirm && confirmed,
          })}
        >
          <Icon name="sparkles" size={13} />
          生成候选版本
        </button>
        <button
          type="button"
          className={styles.reset}
          disabled={changedNames.length === 0 || submitting}
          onClick={() => { setDraft({}); setConfirmed(false); }}
        >
          放弃改动
        </button>
      </div>

    </section>
  );
}

/**
 * P4R-3 — P4 Core 参数面板的产品位置。
 *
 * 使用原生 details 保留键盘/读屏语义，默认关闭；抽屉只改变显著性，
 * 不改变 ResultEditPanel 的提交结构或科学确认边界。
 */
export function ResultEditAdvancedDrawer({
  editControls,
  disabledReason = null,
  submitting = false,
  onSubmit,
}: {
  editControls: ResultStudioEditControls | null;
  disabledReason?: string | null;
  submitting?: boolean;
  onSubmit: (submission: ResultEditSubmission) => void;
}): React.ReactElement | null {
  if (!editControls) return null;
  return (
    <details className={styles.advancedDrawer} aria-label="高级精细调整">
      <summary>
        <span>高级精细调整</span>
        <small>按插件参数逐项控制</small>
      </summary>
      <ResultEditPanel
        editControls={editControls}
        disabledReason={disabledReason}
        submitting={submitting}
        onSubmit={onSubmit}
      />
    </details>
  );
}

