// ============================================================
// WindowShell — BLOCK-59 P1 弹出窗最小 chrome
//
// 独立窗（/window/* 路由）共用的外壳：可拖拽标题区 + 收回 / ×。
// × 永远是降格（minimizeToRail → 主进程 hide，窗口保活，plan §3
// 不可变契约）；收回（returnToDock）销毁 BrowserWindow，内容回主窗。
// 非 Electron 环境（纯浏览器直开路由）诚实降级：只提示，不出按钮。
// ============================================================
import React, { useEffect, useState } from 'react';
import { getBridge } from '@/lib/desktopBridge';
import styles from './window-shell.module.css';

export function WindowShell({
  title,
  subtitle,
  badge = '独立窗 · 只读',
  closeBehavior = 'rail',
  children,
}: {
  title: string;
  subtitle?: string | null;
  badge?: string;
  /** 'rail'（默认）：× = 降格进轨道（不可变契约）；'close'：× = 直接关闭
   *  （无状态单例，如指挥中心，plan §4.1）。close 形态不显示「收回」。 */
  closeBehavior?: 'rail' | 'close';
  children: React.ReactNode;
}): React.ReactElement {
  const [contentId, setContentId] = useState<string | null>(null);
  const [bridgeMissing, setBridgeMissing] = useState(false);
  const [actionError, setActionError] = useState('');

  useEffect(() => {
    const bridge = getBridge('windowManager');
    if (!bridge) {
      setBridgeMissing(true);
      return;
    }
    let cancelled = false;
    bridge
      .self()
      .then((res) => {
        if (cancelled) return;
        if (res.ok && res.contentId) setContentId(res.contentId);
        else setBridgeMissing(true);
      })
      .catch(() => setBridgeMissing(true));
    return () => {
      cancelled = true;
    };
  }, []);

  const handleReturn = async () => {
    if (!contentId) return;
    setActionError('');
    const bridge = getBridge('windowManager');
    const res = await bridge?.returnToDock(contentId);
    if (res && !res.ok) setActionError(res.error || '收回失败');
  };

  const handleDemote = async () => {
    setActionError('');
    if (closeBehavior === 'close') {
      // 无状态单例：× 即真关闭（适配器不拦截 closeBehavior 'close'）
      try { window.close(); } catch {}
      return;
    }
    if (!contentId) return;
    const bridge = getBridge('windowManager');
    const res = await bridge?.minimizeToRail(contentId);
    if (res && !res.ok) setActionError(res.error || '降格失败');
  };

  return (
    <div className={styles.shell}>
      <header className={styles.header} data-drag-region="">
        <div className={styles.titleGroup}>
          <span className={styles.badge}>{badge}</span>
          <strong className={styles.title} title={title}>{title}</strong>
          {subtitle && <span className={styles.subtitle}>{subtitle}</span>}
        </div>
        <div className={styles.actions} data-no-drag-region="">
          {actionError && <span className={styles.actionError}>{actionError}</span>}
          {closeBehavior === 'rail' && contentId && !bridgeMissing && (
            <button
              type="button"
              className={styles.actionBtn}
              onClick={() => void handleReturn()}
              title="收回主窗（独立窗关闭，内容回主窗）"
            >
              收回
            </button>
          )}
          {(!bridgeMissing || closeBehavior === 'close') && (
            <button
              type="button"
              className={`${styles.actionBtn} ${styles.demoteBtn}`}
              onClick={() => void handleDemote()}
              title={closeBehavior === 'close' ? '关闭指挥中心（无状态单例，随开随关）' : '降格到边缘活动轨道（不销毁，可从轨道恢复）'}
              aria-label={closeBehavior === 'close' ? '关闭指挥中心' : '降格到活动轨道'}
            >
              ×
            </button>
          )}
        </div>
      </header>
      {bridgeMissing && (
        <div className={styles.degradedNote} role="note">
          当前环境不支持独立窗管理（仅桌面版可用）；内容以只读视图展示。
        </div>
      )}
      <div className={styles.body}>{children}</div>
    </div>
  );
}

// ============================================================
// AgentRunPanel — UI-385：子智能体实时详情面板（右栏 tab 承载）。
//
// 自 AgentWindowPage（BLOCK-59 P4 / BLOCK-65 P1-a）提取：数据全部来自
// /api/ai/agent/task/:taskId 既有 SSE（task_events 回放 + 实时推送，
// 复用 copilotClient subscribeAgentTask——与主窗同一订阅路径）；交互
// 完整保留：中断（两步确认）/ 留言（队列语义）/ 继续派（沿用父链/
// 模型/权限）。
//
// UI-385（用户裁决）：子智能体详情不再弹独立窗——续派产生的新 agent
// 经 onSpawnedAgent 回调交由宿主（右栏 tab 切换），独立窗路线退役。
// ============================================================
import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import {
  subscribeAgentTask,
  cancelAgentTask,
  fetchAgentTaskMeta,
  sendAgentTaskMessage,
  followupAgentTask,
  type ToolCallEvent,
  type ToolResultEvent,
} from '@/components/copilot/copilotClient';
import { resolveAgentCategory } from '@/lib/agentCategories';
import { Icon } from '@/components/icons/Icon';
import styles from '@/pages/window/command-center.module.css';
import shellStyles from '@/components/window/window-shell.module.css';

interface TimelineEntry {
  key: string;
  name: string;
  status: 'running' | 'success' | 'error' | 'denied';
  durationMs?: number;
}

const MAX_TIMELINE = 200;
const MAX_SUMMARY_CHARS = 8000;

type RunState = 'running' | 'done' | 'failed' | 'cancelled';

const STATE_LABEL: Record<RunState, string> = {
  running: '运行中',
  done: '已完成',
  failed: '失败',
  cancelled: '已取消',
};

function runStateFromStatus(status: string | null | undefined): RunState {
  if (status === 'completed' || status === 'done') return 'done';
  if (status === 'failed') return 'failed';
  if (status === 'cancelled') return 'cancelled';
  return 'running';
}

export function AgentRunPanel({
  runId,
  onSpawnedAgent,
}: {
  runId: string;
  /** 续派成功后回调（宿主切换面板到新 agent；不再弹独立窗）。 */
  onSpawnedAgent?: (agentId: string) => void;
}): React.ReactElement {
  const [runState, setRunState] = useState<RunState>('running');
  const [taskText, setTaskText] = useState('');
  const [conversationTitle, setConversationTitle] = useState('');
  // BLOCK-93 P2 — 显式 spawn role（meta 拉取；未指定=空 → 文本推断兜底）
  const [taskRole, setTaskRole] = useState('');
  const [statusLine, setStatusLine] = useState('事件流连接中…');
  const [timeline, setTimeline] = useState<TimelineEntry[]>([]);
  const [summary, setSummary] = useState('');
  const [errorText, setErrorText] = useState('');
  const [streamError, setStreamError] = useState('');
  const [actionNote, setActionNote] = useState('');
  const [actionError, setActionError] = useState('');
  const [interruptArmed, setInterruptArmed] = useState(false);
  // UI-404 — 分区折叠：运行中默认展开（时间线/中断是实时价值），终态默认收起（回看场景主展示需求+终态摘要）；
  // 用户点击后 override 记忆本次挂载内的选择。
  const [actionsOpenOverride, setActionsOpenOverride] = useState<boolean | null>(null);
  const [timelineOpenOverride, setTimelineOpenOverride] = useState<boolean | null>(null);
  const [messageDraft, setMessageDraft] = useState('');
  const [messageSending, setMessageSending] = useState(false);
  const [followupDraft, setFollowupDraft] = useState('');
  const [followupSending, setFollowupSending] = useState(false);

  // 订阅参数经 ref 稳定（避免 effect 重入导致重复订阅）；累积器走 ref，
  // 渲染状态节流提交。
  const summaryRef = useRef('');
  const summaryFlushTimer = useRef<number | null>(null);

  // meta 拉取——task 描述 + 权威初始状态
  useEffect(() => {
    if (!runId) return;
    let alive = true;
    void fetchAgentTaskMeta(runId)
      .then((meta) => {
        if (!alive) return;
        setTaskText(String(meta.taskText || ''));
        setConversationTitle(String((meta as { conversationTitle?: string }).conversationTitle || ''));
        setTaskRole(String((meta as { role?: string }).role || ''));
        setRunState(runStateFromStatus(meta.status));
      })
      .catch(() => {});
    return () => {
      alive = false;
    };
  }, [runId]);

  // 两步中断的武装态 3s 自动解除
  useEffect(() => {
    if (!interruptArmed) return;
    const timer = window.setTimeout(() => setInterruptArmed(false), 3000);
    return () => window.clearTimeout(timer);
  }, [interruptArmed]);

  useEffect(() => {
    if (!runId) return;
    let cancelled = false;
    const flushSummary = () => {
      if (summaryFlushTimer.current != null) return;
      summaryFlushTimer.current = window.setTimeout(() => {
        summaryFlushTimer.current = null;
        setSummary(summaryRef.current.slice(0, MAX_SUMMARY_CHARS));
      }, 200);
    };

    const upsertTimeline = (entry: TimelineEntry) => {
      setTimeline((prev) => {
        const index = prev.findIndex((item) => item.key === entry.key);
        if (index >= 0) {
          const next = prev.slice();
          next[index] = { ...next[index], ...entry };
          return next;
        }
        const next = [...prev, entry];
        return next.length > MAX_TIMELINE ? next.slice(next.length - MAX_TIMELINE) : next;
      });
    };

    subscribeAgentTask(runId, {
      messages: [],
      onDelta: (delta: string) => {
        if (cancelled || !delta) return;
        summaryRef.current += delta;
        flushSummary();
      },
      onAgentStatus: (info: { phase: string; message: string }) => {
        if (cancelled) return;
        setStatusLine(info.message || info.phase || statusLine);
      },
      onAgentProgress: (info: { iteration: number; content: string }) => {
        if (cancelled) return;
        setStatusLine(info.content.slice(0, 160));
      },
      onToolCall: (event: ToolCallEvent) => {
        if (cancelled) return;
        upsertTimeline({
          key: event.callId || `${event.name}:${event.traceId || 'legacy'}`,
          name: event.name,
          status: 'running',
        });
      },
      onToolResult: (event: ToolResultEvent) => {
        if (cancelled) return;
        const result = event.toolResult;
        upsertTimeline({
          key: result?.callId || event.name,
          name: result?.tool || event.name,
          status: result?.status === 'error' || result?.status === 'denied' ? result.status : 'success',
          durationMs: result?.durationMs,
        });
      },
      onDone: () => {
        if (cancelled) return;
        setRunState('done');
        setStatusLine('任务完成');
      },
      onError: (err: Error) => {
        if (cancelled) return;
        setRunState('failed');
        setErrorText(err.message || '任务失败');
      },
    }).catch((e: unknown) => {
      if (cancelled) return;
      // 终态已由 onDone/onError 表达；此处仅覆盖流本身断开等异常
      setStreamError(e instanceof Error ? e.message : '事件流连接失败');
    });

    return () => {
      cancelled = true;
      if (summaryFlushTimer.current != null) {
        window.clearTimeout(summaryFlushTimer.current);
        setSummary(summaryRef.current.slice(0, MAX_SUMMARY_CHARS));
      }
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [runId]);

  const handleInterrupt = useCallback(async () => {
    if (!runId || !interruptArmed) return;
    setActionError('');
    setActionNote('');
    setInterruptArmed(false);
    try {
      await cancelAgentTask(runId);
      setActionNote('中断请求已发出：子 agent 将在下一个取消检查点让出（级联覆盖其派生链）。');
      setRunState('cancelled');
      setStatusLine('已请求中断');
    } catch (e) {
      setActionError(e instanceof Error ? e.message : '中断失败');
    }
  }, [runId, interruptArmed]);

  const handleSendMessage = useCallback(async () => {
    const text = messageDraft.trim();
    if (!runId || !text || messageSending) return;
    setMessageSending(true);
    setActionError('');
    setActionNote('');
    try {
      const result = await sendAgentTaskMessage(runId, text);
      setActionNote(result.note);
      setMessageDraft('');
    } catch (e) {
      setActionError(e instanceof Error ? e.message : '留言失败');
    } finally {
      setMessageSending(false);
    }
  }, [runId, messageDraft, messageSending]);

  const handleFollowup = useCallback(async () => {
    const text = followupDraft.trim();
    if (!runId || !text || followupSending) return;
    setFollowupSending(true);
    setActionError('');
    setActionNote('');
    try {
      const result = await followupAgentTask(runId, text);
      setActionNote(`已续派为新子 agent ${result.agentId.slice(0, 8)}（沿用父链/模型/权限），右栏已切换到新任务。`);
      setFollowupDraft('');
      onSpawnedAgent?.(result.agentId);
    } catch (e) {
      setActionError(e instanceof Error ? e.message : '续派失败');
    } finally {
      setFollowupSending(false);
    }
  }, [runId, followupDraft, followupSending, onSpawnedAgent]);

  const timelineView = useMemo(() => timeline.slice(-MAX_TIMELINE), [timeline]);

  // UI-404 — 折叠派生：override ?? (运行中展开 / 终态收起)
  const running = runState === 'running';
  const actionsOpen = actionsOpenOverride ?? running;
  const timelineOpen = timelineOpenOverride ?? running;
  const failedCalls = timeline.filter((t) => t.status === 'error' || t.status === 'denied').length;

  return (
    <div className={styles.agentBody}>
      <div className={styles.agentStatusRow}>
        {/* UI-387 — 面板头带职能图标（类别推断）+ 任务描述 */}
        <span className={shellStyles.statusChip} data-status="done" title={`职能：${resolveAgentCategory(taskRole, taskText).label}`}>
          <span aria-hidden="true">{resolveAgentCategory(taskRole, taskText).emoji}</span>
        </span>
        <span className={styles.agentTaskTextFull} title={taskText}>
          {taskText ? taskText.replace(/\s+/g, ' ').trim() : `Agent ${runId.slice(0, 8)}`}
        </span>
        <span className={shellStyles.statusChip} data-status={runState === 'running' ? 'running' : runState === 'failed' ? 'failed' : 'done'}>
          {STATE_LABEL[runState]}
        </span>
        <span className={styles.agentStatusLine}>{statusLine}</span>
        {(conversationTitle || taskText) && (
          <span className={styles.agentParentLine} data-testid="agent-parent-conversation">
            父会话：{conversationTitle || '（未命名会话）'}
          </span>
        )}
      </div>
      {streamError && <div className={styles.loadError} role="alert">事件流断开：{streamError}</div>}
      {errorText && <div className={styles.loadError} role="alert">{errorText}</div>}
      {actionNote && <div className={styles.drillNote} role="status">{actionNote}</div>}
      {actionError && <div className={styles.loadError} role="alert">{actionError}</div>}

      {/* BLOCK-65 P1-a — 交互区（UI-404：终态默认收起，运行中默认展开；点击标题切换） */}
      <section className={styles.agentSection} data-testid="agent-run-actions">
        <button
          type="button"
          className={styles.agentSectionToggle}
          aria-expanded={actionsOpen}
          onClick={() => setActionsOpenOverride(!actionsOpen)}
        >
          <Icon name={actionsOpen ? 'chevron-down' : 'chevron-right'} size={12} />
          <h3 className={styles.agentSectionTitle}>操作</h3>
        </button>
        {actionsOpen && (
          <>
            <div className={styles.actionBar}>
              {runState === 'running' && (
                interruptArmed ? (
                  <button
                    type="button"
                    className={styles.cancelArmBtn}
                    onClick={() => void handleInterrupt()}
                    title="再次点击确认中断（3 秒后自动还原）；级联覆盖该 agent 派生链"
                  >
                    确认中断？
                  </button>
                ) : (
                  <button
                    type="button"
                    className={styles.actionBtn}
                    onClick={() => setInterruptArmed(true)}
                  >
                    中断
                  </button>
                )
              )}
            </div>
            {runState === 'running' && (
              <div className={styles.composer}>
                <textarea
                  className={styles.composerInput}
                  value={messageDraft}
                  onChange={(e) => setMessageDraft(e.target.value)}
                  placeholder="给这个 agent 留言（队列语义：运行中不即时注入，将在「继续派」续派时作为上下文注入）"
                  rows={2}
                />
                <button
                  type="button"
                  className={styles.actionBtn}
                  disabled={!messageDraft.trim() || messageSending}
                  onClick={() => void handleSendMessage()}
                >
                  {messageSending ? '入队中…' : '留言'}
                </button>
              </div>
            )}
            {(runState === 'done' || runState === 'failed' || runState === 'cancelled') && (
              <div className={styles.composer}>
                <textarea
                  className={styles.composerInput}
                  value={followupDraft}
                  onChange={(e) => setFollowupDraft(e.target.value)}
                  placeholder="追加新任务（基于前情续派：沿用父链 / 模型 / 权限，成功后右栏切换到新任务）"
                  rows={2}
                />
                <button
                  type="button"
                  className={styles.actionBtn}
                  disabled={!followupDraft.trim() || followupSending}
                  onClick={() => void handleFollowup()}
                >
                  {followupSending ? '续派中…' : '继续派'}
                </button>
              </div>
            )}
          </>
        )}
      </section>

      <section className={styles.agentSection}>
        <button
          type="button"
          className={styles.agentSectionToggle}
          aria-expanded={timelineOpen}
          onClick={() => setTimelineOpenOverride(!timelineOpen)}
        >
          <Icon name={timelineOpen ? 'chevron-down' : 'chevron-right'} size={12} />
          <h3 className={styles.agentSectionTitle} data-testid="agent-timeline-title">
            实时工作流（工具调用时间线）· {timeline.length} 次调用
            {failedCalls > 0 ? ` · ${failedCalls} 异常` : ''}
          </h3>
        </button>
        {timelineOpen && (
          timelineView.length === 0 ? (
            <div className={styles.empty}>暂无工具调用记录。</div>
          ) : (
            <ul className={styles.timeline}>
              {timelineView.map((item) => (
                <li key={item.key} className={styles.timelineRow} data-status={item.status}>
                  <span className={styles.timelineDot} data-status={item.status} />
                  <code className={styles.timelineName}>{item.name}</code>
                  <span className={styles.timelineStatus}>
                    {item.status === 'running'
                      ? '运行中'
                      : item.status === 'error'
                        ? '失败'
                        : item.status === 'denied'
                          ? '已拒绝'
                          : '完成'}
                    {typeof item.durationMs === 'number' ? ` · ${(item.durationMs / 1000).toFixed(1)}s` : ''}
                  </span>
                </li>
              ))}
            </ul>
          )
        )}
      </section>
      <section className={styles.agentSection}>
        <h3 className={styles.agentSectionTitle}>终态摘要（与父会话同源）</h3>
        {summary ? (
          <pre className={styles.agentSummary}>{summary}</pre>
        ) : (
          <div className={styles.empty}>{runState === 'running' ? '等待模型输出…' : '该任务没有文本输出。'}</div>
        )}
      </section>
    </div>
  );
}

import React from 'react';
import { Icon } from '@/components/icons/Icon';
import type { CatalogTool } from '@/lib/tool-catalog';
import styles from '@/pages/project-workspace.module.css';

function groupByCategory(tools: CatalogTool[]): Array<{ category: string; items: CatalogTool[] }> {
  const map = new Map<string, CatalogTool[]>();
  for (const tool of tools) {
    if (!map.has(tool.category)) map.set(tool.category, []);
    map.get(tool.category)!.push(tool);
  }
  return [...map.entries()].map(([category, items]) => ({ category, items }));
}

export interface AnalysisLaunchPanelProps {
  tools: CatalogTool[];
  onLaunch: (tool: CatalogTool) => void;
  /** 目录尚在拉取中（区别于「已确认无插件」）。 */
  loading?: boolean;
}

/**
 * UI-147 / T84 — 分析入口面板：工作台内统一的分析启动/编排入口。
 * 把分散在 DataIntakeControl「开始分析」与聊天框输入里的分析启动能力，
 * 收敛为一个可发现、按类别分组、可一键启动的分析目录。点击「运行」即把
 * 该分析作为请求发送给 Agent（onLaunch），由 Agent 负责数据就绪检查与执行。
 * 仅依赖 props 与 onLaunch 回调，不持有状态、不反向依赖 RightPanel。
 *
 * BLOCK-83 D4：目录内容投影自已装插件（不再是核心内置清单）——零插件时
 * 渲染诚实空态，不伪造条目。
 */
export function AnalysisLaunchPanel({ tools, onLaunch, loading = false }: AnalysisLaunchPanelProps): React.ReactElement {
  const groups = React.useMemo(() => groupByCategory(tools), [tools]);
  const isEmpty = tools.length === 0;

  return (
    <div className={styles.analysisLaunch}>
      <header className={styles.analysisLaunchHeader}>
        <strong>分析入口</strong>
        <span className={styles.analysisLaunchHint}>选择一项分析，发给 Agent 运行</span>
      </header>
      {isEmpty ? (
        <p className={styles.panelEmpty} data-testid="analysis-launch-empty">
          {loading ? '正在加载分析插件…' : '当前未安装分析插件。安装插件后，其分析项会自动出现在这里。'}
        </p>
      ) : (
        <div className={styles.analysisLaunchList}>
          {groups.map((group) => (
            <section key={group.category} className={styles.analysisLaunchGroup}>
              <h4 className={styles.analysisLaunchGroupTitle}>{group.category}</h4>
              <ul className={styles.analysisLaunchCards}>
                {group.items.map((tool) => (
                  <li key={tool.id}>
                    <div className={styles.analysisLaunchCard}>
                      <div className={styles.analysisLaunchCardMain}>
                        <span className={styles.analysisLaunchCardTitle}>
                          <span
                            className={styles.analysisLaunchDot}
                            style={{ background: tool.color || 'var(--petri-accent, #3b82f6)' }}
                            aria-hidden
                          />
                          {tool.title}
                        </span>
                        <span className={styles.analysisLaunchCardDesc}>{tool.description}</span>
                        <span className={styles.analysisLaunchCardMeta}>
                          {tool.language ? (
                            <span className={styles.analysisLaunchLang} data-lang={tool.language}>
                              {tool.language.toUpperCase()}
                            </span>
                          ) : null}
                          {tool.estimatedMinutes == null ? null : <span>约 {tool.estimatedMinutes} 分钟</span>}
                        </span>
                      </div>
                      <button
                        type="button"
                        className={styles.analysisLaunchRun}
                        disabled={tool.comingSoon}
                        onClick={() => onLaunch(tool)}
                      >
                        {tool.comingSoon ? '即将推出' : '运行'}
                      </button>
                    </div>
                  </li>
                ))}
              </ul>
            </section>
          ))}
        </div>
      )}
    </div>
  );
}

import React, { useEffect } from 'react';
import { Icon } from '@/components/icons/Icon';
import { useTerminalTabs } from '@/hooks/useTerminalTabs';
import { terminalTabLabel, terminalTabSubtitle } from '@/hooks/terminalTabs';
import { useTheme } from '@/themes/ThemeProvider';
import { getBridge } from '@/lib/desktopBridge';
import styles from '@/pages/project-workspace.module.css';

export interface BottomTerminalProps {
  open: boolean;
  height: number;
  /** number 或 CSS var() 字符串（UI-309 拖动期实时跟随侧栏宽度） */
  leftOffset: number | string;
  rightOffset: number | string;
  workspacePath?: string;
  /** BLOCK-67：SSH 远程项目终端（ssh pty 直挂）。 */
  ssh?: { alias: string; remotePath: string };
  onResize: (event: React.MouseEvent) => void;
  onClose: () => void;
}

/**
 * BLOCK-54 P2 — 底部多 Tab 终端面板。
 *
 * - 每个 tab 独立 xterm 实例与 node-pty 会话（会话归 `useTerminalTabs` 管），
 *   本组件只负责布局、tab 条与清空/关闭面板等 affordance。
 * - 打开面板且无 tab 时自动开第一个（保持旧单终端「打开即用」体验）。
 * - 上限 4：后端 terminal.js 与前端 terminalTabs.ts 双端同值，第 5 个诚实拒绝。
 * - UI-363（用户裁决：外层「终端 新标签/清空/×」标题行冗余）——砍掉独立
 *   header，对标 VS Code 面板单行布局：tab 与「+」居左，清空/关闭面板居右。
 *   面板开关仍可经顶栏「底部终端」toggle 与 Ctrl/Cmd+`。
 */
export function BottomTerminal({
  open,
  height,
  leftOffset,
  rightOffset,
  workspacePath,
  ssh,
  onResize,
  onClose,
}: BottomTerminalProps): React.ReactElement {
  const { resolvedTheme } = useTheme();
  // BLOCK-59 P2 — 终端 Tab 升格为独立窗（同一会话第二活视图，主窗 tab 保活）
  const windowManagerBridge = getBridge('windowManager');
  const {
    tabs,
    activeId,
    setActive,
    openTab,
    closeTab,
    registerHost,
    limitNotice,
    dismissLimitNotice,
    clear,
    runningBy,
  } = useTerminalTabs({ open, workspacePath, ssh, theme: resolvedTheme });

  // 打开面板且尚无任何 tab → 自动开第一个（懒启动，此刻才拉起 pty）。
  useEffect(() => {
    if (open && tabs.length === 0) openTab();
  }, [open, tabs.length, openTab]);

  // 上限提示 4s 自动消隐。
  useEffect(() => {
    if (!limitNotice) return undefined;
    const handle = window.setTimeout(dismissLimitNotice, 4000);
    return () => window.clearTimeout(handle);
  }, [limitNotice, dismissLimitNotice]);

  return (
    <section
      className={`${styles.embeddedTerminal} ${open ? styles.embeddedTerminalOpen : ''}`}
      style={{ height: open ? height : 0, left: leftOffset, right: rightOffset }}
      aria-hidden={!open}
      data-petri-motion="functional"
    >
      <div className={styles.embeddedTerminalResize} onMouseDown={onResize} />
      <div className={styles.embeddedTerminalTabs} role="tablist" aria-label="终端标签">
        {tabs.map((tab) => {
          const isActive = tab.id === activeId;
          const label = terminalTabLabel(tab);
          return (
            <div
              key={tab.id}
              className={`${styles.embeddedTerminalTab} ${isActive ? styles.embeddedTerminalTabActive : ''}`}
              data-exited={tab.exited ? 'true' : 'false'}
            >
              <button
                type="button"
                role="tab"
                aria-selected={isActive}
                title={tab.cwd || label}
                className={styles.embeddedTerminalTabLabel}
                onClick={() => setActive(tab.id)}
              >
                <span
                  aria-hidden
                  className={styles.embeddedTerminalTabDot}
                  data-running={runningBy[tab.id] ? 'true' : 'false'}
                />
                <span>{label}</span>
                {terminalTabSubtitle(tab) ? (
                  <small>{terminalTabSubtitle(tab)}</small>
                ) : null}
              </button>
              {windowManagerBridge && (
                <button
                  type="button"
                  className={styles.embeddedTerminalTabClose}
                  aria-label={`升格 ${label} 为独立窗`}
                  title="升格为独立窗（同一会话第二视图，主窗标签保活）"
                  onClick={() => void windowManagerBridge!.popOut('terminal', tab.id)}
                >
                  <Icon name="arrow-right" size={10} />
                </button>
              )}
              <button
                type="button"
                className={styles.embeddedTerminalTabClose}
                aria-label={`关闭 ${label}`}
                onClick={() => closeTab(tab.id)}
              >
                <Icon name="x" size={10} />
              </button>
            </div>
          );
        })}
        <button
          type="button"
          className={styles.embeddedTerminalTabAdd}
          aria-label="新建终端标签"
          title={tabs.length >= 4 ? '最多同时打开 4 个终端标签' : '新建终端标签'}
          onClick={openTab}
        >
          <Icon name="plus" size={12} />
        </button>
        <div className={styles.embeddedTerminalTabActions}>
          {limitNotice ? (
            <span className={styles.embeddedTerminalNotice} role="status">
              {limitNotice}
            </span>
          ) : null}
          <button className="petri-btn petri-btn--ghost petri-btn--sm" type="button" onClick={clear}>清空</button>
          <button className="petri-btn petri-btn--icon" type="button" onClick={onClose} aria-label="关闭终端面板" title="关闭终端面板">
            <Icon name="x" size={13} />
          </button>
        </div>
      </div>
      <div className={styles.embeddedTerminalBody}>
        {tabs.map((tab) => (
          <div
            key={tab.id}
            ref={registerHost(tab.id)}
            className={`${styles.embeddedTerminalHost} ${tab.id === activeId ? '' : styles.embeddedTerminalHostHidden}`}
            data-tab-body={tab.id}
            aria-hidden={tab.id !== activeId}
          />
        ))}
      </div>
    </section>
  );
}

