                )}
                {/* BLOCK-72 / UI-320 — 「知识空间」「后端」tab 已迁出右栏：设备级全局能力，
                    管理面在左栏工作台入口的 /knowledge 与 /backend 全局页；不预留空壳。 */}
              </div>
            ))}
          </div>
        </div>
      </aside>
    </>
  );
}

/**
