    },
    iterations: [{
      iterationId: 'iteration-1',
      loopRunId: 'loop-1',
      sequence: 1,
      decision: 'continue',
      decisionReasonCode: 'TOOL_SUCCEEDED',
      status: 'succeeded',
      publicConclusion: '质控完成',
      createdAt: '2026-07-24T00:01:00.000Z',
    }],
    activeCount: 2,
    backgroundCount: 1,
    usage: {
      calls: 2,
