// ============================================================
// usePluginStore — SWR-style hook for the plugin store
// (installed list + remote manifest + runtime status).
//
// State-decomposition §4.6 [HIGH] flagged that the plugin
// catalog lived in three independent `useState` caches:
//
//   - PluginStorePanel.tsx   (line 94-96 pre-commit, lists +
//                             runtimeStatus + checkUpdates
//                             on mount).
//   - project-workspace.tsx ToolboxPanel (~line 2020-2025
//                             pre-commit, lists only).
//
// Both components called
// `window.petriDesktop.plugins.listInstalled()` +
// `listRemote()` on mount and held their own snapshot. When
// one panel installed or uninstalled a plugin, the other
// panel's list stayed stale until the user toggled its tab
// or remounted the workspace. The hook replaces both caches
// and shares them via a module-level listener fan-out.
//
// Per-call UI state (install / uninstall spinner flags,
// progress bar by pluginId, last-installed runtime banner)
// stays in the caller; these are intrinsically per-action
// concerns, not shared catalog data.
// ============================================================

import { useCallback, useEffect, useState } from 'react';
import { getBridge } from '@/lib/desktopBridge';

// Types — exported so callers don't re-declare them inline
// (the project's existing `RemotePlugin` lives in electron.d.ts;
// the two inline copies in PluginStorePanel / project-workspace
// ToolboxPanel are now replaced by this central one).
export interface PluginInstallProgress {
  ratio: number;
  received: number;
  total: number;
}

export interface InstalledPlugin {
  id: string;
  version: string;
  installedAt?: string;
  type?: string;
  language?: string;
  scriptFingerprint?: string | null;
  installedFingerprint?: string | null;
  currentFingerprint?: string | null;
  manifestDrift?: boolean;
  driftReason?: string | null;
}

export interface RemotePlugin {
  title?: string;
  version?: string;
  language?: string;
  size?: number;
  description?: string;
  type?: string;
  dependencies?: string[];
  optional?: boolean;
}

export interface RuntimeStatus {
  r: { installed: boolean; path: string | null };
  python: { installed: boolean; path: string | null };
}

export interface UpdateInfo {
  id: string;
  currentVersion: string;
  latestVersion: string;
  changelog?: string;
  size?: number;
}

interface PluginManifest {
  plugins: Record<string, RemotePlugin>;
}

interface PluginStoreSnapshot {
  installed: InstalledPlugin[];
  remote: PluginManifest;
  runtimeStatus: RuntimeStatus | null;
}

// Plan 1.6 §4.7 [HIGH] — drop the hand-rolled `PluginBridge`
// interface and the inline `getBridge()` helper. The canonical
// bridge shape lives in `@/lib/electron.d.ts` and the typed
// accessor lives in `@/lib/desktopBridge`. Hook now just
// calls `getBridge('plugins')` and gets the proper return
// type automatically.

let cache: PluginStoreSnapshot = { installed: [], remote: { plugins: {} }, runtimeStatus: null };
let loaded = false;
let inflight: Promise<PluginStoreSnapshot> | null = null;
let updatesInflight: Promise<void> | null = null;
let updatesCache: UpdateInfo[] = [];
const subscribers = new Set<() => void>();

function notify(): void {
  subscribers.forEach((fn) => fn());
}

async function refreshAllCore(): Promise<PluginStoreSnapshot> {
  if (inflight) return inflight;
  const bridge = getBridge('plugins');
  if (!bridge) return cache;
  inflight = (async () => {
    const [inst, rem] = await Promise.all([
      bridge.listInstalled().catch(() => []),
      bridge.listRemote().catch(() => ({ plugins: {} })),
    ]);
    const runtime = getBridge('runtime');
    const rt = (await runtime?.status?.().catch(() => null)) ?? null;
    cache = { installed: inst, remote: rem, runtimeStatus: rt };
    loaded = true;
    notify();
    return cache;
  })().finally(() => {
    inflight = null;
  });
  return inflight;
}

async function refreshUpdates(): Promise<void> {
  const bridge = getBridge('plugins');
  if (!bridge?.checkUpdates) return;
  if (updatesInflight) return updatesInflight;
  updatesInflight = bridge
    .checkUpdates()
    .then((result) => {
      updatesCache = Array.isArray(result) ? result : [];
      notify();
    })
    .catch(() => {
      /* silent — same as the previous caller behaviour */
    })
    .finally(() => {
      updatesInflight = null;
    });
  return updatesInflight;
}

export interface UsePluginStoreResult {
  installed: InstalledPlugin[];
  remote: PluginManifest;
  runtimeStatus: RuntimeStatus | null;
  updates: UpdateInfo[];
  checkingUpdates: boolean;
  loading: boolean;
  /** Force a full refresh (installed + remote + runtime + updates). */
  refresh: () => Promise<void>;
  /** Force a refresh of just the updates list. */
  checkUpdates: () => Promise<void>;
  /** Install a plugin via the electron bridge. On success the
   *  cache is refreshed and `updates` re-checked. The optional
   *  `onProgress` callback fires with per-byte progress events
   *  for the caller to render a progress bar. */
  install: (
    pluginId: string,
    onProgress?: (data: PluginInstallProgress) => void
  ) => Promise<{ ok: boolean; error?: string }>;
  /** Uninstall a plugin via the electron bridge. Cache refresh
   *  happens on success. */
  uninstall: (pluginId: string) => Promise<{ ok: boolean; error?: string }>;
}

export function usePluginStore(
  opts: {
    /** When true, the hook triggers a full refresh on mount
     *  (listInstalled + listRemote + runtime.status + updates).
     *  Defaults to `true` for the standalone PluginStorePanel.
     *  ToolboxPanel sets this to `false` because the user only
     *  needs the catalog when its "plugins" tab is opened —
     *  saving one roundtrip per workspace mount. */
    autoLoad?: boolean;
  } = {}
): UsePluginStoreResult {
  const { autoLoad = true } = opts;
  const [snapshot, setSnapshot] = useState<PluginStoreSnapshot>(cache);
  const [updates, setUpdates] = useState<UpdateInfo[]>(updatesCache);
  const [checkingUpdates] = useState(false); // kept for API stability
  const [loading, setLoading] = useState(!loaded && autoLoad);

  useEffect(() => {
    let cancelled = false;
    const onChange = () => {
      if (cancelled) return;
      setSnapshot(cache);
      setUpdates(updatesCache);
    };
    subscribers.add(onChange);
    if (autoLoad && !loaded) {
      setLoading(true);
      refreshAllCore().then((next) => {
        if (cancelled) return;
        setSnapshot(next);
        setLoading(false);
      }).catch(() => {
        if (cancelled) return;
        setLoading(false);
      });
    } else if (!autoLoad) {
      setLoading(false);
    }
    return () => {
      cancelled = true;
      subscribers.delete(onChange);
    };
  }, [autoLoad]);

  const refresh = useCallback(async () => {
    setLoading(true);
    await Promise.all([
      refreshAllCore().then((next) => setSnapshot(next)),
      refreshUpdates().then(() => setUpdates(updatesCache)),
    ]);
    setLoading(false);
  }, []);

  const checkUpdates = useCallback(async () => {
    await refreshUpdates();
    setUpdates(updatesCache);
  }, []);

  const install = useCallback(
    async (
      pluginId: string,
      onProgress?: (data: PluginInstallProgress) => void
    ): Promise<{ ok: boolean; error?: string }> => {
      const bridge = getBridge('plugins');
      if (!bridge) return { ok: false, error: 'bridge unavailable' };
      const result = await bridge.install(pluginId, (data) => {
        if (onProgress) {
          onProgress({ ratio: data.ratio, received: data.received, total: data.total });
        }
      });
      if (result.ok) {
        const next = await refreshAllCore();
        setSnapshot(next);
        await refreshUpdates();
        setUpdates(updatesCache);
      }
      return result;
    },
    []
  );

  const uninstall = useCallback(async (pluginId: string) => {
    const bridge = getBridge('plugins');
    if (!bridge) return { ok: false, error: 'bridge unavailable' };
    const result = await bridge.uninstall(pluginId);
    if (result.ok) {
      const next = await refreshAllCore();
      setSnapshot(next);
    }
    return result;
  }, []);

  return {
    installed: snapshot.installed,
    remote: snapshot.remote,
    runtimeStatus: snapshot.runtimeStatus,
    updates,
    checkingUpdates,
    loading,
    refresh,
    checkUpdates,
    install,
    uninstall,
  };
}

/** Test-only helper. */
export function __resetPluginStoreCacheForTests(): void {
  cache = { installed: [], remote: { plugins: {} }, runtimeStatus: null };
  loaded = false;
  inflight = null;
  updatesCache = [];
  updatesInflight = null;
  subscribers.clear();
}

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { act, renderHook, type RenderHookResult } from '@testing-library/react';
import { useResizableColumns } from '@/hooks/useResizableColumns';

const LS_KEY = 'petri-pw-cols';

function flush() {
  return act(async () => {
    await Promise.resolve();
  });
}

function fireMouse(
  target: EventTarget,
  type: string,
  init: { clientX?: number; clientY?: number; buttons?: number } = {},
) {
  const event = new MouseEvent(type, { bubbles: true, ...init });
  target.dispatchEvent(event);
  return event;
}

describe('useResizableColumns', () => {
  beforeEach(() => {
    localStorage.removeItem(LS_KEY);
  });
  afterEach(() => {
    localStorage.removeItem(LS_KEY);
    document.documentElement.style.removeProperty('--petri-live-result-right-width');
  });
  it('exposes sane initial sizes', () => {
    const { result } = renderHook(() => useResizableColumns());
    expect(result.current.leftWidth).toBe(240);
    expect(result.current.rightWidth).toBe(340);
    expect(result.current.resultRightWidth).toBe(720);
    expect(result.current.inputHeight).toBe(120);
    expect(result.current.bottomTerminalHeight).toBe(176);
  });

  it('honors overrides on initial render', () => {
    const { result } = renderHook(() =>
      useResizableColumns({ leftWidth: 200, rightWidth: 400, inputHeight: 80, bottomTerminalHeight: 200 }),
    );
    expect(result.current.leftWidth).toBe(200);
    expect(result.current.rightWidth).toBe(400);
    expect(result.current.inputHeight).toBe(80);
    expect(result.current.bottomTerminalHeight).toBe(200);
  });

  it('resizes the left column with a min of 96', async () => {
    const { result }: RenderHookResult<ReturnType<typeof useResizableColumns>, unknown> =
      renderHook(() => useResizableColumns());
    const handler = result.current.startColumnResize('left');
    const fakeEvent = { preventDefault: () => {}, clientX: 0, clientY: 0 } as unknown as React.MouseEvent;

    await flush();
    handler(fakeEvent);

    fireMouse(document, 'mousemove', { clientX: 300, buttons: 1 });
    fireMouse(document, 'mouseup');
    await flush();
    expect(result.current.leftWidth).toBe(240 + 300);

    // Re-attach and try to drag past the minimum.
    handler(fakeEvent);
    fireMouse(document, 'mousemove', { clientX: -10_000, buttons: 1 });
    fireMouse(document, 'mouseup');
    await flush();
    expect(result.current.leftWidth).toBe(96);
  });

  it('resizes the input height with a min of 48', async () => {
    const { result } = renderHook(() => useResizableColumns());
    const handler = result.current.startColumnResize('input');
    const fakeEvent = { preventDefault: () => {}, clientX: 0, clientY: 0 } as unknown as React.MouseEvent;

    await flush();
    handler(fakeEvent);
    fireMouse(document, 'mousemove', { clientY: 100, buttons: 1 });
    fireMouse(document, 'mouseup');
    await flush();
    // 120 - 100 = 20, but Math.max(48, 20) clamps to 48.
    expect(result.current.inputHeight).toBe(48);

    handler(fakeEvent);
    fireMouse(document, 'mousemove', { clientY: -10_000, buttons: 1 });
    fireMouse(document, 'mouseup');
    await flush();
    // deltaY = -10000, startInput = 48 (clamped), so 48 - (-10000) = 10048.
    expect(result.current.inputHeight).toBe(10048);
  });

  it('toggles body cursor and user-select while dragging', async () => {
    const setCursor = vi.spyOn(document.body.style, 'cursor', 'set');
    const setSelect = vi.spyOn(document.body.style, 'userSelect', 'set');
    const { result } = renderHook(() => useResizableColumns());
    const handler = result.current.startColumnResize('right');
    const fakeEvent = { preventDefault: () => {}, clientX: 0, clientY: 0 } as unknown as React.MouseEvent;

    await flush();
    handler(fakeEvent);
    expect(setCursor).toHaveBeenCalledWith('ew-resize');
    expect(setSelect).toHaveBeenCalledWith('none');
    expect(document.body.classList.contains('petri-resizing-columns')).toBe(true);

    fireMouse(document, 'mouseup');
    expect(setCursor).toHaveBeenCalledWith('');
    expect(setSelect).toHaveBeenCalledWith('');
    expect(document.body.classList.contains('petri-resizing-columns')).toBe(false);
  });

  it('honors caller-supplied clamp on the bottom terminal resize', async () => {
    const { result } = renderHook(() => useResizableColumns({ bottomTerminalHeight: 200 }));
    const fakeEvent = { preventDefault: () => {}, clientY: 0 } as unknown as React.MouseEvent;

    // Plan 1.6 §4.4 — project-workspace passes { min: 140, max: 520 } to
    // keep the bottom terminal from eating the whole viewport. Verify
    // that clamp is applied per drag (using the value at drag-start).
    await flush();
    result.current.startBottomTerminalResize(fakeEvent, { min: 140, max: 520 });

    // Drag up by 800px (clientY = -800) — naive next = 200 - (-800) = 1000 → clamp to max 520.
    fireMouse(document, 'mousemove', { clientY: -800, buttons: 1 });
    fireMouse(document, 'mouseup');
    await flush();
    expect(result.current.bottomTerminalHeight).toBe(520);

    // Drag down by 200px (clientY = +200) — naive next = 520 - 200 = 320 → fits in [140, 520].
    result.current.startBottomTerminalResize(fakeEvent, { min: 140, max: 520 });
    fireMouse(document, 'mousemove', { clientY: 200, buttons: 1 });
    fireMouse(document, 'mouseup');
    await flush();
    expect(result.current.bottomTerminalHeight).toBe(320);

    // Drag down by 10_000px (clientY = +10_000) — naive next = 320 - 10000 = -9680 → clamp to min 140.
    result.current.startBottomTerminalResize(fakeEvent, { min: 140, max: 520 });
    fireMouse(document, 'mousemove', { clientY: 10_000, buttons: 1 });
    fireMouse(document, 'mouseup');
    await flush();
    expect(result.current.bottomTerminalHeight).toBe(140);
  });

  // ---- §3 localStorage persistence ----

  it('writes all panel dims to localStorage on each resize', async () => {
    localStorage.removeItem(LS_KEY);
    const { result } = renderHook(() => useResizableColumns());
    await flush();
    const handler = result.current.startColumnResize('left');
    const fakeEvent = { preventDefault: () => {}, clientX: 0, clientY: 0 } as unknown as React.MouseEvent;
    handler(fakeEvent);
    fireMouse(document, 'mousemove', { clientX: 100, buttons: 1 });
    fireMouse(document, 'mouseup');
    await flush();

    const saved = JSON.parse(localStorage.getItem(LS_KEY) || '{}');
    expect(saved.leftWidth).toBe(340); // 240 + 100
    expect(saved.rightWidth).toBe(340);
    expect(saved.resultRightWidth).toBe(720);
    expect(saved.inputHeight).toBe(120);
    expect(saved.bottomTerminalHeight).toBe(176);
  });

  it('resizes and persists the result panel independently from the standard right panel', async () => {
    const { result } = renderHook(() => useResizableColumns());
    const handler = result.current.startColumnResize('resultRight');
    const fakeEvent = { preventDefault: () => {}, clientX: 0, clientY: 0 } as unknown as React.MouseEvent;

    handler(fakeEvent);
    fireMouse(document, 'mousemove', { clientX: 300, buttons: 1 });
    expect(result.current.resultRightWidth).toBe(720);
    await act(async () => {
      await new Promise<void>((resolve) => window.requestAnimationFrame(() => resolve()));
    });
    expect(
      document.documentElement.style.getPropertyValue('--petri-live-result-right-width'),
    ).toBe('420px');
    fireMouse(document, 'mouseup');
    await flush();

    expect(result.current.resultRightWidth).toBe(420);
    expect(result.current.rightWidth).toBe(340);
    const saved = JSON.parse(localStorage.getItem(LS_KEY) || '{}');
    expect(saved.resultRightWidth).toBe(420);
    expect(saved.rightWidth).toBe(340);
  });

  it('restores dimensions from localStorage on re-mount', async () => {
    localStorage.setItem(LS_KEY, JSON.stringify({ leftWidth: 500, rightWidth: 200, inputHeight: 90, bottomTerminalHeight: 300 }));
    const { result } = renderHook(() => useResizableColumns());
    expect(result.current.leftWidth).toBe(500);
    expect(result.current.rightWidth).toBe(200);
    expect(result.current.inputHeight).toBe(90);
    expect(result.current.bottomTerminalHeight).toBe(300);
  });

  it('migrates the legacy default terminal height without overriding custom sizes', () => {
    localStorage.setItem(LS_KEY, JSON.stringify({ bottomTerminalHeight: 240 }));
    const legacyDefault = renderHook(() => useResizableColumns());
    expect(legacyDefault.result.current.bottomTerminalHeight).toBe(176);
    legacyDefault.unmount();

    localStorage.setItem(LS_KEY, JSON.stringify({ bottomTerminalHeight: 320 }));
    const customSize = renderHook(() => useResizableColumns());
    expect(customSize.result.current.bottomTerminalHeight).toBe(320);
    customSize.unmount();
  });

  it('keeps narrow persisted widths usable and rejects values below the safety floor', () => {
    localStorage.setItem(LS_KEY, JSON.stringify({ resultRightWidth: 420 }));
    const narrow = renderHook(() => useResizableColumns());
    expect(narrow.result.current.resultRightWidth).toBe(420);
    narrow.unmount();

    localStorage.setItem(LS_KEY, JSON.stringify({ resultRightWidth: 240 }));
    const belowFloor = renderHook(() => useResizableColumns());
    expect(belowFloor.result.current.resultRightWidth).toBe(360);
    belowFloor.unmount();

    localStorage.setItem(LS_KEY, JSON.stringify({ resultRightWidth: Number.NaN }));
    const invalid = renderHook(() => useResizableColumns());
    expect(invalid.result.current.resultRightWidth).toBe(720);
  });

  it('prefers localStorage over defaults but caller overrides override localStorage', async () => {
    localStorage.setItem(LS_KEY, JSON.stringify({ leftWidth: 999, rightWidth: 888, inputHeight: 77, bottomTerminalHeight: 666 }));
    const { result } = renderHook(() =>
      useResizableColumns({ leftWidth: 300 }), // only leftWidth overridden
    );
    expect(result.current.leftWidth).toBe(300);   // caller wins
    expect(result.current.rightWidth).toBe(888); // LS
    expect(result.current.inputHeight).toBe(77);  // LS
    expect(result.current.bottomTerminalHeight).toBe(666); // LS
  });

  it('persists on bottomTerminalHeight resize', async () => {
    const { result } = renderHook(() => useResizableColumns({ bottomTerminalHeight: 200 }));
    await flush();
    result.current.startBottomTerminalResize(
      { preventDefault: () => {}, clientY: 0 } as unknown as React.MouseEvent,
    );
    fireMouse(document, 'mousemove', { clientY: 80, buttons: 1 }); // 200 - 80 = 120
    fireMouse(document, 'mouseup');
    await flush();

    const saved = JSON.parse(localStorage.getItem(LS_KEY) || '{}');
    expect(saved.bottomTerminalHeight).toBe(120);
  });

  it('survives corrupted localStorage gracefully', async () => {
    localStorage.setItem(LS_KEY, 'not valid json {{{');
    const { result } = renderHook(() => useResizableColumns());
    // Should fall back to defaults without crashing
    expect(result.current.leftWidth).toBe(240);
    expect(result.current.rightWidth).toBe(340);
  });

  it('stops resizing when the mouse button is no longer pressed', async () => {
    const { result } = renderHook(() => useResizableColumns());
    const handler = result.current.startColumnResize('right');
    const fakeEvent = { preventDefault: () => {}, clientX: 0, clientY: 0 } as unknown as React.MouseEvent;

    await flush();
    handler(fakeEvent);
    fireMouse(document, 'mousemove', { clientX: 60, buttons: 1 });
    await flush();
    const draggedWidth = result.current.rightWidth;
    fireMouse(document, 'mousemove', { clientX: 600, buttons: 0 });
    await flush();

    expect(document.body.classList.contains('petri-resizing-columns')).toBe(false);
    expect(result.current.rightWidth).toBe(draggedWidth);
  });

  it('keeps result resizing responsive when an environment omits the buttons bitmask', async () => {
    const { result } = renderHook(() => useResizableColumns());
    const handler = result.current.startColumnResize('resultRight');
    const fakeEvent = { preventDefault: () => {}, clientX: 0, clientY: 0 } as unknown as React.MouseEvent;

    handler(fakeEvent);
    fireMouse(document, 'mousemove', { clientX: 240, buttons: 0 });
    await act(async () => {
      await new Promise<void>((resolve) => window.requestAnimationFrame(() => resolve()));
    });
    expect(
      document.documentElement.style.getPropertyValue('--petri-live-result-right-width'),
    ).toBe('480px');

    fireMouse(document, 'mouseup');
    await flush();
    expect(result.current.resultRightWidth).toBe(480);
  });
});

