/**
 * useSkillStore — centralized state management for Skills discovery,
 * filtering, and execution.
 *
 * Replaces scattered local-state caches across components that called
 * `window.petriDesktop.skills.*` directly. Implements:
 * - Module-level cache with 5-minute TTL
 * - Subscriber fan-out for cross-component sync
 * - Optimistic execution updates
 * - Unified search/filter pipeline
 *
 * References:
 * - core/shared-backend/skill-registry.js — backend Skill registry
 * - core/shared-backend/skill-schema.js — Skill manifest schema
 * - frontend/src/hooks/usePluginStore.ts — adopted pattern
 */

import { useCallback, useEffect, useMemo, useState } from 'react';
import { getBridge } from '@/lib/desktopBridge';

// ─────────────────────────────────────────────────────────────────────────────
// Type definitions — BLOCK-92 Wave B-7 外迁 ./useSkillStore/types.ts（纯搬运），
// 原导入路径保持全部 re-export：消费方（Skills 页等）import 零改动。
// ─────────────────────────────────────────────────────────────────────────────
import type {
  Skill,
  SkillExecution,
  SkillSource,
} from './useSkillStore/types';
import {
  __getProgressUnsubsSize,
  _executionsChanged,
  _startPolling,
  _stopAllPolling,
  _stopAllProgressWakeups,
  _subscribeProgressWakeup,
  _unsubscribeProgressWakeup,
} from './useSkillStore/executionMonitor';

export type {
  ExecutionStatus,
  OutputArtifact,
  ParameterSchema,
  ParameterType,
  Skill,
  SkillExecution,
  SkillSource,
} from './useSkillStore/types';
export { __getProgressUnsubsSize } from './useSkillStore/executionMonitor';
interface DiscoverResult {
  ok: boolean;
  skills?: Skill[];
  error?: string;
}

/** Result of a skill execution call. */
interface ExecuteResult {
  ok: boolean;
  executionId?: string;
  error?: string;
}

/** Snapshot held in the module-level cache. */
interface SkillStoreSnapshot {
  skills: Skill[];
  loaded: boolean;
  lastFetched: number; // timestamp
}

// ─────────────────────────────────────────────────────────────────────────────
// Module-level cache (shared across all hook instances)
// ─────────────────────────────────────────────────────────────────────────────

const CACHE_TTL_MS = 5 * 60 * 1000; // 5 minutes

let _cache: SkillStoreSnapshot = {
  skills: [],
  loaded: false,
  lastFetched: 0,
};

let _inflight: Promise<DiscoverResult> | null = null;
const _subscribers = new Set<() => void>();

function _notify(): void {
  _subscribers.forEach((fn) => fn());
}

function _isCacheStale(): boolean {
  return Date.now() - _cache.lastFetched > CACHE_TTL_MS;
}

// ─────────────────────────────────────────────────────────────────────────────
// Core data-fetching
// ─────────────────────────────────────────────────────────────────────────────

async function _discoverSkills(): Promise<DiscoverResult> {
  if (_inflight) return _inflight;

  const bridge = getBridge('skills');
  if (!bridge) {
    return { ok: false, error: 'skills bridge unavailable' };
  }

  let resolveInflight!: (result: DiscoverResult) => void;
  let rejectInflight!: (err: unknown) => void;

  const promise = new Promise<DiscoverResult>((resolve, reject) => {
    resolveInflight = resolve;
    rejectInflight = reject;
  });

  _inflight = promise;

  (async () => {
    try {
      const result = await bridge.discover();
      if (result.ok && Array.isArray(result.skills)) {
        _cache = {
          skills: result.skills,
          loaded: true,
          lastFetched: Date.now(),
        };
      } else {
        _cache.loaded = true;
      }
      _notify();
      resolveInflight(result);
    } catch (err) {
      const error = err instanceof Error ? err.message : String(err);
      _notify();
      resolveInflight({ ok: false, error });
    } finally {
      _inflight = null;
    }
  })();

  return promise;
}

// ─────────────────────────────────────────────────────────────────────────────
// Polling helpers for execution status
// ─────────────────────────────────────────────────────────────────────────────


// ─────────────────────────────────────────────────────────────────────────────
// Public hook
// ─────────────────────────────────────────────────────────────────────────────

export interface UseSkillStoreResult {
  /** All discovered skills (unfiltered). */
  skills: Skill[];
  /** Skills after applying current filters. */
  filteredSkills: Skill[];
  /** Whether a discovery call is in-flight. */
  loading: boolean;
  /** Error message from last failed operation. */
  error: string | null;
  /** Current search query. */
  searchQuery: string;
  /** Set search query (triggers re-filter). */
  setSearchQuery: (query: string) => void;
  /** Active category filter (null = no filter). */
  categoryFilter: string | null;
  /** Set category filter. */
  setCategoryFilter: (category: string | null) => void;
  /** Active source filter (null = no filter). */
  sourceFilter: SkillSource | null;
  /** Set source filter. */
  setSourceFilter: (source: SkillSource | null) => void;
  /** All known categories from discovered skills. */
  categories: string[];
  /** All known tags from discovered skills. */
  tags: string[];
  /** Map of executionId → execution record. */
  executions: Map<string, SkillExecution>;
  /** Discover/re-discover all skills. */
  discover: () => Promise<void>;
  /** Search skills locally (complements server-side discover). */
  search: (query: string) => Promise<void>;
  /** Execute a skill by ID with given params. */
  execute: (
    skillId: string,
    params?: Record<string, unknown>
  ) => Promise<ExecuteResult>;
  /** Get a specific execution record by ID. */
  getExecution: (executionId: string) => SkillExecution | undefined;
  /** BLOCK-4 G4 顺手补：Cancel a running execution by ID. */
  cancel: (
    executionId: string
  ) => Promise<{ ok: boolean; cancelled?: boolean; error?: string }>;
  /** Invalidate cache and force reload on next use. */
  invalidateCache: () => void;
}

export function useSkillStore(
  opts: {
    /** Automatically trigger discover on mount. Defaults to true. */
    autoLoad?: boolean;
    /** Force cache refresh regardless of TTL. Defaults to false. */
    forceRefresh?: boolean;
  } = {}
): UseSkillStoreResult {
  const { autoLoad = true, forceRefresh = false } = opts;

  const [snapshot, setSnapshot] = useState<SkillStoreSnapshot>(_cache);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(
    !_cache.loaded && autoLoad
  );
  const [searchQuery, setSearchQuery] = useState('');
  const [categoryFilter, setCategoryFilter] = useState<string | null>(null);
  const [sourceFilter, setSourceFilter] = useState<SkillSource | null>(null);
  const [executions, setExecutions] = useState<Map<string, SkillExecution>>(
    new Map()
  );

  // Subscribe to module-level cache changes
  useEffect(() => {
    const onChange = () => {
      setSnapshot({ ..._cache });
    };
    _subscribers.add(onChange);
    return () => {
      _subscribers.delete(onChange);
    };
  }, []);

  // Initial load
  useEffect(() => {
    let cancelled = false;

    if (autoLoad && (!_cache.loaded || forceRefresh || _isCacheStale())) {
      setLoading(true);
      setError(null);
      _discoverSkills()
        .then((result) => {
          if (cancelled) return;
          if (!result.ok) setError(result.error ?? 'Discovery failed');
        })
        .catch((err) => {
          if (cancelled) return;
          setError(err instanceof Error ? err.message : String(err));
        })
        .finally(() => {
          if (cancelled) return;
          setLoading(false);
        });
    } else if (autoLoad) {
      setLoading(false);
    }

    return () => {
      cancelled = true;
    };
  }, [autoLoad, forceRefresh]);

  // Cleanup polling + progress wakeup subscriptions on unmount
  useEffect(() => {
    return () => {
      _stopAllPolling();
      _stopAllProgressWakeups();
    };
  }, []);

  // ── Derived: filtered skills ────────────────────────────────────────────────

  const filteredSkills = useMemo(() => {
    const list = snapshot.skills;
    let result = list;

    if (searchQuery.trim()) {
      const q = searchQuery.toLowerCase();
      result = result.filter(
        (s) =>
          s.id.toLowerCase().includes(q) ||
          s.name.toLowerCase().includes(q) ||
          s.description.toLowerCase().includes(q) ||
          s.category.toLowerCase().includes(q) ||
          s.tags.some((t) => t.toLowerCase().includes(q))
      );
    }

    if (categoryFilter) {
      result = result.filter(
        (s) =>
          s.category === categoryFilter ||
          s.category.startsWith(categoryFilter + '/')
      );
    }

    if (sourceFilter) {
      result = result.filter((s) => s.source === sourceFilter);
    }

    return result;
  }, [snapshot.skills, searchQuery, categoryFilter, sourceFilter]);

  // ── Derived: metadata ────────────────────────────────────────────────────────

  const categories = useMemo(() => {
    const set = new Set<string>();
    snapshot.skills.forEach((s) => set.add(s.category));
    return Array.from(set).sort();
  }, [snapshot.skills]);

  const tags = useMemo(() => {
    const set = new Set<string>();
    snapshot.skills.forEach((s) => s.tags.forEach((t) => set.add(t)));
    return Array.from(set).sort();
  }, [snapshot.skills]);

  // ── Actions ────────────────────────────────────────────────────────────────

  const discover = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const result = await _discoverSkills();
      if (!result.ok) {
        setError(result.error ?? 'Discovery failed');
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : String(err));
    } finally {
      setLoading(false);
    }
  }, []);

  const search = useCallback(async (_query: string) => {
    // Local filtering is handled by useMemo; this method is reserved
    // for server-side search if/when the backend supports it.
    setSearchQuery(_query);
  }, []);

  const execute = useCallback(
    async (
      skillId: string,
      params?: Record<string, unknown>
    ): Promise<ExecuteResult> => {
      const bridge = getBridge('skills');
      if (!bridge) {
        return { ok: false, error: 'skills bridge unavailable' };
      }

      // Generate optimistic execution record
      const executionId = `exec-${Date.now()}-${Math.random().toString(36).slice(2)}`;
      const optimisticExecution: SkillExecution = {
        executionId,
        skillId,
        status: 'pending',
        startedAt: new Date(),
      };

      // BLOCK-4 E2: setExecutions 内部 deep-equal 比较，避免无变化 re-render
      setExecutions((prev) => {
        const existing = prev.get(executionId);
        if (existing && !_executionsChanged(existing, optimisticExecution)) {
          return prev; // skip 跳过 re-render
        }
        const next = new Map(prev);
        next.set(executionId, optimisticExecution);
        return next;
      });

      try {
        const result = await bridge.execute(skillId, params ?? {});

        if (result.ok && result.executionId) {
          // Update with real execution ID if different
          const realId = result.executionId;
          const runningExec: SkillExecution = {
            ...optimisticExecution,
            executionId: realId,
            status: 'running',
          };
          setExecutions((prev) => {
            const next = new Map(prev);
            next.delete(executionId);
            const existing = next.get(realId);
            if (existing && !_executionsChanged(existing, runningExec)) {
              return prev;
            }
            next.set(realId, runningExec);
            return next;
          });

          // Start polling for status updates (2s polling is truth-source fallback)
          _startPolling(realId, (updated) => {
            setExecutions((prev) => {
              const existing = prev.get(realId);
              if (existing && !_executionsChanged(existing, updated)) {
                return prev;
              }
              const next = new Map(prev);
              next.set(realId, updated);
              return next;
            });
          });
          // PHASE 1 G0 UI-157：subscribe event-driven wakeup (~100ms latency)
          _subscribeProgressWakeup(realId, (updated) => {
            setExecutions((prev) => {
              const existing = prev.get(realId);
              if (existing && !_executionsChanged(existing, updated)) {
                return prev;
              }
              const next = new Map(prev);
              next.set(realId, updated);
              return next;
            });
          });

          return { ok: true, executionId: realId };
        } else {
          // Mark as failed
          const failedExec: SkillExecution = {
            ...optimisticExecution,
            status: 'failed',
            completedAt: new Date(),
            error: result.error ?? 'Execution failed',
          };
          setExecutions((prev) => {
            const existing = prev.get(executionId);
            if (existing && !_executionsChanged(existing, failedExec)) {
              return prev;
            }
            const next = new Map(prev);
            next.set(executionId, failedExec);
            return next;
          });
          return { ok: false, error: result.error };
        }
      } catch (err) {
        const error = err instanceof Error ? err.message : String(err);
        const failedExec: SkillExecution = {
          ...optimisticExecution,
          status: 'failed',
          completedAt: new Date(),
          error,
        };
        setExecutions((prev) => {
          const existing = prev.get(executionId);
          if (existing && !_executionsChanged(existing, failedExec)) {
            return prev;
          }
          const next = new Map(prev);
          next.set(executionId, failedExec);
          return next;
        });
        return { ok: false, error };
      }
    },
    []
  );

  const getExecution = useCallback(
    (executionId: string): SkillExecution | undefined => {
      return executions.get(executionId);
    },
    [executions]
  );

  // BLOCK-4 G4 顺手补：store 内部 cancel action（PHASE 6 G4 报告"无 store.cancel() action"）
  const cancel = useCallback(
    async (executionId: string): Promise<{ ok: boolean; cancelled?: boolean; error?: string }> => {
      const bridge = getBridge('skills');
      if (!bridge || typeof bridge.cancel !== 'function') {
        return { ok: false, error: 'skills bridge unavailable' };
      }
      try {
        const result = await bridge.cancel(executionId);
        // 成功 cancel 同步清本地 wakeup 订阅（防止后续 progress 事件还写入 store）
        if (result.ok && result.cancelled !== false) {
          _unsubscribeProgressWakeup(executionId);
        }
        return result;
      } catch (err) {
        const error = err instanceof Error ? err.message : String(err);
        if (typeof console !== 'undefined' && console.warn) {
          console.warn('[useSkillStore] cancel failed:', error);
        }
        return { ok: false, error };
      }
    },
    []
  );

  const invalidateCache = useCallback(() => {
    _cache = { skills: [], loaded: false, lastFetched: 0 };
    _notify();
  }, []);

  return {
    skills: snapshot.skills,
    filteredSkills,
    loading,
    error,
    searchQuery,
    setSearchQuery,
    categoryFilter,
    setCategoryFilter,
    sourceFilter,
    setSourceFilter,
    categories,
    tags,
    executions,
    discover,
    search,
    execute,
    getExecution,
    cancel,
    invalidateCache,
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// Test-only helpers
// ─────────────────────────────────────────────────────────────────────────────

// BLOCK-4 PHASE 2 G5: Test-only selector exposing the module-level
// `_progressUnsubs` Map size, used to assert that the useEffect cleanup
// in useSkillStore clears all wakeup subscriptions on unmount. Internal
// module state stays private; this getter is the only test-facing surface.

export function __resetSkillStoreCacheForTests(): void {
  _cache = { skills: [], loaded: false, lastFetched: 0 };
  _inflight = null;
  _subscribers.clear();
  _stopAllPolling();
  _stopAllProgressWakeups();
}

import { getBridge } from '@/lib/desktopBridge';
import type { SkillExecution } from './types';

// BLOCK-92 Wave B-7 — Skill 执行监控机制外迁（原 useSkillStore.ts，纯搬运零行为变化）：
// 2s polling（真值兜底）+ PHASE 1 G0 UI-157 事件驱动 wakeup（≤100ms 感知）+
// BLOCK-4 E2 deep-equal 变更判定。终态时清理订阅避免泄漏。

function _startPolling(
  executionId: string,
  onUpdate: (execution: SkillExecution) => void
): void {
  if (_pollIntervals.has(executionId)) return;

  const interval = setInterval(async () => {
    const bridge = getBridge('skills');
    if (!bridge) {
      clearInterval(interval);
      _pollIntervals.delete(executionId);
      return;
    }

    try {
      const result = await bridge.getExecution(executionId);
      if (result.ok && result.execution) {
        const exec: SkillExecution = {
          executionId: result.execution.executionId,
          skillId: result.execution.skillId,
          status: result.execution.status,
          startedAt: result.execution.startedAt
            ? new Date(result.execution.startedAt)
            : undefined,
          completedAt: result.execution.completedAt
            ? new Date(result.execution.completedAt)
            : undefined,
          result: result.execution.result,
          error: result.execution.error,
        };
        onUpdate(exec);

        // Stop polling on terminal state
        if (
          exec.status === 'completed' ||
          exec.status === 'failed'
        ) {
          clearInterval(interval);
          _pollIntervals.delete(executionId);
          // BLOCK-3 P2 A1: 终态同步清 onProgress 订阅，避免多 execution 切换后
          // 残留 wakeup callback 继续接收 progress 事件触发重复 IPC。
          _unsubscribeProgressWakeup(executionId);
        }
      }
    } catch {
      clearInterval(interval);
      _pollIntervals.delete(executionId);
      // BLOCK-3 P2 A1: 异常路径同样清 onProgress 订阅
      _unsubscribeProgressWakeup(executionId);
    }
  }, 2000);

  _pollIntervals.set(executionId, interval);
}

const _pollIntervals: Map<string, ReturnType<typeof setInterval>> = new Map();

function _stopAllPolling(): void {
  _pollIntervals.forEach((interval) => clearInterval(interval));
  _pollIntervals.clear();
}

// PHASE 1 G0 UI-157：event-driven wakeup（取代单纯 2s polling）。
// 订阅主进程 webContents.send('skills:progress') 推送，过滤到当前
// executionId 时立即调一次 bridge.getExecution() 拉完整 snapshot。
// 与 _startPolling 并行运行（polling 2s 是真值兜底，wakeup 把感知延迟从
// ≤2s 降到 ≤100ms；终态时清理订阅避免泄漏）。
const _progressUnsubs: Map<string, () => void> = new Map();

// 自动派生自 d.ts onProgress 回调参数的真实类型（BLOCK-4 D1）
type SkillsBridge = NonNullable<ReturnType<typeof getBridge<'skills'>>>;
type SkillsProgressPayload = Parameters<SkillsBridge['onProgress']>[0] extends (p: infer P) => any ? P : never;

function _subscribeProgressWakeup(
  executionId: string,
  onUpdate: (execution: SkillExecution) => void
): void {
  if (_progressUnsubs.has(executionId)) return;
  const bridge = getBridge('skills');
  if (!bridge || typeof bridge.onProgress !== 'function') return;
  const unsubscribe = bridge.onProgress((payload: SkillsProgressPayload) => {
    // BLOCK-4 B4: payload 缺 executionId 时 console.warn 便于诊断
    if (!payload || typeof payload !== 'object') {
      if (typeof console !== 'undefined' && console.warn) {
        console.warn('[useSkillStore] skills:progress payload missing or not object:', payload);
      }
      return;
    }
    if (payload.executionId !== executionId) return;
    void (async () => {
      try {
        const result = await bridge.getExecution(executionId);
        if (result.ok && result.execution) {
          onUpdate({
            executionId: result.execution.executionId,
            skillId: result.execution.skillId,
            status: result.execution.status,
            startedAt: result.execution.startedAt
              ? new Date(result.execution.startedAt)
              : undefined,
            completedAt: result.execution.completedAt
              ? new Date(result.execution.completedAt)
              : undefined,
            result: result.execution.result,
            error: result.execution.error,
          });
        }
      } catch {
        /* 静默兜底：polling 仍会按 2s 节奏兜底真值 */
      }
    })();
  });
  _progressUnsubs.set(executionId, unsubscribe);
}

// BLOCK-4 E2: deep-equal 比较，避免无变化 re-render；返回 true 表示有变化
function _executionsChanged(prev: SkillExecution, next: SkillExecution): boolean {
  if (prev === next) return false;
  if (prev.status !== next.status) return true;
  if (prev.completedAt?.getTime() !== next.completedAt?.getTime()) return true;
  if (prev.error !== next.error) return true;
  if (prev.result !== next.result) return true;
  if (prev.startedAt?.getTime() !== next.startedAt?.getTime()) return true;
  return false;
}

function _unsubscribeProgressWakeup(executionId: string): void {
  const unsub = _progressUnsubs.get(executionId);
  if (unsub) {
    unsub();
    _progressUnsubs.delete(executionId);
  }
}

function _stopAllProgressWakeups(): void {
  _progressUnsubs.forEach((unsub) => unsub());
  _progressUnsubs.clear();
}

// Test-only helper 出口：BLOCK-4 PHASE 2 G5 断言 useEffect 清理订阅用
//（内部 Map 保持模块私有，getter 是唯一 test-facing surface）。
export function __getProgressUnsubsSize(): number {
  return _progressUnsubs.size;
}

export {
  _startPolling,
  _stopAllPolling,
  _subscribeProgressWakeup,
  _executionsChanged,
  _unsubscribeProgressWakeup,
  _stopAllProgressWakeups,
};

/**
 * useStartupTimeline — BLOCK-101 P0 启动 timeline 度量（D1 四段口径，纯观测）
 *
 * 渲染层职责：firstPaint（paintTiming）+ dataReady（左栏 projects 首次到货，
 * 由 AppRailContext 调 markDataReady）+ preloadMs（preload 暴露）汇总后经
 * startup:report 一次性上报主进程存档；flow 经 startup:marks 拉取对账。
 * 主进程侧 mainReady/windowShown/didFinishLoad 由 src/ipc/startup-timeline.js 打点。
 * 桌面外（投影/浏览器）无桥 → 静默跳过（诚实降级，不伪造数字）。
 */

import { useEffect, useRef } from 'react';

export interface StartupReport {
  preloadMs?: number;
  firstPaintMs?: number;
  dataReadyMs?: number;
  reportedAt: number;
}

/** 模块级单例：dataReady 打点先于 hook mount 也可靠 */
let dataReadyMark: number | null = null;
/** 只挡 mount 兜底上报；dataReady 终版始终放行（主进程 last-write-wins） */
let mountReported = false;

/** AppRailContext 在项目列表首次到货时调用；终版带上 dataReady 再报一次 */
export function markDataReady(): void {
  if (dataReadyMark == null) dataReadyMark = Math.round(performance.now());
  sendReport(false);
}

function sendReport(isMountFallback: boolean): void {
  if (typeof window === 'undefined') return;
  if (isMountFallback && mountReported) return;
  const desktop = (window as { petri?: unknown }).petri ?? (window as { petriDesktop?: unknown }).petriDesktop;
  const bridge = (desktop as { startup?: { report?: (p: StartupReport) => void } } | null)?.startup;
  if (!bridge?.report) return;
  if (isMountFallback) mountReported = true;

  const report: StartupReport = { reportedAt: Date.now() };
  const preloadMs = (desktop as { __startupPreloadMs?: number }).__startupPreloadMs;
  if (typeof preloadMs === 'number' && preloadMs >= 0 && preloadMs < 60000) report.preloadMs = Math.round(preloadMs);
  if (dataReadyMark != null) report.dataReadyMs = dataReadyMark;
  const entries = performance.getEntriesByType('paint') as PerformanceEntry[];
  const fp = entries.find((e) => e.name === 'first-paint' || e.name === 'first-contentful-paint');
  if (fp) report.firstPaintMs = Math.round(fp.startTime);
  bridge.report(report);
}

export function useStartupTimeline(): void {
  const mountedRef = useRef(false);

  useEffect(() => {
    if (mountedRef.current) return;
    mountedRef.current = true;
    // mount 即发一版（dataReady 可能未到，字段诚实缺省）；dataReady 到货时
    // markDataReady→sendReport(终版) 再报（主进程 last-write-wins 覆盖）。
    sendReport(true);
    // firstPaint 晚于 mount 的兜底补采一版
    const timer = window.setTimeout(() => sendReport(true), 1500);
    return () => window.clearTimeout(timer);
  }, []);
}

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { act, renderHook } from '@testing-library/react';
import { useTerminalTabs } from '@/hooks/useTerminalTabs';
import { TERMINAL_THEMES, type TerminalThemeName } from '@/themes/terminal-themes';

// ---------------------------------------------------------------------------
// Mocks（沿用 useTerminalSession 旧测试的 Fake xterm 模式）
// ---------------------------------------------------------------------------

const hoisted = vi.hoisted(() => {
  class FakeXTerm {
    static instances: FakeXTerm[] = [];
    cols = 80;
    rows = 24;
    options: { theme?: unknown } = {};
    private onDataHandlers: Array<(data: string) => void> = [];
    onData(handler: (data: string) => void) {
      this.onDataHandlers.push(handler);
      return { dispose: () => {} };
    }
    onDataEmit(data: string) {
      for (const h of this.onDataHandlers) h(data);
    }
    open = vi.fn();
    loadAddon = vi.fn();
    write = vi.fn();
    writeln = vi.fn();
    clear = vi.fn();
    focus = vi.fn();
    dispose = vi.fn();
    constructor(opts: Record<string, unknown>) {
      this.options = opts as { theme?: unknown };
      FakeXTerm.instances.push(this);
    }
  }

  class FakeFitAddon {
    fit = vi.fn();
  }

  return { FakeXTerm, FakeFitAddon, ctor: vi.fn() };
});

vi.mock('@xterm/xterm', () => {
  return {
    Terminal: class extends hoisted.FakeXTerm {
      constructor(opts: Record<string, unknown>) {
        super(opts);
        hoisted.ctor(opts);
      }
    },
  };
});

vi.mock('@xterm/addon-fit', () => {
  return { FitAddon: class extends hoisted.FakeFitAddon {} };
});

class FakeResizeObserver {
  observe = vi.fn();
  unobserve = vi.fn();
  disconnect = vi.fn();
  constructor(_cb: ResizeObserverCallback) {}
}

// ---------------------------------------------------------------------------
// IPC bridge installer（事件 payload 为 BLOCK-54 新形状 { sessionId, ... }）
// ---------------------------------------------------------------------------

type DataPayload = { sessionId: string; data: string };
type ExitPayload = { sessionId: string; code?: number | null; signal?: string | null };

function installBridge() {
  const onDataListeners: Array<(p: DataPayload) => void> = [];
  const onExitListeners: Array<(p: ExitPayload) => void> = [];
  let startCalls = 0;
  const startSession = vi.fn<
    (
      cwd?: string,
      sessionId?: string
    ) => Promise<{ ok: boolean; error?: string; pid?: number; sessionId?: string }>
  >(async (_cwd, sessionId) => ({
    ok: true,
    pid: 1000 + (startCalls += 1),
    sessionId,
  }));
  const bridge = {
    startSession,
    stopSession: vi.fn(async () => ({ ok: true, wasRunning: true })),
    writeSession: vi.fn(async () => ({ ok: true })),
    resizeSession: vi.fn(async () => ({ ok: true })),
    listSessions: vi.fn(async () => ({ ok: true, sessions: [], maxTabs: 4 })),
    onData: vi.fn((cb: (p: DataPayload) => void) => {
      onDataListeners.push(cb);
      return () => {
        const i = onDataListeners.indexOf(cb);
        if (i >= 0) onDataListeners.splice(i, 1);
      };
    }),
    onExit: vi.fn((cb: (p: ExitPayload) => void) => {
      onExitListeners.push(cb);
      return () => {
        const i = onExitListeners.indexOf(cb);
        if (i >= 0) onExitListeners.splice(i, 1);
      };
    }),
  };
  (window as unknown as { petriDesktop: unknown }).petriDesktop = { terminal: bridge };
  return { bridge, onDataListeners, onExitListeners };
}

function uninstallBridge() {
  delete (window as unknown as { petriDesktop?: unknown }).petriDesktop;
}

// ---------------------------------------------------------------------------
// Harness
// ---------------------------------------------------------------------------

function mountHook(open = false, workspacePath?: string, theme: TerminalThemeName = 'dark') {
  const hosts = new Map<string, HTMLDivElement>();
  /** 挂载宿主元素（模拟 React commit：ref 先于 effects 就绪，带 data-tab-body 供断言定位）。 */
  function attachHost(id: string) {
    if (hosts.has(id)) return;
    const el = document.createElement('div');
    el.setAttribute('data-tab-body', id);
    document.body.appendChild(el);
    hosts.set(id, el);
    result.current.registerHost(id)(el);
  }
  const { result, rerender, unmount } = renderHook(
    ({ isOpen, ws, activeTheme }: { isOpen: boolean; ws?: string; activeTheme: TerminalThemeName }) =>
      useTerminalTabs({ open: isOpen, workspacePath: ws, theme: activeTheme }),
    { initialProps: { isOpen: open, ws: workspacePath, activeTheme: theme } }
  );
  /** 连开 n 个 tab；每次 openTab 独立 act（对齐真实用户点击节奏：每 tab 激活期间各自 ensure）。
   *  新 tab 宿主必须在同一 act 内挂载：真实组件所有 tab body 随创建即渲染（ref 先于
   *  passive effect 就绪），createTerminalTab 的 id 规则是 `tab-${maxSeq+1}`。 */
  function openTabAndAttach(count: number) {
    for (let i = 0; i < count; i += 1) {
      act(() => {
        const nextId = `tab-${result.current.tabs.length + 1}`;
        result.current.openTab();
        attachHost(nextId);
      });
    }
  }
  function setOpen(nextOpen: boolean) {
    rerender({ isOpen: nextOpen, ws: workspacePath, activeTheme: theme });
  }
  return { result, rerender, unmount, attachHost, openTabAndAttach, setOpen };
}

async function flush() {
  await act(async () => {
    await Promise.resolve();
  });
}

describe('useTerminalTabs', () => {
  beforeEach(() => {
    hoisted.FakeXTerm.instances = [];
    hoisted.ctor.mockClear();
    document.body.innerHTML = '';
    (globalThis as unknown as { ResizeObserver: typeof FakeResizeObserver }).ResizeObserver =
      FakeResizeObserver;
  });

  afterEach(() => {
    uninstallBridge();
  });

  it('openTab 建首个 tab；面板展开后按 (cwd, sessionId) 懒启动会话', async () => {
    const { bridge } = installBridge();
    const { result, attachHost, setOpen } = mountHook(false, '/tmp/proj');
    act(() => {
      result.current.openTab();
      attachHost('tab-1');
    });
    expect(result.current.tabs.map((t) => t.id)).toEqual(['tab-1']);
    expect(bridge.startSession).not.toHaveBeenCalled(); // 面板未展开不占资源

    setOpen(true);
    await flush();
    expect(bridge.startSession).toHaveBeenCalledTimes(1);
    expect(bridge.startSession).toHaveBeenCalledWith('/tmp/proj', 'tab-1', undefined);
    expect(result.current.activeId).toBe('tab-1');
    expect(result.current.activeRunning).toBe(true);
  });

  it('多 tab 并存：各自独立启动一次，切换不重启既有会话', async () => {
    const { bridge } = installBridge();
    const { result, openTabAndAttach } = mountHook(true, '/tmp/proj');
    openTabAndAttach(1);
    await flush();
    expect(bridge.startSession).toHaveBeenCalledTimes(1);

    openTabAndAttach(1);
    await flush();
    expect(bridge.startSession).toHaveBeenCalledTimes(2);
    expect(bridge.startSession).toHaveBeenLastCalledWith('/tmp/proj', 'tab-2', undefined);

    act(() => result.current.setActive('tab-1'));
    await flush();
    expect(bridge.startSession).toHaveBeenCalledTimes(2); // 切回 tab-1 不重启
    expect(result.current.activeId).toBe('tab-1');
  });

  it(`上限 4：第 5 个 openTab 诚实拒绝并给出提示`, () => {
    installBridge();
    const { result } = mountHook(false, '/tmp/proj');
    for (let i = 0; i < 4; i += 1) act(() => result.current.openTab());
    expect(result.current.tabs).toHaveLength(4);
    act(() => result.current.openTab());
    expect(result.current.tabs).toHaveLength(4);
    expect(result.current.limitNotice).toContain('最多同时打开 4 个');
  });

  it('terminal:data 按 sessionId 路由到对应 xterm', async () => {
    const { onDataListeners } = installBridge();
    const { openTabAndAttach } = mountHook(true, '/tmp/proj');
    openTabAndAttach(2);
    await flush();

    onDataListeners[0]({ sessionId: 'tab-2', data: 'from-2\n' });
    onDataListeners[0]({ sessionId: 'tab-1', data: 'from-1\n' });
    const term1 = hoisted.FakeXTerm.instances.find(
      (t) => t.open.mock.calls[0]?.[0]?.getAttribute?.('data-tab-body') === 'tab-1'
    );
    const term2 = hoisted.FakeXTerm.instances.find(
      (t) => t.open.mock.calls[0]?.[0]?.getAttribute?.('data-tab-body') === 'tab-2'
    );
    expect(term1?.write).toHaveBeenCalledWith('from-1\n');
    expect(term1?.write).not.toHaveBeenCalledWith('from-2\n');
    expect(term2?.write).toHaveBeenCalledWith('from-2\n');
    expect(term2?.write).not.toHaveBeenCalledWith('from-1\n');
  });

  it('terminal:exit 按 sessionId 标记退出 + 写退出行，不误伤其他 tab', async () => {
    const { onExitListeners } = installBridge();
    const { result, openTabAndAttach } = mountHook(true, '/tmp/proj');
    openTabAndAttach(2);
    await flush();

    act(() => {
      onExitListeners[0]({ sessionId: 'tab-2', code: 0, signal: null });
    });
    await flush();
    expect(result.current.tabs.find((t) => t.id === 'tab-2')?.exited).toBe(true);
    expect(result.current.tabs.find((t) => t.id === 'tab-1')?.exited).toBe(false);
    const term2 = hoisted.FakeXTerm.instances[1];
    const lastWrite = term2.writeln.mock.calls.at(-1)?.[0] as string;
    expect(lastWrite).toContain('进程已退出');
  });

  it('closeTab：停进程 + dispose 实例 + 激活右邻', async () => {
    const { bridge } = installBridge();
    const { result, openTabAndAttach } = mountHook(true, '/tmp/proj');
    openTabAndAttach(3);
    await flush();
    const term2 = hoisted.FakeXTerm.instances[1];

    act(() => result.current.closeTab('tab-2'));
    expect(bridge.stopSession).toHaveBeenCalledWith('tab-2');
    expect(term2.dispose).toHaveBeenCalledTimes(1);
    expect(result.current.tabs.map((t) => t.id)).toEqual(['tab-1', 'tab-3']);
    expect(result.current.activeId).toBe('tab-3');
  });

  it('启动失败：写「启动失败」行、running 不置真', async () => {
    const { bridge } = installBridge();
    bridge.startSession.mockResolvedValueOnce({ ok: false, error: 'no pty' });
    const { result, openTabAndAttach } = mountHook(true, '/tmp/proj');
    openTabAndAttach(1);
    await flush();
    expect(result.current.activeRunning).toBe(false);
    const lastWrite = hoisted.FakeXTerm.instances[0].writeln.mock.calls.at(-1)?.[0] as string;
    expect(lastWrite).toContain('启动失败');
    expect(lastWrite).toContain('no pty');
  });

  it('输入按 tab 携带 sessionId；clear 只作用激活 tab；主题跟随应用', async () => {
    const { bridge } = installBridge();
    const { result, openTabAndAttach } = mountHook(true, '/tmp/proj', 'light');
    openTabAndAttach(2);
    await flush();
    const term1 = hoisted.FakeXTerm.instances[0];
    expect(term1.options.theme).toBe(TERMINAL_THEMES.light);

    act(() => result.current.setActive('tab-2'));
    await flush();
    const term2 = hoisted.FakeXTerm.instances[1];
    term2.onDataEmit('ls\n');
    expect(bridge.writeSession).toHaveBeenLastCalledWith('ls\n', 'tab-2');

    act(() => result.current.clear());
    expect(term2.clear).toHaveBeenCalledTimes(1);
    expect(term1.clear).not.toHaveBeenCalled();
  });

  it('卸载：已启动会话全量 stop + 实例全量 dispose', async () => {
    const { bridge } = installBridge();
    const { openTabAndAttach, unmount } = mountHook(true, '/tmp/proj');
    openTabAndAttach(2);
    await flush();
    unmount();
    expect(bridge.stopSession).toHaveBeenCalledWith('tab-1');
    expect(bridge.stopSession).toHaveBeenCalledWith('tab-2');
    expect(hoisted.FakeXTerm.instances.every((t) => t.dispose.mock.calls.length === 1)).toBe(true);
  });
});

messages.message:
