import { useCallback, useEffect, useRef, useState } from 'react';
import { Terminal as XTerm } from '@xterm/xterm';
import '@xterm/xterm/css/xterm.css';
import { FitAddon } from '@xterm/addon-fit';
import { pickTerminalTheme, type TerminalThemeName } from '@/themes/terminal-themes';
import { getBridge } from '@/lib/desktopBridge';
import {
  MAX_TERMINAL_TABS,
  closeTerminalTab,
  createTerminalTab,
  type TerminalTab,
} from './terminalTabs';

export interface UseTerminalTabsOptions {
  /** 底部终端面板是否展开；展开且 tab 激活时才真正启动该 tab 的 pty。 */
  open: boolean;
  /** 新 tab 的默认 cwd（当前项目 workspace）。 */
  workspacePath?: string;
  /** BLOCK-67：SSH 远程项目——pty 直挂 ssh（remotePath 为远端工作目录）。 */
  ssh?: { alias: string; remotePath: string };
  /** 解析后的应用主题；xterm 实例跟随变化（不重建会话）。 */
  theme: TerminalThemeName;
}

export interface UseTerminalTabsResult {
  tabs: TerminalTab[];
  activeId: string | null;
  setActive: (id: string) => void;
  openTab: () => void;
  closeTab: (id: string) => void;
  /** tab 内容容器 callback ref（xterm 首次激活时 open 进该容器）。 */
  registerHost: (id: string) => (el: HTMLDivElement | null) => void;
  /** 上限等操作提示（用户可见，操作后自动消隐）。 */
  limitNotice: string | null;
  dismissLimitNotice: () => void;
  clear: () => void;
  activeRunning: boolean;
  /** sessionId → pty 是否运行中（tab 状态点用）。 */
  runningBy: Record<string, boolean>;
}

interface TabEntry {
  term: XTerm;
  fit: FitAddon;
  started: boolean;
  host: HTMLDivElement;
}

/**
 * BLOCK-54 P2 — 底部终端多 Tab 会话管理（上限 MAX_TERMINAL_TABS=4）。
 *
 * - 每个 tab 独立 xterm 实例 + 独立 node-pty 会话（sessionId 即 tab.id）；
 *   pty 在「面板展开 && tab 首次激活」时才启动（懒启动，不开面板不占资源）。
 * - terminal:data / terminal:exit 事件按 payload.sessionId 路由到对应 tab。
 * - 切换 tab 只做 fit + focus，不重启会话、不丢回显；关闭 tab 即停进程并
 *   dispose 实例；卸载（离开页面）时全量 stop（对齐旧单会话行为）。
 */
export function useTerminalTabs(options: UseTerminalTabsOptions): UseTerminalTabsResult {
  const { open, theme, workspacePath, ssh } = options;
  const [tabs, setTabs] = useState<TerminalTab[]>([]);
  const [activeId, setActiveId] = useState<string | null>(null);
  const [limitNotice, setLimitNotice] = useState<string | null>(null);
  const [runningBy, setRunningBy] = useState<Record<string, boolean>>({});

  const entriesRef = useRef<Map<string, TabEntry>>(new Map());
  const hostsRef = useRef<Map<string, HTMLDivElement>>(new Map());
  const activeIdRef = useRef<string | null>(null);
  const sshRef = useRef(ssh);
  sshRef.current = ssh;
  const themeRef = useRef(theme);
  const resizeObserverRef = useRef<ResizeObserver | null>(null);

  activeIdRef.current = activeId;
  themeRef.current = theme;

  const getBridgeTerminal = useCallback(() => getBridge('terminal'), []);

  // Mount-once: backend event routing by sessionId.
  useEffect(() => {
    const offData = getBridgeTerminal()?.onData?.((payload: { sessionId: string; data: string }) => {
      const entry = entriesRef.current.get(payload?.sessionId);
      entry?.term.write(String(payload?.data || ''));
    });
    const offExit = getBridgeTerminal()?.onExit?.((payload: {
      sessionId: string;
      code?: number | null;
      signal?: string | null;
    }) => {
      const sessionId = payload?.sessionId;
      const entry = entriesRef.current.get(sessionId);
      if (entry) {
        entry.started = false;
        entry.term.writeln(
          `\r\n\x1b[90m[进程已退出${payload.code != null ? `，代码 ${payload.code}` : ''}${payload.signal ? `，信号 ${payload.signal}` : ''}]\x1b[0m`
        );
      }
      setRunningBy((prev) => ({ ...prev, [sessionId]: false }));
      setTabs((prev) => prev.map((t) => (t.id === sessionId ? { ...t, exited: true } : t)));
    });
    return () => {
      offData?.();
      offExit?.();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Theme follows the application palette without recreating sessions.
  useEffect(() => {
    for (const entry of entriesRef.current.values()) {
      try {
        entry.term.options.theme = pickTerminalTheme(theme);
      } catch {
        /* ignore */
      }
    }
  }, [theme]);

  const ensureResizeObserver = useCallback((): ResizeObserver => {
    if (!resizeObserverRef.current) {
      resizeObserverRef.current = new ResizeObserver((observed) => {
        const active = activeIdRef.current;
        for (const item of observed) {
          const id = [...hostsRef.current.entries()].find(([, el]) => el === item.target)?.[0];
          if (!id || id !== active) continue;
          const entry = entriesRef.current.get(id);
          if (!entry) continue;
          try {
            entry.fit.fit();
            getBridgeTerminal()?.resizeSession?.(entry.term.cols, entry.term.rows, id);
          } catch {
            /* ignore */
          }
        }
      });
    }
    return resizeObserverRef.current;
  }, [getBridgeTerminal]);

  const ensureSession = useCallback(
    (tab: TerminalTab) => {
      const host = hostsRef.current.get(tab.id);
      if (!host) return;
      let entry = entriesRef.current.get(tab.id);
      if (!entry) {
        const term = new XTerm({
          cursorBlink: true,
          cursorStyle: 'bar',
          fontFamily: 'SFMono-Regular, Menlo, Monaco, Consolas, monospace',
          fontSize: 11,
          lineHeight: 1.4,
          scrollback: 5000,
          convertEol: true,
          allowProposedApi: false,
          theme: pickTerminalTheme(themeRef.current),
        });
        const fit = new FitAddon();
        term.loadAddon(fit);
        term.open(host);
        term.onData((data) => {
          getBridgeTerminal()?.writeSession?.(data, tab.id);
        });
        entry = { term, fit, started: false, host };
        entriesRef.current.set(tab.id, entry);
        ensureResizeObserver().observe(host);
      }
      const ent: TabEntry = entry;
      if (ent.started || tab.exited) return;
      const bridge = getBridgeTerminal();
      if (!bridge?.startSession) return;
      ent.started = true; // 同步置位防并发重复启动；失败时回退
      bridge
        .startSession(tab.cwd, tab.id, sshRef.current || undefined)
        .then((result) => {
          if (!result?.ok) {
            ent.started = false;
            ent.term.writeln(
              `\r\n\x1b[31m[启动失败] ${result?.error || '桌面终端不可用'}\x1b[0m`
            );
            setRunningBy((prev) => ({ ...prev, [tab.id]: false }));
            return;
          }
          setRunningBy((prev) => ({ ...prev, [tab.id]: true }));
          window.requestAnimationFrame(() => {
            try {
              ent.fit.fit();
              bridge.resizeSession?.(ent.term.cols, ent.term.rows, tab.id);
              ent.term.focus();
            } catch {
              /* ignore */
            }
          });
        })
        .catch(() => {
          ent.started = false;
          setRunningBy((prev) => ({ ...prev, [tab.id]: false }));
        });
    },
    [ensureResizeObserver, getBridgeTerminal]
  );

  // Lazy start: panel open + tab active → ensure xterm + pty for the active tab.
  useEffect(() => {
    if (!open || !activeId) return;
    const tab = tabs.find((t) => t.id === activeId);
    if (tab) ensureSession(tab);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, activeId, tabs, ensureSession]);

  // Switch tab → refit + focus after paint (layout settled).
  useEffect(() => {
    if (!activeId) return;
    const handle = window.requestAnimationFrame(() => {
      const entry = entriesRef.current.get(activeId);
      if (!entry) return;
      try {
        entry.fit.fit();
        getBridgeTerminal()?.resizeSession?.(entry.term.cols, entry.term.rows, activeId);
        entry.term.focus();
      } catch {
        /* ignore */
      }
    });
    return () => window.cancelAnimationFrame(handle);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeId]);

  const openTab = useCallback(() => {
    setLimitNotice(null);
    const res = createTerminalTab(tabs, workspacePath);
    if ('limitReached' in res) {
      setLimitNotice(`最多同时打开 ${MAX_TERMINAL_TABS} 个终端标签，请先关闭不用的标签`);
      return;
    }
    setTabs(res.tabs);
    setActiveId(res.tab.id);
  }, [tabs, workspacePath]);

  const closeTab = useCallback(
    (id: string) => {
      setLimitNotice(null);
      const entry = entriesRef.current.get(id);
      if (entry?.started) getBridgeTerminal()?.stopSession?.(id);
      if (entry) {
        try {
          resizeObserverRef.current?.unobserve(entry.host);
        } catch {
          /* ignore */
        }
        entry.term.dispose();
      }
      entriesRef.current.delete(id);
      hostsRef.current.delete(id);
      setRunningBy((prev) => {
        const next = { ...prev };
        delete next[id];
        return next;
      });
      const res = closeTerminalTab(tabs, id);
      setTabs(res.tabs);
      setActiveId((cur) => (cur === id ? res.nextActiveId : cur));
    },
    [tabs, getBridgeTerminal]
  );

  const setActive = useCallback((id: string) => {
    setLimitNotice(null);
    setActiveId(id);
  }, []);

  const registerHost = useCallback(
    (id: string) =>
      (el: HTMLDivElement | null): void => {
        if (el) hostsRef.current.set(id, el);
        else hostsRef.current.delete(id);
      },
    []
  );

  const clear = useCallback(() => {
    const entry = activeIdRef.current
      ? entriesRef.current.get(activeIdRef.current)
      : undefined;
    entry?.term.clear();
  }, []);

  // Unmount: stop every started pty + dispose every instance (page leave).
  useEffect(() => {
    const entries = entriesRef;
    const observer = resizeObserverRef;
    return () => {
      const bridge = getBridgeTerminal();
      for (const [id, entry] of entries.current.entries()) {
        if (entry.started) bridge?.stopSession?.(id);
        try {
          observer.current?.unobserve(entry.host);
        } catch {
          /* ignore */
        }
        entry.term.dispose();
      }
      entries.current.clear();
      observer.current?.disconnect();
      observer.current = null;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return {
    tabs,
    activeId,
    setActive,
    openTab,
    closeTab,
    registerHost,
    limitNotice,
    dismissLimitNotice: () => setLimitNotice(null),
    clear,
    activeRunning: activeId ? runningBy[activeId] === true : false,
    runningBy,
  };
}

/**
 * useWorkspaceLayout — UI-371 会话框测量回归门。
 *
 * 被测缺陷（实机实证，非推测）：`SessionFrameView` 在 chat（常驻）/ scheduled（条件挂载）
 * 两个互斥分支各渲染一个实例，二者**共用同一个测量 ref**。原实现用普通 refObject +
 * 一次性 effect（deps: []）挂 RO，于是：
 *   ① scheduled 实例卸载时 React 对该元素调用 `ref(null)` → refObject.current 被置空，
 *      而常驻的 chat 实例不会被重新赋值 → 此后测量恒 0 → `summaryVisibility` 恒
 *      'expanded'（摘要卡恒钉住并被 `max-width` 挤成窄条）；
 *   ② RO 只在挂载时 observe 一次 → 节点被替换后观察的是已移除的旧节点，永不触发，
 *      尺寸冻在旧值（只有 window resize 能救）。
 *
 * 本门用可记录的 ResizeObserver 桩 + 按 data-w/data-h 返回尺寸的
 * `getBoundingClientRect` 桩，把五条不变量锁死：
 *   A1 多实例并存取可见（最大宽度）实例；A2 条件实例卸载后宽度不回零；
 *   A3 全部卸载保持上一个已知值；A4 新节点被立刻测量且被 RO 观察（旧节点被清理）；
 *   A5 RO 回调触发即重测（覆盖「无 render 的尺寸变化」，如面板开合）。
 */
import React from 'react';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { act, cleanup, render } from '@testing-library/react';
import { WorkspacePanelsProvider } from '@/components/desktop/WorkspacePanelsContext';
import { useWorkspaceLayout } from './useWorkspaceLayout';

type FrameSpec = { id: string; w: number; h: number };

/** 可记录/可手动触发的 ResizeObserver 桩（happy-dom 自带的 RO 不可控）。 */
class FakeResizeObserver {
  static instances: FakeResizeObserver[] = [];
  observed = new Set<Element>();
  private readonly callback: ResizeObserverCallback;
  constructor(callback: ResizeObserverCallback) {
    this.callback = callback;
    FakeResizeObserver.instances.push(this);
  }
  observe(target: Element): void { this.observed.add(target); }
  unobserve(target: Element): void { this.observed.delete(target); }
  disconnect(): void { this.observed.clear(); }
  trigger(): void { this.callback([], this as unknown as ResizeObserver); }
}

function Harness({ frames }: { frames: FrameSpec[] }): React.ReactElement {
  const layout = useWorkspaceLayout();
  return (
    <div>
      <output data-testid="w">{layout.sessionFrameWidth}</output>
      <output data-testid="h">{layout.sessionFrameHeight}</output>
      {frames.map((frame) => (
        <div
          key={frame.id}
          data-testid={`frame-${frame.id}`}
          data-w={frame.w}
          data-h={frame.h}
          ref={layout.sessionFrameRef}
        />
      ))}
    </div>
  );
}

/** useWorkspaceLayout 依赖 WorkspacePanelsProvider（上下文访问器无 provider 即抛错）。 */
const harness = (frames: FrameSpec[]) => (
  <WorkspacePanelsProvider>
    <Harness frames={frames} />
  </WorkspacePanelsProvider>
);

let originalRect: typeof Element.prototype.getBoundingClientRect;
let originalResizeObserver: unknown;

beforeEach(() => {
  FakeResizeObserver.instances = [];
  originalResizeObserver = (globalThis as { ResizeObserver?: unknown }).ResizeObserver;
  (globalThis as { ResizeObserver?: unknown }).ResizeObserver = FakeResizeObserver;
  originalRect = Element.prototype.getBoundingClientRect;
  // happy-dom 的布局全为 0：按 data-w/data-h 返回尺寸，让「测量」可断言。
  Element.prototype.getBoundingClientRect = function (this: HTMLElement): DOMRect {
    const width = Number(this.dataset?.w ?? 0);
    const height = Number(this.dataset?.h ?? 0);
    return { width, height, top: 0, left: 0, right: width, bottom: height, x: 0, y: 0, toJSON: () => ({}) } as DOMRect;
  };
  if (typeof window.matchMedia !== 'function') {
    (window as { matchMedia?: unknown }).matchMedia = ((query: string) => ({
      matches: false, media: query, onchange: null,
      addEventListener: () => {}, removeEventListener: () => {},
      addListener: () => {}, removeListener: () => {}, dispatchEvent: () => false,
    })) as unknown as typeof window.matchMedia;
  }
});

afterEach(() => {
  Element.prototype.getBoundingClientRect = originalRect;
  (globalThis as { ResizeObserver?: unknown }).ResizeObserver = originalResizeObserver;
  cleanup();
});

describe('useWorkspaceLayout 会话框测量（UI-371）', () => {
  it('A1 多实例并存时取可见（最大宽度）实例的尺寸', () => {
    const view = render(harness([{ id: 'chat', w: 700, h: 600 }, { id: 'sched', w: 0, h: 0 }]));
    expect(view.getByTestId('w').textContent).toBe('700');
    expect(view.getByTestId('h').textContent).toBe('600');
  });

  it('A2 条件实例卸载（ref 回调收到 null）后宽度不回零 —— 缺陷①回归', () => {
    const view = render(harness([{ id: 'chat', w: 700, h: 600 }, { id: 'sched', w: 0, h: 0 }]));
    expect(view.getByTestId('w').textContent).toBe('700');

    // scheduled 实例卸载：旧实现下 React 会把共用 refObject 置 null → 测量写 0
    view.rerender(harness([{ id: 'chat', w: 700, h: 600 }]));
    expect(view.getByTestId('w').textContent).toBe('700');
  });

  it('A3 全部实例卸载时保持上一个已知宽度（不把「暂无节点」写成 0）', () => {
    const view = render(harness([{ id: 'chat', w: 700, h: 600 }]));
    expect(view.getByTestId('w').textContent).toBe('700');

    view.rerender(harness([]));
    expect(view.getByTestId('w').textContent).toBe('700');
  });

  it('A4 替换后的新节点立刻被测量且被 RO 观察，旧节点被清理 —— 缺陷②回归', () => {
    const view = render(harness([{ id: 'chat', w: 700, h: 600 }]));
    const first = view.getByTestId('frame-chat');
    const observer = FakeResizeObserver.instances[0];
    expect(observer?.observed.has(first)).toBe(true);

    view.rerender(harness([{ id: 'next', w: 420, h: 500 }]));
    const next = view.getByTestId('frame-next');

    expect(view.getByTestId('w').textContent).toBe('420');
    expect(observer?.observed.has(next)).toBe(true);   // 旧实现永不 observe 新节点
    expect(observer?.observed.has(first)).toBe(false); // 已移除节点被 unobserve
  });

  it('A5 RO 回调触发即重测（覆盖面板开合等无 render 的尺寸变化）', () => {
    const view = render(harness([{ id: 'chat', w: 700, h: 600 }]));
    const observer = FakeResizeObserver.instances[0];
    const node = view.getByTestId('frame-chat');

    node.dataset.w = '900';
    act(() => observer.trigger());

    expect(view.getByTestId('w').textContent).toBe('900');
  });
});

/**
 * useWorkspaceLayout — panel visibility, responsive breakpoint, and
 * measured DOM dimensions for the ProjectWorkspace shell.
 *
 * Optionally accepts panel overrides from WorkspacePanelsContext so
 * TitleBar-driven state takes precedence over the layout's own state.
 *
 * State owned here:
 * - leftOpen / rightOpen         — panel collapse toggles
 * - compactLayout                — viewport < 960px breakpoint
 * - bottomTerminalOpen           — terminal drawer
 * - summaryOpen                  — pinned summary card visibility
 * - centerColWidth               — measured from ResizeObserver
 * - sessionFrameWidth/Height     — measured from ResizeObserver
 */
import { useCallback, useEffect, useRef, useState } from 'react';
import { useWorkspacePanelsContext } from '@/components/desktop/WorkspacePanelsContext';

export interface UseWorkspaceLayoutResult {
  // Panel toggles
  leftOpen: boolean;
  setLeftOpen: React.Dispatch<React.SetStateAction<boolean>>;
  rightOpen: boolean;
  setRightOpen: React.Dispatch<React.SetStateAction<boolean>>;
  compactLayout: boolean;
  viewportWidth: number;

  // Terminal
  bottomTerminalOpen: boolean;
  setBottomTerminalOpen: React.Dispatch<React.SetStateAction<boolean>>;

  // Summary card
  summaryOpen: boolean;
  setSummaryOpen: React.Dispatch<React.SetStateAction<boolean>>;

  // Measured refs (for passing to children who observe them)
  centerColRef: React.RefObject<HTMLElement | null>;
  /**
   * UI-371 — 会话框测量 ref，**回调式**（可直接传给任意多个元素的 `ref=`）。
   * 每次节点挂载都会重新挂 ResizeObserver 并立刻测量；实例卸载时按连通性自清理。
   */
  sessionFrameRef: React.Ref<HTMLDivElement>;
  centerColWidth: number;
  sessionFrameWidth: number;
  sessionFrameHeight: number;
}

export function useWorkspaceLayout(): UseWorkspaceLayoutResult {
  const ctx = useWorkspacePanelsContext();
  const ctxAvailable = ctx !== null;

  // ── Panel toggles (from context if available, else local) ─────
  const [leftOpenLocal, setLeftOpenLocal] = useState(true);
  const [rightOpenLocal, setRightOpenLocal] = useState(true);
  const [compactLayout, setCompactLayout] = useState(
    () => window.matchMedia('(max-width: 960px)').matches,
  );
  const [viewportWidth, setViewportWidth] = useState(() => window.innerWidth);

  // ── Terminal ────────────────────────────────────────────────────
  const [bottomTerminalOpenLocal, setBottomTerminalOpenLocal] = useState(false);

  const leftOpen = ctxAvailable ? ctx.leftOpen : leftOpenLocal;
  const setLeftOpen = ctxAvailable ? ctx.setLeftOpen : setLeftOpenLocal;
  const rightOpen = ctxAvailable ? ctx.rightOpen : rightOpenLocal;
  const setRightOpen = ctxAvailable ? ctx.setRightOpen : setRightOpenLocal;
  const bottomTerminalOpen = ctxAvailable ? ctx.bottomTerminalOpen : bottomTerminalOpenLocal;
  const setBottomTerminalOpen = ctxAvailable ? ctx.setBottomTerminalOpen : setBottomTerminalOpenLocal;

  // ── Summary card ────────────────────────────────────────────────
  const [summaryOpenLocal, setSummaryOpenLocal] = useState(false);

  const summaryOpen = ctxAvailable ? ctx.summaryOpen : summaryOpenLocal;
  const setSummaryOpen = ctxAvailable ? ctx.setSummaryOpen : setSummaryOpenLocal;

  // ── Measured DOM dimensions ─────────────────────────────────────
  const [centerColWidth, setCenterColWidth] = useState(0);
  const [sessionFrameWidth, setSessionFrameWidth] = useState(0);
  const [sessionFrameHeight, setSessionFrameHeight] = useState(0);
  const centerColRef = useRef<HTMLElement | null>(null);
  const sessionFrameNodesRef = useRef<Set<HTMLDivElement>>(new Set());
  const sessionFrameObserverRef = useRef<ResizeObserver | null>(null);

  // ── Effects ─────────────────────────────────────────────────────

  // Responsive: 仅记录是否 compact（驱动浮层渲染），不动侧栏开合状态。
  useEffect(() => {
    const media = window.matchMedia('(max-width: 960px)');
    const syncLayout = (compact: boolean) => setCompactLayout(compact);
    syncLayout(media.matches);
    const onChange = (event: MediaQueryListEvent) => syncLayout(event.matches);
    media.addEventListener('change', onChange);
    return () => media.removeEventListener('change', onChange);
  }, []);

  useEffect(() => {
    const updateViewportWidth = () => setViewportWidth(window.innerWidth);
    updateViewportWidth();
    window.addEventListener('resize', updateViewportWidth);
    return () => window.removeEventListener('resize', updateViewportWidth);
  }, []);

  // compactLayout 只驱动「浮层渲染样式」（≤960px 时侧栏变浮层 + backdrop），
  // **不再自动收起侧栏**（UI-341 加映二 用户裁决 2026-09-11：侧栏常驻打开，
  // 只由用户主动点击关闭）。原实现在进 compact 时 setLeftOpen/setRightOpen(false)，
  // 于是窄窗口下每次进入页面都表现为「左栏自己消失 + 页面像全屏盖住导航」，
  // 且变宽后不还原（状态残留）。

  // Measure center column width.
  useEffect(() => {
    const element = centerColRef.current;
    if (!element) return;
    const updateWidth = () => setCenterColWidth(element.getBoundingClientRect().width || 0);
    updateWidth();
    window.addEventListener('resize', updateWidth);
    return () => window.removeEventListener('resize', updateWidth);
  }, []);

  // Measure session frame dimensions.
  // UI-351 抓真修：原实现在挂载时 `sessionFrameRef.current` 为 null 就整段
  // return——此后再无任何测量，sessionFrameWidth 永远停在 0，摘要卡恒按
  // 'expanded' 钉住（宽度恒 300px），「compact/悬浮随宽度自适应」从未生效。
  // 改为 rAF 等待 ref 就绪后再挂 RO + resize 监听（ref 晚于 effect 就绪的
  // 场景：SessionFrameView 在子树条件分支内，挂载顺序晚于本 hook 的 effect）。
  //
  // UI-371 — 上述 rAF 修法仍有两个真实缺陷（实机实证，非推测）：
  //   ① **共用 refObject 被两处挂载**：`SessionFrameView` 在两个互斥分支各渲染一个
  //      实例（chat 那个常驻、scheduled 那个条件挂载），而两者 `ref={ctx.sessionFrameRef}`
  //      共用同一个 refObject。scheduled 实例卸载时 React 对该元素调用 `ref(null)` →
  //      refObject.current 被置空；**常驻的 chat 实例并不会被重新赋值**（它没有重挂）
  //      → `sessionFrameRef.current === null` → 之后每次测量都写 0 →
  //      `summaryVisibility` 恒 'expanded'：摘要卡恒按钉住列渲染并被
  //      `max-width: calc(100% - 24px)` 挤成窄条，float/compact 形态彻底失效。
  //   ② **RO 只 observe 一次**：节点被替换/重挂后观察的是已移除的旧节点，永不触发
  //      → 尺寸冻在旧值，面板开合/分支切换都不再重测（只有 window resize 能救）。
  // 修法：测量 ref 改**回调式** + 活节点集合：
  //   · 每次节点挂载都 observe 并立刻测量（不再依赖 rAF 轮询与「只挂一次」）；
  //   · 回调收到 null（有实例卸载）时按 `isConnected` 自清理，绕开「回调拿不到是哪个
  //     节点卸载」的限制（仍连通的节点留待 RO 触发时再清，无副作用）；
  //   · 宽度取「所有已挂载会话框的最大值」——chat/scheduled 两实例并存时只有一个可见，
  //     隐藏的那个是 display:none（宽度 0），故最大值即当前可见会话框宽度；
  //   · 0 宽不写入状态（切模式瞬间/离开工作区），避免把摘要卡瞬时误判为 'expanded'。
  const measureSessionFrames = useCallback(() => {
    const nodes = sessionFrameNodesRef.current;
    const observer = sessionFrameObserverRef.current;
    let width = 0;
    let height = 0;
    for (const node of Array.from(nodes)) {
      if (!node.isConnected) {
        observer?.unobserve(node);
        nodes.delete(node);
        continue;
      }
      const rect = node.getBoundingClientRect();
      if (rect.width > width) {
        width = rect.width;
        height = rect.height;
      }
    }
    if (width > 0) {
      setSessionFrameWidth(width);
      setSessionFrameHeight(height);
    }
  }, []);

  const sessionFrameRef = useCallback((node: HTMLDivElement | null) => {
    if (node) {
      sessionFrameNodesRef.current.add(node);
      if (typeof ResizeObserver !== 'undefined') {
        if (!sessionFrameObserverRef.current) {
          sessionFrameObserverRef.current = new ResizeObserver(measureSessionFrames);
        }
        sessionFrameObserverRef.current.observe(node);
      }
    }
    measureSessionFrames();
  }, [measureSessionFrames]);

  useEffect(() => {
    window.addEventListener('resize', measureSessionFrames);
    return () => {
      window.removeEventListener('resize', measureSessionFrames);
      sessionFrameObserverRef.current?.disconnect();
      sessionFrameObserverRef.current = null;
      sessionFrameNodesRef.current.clear();
    };
  }, [measureSessionFrames]);

  return {
    leftOpen,
    setLeftOpen,
    rightOpen,
    setRightOpen,
    compactLayout,
    viewportWidth,
    bottomTerminalOpen,
    setBottomTerminalOpen,
    summaryOpen,
    setSummaryOpen,
    centerColRef,
    sessionFrameRef,
    centerColWidth,
    sessionFrameWidth,
    sessionFrameHeight,
  };
}

