// Petri 桌面版 auth client — 简化版
// 桌面版无登录，固定本地 admin 用户，所有模块权限全开。
// 替代 Docusaurus 版 authClient.ts 的桌面分支。

import { errMsg } from '@/lib/error';
import { getApiPrefix, getComputeApiPrefix, getPlatformApiPrefix } from '@/lib/env';

export const IS_DESKTOP = true;

export interface AuthUser {
  id: string;
  username: string;
  role: string;
  permissions?: Record<string, boolean>;
}

const DESKTOP_USER: AuthUser = {
  id: 'local-user',
  username: 'Local User',
  role: 'admin',
  permissions: {
    docs: true,
    blog: true,
    tools: true,
    copilot: true,
  },
};

export { getApiPrefix, getComputeApiPrefix, getPlatformApiPrefix };

// 桌面版固定 admin，无需登录
export function getToken(): string | null {
  return 'desktop-local';
}
export function getStoredUser(): AuthUser | null {
  return DESKTOP_USER;
}
export function isLoggedIn(): boolean {
  return true;
}
export function hasModule(user: AuthUser | null, moduleKey: string): boolean {
  return true;
}
export function clearAuth(): void {}
export function logout(): void {}
export function subscribeAuth(callback: (user: AuthUser | null) => void): () => void {
  return () => {};
}
export function getCachedGuestPermissions(): Record<string, boolean> | null {
  return null;
}
export async function fetchGuestPermissions(): Promise<Record<string, boolean> | null> {
  return null;
}
export async function fetchMe(): Promise<AuthUser | null> {
  return DESKTOP_USER;
}

// login/register 桌面版不应被调用，保留 stub 防止类型缺口
export async function login(
  _username: string,
  _password: string
): Promise<{ ok: boolean; error?: string }> {
  return { ok: true };
}
export async function register(_data: {
  username: string;
  password: string;
  email?: string;
}): Promise<{ ok: boolean; error?: string }> {
  return { ok: true };
}

export { errMsg };

// ============================================================
// branchBridge 拆包 + 行映射契约回归（UI-P2-001）
//
// branch:* handler 统一返回 fail-closed 信封 { ok, data?, error? }，
// 落库行为 snake_case（src/database/branch-db.js 原样返回），本桥是
// 唯一拆包 + snake→camel 映射点。回归锁定：
//  1) 此前信封被原样透传，/project/:id/results 首次加载即把信封当
//     数组用（branches.find is not a function），分支 tab 永不渲染；
//  2) switch 缺 projectId、delete/rename 参数键 branchId≠id，
//     UI 切分支恒被 handler 以 "branchId and projectId are required" 拒绝。
// ============================================================
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import type { Branch } from '@/types/branch.types';

const ROW_FIXTURE = {
  id: 'b1',
  project_id: 'p1',
  name: 'main',
  parent_branch_id: null,
  created_at: 100,
  updated_at: 200,
  is_active: 1,
};

const BRANCH_FIXTURE: Branch = {
  id: 'b1',
  projectId: 'p1',
  name: 'main',
  parentBranchId: null,
  createdAt: 100,
  updatedAt: 200,
  isActive: true,
};

type Envelope = { ok: boolean; data?: unknown; error?: string };

function stubBridge(methods: Record<string, unknown>): void {
  (window as unknown as Record<string, unknown>).petri = { branch: methods };
}

async function loadBranchApi() {
  vi.resetModules();
  const mod = await import('@/lib/branchBridge');
  return mod.branchApi;
}

beforeEach(() => {
  delete (window as unknown as Record<string, unknown>).petri;
  delete (window as unknown as Record<string, unknown>).petriDesktop;
});

afterEach(() => {
  delete (window as unknown as Record<string, unknown>).petri;
  delete (window as unknown as Record<string, unknown>).petriDesktop;
  vi.restoreAllMocks();
});

describe('branchBridge envelope unwrap + row mapping (UI-P2-001)', () => {
  it('list：信封拆包 + snake→camel 映射返回裸 Branch 数组（崩溃回归锁定）', async () => {
    const list = vi.fn(async (): Promise<Envelope> => ({
      ok: true,
      data: [ROW_FIXTURE],
    }));
    stubBridge({ list });
    const api = await loadBranchApi();
    const branches = await api.list('p1');
    expect(Array.isArray(branches)).toBe(true);
    expect(branches).toEqual([BRANCH_FIXTURE]);
    expect(list).toHaveBeenCalledWith({ projectId: 'p1' });
  });

  it('create：信封拆包返回裸 Branch；isActive 数字 0/1 → false/true', async () => {
    stubBridge({
      create: vi.fn(async (): Promise<Envelope> => ({
        ok: true,
        data: { ...ROW_FIXTURE, is_active: 0 },
      })),
    });
    const api = await loadBranchApi();
    const created = await api.create('p1', 'feature-x');
    expect(created.isActive).toBe(false);
    expect(created.projectId).toBe('p1');
    expect(created.parentBranchId).toBeNull();
  });

  it('switch：参数键 { branchId, projectId }（handler 契约），返回映射后 Branch', async () => {
    const sw = vi.fn(async (): Promise<Envelope> => ({ ok: true, data: ROW_FIXTURE }));
    stubBridge({ switch: sw });
    const api = await loadBranchApi();
    const active = await api.switch('b1', 'p1');
    expect(sw).toHaveBeenCalledWith({ branchId: 'b1', projectId: 'p1' });
    expect(active).toEqual(BRANCH_FIXTURE);
  });

  it('delete/rename：参数键为 id（非 branchId），按 handler 契约传参', async () => {
    const del = vi.fn(async (): Promise<Envelope> => ({ ok: true }));
    const rename = vi.fn(async (): Promise<Envelope> => ({ ok: true, data: ROW_FIXTURE }));
    stubBridge({ delete: del, rename });
    const api = await loadBranchApi();
    await expect(api.delete('b1')).resolves.toBeUndefined();
    await expect(api.rename('b1', 'renamed')).resolves.toBeUndefined();
    expect(del).toHaveBeenCalledWith({ id: 'b1' });
    expect(rename).toHaveBeenCalledWith({ id: 'b1', newName: 'renamed' });
  });

  it('getActive：data null → null（项目尚无分支）', async () => {
    stubBridge({
      getActive: vi.fn(async (): Promise<Envelope> => ({ ok: true, data: null })),
    });
    const api = await loadBranchApi();
    await expect(api.getActive('p1')).resolves.toBeNull();
  });

  it('error 信封：抛出 handler 错误信息（store 侧进 error 态）', async () => {
    stubBridge({
      list: vi.fn(async (): Promise<Envelope> => ({ ok: false, error: 'db closed' })),
    });
    const api = await loadBranchApi();
    await expect(api.list('p1')).rejects.toThrow('db closed');
  });

  it('switch error 信封：UI 切分支失败不再被静默吞掉', async () => {
    stubBridge({
      switch: vi.fn(async (): Promise<Envelope> => ({
        ok: false,
        error: 'branchId and projectId are required',
      })),
    });
    const api = await loadBranchApi();
    await expect(api.switch('b1', 'p1')).rejects.toThrow(
      'branchId and projectId are required'
    );
  });

  it('桥不可用：兜底空值语义不抛错（list → []，getActive → null）', async () => {
    const api = await loadBranchApi();
    await expect(api.list('p1')).resolves.toEqual([]);
    await expect(api.getActive('p1')).resolves.toBeNull();
  });
});

// ============================================================
// branchBridge — IPC wrapper for branch operations
//
// Wraps Electron IPC calls to the main process branch API.
// Uses the typed bridge accessor from desktopBridge.ts.
//
// UI-P2-001 — branch:* handler 统一返回 fail-closed 信封 { ok, data?, error? }
// （与 result:* 的 UI-311 同型），本桥是 branch 命名空间的唯一拆包 + 行映射点：
// handler 落库行是 snake_case（project_id / is_active / created_at …），
// 消费方（useBranchStore / ResultStudioPage）见裸 camelCase Branch 契约。
// 此前无人拆包，/project/:id/results 首次加载即把信封当数组用
// （branches.find is not a function），分支 tab 永不渲染；且 switch/delete/
// rename 的参数键与 handler 契约不符（缺 projectId / branchId≠id），
// UI 切分支恒被 handler 以 "branchId and projectId are required" 拒绝。
// ============================================================

import { getBridge } from '@/lib/desktopBridge';
import type { Branch } from '@/types/branch.types';

interface BranchIpcEnvelope<T> {
  ok: boolean;
  data?: T;
  error?: string;
}

/** branch:* handler 的落库行（snake_case SQLite 列，见 src/database/branch-db.js）。 */
interface BranchRow {
  id: string;
  project_id: string;
  name: string;
  parent_branch_id: string | null;
  created_at: number;
  updated_at: number;
  is_active: number | boolean;
}

/** ok=true → data；否则抛 handler 错误信息（store 捕获后进 error 态）。 */
async function unwrap<T>(call: Promise<BranchIpcEnvelope<T>>): Promise<T> {
  const envelope = await call;
  if (!envelope || envelope.ok !== true) {
    throw new Error(envelope?.error || 'Branch bridge error');
  }
  return envelope.data as T;
}

/** snake_case 落库行 → 前端 camelCase Branch 契约（types/branch.types.ts）。 */
function toBranch(row: BranchRow | null | undefined): Branch | null {
  if (!row || !row.id) return null;
  return {
    id: row.id,
    projectId: row.project_id,
    name: row.name,
    parentBranchId: row.parent_branch_id ?? null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
    isActive: Boolean(row.is_active),
  };
}

function createBranchBridge(): {
  create: (projectId: string, name: string, parentBranchId?: string) => Promise<Branch>;
  list: (projectId: string) => Promise<Branch[]>;
  switch: (branchId: string, projectId: string) => Promise<Branch | null>;
  delete: (branchId: string) => Promise<void>;
  rename: (branchId: string, newName: string) => Promise<void>;
  getActive: (projectId: string) => Promise<Branch | null>;
} {
  const bridge = getBridge('branch');

  if (!bridge) {
    // Stub implementation when branch bridge is not available
    return {
      create: async () => {
        throw new Error('Branch bridge not available');
      },
      list: async () => [],
      switch: async () => {
        throw new Error('Branch bridge not available');
      },
      delete: async () => {
        throw new Error('Branch bridge not available');
      },
      rename: async () => {
        throw new Error('Branch bridge not available');
      },
      getActive: async () => null,
    };
  }

  return {
    create: async (projectId, name, parentBranchId) => {
      const row = await unwrap<BranchRow>(
        bridge.create({ projectId, name, parentBranchId }) as Promise<BranchIpcEnvelope<BranchRow>>
      );
      return toBranch(row) as Branch;
    },

    list: async (projectId) => {
      const rows = await unwrap<BranchRow[]>(
        bridge.list({ projectId }) as Promise<BranchIpcEnvelope<BranchRow[]>>
      );
      return (rows || []).map(toBranch).filter((b): b is Branch => b !== null);
    },

    switch: async (branchId, projectId) => {
      const row = await unwrap<BranchRow>(
        bridge.switch({ branchId, projectId }) as Promise<BranchIpcEnvelope<BranchRow>>
      );
      return toBranch(row);
    },

    delete: async (branchId) => {
      // handler 契约参数键是 id（src/ipc/branch-handlers.js branch:delete）
      await unwrap(bridge.delete({ id: branchId }) as Promise<BranchIpcEnvelope<undefined>>);
    },

    rename: async (branchId, newName) => {
      // handler 契约参数键是 id + newName（branch:rename）
      await unwrap(
        bridge.rename({ id: branchId, newName }) as Promise<BranchIpcEnvelope<BranchRow>>
      );
    },

    getActive: async (projectId) => {
      const row = await unwrap<BranchRow | null>(
        bridge.getActive({ projectId }) as Promise<BranchIpcEnvelope<BranchRow | null>>
      );
      return toBranch(row);
    },
  };
}

export const branchApi = createBranchBridge();

