async function jsonOrThrow<T>(resp: Response): Promise<T> {
  const body = await resp.json().catch(() => ({}));
  if (!resp.ok || (body as { status?: string }).status === 'error') {
    throw new Error((body as { error?: string }).error || `HTTP ${resp.status}`);
  }
  return body as T;
}

