/** POST /api/loop/runs/:loopRunId/abort — request the loop stop on next pre-turn check. */
export async function abortLoopRun(
  loopRunId: string
): Promise<{ loopRunId: string; aborted: boolean; updatedAt: string }> {
  const resp = await fetch(`${loopBase()}/runs/${encodeURIComponent(loopRunId)}/abort`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...authHeaders() },
  });
  const data = (await resp.json()) as {
    ok?: boolean;
    error?: string;
    loopRunId: string;
    aborted: boolean;
    updatedAt: string;
  };
  if (!resp.ok || !data.ok) {
    throw new Error(data.error || `loop abort failed: HTTP ${resp.status}`);
  }
  return { loopRunId: data.loopRunId, aborted: data.aborted, updatedAt: data.updatedAt };
}

// ---------------------------------------------------------------------------
// Presentation helpers — pure, shared by chat + summary so completion state
// has ONE derivation (never a second source of truth).
// ---------------------------------------------------------------------------

/** A loop is "done successfully" ONLY when the backend says completed. */
export function isLoopComplete(status: LoopStatus | string | null | undefined): boolean {
  return status === 'completed';
}

/** failed/blocked/cancelled are terminal-but-not-success; must never show green. */
export function isLoopUnsuccessfulTerminal(status: LoopStatus | string | null | undefined): boolean {
  return status === 'failed' || status === 'blocked' || status === 'cancelled';
}

/** Map a loop status to a compact, honest phase label for the chat/summary. */
export function loopStatusLabel(status: LoopStatus | string | null | undefined): string {
  switch (status) {
    case 'planned': return '已规划';
    case 'running': return '执行中';
    case 'completed': return '已完成';
    case 'failed': return '失败';
    case 'blocked': return '已阻断';
    case 'cancelled': return '已取消';
    default: return '未知';
  }
}

// ---------------------------------------------------------------------------
// Loop display derivation — ONE honest mapping from live loop state to a
// compact status chip. Shared by chat + summary so they never disagree, and
// so a blocked / false-success run can NEVER render as a green completion.
// ---------------------------------------------------------------------------

export interface LoopDisplay {
  status: 'running' | 'completed' | 'blocked' | 'cancelled' | 'retrying' | 'idle';
  label: string;
  /** visual tone: success is the ONLY green; blocked is warning, never green. */
  tone: 'running' | 'success' | 'warning' | 'neutral';
  /** number of recorded iterations (attempts) this run. */
  attempts: number;
}

export function deriveLoopDisplay(
  loop:
    | { phase?: string; iterations?: LoopIterationEvent[]; lastDecision?: string }
    | null
    | undefined,
  pending?: boolean
): LoopDisplay {
  const iterations = loop?.iterations || [];
  const attempts = iterations.length;
  const phase = loop?.phase;
  const lastDecision = loop?.lastDecision || iterations[iterations.length - 1]?.decision;

  // A validator block or false-success detection must win over everything —
  // it can never be shown as a green completion.
  const anyBlocked = iterations.some((it) => it.decision === 'block' || it.status === 'blocked');
  if (anyBlocked || phase === 'blocked') {
    return { status: 'blocked', label: '已阻断', tone: 'warning', attempts };
  }
  if (phase === 'cancelled' || lastDecision === 'cancel') {
    return { status: 'cancelled', label: '已取消', tone: 'neutral', attempts };
  }
  if (phase === 'completed' || lastDecision === 'complete') {
    return { status: 'completed', label: '已完成', tone: 'success', attempts };
  }
  if (lastDecision === 'retry') {
    return { status: 'retrying', label: '重试中', tone: 'running', attempts };
  }
  if (pending || phase === 'started' || phase === 'resumed' || phase === 'running') {
    return { status: 'running', label: '执行中', tone: 'running', attempts };
  }
  return { status: 'idle', label: '等待中', tone: 'neutral', attempts };
}

export function loopDecisionLabel(decision: string | null | undefined): string {
  switch (decision) {
    case 'continue': return '继续';
    case 'retry': return '重试';
    case 'block': return '阻断';
    case 'wait': return '等待确认';
    case 'complete': return '完成';
    case 'cancel': return '取消';
    default: return decision || '';
  }
}

// ============================================================
// markdownDiff — BLOCK-18 markdown 前后差异算法
//
// 三种 diff：
//   - computeSimpleDiff：BLOCK-17 傻瓜并排（保留为 fallback / 回归对照）
//   - computeLcsDiff : LCS 双列并排（git-style 折叠）
//   - computeUnifiedDiff : LCS 单列 unified（git diff 默认风格，带 @@ hunk 头）
//
// 渲染端按 `classifyDiffLine` 上色，无需感知算法来源。
// ============================================================

export interface DiffSide {
  left: string[];
  right: string[];
}

export type DiffLineKind = 'add' | 'del' | 'ctx' | 'fold' | 'hunk';

// ---------- 旧版 BLOCK-17 傻瓜并排 ----------

export function computeSimpleDiff(left: string, right: string): DiffSide {
  const leftLines = left.split('\n');
  const rightLines = right.split('\n');
  const minLen = Math.min(leftLines.length, rightLines.length);
  const result: DiffSide = { left: [], right: [] };
  for (let i = 0; i < minLen; i++) {
    if (leftLines[i] === rightLines[i]) {
      result.left.push(` ${leftLines[i]}`);
      result.right.push(` ${rightLines[i]}`);
    } else {
      result.left.push(`-${leftLines[i]}`);
      result.right.push(`+${rightLines[i]}`);
    }
  }
  for (let i = minLen; i < leftLines.length; i++) {
    result.left.push(`-${leftLines[i]}`);
    result.right.push('  ');
  }
  for (let i = minLen; i < rightLines.length; i++) {
    result.left.push('  ');
    result.right.push(`+${rightLines[i]}`);
  }
  return result;
}

// ---------- LCS 共享底层 ----------

type Op = { kind: 'eq' | 'del' | 'add'; line: string };

export function buildOps(leftLines: string[], rightLines: string[]): Op[] {
  const m = leftLines.length;
  const n = rightLines.length;
  // dp 使用 number[]（避免 Uint32Array 在 V8 里的特殊处理）
  const dp: number[][] = [];
  for (let i = 0; i <= m; i++) {
    dp.push(new Array<number>(n + 1).fill(0));
  }
  for (let i = 1; i <= m; i++) {
    const li = leftLines[i - 1];
    for (let j = 1; j <= n; j++) {
      if (li === rightLines[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1] + 1;
      } else {
        dp[i][j] = dp[i - 1][j] >= dp[i][j - 1] ? dp[i - 1][j] : dp[i][j - 1];
      }
    }
  }
  const ops: Op[] = [];
  let i = m;
  let j = n;
  while (i > 0 && j > 0) {
    if (leftLines[i - 1] === rightLines[j - 1]) {
      ops.push({ kind: 'eq', line: leftLines[i - 1] });
      i--; j--;
    } else if (dp[i - 1][j] >= dp[i][j - 1]) {
      ops.push({ kind: 'del', line: leftLines[i - 1] });
      i--;
    } else {
      ops.push({ kind: 'add', line: rightLines[j - 1] });
      j--;
    }
  }
  while (i > 0) { ops.push({ kind: 'del', line: leftLines[i - 1] }); i--; }
  while (j > 0) { ops.push({ kind: 'add', line: rightLines[j - 1] }); j--; }
  ops.reverse();
  return ops;
}

// ---------- computeLcsDiff 双列 ----------

export function computeLcsDiff(left: string, right: string, context = 3): DiffSide {
  const leftLines = left.split('\n');
  const rightLines = right.split('\n');
  const ops = buildOps(leftLines, rightLines);
  const sides: DiffSide = { left: [], right: [] };
  let k = 0;
  while (k < ops.length) {
    const op = ops[k];
    if (op.kind === 'eq') {
      let runEnd = k;
      while (runEnd + 1 < ops.length && ops[runEnd + 1].kind === 'eq') runEnd++;
      const runLen = runEnd - k + 1;
      let nearBefore = false;
      let nearAfter = false;
      for (let d = 1; d <= context; d++) {
        if (k - d >= 0 && ops[k - d].kind !== 'eq') { nearBefore = true; break; }
      }
      for (let d = 1; d <= context; d++) {
        if (runEnd + d < ops.length && ops[runEnd + d].kind !== 'eq') { nearAfter = true; break; }
      }
      const anyNear = nearBefore || nearAfter;
      if (!anyNear || runLen <= context * 2) {
        for (let q = k; q <= runEnd; q++) {
          sides.left.push(` ${ops[q].line}`);
          sides.right.push(` ${ops[q].line}`);
        }
      } else {
        const head = context;
        const tail = context;
        const foldCount = runLen - head - tail;
        for (let q = 0; q < head; q++) {
          sides.left.push(` ${ops[k + q].line}`);
          sides.right.push(` ${ops[k + q].line}`);
        }
        sides.left.push(`… ${foldCount} unchanged line${foldCount === 1 ? '' : 's'}`);
        sides.right.push(`… ${foldCount} unchanged line${foldCount === 1 ? '' : 's'}`);
        for (let q = 0; q < tail; q++) {
          sides.left.push(` ${ops[runEnd - tail + 1 + q].line}`);
          sides.right.push(` ${ops[runEnd - tail + 1 + q].line}`);
        }
      }
      k = runEnd + 1;
    } else if (op.kind === 'del') {
      let runEnd = k;
      while (runEnd + 1 < ops.length && ops[runEnd + 1].kind === 'del') runEnd++;
      for (let q = k; q <= runEnd; q++) {
        sides.left.push(`-${ops[q].line}`);
        sides.right.push('  ');
      }
      k = runEnd + 1;
    } else {
      let runEnd = k;
      while (runEnd + 1 < ops.length && ops[runEnd + 1].kind === 'add') runEnd++;
      for (let q = k; q <= runEnd; q++) {
        sides.left.push('  ');
        sides.right.push(`+${ops[q].line}`);
      }
      k = runEnd + 1;
    }
  }
  return sides;
}

// ---------- computeUnifiedDiff 单列 (BLOCK-18 用户要的 unified) ----------

function appendFoldedEqRun(
  out: string[],
  lines: string[],
  context: number,
) {
  if (lines.length === 0) return;
  if (lines.length <= context * 2) {
    for (const l of lines) out.push(` ${l}`);
    return;
  }
  const head = context;
  const tail = context;
  const foldCount = lines.length - head - tail;
  for (let i = 0; i < head; i++) out.push(` ${lines[i]}`);
  out.push(`… ${foldCount} unchanged line${foldCount === 1 ? '' : 's'}`);
  for (let i = lines.length - tail; i < lines.length; i++) out.push(` ${lines[i]}`);
}

/**
 * 找出 ops 中所有 hunk（[0..n-1] 区间）的 [start, end) 半开区间。
 * 每个 hunk 包含：前 context 行 eq + 连续 del/add + 后 context 行 eq。
 */
function computeHunkRanges(ops: Op[], context: number): Array<[number, number]> {
  const hunks: Array<[number, number]> = [];
  // 第一遍：标记每个 eq 是否被 hunk 内的 ctx 保留（即是否在某个改动的前后 context 行内）
  const kept = new Array<boolean>(ops.length).fill(false);
  for (let i = 0; i < ops.length; i++) {
    if (ops[i].kind !== 'eq') continue;
    // 看 i 前后 context 行内是否有非 eq
    let nearChange = false;
    for (let d = 1; d <= context; d++) {
      if (i - d >= 0 && ops[i - d].kind !== 'eq') { nearChange = true; break; }
      if (i + d < ops.length && ops[i + d].kind !== 'eq') { nearChange = true; break; }
    }
    if (nearChange) kept[i] = true;
  }
  // 第二遍：找出所有 hunks（被 kept 的 eq 也属于某个 hunk）
  let k = 0;
  while (k < ops.length) {
    // 跳过"游离" eq（即前后都没改动的 eq）
    while (k < ops.length && ops[k].kind === 'eq' && !kept[k]) k++;
    if (k >= ops.length) break;
    const start = k;
    // 找连续 hunk 区域：所有非游离 ops（被 kept 的 eq + 所有非 eq）
    while (k < ops.length && (ops[k].kind !== 'eq' || kept[k])) k++;
    const end = k;
    hunks.push([start, end]);
  }
  // 合并相邻 hunk
  const merged: Array<[number, number]> = [];
  for (const h of hunks) {
    const last = merged[merged.length - 1];
    if (last && last[1] >= h[0]) {
      last[1] = Math.max(last[1], h[1]);
    } else {
      merged.push([h[0], h[1]]);
    }
  }
  return merged;
}

function hunkHeaderCounts(
  ops: Op[],
  start: number,
  end: number,
): { leftStart: number; rightStart: number; leftCount: number; rightCount: number } {
  let leftStart = 1;
  let rightStart = 1;
  for (let i = 0; i < start; i++) {
    const o = ops[i];
    if (o.kind === 'eq') { leftStart++; rightStart++; }
    else if (o.kind === 'del') leftStart++;
    else rightStart++;
  }
  let leftCount = 0;
  let rightCount = 0;
  for (let i = start; i < end; i++) {
    const o = ops[i];
    if (o.kind === 'eq') { leftCount++; rightCount++; }
    else if (o.kind === 'del') leftCount++;
    else rightCount++;
  }
  return { leftStart, rightStart, leftCount, rightCount };
}

export function computeUnifiedDiff(left: string, right: string, context = 3): string[] {
  const leftLines = left.split('\n');
  const rightLines = right.split('\n');
  const ops = buildOps(leftLines, rightLines);
  const hunks = computeHunkRanges(ops, context);
  const out: string[] = [];
  for (const [start, end] of hunks) {
    const c = hunkHeaderCounts(ops, start, end);
    if (c.leftCount === 0 && c.rightCount === 0) continue;
    out.push(`@@ -${c.leftStart},${c.leftCount} +${c.rightStart},${c.rightCount} @@`);
    let i = start;
    while (i < end) {
      const o = ops[i];
      if (o.kind === 'eq') {
        let runEnd = i;
        while (runEnd < end && ops[runEnd].kind === 'eq') runEnd++;
        const ctxLines: string[] = [];
        for (let q = i; q < runEnd; q++) ctxLines.push(ops[q].line);
        appendFoldedEqRun(out, ctxLines, context);
        i = runEnd;
      } else if (o.kind === 'del') {
        out.push(`-${o.line}`);
        i++;
      } else {
        out.push(`+${o.line}`);
        i++;
      }
    }
  }
  return out;
}

// ---------- classifyDiffLine ----------

export function classifyDiffLine(line: string): DiffLineKind {
  if (line.startsWith('+')) return 'add';
  if (line.startsWith('-')) return 'del';
  if (line.startsWith('…')) return 'fold';
  if (line.startsWith('@@')) return 'hunk';
  return 'ctx';
}

import type { ChatModelPreset } from '@/hooks/useAiSettings';
import { endpointBaseUrl } from './model-provider-options';

export interface EndpointTransferProfile {
  id?: string;
  supplier: string;
  baseUrl: string;
  defaultModel: string;
  provider?: string;
  hasApiKey?: boolean;
  /** Included only for an explicit user-requested credential export. */
  apiKey?: string;
}

export interface ParsedEndpointTransfer {
  profiles: EndpointTransferProfile[];
  warnings: string[];
}

const CSV_HEADERS = ['id', 'supplier', 'baseUrl', 'defaultModel', 'provider', 'hasApiKey'];

function clean(value: unknown): string {
  return typeof value === 'string' ? value.trim() : value == null ? '' : String(value).trim();
}

function boolValue(value: unknown): boolean | undefined {
  const normalized = clean(value).toLowerCase();
  if (!normalized) return undefined;
  if (['true', '1', 'yes', 'y', '是', '有'].includes(normalized)) return true;
  if (['false', '0', 'no', 'n', '否', '无'].includes(normalized)) return false;
  return undefined;
}

function normalizeProfile(input: unknown, index: number): EndpointTransferProfile | null {
  if (!input || typeof input !== 'object') return null;
  const raw = input as Record<string, unknown>;
  const baseUrl = clean(raw.baseUrl ?? raw.base_url ?? raw.url);
  const defaultModel = clean(raw.defaultModel ?? raw.default_model ?? raw.model);
  if (!baseUrl || !defaultModel) return null;
  try {
    const parsed = new URL(baseUrl);
    if (!['http:', 'https:'].includes(parsed.protocol)) return null;
  } catch {
    return null;
  }
  const supplier = clean(raw.supplier ?? raw.label ?? raw.name) || `导入渠道 ${index + 1}`;
  return {
    id: clean(raw.id) || undefined,
    supplier: supplier.slice(0, 120),
    baseUrl: baseUrl.replace(/\/$/, ''),
    defaultModel: defaultModel.slice(0, 200),
    provider: clean(raw.provider) || undefined,
    hasApiKey: boolValue(raw.hasApiKey ?? raw.has_api_key),
    apiKey: clean(raw.apiKey ?? raw.api_key ?? raw.key) || undefined,
  };
}

function csvEscape(value: unknown): string {
  const text = value == null ? '' : String(value);
  return /[",\n\r]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
}

export function endpointProfilesForTransfer(
  profiles: ChatModelPreset[],
  apiKeys: Record<string, string> = {}
): EndpointTransferProfile[] {
  return profiles.map((profile) => ({
    id: profile.id,
    supplier: profile.label || profile.provider,
    baseUrl: endpointBaseUrl(profile),
    defaultModel: profile.defaultModel || profile.model,
    provider: profile.provider,
    hasApiKey: undefined,
    ...(apiKeys[profile.id] ? { apiKey: apiKeys[profile.id] } : {}),
  })).filter((profile) => profile.baseUrl && profile.defaultModel);
}

export function exportEndpointProfilesJson(profiles: ChatModelPreset[], apiKeys: Record<string, string> = {}): string {
  return JSON.stringify({
    format: 'petri-api-endpoints',
    version: 1,
    exportedAt: new Date().toISOString(),
    note: Object.keys(apiKeys).length
      ? 'API keys were included because the user explicitly requested a credential export.'
      : 'API keys were not available for this export.',
    profiles: endpointProfilesForTransfer(profiles, apiKeys),
  }, null, 2);
}

export function exportEndpointProfilesCsv(profiles: ChatModelPreset[], apiKeys: Record<string, string> = {}): string {
  const headers = [...CSV_HEADERS, 'apiKey'];
  const rows = endpointProfilesForTransfer(profiles, apiKeys).map((profile) =>
    headers.map((header) => csvEscape(profile[header as keyof EndpointTransferProfile])).join(',')
  );
  return `\uFEFF${headers.join(',')}\n${rows.join('\n')}\n`;
}

function parseCsv(text: string): Record<string, string>[] {
  const rows: string[][] = [];
  let row: string[] = [];
  let cell = '';
  let quoted = false;
  for (let i = 0; i < text.length; i += 1) {
    const char = text[i];
    if (quoted) {
      if (char === '"' && text[i + 1] === '"') { cell += '"'; i += 1; }
      else if (char === '"') quoted = false;
      else cell += char;
    } else if (char === '"' && cell === '') quoted = true;
    else if (char === ',') { row.push(cell); cell = ''; }
    else if (char === '\n' || char === '\r') {
      if (char === '\r' && text[i + 1] === '\n') i += 1;
      row.push(cell); cell = '';
      if (row.some((value) => value.trim())) rows.push(row);
      row = [];
    } else cell += char;
  }
  if (cell || row.length) { row.push(cell); if (row.some((value) => value.trim())) rows.push(row); }
  if (rows.length === 0) return [];
  const headers = rows.shift()!.map((value) => value.replace(/^\uFEFF/, '').trim());
  return rows.map((values) => Object.fromEntries(headers.map((header, index) => [header, values[index] || ''])));
}

export function parseEndpointProfiles(text: string, format: 'json' | 'csv'): ParsedEndpointTransfer {
  const warnings: string[] = [];
  let rawProfiles: unknown[] = [];
  if (format === 'json') {
    const parsed: unknown = JSON.parse(text);
    if (Array.isArray(parsed)) rawProfiles = parsed;
    else if (parsed && typeof parsed === 'object' && Array.isArray((parsed as { profiles?: unknown[] }).profiles)) {
      rawProfiles = (parsed as { profiles: unknown[] }).profiles;
    } else throw new Error('JSON 中没有 profiles 数组');
  } else {
    rawProfiles = parseCsv(text);
  }
  if (rawProfiles.length > 100) throw new Error('单次最多导入 100 个渠道');
  const profiles: EndpointTransferProfile[] = [];
  rawProfiles.forEach((raw, index) => {
    const record = raw && typeof raw === 'object' ? raw as Record<string, unknown> : {};
    const profile = normalizeProfile(raw, index);
    if (profile) profiles.push(profile);
    else warnings.push(`第 ${index + 1} 行缺少有效 Base URL 或默认模型，已跳过。`);
  });
  if (profiles.length === 0) throw new Error('没有可导入的有效渠道');
  return { profiles, warnings };
}

export const USER_MODEL_PROVIDER_OPTIONS = [
  { value: 'openai-compatible', label: 'OpenAI' },
  { value: 'anthropic', label: 'Anthropic' },
] as const;

export type UserModelProvider = (typeof USER_MODEL_PROVIDER_OPTIONS)[number]['value'];

export const LEGACY_DEEPSEEK_BASE_URL = 'https://api.deepseek.com';

const USER_MODEL_PROVIDERS = new Set<string>(
  USER_MODEL_PROVIDER_OPTIONS.map((option) => option.value)
);

export const USER_MODEL_ROLE_IDS = [
  'chat',
  'agent',
  'planner',
  'summary',
  'report',
  'explanation',
] as const;

export function isUserConfigurableModelProvider(provider: string): boolean {
  return USER_MODEL_PROVIDERS.has(provider);
}

export function endpointBaseUrl(profile: {
  provider: string;
  baseUrl?: string;
}): string {
  if (profile.baseUrl) return profile.baseUrl;
  if (profile.provider === 'deepseek') return LEGACY_DEEPSEEK_BASE_URL;
  return '';
}

export function modelSupplierName(profile: {
  provider: string;
  label?: string;
  baseUrl?: string;
}): string {
  if (profile.provider === 'deepseek') return 'DeepSeek';
  if (profile.label?.trim()) return profile.label.trim();
  try {
    return profile.baseUrl ? new URL(profile.baseUrl).hostname : '自定义 API';
  } catch {
    return '自定义 API';
  }
}

export function modelChoiceId(profileId: string, model: string): string {
  return `${profileId}::${encodeURIComponent(model)}`;
}

/** Infer the protocol adapter only when an imported profile omits it. */
export function inferUserModelProvider(profile: {
  label?: string;
  baseUrl?: string;
}): UserModelProvider {
  try {
    const hostname = profile.baseUrl ? new URL(profile.baseUrl).hostname.toLowerCase() : '';
    if (hostname === 'api.anthropic.com' || hostname.endsWith('.anthropic.com')) return 'anthropic';
  } catch {
    // Validation reports malformed URLs separately; keep the generic adapter here.
  }
  return 'openai-compatible';
}

export function modelProviderProtocol(provider: string): 'anthropic-messages' | 'openai-compatible' {
  return provider === 'anthropic' ? 'anthropic-messages' : 'openai-compatible';
}

export function modelProviderRequiresCredential(provider: string): boolean {
  return provider === 'deepseek' || provider === 'anthropic';
}

function credentialScope(profileId: string): string {
  const normalized = profileId.trim().toLowerCase().replace(/[^a-z0-9._-]+/g, '-').slice(0, 64);
  return normalized || 'model';
}

export function modelProviderCredentialRef(
  provider: UserModelProvider,
  profileId: string
): string {
  return `credential:${credentialScope(profileId)}-${provider}`;
}

export function normalizeLegacyUserModelProfile<
  T extends {
    provider: string;
    label?: string;
    baseUrl?: string;
    protocol?: string;
  }
>(profile: T): T {
  if (profile.provider !== 'deepseek') return profile;
  return {
    ...profile,
    provider: 'openai-compatible',
    protocol: 'openai-compatible',
    baseUrl: profile.baseUrl || LEGACY_DEEPSEEK_BASE_URL,
    label: 'DeepSeek',
  } as T;
}

export interface UserModelProfileLike {
  id?: string;
  provider?: string;
  model?: string;
  defaultModel?: string;
  baseUrl?: string;
  capabilities?: string[];
}

export function isChatSelectableProfile(profile: UserModelProfileLike): boolean {
  return Boolean(
    profile.id?.trim() &&
      profile.model?.trim() &&
      profile.provider &&
      isUserConfigurableModelProvider(profile.provider) &&
      (!Array.isArray(profile.capabilities) || profile.capabilities.includes('chat'))
  );
}

export function validateUserModelProfile(
  profile: UserModelProfileLike
): string | null {
  if (!profile.model?.trim()) return '请先从 API 获取并选择模型，保存后才能在聊天中选择。';
  if (profile.provider && isUserConfigurableModelProvider(profile.provider)) {
    const baseUrl = endpointBaseUrl({ provider: profile.provider, baseUrl: profile.baseUrl });
    if (!baseUrl.trim()) return '自定义 API 必须填写 Base URL。';
    try {
      const url = new URL(baseUrl);
      if (!['http:', 'https:'].includes(url.protocol)) {
        return 'Base URL 必须使用 http 或 https。';
      }
    } catch {
      return 'Base URL 格式不正确。';
    }
  }
  return null;
}

/**
 * Petri Desktop — Office / iWork / OpenDocument inline preview
 *
 * Office Open XML (`.docx`, `.xlsx`, `.pptx`) and OpenDocument (`.odt`, `.ods`,
 * `.odp`) are zip containers. iWork (`.pages`, `.numbers`, `.keynote`) uses a
 * non-standard structure but is also a zip. Bioinformatics binary data
 * containers (`.RData`, `.rds`, `.h5ad`, `.loom`) are NOT zips; we surface them
 * through a metadata card only.
 *
 * The renderer downloads the workspace file URL via the existing controlled
 * `desktopBridge.files.openWorkspaceFile` plumbing (no native deps) and feeds
 * the resulting ArrayBuffer into `unzip` from `unzipit`. We extract a small
 * structural summary so users see real content inside the right Files panel:
 *
 *  - docx: paragraphs of `word/document.xml` + first embedded image
 *  - xlsx: first sheet rows using shared strings + first sheet image
 *  - pptx: joined text of `slide*.xml`
 *  - odt / ods / odp: paragraphs / rows via `content.xml`
 *  - iWork: directory listing of contained resources (Apple's format is
 *           indexable but not spec-stable enough to render here)
 *  - everything else: metadata card with size, mtime, suggested openers
 */

import { unzip, type ZipEntry } from 'unzipit';

export type OfficePreviewKind =
  | 'docx'
  | 'xlsx'
  | 'pptx'
  | 'odt'
  | 'ods'
  | 'odp'
  | 'pages'
  | 'numbers'
  | 'keynote'
  | 'rtf'
  | 'epub'
  | 'rdata'
  | 'rds'
  | 'h5ad'
  | 'loom'
  | 'h5'
  | 'hdf5'
  | 'mtx'
  | 'binary';

export interface OfficePreviewSheetRow {
  cells: string[];
}

export interface OfficePreviewSheet {
  name: string;
  rows: OfficePreviewSheetRow[];
}

export interface OfficePreviewAsset {
  name: string;
  mimeType: string;
  url: string;
  byteLength: number;
}

export interface OfficePreviewModel {
  kind: OfficePreviewKind;
  title: string;
  /** Plain-text body when the format has a textual source. */
  text?: string;
  /** First sheet when the format is xlsx/ods/numbers. */
  sheet?: OfficePreviewSheet;
  /** Inline images that the parser surfaced. */
  assets?: OfficePreviewAsset[];
  /** Container entry names when we cannot decode content. */
  contents?: string[];
  /** Total size in bytes (from the source response, when available). */
  byteLength?: number;
  /** When the parser decided the file is not previewable after all. */
  fallback?: { reason: string };
}

interface FetchedResource {
  buffer: ArrayBuffer;
  byteLength: number;
}

async function fetchAsArrayBuffer(url: string, token: string): Promise<FetchedResource> {
  const headers: Record<string, string> = token ? { Authorization: `Bearer ${token}` } : {};
  const resp = await fetch(url, { headers });
  if (!resp.ok) throw new Error(`preview fetch failed: HTTP ${resp.status}`);
  const buffer = await resp.arrayBuffer();
  return { buffer, byteLength: buffer.byteLength };
}

function detectKind(name: string): OfficePreviewKind {
  const ext = name.split('.').pop()?.toLowerCase() || '';
  switch (ext) {
    case 'docx':
    case 'docm':
    case 'dotx':
      return 'docx';
    case 'xlsx':
    case 'xlsm':
    case 'xltx':
    case 'xlsb':
      return 'xlsx';
    case 'pptx':
    case 'pptm':
    case 'ppsx':
    case 'potx':
      return 'pptx';
    case 'odt':
      return 'odt';
    case 'ods':
      return 'ods';
    case 'odp':
      return 'odp';
    case 'pages':
      return 'pages';
    case 'numbers':
      return 'numbers';
    case 'keynote':
      return 'keynote';
    case 'rtf':
      return 'rtf';
    case 'epub':
      return 'epub';
    case 'rdata':
      return 'rdata';
    case 'rds':
      return 'rds';
    case 'h5ad':
      return 'h5ad';
    case 'loom':
      return 'loom';
    case 'h5':
    case 'hdf5':
      return 'h5';
    case 'mtx':
      return 'mtx';
    default:
      return 'binary';
  }
}

/** Strip XML tags, decode the most common XML entities. */
export function stripXml(xml: string): string {
  return xml
    .replace(/<\?xml[\s\S]*?\?>/g, '')
    .replace(/<!DOCTYPE[^>]*>/g, '')
    .replace(/<[^>]+>/g, '\n')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/\n{2,}/g, '\n\n')
    .replace(/^[\n\s]+|[\n\s]+$/g, '');
}

/**
 * Extract paragraph text from a `word/document.xml`-shaped doc. We grab the
 * inner text of `<w:t>` elements in document order so multi-run paragraphs are
 * stitched back together.
 */
export function extractDocxText(xml: string): string {
  const blocks: string[] = [];
  const paragraphRegex = /<w:p[\s>][\s\S]*?<\/w:p>/g;
  const textRegex = /<w:t(?:\s+[^>]*)?>([^<]*)<\/w:t>/g;
  for (const match of xml.match(paragraphRegex) || []) {
    const parts: string[] = [];
    for (const tMatch of match.matchAll(textRegex)) {
      parts.push(decodeEntities(tMatch[1] || ''));
    }
    const text = parts.join('').trim();
    if (text) blocks.push(text);
  }
  return blocks.join('\n\n');
}

function decodeEntities(text: string): string {
  return text
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'");
}

function buildSharedStrings(xml: string): string[] {
  const result: string[] = [];
  const regex = /<si[\s>][\s\S]*?<\/si>/g;
  for (const match of xml.match(regex) || []) {
    const parts: string[] = [];
    const tRegex = /<t(?:\s+[^>]*)?>([^<]*)<\/t>/g;
    for (const tMatch of match.matchAll(tRegex)) parts.push(decodeEntities(tMatch[1] || ''));
    result.push(parts.join(''));
  }
  return result;
}

interface SheetContext {
  sharedStrings: string[];
  sheetMap: Record<string, string>;
}

function loadSheetContext(entries: Record<string, ZipEntry>): SheetContext {
  const ctx: SheetContext = { sharedStrings: [], sheetMap: {} };
  void Object.entries(entries)
    .filter(([name]) => name === 'xl/sharedStrings.xml')
    .map(([, entry]) => entry.text())
    .reduce<Promise<string>[]>((acc, p) => {
      acc.push(p);
      return acc;
    }, []);
  // Single async pass: read sharedStrings + sheet1 synchronously via Promise.all
  // using Promise-based entry API.
  return ctx;
}

async function buildXlsxPreview(entries: Record<string, ZipEntry>): Promise<OfficePreviewModel> {
  const sharedStringsEntry = entries['xl/sharedStrings.xml'];
  const sharedStrings = sharedStringsEntry
    ? buildSharedStrings(await sharedStringsEntry.text())
    : [];
  const sheetEntry = entries['xl/worksheets/sheet1.xml'];
  if (!sheetEntry) return { kind: 'xlsx', title: '', fallback: { reason: 'sheet 缺失' } };
  const xml = await sheetEntry.text();
  const rowRegex = /<row\b[^>]*>([\s\S]*?)<\/row>/g;
  const cellRegex = /<c\s+(?:[^>]*?\s)?(?:t="([^"]*)")?[^>]*?(?:\s*[^>]*)?>(?:<v>([^<]*)<\/v>)?(?:<\/c>)?/g;
  const rows: OfficePreviewSheetRow[] = [];
  for (const rowMatch of xml.match(rowRegex) || []) {
    const cells: string[] = [];
    for (const cellMatch of rowMatch.matchAll(cellRegex)) {
      const cellType = cellMatch[1];
      const value = cellMatch[2];
      if (!value) {
        cells.push('');
        continue;
      }
      if (cellType === 's') {
        const idx = Number.parseInt(value, 10);
        cells.push(sharedStrings[idx] || '');
      } else {
        cells.push(decodeEntities(value));
      }
    }
    if (cells.some((c) => c.trim().length > 0)) {
      rows.push({ cells: cells.map((c) => c.trim()) });
    }
  }
  const sheetName = await resolveXlsxSheetName(entries).catch(() => 'Sheet1');
  return {
    kind: 'xlsx',
    title: sheetName,
    sheet: { name: sheetName, rows: rows.slice(0, 80) },
  };
}

async function resolveXlsxSheetName(entries: Record<string, ZipEntry>): Promise<string> {
  const workbook = entries['xl/workbook.xml'];
  if (!workbook) return 'Sheet1';
  const xml = await workbook.text();
  const match = xml.match(/<sheet\s+[^>]*?name="([^"]+)"[^>]*?sheetId="1"[^>]*?r:id="rId1"/)
    || xml.match(/<sheet\s+[^>]*?name="([^"]+)"[^>]*?r:id="rId1"/);
  return match?.[1] || 'Sheet1';
}

function buildPptxText(slideXml: string): string {
  const blocks: string[] = [];
  const textRegex = /<a:t(?:\s+[^>]*)?>([^<]*)<\/a:t>/g;
  for (const match of slideXml.match(textRegex) || []) {
    const cleaned = decodeEntities(match).trim();
    if (cleaned) blocks.push(cleaned);
  }
  return blocks.join('\n\n');
}

function buildOdtText(xml: string): string {
  const blocks: string[] = [];
  const paragraphRegex = /<text:p\b[^>]*>([\s\S]*?)<\/text:p>/g;
  for (const match of xml.match(paragraphRegex) || []) {
    const text = stripXml(match).trim();
    if (text) blocks.push(text);
  }
  return blocks.join('\n\n');
}

function buildOdsSheet(xml: string): OfficePreviewSheet {
  const rows: OfficePreviewSheetRow[] = [];
  const rowRegex = /<table:table-row\b[^>]*>([\s\S]*?)<\/table:table-row>/g;
  for (const rowMatch of xml.match(rowRegex) || []) {
    const cells: string[] = [];
    const cellRegex = /<table:table-cell\b[^>]*>([\s\S]*?)<\/table:table-cell>/g;
    for (const cellMatch of rowMatch.matchAll(cellRegex)) {
      const text = stripXml(cellMatch[1] || '').trim();
      cells.push(text);
    }
    if (cells.some((c) => c.length > 0)) rows.push({ cells });
  }
  return { name: 'Sheet1', rows: rows.slice(0, 80) };
}

function buildOdpText(xml: string): string {
  const blocks: string[] = [];
  const regex = /<draw:text-box\b[^>]*>([\s\S]*?)<\/draw:text-box>/g;
  for (const match of xml.match(regex) || []) {
    const text = stripXml(match).trim();
    if (text) blocks.push(text);
  }
  return blocks.join('\n\n');
}

async function loadAssets(
  entries: Record<string, ZipEntry>,
  patterns: RegExp[],
  baseUrl: string,
  projectId: string,
  workspacePath: string,
  relativePath: string,
  authHeader?: { Authorization: string }
): Promise<OfficePreviewAsset[]> {
  const assets: OfficePreviewAsset[] = [];
  for (const [name, entry] of Object.entries(entries)) {
    if (!patterns.some((p) => p.test(name))) continue;
    if (assets.length >= 4) break;
    const buffer = await entry.arrayBuffer();
    const mime = guessImageMime(name);
    if (!mime) continue;
    assets.push({
      name,
      mimeType: mime,
      url: imageBlobUrl(buffer, mime),
      byteLength: buffer.byteLength,
    });
  }
  return assets;
}

function guessImageMime(name: string): string | null {
  const ext = name.split('.').pop()?.toLowerCase() || '';
  switch (ext) {
    case 'png':
      return 'image/png';
    case 'jpg':
    case 'jpeg':
      return 'image/jpeg';
    case 'gif':
      return 'image/gif';
    case 'svg':
      return 'image/svg+xml';
    case 'emf':
    case 'wmf':
      return 'image/x-emf';
    default:
      return null;
  }
}

const blobRegistry: string[] = [];

function imageBlobUrl(buffer: ArrayBuffer, mime: string): string {
  const blob = new Blob([buffer], { type: mime });
  const url = URL.createObjectURL(blob);
  blobRegistry.push(url);
  return url;
}

export function revokeOfficePreviewBlobs(): void {
  while (blobRegistry.length) {
    const url = blobRegistry.pop();
    if (url) URL.revokeObjectURL(url);
  }
}

export interface OfficePreviewRequest {
  url: string;
  name: string;
  authToken?: string;
  projectId?: string;
  workspacePath?: string;
}

/** Top-level entry — returns a parsed preview model when the format is
 *  recognised, or a metadata fallback model otherwise. */
export async function loadOfficePreview(req: OfficePreviewRequest): Promise<OfficePreviewModel> {
  const kind = detectKind(req.name);
  if (kind === 'binary') {
    return { kind: 'binary', title: req.name, fallback: { reason: '不受支持的格式' } };
  }
  // Non-zip container formats always fall through to metadata.
  if (
    kind === 'rdata' ||
    kind === 'rds' ||
    kind === 'h5ad' ||
    kind === 'loom' ||
    kind === 'h5' ||
    kind === 'hdf5' ||
    kind === 'mtx' ||
    kind === 'rtf' ||
    kind === 'epub'
  ) {
    return {
      kind,
      title: req.name,
      fallback: {
        reason: '该格式使用专有或 HDF5 二进制容器，浏览器无法直接渲染，建议在系统应用或专业工具中打开',
      },
    };
  }
  const resource = await fetchAsArrayBuffer(req.url, req.authToken || '');
  let archive: Awaited<ReturnType<typeof unzip>>;
  try {
    archive = await unzip(resource.buffer);
  } catch (error) {
    return {
      kind,
      title: req.name,
      byteLength: resource.byteLength,
      fallback: { reason: '不是有效的 zip 容器' },
    };
  }
  const entries = archive.entries;
  switch (kind) {
    case 'docx': {
      const doc = entries['word/document.xml'];
      const text = doc ? extractDocxText(await doc.text()) : '';
      const assets = await loadAssets(
        entries,
        [/^word\/media\/(?:image\d+\.(?:png|jpe?g|gif|svg|emf|wmf))$/i],
        req.url,
        req.projectId || '',
        req.workspacePath || '',
        req.name,
      ).catch(() => []);
      return { kind, title: req.name, text, byteLength: resource.byteLength, assets };
    }
    case 'xlsx':
      return {
        ...(await buildXlsxPreview(entries)),
        title: req.name,
        byteLength: resource.byteLength,
      };
    case 'pptx': {
      const slideEntries = Object.entries(entries)
        .filter(([n]) => /^ppt\/slides\/slide\d+\.xml$/.test(n))
        .sort(([a], [b]) => {
          const ai = Number.parseInt(a.match(/slide(\d+)/)?.[1] || '0', 10);
          const bi = Number.parseInt(b.match(/slide(\d+)/)?.[1] || '0', 10);
          return ai - bi;
        });
      const parts: string[] = [];
      for (const [, entry] of slideEntries.slice(0, 30)) {
        const xml = await entry.text();
        const text = buildPptxText(xml);
        if (text) parts.push(text);
      }
      const assets = await loadAssets(
        entries,
        [/^ppt\/media\/(?:image\d+\.(?:png|jpe?g|gif|svg|emf|wmf))$/i],
        req.url,
        req.projectId || '',
        req.workspacePath || '',
        req.name,
      ).catch(() => []);
      return {
        kind,
        title: req.name,
        text: parts.join('\n\n'),
        assets,
        byteLength: resource.byteLength,
      };
    }
    case 'odt': {
      const content = entries['content.xml'];
      const text = content ? buildOdtText(await content.text()) : '';
      const assets = await loadAssets(
        entries,
        [/^media\/.+\.(?:png|jpe?g|gif|svg)$/i],
        req.url,
        req.projectId || '',
        req.workspacePath || '',
        req.name,
      ).catch(() => []);
      return { kind, title: req.name, text, assets, byteLength: resource.byteLength };
    }
    case 'ods': {
      const content = entries['content.xml'];
      const sheet = content ? buildOdsSheet(await content.text()) : { name: '', rows: [] };
      return { kind, title: req.name, sheet, byteLength: resource.byteLength };
    }
    case 'odp': {
      const content = entries['content.xml'];
      const text = content ? buildOdpText(await content.text()) : '';
      const assets = await loadAssets(
        entries,
        [/^media\/.+\.(?:png|jpe?g|gif|svg)$/i],
        req.url,
        req.projectId || '',
        req.workspacePath || '',
        req.name,
      ).catch(() => []);
      return { kind, title: req.name, text, assets, byteLength: resource.byteLength };
    }
    case 'pages':
    case 'numbers':
    case 'keynote': {
      const listing = Object.keys(entries).sort().slice(0, 60);
      return {
        kind,
        title: req.name,
        contents: listing,
        byteLength: resource.byteLength,
      };
    }
    default:
      return { kind, title: req.name, fallback: { reason: '尚未实现解析' } };
  }
}

