/**
 * BLOCK-85 P4 — 投影终端 HTTP 桥。
 *
 * 桌面投影（手机浏览器）里没有 Electron 终端桥——本模块在投影环境下
 * 以同一形状提供真终端：startSession/writeSession/resizeSession/stopSession
 * + onData/onExit，内部走 gateway /m/api/terminal/*（SSE 下行 + POST 上行，
 * node-pty 会话驻留 core 进程，手机锁屏重连经环形缓冲重放）。
 * 消费方（useTerminalTabs）零改动——getBridge('terminal') 在投影环境
 * 自动切换到本桥。
 */
import { getToken } from '@/lib/authClient';

interface ProjectionTerminalBridge {
  startSession: (cwd: string | null, tabId: string, ssh?: unknown) => Promise<{ ok: boolean; sessionId?: string; error?: string }>;
  writeSession: (data: string, tabId: string) => void;
  resizeSession: (cols: number, rows: number, tabId: string) => void;
  stopSession: (tabId: string) => void;
  onData: (handler: (payload: { sessionId: string; data: string }) => void) => () => void;
  onExit: (handler: (payload: { sessionId: string; exitCode?: number | null }) => void) => () => void;
}

const sessionByTab = new Map<string, string>(); // tabId -> gateway sessionId
const sourceByTab = new Map<string, EventSource>();
const dataHandlers = new Set<(payload: { sessionId: string; data: string }) => void>();
const exitHandlers = new Set<(payload: { sessionId: string; exitCode?: number | null }) => void>();

function authHeaders(): Record<string, string> {
  const headers: Record<string, string> = { 'Content-Type': 'application/json' };
  const token = getToken();
  if (token) headers.Authorization = `Bearer ${token}`;
  return headers;
}

function attachStream(tabId: string, sessionId: string) {
  if (sourceByTab.has(tabId)) return;
  // BLOCK-102 P3 — 不再把一年期会话 token 放进 URL（会落中转 nginx 日志与
  // 浏览器历史）；投影 SPA 与网关同源，EventSource 自动携带 HttpOnly
  // gw_session cookie（sessionAuth 的 readCookieToken 分支鉴权）。
  const url = `/m/api/terminal/${encodeURIComponent(sessionId)}/stream`;
  const source = new EventSource(url);
  source.addEventListener('terminal:data', (event) => {
    try {
      const payload = JSON.parse((event as MessageEvent).data);
      for (const handler of dataHandlers) handler({ sessionId: tabId, data: payload.data });
    } catch { /* 忽略坏帧 */ }
  });
  source.addEventListener('terminal:exit', (event) => {
    try {
      const payload = JSON.parse((event as MessageEvent).data);
      for (const handler of exitHandlers) handler({ sessionId: tabId, exitCode: payload.exitCode });
    } catch { /* 忽略坏帧 */ }
    source.close();
    sourceByTab.delete(tabId);
  });
  source.onerror = () => {
    // EventSource 自动重连；环形缓冲会在重连时重放
  };
  sourceByTab.set(tabId, source);
}

const bridge: ProjectionTerminalBridge = {
  async startSession(cwd, tabId, ssh) {
    const sshInfo = ssh as { alias?: string; remotePath?: string } | undefined;
    try {
      const response = await fetch('/m/api/terminal/start', {
        method: 'POST',
        headers: authHeaders(),
        body: JSON.stringify({
          cwd,
          ssh: sshInfo?.alias && sshInfo?.remotePath ? { alias: sshInfo.alias, remotePath: sshInfo.remotePath } : undefined,
        }),
      });
      const data = await response.json();
      if (!data.ok || !data.sessionId) {
        return { ok: false, error: data.message || data.error || '终端启动失败' };
      }
      sessionByTab.set(tabId, data.sessionId);
      attachStream(tabId, data.sessionId);
      return { ok: true, sessionId: data.sessionId };
    } catch (error) {
      return { ok: false, error: error instanceof Error ? error.message : '终端通道连接失败' };
    }
  },

  writeSession(data, tabId) {
    const sessionId = sessionByTab.get(tabId);
    if (!sessionId) return;
    void fetch(`/m/api/terminal/${encodeURIComponent(sessionId)}/input`, {
      method: 'POST',
      headers: authHeaders(),
      body: JSON.stringify({ data }),
    }).catch(() => { /* 瞬时失败由 xterm 光标状态体现 */ });
  },

  resizeSession(cols, rows, tabId) {
    const sessionId = sessionByTab.get(tabId);
    if (!sessionId) return;
    void fetch(`/m/api/terminal/${encodeURIComponent(sessionId)}/resize`, {
      method: 'POST',
      headers: authHeaders(),
      body: JSON.stringify({ cols, rows }),
    }).catch(() => {});
  },

  stopSession(tabId) {
    const sessionId = sessionByTab.get(tabId);
    sourceByTab.get(tabId)?.close();
    sourceByTab.delete(tabId);
    sessionByTab.delete(tabId);
    if (!sessionId) return;
    void fetch(`/m/api/terminal/${encodeURIComponent(sessionId)}/kill`, {
      method: 'POST',
      headers: authHeaders(),
    }).catch(() => {});
  },

  onData(handler) {
    dataHandlers.add(handler);
    return () => dataHandlers.delete(handler);
  },

  onExit(handler) {
    exitHandlers.add(handler);
    return () => exitHandlers.delete(handler);
  },
};

export function isProjectionEnv(): boolean {
  return typeof window !== 'undefined'
    && !!(window.petriDesktop as { __projection?: boolean } | undefined)?.__projection;
}

export function getProjectionTerminalBridge(): ProjectionTerminalBridge | null {
  return isProjectionEnv() ? bridge : null;
}

export type ResultArtifactKind = 'report' | 'plot' | 'table' | 'text' | 'data' | 'file';

export interface ResultArtifactRecord {
  name: string;
  type?: string;
  label?: string;
  title?: string;
  description?: string;
  section?: string;
  role?: string;
  url?: string;
  preview?: boolean;
  download?: boolean;
}

export interface ResultSectionRecord {
  id: string;
  label: string;
  artifactNames: string[];
  description?: string;
}

export interface NormalizedResultManifest {
  raw: unknown;
  title: string | null;
  summary: Record<string, unknown> | null;
  artifacts: ResultArtifactRecord[];
  sections: ResultSectionRecord[];
  hasExplicitSections: boolean;
}

export interface ResultArtifactNavSection {
  id: string;
  label: string;
  description?: string;
  artifactNames: string[];
  artifacts: ResultArtifactRecord[];
  kind: ResultArtifactKind | 'mixed';
}

const SECTION_ORDER: ResultArtifactKind[] = ['report', 'plot', 'table', 'text', 'data', 'file'];
const PREVIEW_ORDER: ResultArtifactKind[] = ['plot', 'table', 'text', 'data', 'file', 'report'];

const SECTION_LABELS: Record<ResultArtifactKind, string> = {
  report: '报告',
  plot: '图表',
  table: '表格',
  text: '文本',
  data: '数据',
  file: '其他',
};

function asString(value: unknown): string {
  return typeof value === 'string' ? value.trim() : '';
}

function asRecord(value: unknown): Record<string, unknown> | null {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return null;
  return value as Record<string, unknown>;
}

function normalizeArtifact(item: unknown): ResultArtifactRecord | null {
  const obj = asRecord(item);
  if (!obj) return null;
  const name = asString(obj.name || obj.filename || obj.path);
  if (!name) return null;
  return {
    name,
    type: asString(obj.type) || undefined,
    label: asString(obj.label) || undefined,
    title: asString(obj.title) || undefined,
    description: asString(obj.description) || undefined,
    section: asString(obj.section) || undefined,
    role: asString(obj.role) || undefined,
    url: asString(obj.url) || undefined,
    preview: typeof obj.preview === 'boolean' ? obj.preview : undefined,
    download: typeof obj.download === 'boolean' ? obj.download : undefined,
  };
}

export function getArtifactName(item: ResultArtifactRecord | { name?: string; filename?: string; path?: string }): string {
  return asString((item as ResultArtifactRecord).name || (item as { filename?: string }).filename || (item as { path?: string }).path);
}

export function classifyArtifact(artifact: ResultArtifactRecord): ResultArtifactKind {
  const name = getArtifactName(artifact).toLowerCase();
  const type = asString(artifact.type).toLowerCase();
  if (type === 'report' || /(^|\/)report(\.html?)?$/.test(name) || /\.html?$/i.test(name)) return 'report';
  if (type === 'plot' || /\.(png|jpg|jpeg|gif|svg|webp)$/i.test(name)) return 'plot';
  if (type === 'table' || /\.(csv|tsv|xls|xlsx)$/i.test(name)) return 'table';
  if (type === 'text' || /\.(txt|md|json|log)$/i.test(name)) return 'text';
  if (/\.(rds|rda|rdata|h5ad|loom|h5|mtx|npz|zarr|feather|parquet)$/i.test(name)) return 'data';
  return 'file';
}

function artifactSortWeight(kind: ResultArtifactKind): number {
  return PREVIEW_ORDER.indexOf(kind);
}

function buildDerivedSections(artifacts: ResultArtifactRecord[]): ResultSectionRecord[] {
  const bucket = new Map<ResultArtifactKind, ResultArtifactRecord[]>();
  for (const kind of SECTION_ORDER) bucket.set(kind, []);
  for (const artifact of artifacts) {
    const kind = classifyArtifact(artifact);
    bucket.get(kind)?.push(artifact);
  }

  return SECTION_ORDER.filter((kind) => (bucket.get(kind)?.length || 0) > 0).map((kind) => ({
    id: kind,
    label: SECTION_LABELS[kind],
    artifactNames: (bucket.get(kind) || []).map((artifact) => artifact.name),
  }));
}

function normalizeExplicitSections(rawSections: unknown): ResultSectionRecord[] {
  if (!Array.isArray(rawSections)) return [];
  return rawSections
    .map((item, index) => {
      const obj = asRecord(item);
      if (!obj) return null;
      const id = asString(obj.id) || `section-${index + 1}`;
      const label = asString(obj.label || obj.title) || id;
      const artifactNames = Array.isArray(obj.artifactNames)
        ? obj.artifactNames.map((name) => asString(name)).filter(Boolean)
        : Array.isArray(obj.artifacts)
          ? obj.artifacts
              .map((entry) => getArtifactName(normalizeArtifact(entry) || { name: '' }))
              .filter(Boolean)
          : [];
      return {
        id,
        label,
        description: asString(obj.description) || undefined,
        artifactNames,
      } as ResultSectionRecord;
    })
    .filter(Boolean) as ResultSectionRecord[];
}

function collectArtifacts(raw: Record<string, unknown>, fallbackFiles: ResultArtifactRecord[]): ResultArtifactRecord[] {
  const source = Array.isArray(raw.files)
    ? raw.files
    : Array.isArray(raw.outputs)
      ? raw.outputs
      : [];
  const normalized = source.map(normalizeArtifact).filter(Boolean) as ResultArtifactRecord[];
  const merged = [...normalized];
  for (const file of fallbackFiles) {
    if (!merged.some((item) => item.name === file.name)) merged.push(file);
  }
  return merged;
}

export function normalizeResultManifest(
  raw: unknown,
  fallbackFiles: ResultArtifactRecord[] = [],
): NormalizedResultManifest | null {
  const obj = asRecord(raw);
  if (!obj) return null;
  const title = asString(obj.title || obj.name || obj.reportTitle) || null;
  const summary = asRecord(obj.summary);
  const artifacts = collectArtifacts(obj, fallbackFiles);
  const explicitSections = normalizeExplicitSections(obj.sections);
  const sections = explicitSections.length > 0 ? explicitSections : buildDerivedSections(artifacts);
  return {
    raw,
    title,
    summary,
    artifacts,
    sections,
    hasExplicitSections: explicitSections.length > 0,
  };
}

export function findArtifactByName(
  artifacts: ResultArtifactRecord[],
  name: string,
): ResultArtifactRecord | null {
  const target = asString(name);
  if (!target) return null;
  return artifacts.find((artifact) => artifact.name === target) || null;
}

export function pickPreferredArtifact(
  artifacts: ResultArtifactRecord[],
  preferredName: string | null | undefined,
): ResultArtifactRecord | null {
  const preferred = preferredName ? findArtifactByName(artifacts, preferredName) : null;
  if (preferred) return preferred;
  const ordered = [...artifacts].sort((a, b) => artifactSortWeight(classifyArtifact(a)) - artifactSortWeight(classifyArtifact(b)));
  return ordered[0] || null;
}

function uniqueSectionId(baseId: string, usedIds: Set<string>): string {
  let id = baseId || 'section';
  let index = 2;
  while (usedIds.has(id)) {
    id = `${baseId}-${index}`;
    index += 1;
  }
  usedIds.add(id);
  return id;
}

function inferSectionKind(artifacts: ResultArtifactRecord[]): ResultArtifactKind | 'mixed' {
  const kinds = new Set(artifacts.map((artifact) => classifyArtifact(artifact)));
  return kinds.size === 1 ? ([...kinds][0] || 'file') : 'mixed';
}

function sectionLabelHintsPlot(label: string | undefined): boolean {
  if (!label) return false;
  return /图表|svg|plot|image|可视化|结果图/i.test(label);
}

export function inferSectionDisplayKind(
  artifacts: ResultArtifactRecord[],
  label?: string,
): ResultArtifactKind {
  const counts = countArtifactsByKind(artifacts);
  if (sectionLabelHintsPlot(label) && counts.plot > 0) return 'plot';
  let winner: ResultArtifactKind = 'file';
  let winnerCount = -1;
  for (const kind of SECTION_ORDER) {
    const count = counts[kind];
    if (count > winnerCount) {
      winner = kind;
      winnerCount = count;
    }
  }
  return winner;
}

export function buildResultArtifactNavigation(
  manifest: NormalizedResultManifest | null,
  artifacts: ResultArtifactRecord[],
): ResultArtifactNavSection[] {
  const sections = manifest?.sections?.length ? manifest.sections : buildDerivedSections(artifacts);
  const usedIds = new Set<string>();
  const assignedNames = new Set<string>();
  const navSections: ResultArtifactNavSection[] = [];

  for (const section of sections) {
    const sectionArtifacts = section.artifactNames
      .map((name) => findArtifactByName(artifacts, name))
      .filter(Boolean) as ResultArtifactRecord[];
    if (sectionArtifacts.length === 0) continue;
    sectionArtifacts.forEach((artifact) => assignedNames.add(artifact.name));
    navSections.push({
      id: uniqueSectionId(section.id, usedIds),
      label: section.label,
      description: section.description,
      artifactNames: sectionArtifacts.map((artifact) => artifact.name),
      artifacts: sectionArtifacts,
      kind: inferSectionKind(sectionArtifacts),
    });
  }

  const unassigned = artifacts.filter((artifact) => !assignedNames.has(artifact.name));
  if (unassigned.length > 0) {
    for (const section of buildDerivedSections(unassigned)) {
      const sectionArtifacts = section.artifactNames
        .map((name) => findArtifactByName(unassigned, name))
        .filter(Boolean) as ResultArtifactRecord[];
      if (sectionArtifacts.length === 0) continue;
      navSections.push({
        id: uniqueSectionId(`more-${section.id}`, usedIds),
        label: manifest?.hasExplicitSections ? `其他${section.label}` : section.label,
        description: section.description,
        artifactNames: sectionArtifacts.map((artifact) => artifact.name),
        artifacts: sectionArtifacts,
        kind: inferSectionKind(sectionArtifacts),
      });
    }
  }

  return navSections;
}

export function countArtifactsByKind(artifacts: ResultArtifactRecord[]): Record<ResultArtifactKind, number> {
  return artifacts.reduce(
    (acc, artifact) => {
      const kind = classifyArtifact(artifact);
      acc[kind] += 1;
      return acc;
    },
    { report: 0, plot: 0, table: 0, text: 0, data: 0, file: 0 } as Record<ResultArtifactKind, number>,
  );
}

export function isTextLikeArtifact(artifact: ResultArtifactRecord): boolean {
  return classifyArtifact(artifact) === 'text';
}

export function isHtmlArtifact(artifact: ResultArtifactRecord): boolean {
  return classifyArtifact(artifact) === 'report';
}

export function isImageArtifact(artifact: ResultArtifactRecord): boolean {
  return classifyArtifact(artifact) === 'plot';
}

export function artifactKindLabel(kind: ResultArtifactKind): string {
  return SECTION_LABELS[kind];
}

import { getApiPrefix, getToken } from '@/lib/authClient';
import type {
  ArtifactInteractionManifest,
  ArtifactSelection,
  SelectionFilterExpression,
  SelectionSortSpec,
} from '@/lib/artifact-selection';
import { fromPersistedSelection, toPersistPayload } from '@/lib/artifact-selection';

export interface ResultTableColumn {
  field: string;
  type: 'number' | 'string';
  sortable: boolean;
  filterable: boolean;
}

export interface ResultTableQuery {
  tableQueryVersion: 1;
  columns: ResultTableColumn[];
  rows: Array<Record<string, string>>;
  totalRows: number;
  matchedCount: number;
  offset: number;
  nextOffset: number | null;
  limit: number;
  virtualized: boolean;
  filterExpression: SelectionFilterExpression;
  sort: SelectionSortSpec[];
  filterHash: string;
  selectionEvidence: {
    idField: string | null;
    entityIdsHash: string | null;
    sampleEntityIds: string[];
    entityIdCount: number;
  };
}

export interface InteractionResponse {
  manifest: ArtifactInteractionManifest;
  revision?: Record<string, unknown> | null;
  backingTable?: ResultTableQuery | null;
}

function headers(json = false): HeadersInit {
  const token = getToken();
  return {
    ...(json ? { 'Content-Type': 'application/json' } : {}),
    ...(token ? { Authorization: `Bearer ${token}` } : {}),
  };
}

async function parseResponse<T>(response: Response): Promise<T> {
  const data = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(data.message || data.error || `HTTP ${response.status}`);
  return data as T;
}

export async function fetchArtifactInteraction(input: {
  language: 'r' | 'python'; jobId: string; artifact: string; revisionId?: string | null;
}): Promise<InteractionResponse> {
  const query = new URLSearchParams({ jobId: input.jobId, artifact: input.artifact });
  if (input.revisionId) query.set('revisionId', input.revisionId);
  return parseResponse(await fetch(`${getApiPrefix(input.language)}/result-studio/interaction?${query}`, {
    headers: headers(),
  }));
}

export async function queryResultStudioTable(input: {
  language: 'r' | 'python'; jobId: string; artifact: string;
  filterExpression?: SelectionFilterExpression | null;
  sort?: SelectionSortSpec[]; offset?: number; limit?: number; signal?: AbortSignal;
}): Promise<ResultTableQuery> {
  return parseResponse(await fetch(`${getApiPrefix(input.language)}/result-studio/table/query`, {
    method: 'POST',
    headers: headers(true),
    body: JSON.stringify({ ...input, signal: undefined }),
    signal: input.signal,
  }));
}

export async function saveResultStudioSelection(input: {
  language: 'r' | 'python'; selection: ArtifactSelection; selectionId: string;
  projectId: string; conversationId?: string | null;
}): Promise<ArtifactSelection> {
  const data = await parseResponse<{ selection: Record<string, unknown> }>(await fetch(
    `${getApiPrefix(input.language)}/result-studio/selection`, {
      method: 'POST', headers: headers(true),
      body: JSON.stringify(toPersistPayload(input.selection, input)),
    },
  ));
  return fromPersistedSelection(data.selection) as ArtifactSelection;
}

export async function restoreResultStudioSelection(input: {
  language: 'r' | 'python'; projectId: string; conversationId?: string | null;
  artifactId: string; revisionId?: string | null; selectionDurable: boolean;
}): Promise<ArtifactSelection | null> {
  const query = new URLSearchParams({
    projectId: input.projectId,
    artifactId: input.artifactId,
    selectionDurable: String(input.selectionDurable),
  });
  if (input.conversationId) query.set('conversationId', input.conversationId);
  if (input.revisionId) query.set('revisionId', input.revisionId);
  const response = await fetch(`${getApiPrefix(input.language)}/result-studio/selection/current?${query}`, { headers: headers() });
  if (response.status === 404) return null;
  const data = await parseResponse<{
    selection: Record<string, unknown>;
    compatibility: { status: 'compatible' | 'stale' | 'invalid' };
  }>(response);
  const selection = fromPersistedSelection(data.selection);
  if (selection) selection.compatibility = data.compatibility.status;
  return selection;
}

export async function deleteResultStudioSelection(input: {
  language: 'r' | 'python'; selectionId: string;
}): Promise<void> {
  await parseResponse(await fetch(`${getApiPrefix(input.language)}/result-studio/selection/${encodeURIComponent(input.selectionId)}`, {
    method: 'DELETE', headers: headers(),
  }));
}

/**
 * G0-RS-P3 — ResultStudioContextEnvelope 的前端有界投影。
 *
 * 前端不自己拼装这些坐标：envelope 由后端从 SQLite / tool_jobs / 插件
 * descriptor 重新解析，前端只提供"用户打开了哪个 Job 的哪个文件"这一线索。
 * contextToken 是不透明字符串，前端不解析、不推导，只在 Composer 里透传。
 */
export interface ResultStudioContextAgentView {
  contextVersion: 1;
  contextToken: string | null;
  artifact: {
    name: string | null;
    kind: string | null;
    entityType: string | null;
    interactionMode: string | null;
  };
  tool: string | null;
  revisionOrdinal: number | null;
  isCurrent: boolean;
  validation: { artifactTruthStatus: string | null; revisionValidationStatus: string | null };
  reproducibility: { status: string | null; scriptAvailable: boolean };
  selection: {
    entityType: string | null;
    entityIdCount: number;
    truncated: boolean;
    sampleEntityIds: string[];
    hasFilter: boolean;
    filterDescription: string | null;
    fields: string[];
    sort: Array<{ field: string; direction: 'asc' | 'desc' }>;
  } | null;
  selectionState: {
    present: boolean;
    compatibility: 'compatible' | 'stale' | 'invalid' | null;
    reason: string | null;
    usableByAgent: boolean;
  };
  editableParameters: Array<{ name: string; type: string | null; impact: string | null }>;
  actions: string[];
  workflow: { available: boolean; nodeId: string | null; stepCount: number | null; downstreamNodeIds: string[] };
  publicPhases: string[];
}

export interface ResultStudioContextDiagnostic {
  code: string;
  message: string;
}

/**
 * G0-RS-P4 — Schema 驱动的参数控件。
 *
 * 控件完全由后端从受信插件 descriptor 投影，前端不硬编码任何插件的参数集合，
 * 也不自行推断 impact。`scientificallyNeutral` 只在 presentation 分组为真，
 * UI 只能在为真时声称"不改变科学结论"。
 */
export interface ResultStudioEditControl {
  name: string;
  controlType: 'number' | 'text' | 'select' | 'color' | 'boolean';
  impact: string;
  group: 'presentation' | 'data' | 'scientific' | 'workflow';
  default: unknown;
  required: boolean;
  minimum?: number | null;
  maximum?: number | null;
  options?: string[];
  scientificallyNeutral: boolean;
}

export interface ResultStudioEditControlGroup {
  group: 'presentation' | 'data' | 'scientific' | 'workflow';
  label: string;
  parameterNames: string[];
}

export interface ResultStudioEditControls {
  controlsVersion: 1;
  groups: ResultStudioEditControlGroup[];
  controls: ResultStudioEditControl[];
  diagnostics: ResultStudioContextDiagnostic[];
  /** 该 Job 真实执行过的归一化参数值；不是 descriptor 默认值。 */
  currentValues: Record<string, unknown>;
}

export interface ResultStudioContextResult {
  status: 'ready' | 'blocked';
  agentView: ResultStudioContextAgentView | null;
  editControls: ResultStudioEditControls | null;
  diagnostics: ResultStudioContextDiagnostic[];
}

/**
 * 读取当前结果的上下文投影。
 *
 * 后端在缺少正式 Revision、归因只能到 Job 或跨项目时返回 409 与可行动诊断；
 * 这里把它归一化成 `blocked`，让 UI 如实显示原因而不是静默退化。
 */
export async function fetchResultStudioContext(input: {
  language: 'r' | 'python';
  projectId: string;
  conversationId?: string | null;
  jobId?: string | null;
  artifact?: string | null;
  revisionId?: string | null;
}): Promise<ResultStudioContextResult> {
  const query = new URLSearchParams({ projectId: input.projectId });
  if (input.conversationId) query.set('conversationId', input.conversationId);
  if (input.jobId) query.set('jobId', input.jobId);
  if (input.artifact) query.set('artifact', input.artifact);
  if (input.revisionId) query.set('revisionId', input.revisionId);
  const response = await fetch(
    `${getApiPrefix(input.language)}/result-studio/context-envelope?${query}`,
    { headers: headers() },
  );
  const data = await response.json().catch(() => ({}));
  if (!response.ok) {
    const diagnostics = Array.isArray(data?.diagnostics) && data.diagnostics.length > 0
      ? (data.diagnostics as ResultStudioContextDiagnostic[])
      : [{ code: String(data?.error || 'context_unavailable'), message: String(data?.message || '无法读取当前结果上下文。') }];
    return { status: 'blocked', agentView: null, editControls: null, diagnostics };
  }
  return {
    status: 'ready',
    agentView: (data.agentView as ResultStudioContextAgentView) || null,
    editControls: (data.editControls as ResultStudioEditControls) || null,
    diagnostics: [],
  };
}

export type ResultTitleBarMode = 'chat' | 'result' | 'code' | 'compare' | 'history' | string;

const MODE_LABELS: Record<string, string> = {
  result: '结果',
  code: '代码',
  compare: '审查修改',
  history: '版本历史',
};

export function buildResultTitleBarTitle(
  mode: ResultTitleBarMode,
  projectTitle: string | null | undefined,
  artifactTitle?: string | null,
): string {
  const project = projectTitle || '梳理开发进展';
  const modeLabel = MODE_LABELS[mode];
  // chat mode (or any unrecognized mode) keeps project identity front-and-center
  // so the user always sees WHICH project they're in. handleOpenResult preserves
  // 'chat' on auto-open from HomePage; 'scheduled' / 'plugins' / null
  // never end up here because ProjectWorkspace normalizes to 'chat' via T85.
  if (!modeLabel) return project;
  // Result/code/compare/history mode: artifact name dominates, project name
  // remains visible as the secondary context marker.
  return artifactTitle ? `${artifactTitle} · ${modeLabel} · ${project}` : `${modeLabel} · ${project}`;
}

// ============================================================
// resultBridge 拆包契约回归（UI-311）
//
// result:* handler 统一返回 fail-closed 信封 { ok, data?, error? }，
// 本桥是唯一拆包点。回归锁定：信封进 → 裸值出；此前信封被原样透传，
// /project/:id/results 首次加载即 snapshot.results.map is not a function。
// ============================================================
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import type { Result, ResultSummary, ResultVersion } from '@/types/result.types';

const RESULT_FIXTURE: Result = {
  id: 'r1',
  projectId: 'p1',
  type: 'chart',
  name: 'volcano',
  data: { points: 12 },
  config: {},
  sourceBranchId: null,
  createdAt: 100,
  updatedAt: 200,
};

const SUMMARY_FIXTURE: ResultSummary = {
  id: 'r1',
  projectId: 'p1',
  type: 'chart',
  name: 'volcano',
  sourceBranchId: null,
  updatedAt: 200,
};

const VERSION_FIXTURE: ResultVersion = {
  id: 'v1',
  resultId: 'r1',
  version: 1,
  data: { points: 12 },
  createdAt: 150,
  createdByBranchId: null,
};

type Envelope = { ok: boolean; data?: unknown; error?: string };

function stubBridge(methods: Record<string, unknown>): void {
  (window as unknown as Record<string, unknown>).petri = { result: methods };
}

async function loadResultApi() {
  vi.resetModules();
  const mod = await import('@/lib/resultBridge');
  return mod.resultApi;
}

beforeEach(() => {
  delete (window as unknown as Record<string, unknown>).petri;
  delete (window as unknown as Record<string, unknown>).petriDesktop;
});

afterEach(() => {
  delete (window as unknown as Record<string, unknown>).petri;
  delete (window as unknown as Record<string, unknown>).petriDesktop;
  vi.restoreAllMocks();
});

describe('resultBridge envelope unwrap (UI-311)', () => {
  it('byProject：信封拆包返回裸数组（崩溃回归锁定）', async () => {
    const byProject = vi.fn(async (): Promise<Envelope> => ({
      ok: true,
      data: [RESULT_FIXTURE],
    }));
    stubBridge({
      byProject,
      list: vi.fn(async (): Promise<Envelope> => ({ ok: true, data: [] })),
    });
    const api = await loadResultApi();
    const results = await api.byProject('p1');
    expect(Array.isArray(results)).toBe(true);
    expect(results).toEqual([RESULT_FIXTURE]);
    expect(byProject).toHaveBeenCalledWith({ projectId: 'p1', options: undefined });
  });

  it('list：信封拆包返回裸数组', async () => {
    stubBridge({
      byProject: vi.fn(async (): Promise<Envelope> => ({ ok: true, data: [] })),
      list: vi.fn(async (): Promise<Envelope> => ({
        ok: true,
        data: [SUMMARY_FIXTURE],
      })),
    });
    const api = await loadResultApi();
    const summaries = await api.list('p1');
    expect(summaries).toEqual([SUMMARY_FIXTURE]);
  });

  it('get：ok → data；not found → null；其他错误 → throw', async () => {
    stubBridge({
      get: vi.fn(async (): Promise<Envelope> => ({ ok: true, data: RESULT_FIXTURE })),
    });
    const api = await loadResultApi();
    await expect(api.get('r1')).resolves.toEqual(RESULT_FIXTURE);

    stubBridge({
      get: vi.fn(async (): Promise<Envelope> => ({
        ok: false,
        error: 'Result not found',
      })),
    });
    const api2 = await loadResultApi();
    await expect(api2.get('missing')).resolves.toBeNull();

    stubBridge({
      get: vi.fn(async (): Promise<Envelope> => ({
        ok: false,
        error: 'boom',
      })),
    });
    const api3 = await loadResultApi();
    await expect(api3.get('r1')).rejects.toThrow('boom');
  });

  it('create/update/version.list/createFromConversation：统一拆包', async () => {
    stubBridge({
      create: vi.fn(async (): Promise<Envelope> => ({ ok: true, data: RESULT_FIXTURE })),
      update: vi.fn(async (): Promise<Envelope> => ({ ok: true, data: RESULT_FIXTURE })),
      createFromConversation: vi.fn(async (): Promise<Envelope> => ({
        ok: true,
        data: RESULT_FIXTURE,
      })),
      version: {
        create: vi.fn(async (): Promise<Envelope> => ({ ok: true, data: VERSION_FIXTURE })),
        get: vi.fn(async (): Promise<Envelope> => ({ ok: true, data: VERSION_FIXTURE })),
        getByNumber: vi.fn(async (): Promise<Envelope> => ({ ok: true, data: VERSION_FIXTURE })),
        list: vi.fn(async (): Promise<Envelope> => ({ ok: true, data: [VERSION_FIXTURE] })),
      },
    });
    const api = await loadResultApi();
    await expect(api.create('p1', 'chart', 'n', {})).resolves.toEqual(RESULT_FIXTURE);
    await expect(api.update('r1', { name: 'x' })).resolves.toEqual(RESULT_FIXTURE);
    await expect(api.createFromConversation('p1', 'b1')).resolves.toEqual(RESULT_FIXTURE);
    await expect(api.version.list('r1')).resolves.toEqual([VERSION_FIXTURE]);
  });

  it('error 信封：抛出 handler 错误信息（store 侧进 error 态）', async () => {
    stubBridge({
      byProject: vi.fn(async (): Promise<Envelope> => ({
        ok: false,
        error: 'db closed',
      })),
      list: vi.fn(async (): Promise<Envelope> => ({ ok: true, data: [] })),
    });
    const api = await loadResultApi();
    await expect(api.byProject('p1')).rejects.toThrow('db closed');
  });

  it('桥不可用：兜底空值语义不抛错（list/byProject → []，get → null）', async () => {
    const api = await loadResultApi();
    await expect(api.byProject('p1')).resolves.toEqual([]);
    await expect(api.list('p1')).resolves.toEqual([]);
    await expect(api.get('r1')).resolves.toBeNull();
  });
});

// ============================================================
// resultBridge — IPC wrapper for result operations
//
// Phase 2: Project-scoped results shared across branches
// Uses the typed bridge accessor from desktopBridge.ts.
//
// UI-311 — result:* handler 统一返回 fail-closed 信封 { ok, data?, error? }
// （electron.d.ts 如实声明），本桥是 result 命名空间的唯一拆包点：消费方
// （useResultStore / ResultVersionHistory）仍见裸值契约。此前无人拆包，
// /project/:id/results 首次加载即把信封当数组用（snapshot.results.map is
// not a function）整页崩溃。
// ============================================================

import { getBridge } from '@/lib/desktopBridge';
import type { Result, ResultSummary, ResultVersion, ListResultsOptions } from '@/types/result.types';

interface ResultIpcEnvelope<T> {
  ok: boolean;
  data?: T;
  error?: string;
}

/** ok=true → data；否则抛 handler 错误信息（store 捕获后进 error 态）。 */
async function unwrap<T>(call: Promise<ResultIpcEnvelope<T>>): Promise<T> {
  const envelope = await call;
  if (!envelope || envelope.ok !== true) {
    throw new Error(envelope?.error || 'Result bridge error');
  }
  return envelope.data as T;
}

/** 同 unwrap，但 handler 明确报「not found」时按契约落 null（get 类方法）。 */
async function unwrapNullable<T>(call: Promise<ResultIpcEnvelope<T | null>>): Promise<T | null> {
  const envelope = await call;
  if (envelope && envelope.ok) return (envelope.data ?? null) as T | null;
  if (envelope && /not found/i.test(String(envelope.error))) return null;
  throw new Error(envelope?.error || 'Result bridge error');
}

export interface ResultApi {
  create: (
    projectId: string,
    type: Result['type'],
    name: string,
    data: unknown,
    config?: Record<string, unknown>,
    sourceBranchId?: string
  ) => Promise<Result>;
  get: (id: string) => Promise<Result | null>;
  list: (projectId: string, options?: ListResultsOptions) => Promise<ResultSummary[]>;
  update: (
    id: string,
    updates: { name?: string; data?: unknown; config?: Record<string, unknown> }
  ) => Promise<Result | null>;
  delete: (id: string) => Promise<void>;
  byProject: (
    projectId: string,
    options?: { type?: Result['type']; limit?: number; offset?: number }
  ) => Promise<Result[]>;
  version: {
    create: (
      resultId: string,
      data: unknown,
      config?: Record<string, unknown>,
      createdByBranchId?: string
    ) => Promise<ResultVersion>;
    get: (id: string) => Promise<ResultVersion | null>;
    getByNumber: (resultId: string, version: number) => Promise<ResultVersion | null>;
    list: (resultId: string, limit?: number, offset?: number) => Promise<ResultVersion[]>;
  };
  // Phase 4: Conversation export
  createFromConversation: (
    projectId: string,
    branchId: string,
    options?: {
      name?: string;
      includeMessages?: boolean;
      generateSummary?: boolean;
    }
  ) => Promise<Result>;
}

function createResultBridge(): ResultApi {
  const bridge = getBridge('result');

  if (!bridge) {
    return {
      create: async () => {
        throw new Error('Result bridge not available');
      },
      get: async () => null,
      list: async () => [],
      update: async () => null,
      delete: async () => {
        throw new Error('Result bridge not available');
      },
      byProject: async () => [],
      version: {
        create: async () => {
          throw new Error('Result bridge not available');
        },
        get: async () => null,
        getByNumber: async () => null,
        list: async () => [],
      },
      createFromConversation: async () => {
        throw new Error('Result bridge not available');
      },
    };
  }

  return {
    create: (projectId, type, name, data, config, sourceBranchId) =>
      unwrap(
        bridge.create({ projectId, type, name, data, config, sourceBranchId })
      ),

    get: (id) => unwrapNullable(bridge.get({ id })),

    list: (projectId, options) => unwrap(bridge.list({ projectId, options })),

    update: (id, updates) => unwrapNullable(bridge.update({ id, updates })),

    delete: (id) => unwrap(bridge.delete({ id })),

    byProject: (projectId, options) =>
      unwrap(bridge.byProject({ projectId, options })),

    version: {
      create: (resultId, data, config, createdByBranchId) =>
        unwrap(
          bridge.version.create({ resultId, data, config, createdByBranchId })
        ),

      get: (id) => unwrapNullable(bridge.version.get({ id })),

      getByNumber: (resultId, version) =>
        unwrapNullable(bridge.version.getByNumber({ resultId, version })),

      list: (resultId, limit, offset) =>
        unwrap(bridge.version.list({ resultId, limit, offset })),
    },

    createFromConversation: (projectId, branchId, options) =>
      unwrap(bridge.createFromConversation({ projectId, branchId, options })),
  };
}

export const resultApi = createResultBridge();

