describe('UI-141 startup gate', () => {
  it('shows backend recovery after 30s when runtimes are installed', () => {
    backendStatus = status({ rRuntime: true, pyRuntime: true });
    render(<Home />);

    expect(screen.queryByText('本地分析服务未就绪')).toBeNull();
    act(() => vi.advanceTimersByTime(30_000));

    expect(screen.getByRole('heading', { name: '本地分析服务未就绪' })).toBeTruthy();
    expect(screen.getByText(/与「是否安装分析运行时」无关/)).toBeTruthy();
    expect(screen.getByRole('button', { name: '重试连接' })).toBeTruthy();
    expect(screen.queryByText('先安装分析运行时')).toBeNull();
  });

  // BLOCK-66 P2 — R 缺失不再整页拦截：首页正常渲染 + 非阻塞引导条 + 商店 overlay。
  // BLOCK-86 P2 — 领域感知：只有已装领域包声明运行时才出提示（stub packs 桥供给）。
  it('keeps home usable with a non-blocking banner when R runtime is missing', async () => {
    backendStatus = status({ rRuntime: false, pyRuntime: true, isReady: true, rServerUp: true });
    vi.mocked(listProjects).mockResolvedValue([]);
    Object.defineProperty(window, 'petriDesktop', {
      configurable: true,
      value: {
        packs: {
          listInstalled: vi.fn(async () => ({
            ok: true,
            packs: [{ packId: 'petri-pack-bio', name: '格物 · 生信分析包', packRoot: '/p', version: '0.1.0', installedAt: 'x', requiresRuntimes: [{ pluginId: 'petri-r-runtime' }] }],
          })),
        },
      },
    });
    vi.useRealTimers();
    render(<Home />);

    // 首页正常渲染（status=ready，未被任何全屏门拦截）
    await screen.findByText('创建第一个项目');
    // 引导条出现（非阻塞），文案挂包名
    await screen.findByRole('status');
    const bannerText = screen.getByText(/已安装领域包/).textContent ?? '';
    expect(bannerText).toContain('格物 · 生信分析包');
    expect(bannerText).toContain('需要 R 运行时');
    expect(screen.getByRole('button', { name: '前往安装' })).toBeTruthy();
    // 全屏门不再出现
    expect(screen.queryByText('先安装分析运行时')).toBeNull();
    expect(screen.queryByText('本地分析服务未就绪')).toBeNull();

    // 点「前往安装」→ 商店 overlay 打开（不再占据整页）；rRuntime=false 时无重启脚注
    act(() => {
      screen.getByRole('button', { name: '前往安装' }).click();
    });
    expect(screen.getByText('插件商店')).toBeTruthy();
    expect(screen.queryByText(/R 运行时已就绪，重启应用即可开始分析/)).toBeNull();

    // 还原 window 桥 stub（防泄漏到后续 describe）
    Object.defineProperty(window, 'petriDesktop', { configurable: true, value: undefined });
  });
});

// ============================================================================
// BLOCK-53 P1 / UI-282 — 拖拽目录直达创建：窗口 drop → validateDirectory →
// UI-253 既有确认面板（不绕过确认）。jsdom 无 DragEvent 构造器，用 Event
// + defineProperty 挂 dataTransfer 模拟 Finder 拖入。
// ============================================================================
describe('BLOCK-53 P1 drag-to-create', () => {
  const originalDesktop = (window as { petriDesktop?: unknown }).petriDesktop;

  function mockDesktop(validate: (path: string) => unknown) {
    Object.defineProperty(window, 'petriDesktop', {
      configurable: true,
      value: {
        files: {
          validateDirectory: vi.fn(validate),
          pathForFile: vi.fn(() => '/tmp/drop-proj'),
        },
      },
    });
  }

  function fireWindowDrop(files: Array<{ name: string }>) {
    const evt = new Event('drop') as DragEvent;
    Object.defineProperty(evt, 'dataTransfer', {
      configurable: true,
      value: { files },
    });
    window.dispatchEvent(evt);
  }

  afterEach(() => {
    Object.defineProperty(window, 'petriDesktop', {
      configurable: true,
      value: originalDesktop,
    });
  });

  it('drops a directory → validates → shows the UI-253 confirm panel', async () => {
    backendStatus = status({ isReady: true, rServerUp: true });
    // vi.restoreAllMocks（全局 afterEach）会清掉模块级 mock 实现，这里重设
    vi.mocked(listProjects).mockResolvedValue([]);
    mockDesktop(() => ({ ok: true, data: { path: '/tmp/drop-proj' } }));
    vi.useRealTimers();
    render(<Home />);
    await screen.findByText('创建第一个项目');

    fireWindowDrop([{ name: 'drop-proj' }]);

    expect(await screen.findByText('将在以下目录创建项目：')).toBeTruthy();
    expect(screen.getByText('/tmp/drop-proj')).toBeTruthy();
    expect(screen.getByRole('button', { name: '在此处创建' })).toBeTruthy();
    // 校验链被真实调用（拖入路径走同一校验，不绕过）
    expect((window as unknown as { petriDesktop: { files: { validateDirectory: ReturnType<typeof vi.fn> } } }).petriDesktop.files.validateDirectory)
      .toHaveBeenCalledWith('/tmp/drop-proj');
  });

  it('drops a non-directory file → visible error, no confirm panel', async () => {
    backendStatus = status({ isReady: true, rServerUp: true });
    vi.mocked(listProjects).mockResolvedValue([]);
    mockDesktop(() => ({ ok: false, error: '该路径不是文件夹' }));
    vi.useRealTimers();
    render(<Home />);
    await screen.findByText('创建第一个项目');

    fireWindowDrop([{ name: 'note.txt' }]);

    expect(await screen.findByText('该路径不是文件夹')).toBeTruthy();
    expect(screen.queryByText('将在以下目录创建项目：')).toBeNull();
  });
});

