import { useCallback, useEffect, useState } from 'react';
import type { Dispatch, SetStateAction } from 'react';
import type { ActiveWorkspaceFile } from './types';

// BLOCK-92 Wave B-1 — 工作区文件 tab 状态簇外迁（原 ProjectWorkspace 内联，纯搬运零行为变化）：
// 打开文件列表 + 活动文件 + 打开/关闭处理（关闭后活动文件回退到相邻 tab）。
export function useWorkspaceFileTabs(projectId: string | null | undefined): {
  openWorkspaceFiles: ActiveWorkspaceFile[];
  activeWorkspaceFile: ActiveWorkspaceFile | null;
  setActiveWorkspaceFile: Dispatch<SetStateAction<ActiveWorkspaceFile | null>>;
  handleOpenWorkspaceFile: (file: ActiveWorkspaceFile) => void;
  handleCloseWorkspaceFile: (pathToClose: string) => void;
} {
  const [openWorkspaceFiles, setOpenWorkspaceFiles] = useState<ActiveWorkspaceFile[]>([]);
  const [activeWorkspaceFile, setActiveWorkspaceFile] = useState<ActiveWorkspaceFile | null>(null);

  useEffect(() => {
    setActiveWorkspaceFile(null);
    setOpenWorkspaceFiles([]);
  }, [projectId]);

  const handleOpenWorkspaceFile = useCallback((file: ActiveWorkspaceFile) => {
    setOpenWorkspaceFiles((prev) => (
      prev.some((item) => item.path === file.path) ? prev : [...prev, file]
    ));
    setActiveWorkspaceFile(file);
  }, []);

  const handleCloseWorkspaceFile = useCallback((pathToClose: string) => {
    setOpenWorkspaceFiles((prev) => {
      const closingIndex = prev.findIndex((item) => item.path === pathToClose);
      const next = prev.filter((item) => item.path !== pathToClose);
      setActiveWorkspaceFile((current) => {
        if (current?.path !== pathToClose) return current;
        return next[Math.min(Math.max(closingIndex, 0), next.length - 1)] || null;
      });
      return next;
    });
  }, []);

  return {
    openWorkspaceFiles,
    activeWorkspaceFile,
    setActiveWorkspaceFile,
    handleOpenWorkspaceFile,
    handleCloseWorkspaceFile,
  };
}

import { useEffect } from 'react';
import type { Dispatch, MutableRefObject, SetStateAction } from 'react';
import type { NavigateFunction } from 'react-router-dom';
import type { Project } from '@/lib/project-types';
import type { ActiveWorkspaceFile } from './types';
import type { WorkspaceMode } from '@/hooks/useWorkspaceRouting';
import { petriEvents, subscribePetriEvent, dispatchPetriEvent } from '@/lib/events';
import { usePendingScroll } from '@/lib/pendingScrollContext';
import type { DiffRevision } from '@/components/editor/CodeMirror/types';
import { workspaceFileUrlFor } from '@/lib/previewFileUtils';
import { getBridge } from '@/lib/desktopBridge';
import {
  requestedArtifactRequestKey,
  shouldApplyRequestedArtifact,
} from '@/components/result-studio/resultSurface';

// BLOCK-92 Wave B-1 — 结果/文件打开事件 effects 簇外迁（原 ProjectWorkspace 内联，纯搬运零行为变化）。
// 覆盖：URL 请求参数自动打开（job/artifact/file）、projectOpenResult、
// projectOpenArtifact（含跨项目导航）、指挥中心独立窗 relay、
// projectOpenWorkspaceFile（含行跳转与系统应用打开）。

type SetPendingRequest = ReturnType<typeof usePendingScroll>['setPendingRequest'];

interface UseWorkspaceOpenEffectsOptions {
  projectId: string | undefined;
  project: Project | null;
  workspacePath: string;
  loading: boolean;
  workspaceMode: WorkspaceMode;
  requestedJobId: string | null;
  requestedArtifactName: string | null;
  requestedFilePath: string | null;
  searchParams: URLSearchParams;
  activeJobId: string | null;
  // jobs 仅作依赖项（保持原 effect 依赖数组逐字不变）
  jobs: readonly unknown[];
  activeWorkspaceFilePath: string | undefined;
  openResultRequestSequenceRef: MutableRefObject<number>;
  autoOpenedJobRef: MutableRefObject<string | null>;
  appliedRequestedArtifactKeyRef: MutableRefObject<string | null>;
  pendingArtifactNameRef: MutableRefObject<string | null>;
  pendingArtifactJobIdRef: MutableRefObject<string | null>;
  setPendingArtifactName: Dispatch<SetStateAction<string | null>>;
  handleOpenResult: (
    jobId: string,
    targetProjectId?: string | null,
    options?: { preserveWorkspaceMode?: boolean; workspaceMode?: WorkspaceMode }
  ) => Promise<void>;
  handleOpenWorkspaceFile: (file: ActiveWorkspaceFile) => void;
  openRightPanel: (tab: import('./rightPanelTabs').RightPanelMode) => void;
  navigate: NavigateFunction;
  setPendingRequest: SetPendingRequest;
}

export function useWorkspaceOpenEffects(options: UseWorkspaceOpenEffectsOptions): void {
  const {
    projectId,
    project,
    workspacePath,
    loading,
    workspaceMode,
    requestedJobId,
    requestedArtifactName,
    requestedFilePath,
    searchParams,
    activeJobId,
    jobs,
    activeWorkspaceFilePath,
    openResultRequestSequenceRef,
    autoOpenedJobRef,
    appliedRequestedArtifactKeyRef,
    pendingArtifactNameRef,
    pendingArtifactJobIdRef,
    setPendingArtifactName,
    handleOpenResult,
    handleOpenWorkspaceFile,
    openRightPanel,
    navigate,
    setPendingRequest,
  } = options;

  useEffect(() => {
    autoOpenedJobRef.current = null;
  }, [projectId]);
  useEffect(() => {
    if (loading || !projectId) return;
    if (searchParams.get('mode')) return;
    if (requestedJobId) {
      const requestKey = requestedArtifactRequestKey({
        projectId,
        jobId: requestedJobId,
        artifactName: requestedArtifactName,
      });
      if (!requestKey) appliedRequestedArtifactKeyRef.current = null;
      if (shouldApplyRequestedArtifact(appliedRequestedArtifactKeyRef.current, requestKey)) {
        appliedRequestedArtifactKeyRef.current = requestKey;
        pendingArtifactNameRef.current = requestedArtifactName;
        pendingArtifactJobIdRef.current = requestedJobId;
        setPendingArtifactName(requestedArtifactName);
      }
      if (
        activeJobId === requestedJobId &&
        (workspaceMode === 'result' || workspaceMode === 'code' || workspaceMode === 'compare' || workspaceMode === 'history' || workspaceMode === 'chat')
      ) return;
      if (autoOpenedJobRef.current === requestedJobId) return;
      autoOpenedJobRef.current = requestedJobId;
      void handleOpenResult(requestedJobId, projectId, {
        preserveWorkspaceMode: workspaceMode === 'chat' || workspaceMode === 'history',
        workspaceMode,
      });
      return;
    }
    appliedRequestedArtifactKeyRef.current = null;
  }, [activeJobId, handleOpenResult, jobs, loading, projectId, requestedArtifactName, requestedJobId, workspaceMode]);
  useEffect(() => {
    if (loading || !projectId || !requestedFilePath) return;
    if (activeWorkspaceFilePath === requestedFilePath) return;
    const file: ActiveWorkspaceFile = {
      path: requestedFilePath,
      name: requestedFilePath.split('/').pop() || requestedFilePath,
      url: workspaceFileUrlFor(projectId, requestedFilePath),
      workspaceDir: project?.workspacePath,
      workspaceKind: project?.workspaceKind,
    };
    handleOpenWorkspaceFile(file);
    openRightPanel('files');
  }, [activeWorkspaceFilePath, handleOpenWorkspaceFile, loading, openRightPanel, projectId, requestedFilePath]);
  useEffect(() => {
    const handler = (detail: { toolJobId: string; projectId?: string | null }) => {
      const d = detail;
      if (d?.toolJobId) {
        handleOpenResult(d.toolJobId, d.projectId || null);
      }
    };
    const unsub = subscribePetriEvent(petriEvents.projectOpenResult, handler);
    return unsub;
  }, [handleOpenResult]);
  useEffect(() => {
    const handler = (detail: { jobId: string; artifactName: string; projectId?: string | null }) => {
      if (!detail?.jobId || !detail?.artifactName) return;
      const targetProjectId = detail.projectId || projectId;
      pendingArtifactNameRef.current = detail.artifactName;
      pendingArtifactJobIdRef.current = detail.jobId;
      setPendingArtifactName(detail.artifactName);
      if (targetProjectId && targetProjectId !== projectId) {
        navigate(
          `/project/${encodeURIComponent(targetProjectId)}?mode=chat&job=${encodeURIComponent(detail.jobId)}&artifact=${encodeURIComponent(detail.artifactName)}`,
        );
        return;
      }
      void handleOpenResult(detail.jobId, targetProjectId || null, { preserveWorkspaceMode: true });
    };
    const unsub = subscribePetriEvent(petriEvents.projectOpenArtifact, handler);
    return unsub;
  }, [handleOpenResult, navigate, projectId]);
  // UI-385 — 指挥中心独立窗下钻 relay（agent/result 独立窗退役）：主窗 preload
  // 收到 window:relay-to-main 后回调，这里转派既有 projectOpenArtifact 处理链
  // （跨项目自动导航；单一事实走同一条结果打开链路）。
  useEffect(() => {
    const wm = getBridge('windowManager');
    if (!wm?.onRelayToMain) return;
    return wm.onRelayToMain((payload) => {
      if (payload?.type !== petriEvents.projectOpenArtifact) return;
      dispatchPetriEvent(petriEvents.projectOpenArtifact, payload.detail as { jobId: string; artifactName: string; projectId?: string | null });
    });
  }, []);
  useEffect(() => {
    const handler = (detail: {
      projectId: string;
      relativePath: string;
      name?: string;
      openWithSystemApp?: boolean;
      line?: number;
      column?: number;
      diffRevision?: { filePath: string; originalText: string; modifiedText: string };
    }) => {
      if (!detail?.projectId || !detail?.relativePath) return;
      if (detail.projectId !== projectId) {
        // Cross-project workspace files are out of scope for the desktop
        // workspace (each project has its own file tree); the chat host
        // can decide to navigate or surface a toast.
        navigate(`/project/${encodeURIComponent(detail.projectId)}?mode=chat&file=${encodeURIComponent(detail.relativePath)}`);
        return;
      }
      const file: ActiveWorkspaceFile = {
        path: detail.relativePath,
        name: detail.name || detail.relativePath.split('/').pop() || detail.relativePath,
        url: workspaceFileUrlFor(projectId || '', detail.relativePath),
        workspaceDir: project?.workspacePath,
      workspaceKind: project?.workspaceKind,
      };
      handleOpenWorkspaceFile(file);
      openRightPanel('files');
      // BLOCK-22 P4.5: Dispatch pending scroll request so WorkspaceFilePreviewBridge
      // can scroll to the target line and/or enter inline-diff mode.
      if (detail.line !== undefined) {
        const diffRevision: DiffRevision | undefined = detail.diffRevision
          ? {
              filePath: detail.diffRevision.filePath,
              originalText: detail.diffRevision.originalText,
              modifiedText: detail.diffRevision.modifiedText,
            }
          : undefined;
        setPendingRequest({
          filePath: detail.relativePath,
          line: detail.line,
          column: detail.column,
          diffRevision,
          // BLOCK-42 P4：事件驱动的跳转（聊天卡片/审阅联动）补 pulse 高亮，
          // 与 highlight:true 简写（3000ms）及 WTR review 跳行行为一致。
          pulseMs: 3000,
          timestamp: Date.now(),
        });
      }
      if (detail.openWithSystemApp && workspacePath) {
        void getBridge('files')?.openWorkspaceFile(workspacePath, detail.relativePath);
      }
    };
    const unsub = subscribePetriEvent(petriEvents.projectOpenWorkspaceFile, handler);
    return unsub;
  }, [handleOpenWorkspaceFile, navigate, openRightPanel, projectId, workspacePath, setPendingRequest]);
}

import { useEffect, useMemo } from 'react';
import type { Dispatch, SetStateAction } from 'react';
import { useWorkspacePanelsContext } from '@/components/desktop/WorkspacePanelsContext';
import { petriEvents, dispatchPetriEvent } from '@/lib/events';
import { RIGHT_PANEL_ITEMS, type RightPanelMode } from './rightPanelTabs';

// BLOCK-92 Wave B-1 — TitleBar 注册 effect 簇外迁（原 ProjectWorkspace 内联，纯搬运零行为变化）。
// TitleBar 注册 —— 8f3d55a5 曾误删整段（右侧工具菜单「+」/ 标签 pills / 结果
// 选择器随之全部失效），UI-309 从 e689f867 恢复。BLOCK-62 P2：宽度两字段
// （leftPanelWidth/rightPanelWidth）已从 TitleBarState 退役——regular 顶栏是
// 列内 ColumnHeader（宽=aside 宽，同 commit），compact/loading/error 的 fixed
// 条宽度改由本页 props 同树直传，不再每拖拽帧跨树推送 context。

type UpdateTitleBar = ReturnType<typeof useWorkspacePanelsContext>['updateTitleBar'];

interface UseWorkspaceTitleBarOptions {
  updateTitleBar: UpdateTitleBar;
  projectName: string | undefined;
  titleBarTitle: string;
  rightTab: RightPanelMode;
  rightToolMenuOpen: boolean;
  openRightTabs: RightPanelMode[];
  activeJobId: string | null;
  conversationJobs: Array<{ id: string; status?: string; name?: string; tool_id?: string; created_at: number | string }>;
  browserCanGoBack: boolean;
  browserCanGoForward: boolean;
  // UI-309：旧版遗漏——缺失会让顶栏会话选择器持有过期闭包（仅作依赖项）
  conversations: readonly unknown[];
  activeConvId: string | null;
  handleSwitchConversation: unknown;
  handleOpenRightResults: () => void;
  handleSelectTitleBarResult: (jobId: string) => void;
  openRightPanel: (tab: RightPanelMode) => void;
  closeRightPanelTab: (tab: RightPanelMode) => void;
  setRightOpen: (open: boolean) => void;
  setRightTab: (tab: RightPanelMode) => void;
  setRightToolMenuOpen: Dispatch<SetStateAction<boolean>>;
}

export function useWorkspaceTitleBar(options: UseWorkspaceTitleBarOptions): void {
  const {
    updateTitleBar,
    projectName,
    titleBarTitle,
    rightTab,
    rightToolMenuOpen,
    openRightTabs,
    activeJobId,
    conversationJobs,
    browserCanGoBack,
    browserCanGoForward,
    conversations,
    activeConvId,
    handleSwitchConversation,
    handleOpenRightResults,
    handleSelectTitleBarResult,
    openRightPanel,
    closeRightPanelTab,
    setRightOpen,
    setRightTab,
    setRightToolMenuOpen,
  } = options;

  const titleBarTabs = useMemo(
    () =>
      openRightTabs
        .filter((tab) => tab !== 'home')
        .map((tab) => {
          const item = RIGHT_PANEL_ITEMS.find((candidate) => candidate.id === tab);
          return {
            id: tab,
            label: item?.label || tab,
            icon: item?.icon || 'folder',
            closable: true,
          };
        }),
    [openRightTabs]
  );
  const titleBarResultItems = useMemo(() => conversationJobs.map((job) => {
    const status = job.status === 'done'
      ? '完成'
      : job.status === 'failed'
        ? '失败'
        : job.status === 'running'
          ? '运行中'
          : '排队中';
    return {
      id: job.id,
      label: job.name || job.tool_id || '分析结果',
      status: `${status} · ${new Date(job.created_at).toLocaleTimeString('zh-CN', {
        month: '2-digit',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit',
      })}`,
    };
  }), [conversationJobs]);

  useEffect(() => {
    updateTitleBar({
      title: titleBarTitle,
      tabs: titleBarTabs,
      activeTabId: rightTab === 'home' ? null : rightTab,
      onSelectTab: (tabId) => {
        if (tabId === 'results') {
          handleOpenRightResults();
          return;
        }
        setRightTab(tabId as RightPanelMode);
        setRightToolMenuOpen(false);
        setRightOpen(true);
      },
      onCloseTab: (tabId) => closeRightPanelTab(tabId as RightPanelMode),
      onMoreAction: () => setRightToolMenuOpen((value) => !value),
      toolMenuOpen: rightToolMenuOpen,
      toolMenuItems: RIGHT_PANEL_ITEMS.map((item) => ({
        id: item.id,
        label: item.label,
        icon: item.icon,
        isOpen: openRightTabs.includes(item.id),
      })),
      onSelectToolItem: (tabId) => {
        if (tabId === 'results') {
          handleOpenRightResults();
          setRightToolMenuOpen(false);
          return;
        }
        openRightPanel(tabId as RightPanelMode);
        setRightToolMenuOpen(false);
      },
      resultItems: titleBarResultItems,
      activeResultId: conversationJobs.some((job) => job.id === activeJobId) ? activeJobId : null,
      onSelectResult: handleSelectTitleBarResult,
      canGoBack: rightTab === 'browser' && browserCanGoBack,
      canGoForward: rightTab === 'browser' && browserCanGoForward,
      onGoBack:
        rightTab === 'browser' && browserCanGoBack
          ? () => dispatchPetriEvent(petriEvents.browserBack)
          : null,
      onGoForward:
        rightTab === 'browser' && browserCanGoForward
          ? () => dispatchPetriEvent(petriEvents.browserForward)
          : null,
    });
    return () => {
      updateTitleBar({
        title: 'Petri',
        tabs: [],
        activeTabId: null,
        onSelectTab: null,
        onCloseTab: null,
        onMoreAction: null,
        toolMenuOpen: false,
        toolMenuItems: [],
        onSelectToolItem: null,
        resultItems: [],
        activeResultId: null,
        onSelectResult: null,
        canGoBack: false,
        canGoForward: false,
        onGoBack: null,
        onGoForward: null,
      });
    };
  }, [
    activeJobId,
    closeRightPanelTab,
    browserCanGoBack,
    browserCanGoForward,
    openRightPanel,
    openRightTabs,
    projectName,
    titleBarTitle,
    rightTab,
    handleOpenRightResults,
    handleSelectTitleBarResult,
    rightToolMenuOpen,
    setRightOpen,
    setRightToolMenuOpen,
    setRightTab,
    titleBarTabs,
    titleBarResultItems,
    updateTitleBar,
    // UI-309：旧版遗漏——缺失会让顶栏会话选择器持有过期闭包
    conversations,
    activeConvId,
    handleSwitchConversation,
  ]);
}

// ============================================================
// ResultStudio Page
//
// Phase 2: Result Studio UI with project-scoped results
//
// Key architectural principle:
//   - Results are loaded by PROJECT ID, not branch ID
//   - Branch switching does NOT trigger Result Studio reload
//   - This page demonstrates the "conversation isolation, result sharing" model
//
// Layout:
//   ┌──────────────────────────────────────────────────────────────┐
//   │ [📁 项目] [Branch A] [Branch B] [+] [结果 2 ▼]             │
//   ├────────────────┬─────────────────────────────────────────────┤
//   │                │                                             │
//   │  Copilot       │         Result Studio（共享）               │
//   │  ──────────   │         ────────────────────               │
//   │  (按分支隔离)  │         (按项目共享，跨分支不变)             │
//   │                │                                             │
//   └────────────────┴─────────────────────────────────────────────┘
// ============================================================

import React, { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import { useResultStore } from '@/hooks/useResultStore';
import { useBranchStore } from '@/hooks/useBranchStore';
import { BranchTabsWrapper } from '@/components/branch/BranchTabsWrapper';
import { ResultVersionHistory } from './components/ResultVersionHistory';
import type { Result, ResultVersion } from '@/types/result.types';
import styles from './ResultStudio.module.css';

export function ResultStudioPage(): React.ReactElement {
  const { projectId } = useParams<{ projectId: string }>();

  // Result store - keyed on projectId, NOT branchId
  // This is the key: results persist across branch switches
  const {
    results,
    summaries,
    activeResultId,
    loading,
    error,
    refresh,
    setActiveResult,
    createResult,
    updateResult,
    deleteResult,
  } = useResultStore(projectId);

  // Branch store - also keyed on projectId
  const { branches, activeBranchId } = useBranchStore(projectId);

  // Current version tracking for the selected result
  const [currentVersion, setCurrentVersion] = useState<number>(1);

  // Load results on mount / projectId change
  useEffect(() => {
    if (projectId) {
      refresh();
    }
  }, [projectId, refresh]);

  const activeResult = results.find((r) => r.id === activeResultId) || null;

  return (
    <div className={styles.resultStudio}>
      {/* Header with project info and branch tabs */}
      <header className={styles.header}>
        <div className={styles.projectInfo}>
          <span className={styles.projectLabel}>项目结果</span>
          {projectId && (
            <span className={styles.resultCount}>
              {results.length} 个结果
            </span>
          )}
        </div>
        <BranchTabsWrapper />
      </header>

      {/* Main content area */}
      <main className={styles.content}>
        {/* Results list sidebar */}
        <aside className={styles.sidebar}>
          <div className={styles.sidebarHeader}>
            <h2>结果列表</h2>
            <button
              type="button"
              className={styles.refreshButton}
              onClick={() => refresh()}
              disabled={loading}
            >
              刷新
            </button>
          </div>

          {loading && <div className={styles.loading}>加载中...</div>}
          {error && <div className={styles.error}>{error}</div>}

          <div className={styles.resultList}>
            {summaries.length === 0 && !loading && (
              <div className={styles.emptyState}>
                <p>暂无结果</p>
                <p className={styles.hint}>
                  在 Copilot 中运行分析后会显示在这里
                </p>
              </div>
            )}

            {summaries.map((result) => (
              <div
                key={result.id}
                className={`${styles.resultItem} ${
                  result.id === activeResultId ? styles.resultItemActive : ''
                }`}
                onClick={() => setActiveResult(result.id)}
                role="button"
                tabIndex={0}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' || e.key === ' ') {
                    setActiveResult(result.id);
                  }
                }}
              >
                <div className={styles.resultIcon}>
                  <ResultTypeIcon type={result.type} />
                </div>
                <div className={styles.resultInfo}>
                  <span className={styles.resultName}>{result.name}</span>
                  <span className={styles.resultMeta}>
                    {result.type} · {formatDate(result.updatedAt)}
                  </span>
                </div>
              </div>
            ))}
          </div>
        </aside>

        {/* Result detail view */}
        <section className={styles.detail}>
          {activeResult ? (
            <ResultDetail
              result={activeResult}
              onUpdate={(updates) => updateResult(activeResult.id, updates)}
              onDelete={() => {
                deleteResult(activeResult.id);
                setActiveResult(null);
              }}
            />
          ) : (
            <div className={styles.noSelection}>
              <p>选择一个结果以查看详情</p>
              <p className={styles.hint}>
                结果按项目共享，切换分支不会影响结果列表
              </p>
            </div>
          )}
        </section>
      </main>

      {/* Branch isolation indicator */}
      <footer className={styles.footer}>
        <div className={styles.branchIndicator}>
          <span className={styles.branchLabel}>当前分支:</span>
          <span className={styles.branchName}>
            {branches.find((b) => b.id === activeBranchId)?.name || '无'}
          </span>
          <span className={styles.isolationNote}>
            (对话隔离，结果共享)
          </span>
        </div>
      </footer>
    </div>
  );
}

