// ============================================================
// ResultVersionHistory Component
//
// Phase 4: Result version management UI
// Displays version history and supports version switching
// ============================================================

import React, { useState } from 'react';
import { resultApi } from '../../../lib/resultBridge';
import type { ResultVersion } from '../../../types/result.types';
import styles from '../ResultStudio.module.css';

interface ResultVersionHistoryProps {
  resultId: string;
  currentVersion: number;
  onVersionSelect: (version: ResultVersion) => void;
}

export const ResultVersionHistory: React.FC<ResultVersionHistoryProps> = ({
  resultId,
  currentVersion,
  onVersionSelect,
}) => {
  const [versions, setVersions] = useState<ResultVersion[]>([]);
  const [loading, setLoading] = useState(false);
  const [expanded, setExpanded] = useState(false);
  const [loaded, setLoaded] = useState(false);

  const loadVersions = async () => {
    if (loaded && versions.length > 0) {
      setExpanded(!expanded);
      return;
    }

    setLoading(true);
    try {
      const versionList = await resultApi.version.list(resultId);
      setVersions(versionList || []);
      setExpanded(true);
      setLoaded(true);
    } catch (error) {
      console.error('Failed to load versions:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleVersionClick = (version: ResultVersion) => {
    onVersionSelect(version);
  };

  const formatDate = (timestamp: number): string => {
    return new Date(timestamp).toLocaleString('zh-CN', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  return (
    <div className={styles.versionHistory}>
      <button
        type="button"
        className={styles.versionHeader}
        onClick={loadVersions}
        aria-expanded={expanded}
      >
        <span>版本历史 ({loaded ? versions.length : '...'})</span>
        <span className={`${styles.expandIcon} ${expanded ? styles.expanded : ''}`}>
          ▼
        </span>
      </button>

      {expanded && (
        <div className={styles.versionList}>
          {loading && <div className={styles.loading}>加载中...</div>}

          {!loading && versions.map((version) => (
            <div
              key={version.id}
              className={`${styles.versionItem} ${
                version.version === currentVersion ? styles.active : ''
              }`}
              onClick={() => handleVersionClick(version)}
              onKeyDown={(e) => {
                if (e.key === 'Enter' || e.key === ' ') {
                  handleVersionClick(version);
                }
              }}
              role="button"
              tabIndex={0}
            >
              <div className={styles.versionNumber}>
                v{version.version}
                {version.version === currentVersion && (
                  <span className={styles.currentBadge}>当前</span>
                )}
              </div>
              <div className={styles.versionMeta}>
                <span>{formatDate(version.createdAt)}</span>
              </div>
            </div>
          ))}

          {!loading && versions.length === 0 && (
            <div className={styles.emptyVersions}>暂无版本历史</div>
          )}
        </div>
      )}
    </div>
  );
};

/**
 * SkillDetail — 技能详情弹窗组件
 * 显示技能的完整信息、参数配置和执行选项
 */

import React, { useCallback, useState } from 'react';
import { Icon } from '@/components/icons/Icon';
import type { Skill, ParameterSchema } from '@/hooks/useSkillStore';
import styles from './styles.module.css';

interface SkillDetailProps {
  skill: Skill;
  onClose: () => void;
  onExecute: (skill: Skill, params: Record<string, unknown>) => void;
  canExecute?: boolean;
  isExecuting?: boolean;
}

interface ParamValues {
  [key: string]: unknown;
}

function ParameterField({
  name,
  spec,
  value,
  onChange,
}: {
  name: string;
  spec: ParameterSchema;
  value: unknown;
  onChange: (name: string, value: unknown) => void;
}): React.ReactElement {
  const handleChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
      let newValue: unknown = e.target.value;
      if (spec.type === 'number') {
        newValue = parseFloat(e.target.value) || 0;
      } else if (spec.type === 'boolean') {
        newValue = (e.target as HTMLInputElement).checked;
      }
      onChange(name, newValue);
    },
    [name, onChange, spec.type]
  );

  const inputId = `param-${name}`;

  return (
    <div className={styles.paramField}>
      <label htmlFor={inputId} className={styles.paramLabel}>
        {name}
        <span className={styles.paramDescription}>{spec.description}</span>
      </label>
      <div className={styles.paramControl}>
        {spec.type === 'boolean' ? (
          <label className={styles.toggle}>
            <input
              type="checkbox"
              id={inputId}
              checked={Boolean(value)}
              onChange={handleChange}
            />
            <span className={styles.toggleSlider} />
          </label>
        ) : spec.type === 'select' ? (
          <select
            id={inputId}
            className={styles.select}
            value={String(value ?? spec.default ?? '')}
            onChange={handleChange}
          >
            {spec.options?.map((opt) => (
              <option key={opt} value={opt}>
                {opt}
              </option>
            ))}
          </select>
        ) : spec.type === 'number' ? (
          <input
            type="number"
            id={inputId}
            className={styles.numberInput}
            value={String(value ?? spec.default ?? '')}
            min={spec.min}
            max={spec.max}
            step={spec.step}
            onChange={handleChange}
          />
        ) : (
          <input
            type="text"
            id={inputId}
            className={styles.textInput}
            value={String(value ?? spec.default ?? '')}
            onChange={handleChange}
          />
        )}
        {spec.type !== 'boolean' && spec.default !== undefined && (
          <span className={styles.paramDefault}>默认: {String(spec.default)}</span>
        )}
      </div>
    </div>
  );
}

export function SkillDetail({
  skill,
  onClose,
  onExecute,
  canExecute = true,
  isExecuting = false,
}: SkillDetailProps): React.ReactElement {
  const [paramValues, setParamValues] = useState<ParamValues>(() => {
    const defaults: ParamValues = {};
    const optionalParams = skill.parameters?.optional ?? {};
    for (const [key, spec] of Object.entries(optionalParams)) {
      defaults[key] = spec.default;
    }
    return defaults;
  });

  const handleParamChange = useCallback((name: string, value: unknown) => {
    setParamValues((prev) => ({ ...prev, [name]: value }));
  }, []);

  const handleExecute = useCallback(() => {
    onExecute(skill, paramValues);
  }, [skill, paramValues, onExecute]);

  const handleBackdropClick = useCallback(
    (e: React.MouseEvent) => {
      if (e.target === e.currentTarget) {
        onClose();
      }
    },
    [onClose]
  );

  const optionalParams = skill.parameters?.optional ?? {};
  const primaryOutputs = skill.outputs?.primary ?? [];
  const secondaryOutputs = skill.outputs?.secondary ?? [];

  return (
    <div
      className={styles.modalBackdrop}
      onClick={handleBackdropClick}
      role="dialog"
      aria-modal="true"
      aria-labelledby="skill-detail-title"
    >
      <div className={styles.modalContent}>
        <header className={styles.modalHeader}>
          <div className={styles.modalTitleRow}>
            <h2 id="skill-detail-title" className={styles.modalTitle}>
              {skill.name}
            </h2>
            <span className={styles.modalVersion}>v{skill.version}</span>
          </div>
          <button
            type="button"
            className={styles.closeButton}
            onClick={onClose}
            aria-label="关闭"
          >
            <Icon name="x" size={18} />
          </button>
        </header>

        <div className={styles.modalBody}>
          <section className={styles.detailSection}>
            <h3 className={styles.sectionTitle}>描述</h3>
            <p className={styles.description}>{skill.description}</p>
          </section>

          <section className={styles.detailSection}>
            <h3 className={styles.sectionTitle}>类别与标签</h3>
            <div className={styles.metaRow}>
              <span className={styles.categoryBadge}>{skill.category}</span>
              {skill.tags.map((tag) => (
                <span key={tag} className={styles.tag}>
                  {tag}
                </span>
              ))}
            </div>
          </section>

          <section className={styles.detailSection}>
            <h3 className={styles.sectionTitle}>依赖插件</h3>
            {skill.plugins.required.length > 0 ? (
              <div className={styles.pluginList}>
                <span className={styles.pluginLabel}>必需</span>
                {skill.plugins.required.map((plugin) => (
                  <span key={plugin} className={styles.pluginBadge}>
                    <Icon name="puzzle" size={12} />
                    {plugin}
                  </span>
                ))}
              </div>
            ) : (
              <p className={styles.emptyText}>无必需依赖</p>
            )}
            {skill.plugins.optional.length > 0 && (
              <div className={styles.pluginList}>
                <span className={styles.pluginLabel}>可选</span>
                {skill.plugins.optional.map((plugin) => (
                  <span key={plugin} className={`${styles.pluginBadge} ${styles.pluginOptional}`}>
                    <Icon name="puzzle" size={12} />
                    {plugin}
                  </span>
                ))}
              </div>
            )}
          </section>

          {Object.keys(optionalParams).length > 0 && (
            <section className={styles.detailSection}>
              <h3 className={styles.sectionTitle}>参数配置</h3>
              <div className={styles.paramForm}>
                {skill.parameters.required.length > 0 && (
                  <p className={styles.requiredNote}>
                    必需参数: {skill.parameters.required.join(', ')}
                  </p>
                )}
                {Object.entries(optionalParams).map(([name, spec]) => (
                  <ParameterField
                    key={name}
                    name={name}
                    spec={spec}
                    value={paramValues[name]}
                    onChange={handleParamChange}
                  />
                ))}
              </div>
            </section>
          )}

          {(primaryOutputs.length > 0 || secondaryOutputs.length > 0) && (
            <section className={styles.detailSection}>
              <h3 className={styles.sectionTitle}>输出产物</h3>
              {primaryOutputs.length > 0 && (
                <>
                  <h4 className={styles.outputGroupTitle}>主要输出</h4>
                  <ul className={styles.outputList}>
                    {primaryOutputs.map((output) => (
                      <li key={output.id} className={styles.outputItem}>
                        <Icon
                          name={output.type === 'plot' ? 'image' : output.type === 'table' ? 'table' : 'file'}
                          size={14}
                        />
                        <span className={styles.outputLabel}>{output.label}</span>
                        <span className={styles.outputDesc}>{output.description}</span>
                      </li>
                    ))}
                  </ul>
                </>
              )}
              {secondaryOutputs.length > 0 && (
                <>
                  <h4 className={styles.outputGroupTitle}>次要输出</h4>
                  <ul className={styles.outputList}>
                    {secondaryOutputs.map((output) => (
                      <li key={output.id} className={styles.outputItem}>
                        <Icon
                          name={output.type === 'plot' ? 'image' : output.type === 'table' ? 'table' : 'file'}
                          size={14}
                        />
                        <span className={styles.outputLabel}>{output.label}</span>
                        <span className={styles.outputDesc}>{output.description}</span>
                      </li>
                    ))}
                  </ul>
                </>
              )}
            </section>
          )}
        </div>

        <footer className={styles.modalFooter}>
          <button
            type="button"
            className={styles.cancelButton}
            onClick={onClose}
          >
            取消
          </button>
          <button
            type="button"
            className={styles.executeButton}
            onClick={handleExecute}
            disabled={!canExecute || isExecuting}
          >
            {isExecuting ? (
              <>
                <span className={styles.spinner} />
                执行中...
              </>
            ) : (
              <>
                <Icon name="play" size={14} />
                执行 Skill
              </>
            )}
          </button>
        </footer>
      </div>
    </div>
  );
}

/**
 * Skills 页面入口
 * 技能管理主页面，提供技能浏览、搜索、筛选和执行功能
 */

import React, { useCallback, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Icon } from '@/components/icons/Icon';
import { SkillCard } from './SkillCard';
import { SkillDetail } from './SkillDetail';
import { SkillSearch } from './SkillSearch';
import { useSkillStore, type Skill } from '@/hooks/useSkillStore';
import styles from './styles.module.css';

function computeStats(skills: Skill[]): {
  total: number;
  bySource: Record<string, number>;
} {
  const bySource: Record<string, number> = {
    'built-in': 0,
    'installed': 0,
    'marketplace': 0,
  };

  for (const skill of skills) {
    bySource[skill.source] = (bySource[skill.source] || 0) + 1;
  }

  return { total: skills.length, bySource };
}

export default function SkillsPage(): React.ReactElement {
  const {
    skills,
    filteredSkills,
    loading,
    error,
    searchQuery,
    setSearchQuery,
    sourceFilter,
    setSourceFilter,
    categoryFilter,
    setCategoryFilter,
    categories,
    executions,
    execute,
  } = useSkillStore({ autoLoad: true });

  const [selectedSkill, setSelectedSkill] = useState<Skill | null>(null);
  const [executingSkillId, setExecutingSkillId] = useState<string | null>(null);

  const stats = computeStats(skills);

  const navigate = useNavigate();
  const handleReturnHome = useCallback(() => {
    // Use history.back() to return to the previous page (e.g. project Copilot),
    // rather than navigating to "/" which may redirect to a recent result view.
    if (window.history.length > 1) {
      window.history.back();
    } else {
      navigate('/');
    }
  }, [navigate]);

  const handleViewDetail = useCallback((skill: Skill) => {
    setSelectedSkill(skill);
  }, []);

  const handleCloseDetail = useCallback(() => {
    setSelectedSkill(null);
  }, []);

  const handleExecute = useCallback(
    async (skill: Skill, params: Record<string, unknown>) => {
      console.log('[SkillsPage] Execute skill:', skill.id, 'with params:', params);
      setExecutingSkillId(skill.id);
      try {
        const result = await execute(skill.id, params);
        if (result.ok) {
          console.log('[SkillsPage] Skill execution started:', result.executionId);
          // Close modal after short delay to show success feedback
          setTimeout(() => {
            setExecutingSkillId(null);
            setSelectedSkill(null);
          }, 800);
        } else {
          console.error('[SkillsPage] Skill execution failed:', result.error);
          setExecutingSkillId(null);
        }
      } catch (err) {
        console.error('[SkillsPage] Execute error:', err);
        setExecutingSkillId(null);
      }
    },
    [execute]
  );

  if (loading) {
    return (
      <div className={styles.skillsPage}>
        <div className={styles.loadingState}>
          <div className={styles.loadingSpinner} />
          <span className={styles.loadingText}>加载 Skills...</span>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className={styles.skillsPage}>
        <div className={styles.loadingState}>
          <Icon name="alert-circle" size={24} />
          <span className={styles.loadingText}>{error}</span>
          <button
            type="button"
            className={styles.retryBtn}
            onClick={handleReturnHome}
            title="返回"
          >
            <Icon name="arrow-left" size={14} />
            <span>返回</span>
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className={styles.skillsPage}>
      <header className={styles.pageHeader}>
        <button
          type="button"
          className={styles.backBtn}
          onClick={handleReturnHome}
          title="返回"
          aria-label="返回"
        >
          <Icon name="arrow-left" size={16} />
          <span>返回</span>
        </button>
        <div className={styles.pageIcon}>
          <Icon name="command" size={22} />
        </div>
        <h1 className={styles.pageTitle}>Skills</h1>
        <div className={styles.pageStats}>
          <span className={styles.statsBadge}>
            <Icon name="layers" size={12} />
            {stats.total} Skills
          </span>
        </div>
      </header>

      <SkillSearch
        searchQuery={searchQuery}
        onSearchChange={setSearchQuery}
        selectedSource={sourceFilter ?? 'all'}
        onSourceChange={(src) => setSourceFilter(src === 'all' ? null : src)}
        selectedCategory={categoryFilter ?? ''}
        onCategoryChange={(cat) => setCategoryFilter(cat || null)}
        categories={categories}
        stats={stats}
      />

      <div className={styles.skillsGrid}>
        {filteredSkills.length === 0 ? (
          <div className={styles.skillsEmpty}>
            <div className={styles.emptyIcon}>
              <Icon name="search" size={24} />
            </div>
            <h3 className={styles.emptyTitle}>没有找到匹配的 Skills</h3>
            <p className={styles.emptyText}>尝试调整搜索条件或筛选器</p>
          </div>
        ) : (
          filteredSkills.map((skill) => (
            <SkillCard
              key={skill.id}
              skill={skill}
              onViewDetail={handleViewDetail}
              onExecute={(s) => handleViewDetail(s)}
              canExecute={executingSkillId === null}
            />
          ))
        )}
      </div>

      {selectedSkill && (
        <SkillDetail
          skill={selectedSkill}
          onClose={handleCloseDetail}
          onExecute={handleExecute}
          canExecute={executingSkillId === null}
          isExecuting={executingSkillId === selectedSkill.id}
        />
      )}
    </div>
  );
}

