// ============================================================
// TerminalWindowPage — BLOCK-59 P2 终端独立窗（/window/terminal/:sessionId）。
//
// 升格语义（plan §7 P2）：把某 Tab 会话升格为窗 = 同一 pty 会话的
// 第二活视图——主窗 tab 的 xterm 保活（session 归主窗 useTerminalTabs
// 所有，零状态丢失），本窗从挂载点起写入新输出；输入/resize 与主窗
// 并发安全（同一 pty）。数据到达依赖 terminal.js 的受管窗口转发
// （terminal:data / terminal:exit → terminal:<sessionId>）。
// 关闭本窗（收回/降格）永不停止 pty 会话。
// ============================================================
import React, { useEffect, useRef, useState } from 'react';
import { useParams } from 'react-router-dom';
import { Terminal as XTerm } from '@xterm/xterm';
import '@xterm/xterm/css/xterm.css';
import { FitAddon } from '@xterm/addon-fit';
import { WindowShell } from '@/components/window/WindowShell';
import { getBridge } from '@/lib/desktopBridge';
import { pickTerminalTheme } from '@/themes/terminal-themes';
import { useTheme } from '@/themes/ThemeProvider';
import styles from '@/components/window/window-shell.module.css';

export function TerminalWindowPage(): React.ReactElement {
  const params = useParams<{ sessionId?: string }>();
  const sessionId = params.sessionId || 'default';
  const { resolvedTheme } = useTheme();
  const [sessionRunning, setSessionRunning] = useState<boolean | null>(null);
  const [attachNote, setAttachNote] = useState('会话检查中…');
  const [actionError, setActionError] = useState('');
  const hostRef = useRef<HTMLDivElement | null>(null);
  const termRef = useRef<XTerm | null>(null);

  // 会话状态探测：运行中 → 直接挂载；未运行 → 提供启动（升格即用）。
  useEffect(() => {
    const bridge = getBridge('terminal');
    if (!bridge?.listSessions) {
      setAttachNote('桌面终端桥不可用（仅桌面版支持终端独立窗）。');
      setSessionRunning(false);
      return;
    }
    let cancelled = false;
    bridge
      .listSessions()
      .then((res) => {
        if (cancelled) return;
        const running = (res?.sessions || []).some(
          (s) => s.sessionId === sessionId && s.running,
        );
        setSessionRunning(running);
        setAttachNote(
          running
            ? '已挂载运行中的会话（新输出从此刻起显示；滚动回看在主窗标签）'
            : '会话未运行——可在此启动（关闭本窗不会停止会话）',
        );
      })
      .catch(() => {
        if (!cancelled) {
          setSessionRunning(false);
          setAttachNote('会话状态获取失败，可尝试启动。');
        }
      });
    return () => {
      cancelled = true;
    };
  }, [sessionId]);

  // xterm 挂载 + 事件订阅（仅本会话）；卸载只 dispose 本视图，不停 pty。
  useEffect(() => {
    if (sessionRunning !== true || !hostRef.current) return undefined;
    const bridge = getBridge('terminal');
    if (!bridge) return undefined;
    const term = new XTerm({
      cursorBlink: true,
      cursorStyle: 'bar',
      fontFamily: 'SFMono-Regular, Menlo, Monaco, Consolas, monospace',
      fontSize: 11,
      lineHeight: 1.4,
      scrollback: 5000,
      convertEol: true,
      allowProposedApi: false,
      theme: pickTerminalTheme(resolvedTheme),
    });
    const fit = new FitAddon();
    term.loadAddon(fit);
    term.open(hostRef.current);
    termRef.current = term;
    term.onData((data) => bridge.writeSession?.(data, sessionId));
    term.writeln(`\x1b[90m[终端独立窗 · 会话 ${sessionId}]\x1b[0m`);

    const observer = new ResizeObserver(() => {
      try {
        fit.fit();
        bridge.resizeSession?.(term.cols, term.rows, sessionId);
      } catch {
        /* ignore */
      }
    });
    observer.observe(hostRef.current);
    window.requestAnimationFrame(() => {
      try {
        fit.fit();
        bridge.resizeSession?.(term.cols, term.rows, sessionId);
        term.focus();
      } catch {
        /* ignore */
      }
    });

    const offData = bridge.onData?.((payload: { sessionId: string; data: string }) => {
      if (payload?.sessionId === sessionId) term.write(String(payload?.data || ''));
    });
    const offExit = bridge.onExit?.((payload: { sessionId: string; code?: number | null }) => {
      if (payload?.sessionId !== sessionId) return;
      setSessionRunning(false);
      term.writeln(
        `\r\n\x1b[90m[进程已退出${payload.code != null ? `，代码 ${payload.code}` : ''}]\x1b[0m`,
      );
    });
    return () => {
      offData?.();
      offExit?.();
      observer.disconnect();
      term.dispose();
      termRef.current = null;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [sessionRunning, sessionId]);

  const handleStart = async () => {
    setActionError('');
    const bridge = getBridge('terminal');
    const res = await bridge?.startSession?.(undefined, sessionId);
    if (res?.ok) {
      setSessionRunning(true);
    } else {
      setActionError(res?.error || '会话启动失败');
    }
  };

  return (
    <WindowShell title={`终端 · ${sessionId}`} badge="独立窗 · 会话视图" subtitle={attachNote}>
      <div style={{ height: 'calc(100vh - 40px)', padding: 8, boxSizing: 'border-box' }}>
        {sessionRunning === false && (
          <div className={styles.resultBody}>
            <span className={styles.statusChip}>{attachNote}</span>
            {actionError && <div className={styles.errorBlock}>{actionError}</div>}
            <div>
              <button type="button" className="petri-btn petri-btn--sm" onClick={() => void handleStart()}>
                启动会话
              </button>
            </div>
          </div>
        )}
        <div
          ref={hostRef}
          data-terminal-host={sessionId}
          style={{ width: '100%', height: '100%', visibility: sessionRunning ? 'visible' : 'hidden' }}
        />
      </div>
    </WindowShell>
  );
}

import React, { createContext, useCallback, useContext, useEffect, useMemo, useState } from 'react';
import { getPlatformApiPrefix, getToken } from '@/lib/authClient';

export type ThemePreference = 'system' | 'light' | 'dark';
export type ResolvedTheme = 'light' | 'dark';
// BLOCK-61：新 key 命名空间 petri-*；历史 key 读兼容（偏好零丢失），写入只落新 key。
const THEME_STORAGE_KEY = 'petri-theme';
const LEGACY_THEME_KEYS = ['petri-theme', 'theme'] as const;
const THEME_CHANGE_EVENT = 'petri:theme-change';

// BLOCK-49 加映三 — 界面字号：root 字号缩放系数（默认 1 = 14px 正文基准）。
// 注入 --petri-font-scale 到 html.style，全部字号 token 走 calc() 跟随缩放。
export const FONT_SCALE_STORAGE_KEY = 'petri-font-scale';
export const FONT_SCALE_MIN = 0.8;
export const FONT_SCALE_MAX = 1.4;
const FONT_CHANGE_EVENT = 'petri:font-scale-change';
import { applyAccent, readAccent, ACCENT_STORAGE_KEY, type AccentId } from './accents';
export { ACCENT_OPTIONS, type AccentId } from './accents';

function readFontScale(): number {
  try {
    const raw = Number(localStorage.getItem(FONT_SCALE_STORAGE_KEY));
    if (Number.isFinite(raw) && raw >= FONT_SCALE_MIN && raw <= FONT_SCALE_MAX) return raw;
  } catch {
    /* storage unavailable */
  }
  return 1;
}

function applyFontScale(scale: number): void {
  document.documentElement.style.setProperty('--petri-font-scale', String(scale));
}

interface ThemeContextValue {
  preference: ThemePreference;
  resolvedTheme: ResolvedTheme;
  setPreference: (preference: ThemePreference) => void;
  /** BLOCK-49 加映三 — 界面字号缩放系数（0.8–1.4，默认 1）。 */
  fontScale: number;
  setFontScale: (scale: number) => void;
  /** BLOCK-49 加映三 — 主题色（强调色维度，独立于明暗）。 */
  accent: AccentId;
  setAccent: (accent: AccentId) => void;
}

const ThemeContext = createContext<ThemeContextValue | null>(null);

function readPreference(): ThemePreference {
  try {
    const saved =
      localStorage.getItem(THEME_STORAGE_KEY) ||
      LEGACY_THEME_KEYS.map((key) => localStorage.getItem(key)).find((v) => v != null);
    if (saved === 'light' || saved === 'dark' || saved === 'system') {
      // BLOCK-61 读到即迁移：历史 key 偏好落新 key 并清除旧 key
      try {
        if (localStorage.getItem(THEME_STORAGE_KEY) == null) localStorage.setItem(THEME_STORAGE_KEY, saved);
        for (const key of LEGACY_THEME_KEYS) localStorage.removeItem(key);
      } catch {
        /* 迁移写失败不影响读取 */
      }
      return saved;
    }
  } catch {
    // Storage can be unavailable in hardened renderer contexts.
  }
  return 'system';
}

function systemTheme(): ResolvedTheme {
  return window.matchMedia?.('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
}

export function ThemeProvider({ children }: { children: React.ReactNode }): React.ReactElement {
  const [preference, setPreferenceState] = useState<ThemePreference>(readPreference);
  const [systemResolvedTheme, setSystemResolvedTheme] = useState<ResolvedTheme>(systemTheme);
  const resolvedTheme = preference === 'system' ? systemResolvedTheme : preference;
  const [fontScale, setFontScaleState] = useState<number>(readFontScale);
  const [accent, setAccentState] = useState<AccentId>(readAccent);

  // BLOCK-86 L1 — 多端偏好同步：服务端 /api/user/prefs 为权威源，
  // localStorage 仅作启动缓存。任何端修改，其余端（桌面/手机投影）
  // 经轮询 + 回前台拉取应用。
  const prefsApi = React.useCallback(() => `${getPlatformApiPrefix()}/user/prefs`, []);
  const prefsHeaders = React.useCallback((): Record<string, string> => {
    const headers: Record<string, string> = { 'Content-Type': 'application/json' };
    try {
      const token = getToken();
      if (token) headers.Authorization = `Bearer ${token}`;
    } catch { /* 非 authClient 场景忽略 */ }
    return headers;
  }, []);

  const applyRemotePrefs = useCallback((prefs: { theme?: string; fontScale?: number; accent?: string }) => {
    if (prefs.theme === 'light' || prefs.theme === 'dark' || prefs.theme === 'system') {
      setPreferenceState(prefs.theme);
      try { localStorage.setItem(THEME_STORAGE_KEY, prefs.theme); } catch { /* 保留内存 */ }
    }
    if (typeof prefs.fontScale === 'number') {
      const clamped = Math.min(FONT_SCALE_MAX, Math.max(FONT_SCALE_MIN, prefs.fontScale));
      setFontScaleState(clamped);
      try { localStorage.setItem(FONT_SCALE_STORAGE_KEY, String(clamped)); } catch { /* 保留内存 */ }
    }
    if (typeof prefs.accent === 'string' && prefs.accent) {
      setAccentState(prefs.accent as AccentId);
      try { localStorage.setItem(ACCENT_STORAGE_KEY, prefs.accent); } catch { /* 保留内存 */ }
    }
  }, []);

  const pushPrefs = useCallback((patch: Record<string, unknown>) => {
    try {
      void fetch(prefsApi(), { method: 'PUT', headers: prefsHeaders(), body: JSON.stringify(patch) }).catch(() => {});
    } catch { /* 同步失败不影响本端生效 */ }
  }, [prefsApi, prefsHeaders]);

  // 拉取服务端偏好：挂载时 + 每 15s + 回前台时（跨端应用）
  useEffect(() => {
    let last = '';
    const pull = async () => {
      try {
        const response = await fetch(prefsApi(), { headers: prefsHeaders() });
        const data = await response.json();
        if (data?.ok && data.prefs) {
          const signature = JSON.stringify(data.prefs);
          if (signature !== last) {
            last = signature;
            applyRemotePrefs(data.prefs);
          }
        }
      } catch { /* 服务端不可达时保持本地 */ }
    };
    void pull();
    const timer = window.setInterval(() => { void pull(); }, 15_000);
    const onVisible = () => { if (document.visibilityState === 'visible') void pull(); };
    document.addEventListener('visibilitychange', onVisible);
    return () => {
      window.clearInterval(timer);
      document.removeEventListener('visibilitychange', onVisible);
    };
  }, [applyRemotePrefs, prefsApi, prefsHeaders]);

  const setPreference = useCallback((next: ThemePreference) => {
    setPreferenceState(next);
    try {
      localStorage.setItem(THEME_STORAGE_KEY, next);
    } catch {
      // Keep the in-memory preference when persistence is unavailable.
    }
    pushPrefs({ theme: next });
  }, [pushPrefs]);

  const setAccent = useCallback((next: AccentId) => {
    setAccentState(next);
    try { localStorage.setItem(ACCENT_STORAGE_KEY, next); } catch { /* 保留内存 */ }
    pushPrefs({ accent: next });
  }, [pushPrefs]);

  const setFontScale = useCallback((scale: number) => {
    const clamped = Math.min(FONT_SCALE_MAX, Math.max(FONT_SCALE_MIN, scale));
    setFontScaleState(clamped);
    try {
      localStorage.setItem(FONT_SCALE_STORAGE_KEY, String(clamped));
    } catch {
      /* 保留内存偏好 */
    }
    pushPrefs({ fontScale: clamped });
  }, [pushPrefs]);

  useEffect(() => {
    const media = window.matchMedia?.('(prefers-color-scheme: dark)');
    if (!media) return;
    const update = () => setSystemResolvedTheme(media.matches ? 'dark' : 'light');
    update();
    media.addEventListener('change', update);
    return () => media.removeEventListener('change', update);
  }, []);

  useEffect(() => {
    const html = document.documentElement;
    html.setAttribute('data-theme', resolvedTheme);
    html.setAttribute('data-theme-preference', preference);
    html.style.colorScheme = resolvedTheme;
  }, [preference, resolvedTheme]);

  // BLOCK-49 加映三 — 字号缩放注入（root var；全部字号 token 走 calc 跟随）
  useEffect(() => {
    applyFontScale(fontScale);
  }, [fontScale]);

  // BLOCK-49 加映三 — 主题色注入（data-accent；teal 默认不设属性）
  useEffect(() => {
    applyAccent(accent);
  }, [accent]);

  useEffect(() => {
    const onThemeChange = (event: Event) => {
      const detail = (event as CustomEvent<{ preference?: ThemePreference }>).detail;
      const next = detail?.preference;
      if (next === 'light' || next === 'dark' || next === 'system') {
        setPreference(next);
      }
    };
    const onStorage = (event: StorageEvent) => {
      if (event.key && event.key !== FONT_SCALE_STORAGE_KEY) {
        if (!event.key || THEME_STORAGE_KEY === event.key || LEGACY_THEME_KEYS.includes(event.key as typeof LEGACY_THEME_KEYS[number])) {
          setPreferenceState(readPreference());
        }
        return;
      }
      // FONT_SCALE_STORAGE_KEY 变更：跨窗口同步字号
      const next = readFontScale();
      setFontScaleState(next);
    };
    const onFontChange = (event: Event) => {
      const detail = (event as CustomEvent<{ scale?: number }>).detail;
      if (detail && typeof detail.scale === 'number') setFontScaleState(detail.scale);
    };
    const onAccentStorage = (event: StorageEvent) => {
      if (!event.key || event.key !== ACCENT_STORAGE_KEY) return;
      setAccentState(readAccent());
    };
    window.addEventListener(THEME_CHANGE_EVENT, onThemeChange as EventListener);
    window.addEventListener(FONT_CHANGE_EVENT, onFontChange);
    window.addEventListener('storage', onStorage);
    window.addEventListener('storage', onAccentStorage);
    return () => {
      window.removeEventListener(THEME_CHANGE_EVENT, onThemeChange as EventListener);
      window.removeEventListener(FONT_CHANGE_EVENT, onFontChange);
      window.removeEventListener('storage', onStorage);
      window.removeEventListener('storage', onAccentStorage);
    };
  }, [setPreference]);

  const value = useMemo(
    () => ({ preference, resolvedTheme, setPreference, fontScale, setFontScale, accent, setAccent }),
    [preference, resolvedTheme, setPreference, fontScale, setFontScale, accent, setAccent],
  );

  return <ThemeContext.Provider value={value}>{children}</ThemeContext.Provider>;
}

export function useTheme(): ThemeContextValue {
  const value = useContext(ThemeContext);
  if (!value) throw new Error('useTheme must be used inside ThemeProvider');
  return value;
}

// ============================================================
// BLOCK-49 加映三 — 主题色（强调色）系统。
//
// 在 light/dark（明暗维度）之上增加独立的「主题色」维度：
// 用户选择强调色（teal 默认 / 蓝 / 紫 / 玫红 / 琥珀），ThemeProvider 将
// data-accent 注入 html；custom.css 里每档 [data-accent='…'] 覆盖
// accent token（light/dark 双套），其余 token 不动。
// ============================================================

export type AccentId = 'teal' | 'blue' | 'violet' | 'rose' | 'amber';

export interface AccentOption {
  id: AccentId;
  label: string;
  /** 面板色板圆点用的 hex（light 基准）。 */
  swatch: string;
}

export const ACCENT_OPTIONS: ReadonlyArray<AccentOption & { id: AccentId }> = [
  { id: 'teal', label: '青碧（默认）', swatch: '#0d9488' },
  { id: 'blue', label: '远蓝', swatch: '#2563eb' },
  { id: 'violet', label: '紫罗兰', swatch: '#7c3aed' },
  { id: 'rose', label: '玫红', swatch: '#e11d48' },
  { id: 'amber', label: '琥珀', swatch: '#d97706' },
];

export const ACCENT_STORAGE_KEY = 'petri-accent';
const ACCENT_CHANGE_EVENT = 'petri:accent-change';
const VALID_IDS = new Set(ACCENT_OPTIONS.map((o) => o.id as string));

export function readAccent(): AccentId {
  try {
    const saved = localStorage.getItem(ACCENT_STORAGE_KEY);
    if (saved && VALID_IDS.has(saved)) return saved as AccentId;
  } catch { /* storage unavailable */ }
  return 'teal';
}

export function applyAccent(accent: AccentId): void {
  const html = document.documentElement;
  if (accent === 'teal') html.removeAttribute('data-accent');
  else html.setAttribute('data-accent', accent);
}

export function accentLabel(id: AccentId): string {
  return ACCENT_OPTIONS.find((o) => o.id === id)?.label || id;
}

import { describe, expect, it } from 'vitest';
import {
  TERMINAL_THEMES,
  pickTerminalTheme,
  type TerminalThemeName,
} from '@/themes/terminal-themes';

describe('terminal-themes', () => {
  it('exposes light and dark palettes with symmetric keys', () => {
    const expectedKeys: Array<keyof (typeof TERMINAL_THEMES)['dark']> = [
      'background',
      'foreground',
      'cursor',
      'cursorAccent',
      'selectionBackground',
      'black',
      'red',
      'green',
      'yellow',
      'blue',
      'magenta',
      'cyan',
      'white',
      'brightBlack',
      'brightRed',
      'brightGreen',
      'brightYellow',
      'brightBlue',
      'brightMagenta',
      'brightCyan',
      'brightWhite',
    ];
    for (const key of expectedKeys) {
      expect(TERMINAL_THEMES.dark, `dark.${String(key)}`).toHaveProperty(key);
      expect(TERMINAL_THEMES.light, `light.${String(key)}`).toHaveProperty(key);
    }
  });

  it('uses distinct palettes for light vs dark', () => {
    expect(TERMINAL_THEMES.dark.background).not.toBe(TERMINAL_THEMES.light.background);
    expect(TERMINAL_THEMES.dark.foreground).not.toBe(TERMINAL_THEMES.light.foreground);
  });

  it('keeps the dark terminal on the Petri surface and accent palette', () => {
    expect(TERMINAL_THEMES.dark.background).toBe('#111a2e');
    expect(TERMINAL_THEMES.dark.foreground).toBe('#e6edf3');
    expect(TERMINAL_THEMES.dark.cursor).toBe('#2dd4bf');
    expect(TERMINAL_THEMES.dark.cyan).toBe('#2dd4bf');
  });

  describe('pickTerminalTheme', () => {
    const cases: Array<[unknown, TerminalThemeName]> = [
      ['light', 'light'],
      ['dark', 'dark'],
      [null, 'dark'],
      [undefined, 'dark'],
      ['', 'dark'],
      ['unknown', 'dark'],
    ];
    for (const [input, expected] of cases) {
      it(`returns ${expected} for ${JSON.stringify(input)}`, () => {
        expect(pickTerminalTheme(input as string | null | undefined)).toBe(
          TERMINAL_THEMES[expected],
        );
      });
    }
  });
});

/**
 * Embedded xterm theme registry + theme-resolution contract.
 *
 * Out-of-the-box light/dark palettes tuned for the Petri workspace shell.
 * Theme switching is driven by the application's resolved `light` / `dark`
 * value. Callers should pass that value explicitly so xterm and the React
 * shell update from the same source of truth.
 *
 * Consumers should:
 *   1. Call `pickTerminalTheme(resolvedTheme)` when constructing xterm.
 *   2. Re-invoke via `useTerminalTheme` (or their own MutationObserver) on
 *      `data-theme` mutations to reapply palette live.
 */
import { useEffect, useState } from 'react';
import type { ITheme } from '@xterm/xterm';

export type TerminalThemeName = 'light' | 'dark';

export const TERMINAL_THEMES: Readonly<Record<TerminalThemeName, ITheme>> = {
  dark: {
    background: '#111a2e',
    foreground: '#e6edf3',
    cursor: '#2dd4bf',
    cursorAccent: '#111a2e',
    selectionBackground: 'rgba(45, 212, 191, 0.24)',
    black: '#0b1220',
    red: '#f87171',
    green: '#4ade80',
    yellow: '#fbbf24',
    blue: '#60a5fa',
    magenta: '#c084fc',
    cyan: '#2dd4bf',
    white: '#b1bac4',
