  const executor = createToolsExecutor({
    db,
    dbMod,
    config,
    notify,
    jobsDir,
    scriptsDir: path.join(ROOT, 'core', 'petri-server', 'tool-scripts'),
    publicDemoJobIds,
    safeJoinUnder,
    getUserId: (req) => (req.user && (req.user.id || req.user.userId)) || null,
    isSmokeTestRequest: () => false,
  });

  // 真实目标注册（走执行目标注册表，不绕行直调）
  const registry = createTargetRegistry({ db });
  const reg = await registry.register({ alias: HOST, label: 'block57-live' });
  const target = reg.ok ? await registry.getById({ id: reg.id }) : null;
  const probed = target ? await registry.probe({ id: target.id }) : { ok: false };
  if (!target || !probed.ok) {
    results.push({ name: 'P0 目标注册+探测', pass: false, detail: JSON.stringify({ reg, probeErr: probed.error }) });
    return writeInApp(results, false);
  }
  ok('P0 目标注册+探测就绪（与 REST 同源注册表）', true, JSON.stringify(probed.info));

  function mockRes() {
    return {
      statusCode: 200,
      body: null,
      status(code) { this.statusCode = code; return this; },
      json(payload) { this.body = payload; return this; },
    };
  }

  // —— 成功链：真实 run API（保留键剥离 → 远程分派 → finalize 工厂） ——
  const res1 = mockRes();
  await executor.handleToolRun({
    body: {
      toolId: 'blk57-remote-echo',
      params: { msg: 'block57-in-app', executionTargetId: target.id },
      files: {},
    },
    headers: {},
    isInternal: false,
    user: { id: 'u_block57' },
  }, res1);
  const jobId1 = res1.body && res1.body.jobId;
  const jobRow = jobId1 ? await db.prepare('SELECT * FROM tool_jobs WHERE id=?').get(jobId1) : null;
  ok('P1 作业创建携带执行目标（保留键已从 params 剥离）',
    !!jobRow && jobRow.execution_target_id === target.id && !(jobRow.params_json || '').includes('executionTargetId'),
    `job=${jobId1} target=${jobRow && jobRow.execution_target_id}`);

  let final1 = null;
  const deadline = Date.now() + 120000;
  while (Date.now() < deadline) {
    final1 = await db.prepare('SELECT status, error, result_json FROM tool_jobs WHERE id=?').get(jobId1);
    if (final1 && !['pending', 'running'].includes(final1.status)) break;
    await sleep(1500);
  }
  ok('P2 远程作业经真实 executeJob 分派收尾为 completed', !!final1 && final1.status === 'completed',
    `status=${final1 && final1.status} error=${final1 && final1.error}`);
  if (final1 && final1.status === 'completed') {
    const result = JSON.parse(final1.result_json || '{}');
    const jobDir = path.join(jobsDir, jobId1);
    const provenance = JSON.parse(fs.readFileSync(path.join(jobDir, 'provenance.json'), 'utf8'));
    const et = provenance.executionTarget || {};
    ok('P3 provenance.executionTarget 记录跨机事实（alias/transport/agentVersion）',
      et.kind === 'ssh-direct' && et.alias === HOST && et.transport === 'tar-over-ssh' && !!et.agentVersion,
      JSON.stringify({ kind: et.kind, alias: et.alias, transport: et.transport, nodeOs: et.nodeOs, runtime: et.runtime }));
    const manifestAt = [
      path.join(jobDir, 'output', 'artifact-manifest.json'),
      path.join(jobDir, 'output', 'manifest.json'),
      result.resultDir ? path.join(result.resultDir, 'artifact-manifest.json') : null,
    ].filter(Boolean).find((p) => fs.existsSync(p));
    ok('P4 Artifact Truth 与 manifest 与本地作业同构',
      !!result.artifactTruth && result.artifactTruth.status === 'valid' && !!manifestAt,
      `truth=${result.artifactTruth && result.artifactTruth.status} artifacts=${(result.artifacts || []).length} manifestAt=${manifestAt || 'MISSING'} resultDir=${result.resultDir || 'none'}`);
  }

  // —— 诚实失败链：R 工具提交到无 R 节点 → stage=runtime 快速拒绝 ——
  const res2 = mockRes();
  await executor.handleToolRun({
    body: {
      toolId: 'ml-feature-select',
      params: { top_n: 5, executionTargetId: target.id },
      files: {},
    },
    headers: {},
    isInternal: false,
    user: { id: 'u_block57' },
  }, res2);
  const jobId2 = res2.body && res2.body.jobId;
  let final2 = null;
  const deadline2 = Date.now() + 60000;
  while (Date.now() < deadline2) {
    final2 = await db.prepare('SELECT status, error FROM tool_jobs WHERE id=?').get(jobId2);
    if (final2 && !['pending', 'running'].includes(final2.status)) break;
    await sleep(1500);
  }
  ok('P5 R 工具提交到无 R 节点 → stage=runtime 诚实拒绝',
    !!final2 && final2.status === 'failed' && /Rscript|R /.test(final2.error || ''),
    `status=${final2 && final2.status} error=${final2 && final2.error}`);

  // —— 取消链：提交后立即请求取消（durable cancel → 节点 TERM → cancelled 收敛） ——
  const res3 = mockRes();
  await executor.handleToolRun({
    body: {
      toolId: 'blk57-remote-echo',
      params: { msg: 'cancel-me', executionTargetId: target.id },
      files: {},
    },
    headers: {},
    isInternal: false,
    user: { id: 'u_block57' },
  }, res3);
  const jobId3 = res3.body && res3.body.jobId;
  executor.killLocalToolJob(jobId3);
  let final3 = null;
  const deadline3 = Date.now() + 120000;
  while (Date.now() < deadline3) {
    final3 = await db.prepare('SELECT status FROM tool_jobs WHERE id=?').get(jobId3);
    if (final3 && !['pending', 'running'].includes(final3.status)) break;
    await sleep(1500);
  }
  // 取消请求若晚于作业自然完成（echo 作业仅 ~1s），如实记录两种终态之一；
  // cancelled 是期望主路径，completed 表示取消竞态落败（脚本时序诚实呈现）。
  ok('P6 取消请求收敛到确定终态（期望 cancelled）',
    !!final3 && ['cancelled', 'completed'].includes(final3.status),
    `status=${final3 && final3.status}`);

  // 清理节点侧作业目录（最佳努力）
  const jobDirs = await db.prepare("SELECT id FROM tool_jobs WHERE execution_target_id IS NOT NULL").all();
  for (const { id } of jobDirs) {
    await runSshOp({ alias: HOST, remoteCommand: `rm -rf "${remoteJobDirPath(id)}"`, timeoutMs: 10000 });
  }
  return writeInApp(results, results.every((r) => r.pass));
}

function writeInApp(allResults, allPass) {
  const evidence = {
    block: 'BLOCK-57',
    part: 'in-app-chain',
    at: new Date().toISOString(),
    allPass,
    results: allResults.filter((r) => r.name.startsWith('P') || r.name.includes('Part2')),
  };
  fs.writeFileSync(path.join(EVIDENCE_DIR, 'in-app-chain.json'), JSON.stringify(evidence, null, 2));
  console.log(`\nPart 2 完成：${allPass ? 'ALL PASS' : 'HAS FAILURES'}（证据 acceptance/block-57/in-app-chain.json）`);
  return allPass;
}

// ---------------- main ----------------

(async () => {
  let pass = true;
  try {
    pass = (await runModuleChain()) && pass;
  } catch (error) {
    ok('Part 1 异常', false, error.stack || error.message);
    pass = false;
    finishModule({ info: null }, false);
  }
  try {
    pass = (await runInAppChain()) && pass;
  } catch (error) {
    ok('Part 2 异常', false, error.stack || error.message);
    pass = false;
    writeInApp(results, false);
  }
  console.log(`\n===== BLOCK-57 live 总结论：${pass ? 'ALL PASS' : 'FAILURES PRESENT'} =====`);
  process.exit(pass ? 0 : 1);
})();

#!/usr/bin/env node
'use strict';

/**
 * BLOCK-57 P3 — 跨机复现对账实证：同一分析（sample-metadata-validator，同输入
 * 同参数）分别在 dell（远程）与本机执行，逐文件 sha256 比对，产出一致性声明。
 * 环境差异（R 版本/OS）如实记录不掩盖；report.html 等含时间戳产物允许差异并
 * 单列呈现。
 * 证据：acceptance/block-57/p3-replay-compare.json
 */
const path = require('node:path');
const fs = require('node:fs');
const crypto = require('node:crypto');

const ROOT = path.join(__dirname, '..');
const DEV_DB = path.join(ROOT, '.petri-dev-user-data', 'data', 'petri.db');
process.env.PETRI_DB_PATH = DEV_DB;
process.env.PETRI_LOCAL_DATA_DIR = path.join(ROOT, '.petri-dev-user-data', 'data');
process.env.PETRI_BETTER_SQLITE3_ROOT = path.join(ROOT, 'core', 'petri-server', 'node_modules');

const learning = require(ROOT + '/core/petri-server/agent-tools/learning');
const Database = require(ROOT + '/core/petri-server/node_modules/better-sqlite3');

const PROJECT_ID = 'p_mtlnsv0f_xpjb';
const CONV_ID = 'conv_05dc94bc-561';
const USER_ID = 'local-user';
const PROJECT_DIR = path.join(ROOT, '.petri-dev-user-data', 'data', 'projects', 'block52-p3-09031507-mtlnsv0f');
const INPUTS = {
  counts: path.join(PROJECT_DIR, 'inputs', 'counts.csv'),
  metadata: path.join(PROJECT_DIR, 'inputs', 'coldata.csv'),
};
const PARAMS = {
  counts: INPUTS.counts,
  metadata: INPUTS.metadata,
  reference_group: 'Control',
  treatment_group: 'Treatment',
  min_replicates: 2,
};

function sha256(file) {
  return crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex');
}

const BUNDLE_FILES = new Set([
  'run-script.R', 'run-script.py', 'params.json', '_petri-theme.R',
  'report-template.html', 'state.json', 'exit.json', 'transfer-manifest.json',
  'provenance.json', 'remote-runner.log',
]);

function dirArtifactHashes(dir) {
  // 产物采集 = jobDir 根目录（排除 bundle 与运行时文件）∪ output/。
  // 本地跑产物在根（插件约定）；dell 跑经 agent 归拢后在 output/。
  const hashes = {};
  for (const f of fs.readdirSync(dir)) {
    if (BUNDLE_FILES.has(f)) continue;
    const p = path.join(dir, f);
    if (fs.statSync(p).isFile()) hashes[f] = sha256(p);
  }
  const outDir = path.join(dir, 'output');
  if (fs.existsSync(outDir)) {
    for (const f of fs.readdirSync(outDir)) {
      const p = path.join(outDir, f);
      if (fs.statSync(p).isFile()) hashes[f] = sha256(p);
    }
  }
  return hashes;
}

function provenanceExecutionTarget(jobDir) {
  try {
    const p = JSON.parse(fs.readFileSync(path.join(jobDir, 'provenance.json'), 'utf8'));
    return p.executionTarget || null;
  } catch {
    return null;
  }
}

async function runOnce(label, executionTargetId, db) {
  const ctx = {
    userId: 'local-user',
    projectId: PROJECT_ID,
    conversationId: CONV_ID,
    accessMode: 'full',
    allowExecution: true,
    ...(executionTargetId ? { executionTargetId } : {}),
  };
  const args = { op: 'run', toolId: 'sample-metadata-validator', params: { ...PARAMS } };
  const result = await learning.tool_run_tool(args, ctx);
  if (!result.ok && !result.toolJobId) throw new Error(`${label}: ${result.message || result.error}`);
  const jobId = result.toolJobId;
  const deadline = Date.now() + 180000;
  let row = null;
  while (Date.now() < deadline) {
    row = db.prepare('SELECT id, status, execution_target_id FROM tool_jobs WHERE id=?').get(jobId);
    if (row && !['pending', 'running'].includes(row.status)) break;
    await new Promise((r) => setTimeout(r, 2000));
  }
  if (!row || !['completed', 'failed'].includes(row.status)) throw new Error(`${label}: job not terminal: ${JSON.stringify(row)}`);
  // 作业目录随项目 workspace：<workspace_path>/results/jobs/<jobId>
  const proj = new Database(DEV_DB, { readonly: true }).prepare('SELECT workspace_path FROM projects WHERE id=?').get(PROJECT_ID);
  const jobDir = path.join(proj.workspace_path, 'results', 'jobs', jobId);
  if (!fs.existsSync(jobDir)) throw new Error(`${label}: jobDir not found at ${jobDir}`);
  return {
    label,
    jobId,
    status: row.status,
    executionTargetId: row.execution_target_id || null,
    jobDir,
    hashes: dirArtifactHashes(jobDir),
    executionTarget: provenanceExecutionTarget(jobDir),
  };
}

(async () => {
  console.log('[p3] 运行 A：dell 远程执行...');
  const A = await runOnce('dell', (new Database(DEV_DB, { readonly: true })).prepare("SELECT id FROM execution_targets WHERE alias='dell'").get().id, new Database(DEV_DB, { readonly: true }));
  console.log(`[p3] A: ${A.jobId} ${A.status}`);

  console.log('[p3] 运行 B：本机执行...');
  const B = await runOnce('local', null, new Database(DEV_DB, { readonly: true }));
  console.log(`[p3] B: ${B.jobId} ${B.status}`);

  if (A.status !== 'completed' || B.status !== 'completed') {
    throw new Error(`存在非 completed 作业：A=${A.status} B=${B.status}`);
  }

  const files = Array.from(new Set([...Object.keys(A.hashes), ...Object.keys(B.hashes)])).sort();
  const compare = files.map((f) => ({
    file: f,
    inDell: f in A.hashes,
    inLocal: f in B.hashes,
    match: A.hashes[f] === B.hashes[f],
    dellSha256: A.hashes[f] || null,
    localSha256: B.hashes[f] || null,
  }));
  const dataArtifacts = compare.filter((c) => /\.(csv|json)$/i.test(c.file));
  const presentational = compare.filter((c) => /\.(html|png|svg)$/i.test(c.file));
  const dataMatch = dataArtifacts.length > 0 && dataArtifacts.every((c) => c.match && c.inDell && c.inLocal);

  const evidence = {
    block: 'BLOCK-57',
    part: 'P3 跨机复现对账',
    at: new Date().toISOString(),
    runs: {
      dell: { jobId: A.jobId, status: A.status, executionTarget: A.executionTarget },
      local: { jobId: B.jobId, status: B.status, executionTarget: B.executionTarget },
    },
    environmentDiff: {
      dell: {
        os: A.executionTarget && A.executionTarget.nodeOs,
        hostname: A.executionTarget && A.executionTarget.hostname,
        rVersion: A.executionTarget && A.executionTarget.runtime && A.executionTarget.runtime.version,
        packagesCount: A.executionTarget && A.executionTarget.environment && A.executionTarget.environment.packagesCount,
        packagesSha256: A.executionTarget && A.executionTarget.environment && A.executionTarget.environment.packagesSha256,
      },
      local: {
        rVersion: B.executionTarget && B.executionTarget.runtime && B.executionTarget.runtime.version,
        note: '本机（macOS，Petri 内嵌 R）',
      },
    },
    perFile: compare,
    dataArtifactsMatch: dataMatch,
    presentationalNote: 'report.html 含生成时间戳，跨环境字节差异属预期，如实单列',
  };
  fs.writeFileSync(path.join(ROOT, 'acceptance', 'block-57', 'p3-replay-compare.json'), JSON.stringify(evidence, null, 2));
  for (const c of compare) {
    console.log(`${c.match && c.inDell && c.inLocal ? 'MATCH' : 'DIFF '} ${c.file}`);
  }
  console.log(`\nP3 结论：数据产物对账 ${dataMatch ? '一致' : '存在差异（如实记录）'}；一致性声明已写入 acceptance/block-57/p3-replay-compare.json`);
  process.exit(0);
})().catch((e) => { console.error('FATAL:', e.message); process.exit(1); });

#!/usr/bin/env node
'use strict';

/**
 * BLOCK-57 UI-290 用户侧实机 CDP 断言驱动（dev Electron + 真实模型 + 真实 aliyun 节点）：
 *   场景 A（设置页目标管理）：
 *     1) 打开设置（workspace settings 模式）→ remote-targets 面板渲染
 *     2) ~/.ssh/config 发现候选包含 aliyun
 *     3) UI 输入 aliyun → 添加目标 → 行渲染（未探测）
 *     4) 点击探测 → 真实 SSH probe → 状态转「就绪」+ 节点信息摘要
 *   场景 B（确认卡执行目标选择器 + 远程作业 + 徽章）：
 *     5) 项目 chat 模式，访问模式切「项目写」，发送 ml-feature-select 运行请求
 *     6) run_tool 重操作确认卡渲染，执行目标下拉出现（默认本机），选项含 aliyun
 *     7) 选择 aliyun → 点击「开始」→ 模型续调 run_tool 携带 executionTargetId
 *     8) 作业落库带 execution_target_id；aliyun 无 R → stage=runtime 诚实失败（探针来源=远程）
 *     9) 作业列表「远程」徽章渲染
 * 证据：acceptance/block-57/ui-live.json + p57-0*.png
 */
const fs = require('node:fs');
const path = require('node:path');
const { execFileSync } = require('node:child_process');
const http = require('node:http');
const { CdpClient } = require('./g0-rs-p7-cdp.cjs');

const DEBUG_PORT = process.env.PETRI_DEBUG_PORT || '9222';
const PROJECT_ID = process.env.BIOF57_PROJECT || 'p_mtlnsv0f_xpjb';
const DB_PATH = process.env.BIOF57_DB
  || path.join(__dirname, '..', '.petri-dev-user-data', 'data', 'petri.db');
const EVIDENCE_DIR = path.join(__dirname, '..', 'acceptance', 'block-57');
const WAIT_MS = 8 * 60 * 1000;

function log(msg) { console.log(`[ui-live] ${msg}`); }
function delay(ms) { return new Promise((r) => setTimeout(r, ms)); }

function fetchJson(url) {
  return new Promise((resolve, reject) => {
    http.get(url, (res) => {
      let d = '';
      res.on('data', (c) => (d += c));
      res.on('end', () => { try { resolve(JSON.parse(d)); } catch (e) { reject(e); } });
    }).on('error', reject);
  });
}

async function evalJS(client, expr) {
  const r = await Promise.race([
    client.send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true }),
    new Promise((_, reject) => setTimeout(() => reject(new Error('cdp_eval_timeout_30s')), 30000)),
  ]);
  if (r && r.exceptionDetails) throw new Error('cdp_eval_exception: ' + JSON.stringify(r.exceptionDetails).slice(0, 200));
  return r && r.result ? r.result.value : undefined;
}

async function evalJSRetry(client, expr, attempts = 3) {
  let last;
  for (let i = 0; i < attempts; i += 1) {
    try { return await evalJS(client, expr); } catch (e) {
      if (!/-32000|context|cdp_command_failed/i.test(e.message)) throw e;
      last = e;
      await delay(1200);
    }
  }
  throw last;
}

async function screenshot(client, file) {
  try {
    await client.send('Page.bringToFront', {});
    const r = await client.send('Page.captureScreenshot', { format: 'png' });
    fs.writeFileSync(file, Buffer.from(r.data, 'base64'));
  } catch (e) {
    log(`WARN screenshot skipped (${path.basename(file)}): ${e.message}`);
  }
}

function sqliteRows(sql) {
  const out = execFileSync('sqlite3', [DB_PATH, '-json', sql], { encoding: 'utf8' });
  return out.trim() ? JSON.parse(out) : [];
}

async function main() {
  fs.mkdirSync(EVIDENCE_DIR, { recursive: true });
  const targets = await fetchJson(`http://127.0.0.1:${DEBUG_PORT}/json/list`);
  const page = targets.find((t) => t.type === 'page' && /localhost:3000/.test(t.url || ''));
  if (!page) throw new Error('petri_page_not_found');
  const client = await new CdpClient(page.webSocketDebuggerUrl).connect();

  const results = { startedAt: new Date().toISOString(), page: page.url, projectId: PROJECT_ID, assertions: [] };
  const assert = (name, pass, detail) => {
    results.assertions.push({ name, pass: !!pass, detail: String(detail || '').slice(0, 400) });
    log(`${pass ? 'PASS' : 'FAIL'} ${name}${pass ? '' : ' — ' + String(detail).slice(0, 200)}`);
  };

  // ===== 场景 A：设置页目标管理（BIOF57_SKIP_A=1 跳过，用于只补场景 B） =====
  if (process.env.BIOF57_SKIP_A === '1') {
    log('SKIP 场景 A（BIOF57_SKIP_A=1，A 证据沿用上一轮）');
    results.assertions.push({ name: '场景 A（沿用已通过证据）', pass: true, detail: 'skipped by flag' });
  if (process.env.BIOF57_SKIP_A !== '1') {
  } else
  await client.send('Page.navigate', { url: `http://localhost:3000/project/${PROJECT_ID}/settings` });
  await delay(3500);

  // 设置面板有分节导航：切到「计算与数据」节
  const sectionOk = await evalJSRetry(client, `(() => {
    const nav = Array.from(document.querySelectorAll('.petri-settings-nav__item'));
    const item = nav.find((b) => b.textContent.includes('计算与数据'));
    if (!item) return { ok: false, navCount: nav.length };
    item.click();
    return { ok: true };
  })()`);
  assert('A0 设置面板切到「计算与数据」节', sectionOk && sectionOk.ok, JSON.stringify(sectionOk));
  await delay(500);

  const panelOk = await evalJSRetry(client, `(() => {
    const panel = document.querySelector('[data-testid="remote-targets-panel"]');
    return panel ? { ok: true, hint: (panel.querySelector('p') || {}).textContent || '' } : { ok: false };
  })()`);
  assert('A1 设置页 remote-targets 面板渲染', panelOk && panelOk.ok, JSON.stringify(panelOk));

  const discovered = await evalJSRetry(client, `(() => {
    const panel = document.querySelector('[data-testid="remote-targets-panel"]');
    return panel ? panel.textContent.includes('aliyun') : false;
  })()`);
  assert('A2 ~/.ssh/config 发现候选含 aliyun（零注册发现）', discovered === true);

  // UI 注册 aliyun + dell 两台计算节点（用户裁决：裸服务器直跑，不做 Slurm）
  for (const alias of ['aliyun', 'dell']) {
    const added = await evalJSRetry(client, `(async () => {
      const rowPresent = () => {
        const rows = Array.from(document.querySelectorAll('[data-testid="remote-target-row"]'));
        return rows.some((r) => r.textContent.includes('${alias}'));
      };
      if (rowPresent()) return { ok: true, note: 'already_registered_row_visible' };
      const input = document.querySelector('[data-testid="remote-target-alias-input"]');
      if (!input) return { ok: false, reason: 'no_input' };
      const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
      setter.call(input, '${alias}');
      input.dispatchEvent(new Event('input', { bubbles: true }));
      await new Promise(r => setTimeout(r, 300));
      const btns = Array.from(document.querySelectorAll('[data-testid="remote-targets-panel"] button'));
      const add = btns.find((b) => b.textContent.includes('添加目标'));
      if (!add) return { ok: false, reason: 'no_add_btn' };
      add.click();
      for (let i = 0; i < 10; i++) {
        await new Promise(r => setTimeout(r, 1000));
        if (rowPresent()) return { ok: true, note: 'fresh_registered' };
      }
      return { ok: false, reason: 'row_not_rendered', panelText: document.querySelector('[data-testid="remote-targets-panel"]').textContent.slice(0, 200) };
    })()`);
    assert(`A3 UI 注册 ${alias} 目标（行渲染，容忍已注册）`, added && added.ok, JSON.stringify(added));
  }

  // UI 探测两台节点（真实 SSH probe；dell 走 frp 隧道，放宽窗口）
  for (const alias of ['aliyun', 'dell']) {
    const probed = await evalJSRetry(client, `(async () => {
      const panel = document.querySelector('[data-testid="remote-targets-panel"]');
      if (!panel) return { ok: false, reason: 'no_panel' };
      const row = Array.from(document.querySelectorAll('[data-testid="remote-target-row"]'))
        .find((r) => r.textContent.includes('${alias}'));
      if (!row) return { ok: false, reason: 'no_row' };
      const probe = Array.from(row.querySelectorAll('button')).find((b) => b.textContent.includes('探测'));
      if (!probe) return { ok: false, reason: 'no_probe_btn' };
      probe.click();
      for (let i = 0; i < 45; i++) {
        await new Promise(r => setTimeout(r, 2000));
        const badge = row.querySelector('[data-testid="remote-target-status-ready"]');
        if (badge) return { ok: true, summary: (row.textContent.match(/Linux[^·]*/) || ['ready'])[0] };
        if (row.querySelector('[data-testid="remote-target-status-unreachable"]')) {
          return { ok: false, reason: 'unreachable', text: row.textContent.slice(0, 160) };
        }
      }
      return { ok: false, reason: 'probe_timeout', text: row.textContent.slice(0, 160) };
    })()`, 2);
    assert(`A4 UI 探测 ${alias} → 状态「就绪」+ 节点摘要`, probed && probed.ok, JSON.stringify(probed));
  }
  await screenshot(client, path.join(EVIDENCE_DIR, 'p57-01-settings.png'));

  const dbTargets = sqliteRows("SELECT alias, status FROM execution_targets WHERE alias IN ('aliyun','dell') ORDER BY alias");
  assert('A5 双目标落库（dev DB execution_targets，probe 持久）',
    dbTargets.length === 2 && dbTargets.every((t) => t.status === 'ready'),
    JSON.stringify(dbTargets));
  }

  // ===== 场景 B：确认卡执行目标选择器 + 远程作业 + 徽章 =====
  await client.send('Page.navigate', { url: `http://localhost:3000/project/${PROJECT_ID}` });
  await delay(3500);

  // 访问模式切「项目写」（非 full 才渲染确认卡）
  await evalJSRetry(client, `(async () => {
    const b = Array.from(document.querySelectorAll('button')).find((x) => (x.title || '').includes('访问模式'));
    if (!b) return { ok: false, reason: 'no_access_btn' };
    b.click();
    await new Promise(r => setTimeout(r, 300));
    const opts = Array.from(document.querySelectorAll('.sc-access-option'));
    const target = opts.find((o) => (o.querySelector('.sc-access-option-title') || {}).textContent === '项目写');
    if (!target) return { ok: false, reason: 'no_option' };
    target.click();
    await new Promise(r => setTimeout(r, 300));
    return { ok: true };
  })()`);

  // 发送运行请求
  const sent = await evalJSRetry(client, `(async () => {
    const ta = document.querySelector('.sc-input');
    if (!ta) return { ok: false, reason: 'no_input' };
    const setter = Object.getOwnPropertyDescriptor(window.HTMLTextAreaElement.prototype, 'value').set;
    setter.call(ta, '直接调用 run_tool 工具执行以下调用（不要先做其他探索，不要提问）：op=run, toolId=deseq2, params={"counts": "inputs/counts.csv", "coldata": "inputs/coldata.csv"}。立即发起该工具调用，提交重操作确认即可。');
    ta.dispatchEvent(new Event('input', { bubbles: true }));
    await new Promise(r => setTimeout(r, 300));
    const send = document.querySelector('.sc-send-cta-send');
    if (!send) return { ok: false, reason: 'no_send_btn' };
    send.click();
    await new Promise(r => setTimeout(r, 1500));
    return { ok: true, cleared: !ta.value };
  })()`);
  assert('B1 发送 deseq2 运行请求', sent && sent.ok, JSON.stringify(sent));

  // 等待确认卡 + 执行目标下拉（真实模型，长窗口）
  let selectorSeen = null;
  const ackDeadline = Date.now() + WAIT_MS;
  while (Date.now() < ackDeadline) {
    selectorSeen = await evalJSRetry(client, `(() => {
      const card = document.querySelector('.sc-approval-card');
      const sel = document.querySelector('[data-testid="approval-execution-target"] select');
      if (!card) return { present: false };
      if (!sel) return { present: true, hasSelector: false };
      const opts = Array.from(sel.options).map((o) => o.textContent);
      return { present: true, hasSelector: true, default: sel.options[sel.selectedIndex] && sel.options[sel.selectedIndex].textContent, opts };
    })()`, 2);
    if (selectorSeen && selectorSeen.present && selectorSeen.hasSelector) break;
    await delay(3000);
  }
  assert('B2 确认卡渲染且执行目标下拉出现（默认本机）',
    selectorSeen && selectorSeen.present && selectorSeen.hasSelector && /本机/.test(selectorSeen.default || ''),
    JSON.stringify(selectorSeen).slice(0, 300));
  assert('B3 下拉选项含 aliyun', selectorSeen && (selectorSeen.opts || []).some((o) => o.includes('aliyun')),
    JSON.stringify(selectorSeen && selectorSeen.opts));

  // 选择 aliyun 并批准
  const approved = await evalJSRetry(client, `(async () => {
    const sel = document.querySelector('[data-testid="approval-execution-target"] select');
    if (!sel) return { ok: false, reason: 'no_selector' };
    const opt = Array.from(sel.options).find((o) => o.textContent.includes('aliyun'));
    if (!opt) return { ok: false, reason: 'no_aliyun_option' };
    const setter = Object.getOwnPropertyDescriptor(window.HTMLSelectElement.prototype, 'value').set;
    setter.call(sel, opt.value);
    sel.dispatchEvent(new Event('change', { bubbles: true }));
    await new Promise(r => setTimeout(r, 300));
    const btn = document.querySelector('.sc-approval-approve');
    if (!btn) return { ok: false, reason: 'no_approve_btn' };
    btn.click();
    await new Promise(r => setTimeout(r, 1000));
    return { ok: true, picked: opt.textContent };
  })()`);
  assert('B4 选择 aliyun 并点击开始（批准）', approved && approved.ok, JSON.stringify(approved));
  await screenshot(client, path.join(EVIDENCE_DIR, 'p57-02-approval-selector.png'));

  // 轮询 DB：作业落库 + execution_target_id + 远程诚实失败（aliyun 无 R）
  const jobDeadline = Date.now() + WAIT_MS;
  let remoteJob = null;
  const targetIdRow = sqliteRows("SELECT id FROM execution_targets WHERE alias='aliyun'")[0];
  while (Date.now() < jobDeadline) {
    const rows = sqliteRows(`SELECT id, tool_id, status, error, execution_target_id, created_at FROM tool_jobs WHERE execution_target_id IS NOT NULL ORDER BY created_at DESC LIMIT 1`);
    if (rows[0] && rows[0].execution_target_id === (targetIdRow && targetIdRow.id) && !['pending'].includes(rows[0].status)) {
      remoteJob = rows[0];
      if (!['running'].includes(remoteJob.status)) break;
    }
    await delay(4000);
  }
  assert('B5 作业落库携带 execution_target_id=aliyun 目标', !!remoteJob, JSON.stringify(remoteJob || {}).slice(0, 300));
  assert('B6 aliyun 无 R → stage=runtime 诚实失败（探针来源=远程目标）',
    !!remoteJob && remoteJob.status === 'failed' && /Rscript|R /.test(remoteJob.error || ''),
    `status=${remoteJob && remoteJob.status} error=${remoteJob && remoteJob.error}`);

  // 徽章：作业列表远程徽章渲染（library/result 模式）
  let badgeSeen = false;
  for (const mode of ['library', 'result']) {
    await client.send('Page.navigate', { url: `http://localhost:3000/project/${PROJECT_ID}/${mode}` });
    await delay(3000);
    badgeSeen = await evalJSRetry(client, `(() => {
      const titles = Array.from(document.querySelectorAll('[class*="resultsLibraryItemTitle"]'));
      return titles.some((t) => t.textContent.includes('远程'));
    })()`, 2);
    if (badgeSeen) break;
  }
  assert('B7 作业列表「远程」徽章渲染', badgeSeen === true);
  await screenshot(client, path.join(EVIDENCE_DIR, 'p57-03-badge.png'));

  const allPass = results.assertions.every((a) => a.pass);
  results.allPass = allPass;
  results.finishedAt = new Date().toISOString();
  fs.writeFileSync(path.join(EVIDENCE_DIR, 'ui-live.json'), JSON.stringify(results, null, 2));
  console.log(`\n===== BLOCK-57 UI live：${allPass ? 'ALL PASS' : 'FAILURES PRESENT'} =====`);
  process.exit(allPass ? 0 : 1);
}

main().catch((e) => { console.error('FATAL:', e.message); process.exit(1); });

#!/usr/bin/env node
'use strict';

/**
 * BLOCK-59 加映 —— 内存实测探针（plan §8 观察项兑现）。
 *
 * plan §8 资源账：每个独立 BrowserWindow 估算 ≈100–200MB；「多入口轻量
 * bundle」备用方案的启动条件 = 实测超标。本探针在 dev Electron 上实测：
 *
 *   1) 基线：整个 Electron 进程树 RSS（主进程 + 全部 Helper）+ 窗口数
 *   2) 弹出 2 个结果窗（真实作业）→ 稳定后总量再测
 *   3) 每窗增量 = Δ总量 / 2；每窗 JS 堆（CDP Performance.getMetrics）
 *   4) remove 回收 → 总量回落复核
 *
 * 判读（诚实）：实测数字写入 plan §8；若每窗增量 ≤ 200MB（估算上限）→
 * 多入口 bundle 备用方案不启动。
 * 证据：acceptance/block-59/memory-probe.json
 */
const path = require('node:path');
const fs = require('node:fs');
const { execFileSync } = require('node:child_process');
const http = require('node:http');
const { CdpClient } = require('./g0-rs-p7-cdp.cjs');

const DEBUG_PORT = process.env.PETRI_DEBUG_PORT || '9222';
const DB_PATH = process.env.BIOF59_DB
  || path.join(__dirname, '..', '.petri-dev-user-data', 'data', 'petri.db');
const EVIDENCE_DIR = path.join(__dirname, '..', 'acceptance', 'block-59');
const ELECTRON_MATCH = 'Petri-workspace/desktop/node_modules/electron/dist/Electron.app';

function fetchJson(url) {
  return new Promise((resolve, reject) => {
    http.get(url, (res) => {
      let d = '';
      res.on('data', (c) => (d += c));
      res.on('end', () => { try { resolve(JSON.parse(d)); } catch (e) { reject(e); } });
    }).on('error', reject);
  });
}

async function evalJS(client, expr) {
  const r = await Promise.race([
    client.send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true, userGesture: true }),
    new Promise((_, reject) => setTimeout(() => reject(new Error('cdp_eval_timeout_30s')), 30000)),
  ]);
  if (r.exceptionDetails) {
    throw new Error(`evaluate_failed: ${r.exceptionDetails.text} ${r.exceptionDetails.exception?.description || ''}`.slice(0, 300));
  }
  return r.result.value;
}

async function evalJSRetry(client, expr, { tries = 5, delayMs = 2000 } = {}) {
  let lastErr = null;
  for (let i = 0; i < tries; i++) {
    try { return await evalJS(client, expr); } catch (e) {
      lastErr = e;
      if (!/-32000|context|cdp_command_failed/i.test(e.message)) throw e;
      await delay(delayMs);
    }
  }
  throw lastErr;
}

function delay(ms) { return new Promise((r) => setTimeout(r, ms)); }
function log(msg) { try { fs.writeSync(1, `[${new Date().toISOString().slice(11, 19)}] ${msg}\n`); } catch {} }

/** Electron 进程树 RSS 总量（MB）：主进程 + 全部 Helper（按二进制路径匹配）。 */
function electronTreeRssMB() {
  const out = execFileSync('ps', ['-axo', 'pid=,rss=,command='], { encoding: 'utf8' });
  let totalKB = 0;
  let count = 0;
  for (const line of out.split('\n')) {
    if (!line.includes(ELECTRON_MATCH) && !/ZCode/.test(line)) continue;
    if (!/node_modules\/electron|Electron Helper/.test(line) && !line.includes('Electron.app/Contents/MacOS/Electron')) continue;
    const m = line.trim().match(/^(\d+)\s+(\d+)\s/);
    if (m) { totalKB += Number(m[2]); count += 1; }
  }
  return { totalMB: Math.round(totalKB / 1024), processCount: count };
}

async function listTargets() {
  return fetchJson(`http://127.0.0.1:${DEBUG_PORT}/json/list`);
}

async function windowTargets() {
  const targets = await listTargets();
  return {
    main: targets.filter((t) => t.type === 'page' && /localhost:3000/.test(t.url || '') && !/(\/window\/)/.test(t.url || '')),
    popouts: targets.filter((t) => t.type === 'page' && (t.url || '').includes('/window/')),
    all: targets,
  };
}

const results = { startedAt: new Date().toISOString(), samples: [], assertions: [] };
function assert(name, pass, detail = '') {
  results.assertions.push({ name, pass: !!pass, detail: String(detail).slice(0, 400) });
  log(`${pass ? 'PASS' : 'FAIL'} ${name}${detail ? ' :: ' + String(detail).slice(0, 140) : ''}`);
}

async function main() {
  fs.mkdirSync(EVIDENCE_DIR, { recursive: true });

  // 选作业（两个不同产物）
  const rows = JSON.parse(execFileSync(
    'sqlite3',
    [DB_PATH, '-json',
     "SELECT id, result_json FROM tool_jobs WHERE status='completed' AND result_json LIKE '%artifacts%' ORDER BY completed_at DESC LIMIT 10"],
    { encoding: 'utf8' },
  ));
  const picked = [];
  for (const row of rows) {
    if (picked.length >= 2) break;
    try {
      const parsed = JSON.parse(row.result_json || '{}');
      const res = parsed?.result || parsed;
      const files = res?.artifacts || res?.files || [];
      const name = files[0]?.name || files[0]?.filename;
      if (name && !picked.some((p) => p.jobId === row.id)) {
        picked.push({ jobId: row.id, artifactName: name });
      }
    } catch { /* next */ }
  }
  if (picked.length < 2) throw new Error('need two completed jobs');
  const keys = picked.map((p) => `${p.jobId}:${p.artifactName}`);

  const mainWin = (await windowTargets()).main[0];
  const client = await new CdpClient(mainWin.webSocketDebuggerUrl).connect();

  // 幂等预清理
  await evalJSRetry(client, `(async () => {
    const wm = window.petriDesktop?.windowManager;
    if (!wm) return false;
    const snap = await wm.snapshot();
    for (const id of ${JSON.stringify(keys.map((k) => `result:${k}`))}) {
      const entry = (snap?.snapshot?.entries || []).find((e) => e.id === id);
      if (entry) {
        if (entry.state === 'popped') await wm.minimizeToRail(id);
        await wm.remove(id);
      }
    }
    return true;
  })()`);
  await delay(1200);

  // 1) 基线
  const base = electronTreeRssMB();
  const baseWins = await windowTargets();
  results.samples.push({ phase: 'baseline', ...base, mainWindows: baseWins.main.length, popoutWindows: baseWins.popouts.length });
  log(`基线：总量 ${base.totalMB}MB / ${base.processCount} 进程 / popout ${baseWins.popouts.length}`);

  // 2) 弹出两个结果窗
  for (const key of keys) {
    const r = await evalJSRetry(client, `window.petriDesktop.windowManager.popOut('result', ${JSON.stringify(key)})`);
    assert(`弹出 ${key.slice(-24)}`, r?.ok === true, JSON.stringify(r));
  }
  await delay(4000); // 渲染稳定
  const after2 = electronTreeRssMB();
  const wins2 = await windowTargets();
  results.samples.push({ phase: 'two-popouts', ...after2, mainWindows: wins2.main.length, popoutWindows: wins2.popouts.length });
  log(`两窗：总量 ${after2.totalMB}MB / popout ${wins2.popouts.length}`);

  // 3) 每窗 JS 堆（CDP）
  const heaps = [];
  for (const t of wins2.popouts) {
    try {
      const c = await new CdpClient(t.webSocketDebuggerUrl).connect();
      await c.send('Performance.enable', {});
      const m = await c.send('Performance.getMetrics', {});
      const heap = (m.metrics || []).find((x) => x.name === 'JSHeapUsedSize')?.value || 0;
      heaps.push({ url: (t.url || '').slice(-40), heapMB: Math.round(heap / 1024 / 1024 * 10) / 10 });
    } catch (e) {
      heaps.push({ url: (t.url || '').slice(-40), error: e.message.slice(0, 80) });
    }
  }
  results.jsHeaps = heaps;
  log(`每窗 JS 堆：${JSON.stringify(heaps)}`);

  const deltaTotal = after2.totalMB - base.totalMB;
  const perWindow = Math.round(deltaTotal / keys.length);
  results.deltaTotalMB = deltaTotal;
  results.perWindowMB = perWindow;
  assert('两窗总量增量非负（测量有效）', deltaTotal >= -50, `Δ=${deltaTotal}MB`);
  assert(`每窗增量 ${perWindow}MB ≤ plan §8 估算上限 200MB → 多入口 bundle 不启动`,
    perWindow <= 200 && perWindow > -200, `perWindow=${perWindow}MB`);

  // 4) 回收：remove 两窗 → 总量回落
  for (const key of keys) {
    await evalJSRetry(client, `window.petriDesktop.windowManager.minimizeToRail('result:${key}')`);
    await evalJSRetry(client, `window.petriDesktop.windowManager.remove('result:${key}')`);
  }
  await delay(2500);
  const afterClose = electronTreeRssMB();
  results.samples.push({ phase: 'after-remove', ...afterClose });
  log(`回收后：总量 ${afterClose.totalMB}MB`);
  assert('移除后总量回落（低于两窗态）', afterClose.totalMB <= after2.totalMB,
    `two=${after2.totalMB} → closed=${afterClose.totalMB}MB`);

  const allPass = results.assertions.every((a) => a.pass);
  results.finishedAt = new Date().toISOString();
  results.allPass = allPass;
  results.verdict = perWindow <= 200
    ? '多入口轻量 bundle 备用方案不启动（实测在 plan §8 估算带内）'
    : '实测超出估算上限——启动多入口 bundle 备用方案的评估';
  fs.writeFileSync(path.join(EVIDENCE_DIR, 'memory-probe.json'), JSON.stringify(results, null, 2) + '\n');
  log(`证据已写入 acceptance/block-59/memory-probe.json (allPass=${allPass}) verdict=${results.verdict}`);
  process.exit(allPass ? 0 : 1);
}

main().catch((e) => {
  console.error('FAIL 脚本异常:', e && e.message);
  process.exit(1);
});

#!/usr/bin/env node
'use strict';

/**
 * BLOCK-59 P2 用户侧实机 CDP 断言驱动：终端独立窗（升格 Tab）+ 边缘活动轨道（dev Electron）。
 *   场景 C（P2）：
 *     1) 主窗桥 startSession → pty 会话运行
 *     2) popOut('terminal', sessionId) → /window/terminal/ 独立窗 target + xterm 挂载
 *     3) 数据面：主窗 writeSession → pty echo → 受管窗转发 → 弹出窗收到（terminal.js forward 实锤）
 *     4) × 降格 → railed → 轨道容器窗出现（/window/rail visible）
 *     5) 轨道刻度渲染（data-kind=terminal）+ 点击刻度 = 恢复 → popped
 *     6) 恢复后轨道隐藏（visibilityState hidden）
 *     7) 再降格 → 轨道「显式移除」等价路径（remove）→ 轨道隐藏 + 注册表终结
 *   静态 5min 淡出：railEntries.isFadedRailEntry 单测覆盖（14/14），实机不做 5min 等待。
 * 前置：dev Electron 已在跑（主进程已含 P2 代码——terminal.js 转发 + 轨道窗）。
 * 证据：acceptance/block-59/p2-live.json + p59-p2-*.png
 */
const fs = require('node:fs');
const path = require('node:path');
const http = require('node:http');
const { CdpClient } = require('./g0-rs-p7-cdp.cjs');

const DEBUG_PORT = process.env.PETRI_DEBUG_PORT || '9222';
const EVIDENCE_DIR = path.join(__dirname, '..', 'acceptance', 'block-59');
const SESSION_ID = process.env.BIOF59_SESSION || 'default';

function fetchJson(url) {
  return new Promise((resolve, reject) => {
    http.get(url, (res) => {
      let d = '';
      res.on('data', (c) => (d += c));
      res.on('end', () => { try { resolve(JSON.parse(d)); } catch (e) { reject(e); } });
    }).on('error', reject);
  });
}

async function evalJS(client, expr) {
  const r = await Promise.race([
    client.send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true, userGesture: true }),
    new Promise((_, reject) => setTimeout(() => reject(new Error('cdp_eval_timeout_30s')), 30000)),
  ]);
  if (r.exceptionDetails) {
    throw new Error(`evaluate_failed: ${r.exceptionDetails.text} ${r.exceptionDetails.exception?.description || ''}`.slice(0, 500));
  }
  return r.result.value;
}

async function evalJSRetry(client, expr, { tries = 6, delayMs = 2500 } = {}) {
  let lastErr = null;
  for (let i = 0; i < tries; i++) {
    try { return await evalJS(client, expr); } catch (e) {
      lastErr = e;
      if (!/-32000|context|cdp_command_failed/i.test(e.message)) throw e;
      await delay(delayMs);
    }
  }
  throw lastErr;
}

function delay(ms) { return new Promise((r) => setTimeout(r, ms)); }

function log(msg) {
  try { fs.writeSync(1, `[${new Date().toISOString().slice(11, 19)}] ${msg}\n`); } catch {}
}

async function screenshot(client, file) {
  try {
    await client.send('Page.bringToFront', {});
    const r = await client.send('Page.captureScreenshot', { format: 'png' });
    fs.writeFileSync(file, Buffer.from(r.data, 'base64'));
  } catch (e) {
    log(`WARN screenshot skipped (${path.basename(file)}): ${e.message}`);
  }
}

async function listTargets() {
  return fetchJson(`http://127.0.0.1:${DEBUG_PORT}/json/list`);
}

async function pollTarget(needle, { appear = true, tries = 20, delayMs = 700 } = {}) {
  for (let i = 0; i < tries; i++) {
    const targets = await listTargets();
    const hits = targets.filter((t) => t.type === 'page' && (t.url || '').includes(needle));
    if (appear && hits.length > 0) return hits;
    if (!appear && hits.length === 0) return [];
    await delay(delayMs);
  }
  return appear ? null : [];
}

const results = { startedAt: new Date().toISOString(), assertions: [] };
function assert(name, pass, detail = '') {
  results.assertions.push({ name, pass: !!pass, detail: String(detail).slice(0, 500) });
  log(`${pass ? 'PASS' : 'FAIL'} ${name}${detail ? ' :: ' + String(detail).slice(0, 160) : ''}`);
}

async function main() {
  fs.mkdirSync(EVIDENCE_DIR, { recursive: true });

  const targets = await listTargets();
  const page = targets.find((t) => t.type === 'page' && /localhost:3000/.test(t.url || '') && !/(\/window\/)/.test(t.url || ''));
  if (!page) throw new Error('petri_page_not_found');
  const client = await new CdpClient(page.webSocketDebuggerUrl).connect();
  results.mainPage = page.url;

  // 幂等预清理：上轮残留（terminal 条目 / default 会话）
  const pre = await evalJSRetry(client, `(async () => {
    const wm = window.petriDesktop?.windowManager;
    if (!wm) return { bridge: false };
    const snap = await wm.snapshot();
    const entry = (snap?.snapshot?.entries || []).find((e) => e.id === 'terminal:${SESSION_ID}');
    if (entry) {
      if (entry.state === 'popped') await wm.minimizeToRail(entry.id);
      await wm.remove(entry.id);
    }
    await window.petriDesktop.terminal.stopSession('${SESSION_ID}');
    return { bridge: true, cleaned: !!entry };
  })()`);
  assert('主窗 windowManager/terminal 桥可用 + 预清理', pre?.bridge === true, JSON.stringify(pre));

  // 1) 起会话
  const started = await evalJSRetry(client, `window.petriDesktop.terminal.startSession(undefined, '${SESSION_ID}')`);
  assert('终端会话启动（主窗 tab 语义，pty 运行中）', started?.ok === true && started?.sessionId === '${SESSION_ID}'.replace('${SESSION_ID}', SESSION_ID), JSON.stringify(started));

  // 2) 升格为窗
  const pop = await evalJSRetry(client, `window.petriDesktop.windowManager.popOut('terminal', '${SESSION_ID}')`);
  assert('终端 Tab 升格 → created（terminal:<sessionId>）', pop?.ok && pop?.action === 'created' && pop?.id === `terminal:${SESSION_ID}`, JSON.stringify(pop));
  const popHits = await pollTarget('/window/terminal/');
  assert('终端独立窗 target 出现', Array.isArray(popHits) && popHits.length === 1, `targets=${popHits?.length}`);
  const popClient = await new CdpClient(popHits[0].webSocketDebuggerUrl).connect();
  await delay(2000);

  const termDom = await evalJSRetry(popClient, `(() => ({
    hasXterm: !!document.querySelector('.xterm'),
    hasHost: !!document.querySelector('[data-terminal-host]'),
    attachNote: (document.querySelector('[class*=subtitle]') || {}).textContent || null,
  }))()`);
  assert('终端独立窗 xterm 挂载', termDom?.hasXterm === true, JSON.stringify(termDom));
  await screenshot(popClient, path.join(EVIDENCE_DIR, 'p59-p2-01-terminal-window.png'));

  // 3) 数据面：主窗写入 → pty echo → 受管窗转发 → 弹出窗收到
  await evalJSRetry(popClient, `(() => { window.__p59probe = ''; window.petriDesktop.terminal.onData((p) => { if (p.sessionId === '${SESSION_ID}') window.__p59probe += String(p.data || ''); }); return true; })()`);
  const marker = `B59P2-${Date.now()}`;
  await evalJSRetry(client, `window.petriDesktop.terminal.writeSession('echo ${marker}\\r', '${SESSION_ID}')`);
  let probeHit = false;
  for (let i = 0; i < 15; i++) {
    await delay(600);
    const probe = await evalJS(popClient, `window.__p59probe`);
    if (String(probe).includes(marker)) { probeHit = true; break; }
  }
  assert('数据面实锤：主窗写入 → pty echo → 转发 → 弹出窗收到', probeHit, `marker=${marker}`);
  const termLines = await evalJS(popClient, `(() => { const el = document.querySelector('.xterm-rows'); return el ? el.textContent.length : 0; })()`);
  assert('弹出窗终端有真实渲染内容（xterm rows 非空）', termLines > 0, `chars=${termLines}`);

  // 4) × 降格 → 轨道出现
  const mini = await evalJSRetry(client, `window.petriDesktop.windowManager.minimizeToRail('terminal:${SESSION_ID}')`);
  assert('× → 降格 railed（终端常驻不淡出）', mini?.ok && mini?.state === 'railed', JSON.stringify(mini));
  const railHits = await pollTarget('/window/rail');
  assert('轨道容器窗 target 出现（懒创建）', Array.isArray(railHits) && railHits.length >= 1, `targets=${railHits?.length}`);
  await delay(1500);
  const railClient = await new CdpClient(railHits[0].webSocketDebuggerUrl).connect();
  const railState1 = await evalJSRetry(railClient, `(() => ({
    visible: document.visibilityState,
    tickCount: document.querySelectorAll('[class*=tick]').length,
    terminalTick: !!document.querySelector('[data-kind="terminal"]'),
    fadedAttr: !!document.querySelector('[data-faded]'),
  }))()`);
  assert('轨道窗可见且渲染终端刻度（data-kind=terminal）', railState1?.visible === 'visible' && railState1?.terminalTick, JSON.stringify(railState1));
  await screenshot(railClient, path.join(EVIDENCE_DIR, 'p59-p2-02-rail.png'));

  // 5) 点击刻度 = 恢复
  await evalJSRetry(railClient, `(() => { const t = document.querySelector('[data-kind="terminal"]'); t.click(); return true; })()`);
  await delay(1500);
  const snapRestored = await evalJSRetry(client, `window.petriDesktop.windowManager.snapshot()`);
  const restoredEntry = (snapRestored?.snapshot?.entries || []).find((e) => e.id === `terminal:${SESSION_ID}`);
  assert('轨道刻度点击 → popped（hover 恢复路径的点击等价）', restoredEntry?.state === 'popped', JSON.stringify(restoredEntry));

  // 6) 恢复后轨道隐藏
  let railHidden = false;
  for (let i = 0; i < 10; i++) {
    await delay(600);
    const vis = await evalJS(railClient, `document.visibilityState`);
    if (vis === 'hidden') { railHidden = true; break; }
  }
  assert('无降格窗口时轨道自动隐藏（visibilityState hidden）', railHidden);

  // 7) 再降格 → 轨道显式移除 → 轨道隐藏 + 条目终结
  await evalJSRetry(client, `window.petriDesktop.windowManager.minimizeToRail('terminal:${SESSION_ID}')`);
  await pollTarget('/window/rail');
  await evalJSRetry(client, `window.petriDesktop.windowManager.remove('terminal:${SESSION_ID}')`);
  const snapFinal = await evalJSRetry(client, `window.petriDesktop.windowManager.snapshot()`);
  assert('轨道显式移除 → 条目终结', !((snapFinal?.snapshot?.entries || []).some((e) => e.id === `terminal:${SESSION_ID}`)));
  let railHidden2 = false;
  for (let i = 0; i < 10; i++) {
    await delay(600);
    const vis = await evalJS(railClient, `document.visibilityState`).catch(() => 'gone');
    if (vis !== 'visible') { railHidden2 = true; break; }
  }
  assert('移除后轨道隐藏（常驻窗保活不销毁）', railHidden2);

  // 清理：停 pty 会话
  await evalJSRetry(client, `window.petriDesktop.terminal.stopSession('${SESSION_ID}')`);

  const allPass = results.assertions.every((a) => a.pass);
  results.finishedAt = new Date().toISOString();
  results.allPass = allPass;
  fs.writeFileSync(path.join(EVIDENCE_DIR, 'p2-live.json'), JSON.stringify(results, null, 2) + '\n');
  log(`证据已写入 acceptance/block-59/p2-live.json (allPass=${allPass})`);
  process.exit(allPass ? 0 : 1);
}

const watchdog = setTimeout(() => {
  console.error('FAIL UI 实机脚本 10min 看门狗超时');
  process.exit(1);
}, 10 * 60 * 1000);
watchdog.unref();

main().catch((e) => {
  console.error('FAIL 脚本异常:', e && e.message);
  process.exit(1);
});

#!/usr/bin/env node
'use strict';

/**
 * BLOCK-59 P3 用户侧实机 CDP 断言驱动：指挥中心（多任务俯瞰单例窗，dev Electron）。
 *   场景 D（P3）：
 *     1) popOut('command-center') → 单例窗创建（/window/command-center target）
 *     2) 重复弹出 → focused（单例不双开）
 *     3) 瓦片只读投影：/api/tools/history 既有真相 → 真实作业名上屏（与 SQLite 交叉核对）
 *     4) 点击瓦片 → 下钻弹出 L1 结果窗（popOut result + target 出现）
 *     5) × 关闭指挥中心（无状态单例随开随关）→ target 消失；下钻窗不受影响
 *   瓦片实时进度形态 = 状态 + 已耗时（tool_jobs 无百分比，不虚构进度条）。
 * 前置：dev Electron 已在跑；本地库存在 completed 作业。
 * 证据：acceptance/block-59/p3-live.json + p59-p3-01-command-center.png
 */
const fs = require('node:fs');
const path = require('node:path');
const { execFileSync } = require('node:child_process');
const http = require('node:http');
const { CdpClient } = require('./g0-rs-p7-cdp.cjs');

const DEBUG_PORT = process.env.PETRI_DEBUG_PORT || '9222';
const DB_PATH = process.env.BIOF59_DB
  || path.join(__dirname, '..', '.petri-dev-user-data', 'data', 'petri.db');
const EVIDENCE_DIR = path.join(__dirname, '..', 'acceptance', 'block-59');

function fetchJson(url) {
  return new Promise((resolve, reject) => {
    http.get(url, (res) => {
      let d = '';
      res.on('data', (c) => (d += c));
      res.on('end', () => { try { resolve(JSON.parse(d)); } catch (e) { reject(e); } });
    }).on('error', reject);
  });
}

async function evalJS(client, expr) {
  const r = await Promise.race([
    client.send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true, userGesture: true }),
    new Promise((_, reject) => setTimeout(() => reject(new Error('cdp_eval_timeout_30s')), 30000)),
  ]);
  if (r.exceptionDetails) {
    throw new Error(`evaluate_failed: ${r.exceptionDetails.text} ${r.exceptionDetails.exception?.description || ''}`.slice(0, 500));
  }
  return r.result.value;
}

async function evalJSRetry(client, expr, { tries = 6, delayMs = 2500 } = {}) {
  let lastErr = null;
  for (let i = 0; i < tries; i++) {
    try { return await evalJS(client, expr); } catch (e) {
      lastErr = e;
      if (!/-32000|context|cdp_command_failed/i.test(e.message)) throw e;
      await delay(delayMs);
    }
  }
  throw lastErr;
}

function delay(ms) { return new Promise((r) => setTimeout(r, ms)); }

function log(msg) {
  try { fs.writeSync(1, `[${new Date().toISOString().slice(11, 19)}] ${msg}\n`); } catch {}
}

async function screenshot(client, file) {
  try {
    await client.send('Page.bringToFront', {});
    const r = await client.send('Page.captureScreenshot', { format: 'png' });
    fs.writeFileSync(file, Buffer.from(r.data, 'base64'));
  } catch (e) {
    log(`WARN screenshot skipped (${path.basename(file)}): ${e.message}`);
  }
}

function sqliteRows(sql) {
  const out = execFileSync('sqlite3', [DB_PATH, '-json', sql], { encoding: 'utf8' });
  return out.trim() ? JSON.parse(out) : [];
}

async function listTargets() {
  return fetchJson(`http://127.0.0.1:${DEBUG_PORT}/json/list`);
}

async function pollTarget(needle, { appear = true, tries = 20, delayMs = 700 } = {}) {
  for (let i = 0; i < tries; i++) {
    const targets = await listTargets();
    const hits = targets.filter((t) => t.type === 'page' && (t.url || '').includes(needle));
    if (appear && hits.length > 0) return hits;
    if (!appear && hits.length === 0) return [];
    await delay(delayMs);
  }
  return appear ? null : [];
}

const results = { startedAt: new Date().toISOString(), assertions: [] };
function assert(name, pass, detail = '') {
  results.assertions.push({ name, pass: !!pass, detail: String(detail).slice(0, 500) });
  log(`${pass ? 'PASS' : 'FAIL'} ${name}${detail ? ' :: ' + String(detail).slice(0, 160) : ''}`);
}

async function main() {
  fs.mkdirSync(EVIDENCE_DIR, { recursive: true });

  const targets = await listTargets();
  const page = targets.find((t) => t.type === 'page' && /localhost:3000/.test(t.url || '') && !/(\/window\/)/.test(t.url || ''));
  if (!page) throw new Error('petri_page_not_found');
  const client = await new CdpClient(page.webSocketDebuggerUrl).connect();
  results.mainPage = page.url;

  // 1) 指挥中心弹出（单例）
  const pop = await evalJSRetry(client, `window.petriDesktop.windowManager.popOut('command-center')`);
  assert('指挥中心弹出 → created（单例通道）', pop?.ok && (pop?.action === 'created' || pop?.action === 'focused'), JSON.stringify(pop));
  const ccHits = await pollTarget('/window/command-center');
  assert('指挥中心 target 出现', Array.isArray(ccHits) && ccHits.length === 1, `targets=${ccHits?.length}`);

  // 2) 单例不双开
  const pop2 = await evalJSRetry(client, `window.petriDesktop.windowManager.popOut('command-center')`);
  const ccCount = (await listTargets()).filter((t) => (t.url || '').includes('/window/command-center')).length;
  assert('重复弹出 → focused（单例不双开）', pop2?.ok && pop2?.action === 'focused' && ccCount === 1, `action=${pop2?.action} targets=${ccCount}`);

  // 3) 瓦片只读投影（与 SQLite 真相交叉核对）
  const ccClient = await new CdpClient(ccHits[0].webSocketDebuggerUrl).connect();
  await delay(2500);
  const recentJobs = sqliteRows(
    `SELECT id, name, tool_id, status FROM tool_jobs ORDER BY created_at DESC LIMIT 12`
  );
  const expectedName = (recentJobs.find((j) => (j.name || '').trim()) || {}).name || '';
  const tileState = await evalJSRetry(ccClient, `(() => ({
    tiles: document.querySelectorAll('button[class*=tile]').length,
    bodyText: (document.body.textContent || '').slice(0, 1200),
    hasRunningPulse: !!document.querySelector('[data-status="running"]'),
  }))()`);
  assert('指挥中心瓦片渲染（最近 12 作业内）', tileState?.tiles > 0 && tileState?.tiles <= 12, `tiles=${tileState?.tiles}`);
  assert('瓦片内容与 tool_jobs 真相一致（真实作业名上屏）',
    expectedName && tileState?.bodyText?.includes(expectedName.split(' ').slice(0, 2).join(' ')),
    `expected~="${expectedName.slice(0, 40)}"`);
  await screenshot(ccClient, path.join(EVIDENCE_DIR, 'p59-p3-01-command-center.png'));

  // 4) 点击瓦片 → 下钻 L1 结果窗
  const drill = await evalJSRetry(ccClient, `(() => {
    const tile = document.querySelector('[class*=tile]');
    tile.click();
    return { ok: true };
  })()`);
  assert('点击瓦片触发下钻', drill?.ok === true, JSON.stringify(drill));
  const resultHits = await pollTarget('/window/result/');
  const snapDrill = await evalJSRetry(client, `window.petriDesktop.windowManager.snapshot()`);
  const poppedEntry = (snapDrill?.snapshot?.entries || []).find((e) => e.state === 'popped');
  assert('下钻 → L1 结果窗弹出（popOut result + target 出现）',
    Array.isArray(resultHits) && resultHits.length >= 1 && !!poppedEntry,
    JSON.stringify({ targets: resultHits?.length, entry: poppedEntry?.id }));

  // 5) × 关闭指挥中心（无状态单例随开随关）
  await evalJSRetry(ccClient, `(() => { window.close(); return true; })()`);
  const gone = await pollTarget('/window/command-center', { appear: false });
  assert('× 关闭指挥中心 → target 消失（不进轨道，随开随关）', Array.isArray(gone) && gone.length === 0, `targets=${gone?.length}`);
  const snapFinal = await evalJSRetry(client, `window.petriDesktop.windowManager.snapshot()`);
  assert('指挥中心关闭不影响已下钻的结果窗（注册表 popped 仍在）',
    (snapFinal?.snapshot?.entries || []).some((e) => e.state === 'popped'), JSON.stringify(snapFinal?.snapshot?.entries?.map((e) => ({ id: e.id, state: e.state }))));

  // 清理：移除下钻残留
  const leftover = (snapFinal?.snapshot?.entries || []).find((e) => e.state === 'popped');
  if (leftover) {
    await evalJSRetry(client, `window.petriDesktop.windowManager.minimizeToRail(${JSON.stringify(leftover.id)})`);
    await evalJSRetry(client, `window.petriDesktop.windowManager.remove(${JSON.stringify(leftover.id)})`);
  }

  const allPass = results.assertions.every((a) => a.pass);
  results.finishedAt = new Date().toISOString();
  results.allPass = allPass;
  fs.writeFileSync(path.join(EVIDENCE_DIR, 'p3-live.json'), JSON.stringify(results, null, 2) + '\n');
  log(`证据已写入 acceptance/block-59/p3-live.json (allPass=${allPass})`);
  process.exit(allPass ? 0 : 1);
}

const watchdog = setTimeout(() => {
  console.error('FAIL UI 实机脚本 10min 看门狗超时');
  process.exit(1);
}, 10 * 60 * 1000);
watchdog.unref();

main().catch((e) => {
  console.error('FAIL 脚本异常:', e && e.message);
  process.exit(1);
});

