'use strict';

/**
 * BLOCK-67 P3 实机 CDP 验收：远程终端（ssh pty）+ 远程审阅（git 只读链）。
 *   A1 底部终端展开 → ssh pty 挂通（远端 shell 回显：root@ 或远程路径）
