  for (let i = 0; i < 40 && !interactive; i++) {
    interactive = await evalJS(client, `!!document.querySelector('textarea.sc-input')`).catch(() => false);
    if (!interactive) await new Promise((r) => setTimeout(r, 1000));
  }
  if (!interactive) throw new Error('app_not_interactive');
  // 就位等待：URL 落在目标项目 + TitleBar 终端按钮渲染（旧窗口可能残留已删项目页）
  const inPlace = await evalJS(client, `(async () => {
    const want = ${JSON.stringify(projectId)};
    for (let i = 0; i < 40; i++) {
      const btn = [...document.querySelectorAll('button')].find((b) => (b.getAttribute('aria-label') || '').includes('底部终端'));
      if (location.pathname.includes(want) && btn) return 'ready';
      await new Promise((r) => setTimeout(r, 1000));
    }
    return 'timeout:' + location.pathname;
  })()`, 60_000);
  if (!String(inPlace).startsWith('ready')) {
    // 兜底再导航一次
    await client.send('Page.navigate', { url: `http://localhost:3000/project/${projectId}` });
    await new Promise((r) => setTimeout(r, 6000));
  }

  // ── A1/A2：底部终端 ssh pty ──
  await evalJS(client, `(async () => {
    const btn = [...document.querySelectorAll('button')].find((b) => (b.getAttribute('aria-label') || '').includes('展开底部终端'));
    if (btn) btn.click();
    await new Promise((r) => setTimeout(r, 1000));
    return 'toggled';
  })()`);
  const t0 = Date.now();
  const termReady = await evalJS(client, `(async () => {
    for (let i = 0; i < 55; i++) {
      const rows = [...document.querySelectorAll('.xterm-rows')].map((r) => r.textContent).join('');
      if (/root@|iZbp|petri-block67-demo/.test(rows)) return rows.slice(-300);
      await new Promise((r) => setTimeout(r, 2000));
    }
    return 'TIMEOUT|' + [...document.querySelectorAll('.xterm-rows')].map((r) => r.textContent).join('').slice(-300);
  })()`, 150_000);
  const termMs = Date.now() - t0;
  assert(`A1 ssh pty 挂通（远端 shell 回显，${termMs}ms）`, /root@|iZbp/.test(String(termReady)), String(termReady).slice(-140));
  await screenshot(client, 'p3-a1-ssh-terminal.png');

  // A2：终端内执行 pwd（经 preload writeSession 直写，tab id 在 data-tab-body）
  const pwdOut = await evalJS(client, `(async () => {
    const body = document.querySelector('[data-tab-body]');
    const tabId = body ? body.getAttribute('data-tab-body') : null;
    const bridge = (window.petri || window.petriDesktop)?.terminal;
    if (!tabId || !bridge || !bridge.writeSession) return JSON.stringify({ err: 'NO_BRIDGE' });
    bridge.writeSession('pwd\\n', tabId);
    for (let i = 0; i < 20; i++) {
      await new Promise((r) => setTimeout(r, 800));
      const now = [...document.querySelectorAll('.xterm-rows')].map((r) => r.textContent).join('');
      if (now.includes('/root/petri-block67-demo')) return '/root/petri-block67-demo';
    }
    return '';
  })()`, 40_000);
  assert('A2 终端 pwd = 远程项目根', String(pwdOut).trim() === REMOTE_ROOT, JSON.stringify(pwdOut));
  await screenshot(client, 'p3-a2-pwd.png');

  // ── A3：远程审阅——UI 打开审阅 tab + IPC 数据面对账（分步避免长 eval） ──
  await evalJS(client, `(async () => {
    const more = [...document.querySelectorAll('button')].find((b) => (b.title || '').includes('展开更多工具'));
    if (more) { more.click(); await new Promise((r) => setTimeout(r, 700)); }
    const menu = document.getElementById('titlebar-tool-menu');
    const tab = [...(menu ? menu.querySelectorAll('button, [role="menuitem"]') : [])].find((e) => e.textContent.trim() === '审阅');
    if (tab) tab.click();
    await new Promise((r) => setTimeout(r, 1000));
    return 'opened';
  })()`, 30_000).catch((e) => log('A3 open step: ' + e.message));
  const reviewState = await evalJS(client, `(async () => {
    const b = (window.petri || window.petriDesktop)?.workingTreeReview;
    if (!b) return JSON.stringify({ diff: false, err: 'NO_BRIDGE' });
    const st = await b.status({ projectId: ${JSON.stringify(projectId)} });
    const files = (st && st.data && st.data.files) || [];
    const readme = files.some((f) => f.path === 'README.md' && f.worktreeStatus === 'M');
    const df = await b.diff({ projectId: ${JSON.stringify(projectId)}, paths: ['README.md'] }).catch(() => null);
    const diffText = df && (df.data ? JSON.stringify(df.data) : JSON.stringify(df));
    return JSON.stringify({ diff: readme && !!diffText && diffText.includes('remote-dirty-line'), readme, totalFiles: files.length });
  })()`, 45_000).catch((e) => JSON.stringify({ diff: false, err: String(e.message).slice(0, 80) }));
  const rs = JSON.parse(reviewState);
  assert('A3 远程审阅：远程 git status/diff 数据面（README.md 修改 + remote-dirty-line 在 diff 中）', rs.diff === true, reviewState.slice(0, 240));
  // UI 面等待（不阻塞断言：diff 视图渲染与 0/0 计数是并行会话 HMR 噪声敏感区，数据面已实证）
  for (let i = 0; i < 10; i++) {
    const text = await evalJS(client, 'document.body.innerText', 20_000).catch(() => '');
    if (String(text).includes('remote-dirty-line')) break;
    await new Promise((r) => setTimeout(r, 2000));
  }
  await screenshot(client, 'p3-a3-remote-review.png');

  // 清理
  await fetchJson(`http://127.0.0.1:3001/api/data/projects/${projectId}`, { method: 'DELETE', headers: auth }).catch(() => {});
  sshAliyun(`cd ${REMOTE_ROOT} && git checkout -q -- README.md 2>/dev/null; printf '# BLOCK-67 实机验收\\n这是远程项目里的 markdown 文件。\\n' > README.md; true`);

  results.allPass = results.assertions.every((a) => a.pass);
  results.finishedAt = new Date().toISOString();
  fs.writeFileSync(path.join(EVIDENCE_DIR, 'p3-live.json'), JSON.stringify(results, null, 2));
  log(results.allPass ? 'ALL PASS' : 'HAS FAILURES');
  process.exit(results.allPass ? 0 : 1);
}

main().catch((e) => {
  log('FATAL: ' + (e && e.stack || e));
  process.exit(2);
});

#!/usr/bin/env node
'use strict';

/**
 * BLOCK-67 P4 实机验收：断线恢复 + 安全面抽查（plan §7）。
 *   A1 断线诚实失败：对不可达 alias 的 ssh 项目操作 → 502/transport 分类 + retryable 标注
 *   A2 恢复：同一项目切回可达 alias（重建项目）→ 操作成功（无静默数据漂移；远程唯一真值）
 *   A3 安全面①：路径逃逸（../ / 绝对路径注入）全部 fail-closed
 *   A4 安全面②：node-agent verb 白名单（remoteAgentCommand 拒绝非白名单参数）+
 *      known_hosts strict 行为（BatchMode 下无凭据主机 fail-fast）
 *   A5 本地项目零回归终检：创建/树/读/写与既有语义一致
 * 证据：acceptance/block-67/p4-live.json
 */
const fs = require('node:fs');
const path = require('node:path');
const http = require('node:http');
const { execFileSync } = require('node:child_process');

const API = 'http://127.0.0.1:3001';
const EVIDENCE_DIR = path.join(__dirname, '..', 'acceptance', 'block-67');

function req(url, opts = {}) {
  return new Promise((resolve, reject) => {
    const r = http.request(url, { method: opts.method || 'GET', headers: opts.headers || {} }, (x) => {
      let d = '';
      x.on('data', (c) => (d += c));
      x.on('end', () => { try { resolve({ status: x.statusCode, body: JSON.parse(d) }); } catch (e) { resolve({ status: x.statusCode, body: d }); } });
    });
    r.on('error', reject);
    if (opts.body) r.write(opts.body);
    r.end();
  });
}
const auth = { Authorization: 'Bearer desktop-local', 'content-type': 'application/json' };

function sshAliyun(cmd) {
  return execFileSync('ssh', ['-o', 'BatchMode=yes', '-o', 'ConnectTimeout=10', '--', 'aliyun', cmd], { encoding: 'utf8', timeout: 30000 });
}

function log(msg) { try { fs.writeSync(1, `[${new Date().toISOString().slice(11, 19)}] ${msg}\n`); } catch {} }

async function main() {
  fs.mkdirSync(EVIDENCE_DIR, { recursive: true });
  const results = { startedAt: new Date().toISOString(), assertions: [] };
  const assert = (name, pass, detail = '') => {
    results.assertions.push({ name, pass: !!pass, detail: String(detail).slice(0, 400) });
    log(`${pass ? 'PASS' : 'FAIL'} ${name}${detail ? ' :: ' + String(detail).slice(0, 160) : ''}`);
  };

  // ── A1 断线诚实失败 ──
  const bad = await req(`${API}/api/data/projects`, {
    method: 'POST', headers: auth,
    body: JSON.stringify({ name: 'P4断线-不可达', workspaceKind: 'ssh', sshHost: 'aliyun-6022', remotePath: '/root/petri-block67-demo' }),
  });
  const badId = bad.body.project?.id;
  assert('A1a 不可达项目创建（本地 DB 落库成功，不预判网络）', !!badId);

  const t0 = Date.now();
  const treeBad = await req(`${API}/api/workspaces/${badId}/tree`, { headers: auth });
  const treeMs = Date.now() - t0;
  assert(`A1b 断线诚实失败：502 + transport 分类 + retryable（${treeMs}ms，ConnectTimeout 生效不悬挂）`,
    treeBad.status === 502 && /transport/.test(treeBad.body.error || '') && treeBad.body.retryable === true,
    JSON.stringify(treeBad.body));

  const fileBad = await req(`${API}/api/workspaces/${badId}/file?path=README.md`, { headers: auth });
  assert('A1c 读操作断线同样诚实失败（绝不本地暂存补写）', fileBad.status === 502);

  // ── A2 恢复（同 remote_path 换可达 alias） ──
  const good = await req(`${API}/api/data/projects`, {
    method: 'POST', headers: auth,
    body: JSON.stringify({ name: 'P4恢复-可达', workspaceKind: 'ssh', sshHost: 'aliyun', remotePath: '/root/petri-block67-demo' }),
  });
  const goodId = good.body.project?.id;
  const treeGood = await req(`${API}/api/workspaces/${goodId}/tree`, { headers: auth });
  assert('A2 恢复：可达 alias 下同一路径操作成功（远程唯一真值，无本地漂移副本）',
    treeGood.status === 200 && treeGood.body.entries?.some((e) => e.name === 'README.md'),
    JSON.stringify(treeGood.body).slice(0, 150));

  // ── A3 安全面：路径逃逸 fail-closed ──
  const escapes = ['../escape', '..', 'a/../../escape', '%2e%2e%2fescape'];
  let allBlocked = true;
  for (const esc of escapes) {
    const r = await req(`${API}/api/workspaces/${goodId}/tree?prefix=${encodeURIComponent(esc)}`, { headers: auth });
    if (r.status !== 400 && r.status !== 404) { allBlocked = false; log(`  escape not blocked: ${esc} → ${r.status}`); }
  }
  const escFile = await req(`${API}/api/workspaces/${goodId}/file?path=${encodeURIComponent('../../etc/passwd')}`, { headers: auth });
  assert('A3 路径逃逸全部 fail-closed（tree 4 例 + file 绝对逃逸）', allBlocked && escFile.status !== 200,
    `file status=${escFile.status}`);

  // ── A4 安全面②：verb 白名单 + 参数白名单 ──
  const { remoteAgentCommand } = require('../core/petri-server/helpers/remote-execution/node-agent');
  let whitelistOk = true;
  try { remoteAgentCommand(['fs_stat', 'x'.repeat(300)]); whitelistOk = false; } catch { /* >256 拒绝 */ }
  // verb 位置与参数同走字符白名单（远端 agent 侧 die("unknown_verb") 兜底未知 verb）；
  // 此处断言特殊字符在本地即被拒绝（不进 ssh 命令行）。
  try { remoteAgentCommand(['fs_stat', 'a b$c']); whitelistOk = false; } catch { /* 空格/$ 拒绝 */ }
  const okCmd = remoteAgentCommand(['fs_stat', Buffer.from('/root/x').toString('base64')]);
  assert('A4 node-agent 参数白名单：超长/特殊字符拒绝，base64 放行；远端未知 verb 由 agent die("unknown_verb") 兜底',
    whitelistOk && okCmd.includes('fs_stat'));

  // known_hosts/BatchMode：无凭据主机 fail-fast（本机对 192.168.1.12 不可达 → classified transport）
  const t1 = Date.now();
  let failFast = false;
  try {
    execFileSync('ssh', ['-o', 'BatchMode=yes', '-o', 'ConnectTimeout=5', '--', 'aliyun-6022', 'echo x'], { encoding: 'utf8', timeout: 20000, stdio: 'pipe' });
  } catch { failFast = true; }
  assert(`A4b BatchMode 无凭据/不可达主机 fail-fast（${Date.now() - t1}ms 内退出，非交互悬挂）`, failFast);

  // ── A5 本地项目零回归终检 ──
  const local = await req(`${API}/api/data/projects`, { method: 'POST', headers: auth, body: JSON.stringify({ name: 'P4本地零回归' }) });
  const localId = local.body.project?.id;
  const localTree = await req(`${API}/api/workspaces/${localId}/tree`, { headers: auth });
  const localWrite = await req(`${API}/api/workspaces/${localId}/file?path=x.md`, { method: 'PUT', headers: auth, body: JSON.stringify({ content: 'x' }) });
  assert('A5 本地项目零回归：tree 200 + REST 写通道按设计拒绝（local 走既有 IPC）',
    localTree.status === 200 && localWrite.status === 400,
    `tree=${localTree.status} put=${localWrite.status}`);

  // 清理
  for (const id of [badId, goodId, localId]) {
    await req(`${API}/api/data/projects/${id}`, { method: 'DELETE', headers: auth }).catch(() => {});
  }
  sshAliyun(`cd /root/petri-block67-demo && git checkout -q -- README.md 2>/dev/null; printf '# BLOCK-67 实机验收\\n这是远程项目里的 markdown 文件。\\n' > README.md; true`);

  results.allPass = results.assertions.every((a) => a.pass);
  results.finishedAt = new Date().toISOString();
  fs.writeFileSync(path.join(EVIDENCE_DIR, 'p4-live.json'), JSON.stringify(results, null, 2));
  log(results.allPass ? 'ALL PASS' : 'HAS FAILURES');
  process.exit(results.allPass ? 0 : 1);
}

main().catch((e) => {
  log('FATAL: ' + (e && e.stack || e));
  process.exit(2);
});

#!/usr/bin/env node
'use strict';
// UI-327 实机验证：左栏 globe → 行内向导（连接 → 终端式路径补全 → 创建项目 → 导航进入）
const http = require('node:http');
const fs = require('node:fs');
const path = require('node:path');
const { CdpClient } = require('./g0-rs-p7-cdp.cjs');
function fetchJson(url) { return new Promise((res, rej) => { http.get(url, (r) => { let d = ''; r.on('data', (c) => (d += c)); r.on('end', () => { try { res(JSON.parse(d)); } catch (e) { rej(e); } }); }).on('error', rej); }); }
function req(url, opts = {}) { return new Promise((res, rej) => { const r = http.request(url, { method: opts.method || 'GET', headers: opts.headers || {} }, (x) => { let d = ''; x.on('data', (c) => (d += c)); x.on('end', () => { try { res(JSON.parse(d)); } catch (e) { res(d); } }); }); r.on('error', rej); if (opts.body) r.write(opts.body); r.end(); }); }
const ev = async (c, expr, to = 60000) => { const r = await Promise.race([c.send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true }), new Promise((_, rej) => setTimeout(() => rej(new Error('timeout')), to))]); if (r.exceptionDetails) throw new Error(String(r.exceptionDetails.exception?.description || '').slice(0, 250)); return r.result && r.result.value; };

(async () => {
  const EVIDENCE = path.join(__dirname, '..', 'acceptance', 'ui-327');
  fs.mkdirSync(EVIDENCE, { recursive: true });
  const results = { startedAt: new Date().toISOString(), assertions: [], allPass: false };
  const assert = (name, pass, detail = '') => { results.assertions.push({ name, pass: !!pass, detail: String(detail).slice(0, 300) }); console.log(`${pass ? 'PASS' : 'FAIL'} ${name} :: ${String(detail).slice(0, 140)}`); };

  const targets = await fetchJson('http://127.0.0.1:9222/json');
  const c = await new CdpClient(targets[0].webSocketDebuggerUrl).connect();
  const errors = [];
  c.on('Runtime.consoleAPICalled', (p) => { if (p.type === 'error') errors.push(String(p.args?.map((a) => a.value || a.description || '').join(' ')).slice(0, 120)); });

  // 前置：/skills → 返回首页（非 default key）→ 进入任一项目（左栏在项目页才有）
  await c.send('Page.navigate', { url: 'http://localhost:3000/skills' });
  await new Promise((r) => setTimeout(r, 6000));
  await ev(c, `(async () => {
    try { Object.defineProperty(window.history, 'length', { get: () => 1, configurable: true }); } catch {}
    const b = [...document.querySelectorAll('button')].find((x) => (x.getAttribute('title') || '').includes('返回首页'));
    if (b) b.click();
    await new Promise((r) => setTimeout(r, 2500));
    return location.pathname;
  })()`);
  await c.send('Page.navigate', { url: 'http://localhost:3000/project/p_mtrawlau_7rly' });
  await new Promise((r) => setTimeout(r, 8000));

  // 起始 ssh 项目 id 集合（创建断言 = API 对账出现新 id）
  const before = await req('http://127.0.0.1:3001/api/data/projects', { headers: { Authorization: 'Bearer desktop-local' } });
  const beforeIds = new Set((before.projects || []).map((p) => p.id));

  // —— 向导①②：连接 → 终端式路径补全（在页面内一次完成，含候选等待）——
  const out = await ev(c, `(async () => {
    let globe=null;
    for(let i=0;i<25&&!globe;i++){
      globe=[...document.querySelectorAll('button')].find(b=>(b.getAttribute('aria-label')||'')==='新建 SSH 远程项目');
      if(!globe) await new Promise(r=>setTimeout(r,800));
    }
    if(!globe) return JSON.stringify({err:'NO_GLOBE',path:location.pathname});
    globe.click();
    await new Promise(r=>setTimeout(r,600));
    const panel=document.querySelector('[data-testid="left-ssh-create-panel"]');
    if(!panel) return JSON.stringify({err:'NO_PANEL'});
    const setVal=(el,v)=>{const setter=Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype,'value').set;setter.call(el,v);el.dispatchEvent(new Event('input',{bubbles:true}));};
    setVal(panel.querySelector('input[aria-label="SSH 主机别名"]'),'aliyun');
    const connectBtn=[...panel.querySelectorAll('button')].find(b=>b.textContent.trim()==='连接');
    connectBtn.click();
    // 等路径输入出现且预填 $HOME/
    let pathInput=null;
    for(let i=0;i<30;i++){
      await new Promise(r=>setTimeout(r,1000));
      pathInput=panel.querySelector('[data-testid="ssh-path-input"]');
      if(pathInput&&pathInput.value==='/root/') break;
    }
    if(!pathInput) return JSON.stringify({step:'connect',err:'NO_PATH_INPUT',text:panel.textContent.slice(0,150)});
    // 等候选加载（/root 子目录）
    let hasCandidate=false;
    for(let i=0;i<20;i++){
      await new Promise(r=>setTimeout(r,500));
      if(panel.textContent.includes('/root/petri-block67-demo/')){ hasCandidate=true; break; }
    }
    // 终端式补全：打 /root/ge → Tab → 完整路径（含原生事件探针）
    const setter=Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype,'value').set;
    setter.call(pathInput,'/root/ge');
    pathInput.dispatchEvent(new Event('input',{bubbles:true}));
    await new Promise(r=>setTimeout(r,700));
    window.__tabSeen=false;
    pathInput.addEventListener('keydown',()=>{ window.__tabSeen=true; },{once:true});
    pathInput.dispatchEvent(new KeyboardEvent('keydown',{key:'Tab',bubbles:true,cancelable:true}));
    for(let j=0;j<16;j++){
      await new Promise(r=>setTimeout(r,500));
      if(pathInput.value==='/root/petri-block67-demo/') break;
    }
    return JSON.stringify({step:'pick',chip:chip0(),selected:pathInput.value,hasCandidate,tabSeen:window.__tabSeen});
    function chip0(){const c=panel.querySelector('[data-testid="ssh-connected-chip"]');return c?c.textContent.trim():'';}
  })()`, 120000);
  const s = JSON.parse(out);
  const step1ok = s.step === 'pick' && s.chip === 'aliyun' && s.hasCandidate === true;
  assert('向导① 连接主机（chip=aliyun）+ 路径输入预填 /root/ + 候选展示', step1ok && s.hasCandidate, out);
  assert('向导② Tab 补全 /root/ge → /root/petri-block67-demo/（onKeyDown 链）', s.tabSeen === true && s.selected === '/root/petri-block67-demo/', out);

  // —— 向导③：在此路径创建项目 → API 对账新项目 → 导航对账 ——
  await ev(c, `(async () => {
    const create=[...document.querySelectorAll('button')].find(b=>b.textContent.trim()==='在此路径创建项目');
    if(!create) return 'NO_CREATE_BTN:'+document.querySelector('[data-testid="ssh-path-input"]')?.value;
    create.click();
    return 'clicked';
  })()`, 20000);
  let created = null;
  for (let i = 0; i < 25; i += 1) {
    await new Promise((r) => setTimeout(r, 1000));
    const now = await req('http://127.0.0.1:3001/api/data/projects', { headers: { Authorization: 'Bearer desktop-local' } });
    const newSsh = (now.projects || []).find((p) => p.workspace_kind === 'ssh' && !beforeIds.has(p.id));
    if (newSsh) { created = newSsh; break; }
  }
  assert('向导③ 创建项目（API 对账：新 ssh 项目出现）', !!created, JSON.stringify(created && { id: created.id, name: created.name }));

  let navigatedOk = false;
  if (created) {
    for (let i = 0; i < 15; i += 1) {
      const state = await ev(c, `location.pathname`, 15000).catch(() => '');
      if (String(state).includes(created.id)) { navigatedOk = true; break; }
      await new Promise((r) => setTimeout(r, 1000));
    }
  }
  assert('导航进入新建项目页', navigatedOk, created ? `expect /project/${created.id}` : 'no project');

  const shot = await c.send('Page.captureScreenshot', { format: 'png' });
  fs.writeFileSync(path.join(EVIDENCE, 'ui327-wizard-live.png'), Buffer.from(shot.data, 'base64'));
  console.log('renderer errors:', errors.length);

  c.socket.close();
  const projects = await req('http://127.0.0.1:3001/api/data/projects', { headers: { Authorization: 'Bearer desktop-local' } });
  const mine = (projects.projects || []).filter((p) => p.workspace_kind === 'ssh' && !beforeIds.has(p.id));
  for (const p of mine) { await req('http://127.0.0.1:3001/api/data/projects/' + p.id, { method: 'DELETE', headers: { Authorization: 'Bearer desktop-local' } }); }
  console.log('cleaned probe projects:', mine.length);

  results.allPass = results.assertions.every((a) => a.pass);
  results.finishedAt = new Date().toISOString();
