    if (!tabState.ok) await new Promise((r) => setTimeout(r, 2000));
  }
  assert('S5c 右栏「知识」tab 可打开且 KnowledgeSpacePanel 渲染', tabState.ok && tabState.panel, JSON.stringify(tabState));

  const panelState = JSON.parse(await evalJS(client, `JSON.stringify({
    notice: document.querySelector('[data-testid="knowledge-embed-unavailable"]')?.textContent || '',
    toggle: !!document.querySelector('[data-testid="knowledge-toggle"]'),
    toggleDisabled: document.querySelector('[data-testid="knowledge-toggle"]')?.disabled ?? null,
    upload: !!document.querySelector('[data-testid="knowledge-upload"]'),
    searchInput: !!document.querySelector('[data-testid="knowledge-search-input"]'),
  })`));
  if (!results.embeddingKeyConfigured) {
    assert('S5d 无 key：面板诚实空态（DashScope notice + 开关禁用）',
      /DashScope/.test(panelState.notice) && panelState.toggleDisabled === true, JSON.stringify(panelState));
  }
  assert('S5e 面板核心控件齐备（上传/检索测试框）', panelState.upload && panelState.searchInput, JSON.stringify(panelState));

  // ── S2（无 key 分支）：启用请求被诚实拒绝（409），不假启用 ──
  const enableResp = await fetchJson(`${API}/knowledge/space`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ enabled: true }),
  });
  if (!results.embeddingKeyConfigured) {
    assert('S2a 无 key：启用端点 409 诚实拒绝（D7）', enableResp.status === 409 && /DashScope|嵌入/.test(enableResp.body.error || ''),
      `status=${enableResp.status} error=${enableResp.body.error}`);
    const spaceAfterDeny = await fetchJson(`${API}/knowledge/space`);
    assert('S2b 无 key：空间保持未启用', spaceAfterDeny.body.space.enabled === false, JSON.stringify(spaceAfterDeny.body.space));
  } else {
    assert('S2a 有 key：启用成功', enableResp.status === 200 && enableResp.body.space.enabled === true, JSON.stringify(enableResp.body));
    const keyDepEnable = enableResp;
    void keyDepEnable;
  }

  // ── S1：上传 md → 状态流转 ──
  const uploadResult = JSON.parse(await evalJS(client, `(async () => {
    try {
      const content = ${JSON.stringify(SAMPLE_MD)};
      const form = new FormData();
      form.append('files', new File([content], 'brca2-acceptance.md', { type: 'text/markdown' }));
      const resp = await fetch(${JSON.stringify(API)} + '/knowledge/documents', { method: 'POST', body: form });
      return JSON.stringify({ status: resp.status, body: await resp.json() });
    } catch (e) { return JSON.stringify({ status: 0, error: String(e) }); }
  })()`));
  const up = uploadResult.body || {};
  assert('S1a 上传端点接受 md 并建档', uploadResult.status === 200 && (up.accepted || []).length === 1, JSON.stringify(uploadResult).slice(0, 300));

  // 轮询状态至终态（failed 或 ready）
  let finalDoc = null;
  for (let i = 0; i < 30; i++) {
    await new Promise((r) => setTimeout(r, 1000));
    const docs = await fetchJson(`${API}/knowledge/documents`);
    finalDoc = (docs.body.documents || []).find((d) => d.name === 'brca2-acceptance.md');
    if (finalDoc && (finalDoc.status === 'ready' || finalDoc.status === 'failed')) break;
  }
  if (!finalDoc) throw new Error('upload_doc_not_found_after_poll');
  if (results.embeddingKeyConfigured) {
    assertKeyDep('S1b 上传 md → ready 且块数合理', finalDoc.status === 'ready' && finalDoc.chunkCount >= 1,
      JSON.stringify(finalDoc));
  } else {
    assert('S1b 无 key：文档诚实 failed 且 error 指向嵌入不可用（D7 不静默降级）',
      finalDoc.status === 'failed' && /嵌入|embed/i.test(finalDoc.error || ''), JSON.stringify(finalDoc));
  }

  // ── S3：检索测试框 ──
  const searchResp = await fetchJson(`${API}/knowledge/search`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ query: 'BRCA2 胰腺癌' }),
  });
  if (results.embeddingKeyConfigured) {
    assertKeyDep('S3 检索测试框 top-k 命中合理（双通道）',
      searchResp.body.hits.length >= 1 && searchResp.body.hits[0].docName === 'brca2-acceptance.md',
      JSON.stringify(searchResp.body.hits));
  } else {
    assert('S3a 无 key：检索端点诚实空（无就绪块）', searchResp.status === 200 && searchResp.body.hits.length === 0 && searchResp.body.readyChunks === 0,
      JSON.stringify(searchResp.body));
  }

  // UI 检索框：无 key 场景发查询 → 诚实提示（不崩）
  const uiSearch = JSON.parse(await evalJS(client, `(async () => {
    try {
      const input = document.querySelector('[data-testid="knowledge-search-input"]');
      const btn = document.querySelector('[data-testid="knowledge-search-btn"]');
      if (!input || !btn) return JSON.stringify({ ok: false, reason: 'missing_controls' });
      const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
      setter.call(input, 'BRCA2 胰腺癌');
      input.dispatchEvent(new Event('input', { bubbles: true }));
      await new Promise((r) => setTimeout(r, 300));
      btn.click();
      await new Promise((r) => setTimeout(r, 2500));
      const note = document.querySelector('[class*="searchNote"]')?.textContent || '';
      const hits = document.querySelectorAll('[data-testid="knowledge-search-hits"] > div').length;
      return JSON.stringify({ ok: true, note, hits });
    } catch (e) { return JSON.stringify({ ok: false, error: String(e) }); }
  })()`));
  assert('S3b UI 检索测试框可交互且诚实呈现（不崩）', uiSearch.ok === true, JSON.stringify(uiSearch).slice(0, 300));

  // ── S2c/S2d：真实对话命中 / 关闭后不再命中（唯一标记词，模型无法凭常识得知）──
  if (results.embeddingKeyConfigured) {
    await evalJS(client, `(async () => {
      const form = new FormData();
      form.append('files', new File([${JSON.stringify(MARKER_DOC_MD)}], 'marker-doc.md', { type: 'text/markdown' }));
      await fetch(${JSON.stringify(API)} + '/knowledge/documents', { method: 'POST', body: form });
      return 'seeded';
    })()`);
    const markerDoc = await pollDocReady('marker-doc.md', 60000);
    if (markerDoc.status !== 'ready') throw new Error('marker_doc_not_ready: ' + JSON.stringify(markerDoc));

    const replyOn = await agentReply(MARKER_QUESTION);
    assert('S2c 启用后对话命中知识（回复含标记数值 42.7）', /42\.7/.test(replyOn),
      `reply=${replyOn.slice(0, 200)}`);

    await fetchJson(`${API}/knowledge/space`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ enabled: false }),
    });
    const replyOff = await agentReply(MARKER_QUESTION);
    assert('S2d 关闭开关后同问题不再命中（回复不含 42.7）', !/42\.7/.test(replyOff),
      `reply=${replyOff.slice(0, 200)}`);
  }

  await screenshot(client, 'ui318-live-panel.png');

  // ── S4：删除（单事务两通道同灭）+ 清空两步确认 ──
  if (results.embeddingKeyConfigured) {
    const docsNow = await fetchJson(`${API}/knowledge/documents`);
    let delOk = true;
    for (const d of docsNow.body.documents || []) {
      const delResp = await fetchJson(`${API}/knowledge/documents/${encodeURIComponent(d.id)}`, { method: 'DELETE' });
      if (delResp.status !== 200) delOk = false;
    }
    assertKeyDep('S4a 删除文档成功（含标记文档）', delOk, `deleted=${(docsNow.body.documents || []).length}`);
    const searchAfterDel = await fetchJson(`${API}/knowledge/search`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ query: 'BRCA2 胰腺癌' }),
    });
    assertKeyDep('S4b 删除后两条检索通道均不再命中', searchAfterDel.body.hits.length === 0 && searchAfterDel.body.readyChunks === 0,
      JSON.stringify(searchAfterDel.body.readyChunks));
  } else {
    // 无 key：UI 删除入口存在且可执行（通道同灭断言需 key，复跑补齐）
    // 面板空闲态 10s 慢轮询——等 doc row 出现（≤15s）
    let rowSeen = false;
    for (let i = 0; i < 15; i++) {
      rowSeen = JSON.parse(await evalJS(client, `JSON.stringify({ rows: document.querySelectorAll('[data-testid="knowledge-doc-row"]').length })`)).rows > 0;
      if (rowSeen) break;
      await new Promise((r) => setTimeout(r, 1000));
    }
    assert('S4-pre 面板轮询出现已上传文档行（空闲慢刷 10s 生效）', rowSeen, 'waited up to 15s');
    const uiDelete = JSON.parse(await evalJS(client, `(async () => {
      try {
        const row = document.querySelector('[data-testid="knowledge-doc-row"]');
        if (!row) return JSON.stringify({ ok: false, reason: 'no_doc_row' });
        const del = [...row.querySelectorAll('button')].pop();
        del.click();
        await new Promise((r) => setTimeout(r, 2000));
        return JSON.stringify({ ok: true, rowsLeft: document.querySelectorAll('[data-testid="knowledge-doc-row"]').length });
      } catch (e) { return JSON.stringify({ ok: false, error: String(e) }); }
    })()`));
    assert('S4a 无 key：UI 文档行删除可执行', uiDelete.ok === true, JSON.stringify(uiDelete));

    const delApi = await fetchJson(`${API}/knowledge/documents`, { method: 'GET' });
    assert('S4b 无 key：删除后文档清单一致（诚实）', (delApi.body.documents || []).every((d) => d.name !== 'brca2-acceptance.md'),
      JSON.stringify(delApi.body.documents));
  }

  // 清空两步确认（UI）：第一次点击 = 确认文案，第二次 = 执行
  // 需要 documents.length>0 才渲染清空按钮 → 先经 REST 重建一份 failed/ready 文档，
  // 并等面板轮询到它（空闲 10s 慢刷）
  await evalJS(client, `(async () => {
    const form = new FormData();
    form.append('files', new File(['验收清空样本'], 'clear-sample.txt', { type: 'text/plain' }));
    await fetch(${JSON.stringify(API)} + '/knowledge/documents', { method: 'POST', body: form });
    await new Promise((r) => setTimeout(r, 1500));
    return 'seeded';
  })()`);
  let clearBtnSeen = false;
  for (let i = 0; i < 15; i++) {
    clearBtnSeen = JSON.parse(await evalJS(client, `JSON.stringify({ b: !!document.querySelector('[data-testid="knowledge-clear"]') })`)).b;
    if (clearBtnSeen) break;
    await new Promise((r) => setTimeout(r, 1000));
  }
  const clearTwoStep = JSON.parse(await evalJS(client, `(async () => {
    try {
      const btn = document.querySelector('[data-testid="knowledge-clear"]');
      if (!btn) return JSON.stringify({ ok: false, reason: 'no_clear_btn' });
      const rowsBefore = document.querySelectorAll('[data-testid="knowledge-doc-row"]').length;
      btn.click();
      await new Promise((r) => setTimeout(r, 400));
      const confirmText = btn.textContent || '';
      if (!confirmText.includes('确认清空')) return JSON.stringify({ ok: false, reason: 'no_confirm_step', text: confirmText });
      btn.click();
      await new Promise((r) => setTimeout(r, 3500));
      const rowsAfter = document.querySelectorAll('[data-testid="knowledge-doc-row"]').length;
      return JSON.stringify({ ok: true, confirmText, rowsBefore, rowsAfter });
    } catch (e) { return JSON.stringify({ ok: false, error: String(e) }); }
  })()`));
  assert('S4c 清空空间两步确认生效（先确认文案后执行清空）',
    clearTwoStep.ok === true && clearTwoStep.rowsBefore > 0 && clearTwoStep.rowsAfter === 0, JSON.stringify(clearTwoStep));

  await screenshot(client, 'ui318-live.png');

  results.blockedCount = results.keyDependentAssertions.filter((a) => a.status === 'blocked_on_dashscope_key').length;
  results.allPass = results.assertions.every((a) => a.pass)
    && results.keyDependentAssertions.every((a) => a.status === 'blocked_on_dashscope_key' || a.pass);
  results.finishedAt = new Date().toISOString();
  fs.writeFileSync(path.join(EVIDENCE_DIR, 'ui318-live.json'), JSON.stringify(results, null, 2) + '\n');
  log(`allPass=${results.allPass} blocked=${results.blockedCount}`);
  client.socket.close();
  process.exit(results.allPass ? 0 : 1);
}

main().catch((e) => { console.error('LIVE_ERR', e.message); process.exit(1); });

#!/usr/bin/env node
/**
 * BLOCK-70 实机验收（隔离探针）：mobile-gateway 真实起服双态全链。
 *
 * A1 关闭态 additive 红线：默认（无 env/无配置）起服 → 主后端健康、移动端口不监听
 * A2 启用态：PETRI_MOBILE_ENABLED=1 → gateway 健康
 * A3 静态移动页 /m/ 可达（独立 bundle，不进 Vite 图）
 * A4 管理 REST：主后端 /api/mobile/status 如实呈现 enabled/port
 * A5 配对 token + QR SVG（服务端渲染）
 * A6 手机配对：一次性 token → 会话；同 token 重放被拒
 * A7 授权读：Bearer 与 ?session= 双通道 → conversations 读面通；无凭证 401
 * A8 吊销即刻失效：主后端吊销 → 移动面下一请求 401
 * A9 审计日志落盘且不含会话 token（D9：只记元数据）
 *
 * 证据：acceptance/block-70/block70-mobile-gateway-live.json（token 全程脱敏不入证）
 */
import { spawn } from 'node:child_process';
import { existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, statSync, writeFileSync } from 'node:fs';
import net from 'node:net';
import { createServer } from 'node:net';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createRequire } from 'node:module';

import { applyMigrations, createCaptureEnv, stopServer } from './g0-rs-p4r-capture.mjs';

const require = createRequire(import.meta.url);
const Database = require('better-sqlite3');

const REPO_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const SERVER_ENTRY = path.join(REPO_ROOT, 'core', 'petri-server', 'server.js');
const EVIDENCE_PATH = path.join(REPO_ROOT, 'acceptance', 'block-70', 'block70-mobile-gateway-live.json');

const results = [];
function assert(name, ok, detail) {
  results.push({ name, ok: !!ok, detail: detail == null ? '' : String(detail).slice(0, 300) });
  console.log(`${ok ? 'PASS' : 'FAIL'} — ${name}${ok ? '' : ` :: ${String(detail).slice(0, 300)}`}`);
}

async function freePort() {
  return new Promise((resolve) => {
    const srv = createServer();
    srv.listen(0, '127.0.0.1', () => {
      const { port } = srv.address();
      srv.close(() => resolve(port));
    });
  });
}

function spawnServer(env) {
  const child = spawn(process.execPath, [SERVER_ENTRY], {
    env,
    cwd: REPO_ROOT,
    stdio: ['ignore', 'pipe', 'pipe'],
  });
  const logs = [];
  child.stdout.setEncoding('utf8');
  child.stderr.setEncoding('utf8');
  child.stdout.on('data', (chunk) => logs.push(chunk));
  child.stderr.on('data', (chunk) => logs.push(chunk));
  child.logs = logs;
  return child;
}

async function waitHealthy(baseUrl, timeoutMs = 45_000) {
  const startedAt = Date.now();
  let lastError = '';
  while (Date.now() - startedAt < timeoutMs) {
    try {
      const response = await fetch(`${baseUrl}/api/health`);
      if (response.ok) return true;
      lastError = `status ${response.status}`;
    } catch (error) {
      lastError = error.message;
    }
    await new Promise((resolve) => setTimeout(resolve, 500));
  }
  throw new Error(`server not healthy: ${lastError}`);
}

function isPortClosed(port) {
  return new Promise((resolve) => {
    const socket = new net.Socket();
    socket.setTimeout(1500);
    socket.once('connect', () => { socket.destroy(); resolve(false); });
    socket.once('timeout', () => { socket.destroy(); resolve(true); });
    socket.once('error', () => resolve(true));
    socket.connect(port, '127.0.0.1');
  });
}

async function main() {
  // ── A1 关闭态（additive 红线）───────────────────────────────────────
  const offRoot = mkdtempSync(path.join(os.tmpdir(), 'block70-off-'));
  const offMobilePort = await freePort();
  const offEnvRoot = createCaptureEnv({ root: offRoot, port: await freePort() });
  await applyMigrations(offEnvRoot.paths.PETRI_DB_PATH, { quiet: true });
  const offChild = spawnServer({ ...offEnvRoot.env, PETRI_MOBILE_PORT: String(offMobilePort) });
  const offBase = `http://127.0.0.1:${offEnvRoot.env.R_SERVER_PORT}`;
  try {
    await waitHealthy(offBase);
    const health = await (await fetch(`${offBase}/api/health`)).json();
    assert('A1a 关闭态主后端健康', health.status === 'ok', JSON.stringify(health).slice(0, 120));
    assert('A1b 关闭态移动端口不监听', await isPortClosed(offMobilePort), `port ${offMobilePort} should be closed`);
    const offStatus = await (await fetch(`${offBase}/api/mobile/status`)).json();
    assert('A1c 关闭态管理面如实呈现 enabled=false', offStatus.ok === true && offStatus.enabled === false, JSON.stringify(offStatus).slice(0, 160));
  } finally {
    await stopServer(offChild);
    rmSync(offRoot, { recursive: true, force: true });
  }

  // ── A2–A9 启用态全链 ────────────────────────────────────────────────
  const root = mkdtempSync(path.join(os.tmpdir(), 'block70-live-'));
  const mobilePort = await freePort();
  const envRoot = createCaptureEnv({ root, port: await freePort() });
  await applyMigrations(envRoot.paths.PETRI_DB_PATH, { quiet: true });
  const child = spawnServer({
    ...envRoot.env,
    PETRI_MOBILE_ENABLED: '1',
    PETRI_MOBILE_PORT: String(mobilePort),
  });
  const mainBase = `http://127.0.0.1:${envRoot.env.R_SERVER_PORT}`;
  const gatewayBase = `http://127.0.0.1:${mobilePort}`;
  let sessionId = null;
  try {
    await waitHealthy(mainBase);

    const gwHealth = await (await fetch(`${gatewayBase}/m/api/health`)).json();
    assert('A2 gateway 健康', gwHealth.ok === true && gwHealth.service === 'petri-mobile-gateway', JSON.stringify(gwHealth));

    const page = await fetch(`${gatewayBase}/m/`);
    const pageText = await page.text();
    assert('A3 移动页可达', page.status === 200 && pageText.includes('Petri · 移动工作区'), `status ${page.status}`);

    const status = await (await fetch(`${mainBase}/api/mobile/status`)).json();
    assert('A4 管理面 status 如实', status.ok === true && status.enabled === true && status.port === mobilePort, JSON.stringify({ ...status, devices: (status.devices || []).length }));

    const pairing = await (await fetch(`${mainBase}/api/mobile/pairing/token`, { method: 'POST' })).json();
    // 4bd0f0bd 起配对 URL 双形态：LAN 直连 = /m#t=（移动页）；隧道 connected = /pair?token=（桌面投影入口）
    assert('A5a 配对 token 签发', pairing.ok === true && /^http:\/\/.+\/(m#|pair\?token=)/.test(pairing.primaryUrl), JSON.stringify({ ...pairing, token: '***', urls: pairing.urls?.length }));
    const qr = await fetch(`${mainBase}/api/mobile/pairing/qr.svg?token=${encodeURIComponent(pairing.token)}`);
    assert('A5b QR SVG 渲染', qr.status === 200 && (qr.headers.get('content-type') || '').includes('image/svg+xml'), `status ${qr.status}`);

    const paired = await (await fetch(`${gatewayBase}/m/api/pair`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ token: pairing.token }),
    })).json();
    assert('A6a 手机配对成功', paired.ok === true && typeof paired.sessionToken === 'string' && paired.sessionToken.length >= 32);
    sessionId = paired.sessionId;
    const replay = await fetch(`${gatewayBase}/m/api/pair`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ token: pairing.token }),
    });
    assert('A6b 一次性 token 重放被拒', replay.status === 401, `status ${replay.status}`);

    const authed = await (await fetch(`${gatewayBase}/api/ai/conversations`, {
      headers: { Authorization: `Bearer ${paired.sessionToken}` },
    })).json();
    assert('A7a Bearer 授权读（conversations 投影）', authed.status === 'ok' && Array.isArray(authed.conversations), JSON.stringify(authed).slice(0, 140));
    const viaQuery = await (await fetch(`${gatewayBase}/api/ai/conversations?session=${encodeURIComponent(paired.sessionToken)}`)).json();
    assert('A7b ?session= 通道（EventSource 场景）', viaQuery.status === 'ok');
    const anonymous = await fetch(`${gatewayBase}/api/ai/conversations`);
    assert('A7c 无凭证 401', anonymous.status === 401, `status ${anonymous.status}`);

    const revoke = await (await fetch(`${mainBase}/api/mobile/devices/${encodeURIComponent(sessionId)}/revoke`, { method: 'POST' })).json();
    assert('A8a 主后端吊销成功', revoke.ok === true);
    const afterRevoke = await fetch(`${gatewayBase}/api/ai/conversations`, {
      headers: { Authorization: `Bearer ${paired.sessionToken}` },
    });
    assert('A8b 吊销后移动面即刻 401', afterRevoke.status === 401, `status ${afterRevoke.status}`);

    const auditPath = path.join(root, 'data', 'mobile', 'audit.log');
    const auditExists = existsSync(auditPath) && statSync(auditPath).size > 0;
    const auditRaw = auditExists ? readFileSync(auditPath, 'utf8') : '';
    assert('A9 审计落盘且不含 token', auditExists && auditRaw.includes('/m/api/pair') && !auditRaw.includes(paired.sessionToken), `exists=${auditExists}`);

    // ── B 系列：P2 控制面（发消息契约 / 取消 / 批准全链，真实 tool_jobs 行）──
    // A8 已吊销第一会话；此处再配对第二会话（同时证明吊销后可重新配对、多会话并存）。
    const pairing2 = await (await fetch(`${mainBase}/api/mobile/pairing/token`, { method: 'POST' })).json();
    const paired2 = await (await fetch(`${gatewayBase}/m/api/pair`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ token: pairing2.token }),
    })).json();
    assert('B0 吊销后可重新配对（第二会话）', paired2.ok === true && typeof paired2.sessionToken === 'string');
    const authHeaders = { Authorization: `Bearer ${paired2.sessionToken}`, 'Content-Type': 'application/json' };

    const sendAnon = await fetch(`${gatewayBase}/api/ai/agent`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ messages: [{ role: 'user', content: 'hi' }] }),
    });
    assert('B1a 发消息无会话 401', sendAnon.status === 401, `status ${sendAnon.status}`);
    const sendNoMessages = await fetch(`${gatewayBase}/api/ai/agent`, {
      method: 'POST', headers: authHeaders, body: JSON.stringify({}),
    });
    const sendNoMessagesBody = await sendNoMessages.json().catch(() => ({}));
    assert('B1b 发消息契约校验（会话通过、缺消息 400）', sendNoMessages.status === 400 && sendNoMessagesBody.error === '缺少消息', `status ${sendNoMessages.status} body ${JSON.stringify(sendNoMessagesBody).slice(0, 120)}`);

    const cancelAnon = await fetch(`${gatewayBase}/api/ai/agent/task/nonexistent/cancel`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' });
    assert('B2a 取消无会话 401', cancelAnon.status === 401, `status ${cancelAnon.status}`);
    const cancelUnknown = await fetch(`${gatewayBase}/api/ai/agent/task/nonexistent/cancel`, { method: 'POST', headers: authHeaders, body: '{}' });
    assert('B2b 取消未知任务结构化 404', cancelUnknown.status === 404, `status ${cancelUnknown.status}`);

    // 批准全链：向隔离 DB 插入两行 pending tool_job（真实 migrations schema）。
    const db = new Database(envRoot.paths.PETRI_DB_PATH);
    const columns = db.prepare('PRAGMA table_info(tool_jobs)').all();
    const columnNameSet = new Set(columns.map((column) => column.name));
    function insertPendingJob(id, ackToken, projectId) {
      const values = {
        id,
        tool_id: 'demo_tool',
        status: 'pending',
        ack_token: ackToken,
        ack_status: 'pending',
        // 必须与 auth.js LOCAL_USER.id 一字不差（09766808 修正 'local'→'local-user'
        // 后本探针未重采，decide 范围校验曾因此失配 404）
        user_id: 'local-user',
        project_id: projectId,
        created_at: Date.now(),
      };
      const usable = Object.keys(values).filter((key) => columnNameSet.has(key));
      const notNullNoDefault = columns
        .filter((column) => column.notnull && column.dflt_value === null && !usable.includes(column.name) && column.pk === 0)
        .map((column) => column.name);
      if (notNullNoDefault.length > 0) throw new Error(`tool_jobs has unfilled NOT NULL columns: ${notNullNoDefault.join(',')}`);
      db.prepare(`INSERT INTO tool_jobs (${usable.join(',')}) VALUES (${usable.map(() => '?').join(',')})`)
        .run(...usable.map((key) => values[key]));
    }
    insertPendingJob('b70_job_approve', 'b70_ack_approve', 'p_b70');
    insertPendingJob('b70_job_reject', 'b70_ack_reject', 'p_b70');

    const decideAnon = await fetch(`${gatewayBase}/m/api/approvals/b70_ack_approve/decide`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ approve: true, projectId: null, conversationId: null }),
    });
    assert('B3a 批准无会话 401', decideAnon.status === 401, `status ${decideAnon.status}`);

    const missingScope = await fetch(`${gatewayBase}/m/api/approvals/b70_ack_approve/decide`, {
      method: 'POST', headers: authHeaders, body: JSON.stringify({ approve: true }),
    });
    assert('B3b 批准缺 scope 400（与桌面 REST 同契约）', missingScope.status === 400, `status ${missingScope.status}`);

    const scopeMismatch = await fetch(`${gatewayBase}/m/api/approvals/b70_ack_approve/decide`, {
      method: 'POST', headers: authHeaders, body: JSON.stringify({ approve: true, projectId: 'p_other', conversationId: null }),
    });
    assert('B3c scope 不匹配 404（权限不放大）', scopeMismatch.status === 404, `status ${scopeMismatch.status}`);

    const approveRes = await fetch(`${gatewayBase}/m/api/approvals/b70_ack_approve/decide`, {
      method: 'POST', headers: authHeaders, body: JSON.stringify({ approve: true, projectId: 'p_b70', conversationId: null }),
    });
    const approveBody = await approveRes.json().catch(() => ({}));
    assert('B3d 手机批准放行', approveRes.status === 200 && approveBody.ok === true && approveBody.ackStatus === 'approved', `status ${approveRes.status} body ${JSON.stringify(approveBody).slice(0, 140)}`);
    const approvedRow = db.prepare('SELECT ack_status, status FROM tool_jobs WHERE id=?').get('b70_job_approve');
    assert('B3e 批准落库 ack_status=approved 且 job 状态不被破坏', approvedRow && approvedRow.ack_status === 'approved' && approvedRow.status === 'pending', JSON.stringify(approvedRow));

    const rejectRes = await fetch(`${gatewayBase}/m/api/approvals/b70_ack_reject/decide`, {
      method: 'POST', headers: authHeaders, body: JSON.stringify({ approve: false, projectId: 'p_b70', conversationId: null }),
    });
    assert('B4a 手机拒绝成功', rejectRes.status === 200, `status ${rejectRes.status}`);
    const rejectedRow = db.prepare('SELECT ack_status, status, error FROM tool_jobs WHERE id=?').get('b70_job_reject');
    assert('B4b 拒绝落库 ack_status=rejected + job failed', rejectedRow && rejectedRow.ack_status === 'rejected' && rejectedRow.status === 'failed', JSON.stringify(rejectedRow));
    db.close();
  } finally {
    await stopServer(child);
    if (sessionId) rmSync(path.join(root, 'mobile', 'sessions.json'), { force: true });
    rmSync(root, { recursive: true, force: true });
  }

  const allPass = results.every((entry) => entry.ok);
  const evidence = {
    schemaVersion: 1,
    acceptanceId: 'BLOCK-70-A1-P0-P1-LIVE',
    generatedAt: new Date().toISOString(),
    qualificationEligible: false,
    allPass,
    checks: results,
    notes: {
      method: 'isolated probe: real petri-server child processes (off-state + on-state), fresh tmp dataDir, migrations applied',
      redaction: 'pairing/session tokens never stored in evidence',
      honestBoundary: 'real-phone scan acceptance pending user; settings-panel CDP assertion pending dev-stack window',
    },
  };
  mkdirSync(path.dirname(EVIDENCE_PATH), { recursive: true });
  writeFileSync(EVIDENCE_PATH, `${JSON.stringify(evidence, null, 2)}\n`, 'utf8');
  console.log(`\n${allPass ? 'ALL PASS' : 'FAILED'} — ${results.filter((entry) => entry.ok).length}/${results.length}`);
  console.log(`evidence: ${EVIDENCE_PATH}`);
  if (!allPass) process.exitCode = 1;
}

main().catch(async (error) => {
  console.error('[block70-live] FAIL —', error.message);
  process.exitCode = 1;
});

#!/usr/bin/env node
/**
 * BLOCK-70 P3 实机验收：aliyun 反向隧道（真实 ssh -R，穿远端回环验证）。
 *
 * 前置：本机 ~/.ssh/config 有免密 Host `aliyun`（root@ECS）。
 *
 * T1 关闭态：tunnel 默认 disabled，不起 ssh
 * T2 启用态：写入 tunnel.json（enabled/host=aliyun/随机远端端口）→ REST reload →
 *    /api/mobile/tunnel 状态进入 connected（≤20s）
 * T3 端到端穿隧道：ssh aliyun 'curl http://127.0.0.1:<remotePort>/m/api/health'
 *    → 返回 mobile-gateway health（转发真实成立，且此刻无需 aliyun 反代）
 * T4 无凭证经隧道访问受保护面 → 401（隧道不放大攻击面）
 * T5 配对 URL 公网优先：primaryUrl = https://<publicIp>/m#...（隧道 connected 时）
 * T6 韧性：杀 ssh 进程 → reconnecting → 自动重连回 connected
 * T7 停用 → disabled 且 ssh 进程消失
 *
 * 证据：acceptance/block-70/block70-tunnel-live.json（token 脱敏）
 */
import { execSync, spawn } from 'node:child_process';
import fs from 'node:fs';
import http from 'node:http';
import net from 'node:net';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import { applyMigrations, createCaptureEnv, stopServer } from './g0-rs-p4r-capture.mjs';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const SERVER_ENTRY = path.join(ROOT, 'core', 'petri-server', 'server.js');
const EVIDENCE_PATH = path.join(ROOT, 'acceptance', 'block-70', 'block70-tunnel-live.json');
const TUNNEL_HOST = process.env.B70_TUNNEL_HOST || 'aliyun';

const results = [];
function assert(name, ok, detail) {
  results.push({ name, ok: !!ok, detail: detail == null ? '' : String(detail).slice(0, 300) });
  console.log((ok ? 'PASS' : 'FAIL') + ' — ' + name + (ok ? '' : ' :: ' + String(detail).slice(0, 300)));
}
function sleep(ms) { return new Promise((r) => setTimeout(r, ms)); }

function fetchJson(url) {
  return new Promise((resolve, reject) => {
    http.get(url, (res) => {
      let d = '';
      res.on('data', (c) => (d += c));
      res.on('end', () => {
        try { resolve(JSON.parse(d)); } catch (e) { reject(new Error(`non-json from ${url}: ${d.slice(0, 120)}`)); }
      });
    }).on('error', reject);
  });
}

async function freePort() {
  return new Promise((resolve) => {
    const srv = net.createServer();
    srv.listen(0, '127.0.0.1', () => {
      const { port } = srv.address();
      srv.close(() => resolve(port));
    });
  });
}

function sshQuiet(host, command, timeoutMs = 20000) {
  return execSync(`ssh -o BatchMode=yes -o ConnectTimeout=10 ${host} ${JSON.stringify(command)}`, {
    encoding: 'utf8',
    timeout: timeoutMs,
    stdio: ['ignore', 'pipe', 'pipe'],
  });
}

async function main() {
  const envRoot = createCaptureEnv({ port: await freePort() });
  const root = envRoot.root;
  const dataDir = envRoot.env.PETRI_LOCAL_DATA_DIR;
  await applyMigrations(envRoot.env.PETRI_DB_PATH, { quiet: true });

  const gatewayPort = await freePort();
  const remotePort = await freePort();
  fs.mkdirSync(path.join(dataDir, 'mobile'), { recursive: true });

  const child = spawn(process.execPath, [SERVER_ENTRY], {
    env: {
      ...envRoot.env,
      PETRI_MOBILE_ENABLED: '1',
      PETRI_MOBILE_PORT: String(gatewayPort),
    },
    cwd: ROOT,
    stdio: ['ignore', 'ignore', 'ignore'],
  });
  const mainBase = `http://127.0.0.1:${envRoot.env.R_SERVER_PORT}`;
  const startedAt = Date.now();
  while (Date.now() - startedAt < 45000) {
    try {
      const health = await fetchJson(`${mainBase}/api/health`);
      if (health.status === 'ok') break;
    } catch { /* retry */ }
    await sleep(500);
  }

  try {
    // T1 关闭态基线（tunnel.json 未写）
    const tunnelOff = await fetchJson(`${mainBase}/api/mobile/tunnel`);
    assert('T1_tunnel_defaults_disabled', tunnelOff.ok === true && tunnelOff.tunnel.enabled === false && tunnelOff.tunnel.state === 'disabled', JSON.stringify(tunnelOff.tunnel));

    // T2 启用（REST config reload——与产品同路径）
    const applyRes = await fetch(`${mainBase}/api/mobile/tunnel/config`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ enabled: true, host: TUNNEL_HOST, remotePort, localPort: gatewayPort, publicUrl: 'https://112.120.48.126' }),
    });
    const applied = await applyRes.json();
    assert('T2a_config_applied', applied.ok === true && applied.tunnel.enabled === true && applied.tunnel.host === TUNNEL_HOST, JSON.stringify(applied.tunnel));

    let connected = false;
    let lastStatus = null;
    for (let i = 0; i < 40; i += 1) {
      lastStatus = await fetchJson(`${mainBase}/api/mobile/tunnel`);
      if (lastStatus.tunnel.state === 'connected') { connected = true; break; }
      await sleep(500);
    }
    assert('T2_tunnel_connected', connected, JSON.stringify(lastStatus && lastStatus.tunnel));

    // T3 端到端：从 aliyun 回环穿隧道打 gateway（无需反代即证明转发成立）
    const loopbackHealth = execSync(`ssh -o BatchMode=yes -o ConnectTimeout=10 ${TUNNEL_HOST} "curl -s -m 5 http://127.0.0.1:${remotePort}/m/api/health"`, { encoding: 'utf8', timeout: 20000, stdio: ['ignore', 'pipe', 'pipe'] });
    const health = JSON.parse(loopbackHealth);
    assert('T3_end_to_end_through_tunnel', health.ok === true && health.service === 'petri-mobile-gateway', loopbackHealth.slice(0, 160));

    // T4 隧道不放大攻击面：无会话访问受保护面 → 401
    const unauthorized = execSync(`ssh -o BatchMode=yes -o ConnectTimeout=10 ${TUNNEL_HOST} "curl -s -o /dev/null -w '%{http_code}' -m 5 http://127.0.0.1:${remotePort}/api/ai/conversations"`, { encoding: 'utf8', timeout: 20000, stdio: ['ignore', 'pipe', 'pipe'] });
    assert('T4_protected_route_401_via_tunnel', String(unauthorized).trim() === '401', unauthorized.slice(0, 60));

    // T5 配对 URL 公网优先
    const pairing = await (await fetch(`${mainBase}/api/mobile/pairing/token`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' })).json();
    assert('T5_pairing_prefers_public_url', pairing.ok === true && pairing.primaryUrl.startsWith('https://112.120.48.126/m#'), pairing.primaryUrl.replace(/#.{20,}/, '#***'));

    // T6 韧性：杀 ssh → reconnecting → 自动重连回 connected（新 pid）
    const statusBeforeKill = await fetchJson(`${mainBase}/api/mobile/tunnel`);
    if (statusBeforeKill.tunnel.pid) {
      try { process.kill(statusBeforeKill.tunnel.pid); } catch { /* 已退出也可 */ }
    }
    let reconnected = false;
    for (let i = 0; i < 40; i += 1) {
      const status = await fetchJson(`${mainBase}/api/mobile/tunnel`);
      if (status.tunnel.state === 'connected' && status.tunnel.pid !== statusBeforeKill.tunnel.pid) { reconnected = true; break; }
      await sleep(500);
    }
    assert('T6_auto_reconnect_after_kill', reconnected, JSON.stringify(lastStatus && lastStatus.tunnel));

    // T7 停用 → disabled
    const disableRes = await fetch(`${mainBase}/api/mobile/tunnel/config`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ enabled: false }),
    });
    const disabled = await disableRes.json();
    assert('T7_disable_stops_tunnel', disabled.ok === true && disabled.tunnel.state === 'disabled', JSON.stringify(disabled.tunnel));
  } finally {
    await stopServer(child);
    await sleep(1000);
    fs.rmSync(root, { recursive: true, force: true });
  }

  const allPass = results.every((entry) => entry.ok);
  const evidence = {
    schemaVersion: 1,
    acceptanceId: 'BLOCK-70-P3-TUNNEL-LIVE',
    generatedAt: new Date().toISOString(),
    qualificationEligible: false,
    allPass,
    checks: results,
    notes: {
      method: 'real ssh -R reverse tunnel to user aliyun host; end-to-end via remote loopback curl (nginx not required for this proof)',
      redaction: 'pairing tokens masked in evidence',
      honestBoundary: 'public 443 exposure requires aliyun-side reverse proxy (self-signed TLS) + security-group; real-phone external-network scan pending user',
    },
  };
  fs.mkdirSync(path.dirname(EVIDENCE_PATH), { recursive: true });
  fs.writeFileSync(EVIDENCE_PATH, `${JSON.stringify(evidence, null, 2)}\n`);
  console.log(`\n${allPass ? 'ALL PASS' : 'FAILED'} — ${results.filter((entry) => entry.ok).length}/${results.length}`);
  console.log(`evidence: ${EVIDENCE_PATH}`);
  if (!allPass) process.exitCode = 1;
}

main().catch((error) => {
  console.error('[block70-tunnel-live] FAIL —', error.message);
  process.exitCode = 1;
});

#!/usr/bin/env node
'use strict';

/**
 * BLOCK-76 P1 实机验证（plan §6 P1 出口：真实节点上插件作业服务器直跑成功）。
 *
 * 链路：REST 创建 dell SSH 项目 → POST /api/tools/run 跑真插件 deseq2（demo 数据）
 * → 轮询至终态 → 断言：
 *   A1 作业 completed
 *   A2 result_json.workspaceKind='ssh' + outputPath=results/jobs/<jobId>/output + transport=gateway-ssh-direct
 *   A3 服务器真值：results/jobs/<jobId>/output/ 有 all_results.zip + run.log（ssh 直查）
 *   A4 本地 staging 无产物拉回（直跑核心语义；remote-runner.log 镜像除外）
 * 前置：dev 栈在跑（9222/3001，后端须已加载 P1 代码）；ssh dell 可达（有 Rscript + DESeq2）。
 * 证据：acceptance/block-76/p1-live.json
 */
const path = require('node:path');
const fs = require('node:fs');
const http = require('node:http');
const { execFileSync } = require('node:child_process');

const REPO = path.join(__dirname, '..');
const EVIDENCE = path.join(REPO, 'acceptance', 'block-76');
const API = 'http://127.0.0.1:3001/api';
const AUTH = { Authorization: 'Bearer desktop-local', 'content-type': 'application/json' };
const REMOTE_ROOT = '/root/petri-block76-demo';
const MARKER = 'B76-' + Date.now();

function fetchJson(url, opts = {}) {
  return new Promise((resolve, reject) => {
    const req = http.request(url, { method: opts.method || 'GET', headers: opts.headers || {} }, (res) => {
      let d = '';
      res.on('data', (c) => (d += c));
      res.on('end', () => {
        try { resolve(JSON.parse(d)); } catch (e) { resolve({ raw: d.slice(0, 200), status: res.statusCode }); }
      });
    });
    req.on('error', reject);
    if (opts.body) req.write(opts.body);
    req.end();
  });
}

function sshDell(cmd) {
  return execFileSync('ssh', ['-o', 'BatchMode=yes', '-o', 'ConnectTimeout=10', 'dell', cmd], { encoding: 'utf8', timeout: 30000, windowsHide: true });
}

function b64file(p) {
  return fs.readFileSync(p).toString('base64');
}

async function main() {
  fs.mkdirSync(EVIDENCE, { recursive: true });
  const results = { startedAt: new Date().toISOString(), marker: MARKER, assertions: [] };
  const assert = (name, pass, detail = '') => {
    results.assertions.push({ name, pass: !!pass, detail: String(detail).slice(0, 500) });
    try { fs.writeSync(1, "[" + new Date().toISOString().slice(11, 19) + "] " + (pass ? "PASS" : "FAIL") + " " + name + (detail ? " :: " + String(detail).slice(0, 160) : "") + String.fromCharCode(10)); } catch {}
  };
  const delay = (ms) => new Promise((r) => setTimeout(r, ms));
  let projectId = null;

  try {
    // 0) 节点预检 + 远端项目目录
    sshDell(`mkdir -p ${REMOTE_ROOT} && which Rscript`);
    assert('P1-0 dell node ready (Rscript + project dir)', true, REMOTE_ROOT);

    // 1) REST 创建 SSH 项目（dell）
    const created = await fetchJson(`${API}/data/projects`, {
      method: 'POST', headers: AUTH,
      body: JSON.stringify({ name: `P1直跑-${MARKER}`, workspaceKind: 'ssh', sshHost: 'dell', remotePath: REMOTE_ROOT }),
    });
    projectId = created.project && created.project.id;
    assert('P1-1 ssh project created (dell)', !!projectId, JSON.stringify(created).slice(0, 160));
    if (!projectId) throw new Error('project create failed');

    // 2) 直跑链：POST /api/tools/run 跑 deseq2（demo 数据）
    const run = await fetchJson(`${API}/tools/run`, {
      method: 'POST', headers: AUTH,
      body: JSON.stringify({
        toolId: 'deseq2',
        projectId,
        params: { design: 'condition', contrast_ref: 'WT', contrast_treat: 'KO' },
        files: {
          'counts.csv': b64file(path.join(REPO, 'resources', 'demo-data', 'deseq2', 'demo-counts.csv')),
          'coldata.csv': b64file(path.join(REPO, 'resources', 'demo-data', 'deseq2', 'demo-coldata.csv')),
        },
      }),
    });
    const jobId = run.jobId;
    assert('P1-2 tool job submitted', !!jobId, JSON.stringify(run).slice(0, 160));
    if (!jobId) throw new Error('job submit failed');

    // 3) 轮询终态（直跑链含心跳；demo 数据秒级，给 4 分钟预算）
    let status = null;
    const deadline = Date.now() + 4 * 60 * 1000;
    while (Date.now() < deadline) {
      await delay(4000);
      status = await fetchJson(`${API}/tools/status/${jobId}`, { headers: AUTH });
      const st = status.status || (status.job && status.job.status);
      if (st === 'completed' || st === 'failed' || st === 'cancelled') break;
    }
    const finalStatus = status && (status.status || (status.job && status.job.status));
    assert('P1-3 job reaches terminal (completed)', finalStatus === 'completed', `status=${finalStatus} detail=${JSON.stringify(status).slice(0, 220)}`);

    // 4) result_json 语义（R4：workspaceKind + 相对 outputPath + 直跑 transport）
    const rj = status && (status.result || status.result_json || (status.job && status.job.result_json));
    let parsed = rj;
    if (typeof rj === 'string') { try { parsed = JSON.parse(rj); } catch {} }
    assert('P1-4 result_json ssh semantics', !!parsed && parsed.workspaceKind === 'ssh'
      && parsed.outputPath === `results/jobs/${jobId}/output`
      && parsed.transport === 'gateway-ssh-direct',
    JSON.stringify({ workspaceKind: parsed && parsed.workspaceKind, outputPath: parsed && parsed.outputPath, transport: parsed && parsed.transport }).slice(0, 220));

    // 5) 服务器真值：output/ 有 all_results.zip + run.log（ssh 直查，不经本地）
    let remoteListing = '';
    try {
      remoteListing = sshDell(`ls -1 ${REMOTE_ROOT}/results/jobs/${jobId}/output/ 2>/dev/null`);
    } catch (e) {
      remoteListing = 'SSH_ERR ' + e.message.slice(0, 80);
    }
    const remoteFiles = remoteListing.split('\n').map((s) => s.trim()).filter(Boolean);
    assert('P1-5 server output dir has artifacts', remoteFiles.includes('run.log') && remoteFiles.length >= 3,
      `remote output: [${remoteFiles.join(', ').slice(0, 200)}]`);

    // 6) 本地无拉回：staging output 不存在 all_results.zip（仅允许 remote-runner.log 镜像）
    const localDataRoot = path.join(REPO, '.petri-dev-user-data', 'data', 'remote-projects', projectId, 'results', 'jobs', jobId, 'output');
    let localFiles = [];
    try { localFiles = fs.readdirSync(localDataRoot); } catch { /* 目录不存在 = 更干净 */ }
    const pulledArtifacts = localFiles.filter((f) => f !== 'remote-runner.log');
    assert('P1-6 no artifact pull-back to local staging', pulledArtifacts.length === 0,
      `local output files: [${localFiles.join(', ').slice(0, 160) || 'dir absent'}]`);
  } finally {
    // 清理：删项目 + 远端目录
    if (projectId) {
      await fetchJson(`${API}/data/projects/${projectId}`, { method: 'DELETE', headers: AUTH }).catch(() => {});
    }
    try { sshDell(`rm -rf ${REMOTE_ROOT}`); } catch {}
  }

  const allPass = results.assertions.length > 0 && results.assertions.every((a) => a.pass);
  results.allPass = allPass;
  results.finishedAt = new Date().toISOString();
  fs.writeFileSync(path.join(EVIDENCE, 'p1-live.json'), JSON.stringify(results, null, 2) + '\n');
  process.exit(allPass ? 0 : 1);
}

main().catch((e) => { console.error('LIVE_ERR', e.message); process.exit(1); });

#!/usr/bin/env node
'use strict';

/**
 * BLOCK-76 P2 实机验证（读面全量 Gateway 化的主链断言，plan §6 P2 出口）。
 *   A1 dell SSH 项目 + deseq2 直跑作业 completed（P1 链复用）
 *   A2 /api/tools/file/:jobId/deg_table.csv → 200 且内容为服务器真值（csv 含逗号表头）
 *   A3 /api/tools/log/:id → 服务器 run.log 尾部（含 source=run.log / live 标记）
 *   A4 POST /api/tools/report/:jobId → 报告生成且 report.html 已写回服务器 output/
