#!/usr/bin/env node
'use strict';

/**
 * BLOCK-77 P4 实机全链验收（两阶段，外层 bash 编排关软件/重开）：
 *
 * phase1:
 *   REST 建 aliyun SSH 项目 → CDP 真实模型对话（resident_task_create 挂机 sleep）
 *   → 断言意图卡落服务器 + 进程存活 → 记录 taskId/pid → 写状态文件
 * phase2（外层已重启软件 = 重开交接班）:
 *   CDP 真实对话：agent 应主动汇报驻留任务（systemPrompt 注入 digest）
 *   → ssh kill 驻留进程（异常路径）→ 回访循环翻转 failed
 *   → 再对话：agent 汇报失败状态（R5 不自动重启）→ 清理
 *
 * 证据：acceptance/block-77/p4-live.json + 截图
 */
const path = require('node:path');
const fs = require('node:fs');
const http = require('node:http');
const { execFileSync } = require('node:child_process');

const REPO = path.join(__dirname, '..');
const EVIDENCE = path.join(REPO, 'acceptance', 'block-77');
const API = 'http://127.0.0.1:3001/api';
const AUTH = { Authorization: 'Bearer desktop-local', 'content-type': 'application/json' };
const REMOTE_ROOT = '/root/petri-block77-demo';
const STATE = path.join(EVIDENCE, 'p4-state.json');
const PHASE = process.argv[2] || 'phase1';

const results = { startedAt: new Date().toISOString(), phase: PHASE, assertions: [] };
try {
  const prev = JSON.parse(fs.readFileSync(path.join(EVIDENCE, 'p4-live.json'), 'utf8'));
  if (prev.phase === 'phase1' && PHASE === 'phase2') results.prevAssertions = prev.assertions;
} catch {}

function assert(name, pass, detail = '') {
  results.assertions.push({ name, pass: !!pass, detail: String(detail).slice(0, 400) });
  try { fs.writeSync(1, '[p4-' + PHASE.slice(-1) + '] ' + (pass ? 'PASS' : 'FAIL') + ' ' + name + ' :: ' + String(detail).slice(0, 150) + '\n'); } catch {}
}
const delay = (ms) => new Promise((r) => setTimeout(r, ms));

function fetchRaw(url, opts = {}) {
  return new Promise((resolve, reject) => {
    const req = http.request(url, { method: opts.method || 'GET', headers: opts.headers || {} }, (res) => {
      const chunks = [];
      res.on('data', (c) => chunks.push(c));
      res.on('end', () => resolve({ status: res.statusCode, body: Buffer.concat(chunks) }));
    });
    req.on('error', reject);
    if (opts.body) req.write(opts.body);
    req.end();
  });
}
async function fetchJson(url, opts = {}) {
  const r = await fetchRaw(url, opts);
  try { return { status: r.status, json: JSON.parse(r.body.toString('utf8')) }; } catch { return { status: r.status, json: null }; }
}
function sshDell(cmd) {
  return execFileSync('ssh', ['-o', 'BatchMode=yes', '-o', 'ConnectTimeout=10', 'aliyun', cmd], { encoding: 'utf8', timeout: 30000, windowsHide: true });
}

// CDP 对话驱动（block67-p2-live 同款）
let lib = null;
async function connectMain(projectId) {
  const targets = await lib.pollTargets({ timeoutMs: 15000 });
  const pages = lib.filterPageTargets(targets, /localhost:3000/);
  if (!pages.length) throw new Error('no_spa_page');
  const main = await lib.selectPageTarget(pages, {
    probe: (client) => lib.evalJs(client, '!!document.querySelector(\'textarea.sc-input\')', 5000).catch(() => false),
  });
  const client = await lib.connectTarget(main);
  await client.send('Page.navigate', { url: `http://localhost:3000/project/${projectId}` }).catch(() => {});
  let ok = false;
  for (let i = 0; i < 30 && !ok; i++) {
    ok = await lib.evalJs(client, '!!document.querySelector(\'textarea.sc-input\')').catch(() => false);
    if (!ok) await delay(1000);
  }
  if (!ok) throw new Error('app_not_interactive');
  await delay(2500);
  return client;
}

async function listConversationMessages(projectId) {
  const convs = await fetchJson(`${API}/ai/conversations?status=all&project_id=${encodeURIComponent(projectId)}`, { headers: AUTH });
  const list = (convs.json && convs.json.conversations) || [];
  if (!list.length) return { conversationId: null, messages: [] };
  const conv = list[0];
  const msgs = await fetchJson(`${API}/ai/conversations/${encodeURIComponent(conv.id)}/messages?limit=100`, { headers: AUTH });
  return { conversationId: conv.id, messages: (msgs.json && msgs.json.messages) || [] };
}

// 回复确认改走 REST 真值（2026-09-11 抓真修两处：①原 DOM 抓取选择器对当前
// SimpleChat 消息类名失效——sc-msg-assistant 只匹配任务循环摘要卡，5+1 轮
// 全部 reply= 空全是脚本问题而非功能问题；②上一 turn 流式状态未复位时发送
// 按钮 disabled，先等 UI 空闲再填再点，重试间隔 4s，每次尝试结果记录在案）。
async function sendAndWaitReply(client, prompt, projectId) {
  const attempts = [];
  // ① 等 UI 空闲（发送按钮可用）——上一 turn streaming 未复位时点不动
  const tIdle = Date.now();
  while (Date.now() - tIdle < 90000) {
    const st = await lib.evalJs(client, `(() => {
      const b = [...document.querySelectorAll('button')].find((x) => (x.getAttribute('aria-label') || x.title || '').includes('发送消息'));
      return b ? (b.disabled ? 'disabled' : 'ready') : 'no_button';
    })()`, 5000).catch((e) => 'eval_err:' + String(e.message).slice(0, 40));
    attempts.push(st + '@' + new Date().toISOString().slice(11, 19));
    if (st === 'ready') break;
    await delay(4000);
  }
  const baseline = await listConversationMessages(projectId);
  const baselineAssistant = baseline.messages.filter((m) => m.role === 'assistant').length;
  const sendExpr = `(async () => {
    const ta = document.querySelector('textarea.sc-input');
    if (!ta) return 'no_textarea';
    const setter = Object.getOwnPropertyDescriptor(window.HTMLTextAreaElement.prototype, 'value').set;
    setter.call(ta, ${JSON.stringify(prompt)});
    ta.dispatchEvent(new Event('input', { bubbles: true }));
    await new Promise((r) => setTimeout(r, 400));
    const send = [...document.querySelectorAll('button')].find((b) => (b.getAttribute('aria-label') || b.title || '').includes('发送消息'));
    if (!send || send.disabled) return 'send_unavailable';
    send.click();
    return 'sent';
  })()`;
  let sent = false;
  for (let a = 0; a < 3 && !sent; a += 1) {
    try {
      const r = await lib.evalJs(client, sendExpr, 10000);
      attempts.push('try' + a + '=' + r);
      if (r === 'sent') sent = true;
    } catch (e) { attempts.push('try' + a + '=err:' + String(e.message).slice(0, 40)); }
    if (!sent) await delay(4000);
  }
  if (!sent) return { text: '', conversationId: baseline.conversationId, attempts: attempts.join(',') };
  // ② REST 轮询真值：等新 assistant 消息落库且内容连续两轮（6s）稳定
  const t0 = Date.now();
  let lastText = '';
  let stableSince = 0;
  let convId = baseline.conversationId;
  while (Date.now() - t0 < 240000) {
    await delay(3000);
    const snapshot = await listConversationMessages(projectId).catch(() => null);
    if (!snapshot) continue;
    convId = snapshot.conversationId || convId;
    const assistants = snapshot.messages.filter((m) => m.role === 'assistant' && !m.pending);
    if (assistants.length <= baselineAssistant) { stableSince = 0; lastText = ''; continue; }
    const latest = String(assistants[assistants.length - 1].content || '').trim();
    if (latest && latest === lastText) {
      stableSince += 3000;
      if (stableSince >= 6000) return { text: latest, conversationId: convId, attempts: attempts.join(',') };
    } else stableSince = 0;
    lastText = latest;
  }
  return { text: lastText, conversationId: convId, attempts: attempts.join(',') };
}

async function createProject(name) {
  sshDell(`rm -rf ${REMOTE_ROOT} && mkdir -p ${REMOTE_ROOT}`);
  const created = await fetchJson(`${API}/data/projects`, {
    method: 'POST', headers: AUTH,
    body: JSON.stringify({ name, workspaceKind: 'ssh', sshHost: 'aliyun', remotePath: REMOTE_ROOT }),
  });
  const projectId = created.json && created.json.project && created.json.project.id;
  assert('project created', !!projectId, JSON.stringify(created.json || created).slice(0, 120));
  return projectId;
}

async function main() {
  fs.mkdirSync(EVIDENCE, { recursive: true });
  const libPath = path.join(REPO, '.agents', 'skills', 'petri-dev-infra', 'dev-verify', 'lib.cjs');
  lib = require(libPath);
  let projectId = null;

  if (PHASE === 'phase1') {
    // ── ① 建 aliyun SSH 项目 ──
    projectId = await createProject(`P4驻留-${Date.now()}`);
    if (!projectId) process.exit(1);
    const client = await connectMain(projectId);

    // ── ② 真实模型对话：挂机 sleep 900 ──
    const prompt = [
      '请用 resident_task_create 工具创建一个驻留任务，参数：',
      'command 填：sleep 900 && echo done > .petri/resident/p4-done.txt',
      'intent 填：P4 全链验收：挂机 15 分钟探针',
      'success_criteria 填：900 秒后 p4-done.txt 出现',
      'failure_handling 填：notify-only',
      '创建完成后告诉我 taskId。',
    ].join('\n');
    const reply = await sendAndWaitReply(client, prompt, projectId);
    const replyText = String(reply.text);
    const taskIdMatch = replyText.match(/res_[0-9a-z_]+/);
    assert('P4-1 agent created resident task (model used tool)', !!taskIdMatch,
      `reply=${replyText.slice(0, 160)} | attempts=${reply.attempts || ''}`);
    if (!taskIdMatch) {
      await lib.screenshotPng(client, EVIDENCE, 'p4-no-card.png').catch(() => {});
      saveAndExit(projectId, null);
      return;
    }
    const taskId = taskIdMatch[0];

    // ── ③ 服务器真值：意图卡 + 进程存活 ──
    const cardRaw = sshDell(`cat ${REMOTE_ROOT}/.petri/resident/${taskId}.json`);
    const card = JSON.parse(cardRaw);
    assert('P4-2 intent card on server (running)', card.status === 'running', `status=${card.status}`);
    let alive = true;
    try { sshDell(`kill -0 ${card.backingProcess.pid}`); } catch { alive = false; }
    assert('P4-3 backing process alive on aliyun', alive, `pid=${card.backingProcess.pid}`);

    // ── ④ 交接班 Channel B：同会话追问（systemPrompt 已注入 digest）──
    const followup = await sendAndWaitReply(client, '现在项目里有几个驻留任务？请用 resident_task_list 确认并汇报。', projectId);
    const followupText = String(followup.text);
    assert('P4-4 handover Channel B: agent reports via resident_task_list',
      followupText.includes(taskId) || /running|进行中|1 个/.test(followupText),
      `reply=${followupText.slice(0, 160)} | attempts=${followup.attempts || ''}`);
    await lib.screenshotPng(client, EVIDENCE, 'p4-phase1-conversation.png').catch(() => {});

    // ── ⑤ 关软件（外层 bash 编排 kill 栈）+ 写状态 ──
    // 2026-09-11 补：STATE 此前由外层 bash 手工维护，脚本自身不写导致复跑缺文件；
    // 现在 phase1 直接落盘，phase2 复跑自洽。
    fs.writeFileSync(STATE, JSON.stringify({ projectId, taskId, pid: card.backingProcess.pid }, null, 2) + '\n');
    saveAndExit(projectId, taskId);
  }

  if (PHASE === 'phase2') {
    // ── 读取 phase1 状态 ──
    const state = JSON.parse(fs.readFileSync(STATE, 'utf8'));
    projectId = state.projectId;
    const taskId = state.taskId;
    const pid = state.pid;
    assert('P4-5 state restored from phase1', !!projectId && !!taskId && !!pid, JSON.stringify(state).slice(0, 160));

    // ── ⑥ 重开后：dell 进程仍存活（关软件不影响 detached 进程）──
    let alive = true;
    try { sshDell(`kill -0 ${pid}`); } catch { alive = false; }
    assert('P4-6 backing process survived app restart', alive, `pid=${pid} alive=${alive}`);

    // ── ⑦ 交接班 Channel A+B：新会话 → agent 主动汇报 ──
    const client = await connectMain(projectId);
    const reply = await sendAndWaitReply(client, '项目当前有什么挂机中的驻留任务？请汇报意图和状态。', projectId);
    const replyText = String(reply.text);
    assert('P4-7 handover: agent reports resident task after restart',
      replyText.includes(taskId) || /挂机|驻留|P4 全链/.test(replyText),
      `reply=${replyText.slice(0, 160)} | attempts=${reply.attempts || ''}`);

    // ── ⑧ 异常路径：kill 进程 → 回访循环翻转 failed → agent 汇报 ──
    sshDell(`kill -9 ${pid} 2>/dev/null; true`);
    // 等回访循环（60s 节奏 + deadTicks 2 轮 → failed 翻转）
    let flipped = false;
    for (let i = 0; i < 10 && !flipped; i++) {
      await delay(15000);
      try {
        const raw = sshDell(`grep -o '"status": "[a-z]*"' ${REMOTE_ROOT}/.petri/resident/${taskId}.json | head -1`);
        flipped = /failed/.test(raw);
      } catch { /* keep waiting */ }
    }
    assert('P4-8 abnormal exit flipped card to failed (revisit loop)', flipped, 'server card status');
    const reply2 = await sendAndWaitReply(client, '驻留任务的进程已经终止了，请确认状态并汇报。', projectId);
    const reply2Text = String(reply2.text);
    assert('P4-9 agent reports failure honestly (R5 no auto-restart)',
      /failed|失败|异常|终止/.test(reply2Text), `reply=${reply2Text.slice(0, 160)} | attempts=${reply2.attempts || ''}`);

    // ── 清理 ──
    try { sshDell(`rm -rf ${REMOTE_ROOT}`); } catch {}
    await fetchJson(`${API}/data/projects/${projectId}`, { method: 'DELETE', headers: AUTH }).catch(() => {});
  }

  saveAndExit(projectId, null);
}

function saveAndExit(projectId, taskId) {
  const merged = {
    phase: PHASE,
    startedAt: results.startedAt,
    finishedAt: new Date().toISOString(),
    assertions: results.assertions,
    allPass: results.assertions.length > 0 && results.assertions.every((a) => a.pass),
    projectId: projectId || null,
    taskId: taskId || null,
  };
  fs.writeFileSync(path.join(EVIDENCE, `p4-${PHASE}.json`), JSON.stringify(merged, null, 2) + '\n');
  console.log(`[p4] ${PHASE}: ${merged.assertions.filter((a) => a.pass).length}/${merged.assertions.length} allPass=${merged.allPass}`);
  process.exit(merged.allPass ? 0 : 1);
}

main().catch((e) => { console.error('LIVE_ERR', e.message); process.exit(1); });

#!/usr/bin/env node
'use strict';

/**
 * BLOCK-78 P2-① 实机验收（远程资源实时快照，plan §5 P2① 出口）。
 *   A1 dell SSH 项目创建
 *   A2 首击 GET resource-snapshot?projectId → source=remote/host=dell
 *      （首击即证 ensureAgent 新哈希重部署 + sys_resource verb 生效）
 *   A3 读数对账：free -b / nproc / df -P 逐项（±2% 容差，meminfo 同源应精确）
 *   A4 TTL 合并：3s 内二次 GET → observedAt 相同（缓存命中，仅一次往返）
 *   A5 TTL 过期：>3s 后 GET → observedAt 更新（新探测）
 *   A6 不可达三态：假别名项目 → 502 remote_resource_unreachable + host 回显
 *   A7 本地不回归：无参 GET → 本机快照（无 source=remote）
 *   A8 路由 sanity：不存在 projectId → 404 project_not_found
 * 前置：dev 栈在跑（后端已载 P2-① 代码）；ssh dell 可达（BatchMode）。
 * 证据：acceptance/block-78/resource-live.json
 */

const http = require('node:http');
const fs = require('node:fs');
const path = require('node:path');
const { execFileSync } = require('node:child_process');

const REPO = path.join(__dirname, '..');
const EVIDENCE = path.join(REPO, 'acceptance', 'block-78');
const API = 'http://127.0.0.1:3001/api';
const AUTH = { Authorization: 'Bearer desktop-local', 'content-type': 'application/json' };
const REMOTE_ROOT = '/root/petri-block78-demo';

function fetchRaw(url, opts = {}) {
  return new Promise((resolve, reject) => {
    const req = http.request(url, { method: opts.method || 'GET', headers: opts.headers || {} }, (res) => {
      const chunks = [];
      res.on('data', (c) => chunks.push(c));
      res.on('end', () => resolve({ status: res.statusCode, headers: res.headers, body: Buffer.concat(chunks) }));
    });
    req.on('error', reject);
    if (opts.body) req.write(opts.body);
    req.end();
  });
}

async function fetchJson(url, opts = {}) {
  const r = await fetchRaw(url, opts);
  try { return { status: r.status, headers: r.headers, json: JSON.parse(r.body.toString('utf8')) }; } catch { return { status: r.status, headers: r.headers, json: null, raw: r.body.toString('utf8').slice(0, 200) }; }
}

function sshDell(cmd) {
  return execFileSync('ssh', ['-o', 'BatchMode=yes', '-o', 'ConnectTimeout=10', 'dell', cmd], { encoding: 'utf8', timeout: 30000, windowsHide: true });
}

const near = (a, b, tol = 0.02) => Math.abs(Number(a) - Number(b)) <= Math.abs(Number(b)) * tol;

async function main() {
  fs.mkdirSync(EVIDENCE, { recursive: true });
  const results = { startedAt: new Date().toISOString(), assertions: [] };
  const assert = (name, pass, detail = '') => {
    results.assertions.push({ name, pass: !!pass, detail: String(detail).slice(0, 500) });
    try { fs.writeSync(1, '[' + new Date().toISOString().slice(11, 19) + '] ' + (pass ? 'PASS' : 'FAIL') + ' ' + name + (detail ? ' :: ' + String(detail).slice(0, 160) : '') + '\n'); } catch {}
  };
  const delay = (ms) => new Promise((r) => setTimeout(r, ms));

  try {
    sshDell(`mkdir -p ${REMOTE_ROOT}`);
    const created = await fetchJson(`${API}/data/projects`, {
      method: 'POST', headers: AUTH,
      body: JSON.stringify({ name: `B78资源快照-${Date.now()}`, workspaceKind: 'ssh', sshHost: 'dell', remotePath: REMOTE_ROOT }),
    });
    projectId = created.json && created.json.project && created.json.project.id;
    assert('A1 dell ssh project created', created.status === 200 && !!projectId, JSON.stringify(created.json).slice(0, 160));

    // A2 首击：ensureAgent（新哈希 → 重部署）+ sys_resource verb 生效
    const first = await fetchJson(`${API}/harness/resource-snapshot?projectId=${encodeURIComponent(projectId)}`, { headers: AUTH });
    const snap = first.json && first.json.snapshot;
    assert('A2 first probe source=remote host=dell', first.status === 200 && snap && snap.source === 'remote' && snap.host === 'dell',
      JSON.stringify(first.json).slice(0, 200));

    // A3 与节点真值逐项对账
    let reconcile = '';
    try {
      const free = sshDell('free -b');
      const mt = Number((free.match(/Mem:\s+(\d+)/) || [])[1]);
      const ma = Number((free.match(/Mem:\s+\d+\s+\d+\s+\d+\s+\d+\s+(\d+)/) || [])[1]) || null;
      // free 输出第 6 列即 available（available 列存在时）；直接抓 available 行更稳：
      const maMatch = free.match(/Mem:\s+\d+\s+\d+\s+\d+\s+\d+\s+\d+\s+(\d+)/);
      const memAvailable = maMatch ? Number(maMatch[1]) : ma;
      const cores = Number(sshDell('nproc').trim());
      const df = sshDell(`df -PB1 ${REMOTE_ROOT}`).trim().split('\n').pop().split(/\s+/);
      const diskTotal = Number(df[1]); const diskAvail = Number(df[3]);
      const memOk = near(snap.memory.totalBytes, mt, 0.001) && near(snap.memory.availableBytes, memAvailable, 0.02);
      const coresOk = snap.cpu.logicalCores === cores;
      const diskOk = near(snap.disk.totalBytes, diskTotal, 0.001) && near(snap.disk.availableBytes, diskAvail, 0.02);
      assert('A3a memory matches free -b', memOk, `card=${snap.memory.totalBytes}/${snap.memory.availableBytes} node=${mt}/${memAvailable}`);
      assert('A3b cores matches nproc', coresOk, `card=${snap.cpu.logicalCores} node=${cores}`);
      assert('A3c disk matches df -P', diskOk, `card=${snap.disk.totalBytes}/${snap.disk.availableBytes} node=${diskTotal}/${diskAvail}`);
      reconcile = `mem ${memOk} cores ${coresOk} disk ${diskOk}`;
    } catch (e) {
      assert('A3 reconcile (ssh free/df)', false, e.message);
    }

    // A4 TTL：3s 内二次 GET → observedAt 相同
    const second = await fetchJson(`${API}/harness/resource-snapshot?projectId=${encodeURIComponent(projectId)}`, { headers: AUTH });
    assert('A4 TTL cache hit (same observedAt)', second.json && second.json.snapshot && second.json.snapshot.observedAt === snap.observedAt,
      `${snap.observedAt} vs ${second.json && second.json.snapshot && second.json.snapshot.observedAt}`);

    // A5 TTL 过期：>3.2s → 新观测
    await delay(3300);
    const third = await fetchJson(`${API}/harness/resource-snapshot?projectId=${encodeURIComponent(projectId)}`, { headers: AUTH });
    assert('A5 TTL expiry → fresh probe (new observedAt)', third.json && third.json.snapshot && third.json.snapshot.observedAt !== snap.observedAt,
      `${snap.observedAt} → ${third.json && third.json.snapshot && third.json.snapshot.observedAt}`);

    // A6 不可达三态：假别名 → 502 remote_resource_unreachable
    const bogus = await fetchJson(`${API}/data/projects`, {
      method: 'POST', headers: AUTH,
      body: JSON.stringify({ name: `B78不可达-${Date.now()}`, workspaceKind: 'ssh', sshHost: 'b78-nonexistent-alias', remotePath: '/tmp/b78' }),
    });
    const bogusId = bogus.json && bogus.json.project && bogus.json.project.id;
    const bad = await fetchJson(`${API}/harness/resource-snapshot?projectId=${encodeURIComponent(bogusId)}`, { headers: AUTH });
    assert('A6 unreachable → 502 remote_resource_unreachable',
      bad.status === 502 && bad.json && bad.json.error === 'remote_resource_unreachable' && bad.json.host === 'b78-nonexistent-alias',
      JSON.stringify(bad.json).slice(0, 200));

    // A7 本地不回归：无参 GET → 本机快照（无 source=remote）
    const local = await fetchJson(`${API}/harness/resource-snapshot`, { headers: AUTH });
    assert('A7 no-param local snapshot unchanged', local.status === 200 && local.json && local.json.snapshot && local.json.snapshot.source !== 'remote',
      `platform=${local.json && local.json.snapshot && local.json.snapshot.platform}`);

    // A8 路由 sanity：不存在项目 → 404
    const missing = await fetchJson(`${API}/harness/resource-snapshot?projectId=p_nonexistent`, { headers: AUTH });
    assert('A8 missing project → 404 project_not_found', missing.status === 404 && missing.json && missing.json.error === 'project_not_found',
      JSON.stringify(missing.json).slice(0, 120));
  } catch (e) {
    assert('FATAL', false, e.message);
  }

  results.allPass = results.assertions.every((a) => a.pass);
  results.finishedAt = new Date().toISOString();
  fs.writeFileSync(path.join(EVIDENCE, 'resource-live.json'), JSON.stringify(results, null, 2));
  fs.writeSync(1, `[${new Date().toISOString().slice(11, 19)}] allPass=${results.allPass}\n`);
}

let projectId = null;
main().catch((e) => { console.error(e); process.exit(1); });

#!/usr/bin/env node
'use strict';

/**
 * BLOCK-79 P3 实机数值一致性对账（真实模型推理 → 端点 vs 库内重算）。
 *   A1 真实推理一轮：直驱 modelGateway（同 dev 设置/密钥/网关注入代码路径），
 *      telemetry.provider 注入 → ai_usage 落账（kind=chat, conversation 归因）
 *   A2 usage-mine 返回 providers 分组数组
 *   A3 至少一个供应商组 measurable=true 且 tokensPerSecond>0（真实推理产生读数）
 *   A4 端点数值 = 库内重算（readonly sqlite 独立重算 30d 窗口逐组一致）
 *   A5 embedding 不出现在任何分组
 * 前置：dev 栈已载 BLOCK-79 代码；本地已配置可用 chat 模型。
 * 证据：acceptance/block-79/provider-live.json
 */

const http = require('node:http');
const fs = require('node:fs');
const path = require('node:path');

const REPO = path.join(__dirname, '..');
const EVIDENCE_DIR = path.join(REPO, 'acceptance', 'block-79');
const API = 'http://127.0.0.1:3001/api';
const AUTH = { Authorization: 'Bearer desktop-local', 'content-type': 'application/json' };
// 与 dev 启动器同一数据根与同一 DB（db.js: PETRI_DB_PATH 优先——不设会回落
// core/petri-server/petri.db 第二库，归因行将落错库）
process.env.PETRI_LOCAL_DATA_DIR = path.join(REPO, '.petri-dev-user-data', 'data');
process.env.PETRI_DB_PATH = path.join(process.env.PETRI_LOCAL_DATA_DIR, 'petri.db');

const Database = require(path.join(REPO, 'core', 'petri-server', 'node_modules', 'better-sqlite3'));
const { modelGateway } = require(path.join(REPO, 'core', 'petri-server', 'helpers', 'model-gateway.js'));
const { LOCAL_USER } = require(path.join(REPO, 'core', 'petri-server', 'auth.js'));

function fetchJson(url, opts = {}) {
  return new Promise((resolve, reject) => {
    const req = http.request(url, { method: opts.method || 'GET', headers: opts.headers || {} }, (res) => {
      let d = '';
      res.on('data', (c) => (d += c));
      res.on('end', () => {
        let json = null;
        try { json = JSON.parse(d); } catch { /* raw 兜底 */ }
        resolve({ status: res.statusCode, json, raw: d });
      });
    });
    req.on('error', reject);
    if (opts.body) req.write(opts.body);
    req.end();
  });
}

function log(msg) { try { fs.writeSync(1, `[${new Date().toISOString().slice(11, 19)}] ${msg}\n`); } catch {} }

async function main() {
  fs.mkdirSync(EVIDENCE_DIR, { recursive: true });
  const results = { startedAt: new Date().toISOString(), assertions: [] };
  const assert = (name, pass, detail = '') => {
    results.assertions.push({ name, pass: !!pass, detail: String(detail).slice(0, 400) });
    log(`${pass ? 'PASS' : 'FAIL'} ${name}${detail ? ' :: ' + String(detail).slice(0, 140) : ''}`);
  };

  // A1 真实推理一轮（网关注入 telemetry.provider → usageArgs 落库）
  const convId = `conv_b79_live_${Date.now().toString(36)}`;
  let assistantText = '';
  let usedProfile = null;
  const result = await modelGateway.chat({
    role: 'chat',
    body: { messages: [{ role: 'user', content: '请只回复两个字：收到' }], temperature: 0 },
    telemetry: { userId: LOCAL_USER.id, kind: 'chat', conversationId: convId },
  });
  if (result && !result.error) {
    assistantText = String(result.text || result.content || (result.choices && result.choices[0] && result.choices[0].message && result.choices[0].message.content) || '');
    usedProfile = result.profile && result.profile.id;
  }
  assert('A1 real inference via gateway (injection path)', !result || !result.error ? assistantText.length >= 0 : false,
    `error=${result && result.error} text="${assistantText.slice(0, 40)}" profile=${usedProfile || 'n/a'}`);
  if (result && result.error) {
    // 推理不可用（渠道/密钥问题）：后续读数断言诚实标注失败原因后退出
    results.allPass = false;
    results.finishedAt = new Date().toISOString();
    fs.writeFileSync(path.join(EVIDENCE_DIR, 'provider-live.json'), JSON.stringify(results, null, 2));
    log('allPass=false (inference unavailable)');
    return;
  }

  // A2 providers 分组数组
  const mine = await fetchJson(`${API}/ai/usage-mine?days=30`, { headers: AUTH });
  const providers = (mine.json && mine.json.providers) || null;
  assert('A2 usage-mine exposes providers array', mine.status === 200 && Array.isArray(providers),
    `status=${mine.status} body=${(mine.raw || '').slice(0, 200) || JSON.stringify(mine.json || null)}`);

  // A3 至少一组 measurable 且 tps>0（本轮真实推理应归因可见）
  const measurable = (providers || []).filter((p) => p.measurable && p.tokensPerSecond > 0);
  assert('A3 at least one measurable provider with tps>0', measurable.length > 0,
    JSON.stringify(measurable).slice(0, 260));

  // A4 端点 = 库内重算（独立 readonly 连接，30d 窗口 + 同 user 过滤，逐组一致）
  const ro = new Database(path.join(REPO, '.petri-dev-user-data', 'data', 'petri.db'), { readonly: true });
  const cutoff = new Date(Date.now() - 30 * 86400000).toISOString();
  const recompute = ro.prepare(`SELECT COALESCE(provider,'(未归因)') AS provider,
      COUNT(*) AS calls, COALESCE(SUM(prompt_tokens),0) AS inputTokens,
      COALESCE(SUM(completion_tokens),0) AS outputTokens,
      COALESCE(SUM(latency_ms),0) AS latencyMs
    FROM ai_usage WHERE ts >= ? AND user_id = ? AND kind <> 'embedding'
    GROUP BY provider ORDER BY outputTokens DESC`).all(cutoff, LOCAL_USER.id);
  ro.close();
  let consistent = recompute.length === (providers || []).length;
  if (consistent) {
    for (let i = 0; i < recompute.length; i++) {
      const a = recompute[i]; const b = (providers || [])[i];
      if (!b || a.provider !== b.provider || a.calls !== b.calls || a.outputTokens !== b.outputTokens || a.latencyMs !== b.latencyMs) { consistent = false; break; }
    }
  }
  assert('A4 endpoint matches DB recompute (30d, per provider)', consistent,
    `endpoint=${JSON.stringify(providers).slice(0, 200)} db=${JSON.stringify(recompute).slice(0, 200)}`);

  // A5 embedding 不出现在任何分组
  assert('A5 embedding excluded from groups', !(providers || []).some((p) => String(p.provider).toLowerCase().includes('embed')));

  results.allPass = results.assertions.every((a) => a.pass);
  results.finishedAt = new Date().toISOString();
  fs.writeFileSync(path.join(EVIDENCE_DIR, 'provider-live.json'), JSON.stringify(results, null, 2));
  log(`allPass=${results.allPass}`);
}

main().catch((e) => { console.error(e); process.exit(1); });

#!/usr/bin/env node
'use strict';
/**
 * block81-p3-channel-probe.cjs — BLOCK-81 P3：上游参数接受度矩阵（真渠道实测）。
 *
 * 回答的问题（P3 收口必需）：D3「去参重试」在**本机可用渠道**上能不能被真实触发？
 * 做法：对每个 OpenAI 兼容 chat 渠道各发两次最小请求——A 不带思考参数、B 带
 * `reasoning_effort: "high"`——比较状态码与响应字段形状。这是**直连上游**的探针
 * （不经我方能力位门控），只观测上游行为，不写任何配置。
 *
 * 判定口径（诚实）：
 *   - 无渠道以「未知/非法参数」类 400 拒绝 → D3 实机触发路径在本机不可达，
 *     该分支由确定性门禁（test/thinking-level-injection.test.mjs）覆盖，如实登记。
 *   - 出现此类 400 → D3 具备实机靶场，可在 UI/agent 链路上复验（本脚本只报可用性）。
 *   - 响应侧思考段字段名若非 `reasoning_content`，一并如实登记（我方解析面只认该名）。
 */

const fs = require('node:fs');
const path = require('node:path');
const https = require('node:https');
const http = require('node:http');

const ROOT = path.join(__dirname, '..');
const lib = require(path.join(ROOT, '.agents', 'skills', 'petri-dev-infra', 'dev-verify', 'lib.cjs'));
const DATA_DIR = process.env.PETRI_LOCAL_DATA_DIR || path.join(ROOT, '.petri-dev-user-data', 'data');
const EVIDENCE_DIR = path.join(ROOT, 'acceptance', 'block-81');
const PROMPT = '只回复「收到」';

/** 凭据解析：与 core/petri-server/helpers/model-gateway.js getCredential 同口径。 */
function credentialKeyFor(profile) {
  const ref = String(profile.credentialRef || '');
  const sep = ref.indexOf(':');
  if (sep >= 0 && ref.slice(sep + 1)) return ref.slice(sep + 1);
  return profile.provider || ref;
}

function post(baseUrl, apiKey, payload, timeoutMs = 30000) {
  return new Promise((resolve) => {
    const body = JSON.stringify(payload);
    const url = new URL(baseUrl);
    const isHttps = url.protocol === 'https:';
    const client = isHttps ? https : http;
    const reqPath = `${url.pathname.replace(/\/$/, '')}/chat/completions`;
    const req = client.request({
      hostname: url.hostname,
      port: url.port || (isHttps ? 443 : 80),
      path: reqPath,
      method: 'POST',
      timeout: timeoutMs,
      headers: {
        'content-type': 'application/json',
        'content-length': Buffer.byteLength(body),
        authorization: `Bearer ${apiKey}`,
      },
    }, (res) => {
      let d = '';
      res.on('data', (c) => { d += c; });
      res.on('end', () => {
        let parsed = null;
        try { parsed = JSON.parse(d); } catch { /* 非 JSON 原样返回 */ }
        resolve({ status: res.statusCode, parsed, raw: d.slice(0, 400) });
      });
    });
    req.on('error', (e) => resolve({ status: 0, error: e.message }));
    req.on('timeout', () => { req.destroy(); resolve({ status: 0, error: 'timeout' }); });
    req.write(body);
    req.end();
  });
}

/** 上游错误是否属「未知/非法参数」类（与 thinking-level.isUnknownParameterError 判据同源）。 */
function looksLikeUnknownParam(status, parsed) {
  if (status !== 400) return false;
  const text = JSON.stringify(parsed || {}).toLowerCase();
  return /unknown (parameter|argument|field|property)|unrecognized (parameter|field|property)|unsupported (parameter|argument|field|property)|invalid (parameter|argument|field|property)|unexpected (parameter|argument|field)/.test(text);
}

function reasoningFieldShapes(parsed) {
  const msg = parsed && parsed.choices && parsed.choices[0] && parsed.choices[0].message;
  if (!msg || typeof msg !== 'object') return [];
  return Object.keys(msg).filter((k) => /reason/i.test(k) && msg[k]);
}

(async () => {
  const run = lib.createRun({ name: 'block-81-p3-channel-probe', evidenceDir: EVIDENCE_DIR });
  const observations = { channels: [] };
  try {
    const settings = JSON.parse(fs.readFileSync(path.join(DATA_DIR, 'ai-settings.json'), 'utf8'));
    const creds = JSON.parse(fs.readFileSync(path.join(DATA_DIR, 'ai-credentials.json'), 'utf8'));
    const profiles = (settings.model_profiles || []).filter((p) => (p.protocol || 'openai-compatible') === 'openai-compatible');

    for (const profile of profiles) {
      const apiKey = creds[credentialKeyFor(profile)];
      const entry = {
        profileId: profile.id,
        model: profile.model,
        baseUrl: profile.baseUrl,
        hasCredential: !!apiKey,
        withoutParam: null,
        withParam: null,
        rejectedParam: false,
      };
      if (apiKey) {
        const base = { model: profile.model, messages: [{ role: 'user', content: PROMPT }], max_tokens: 64, stream: false };
        const a = await post(profile.baseUrl, apiKey, base);
        const b = await post(profile.baseUrl, apiKey, { ...base, reasoning_effort: 'high' });
        entry.withoutParam = { status: a.status, error: a.error || null, reasoningFields: reasoningFieldShapes(a.parsed), finishReason: a.parsed && a.parsed.choices && a.parsed.choices[0] ? a.parsed.choices[0].finish_reason : null, errorText: a.status >= 400 ? String(a.raw).slice(0, 200) : null };
        entry.withParam = { status: b.status, error: b.error || null, reasoningFields: reasoningFieldShapes(b.parsed), finishReason: b.parsed && b.parsed.choices && b.parsed.choices[0] ? b.parsed.choices[0].finish_reason : null, errorText: b.status >= 400 ? String(b.raw).slice(0, 200) : null };
        entry.rejectedParam = looksLikeUnknownParam(b.status, b.parsed);
        entry.paramAccepted = b.status >= 200 && b.status < 300;
        lib.log(`${profile.id}: without=${a.status} with=${b.status} rejectedParam=${entry.rejectedParam}`);
      }
      observations.channels.push(entry);
    }

    const probed = observations.channels.filter((c) => c.withParam);
    const accepting = probed.filter((c) => c.paramAccepted);
    const rejecting = probed.filter((c) => c.rejectedParam);
    const reasoningShapes = [...new Set(probed.flatMap((c) => [...(c.withParam.reasoningFields || []), ...(c.withoutParam.reasoningFields || [])]))];

    observations.summary = {
      probedChannels: probed.length,
      acceptedParam: accepting.map((c) => c.profileId),
      rejectedParamAsUnknown: rejecting.map((c) => c.profileId),
      reasoningFieldShapesSeen: reasoningShapes,
    };

    run.assert('PR1_channels_probed', probed.length > 0,
      `已实测 ${probed.length} 个 OpenAI 兼容渠道（不含无凭据渠道）：${probed.map((c) => c.profileId).join(', ')}`);
    run.assert('PR2_no_unknown_param_rejection', rejecting.length === 0,
      rejecting.length === 0
        ? `本机无渠道以「未知/非法参数」400 拒绝 reasoning_effort → D3 去参重试的**实机触发路径不可达**，该分支由确定性门禁覆盖（已如实登记，非缺陷）`
        : `发现实机靶场：${rejecting.map((c) => c.profileId).join(', ')} 以未知参数 400 拒绝 → D3 可在 agent 链路复验`);
    run.assert('PR3_reasoning_field_shape', reasoningShapes.includes('reasoning_content') || reasoningShapes.length === 0,
      `上游思考段字段实测形状：${JSON.stringify(reasoningShapes)}（我方解析面只认 reasoning_content；其他形状如实登记为观察）`);

    return await run.finish({ observations });
  } catch (err) {
    run.assert('RUN_COMPLETED', false, `脚本异常：${err && err.message ? err.message : String(err)}`);
    observations.error = String((err && err.stack) || err).slice(0, 1200);
    return await run.finish({ observations });
  }
})().then((p) => process.exit(p && p.allPass ? 0 : 1)).catch((e) => { console.error('FATAL', e && e.message); process.exit(2); });

#!/usr/bin/env node
'use strict';
/**
 * block81-p3-thinking-live.cjs — BLOCK-81 P3 实机对比验收（标准 vs 高）。
 *
 * 目标：用**真实渠道**（本机已配置的 OpenAI 兼容网关）跑两轮真实对话，证明
 * 「档位确实映射成上游请求参数」并且「上游实际收到/未收到该参数」，同时如实
 * 记录响应侧是否出现思考段（reasoning_content）。
 *
 * 证据三层：
 *   1) UI 层   — composer 档位控件（data-testid=thinking-level-trigger）的档位与默认值；
 *   2) 后端层  — 任务参数落库（DB tasks.params，由 P2 UI-345 已覆盖，本脚本只读会话消息 meta）；
 *   3) 上游层  — `llm-transcripts/<convId>.jsonl` 的 `request.params`（网关发给上游的
 *                请求体去掉 messages 后的序列化文本）→ 这是本阶段的核心新证据。
 *
 * 判定纪律（禁止编造效果）：上游是否产生思考段由渠道决定，本脚本只如实记录
 * 「发出去了什么 + 上游回了什么」；渠道不产思考段、或 400 后按 D3 去参重试，
 * 都属合格结论。
 *
 * 前置：dev 栈在跑（3001 API + 3000 Vite + 9222 CDP）；改了 core/ 必须重启 dev 栈。
 */

const fs = require('node:fs');
const path = require('node:path');
const http = require('node:http');

const ROOT = path.join(__dirname, '..');
const lib = require(path.join(ROOT, '.agents', 'skills', 'petri-dev-infra', 'dev-verify', 'lib.cjs'));

const API = 'http://127.0.0.1:3001/api';
const AUTH = { Authorization: 'Bearer desktop-local' };
const DATA_DIR = process.env.PETRI_LOCAL_DATA_DIR || path.join(ROOT, '.petri-dev-user-data', 'data');
const TRANSCRIPT_DIR = path.join(DATA_DIR, 'llm-transcripts');
const EVIDENCE_DIR = path.join(ROOT, 'acceptance', 'block-81');

const PROMPT = '一个班有 30 名学生，其中 60% 是女生。把 5 名男生换成女生后，女生有多少人？只输出最后结论一行，不要使用任何工具。';
// 工具轮：UI-272 的思考段渲染面挂在「执行记录」内（仅当本轮有工具活动才存在），
// 零工具直答轮看不到思考行——故补一轮必然触发工具的对照。
const TOOL_PROMPT = '先看当前项目根目录里有什么文件，再只回复一行「文件数量=N」，不要展开细节。';

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

/* ── HTTP ────────────────────────────────────────────────────────────────── */

function req(method, p, body) {
  return new Promise((resolve, reject) => {
    const data = body ? JSON.stringify(body) : null;
    const r = http.request({
      host: '127.0.0.1',
      port: 3001,
      path: p,
      method,
      headers: {
        ...AUTH,
        ...(data ? { 'content-type': 'application/json', 'content-length': Buffer.byteLength(data) } : {}),
      },
    }, (res) => {
      let d = '';
      res.on('data', (c) => { d += c; });
      res.on('end', () => {
        try { resolve({ status: res.statusCode, json: JSON.parse(d || '{}') }); } catch { resolve({ status: res.statusCode, json: null, raw: d.slice(0, 300) }); }
      });
    });
    r.on('error', reject);
    if (data) r.write(data);
    r.end();
  });
}

/* ── 信息流读取（BLOCK-37 落盘 / BLOCK-38 readLastRecord 同源目录） ─────────── */

function safeIdPart(value) {
  const cleaned = String(value || '').replace(/[^A-Za-z0-9_-]+/g, '_').replace(/^_+|_+$/g, '');
  return cleaned || 'unattributed';
}

function transcriptFile(conversationId) {
  return path.join(TRANSCRIPT_DIR, `${safeIdPart(conversationId)}.jsonl`);
}

function readRecords(conversationId) {
  try {
    return fs.readFileSync(transcriptFile(conversationId), 'utf8')
      .split('\n')
      .filter((line) => line.trim())
      .map((line) => { try { return JSON.parse(line); } catch { return null; } })
      .filter(Boolean);
  } catch {
    return [];
  }
}

/** 从落盘记录里抽出「网关实际发给上游的请求参数」（request.params 是去 messages 的 JSON 文本）。 */
function sentParams(record) {
  try {
    const parsed = JSON.parse((record && record.request && record.request.params) || '{}');
    return parsed && typeof parsed === 'object' ? parsed : {};
  } catch {
    return {};
  }
}

function reasoningKeysOf(params) {
  return ['reasoning_effort', 'thinking', 'enable_thinking'].filter((k) => k in params);
}

function summarizeRecord(record) {
  const params = sentParams(record);
  const response = record.response || null;
  return {
    ts: record.ts,
    attemptIndex: record.attemptIndex,
    profileId: record.profileId || null,
    provider: record.provider || null,
    model: record.model || null,
    sentParamKeys: Object.keys(params).filter((k) => k !== 'model').sort(),
    reasoningKeys: reasoningKeysOf(params),
    reasoning_effort: params.reasoning_effort === undefined ? null : params.reasoning_effort,
    temperature: params.temperature === undefined ? null : params.temperature,
    max_tokens: params.max_tokens === undefined ? null : params.max_tokens,
    error: record.error || null,
    finishReason: response ? response.finishReason : null,
    contentLength: response && typeof response.content === 'string' ? response.content.length : 0,
    reasoningLength: response && typeof response.reasoningContent === 'string' ? response.reasoningContent.length : 0,
    reasoningPreview: response && typeof response.reasoningContent === 'string'
      ? response.reasoningContent.slice(0, 200)
      : null,
    contentPreview: response && typeof response.content === 'string' ? response.content.slice(0, 200) : null,
  };
}

/* ── CDP 页面附着 ───────────────────────────────────────────────────────── */

async function attachWorkspacePage() {
  const targets = await lib.pollTargets({ timeoutMs: 20000 });
  // 排除 /window/* 辅助窗（RailPage / 结果窗等），只留主窗页面
  const candidates = lib.filterPageTargets(targets, /^http:\/\/localhost:3000\/(?!window\/)/);
  const target = await lib.selectPageTarget(candidates, {
    probe: async (client) => lib.evalJs(client, `!!document.getElementById('root')`).catch(() => false),
  });
  if (!target) throw new Error('no_workspace_page_target');
  return lib.connectTarget(target);
}

const COMPOSER_READY = `(function(){ var ta=document.querySelector('textarea.sc-input'); return ta ? 'ready' : null; })()`;
const MODEL_LABEL = `(function(){
  var b = document.querySelector('.sc-model-picker:not(.sc-model-picker-footer) button');
  return b ? (b.getAttribute('title') || b.textContent || '').trim() : null;
})()`;
const TRIGGER_STATE = `(function(){
  var el = document.querySelector('[data-testid="thinking-level-trigger"]');
  if (!el) return null;
  return JSON.stringify({
    level: el.getAttribute('data-level'),
    label: (el.textContent || '').trim(),
    hasTextLabel: !!el.querySelector('span'),
    title: el.getAttribute('title')
  });
})()`;
const REASONING_ROWS = `document.querySelectorAll('.sc-tool-reasoning').length`;
const SEND_BUTTON = `(function(){
  var b = [].slice.call(document.querySelectorAll('button')).find(function (x) {
    var t = (x.getAttribute('title') || '') + ' ' + (x.getAttribute('aria-label') || '');
    return t.indexOf('发送消息') >= 0;
  });
  if (!b) return 'send_button_missing';
  if (b.disabled) return 'send_disabled';
  b.click();
  return 'sent';
})()`;
const INSTALL_RECORDER = `(function(){
  window.__p3sent = [];
  if (!window.__p3patched) {
    window.__p3patched = true;
    var orig = window.fetch;
    window.fetch = function () {
      try {
        var a = arguments[0], b = arguments[1];
        var url = typeof a === 'string' ? a : (a && a.url);
        if (String(url).indexOf('/ai/agent') >= 0 && b && b.method === 'POST') {
          window.__p3sent.push(String(b.body || ''));
        }
      } catch (e) {}
      return orig.apply(this, arguments);
    };
  }
  return 'installed';
})()`;
const READ_RECORDER = `JSON.stringify(window.__p3sent || [])`;

/** 读回页面实发 /api/ai/agent 请求体（UI 层证据：档位是否随本轮下发）。 */
async function readSentBodies(client) {
  const raw = await lib.evalJs(client, READ_RECORDER).catch(() => '[]');
  return JSON.parse(raw || '[]').map((body) => {
    try {
      const parsed = JSON.parse(body);
      return {
        conversationId: parsed.conversationId || null,
        modelPresetId: parsed.modelPresetId || null,
        thinkingLevel: parsed.thinkingLevel === undefined ? null : parsed.thinkingLevel,
        kind: parsed.kind || null,
      };
    } catch {
      return { unparsed: String(body).slice(0, 120) };
    }
  });
}

async function waitComposer(client, timeoutMs = 30000) {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    const ok = await lib.evalJs(client, COMPOSER_READY).catch(() => null);
    if (ok === 'ready') return true;
    await sleep(1000);
  }
  return false;
}

async function waitTrigger(client, timeoutMs = 20000) {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    const raw = await lib.evalJs(client, TRIGGER_STATE).catch(() => null);
    if (raw) return JSON.parse(raw);
    await sleep(1000);
  }
  return null;
}

async function setLevel(client, level) {
  await lib.evalJs(client, `(function(){ var el=document.querySelector('[data-testid="thinking-level-trigger"]'); if (el) el.click(); return 'opened'; })()`);
  await sleep(500);
  const clicked = await lib.evalJs(client, `(function(){ var o=document.querySelector('[data-testid="thinking-level-option-${level}"]'); if(!o) return 'option_missing'; o.click(); return 'clicked'; })()`);
  await sleep(700);
  const raw = await lib.evalJs(client, TRIGGER_STATE).catch(() => null);
  return { clicked, state: raw ? JSON.parse(raw) : null };
}

async function typeAndSend(client, text) {
  const typed = await lib.evalJs(client, `(function(){
    var ta = document.querySelector('textarea.sc-input');
    if (!ta) return 'no_textarea';
    var setter = Object.getOwnPropertyDescriptor(window.HTMLTextAreaElement.prototype, 'value').set;
    setter.call(ta, ${JSON.stringify(text)});
    ta.dispatchEvent(new Event('input', { bubbles: true }));
    return 'typed:' + ta.value.length;
  })()`);
  await sleep(900);
  const sent = await lib.evalJs(client, SEND_BUTTON);
  return { typed, sent };
}

/** 等这一轮的 assistant 消息落库（内容非空即为该轮跑完）。 */
async function waitAssistantMessage(conversationId, timeoutMs = 180000) {
  const deadline = Date.now() + timeoutMs;
  let last = null;
  while (Date.now() < deadline) {
    const r = await req('GET', `/api/ai/conversations/${encodeURIComponent(conversationId)}/messages?limit=50`);
    const messages = (r.json && r.json.messages) || [];
    const assistant = messages.filter((m) => m.role === 'assistant' && String(m.content || '').trim().length > 0);
    if (assistant.length > 0) {
      last = assistant[assistant.length - 1];
      // 落库后可能仍在写 meta，短暂稳定期再取终值
      await sleep(2500);
      const r2 = await req('GET', `/api/ai/conversations/${encodeURIComponent(conversationId)}/messages?limit=50`);
      const again = ((r2.json && r2.json.messages) || []).filter((m) => m.role === 'assistant' && String(m.content || '').trim().length > 0);
      if (again.length > 0) last = again[again.length - 1];
      return { messages, assistant: last };
    }
    await sleep(3000);
  }
  return { messages: [], assistant: last, timedOut: true };
}

function metaOf(message) {
  if (!message) return {};
  if (message.meta && typeof message.meta === 'object') return message.meta;
  try { return JSON.parse(message.meta_json || '{}'); } catch { return {}; }
}

/* ── 主流程 ─────────────────────────────────────────────────────────────── */

(async () => {
  const run = lib.createRun({ name: 'block-81-p3-thinking', evidenceDir: EVIDENCE_DIR });
  const observations = {};
  let patchedProfiles = null;
  let client = null;

  try {
    /* 1) 渠道能力位就绪（D3 双保险①的声明面） */
    const settingsRes = await req('GET', '/api/ai/settings');
    const settings = (settingsRes.json && settingsRes.json.settings) || {};
    const profiles = Array.isArray(settings.model_profiles) ? settings.model_profiles : [];
    if (profiles.length === 0) throw new Error('no_model_profiles');

    const projectsRes = await req('GET', '/api/data/projects');
    const projectId = ((projectsRes.json && projectsRes.json.projects) || [])[0]
      && projectsRes.json.projects[0].id;
    if (!projectId) throw new Error('no_project');

    /* 2) 附着工作区页面 → 读 composer 当前绑定的模型 → 保证该渠道声明 reasoning */
    client = await attachWorkspacePage();
    await lib.evalJs(client, `location.href = 'http://localhost:3000/project/${projectId}'; 'nav'`);
    await sleep(5000);
    client = await attachWorkspacePage();
    const composerReady = await waitComposer(client);
    run.assert('P0_composer_ready', composerReady, `工作区 composer 就绪（project=${projectId}）`);
    if (!composerReady) throw new Error('composer_not_ready');

    const modelLabel = await lib.evalJs(client, MODEL_LABEL).catch(() => null);
    const activeProfile = profiles.find((p) => p.model && String(modelLabel || '').includes(p.model))
      || profiles.find((p) => p.provider === 'deepseek' && (p.protocol || '') === 'openai-compatible')
      || profiles[0];
    observations.composerModelLabel = modelLabel;
    observations.targetProfileId = activeProfile.id;
    observations.targetProfileProtocol = activeProfile.protocol || null;
    observations.targetProfileModel = activeProfile.model;

    const hadReasoning = Array.isArray(activeProfile.capabilities) && activeProfile.capabilities.includes('reasoning');
    if (!hadReasoning) {
      const baseline = Array.isArray(activeProfile.capabilities) && activeProfile.capabilities.length
        ? activeProfile.capabilities
        : ['chat', 'streaming', 'tools'];
      patchedProfiles = profiles;
      const next = profiles.map((p) => (p.id === activeProfile.id
        ? { ...p, capabilities: Array.from(new Set([...baseline, 'reasoning'])) }
        : p));
      const w = await req('POST', '/api/ai/settings', { model_profiles: next });
      run.assert('P1_capability_declared', w.status === 200, `渠道 ${activeProfile.id} 声明 capabilities.reasoning（写 settings HTTP ${w.status}）`);
      const targets2 = await lib.pollTargets({ timeoutMs: 15000 });
      client = await lib.connectTarget(lib.filterPageTargets(targets2, /^http:\/\/localhost:3000\/(?!window\/)/)[0]);
      await lib.evalJs(client, `location.reload(); 'r'`).catch(() => {});
      await sleep(5000);
      client = await attachWorkspacePage();
      await waitComposer(client);
    } else {
      run.assert('P1_capability_declared', true, `渠道 ${activeProfile.id} 已在配置中声明 capabilities.reasoning（无需改写）`);
    }

    const trigger0 = await waitTrigger(client);
    run.assert('P2_control_visible', !!trigger0,
      trigger0 ? `档位控件出现（data-level=${trigger0.level}，label=${trigger0.label}）` : '档位控件未出现');

    /* 3) 两轮真实对话：标准 → 高（各自独立会话，提示词逐字相同） */
    const rounds = [
      { key: 'standard', title: 'BLOCK-81 P3 · 标准档对比', level: 'standard', prompt: PROMPT },
      { key: 'high', title: 'BLOCK-81 P3 · 高档对比', level: 'high', prompt: PROMPT },
      { key: 'tool', title: 'BLOCK-81 P3 · 工具轮（高）', level: 'high', prompt: TOOL_PROMPT, expandActivity: true },
    ];
    const roundEvidence = [];

    for (const round of rounds) {
      const created = await req('POST', '/api/ai/conversations', { project_id: projectId, title: round.title });
      const conversationId = created.json && created.json.conversation && created.json.conversation.id;
      if (!conversationId) throw new Error(`conversation_create_failed_${round.key}`);

      // 新会话须被工作区自动选中（列表按 updated_at DESC，新建即最新）
      await lib.evalJs(client, `location.href = 'http://localhost:3000/project/${projectId}'; 'nav'`);
      await sleep(5000);
      client = await attachWorkspacePage();
      const ready = await waitComposer(client);
      await lib.evalJs(client, INSTALL_RECORDER).catch(() => null);
      const before = await waitTrigger(client);
      if (round.level !== 'standard' || (before && before.level !== round.level)) {
        await setLevel(client, round.level);
      }
      const after = await waitTrigger(client);
      const typedSent = await typeAndSend(client, round.prompt);
      const waited = await waitAssistantMessage(conversationId);
      const sentBodies = await readSentBodies(client);
      // UI-272 展示面核对：展开「执行记录」后再数思考行（工具轮专用）
      let expandClick = null;
      let reasoningRowsExpanded = null;
      if (round.expandActivity) {
        expandClick = await lib.evalJs(client, `(function(){
          var b = document.querySelector('.sc-tool-activity-summary');
          if (!b) return 'no_activity_summary';
          b.click();
          return 'clicked';
        })()`).catch((e) => 'err:' + String(e.message).slice(0, 60));
        await sleep(1200);
        reasoningRowsExpanded = await lib.evalJs(client, REASONING_ROWS).catch(() => null);
      }
      const messages = waited.messages || [];
      const userProbe = round.prompt.slice(0, 12);
      const boundToConversation = messages.some((m) => m.role === 'user' && String(m.content || '').includes(userProbe));
      const records = readRecords(conversationId).map(summarizeRecord);
      const meta = metaOf(waited.assistant);
      const reasoningByIteration = meta.reasoningByIteration && typeof meta.reasoningByIteration === 'object'
        ? meta.reasoningByIteration
        : {};
      const reasoningRows = await lib.evalJs(client, REASONING_ROWS).catch(() => null);

      roundEvidence.push({
        key: round.key,
        conversationId,
        requestedLevel: round.level,
        composerLevelBeforeSwitch: before ? before.level : null,
        composerLevelAfterSwitch: after ? after.level : null,
        composerReady: ready,
        typed: typedSent.typed,
        send: typedSent.sent,
        uiSentBodies: sentBodies,
        boundToConversation,
        assistantTimedOut: !!waited.timedOut,
        assistantMessageId: waited.assistant ? waited.assistant.id : null,
        assistantContentPreview: waited.assistant ? String(waited.assistant.content || '').slice(0, 400) : null,
        reasoningIterations: Object.keys(reasoningByIteration),
        reasoningLengths: Object.fromEntries(Object.entries(reasoningByIteration).map(([k, v]) => [k, String(v || '').length])),
        reasoningRowsInDom: reasoningRows,
        activityExpandClick: expandClick,
        reasoningRowsInDomExpanded: reasoningRowsExpanded,
        transcriptFile: transcriptFile(conversationId),
        upstreamRecords: records,
      });

      await lib.screenshotPng(client, EVIDENCE_DIR, `block81-p3-${round.key}.png`).catch(() => null);
    }

    const [std, high] = roundEvidence;
    const uiBodies = (round) => (round.uiSentBodies || []).filter((b) => b.conversationId === round.conversationId);

    /* 4) 断言：标准档 = 上游零思考参数 */
    run.assert('R1_default_standard', std.composerLevelBeforeSwitch === 'standard',
      `新会话档位控件默认 data-level=${std.composerLevelBeforeSwitch}（默认标准）`);
    run.assert('R1_ui_body_standard', uiBodies(std).length > 0 && uiBodies(std).every((b) => b.thinkingLevel === 'standard'),
      `UI 实发请求体 thinkingLevel 全为 standard（实测 ${JSON.stringify(uiBodies(std).map((b) => b.thinkingLevel))}）`);
    run.assert('R1_ui_bound_to_conversation', !!std.boundToConversation,
      `发送落到了本轮新建会话 ${std.conversationId}（会话级隔离）`);
    run.assert('R1_upstream_records_present', std.upstreamRecords.length > 0,
      `标准档会话信息流落盘 ${std.upstreamRecords.length} 条上游记录`);
    run.assert('R1_no_reasoning_param', std.upstreamRecords.length > 0 && std.upstreamRecords.every((r) => r.reasoningKeys.length === 0),
      `标准档全部上游请求体均无思考参数（参数键实测：${JSON.stringify(std.upstreamRecords.map((r) => r.sentParamKeys))}）`);

    /* 5) 断言：高档 = 上游确实收到 reasoning_effort=high */
    run.assert('R2_control_set_high', high.composerLevelAfterSwitch === 'high',
      `控件切到高（data-level=${high.composerLevelAfterSwitch}）`);
    run.assert('R2_ui_body_high', uiBodies(high).length > 0 && uiBodies(high).every((b) => b.thinkingLevel === 'high'),
      `UI 实发请求体 thinkingLevel=high（实测 ${JSON.stringify(uiBodies(high).map((b) => b.thinkingLevel))}）——档位控件到请求体不再静默失效`);
    run.assert('R2_ui_bound_to_conversation', !!high.boundToConversation,
      `发送落到了本轮新建会话 ${high.conversationId}`);
    const highWithParam = high.upstreamRecords.filter((r) => r.reasoningKeys.includes('reasoning_effort'));
    run.assert('R2_reasoning_effort_sent', highWithParam.length > 0 && highWithParam.every((r) => r.reasoning_effort === 'high'),
      `上游请求体实测 reasoning_effort=high（${highWithParam.length}/${high.upstreamRecords.length} 条记录携带；值=${JSON.stringify(highWithParam.map((r) => r.reasoning_effort))}）`);

    /* 6) 工具轮：UI-272 思考段展示面实机核对（思考行只存在于「执行记录」内） */
    const tool = roundEvidence[2];
    const toolWithParam = tool.upstreamRecords.filter((r) => r.reasoningKeys.includes('reasoning_effort'));
    run.assert('R4_tool_round_param_sent', toolWithParam.length > 0 && toolWithParam.every((r) => r.reasoning_effort === 'high'),
      `工具轮上游请求体同样携带 reasoning_effort=high（${toolWithParam.length}/${tool.upstreamRecords.length} 条记录）`);
    const toolReasoningChars = Object.values(tool.reasoningLengths || {}).reduce((n, v) => n + Number(v || 0), 0);
    run.assert('R4_reasoning_row_visible', toolReasoningChars > 0 && Number(tool.reasoningRowsInDomExpanded) > 0,
      `展开「执行记录」后渲染出思考行（meta 思考字数=${toolReasoningChars}，DOM .sc-tool-reasoning=${tool.reasoningRowsInDomExpanded}，展开点击=${tool.activityExpandClick}）`);

    /* 6) 观测（非判定）：上游响应侧是否真的产生思考段 / 是否走了 D3 去参重试 */
    const stdReasoning = std.upstreamRecords.reduce((n, r) => n + r.reasoningLength, 0);
    const highReasoning = high.upstreamRecords.reduce((n, r) => n + r.reasoningLength, 0);
    const highErrors = high.upstreamRecords.filter((r) => r.error);
    const droppedRetry = high.upstreamRecords.filter((r) => r.reasoningKeys.length === 0 && !r.error);
    observations.responseEvidence = {
      standard: {
        upstreamCalls: std.upstreamRecords.length,
        reasoningChars: stdReasoning,
        reasoningRowsInDom: std.reasoningRowsInDom,
        reasoningIterations: std.reasoningIterations,
        reasoningLengths: std.reasoningLengths,
        finishReasons: std.upstreamRecords.map((r) => r.finishReason),
        errors: std.upstreamRecords.map((r) => r.error).filter(Boolean),
      },
      high: {
        upstreamCalls: high.upstreamRecords.length,
        reasoningChars: highReasoning,
        reasoningRowsInDom: high.reasoningRowsInDom,
        reasoningIterations: high.reasoningIterations,
        reasoningLengths: high.reasoningLengths,
        finishReasons: high.upstreamRecords.map((r) => r.finishReason),
        errors: high.upstreamRecords.map((r) => r.error).filter(Boolean),
        paramDroppedRetryRecords: droppedRetry.length,
      },
      verdict: highErrors.length > 0
        ? 'upstream_rejected_param'
        : highReasoning > 0
          ? 'upstream_emitted_reasoning'
          : 'upstream_accepted_param_no_reasoning_emitted',
    };
    observations.responseEvidence.upstreamReasoningNote = '响应侧思考段取自上游流式 delta（前端 conversationRunStore 按迭代聚合 → 消息 meta.reasoningByIteration）；'
      + '信息流落盘的聚合 response.reasoningContent 为空属落盘面事实（agent 路径走 chatStream，聚合体不含 reasoning_content），展示面不受影响。';
    observations.responseEvidence.toolRound = {
      upstreamCalls: tool.upstreamRecords.length,
      reasoningChars: toolReasoningChars,
      reasoningRowsInDomExpanded: tool.reasoningRowsInDomExpanded,
      reasoningIterations: tool.reasoningIterations,
      reasoningLengths: tool.reasoningLengths,
      activityExpandClick: tool.activityExpandClick,
      assistantContentPreview: tool.assistantContentPreview,
    };
    run.assert('R3_response_captured', std.upstreamRecords.length > 0 && high.upstreamRecords.length > 0,
      `两轮响应均已捕获（标准 ${std.upstreamRecords.length} 条 / 高 ${high.upstreamRecords.length} 条上游记录，判定=${observations.responseEvidence.verdict}）`);

    observations.rounds = roundEvidence;

    return await run.finish({ observations });
  } catch (err) {
    run.assert('RUN_COMPLETED', false, `脚本异常：${err && err.message ? err.message : String(err)}`);
    observations.error = String((err && err.stack) || err).slice(0, 1200);
    return await run.finish({ observations });
  } finally {
    if (patchedProfiles) {
      const restore = await req('POST', '/api/ai/settings', { model_profiles: patchedProfiles }).catch(() => null);
      lib.log(`capability restore: HTTP ${restore ? restore.status : 'failed'}`);
    }
    try { client?.socket?.close(); } catch { /* ignore */ }
  }
})().then((payload) => {
  process.exit(payload && payload.allPass ? 0 : 1);
}).catch((e) => {
  console.error('FATAL', e && e.message);
  process.exit(2);
});

#!/usr/bin/env node
'use strict';
/**
 * block82-thinking-compat-live.cjs — BLOCK-82 P2 实机验收（sensenova 真渠道）。
 *
 * 本包核心：sensenova 上游思考段字段名为 `reasoning`，我方解析面此前只认
 * `reasoning_content` → 该渠道思考段整段丢失。P1 修复 = 解析归一（reasoning_content
 * 优先 / reasoning 兜底）。本脚本用真实 sensenova 渠道跑两轮对话证明：
 *   C0 配置面   — sensenova profile 已声明 capabilities.reasoning（思考档位发参前提）；
 *   C1 标准档   — 请求体零思考参数（BLOCK-81 additive 红线回归）；
 *   C2 高档     — 上游收到 reasoning_effort=high（能力位门控放行 + 映射生效）；
 *   C3 归一生效 — 上游 reasoning 字段思考段经归一以 reasoningContent 落 transcript
 *                 （记录面）且 meta.reasoningByIteration 落库（会话面）——修复前必为空；
 *   C4 标准档归一 — sensenova 默认产思考段（probe 证实），standard 不发参但思考段
 *                 同样归一可达（本包修复对默认路径同等受益）；
 *   C5 内容主路径 — assistant 正文非空（零破坏）。
 *
 * 判定纪律：上游是否产思考段由渠道决定；若上游未产思考段，C3/C4 如实 fail 并记录
 * 原始形状，不编造效果。证据落 acceptance/block-82/。
 *
 * 前置：dev 栈在跑（3001 API；3000 Vite + 9222 CDP 不被本脚本直接依赖）；
 * 改了 core/ 必须重启 dev 栈。模型渠道=sensenova（model-1788504346152）。
 */

const fs = require('node:fs');
const path = require('node:path');
const http = require('node:http');

const ROOT = path.join(__dirname, '..');
const lib = require(path.join(ROOT, '.agents', 'skills', 'petri-dev-infra', 'dev-verify', 'lib.cjs'));

const API = 'http://127.0.0.1:3001';
const AUTH = { Authorization: 'Bearer desktop-local' };
const DATA_DIR = process.env.PETRI_LOCAL_DATA_DIR || path.join(ROOT, '.petri-dev-user-data', 'data');
const TRANSCRIPT_DIR = path.join(DATA_DIR, 'llm-transcripts');
const EVIDENCE_DIR = path.join(ROOT, 'acceptance', 'block-82');

const SENSO_PROFILE_ID = 'model-1788504346152';
// 数学题触发思考段（照抄 BLOCK-81 P3 prompt 思路）
const PROMPT = '一个班有 30 名学生，其中 60% 是女生。把 5 名男生换成女生后，女生有多少人？请先推理再只输出最后结论一行，不要使用任何工具。';
const THINKING_PARAM_KEYS = ['reasoning_effort', 'thinking', 'enable_thinking'];

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

function req(method, p, body) {
  return new Promise((resolve, reject) => {
    const data = body ? JSON.stringify(body) : null;
    const r = http.request({
      host: '127.0.0.1',
      port: 3001,
      path: p,
      method,
      headers: {
        ...AUTH,
        ...(data ? { 'content-type': 'application/json', 'content-length': Buffer.byteLength(data) } : {}),
      },
    }, (res) => {
      let d = '';
      res.on('data', (c) => { d += c; });
      res.on('end', () => {
        try { resolve({ status: res.statusCode, json: JSON.parse(d || '{}') }); } catch { resolve({ status: res.statusCode, json: null, raw: d.slice(0, 300) }); }
      });
    });
    r.on('error', reject);
    r.setTimeout(30000, () => r.destroy(new Error('client timeout')));
    if (data) r.write(data);
    r.end();
  });
}

function safeIdPart(value) {
  const cleaned = String(value || '').replace(/[^A-Za-z0-9_-]+/g, '_').replace(/^_+|_+$/g, '');
  return cleaned || 'unattributed';
}

function readRecords(conversationId) {
  try {
    return fs.readFileSync(path.join(TRANSCRIPT_DIR, `${safeIdPart(conversationId)}.jsonl`), 'utf8')
      .split('\n')
      .filter((line) => line.trim())
      .map((line) => { try { return JSON.parse(line); } catch { return null; } })
      .filter(Boolean);
  } catch {
    return [];
  }
}

function sentParams(record) {
  try {
    const parsed = JSON.parse((record && record.request && record.request.params) || '{}');
    return parsed && typeof parsed === 'object' ? parsed : {};
  } catch {
    return {};
  }
}

function summarizeRecord(record) {
  const params = sentParams(record);
  const response = record.response || null;
  return {
    attemptIndex: record.attemptIndex,
    profileId: record.profileId || null,
    model: record.model || null,
    sentParamKeys: Object.keys(params).filter((k) => k !== 'model').sort(),
    thinkingKeys: THINKING_PARAM_KEYS.filter((k) => k in params),
    reasoning_effort: params.reasoning_effort === undefined ? null : params.reasoning_effort,
    error: record.error || null,
    finishReason: response ? response.finishReason : null,
    contentLength: response && typeof response.content === 'string' ? response.content.length : 0,
    reasoningLength: response && typeof response.reasoningContent === 'string' ? response.reasoningContent.length : 0,
    reasoningPreview: response && typeof response.reasoningContent === 'string'
      ? response.reasoningContent.slice(0, 200)
      : null,
  };
}

async function createConversation(title) {
  const r = await req('POST', '/api/ai/conversations', { title });
  if (r.status !== 200 || !r.json || !r.json.conversation) throw new Error(`create_conversation_failed:${r.status}`);
  return r.json.conversation.id;
}

async function runAgentRound(conversationId, thinkingLevel) {
  const body = {
    conversationId,
    modelPresetId: SENSO_PROFILE_ID,
    thinkingLevel,
    messages: [{ role: 'user', content: PROMPT }],
  };
  return req('POST', '/api/ai/agent', body);
}

async function waitAssistantMessage(conversationId, timeoutMs = 180000) {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    const r = await req('GET', `/api/ai/conversations/${encodeURIComponent(conversationId)}/messages?limit=50`);
    const messages = (r.json && r.json.messages) || [];
    const assistant = messages.filter((m) => m.role === 'assistant' && String(m.content || '').trim().length > 0);
    if (assistant.length > 0) {
      // 落库后可能仍在写 meta，短暂稳定期再取终值（照抄 BLOCK-81 P3 节奏）
      await sleep(2500);
      const r2 = await req('GET', `/api/ai/conversations/${encodeURIComponent(conversationId)}/messages?limit=50`);
      const again = ((r2.json && r2.json.messages) || []).filter((m) => m.role === 'assistant' && String(m.content || '').trim().length > 0);
      return again.length > 0 ? again[again.length - 1] : assistant[assistant.length - 1];
    }
    await sleep(3000);
  }
  return null;
}

function metaOf(message) {
  if (!message) return {};
  if (message.meta && typeof message.meta === 'object') return message.meta;
  try { return JSON.parse(message.meta_json || '{}'); } catch { return {}; }
}

function reasoningCharsOfMeta(meta) {
  const byIter = meta && meta.reasoningByIteration;
  if (!byIter || typeof byIter !== 'object') return 0;
  return Object.values(byIter).reduce((acc, v) => acc + (typeof v === 'string' ? v.length : 0), 0);
}

(async () => {
  const run = lib.createRun({ name: 'block-82-thinking-compat', evidenceDir: EVIDENCE_DIR });
  const observations = {};

  try {
    /* 0) API 就绪 */
    let apiReady = false;
    for (let i = 0; i < 10; i += 1) {
      const r = await req('GET', '/api/data/projects').catch(() => null);
      if (r && r.status === 200) { apiReady = true; break; }
      await sleep(2000);
    }
    run.assert('ENV_api_ready', apiReady, '3001 API 就绪');

    /* C0 配置面：sensenova 声明 reasoning 能力位 */
    const settingsRes = await req('GET', '/api/ai/settings');
    const settings = (settingsRes.json && settingsRes.json.settings) || {};
    const senso = (settings.model_profiles || []).find((p) => p.id === SENSO_PROFILE_ID);
    const hasReasoningCap = !!senso && Array.isArray(senso.capabilities) && senso.capabilities.includes('reasoning');
    run.assert('C0_config_capability', hasReasoningCap,
      `sensenova(${SENSO_PROFILE_ID}) capabilities=${JSON.stringify(senso ? senso.capabilities : null)} 含 reasoning`);

    /* C1-C2 两轮真实对话 */
    const convStd = await createConversation(`BLOCK-82 标准档 ${Date.now()}`);
    const stdSent = await runAgentRound(convStd, 'standard');
    run.assert('RUN_std_accepted', stdSent.status === 200, `standard 轮 POST /api/ai/agent HTTP ${stdSent.status}`);

    const stdAssistant = await waitAssistantMessage(convStd);
    run.assert('RUN_std_replied', !!stdAssistant, `standard 轮 assistant 回复${stdAssistant ? ` ${String(stdAssistant.content).length} 字` : '（180s 超时）'}`);

    const convHigh = await createConversation(`BLOCK-82 高档 ${Date.now()}`);
    const highSent = await runAgentRound(convHigh, 'high');
    run.assert('RUN_high_accepted', highSent.status === 200, `high 轮 POST /api/ai/agent HTTP ${highSent.status}`);

    const highAssistant = await waitAssistantMessage(convHigh);
    run.assert('RUN_high_replied', !!highAssistant, `high 轮 assistant 回复${highAssistant ? ` ${String(highAssistant.content).length} 字` : '（180s 超时）'}`);

    const stdRecords = readRecords(convStd).map(summarizeRecord);
    const highRecords = readRecords(convHigh).map(summarizeRecord);
    observations.stdRecords = stdRecords;
    observations.highRecords = highRecords;
    // 会话 transcript 是会话级归档：主迭代轮之外还有标题生成等辅助调用
    // （走默认 chat 渠道、不带档位参数，本就不该发）——档位断言只针对 sensenova 记录。
    const stdSenso = stdRecords.filter((r) => r.profileId === SENSO_PROFILE_ID);
    const highSenso = highRecords.filter((r) => r.profileId === SENSO_PROFILE_ID);
    observations.stdSensoRounds = stdSenso.length;
    observations.highSensoRounds = highSenso.length;

    /* C1 标准档：请求体零思考参数（additive 红线回归） */
    run.assert('C1_std_no_thinking_param', stdSenso.length > 0 && stdSenso.every((r) => r.thinkingKeys.length === 0),
      `standard 轮 sensenova ${stdSenso.length} 条上游记录全部零思考参数（sentParamKeys=${JSON.stringify(stdSenso.map((r) => r.sentParamKeys))}）`);

    /* C2 高档：上游收到 reasoning_effort=high */
    run.assert('C2_high_sends_reasoning_effort', highSenso.length > 0 && highSenso.every((r) => r.reasoning_effort === 'high'),
      `high 轮 sensenova ${highSenso.length} 条上游记录 reasoning_effort 全为 high（实测=${JSON.stringify(highSenso.map((r) => r.reasoning_effort))}；会话内辅助调用走默认渠道不涉档位）`);

    /* C3 归一生效（核心）：上游 reasoning 字段思考段经事件流归一 → meta.reasoningByIteration 落库。
     * 注：思考段走事件流（reasoning_delta）路径进 meta；transcript 聚合记录面的 message
     * 本就不保留思考段（无论是否归一，sensenova 记录 response 无 reasoningContent 字段，
     * io-transcript 归一为防御性一致，由契约测试覆盖）——如实登记，不作为实机断言。 */
    const highMetaChars = reasoningCharsOfMeta(metaOf(highAssistant));
    observations.highMetaReasoningChars = highMetaChars;
    observations.highSensoReasoningCharsInTranscript = highSenso.reduce((acc, r) => acc + r.reasoningLength, 0);
    run.assert('C3_high_reasoning_normalized', highMetaChars > 0,
      `high 轮 sensenova 思考段经归一落库：meta.reasoningByIteration 共 ${highMetaChars} 字（修复前恒 0——sensenova 字段名 reasoning，旧解析只认 reasoning_content）`);

    /* C4 标准档归一：sensenova 默认产思考段（不发参路径同样受益） */
    const stdMetaChars = reasoningCharsOfMeta(metaOf(stdAssistant));
    observations.stdMetaReasoningChars = stdMetaChars;
    run.assert('C4_std_reasoning_normalized', stdMetaChars > 0,
      `standard 轮（零思考参数）sensenova 思考段同样经归一落库：meta.reasoningByIteration 共 ${stdMetaChars} 字`);

    /* C5 内容主路径零破坏 */
    run.assert('C5_content_intact',
      !!stdAssistant && String(stdAssistant.content).trim().length > 0
      && !!highAssistant && String(highAssistant.content).trim().length > 0,
      `两会话 assistant 正文非空（std=${stdAssistant ? String(stdAssistant.content).length : 0} 字 / high=${highAssistant ? String(highAssistant.content).length : 0} 字）`);
  } catch (err) {
    observations.error = String((err && err.stack) || err).slice(0, 1200);
    return run.finish({ observations });
  }

  return run.finish({ observations });
})().then((payload) => {
  process.exit(payload && payload.allPass ? 0 : 1);
}).catch((e) => {
  console.error('FATAL', e && e.message);
  process.exit(2);
});

#!/usr/bin/env node
'use strict';

/**
 * BLOCK-83 P1 出口实机验收：15 生信插件链在 P1 改动（D1 改名 / D2 SDK 放宽 / D3 钩子化）后完好。
 *
 * 运行（对标 BLOCK-79/82 in-process 驱动先例，需 fnm Node 24 + dev 数据面 env）：
 *   export PATH="/c/Users/Admin/AppData/Roaming/fnm/node-versions/v24.20.0/installation:$PATH"
 *   export PETRI_DB_PATH='D:\1.WorkDir\petri-desktop\.petri-dev-user-data\data\petri.db'
 *   export PETRI_LOCAL_DATA_DIR='D:\1.WorkDir\petri-desktop\.petri-dev-user-data\data'
 *   node scripts/block83-p1-plugin-live.cjs
 *
 * 断言：
 *   A1 mcp registry 注册面含全部 15 个生信插件工具
 *   A2 D3 过渡装配在进程内生效（scientific-task-confirmation 钩子已注册）
 *   A3 run_tool 对 R 插件呈诚实结构化失败（本机无 R；若命中科学确认门则同时实证钩子链）
 *   A4 RS 全量 descriptor 的 4 插件严格 lint 通过（D2 放宽后 .R 契约继续合法）
