}

const pluginLoader = require(path.join(ROOT, 'core/petri-server/plugin-loader.js'));
const catalogRoutes = require(path.join(ROOT, 'core/petri-server/routes/tools-catalog.js'));

const packJsonPath = path.join(packRoot, 'pack.json');
const pack = fs.existsSync(packJsonPath) ? JSON.parse(fs.readFileSync(packJsonPath, 'utf8')) : null;
assert('P0_pack_manifest_present', !!pack && !!pack.packId, pack ? pack.packId : 'pack.json 缺失');

const manifests = pluginLoader.ensurePluginSourcesLoaded();
const declared = pack && pack.provenance ? null : null; // 声明插件数由清单文件决定，这里以实际加载为准
assert('P1_plugins_load_from_pack', manifests.length > 0,
  '从包加载插件数=' + manifests.length + '（内置源=' + emptyBuiltIn + ' 为空）');

const pluginDirsInPack = fs.readdirSync(pluginsDir, { withFileTypes: true })
  .filter((e) => e.isDirectory() && fs.existsSync(path.join(pluginsDir, e.name, 'plugin.json')))
  .map((e) => e.name);
const loadedFromPack = manifests.filter((m) => {
  const dir = (m.execution && m.execution.pluginDir) || '';
  return dir && path.resolve(dir).startsWith(path.resolve(pluginsDir));
});
assert('P1b_all_loaded_plugins_come_from_pack', loadedFromPack.length === manifests.length,
  loadedFromPack.length + '/' + manifests.length + ' 来自包（包内插件目录 ' + pluginDirsInPack.length + ' 个）');

const sample = manifests.find((m) => m.id === 'deseq2') || manifests[0];
assert('P2_manifest_contract_compat',
  !!sample && typeof sample.title === 'string' && typeof sample.category === 'string' && Array.isArray(sample.inputs),
  sample ? JSON.stringify({ id: sample.id, title: sample.title, category: sample.category, inputs: sample.inputs.length }) : 'no manifest');

const catalog = manifests.map(catalogRoutes._toCatalogEntry).filter(Boolean);
assert('P3_catalog_projects_from_pack', catalog.length === manifests.length && catalog.length > 0,
  '目录条目=' + catalog.length);

const summary = {
  generatedAt: new Date().toISOString(),
  block: 'BLOCK-83-P4-PACK-SOURCE',
  packRoot,
  packId: pack ? pack.packId : null,
  env: { node: process.version, builtInSource: emptyBuiltIn, installedSource: pluginsDir },
  totals: { pass: results.filter((r) => r.ok).length, fail: results.filter((r) => !r.ok).length, all: results.length },
  loadedPluginIds: manifests.map((m) => m.id).sort(),
  results,
};
const outDir = path.join(ROOT, 'acceptance/block-83');
fs.mkdirSync(outDir, { recursive: true });
fs.writeFileSync(path.join(outDir, 'block83-pack-source-live.json'), JSON.stringify(summary, null, 2));
console.log('---');
console.log('包源装卸缝: ' + summary.totals.pass + '/' + summary.totals.all + ' allPass=' + (summary.totals.fail === 0));
console.log('evidence: acceptance/block-83/block83-pack-source-live.json');
process.exitCode = summary.totals.fail === 0 ? 0 : 1;

#!/usr/bin/env node
'use strict';
/**
 * BLOCK-84 P2 前端实机验收：CDP 驱动商店「领域包」分区（dev Electron 边界内）。
 *
 * 路径：软导航（Page.navigate）→ local 项目商店页 → 领域包分区。
 *
 * 环境纪律（P2 实机抓真，务必遵守）：
 *  1) origin 必须用 http://localhost:3000。后端 CORS 白名单口径是
 *     PETRI_TRUSTED_DESKTOP_ORIGINS（env-coordinator 注入，含 localhost:3000）；
 *     页面若跑在 http://127.0.0.1:3000 会被 CORS 拒（无 ACAO 头）→ 渲染进程
 *     fetch failed（网络层其实 200）→ getProject 返回 null → 全屏
 *     「项目不存在或无权访问」，商店页无从渲染。
 *  2) 导航必须用 CDP Page.navigate（软导航）。location.href 硬导航会触发欢迎页
 *     的 auto-navigate，把 URL 弹回 allProjects[0]（很可能是不可达的 ssh 项目）。
 *  3) 必须选 local 项目（workspace_kind='local'），ssh 项目远端不可达时工作区加载
 *     失败，同样看不到商店页。
 *
 * 断言：
 *   U1 页面可达
 *   U2 商店页可达且非错误屏
 *   U3 「领域包」分区可见（data-testid="domain-packs-section"）
 *   U4 包卡片存在（data-testid="domain-pack-<packId>"）
 *   U5 桥 listInstalled 返回非空且与分区渲染一致
 *   U6 分区含「重启」诚实提示
 * 证据：acceptance/block-84/block84-p2-ui-live.json
 */
const fs = require('fs');
const path = require('path');
const http = require('node:http');

const ROOT = path.resolve(__dirname, '..');
const results = [];
function assert(name, ok, detail) {
  results.push({ name, ok: !!ok, detail: detail == null ? '' : String(detail).slice(0, 400) });
  console.log((ok ? 'PASS' : 'FAIL') + ' — ' + name + (ok ? '' : ' :: ' + String(detail).slice(0, 400)));
}
function sleep(ms) { return new Promise((r) => setTimeout(r, ms)); }

function fetchJson(url) {
  return new Promise((resolve, reject) => {
    http.get(url, (res) => { let d = ''; res.on('data', (c) => (d += c)); res.on('end', () => resolve(JSON.parse(d))); }).on('error', reject);
  });
}

function cdpEval(expr, timeoutMs = 25000) {
  return new Promise(async (resolve, reject) => {
    try {
      const targets = await fetchJson('http://127.0.0.1:9222/json/list');
      const page = targets.find((t) => t.type === 'page');
      if (!page) return reject(new Error('no page target'));
      const ws = new WebSocket(page.webSocketDebuggerUrl);
      const timer = setTimeout(() => { try { ws.close(); } catch {} reject(new Error('cdp timeout')); }, timeoutMs);
      ws.addEventListener('open', () => {
        ws.send(JSON.stringify({ id: 1, method: 'Runtime.evaluate', params: { expression: expr, awaitPromise: true, returnByValue: true } }));
      });
      ws.addEventListener('message', (ev) => {
        const p = JSON.parse(ev.data);
        if (p.id !== 1) return;
        clearTimeout(timer);
        try { ws.close(); } catch {}
        if (p.result && p.result.exceptionDetails) {
          const t = p.result.exceptionDetails;
          return reject(new Error('JS: ' + (t.text || '') + ' ' + ((t.exception && t.exception.description) || '')));
        }
        resolve(p.result && p.result.result ? p.result.result.value : undefined);
      });
      ws.addEventListener('error', (e) => { clearTimeout(timer); reject(new Error('ws: ' + (e && e.message))); });
    } catch (e) { reject(e); }
  });
}

const RENDERER_BASE = 'http://localhost:3000';

/** CDP 软导航：不改 location.href，避免欢迎页 auto-navigate 把 URL 弹回兜底项目。 */
function cdpNavigate(url, timeoutMs = 25000) {
  return new Promise(async (resolve, reject) => {
    try {
      const targets = await fetchJson('http://127.0.0.1:9222/json/list');
      const page = targets.find((t) => t.type === 'page');
      if (!page) return reject(new Error('no page target'));
      const ws = new WebSocket(page.webSocketDebuggerUrl);
      const timer = setTimeout(() => { try { ws.close(); } catch {} reject(new Error('cdp nav timeout')); }, timeoutMs);
      ws.addEventListener('open', () => {
        ws.send(JSON.stringify({ id: 1, method: 'Page.enable', params: {} }));
        ws.send(JSON.stringify({ id: 2, method: 'Page.navigate', params: { url } }));
      });
      ws.addEventListener('message', (ev) => {
        const p = JSON.parse(ev.data);
        if (p.id !== 2) return;
        clearTimeout(timer);
        try { ws.close(); } catch {}
        resolve(true);
      });
      ws.addEventListener('error', (e) => { clearTimeout(timer); reject(new Error('ws: ' + (e && e.message))); });
    } catch (e) { reject(e); }
  });
}

/** 从后端取一个 local 工作区项目（ssh 项目远端不可达时工作区加载失败）。 */
function pickLocalProject() {
  return new Promise((resolve) => {
    http.get('http://127.0.0.1:3001/api/data/projects', (res) => {
      let d = '';
      res.on('data', (c) => (d += c));
      res.on('end', () => {
        try {
          const j = JSON.parse(d);
          const list = Array.isArray(j.projects) ? j.projects : [];
          const local = list.find((p) => p.workspace_kind === 'local' && p.status !== 'archived');
          resolve(local || null);
        } catch { resolve(null); }
      });
    }).on('error', () => resolve(null));
  });
}

async function main() {
  // U1
  const href0 = await cdpEval('location.href');
  assert('U1_page_reachable', typeof href0 === 'string' && href0.startsWith('http'), 'href=' + href0);

  // 解析 local 项目（ssh 项目会因远端不可达导致工作区加载失败）
  const localProject = await pickLocalProject();
  console.log('  local project:', localProject ? localProject.id + ' / ' + localProject.name : 'NOT FOUND');
  const targetProjectId = localProject ? localProject.id : 'p_mtkamsfu_3mxo';

  // 软导航到商店页（localhost origin + local 项目）
  const storeUrl = `${RENDERER_BASE}/project/${targetProjectId}/plugins`;
  await cdpNavigate(storeUrl).catch((e) => console.log('  navErr:', e.message));
  await sleep(12000);

  // U2 商店页
  const href = await cdpEval('location.href');
  const bodyText = await cdpEval('document.body.innerText');
  const onErrorScreen = typeof bodyText === 'string' && bodyText.includes('项目不存在或无权访问');
  assert('U2_store_reached', typeof href === 'string' && href.includes('/plugins') && !onErrorScreen,
    'href=' + href + ' errorScreen=' + onErrorScreen);

  // U3 分区
  const sectionExists = await cdpEval(`!!document.querySelector('[data-testid="domain-packs-section"]')`);

  // U4 卡片
  const cards = await cdpEval(`Array.from(document.querySelectorAll('[data-testid^="domain-pack-"]')).map(function(e){return e.getAttribute('data-testid')})`);

  // U5 桥
  const bridgeRaw = await cdpEval(`window.petriDesktop.packs.listInstalled().then(function(r){return JSON.stringify(r)}).catch(function(e){return 'ERR:'+e.message})`);
  let bridgeInstalled = 0;
  try {
    const parsed = JSON.parse(bridgeRaw);
    bridgeInstalled = Array.isArray(parsed.packs) ? parsed.packs.length : (Array.isArray(parsed) ? parsed.length : 0);
  } catch {}

  assert('U3_domain_packs_section_visible', sectionExists === true, 'sectionExists=' + sectionExists);
  assert('U4_pack_card_present', Array.isArray(cards) && cards.length >= 1, 'cards=' + JSON.stringify(cards));
  assert('U5_bridge_matches_section', bridgeInstalled >= 1 && sectionExists === true,
    'bridgeInstalled=' + bridgeInstalled + ' section=' + sectionExists);
  assert('U6_restart_hint_present', typeof bodyText === 'string' && /重启/.test(bodyText),
    'has重启=' + (typeof bodyText === 'string' && /重启/.test(bodyText)));

  const summary = {
    ok: results.every((r) => r.ok),
    total: results.length,
    passed: results.filter((r) => r.ok).length,
    failed: results.filter((r) => !r.ok).length,
    targetProjectId,
    storeUrl,
    href,
    cards,
    bridgeInstalled,
    results,
  };
  console.log('\n' + (summary.ok ? 'ALL PASS' : 'HAS FAILURES') + ' — ' + summary.passed + '/' + summary.total);

  const outDir = path.join(ROOT, 'acceptance', 'block-84');
  fs.mkdirSync(outDir, { recursive: true });
  fs.writeFileSync(path.join(outDir, 'block84-p2-ui-live.json'),
    JSON.stringify({ ...summary, capturedAt: new Date().toISOString() }, null, 2));
  console.log('evidence: ' + path.join(outDir, 'block84-p2-ui-live.json'));
  process.exit(summary.ok ? 0 : 1);
}

main().catch((e) => { console.error('FATAL:', e.message); process.exit(2); });

#!/usr/bin/env node
// BLOCK-85 §9.2 Mac 侧出码：打开左栏「联邦」弹层（默认「我的设备」tab），读取自动出码的配对链接。
// 前置：dev 栈在跑且 CDP 9222（PETRI_DEV_ELECTRON_ARGS="--remote-debugging-port=9222" npm run dev）。
// 用法: node scripts/block85-mac-pairing-code.cjs
const fs = require('fs');
const path = require('path');
const {
  pollTargets, filterPageTargets, selectPageTarget, connectTarget, evalJs,
  screenshotPng, createRun,
} = require(path.join(__dirname, '..', '.agents', 'skills', 'petri-dev-infra', 'dev-verify', 'lib.cjs'));

const EVIDENCE_DIR = path.join(__dirname, '..', 'acceptance', 'block-85');

async function main() {
  const run = createRun({ name: 'block85-mac-pairing-code', evidenceDir: EVIDENCE_DIR });
  const targets = await pollTargets({ port: 9222, timeoutMs: 15000 });
  const pages = filterPageTargets(targets, /localhost:3000|127\.0\.0\.1:3000|index\.html/);
  if (!pages.length) throw new Error('no_page_target: ' + targets.map(t => t.url).join(' | '));
  const target = await selectPageTarget(pages, {
    probe: async (c) => evalJs(c, `!!document.querySelector('[data-testid="sidebar-federation"]')`),
  });
  const client = await connectTarget(target);

  // 1. 打开「联邦」弹层（开关语义：已开则不重复点），确保切到「我的设备」tab
  //    （MobileSyncPanel 挂载即自动出码；弹层会记住上次停留的 tab）
  const alreadyOpen = await evalJs(client, `!!document.querySelector('[data-testid="federation-popup"]')`);
  if (!alreadyOpen) {
    await evalJs(client, `document.querySelector('[data-testid="sidebar-federation"]').click(); 'ok'`);
  }
  await evalJs(client, `document.querySelector('[data-testid="federation-tab-devices"]')?.click(); 'ok'`);

  // 2. 轮询等 QR 就绪（后端 TTL 5 分钟，面板打开即生成）
  let qrReady = false;
  for (let i = 0; i < 30 && !qrReady; i++) {
    await new Promise((r) => setTimeout(r, 500));
    qrReady = await evalJs(client, `!!document.querySelector('[data-testid="mobile-pairing-qr"]')`);
  }
  run.assert('federation_popup_open', await evalJs(client, `!!document.querySelector('[data-testid="federation-popup"]')`), '弹层在场');
  run.assert('pairing_qr_present', qrReady, '自动出码 QR 在场（≤15s）');
  if (!qrReady) { console.error('QR 未就绪'); process.exitCode = 1; }

  // 3. 读 token 与 primaryUrl（linkHost 是 CSS module 哈希类，改按 title 属性取完整链接）
  const info = await evalJs(client, `(() => {
    const img = document.querySelector('[data-testid="mobile-pairing-qr"]');
    const link = document.querySelector('[data-testid="mobile-copy-link"] span[title]')
      || document.querySelector('[data-testid="mobile-copy-link"] [title]');
    return { qrSrc: img ? img.getAttribute('src') : null, primaryUrl: link ? link.getAttribute('title') : null };
  })()`);
  const token = info && info.qrSrc ? (info.qrSrc.match(/token=([^&]+)/) || [])[1] : null;
  let url = info ? info.primaryUrl : null;
  if (!url && token) {
    // 兜底：本地 localhost 信任面直接向后端要当前活动码。
    // 注意：每次 POST 都轮转新码（面板 4 分钟自动续码同机制），后端活动码与面板 QR
    // 的 token 天然可能不同步——两者各自有效至各自 5 分钟 TTL，不做同 token 断言。
    const res = await fetch('http://127.0.0.1:3001/api/mobile/pairing/token', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}',
    });
    const data = await res.json();
    run.assert('backend_pairing_url_shape', !!(data && data.ok && /\/pair\?token=/.test(data.primaryUrl || '')),
      '后端直取配对链接形状');
    url = (data && data.primaryUrl) || null;
  }
  run.assert('pairing_token_extracted', !!token, 'QR src 提取 token');
  run.assert('primary_url_pair_shape', !!url && /\/pair\?token=/.test(url), 'primaryUrl 为配对链接: ' + (url || 'null'));
  run.assert('primary_url_lan_not_loopback', !!url && !url.includes('127.0.0.1') && !url.includes('localhost'),
    'BLOCK-85-HOTFIX 契约：primary 走 LAN 不吃 127.0.0.1');

  const shot = await screenshotPng(client, EVIDENCE_DIR, 'mac-pairing-code.png');
  console.log('screenshot: ' + shot);
  console.log('PAIRING_URL: ' + (url || '(未取得)'));
  await run.finish({ primaryUrl: url, lan: '192.168.0.102', gatewayPort: 3005 });
  try { client.socket.close(); } catch { /* ignore */ }
  if (!run.allPass) process.exitCode = 1;
}

main().catch((e) => { console.error('FATAL', e.message); process.exit(1); });

#!/usr/bin/env node
'use strict';

/**
 * BLOCK-85 双真机验收 P2（Runbook §2）：Windows 提交真实分析作业 → fed 转发 → Mac 执行。
 *
 * 链路：POST /api/tools/run（params.executionTargetId=fed:<peerId>，tools-executor.js fed 分支）
 * → 对端以其本地身份跑 deseq2（demo 数据）→ Windows 侧镜像 job 投影。
 * 断言：
 *   A1 提交响应 federated:true + 对端 job 投影（peerName=MacBook-Pro.local）
 *   A2 镜像 job 到终态 completed（轮询 /api/tools/status）
 *   A3 result 语义含对端指纹（executor/outputPath 等，如实记录）
 *   A4 Artifact Truth 在执行端：Windows 本地 staging 无产物拉回
 * 证据：acceptance/block-85/dual-p2-job.json（Runbook 指定路径）
 * 前置：dev 栈 :3001 在跑；peer probe 绿灯；Mac 有 Rscript + DESeq2 库（缺则 failed+run.log 明示，如实登记）。
 */
const path = require('node:path');
const fs = require('node:fs');
const http = require('node:http');

const REPO = path.join(__dirname, '..');
const EVIDENCE = path.join(REPO, 'acceptance', 'block-85');
const API = 'http://127.0.0.1:3001/api';
const AUTH = { Authorization: 'Bearer desktop-local', 'content-type': 'application/json' };
const PEER_ID = process.env.B85_LOCAL ? null : (process.env.B85_PEER_ID || 'gpeer_1b29dffe41f7d531');
const MODE = PEER_ID ? 'fed' : 'local'; // B85_LOCAL=1 → 本地同链验证（job-provenance 收尾修复回归）
const MARKER = 'B85P2-' + Date.now();

function fetchJson(url, opts = {}) {
  return new Promise((resolve, reject) => {
    const req = http.request(url, { method: opts.method || 'GET', headers: opts.headers || {} }, (res) => {
      let d = '';
      res.on('data', (c) => (d += c));
      res.on('end', () => {
        try { resolve(JSON.parse(d)); } catch (e) { resolve({ raw: d.slice(0, 200), status: res.statusCode }); }
      });
    });
    req.on('error', reject);
    if (opts.body) req.write(opts.body);
    req.end();
  });
}

function b64file(p) {
  return fs.readFileSync(p).toString('base64');
}

// demo 输入从 demo-data 端点取（与 UI 同链），不做本地路径依赖
function fetchB64(url) {
  return new Promise((resolve, reject) => {
    http.get(url, (res) => {
      const chunks = [];
      res.on('data', (c) => chunks.push(c));
      res.on('end', () => res.statusCode === 200
        ? resolve(Buffer.concat(chunks).toString('base64'))
        : reject(new Error(`HTTP ${res.statusCode} for ${url}`)));
    }).on('error', reject);
  });
}

async function main() {
  fs.mkdirSync(EVIDENCE, { recursive: true });
  const results = { startedAt: new Date().toISOString(), marker: MARKER, peerId: PEER_ID, assertions: [] };
  const assert = (name, pass, detail = '') => {
    results.assertions.push({ name, pass: !!pass, detail: String(detail).slice(0, 600) });
    try { fs.writeSync(1, '[' + new Date().toISOString().slice(11, 19) + '] ' + (pass ? 'PASS' : 'FAIL') + ' ' + name + (detail ? ' :: ' + String(detail).slice(0, 180) : '') + String.fromCharCode(10)); } catch {}
  };
  const delay = (ms) => new Promise((r) => setTimeout(r, ms));

  // 0) 预检：fed 模式要求 peer 在册
  if (PEER_ID) {
    const peers = await fetchJson(`${API}/federation/peers`, { headers: AUTH });
    const peer = (peers.peers || []).find((p) => p.peerId === PEER_ID);
    assert('P2-0 peer registered', !!peer, JSON.stringify(peers).slice(0, 200));
    if (!peer) throw new Error('peer not registered');
  } else {
    assert('P2-0 local mode (fed dispatch skipped)', true, 'B85_LOCAL=1');
  }

  // 1) 提交作业（fed → Mac 执行；local → 本机同链回归）
  const params = MODE === 'fed'
    ? { design: 'condition', contrast_ref: 'WT', contrast_treat: 'KO', executionTargetId: `fed:${PEER_ID}` }
    : { design: 'condition', contrast_ref: 'WT', contrast_treat: 'KO' };
  const run = await fetchJson(`${API}/tools/run`, {
    method: 'POST', headers: AUTH,
    body: JSON.stringify({
      toolId: 'deseq2',
      params,
      files: {
        'counts.csv': await fetchB64(`${API.replace(/\/api$/, '')}/api/tools/demo-data/deseq2/demo-counts.csv`),
        'coldata.csv': await fetchB64(`${API.replace(/\/api$/, '')}/api/tools/demo-data/deseq2/demo-coldata.csv`),
      },
    }),
  });
  results.submitResponse = run;
  const fedOk = MODE === 'local'
    ? run.ok === true && !!run.jobId
    : run.ok === true && run.federated === true && run.peerId === PEER_ID;
  const jobId = run.jobId || (run.job && run.job.jobId);
  assert('P2-1 submit accepted', fedOk && !!jobId, JSON.stringify(run).slice(0, 300));
  if (!jobId) throw new Error('job submit failed: ' + JSON.stringify(run).slice(0, 200));

  // 2) 轮询到终态（R 冷启动 + DESeq2 加载 +〔fed〕跨网段，给 6 分钟预算）
  const statusUrl = MODE === 'fed'
    ? `${API}/federation/peers/${PEER_ID}/jobs/${jobId}`
    : `${API}/tools/status/${jobId}`;
  let status = null;
  const deadline = Date.now() + 6 * 60 * 1000;
  while (Date.now() < deadline) {
    await delay(5000);
    status = await fetchJson(statusUrl, { headers: AUTH });
    const st = status.status || (status.job && status.job.status);
    if (st === 'completed' || st === 'failed' || st === 'cancelled') break;
  }
  const finalStatus = status && (status.status || (status.job && status.job.status));
  results.finalStatus = status;
  assert('P2-2 mirror job reaches completed', finalStatus === 'completed', `status=${finalStatus} detail=${JSON.stringify(status).slice(0, 300)}`);

  // 3) result 语义（对端指纹如实记录：workspaceKind/executor/outputPath 形状以对端产出为准）
  const rj = status && (status.result || status.result_json || (status.job && (status.job.result || status.job.result_json)));
  let parsed = rj;
  if (typeof rj === 'string') { try { parsed = JSON.parse(rj); } catch {} }
  results.resultJson = parsed;
  assert('P2-3 result present (peer truth)', !!parsed, JSON.stringify(parsed || {}).slice(0, 300));

  // 4) Artifact Truth 在执行端：fed 模式断言 Windows staging 无拉回（local 模式产物本就在本地，跳过）
  if (MODE === 'fed') {
    const candidates = [
      path.join(REPO, '.petri-dev-user-data', 'data', 'results', 'jobs', jobId),
      path.join(REPO, '.petri-dev-user-data', 'data', 'tools-results', jobId),
    ];
    let pulled = [];
    for (const dir of candidates) {
      try { pulled = pulled.concat(fs.readdirSync(dir)); } catch { /* 目录不存在 = 更干净 */ }
    }
    assert('P2-4 no artifact pull-back to Windows staging', pulled.length === 0,
      `local dirs checked: [${candidates.join(', ')}] found: [${pulled.join(', ').slice(0, 120) || 'none'}]`);
  }

  const allPass = results.assertions.length > 0 && results.assertions.every((a) => a.pass);
  results.allPass = allPass;
  results.finishedAt = new Date().toISOString();
  const evidenceName = MODE === 'fed' ? 'dual-p2-job.json' : 'local-p2-regression.json';
  fs.writeFileSync(path.join(EVIDENCE, evidenceName), JSON.stringify(results, null, 2) + '\n');
  process.exit(allPass ? 0 : 1);
}

main().catch((e) => { console.error('LIVE_ERR', e.message); process.exit(1); });

#!/usr/bin/env node
'use strict';

/**
 * BLOCK-85 双真机验收 P3（Runbook §3）：真实模型委托跨机跑通。
 *
 * 链路：POST /api/ai/agent（task 模式，返回 taskId）→ GET /api/ai/agent/task/:taskId
 * 消费 SSE → agent 调 delegate_to_petri_node(peerId, task) → Mac 开独立 agent 会话执行
 * → 回执（状态 + 对方 agent 摘要）回流 Windows 会话。
 * 断言：
 *   A1 事件流出现 delegate_to_petri_node 调用（peerId 正确）
 *   A2 委托回执成功（Mac 侧 agent 执行并返回摘要）
 *   A3 任务终态完成
 * 证据：acceptance/block-85/dual-p3-delegate.json（Runbook 指定路径，含原始事件流）
 * 前置：Windows 侧聊天模型凭据可用；Mac 侧 agent 模型凭据可用（Runbook：DeepSeek）。
 */
const path = require('node:path');
const fs = require('node:fs');
const http = require('node:http');

const REPO = path.join(__dirname, '..');
const EVIDENCE = path.join(REPO, 'acceptance', 'block-85');
const API = 'http://127.0.0.1:3001';
const AUTH = { Authorization: 'Bearer desktop-local', 'content-type': 'application/json' };
const PEER_ID = process.env.B85_PEER_ID || 'gpeer_1b29dffe41f7d531';
const MARKER = 'B85P3-' + Date.now();
const BUDGET_MS = 8 * 60 * 1000;

function postJson(url, body) {
  return new Promise((resolve, reject) => {
    const req = http.request(url, { method: 'POST', headers: AUTH }, (res) => {
      let d = '';
      res.on('data', (c) => (d += c));
      res.on('end', () => { try { resolve(JSON.parse(d)); } catch (e) { reject(new Error('non-JSON: ' + d.slice(0, 200))); } });
    });
    req.on('error', reject);
    req.write(JSON.stringify(body));
    req.end();
  });
}

function consumeSse(url, onEvent) {
  return new Promise((resolve) => {
    const req = http.get(url, { headers: { Authorization: AUTH.Authorization, accept: 'text/event-stream' } }, (res) => {
      let buf = '';
      res.on('data', (c) => {
        buf += c;
        let idx;
        while ((idx = buf.indexOf('\n\n')) !== -1) {
          const frame = buf.slice(0, idx);
          buf = buf.slice(idx + 2);
          const dataLine = frame.split('\n').find((l) => l.startsWith('data:'));
          if (dataLine) {
            try { onEvent(JSON.parse(dataLine.slice(5).trim())); } catch { onEvent({ raw: dataLine.slice(5, 300) }); }
          }
        }
      });
      res.on('end', () => resolve('stream_end'));
      res.on('error', () => resolve('stream_error'));
    });
    req.setTimeout(BUDGET_MS, () => { req.destroy(); resolve('budget_timeout'); });
  });
}

async function main() {
  fs.mkdirSync(EVIDENCE, { recursive: true });
  const results = { startedAt: new Date().toISOString(), marker: MARKER, peerId: PEER_ID, events: [], assertions: [] };
  const assert = (name, pass, detail = '') => {
    results.assertions.push({ name, pass: !!pass, detail: String(detail).slice(0, 900) });
    try { fs.writeSync(1, '[' + new Date().toISOString().slice(11, 19) + '] ' + (pass ? 'PASS' : 'FAIL') + ' ' + name + (detail ? ' :: ' + String(detail).slice(0, 240) : '') + String.fromCharCode(10)); } catch {}
  };

  const submitted = await postJson(`${API}/api/ai/agent`, {
    messages: [{
      role: 'user',
      // 教训（P3 前两轮 FAIL）：
      // ① task 文本带「委托/协作节点/peerId」字样 → Mac agent 二阶歧义，拒绝执行只做侦察；
      // ② 「创建文件」类任务 → 委托会话 projectId:null，文件工具被 project_required 前置拒绝
      //    （delegate 无项目绑定的结构缺口，登记 BLOCK-88 域）；且委托未开独立会话，历史只读纪律延续。
      // ③ 故 P3 载体改为不依赖项目绑定的真实只读委托：跨机系统信息侦察+如实汇报，
      //    委托链断言（调用/回执/终态摘要）不变；分析作业跨机已由 P2 单独足额证明。
      content: `使用 delegate_to_petri_node 工具把一项工作交给协作成员（peerId 填 "${PEER_ID}"）执行。delegate 的 task 参数只写这句话：「汇报你本机的运行环境：操作系统名称与版本、CPU 架构、主机名，以及 Node/npm 的版本号（可用 system_info 等工具查询），以清单形式回复」。委托等待 2 分钟。你自己不要在本机查询这些信息，全部由协作成员完成。`,
    }],
    context: {},
  });
  const taskId = submitted.taskId;
  assert('P3-0 task submitted', !!taskId && submitted.status === 'running', JSON.stringify(submitted).slice(0, 200));
  if (!taskId) throw new Error('agent task submit failed');

  let sawDelegateCall = false;
  let delegateCallDetail = '';
  let delegateReceipt = '';
  let finalText = '';
  let sawDone = false;

  const stop = await consumeSse(`${API}/api/ai/agent/task/${taskId}`, (ev) => {
    const text = JSON.stringify(ev);
    // tool_call/tool_result 必须存全文（JSON 截断会让断言解析失败——第二轮实测坑）
    const isTool = ev.eventType === 'tool_call' || ev.eventType === 'tool_result' || text.includes('toolResult');
    results.events.push(isTool ? text : text.slice(0, 1500));
    if (results.events.length > 4000) return; // 保险丝
    if (text.includes('delegate_to_petri_node')) {
      if (!sawDelegateCall && (ev.eventType === 'tool_call' || ev.eventType === 'tool_start' || text.includes('arguments') || text.includes('arguments_json') || text.includes(PEER_ID))) {
        sawDelegateCall = true;
        delegateCallDetail = text.slice(0, 600);
      }
      if (ev.eventType === 'tool_result' || ev.eventType === 'tool_end' || text.includes('执行回执') || text.includes('委托完成') || text.includes('委托结果')) {
        delegateReceipt = text.slice(0, 900);
        if (text.includes('"ok":true') || text.includes('成功') || text.includes('completed') || text.includes('status')) sawDelegateCall = true;
      }
    }
    if (ev.eventType === 'assistant_message' || ev.eventType === 'message' || ev.eventType === 'token' || ev.eventType === 'final') {
      const t = ev.payload && (ev.payload.text || ev.payload.content || ev.payload.delta);
      if (typeof t === 'string') finalText += t;
    }
    if (ev.eventType === 'done' || ev.eventType === 'end' || ev.eventType === 'task_done' || ev.eventType === 'task_completed' || (ev.payload && ev.payload.done === true)) {
      sawDone = true;
    }
  });

  results.stopReason = stop;
  results.finalText = finalText.slice(0, 2000);
  results.delegateReceipt = delegateReceipt;
  assert('P3-1 delegate tool invoked with correct peer', sawDelegateCall, delegateCallDetail || `（事件类型样本：${[...new Set(results.events.map((e) => { try { return JSON.parse(e).eventType; } catch { return '?'; } }))].slice(0, 12).join(',')}）`);
  // 教训（首轮 FAIL）：tool_result 顶层 summary:"ok" 是事件摘要字段不是执行结果——
  // 首轮 status:"error"/handler_error 被它掩护过关。断言必须锚 toolResult.status。
  let toolStatus = '';
  let delegateOk = null;
  let replyText = '';
  for (const e of results.events) {
    if (!e.includes('delegate_to_petri_node') || !e.includes('toolResult')) continue;
    try {
      const j = JSON.parse(e);
      const tr = j.payload && j.payload.toolResult;
      if (tr && tr.status) {
        toolStatus = tr.status;
        delegateOk = !!(tr.data && tr.data.ok);
        replyText = (tr.data && tr.data.reply) || '';
      }
    } catch {}
  }
  results.toolStatus = toolStatus;
  results.delegateOk = delegateOk;
  results.replyText = replyText.slice(0, 1500);
  // P3 载体=跨机系统信息侦察（只读、不依赖项目绑定）：回执必须含 Mac 真实环境指纹。
  // status 契约值='success'（S-003）；委托成败锚 data.ok（终态 done/completed 均认可）。
  const macFingerprint = /darwin|arm64|MacBook-Pro|macOS/i.test(replyText);
  assert('P3-2 delegate receipt from Mac (task done)', toolStatus === 'success' && delegateOk === true && macFingerprint,
    `toolStatus=${toolStatus} delegateOk=${delegateOk} macFingerprint=${macFingerprint} reply=${replyText.slice(0, 400)}`);
  assert('P3-3 agent stream reached terminal', sawDone || stop === 'stream_end', `stop=${stop} done=${sawDone}`);
  fs.writeFileSync(path.join(EVIDENCE, 'dual-p3-delegate.json'), JSON.stringify(results, null, 2) + '\n');
  const allPass = results.assertions.every((a) => a.pass);
  process.exit(allPass ? 0 : 1);
}

main().catch((e) => { console.error('LIVE_ERR', e.message); process.exit(1); });

#!/usr/bin/env node
'use strict';

/**
 * BLOCK-88 P1 实机验收 — 工程师声明身份双端贯通（loopback 双节点）。
 *
 * 拓扑：被访端 B = 本机 dev 栈（:3001 admin + :3005 gateway，真实进程）；
 *       指挥席 A = 独立真实 federation-admin REST（独立 dataDir + 临时端口）。
 * 链路：A 带署名（工程师 A · macOS）→ B /m/api/pair 落会话身份 → B 健康回显 →
 *       B /api/federation/members 成员面 → A peers 注册表投影 → CDP 测试实例
 *       联邦面板「协作成员」UI 可见。
 *
 * 前置：主 dev 栈在跑（:3001 健康）且后端代码为当前 HEAD（后端变更须重启）；
 *       UI 走查用 bash scripts/start-test-instance.sh 拉起 CDP 9223 测试实例
 *       （永久红线：探针禁导航 9222 用户主窗口）。
 * 用法: node scripts/block88-p1-dual-identity.cjs
 * 证据: acceptance/block-88/p1-identity.json + p1-identity-ui.png
 */

const assert = require('node:assert/strict');
const { mkdtempSync, rmSync, mkdirSync, writeFileSync } = require('node:fs');
const { tmpdir } = require('node:os');
const path = require('node:path');
const { spawn } = require('node:child_process');

const ROOT = path.resolve(__dirname, '..');
const B_BASE = process.env.PETRI_B_BASE || 'http://127.0.0.1:3001';
const B_GATEWAY = process.env.PETRI_B_GATEWAY || 'http://127.0.0.1:3005';
const ENGINEER = { displayName: '工程师 A', device: 'macOS' };

const startedAt = new Date().toISOString();
const assertions = [];
function assert_(name, pass, detail = '') {
  assertions.push({ name, pass: pass === true, detail: String(detail) });
  console.log(`  ${pass ? 'PASS' : 'FAIL'}  ${name}${detail ? ` — ${detail}` : ''}`);
  if (pass !== true) process.exitCode = 1;
}

async function json(url, { method = 'GET', headers = {}, body = null } = {}) {
  const res = await fetch(url, {
    method,
    headers: { 'Content-Type': 'application/json', ...headers },
    body: body ? JSON.stringify(body) : undefined,
  });
  return { status: res.status, data: await res.json().catch(() => ({})) };
}

function listen(app) {
  return new Promise((resolve) => {
    const server = app.listen(0, '127.0.0.1', () => resolve(server));
  });
}

async function ensureTestInstance() {
  // 已在跑则直接用；否则 bash scripts/start-test-instance.sh 拉起（fail-fast 语义自带）。
  const lib = require(path.join(ROOT, '.agents/skills/petri-dev-infra/dev-verify/lib.cjs'));
  try {
    await lib.pollTargets({ port: lib.TEST_INSTANCE_PORT, timeoutMs: 2000 });
    return { booted: false };
  } catch {
    const proc = spawn('bash', [path.join(ROOT, 'scripts/start-test-instance.sh')], {
      cwd: ROOT, stdio: 'inherit',
    });
    await new Promise((resolve, reject) => {
      proc.on('exit', (code) => (code === 0 ? resolve() : reject(new Error(`start-test-instance exit ${code}`))));
      proc.on('error', reject);
    });
    return { booted: true };
  }
}

async function main() {
  // ── P0 前置：B 栈健康 ──
  const health = await json(`${B_BASE}/api/health`);
  assert_('P0_backend_3001_healthy', health.status === 200, `status=${health.status}`);

  // ── P1 B 出码（REST 出码，SKILL 第 1 条禁面板出码）──
  const invite = await json(`${B_BASE}/api/mobile/pairing/token`, {
    method: 'POST', headers: { Authorization: 'Bearer desktop-local' }, body: {},
  });
  assert_('P1_invite_token_issued', invite.status === 200 && !!invite.data.token, `status=${invite.status}`);
  const pairingUrl = `http://127.0.0.1:3005/pair?token=${invite.data.token}`;

  // ── P2 A 端带署名配对（真实 federation-admin + 独立 dataDir）──
  const cmdRoot = mkdtempSync(path.join(tmpdir(), 'petri-block88-cmd-'));
  let cmdServer = null;
  try {
    const express = require('express');
    const cmdApp = express();
    require(path.join(ROOT, 'core/petri-server/routes/federation-admin.js'))(cmdApp, { dataDir: cmdRoot });
    cmdServer = await listen(cmdApp);
    const cmdBase = `http://127.0.0.1:${cmdServer.address().port}`;

    const paired = await json(`${cmdBase}/api/federation/peers/pair`, {
      method: 'POST',
      body: { url: pairingUrl, identity: ENGINEER },
    });
    assert_('P2_pair_with_identity_ok', paired.status === 200 && paired.data.ok === true,
      JSON.stringify(paired.data).slice(0, 200));

    // A 端可见：peers 注册表投影带署名（token 仍不出）
    const peers = await json(`${cmdBase}/api/federation/peers`);
