  // ── A5 粘贴入库（F3）──
  r = await apiRequest('POST', '/api/knowledge/documents/paste', { name: 'block94-粘贴', text: '粘贴入库的知识内容：单细胞转录组聚类使用 Leiden 算法。' });
  const pasteDoc = r.body.document;
  run.assert('A5a_paste_accepted', !!pasteDoc, JSON.stringify(r.body).slice(0, 160));
  createdDocIds.push(pasteDoc.id);
  const pasteReady = await pollDocReady(pasteDoc.id);
  run.assert('A5b_paste_ready', !!pasteReady && pasteReady.status === 'ready', JSON.stringify(pasteReady && pasteReady.status));

  // ── A6 真实双通道检索 ──
  r = await apiRequest('POST', '/api/knowledge/search', { query: 'TP53 细胞凋亡 机制' });
  const search = r.body;
  run.assert('A6_search_dual_channel',
    search.hits.length >= 1 && search.embeddingAvailable === true && search.hits.some((h) => h.channels && h.channels.vector != null),
    `hits=${search.hits.length} emb=${search.embeddingAvailable} first=${JSON.stringify(search.hits[0] && search.hits[0].channels)}`);

  // ── A7 docId 过滤（F5）──
  r = await apiRequest('POST', '/api/knowledge/search', { query: 'TP53', docId: pasteDoc.id });
  const filtered = r.body;
  run.assert('A7_docid_filter', filtered.hits.every((h) => h.docId === pasteDoc.id) && filtered.readyChunks >= 1,
    `hits=${filtered.hits.length} scoped=${filtered.readyChunks}`);

  // ── A8 纯符号降级诚实化（F5）──
  r = await apiRequest('POST', '/api/knowledge/search', { query: '!!!###' });
  run.assert('A8_fts_degraded_honest', r.body.ftsDegraded === true, `ftsDegraded=${r.body.ftsDegraded}`);

  // ── A9 预览（F4）──
  r = await apiRequest('GET', `/api/knowledge/documents/${textDoc.id}/preview`);
  run.assert('A9_preview_chunks_raw',
    r.body.status === 'ok' && (r.body.chunks || []).length >= 1 && r.body.rawAvailable === true,
    `chunks=${(r.body.chunks || []).length} raw=${r.body.rawAvailable}`);

  // ── A10 批量删除 + 不支持格式拒绝（F4/F3）──
  const badForm = new FormData();
  badForm.append('files', new Blob([Buffer.from('MZ')], { type: 'application/octet-stream' }), 'bad.exe');
  badForm.append('files', new Blob([textContent], { type: 'text/plain' }), 'good.txt');
  r = await apiRequest('POST', '/api/knowledge/documents', badForm, true);
  const rejectedNames = (r.body.rejected || []).map((x) => x.name);
  const goodDoc = (r.body.accepted || [])[0];
  if (goodDoc) createdDocIds.push(goodDoc.id);
  run.assert('A10a_reject_aggregated', rejectedNames.includes('bad.exe') && (r.body.accepted || []).length === 1,
    `rejected=${JSON.stringify(rejectedNames)} accepted=${(r.body.accepted || []).length}`);
  r = await apiRequest('POST', '/api/knowledge/documents/batch-delete', { ids: [pdfDoc.id, 'kdoc_absent__'] });
  run.assert('A10b_batch_delete', r.body.deleted && r.body.deleted.includes(pdfDoc.id) && r.body.missing.includes('kdoc_absent__'),
    JSON.stringify({ deleted: r.body.deleted, missing: r.body.missing }));
  createdDocIds.splice(createdDocIds.indexOf(pdfDoc.id), 1);

  // ── A11 真实模型轮次 → knowledge_citations（F5 端到端）──
  const projList = await apiRequest('GET', '/api/data/projects');
  const projectId = process.argv[2] || (projList.body.projects && projList.body.projects[0] && projList.body.projects[0].id);
  const taskRes = await apiRequest('POST', '/api/ai/agent', {
    messages: [{ role: 'user', content: '请根据知识空间检索结果，用一句话回答：TP53 的核心功能是什么？（直接作答，不要调用工具）' }],
    context: { page: 'desktop-project', projectId },
    projectId,
  });
  const taskId = taskRes.body.taskId;
  run.assert('A11a_task_created', !!taskId, JSON.stringify(taskRes.body).slice(0, 160));
  let citationEvent = null;
  let taskDone = false;
  for (let i = 0; i < 20 && !citationEvent; i++) {
    await sleep(6000);
    const events = await fetchTaskEvents(taskId, 10000);
    citationEvent = events.find((e) => e && e.event === 'knowledge_citations');
    taskDone = events.some((e) => e && e.event === 'done');
    if (taskDone && !citationEvent) break;
  }
  run.assert('A11b_citations_event_real_round',
    !!citationEvent && Array.isArray(citationEvent.citations) &&
    citationEvent.citations.some((c) => /block94-tp53-notes|TP53 知识笔记/.test(String(c.docName))),
    citationEvent ? JSON.stringify(citationEvent.citations).slice(0, 220) : 'no knowledge_citations in task events');

  // ── V1 CDP：/knowledge 面板 ──
  try {
    let target = await pollTargets();
    client = await lib.connectTarget(target);
    await lib.evalJs(client, `location.href = 'http://localhost:3000/knowledge'; 'nav'`);
    await sleep(3500);
    target = await pollTargets();
    client = await lib.connectTarget(target);
    const panel = await EVAL(`!!document.querySelector('[data-testid="knowledge-panel"]')`);
    run.assert('V1a_knowledge_panel_mounted', panel === true || panel === 'true', `panel=${panel}`);
    const docRows = await EVAL(`document.querySelectorAll('[data-testid="knowledge-doc-row"]').length`);
    run.assert('V1b_panel_doc_rows', Number(docRows) >= 1, `rows=${docRows}`);
    await lib.screenshotPng(client, EVIDENCE_DIR, 'block94-knowledge-panel.png');
  } catch (e) {
    run.assert('V1_knowledge_panel', false, `cdp: ${e.message}`);
  }

  // ── V2 CDP：摘要卡「知识溯源」节（composer 真发轮次 → 工作台当前会话）──
  try {
    let target = await pollTargets();
    client = await lib.connectTarget(target);
    await lib.evalJs(client, `location.href = 'http://localhost:3000/project/${projectId}'; 'nav'`);
    await sleep(4500);
    target = await pollTargets();
    client = await lib.connectTarget(target);

    // composer 真发（block97 同款：React 受控 setter + input 事件 + 点发送）
    const COMPOSER_PROMPT =
      '请根据知识空间检索结果，用一句话回答 BRCA1 与哪种修复相关？（直接作答，不要调用工具）';
    let typed = '';
    for (let i = 0; i < 15; i++) {
      typed = await EVAL(
        "(function(){\n" +
        "  var ta = document.querySelector('textarea.sc-input');\n" +
        "  if (!ta) return 'no_textarea';\n" +
        "  var setter = Object.getOwnPropertyDescriptor(window.HTMLTextAreaElement.prototype, 'value').set;\n" +
        "  setter.call(ta, " + JSON.stringify(COMPOSER_PROMPT) + ");\n" +
        "  ta.dispatchEvent(new Event('input', { bubbles: true }));\n" +
        "  return 'typed:' + ta.value.length;\n" +
        "})()");
      if (String(typed).startsWith('typed:')) break;
      await sleep(1000);
    }
    const clicked = String(typed).startsWith('typed:')
      ? await EVAL(
        "(function(){\n" +
        "  var btns = document.querySelectorAll('button');\n" +
        "  for (var i = 0; i < btns.length; i++) {\n" +
        "    var t = btns[i].getAttribute('title') || '';\n" +
        "    if (t.indexOf('发送') >= 0 && btns[i].offsetParent) { btns[i].click(); return 'clicked:' + t; }\n" +
        "  }\n" +
        "  return 'send_button_not_found';\n" +
        "})()")
      : 'skipped_no_textarea';
    run.assert('V2a_composer_sent', clicked.indexOf('clicked') === 0, String(clicked));

    // 等摘要卡「知识溯源」节出现（真轮次注入事件 → 会话级存储 → 摘要卡节）
    let citeSeen = false;
    for (let i = 0; i < 40 && !citeSeen; i++) {
      await sleep(3000);
      citeSeen = (await EVAL(`!!document.querySelector('section[aria-label="知识溯源"]')`)) === true;
      if (!citeSeen && i === 2) {
        // 摘要卡可能整体收起 → 点 TitleBar「展开摘要概览」（已展开则无此按钮）
        await EVAL(
          "(function(){\n" +
          "  var btns = document.querySelectorAll('button[aria-label]');\n" +
          "  for (var i = 0; i < btns.length; i++) {\n" +
          "    if (btns[i].getAttribute('aria-label') === '展开摘要概览') { btns[i].click(); return 'opened'; }\n" +
          "  }\n" +
          "  return 'already_open_or_not_found';\n" +
          "})()").catch(() => 'eval_err');
      }
    }
    run.assert('V2b_summary_citations_section', citeSeen, `citationsSection=${citeSeen}`);
    await lib.screenshotPng(client, EVIDENCE_DIR, 'block94-summary-citations.png');
  } catch (e) {
    run.assert('V2_summary_citations', false, `cdp: ${e.message}`);
  }

  // ── 清理：删除本次创建的文档，空间复位 ──
  if (createdDocIds.length) {
    await apiRequest('POST', '/api/knowledge/documents/batch-delete', { ids: createdDocIds });
  }
  await apiRequest('POST', '/api/knowledge/space', { enabled: false });

  run.finish({ meta: { taskId, projectId } });
})().catch((e) => {
  console.error('[block94-knowledge-live] fatal:', e);
  process.exit(1);
});

#!/usr/bin/env node
'use strict';
/**
 * block95-b1-diff-live.cjs — BLOCK-95 B1 实机 diff 对账（dev 栈，开关开）。
 *
 * 前置：dev 栈以 PETRI_SERVER_HISTORY_ASSEMBLY=1 启动（restart-dev-stack.sh 透传）。
 * 流程：
 *   S1 短会话全等对账：seed 4 条历史 → 模拟前端 POST tagged(4+1) → 等 task 完成 →
 *      transcript request.messages 与 DB 拼装重放逐字 diff（短请求不触发折叠）；
 *   S2 长会话（250 条）对账：同法，长度=行数、尾条=本轮原文；若 transcript 触发
 *      折叠则降级为首尾+messagesTruncated 断言并如实登记；
 *   S3 开关关（当前进程 env 判断不可行——dev 栈已带开关；此断言由契约测试覆盖，
 *      本脚本只跑开态实机）。
 * 证据：acceptance/block-95/block95-b1-diff-live.json
 */
const fs = require('node:fs');
const path = require('node:path');
const http = require('node:http');
const lib = require(path.join(__dirname, '..', '.agents', 'skills', 'petri-dev-infra', 'dev-verify', 'lib.cjs'));

const ROOT = path.join(__dirname, '..');
const EVIDENCE_DIR = path.join(ROOT, 'acceptance', 'block-95');
const DB_FILE = path.join(ROOT, '.petri-dev-user-data', 'data', 'petri.db');
const TRANSCRIPT_DIR = path.join(ROOT, '.petri-dev-user-data', 'data', 'llm-transcripts');
const API = 'http://127.0.0.1:3001';
const AUTH = { Authorization: 'Bearer desktop-local', 'Content-Type': 'application/json' };

function apiPost(pathname, body) {
  return new Promise((resolve, reject) => {
    const req = http.request(API + pathname, { method: 'POST', headers: AUTH }, (res) => {
      let d = '';
      res.on('data', (c) => { d += c; });
      res.on('end', () => {
        try { resolve({ status: res.statusCode, body: JSON.parse(d) }); } catch { resolve({ status: res.statusCode, body: d }); }
      });
    });
    req.on('error', reject);
    req.end(JSON.stringify(body));
  });
}
function apiGet(pathname) {
  return new Promise((resolve, reject) => {
    http.get(API + pathname, { headers: AUTH }, (res) => {
      let d = '';
      res.on('data', (c) => { d += c; });
      res.on('end', () => { try { resolve({ status: res.statusCode, body: JSON.parse(d) }); } catch { resolve({ status: res.statusCode, body: d }); } });
    }).on('error', reject);
  });
}

const Database = require(path.join(ROOT, 'core', 'petri-server', 'node_modules', 'better-sqlite3'));

function readTranscriptFor(convId) {
  const file = path.join(TRANSCRIPT_DIR, `${convId}.jsonl`); // convId 本身已带 conv_ 前缀
  if (!fs.existsSync(file)) return [];
  return fs.readFileSync(file, 'utf8').split('\n').filter(Boolean).map((l) => {
    try { return JSON.parse(l); } catch { return null; }
  }).filter(Boolean);
}

(async () => {
  const run = lib.createRun({ name: 'block95-b1-diff-live', evidenceDir: EVIDENCE_DIR });
  const db = new Database(DB_FILE); // WAL 多连接：dev 后端持连接，此处读写并行安全（busy_timeout 兜底）
  db.pragma('busy_timeout = 10000');

  // ---------- S1 短会话全等对账 ----------
  const convS1 = `conv_b95_b1_${Date.now().toString(36)}`;
  const now = Date.now();
  db.prepare('INSERT INTO copilot_conversations(id, user_id, title, status, project_id, created_at, updated_at) VALUES (?,?,?,?,?,?,?)')
    .run(convS1, 'local-user', 'B1 对账短会话', 'active', null, new Date(now).toISOString(), new Date(now).toISOString());
  const seedS1 = db.prepare('INSERT INTO copilot_messages(id, conversation_id, role, content, meta_json, ts) VALUES (?,?,?,?,?,?)');
  // seed ts 必须整体早于后端 append（真实 now）——否则 rowid 游标排序把本轮 user 插进历史中间
  [['user', '第一问：用一句话说明什么是 RAG'], ['assistant', 'RAG 是检索增强生成……']]
    .forEach(([role, content], i) => seedS1.run(`msg_s1_${Date.now().toString(36)}_${i}`, convS1, role, content, null, new Date(now - 120000 + i * 1000).toISOString()));
  const s1Incoming = '第二问（带引用原文）：[引用: demo.md]\n那向量检索呢？';
  // 增量形态请求（B1b 前端形态预演）：只发本轮 user——开关生效时 LLM 应收到
  // DB 全量历史 + 本轮原文；开关未生效时只会收到这 1 条（断言因此有区分度）。
  const s1Tagged = [
    { role: 'user', content: s1Incoming },
  ];

  const p1 = await apiPost('/api/ai/agent', {
    conversationId: convS1,
    messages: s1Tagged,
    context: { page: 'desktop-project', projectId: null },
  });
  if (p1.status !== 200 || !p1.body.taskId) {
    run.assert('s1_post_task_created', false, JSON.stringify(p1).slice(0, 200));
    const payload = await run.finish({ stage: 'S1-post-failed' });
    console.log('ALLPASS=' + payload.allPass);
    process.exit(payload.allPass ? 0 : 1);
  }
  const taskIdS1 = p1.body.taskId;
  run.assert('s1_post_task_created', true, `taskId=${taskIdS1} conv=${convS1}`);

  // 等 task 终态（真 LLM 轮次，上限 120s）——直查 DB（/task/:taskId 是 SSE 流端点会挂住）
  let finalS1 = null;
  for (let i = 0; i < 40; i++) {
    await new Promise((r) => setTimeout(r, 3000));
    const row = db.prepare('SELECT status FROM tasks WHERE id=?').get(taskIdS1);
    if (row && row.status && row.status !== 'running') { finalS1 = row.status; break; }
  }
  run.assert('s1_task_settled', finalS1 === 'done' || finalS1 === 'completed' || finalS1 === 'failed', `status=${finalS1}`);

  // transcript 对账：任务完成后 DB 尾部多出本轮 assistant 回复——
  // 第一轮请求的历史 = 除去尾部 assistant 回复后的 DB 前缀（+尾部原文回填语义）
  const allRowsS1 = db.prepare("SELECT role, content FROM copilot_messages WHERE conversation_id=? AND role IN ('user','assistant') ORDER BY ts ASC, rowid ASC").all(convS1);
  run.assert('s1_db_row_count_includes_turn_user', allRowsS1.length >= 3, `rows=${allRowsS1.length}`);
  const preReplyS1 = (allRowsS1.length > 0 && allRowsS1[allRowsS1.length - 1].role === 'assistant')
    ? allRowsS1.slice(0, -1)
    : allRowsS1;
  const expectedS1 = preReplyS1.map((r) => ({ role: r.role, content: String(r.content || '') }));
  const recsS1 = readTranscriptFor(convS1);
  const llmRec = recsS1.filter((r) => r.request && Array.isArray(r.request.messages))[0]; // 第一轮请求
  if (!llmRec) {
    run.assert('s1_transcript_found', false, `records=${recsS1.length}`);
  } else {
    run.assert('s1_transcript_found', true, `records=${recsS1.length}`);
    const folded = Boolean(llmRec.messagesTruncated);
    // runner 会把 system prompt 放头部——B1 对账只管对话历史，过滤 system 后逐字比
    const llmHistory = llmRec.request.messages.filter((m) => m.role !== 'system');
    if (!folded) {
      run.assert('s1_request_matches_db_assembly', JSON.stringify(llmHistory) === JSON.stringify(expectedS1),
        `llm=${llmHistory.length} expected=${expectedS1.length} first=${JSON.stringify(llmHistory[0]).slice(0, 80)}`);
      run.assert('s1_tail_is_original_incoming', llmHistory[llmHistory.length - 1].content === s1Incoming,
        'tail=' + String(llmHistory[llmHistory.length - 1].content).slice(0, 50));
    } else {
      run.assert('s1_request_matches_db_assembly_folded', llmRec.messagesTruncated > 0 && llmHistory.length > 0,
        `truncated=${llmRec.messagesTruncated}`);
    }
  }

  const payload = await run.finish({
    conversationId: convS1,
    taskId: taskIdS1,
    note: 'B1 开态实机：LLM 实际收到的 messages 与 DB 拼装逐字对账（开关=PETRI_SERVER_HISTORY_ASSEMBLY=1）',
  });
  db.close();
  console.log('ALLPASS=' + payload.allPass);
  process.exit(payload.allPass ? 0 : 1);
})().catch((e) => { console.error('PROBE_ERROR', e && e.message); process.exit(2); });

#!/usr/bin/env node
'use strict';
/**
 * block95-b2-compaction-live.cjs — BLOCK-95 B2/A5 实机验收（dev 栈，双开关开）。
 *
 * 前置：dev 栈以 PETRI_SERVER_HISTORY_ASSEMBLY=1 PETRI_SESSION_COMPACTION=1 启动。
 * 流程：
 *   S1 seed 重会话（40 条 × ~800 字 ≈ 数万 token，稳过 12000 阈值）；
 *   S2 轮次 1：POST 增量请求 → 完成 → 后台 compaction 触发 → 等 conversation_compaction 落库；
 *   S3 轮次 2：再发一轮 → transcript 对账：
 *      - before/after prompt_tokens（io-transcript usage）——压缩后显著下降；
 *      - 第二次请求 messages[0] = 摘要卡（[会话早期对话摘要…]）；
 *      - 红线：copilot_messages 原文只增不改（行数单调、历史行逐字节不变）。
 * 证据：acceptance/block-95/block95-b2-compaction-live.json（含 token 对账数字）。
 */
const fs = require('node:fs');
const path = require('node:path');
const http = require('node:http');
const lib = require(path.join(__dirname, '..', '.agents', 'skills', 'petri-dev-infra', 'dev-verify', 'lib.cjs'));

const ROOT = path.join(__dirname, '..');
const EVIDENCE_DIR = path.join(ROOT, 'acceptance', 'block-95');
const DB_FILE = path.join(ROOT, '.petri-dev-user-data', 'data', 'petri.db');
const TRANSCRIPT_DIR = path.join(ROOT, '.petri-dev-user-data', 'data', 'llm-transcripts');
const API = 'http://127.0.0.1:3001';
const AUTH = { Authorization: 'Bearer desktop-local', 'Content-Type': 'application/json' };
const N_SEED = 40;
const CHUNK = '这段较早的讨论涵盖了数据清洗的参数选择、聚类分辨率对比与差异表达阈值约定，';

function apiPost(pathname, body) {
  return new Promise((resolve, reject) => {
    const req = http.request(API + pathname, { method: 'POST', headers: AUTH }, (res) => {
      let d = '';
      res.on('data', (c) => { d += c; });
      res.on('end', () => { try { resolve({ status: res.statusCode, body: JSON.parse(d) }); } catch { resolve({ status: res.statusCode, body: d }); } });
    });
    req.on('error', reject);
    req.end(JSON.stringify(body));
  });
}

const Database = require(path.join(ROOT, 'core', 'petri-server', 'node_modules', 'better-sqlite3'));

function readTranscriptFor(convId) {
  const file = path.join(TRANSCRIPT_DIR, `${convId}.jsonl`);
  if (!fs.existsSync(file)) return [];
  return fs.readFileSync(file, 'utf8').split('\n').filter(Boolean).map((l) => { try { return JSON.parse(l); } catch { return null; } }).filter(Boolean);
}

async function waitTaskDone(taskId, db, timeoutMs) {
  const t0 = Date.now();
  while (Date.now() - t0 < timeoutMs) {
    await new Promise((r) => setTimeout(r, 3000));
    const row = db.prepare('SELECT status FROM tasks WHERE id=?').get(taskId);
    if (row && row.status && row.status !== 'running') return row.status;
  }
  return 'timeout';
}

(async () => {
  const run = lib.createRun({ name: 'block95-b2-compaction-live', evidenceDir: EVIDENCE_DIR });
  const db = new Database(DB_FILE);
  db.pragma('busy_timeout = 10000');

  // S1 seed 重会话（ts 依次排在过去，后端 append 在其后）
  const convId = `conv_b95_b2_${Date.now().toString(36)}`;
  const now = Date.now();
  db.prepare('INSERT INTO copilot_conversations(id, user_id, title, status, project_id, created_at, updated_at) VALUES (?,?,?,?,?,?,?)')
    .run(convId, 'local-user', 'B2 压缩验证重会话', 'active', null, new Date(now).toISOString(), new Date(now).toISOString());
  const seed = db.prepare('INSERT INTO copilot_messages(id, conversation_id, role, content, meta_json, ts) VALUES (?,?,?,?,?,?)');
  for (let i = 0; i < N_SEED; i += 1) {
    const role = i % 2 === 0 ? 'user' : 'assistant';
    seed.run(`msg_b2l_${Date.now().toString(36)}_${i}`, convId, role,
      `B2消息-${i}（${role === 'user' ? '问' : '答'}）：${CHUNK.repeat(40)}`,
      null, new Date(now - 600000 + i * 1000).toISOString());
  }
  const seedSnapshot = db.prepare('SELECT rowid, id, role, content FROM copilot_messages WHERE conversation_id=? ORDER BY rowid ASC').all(convId);
  run.assert('s1_seeded_heavy_conversation', seedSnapshot.length === N_SEED, `rows=${seedSnapshot.length}`);

  const postTurn = async (text) => {
    const p = await apiPost('/api/ai/agent', {
      conversationId: convId,
      messages: [{ role: 'user', content: text }], // 增量形态（B1 后端拼装）
      context: { page: 'desktop-project', projectId: null },
    });
    return p;
  };

  // S2 轮次 1 → 后台 compaction
  const t1 = await postTurn('第一轮：请用一句话确认你在跟踪本会话背景');
  if (t1.status !== 200 || !t1.body.taskId) {
    run.assert('s2_turn1_posted', false, JSON.stringify(t1).slice(0, 160));
    const payload = await run.finish({ stage: 'S2-failed' });
    console.log('ALLPASS=' + payload.allPass);
    process.exit(payload.allPass ? 0 : 1);
  }
  const st1 = await waitTaskDone(t1.body.taskId, db, 180000);
  run.assert('s2_turn1_posted', st1 === 'completed' || st1 === 'done', `status=${st1} taskId=${t1.body.taskId}`);

  // 等 compaction 落库（后台生成，上限 90s）
  let comp = null;
  for (let i = 0; i < 30; i++) {
    await new Promise((r) => setTimeout(r, 3000));
    comp = db.prepare('SELECT * FROM conversation_compaction WHERE conversation_id=?').get(convId);
    if (comp) break;
  }
  run.assert('s2_compaction_recorded', !!comp, comp ? `covers=${comp.covers_count} srcTokens=${comp.source_tokens}` : 'no record');

  const recs1 = readTranscriptFor(convId);
  const firstReq = recs1.filter((r) => r.request && Array.isArray(r.request.messages))[0];
  const tokensBefore = firstReq && firstReq.response && firstReq.response.usage ? (firstReq.response.usage.prompt_tokens || 0) : 0;
  run.assert('s2_baseline_tokens_captured', tokensBefore > 0, `promptTokensBefore=${tokensBefore}`);

  // S3 轮次 2：摘要版视图
  const t2 = await postTurn('第二轮：背景里最早的讨论主题是什么？');
  const st2 = t2.status === 200 && t2.body.taskId ? await waitTaskDone(t2.body.taskId, db, 180000) : 'post_failed';
  run.assert('s3_turn2_settled', st2 === 'completed' || st2 === 'done', `status=${st2}`);

  const recs2 = readTranscriptFor(convId);
  const reqs = recs2.filter((r) => r.request && Array.isArray(r.request.messages));
  const secondReq = reqs[reqs.length - 1];
  let tokensAfter = 0;
  let summaryFirst = false;
  if (secondReq) {
    const hist = secondReq.request.messages.filter((m) => m.role !== 'system');
    summaryFirst = hist.length > 0 && /\[会话早期对话摘要/.test(String(hist[0].content || ''));
    tokensAfter = secondReq.response && secondReq.response.usage ? (secondReq.response.usage.prompt_tokens || 0) : 0;
  }
  run.assert('s3_summary_leads_second_request', summaryFirst, `secondReqMessages=${secondReq ? secondReq.request.messages.length : 0}`);
  run.assert('s3_tokens_reduced', tokensAfter > 0 && tokensAfter < tokensBefore, `before=${tokensBefore} after=${tokensAfter} saved=${tokensBefore - tokensAfter}`);

  // 红线：原文只增不改
  const afterSnapshot = db.prepare('SELECT rowid, id, role, content FROM copilot_messages WHERE conversation_id=? ORDER BY rowid ASC').all(convId);
  const prefixUnchanged = seedSnapshot.every((r, i) => afterSnapshot[i] && afterSnapshot[i].id === r.id && afterSnapshot[i].content === r.content);
  run.assert('redline_source_messages_immutable', afterSnapshot.length >= seedSnapshot.length && prefixUnchanged,
    `before=${seedSnapshot.length} after=${afterSnapshot.length}`);

  await lib.screenshotPng ? null : null;
  const payload = await run.finish({
    conversationId: convId,
    tokenLedger: { promptTokensBefore: tokensBefore, promptTokensAfter: tokensAfter, saved: Math.max(0, tokensBefore - tokensAfter) },
    compaction: comp ? { coversCount: comp.covers_count, sourceTokens: comp.source_tokens, summaryHead: String(comp.summary).slice(0, 120) } : null,
  });
  db.close();
  console.log('ALLPASS=' + payload.allPass);
  process.exit(payload.allPass ? 0 : 1);
})().catch((e) => { console.error('PROBE_ERROR', e && e.message); process.exit(2); });

#!/usr/bin/env node
/**
 * BLOCK-96 P1 — SSH 通道效率与稳定性 实机探针（dev Electron 不需要；真节点 WSL）。
 *
 * 用产品真实路径取证：sshTransport 首连计时 → gateway createSshBackend（含
 * ensureAgent 自动部署 + mux 复用）跑 恶意文件名 fs_list 往返 / 500 文件计时 /
 * 分页契约。证据落 acceptance/block-96/block96-p1-live.json。
 *
 * 用法：node scripts/block96-ssh-channel-live.cjs [--alias wsl]
 * 前置：目标节点 ssh 免密可达（key auth）。
 */
process.env.PETRI_SSH_MUX = process.env.PETRI_SSH_MUX || '1';

const fs = require('fs');
const path = require('path');
const { spawnSync } = require('child_process');

const aliasIdx = process.argv.indexOf('--alias');
const ALIAS = aliasIdx >= 0 ? process.argv[aliasIdx + 1] : (process.env.BLOCK96_SSH_ALIAS || 'wsl');
const OUT = path.join(__dirname, '..', 'acceptance', 'block-96', 'block96-p1-live.json');

const sshTransport = require('../core/petri-server/helpers/remote-execution/ssh-transport');
const gateway = require('../core/petri-server/helpers/workspace-gateway');

const checks = [];
function record(name, passed, detail) {
  checks.push({ name, passed, detail });
  console.log(`${passed ? 'PASS' : 'FAIL'}  ${name}  ${JSON.stringify(detail)}`);
}

function sshRun(remoteCommand, input) {
  const r = spawnSync('ssh', [ALIAS, remoteCommand], { input, encoding: 'utf8', timeout: 30000 });
  if (r.status !== 0) throw new Error(`ssh ${ALIAS} failed: ${(r.stderr || '').slice(0, 200)}`);
  return r.stdout;
}

(async () => {
  const baseline = {
    firstConnectBeforeMs: 21200,
    fsList500BeforeMs: 2600,
    note: '立项日（2026-09-16）WSL 同节点实测基线；节点侧已先加 AddressFamily inet 缓解',
  };

  // ① 首连计时（一次性 ssh 全成本）
  let t0 = Date.now();
  const op = await sshTransport.runSshOp({ alias: ALIAS, remoteCommand: 'echo ok' });
  const firstConnectMs = Date.now() - t0;
  record('first_connect', op.classified.kind === 'ok' && firstConnectMs < 1000, {
    ms: firstConnectMs, baselineMs: baseline.firstConnectBeforeMs, classified: op.classified.kind,
  });

  // ② 产品路径 backend（ensureAgent 自动部署 + mux）
  const backend = gateway.createSshBackend({ alias: ALIAS });
  const root = `/tmp/block96-live-${process.pid}`;

  // ③ 恶意文件名往返（引号/反斜杠/换行/制表符/空格/中文 + NUL 协议不可表示性排除）
  sshRun('bash -s', [
    `rm -rf ${root} && mkdir -p ${root}`,
    `cd ${root}`,
    `touch 'a"b.txt' "back${String.fromCharCode(92)}slash.txt" 'space name.txt' '中文测试.txt'`,
    `touch $'newline\nname.txt' "tab\tname.txt"`,
    'echo OK',
  ].join('\n'));
  const BSCH = String.fromCharCode(92);
  const hostileExpect = ['a"b.txt', 'back\\slash.txt', 'space name.txt', '中文测试.txt', 'newline\nname.txt', 'tab\tname.txt'];
  const BS_REMOTE = String.fromCharCode(92);
  const hostileEntries = await backend.list(root);
  const hostileNames = hostileEntries.map((e) => e.name).sort();
  record('hostile_names_roundtrip', JSON.stringify(hostileNames) === JSON.stringify([...hostileExpect].sort()), {
    names: hostileNames,
  });

  // ④ 500 文件 fs_list 计时（cold=mux bootstrap 首列；warm=复用连接）
  sshRun('bash -s', `rm -rf ${root}-500 && mkdir -p ${root}-500 && for i in $(seq 1 500); do touch "${root}-500/f\$i.txt"; done && echo OK`);
  t0 = Date.now();
  const coldEntries = await backend.list(`${root}-500`);
  const coldMs = Date.now() - t0;
  t0 = Date.now();
  const warmEntries = await backend.list(`${root}-500`);
  const warmMs = Date.now() - t0;
  record('fs_list_500_cold', coldEntries.length === 500 && coldMs < 2000, { ms: coldMs, entries: coldEntries.length, baselineMs: baseline.fsList500BeforeMs });
  record('fs_list_500_warm', warmEntries.length === 500 && warmMs < 100, { ms: warmMs, entries: warmEntries.length, baselineMs: baseline.fsList500BeforeMs });

  // ⑤ 分页契约（limit/offset/truncated 数学）
  const page = await backend.listPage(`${root}-500`, { limit: 200, offset: 450 });
  record('pagination_contract', page.total === 500 && page.entries.length === 50 && page.truncated === false, {
    total: page.total, entries: page.entries.length, truncated: page.truncated,
  });
  const midPage = await backend.listPage(`${root}-500`, { limit: 200, offset: 0 });
  record('pagination_truncated_flag', midPage.total === 500 && midPage.entries.length === 200 && midPage.truncated === true, {
    total: midPage.total, entries: midPage.entries.length, truncated: midPage.truncated,
  });

  // ⑥ mux 写列一致（同会话 fs_write 产物立即可见）
  const b64 = (s) => Buffer.from(s).toString('base64');
  await backend.write(`${root}-500/由写而生.txt`, 'block96');
  const afterWrite = await backend.list(`${root}-500`);
  record('mux_write_list_consistency', afterWrite.some((e) => e.name === '由写而生.txt'), {
    entries: afterWrite.length,
  });

  // ── P3 进程面（F4）─────────────────────────────────────────
  // ⑦ exec_bg pidfile 身份：pid+starttime 落 <log>.pid（替代 pgrep 猜测）
  const procRoot = `${root}-proc`;
  sshRun('bash -s', `rm -rf ${procRoot} && mkdir -p ${procRoot} && echo OK`, '');
  const bg = await backend.execBackground('sleep 30', procRoot, `${procRoot}/bg.log`);
  record('exec_bg_pidfile_identity', Number.isInteger(bg.pid) && bg.pid > 0 && typeof bg.starttime === 'string', bg);

  // ⑧ ps_pid starttime 身份校验：存活判定 + 伪造starttime 识别为 reused
  const alive = await backend.processAlive(bg.pid, bg.starttime);
  record('ps_pid_starttime_alive', alive.alive === true && alive.reused !== true, alive);

  // ⑨ kill_pid 进程组击杀：setsid 会话（PGID=PID）连同子孙一并收敛
  const killRes = await backend.killPid(bg.pid, 'KILL');
  await new Promise((r) => setTimeout(r, 400));
  const dead = await backend.processAlive(bg.pid, bg.starttime);
  record('kill_pid_group_reaps', killRes.signaled === true && dead.alive === false, {
    signaled: killRes.signaled, alive: dead.alive,
  });

  // ⑩ exec 超时孙进程组杀清零（旧 timeout 只杀直接子 bash，孙进程存活累积）
  const orphansBefore = sshRun('pgrep -fc "sleep[ ]87\\.42" || true', '').trim();
  const execRes = await backend.exec('sleep 87.42 & echo go; sleep 93.17', procRoot, 2);
  await new Promise((r) => setTimeout(r, 500));
  const orphansAfter = sshRun('pgrep -fc "sleep[ ]87\\.42" || true', '').trim();
  record('exec_timeout_grandchild_reaped', execRes.code !== 0 && orphansAfter === '0', {
    code: execRes.code, orphansBefore, orphansAfter,
  });

  // 清理
  sshRun(`rm -rf ${root} ${root}-500 ${root}-proc && echo OK`, '');

  const allPass = checks.every((c) => c.passed);
  const evidence = {
    generatedAt: new Date().toISOString(),
    alias: ALIAS,
    baseline,
    checks,
    allPass,
    stage: 'P1 (F1/F2/F6) + P3 (F4 进程面)',
    head: require('../package.json').version,
  };
  fs.mkdirSync(path.dirname(OUT), { recursive: true });
  fs.writeFileSync(OUT, JSON.stringify(evidence, null, 2));
  console.log(`\n${allPass ? 'ALL PASS' : 'FAILED'} → ${OUT}`);
  // mux 会话的子进程/stdio 句柄会吊住事件循环——显式关闭后硬退出，保证可被 flow/CI 消费
  require('../core/petri-server/helpers/remote-execution/ssh-multiplexer').closeAll();
  process.exit(allPass ? 0 : 1);
})().catch((e) => {
  console.error('LIVE PROBE ERROR:', e.message);
  try { require('../core/petri-server/helpers/remote-execution/ssh-multiplexer').closeAll(); } catch {}
  process.exit(1);
});

#!/usr/bin/env node
'use strict';
/**
 * block97-todo-live.cjs — BLOCK-97 P3 实机验收（dev Electron 真轮次）：
 *   V1 composer 真发多步消息（产品路径），agent 真实调用 todo_write；
 *   V2 摘要卡「任务清单」节实时出现（aria-label=任务清单），运行中捕获到
 *      in_progress / completed 状态（实时勾选可见）；
 *   V3 真轮次终态：回复到达 / 任务终态 done，最终清单全 completed；
 *   V4 事件持久化与专属性：task SSE afterSeq=0 重放含 task_todo ≥2 次整单
 *      （≥1 次初始 + ≥1 次勾选更新），且 task_todo 恒随 tool_result(todo_write)
 *      成功回执之后（seq 单调）；
 *   V5 重放确定性：二次 afterSeq=0 拉取最终清单逐字节一致（D1 事件重放定案）。
 * 前置：dev 栈（vite 3000 + 后端 3001 + CDP 9222），栈须在 5552e68f 之后重启。
 * 证据：acceptance/block-97/block97-todo-live.json + 截图。
 */
const path = require('node:path');
const http = require('node:http');
const lib = require(path.join(__dirname, '..', '.agents', 'skills', 'petri-dev-infra', 'dev-verify', 'lib.cjs'));
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const PROJECT_ID = process.argv[2] || 'p_mu5emekx_g13p';
const API = 'http://127.0.0.1:3001';
const AUTH = { Authorization: 'Bearer desktop-local' };
const EVIDENCE_DIR = path.join(__dirname, '..', 'acceptance', 'block-97');

const PROMPT =
  '请严格按以下流程执行，并全程使用 todo_write 工具维护任务清单：' +
  '开工前先用 todo_write 写入 3 条 pending 清单（内容逐字使用：' +
  '「第一步：回答算术题」「第二步：回答应用定位题」「第三步：报告完成」），' +
  '然后逐条执行：执行某条前置为 in_progress，完成立即置 completed。' +
  '步骤一：直接回答 1+1 等于几。步骤二：用一句话说明格物桌面版是什么类型的应用。' +
  '步骤三：输出「三步完成」。除 todo_write 外不要调用任何其他工具。';

let client;
const EVAL = (expr) => lib.evalJs(client, expr);

function apiJson(pathname) {
  return new Promise((resolve, reject) => {
    http.get(API + pathname, { headers: AUTH }, (res) => {
      let buf = '';
      res.on('data', (c) => { buf += c; });
      res.on('end', () => {
        try { resolve(JSON.parse(buf)); } catch (e) { reject(e); }
      });
    }).on('error', reject);
  });
}

/** 拉取 task 事件流（afterSeq=0 全量重放），直到 [DONE] / 终态 / 超时。
 *  task 模式事件包成 {seq, eventType, payload} 信封——取 payload 走原解析。 */
function fetchTaskEvents(taskId, timeoutMs = 30000) {
  return new Promise((resolve, reject) => {
    const events = [];
    const req = http.get(`${API}/api/ai/agent/task/${taskId}?afterSeq=0`, { headers: AUTH }, (res) => {
      let buf = '';
      let done = false;
      const finish = () => {
        if (done) return;
        done = true;
        try { res.destroy(); } catch {}
        resolve(events);
      };
      const timer = setTimeout(finish, timeoutMs);
      res.on('data', (c) => {
        buf += c.toString('utf8');
        let idx;
        while ((idx = buf.indexOf('\n\n')) !== -1) {
          const raw = buf.slice(0, idx);
          buf = buf.slice(idx + 2);
          for (const line of raw.split('\n')) {
            const m = line.match(/^data:\s?(.*)$/);
            if (!m) continue;
            if (m[1] === '[DONE]') { clearTimeout(timer); finish(); return; }
            try {
              const obj = JSON.parse(m[1]);
              events.push(obj && obj.payload ? obj.payload : obj);
            } catch {}
          }
        }
      });
      // 终态任务重放完即关连接——必须在 end 上收敛，否则白等超时截断事件
      res.on('end', () => { clearTimeout(timer); finish(); });
      res.on('error', () => { clearTimeout(timer); finish(); });
    });
    req.on('error', reject);
  });
}

async function pollTargets() {
  const targets = await lib.pollTargets({ timeoutMs: 20000 });
  const candidates = lib.filterPageTargets(targets, /^http:\/\/localhost:3000\/(?!window\/)/);
  return lib.selectPageTarget(candidates, {
    probe: async (c) => lib.evalJs(c, `!!document.getElementById('root')`).catch(() => false),
  });
}

(async () => {
