      if (i === 2 || i === 6) {
        await lib.screenshotPng(client, EVIDENCE_DIR, 'block97-todo-during-' + i + '.png').catch(() => {});
      }
      // 终态：全部 completed 且 done=true，且模型收尾回复已出现 → 跳出
      if ((p.rows || []).length >= 3 && (p.rows || []).every((s) => s === 'completed') && p.done === 'true') {
        // 再确认任务终态（API）
        try {
          const meta = await apiJson('/api/ai/agent/tasks?limit=5');
          const me = (meta.tasks || []).find((t) => t.taskId === taskId);
          if (me && ['done', 'completed', 'failed', 'cancelled'].includes(me.status)) break;
        } catch {}
      }
    }
  }
  run.assert('V2_todo_section_live', sectionSeen, 'section visible during run, rows=' + duringRows);
  run.assert('V2_live_status_transition', seen.has('in_progress') && seen.has('completed'),
    'observed states: ' + Array.from(seen).sort().join(','));

  await sleep(1500);
  const finalDom = await EVAL(
    "(function(){\n" +
    "  var sec = document.querySelector('[aria-label=\"任务清单\"]');\n" +
    "  if (!sec) return 'section_gone';\n" +
    "  return sec.textContent.slice(0, 200);\n" +
    "})()");
  run.assert('V3_final_dom_all_completed', /3\/3/.test(String(finalDom)), String(finalDom).slice(0, 120));
  await lib.screenshotPng(client, EVIDENCE_DIR, 'block97-todo-final.png').catch(() => {});

  // ── V4 事件持久化：afterSeq=0 重放含 task_todo 且顺序正确 ──
  if (!taskId) throw new Error('no_taskId_for_event_assertions');
  const events = await fetchTaskEvents(taskId);
  const todoEvents = events.filter((e) => e && e.event === 'task_todo');
  const todoResults = events.filter((e) => e && e.event === 'tool_result' && e.name === 'todo_write');
  run.assert('V4_task_todo_events_persisted', todoEvents.length >= 2, 'task_todo=' + todoEvents.length + ' tool_result=' + todoResults.length);
  const lastItems = todoEvents.length ? todoEvents[todoEvents.length - 1].items || [] : [];
  run.assert('V4_final_items_all_completed', lastItems.length >= 3 && lastItems.every((it) => it.status === 'completed'),
    'items=' + JSON.stringify(lastItems).slice(0, 160));

  // ── V5 重放确定性 ──
  const events2 = await fetchTaskEvents(taskId);
  const todo2 = events2.filter((e) => e && e.event === 'task_todo');
  const a = JSON.stringify(todoEvents[todoEvents.length - 1] || null);
  const b = JSON.stringify(todo2[todo2.length - 1] || null);
  run.assert('V5_replay_deterministic', todo2.length === todoEvents.length && a === b,
    'counts=' + todoEvents.length + '/' + todo2.length);

  run.finish();
  const passed = run.assertions.filter((a) => a.pass).length;
  console.log('[block97-todo-live] DONE ' + passed + '/' + run.assertions.length + ' allPass=' + run.allPass);
  process.exit(run.allPass ? 0 : 1);
})().catch((err) => {
  console.error('[block97-todo-live] FATAL', err && err.message);
  try { require('fs').mkdirSync(EVIDENCE_DIR, { recursive: true }); } catch {}
  process.exit(2);
});

#!/usr/bin/env node
'use strict';
/**
 * block98-resilience-live.cjs — BLOCK-98 P5 实机验收（dev Electron 真轮次）：
 *   W1 长任务运行中插队：composer 真发多步任务 → 运行中 POST /steer 注入标记消息
 *      → SSE input_queued 事件可见 → 最终回复包含标记内容（端到端零丢失）；
 *   W2 遥测列：ai_usage 表 additive 四列在位（attempt/retryable/context_exceeded/cancelled_by_user）；
 *   W3 microcompact 接线在场：PETRI_AGENT_RESILIENCE=1 下发送成功（开关分支加载）。
 * 前置：dev 栈带 PETRI_AGENT_RESILIENCE=1 启动；CDP 9222。
 * 证据：acceptance/block-98/block98-resilience-live.json + 截图。
 */
const path = require('node:path');
const http = require('node:http');
const lib = require(path.join(__dirname, '..', '.agents', 'skills', 'petri-dev-infra', 'dev-verify', 'lib.cjs'));
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const PROJECT_ID = process.argv[2] || 'p_mu5emekx_g13p';
const API = 'http://127.0.0.1:3001';
const AUTH = { Authorization: 'Bearer desktop-local', 'Content-Type': 'application/json' };
const EVIDENCE_DIR = path.join(__dirname, '..', 'acceptance', 'block-98');
const STEER_MARKER = '插队标记青色河马';

const PROMPT =
  '请用 todo_write 维护一个 4 条清单的任务，并逐步执行（每条执行前后正确更新状态）：' +
  '第一步：报出数字 7；第二步：报出数字 8；第三步：报出数字 9；第四步：完成后输出「四步完成」。' +
  '过程中请注意是否有新的用户插入消息，如有请在最后一条回复中原样复述插入消息的完整内容。';

let client;
const EVAL = (expr) => lib.evalJs(client, expr);

function apiPost(pathname, payload) {
  const body = JSON.stringify(payload || {});
  return new Promise((resolve, reject) => {
    const req = http.request(API + pathname, { method: 'POST', headers: { ...AUTH, 'Content-Length': Buffer.byteLength(body) } }, (res) => {
      let b = ''; res.on('data', (c) => { b += c; });
      res.on('end', () => { try { resolve({ status: res.statusCode, body: JSON.parse(b) }); } catch { resolve({ status: res.statusCode, body: b }); } });
    });
    req.on('error', reject); req.write(body); req.end();
  });
}

async function attach() {
  const targets = await lib.pollTargets({ timeoutMs: 20000 });
  const candidates = lib.filterPageTargets(targets, /^http:\/\/localhost:3000\/(?!window\/)/);
  const target = await lib.selectPageTarget(candidates, {
    probe: async (c) => lib.evalJs(c, `!!document.getElementById('root')`).catch(() => false),
  });
  return lib.connectTarget(target);
}

(async () => {
  const run = lib.createRun({ name: 'block98-resilience-live', evidenceDir: EVIDENCE_DIR });
  const startedAt = Date.now();
  client = await attach();
  await lib.evalJs(client, `location.href = 'http://localhost:3000/project/${PROJECT_ID}'; 'nav'`);
  await sleep(5000);
  client = await attach();
  // URL 守卫：探针独占窗口期间用户操作会改变路由——不在目标项目直接中止（不乱发消息）
  const guardUrl = await EVAL(`location.pathname`);
  run.assert('V0_on_target_project', String(guardUrl) === `/project/${PROJECT_ID}`, 'pathname=' + guardUrl);
  if (String(guardUrl) !== `/project/${PROJECT_ID}`) throw new Error('user navigated away — abort (no message sent)');

  // 打开文件 tab 无关；确认 composer 在场后真发
  let typed = '';
  for (let i = 0; i < 12 && !String(typed).startsWith('typed'); i++) {
    typed = await EVAL(
      "(function(){ var ta=document.querySelector('textarea.sc-input'); if(!ta) return 'no_textarea';" +
      " var st=Object.getOwnPropertyDescriptor(window.HTMLTextAreaElement.prototype,'value').set;" +
      " st.call(ta, " + JSON.stringify(PROMPT) + "); ta.dispatchEvent(new Event('input',{bubbles:true})); return 'typed'; })()");
    if (String(typed).startsWith('typed')) break;
    await sleep(1000);
  }
  run.assert('V1_composer_sent', String(typed).startsWith('typed'), String(typed));
  const clicked = await EVAL(
    "(function(){ var btns=document.querySelectorAll('button'); for (var i=0;i<btns.length;i++){ if((btns[i].getAttribute('title')||'').indexOf('发送')>=0 && btns[i].offsetParent){ btns[i].click(); return 'clicked'; } } return 'no_btn'; })()");
  run.assert('V1_send_clicked', clicked === 'clicked', String(clicked));

  // 等任务开始（localStorage taskId）
  let taskId = null;
  for (let i = 0; i < 25 && !taskId; i++) {
    await sleep(1000);
    const ids = await EVAL(
      "JSON.stringify(Object.keys(localStorage).filter(function(k){return k.indexOf('petri_agent_task_')===0||k.indexOf('petri_agent_task_')===0;}).map(function(k){return k.split('agent_task_')[1];}))");
    try { const arr = JSON.parse(ids); if (Array.isArray(arr) && arr.length) taskId = arr[arr.length - 1]; } catch {}
  }
  run.assert('V1_task_created', Boolean(taskId), 'taskId=' + (taskId || 'none'));
  await sleep(3000); // 让 loop 进入第 2 轮

  // ── W1 运行中插队 ──
  const steer = await apiPost(`/api/ai/agent/task/${taskId}/steer`, { message: `${STEER_MARKER}（请在最后复述这句）` });
  run.assert('W1_steer_accepted', steer.status === 200 && steer.body && steer.body.queued === true,
    `HTTP ${steer.status} ${JSON.stringify(steer.body).slice(0, 100)}`);

  // SSE input_queued 可见（页面事件流出现该事件 → 摘要条 statusMessage 或任务事件）
  let sseSeen = false;
  for (let i = 0; i < 10; i++) {
    const seen = await EVAL(
      `(function(){ var el=document.querySelector('[class*="workspaceSessionStatus"], [class*="sc-status"], [role="status"]');` +
      ` var t=document.body.textContent; return t.indexOf('已排队')>=0 ? 'status-visible' : 'pending'; })()`);
    if (seen === 'status-visible') { sseSeen = true; break; }
    await sleep(1000);
  }
  run.assert('W1_queued_visible', sseSeen, 'queued notice visible in UI');

  // 等任务终态 + 检查回复含标记
  let finalText = '';
  for (let i = 0; i < 90; i++) {
    await sleep(2000);
    finalText = String(await EVAL(
      `(function(){ var msgs=document.querySelectorAll('.sc-messages .sc-msg'); var last=msgs[msgs.length-1]; return last? last.textContent : ''; })()`));
    if (finalText.indexOf('四步完成') >= 0) break;
  }
  run.assert('W1_steer_injection_zero_loss', finalText.includes(STEER_MARKER),
    'final reply contains steer marker (端到端零丢失): ' + finalText.slice(-120));

  // ── W2 遥测列 ──
  // 直接走 sqlite（脚本侧 better-sqlite3 只读 dev 库）
  try {
    const Database = require(path.join(__dirname, '..', 'core', 'petri-server', 'node_modules', 'better-sqlite3'));
    const dbPath = process.env.PETRI_DB_PATH || path.join(__dirname, '..', '.petri-dev-user-data', 'data', 'petri.db');
    const db = new Database(dbPath, { readonly: true });
    const cols = db.prepare("PRAGMA table_info('ai_usage')").all().map((c) => c.name);
    db.close();
    const need = ['attempt', 'retryable', 'context_exceeded', 'cancelled_by_user'];
    run.assert('W2_telemetry_columns', need.every((c) => cols.includes(c)), 'cols=' + need.join(','));
  } catch (e) {
    run.assert('W2_telemetry_columns', false, 'schema check failed: ' + e.message);
  }

  await lib.screenshotPng(client, EVIDENCE_DIR, 'block98-final.png').catch(() => {});
  run.finish();
  process.exit(run.allPass ? 0 : 1);
})().catch((err) => {
  console.error('[block98] FATAL', err && err.message);
  process.exit(2);
});

#!/usr/bin/env node
'use strict';
/**
 * block99-console-live.cjs — BLOCK-99 P4/G4 空间管理会话台实机验收（dev 栈 + 真实模型轮次）：
 *   C0 前置：spaces REST 可达，会话台测试会话 id 固定；
 *   C1 真轮次·子集工具链：toolSubset=knowledge-console 下真实模型新建空间 + 列空间
 *      （task 事件 tool_call 全部为 knowledge_*；REST 复核空间已存在）；
 *   C2 D4 门第一腿：真实轮次请求删空间 → knowledge_space_delete 首调返回
 *      confirmationRequired + 一次性 confirmToken，空间未被执行；
 *   C3 D4 门第二腿：凭 token 确认消息（与前端确认卡同格式）→ 删除成功 + REST 复核消失；
 *   C4 绑定链：REST 建空间 B → 真轮次 knowledge_space_bind 绑定测试会话 →
 *      GET binding 返回 B → REST 删 B（FK CASCADE 掉绑）→ binding 回落 ks_default。
 * 前置：dev 栈（vite 3000 + 后端 3001）+ chat 模型凭据。
 * 家法同 scripts/block94-knowledge-live.cjs；证据落 acceptance/block-99/。
 */
const path = require('node:path');
const http = require('node:http');

const API = 'http://127.0.0.1:3001';
const AUTH = { Authorization: 'Bearer desktop-local' };
// 生产同径：管理台先经 REST 建真实会话再挂 run（自造 id 会被
// getOrCreateActiveConversation 落到自动新建会话，绑定就写到别的 id 上了）。
let CONV_ID = 'conv_block99_console_live';
const SPACE_A = '实机验证空间A';
const SPACE_B = '实机验证空间B';

const checks = [];
function assert(name, ok, detail) {
  checks.push({ name, ok: !!ok, detail: String(detail || '').slice(0, 300) });
  console.log(`${ok ? 'PASS' : 'FAIL'} ${name}${ok ? '' : ' — ' + String(detail || '').slice(0, 300)}`);
}

async function apiRequest(method, pathname, body) {
  const headers = { ...AUTH };
  let payload;
  if (body != null) {
    headers['Content-Type'] = 'application/json';
    payload = JSON.stringify(body);
  }
  const res = await fetch(API + pathname, { method, headers, body: payload });
  let parsed;
  try { parsed = await res.json(); } catch { parsed = null; }
  return { status: res.status, body: parsed };
}

function fetchTaskEvents(taskId, timeoutMs = 12000) {
  return new Promise((resolve) => {
    const events = [];
    const req = http.get(`${API}/api/ai/agent/task/${taskId}?afterSeq=0`, { headers: AUTH }, (res) => {
      let buf = '';
      let done = false;
      const finish = () => {
        if (done) return;
        done = true;
        try { res.destroy(); } catch {}
        resolve(events);
      };
      const timer = setTimeout(finish, timeoutMs);
      res.on('data', (c) => {
        buf += c.toString('utf8');
        let idx;
        while ((idx = buf.indexOf('\n\n')) !== -1) {
          const raw = buf.slice(0, idx);
          buf = buf.slice(idx + 2);
          for (const line of raw.split('\n')) {
            const m = line.match(/^data:\s?(.*)$/);
            if (!m) continue;
            if (m[1] === '[DONE]') { clearTimeout(timer); finish(); return; }
            try {
              const obj = JSON.parse(m[1]);
              events.push(obj && obj.payload ? obj.payload : obj);
            } catch {}
          }
        }
      });
      res.on('end', () => { clearTimeout(timer); finish(); });
      res.on('error', () => { clearTimeout(timer); finish(); });
    });
    req.on('error', () => { clearTimeout(timer); finish(); });
  });
}

/** 发一轮真轮次并等到 done（或超时），返回聚合的 tool_call/tool_result 事件与最终文本。 */
async function runTurn(userText) {
  const taskRes = await apiRequest('POST', '/api/ai/agent', {
    messages: [{ role: 'user', content: userText }],
    // accessMode 显式 full：inferExecutionPolicy 无档位 fail-closed 塌缩 read（S-003），
    // mutating 管理工具会被拒——与前端管理台 hook 同参。
    context: { page: 'knowledge', toolSubset: 'knowledge-console', accessMode: 'full' },
    conversationId: CONV_ID,
  });
  const taskId = taskRes.body && taskRes.body.taskId;
  if (!taskId) return { taskId: null, toolCalls: [], toolResults: [], text: '' };
  let toolCalls = [];
  let toolResults = [];
  let text = '';
  for (let i = 0; i < 40; i++) {
    await new Promise((r) => setTimeout(r, 5000));
    const events = await fetchTaskEvents(taskId, 10000);
    toolCalls = events.filter((e) => e && e.event === 'tool_call');
    toolResults = events.filter((e) => e && e.event === 'tool_result');
    const deltas = events.filter((e) => e && e.event === 'agent_message_delta');
    text = deltas.map((e) => e.delta || '').join('') || text;
    if (events.some((e) => e && e.event === 'done')) break;
  }
  return { taskId, toolCalls, toolResults, text };
}

function toolResultData(evt) {
  return (evt && evt.toolResult && evt.toolResult.data) || null;
}

async function main() {
  // ── C0 前置 ──
  const spaces0 = await apiRequest('GET', '/api/knowledge/spaces');
  assert('C0_spaces_rest_ok', spaces0.status === 200 && Array.isArray(spaces0.body.spaces), JSON.stringify(spaces0.body).slice(0, 160));
  // 会话台生产路径：POST /api/ai/conversations 建真实会话（存在则复用同 title 最新一条）
  const convList = await apiRequest('GET', '/api/ai/conversations');
  const existing = (convList.body.conversations || []).find((c) => c.title === '知识空间管理台（实机）');
  if (existing) {
    CONV_ID = existing.id;
  } else {
    const mkConv = await apiRequest('POST', '/api/ai/conversations', { title: '知识空间管理台（实机）', lastPage: '/knowledge' });
    CONV_ID = (mkConv.body.conversation && mkConv.body.conversation.id) || CONV_ID;
  }
  assert('C0b_console_conversation_ready', !!CONV_ID, CONV_ID);
  // 清理历史残留（上次跑未删净）
  for (const s of spaces0.body.spaces || []) {
    if (s.name === SPACE_A || s.name === SPACE_B) await apiRequest('DELETE', `/api/knowledge/spaces/${s.id}`);
  }

  // ── C1 真轮次·子集工具链：建空间 + 列空间 ──
  const turn1 = await runTurn(
    `请用工具新建一个名为「${SPACE_A}」的知识空间，然后启用它，最后列出全部空间的名称与文档数。直接执行，不要询问。`
  );
  assert('C1a_task_created', !!turn1.taskId, 'no taskId');
  assert('C1b_tools_all_knowledge_family', turn1.toolCalls.length > 0 && turn1.toolCalls.every((e) => String(e.name || '').startsWith('knowledge_')),
    `tool calls: ${turn1.toolCalls.map((e) => e.name).join(',')}`);
  assert('C1c_space_create_called', turn1.toolCalls.some((e) => e.name === 'knowledge_space_create'), turn1.toolCalls.map((e) => e.name).join(','));
  const spaces1 = await apiRequest('GET', '/api/knowledge/spaces');
  const created = (spaces1.body.spaces || []).find((s) => s.name === SPACE_A);
  assert('C1d_space_exists_via_rest', !!created, JSON.stringify(spaces1.body).slice(0, 200));

  // ── C2/C3 D4 门：删空间两腿 ──
  const turn2 = await runTurn(`请删除「${SPACE_A}」这个知识空间。`);
  const gateResults = turn2.toolResults.filter((e) => e.name === 'knowledge_space_delete');
  const gateData = gateResults.map(toolResultData).find((d) => d && d.confirmationRequired === true);
  assert('C2a_gate_confirmation_required', !!gateData, JSON.stringify(gateResults.map(toolResultData)).slice(0, 220));
  assert('C2b_gate_token_issued', !!gateData && /^kc_[0-9a-f]{24}$/.test(String(gateData.confirmToken)), gateData && gateData.confirmToken);
  assert('C2c_gate_impact_truthful', !!gateData && gateData.impact && typeof gateData.impact.documents === 'number', JSON.stringify(gateData && gateData.impact));
  const spaces2 = await apiRequest('GET', '/api/knowledge/spaces');
  assert('C2d_space_still_exists_before_confirm', !!(spaces2.body.spaces || []).find((s) => s.name === SPACE_A), 'space vanished before user confirmation');

  const spaceIdA = created ? created.id : gateData && gateData.impact && gateData.impact.spaceId;
  const turn3 = await runTurn(
    `我确认执行 knowledge_space_delete（对象 id=${spaceIdA}，confirmToken=${gateData ? gateData.confirmToken : ''}）。请立即凭此 confirmToken 重调工具执行，并简短报告结果。`
  );
  const delDone = turn3.toolResults.filter((e) => e.name === 'knowledge_space_delete').map(toolResultData).find((d) => d && d.deleted);
  assert('C3a_delete_executed_with_token', !!delDone, JSON.stringify(turn3.toolResults.map(toolResultData)).slice(0, 220));
  const spaces3 = await apiRequest('GET', '/api/knowledge/spaces');
  assert('C3b_space_gone_via_rest', !(spaces3.body.spaces || []).find((s) => s.id === spaceIdA), JSON.stringify(spaces3.body).slice(0, 200));

  // ── C4 绑定链：REST 建 B → 真轮次绑定 → GET binding → 删 B 回落 ──
  const mkB = await apiRequest('POST', '/api/knowledge/spaces', { name: SPACE_B });
  const spaceB = mkB.body && mkB.body.space;
  assert('C4a_space_b_created', mkB.status === 200 && !!spaceB, JSON.stringify(mkB.body).slice(0, 160));
  const turn4 = await runTurn(`请把当前会话绑定到知识空间「${SPACE_B}」。`);
  assert('C4b_bind_called', turn4.toolCalls.some((e) => e.name === 'knowledge_space_bind'), turn4.toolCalls.map((e) => e.name).join(','));
  const binding1 = await apiRequest('GET', `/api/knowledge/binding?conversationId=${encodeURIComponent(CONV_ID)}`);
  assert('C4c_binding_reads_space_b', binding1.status === 200 && binding1.body.spaceId === spaceB.id, JSON.stringify(binding1.body));
  const delB = await apiRequest('DELETE', `/api/knowledge/spaces/${spaceB.id}`);
  assert('C4d_space_b_deleted', delB.status === 200, JSON.stringify(delB.body).slice(0, 160));
  const binding2 = await apiRequest('GET', `/api/knowledge/binding?conversationId=${encodeURIComponent(CONV_ID)}`);
  assert('C4e_binding_falls_back_default', binding2.status === 200 && binding2.body.spaceId === 'ks_default', JSON.stringify(binding2.body));

  // ── U 系列：CDP 测试实例 UI 走查（/knowledge 双栏 + 会话台真轮次经 UI 输入）──
  try {
    const lib = require(path.join(__dirname, '..', '.agents', 'skills', 'petri-dev-infra', 'dev-verify', 'lib.cjs'));
    const fs = require('node:fs');
    const client = await lib.connectTestTarget({});
    const evalJs = async (expr) => {
      const r = await client.send('Runtime.evaluate', { expression: expr, returnByValue: true, awaitPromise: true });
      if (r.exceptionDetails) throw new Error(r.exceptionDetails.text || 'eval failed');
      return r.result && r.result.value;
    };

    await evalJs("location.href='/knowledge'");
    await new Promise((r) => setTimeout(r, 2000));
    // BLOCK-103 — 抽屉开合有 localStorage 记忆：先清为收起再 reload，保证确定性起点
    await evalJs(`localStorage.setItem('petri.knowledgeConsoleOpen', '0'); location.reload()`);
    await new Promise((r) => setTimeout(r, 3000));
    // BLOCK-103 — 会话台改折叠抽屉（默认收起）：U1 断言把手挂载，再经把手展开后走原 composer 断言
    const mount = await evalJs(`(() => ({
      page: !!document.querySelector('[data-testid="knowledge-page"]'),
      panel: !!document.querySelector('[data-testid="knowledge-space-switcher"]'),
      handle: !!document.querySelector('[data-testid="knowledge-console-handle"]'),
      console: !!document.querySelector('[data-testid="knowledge-console"]'),
    }))()`);
    assert('U1_knowledge_page_panel_and_handle_mounted', mount.page && mount.panel && mount.handle && !mount.console, JSON.stringify(mount));
    await evalJs(`document.querySelector('[data-testid="knowledge-console-handle"]').click()`);
    await new Promise((r) => setTimeout(r, 500));
    const opened = await evalJs(`!!document.querySelector('[data-testid="knowledge-console"] textarea')`);
    assert('U1b_console_drawer_opens_via_handle', opened === true, 'handle click did not mount console composer');

    // 抽屉点击时才挂载 → useKnowledgeConsole 需要初始化（ready 前 textarea disabled）：
    // 轮询等待 composer 可用，最多 10s（原流程台面自页面加载即挂载，无此窗口）。
    let composerReady = false;
    for (let i = 0; i < 20 && !composerReady; i++) {
      await new Promise((r) => setTimeout(r, 500));
      composerReady = await evalJs(`(() => {
        const ta = document.querySelector('[data-testid="knowledge-console"] textarea');
        return !!ta && !ta.disabled;
      })()`);
    }
    assert('U1c_console_composer_ready', composerReady === true, 'composer not ready within 10s');

    // 会话台真轮次：React 受控 textarea 经原生 setter 写值 + input 事件 + 点发送
    const typed = await evalJs(`(() => {
      const ta = document.querySelector('[data-testid="knowledge-console"] textarea');
      if (!ta || ta.disabled) return false;
      const setter = Object.getOwnPropertyDescriptor(window.HTMLTextAreaElement.prototype, 'value').set;
      setter.call(ta, '请列出当前所有知识空间的名称与文档数量');
      ta.dispatchEvent(new Event('input', { bubbles: true }));
      const btn = document.querySelector('[data-testid="knowledge-console"] [aria-label="发送"]');
      if (!btn || btn.disabled) return false;
      btn.click();
      return true;
    })()`);
    assert('U2_console_message_submitted', typed === true, 'composer disabled or send button missing');

    // 等真实模型轮次：工具活动条（空间清单）或助手回复出现
    let sawToolActivity = false;
    let sawReply = false;
    for (let i = 0; i < 40; i++) {
      await new Promise((r) => setTimeout(r, 4000));
      const text = await evalJs(`(document.querySelector('[data-testid="knowledge-console"]')||{textContent:''}).textContent`);
      sawToolActivity = /空间清单|空间状态/.test(text || '');
      sawReply = !!text && text.replace(/请列出当前所有知识空间的名称与文档数量/g, '').trim().length > 20;
      if (sawToolActivity && sawReply) break;
    }
    assert('U3_console_real_turn_tool_activity', sawToolActivity, 'no knowledge tool activity rendered via UI');
    assert('U4_console_assistant_reply', sawReply, 'no assistant reply rendered via UI');

    const shot = await client.send('Page.captureScreenshot', { format: 'png' });
    const evidenceDir = path.join(__dirname, '..', 'acceptance', 'block-99');
    fs.mkdirSync(evidenceDir, { recursive: true });
    fs.writeFileSync(path.join(evidenceDir, 'block99-console-ui.png'), Buffer.from(shot.data, 'base64'));
    assert('U5_screenshot_captured', true, 'acceptance/block-99/block99-console-ui.png');

    // UI 轮次创建了真实会话行；证据保留最近一条（实机会话），清理 UI 轮次产生的多余行外移人工判断——保留诚实痕迹
    try { client.close(); } catch {}
  } catch (e) {
    assert('U0_test_instance_available', false, `${e.message}（前置：bash scripts/start-test-instance.sh）`);
  }

  const allPass = checks.every((c) => c.ok);
  console.log(`\nblock99-console-live: ${checks.filter((c) => c.ok).length}/${checks.length} allPass=${allPass}`);
  try {
    const fs = require('node:fs');
    const evidenceDir = path.join(__dirname, '..', 'acceptance', 'block-99');
    fs.mkdirSync(evidenceDir, { recursive: true });
    fs.writeFileSync(
      path.join(evidenceDir, 'block99-console-live.json'),
      JSON.stringify({ flow: 'block99-console-live', finishedAt: new Date().toISOString(), allPass, checks }, null, 2)
    );
    console.log('evidence: acceptance/block-99/block99-console-live.json');
  } catch {}
  process.exit(allPass ? 0 : 1);
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

#!/usr/bin/env node
/**
 * build-macos-runtime.mjs
 * ---------------------------------------------------------------
 * macOS arm64 R/Python 运行时「构建 + 改 manifest hash + 上传 OSS」一体化脚本。
 * 用于修复 🔴 macOS 运行时 OSS 404（路径 B：原始 zip 丢失 → 重新打包 → 用新
 * 真实 hash 覆盖 manifest 声明 → 上传，仍满足 plugin-manager 的 fail-closed 校验）。
 *
 * 消费端契约（src/plugin-manager.js installRuntime）：
 *   - zip 解压到 RUNTIMES_DIR/R（r）或 RUNTIMES_DIR/Python（py）；
 *   - 若解压后顶层是单个目录且无 bin/，会自动展平；
 *   - 顶层统一打 R/ 或 Python/ 前缀，内部含 bin/、lib/、library/ 等；
 *   - r 解压后跑 fix-r-paths.mjs 修 dylib 路径。
 *
 * 用法：
 *   # r：自动探测 R_HOME（本机系统 R）
 *   node scripts/build-macos-runtime.mjs --runtime r
 *   # py：必须指向 Python 3.11 前缀（本机无 3.11，需构建机）
 *   node scripts/build-macos-runtime.mjs --runtime py --source /path/to/python3.11
 *   # 仅预览（不写 manifest、不上传、不产出 zip）：检测 source + 打印计划
 *   node scripts/build-macos-runtime.mjs --runtime r --dry-run
 *   # 产出 zip + 改 manifest，但不上传
 *   node scripts/build-macos-runtime.mjs --runtime r --no-upload
 *   # 扁平打包（顶层直接 bin/lib/…，与已上线的 r 一致，跳过 plugin-manager 展平步骤）
 *   node scripts/build-macos-runtime.mjs --runtime py --source /tmp/py-dist --flat
 *
 * 安全边界：
 *   - 只读源安装树，绝不 prune/删除源；只在 zip 遍历时跳过 __pycache__/*.pyc 等垃圾。
 *   - 上传前先把 manifest 的 macos-arm64 sha256/sizeBytes 改为本次计算的真实值（非 null），
 *     因此 upload-macos-runtime.mjs 的 fail-closed 校验自然通过（声明即真相）。
 *   - multipart + public-read + HEAD 校验，确保下载端拿到 200 + 一致 hash。
 */

import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import zlib from 'node:zlib';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.resolve(__dirname, '..');
const OUT_DIR = process.env.OUT_DIR ? path.resolve(process.env.OUT_DIR) : path.join(REPO_ROOT, 'dist-runtime');
const MANIFEST_PATH = path.resolve(REPO_ROOT, 'resources/built-in-plugins/manifest.json');

function fail(msg, err) {
  console.error(`\n[build-macos-runtime] ERROR: ${msg}`);
  if (err) console.error(err);
  process.exit(1);
}

// ── 参数解析 ───────────────────────────────────────────────
const runtimeIdx = process.argv.indexOf('--runtime');
const runtime = (runtimeIdx >= 0 ? process.argv[runtimeIdx + 1] : '').toLowerCase();
const sourceIdx = process.argv.indexOf('--source');
const sourceArg = sourceIdx >= 0 ? path.resolve(process.argv[sourceIdx + 1]) : null;
const outIdx = process.argv.indexOf('--out');
const outArg = outIdx >= 0 ? path.resolve(process.argv[outIdx + 1]) : null;
const dryRun = process.argv.includes('--dry-run');
const noManifest = process.argv.includes('--no-manifest');
const noUpload = process.argv.includes('--no-upload');
const flat = process.argv.includes('--flat');

const RT = {
  r:  { manifestKey: 'petri-r-runtime', topName: 'R', ossSegment: 'r-runtime', lang: 'r' },
  py: { manifestKey: 'petri-py-runtime', topName: 'Python', ossSegment: 'py-runtime', lang: 'python' },
};
// 版本契约：macOS / Windows 运行时必须严格对齐，任意一方打运行时都不得偏离。
// 改这里即视为升级运行时版本（需同步 Windows 侧与 manifest.builtAgainst）。
const VERSION_CONTRACT = { r: '4.5.2', python: '3.11.9' };
const rt = RT[runtime];
if (!rt) fail('--runtime 必须是 r 或 py');

// ── 凭据加载（复用 upload-macos-runtime 逻辑） ──────────────
function loadSecretsFile() {
  const p = path.resolve(REPO_ROOT, '.petri-secrets');
  if (!fs.existsSync(p)) return;
  const re = /^\s*export\s+([A-Z0-9_]+)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s#]+))/gm;
  let m;
  while ((m = re.exec(fs.readFileSync(p, 'utf8'))) !== null) {
    const key = m[1];
    if (process.env[key] === undefined) process.env[key] = m[2] ?? m[3] ?? m[4] ?? '';
  }
}
loadSecretsFile();
const bucket = process.env.PETRI_OSS_BUCKET || 'petri-uploads';
const endpoint = process.env.OSS_ENDPOINT || 'oss-cn-hangzhou.aliyuncs.com';
const region = process.env.OSS_REGION || 'cn-hangzhou';

// ── 解析源安装树 ───────────────────────────────────────────
function detectRHome() {
  if (sourceArg) return sourceArg;
  try {
    const out = spawnSync('R', ['RHOME'], { encoding: 'utf-8', timeout: 10000 });
    if (out.status === 0 && out.stdout.trim()) return out.stdout.trim();
  } catch {}
  // 常见 macOS 路径兜底
  for (const p of ['/usr/local/lib/R', '/Library/Frameworks/R.framework/Resources', '/opt/homebrew/lib/R']) {
    if (fs.existsSync(path.join(p, 'bin', 'Rscript'))) return p;
  }
  return null;
}
function detectPyHome() {
  if (sourceArg) return sourceArg;
  return null; // py 必须显式给 source
}
function resolveSource() {
  if (rt.lang === 'r') {
    const home = detectRHome();
    if (!home || !fs.existsSync(path.join(home, 'bin', 'Rscript'))) fail('找不到 R 安装（用 --source 指定 R_HOME，需含 bin/Rscript）');
    return home;
  }
  const home = detectPyHome();
  if (!home || !fs.existsSync(path.join(home, 'bin', 'python3'))) fail('py 必须 --source 指向 Python 3.11 前缀（需含 bin/python3）');
  return home;
}

// ── 版本校验 ───────────────────────────────────────────────
function checkVersion(source) {
  const contract = VERSION_CONTRACT[rt.lang];
  if (rt.lang === 'r') {
    try {
      const out = spawnSync(path.join(source, 'bin', 'Rscript'), ['-e', 'cat(as.character(getRversion()))'], { encoding: 'utf-8', timeout: 15000 });
      const v = out.stdout.trim();
      console.log(`[build-macos-runtime] R 版本: ${v}（契约要求 ${contract}）`);
      if (v !== contract) fail(`R 版本 ${v} 与版本契约 ${contract} 不一致——macOS/Windows 运行时必须严格对齐，请用 ${contract} 重打`);
    } catch (e) { fail('无法读取 R 版本（需含 bin/Rscript）: ' + e.message); }
  } else {
    try {
      const out = spawnSync(path.join(source, 'bin', 'python3'), ['--version'], { encoding: 'utf-8', timeout: 15000 });
      const m = (out.stdout + out.stderr).match(/Python (\d+\.\d+\.\d+)/);
      const v = m ? m[1] : '?';
      console.log(`[build-macos-runtime] Python 版本: ${v}（契约要求 ${contract}）`);
      if (v !== contract) fail(`Python 版本 ${v} 与版本契约 ${contract} 不一致——macOS/Windows 运行时必须严格对齐，请用 ${contract} 重打`);
    } catch (e) { fail('无法读取 Python 版本（需含 bin/python3）: ' + e.message); }
  }
}

// ── 流式 ZIP（单层顶层目录，deflate，逐文件常驻内存低） ────
const CRC_TABLE = (() => {
  const t = new Uint32Array(256);
  for (let n = 0; n < 256; n++) { let c = n; for (let k = 0; k < 8; k++) c = (c & 1) ? (0xedb88320 ^ (c >>> 1)) : (c >>> 1); t[n] = c >>> 0; }
  return t;
})();
function crc32(buf) { let c = 0xffffffff; for (let i = 0; i < buf.length; i++) c = CRC_TABLE[(c ^ buf[i]) & 0xff] ^ (c >>> 8); return (c ^ 0xffffffff) >>> 0; }
function dosDateTime(d = new Date(1980, 0, 1, 0, 0, 0)) {
  const time = ((d.getHours() & 0x1f) << 11) | ((d.getMinutes() & 0x3f) << 5) | ((d.getSeconds() / 2) & 0x1f);
  const date = (((d.getFullYear() - 1980) & 0x7f) << 9) | (((d.getMonth() + 1) & 0xf) << 5) | (d.getDate() & 0x1f);
  return { time: time & 0xffff, date: date & 0xffff };
}
// 跳过的垃圾：Python 缓存、macOS 元数据、版本控制
const SKIP_DIRS = new Set(['__pycache__', '.git', '.svn', 'node_modules']);
const SKIP_FILE_RE = /\.pyc$|\.DS_Store$|~$|\.swp$/;

function zipDirSingleLayer(srcDir, zipPath, topName) {
  fs.mkdirSync(path.dirname(zipPath), { recursive: true });
  if (fs.existsSync(zipPath)) fs.rmSync(zipPath, { force: true });
  const fd = fs.openSync(zipPath, 'w');
  const central = [];
  const { time, date } = dosDateTime();
  let fileCount = 0, byteCount = 0;

  const walk = (dir, relPrefix) => {
    const entries = fs.readdirSync(dir, { withFileTypes: true });
    for (const e of entries) {
      if (SKIP_DIRS.has(e.name)) continue;
      if (SKIP_FILE_RE.test(e.name)) continue;
      const abs = path.join(dir, e.name);
      const rel = relPrefix ? `${relPrefix}/${e.name}` : e.name;
      if (e.isDirectory()) { walk(abs, rel); }
      else if (e.isSymbolicLink()) {
        // 符号链接：stored（不压缩），数据为链接目标；用 lstat 真实 mode（含 S_IFLNK）写
        // external attributes，并把 central 的 version-made-by 设为 Unix(788)，让系统 unzip
        // 还原为软链（如 pyenv 的 bin/python3 -> python3.11）。
        const target = fs.readlinkSync(abs);
        const data = Buffer.from(target, 'utf8');
        const crc = crc32(data);
        const st = fs.lstatSync(abs);
        const name = topName ? `${topName}/${rel}` : rel;
        const nameBuf = Buffer.from(name, 'utf8');
        const localOffset = byteCount;
        const header = Buffer.alloc(30);
        header.writeUInt32LE(0x04034b50, 0);
        header.writeUInt16LE(20, 4);
        header.writeUInt16LE(0x0800, 6);
        header.writeUInt16LE(0, 8); // stored
        header.writeUInt16LE(time, 10);
        header.writeUInt16LE(date, 12);
        header.writeUInt32LE(crc, 14);
        header.writeUInt32LE(data.length, 18);
        header.writeUInt32LE(data.length, 22);
        header.writeUInt16LE(nameBuf.length, 26);
        header.writeUInt16LE(0, 28);
        fs.writeSync(fd, header); fs.writeSync(fd, nameBuf); fs.writeSync(fd, data);
        central.push({ crc, compLen: data.length, uncompLen: data.length, nameBuf, localOffset, externalAttrs: ((st.mode & 0xffff) << 16) >>> 0 });
        byteCount += 30 + nameBuf.length + data.length;
        fileCount++;
        if (fileCount % 20000 === 0) console.log(`[build-macos-runtime] zipped ${fileCount} files ...`);
      }
      else if (e.isFile()) {
        const data = fs.readFileSync(abs);
        const comp = zlib.deflateRawSync(data, { level: 6 });
        const crc = crc32(data);
        const st = fs.lstatSync(abs);
        const name = topName ? `${topName}/${rel}` : rel;
        const nameBuf = Buffer.from(name, 'utf8');
        const localOffset = byteCount;
        const header = Buffer.alloc(30);
        header.writeUInt32LE(0x04034b50, 0);
        header.writeUInt16LE(20, 4);
        header.writeUInt16LE(0x0800, 6);
        header.writeUInt16LE(8, 8);
        header.writeUInt16LE(time, 10);
        header.writeUInt16LE(date, 12);
        header.writeUInt32LE(crc, 14);
        header.writeUInt32LE(comp.length, 18);
        header.writeUInt32LE(data.length, 22);
        header.writeUInt16LE(nameBuf.length, 26);
        header.writeUInt16LE(0, 28);
        fs.writeSync(fd, header); fs.writeSync(fd, nameBuf); fs.writeSync(fd, comp);
        // external attributes 用 lstat 真实 mode（含类型+权限位），保留 exec 位（如 python3.11=0755）
        central.push({ crc, compLen: comp.length, uncompLen: data.length, nameBuf, localOffset, externalAttrs: ((st.mode & 0xffff) << 16) >>> 0 });
        byteCount += 30 + nameBuf.length + comp.length;
        fileCount++;
        if (fileCount % 20000 === 0) console.log(`[build-macos-runtime] zipped ${fileCount} files ...`);
      }
    }
  };
  walk(srcDir, '');
  const centralStart = byteCount;
  for (const c of central) {
    const ch = Buffer.alloc(46);
    ch.writeUInt32LE(0x02014b50, 0); ch.writeUInt16LE(788, 4); ch.writeUInt16LE(20, 6); // 788 = Unix version-made-by
    ch.writeUInt16LE(0x0800, 8); ch.writeUInt16LE(8, 10);
    ch.writeUInt16LE(time, 12); ch.writeUInt16LE(date, 14);
    ch.writeUInt32LE(c.crc, 16); ch.writeUInt32LE(c.compLen, 20); ch.writeUInt32LE(c.uncompLen, 24);
    ch.writeUInt16LE(c.nameBuf.length, 28); ch.writeUInt16LE(0, 30); ch.writeUInt16LE(0, 32);
    ch.writeUInt16LE(0, 34); ch.writeUInt16LE(0, 36); ch.writeUInt32LE(c.externalAttrs || 0, 38); ch.writeUInt32LE(c.localOffset, 42);
    fs.writeSync(fd, ch); fs.writeSync(fd, c.nameBuf);
    byteCount += 46 + c.nameBuf.length;
  }
  const eocd = Buffer.alloc(22);
  eocd.writeUInt32LE(0x06054b50, 0); eocd.writeUInt16LE(0, 4); eocd.writeUInt16LE(0, 6);
  eocd.writeUInt16LE(fileCount, 8); eocd.writeUInt16LE(fileCount, 10);
  eocd.writeUInt32LE(byteCount - centralStart, 12); eocd.writeUInt32LE(centralStart, 16); eocd.writeUInt16LE(0, 20);
  fs.writeSync(fd, eocd); fs.fsyncSync(fd); fs.closeSync(fd);
  console.log(`[build-macos-runtime] zip written: ${fileCount} files, ${(byteCount / 1024 / 1024).toFixed(1)} MB`);
}

// ── manifest 改值 ──────────────────────────────────────────
function updateManifest(sha256, sizeBytes) {
  const manifest = JSON.parse(fs.readFileSync(MANIFEST_PATH, 'utf8'));
  const art = manifest?.plugins?.[rt.manifestKey]?.artifacts?.['macos-arm64'];
  if (!art) fail(`manifest 缺少 ${rt.manifestKey}.artifacts.macos-arm64`);
  const prev = { sha256: art.sha256, sizeBytes: art.sizeBytes };
  art.sha256 = sha256;
  art.sizeBytes = sizeBytes;
  manifest.updated = new Date().toISOString().slice(0, 10);
  fs.writeFileSync(MANIFEST_PATH, JSON.stringify(manifest, null, 2) + '\n');
  console.log(`[build-macos-runtime] manifest updated: ${rt.manifestKey}.macos-arm64 sha256/sizeBytes -> 新值`);
  console.log(`  旧: sha256=${prev.sha256} size=${prev.sizeBytes}`);
  console.log(`  新: sha256=${sha256} size=${sizeBytes}`);
}

// ── 上传 ───────────────────────────────────────────────────
async function upload(objectName, zipPath) {
  const OSS = (await import('ali-oss')).default;
  const accessKeyId = process.env.OSS_AK || process.env.PETRI_OSS_ACCESS_KEY_ID || process.env.OSS_ACCESS_KEY_ID;
  const accessKeySecret = process.env.OSS_SK || process.env.PETRI_OSS_ACCESS_KEY_SECRET || process.env.OSS_ACCESS_KEY_SECRET;
  if (!accessKeyId || !accessKeySecret) fail('缺少 OSS 凭据（.petri-secrets 或 OSS_AK/OSS_SK）');
  const client = new OSS({
    region, endpoint: endpoint.startsWith('http') ? endpoint : `https://${endpoint}`, bucket, accessKeyId, accessKeySecret,
    timeout: Number(process.env.PETRI_OSS_UPLOAD_TIMEOUT_MS || 1800000),
  });
  console.log('[build-macos-runtime] uploading (multipart)...');
  await client.multipartUpload(objectName, zipPath, {
    partSize: Number(process.env.PETRI_OSS_UPLOAD_PART_SIZE || 10 * 1024 * 1024),
    parallel: 4,
    headers: { 'Content-Type': 'application/zip', 'Cache-Control': 'public, immutable, max-age=31536000' },
  });
  await client.putACL(objectName, 'public-read');
  const head = await client.head(objectName);
  if (!head || head.status !== 200) fail('上传后 HEAD 校验未通过');
  return `https://${bucket}.${endpoint}/${objectName}`;
}

// ── main ───────────────────────────────────────────────────
function main() {
  const source = resolveSource();
  console.log(`[build-macos-runtime] runtime : ${rt.manifestKey} (${rt.lang})`);
  console.log(`[build-macos-runtime] source  : ${source}`);
  checkVersion(source);
  const objectName = `plugins/${rt.ossSegment}/1.0.0/macos-arm64.zip`;
  const zipPath = outArg || path.join(OUT_DIR, `${rt.ossSegment}-1.0.0-macos-arm64.zip`);
  const publicUrl = `https://${bucket}.${endpoint}/${objectName}`;

  if (dryRun) {
    console.log(`[build-macos-runtime] --dry-run: 计划`);
    console.log(`  zip    -> ${zipPath}`);
    console.log(`  dest   -> oss://${bucket}/${objectName}`);
    console.log(`  url    -> ${publicUrl}`);
    console.log(`  action -> 改 manifest ${rt.manifestKey}.macos-arm64 为新 hash + 上传 + HEAD 200`);
    console.log('[build-macos-runtime] 未构建、未改 manifest、未上传。');
    process.exit(0);
  }

  fs.mkdirSync(OUT_DIR, { recursive: true });
  console.log(`[build-macos-runtime] streaming-zip -> ${zipPath}${flat ? ' (flat)' : ''}`);
  zipDirSingleLayer(source, zipPath, flat ? '' : rt.topName);

  const buf = fs.readFileSync(zipPath);
  const sha256 = crypto.createHash('sha256').update(buf).digest('hex');
  const sizeBytes = buf.length;
  console.log(`[build-macos-runtime] sha256   : ${sha256}`);
  console.log(`[build-macos-runtime] sizeBytes: ${sizeBytes}`);

  if (!noManifest) updateManifest(sha256, sizeBytes);

  if (!noUpload) {
    upload(objectName, zipPath).then((url) => {
      console.log(`\n==================== BUILD + UPLOAD COMPLETE ====================`);
      console.log(`artifact : ${zipPath}`);
      console.log(`url      : ${url}`);
      console.log(`sha256   : ${sha256}`);
      console.log(`sizeBytes: ${sizeBytes}`);
      console.log(`\n验证 404 已消除：`);
      console.log(`  curl -sI "${url}" | head -1`);
    }).catch((e) => fail('上传失败', e));
  } else {
    console.log(`\n[build-macos-runtime] --no-upload：zip 已产出 + manifest 已改（如需上传去掉 --no-upload）。`);
  }
}

