#!/usr/bin/env node
'use strict';

/**
 * Resilient CDP bridge: keeps playwright MCP alive across Electron restarts.
 *
 * Loop:
 *   1. Poll for CDP endpoint (blocks until Electron is ready)
 *   2. Spawn playwright MCP with the resolved endpoint
 *   3. When playwright exits → go back to step 1
 *
 * The script never exits on its own. Only Ctrl+C / SIGTERM stops it.
 */
const http = require('http');
const { spawn } = require('child_process');

const isWin = process.platform === 'win32';
const npmCmd = isWin ? 'npm.cmd' : 'npx';
const PLAYWRIGHT_MCP = '@playwright/mcp@latest';
const CDP_PORT = process.env.CDP_PORT || '9222';
const CDP_POLL_MS = 800;

function fetchJson(url) {
  return new Promise((resolve, reject) => {
    const mod = url.startsWith('https') ? require('https') : require('http');
    const req = mod.get(url, (res) => {
      if (res.statusCode >= 400) { reject(new Error(`HTTP ${res.statusCode}`)); return; }
      let data = '';
      res.on('data', (c) => (data += c));
      res.on('end', () => {
        try { resolve(JSON.parse(data)); }
        catch { reject(new Error('invalid JSON')); }
      });
    });
    req.on('error', reject);
    req.setTimeout(5000, () => { req.destroy(); reject(new Error('fetch timeout')); });
  });
}

async function pollCdp(port) {
  let attempt = 0;
  while (true) {
    attempt++;
    if (attempt === 1) {
      log(`polling for dev Electron CDP on port ${port}...`);
    } else if (attempt % 20 === 0) {
      log(`still polling for CDP... (attempt ${attempt})`);
      log(`start dev with: PETRI_DEV_ELECTRON_CDP=1 npm run dev`);
    }
    try {
      const v = await fetchJson(`http://127.0.0.1:${port}/json/version`);
      if (v?.webSocketDebuggerUrl) {
        log(`CDP ready: ${v.webSocketDebuggerUrl}`);
        return v.webSocketDebuggerUrl;
      }
    } catch {}
    await new Promise((r) => setTimeout(r, CDP_POLL_MS));
  }
}

function log(msg) {
  process.stderr.write(`[cdp-wrap] ${msg}\n`);
}

async function spawnPlaywright(wsUrl) {
  log(`spawning @playwright/mcp with ${wsUrl}`);
  const child = spawn(npmCmd, [PLAYWRIGHT_MCP, '--no-sandbox'], {
    stdio: ['inherit', 'pipe', 'pipe'],
    shell: isWin,
    env: {
      ...process.env,
      PLAYWRIGHT_MCP_CDP_ENDPOINT: wsUrl,
      CDP_ENDPOINT: wsUrl,
    },
  });

  // Forward playwright stdout/stderr
  child.stdout?.on('data', (c) => process.stdout.write(c));
  child.stderr?.on('data', (c) => process.stderr.write(c));

  return new Promise((resolve) => {
    child.on('exit', (code) => {
      log(`playwright exited (code=${code})`);
      resolve(code);
    });
  });
}

async function main() {
  while (true) {
    const wsUrl = await pollCdp(CDP_PORT);
    await spawnPlaywright(wsUrl);
    log(`playwright stopped — Electron may have restarted, re-polling CDP...`);
  }
}

main().catch((err) => {
  log(`FATAL: ${err.message}`);
  process.exit(1);
});

#!/usr/bin/env node
/**
 * UI-124 / MODEL-ANTHROPIC-NATIVE 实机收口证据脚本
 *
 * 模式：
 * - 未设置 BIOTEST_ANTHROPIC_KEY：dryrun 模式，验证脚本与调用 surface 可用，写出 dryrun 证据
 * - 设置 BIOTEST_ANTHROPIC_KEY：live 模式，访问 https://api.anthropic.com/v1 跑 4 步实机
 *
 * 输出：acceptance/MODEL-ANTHROPIC-NATIVE/anthropic-real-key-evidence.json
 * 不向 git 写入任何 Key 本身；evidence 仅记录 keyPresent 与 header 形态。
 */

import { writeFile, mkdir } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { createRequire } from 'node:module';

const require = createRequire(import.meta.url);
const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

const ROOT = resolve(__dirname, '..');
const EVIDENCE_DIR = resolve(ROOT, 'acceptance', 'MODEL-ANTHROPIC-NATIVE');
const EVIDENCE_PATH = resolve(EVIDENCE_DIR, 'anthropic-real-key-evidence.json');
const ANTHROPIC_BASE = 'https://api.anthropic.com';
const ANTHROPIC_VERSION = '2023-06-01';
const HTTP_TIMEOUT_MS = 30_000;

const KEY = process.env.BIOTEST_ANTHROPIC_KEY || '';
const MODE = KEY ? 'live' : 'dryrun';
const START_TS = new Date().toISOString();

const evidence = {
  uiId: 'UI-124',
  workPackage: 'MODEL-ANTHROPIC-NATIVE',
  mode: MODE,
  baseUrl: ANTHROPIC_BASE,
  anthropicVersion: ANTHROPIC_VERSION,
  keyPresent: Boolean(KEY),
  keyLength: KEY.length,
  startedAt: START_TS,
  steps: [],
  errors: [],
};

function recordStep(name, payload) {
  evidence.steps.push({ name, ts: new Date().toISOString(), ...payload });
}

function recordError(name, err) {
  evidence.errors.push({
    name,
    ts: new Date().toISOString(),
    message: err && err.message ? err.message : String(err),
    code: err && err.code ? err.code : null,
  });
}

async function withTimeout(promise, ms, label) {
  let handle;
  const timeout = new Promise((_, reject) => {
    handle = setTimeout(() => reject(new Error(`${label} timeout ${ms}ms`)), ms);
  });
  try {
    return await Promise.race([promise, timeout]);
  } finally {
    clearTimeout(handle);
  }
}

async function liveFetch(pathname, init = {}) {
  const url = `${ANTHROPIC_BASE}${pathname}`;
  const headers = {
    'content-type': 'application/json',
    'x-api-key': KEY,
    'anthropic-version': ANTHROPIC_VERSION,
    ...(init.headers || {}),
  };
  const start = Date.now();
  const res = await withTimeout(
    fetch(url, { ...init, headers }),
    HTTP_TIMEOUT_MS,
    pathname,
  );
  const text = await res.text();
  return {
    status: res.status,
    headers: Object.fromEntries(res.headers.entries()),
    text,
    durationMs: Date.now() - start,
  };
}

async function stepListModels() {
  // Anthropic 不提供 list models endpoint；走 messages minimal ping 作为模型可达性
  // 这里复用核心 provider 类的 discover 路径，仅用其输入契约，不调用 fetch
  const { AnthropicProvider } = require(resolve(
    ROOT,
    'core/shared-backend/llm-providers/anthropic.js',
  ));
  const provider = new AnthropicProvider({
    apiKey: KEY,
    baseUrl: ANTHROPIC_BASE,
    model: 'claude-haiku-4-5',
  });
  recordStep('listModels', {
    providerClass: provider.constructor.name,
    defaultModel: provider.model,
    discovery: 'anthropic-no-list-endpoint; use static defaults from model-provider-options',
  });
}

async function stepChatRoundtrip() {
  const { AnthropicProvider } = require(resolve(
    ROOT,
    'core/shared-backend/llm-providers/anthropic.js',
  ));
  const provider = new AnthropicProvider({
    apiKey: KEY,
    baseUrl: ANTHROPIC_BASE,
    model: 'claude-haiku-4-5',
  });
  const messages = [{ role: 'user', content: 'ping' }];
  const result = await provider.chat({ messages, maxTokens: 16 });
  recordStep('chat', {
    durationMs: result.durationMs || null,
    contentChars: (result.content || '').length,
    usage: result.usage || null,
    finishReason: result.finishReason || null,
    contentHead: (result.content || '').slice(0, 80),
  });
  return result;
}

async function stepChatStream() {
  const { AnthropicProvider } = require(resolve(
    ROOT,
    'core/shared-backend/llm-providers/anthropic.js',
  ));
  const provider = new AnthropicProvider({
    apiKey: KEY,
    baseUrl: ANTHROPIC_BASE,
    model: 'claude-haiku-4-5',
  });
  const messages = [{ role: 'user', content: 'stream-ping' }];
  let firstEventTs = null;
  let lastEventTs = null;
  let textLen = 0;
  let usage = null;
  const events = [];
  await provider.chatStream({
    messages,
    maxTokens: 16,
    onEvent(ev) {
      const now = Date.now();
      if (!firstEventTs) firstEventTs = now;
      lastEventTs = now;
      events.push(ev.type || 'unknown');
      if (typeof ev.text === 'string') textLen += ev.text.length;
      if (ev.usage) usage = ev.usage;
    },
  });
  recordStep('chatStream', {
    eventTypes: Array.from(new Set(events)),
    firstEventMs: firstEventTs ? firstEventTs - START_TS_TS() : null,
    lastEventMs: lastEventTs ? lastEventTs - START_TS_TS() : null,
    textLen,
    usage,
  });
}

function START_TS_TS() {
  return new Date(evidence.startedAt).getTime();
}

async function stepUsageChannel() {
  // 用最轻的 ai-usage-helper 单测 hook 验证通道；只检查导出与 recordAiUsage 函数形态
  const usagePath = resolve(ROOT, 'core/shared-backend/ai-usage-helper.js');
  if (!existsSync(usagePath)) {
    recordStep('usage', { found: false });
    return;
  }
  delete require.cache[usagePath];
  const helper = require(usagePath);
  const fnNames = Object.keys(helper || {}).filter(
    (k) => typeof helper[k] === 'function',
  );
  recordStep('usage', {
    found: true,
    fnNames,
    modulePath: pathToFileURL(usagePath).href,
  });
}

async function run() {
  if (!existsSync(EVIDENCE_DIR)) {
    await mkdir(EVIDENCE_DIR, { recursive: true });
  }
  if (MODE === 'dryrun') {
    evidence.steps.push(
      {
        name: 'listModels',
        ts: new Date().toISOString(),
        note: 'dryrun: 跳过 fetch，仅打印 provider 默认模型',
        expectedProviderClass: 'AnthropicProvider',
        expectedDefaultModel: 'claude-haiku-4-5',
      },
      {
        name: 'chat',
        ts: new Date().toISOString(),
        note: 'dryrun: BIOTEST_ANTHROPIC_KEY 未设置，跳过实机',
        expectedDurationMs: '<3000 on healthy key',
      },
      {
        name: 'chatStream',
        ts: new Date().toISOString(),
        note: 'dryrun: 跳过流式实机',
        expectedEventTypes: ['content_block_delta', 'message_stop', 'message_start'],
      },
      {
        name: 'usage',
        ts: new Date().toISOString(),
        note: 'dryrun: 仅校验 ai-usage-helper 导出形态',
      },
    );
    evidence.errors.push({
      name: 'live-skip',
      ts: new Date().toISOString(),
      message:
        'BIOTEST_ANTHROPIC_KEY 未设置；未做实机。本机配置完成后重跑脚本以升级 evidence。',
      code: 'NO_KEY',
    });
  } else {
    try {
      await stepListModels();
    } catch (err) {
      recordError('listModels', err);
    }
    try {
      await stepChatRoundtrip();
    } catch (err) {
      recordError('chat', err);
    }
    try {
      await stepChatStream();
    } catch (err) {
      recordError('chatStream', err);
    }
    try {
      await stepUsageChannel();
    } catch (err) {
      recordError('usage', err);
    }
  }

  evidence.finishedAt = new Date().toISOString();
  await writeFile(EVIDENCE_PATH, JSON.stringify(evidence, null, 2) + '\n', 'utf8');
  const summary = {
    mode: MODE,
    steps: evidence.steps.length,
    errors: evidence.errors.length,
    evidence: EVIDENCE_PATH,
  };
  console.log(JSON.stringify(summary, null, 2));
  if (MODE === 'live' && evidence.errors.length > 0) {
    process.exitCode = 1;
  }
}

run().catch((err) => {
  console.error('check-model-anthropic-native failed:', err);
  process.exit(2);
});

#!/usr/bin/env node

/**
 * dev-electron-profile — measure Electron main-process startup proxy metrics.
 *
 * Measures module-load overhead as a proxy for startup time without requiring
 * a real display or Electron binary. Actual Electron launch timing (T0 spawn →
 * T4 renderer first paint) requires a live display and is documented in the
 * output for local manual verification.
 *
 * Usage (proxy mode):
 *   node scripts/dev-electron-profile.mjs [--warmup N] [--threshold ms]
 *
 * Usage (CDP mode — measures T0→T4):
 *   node scripts/dev-electron-profile.mjs --cdp [--port N] [--timeout ms] [--output json|csv]
 *
 * CLI options (proxy mode):
 *   --warmup N     number of warmup iterations before measurement (default: 5)
 *   --threshold MS warn if average measured time exceeds this threshold (default: 1000)
 *
 * CLI options (CDP mode):
 *   --cdp          enable CDP measurement mode (requires Electron binary on PATH)
 *   --port N       remote-debugging-port (default: 9222)
 *   --timeout MS   max time to wait for Electron startup (default: 30000)
 *   --output FMT   output format: 'text' (default) or 'json'
 *
 * Output:
 *   Prints structured benchmark results and a WARNING line if threshold exceeded.
 *
 * CDP phases captured:
 *   T0: spawn       electron process launched
 *   T1: appReady    app 'ready' event fired in main process
 *   T2: windowShown main window first rendered
 *   T3: DOMLoaded   Page.lifecycleEvent 'DOMContentLoaded'
 *   T4: load        Page.lifecycleEvent 'load'
 *
 * CDP requirements:
 *   - Node.js >= 21 (uses built-in WebSocket)
 *   - Electron binary on PATH
 *   - No --disable-gpu flag needed for headless measurement
 */

import { execSync, spawn } from 'node:child_process';
import { readFileSync, statSync } from 'node:fs';
import { performance } from 'node:perf_hooks';
import { createRequire } from 'node:module';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const require = createRequire(import.meta.url);

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const MAIN_JS = path.join(ROOT, 'src/main.js');
const PRELOAD_JS = path.join(ROOT, 'src/preload.js');

// ── CLI argument parsing ───────────────────────────────────────────────────────

function parseArgs(argv) {
  let warmup = 5;
  let threshold = 1000;
  let cdpMode = false;
  let cdpPort = 9222;
  let cdpTimeout = 30_000;
  let outputFormat = 'text';
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === '--warmup' && i + 1 < argv.length) {
      warmup = parseInt(argv[++i], 10);
    } else if (arg === '--threshold' && i + 1 < argv.length) {
      threshold = parseInt(argv[++i], 10);
    } else if (arg === '--cdp') {
      cdpMode = true;
    } else if (arg === '--port' && i + 1 < argv.length) {
      cdpPort = parseInt(argv[++i], 10);
    } else if (arg === '--timeout' && i + 1 < argv.length) {
      cdpTimeout = parseInt(argv[++i], 10);
    } else if (arg === '--output' && i + 1 < argv.length) {
      const fmt = argv[++i];
      if (!['json', 'csv', 'text'].includes(fmt)) {
        console.error(`Unknown output format: ${fmt} (use json|csv|text)`);
        process.exit(1);
      }
      outputFormat = fmt;
    }
  }
  return { warmup, threshold, cdpMode, cdpPort, cdpTimeout, outputFormat };
}

// ── Static metrics ─────────────────────────────────────────────────────────────

function countPattern(content, pattern) {
  return (content.match(pattern) || []).length;
}

function collectStaticMetrics() {
  const main = readFileSync(MAIN_JS, 'utf8');
  const preload = readFileSync(PRELOAD_JS, 'utf8');

  const ipcHandleCount = countPattern(main, /ipcMain\.handle\(/g);
  const ipcOnCount = countPattern(main, /ipcMain\.on\(/g);
  const preloadInvokeCount = countPattern(preload, /ipcRenderer\.invoke\(/g);
  const preloadOnCount = countPattern(preload, /ipcRenderer\.on\(/g);
  const contextBridgeCount = countPattern(preload, /contextBridge\.exposeInMainWorld\(/g);

  const mainLines = main.split('\n').length;
  const preloadLines = preload.split('\n').length;
  const mainBytes = Buffer.byteLength(main, 'utf8');
  const preloadBytes = Buffer.byteLength(preload, 'utf8');
  const mainStat = statSync(MAIN_JS);
  const preloadStat = statSync(PRELOAD_JS);

  return {
    main: {
      lines: mainLines,
      bytes: mainBytes,
      modifiedMs: mainStat.mtimeMs,
      ipcHandlers: ipcHandleCount,
      ipcOn: ipcOnCount,
    },
    preload: {
      lines: preloadLines,
      bytes: preloadBytes,
      modifiedMs: preloadStat.mtimeMs,
      ipcInvokes: preloadInvokeCount,
      ipcOn: preloadOnCount,
      contextBridgeExposes: contextBridgeCount,
    },
    totalIpcChannels: ipcHandleCount + ipcOnCount,
  };
}

// ── Module-load timing ─────────────────────────────────────────────────────────
// node --check fails in plain Node because main.js requires Electron-only modules
// (electron, better-sqlite3, etc.). Detect this gracefully and fall back.

function tryNodeCheck(args, options) {
  try {
    return execSync('node --check src/main.js', { cwd: ROOT, encoding: 'utf8', ...options });
  } catch (err) {
    return null; // Electron-only module — plain Node cannot parse
  }
}

function measureNodeCheckWarmup(iterations) {
  for (let i = 0; i < iterations; i++) {
    tryNodeCheck(['--check', 'src/main.js'], { stdio: 'ignore' });
  }
}

function measureNodeCheck(iterations) {
  const times = [];
  for (let i = 0; i < iterations; i++) {
    const t0 = performance.now();
    const result = tryNodeCheck(['--check', 'src/main.js'], { stdio: 'ignore' });
    const elapsed = performance.now() - t0;
    if (result !== null) {
      times.push(elapsed);
    }
  }
  return times;
}

// ── File-read timing ──────────────────────────────────────────────────────────

function measureFileRead(iterations) {
  const times = [];
  for (let i = 0; i < iterations; i++) {
    const t0 = performance.now();
    readFileSync(MAIN_JS, 'utf8');
    readFileSync(PRELOAD_JS, 'utf8');
    times.push(performance.now() - t0);
  }
  return times;
}

// ── Statistics helpers ─────────────────────────────────────────────────────────

function median(values) {
  const sorted = [...values].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 !== 0 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
}

function mean(values) {
  return values.reduce((a, b) => a + b, 0) / values.length;
}

// ── CDP measurement ─────────────────────────────────────────────────────────────
// Uses Node.js built-in WebSocket (Node >= 21) + Electron --remote-debugging-port
// to capture T0–T4 startup phases.

function delay(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * Poll http://host:port/json/version until CDP is ready.
 * Returns { webSocketDebuggerUrl }.
 */
async function fetchCdpVersion(port, timeoutMs) {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    try {
      const controller = new AbortController();
      const timer = setTimeout(() => controller.abort(), 2000);
      const resp = await fetch(`http://127.0.0.1:${port}/json/version`, {
        signal: controller.signal,
      });
      clearTimeout(timer);
      if (resp.ok) {
        const data = await resp.json();
        if (data?.webSocketDebuggerUrl) return data;
      }
    } catch {}
    await delay(200);
  }
  throw new Error(`CDP endpoint not available on port ${port} within ${timeoutMs}ms`);
}

/**
 * Poll http://host:port/json/list and return the first 'page' target ws URL.
 */
async function fetchCdpPageTarget(port, timeoutMs) {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    try {
      const controller = new AbortController();
      const timer = setTimeout(() => controller.abort(), 2000);
      const resp = await fetch(`http://127.0.0.1:${port}/json/list`, {
        signal: controller.signal,
      });
      clearTimeout(timer);
      if (resp.ok) {
        const targets = await resp.json();
        if (Array.isArray(targets)) {
          const page = targets.find((t) => t?.type === 'page' && t.webSocketDebuggerUrl);
          if (page) return page;
        }
      }
    } catch {}
    await delay(200);
  }
  throw new Error(`CDP page target not found within ${timeoutMs}ms`);
}

class CdpClient {
  constructor(wsUrl) {
    this.wsUrl = wsUrl;
    this.nextId = 1;
    this.pending = new Map();
    this.listeners = new Map();
    this.socket = null;
    this._wsClass = null;
  }

  async connect(timeoutMs = 15_000) {
    const wsUrl = this.wsUrl;

    // Node.js >= 21 ships a global WebSocket; use dynamic import to be safe.
    const { default: WSClass } = await import('node:ws').catch(() => {
      throw new Error(
        'ws_unavailable: Node.js built-in WebSocket not found. ' +
        'Ensure Node.js >= 21, or install the "ws" package: npm install --save-dev ws',
      );
    });
    this._wsClass = WSClass;

    return new Promise((resolve, reject) => {
      const socket = new WSClass(wsUrl);
      this.socket = socket;

      const rejectOnce = (err) => {
        cleanup();
        reject(err);
      };

      const cleanup = () => {
        socket.removeListener('open', onOpen);
        socket.removeListener('error', onError);
        socket.removeListener('close', onClose);
        socket.removeListener('message', onMessage);
      };

      const onOpen = () => {
        socket.on('message', onMessage);
        socket.on('close', onClose);
        socket.on('error', () => {});
      };

      const onError = () => rejectOnce(new Error('cdp_socket_open_failed'));

      const onClose = () => {
        for (const p of this.pending.values()) p.reject(new Error('cdp_socket_closed'));
        this.pending.clear();
      };

      const onMessage = (data) => {
        let payload;
        try { payload = JSON.parse(String(data)); } catch { return; }
        if (payload.id) {
          const pending = this.pending.get(payload.id);
          if (!pending) return;
          this.pending.delete(payload.id);
          if (payload.error) pending.reject(new Error(`cdp_command_failed:${payload.error.code}`));
          else pending.resolve(payload.result || {});
        } else if (payload.method) {
          const listeners = this.listeners.get(payload.method) || [];
          for (const l of listeners) l(payload.params || {});
        }
      };

      const timer = setTimeout(() => rejectOnce(new Error('cdp_socket_open_timeout')), timeoutMs);

      const onOpenTimeout = () => {
        clearTimeout(timer);
        cleanup();
        rejectOnce(new Error('cdp_socket_open_timeout'));
      };

      socket.on('open', () => {
        clearTimeout(timer);
        socket.on('open', onOpen);
        socket.on('error', onError);
        resolve(this);
      });

      socket.on('error', onError);
    });
  }

  on(method, listener) {
    const list = this.listeners.get(method) || [];
    list.push(listener);
    this.listeners.set(method, list);
  }

  send(method, params = {}) {
    if (!this.socket || this.socket.readyState !== 1 /* OPEN */) {
      return Promise.reject(new Error('cdp_socket_not_open'));
    }
    const id = this.nextId++;
    return new Promise((resolve, reject) => {
      this.pending.set(id, { resolve, reject });
      this.socket.send(JSON.stringify({ id, method, params }));
    });
  }

  close() {
    try { this.socket?.terminate?.(); } catch {}
    try { this.socket?.close?.(); } catch {}
  }
}

/**
 * Measure Electron startup phases T0–T4 using CDP.
 *
 * @param {object} opts
 * @param {number}  opts.port      remote-debugging-port
 * @param {number}  opts.timeoutMs  max total measurement time
 * @param {string}  opts.outputFormat 'text' | 'json' | 'csv'
 * @param {string}  opts.electronPath optional path to electron binary
 */
async function measureCdpStartup({ port = 9222, timeoutMs = 30_000, outputFormat = 'text', electronPath = 'electron' } = {}) {
  const t0 = performance.now(); // spawn time — set immediately
  const phases = {
    T1: null, // app ready
    T2: null, // window shown
    T3: null, // DOMContentLoaded
    T4: null, // load
  };

  // Step 1: spawn Electron with --remote-debugging-port
  console.log(`[CDP] Spawning ${electronPath} with --remote-debugging-port=${port}...`);
  const electronBin = electronPath;

  let electronProcess;
  try {
    electronProcess = spawn(electronBin, ['.', '--dev', `--remote-debugging-port=${port}`], {
      stdio: ['ignore', 'pipe', 'pipe'],
      detached: false,
      env: { ...process.env, ELECTRON_DISABLE_SANDBOX: '1' },
    });
  } catch (err) {
    throw new Error(`electron_not_found: "${electronBin}" not on PATH. Install Electron globally or pass --electron-path.`);
  }

  // Capture stderr lines until CDP is ready (app 'ready' event fires before CDP is up)
  const stderrLines = [];
  electronProcess.stderr?.on('data', (chunk) => {
    const line = String(chunk);
    stderrLines.push(line);
    if (line.includes('(electron)') || line.includes('app ready') || line.includes('App ready')) {
      if (!phases.T1) phases.T1 = performance.now();
    }
  });

  electronProcess.on('exit', (code) => {
    if (code !== null && code !== 0 && code !== null) {
      console.error(`[CDP] Electron exited early with code ${code}`);
      electronProcess.kill();
    }
  });

  // Step 2: wait for CDP to be available
  let versionInfo;
  try {
    versionInfo = await fetchCdpVersion(port, timeoutMs);
  } catch (err) {
    electronProcess.kill();
    throw new Error(`cdp_not_available: ${err.message}`);
  }

  // Step 3: connect to the first page target
  let target;
  try {
    target = await fetchCdpPageTarget(port, timeoutMs);
  } catch (err) {
    electronProcess.kill();
    throw new Error(`cdp_target_not_found: ${err.message}`);
  }

  const client = new CdpClient(target.webSocketDebuggerUrl);
  await client.connect(10_000);
  await client.send('Page.enable');
  await client.send('Runtime.enable');

  // Register lifecycle listeners
  const lifecycleEvents = [];
  client.on('Page.lifecycleEvent', (params) => {
    const now = performance.now();
    lifecycleEvents.push({ name: params.name, timestamp: params.timestamp, elapsed: now - t0 });

    if (params.name === 'init' && !phases.T1) phases.T1 = now;
    if (params.name === 'firstPaint' && !phases.T2) phases.T2 = now;
    if (params.name === 'DOMContentLoaded' && !phases.T3) phases.T3 = now;
    if (params.name === 'load' && !phases.T4) phases.T4 = now;
  });

  // Wait for T4 (load) or timeout
  const deadline = Date.now() + timeoutMs;
  while (!phases.T4 && Date.now() < deadline) {
    await delay(100);
    // Also check if process died
    if (electronProcess.exitCode !== null && !phases.T4) {
      // Process exited before load — that's a real measurement
      break;
    }
  }

  // Compute absolute timestamps relative to T0 (spawn)
  const t0_abs = t0;
  const result = {
    spawn: { ms: 0, label: 'T0 spawn' },
    T1: phases.T1 ? { ms: phases.T1 - t0_abs, label: 'T1 appReady' } : null,
    T2: phases.T2 ? { ms: phases.T2 - t0_abs, label: 'T2 firstPaint' } : null,
    T3: phases.T3 ? { ms: phases.T3 - t0_abs, label: 'T3 DOMLoaded' } : null,
    T4: phases.T4 ? { ms: phases.T4 - t0_abs, label: 'T4 load' } : null,
  };

  // Attach raw lifecycle events
  result._lifecycleEvents = lifecycleEvents;

  // Clean up
  client.close();
  electronProcess.kill();

  return result;
}

function printCdpResult(result, outputFormat) {
  if (outputFormat === 'json') {
    const serializable = { ...result };
    delete serializable._lifecycleEvents;
    serializable.lifecycleEvents = result._lifecycleEvents;
    console.log(JSON.stringify(serializable, null, 2));
    return;
  }

  if (outputFormat === 'csv') {
    const headers = ['phase', 'elapsed_ms', 'label'];
    const rows = [headers];
    for (const [key, val] of Object.entries(result)) {
      if (key === '_lifecycleEvents') {
        for (const ev of val) {
          rows.push([ev.name, ev.elapsed.toFixed(2), `lifecycle:${ev.name}`]);
        }
      } else if (val !== null) {
        rows.push([key, val.ms.toFixed(2), val.label]);
      }
    }
    console.log(rows.map((r) => r.join(',')).join('\n'));
    return;
  }

  // text format (default)
  console.log('=== dev-electron-profile CDP T0-T4 measurement ===');
  console.log(`platform: ${process.platform}-${process.arch}`);
  console.log(`node: ${process.version}`);
  console.log(`timestamp: ${new Date().toISOString()}`);
  console.log('');
  console.log('--- Startup phases ---');
  console.log(`T0 spawn:         0.0 ms (reference point)`);
  for (const key of ['T1', 'T2', 'T3', 'T4']) {
    const phase = result[key];
    if (phase) {
      console.log(`${phase.label}: ${phase.ms.toFixed(1)} ms`);
    } else {
      console.log(`${key} (${key}): not observed within timeout`);
    }
  }
  console.log('');
  console.log('--- Lifecycle events ---');
  for (const ev of result._lifecycleEvents) {
    console.log(`  ${ev.name.padEnd(20)} +${ev.elapsed.toFixed(1)} ms`);
  }
  console.log('');
  console.log('qualificationEligible: false (G0 dev Electron; packaged/Provider/GA out of scope)');
}

// ── Main ───────────────────────────────────────────────────────────────────────

function main(argv = process.argv.slice(2)) {
  const { warmup, threshold, cdpMode, cdpPort, cdpTimeout, outputFormat } = parseArgs(argv);

  if (cdpMode) {
    // CDP mode: spawn Electron and measure T0→T4 via Chrome DevTools Protocol
    measureCdpStartup({ port: cdpPort, timeoutMs: cdpTimeout, outputFormat })
      .then((result) => {
        printCdpResult(result, outputFormat);
      })
      .catch((err) => {
        console.error(`ERROR: ${err.message}`);
        process.exitCode = 1;
      });
    return;
  }

  console.log('=== dev-electron-profile baseline ===');
  console.log(`platform: ${process.platform}-${process.arch}`);
  console.log(`node: ${process.version}`);
  console.log(`timestamp: ${new Date().toISOString()}`);
  console.log('');

  // Static metrics
  const static_ = collectStaticMetrics();
  console.log('--- Static metrics ---');
  console.log(`main.js:            ${static_.main.lines} lines, ${static_.main.bytes} bytes`);
  console.log(`  ipcMain.handle:  ${static_.main.ipcHandlers}`);
  console.log(`  ipcMain.on:       ${static_.main.ipcOn}`);
  console.log(`preload.js:        ${static_.preload.lines} lines, ${static_.preload.bytes} bytes`);
  console.log(`  ipcRenderer.invoke:   ${static_.preload.ipcInvokes}`);
  console.log(`  ipcRenderer.on:       ${static_.preload.ipcOn}`);
  console.log(`  contextBridge.exposeInMainWorld: ${static_.preload.contextBridgeExposes}`);
  console.log(`total IPC channels: ${static_.totalIpcChannels}`);
  console.log('');

  // File-read timing
  console.log(`--- File read timing (${warmup} warmup + 3 measurement iterations) ---`);
  measureNodeCheckWarmup(warmup);
  const fileReadTimes = measureFileRead(3);
  const fileReadMedian = median(fileReadTimes);
  const fileReadMean = mean(fileReadTimes);
  console.log(`file-read times:  ${fileReadTimes.map((t) => `${t.toFixed(1)}ms`).join(', ')}`);
  console.log(`file-read median:  ${fileReadMedian.toFixed(1)}ms`);
  console.log(`file-read mean:    ${fileReadMean.toFixed(1)}ms`);
  console.log('');

  // node --check timing (primary proxy metric — may be empty in plain Node environments)
  console.log(`--- node --check src/main.js timing (${warmup} warmup + 3 measurement iterations) ---`);
  measureNodeCheckWarmup(warmup);
  const nodeCheckTimes = measureNodeCheck(3);
  if (nodeCheckTimes.length > 0) {
    const nodeCheckMedian = median(nodeCheckTimes);
    const nodeCheckMean = mean(nodeCheckTimes);
    console.log(`node --check times: ${nodeCheckTimes.map((t) => `${t.toFixed(1)}ms`).join(', ')}`);
    console.log(`node --check median: ${nodeCheckMedian.toFixed(1)}ms`);
    console.log(`node --check mean:   ${nodeCheckMean.toFixed(1)}ms`);
  } else {
    console.log('(skipped: main.js requires Electron-only modules — plain Node cannot parse syntax)');
  }
  console.log('');

  // Baseline summary
  console.log('--- Baseline summary ---');
  if (nodeCheckTimes.length > 0) {
    const nodeCheckMean = mean(nodeCheckTimes);
    console.log(`node --check mean (ms): ${nodeCheckMean.toFixed(1)}`);
    console.log(`threshold (ms):         ${threshold}`);
    console.log('');
    const exceeded = nodeCheckMean > threshold;
    if (exceeded) {
      console.log(`WARNING: node --check mean (${nodeCheckMean.toFixed(1)}ms) exceeds threshold (${threshold}ms)`);
      process.exitCode = 1;
    } else {
      console.log('OK: within threshold');
    }
  } else {
    console.log('(node --check skipped — Electron-only modules not available in plain Node)');
    console.log('Using file-read median as proxy baseline metric:');
    console.log(`file-read median (ms): ${fileReadMedian.toFixed(1)}`);
    console.log(`threshold (ms):        ${threshold}`);
    console.log('');
    const exceeded = fileReadMedian > threshold;
    if (exceeded) {
      console.log(`WARNING: file-read median (${fileReadMedian.toFixed(1)}ms) exceeds threshold (${threshold}ms)`);
      process.exitCode = 1;
    } else {
      console.log('OK: within threshold');
    }
  }

  // Document actual Electron launch timing requirements (not measured here)
  console.log('');
  console.log('--- Notes ---');
  console.log('This fixture measures module-load proxy metrics only.');
  console.log('Actual Electron launch timing requires a display and the following sequence:');
  console.log('  T0: spawn        electron . --disable-gpu --no-sandbox --remote-debugging-port=9222');
  console.log('  T1: app.whenReady    main process "app ready" event');
  console.log('  T2: did-finish-load  renderer HTML loaded (CDP Page.loadEventFired)');
  console.log('  T3: did-stop-loading all resources loaded (CDP Page.networkIdle)');
  console.log('  T4: first paint      renderer DOM first paint (CDP Runtime.evaluate performance.timing.loadEventEnd)');
  console.log('');
  console.log('To measure with CDP locally:');
  console.log('  1. Start Vite: cd frontend && npm run dev');
  console.log('  2. Start Electron with remote debugging: electron . --dev --remote-debugging-port=9222');
  console.log('  3. Connect Chrome DevTools to ws://localhost:9222 and measure lifecycle events');
  console.log('');
  console.log(`qualificationEligible: false (G0 dev Electron; packaged/Provider/GA out of scope)`);
}

main();

#!/usr/bin/env node

/**
 * Start Petri desktop in renderer-HMR mode.
 *
 * One command starts:
 * 1. Vite dev server for frontend hot updates.
 * 2. Electron main process loading the Vite URL instead of frontend/dist.
 */

const { spawn, spawnSync } = require('child_process');
const fs = require('fs');
const http = require('http');
const os = require('os');
const path = require('path');
// BLOCK-45 — 启动记录持久化 + boot 清理决策（纯逻辑，可单测）。
const {
  readLaunchRecord,
  writeLaunchRecord,
  clearLaunchRecord,
  resolveBootElectronAction,
} = require('./lib/dev-launch-state');

const isWin = process.platform === 'win32';
const npmCmd = isWin ? 'npm.cmd' : 'npm';
const npxCmd = isWin ? 'npx.cmd' : 'npx';
const rendererUrl = process.env.PETRI_RENDERER_DEV_URL || 'http://localhost:3000';
const projectRoot = process.cwd();
const electronApp = path.join(projectRoot, 'node_modules/electron/dist/Electron.app');
const electronBinary = path.join(electronApp, 'Contents/MacOS/Electron');
const electronUserDataDir =
  process.env.PETRI_ELECTRON_USER_DATA_DIR || path.join(projectRoot, '.petri-dev-user-data');
const electronLocalDataDir =
  process.env.PETRI_LOCAL_DATA_DIR || path.join(electronUserDataDir, 'data');
// petri-server 与迁移子进程同样按 PETRI_LOCAL_DATA_DIR 解析 ai-settings.json /
// credential-store / 数据根。只把它放进 electronEnv 会让后端各自回落到
// ~/Documents/Petri-Local（无配置 → 模型列表重置为 deepseek 默认、凭据读空），
// 必须在 fork 任何子进程前导出，与 Electron 主进程（env-coordinator）同根。
process.env.PETRI_LOCAL_DATA_DIR = electronLocalDataDir;
const electronLogPath = process.env.PETRI_ELECTRON_LOG_PATH || path.join(os.tmpdir(), 'petri-electron-main.log');
const electronErrorLogPath = `${electronLogPath}.error`;

const children = new Set();
let shuttingDown = false;
let launchedElectronViaOpen = false;
// BLOCK-35：launch-token 定向。shutdown 只杀本 wrapper 启动的 Electron 实例
// （token 随 --args 注入主进程 argv；Helper 子进程 argv 不含 token，天然只中主进程），
// 不再按二进制路径全杀工作区 Electron —— 否则会误杀人工 `electron . --dev`
// 或另一 wrapper 启动的并存实例（BLOCK-34 P4 实机两次静默退出的根因）。
const launchToken = `petridev-${process.pid}-${Date.now().toString(36)}`;
// BLOCK-45：boot 清理逃生口 —— 仅显式传入时恢复旧「全杀工作区 Electron」语义，
// 覆盖 pre-BLOCK-45 无启动记录残留实例的极端场景。
const forceCleanElectron =
  process.argv.includes('--force-clean-electron') || process.env.PETRI_FORCE_CLEAN_ELECTRON === '1';

function spawnChild(command, args, options = {}) {
  const { shutdownOnExit = 'error', ...spawnOptions } = options;
  const child = spawn(command, args, {
    stdio: 'inherit',
    // npm.cmd / npx.cmd need cmd.exe on Windows. POSIX launches directly so
    // paths and optional Electron args are never re-parsed by a shell.
    shell: isWin,
    detached: !isWin,
    ...spawnOptions,
  });
  children.add(child);
  child.on('exit', (code, signal) => {
    children.delete(child);
    if (shuttingDown) return;
    if (shutdownOnExit === 'always') {
      shutdown(code || 0);
    } else if (signal !== 'SIGTERM' && code !== 0) {
      shutdown(code || 1);
    }
  });
  return child;
}

function terminateChild(child) {
  try {
    // npm and npx launch grandchildren (Vite/Electron). Killing the POSIX
    // process group prevents those grandchildren from surviving the launcher.
    if (!isWin && child.pid) {
      process.kill(-child.pid, 'SIGTERM');
    } else {
      child.kill('SIGTERM');
    }
  } catch {
    // The child may already have exited.
  }
}

// 工作区 Electron 主进程的两种启动变体（BLOCK-35 P2 实机发现）：
// 1. wrapper 经 `open -a Electron.app` 启动 → argv 为
//    `<root>/node_modules/electron/dist/Electron.app/Contents/MacOS/Electron`
// 2. `npx electron .` / `./node_modules/.bin/electron`（cli.js）启动 → argv 为
//    `<root>/node_modules/electron/dist/electron`（小写直连二进制）。
// 旧模式只匹配 .app 路径，boot 清理会漏掉变体 2。Helper 子进程位于
// `.../Frameworks/Electron Helper ...`，不匹配任一分支，天然只中主进程。
function getWorkspaceElectronPids() {
  if (process.platform !== 'darwin' || !fs.existsSync(electronBinary)) return [];
  const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const pattern = `${esc(projectRoot)}/node_modules/electron/dist/(Electron[.]app/Contents/MacOS/Electron|electron)( |$)`;
  const result = spawnSync('pgrep', ['-f', pattern], { encoding: 'utf8' });
  if (result.status !== 0) return [];
  return result.stdout
    .trim()
    .split(/\s+/)
    .map(Number)
    .filter((pid) => Number.isInteger(pid) && pid > 0);
}

// token 定向 pgrep（BLOCK-45 泛化）：匹配 argv 含 `petri-dev-launch-token=<token>`
// 的进程。pattern 不带前导 `--`（避免被 pgrep 当选项解析）；pgrep 会把仍存活的
// `open` 自身也命中（其 argv 含 token），排除掉。
function getElectronPidsByToken(token) {
  if (process.platform !== 'darwin' || !token) return [];
  const result = spawnSync('pgrep', ['-f', `petri-dev-launch-token=${token}`], { encoding: 'utf8' });
  if (result.status !== 0) return [];
  const childPids = new Set([...children].map((child) => child.pid));
  return result.stdout
    .trim()
    .split(/\s+/)
    .map(Number)
    .filter((pid) => Number.isInteger(pid) && pid > 0 && !childPids.has(pid));
}

// 本 wrapper 经 `open --args ... --petri-dev-launch-token=<token>` 启动的实例。
function getLaunchedElectronPids() {
  return getElectronPidsByToken(launchToken);
}

function isPidAlive(pid) {
  try {
    process.kill(pid, 0);
    return true;
  } catch {
    return false;
  }
}

// BLOCK-45：SIGTERM → 等待 → SIGKILL 的优雅击杀，boot 清理与 shutdown 共用。
async function killPidsGracefully(pids, label) {
  if (pids.length === 0) return;
  signalPids(pids, 'SIGTERM');
  const remaining = await waitForPidsToExit(pids, 5000);
  if (remaining.length > 0) {
    signalPids(remaining, 'SIGKILL');
    const survivors = await waitForPidsToExit(remaining, 2000);
    if (survivors.length > 0) {
      throw new Error(`Unable to stop ${label}: ${survivors.join(', ')}`);
    }
  }
}

// BLOCK-45 逃生口：显式 force-clean 时恢复旧「全杀工作区 Electron 主进程」语义。
async function stopWorkspaceElectron() {
  const pids = getWorkspaceElectronPids();
  if (pids.length === 0) return;
  await killPidsGracefully(pids, 'workspace Electron processes');
}

// BLOCK-45：boot 清理 Electron 段 —— 读上一启动记录做定向决策，
// 不再按二进制路径全杀（并存实例误杀根因，BLOCK-43 P3 实测踩中）。
// fail-closed 决策向上抛出（中止 boot）；清理失败仅告警不阻塞端口接管。
async function stopPreviousLaunchElectron() {
  const record = readLaunchRecord(electronUserDataDir);
  const tokenPids = record ? getElectronPidsByToken(record.token) : [];
  const wrapperAlive = record
    ? record.wrapperPid !== process.pid && isPidAlive(record.wrapperPid)
    : false;
  const decision = resolveBootElectronAction({
    record,
    wrapperAlive,
    hasTokenPids: tokenPids.length > 0,
    forceClean: false,
  });
  if (decision.action === 'fail') throw new Error(decision.message);
  if (decision.action === 'cleanup') {
    console.log(`[dev] cleaning up previous launch Electron (token-scoped, pids: ${tokenPids.join(', ')})`);
    await killPidsGracefully(tokenPids, 'previous launch Electron');
  }
}

function signalPids(pids, signal) {
  for (const pid of pids) {
    try {
      process.kill(pid, signal);
    } catch {
      // The process may already have exited.
    }
  }
}

async function waitForPidsToExit(pids, timeoutMs) {
  const startedAt = Date.now();
  while (Date.now() - startedAt <= timeoutMs) {
    const remaining = pids.filter((pid) => {
      try {
        process.kill(pid, 0);
        return true;
      } catch {
        return false;
      }
    });
    if (remaining.length === 0) return [];
    await new Promise((resolve) => setTimeout(resolve, 100));
  }
  return pids.filter((pid) => {
    try {
      process.kill(pid, 0);
      return true;
    } catch {
      return false;
    }
  });
}

async function stopWorkspaceElectron() {
  const pids = getWorkspaceElectronPids();
  if (pids.length === 0) return;
  signalPids(pids, 'SIGTERM');
  const remaining = await waitForPidsToExit(pids, 5000);
  if (remaining.length > 0) {
    signalPids(remaining, 'SIGKILL');
    const survivors = await waitForPidsToExit(remaining, 2000);
    if (survivors.length > 0) {
      throw new Error(`Unable to stop workspace Electron processes: ${survivors.join(', ')}`);
    }
  }
}

// BLOCK-35：shutdown 路径专用 —— 只停本 wrapper 启动的实例，并存实例不受影响。
async function stopLaunchedElectron() {
  const pids = getLaunchedElectronPids();
  await killPidsGracefully(pids, 'launched Electron');
}

async function waitForWorkspaceElectron(timeoutMs = 15000) {
  const startedAt = Date.now();
  while (Date.now() - startedAt <= timeoutMs) {
    // token 就绪判定：只认本 wrapper 启动的实例，陈旧实例不构成假阳性
    if (getLaunchedElectronPids().length > 0) return;
    await new Promise((resolve) => setTimeout(resolve, 250));
  }
  throw new Error(
    `Electron did not start within ${timeoutMs}ms. See ${electronLogPath} and ${electronErrorLogPath}`,
  );
}

async function shutdown(code = 0) {
  if (shuttingDown) return;
  shuttingDown = true;
  for (const child of children) {
    terminateChild(child);
  }
  // On macOS the Electron instance is launched via `open -a` (GUI session) and
  // is not part of our process group, so tear it down explicitly. BLOCK-35:
  // only the instance this wrapper launched (token-scoped) — coexisting
  // Electron instances from this workspace must survive our shutdown.
  if (launchedElectronViaOpen && process.platform === 'darwin') {
    try {
      await stopLaunchedElectron();
    } catch (error) {
      console.error(`[dev] ${error.message}`);
      code = code || 1;
    }
    // BLOCK-45：清掉自己的启动记录（仅当记录仍指向本 wrapper —— 若已被
    // 后继 wrapper 覆盖则不动，避免误删他者记录）。
    try {
      const record = readLaunchRecord(electronUserDataDir);
      if (record && record.token === launchToken) clearLaunchRecord(electronUserDataDir);
    } catch {
      // best-effort；残留记录会在下次 boot 按「wrapper 已死」路径正常清理
    }
  }
  process.exit(code);
}

function urlIsAvailable(url, timeoutMs = 800) {
  return new Promise((resolve) => {
    const req = http.get(url, (res) => {
      res.resume();
      resolve(true);
    });
    req.on('error', () => resolve(false));
    req.setTimeout(timeoutMs, () => {
      req.destroy();
      resolve(false);
    });
  });
}

function waitForUrl(url, timeoutMs = 30000) {
  const startedAt = Date.now();
  return new Promise((resolve, reject) => {
    const tick = () => {
      const req = http.get(url, (res) => {
        res.resume();
        resolve();
      });
      req.on('error', () => {
        if (Date.now() - startedAt > timeoutMs) {
          reject(new Error(`Timed out waiting for ${url}`));
          return;
        }
        setTimeout(tick, 250);
      });
      req.setTimeout(1200, () => {
        req.destroy();
      });
    };
    tick();
  });
}

process.on('SIGINT', () => void shutdown(0));
process.on('SIGTERM', () => void shutdown(0));

async function getPortOwnerPids(port) {
  if (process.platform === 'win32') {
    // netstat -ano | findstr :PORT then FOR /F tokens=5 to extract PID — kept
    // out of the dev loop's hot path because devs almost never run on Windows.
    return [];
  }
  // `lsof -ti :PORT` returns PIDs listening on PORT, one per line. Exit code 1
  // means "no matches" which is the steady state we want, not an error.
  const result = spawnSync('lsof', ['-ti', `:${port}`], { encoding: 'utf8' });
  if (result.status !== 0) return [];
  return result.stdout
    .trim()
    .split(/\s+/)
    .map(Number)
    .filter((pid) => Number.isInteger(pid) && pid > 0);
}

async function stopPidsByPort(port, label) {
  const pids = await getPortOwnerPids(port);
  if (pids.length === 0) return 0;
  console.log(`[dev] clearing ${pids.length} stale ${label} process(es) holding :${port} (pids: ${pids.join(', ')})`);
  signalPids(pids, 'SIGTERM');
  const remaining = await waitForPidsToExit(pids, 3000);
  if (remaining.length > 0) {
    signalPids(remaining, 'SIGKILL');
    const survivors = await waitForPidsToExit(remaining, 2000);
    if (survivors.length > 0) {
      console.warn(`[dev] ${label} pid(s) still alive after SIGKILL: ${survivors.join(', ')}`);
    }
  }
  // Final settle — give the kernel a beat to release the listening socket.
  await new Promise((resolve) => setTimeout(resolve, 200));
  return pids.length;
}

async function stopWorkspaceDevProcesses() {
  // macOS-launched Electron is detached from our process group and survives
  // shell exits; kill it before touching the backend ports so it doesn't
  // immediately re-bind them via its child process manager.
  //
  // BLOCK-45：Electron 段不再按二进制路径全杀（并存实例误杀根因）——
  //   - 显式 `--force-clean-electron` / PETRI_FORCE_CLEAN_ELECTRON=1 →
  //     恢复旧全杀语义（逃生口，覆盖 pre-BLOCK-45 无记录残留）；
  //   - 默认走 token 定向：上一 wrapper 仍存活且其 token 命中 → fail-closed
  //     抛错中止 boot（提示先停旧栈）；wrapper 已死 → token 定向清理残留；
  //     无记录 → 跳过 Electron 段（仅端口接管）。
  //   fail-closed 决策必须向上传播中止 boot（不得吞掉）；清理类失败仅告警。
  if (process.platform === 'darwin') {
    try {
      if (forceCleanElectron) {
        await stopWorkspaceElectron();
      } else {
        await stopPreviousLaunchElectron();
      }
    } catch (error) {
      if (forceCleanElectron) {
        console.warn(`[dev] ${error.message}`);
      } else {
        throw error;
      }
    }
  }
  // Always sweep vite / petri-server regardless of OS — these are the
    // ports the dev loop actually waits on. The order matches the boot
    // sequence so an older stack drops in reverse.
    // (BLOCK-30 P1: 独立 Python 后端 :3004 已摘除。)
  const rendererPort = Number(new URL(rendererUrl).port) || 3000;
  await stopPidsByPort(rendererPort, 'vite renderer');
  await stopPidsByPort(3001, 'petri-server');
}

async function main() {
  // Auto-clear any Petri dev process from a previous session that still owns
  // the dev ports, then verify the renderer port is actually free. Doing both
  // means a hot-reload dev loop can re-run `npm run dev` without first having
  // to manually `lsof -ti :3000 | xargs kill`.
  await stopWorkspaceDevProcesses();
  if (await urlIsAvailable(rendererUrl)) {
    // A foreign server (not Petri) is holding the port — refuse rather than
    // kill something we don't own.
    throw new Error(
      `${rendererUrl} is already serving a page by a non-Petri process. ` +
        `Stop it manually before running npm run dev again.`
    );
  }

  spawnChild(npmCmd, ['--prefix', 'frontend', 'run', 'dev']);
  await waitForUrl(rendererUrl);

  // petri-server (and later Electron) both need the same DB. env-coordinator
  // pins the main-process DB to <PETRI_LOCAL_DATA_DIR>/petri.db（上面已导出为
  // electronLocalDataDir）。镜像同一路径，petri-server 与迁移子进程打开同一个
  // 已迁移库，而不是各自回落（core/petri-server/petri.db 或 macOS 时代的
  // ~/Library/Application Support/petri-local/petri.db —— 后者在本机会把
  // 后端指到另一个空库，与主进程分裂）。
  process.env.PETRI_DB_PATH = path.join(electronLocalDataDir, 'petri.db');

  // Run pending DB migrations against the shared DB before petri-server starts.
  // Uses the same PETRI_BETTER_SQLITE3_ROOT root as main.js:367 so the
  // better-sqlite3 native addon ABI matches.
  const migrationEnv = { ...process.env, ELECTRON_RUN_AS_NODE: '1', PETRI_BETTER_SQLITE3_ROOT: path.join(projectRoot, 'core/petri-server') };
  const migrationResult = spawnSync(
    process.execPath,
    [path.join(projectRoot, 'src', 'migration-runner.js'), process.env.PETRI_DB_PATH, path.join(projectRoot, 'src', 'migrations')],
    { cwd: projectRoot, encoding: 'utf8', env: migrationEnv },
  );
  if (migrationResult.error) throw migrationResult.error;
  if (migrationResult.status !== 0) {
    throw new Error((migrationResult.stderr || migrationResult.stdout || 'migration child failed').trim());
  }
  const migrationOutput = String(migrationResult.stdout || '').trim();
  if (migrationOutput) console.log('[dev-electron] ' + migrationOutput.replace(/\n/g, '\n[dev-electron] '));

  // Start petri-server on :3001 so /api/ai/chat (and other /api/* routes used by
  // the renderer) are reachable from the dev shell. Without this the copilot
  // context-budget ring (UI-190) and other live SSE features stay empty.
  spawnChild(npmCmd, ['--prefix', 'core/petri-server', 'start'], { env: { ...process.env } });
  await waitForUrl('http://127.0.0.1:3001/api/health');

  // Optional extra Electron CLI args for local debugging, e.g.
  //   PETRI_DEV_ELECTRON_ARGS="--remote-debugging-port=9222" npm run dev
  // Empty by default so normal dev runs are unchanged.
  const extraElectronArgs = (process.env.PETRI_DEV_ELECTRON_ARGS || '')
    .split(' ')
    .map((arg) => arg.trim())
    .filter(Boolean);

  if (process.platform === 'darwin') {
    // macOS: launch Electron via `open -a` so it inherits the GUI login session
    // and receives keyboard focus. A plain spawn from a background/agent shell
    // starts Electron without a key window (AXFocused=false) → the input box
    // can be clicked but cannot receive keystrokes. `open` brokers the launch
    // through LaunchServices, which attaches a proper window-server connection.
    // `open -a` otherwise focuses an existing instance. Only stop the Electron
    // binary from this workspace; never match generic Electron Helper processes.
    fs.mkdirSync(electronUserDataDir, { recursive: true });
    fs.mkdirSync(electronLocalDataDir, { recursive: true });
    // BLOCK-45：持久化本次启动记录 —— 下次 boot 的清理只认这条记录指向的
    // 实例（token 定向），并存实例不再被无差别击杀。
    writeLaunchRecord(electronUserDataDir, {
      token: launchToken,
      wrapperPid: process.pid,
      startedAt: new Date().toISOString(),
    });
    fs.writeFileSync(electronLogPath, '');
    fs.writeFileSync(electronErrorLogPath, '');
    // `open` returns immediately; do NOT treat its exit as a shutdown signal.
    // Electron is tracked separately so SIGINT/Cmd+Q can still tear it down.
    launchedElectronViaOpen = true;
    const openArgs = [
      '-n',
      '-a',
      electronApp,
      '-o',
      electronLogPath,
      '--stderr',
      electronErrorLogPath,
      '--env',
      'ELECTRON_IS_DEV=1',
      '--env',
      'NODE_ENV=development',
      '--env',
      `PETRI_RENDERER_DEV_URL=${rendererUrl}`,
      '--env',
      `PETRI_ELECTRON_USER_DATA_DIR=${electronUserDataDir}`,
      '--env',
      `PETRI_LOCAL_DATA_DIR=${electronLocalDataDir}`,
    ];
    if (process.env.ELECTRON_DISABLE_SANDBOX) {
      openArgs.push('--env', `ELECTRON_DISABLE_SANDBOX=${process.env.ELECTRON_DISABLE_SANDBOX}`);
    }
    openArgs.push('--args', projectRoot, '--dev', `--petri-dev-launch-token=${launchToken}`, ...extraElectronArgs);
    spawnChild('/usr/bin/open', openArgs);
    await waitForWorkspaceElectron();
    console.log(`[dev] Electron started via LaunchServices; main log: ${electronLogPath}`);
    console.log(`[dev] Electron stderr: ${electronErrorLogPath}`);
  } else {
    // Ensure dev data directories exist (macOS does this above; Windows must match).
    fs.mkdirSync(electronUserDataDir, { recursive: true });
    fs.mkdirSync(electronLocalDataDir, { recursive: true });
      // Strip ELECTRON_RUN_AS_NODE before spawning the GUI. That var is set
      // only for the migration-runner child (run as plain Node); if it leaks
      // into the Electron main process, Electron degenerates into a plain Node
      // and require('electron').app becomes undefined — crashing main.js at
      // app.requestSingleInstanceLock(). (2026-09-02 launch fix.)
      const electronEnv = {
        ...process.env,
        ELECTRON_IS_DEV: '1',
        NODE_ENV: 'development',
        PETRI_RENDERER_DEV_URL: rendererUrl,
        PETRI_ELECTRON_USER_DATA_DIR: electronUserDataDir,
        PETRI_LOCAL_DATA_DIR: electronLocalDataDir,
      };
      delete electronEnv.ELECTRON_RUN_AS_NODE;
      spawnChild(npxCmd, ['electron', '.', '--dev', ...extraElectronArgs], {
        shutdownOnExit: 'always',
        env: electronEnv,
      });
  }
}

main().catch((error) => {
  console.error('[dev] failed:', error.message);
  shutdown(1);
});

#!/usr/bin/env node
/**
 * scripts/docs-governance.mjs — `docs/` 注册、覆盖、冲突门禁主入口
 *
 * 子命令：
 *   --status     默认；输出注册数量、状态、类型、未注册文件与契约问题
 *   --check      注册缺失 / 路径失效 / 入口断链 / canonical 冲突时非 0 退出
 *   --reconcile  只读报告：孤立文档、归档候选、稳定保留项、冲突；不写文件
 *   --write-report  与 --reconcile 一起把报告写到 acceptance/...
 *
 * 退出码契约（GATES-1 文档化，2026-08-16）：
 *   0   PASS — 校验通过 / 状态报告正常输出
 *   1   FAIL — 校验发现问题（注册缺失、路径失效、入口断链、canonical 冲突等）
 *   2   分类冲突 — CLI 调用冲突（同时传入多个互斥模式）或未捕获的运行期错误
 *       注意：2 不是 fail-closed；仅提示调用方修正参数 / 修复工具自身 bug，
 *       **不**代表 docs/ 治理栈在你的工作包里有"未通过的契约"。
 *
 * `--report` JSON 输出模式（GATES-2 文档化，2026-08-16）：
 *   与 `--status` / `--check` / `--reconcile` 互斥的并行模式；通过
 *   `--report <path>` 触发，输出机器可读 JSON，由 `docs/schemas/docs-governance-report.schema.json`
 *   强校验，写盘失败 / schema 校验失败 → exit 2（分类冲突）。
 *   退出码语义与现有契约一致：report 模式下的 exit 0/1/2 仍走 0=PASS / 1=FAIL / 2=分类冲突。
 *   报告 `summary.status` 反映业务分类（PASS / FAIL / CLASSIFICATION_CONFLICT），
 *   `exitCode` 反映 `process.exitCode`。
 *
 * 同步文档：`docs/document-governance.md` §4.5"门禁退出码契约" + GATES-2 §3.2"JSON 输出契约"。
 * 该契约为本工作包 DOC-GOVERNANCE-GATES / GATES-1 阶段固化本，不在本阶段内
 * 改动 `process.exit()` 行为；如未来升级退出码语义须同步 §4.5 并联动
 * `package.json` 脚本。
 */

import fs from 'node:fs/promises';
import path from 'node:path';
import process from 'node:process';
import { fileURLToPath } from 'node:url';
import { GATE_REPORT_SCHEMA_VERSION, validateReport } from './lib/gate-report-schema.mjs';

const SCRIPT_PATH = fileURLToPath(import.meta.url);
const DEFAULT_ROOT = path.resolve(path.dirname(SCRIPT_PATH), '..');

export const DOCUMENT_KINDS = Object.freeze([
  'governance',
  'vision',
  'roadmap',
  'living-plan',
  'work-package',
  'handoff',
  'audit',
  'reference',
  'release',
]);

export const DOCUMENT_STATUSES = Object.freeze([
  'active',
  'planned',
  'completed',
  'reference',
  'superseded',
  'archived',
]);

export const ARCHIVE_POLICIES = Object.freeze([
  'never_archive',
  'retain_stable_path',
  'archive_after_completion',
  'archive_when_superseded',
  'manual_review',
]);

function toPosix(value) {
  return value.split(path.sep).join('/');
}

function normalizeRepoPath(value) {
  if (typeof value !== 'string' || value.trim() === '') return null;
  const candidate = value.trim().replaceAll('\\', '/');
  if (path.posix.isAbsolute(candidate)) return null;
  if (candidate.split('/').includes('..')) return null;
  const normalized = path.posix.normalize(candidate);
  if (normalized === '.' || normalized === '..' || normalized.startsWith('../')) return null;
  return normalized;
}

function isExcluded(repoPath, excludedPrefixes) {
  return excludedPrefixes.some((prefix) => {
    const normalized = normalizeRepoPath(prefix);
    if (!normalized) return false;
    const base = normalized.replace(/\/$/, '');
    return repoPath === base || repoPath.startsWith(`${base}/`);
  });
}

async function pathExists(absolutePath) {
  try {
    await fs.access(absolutePath);
    return true;
  } catch {
    return false;
  }
}

async function walkMarkdown(rootDir, absoluteDir, excludedPrefixes, results) {
  const relativeDir = toPosix(path.relative(rootDir, absoluteDir));
  if (relativeDir && isExcluded(relativeDir, excludedPrefixes)) return;

  let entries;
  try {
    entries = await fs.readdir(absoluteDir, { withFileTypes: true });
  } catch (error) {
    if (error?.code === 'ENOENT') return;
    throw error;
  }

  for (const entry of entries) {
    const absolutePath = path.join(absoluteDir, entry.name);
    const relativePath = toPosix(path.relative(rootDir, absolutePath));
    if (isExcluded(relativePath, excludedPrefixes)) continue;
    if (entry.isDirectory()) {
      await walkMarkdown(rootDir, absolutePath, excludedPrefixes, results);
    } else if (entry.isFile() && entry.name.endsWith('.md')) {
      results.push(relativePath);
    }
  }
}

export async function collectManagedMarkdown(rootDir = DEFAULT_ROOT, coverage = {}) {
  const managedRoots = Array.isArray(coverage.managedRoots) && coverage.managedRoots.length > 0
    ? coverage.managedRoots
    : ['docs'];
  const excludedPrefixes = Array.isArray(coverage.excludedPrefixes)
    ? coverage.excludedPrefixes
    : ['docs/archive/'];
  const results = [];

  for (const root of managedRoots) {
    const repoPath = normalizeRepoPath(root);
    if (!repoPath) continue;
    await walkMarkdown(rootDir, path.join(rootDir, repoPath), excludedPrefixes, results);
  }

  return [...new Set(results)].sort();
}

export async function loadDocumentRegistry(rootDir = DEFAULT_ROOT) {
  const registryPath = path.join(rootDir, 'docs', 'DOC-REGISTRY.json');
  const source = await fs.readFile(registryPath, 'utf8');
  return JSON.parse(source);
}

export function extractLocalMarkdownLinks(markdown, sourcePath) {
  const links = [];
  const pattern = /\[[^\]]*\]\(([^)]+)\)/g;
  let match;

  while ((match = pattern.exec(markdown)) !== null) {
    let target = match[1].trim();
    if (target.startsWith('<') && target.endsWith('>')) target = target.slice(1, -1);
    target = target.split(/\s+["']/)[0];
    target = target.split('#')[0].split('?')[0];
    if (!target || target.startsWith('#') || /^[a-z][a-z0-9+.-]*:/i.test(target)) continue;
    if (target.startsWith('/')) continue;
    const resolved = normalizeRepoPath(path.posix.join(path.posix.dirname(sourcePath), target));
    if (resolved) links.push(resolved);
  }

  return links;
}

function issue(code, message, documentId = null, documentPath = null) {
  return { code, message, documentId, path: documentPath };
}

export async function validateDocumentRegistry(registry, options = {}) {
  const rootDir = options.rootDir ?? DEFAULT_ROOT;
  const issues = [];

  if (!registry || typeof registry !== 'object' || Array.isArray(registry)) {
    return [issue('REGISTRY_INVALID', 'Registry must be a JSON object.')];
  }
  if (registry.schemaVersion !== 1) {
    issues.push(issue('SCHEMA_VERSION_INVALID', 'schemaVersion must equal 1.'));
  }
  if (!registry.coverage || typeof registry.coverage !== 'object') {
    issues.push(issue('COVERAGE_INVALID', 'coverage must be an object.'));
  }
  if (!Array.isArray(registry.documents)) {
    issues.push(issue('DOCUMENTS_INVALID', 'documents must be an array.'));
    return issues;
  }

  const idOwners = new Map();
  const pathOwners = new Map();
  const truthOwners = new Map();
  const normalizedDocuments = [];

  for (const document of registry.documents) {
    if (!document || typeof document !== 'object' || Array.isArray(document)) {
      issues.push(issue('DOCUMENT_INVALID', 'Each document entry must be an object.'));
      continue;
    }

    const id = typeof document.id === 'string' ? document.id.trim() : '';
    const repoPath = normalizeRepoPath(document.path);
    if (!/^[A-Z0-9][A-Z0-9._-]*$/.test(id)) {
      issues.push(issue('ID_INVALID', 'id must use uppercase letters, numbers, dot, underscore, or hyphen.', id || null, repoPath));
    }
    if (!repoPath || !repoPath.startsWith('docs/') || !repoPath.endsWith('.md')) {
      issues.push(issue('PATH_INVALID', 'path must be a safe repository-relative Markdown path under docs/.', id || null, document.path ?? null));
    }
    if (!DOCUMENT_KINDS.includes(document.kind)) {
      issues.push(issue('KIND_INVALID', `kind must be one of: ${DOCUMENT_KINDS.join(', ')}.`, id || null, repoPath));
    }
    if (!DOCUMENT_STATUSES.includes(document.status)) {
      issues.push(issue('STATUS_INVALID', `status must be one of: ${DOCUMENT_STATUSES.join(', ')}.`, id || null, repoPath));
    }
    if (typeof document.canonical !== 'boolean') {
      issues.push(issue('CANONICAL_INVALID', 'canonical must be a boolean.', id || null, repoPath));
    }
    if (!ARCHIVE_POLICIES.includes(document.archivePolicy)) {
      issues.push(issue('ARCHIVE_POLICY_INVALID', `archivePolicy must be one of: ${ARCHIVE_POLICIES.join(', ')}.`, id || null, repoPath));
    }

    if (id) {
      if (idOwners.has(id)) {
        issues.push(issue('DUPLICATE_ID', `id is already used by ${idOwners.get(id)}.`, id, repoPath));
      } else {
        idOwners.set(id, repoPath ?? '<invalid path>');
      }
    }
    if (repoPath) {
      if (pathOwners.has(repoPath)) {
        issues.push(issue('DUPLICATE_PATH', `path is already registered as ${pathOwners.get(repoPath)}.`, id || null, repoPath));
      } else {
        pathOwners.set(repoPath, id || '<invalid id>');
      }
      if (!(await pathExists(path.join(rootDir, repoPath)))) {
        issues.push(issue('DOCUMENT_MISSING', 'Registered document does not exist.', id || null, repoPath));
      }
    }

    if (document.status === 'archived' && repoPath && !repoPath.startsWith('docs/archive/')) {
      issues.push(issue('ARCHIVED_PATH_INVALID', 'archived documents must live under docs/archive/.', id || null, repoPath));
    }
    if (repoPath?.startsWith('docs/archive/') && document.status !== 'archived') {
      issues.push(issue('ARCHIVE_STATUS_INVALID', 'Documents under docs/archive/ must use archived status.', id || null, repoPath));
    }

    if (document.canonical === true) {
      const truthDomain = typeof document.truthDomain === 'string' ? document.truthDomain.trim() : '';
      const entrypoint = normalizeRepoPath(document.entrypoint);
      if (!truthDomain) {
        issues.push(issue('TRUTH_DOMAIN_REQUIRED', 'canonical documents require truthDomain.', id || null, repoPath));
      } else if (!['archived', 'superseded'].includes(document.status)) {
        if (truthOwners.has(truthDomain)) {
          issues.push(issue('DUPLICATE_TRUTH_DOMAIN', `truthDomain is already owned by ${truthOwners.get(truthDomain)}.`, id || null, repoPath));
        } else {
          truthOwners.set(truthDomain, id || '<invalid id>');
        }
      }
      if (!entrypoint) {
        issues.push(issue('CANONICAL_ENTRYPOINT_REQUIRED', 'canonical documents require a safe entrypoint path.', id || null, repoPath));
      } else if (!(await pathExists(path.join(rootDir, entrypoint)))) {
        issues.push(issue('ENTRYPOINT_MISSING', `entrypoint does not exist: ${entrypoint}.`, id || null, repoPath));
      } else if (repoPath) {
        const entrypointSource = await fs.readFile(path.join(rootDir, entrypoint), 'utf8');
        const links = extractLocalMarkdownLinks(entrypointSource, entrypoint);
        if (!links.includes(repoPath)) {
          issues.push(issue('ENTRYPOINT_LINK_MISSING', `${entrypoint} does not link to the canonical document.`, id || null, repoPath));
        }
      }
    }

    if (document.supersedes !== undefined && !Array.isArray(document.supersedes)) {
      issues.push(issue('SUPERSEDES_INVALID', 'supersedes must be an array when present.', id || null, repoPath));
    }
    if (document.acceptanceRefs !== undefined && !Array.isArray(document.acceptanceRefs)) {
      issues.push(issue('ACCEPTANCE_REFS_INVALID', 'acceptanceRefs must be an array when present.', id || null, repoPath));
    }

    // GATES-3: truthDomain must not be retained on archived / superseded entries.
    // P2 closeout already removed truthDomain from IDE-TRANSFORMATION et al; this rule
    // makes the invariant explicit so future regressions fail docs:check loudly.
    if (
      document.truthDomain !== undefined
      && document.truthDomain !== null
      && (typeof document.truthDomain !== 'string' || document.truthDomain.trim() !== '')
      && ['archived', 'superseded'].includes(document.status)
    ) {
      issues.push(issue(
        'TRUTH_DOMAIN_RETAINED_ON_RETIRED',
        `truthDomain must be removed when status is ${document.status}; use tags for historical grouping instead.`,
        id || null,
        repoPath,
      ));
    }

    normalizedDocuments.push({ ...document, id, path: repoPath });
  }

  for (const document of normalizedDocuments) {
    if (!Array.isArray(document.supersedes)) continue;
    for (const supersededId of document.supersedes) {
      if (!idOwners.has(supersededId)) {
        issues.push(issue('SUPERSEDED_ID_MISSING', `supersedes references unknown id ${supersededId}.`, document.id || null, document.path));
      }
    }
  }

  // GATES-3: supersededBy is now an optional array of registered document ids.
  // Validated in a second pass so order of appearance in the registry does not
  // matter; mirrors the existing supersedes post-pass style.
  const livingStatuses = new Set(['active', 'planned', 'completed', 'reference']);
  for (const document of normalizedDocuments) {
    if (document.supersededBy === undefined || document.supersededBy === null) continue;
    if (!Array.isArray(document.supersededBy)) {
      issues.push(issue(
        'SUPERSEDED_BY_INVALID',
        'supersededBy must be an array of registered document ids when present.',
        document.id || null,
        document.path,
      ));
      continue;
    }
    if (document.supersededBy.length === 0) {
      issues.push(issue(
        'SUPERSEDED_BY_EMPTY',
        'supersededBy must contain at least one registered document id when present.',
        document.id || null,
        document.path,
      ));
      continue;
    }
    let hasLivingTarget = false;
    document.supersededBy.forEach((targetId, index) => {
      if (typeof targetId !== 'string' || targetId.trim() === '') {
        issues.push(issue(
          'SUPERSEDED_BY_ELEMENT_INVALID',
          `supersededBy[${index}] must be a non-empty registered document id.`,
          document.id || null,
          document.path,
        ));
        return;
      }
      if (!idOwners.has(targetId)) {
        issues.push(issue(
          'SUPERSEDED_BY_UNKNOWN_ID',
          `supersededBy[${index}] references unknown id ${targetId}.`,
          document.id || null,
          document.path,
        ));
        return;
      }
      const targetDoc = registry.documents.find((entry) => entry && entry.id === targetId);
      if (targetDoc && livingStatuses.has(targetDoc.status)) {
        hasLivingTarget = true;
      }
    });
    if (hasLivingTarget === false) {
      issues.push(issue(
        'SUPERSEDED_BY_NO_LIVING_TARGET',
        'supersededBy must reference at least one living document (active / planned / completed / reference).',
        document.id || null,
        document.path,
      ));
    }
  }

  const coverage = registry.coverage ?? {};
  const managedMarkdown = await collectManagedMarkdown(rootDir, coverage);
  const registeredPaths = new Set(normalizedDocuments.map((document) => document.path).filter(Boolean));
  if (coverage.requireRegistration === true) {
    for (const repoPath of managedMarkdown) {
      if (!registeredPaths.has(repoPath)) {
        issues.push(issue('UNREGISTERED_DOCUMENT', 'Managed Markdown is not registered.', null, repoPath));
      }
    }
  }

  // SINGLE_ACTIVE_WORK_PACKAGE: document-governance.md §2.1 mandates strictly serial
  // development — at most one work package may be `active` at a time. `npm run state`
  // already treats `kind === 'work-package' && status === 'active'` as the authoritative
  // active-package signal, so this gate makes the same invariant fail loudly instead of
  // letting drift accumulate silently (see docs/git-sync-agent-flow-eval-2026-09-13.md D-2).
  const activeWorkPackages = normalizedDocuments.filter(
    (document) => document.kind === 'work-package' && document.status === 'active',
  );
  if (activeWorkPackages.length > 1) {
    issues.push(issue(
      'MULTIPLE_ACTIVE_WORK_PACKAGES',
      `at most one work package may be active (found ${activeWorkPackages.length}): ${activeWorkPackages.map((d) => d.id || '<invalid id>').join(', ')}. Close out or downgrade the extras — see docs/document-governance.md §2.1.`,
    ));
  }

  // ORPHAN_ACTIVE_REVIEW: a design-review / process artefact must not stay `active`
  // once its owning work package has been retired. Leaving `phase: P0-REVIEW` behind
  // makes state recovery believe a review stage is still running.
  const retiredOwnerStatuses = new Set(['completed', 'superseded', 'archived']);
  const documentById = new Map(
    normalizedDocuments.filter((document) => document.id).map((document) => [document.id, document]),
  );
  for (const document of normalizedDocuments) {
    if (document.status !== 'active') continue;
    const ownerIds = [
      ...(Array.isArray(document.supersedes) ? document.supersedes : []),
      ...(Array.isArray(document.supersededBy) ? document.supersededBy : []),
      ...(Array.isArray(document.relatedWorkPackages) ? document.relatedWorkPackages : []),
    ];
    const retiredOwner = ownerIds.find((ownerId) => {
      const owner = documentById.get(ownerId);
      return owner && retiredOwnerStatuses.has(owner.status);
    });
    if (retiredOwner) {
      issues.push(issue(
        'ORPHAN_ACTIVE_REVIEW',
        `status is active but its owning work package ${retiredOwner} is already retired; downgrade this document and drop any stale phase.`,
        document.id || null,
        document.path,
      ));
    }
  }

  return issues;
}

async function buildInboundReferenceMap(rootDir, markdownPaths) {
  const inbound = new Map(markdownPaths.map((repoPath) => [repoPath, []]));
  for (const sourcePath of markdownPaths) {
    const source = await fs.readFile(path.join(rootDir, sourcePath), 'utf8');
    for (const targetPath of extractLocalMarkdownLinks(source, sourcePath)) {
      if (targetPath !== sourcePath && inbound.has(targetPath)) {
        inbound.get(targetPath).push(sourcePath);
      }
    }
  }
  for (const references of inbound.values()) references.sort();
  return inbound;
}

export async function buildReconciliationReport(registry, options = {}) {
  const rootDir = options.rootDir ?? DEFAULT_ROOT;
  const coverage = registry.coverage ?? {};
  const managedMarkdown = await collectManagedMarkdown(rootDir, coverage);
  const registeredPaths = new Set(registry.documents.map((document) => normalizeRepoPath(document.path)).filter(Boolean));
  const inbound = await buildInboundReferenceMap(rootDir, managedMarkdown);
  const unregistered = managedMarkdown.filter((repoPath) => !registeredPaths.has(repoPath));
  const validationIssues = await validateDocumentRegistry(registry, { rootDir });

  const archiveCandidates = registry.documents
    .filter((document) => ['completed', 'superseded'].includes(document.status))
    .filter((document) => ['archive_after_completion', 'archive_when_superseded'].includes(document.archivePolicy))
    .map((document) => ({
      id: document.id,
      path: document.path,
      inboundReferences: inbound.get(document.path) ?? [],
      readyForExplicitReview: (inbound.get(document.path) ?? []).length === 0,
    }));

  const retainedCompleted = registry.documents
    .filter((document) => document.status === 'completed' && document.archivePolicy === 'retain_stable_path')
    .map((document) => ({ id: document.id, path: document.path }));

  const manualReview = registry.documents
    .filter((document) => document.archivePolicy === 'manual_review')
    .map((document) => ({ id: document.id, path: document.path, status: document.status }));

  return {
    schemaVersion: 1,
    generatedAt: new Date().toISOString(),
    mode: 'read_only_reconciliation',
    counts: {
      registered: registry.documents.length,
      managedMarkdown: managedMarkdown.length,
      unregistered: unregistered.length,
      validationIssues: validationIssues.length,
      archiveCandidates: archiveCandidates.length,
      retainedCompleted: retainedCompleted.length,
      manualReview: manualReview.length,
    },
    unregistered,
    orphanDocuments: unregistered.filter((repoPath) => (inbound.get(repoPath) ?? []).length === 0),
    archiveCandidates,
    retainedCompleted,
    manualReview,
    validationIssues,
  };
}

function countBy(documents, field) {
  const counts = new Map();
  for (const document of documents) {
    const key = document[field] ?? '<missing>';
    counts.set(key, (counts.get(key) ?? 0) + 1);
  }
  return [...counts.entries()].sort(([left], [right]) => left.localeCompare(right));
}

function printIssueList(issues) {
  for (const item of issues) {
    const target = item.path ?? item.documentId ?? 'registry';
    console.error(`  - ${item.code} ${target}: ${item.message}`);
  }
}

function countByStatus(documents) {
  const counts = {};
  for (const document of documents) {
    const key = document.status ?? '<missing>';
    counts[key] = (counts[key] ?? 0) + 1;
  }
  return counts;
}

function countByKind(documents) {
  const counts = {};
  for (const document of documents) {
    const key = document.kind ?? '<missing>';
    counts[key] = (counts[key] ?? 0) + 1;
  }
  return counts;
}

/**
 * GATES-2 `--report` mode runner. Produces a deterministic JSON report
 * conforming to `docs/schemas/docs-governance-report.schema.json`.
 *
 * Exit codes (per `docs/document-governance.md` §4.5):
 *   0  — schema-valid report written; validation passed
 *   1  — schema-valid report written; registry validation found issues
 *   2  — classification conflict (path invalid, write failed, schema failed)
 *
 * The report is written BEFORE exit; on exit 2 the partial report is still
 * emitted for diagnosis, but `summary.status` is `CLASSIFICATION_CONFLICT`.
 */
async function runReportMode(reportPathRaw) {
  const reportPath = path.resolve(reportPathRaw);
  let registry;
  let issues;
  let managed;
  try {
    registry = await loadDocumentRegistry(DEFAULT_ROOT);
    issues = await validateDocumentRegistry(registry, { rootDir: DEFAULT_ROOT });
    managed = await collectManagedMarkdown(DEFAULT_ROOT, registry.coverage);
  } catch (error) {
    console.error(`[docs:report] 分类冲突 — registry/validation failure: ${error.message}`);
    process.exitCode = 2;
    return;
  }

  const isFailure = issues.length > 0;
  const status = isFailure ? 'FAIL' : 'PASS';
  const result = isFailure ? 'fail' : 'pass';
  const exitCode = isFailure ? 1 : 0;
  const report = {
    schemaVersion: GATE_REPORT_SCHEMA_VERSION,
    generatedAt: new Date().toISOString(),
    script: 'scripts/docs-governance.mjs',
    mode: 'report',
    exitCode,
    summary: {
      status,
      registered: registry.documents.length,
      managedMarkdown: managed.length,
      validationIssues: issues.length,
      result,
    },
    counts: {
      byStatus: countByStatus(registry.documents),
      byKind: countByKind(registry.documents),
    },
    issues: issues.map((item) => ({
      code: item.code,
      message: item.message,
      documentId: item.documentId ?? null,
      path: item.path ?? null,
    })),
  };

  const validation = validateReport('scripts/docs-governance.mjs', report);
  if (!validation.valid) {
    console.error('[docs:report] 分类冲突 — produced JSON does not match schema:');
    for (const err of validation.errors) {
      console.error(`  - ${err.path} ${err.keyword}: ${err.message}`);
    }
    process.exitCode = 2;
    return;
  }

  try {
    const parentDir = path.dirname(reportPath);
    await fs.mkdir(parentDir, { recursive: true });
    await fs.writeFile(reportPath, `${JSON.stringify(report, null, 2)}\n`, 'utf8');
  } catch (error) {
    console.error(`[docs:report] 分类冲突 — failed to write report to ${reportPath}: ${error.message}`);
    process.exitCode = 2;
    return;
  }

  report.reportPath = reportPath;
  if (isFailure) {
    console.error(`[docs:report] FAIL (${issues.length} validation issue(s)); report written to ${reportPath}`);
    process.exitCode = 1;
    return;
  }
  console.log(`[docs:report] PASS (${registry.documents.length} registered, ${managed.length} managed); report written to ${reportPath}`);
  process.exitCode = 0;
}

async function runCli() {
  const args = new Set(process.argv.slice(2));
  const modes = ['--status', '--check', '--reconcile'].filter((mode) => args.has(mode));
  if (modes.length > 1) {
    console.error('Choose only one of --status, --check, or --reconcile.');
    process.exitCode = 2;
    return;
  }
  if (args.has('--report') && modes.length > 0) {
    console.error('--report is mutually exclusive with --status, --check, --reconcile.');
    process.exitCode = 2;
    return;
  }
  const mode = modes[0] ?? '--status';

  // GATES-2: `--report <path>` JSON output mode. Activated before
  // registry loading so we can fail-closed (exit 2) on path misuse.
  // The path argument is taken literally from the next argv token; no
  // shell expansion, no auto-resolution outside the user's intent.
  if (args.has('--report')) {
    const reportIdx = process.argv.indexOf('--report');
    const reportPathRaw = process.argv[reportIdx + 1];
    if (!reportPathRaw || reportPathRaw.startsWith('--')) {
      console.error('--report requires a non-empty output path argument.');
      process.exitCode = 2;
      return;
    }
    await runReportMode(reportPathRaw);
    return;
  }

  const registry = await loadDocumentRegistry(DEFAULT_ROOT);
  const issues = await validateDocumentRegistry(registry, { rootDir: DEFAULT_ROOT });

  if (mode === '--check') {
    if (issues.length > 0) {
      console.error(`[docs:check] FAIL (${issues.length} issue(s))`);
      printIssueList(issues);
      process.exitCode = 1;
      return;
    }
    console.log(`[docs:check] PASS (${registry.documents.length} registered documents)`);
    return;
  }

  if (mode === '--status') {
    const managed = await collectManagedMarkdown(DEFAULT_ROOT, registry.coverage);
    console.log('Petri document governance status');
    console.log(`  Registered: ${registry.documents.length}`);
    console.log(`  Managed Markdown: ${managed.length}`);
    console.log(`  Validation: ${issues.length === 0 ? 'PASS' : `FAIL (${issues.length})`}`);
    console.log('  By status:');
    for (const [status, count] of countBy(registry.documents, 'status')) console.log(`    ${status}: ${count}`);
    console.log('  By kind:');
    for (const [kind, count] of countBy(registry.documents, 'kind')) console.log(`    ${kind}: ${count}`);
    if (issues.length > 0) printIssueList(issues);
    return;
  }

  const report = await buildReconciliationReport(registry, { rootDir: DEFAULT_ROOT });
  console.log('[docs:reconcile] read-only report; no files were moved or deleted');
  console.log(`  Registered: ${report.counts.registered}`);
  console.log(`  Unregistered: ${report.counts.unregistered}`);
  console.log(`  Archive candidates: ${report.counts.archiveCandidates}`);
  for (const candidate of report.archiveCandidates) {
    console.log(`    ${candidate.id}: refs=${candidate.inboundReferences.length}, explicitReview=${candidate.readyForExplicitReview}`);
  }
  console.log(`  Retained completed references: ${report.counts.retainedCompleted}`);
  console.log(`  Manual review: ${report.counts.manualReview}`);
  console.log(`  Validation issues: ${report.counts.validationIssues}`);
  if (report.validationIssues.length > 0) printIssueList(report.validationIssues);

  if (args.has('--write-report')) {
    const reportPath = path.join(DEFAULT_ROOT, 'acceptance', 'project-governance', 'document-audit.json');
    await fs.mkdir(path.dirname(reportPath), { recursive: true });
    await fs.writeFile(reportPath, `${JSON.stringify(report, null, 2)}\n`, 'utf8');
    console.log('  Wrote acceptance/project-governance/document-audit.json');
  }
}

if (path.resolve(process.argv[1] ?? '') === SCRIPT_PATH) {
  runCli().catch((error) => {
    console.error(`[docs-governance] ${error.message}`);
    process.exitCode = 1;
  });
}

#!/usr/bin/env node

import { spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const repoRoot = process.cwd();
const evidenceDir = join(repoRoot, 'acceptance/g0-critical-crosscut-hardening');
const files = [
  'package.json',
  'src/main.js',
  'core/petri-server/bootstrap.js',
  'core/petri-server/db.js',
  'core/petri-server/helpers/local-request-boundary.js',
  'core/petri-server/helpers/process-lifecycle.js',
  'core/petri-server/helpers/tools-executor.js',
  'core/petri-server/routes/files.js',
  'core/petri-server/routes/tools-platform.js',
  'core/shared-backend/local-request-boundary.js',
  'core/shared-backend/storage/local-storage.js',
  // Bio plugin sources moved to the independent domain pack (BLOCK-83 P4);
  // the science contracts (CHF0-SCI-*) moved with them. This core gate keeps
  // the origin-routing and lifecycle contracts only.
  'test/g0-chf0-http.test.mjs',
  'test/g0-chf0-lifecycle.test.mjs',
  'test/impact-map.json',
  'scripts/g0-chf0-acceptance.mjs',
];

const contracts = [
  {
    id: 'CHF0-SEC-1',
    assertion: 'R/Python raw execution and replot code routes fail closed for non-Petri origins',
    testFile: 'test/g0-chf0-http.test.mjs',
    pattern: 'CHF0 SEC-1',
  },
  {
    id: 'CHF0-SEC-2',
    assertion: 'Real /api/files routing rejects foreign origins, traversal, absolute paths and symlink escape',
    testFile: 'test/g0-chf0-http.test.mjs',
    pattern: 'CHF0 SEC-2',
  },
  {
    id: 'CHF0-BE-5',
    assertion: 'PID-gated liveness, confirmed TERM→KILL and cancellation DB truth agree',
    testFile: 'test/g0-chf0-lifecycle.test.mjs',
    pattern: 'CHF0 BE-5',
  },
];

function sha256(relativePath) {
  return createHash('sha256').update(readFileSync(join(repoRoot, relativePath))).digest('hex');
}

function git(...args) {
  const result = spawnSync('git', args, { cwd: repoRoot, encoding: 'utf8' });
  return result.status === 0 ? result.stdout.trim() : null;
}

function runContract(contract) {
  const args = ['--test', `--test-name-pattern=${contract.pattern}`, contract.testFile];
  const result = spawnSync(process.execPath, args, {
    cwd: repoRoot,
    encoding: 'utf8',
    env: { ...process.env, PYTHONDONTWRITEBYTECODE: '1' },
  });
  const output = `${result.stdout || ''}\n${result.stderr || ''}`.trim();
  const passMatches = [...output.matchAll(/(?:^|\s)pass\s+(\d+)/gm)];
  const testCount = passMatches.length ? Number(passMatches.at(-1)[1]) : 0;
  const passed = result.status === 0 && testCount > 0;
  return {
    id: contract.id,
    status: passed ? 'passed' : 'failed',
    assertion: contract.assertion,
    command: ['node', ...args].join(' '),
    testFile: contract.testFile,
    testNamePattern: contract.pattern,
    testCount,
    exitCode: result.status,
    outputTail: output.split(/\r?\n/).slice(-24).join('\n'),
  };
}

const checks = contracts.map(runContract);
const sourceHashes = Object.fromEntries(files.map((file) => [file, sha256(file)]));
const sourceTreeDigest = createHash('sha256')
  .update(Object.entries(sourceHashes).map(([file, hash]) => `${file}:${hash}`).join('\n'))
  .digest('hex');
const sourceCommit = git('rev-parse', 'HEAD');
const sourceCommitReachable = !!sourceCommit
  && spawnSync('git', ['merge-base', '--is-ancestor', sourceCommit, 'HEAD'], { cwd: repoRoot }).status === 0;
const sourceCommitMismatches = sourceCommit ? files.filter((file) => {
  const result = spawnSync('git', ['show', `${sourceCommit}:${file}`], { cwd: repoRoot });
  if (result.status !== 0) return true;
  const committedHash = createHash('sha256').update(result.stdout).digest('hex');
  return committedHash !== sourceHashes[file];
}) : [...files];
const sourceCommitMatchesSourceHashes = sourceCommitReachable && sourceCommitMismatches.length === 0;
const passed = checks.every((check) => check.status === 'passed') && sourceCommitMatchesSourceHashes;

mkdirSync(evidenceDir, { recursive: true });
const evidence = {
  schemaVersion: 2,
  acceptanceId: 'G0-CHF0-7',
  generatedAt: new Date().toISOString(),
  sourceCommit,
  sourceCommitReachable,
  sourceCommitMatchesSourceHashes,
  sourceCommitMismatches,
  sourceTreeDigest,
  qualificationEligible: false,
  passed,
  checks,
  sourceHashes,
};
writeFileSync(join(evidenceDir, 'acceptance.json'), `${JSON.stringify(evidence, null, 2)}\n`);
console.log(`[G0-CHF0] ${passed ? 'PASS' : 'FAIL'} — ${checks.filter((check) => check.status === 'passed').length}/${checks.length} contract classes`);
for (const check of checks) console.log(`  ${check.status === 'passed' ? '✓' : '✗'} ${check.id}: ${check.testCount} test(s)`);
if (!passed) process.exitCode = 1;

