    report.sourceCommitMismatches = commitStatus.mismatches;
    if (!report.sourceCommitMatchesSourceHashes) throw new Error(`source commit mismatch: ${commitStatus.mismatches.join(',')}`);
    if (!report.passed) throw new Error(report.checks.filter((check) => !check.passed).map((check) => check.id).join(','));
    mkdirSync(dirname(evidencePath), { recursive: true });
    writeFileSync(evidencePath, `${JSON.stringify(report, null, 2)}\n`);
    console.log(`[G0-RS-P2] PASS — evidence updated (${report.checks.length}/${report.checks.length})`);
  } else {
    if (!existsSync(evidencePath)) throw new Error('evidence missing; run npm run g0:result-studio:p2:update');
    const stored = JSON.parse(readFileSync(evidencePath, 'utf8'));
    const current = inspect(stored.verification);
    const commitStatus = sourceCommitStatus(stored.sourceCommit, stored.sourceHashes || {});
    if (!stored.passed || !current.passed || !stored.sourceCommitMatchesSourceHashes
      || !commitStatus.reachable || commitStatus.mismatches.length > 0
      || JSON.stringify(stored.sourceHashes) !== JSON.stringify(current.sourceHashes)) {
      throw new Error('stored G0-RS-P2 evidence is stale or invalid');
    }
    console.log(`[G0-RS-P2] PASS — ${current.checks.length}/${current.checks.length}`);
  }
} catch (error) {
  console.error(`[G0-RS-P2] FAIL — ${error.message}`);
  process.exitCode = 1;
}

#!/usr/bin/env node

import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { existsSync, readFileSync, realpathSync, writeFileSync } from 'node:fs';
import { basename, dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const outputPath = join(root, 'acceptance/g0-result-studio/rs-p2-live-observation.json');
const SHA256 = /^[a-f0-9]{64}$/;

function sha(value) {
  return createHash('sha256').update(typeof value === 'string' || Buffer.isBuffer(value)
    ? value : JSON.stringify(value)).digest('hex');
}

function parseArgs(argv) {
  const parsed = {};
  for (let index = 0; index < argv.length; index += 1) {
    const key = argv[index];
    if (!key.startsWith('--')) continue;
    parsed[key.slice(2)] = argv[index + 1];
    index += 1;
  }
  return parsed;
}

function required(args, key) {
  const value = String(args[key] || '').trim();
  if (!value) throw new Error(`--${key} is required`);
  return value;
}

async function fetchJson(url, options = {}) {
  const response = await fetch(url, options);
  const raw = await response.text();
  if (!response.ok) throw new Error(`${response.status} ${new URL(url).pathname}: ${raw.slice(0, 240)}`);
  return { data: JSON.parse(raw), responseSha256: sha(raw) };
}

function endpoint(base, pathname, query = null) {
  const url = new URL(pathname, base);
  if (query) {
    for (const [key, value] of Object.entries(query)) {
      if (value !== null && value !== undefined && value !== '') url.searchParams.set(key, String(value));
    }
  }
  return url.toString();
}

function interactionShape(response) {
  const manifest = response.data?.manifest || {};
  const backing = response.data?.backingTable || null;
  return {
    responseSha256: response.responseSha256,
    mode: manifest.interactionMode || 'read_only',
    entityType: manifest.entityType || null,
    durable: manifest.selectionDurable === true,
    backingRows: backing?.matchedCount ?? 0,
    backingEntityHashPresent: SHA256.test(backing?.selectionEvidence?.entityIdsHash || ''),
    revisionValid: response.data?.revision?.validationStatus === 'valid',
    reproducibilityAvailable: response.data?.revision?.reproducibilityStatus === 'available',
    sourceScriptHashPresent: SHA256.test(response.data?.revision?.sourceScriptRef?.sha256 || ''),
  };
}

function serverStartedAtMs(apiBase) {
  const port = new URL(apiBase).port;
  if (!port) return null;
  try {
    const pids = execFileSync('lsof', ['-nP', `-tiTCP:${port}`, '-sTCP:LISTEN'], { encoding: 'utf8' })
      .trim().split(/\s+/).filter(Boolean);
    if (pids.length !== 1) return null;
    const started = execFileSync('ps', ['-p', pids[0], '-o', 'lstart='], { encoding: 'utf8' }).trim();
    const parsed = Date.parse(started);
    return Number.isFinite(parsed) ? parsed : null;
  } catch {
    return null;
  }
}

function materializationEvidence(downstream, expectedSelectionId, expectedCount) {
  const geneList = String(downstream?.params?.deg_table || '');
  if (!geneList || basename(geneList) !== 'gene-list.csv') throw new Error('downstream gene-list materialization is missing');
  const realGeneList = realpathSync(geneList);
  const materializationRoot = dirname(realGeneList);
  const parametersPath = join(materializationRoot, 'selection-ids.json');
  const scriptPath = join(materializationRoot, 'materialize-selection.R');
  if (!existsSync(parametersPath) || !existsSync(scriptPath)) throw new Error('independent selection script or parameters are missing');
  const parametersRaw = readFileSync(parametersPath, 'utf8');
  const scriptRaw = readFileSync(scriptPath, 'utf8');
  const geneRaw = readFileSync(realGeneList, 'utf8');
  const parameters = JSON.parse(parametersRaw);
  const entityIds = Array.isArray(parameters.entityIds) ? parameters.entityIds : [];
  const geneRows = geneRaw.trim().split(/\r?\n/).slice(1);
  if (parameters.selectionId !== expectedSelectionId || entityIds.length !== expectedCount || geneRows.length !== expectedCount) {
    throw new Error('selection materialization count or identity drifted');
  }
  if (!/write\.csv/.test(scriptRaw) || !/selection-ids\.json/.test(scriptRaw)) {
    throw new Error('selection materialization script is not independently reproducible');
  }
  return {
    independentFiles: 3,
    entityCount: entityIds.length,
    parameterSha256: sha(parametersRaw),
    scriptSha256: sha(scriptRaw),
    outputSha256: sha(geneRaw),
  };
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  const apiBase = required(args, 'api-base');
  const parsedBase = new URL(apiBase);
  if (parsedBase.protocol !== 'http:' || !['127.0.0.1', 'localhost'].includes(parsedBase.hostname)) {
    throw new Error('--api-base must be a loopback HTTP endpoint');
  }
  const projectId = required(args, 'project-id');
  const sourceJobId = required(args, 'source-job-id');
  const downstreamJobId = required(args, 'downstream-job-id');
  const selectionId = required(args, 'selection-id');

  const [sourceStatus, downstreamStatus, deg, volcano, heatmap, enrichment] = await Promise.all([
    fetchJson(endpoint(apiBase, `/api/tools/status/${encodeURIComponent(sourceJobId)}`)),
    fetchJson(endpoint(apiBase, `/api/tools/status/${encodeURIComponent(downstreamJobId)}`)),
    fetchJson(endpoint(apiBase, '/api/result-studio/interaction', { jobId: sourceJobId, artifact: 'deg_table.csv' })),
    fetchJson(endpoint(apiBase, '/api/result-studio/interaction', { jobId: sourceJobId, artifact: 'volcano.png' })),
    fetchJson(endpoint(apiBase, '/api/result-studio/interaction', { jobId: sourceJobId, artifact: 'heatmap.png' })),
    fetchJson(endpoint(apiBase, '/api/result-studio/interaction', { jobId: downstreamJobId, artifact: 'go_bp_results.csv' })),
  ]);
  const revisionId = deg.data?.manifest?.revisionId;
  const artifactId = deg.data?.manifest?.artifactId;
  const selection = await fetchJson(endpoint(apiBase, '/api/result-studio/selection/current', {
    projectId,
    artifactId,
    revisionId,
    selectionDurable: true,
  }));
  const sourceQuery = await fetchJson(endpoint(apiBase, '/api/result-studio/table/query'), {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ jobId: sourceJobId, artifact: 'deg_table.csv', offset: 0, limit: 10 }),
  });
  const enrichmentQuery = await fetchJson(endpoint(apiBase, '/api/result-studio/table/query'), {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ jobId: downstreamJobId, artifact: 'go_bp_results.csv', offset: 0, limit: 10 }),
  });

  const source = sourceStatus.data;
  const downstream = downstreamStatus.data;
  const persisted = selection.data?.selection || {};
  const sourceTruth = source?.result?.artifactTruth || {};
  const downstreamTruth = downstream?.result?.artifactTruth || {};
  const serverStart = serverStartedAtMs(apiBase);
  const selectionCreated = Date.parse(persisted.createdAt || '');
  const recoveredAcrossServerRestart = Number.isFinite(serverStart)
    && Number.isFinite(selectionCreated) && selectionCreated < serverStart;
  const materialization = materializationEvidence(downstream, selectionId, persisted.entityIdCount);
  const interactions = {
    degTable: interactionShape(deg),
    volcano: interactionShape(volcano),
    heatmap: interactionShape(heatmap),
    enrichmentTable: interactionShape(enrichment),
  };

  const checks = {
    sourceJobValid: source.projectId === projectId && source.toolId === 'deseq2'
      && source.status === 'completed' && sourceTruth.status === 'valid' && sourceTruth.issueCount === 0,
    downstreamJobValid: downstream.projectId === projectId && downstream.toolId === 'go-kegg'
      && downstream.status === 'completed' && downstreamTruth.status === 'valid' && downstreamTruth.issueCount === 0,
    formalChainOrdered: Number(downstream.createdAt) > Number(source.completedAt),
    selectionCompatible: persisted.selectionId === selectionId && persisted.projectId === projectId
      && persisted.artifactId === artifactId && persisted.revisionId === revisionId
      && persisted.entityType === 'gene' && persisted.entityIdCount >= 3
      && SHA256.test(persisted.entityIdsHash || '') && selection.data?.compatibility?.status === 'compatible',
    restartRecovery: recoveredAcrossServerRestart,
    tableMapping: interactions.degTable.mode === 'table' && interactions.degTable.entityType === 'gene'
      && interactions.degTable.durable && interactions.degTable.revisionValid,
    scatterMapping: interactions.volcano.mode === 'scatter' && interactions.volcano.entityType === 'gene'
      && interactions.volcano.durable && interactions.volcano.backingRows > 0,
    matrixMapping: interactions.heatmap.mode === 'matrix' && interactions.heatmap.entityType === 'gene'
      && interactions.heatmap.durable && interactions.heatmap.backingRows > 0,
    enrichmentMapping: interactions.enrichmentTable.mode === 'table'
      && interactions.enrichmentTable.entityType === 'pathway' && interactions.enrichmentTable.durable,
    authoritativeQueries: sourceQuery.data?.selectionEvidence?.entityIdCount > 0
      && SHA256.test(sourceQuery.data?.selectionEvidence?.entityIdsHash || '')
      && enrichmentQuery.data?.selectionEvidence?.entityIdCount > 0
      && SHA256.test(enrichmentQuery.data?.selectionEvidence?.entityIdsHash || ''),
    independentMaterialization: materialization.independentFiles === 3
      && materialization.entityCount === persisted.entityIdCount,
  };
  const failed = Object.entries(checks).filter(([, passed]) => !passed).map(([id]) => id);
  if (failed.length > 0) throw new Error(`live observation failed: ${failed.join(', ')}`);

  const observation = {
    schemaVersion: 1,
    workPackage: 'G0-RS-P2',
    evidenceClass: 'live_local_product_observation_non_qualifying',
    capturedAt: new Date().toISOString(),
    qualificationEligible: false,
    privacy: 'digests_counts_timings_and_bounded_statuses_only_no_ids_urls_paths_credentials_prompts_or_result_values',
    scopeDigest: sha([projectId, sourceJobId, downstreamJobId, selectionId].join(':')),
    responseDigests: {
      sourceStatus: sourceStatus.responseSha256,
      downstreamStatus: downstreamStatus.responseSha256,
      selection: selection.responseSha256,
      sourceQuery: sourceQuery.responseSha256,
      enrichmentQuery: enrichmentQuery.responseSha256,
    },
    jobs: {
      source: { tool: 'deseq2', truth: sourceTruth.status, artifactCount: sourceTruth.validCount },
      downstream: { tool: 'go-kegg', truth: downstreamTruth.status, artifactCount: downstreamTruth.validCount },
      formalChain: 'run_tool -> tool_job -> artifact_truth',
    },
    selection: {
      entityType: persisted.entityType,
      entityCount: persisted.entityIdCount,
      entityIdsHash: persisted.entityIdsHash,
      compatibility: selection.data.compatibility.status,
      recoveredAcrossServerRestart,
      createdBeforeServerStartMs: recoveredAcrossServerRestart ? serverStart - selectionCreated : null,
    },
    interactions,
    authoritativeTables: {
      sourceRows: sourceQuery.data.totalRows,
      sourceEntityCount: sourceQuery.data.selectionEvidence.entityIdCount,
      enrichmentRows: enrichmentQuery.data.totalRows,
      enrichmentEntityCount: enrichmentQuery.data.selectionEvidence.entityIdCount,
    },
    materialization,
    checks,
    passed: true,
  };
  writeFileSync(outputPath, `${JSON.stringify(observation, null, 2)}\n`);
  console.log(`[G0-RS-P2] PASS — live observation captured (${Object.keys(checks).length}/${Object.keys(checks).length})`);
}

main().catch((error) => {
  console.error(`[G0-RS-P2] FAIL — ${error.message}`);
  process.exitCode = 1;
});

#!/usr/bin/env node

/**
 * G0-RS-P3 acceptance — Agent Context 与 Edit Orchestration。
 *
 * 与 P1/P2 同一形态：源码哈希 + 命令门禁 + 结构性断言，全部机器可读。
 * 本阶段是 offline/contract 层的 P3 收口，`qualificationEligible` 恒为 false：
 * 真实双 Provider tool calling 与 packaged 连续 trace 仍然只属于 G0-RS-P7。
 */

import { createHash } from 'node:crypto';
import { execFileSync, spawnSync } from 'node:child_process';
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const evidencePath = join(root, 'acceptance/g0-result-studio/rs-p3-agent-context.json');
const read = (file) => readFileSync(join(root, file), 'utf8');
const sha = (value) => createHash('sha256').update(String(value)).digest('hex');
const git = (...args) => execFileSync('git', args, { cwd: root, encoding: 'utf8' }).trim();
const item = (id, passed, evidence, detail) => ({ id, passed: passed === true, evidence, detail });

const sourceFiles = {
  contextContract: 'core/shared-backend/result-studio-context.js',
  contextTools: 'core/petri-server/agent-tools/result-context-tools.js',
  contextEditTools: 'core/petri-server/agent-tools/result-context-edit-tools.js',
  toolDefinitions: 'core/petri-server/agent-tools/tool-defs.js',
  toolRegistry: 'core/petri-server/agent-tools/registry.js',
  systemPrompt: 'core/petri-server/helpers/system-prompt.js',
  routes: 'core/petri-server/routes/result-studio.js',
  editTools: 'core/petri-server/agent-tools/result-edit-tools.js',
  contextClient: 'frontend/src/lib/result-studio-interaction-client.ts',
  surface: 'frontend/src/components/result-studio/ResultStudioSurface.tsx',
  surfaceStyle: 'frontend/src/components/result-studio/ResultStudioSurface.module.css',
  rightPanel: 'frontend/src/components/workspace-panels/RightPanel.tsx',
  workspace: 'frontend/src/pages/project-workspace.tsx',
  contextTest: 'test/result-studio-context.test.mjs',
  promptTest: 'test/system-prompt-result-context.test.mjs',
  registryTest: 'test/agent-tool-registry.test.mjs',
  intentTest: 'test/result-edit-intent.test.mjs',
  editAgentToolTest: 'test/result-edit-agent-tool.test.mjs',
  readinessTest: 'frontend/src/components/result-studio/ResultStudioContextReadiness.test.tsx',
  surfaceTest: 'frontend/src/components/result-studio/ResultStudioSurface.test.tsx',
  acceptanceScript: 'scripts/g0-rs-p3-acceptance.mjs',
  packageScripts: 'package.json',
};

const productObservation = {
  captureMode: 'automated_contract_registry_prompt_and_strict_build_offline_verification',
  qualificationEligible: false,
  qualificationReason:
    'P3 closes the offline Agent-context contract stage. Two real Providers completing tool calling with no internal ids, and packaged continuous product trace, remain reserved for G0-RS-P7.',
  notCoveredByThisStage: [
    'real_provider_tool_calling',
    'packaged_electron_continuous_trace',
    'manual_parameter_panels',
    'real_scientific_diff',
  ],
};

const CONTEXT_BOUND_TOOLS = Object.freeze([
  'result_studio_context',
  'result_edit_plan_in_context',
  'result_changeset_create_in_context',
  'result_changeset_status_in_context',
  'result_changeset_compare_in_context',
  'result_changeset_adopt_in_context',
  'result_changeset_revert_in_context',
]);

const INTERNAL_ID_PARAMS = Object.freeze(['toolJobId', 'artifactId', 'revisionId', 'artifactFamilyId', 'selectionId']);

function sourceHashes() {
  return Object.fromEntries(Object.entries(sourceFiles).map(([key, file]) => [key, sha(read(file))]));
}

function sourceCommitStatus(commit, hashes) {
  if (!commit || spawnSync('git', ['merge-base', '--is-ancestor', commit, 'HEAD'], { cwd: root }).status !== 0) {
    return { reachable: false, mismatches: Object.values(sourceFiles) };
  }
  const mismatches = Object.entries(sourceFiles).flatMap(([key, file]) => {
    const result = spawnSync('git', ['show', `${commit}:${file}`], { cwd: root, encoding: 'utf8' });
    return result.status === 0 && sha(result.stdout) === hashes[key] ? [] : [file];
  });
  return { reachable: true, mismatches };
}

function runCommands() {
  const npmCommand = (args) => process.platform === 'win32'
    ? [process.env.ComSpec || 'cmd.exe', ['/d', '/s', '/c', 'npm', ...args]]
    : ['npm', args];
  const [frontendTestBin, frontendTestArgs] = npmCommand([
    'run', 'test:files', '--prefix', 'frontend', '--',
    'ResultStudioContextReadiness.test.tsx',
    'ResultStudioSurface.test.tsx',
  ]);
  const [frontendBuildBin, frontendBuildArgs] = npmCommand([
    'run', 'build:check', '--prefix', 'frontend',
  ]);
  const commands = [
    ['backend-p3', 'node', ['--test',
      'test/result-studio-context.test.mjs',
      'test/system-prompt-result-context.test.mjs',
      'test/agent-tool-registry.test.mjs',
      'test/result-edit-intent.test.mjs',
      'test/result-edit-agent-tool.test.mjs',
    ]],
    // `npm test` in frontend is `vitest run --changed`, which combines with these
    // filters to select nothing and exit 0 — recording passed:true for a run that
    // executed no tests. `test:files` is plain `vitest run`, matching the gate.
    ['frontend-p3', frontendTestBin, frontendTestArgs],
    ['frontend-build', frontendBuildBin, frontendBuildArgs],
    ['syntax', 'node', ['--check', 'scripts/g0-rs-p3-acceptance.mjs']],
  ];
  return commands.map(([label, bin, args]) => {
    const result = spawnSync(bin, args, { cwd: root, encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 });
    return {
      label,
      command: [bin, ...args].join(' '),
      exitCode: result.status,
      passed: result.status === 0,
      stdoutSha256: sha(result.stdout || ''),
      stderrSha256: sha(result.stderr || ''),
    };
  });
}

/** 从注册表读取模型可见 schema。绕过 provider 投影就无法证明"模型看不到内部 id"。 */
function providerDefinitions() {
  // 用显式哨兵切分：注册表加载会打印启动日志（含 `[llm-providers]` 这类方括号），
  // 直接取第一个 '[' 会切到日志上，而不是 JSON 数组。
  const probe = spawnSync(process.execPath, ['-e',
    "process.stdout.write('<<RS_P3_DEFS>>' + JSON.stringify(require('./core/petri-server/agent-tools/registry.js').getProviderToolDefs()))",
  ], { cwd: root, encoding: 'utf8', maxBuffer: 32 * 1024 * 1024 });
  if (probe.status !== 0) throw new Error('tool registry failed to load');
  const marker = '<<RS_P3_DEFS>>';
  const index = probe.stdout.indexOf(marker);
  if (index < 0) throw new Error('tool registry probe produced no provider definitions');
  return JSON.parse(probe.stdout.slice(index + marker.length));
}

function inspect(verification = null) {
  const contract = read(sourceFiles.contextContract);
  const contextTools = read(sourceFiles.contextTools);
  const contextEditTools = read(sourceFiles.contextEditTools);
  const prompt = read(sourceFiles.systemPrompt);
  const routes = read(sourceFiles.routes);
  const client = read(sourceFiles.contextClient);
  const surface = read(sourceFiles.surface);
  const workspace = read(sourceFiles.workspace);
  const rightPanel = read(sourceFiles.rightPanel);
  const definitions = providerDefinitions();
  const byName = new Map(definitions.map((definition) => [definition.function.name, definition]));
  const commands = verification?.commands || [];

  const contextToolsRegistered = CONTEXT_BOUND_TOOLS.every((name) => byName.has(name));
  // 模型可见 schema 里不得出现内部 id 参数：这是 P3 的核心可验证断言。
  const noInternalIdParams = CONTEXT_BOUND_TOOLS.every((name) => {
    const properties = byName.get(name)?.function?.parameters?.properties || {};
    return INTERNAL_ID_PARAMS.every((param) => !(param in properties));
  });
  const writeToolsRequireToken = ['result_changeset_create_in_context', 'result_changeset_adopt_in_context', 'result_changeset_revert_in_context']
    .every((name) => (byName.get(name)?.function?.parameters?.required || []).includes('contextToken'));
  const legacyToolsPreserved = ['result_edit_plan', 'result_changeset_create', 'result_changeset_adopt']
    .every((name) => byName.has(name));

  const checks = [
    item('RS-P3-01',
      /RESULT_STUDIO_CONTEXT_VERSION = 1/.test(contract)
      && /buildResultStudioContextEnvelope/.test(contract)
      && ['artifact', 'job', 'revision', 'script', 'plugin', 'selection', 'workflow', 'validation', 'reproducibility']
        .every((field) => new RegExp(`${field}:`).test(contract)),
      [sourceFiles.contextContract],
      'ResultStudioContextEnvelope v1 carries project, conversation, job, artifact, family, revision, selection, plugin, script, validation and reproducibility coordinates.'),
    item('RS-P3-02',
      /computeContextToken/.test(contract) && /context_token_stale/.test(contract) && /authorizeContextOperation/.test(contract),
      [sourceFiles.contextContract],
      'A content-addressed contextToken exists and stale operations are rejected fail-closed.'),
    item('RS-P3-03', contextToolsRegistered, [sourceFiles.toolRegistry, sourceFiles.toolDefinitions],
      'All seven context-bound tools are registered with definition, handler and contract parity.'),
    item('RS-P3-04', noInternalIdParams, [sourceFiles.toolDefinitions],
      'No context-bound tool exposes toolJobId, artifactId, revisionId, artifactFamilyId or selectionId to the model.'),
    item('RS-P3-05', writeToolsRequireToken, [sourceFiles.toolDefinitions],
      'Create, adopt and revert require contextToken in their model-visible schema.'),
    item('RS-P3-06',
      /resolveResultStudioContext/.test(contextTools)
      && /findRevisionByJobArtifact/.test(contextTools)
      && /assessSelectionCompatibility/.test(contextTools),
      [sourceFiles.contextTools],
      'Coordinates are re-resolved from SQLite, tool_jobs and plugin descriptors instead of trusting client-declared identity.'),
    item('RS-P3-07',
      /context_attribution_job_only/.test(contract) && /context_revision_missing/.test(contract),
      [sourceFiles.contextContract],
      'Job-only attribution and a missing revision block honestly rather than fabricating script coordinates.'),
    // 兼容性闸门实现在契约层（buildResultStudioContextEnvelope），工具层只负责
    // 从 SQLite 恢复选择并交给它判定。断言必须落在真正实现该行为的文件上。
    item('RS-P3-08',
      /compatibility === 'compatible'/.test(contract)
        && /selectionState/.test(contract)
        && /usableByAgent/.test(contract)
        && /assessSelectionCompatibility/.test(contextTools),
      [sourceFiles.contextContract, sourceFiles.contextTools],
      'Only a compatible selection enters the agent context; stale and invalid selections report actionable state.'),
    item('RS-P3-09',
      /context_change_set_ambiguous/.test(contextTools) && /OPEN_CHANGE_SET_STATUSES/.test(contextTools),
      [sourceFiles.contextTools],
      'Change sets are bound from context and ambiguity is refused instead of guessed.'),
    item('RS-P3-10',
      /PUBLIC_EDIT_PHASES/.test(contract)
      && ['understand_intent', 'assess_impact', 'execute_or_recompute', 'validate', 'candidate_comparable']
        .every((phase) => contract.includes(phase))
      && /publicProgress/.test(contextEditTools),
      [sourceFiles.contextContract, sourceFiles.contextEditTools],
      'Public progress is fixed to the five phases and projected from engineering stages without exposing hidden reasoning.'),
    item('RS-P3-11',
      /createResultChangeSetTools/.test(contextEditTools) && /result-edit-tools/.test(contextEditTools),
      [sourceFiles.contextEditTools, sourceFiles.editTools],
      'Context-bound tools delegate to the existing ChangeSet and compare services, creating no second execution truth.'),
    item('RS-P3-12',
      /context_intent_mismatch/.test(contextEditTools),
      [sourceFiles.contextEditTools],
      'An intent planned against another revision cannot be materialized in the current context.'),
    item('RS-P3-13',
      /result-studio\/context-envelope/.test(routes) && /canAccessProject/.test(routes),
      [sourceFiles.routes],
      'The production API exposes the same envelope projection under existing project authorization.'),
    item('RS-P3-14',
      /RESULT_STUDIO_CONTEXT_v1/.test(prompt)
      && /result_studio_context/.test(prompt)
      && /不要向用户索要/.test(prompt),
      [sourceFiles.systemPrompt],
      'The system prompt describes the open result and forbids asking the user for internal ids.'),
    item('RS-P3-15',
      !/revisionId\s*\+/.test(prompt) && !/artifact\.revisionId\s*\)/.test(prompt.replace(/artifact\.revisionId \? /g, '')),
      [sourceFiles.systemPrompt],
      'The prompt never interpolates a revision, job, changeset or selection id into model-visible text.'),
    item('RS-P3-16',
      /fetchResultStudioContext/.test(client) && /context-envelope/.test(client) && /blocked/.test(client),
      [sourceFiles.contextClient],
      'The frontend reads the same envelope and normalizes backend blocking into an honest state.'),
    item('RS-P3-17',
      /ResultStudioContextReadiness/.test(surface)
      && /已过期/.test(surface)
      && /fetchResultStudioContext/.test(workspace)
      && /resultContext/.test(rightPanel),
      [sourceFiles.surface, sourceFiles.workspace, sourceFiles.rightPanel],
      'Inspector readiness is wired to the real projection and reports stale or unusable selections truthfully.'),
    item('RS-P3-18', legacyToolsPreserved, [sourceFiles.toolDefinitions],
      'The original explicit-id RS4-RS6 tools remain available for scripted use and were not replaced.'),
    item('RS-P3-19', commands.length >= 4 && commands.every((command) => command.passed),
      ['acceptance/g0-result-studio/rs-p3-agent-context.json'],
      'All declared P3 command gates passed, including frontend strict build.'),
    item('RS-P3-20',
      /qualificationEligible/.test(read(sourceFiles.acceptanceScript))
      && productObservation.qualificationEligible === false,
      [sourceFiles.acceptanceScript],
      'This stage explicitly declares itself non-qualifying; real Provider and packaged trace stay with P7.'),
  ];

  return {
    schemaVersion: 1,
    workPackage: 'G0-RS-P3',
    sourceCommit: git('rev-parse', 'HEAD'),
    captureMode: productObservation.captureMode,
    qualificationEligible: false,
    privacy: 'repository_relative_paths_digests_counts_and_bounded_statuses_only_no_project_job_conversation_selection_url_credential_prompt_or_result_data',
    sourceHashes: sourceHashes(),
    productObservation,
    modelVisibleTools: {
      total: definitions.length,
      contextBound: CONTEXT_BOUND_TOOLS.length,
      internalIdParametersExposed: 0,
    },
    checks,
    verification,
    invariants: {
      executionTruth: 'run_tool -> tool_job -> artifact_truth',
      secondExecutionTruth: false,
      resultStudioQualificationClaimed: false,
      futureStagesImplemented: false,
    },
    passed: checks.every((check) => check.passed),
  };
}

try {
  if (process.argv.includes('--write-evidence')) {
    const verification = { generatedAt: new Date().toISOString(), commands: runCommands() };
    const report = { ...inspect(verification), generatedAt: verification.generatedAt, privacyClean: true };
    const commitStatus = sourceCommitStatus(report.sourceCommit, report.sourceHashes);
    report.sourceCommitReachable = commitStatus.reachable;
    report.sourceCommitMatchesSourceHashes = commitStatus.reachable && commitStatus.mismatches.length === 0;
    report.sourceCommitMismatches = commitStatus.mismatches;
    if (!report.sourceCommitMatchesSourceHashes) throw new Error(`source commit mismatch: ${commitStatus.mismatches.join(',')}`);
    if (!report.passed) throw new Error(report.checks.filter((check) => !check.passed).map((check) => check.id).join(','));
    mkdirSync(dirname(evidencePath), { recursive: true });
    writeFileSync(evidencePath, `${JSON.stringify(report, null, 2)}\n`);
    console.log(`[G0-RS-P3] PASS — evidence updated (${report.checks.length}/${report.checks.length})`);
  } else {
    if (!existsSync(evidencePath)) throw new Error('evidence missing; run npm run g0:result-studio:p3:update');
    const stored = JSON.parse(readFileSync(evidencePath, 'utf8'));
    const current = inspect(stored.verification);
    const commitStatus = sourceCommitStatus(stored.sourceCommit, stored.sourceHashes || {});
    if (!stored.passed || !current.passed || !stored.sourceCommitMatchesSourceHashes
      || !commitStatus.reachable || commitStatus.mismatches.length > 0
      || JSON.stringify(stored.sourceHashes) !== JSON.stringify(current.sourceHashes)) {
      throw new Error('stored G0-RS-P3 evidence is stale or invalid');
    }
    console.log(`[G0-RS-P3] PASS — ${current.checks.length}/${current.checks.length}`);
  }
} catch (error) {
  console.error(`[G0-RS-P3] FAIL — ${error.message}`);
  process.exitCode = 1;
}

#!/usr/bin/env node

/**
 * G0-RS-P4 验收 — Manual + AI Unified Editing。
 *
 * 证据类型：离线契约 + descriptor 投影 + 插件脚本接线 + 模型可见 schema +
 * strict build。这些**不能**替代 P7 要求的 packaged 连续产品 trace 与双真实
 * Provider 观测，因此 `qualificationEligible` 恒为 false。
 *
 * 断言原则：只断言可从真实源码/descriptor/注册表读出的事实，不接受人工布尔值。
 */

import { createHash } from 'node:crypto';
import { execFileSync, spawnSync } from 'node:child_process';
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const evidencePath = join(root, 'acceptance/g0-result-studio/rs-p4-unified-editing.json');
const read = (file) => readFileSync(join(root, file), 'utf8');
const readJson = (file) => JSON.parse(read(file));
const sha = (value) => createHash('sha256').update(String(value)).digest('hex');
const git = (...args) => execFileSync('git', args, { cwd: root, encoding: 'utf8' }).trim();
const item = (id, passed, evidence, detail) => ({ id, passed: passed === true, evidence, detail });

const sourceFiles = {
  controls: 'core/shared-backend/result-edit-controls.js',
  intent: 'core/shared-backend/result-edit-intent.js',
  contextTools: 'core/petri-server/agent-tools/result-context-tools.js',
  contextEditTools: 'core/petri-server/agent-tools/result-context-edit-tools.js',
  toolDefinitions: 'core/petri-server/agent-tools/tool-defs.js',
  changeSetService: 'core/shared-backend/result-changeset-service.js',
  routes: 'core/petri-server/routes/result-studio.js',
  panel: 'frontend/src/components/result-studio/ResultEditPanel.tsx',
  panelStyle: 'frontend/src/components/result-studio/ResultEditPanel.module.css',
  panelTest: 'frontend/src/components/result-studio/ResultEditPanel.test.tsx',
  agentComposer: 'frontend/src/components/result-studio/ResultAgentComposer.tsx',
  agentComposerTest: 'frontend/src/components/result-studio/ResultAgentComposer.test.tsx',
  agentBridge: 'frontend/src/lib/result-edit-agent-bridge.ts',
  agentBridgeTest: 'frontend/src/lib/result-edit-agent-bridge.test.ts',
  simpleChat: 'frontend/src/components/copilot/SimpleChat.tsx',
  rightPanel: 'frontend/src/components/workspace-panels/RightPanel.tsx',
  rightPanelTest: 'frontend/src/components/workspace-panels/RightPanel.test.tsx',
  workspace: 'frontend/src/pages/project-workspace.tsx',
  contextClient: 'frontend/src/lib/result-studio-interaction-client.ts',
  systemPrompt: 'core/petri-server/helpers/system-prompt.js',
  volcanoDescriptor: 'resources/built-in-plugins/volcano-plot/tool-definition.json',
  volcanoScript: 'resources/built-in-plugins/volcano-plot/scripts/volcano-plot.R',
  volcanoGolden: 'resources/built-in-plugins/volcano-plot/golden-revisions/result-studio-v1.json',
  controlsTest: 'test/result-edit-controls.test.mjs',
  intentTest: 'test/result-edit-intent.test.mjs',
  contextTest: 'test/result-studio-context.test.mjs',
  pluginSdkTest: 'test/result-studio-plugin-sdk.test.mjs',
  qualificationTest: 'test/result-studio-qualification.test.mjs',
  registryTest: 'test/agent-tool-registry.test.mjs',
  readinessTest: 'frontend/src/components/result-studio/ResultStudioContextReadiness.test.tsx',
  surfaceTest: 'frontend/src/components/result-studio/ResultStudioSurface.test.tsx',
  centerPanelTest: 'frontend/src/components/workspace-panels/CenterPanel.test.tsx',
  acceptanceScript: 'scripts/g0-rs-p4-acceptance.mjs',
  packageScripts: 'package.json',
};

/** P4 交付要求的首批控件类别 → volcano descriptor 中的参数名。 */
const FIRST_BATCH_CONTROLS = Object.freeze({
  color: ['color_up', 'color_down', 'color_ns'],
  font: ['base_font_size', 'label_size'],
  size: ['point_size', 'plot_width', 'plot_height'],
  legend: ['legend_position'],
  label: ['plot_title'],
  export: ['export_dpi'],
});

function sourceHashes() {
  return Object.fromEntries(Object.entries(sourceFiles).map(([key, file]) => [key, sha(read(file))]));
}

function sourceCommitStatus(commit, hashes) {
  if (!commit || spawnSync('git', ['merge-base', '--is-ancestor', commit, 'HEAD'], { cwd: root }).status !== 0) {
    return { reachable: false, mismatches: Object.values(sourceFiles) };
  }
  const mismatches = Object.entries(sourceFiles).flatMap(([key, file]) => {
    const result = spawnSync('git', ['show', `${commit}:${file}`], { cwd: root, encoding: 'utf8' });
    return result.status === 0 && sha(result.stdout) === hashes[key] ? [] : [file];
  });
  return { reachable: true, mismatches };
}

function runCommands() {
  const commands = [
    ['backend-p4', 'node', ['--test',
      'test/result-edit-controls.test.mjs',
      'test/result-edit-intent.test.mjs',
      'test/result-studio-context.test.mjs',
      'test/result-studio-plugin-sdk.test.mjs',
      'test/result-studio-qualification.test.mjs',
      'test/agent-tool-registry.test.mjs',
    ]],
    // `npm test` in frontend is `vitest run --changed`, which combines with these
    // filters to select nothing and exit 0 — recording passed:true for a run that
    // executed no tests. `test:files` is plain `vitest run`, matching the gate.
    ['frontend-p4', 'npm', ['run', 'test:files', '--prefix', 'frontend', '--',
      'ResultEditPanel.test.tsx',
      'ResultAgentComposer.test.tsx',
      'result-edit-agent-bridge.test.ts',
      'ResultStudioContextReadiness.test.tsx',
      'ResultStudioSurface.test.tsx',
      'CenterPanel.test.tsx',
      'RightPanel.test.tsx',
    ]],
    ['frontend-build', 'npm', ['run', 'build:check', '--prefix', 'frontend']],
    ['syntax', 'node', ['--check', 'scripts/g0-rs-p4-acceptance.mjs']],
  ];
  return commands.map(([label, bin, args]) => {
    const result = spawnSync(bin, args, { cwd: root, encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 });
    return {
      label,
      command: [bin, ...args].join(' '),
      exitCode: result.status,
      passed: result.status === 0,
      stdoutSha256: sha(result.stdout || ''),
      stderrSha256: sha(result.stderr || ''),
    };
  });
}

/** 从真实模块投影控件，避免只用正则"看起来实现了"。 */
function projectControls() {
  const probe = spawnSync(process.execPath, ['-e', `
    const controls = require('./core/shared-backend/result-edit-controls');
    const intentModule = require('./core/shared-backend/result-edit-intent');
    const definition = require('./resources/built-in-plugins/volcano-plot/tool-definition.json');
    const schema = controls.buildEditControlSchema(definition.resultStudio);
    const neutral = controls.normalizeEditSubmission({
      descriptor: definition.resultStudio,
      proposedValues: { color_up: '#111111', plot_title: 'New title' },
      origin: 'manual',
    });
    const scientific = controls.normalizeEditSubmission({
      descriptor: definition.resultStudio,
      proposedValues: { fc_threshold: 2 },
      origin: 'agent',
    });
    // 真正的降级尝试：调用方自称这只是样式修改，descriptor 说是科学参数。
    // normalizeEditSubmission 只信 descriptor，因此 requestedEditClass 必须无效。
    const downgradeAttempt = controls.normalizeEditSubmission({
      descriptor: definition.resultStudio,
      proposedValues: { fc_threshold: 2 },
      requestedEditClass: 'presentation_rerender',
      editClass: 'presentation_rerender',
      origin: 'agent',
    });
    // deseq2 把 design 声明为 workflow。保护字段表也认识 design，但只能当下限：
    // 若保护字段覆盖了 descriptor，workflow 会被悄悄降级成 scientific。
    const deseq2 = require('./resources/built-in-plugins/deseq2/tool-definition.json');
    const workflowAttempt = controls.normalizeEditSubmission({
      descriptor: deseq2.resultStudio,
      proposedValues: { design: 'condition + batch' },
      requestedEditClass: 'presentation_rerender',
      origin: 'agent',
    });
    const rejected = controls.normalizeEditSubmission({
      descriptor: definition.resultStudio,
      proposedValues: { color_up: 'not-a-color', undeclared_param: 1 },
      origin: 'manual',
    });
    const unchanged = controls.normalizeEditSubmission({
      descriptor: definition.resultStudio,
      proposedValues: { point_size: 1.8 },
      currentValues: { point_size: 1.8 },
      origin: 'manual',
    });
    process.stdout.write('__RSP4__' + JSON.stringify({
      groups: schema.groups.map((group) => group.group),
      controlCount: schema.controls.length,
      byName: Object.fromEntries(schema.controls.map((control) => [control.name, {
        group: control.group,
        controlType: control.controlType,
        neutral: control.scientificallyNeutral,
      }])),
      neutral: {
        editClass: neutral.classification && neutral.classification.editClass,
        requiresJob: neutral.classification && neutral.classification.requiresJob,
        confirm: neutral.classification && neutral.classification.requiresScientificConfirmation,
        impact: controls.explainEditImpact(neutral.classification),
      },
      scientific: {
        editClass: scientific.classification && scientific.classification.editClass,
        confirm: scientific.classification && scientific.classification.requiresScientificConfirmation,
        impact: controls.explainEditImpact(scientific.classification, { affectedNodeIds: ['a', 'b'] }),
      },
      downgradeBlocked: downgradeAttempt.classification.editClass === 'scientific_recompute',
      workflowNotDowngraded: workflowAttempt.classification.editClass === 'workflow_replan',
      workflowConfirm: workflowAttempt.classification.requiresScientificConfirmation === true,
      // 未知参数的保守回退发生在 classifyParameterPatch：控件层会直接拒绝
      // 未声明参数，而 AI 直接提交的 patch 仍要经过这条保守分级。
      unknownParameterFallback: intentModule.classifyParameterPatch({
        proposedParameterPatch: { mystery_knob: 5 },
        parameterImpactRules: {},
        requestedEditClass: 'presentation_rerender',
      }).editClass,
      unknownParameterConservative: intentModule.classifyParameterPatch({
        proposedParameterPatch: { mystery_knob: 5 },
        parameterImpactRules: {},
      }).usedConservativeFallback,
      rejected: rejected.rejected.sort(),
      rejectedOk: rejected.ok,
      unchangedChanged: unchanged.changed.length,
      unchangedOk: unchanged.ok,
    }));
  `], { cwd: root, encoding: 'utf8', maxBuffer: 32 * 1024 * 1024 });
  if (probe.status !== 0) throw new Error(`control projection failed: ${(probe.stderr || '').slice(0, 300)}`);
  const marker = probe.stdout.indexOf('__RSP4__');
  if (marker < 0) throw new Error('control projection produced no payload');
  return JSON.parse(probe.stdout.slice(marker + '__RSP4__'.length));
}

/** 读取模型可见 schema，证明 AI 侧与手动侧共用同一入口。 */
function providerDefinitions() {
  const probe = spawnSync(process.execPath, ['-e',
    "process.stdout.write('__DEFS__' + JSON.stringify(require('./core/petri-server/agent-tools/registry.js').getProviderToolDefs()))",
  ], { cwd: root, encoding: 'utf8', maxBuffer: 32 * 1024 * 1024 });
  if (probe.status !== 0) throw new Error('tool registry failed to load');
  const marker = probe.stdout.indexOf('__DEFS__');
  if (marker < 0) throw new Error('registry produced no payload');
  return JSON.parse(probe.stdout.slice(marker + '__DEFS__'.length));
}

function inspect(verification = null) {
  const controls = read(sourceFiles.controls);
  const intent = read(sourceFiles.intent);
  const contextEditTools = read(sourceFiles.contextEditTools);
  const contextTools = read(sourceFiles.contextTools);
  const routes = read(sourceFiles.routes);
  const panel = read(sourceFiles.panel);
  const workspace = read(sourceFiles.workspace);
  const rightPanel = read(sourceFiles.rightPanel);
  const changeSetService = read(sourceFiles.changeSetService);
  const volcanoScript = read(sourceFiles.volcanoScript);
  const descriptor = readJson(sourceFiles.volcanoDescriptor).resultStudio;
  const projected = projectControls();
  const definitions = providerDefinitions();
  const planDefinition = definitions.find((d) => d.function.name === 'result_edit_plan_in_context');
  const commands = verification?.commands || [];

  // 首批控件必须真的出现在 descriptor 投影里，且被 R 脚本消费。
  const firstBatch = Object.entries(FIRST_BATCH_CONTROLS).map(([category, names]) => ({
    category,
    names,
    projected: names.every((name) => !!projected.byName[name]),
    wired: names.every((name) => new RegExp(`params\\$${name}\\b`).test(volcanoScript)),
  }));
  const firstBatchPassed = firstBatch.every((entry) => entry.projected && entry.wired);

  // presentation 控件不得被声明成会重算科学的级别。
  const presentationNames = Object.values(FIRST_BATCH_CONTROLS).flat();
  const presentationNeutral = presentationNames.every((name) => projected.byName[name]?.group === 'presentation'
    && projected.byName[name]?.neutral === true);

  const checks = [
    item('RS-P4-01',
      /buildEditControlSchema/.test(controls) && /descriptor\.parameters/.test(controls)
        && projected.controlCount >= 12 && projected.groups.includes('presentation'),
      [sourceFiles.controls],
      'Controls are projected from the plugin descriptor schema; no per-plugin result page is hand written.'),
    item('RS-P4-02', firstBatchPassed, [sourceFiles.volcanoDescriptor, sourceFiles.volcanoScript],
      'The first control batch covers color, font, size, legend, label and export format, and each parameter is consumed by the real renderer script.'),
    item('RS-P4-03', presentationNeutral && projected.neutral.editClass === 'presentation_rerender'
      && projected.neutral.impact.rerunsScience === false,
      [sourceFiles.controls, sourceFiles.volcanoDescriptor],
      'A pure styling change is classified as presentation rerender and never reruns the scientific computation.'),
    item('RS-P4-04', projected.scientific.editClass === 'scientific_recompute'
      && projected.scientific.confirm === true
      && projected.scientific.impact.affectedNodeCount === 2,
      [sourceFiles.controls],
      'A scientific threshold change requires explicit confirmation and reports its affected downstream nodes.'),
    item('RS-P4-05', /normalizeEditSubmission/.test(contextEditTools)
      && /editOrigin/.test(contextEditTools)
      && /planResultEdit/.test(intent),
      [sourceFiles.contextEditTools],
      'Manual controls and AI intent pass through one normalization gate before the shared ResultEditIntent planner.'),
    item('RS-P4-06', planDefinition?.function?.parameters?.properties?.editOrigin?.enum?.includes('manual') === true
      && planDefinition?.function?.parameters?.properties?.editOrigin?.enum?.includes('agent') === true,
      [sourceFiles.toolDefinitions],
      'The model-visible schema records the edit origin so manual and AI submissions stay auditable on one tool.'),
    item('RS-P4-07', projected.rejectedOk === false
      && projected.rejected.includes('undeclared_param') && projected.rejected.includes('color_up'),
      [sourceFiles.controls],
      'Undeclared parameters and out-of-contract values are rejected rather than silently dropped or clamped.'),
    item('RS-P4-08', projected.unchangedChanged === 0 && projected.unchangedOk === false
      && /edit_no_effective_change/.test(contextEditTools),
      [sourceFiles.controls, sourceFiles.contextEditTools],
      'A submission equal to the current values produces no patch, so no empty ChangeSet or Job is created.'),
    item('RS-P4-09', projected.downgradeBlocked === true
      && projected.workflowNotDowngraded === true && projected.workflowConfirm === true,
      [sourceFiles.controls, sourceFiles.intent],
      'A caller declaring presentation_rerender cannot downgrade a parameter the descriptor declares scientific, and a declared workflow parameter is not silently degraded to scientific by the protected-field table.'),
    item('RS-P4-10', projected.unknownParameterFallback === 'scientific_recompute'
      && projected.unknownParameterConservative === true,
      [sourceFiles.intent],
      'A parameter with no declared impact falls back to scientific recompute and is flagged as a conservative decision, never guessed as styling.'),
    item('RS-P4-11', /currentParameters/.test(contextTools)
      && /executionProvenance/.test(contextTools),
      [sourceFiles.contextTools],
      'Current values come from the parameters the job really executed, not from descriptor defaults.'),
    item('RS-P4-12', /editControls/.test(routes) && /buildEditControlSchema/.test(routes)
      && /currentValues/.test(routes),
      [sourceFiles.routes],
      'The production API serves one control schema shared by the manual panel and the agent context.'),
    item('RS-P4-13', /scientificallyNeutral/.test(panel) && /needsConfirm/.test(panel)
      && /我已理解这会改变科学结论/.test(panel),
      [sourceFiles.panel],
      'The panel only claims scientific neutrality where the descriptor allows it and requires explicit confirmation otherwise.'),
    item('RS-P4-14', !/fetch\(/.test(panel) && !/writeFile|localStorage/.test(panel),
      [sourceFiles.panel],
      'No control writes an Artifact, source data, or the current Revision: the panel only emits an edit request.'),
    item('RS-P4-15', commands.find((command) => command.label === 'frontend-p4')?.passed === true
      && /buildResultEditCopilotAsk/.test(workspace)
      && /copilotContextOverrideForAsk/.test(read(sourceFiles.simpleChat))
      && /result_studio_context/.test(read(sourceFiles.systemPrompt))
      && /result_edit_plan_in_context/.test(read(sourceFiles.systemPrompt)),
      [sourceFiles.workspace, sourceFiles.agentBridge, sourceFiles.agentBridgeTest, sourceFiles.simpleChat, sourceFiles.systemPrompt],
      'Manual and Agent submissions share the tested atomic context bridge; the production chat consumer preserves the click-time snapshot, then the hidden system orchestration reads the trusted schema before planning the edit.'),
    item('RS-P4-16', /ResultEditAdvancedDrawer/.test(rightPanel) && /disabledReason/.test(rightPanel),
      [sourceFiles.rightPanel, sourceFiles.panel, sourceFiles.panelTest],
      'The schema panel is a default-closed advanced drawer and remains disabled with an honest reason when reproducible coordinates are unavailable.'),
    item('RS-P4-17', /createResultChangeSet/.test(changeSetService)
      && /run_tool|executeJob/.test(changeSetService),
      [sourceFiles.changeSetService],
      'Candidate creation still flows through the existing ChangeSet service and formal execution truth.'),
    item('RS-P4-18', commands.length >= 4 && commands.every((command) => command.passed),
      [evidencePath.replace(`${root}/`, '')],
      'All declared P4 command gates passed.'),
  ];

  return {
    schemaVersion: 1,
    workPackage: 'G0-RS-P4',
    sourceCommit: git('rev-parse', 'HEAD'),
    captureMode: 'automated_descriptor_projection_plugin_wiring_registry_and_strict_build_offline_verification',
    qualificationEligible: false,
    qualificationReason: 'P4 closes the offline unified-editing contract; real manual-vs-AI equivalence on a live plugin run and packaged product qualification remain reserved for P5 and P7.',
    privacy: 'repository_relative_paths_digests_counts_and_bounded_statuses_only_no_project_job_conversation_selection_url_credential_prompt_or_result_data',
    sourceHashes: sourceHashes(),
    controlObservation: {
      controlCount: projected.controlCount,
      groups: projected.groups,
      firstBatch,
      presentationNeutral,
      descriptorParameterCount: Object.keys(descriptor.parameters || {}).length,
    },
    checks,
    verification,
    invariants: {
      executionTruth: 'run_tool -> tool_job -> artifact_truth',
      secondEditingChain: false,
      resultStudioQualificationClaimed: false,
      futureStagesImplemented: false,
    },
    passed: checks.every((check) => check.passed),
  };
}

try {
  if (process.argv.includes('--write-evidence')) {
    const verification = { generatedAt: new Date().toISOString(), commands: runCommands() };
    const report = { ...inspect(verification), generatedAt: verification.generatedAt, privacyClean: true };
    const commitStatus = sourceCommitStatus(report.sourceCommit, report.sourceHashes);
    report.sourceCommitReachable = commitStatus.reachable;
    report.sourceCommitMatchesSourceHashes = commitStatus.reachable && commitStatus.mismatches.length === 0;
    report.sourceCommitMismatches = commitStatus.mismatches;
    if (!report.sourceCommitMatchesSourceHashes) throw new Error(`source commit mismatch: ${commitStatus.mismatches.join(',')}`);
    if (!report.passed) throw new Error(report.checks.filter((check) => !check.passed).map((check) => check.id).join(','));
    mkdirSync(dirname(evidencePath), { recursive: true });
    writeFileSync(evidencePath, `${JSON.stringify(report, null, 2)}\n`);
    console.log(`[G0-RS-P4] PASS — evidence updated (${report.checks.length}/${report.checks.length})`);
  } else {
    if (!existsSync(evidencePath)) throw new Error('evidence missing; run npm run g0:result-studio:p4:update');
    const stored = JSON.parse(readFileSync(evidencePath, 'utf8'));
    const current = inspect(stored.verification);
    const commitStatus = sourceCommitStatus(stored.sourceCommit, stored.sourceHashes || {});
    if (!stored.passed || !current.passed || !stored.sourceCommitMatchesSourceHashes
      || !commitStatus.reachable || commitStatus.mismatches.length > 0
      || JSON.stringify(stored.sourceHashes) !== JSON.stringify(current.sourceHashes)) {
      throw new Error('stored G0-RS-P4 evidence is stale or invalid');
    }
    console.log(`[G0-RS-P4] PASS — ${current.checks.length}/${current.checks.length}`);
  }
} catch (error) {
  console.error(`[G0-RS-P4] FAIL — ${error.message}`);
  process.exitCode = 1;
}

#!/usr/bin/env node

/**
 * G0-RS-P4R-0 验收 — Truth Baseline 与预算冻结。
 *
 * 证据类型：一次性隔离环境中的真实 `run_tool → tool_job → artifact truth` 语料 +
 * 真实服务器请求瀑布 + 10ms 分辨率事件循环直方图。**不包含**客户端指标：仓库内
 * 没有浏览器自动化，因此首屏内容可见、Artifact 切换、版本切换与代码打开一律记为
 * 未捕获，不做估算。`qualificationEligible` 恒为 false。
 *
 * `passed` 的语义是「P4R-0 交付了有效基线并冻结了预算」，**不是**「性能达标」。
 * 当前实现实测违反 250ms 事件循环预算，这一事实由 budgetStatus 显式记录，
 * 并且是 P4R-1 必须修复的对象。
 *
 * 断言原则：只断言可从真实源码与真实测量读出的事实，不接受人工布尔值。
 */

import { createHash } from 'node:crypto';
import { execFileSync, spawnSync } from 'node:child_process';
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { homedir } from 'node:os';
import { createRequire } from 'node:module';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import { captureBaseline } from './g0-rs-p4r-baseline.mjs';
import { ISOLATED_PATH_ENV, assertIsolated } from './g0-rs-p4r-capture.mjs';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const evidencePath = join(root, 'acceptance/g0-result-studio/rs-p4r-performance.json');
const read = (file) => readFileSync(join(root, file), 'utf8');
const sha = (value) => createHash('sha256').update(String(value)).digest('hex');
const git = (...args) => execFileSync('git', args, { cwd: root, encoding: 'utf8' }).trim();
const item = (id, passed, evidence, detail) => ({ id, passed: passed === true, evidence, detail });

const sourceFiles = {
  probe: 'core/petri-server/helpers/perf-probe.js',
  probeRoutes: 'core/petri-server/routes/perf-probe.js',
  bootstrap: 'core/petri-server/bootstrap.js',
  routes: 'core/petri-server/routes/result-studio.js',
  background: 'core/shared-backend/result-studio-background.js',
  backgroundChild: 'core/shared-backend/result-studio-background-child.js',
  capture: 'scripts/g0-rs-p4r-capture.mjs',
  corpus: 'scripts/g0-rs-p4r-corpus.mjs',
  baseline: 'scripts/g0-rs-p4r-baseline.mjs',
  probeTest: 'test/perf-probe.test.mjs',
  captureTest: 'test/p4r-capture.test.mjs',
  baselineTest: 'test/p4r-baseline.test.mjs',
  invariantTest: 'test/p4r-invariants.test.mjs',
  backgroundTest: 'test/result-studio-background.test.mjs',
  impactMap: 'test/impact-map.json',
  packageScripts: 'package.json',
  acceptanceScript: 'scripts/g0-rs-p4r-acceptance.mjs',
};

function sourceCommitStatus(commit, hashes) {
  if (!commit || spawnSync('git', ['merge-base', '--is-ancestor', commit, 'HEAD'], { cwd: root }).status !== 0) {
    return { reachable: false, mismatches: Object.values(sourceFiles) };
  }
  const mismatches = Object.entries(sourceFiles).flatMap(([key, file]) => {
    const result = spawnSync('git', ['show', `${commit}:${file}`], { cwd: root, encoding: 'utf8' });
    return result.status === 0 && sha(result.stdout) === hashes[key] ? [] : [file];
  });
  return { reachable: true, mismatches };
}

/**
 * Frozen budgets.
 *
 * Only the plan's own product contracts are frozen here. The plan also asks for
 * per-artifact-size first-content and version-switch thresholds "written from
 * real sampling", but sampling the CURRENT implementation would enshrine the
 * defect P4R-1 exists to remove — the measured secondary path is already an
 * order of magnitude over the block budget. Those thresholds are therefore
 * deferred to P4R-1, when a fast path exists to sample. Deferring is recorded
 * explicitly; it is not a silent omission, and it is not a loosening.
 */
const BUDGETS = Object.freeze({
  eventLoopMaxMs: {
    value: 250,
    source: 'G0-RS-P4R-0 plan: no synchronous Result Studio block may exceed 250ms',
    signal: 'perf-probe eventLoop.maxMs (monitorEventLoopDelay, 10ms resolution)',
    // server.js's tick sampler runs at 1Hz and only warns above 2000ms, so it
    // cannot resolve or attribute a 250ms block. The histogram is authoritative.
    rejectedSignal: 'server.js startEventLoopMonitor tick sampler (1Hz, 2000ms threshold)',
    machineVerifiable: true,
  },
  visibleFeedbackMs: {
    value: 100,
    source: 'G0-RS-P4R-0 plan: visible feedback within 100ms of a result click',
    signal: 'client-side; no producer exists in this repository',
    machineVerifiable: false,
    status: 'frozen_target_not_yet_measurable',
  },
});

const DEFERRED_BUDGETS = Object.freeze({
  firstContentBySizeMs: 'deferred_to_G0-RS-P4R-1: sampling the pre-fast-path implementation would freeze the defect as the standard',
  versionSwitchMs: 'unmeasured_not_captured_no_browser_automation_in_repo',
  codeOpenMs: 'unmeasured_not_captured_no_browser_automation_in_repo',
});

/**
 * The P4R-0 baseline, frozen as a CONSTANT.
 *
 * A baseline is a record of how the system behaved at a moment, so it must not
 * be re-measured. Until this was added, `--write-evidence` re-ran the capture
 * and overwrote these numbers, and the gate stayed green while doing it — so
 * running the documented update command after a P4R-1 optimisation would have
 * silently destroyed the evidence that the optimisation improved anything.
 * That is the same shape as the defects this stage spent its time removing: an
 * operation that looks routine and quietly erases the thing it reports on.
 *
 * Captured at e1f841c8, revisionCount 1, on an idle machine
 * (gitSpawnMedianMs 9.559, not under npm). Later runs re-measure into
 * `currentObservation` and are compared against this; they never replace it.
 */
export const FROZEN_BASELINE = Object.freeze({
    "capturedAtCommit": "e1f841c8ada919250c01f5cde76586ef2375bdc6",
    "revisionCount": 1,
    "calibration": {
      "gitSpawnMedianMs": 9.559,
      "pathEntries": 31,
      "invokedUnderNpm": false
    },
    "requests": [
      {
        "id": "job-status",
        "role": "render-blocking",
        "status": 200,
        "coldMs": 5.492,
        "warmMs": 2.229,
        "oneTimeCostMs": 3.263
      },
      {
        "id": "artifact-bytes",
        "role": "render-blocking",
        "status": 200,
        "coldMs": 5.043,
        "warmMs": 2.174,
        "oneTimeCostMs": 2.869
      },
      {
        "id": "interaction",
        "role": "secondary",
        "status": 200,
        "coldMs": 389.139,
        "warmMs": 9.9,
        "oneTimeCostMs": 379.239
      },
      {
        "id": "context-envelope",
        "role": "secondary",
        "status": 409,
        "coldMs": 4.235,
        "warmMs": 1.719,
        "oneTimeCostMs": 2.516
      },
      {
        "id": "changesets",
        "role": "secondary",
        "status": 200,
        "coldMs": 45.73,
        "warmMs": 42.102,
        "oneTimeCostMs": 3.628
      },
      {
        "id": "workspace-status",
        "role": "secondary",
        "status": 200,
        "coldMs": 64.925,
        "warmMs": 64.862,
        "oneTimeCostMs": 0.063
      }
    ],
    "eventLoop": {
      "resolutionMs": 10,
      "samples": 16,
      "minMs": 9.839,
      "meanMs": 58.073,
      "maxMs": 394.265,
      "percentilesOmitted": "sample count too low for p95/p99 to be meaningful"
    }
  });

/** Routes whose real cost the baseline must have measured. */
const MUST_BE_MEASURED = ['job-status', 'artifact-bytes', 'interaction', 'changesets', 'workspace-status'];

function sourceHashes() {
  return Object.fromEntries(Object.entries(sourceFiles).map(([key, file]) => [key, sha(read(file))]));
}

function runCommands() {
  const commands = [
    ['probe-and-harness', 'node', ['--test',
      'test/perf-probe.test.mjs',
      'test/p4r-capture.test.mjs',
      'test/p4r-baseline.test.mjs',
      'test/result-studio-background.test.mjs',
    ]],
    ['impact-map', 'node', ['--test', 'test/test-affected.test.mjs']],
    ['syntax', 'node', ['--check', 'scripts/g0-rs-p4r-acceptance.mjs']],
  ];
  return commands.map(([label, bin, args]) => {
    const result = spawnSync(bin, args, { cwd: root, encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 });
    return {
      label,
      command: [bin, ...args].join(' '),
      exitCode: result.status,
      passed: result.status === 0,
      stdoutSha256: sha(result.stdout || ''),
      stderrSha256: sha(result.stderr || ''),
    };
  });
}

/** Reduce a raw capture into the bounded, redacted observation stored as evidence. */
function toObservation(capture) {
  const byId = new Map(capture.requests.map((request) => [request.id, request]));
  const renderBlocking = capture.requests.filter((request) => request.role === 'render-blocking');
  return {
    captureMode: 'real_run_tool_chain_in_disposable_root_with_env_gated_probe',
    calibration: capture.calibration,
    revisionCount: capture.revisionCount ?? null,
    scalingNote: 'workspace-status is linear in revisionCount. This capture is the cheapest case; the route grows and crosses the frozen 250ms budget well before the 5000-revision cap. P4R-1 must re-capture with revisionCount swept before choosing any cache key.',
    corpus: capture.corpus.map(({ toolId, durationMs, artifactCount }) => ({ toolId, durationMs, artifactCount })),
    requests: capture.requests.map(({ id, role, status, totalMs, coldMs, warmMs, warmSamplesMs, warmSpreadMs, oneTimeCostMs, bytes }) =>
      ({ id, role, status, totalMs, coldMs, warmMs, warmSamplesMs, warmSpreadMs, oneTimeCostMs, bytes })),
    renderBlockingTotalMs: Number(renderBlocking.reduce((sum, request) => sum + request.totalMs, 0).toFixed(3)),
    slowestRequest: capture.requests.reduce((worst, request) => (request.totalMs > (worst?.totalMs ?? -1) ? request : worst), null)?.id ?? null,
    // p95/p99 are dropped deliberately: these runs record ~17 samples, at which
    // percentile(99) returns max exactly, so publishing them invents precision.
    // Report the sample count and the peak, and let the reader judge.
    eventLoop: capture.eventLoop
      ? {
        resolutionMs: capture.eventLoop.resolutionMs,
        samples: capture.eventLoop.samples,
        minMs: capture.eventLoop.minMs,
        meanMs: capture.eventLoop.meanMs,
        maxMs: capture.eventLoop.maxMs,
        percentilesOmitted: 'sample count too low for p95/p99 to be meaningful',
      }
      : null,
    unmeasured: [
      ...Object.entries(capture.clientMetrics).map(([key, metric]) => ({ metric: key, reason: metric.status })),
      // Recorded so the gap cannot be mistaken for a measured zero.
      { metric: 'context-envelope', reason: `route returned ${byId.get('context-envelope')?.status ?? 'unknown'}; excluded from the baseline` },
    ],
  };
}

/**
 * Exercise the isolation list instead of reading its source.
 *
 * Deleting the real keys from ISOLATED_PATH_ENV must fail this. The previous
 * source-regex version stayed green because the same variable names appear in
 * the capture script's own doc comment.
 */
function probeIsolationBehaviour() {
  const REQUIRED = [
    'PETRI_DB_PATH', 'PETRI_TEMP_DIR', 'PETRI_LOCAL_RESULTS_DIR', 'PETRI_LOCAL_UPLOADS_DIR',
    'PETRI_LOCAL_DATA_DIR', 'PETRI_PLUGINS_DIR', 'PETRI_HARNESS_LOCAL_ROOT',
  ];
  const allGuarded = REQUIRED.every((key) => key in ISOLATED_PATH_ENV);
  const fakeRoot = '/tmp/petri-acceptance-probe';
  const env = Object.fromEntries(
    Object.entries(ISOLATED_PATH_ENV).map(([key, leaf]) => [key, join(fakeRoot, leaf)]),
  );
  let rejectsRealDataRoot = false;
  try {
    assertIsolated({ ...env, PETRI_LOCAL_DATA_DIR: join(homedir(), 'Documents', 'Petri-Local') }, fakeRoot);
  } catch {
    rejectsRealDataRoot = true;
  }
  return { allGuarded, rejectsRealDataRoot };
}

/** Exercise the probe rather than grepping it: off by default, real samples when armed. */
function probeBehaviourCheck() {
  const perfProbe = createRequire(import.meta.url)(join(root, 'core/petri-server/helpers/perf-probe.js'));
  const hadFlag = process.env.PETRI_PERF_PROBE;
  delete process.env.PETRI_PERF_PROBE;
  perfProbe.disableProbe();
  const offByDefault = perfProbe.enableProbe() === false
    && perfProbe.snapshotProbe().enabled === false;

  perfProbe.enableProbe({ force: true });
  const snapshot = perfProbe.snapshotProbe();
  const resolutionMs = snapshot.eventLoop ? snapshot.eventLoop.resolutionMs : null;
  // An unsampled histogram must report null rather than its int64 sentinel.
  const reportsRealSamples = snapshot.eventLoop !== null
    && (snapshot.eventLoop.samples === 0 ? snapshot.eventLoop.maxMs === null : true);
  perfProbe.disableProbe();
  if (hadFlag !== undefined) process.env.PETRI_PERF_PROBE = hadFlag;
  return { offByDefault, resolutionMs, reportsRealSamples };
}

/** Run the invariant suite and parse its real outcome. */
function runInvariantSuite() {
  const result = spawnSync('node', ['--test', sourceFiles.invariantTest], {
    cwd: root, encoding: 'utf8', maxBuffer: 64 * 1024 * 1024,
  });
  const out = `${result.stdout || ''}\n${result.stderr || ''}`;
  const num = (label) => {
    const match = new RegExp(`^# ${label} (\\d+)$`, 'm').exec(out);
    return match ? Number(match[1]) : Number((new RegExp(`\u2139 ${label} (\\d+)`).exec(out) || [])[1] ?? NaN);
  };
  const total = num('tests');
  const passed = num('pass');
  const failed = num('fail');
  const skipped = num('skipped');
  return {
    passed,
    failed,
    skipped,
    total,
    skipGuardObserved: skipped === 0 || out.includes('[p4r-invariants] invariant coverage SKIPPED:'),
  };
}

/** Compare a fresh measurement against the frozen baseline, warm path only. */
function compareToBaseline(observation) {
  const baseline = new Map(FROZEN_BASELINE.requests.map((r) => [r.id, r]));
  return (observation?.requests || [])
    .filter((r) => r.status === 200 && Number.isFinite(r.warmMs))
    .map((r) => {
      const was = baseline.get(r.id);
      if (!was || !Number.isFinite(was.warmMs)) return { id: r.id, baselineWarmMs: null, currentWarmMs: r.warmMs };
      return {
        id: r.id,
        baselineWarmMs: was.warmMs,
        currentWarmMs: r.warmMs,
        deltaPct: Number((((r.warmMs - was.warmMs) / was.warmMs) * 100).toFixed(1)),
      };
    });
}

function inspect(verification, observation) {
  const capture = read(sourceFiles.capture);
  const corpus = read(sourceFiles.corpus);
  const baseline = read(sourceFiles.baseline);
  const probe = read(sourceFiles.probe);
  const commands = verification?.commands || [];

  const isolationBehaviour = probeIsolationBehaviour();
  const probeBehaviour = probeBehaviourCheck();
  const invariantRun = runInvariantSuite();
  const packageScripts = JSON.parse(read('package.json')).scripts || {};
  const byId = new Map((observation?.requests || []).map((request) => [request.id, request]));
  const measuredAll = MUST_BE_MEASURED.every((id) => byId.get(id)?.status === 200);
  const eventLoop = observation?.eventLoop || {};
  const budgetMet = Number.isFinite(eventLoop.maxMs) && eventLoop.maxMs <= BUDGETS.eventLoopMaxMs.value;
  const requests = observation?.requests || [];
  // A route is one-time dominated when most of its first-call cost disappears on
  // the second call; optimising it would not change steady-state viewing.
  const oneTimeDominated = requests.filter((r) => Number.isFinite(r.oneTimeCostMs)
    && Number.isFinite(r.coldMs) && r.coldMs > 0 && r.oneTimeCostMs / r.coldMs >= 0.5);
  const steadyStateWorst = requests
    .filter((r) => Number.isFinite(r.warmMs))
    .reduce((worst, r) => (r.warmMs > (worst?.warmMs ?? -1) ? r : worst), null);

  const checks = [
    item('RS-P4R0-1',
      Array.isArray(observation?.corpus) && observation.corpus.length >= 3
      && observation.corpus.every((step) => step.artifactCount > 0),
      [sourceFiles.corpus],
      'Baseline corpus was produced by real run_tool -> tool_job -> artifact truth runs, not a database seed.'),

    item('RS-P4R0-2', measuredAll,
      [sourceFiles.baseline, sourceFiles.baselineTest],
      'Every route the baseline must measure returned 200, so the timings are the real path and not argument validation.'),

    item('RS-P4R0-3',
      Number.isFinite(eventLoop.maxMs) && Number(eventLoop.samples) > 0,
      [sourceFiles.probe],
      'Event-loop delay came from a real histogram sample, not the empty-histogram sentinel.'),

    // Was `BUDGETS.x.signal.includes('monitorEventLoopDelay')` — a constant
    // asserted against itself. Now exercises the probe: a live histogram must
    // report a real resolution and real samples.
    item('RS-P4R0-4',
      probeBehaviour.resolutionMs === 10 && probeBehaviour.reportsRealSamples === true,
      [sourceFiles.probe],
      'The authoritative >250ms signal is declared as the 10ms-resolution histogram; the 1Hz tick sampler is explicitly rejected as unable to resolve it.'),

    item('RS-P4R0-5',
      Array.isArray(observation?.unmeasured) && observation.unmeasured.length > 0
      && observation.unmeasured.every((entry) => typeof entry.reason === 'string' && entry.reason.length > 0),
      [sourceFiles.baseline],
      'Metrics with no producer are recorded as unmeasured with a stated reason, never estimated or defaulted to zero.'),

    // Was five regexes over scripts/g0-rs-p4r-capture.mjs. All three variable
    // names also appear in that file's own doc comment, so deleting the real
    // keys from ISOLATED_PATH_ENV left this green while its claim became false.
    // Now imports the list and exercises the guard.
    item('RS-P4R0-6', isolationBehaviour.allGuarded === true && isolationBehaviour.rejectsRealDataRoot === true,
      [sourceFiles.capture, sourceFiles.captureTest],
      'Every writable path is redirected and guarded from one declared list, so a capture cannot reach the developer database or the real user data root.'),

    item('RS-P4R0-7', probeBehaviour.offByDefault === true,
      [sourceFiles.probe, sourceFiles.probeRoutes],
      'The probe is env-gated: with the flag unset every export is a no-op and the /api/__perf surface is not mounted.'),

    // A grep for 'createProject' matched this script's own prose too. The
    // measurement itself proves it: without an owned project every
    // result-studio route rejects, so 200s ARE the evidence.
    item('RS-P4R0-8',
      MUST_BE_MEASURED.filter((id) => id.startsWith('changesets') || id.startsWith('workspace'))
        .every((id) => byId.get(id)?.status === 200),
      [sourceFiles.corpus],
      'The corpus creates and owns a real project, without which every Result Studio route rejects and the baseline would time validation.'),

    item('RS-P4R0-11',
      requests.length > 0
      && requests.filter((r) => r.status === 200).every((r) => Number.isFinite(r.coldMs) && Number.isFinite(r.warmMs)),
      [sourceFiles.baseline],
      'Every measured route records both a first-call and a second-call timing, so one-time creation cost cannot be reported as steady-state viewing cost.'),

    // Was three literal greps, all of which also occur in that file's comments,
    // so deleting every assertion kept this green. P4R-0 then deliberately
    // required a red invariant owned by a later phase. P4R-5 has now closed the
    // final source/replay invariant, so the durable contract is the opposite:
    // no failures, the full current suite accounted for, and any runtime skip
    // must be surfaced by the suite's explicit skip guard.
    item('RS-P4R0-12',
      invariantRun.total >= 8
      && invariantRun.failed === 0
      && invariantRun.passed + invariantRun.skipped === invariantRun.total
      && invariantRun.passed >= 1
      && invariantRun.skipGuardObserved === true,
      [sourceFiles.invariantTest],
      'The P4R invariants run against code reality with no failures. All current tests are accounted for; if the R runtime is unavailable, only the suite\'s explicit and visible skip guard may permit the bounded skip.'),

    // Fails if the frozen baseline is edited to match a later measurement.
    // A baseline that drifts toward the present proves nothing.
    item('RS-P4R0-13',
      FROZEN_BASELINE.capturedAtCommit === 'e1f841c8ada919250c01f5cde76586ef2375bdc6'
      && FROZEN_BASELINE.revisionCount === 1
      && (FROZEN_BASELINE.requests.find((r) => r.id === 'workspace-status') || {}).warmMs === 64.862
      && (FROZEN_BASELINE.requests.find((r) => r.id === 'changesets') || {}).warmMs === 42.102,
      [sourceFiles.acceptanceScript],
      'The P4R-0 baseline is a frozen constant, not a re-measured value. Its numbers are pinned so a later run cannot quietly replace the record it exists to preserve.'),

    item('RS-P4R0-9', commands.length >= 3 && commands.every((command) => command.passed),
      [evidencePath.replace(`${root}/`, '')],
      'All declared P4R-0 command gates passed.'),

    // Checks the recorded commands, not this file's own source: an earlier
    // version grepped the script for the pattern and matched the check's own
    // code, which is a self-referential assertion rather than a real one.
    // Reads package.json rather than this script's own command literals: the
    // vacuous-gate class lives in the npm scripts, so that is what must be checked.
    item('RS-P4R0-10',
      commands.length > 0
      && commands.every((command) => !/\bnpm test\b/.test(command.command))
      && Object.values(packageScripts).every((value) => !/npm test --prefix frontend/.test(String(value))),
      [evidencePath.replace(`${root}/`, ''), 'package.json'],
      'No recorded gate invokes bare `npm test`, which under a file filter resolves to `vitest run --changed`, selects nothing and reports success for a zero-test run.'),

    item('RS-P4R6-1',
      budgetMet
      && Number(eventLoop.maxMs) <= BUDGETS.eventLoopMaxMs.value
      && byId.get('interaction')?.status === 200
      && byId.get('workspace-status')?.status === 200,
      [sourceFiles.routes, sourceFiles.background, sourceFiles.backgroundChild, sourceFiles.backgroundTest],
      'P4R-6 closes the frozen event-loop budget on the real cold/warm chain: canonical baseline materialization and workspace inspection may complete asynchronously, but neither may block the Express event loop above 250ms.'),
  ];

  return {
    schemaVersion: 1,
    workPackage: 'G0-RS-P4R-0/P4R-6',
    sourceCommit: git('rev-parse', 'HEAD'),
    captureMode: 'real_chain_corpus_plus_server_request_waterfall_and_event_loop_histogram_in_disposable_root',
    qualificationEligible: false,
    qualificationReason: 'P4R-6 closes the frozen server event-loop budget using the canonical Git/SQLite services in an isolated background process. Client layout and journey evidence is separate, and Provider/packaged Result Studio qualification remains reserved for P7.',
    privacy: 'repository_relative_paths_digests_counts_timings_and_bounded_statuses_only_no_project_job_conversation_selection_url_credential_prompt_or_result_data',
    sourceHashes: sourceHashes(),
    budgets: BUDGETS,
    deferredBudgets: DEFERRED_BUDGETS,
    // The frozen record and a fresh measurement, kept apart on purpose. Only
    // `currentObservation` moves; `frozenBaseline` is a constant in this file.
    frozenBaseline: FROZEN_BASELINE,
    baselineObservation: observation,
    improvementVsBaseline: compareToBaseline(observation),
    budgetStatus: {
      eventLoopMaxMs: budgetMet ? 'met' : 'violated_by_current_implementation',
      observedMaxMs: eventLoop.maxMs ?? null,
      attributedTo: observation?.slowestRequest ?? null,
      // The first version of this evidence attributed the whole peak to
      // `interaction` without noting that its first call lazily creates a
      // ChangeSet, writes .petri/revision/ and makes a Git commit. Measuring a
      // second pass separates one-time creation from what every view pays, and
      // that distinction decides what P4R-1 should actually optimise.
      steadyStateWorstMs: steadyStateWorst?.warmMs ?? null,
      steadyStateWorstRoute: steadyStateWorst?.id ?? null,
      oneTimeDominated: oneTimeDominated.map((r) => r.id),
      note: budgetMet
        ? 'Current implementation is within the frozen block budget.'
        : 'The frozen 250ms budget is exceeded by the current implementation. This is the P4R-0 finding, not a P4R-0 failure: P4R-1 owns the fix. The budget must not be raised to accommodate it.',
      // Honesty about the instrument, not just the reading. Absolute timings on
      // this harness are load-sensitive: the same capture produced a 383ms cold
      // interaction on an idle machine and 4072ms immediately after several
      // back-to-back DESeq2 runs, with tight within-run spreads either way. What
      // is stable across every observation is the STRUCTURE below, and the
      // violation conclusion holds at both ends of the observed range, since even
      // the cleanest run exceeds 250ms.
      absoluteTimingsAreLoadSensitive: true,
      observedColdRangeMsAcrossRuns: [383.491, 4072.669],
      loadSensitivityCause: 'Absolute request completion varies with R/Git process scheduling and host load. P4R-6 therefore freezes the 250ms budget on attributed event-loop blocking, while preserving cold/warm request completion separately; no request duration is re-labelled as event-loop delay.',
      violationRobustAtRangeFloor: !budgetMet,
      structuralFinding: 'Cold Interaction baseline materialization remains a one-time asynchronous secondary completion; workspace/status remains a recurring asynchronous inspection. The main thread stays responsive while both reuse the canonical Git/SQLite services.',
      violationAttribution: budgetMet
        ? 'No current Result Studio synchronous task violated the frozen 250ms event-loop budget in this source-bound observation.'
        : 'The current source-bound observation still violates the frozen event-loop budget and P4R-6 cannot close.',
    },
    checks,
    verification,
    // No hand-written invariant booleans. This script's own stated principle
    // rejects manual assertions, and six unchecked booleans (secondExecutorCreated,
    // developerDatabaseTouched, ...) had no check behind them and were referenced
    // by none of the checks. What is actually verified lives in checks[].
    executionTruth: 'run_tool -> tool_job -> artifact_truth',
    passed: checks.every((check) => check.passed),
  };
}

// Guarded: this module also exports FROZEN_BASELINE, and importing that must
// not run the gate. Without this, importing the constant regenerated this very
// evidence file as a side effect of another script starting up.
const invokedDirectly = process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1];

try {
  if (!invokedDirectly) {
    // imported for FROZEN_BASELINE only
  } else if (process.argv.includes('--write-evidence')) {
    const capture = await captureBaseline({ quiet: true });
    const observation = toObservation(capture);
    const verification = { generatedAt: new Date().toISOString(), commands: runCommands() };
    const report = { ...inspect(verification, observation), generatedAt: verification.generatedAt, privacyClean: true };
    const commitStatus = sourceCommitStatus(report.sourceCommit, report.sourceHashes);
    report.sourceCommitReachable = commitStatus.reachable;
    report.sourceCommitMatchesSourceHashes = commitStatus.reachable && commitStatus.mismatches.length === 0;
    report.sourceCommitMismatches = commitStatus.mismatches;
    if (!report.sourceCommitMatchesSourceHashes) throw new Error(`source commit mismatch: ${commitStatus.mismatches.join(',')}`);
    if (!report.passed) throw new Error(report.checks.filter((check) => !check.passed).map((check) => check.id).join(','));
    mkdirSync(dirname(evidencePath), { recursive: true });
    writeFileSync(evidencePath, `${JSON.stringify(report, null, 2)}\n`);
    console.log(`[G0-RS-P4R-0] PASS — evidence updated (${report.checks.length}/${report.checks.length})`);
    console.log(`[G0-RS-P4R-0] budget ${report.budgetStatus.eventLoopMaxMs}: observed ${report.budgetStatus.observedMaxMs}ms against a frozen ${BUDGETS.eventLoopMaxMs.value}ms`);
  } else {
    if (!existsSync(evidencePath)) throw new Error('evidence missing; run npm run g0:result-studio:p4r:update');
    const stored = JSON.parse(readFileSync(evidencePath, 'utf8'));
    const current = inspect(stored.verification, stored.baselineObservation);
    const commitStatus = sourceCommitStatus(stored.sourceCommit, stored.sourceHashes || {});
    if (!stored.passed || !current.passed || !stored.sourceCommitMatchesSourceHashes
      || !commitStatus.reachable || commitStatus.mismatches.length > 0
      || JSON.stringify(stored.sourceHashes) !== JSON.stringify(current.sourceHashes)) {
      throw new Error('stored G0-RS-P4R-0 evidence is stale or invalid');
    }
    // A stored budget that was quietly raised is exactly the failure the plan
    // forbids, so the frozen values are re-verified rather than trusted.
    if (JSON.stringify(stored.budgets) !== JSON.stringify(BUDGETS)) {
      throw new Error('frozen G0-RS-P4R-0 budgets were modified; they must not be loosened to obtain a pass');
    }
    console.log(`[G0-RS-P4R-0] PASS — ${current.checks.length}/${current.checks.length} (budget ${stored.budgetStatus.eventLoopMaxMs}, observed ${stored.budgetStatus.observedMaxMs}ms)`);
  }
} catch (error) {
  console.error(`[G0-RS-P4R-0] FAIL — ${error.message}`);
  process.exitCode = 1;
}

#!/usr/bin/env node
/**
 * G0-RS-P4R-0 — machine-capture the real open-result baseline.
 *
 * Composes the three pieces P4R-0 needs into one measurement:
 *
 *   g0-rs-p4r-corpus.mjs    real artifacts via run_tool -> tool_job -> artifact truth
 *   g0-rs-p4r-capture.mjs   disposable root + the env-gated probe from 340c09a
 *   this script             drives the request waterfall and records timings
 *
 * The corpus and the server share ONE disposable root, so the server serves real
 * artifacts from real jobs rather than a seeded fixture.
 *
 * WHAT THIS DOES AND DOES NOT MEASURE. Server-side timings are real: per-request
 * duration, the ordering of the waterfall, and event-loop delay from
 * monitorEventLoopDelay at 10ms resolution. Client-side metrics — first content
 * visible, artifact switch, version switch — are NOT captured, because the repo
 * has no browser automation. They are reported as null with an explicit status
 * rather than estimated, following the RS-P1 precedent.
 *
 * The authoritative signal for the plan's ">250ms synchronous block" gate is
 * eventLoop.maxMs from the probe histogram. The tick sampler in server.js
 * samples at 1Hz and only warns above 2000ms, so it cannot resolve 250ms; its
 * blocks[] output is recorded for context but is not the gate.
 *
 * Usage:
 *   node scripts/g0-rs-p4r-baseline.mjs
 *   node scripts/g0-rs-p4r-baseline.mjs --json
 *   node scripts/g0-rs-p4r-baseline.mjs --keep --verbose
 */

import { existsSync, mkdtempSync, rmSync } from 'node:fs';
import { createRequire } from 'node:module';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { pathToFileURL } from 'node:url';

import {
  createCaptureEnv,
  resetProbe,
  snapshotProbe,
  startServer,
  stopServer,
} from './g0-rs-p4r-capture.mjs';
import { generateCorpus } from './g0-rs-p4r-corpus.mjs';
import { buildPackEnv } from './g0-rs-p4r-pack.mjs';

const require = createRequire(import.meta.url);

/** How many revisions the sampled workspace held. workspace-status scales with it. */
function countRevisions(dbPath) {
  try {
    const Database = require(require.resolve('better-sqlite3', {
      paths: [path.join(path.dirname(fileURLToPath(import.meta.url)), '..', 'core', 'petri-server')],
    }));
    const db = new Database(dbPath, { readonly: true });
    try {
      const t = db.prepare("select name from sqlite_master where type='table' and name='artifact_revisions'").get();
      return t ? db.prepare('select count(*) c from artifact_revisions').get().c : null;
    } finally { db.close(); }
  } catch { return null; }
}

/**
 * The requests a result open actually issues, in the order the frontend fires
 * them. Sourced from the frontend survey: /tools/status is render-blocking for
 * every body because selectedArtifact derives from it; the rest are secondary
 * and must not block the body, which is what P4R-1 has to prove.
 */
const WATERFALL = [
  { id: 'job-status', role: 'render-blocking', path: ({ jobId }) => `/api/tools/status/${jobId}` },
  { id: 'artifact-bytes', role: 'render-blocking', path: ({ jobId, artifact }) => `/api/tools/file/${jobId}/${artifact}` },
  { id: 'interaction', role: 'secondary', path: ({ jobId, artifact }) => `/api/result-studio/interaction?jobId=${jobId}&artifact=${encodeURIComponent(artifact)}` },
  { id: 'context-envelope', role: 'secondary', path: ({ projectId }) => `/api/result-studio/context-envelope?projectId=${projectId ?? ''}` },
  { id: 'changesets', role: 'secondary', path: ({ projectId }) => `/api/result-studio/changesets?projectId=${projectId ?? ''}` },
  { id: 'workspace-status', role: 'secondary', path: ({ projectId }) => `/api/result-studio/workspace/status?projectId=${projectId ?? ''}` },
];

/** Client metrics the plan asks for that no tooling in this repo can capture. */
/** Steady-state passes after the cold one. Odd, so the median is a real sample. */
const WARM_PASSES = 3;

const UNCAPTURED_CLIENT_METRICS = [
  'firstContentVisibleMs',
  'artifactSwitchMs',
  'versionSwitchMs',
  'codeOpenMs',
];

async function timeRequest(baseUrl, url) {
  const startedAt = process.hrtime.bigint();
  let status = null;
  let bytes = null;
  let error = null;
  try {
    const response = await fetch(`${baseUrl}${url}`);
    status = response.status;
    bytes = (await response.arrayBuffer()).byteLength;
  } catch (e) {
    error = e.message;
  }
  return {
    url,
    status,
    bytes,
    error,
    totalMs: Number(Number(process.hrtime.bigint() - startedAt) / 1e6).toFixed(3) * 1,
  };
}

/**
 * Drive the waterfall serially, twice.
 *
 * The two passes are NOT redundant. `/api/result-studio/interaction` does real
 * work on first touch of an artifact: it lazily creates a ChangeSet, writes into
 * `.petri/revision/`, makes a Git commit on a new branch, inserts an
 * ArtifactRevision and adopts it. Reporting only the first call attributes
 * one-time creation cost to steady-state viewing, which is what an earlier
 * version of this baseline did.
 *
 * Serial rather than concurrent is the honest lower bound: it measures each
 * request's own cost without contention. Contention is what the event-loop
 * histogram captures alongside it.
 */
async function driveWaterfall(baseUrl, target) {
  const cold = [];
  for (const step of WATERFALL) {
    cold.push({ id: step.id, role: step.role, ...(await timeRequest(baseUrl, step.path(target))) });
  }
  // Steady state is sampled more than once. A single sample is cheap to
  // contaminate: an otherwise identical run taken straight after another
  // process reported a 4020ms event-loop peak against a ~450ms cluster from
  // three clean sequential runs. The median of several passes is what gets
  // recorded; the spread is recorded too, so contamination stays visible
  // instead of silently becoming the number.
  const warmSamples = new Map(WATERFALL.map((step) => [step.id, []]));
  for (let pass = 0; pass < WARM_PASSES; pass += 1) {
    for (const step of WATERFALL) {
      const timing = await timeRequest(baseUrl, step.path(target));
      warmSamples.get(step.id).push({ ms: timing.totalMs, status: timing.status });
    }
  }

  return cold.map((request) => {
    const samples = warmSamples.get(request.id) || [];
    const values = samples.map((s) => s.ms).filter(Number.isFinite).sort((a, b) => a - b);
    const median = values.length ? values[Math.floor(values.length / 2)] : null;
    return {
      ...request,
      coldMs: request.totalMs,
      warmMs: median,
      warmSamplesMs: values,
      warmSpreadMs: values.length ? Number((values[values.length - 1] - values[0]).toFixed(3)) : null,
      warmStatus: samples[0]?.status ?? null,
      // A large gap means the first call did one-time work; a flat profile means
      // the cost is inherent to every view.
      oneTimeCostMs: Number.isFinite(median)
        ? Number((request.totalMs - median).toFixed(3))
        : null,
    };
  });
}

/**
 * Calibrate the instrument before trusting its readings.
 *
 * Process-spawn cost is not a constant of this machine — it depends on the PATH
 * the capture inherits. Measured here: `git --version` costs ~9.7ms with a
 * 31-entry PATH and ~122.5ms with the 40-entry PATH that `npm run` injects, a
 * 12.6x difference that propagates straight into any git-touching route because
 * detectGitRuntime() is documented as uncached and re-resolves per call.
 *
 * That is why an identical capture read 412ms invoked directly and 4028ms
 * through `npm run`. Recording the calibration makes a reading interpretable and
 * comparable across environments instead of silently invocation-dependent.
 */
async function calibrateSpawnCost() {
  const { execFileSync } = await import('node:child_process');
  const samples = [];
  for (let i = 0; i < 5; i += 1) {
    const startedAt = process.hrtime.bigint();
    try {
      execFileSync('git', ['--version'], { encoding: 'utf8' });
      samples.push(Number(Number(process.hrtime.bigint() - startedAt) / 1e6));
    } catch {
      return { gitSpawnMedianMs: null, pathEntries: (process.env.PATH || '').split(path.delimiter).length };
    }
  }
  samples.sort((a, b) => a - b);
  return {
    gitSpawnMedianMs: Number(samples[Math.floor(samples.length / 2)].toFixed(3)),
    pathEntries: (process.env.PATH || '').split(path.delimiter).length,
    invokedUnderNpm: Boolean(process.env.npm_lifecycle_event),
  };
}

export async function captureBaseline({ keep = false, quiet = false, onLog } = {}) {
  const root = mkdtempSync(path.join(tmpdir(), 'petri-p4r-baseline-'));
  let server = null;

  try {
    // 1. Real artifacts in this root.
    const corpus = await generateCorpus({ root, keep: true, quiet, onLog });
    if (!corpus.ok) throw new Error(`corpus generation failed: ${JSON.stringify(corpus.records)}`);

    // 2. Boot the server against the same root, with the probe armed.
    const { env } = createCaptureEnv({ port: 0, root });
    // BLOCK-83/86 package awareness: same pack sources as the corpus child.
    Object.assign(env, buildPackEnv({ captureRoot: root, toolIds: corpus.pack.stagedToolIds }).env);
    const port = await import('node:net').then(({ createServer }) => new Promise((resolve, reject) => {
      const probe = createServer();
      probe.on('error', reject);
      probe.listen(0, '127.0.0.1', () => {
        const { port: p } = probe.address();
        probe.close(() => resolve(p));
      });
    }));
    env.R_SERVER_PORT = String(port);
    server = await startServer(env, { onLog });

    // 3. Measure from a clean probe window.
    await resetProbe(server.baseUrl);
    const deseq2 = corpus.records.find((record) => record.id === 'deseq2');
    const target = {
      jobId: deseq2.toolJobId,
      artifact: 'volcano.png',
      projectId: corpus.projectId,
    };
    const calibration = await calibrateSpawnCost();
    const requests = await driveWaterfall(server.baseUrl, target);
    // Sampled AFTER the waterfall: the first interaction call is what registers
    // the baseline revision, so counting earlier reports 0 and understates the
    // very term workspace-status scales with.
    const revisionCount = countRevisions(env.PETRI_DB_PATH);
    const snapshot = await snapshotProbe(server.baseUrl);

    return {
      root,
      corpus: corpus.records.map(({ id, toolId, durationMs, artifactCount, toolJobId }) =>
        ({ id, toolId, durationMs, artifactCount, toolJobId })),
      target,
      calibration,
      revisionCount,
      requests,
      eventLoop: snapshot.eventLoop,
      probeBlocks: snapshot.blocks,
      probeRoutes: snapshot.requests,
      clientMetrics: Object.fromEntries(UNCAPTURED_CLIENT_METRICS.map((key) => [key, {
        observedMs: null,
        status: 'not_captured_no_browser_automation_in_repo',
      }])),
      kept: keep,
    };
  } finally {
    await stopServer(server?.child);
    if (!keep && existsSync(root)) rmSync(root, { recursive: true, force: true });
  }
}

async function main() {
  const argv = process.argv.slice(2);
  const keep = argv.includes('--keep');
  const asJson = argv.includes('--json');
  const verbose = argv.includes('--verbose');

  const result = await captureBaseline({
    keep,
    quiet: asJson,
    onLog: verbose ? (channel, line) => console.error(`[${channel}] ${line}`) : undefined,
  });

  if (asJson) {
    console.log(JSON.stringify(result, null, 2));
    return;
  }

  console.log('G0-RS-P4R-0 open-result baseline\n');
  console.log('  corpus (real run_tool chain)');
  for (const record of result.corpus) {
    console.log(`    ${record.toolId.padEnd(18)} ${String(record.durationMs).padStart(7)}ms  ${record.artifactCount} artifacts`);
  }

  console.log('\n  request waterfall');
  console.log(`    ${'route'.padEnd(18)} ${'cold'.padStart(9)} ${'warm'.padStart(9)}  ${'one-time'.padStart(9)}  status  role`);
  for (const request of result.requests) {
    const warm = request.warmMs === null ? '-' : `${request.warmMs}ms`;
    const once = request.oneTimeCostMs === null ? '-' : `${request.oneTimeCostMs}ms`;
    console.log(`    ${request.id.padEnd(18)} ${String(request.coldMs).padStart(7)}ms ${warm.padStart(9)}  ${once.padStart(9)}  ${String(request.status ?? 'ERR').padEnd(6)}  ${request.role}${request.error ? `  ${request.error}` : ''}`);
  }

  const el = result.eventLoop || {};
  console.log('\n  event loop (10ms-resolution histogram — the authoritative >250ms signal)');
  console.log(`    samples ${el.samples ?? 0}  p50 ${el.p50Ms ?? '-'}ms  p95 ${el.p95Ms ?? '-'}ms  p99 ${el.p99Ms ?? '-'}ms  max ${el.maxMs ?? '-'}ms`);

  console.log('\n  client metrics: not captured (no browser automation in repo)');
  for (const key of Object.keys(result.clientMetrics)) console.log(`    ${key}: null`);

  if (result.kept) console.log(`\n  remove when done:  rm -rf ${result.root}`);
}

if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  main().catch((error) => { console.error(error.message); process.exit(1); });
}

#!/usr/bin/env node
/**
 * G0-RS-P4R-0 — disposable capture environment for the Result Studio baseline.
 *
 * P4R-0 has to measure the real open-result path, but the developer database
 * holds real projects and 382 synthetic `test-tool-2` jobs, and it never had
 * `001_result_studio.sql` applied. Sampling it would both touch user data and
 * violate the plan's "no database seed pretending to be a real product
 * journey" rule.
 *
 * So every capture run gets a throwaway root instead. The backend already reads
 * every path it needs from the environment, so isolation needs no production
 * code change. The authoritative list is ISOLATED_PATH_ENV below; on top of it
 * a run sets R_SERVER_PORT and PETRI_PERF_PROBE=1, which arms the probe from
 * commit 340c09a.
 *
 * The isolation is asserted, not assumed: assertIsolated() refuses to run when
 * any path resolves outside the throwaway root or onto the repository database.
 * It fails closed, because the cost of being wrong is the user's data.
 *
 * This module owns the environment lifecycle only. Which scenarios to drive is
 * P4R-0's next unit; `capture()` takes them as a callback.
 *
 * Usage:
 *   node scripts/g0-rs-p4r-capture.mjs            # smoke: boot, snapshot, tear down
 *   node scripts/g0-rs-p4r-capture.mjs --keep     # keep the root for inspection
 *   node scripts/g0-rs-p4r-capture.mjs --json     # machine-readable snapshot
 */

import { spawn } from 'node:child_process';
import { createServer } from 'node:net';
import { mkdtempSync, mkdirSync, readdirSync, rmSync, existsSync, statSync } from 'node:fs';
import { createRequire } from 'node:module';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const require = createRequire(import.meta.url);
const REPO_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const SERVER_ENTRY = path.join(REPO_ROOT, 'core', 'petri-server', 'server.js');
const MIGRATIONS_DIR = path.join(REPO_ROOT, 'src', 'migrations');
const REPO_DB = path.join(REPO_ROOT, 'core', 'petri-server', 'petri.db');

/**
 * Every environment variable that decides where the backend WRITES.
 *
 * Declared once and consumed by both createCaptureEnv() and assertIsolated(),
 * so a path can never be redirected without also being guarded — the first
 * version of this file set four of these and guarded the same four, which left
 * PETRI_LOCAL_DATA_DIR, PETRI_PLUGINS_DIR and PETRI_HARNESS_LOCAL_ROOT falling
 * back to ~/Documents/Petri-Local, the real user data root.
 *
 * Each entry maps the variable to its subdirectory inside the disposable root.
 * Sources: config.js (db/temp/results/uploads), db.js:550 getLocalDataRoot,
 * server.js:63 + plugin-loader.js:492 + mcp/registry.js:131 (plugins),
 * mcp/registry.js:167 + helpers/tools-executor.js:116 (harness root).
 */
export const ISOLATED_PATH_ENV = Object.freeze({
  PETRI_DB_PATH: 'petri.db',
  PETRI_TEMP_DIR: 'tmp',
  PETRI_LOCAL_RESULTS_DIR: 'results',
  PETRI_LOCAL_UPLOADS_DIR: 'uploads',
  PETRI_LOCAL_DATA_DIR: 'data',
  PETRI_PLUGINS_DIR: 'plugins',
  PETRI_HARNESS_LOCAL_ROOT: 'results',
});

/**
 * Bounded fingerprint of the real user data root, for tests that must prove a
 * run stayed out of it.
 *
 * A directory's mtime does NOT change when a file inside it is rewritten, nor
 * when anything is created in a subdirectory — so the obvious
 * `statSync(root).mtimeMs` check cannot see the leaks it appears to guard, and
 * an earlier version of these tests used exactly that. This instead samples the
 * things a leak actually produces: a new project directory, a new top-level
 * entry, or a write to the live database.
 *
 * Deliberately bounded: the root holds ~85k files and a recursive walk costs
 * ~2s per sample. This does not detect a modification deep inside an existing
 * project. It does detect every creation shape a capture run could produce.
 */
export function fingerprintRealDataRoot(realRoot) {
  if (!existsSync(realRoot)) return { present: false };
  const list = (dir) => (existsSync(dir) ? readdirSync(dir).sort().join('\n') : null);
  const dbPath = path.join(realRoot, 'petri.db');
  const db = existsSync(dbPath) ? statSync(dbPath) : null;
  return {
    present: true,
    rootEntries: list(realRoot),
    projectEntries: list(path.join(realRoot, 'projects')),
    dbSize: db ? db.size : null,
    dbMtimeMs: db ? db.mtimeMs : null,
  };
}

/** Tables `001_result_studio.sql` must create for the RS paths to be reachable. */
export const REQUIRED_RS_TABLES = [
  'git_repository_bindings',
  'scientific_change_sets',
  'artifact_revisions',
  'result_selection_contexts',
  'workspace_revision_checkpoints',
];

const HEALTH_TIMEOUT_MS = 30000;
const HEALTH_POLL_MS = 100;
const SHUTDOWN_GRACE_MS = 3000;

/** Ask the OS for a free port. Racy in principle, fine for a local capture run. */
async function findFreePort() {
  return new Promise((resolve, reject) => {
    const probe = createServer();
    probe.on('error', reject);
    probe.listen(0, '127.0.0.1', () => {
      const { port } = probe.address();
      probe.close(() => resolve(port));
    });
  });
}

/**
 * Refuse to run unless every writable path sits inside the throwaway root.
 * Fails closed: an unexpected path aborts the run rather than degrading to a
 * capture that quietly writes into the developer database.
 */
export function assertIsolated(env, root) {
  const resolvedRoot = path.resolve(root);
  const guarded = Object.keys(ISOLATED_PATH_ENV).map((key) => [key, env[key]]);

  // Checked before the containment rule below: pointing at the repository
  // database is the most damaging mistake available here, so it earns the
  // specific message. The generic rule would otherwise swallow it, since the
  // repository database is always outside a throwaway root.
  if (env.PETRI_DB_PATH && path.resolve(env.PETRI_DB_PATH) === path.resolve(REPO_DB)) {
    throw new Error('capture isolation: refusing to capture against the repository database');
  }

  for (const [key, value] of guarded) {
    if (!value) throw new Error(`capture isolation: ${key} must be set explicitly`);
    const resolved = path.resolve(value);
    if (resolved !== resolvedRoot && !resolved.startsWith(resolvedRoot + path.sep)) {
      throw new Error(`capture isolation: ${key} resolves outside the disposable root (${resolved})`);
    }
  }
  return true;
}

/** Build a disposable root plus the environment that points the server at it. */
export function createCaptureEnv({ port, root } = {}) {
  const captureRoot = root || mkdtempSync(path.join(tmpdir(), 'petri-p4r-capture-'));

  const paths = Object.fromEntries(
    Object.entries(ISOLATED_PATH_ENV).map(([key, leaf]) => [key, path.join(captureRoot, leaf)]),
  );
  // PETRI_DB_PATH names a file; the rest are directories the backend expects to exist.
  for (const [key, value] of Object.entries(paths)) {
    if (key !== 'PETRI_DB_PATH') mkdirSync(value, { recursive: true });
  }

  const env = {
    ...process.env,
    ...paths,
    PETRI_PERF_PROBE: '1',
    PETRI_DESKTOP: '1',
    R_SERVER_PORT: String(port ?? 0),
    // Keep a capture run off the network and out of the AI path entirely.
    R_POOL_ENABLED: 'false',
  };

  assertIsolated(env, captureRoot);
  return { root: captureRoot, env, paths };
}

/**
 * Run `fn` with console.log suppressed.
 *
 * The migration runner logs progress to stdout, which corrupts `--json` output
 * for the machine consumers that flag exists to serve. Errors still surface:
 * console.error is untouched and exceptions propagate.
 */
export async function withQuietStdout(fn) {
  const original = console.log;
  console.log = () => {};
  try {
    return await fn();
  } finally {
    console.log = original;
  }
}

/** Apply `src/migrations/*.sql` to the disposable database. */
export async function applyMigrations(dbPath, { quiet = false } = {}) {
  const { runMigrations } = require(path.join(REPO_ROOT, 'src', 'migration-runner.js'));
  const run = () => runMigrations(dbPath, MIGRATIONS_DIR);
  return quiet ? withQuietStdout(run) : run();
}

/** Report which RS tables actually exist, so a capture cannot silently run half-migrated. */
export function inspectTables(dbPath) {
  const Database = require(require.resolve('better-sqlite3', {
    paths: [path.join(REPO_ROOT, 'core', 'petri-server'), REPO_ROOT],
  }));
  const db = new Database(dbPath, { readonly: true });
  try {
    const present = new Set(
      db.prepare("select name from sqlite_master where type='table'").all().map((r) => r.name),
    );
    return {
      present: REQUIRED_RS_TABLES.filter((t) => present.has(t)),
      missing: REQUIRED_RS_TABLES.filter((t) => !present.has(t)),
    };
  } finally {
    db.close();
  }
}

async function waitForHealth(baseUrl, { signal } = {}) {
  const deadline = Date.now() + HEALTH_TIMEOUT_MS;
  let lastError = 'no attempt made';
  while (Date.now() < deadline) {
    if (signal?.exited) throw new Error(`server exited before becoming healthy: ${signal.exited}`);
    try {
      const response = await fetch(`${baseUrl}/api/health`);
      if (response.ok) return await response.json();
      lastError = `status ${response.status}`;
    } catch (error) {
      lastError = error.message;
    }
    await new Promise((resolve) => { setTimeout(resolve, HEALTH_POLL_MS); });
  }
  throw new Error(`server did not become healthy within ${HEALTH_TIMEOUT_MS}ms (${lastError})`);
}

/** Spawn the real server against the disposable environment. */
export async function startServer(env, { onLog } = {}) {
  // Only take the server's output when someone is actually consuming it.
  // Piping it unconditionally makes the measurement measure the harness: the
  // server's console.log blocks once the pipe buffer fills and the parent is
  // slow to drain, which happens as soon as this runs under `npm run ... | tail`.
  // That backpressure stalls the server's event loop, and the probe faithfully
  // records the stall — the same capture read 463ms run directly and 4257ms
  // through npm, purely from this.
  const capturesOutput = typeof onLog === 'function';
  const stdio = capturesOutput ? ['ignore', 'pipe', 'pipe'] : ['ignore', 'ignore', 'ignore'];
  const child = spawn(process.execPath, [SERVER_ENTRY], { env, cwd: REPO_ROOT, stdio });
  const logs = [];
  const signal = { exited: null };

  const collect = (stream, channel) => {
    if (!stream) return;
    stream.setEncoding('utf8');
    stream.on('data', (chunk) => {
      for (const line of chunk.split('\n').filter(Boolean)) {
        logs.push({ channel, line });
        onLog?.(channel, line);
      }
    });
  };
  collect(child.stdout, 'stdout');
  collect(child.stderr, 'stderr');
  child.on('exit', (code, sig) => { signal.exited = `code=${code} signal=${sig}`; });

  const baseUrl = `http://127.0.0.1:${env.R_SERVER_PORT}`;
  try {
    await waitForHealth(baseUrl, { signal });
  } catch (error) {
    child.kill('SIGKILL');
    const tail = logs.slice(-15).map((l) => `  [${l.channel}] ${l.line}`).join('\n');
    throw new Error(`${error.message}\n${tail}`);
  }
  return { child, baseUrl, logs };
}

export async function stopServer(child) {
  if (!child || child.exitCode !== null) return;
  child.kill('SIGTERM');
  await new Promise((resolve) => {
    const timer = setTimeout(() => { child.kill('SIGKILL'); resolve(); }, SHUTDOWN_GRACE_MS);
    child.on('exit', () => { clearTimeout(timer); resolve(); });
  });
}

export async function snapshotProbe(baseUrl) {
  const response = await fetch(`${baseUrl}/api/__perf/event-loop`);
  if (!response.ok) throw new Error(`probe snapshot failed: status ${response.status}`);
  return response.json();
}

export async function resetProbe(baseUrl) {
  const response = await fetch(`${baseUrl}/api/__perf/reset`, { method: 'POST' });
  if (!response.ok) throw new Error(`probe reset failed: status ${response.status}`);
  return response.json();
}

/**
 * Full lifecycle: disposable root → migrate → boot with probe → run scenarios →
 * snapshot → tear down. `scenarios` receives { baseUrl, env, root } and drives
 * whatever the caller wants measured.
 */
export async function capture({ scenarios, keep = false, quiet = false, onLog } = {}) {
  const port = await findFreePort();
  const { root, env } = createCaptureEnv({ port });
  let server = null;

  try {
    const migration = await applyMigrations(env.PETRI_DB_PATH, { quiet });
    const tables = inspectTables(env.PETRI_DB_PATH);
    if (tables.missing.length) {
      throw new Error(`migration left RS tables missing: ${tables.missing.join(', ')}`);
    }

    server = await startServer(env, { onLog });
    await resetProbe(server.baseUrl);

    const scenarioResult = scenarios ? await scenarios({ baseUrl: server.baseUrl, env, root }) : null;
    const snapshot = await snapshotProbe(server.baseUrl);

    return { root, port, migration, tables, snapshot, scenarioResult, kept: keep };
  } finally {
    await stopServer(server?.child);
    if (!keep && existsSync(root)) rmSync(root, { recursive: true, force: true });
  }
}

async function main() {
  const argv = process.argv.slice(2);
  const keep = argv.includes('--keep');
  const asJson = argv.includes('--json');
  const verbose = argv.includes('--verbose');

  const result = await capture({
    keep,
    quiet: asJson,
    onLog: verbose ? (channel, line) => console.error(`[server:${channel}] ${line}`) : undefined,
  });

  if (asJson) {
    console.log(JSON.stringify(result, null, 2));
    return;
  }

  console.log('G0-RS-P4R-0 capture environment');
  console.log(`  disposable root : ${result.kept ? result.root : '(removed)'}`);
  console.log(`  port            : ${result.port}`);
  console.log(`  RS tables       : ${result.tables.present.length}/${REQUIRED_RS_TABLES.length} present`);
  console.log(`  probe enabled   : ${result.snapshot.enabled}`);
  console.log(`  event-loop      : ${result.snapshot.eventLoop?.samples ?? 0} samples`);
  console.log(`  routes recorded : ${result.snapshot.requests.length}`);
  console.log('\nEnvironment is reusable; scenario driving is the next P4R-0 unit.');
}

if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  main().catch((error) => { console.error(error.message); process.exit(1); });
}

#!/usr/bin/env node

/**
 * G0-RS-P4R-6 — one-shot, disposable continuous live journey.
 *
 * This is development evidence, not product qualification.  In particular the
 * "Agent" step invokes the real context-bound Agent tools deterministically
 * with a trusted presentation patch; it does not claim that a real Provider
 * understood the natural-language request.  Provider and packaged-app proof
 * remains owned by P7.
 *
 * The parent process owns the complete lifecycle:
 *   corpus -> backend #1 -> edit/review/code/replay/adopt/revert
 *          -> backend stop -> backend #2 -> durable truth verification
 *          -> cleanup
 *
 * Default runs print the sanitized report only.  `--write-evidence` is the
 * sole mode that writes the canonical acceptance JSON.
 */

import { spawn, spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import {
  existsSync,
  mkdirSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from 'node:fs';
import { createRequire } from 'node:module';
import { createServer } from 'node:net';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

import { createCaptureEnv, startServer, stopServer } from './g0-rs-p4r-capture.mjs';
import { buildPackEnv } from './g0-rs-p4r-pack.mjs';
import { generateCorpus } from './g0-rs-p4r-corpus.mjs';

const require = createRequire(import.meta.url);
const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const SELF = fileURLToPath(import.meta.url);
const EVIDENCE_PATH = path.join(ROOT, 'acceptance/g0-result-studio/rs-p4r-live-observation.json');
const SHA256 = /^[a-f0-9]{64}$/;
const INTERNAL_ID = /(?:^|[^A-Za-z0-9])(?:p|tj|rev|cs|conv|msg|sel)_[A-Za-z0-9._-]+/;
const SECRET_KEY = /(?:authorization|cookie|token|password|secret|api[_-]?key)/i;
const AGENT_CHILD_MARKER = '__P4R6_AGENT_RESULT__';
const CORPUS_CHILD_MARKER = '__P4R6_CORPUS_RESULT__';
const SIGNAL_FIXTURE_MARKER = '__P4R6_SIGNAL_READY__';
const AGENT_CHILD_TIMEOUT_MS = 12 * 60 * 1000;

export const LIVE_SOURCE_FILES = Object.freeze({
  producer: 'scripts/g0-rs-p4r-live-observation.mjs',
  producerTest: 'test/p4r-live-observation.test.mjs',
  corpus: 'scripts/g0-rs-p4r-corpus.mjs',
  capture: 'scripts/g0-rs-p4r-capture.mjs',
  routes: 'core/petri-server/routes/result-studio.js',
  contextTools: 'core/petri-server/agent-tools/result-context-tools.js',
  contextEditTools: 'core/petri-server/agent-tools/result-context-edit-tools.js',
  editTools: 'core/petri-server/agent-tools/result-edit-tools.js',
  changeSetService: 'core/shared-backend/result-changeset-service.js',
  compareService: 'core/shared-backend/result-compare-service.js',
  revisionSource: 'core/shared-backend/result-revision-source.js',
  replayService: 'core/shared-backend/result-replay-service.js',
  background: 'core/shared-backend/result-studio-background.js',
  backgroundChild: 'core/shared-backend/result-studio-background-child.js',
  repository: 'core/shared-backend/result-studio-repository.js',
  conversations: 'core/petri-server/helpers/conversations.js',
  packageScripts: 'package.json',
  impactMap: 'test/impact-map.json',
});

function hash(value) {
  return createHash('sha256').update(value).digest('hex');
}

function stableValue(value) {
  if (Array.isArray(value)) return value.map(stableValue);
  if (value && typeof value === 'object') {
    return Object.fromEntries(Object.keys(value).sort().map((key) => [key, stableValue(value[key])]));
  }
  return value;
}

function stableHash(value) {
  return hash(JSON.stringify(stableValue(value)));
}

function sourceBinding() {
  const sourceCommit = spawnSync('git', ['rev-parse', 'HEAD'], {
    cwd: ROOT,
    encoding: 'utf8',
  }).stdout.trim();
  const sourceHashes = Object.fromEntries(Object.entries(LIVE_SOURCE_FILES).map(([key, file]) => [
    key,
    hash(readFileSync(path.join(ROOT, file))),
  ]));
  const sourceMismatches = Object.entries(LIVE_SOURCE_FILES).flatMap(([key, file]) => {
    const shown = spawnSync('git', ['show', `${sourceCommit}:${file}`], { cwd: ROOT });
    return shown.status === 0 && hash(shown.stdout) === sourceHashes[key] ? [] : [file];
  });
  return {
    sourceCommit,
    sourceFiles: LIVE_SOURCE_FILES,
    sourceHashes,
    sourceCommitMatchesSourceHashes: sourceMismatches.length === 0,
    sourceMismatches,
  };
}

/**
 * Reject evidence that leaks runtime coordinates or secret-bearing material.
 * Repository-relative source refs and cryptographic digests are allowed.
 */
export function assertSanitizedEvidence(value, pointer = '$') {
  if (Array.isArray(value)) {
    value.forEach((item, index) => assertSanitizedEvidence(item, `${pointer}[${index}]`));
    return true;
  }
  if (value && typeof value === 'object') {
    for (const [key, item] of Object.entries(value)) {
      if (SECRET_KEY.test(key) && key !== 'qualificationEligible') {
        throw new Error(`unsafe evidence key at ${pointer}.${key}`);
      }
      assertSanitizedEvidence(item, `${pointer}.${key}`);
    }
    return true;
  }
  if (typeof value !== 'string') return true;
  if (/^https?:\/\//i.test(value)) throw new Error(`URL leaked at ${pointer}`);
  if (path.isAbsolute(value) || /^[A-Za-z]:[\\/]/.test(value)) {
    throw new Error(`absolute path leaked at ${pointer}`);
  }
  if (value.includes('..')) throw new Error(`parent path leaked at ${pointer}`);
  if (INTERNAL_ID.test(value)) throw new Error(`internal id leaked at ${pointer}`);
  return true;
}

export function injectFailure(stage, faultAt) {
  if (faultAt && stage === faultAt) {
    const error = new Error(`injected_failure:${stage}`);
    error.code = 'p4r6_injected_failure';
    throw error;
  }
}

export function assertEvidenceWritable(evidence) {
  if (evidence?.sourceCommitMatchesSourceHashes !== true) {
    const error = new Error('refusing to write evidence whose source hashes are not bound to sourceCommit');
    error.code = 'source_binding_not_current';
    throw error;
  }
  if (evidence?.passed !== true) {
    const error = new Error('refusing to write failed live evidence');
    error.code = 'live_observation_not_passed';
    throw error;
  }
  return true;
}

export async function withGuaranteedCleanup(operation, cleanup) {
  try {
    return await operation();
  } finally {
    await cleanup();
  }
}

/**
 * Install cleanup for interruptible local runs.  SIGKILL cannot be trapped;
 * SIGINT/SIGTERM are handled once and cleanup itself must be idempotent.
 */
export function installSignalCleanup(cleanup, {
  processRef = process,
  signals = ['SIGINT', 'SIGTERM'],
  terminate = (code) => {
    processRef.exitCode = code;
    if (typeof processRef.exit === 'function') processRef.exit(code);
  },
} = {}) {
  let handling = false;
  const listeners = new Map();
  for (const signal of signals) {
    const listener = () => {
      if (handling) return;
      handling = true;
      Promise.resolve(cleanup()).finally(() => {
        terminate(signal === 'SIGINT' ? 130 : 143);
      });
    };
    listeners.set(signal, listener);
    processRef.once(signal, listener);
  }
  return () => {
    for (const [signal, listener] of listeners) processRef.removeListener(signal, listener);
  };
}

export function createOwnedLifecycle({ keep = false } = {}) {
  let root = null;
  let backend = null;
  let cleaned = false;
  const children = new Set();
  return {
    setRoot(next) { root = next; },
    setBackend(next) { backend = next; },
    addChild(child) { if (child) children.add(child); },
    removeChild(child) { children.delete(child); },
    get root() { return root; },
    get backend() { return backend; },
    async cleanup() {
      if (cleaned) return;
      cleaned = true;
      const ownedChildren = [...children];
      children.clear();
      await Promise.all(ownedChildren.map((child) => new Promise((resolve) => {
        if (!child || child.exitCode !== null) { resolve(); return; }
        const timer = setTimeout(() => {
          try { child.kill('SIGKILL'); } catch { /* already exited */ }
          resolve();
        }, 2000);
        child.once('exit', () => { clearTimeout(timer); resolve(); });
        try { child.kill('SIGTERM'); } catch { clearTimeout(timer); resolve(); }
      })));
      const current = backend;
      backend = null;
      await stopServer(current?.child);
      if (!keep && root && existsSync(root)) rmSync(root, { recursive: true, force: true });
    },
  };
}

async function freePort() {
  return new Promise((resolve, reject) => {
    const probe = createServer();
    probe.once('error', reject);
    probe.listen(0, '127.0.0.1', () => {
      const port = probe.address().port;
      probe.close(() => resolve(port));
    });
  });
}

async function fetchResponse(baseUrl, route, options = {}) {
  const response = await fetch(`${baseUrl}${route}`, {
    ...options,
    signal: options.signal || AbortSignal.timeout(options.timeoutMs || 30000),
    headers: {
      ...(options.body ? { 'Content-Type': 'application/json' } : {}),
      ...(options.headers || {}),
    },
  });
  return response;
}

async function fetchJson(baseUrl, route, options = {}) {
  const response = await fetchResponse(baseUrl, route, options);
  const raw = await response.text();
  const data = raw ? JSON.parse(raw) : {};
  if (!response.ok) {
    const error = new Error(data.error || `http_${response.status}`);
    error.code = data.error || 'http_request_failed';
    error.status = response.status;
    throw error;
  }
  return { data, responseDigest: hash(raw), status: response.status };
}

function postJson(baseUrl, route, body, timeoutMs = 30000) {
  return fetchJson(baseUrl, route, {
    method: 'POST',
    body: JSON.stringify(body),
    timeoutMs,
  });
}

function artifactName(outputs, preferred = 'volcano.png') {
  if (outputs?.[preferred]) return preferred;
  return Object.keys(outputs || {}).find((name) => /volcano.*\.(?:png|svg)$/i.test(name)) || null;
}

function openDatabase(dbPath, { readonly = false } = {}) {
  const Database = require(require.resolve('better-sqlite3', {
    paths: [path.join(ROOT, 'core/petri-server'), ROOT],
  }));
  return new Database(dbPath, readonly ? { readonly: true } : undefined);
}

function alignDisposableDesktopIdentity(dbPath, projectId) {
  const db = openDatabase(dbPath);
  try {
    const row = db.prepare('SELECT user_id FROM projects WHERE id=?').get(projectId);
    if (!row) throw new Error('disposable project is missing');
    if (row.user_id === 'local-user') return { matched: true, changed: false };
    if (row.user_id !== 'p4r-corpus') {
      throw new Error('refusing to rewrite an unexpected disposable project owner');
    }
    const result = db.prepare('UPDATE projects SET user_id=? WHERE id=? AND user_id=?')
      .run('local-user', projectId, 'p4r-corpus');
    if (result.changes !== 1) throw new Error('disposable desktop identity alignment failed');
    return { matched: true, changed: true };
  } finally {
    db.close();
  }
}

function inspectTruth(dbPath, {
  projectId,
  artifactFamilyId,
  sourceRevisionId,
  adoptedRevisionId,
  replayRevisionId,
  conversationId,
} = {}) {
  const db = openDatabase(dbPath, { readonly: true });
  try {
    const revisions = db.prepare(`
      SELECT revision_id, artifact_family_id, artifact_id, revision_ordinal,
             source_commit, parameters_hash, tool_job_id, output_hash,
             validation_status, reproducibility_status, change_set_id, is_current
      FROM artifact_revisions
      WHERE project_id=? AND artifact_family_id=?
      ORDER BY revision_ordinal
    `).all(projectId, artifactFamilyId);
    const changeSets = db.prepare(`
      SELECT change_set_id, status, candidate_commit, created_by
      FROM scientific_change_sets WHERE project_id=? ORDER BY created_at
    `).all(projectId);
    const jobs = db.prepare(`
      SELECT tool_id, status, COUNT(*) AS count
      FROM tool_jobs WHERE project_id=? GROUP BY tool_id, status ORDER BY tool_id, status
    `).all(projectId);
    const conversation = db.prepare(`
      SELECT id, user_id, project_id, status, message_count
      FROM copilot_conversations WHERE id=?
    `).get(conversationId) || null;
    const messages = db.prepare(`
      SELECT role, content, meta_json FROM copilot_messages
      WHERE conversation_id=? ORDER BY ts, id
    `).all(conversationId);
    const byId = new Map(revisions.map((row) => [row.revision_id, row]));
    const changeById = new Map(changeSets.map((row) => [row.change_set_id, row]));
    const current = revisions.find((row) => row.is_current === 1) || null;
    const projection = {
      revisionCount: revisions.length,
      currentRevisionOrdinal: current?.revision_ordinal || null,
      currentIsAdoptedRevision: current?.revision_id === adoptedRevisionId,
      sourceOutputHash: byId.get(sourceRevisionId)?.output_hash || null,
      adoptedOutputHash: byId.get(adoptedRevisionId)?.output_hash || null,
      replayOutputHash: byId.get(replayRevisionId)?.output_hash || null,
      adoptedStatus: changeById.get(byId.get(adoptedRevisionId)?.change_set_id)?.status || null,
      replayStatus: changeById.get(byId.get(replayRevisionId)?.change_set_id)?.status || null,
      jobs,
      conversationPresent: Boolean(conversation),
      conversationStatus: conversation?.status || null,
      conversationMessageCount: conversation?.message_count || 0,
      durableMessageCount: messages.length,
      durableMessageDigest: stableHash(messages),
      revisionTruthDigest: stableHash(revisions),
      changeSetTruthDigest: stableHash(changeSets),
    };
    return projection;
  } finally {
    db.close();
  }
}

function countTool(truth, toolId) {
  return truth.jobs
    .filter((row) => row.tool_id === toolId)
    .reduce((sum, row) => sum + Number(row.count || 0), 0);
}

async function runMarkerChild({
  args,
  env,
  marker,
  lifecycle,
  timeoutMs = AGENT_CHILD_TIMEOUT_MS,
  label,
}) {
  return new Promise((resolve, reject) => {
    const child = spawn(process.execPath, [SELF, ...args], {
      cwd: ROOT,
      env,
      stdio: ['ignore', 'pipe', 'pipe'],
    });
    lifecycle?.addChild(child);
    let stdout = '';
    let stderr = '';
    const timer = setTimeout(() => {
      child.kill('SIGKILL');
      reject(new Error(`${label} timed out`));
    }, timeoutMs);
    child.stdout.setEncoding('utf8');
    child.stdout.on('data', (chunk) => { stdout += chunk; });
    child.stderr.setEncoding('utf8');
    child.stderr.on('data', (chunk) => { stderr += chunk; });
    child.once('exit', (code) => {
      clearTimeout(timer);
      lifecycle?.removeChild(child);
      const markerAt = stdout.lastIndexOf(marker);
      if (code !== 0 || markerAt === -1) {
        reject(new Error(`${label} failed (${code}): ${stderr.slice(-1200)}`));
        return;
      }
      try {
        resolve(JSON.parse(stdout.slice(markerAt + marker.length).trim()));
      } catch (error) {
        reject(new Error(`${label} result invalid: ${error.message}`));
      }
    });
  });
}

export function runAgentChild(env, spec, lifecycle) {
  return runMarkerChild({
    args: ['--agent-child', JSON.stringify(spec)],
    env,
    marker: AGENT_CHILD_MARKER,
    lifecycle,
    label: 'agent child',
  });
}

function runCorpusChild(root, lifecycle) {
  return runMarkerChild({
    args: ['--corpus-child', root],
    env: process.env,
    marker: CORPUS_CHILD_MARKER,
    lifecycle,
    timeoutMs: AGENT_CHILD_TIMEOUT_MS,
    label: 'corpus child',
  });
}

async function runCorpusChildMain() {
  const index = process.argv.indexOf('--corpus-child');
  const root = process.argv[index + 1];
  const corpus = await generateCorpus({ root, keep: true, quiet: true });
  process.stdout.write(`${CORPUS_CHILD_MARKER}${JSON.stringify({
    root: corpus.root,
    tables: corpus.tables,
    records: corpus.records,
    outputs: corpus.outputs,
    projectId: corpus.projectId,
    pack: corpus.pack,
    ok: corpus.ok,
    kept: true,
  })}\n`);
}

async function runSignalFixtureChildMain() {
  const index = process.argv.indexOf('--signal-fixture-child');
  const root = process.argv[index + 1];
  const lifecycle = createOwnedLifecycle();
  lifecycle.setRoot(root);
  installSignalCleanup(() => lifecycle.cleanup());
  process.stdout.write(`${SIGNAL_FIXTURE_MARKER}\n`);
  // The signal handler owns termination. This interval makes it impossible for
  // the fixture to pass merely because the process naturally reached EOF.
  setInterval(() => {}, 1000);
}

async function runAgentChildMain() {
  const index = process.argv.indexOf('--agent-child');
  const spec = JSON.parse(process.argv[index + 1]);
  const {
    createResultContextEditTools,
  } = require(path.join(ROOT, 'core/petri-server/agent-tools/result-context-edit-tools.js'));
  const {
    createResultChangeSetTools,
  } = require(path.join(ROOT, 'core/petri-server/agent-tools/result-edit-tools.js'));
  const mcpRegistry = require(path.join(ROOT, 'core/petri-server/mcp/registry.js'));
  const {
    getOrCreateActiveConversation,
    appendMessageToConversation,
  } = require(path.join(ROOT, 'core/petri-server/helpers/conversations.js'));
  const db = require(path.join(ROOT, 'core/petri-server/db.js'));
  const project = db.getProject(spec.projectId);
  const ownerId = String(project?.user_id || '').trim();
  if (!project || !ownerId) throw new Error('live project owner is unavailable');
  const conversation = getOrCreateActiveConversation(ownerId, {
    projectId: spec.projectId,
    titleHint: 'P4R-6 live journey',
    page: 'project-workspace',
  });
  appendMessageToConversation(conversation.id, 'user', spec.requestedOutcome, {
    page: 'project-workspace',
    evidenceMode: 'deterministic_context_bound_no_provider',
  });

  const progress = [];
  const ctx = {
    projectId: spec.projectId,
    // The disposable backend is booted without an authenticated HTTP user;
    // use the same local-desktop trust boundary here. Both context/edit tool
    // authorizers explicitly admit a missing user id while still requiring
    // the project, Job, Revision and context token to match SQLite truth.
    userId: undefined,
    conversationId: conversation.id,
    activeArtifact: {
      jobId: spec.jobId,
      name: spec.artifact,
      revisionId: spec.revisionId,
    },
    emitResultEditProgress(event) { progress.push(event); },
  };
  const changeSetTools = createResultChangeSetTools({
    callTool(toolId, params, toolContext) {
      return mcpRegistry.callTool(toolId, params, { ...toolContext, userId: ownerId });
    },
  });
  const tools = createResultContextEditTools({ changeSetTools });
  const planned = await tools.plan({
    requestedOutcome: spec.requestedOutcome,
    proposedParameterPatch: spec.parameterPatch,
    editOrigin: 'agent',
    userMessageId: 'live-observation-user-turn',
  }, ctx);
  if (!planned?.ok || !planned.intent || !planned.context?.contextToken) {
    throw new Error(`context edit plan failed: ${planned?.error || 'unknown'}`);
  }
  const created = await tools.create({
    contextToken: planned.context.contextToken,
    intent: planned.intent,
    scientificConfirmed: false,
  }, ctx);
  if (!created?.ok || created.changeSet?.status !== 'preview_ready' || !created.revision) {
    throw new Error(`context edit create failed: ${created?.error || 'unknown'}`);
  }
  appendMessageToConversation(conversation.id, 'assistant', '展示修改候选已生成并完成验证。', {
    page: 'project-workspace',
    resultEditStatus: 'preview_ready',
  });
  process.stdout.write(`${AGENT_CHILD_MARKER}${JSON.stringify({
    conversationId: conversation.id,
    contextToken: planned.context.contextToken,
    editClass: planned.intent.editClass,
    affectedScope: planned.intent.affectedScope,
    changeSetId: created.changeSet.changeSetId,
    revisionId: created.revision.revisionId,
    artifactFamilyId: created.revision.artifactFamilyId,
    revisionOrdinal: created.revision.revisionOrdinal,
    toolJobId: created.toolJobId,
    outputHash: created.revision.outputHash,
    parametersHash: created.revision.parametersHash,
    publicProgressPhases: (created.publicProgress || []).map((item) => item.phase),
    emittedProgressCount: progress.length,
  })}\n`);
}

function eventChain(events) {
  let previous = '0'.repeat(64);
  return events.map((event, index) => {
    const digest = stableHash({ index, previous, event });
    previous = digest;
    return { ...event, digest };
  });
}

/**
 * Full live run. `faultAt` exists only for deterministic lifecycle tests and
 * local diagnosis; CLI callers do not expose it as an acceptance shortcut.
 */
export async function captureLiveObservation({
  keep = false,
  faultAt = null,
  writeEvidence = false,
} = {}) {
  const lifecycle = createOwnedLifecycle({ keep });
  const removeSignalHandlers = installSignalCleanup(() => lifecycle.cleanup());
  const startedAt = Date.now();

  return withGuaranteedCleanup(async () => {
    injectFailure('before_corpus', faultAt);
    const captureRoot = createCaptureEnv({ port: 0 }).root;
    lifecycle.setRoot(captureRoot);
    const corpus = await runCorpusChild(captureRoot, lifecycle);
    if (!corpus.ok) throw new Error('live corpus incomplete');
    const desktopIdentity = alignDisposableDesktopIdentity(
      path.join(corpus.root, 'petri.db'),
      corpus.projectId,
    );
    const volcano = corpus.records.find((record) => record.id === 'volcano-plot');
    const artifact = artifactName(corpus.outputs['volcano-plot']);
    if (!volcano?.toolJobId || !artifact) throw new Error('standalone volcano artifact unavailable');
    injectFailure('after_corpus', faultAt);

    const { env } = createCaptureEnv({ root: corpus.root, port: await freePort() });
    // BLOCK-83/86 package awareness: the server must see the same pack sources
    // the corpus child ran with, or its replay/verify routes resolve plugins
    // from an empty core tree.
    Object.assign(env, buildPackEnv({ captureRoot: corpus.root, toolIds: corpus.pack.stagedToolIds }).env);
    let backend = await startServer(env);
    lifecycle.setBackend(backend);
    const timings = {};
    const timed = async (name, operation) => {
      const start = process.hrtime.bigint();
      const result = await operation();
      timings[name] = Number((Number(process.hrtime.bigint() - start) / 1e6).toFixed(3));
      return result;
    };

    const interaction = await timed('openResultMs', () => fetchJson(
      backend.baseUrl,
      `/api/result-studio/interaction?projectId=${encodeURIComponent(corpus.projectId)}&jobId=${encodeURIComponent(volcano.toolJobId)}&artifact=${encodeURIComponent(artifact)}`,
    ));
    const sourceRevision = interaction.data.revision;
    if (!sourceRevision?.revisionId || !interaction.data.manifest?.artifactFamilyId) {
      throw new Error('interaction did not create a formal source Revision');
    }
    injectFailure('after_open', faultAt);

    const beforeEdit = inspectTruth(env.PETRI_DB_PATH, {
      projectId: corpus.projectId,
      artifactFamilyId: interaction.data.manifest.artifactFamilyId,
      sourceRevisionId: sourceRevision.revisionId,
      conversationId: 'not-created',
    });
    const requestedOutcome = '换成色盲友好配色，并让标签更容易阅读';
    const agent = await timed('agentEditMs', () => runAgentChild(env, {
      userId: 'p4r-corpus',
      projectId: corpus.projectId,
      jobId: volcano.toolJobId,
      artifact,
      revisionId: sourceRevision.revisionId,
      requestedOutcome,
      parameterPatch: {
        color_up: '#d55e00',
        color_down: '#0072b2',
        point_size: 2.4,
        label_size: 3.6,
      },
    }, lifecycle));
    if (agent.editClass !== 'presentation_rerender' || agent.affectedScope !== 'current_result_only') {
      throw new Error('deterministic Agent edit escaped the presentation-only boundary');
    }
    injectFailure('after_agent_edit', faultAt);

    const comparisonA = await timed('compareMs', () => fetchJson(
      backend.baseUrl,
      `/api/result-studio/changesets/${encodeURIComponent(agent.changeSetId)}/compare`,
    ));
    const sourceA = await timed('codeOpenMs', () => fetchJson(
      backend.baseUrl,
      `/api/result-studio/revisions/${encodeURIComponent(agent.revisionId)}/source?projectId=${encodeURIComponent(corpus.projectId)}`,
    ));
    const downloaded = await fetchResponse(
      backend.baseUrl,
      `/api/result-studio/revisions/${encodeURIComponent(agent.revisionId)}/source?projectId=${encodeURIComponent(corpus.projectId)}&download=1`,
    );
    const downloadedBytes = Buffer.from(await downloaded.arrayBuffer());
    if (!downloaded.ok || hash(downloadedBytes) !== sourceA.data.sha256) {
      throw new Error('downloaded Revision source did not match sourceScriptRef');
    }

    const adopted = await timed('adoptMs', () => postJson(
      backend.baseUrl,
      `/api/result-studio/changesets/${encodeURIComponent(agent.changeSetId)}/adopt`,
      {},
    ));
    const adoptedRevision = adopted.data.currentRevisions?.find(
      (revision) => revision.revisionId === agent.revisionId,
    ) || adopted.data.currentRevisions?.[0];
    if (!adoptedRevision || adoptedRevision.revisionId !== agent.revisionId) {
      throw new Error('Agent candidate was not adopted as current');
    }

    const adoptedContext = await fetchJson(
      backend.baseUrl,
      `/api/result-studio/context-envelope?projectId=${encodeURIComponent(corpus.projectId)}&conversationId=${encodeURIComponent(agent.conversationId)}&jobId=${encodeURIComponent(agent.toolJobId)}&artifact=${encodeURIComponent(artifact)}&revisionId=${encodeURIComponent(agent.revisionId)}`,
    );
    const contextToken = adoptedContext.data.agentView?.contextToken;
    if (!SHA256.test(contextToken || '')) throw new Error('adopted Revision context token unavailable');
    const preflight = await timed('replayPreflightMs', () => postJson(
      backend.baseUrl,
      `/api/result-studio/revisions/${encodeURIComponent(agent.revisionId)}/replay`,
      {
        phase: 'preflight',
        projectId: corpus.projectId,
        revisionId: agent.revisionId,
        conversationId: agent.conversationId,
        contextToken,
        expectedSourceSha256: sourceA.data.sha256,
        expectedParametersHash: sourceA.data.parameters?.sha256,
      },
    ));
    const confirmBody = {
      phase: 'confirm',
      projectId: corpus.projectId,
      revisionId: agent.revisionId,
      conversationId: agent.conversationId,
      contextToken,
      confirmationToken: preflight.data.confirmationToken,
    };
    const replay = await timed('replayConfirmMs', () => postJson(
      backend.baseUrl,
      `/api/result-studio/revisions/${encodeURIComponent(agent.revisionId)}/replay`,
      confirmBody,
      10 * 60 * 1000,
    ));
    const afterFirstReplay = inspectTruth(env.PETRI_DB_PATH, {
      projectId: corpus.projectId,
      artifactFamilyId: agent.artifactFamilyId,
      sourceRevisionId: sourceRevision.revisionId,
      adoptedRevisionId: agent.revisionId,
      replayRevisionId: replay.data.revisionId,
      conversationId: agent.conversationId,
    });
    const replayAgain = await postJson(
      backend.baseUrl,
      `/api/result-studio/revisions/${encodeURIComponent(agent.revisionId)}/replay`,
      confirmBody,
      10 * 60 * 1000,
    );
    const afterDuplicateReplay = inspectTruth(env.PETRI_DB_PATH, {
      projectId: corpus.projectId,
      artifactFamilyId: agent.artifactFamilyId,
      sourceRevisionId: sourceRevision.revisionId,
      adoptedRevisionId: agent.revisionId,
      replayRevisionId: replay.data.revisionId,
      conversationId: agent.conversationId,
    });
    if (replay.data.adopted !== false || replay.data.idempotent !== false
      || replayAgain.data.idempotent !== true
      || replayAgain.data.revisionId !== replay.data.revisionId) {
      throw new Error('controlled replay idempotency/current contract failed');
    }
    const comparisonB = await fetchJson(
      backend.baseUrl,
      `/api/result-studio/changesets/${encodeURIComponent(replay.data.changeSetId)}/compare`,
    );
    const reverted = await timed('revertMs', () => postJson(
      backend.baseUrl,
      `/api/result-studio/changesets/${encodeURIComponent(replay.data.changeSetId)}/revert`,
      { reason: 'p4r6_live_discard_candidate' },
    ));
    injectFailure('before_restart', faultAt);

    const beforeRestart = inspectTruth(env.PETRI_DB_PATH, {
      projectId: corpus.projectId,
      artifactFamilyId: agent.artifactFamilyId,
      sourceRevisionId: sourceRevision.revisionId,
      adoptedRevisionId: agent.revisionId,
      replayRevisionId: replay.data.revisionId,
      conversationId: agent.conversationId,
    });
    await stopServer(backend.child);
    lifecycle.setBackend(null);
    let unreachableBetweenRestarts = false;
    try {
      await fetchResponse(backend.baseUrl, '/api/health', { timeoutMs: 1200 });
    } catch {
      unreachableBetweenRestarts = true;
    }
    if (!unreachableBetweenRestarts) throw new Error('backend did not stop before restart observation');

    backend = await startServer(env);
    lifecycle.setBackend(backend);
    const healthAfterRestart = await fetchJson(backend.baseUrl, '/api/health');
    const versionsAfterRestart = await fetchJson(
      backend.baseUrl,
      `/api/result-studio/changesets?projectId=${encodeURIComponent(corpus.projectId)}&artifactFamilyId=${encodeURIComponent(agent.artifactFamilyId)}`,
    );
    const workspaceAfterRestart = await fetchJson(
      backend.baseUrl,
      `/api/result-studio/workspace/status?projectId=${encodeURIComponent(corpus.projectId)}&conversationId=${encodeURIComponent(agent.conversationId)}`,
    );
    const sourceAfterRestart = await fetchJson(
      backend.baseUrl,
      `/api/result-studio/revisions/${encodeURIComponent(agent.revisionId)}/source?projectId=${encodeURIComponent(corpus.projectId)}&expectSha256=${encodeURIComponent(sourceA.data.sha256)}`,
    );
    const artifactAfterRestart = await fetchResponse(
      backend.baseUrl,
      `/api/result-studio/revisions/${encodeURIComponent(agent.revisionId)}/artifact`,
    );
    const artifactBytesAfterRestart = Buffer.from(await artifactAfterRestart.arrayBuffer());
    if (!artifactAfterRestart.ok || hash(artifactBytesAfterRestart) !== agent.outputHash) {
      throw new Error('adopted Artifact failed hash verification after restart');
    }
    const afterRestart = inspectTruth(env.PETRI_DB_PATH, {
      projectId: corpus.projectId,
      artifactFamilyId: agent.artifactFamilyId,
      sourceRevisionId: sourceRevision.revisionId,
      adoptedRevisionId: agent.revisionId,
      replayRevisionId: replay.data.revisionId,
      conversationId: agent.conversationId,
    });
    injectFailure('after_restart', faultAt);

    const checks = {
      realCorpusCompleted: corpus.ok === true && corpus.records.every((record) => record.ok === true),
      disposableDesktopIdentityMatchesRuntime: desktopIdentity.matched === true,
      formalResultOpened: sourceRevision.validationStatus === 'valid',
      userSuppliedNoInternalIds: !INTERNAL_ID.test(requestedOutcome),
      deterministicAgentBoundaryHonest: agent.editClass === 'presentation_rerender',
      agentCandidateValid: comparisonA.data.summary?.status === 'preview_ready'
        && comparisonA.data.summary?.validationStatus === 'valid',
      codeSourceExact: SHA256.test(sourceA.data.sha256 || '')
        && hash(downloadedBytes) === sourceA.data.sha256
        && sourceA.data.parameters?.sha256 === agent.parametersHash,
      adoptedExactlyOnce: adopted.data.changeSet?.status === 'adopted'
        && beforeRestart.currentIsAdoptedRevision,
      replayCreatedNonCurrentCandidate: replay.data.adopted === false
        && comparisonB.data.summary?.status === 'preview_ready',
      replayConfirmationIdempotent: replayAgain.data.idempotent === true
        && afterFirstReplay.revisionCount === afterDuplicateReplay.revisionCount
        && countTool(afterFirstReplay, 'volcano-plot') === countTool(afterDuplicateReplay, 'volcano-plot'),
      replayCandidateDiscarded: reverted.data.changeSet?.status === 'reverted'
        && beforeRestart.replayStatus === 'reverted',
      sourceAnalysisNotRerun: countTool(beforeEdit, 'deseq2') === countTool(beforeRestart, 'deseq2'),
      sourceArtifactPreserved: beforeEdit.sourceOutputHash === beforeRestart.sourceOutputHash,
      conversationDurable: beforeRestart.conversationPresent
        && beforeRestart.conversationMessageCount === 2
        && beforeRestart.durableMessageCount === 2,
      backendActuallyRestarted: unreachableBetweenRestarts && healthAfterRestart.status === 200,
      truthRecoveredAfterRestart: beforeRestart.revisionTruthDigest === afterRestart.revisionTruthDigest
        && beforeRestart.changeSetTruthDigest === afterRestart.changeSetTruthDigest
        && beforeRestart.durableMessageDigest === afterRestart.durableMessageDigest,
      currentRecoveredAfterRestart: afterRestart.currentIsAdoptedRevision
        && versionsAfterRestart.data.currentRevision?.revisionOrdinal === agent.revisionOrdinal,
      lifecycleRecoveredFromTruth: workspaceAfterRestart.data.lifecycle?.status === 'ready'
        && workspaceAfterRestart.data.lifecycle?.revisionIntegrity?.intact === true,
      sourceAndArtifactReadableAfterRestart: sourceAfterRestart.data.sha256 === sourceA.data.sha256
        && hash(artifactBytesAfterRestart) === agent.outputHash,
    };

    const events = eventChain([
      { step: 'real_completed_job', status: 'observed' },
      { step: 'open_result', status: 'observed' },
      { step: 'context_bound_agent_style_edit', status: 'observed' },
      { step: 'candidate_compare', status: 'observed' },
      { step: 'revision_code', status: 'observed' },
      { step: 'adopt_candidate', status: 'observed' },
      { step: 'controlled_replay', status: 'observed' },
      { step: 'discard_replay_candidate', status: 'observed' },
      { step: 'conversation_roundtrip', status: 'observed' },
      { step: 'backend_restart_recovery', status: 'observed' },
    ]);
    const binding = sourceBinding();
    const evidence = {
      schemaVersion: 1,
      workPackage: 'G0-RS-P4R-6',
      evidenceClass: 'live_local_continuous_journey_non_qualifying',
      capturedAt: new Date().toISOString(),
      qualificationEligible: false,
      providerBoundary: {
        realProviderUsed: false,
        mode: 'deterministic_context_bound_agent_tool_invocation',
        deferredQualificationOwner: 'G0-RS-P7',
      },
      runtimeBoundary: {
        appMode: 'local_backend_and_real_tool_runtime',
        packagedDesktopObserved: false,
        uiInteractionObserved: false,
      },
      privacy: {
        classification: 'digests_counts_statuses_and_timings_only',
        rawInternalIdsPersisted: false,
        absolutePathsPersisted: false,
        urlsOrPortsPersisted: false,
        promptsOrResultValuesPersisted: false,
        credentialsPersisted: false,
      },
      ...binding,
      executionTruthChain: [
        'run_tool',
        'tool_job',
        'artifact_truth',
        'artifact_revision',
        'context_bound_edit',
        'candidate_revision',
        'compare',
        'adopt',
        'controlled_replay',
        'discard_candidate',
        'backend_restart',
        'truth_reopen',
      ],
      events,
      eventChainDigest: events.at(-1)?.digest || null,
      observations: {
        corpusToolCount: corpus.records.length,
        initialRevisionOrdinal: sourceRevision.revisionOrdinal,
        adoptedRevisionOrdinal: agent.revisionOrdinal,
        revisionCountAfterJourney: afterRestart.revisionCount,
        conversationMessageCount: afterRestart.durableMessageCount,
        sourceSha256: sourceA.data.sha256,
        adoptedArtifactSha256: agent.outputHash,
        sourceTruthDigest: afterRestart.revisionTruthDigest,
        changeSetTruthDigest: afterRestart.changeSetTruthDigest,
        conversationTruthDigest: afterRestart.durableMessageDigest,
        publicProgressPhaseCount: agent.publicProgressPhases.length,
        backendStartCount: 2,
        disposableDesktopIdentityChanged: desktopIdentity.changed,
        timingsMs: timings,
        totalDurationMs: Date.now() - startedAt,
      },
      checks,
    };
    evidence.passed = Object.values(checks).every(Boolean)
      && binding.sourceCommitMatchesSourceHashes === true;
    assertSanitizedEvidence(evidence);
    if (writeEvidence) {
      assertEvidenceWritable(evidence);
      mkdirSync(path.dirname(EVIDENCE_PATH), { recursive: true });
      writeFileSync(EVIDENCE_PATH, `${JSON.stringify(evidence, null, 2)}\n`);
    }
    return evidence;
  }, async () => {
    removeSignalHandlers();
    await lifecycle.cleanup();
  });
}

function parseCli(argv) {
  return {
    writeEvidence: argv.includes('--write-evidence'),
    keep: argv.includes('--keep'),
  };
}

async function main() {
  if (process.argv.includes('--signal-fixture-child')) {
    await runSignalFixtureChildMain();
    return;
  }
  if (process.argv.includes('--corpus-child')) {
    await runCorpusChildMain();
    return;
  }
  if (process.argv.includes('--agent-child')) {
    await runAgentChildMain();
    return;
  }
  const result = await captureLiveObservation(parseCli(process.argv.slice(2)));
  console.log(JSON.stringify(result, null, 2));
  if (!result.passed) process.exitCode = 1;
}

if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  main().catch((error) => {
    console.error(`[G0-RS-P4R-6 live] FAIL — ${error.code || error.message}`);
    if (process.argv.includes('--verbose')) console.error(error.stack || error);
    process.exitCode = 1;
  });
}

#!/usr/bin/env node

/**
 * P4R-5 source-bound observation.  This is deliberately separate from the
 * fast product gate: it runs the real disposable corpus (including GO/KEGG),
 * creates the formal Revision through the interaction route, then reads the
 * exact source projection for each artifact class.  Only bounded digests and
 * statuses are persisted.
 */
import { createHash } from 'node:crypto';
import { execFileSync, spawnSync } from 'node:child_process';
import { createServer } from 'node:net';
import { existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { generateCorpus } from './g0-rs-p4r-corpus.mjs';
import { createCaptureEnv, startServer, stopServer } from './g0-rs-p4r-capture.mjs';
import { buildPackEnv, locatePackPluginDir, resolveBioPackRoot } from './g0-rs-p4r-pack.mjs';

const rootDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const evidencePath = path.join(rootDir, 'acceptance/g0-result-studio/rs-p4r-source-observation.json');
/** 桌面仓文件：commit 绑定（git show 对账）。 */
const sourceFiles = Object.freeze({
  observation: 'scripts/g0-rs-p4r-source-observation.mjs',
  corpus: 'scripts/g0-rs-p4r-corpus.mjs',
  routes: 'core/petri-server/routes/result-studio.js',
  sourceProjection: 'core/shared-backend/result-revision-source.js',
  replayService: 'core/shared-backend/result-replay-service.js',
});
/** 插件定义/脚本自 BLOCK-83 起随领域包交付：按 dormant 感知定位解析为包相对路径
 * （封存态下 volcano-plot 等在 plugins.dormant/），绑定走包 commit+哈希对账。 */
function resolvePackBindingPaths(packRoot) {
  const rel = (toolId, ...parts) => {
    const dir = locatePackPluginDir(packRoot, toolId);
    return path.relative(packRoot, path.join(dir, ...parts));
  };
  return {
    deseq2Definition: rel('deseq2', 'tool-definition.json'),
    deseq2Script: rel('deseq2', 'scripts', 'deseq2.R'),
    volcanoDefinition: rel('volcano-plot', 'tool-definition.json'),
    volcanoScript: rel('volcano-plot', 'scripts', 'volcano-plot.R'),
    correlationDefinition: rel('gene-correlation', 'tool-definition.json'),
    correlationScript: rel('gene-correlation', 'scripts', 'gene-correlation.R'),
    enrichmentDefinition: rel('go-kegg', 'tool-definition.json'),
    enrichmentScript: rel('go-kegg', 'scripts', 'go-kegg.R'),
  };
}
const hash = (value) => createHash('sha256').update(value).digest('hex');

function sourceBinding(packRoot) {
  const sourceCommit = execFileSync('git', ['rev-parse', 'HEAD'], { cwd: rootDir, encoding: 'utf8' }).trim();
  const sourceHashes = Object.fromEntries(Object.entries(sourceFiles).map(([key, file]) => [
    key,
    hash(readFileSync(path.join(rootDir, file))),
  ]));
  const mismatches = Object.entries(sourceFiles).filter(([key, file]) => {
    const shown = spawnSync('git', ['show', `${sourceCommit}:${file}`], { cwd: rootDir });
    return shown.status !== 0 || hash(shown.stdout) !== sourceHashes[key];
  }).map(([, file]) => file);
  const packCommit = execFileSync('git', ['rev-parse', 'HEAD'], { cwd: packRoot, encoding: 'utf8' }).trim();
  const packSourceFiles = resolvePackBindingPaths(packRoot);
  const packHashes = Object.fromEntries(Object.entries(packSourceFiles).map(([key, file]) => [
    key,
    hash(readFileSync(path.join(packRoot, file))),
  ]));
  const packMismatches = Object.entries(packSourceFiles).filter(([key, file]) => {
    const shown = spawnSync('git', ['show', `${packCommit}:${file}`], { cwd: packRoot });
    return shown.status !== 0 || hash(shown.stdout) !== packHashes[key];
  }).map(([, file]) => file);
  return {
    sourceCommit,
    sourceFiles,
    sourceHashes,
    sourceCommitMatchesSourceHashes: mismatches.length === 0,
    sourceMismatches: mismatches,
    pack: {
      root: packRoot,
      commit: packCommit,
      files: packSourceFiles,
      hashes: packHashes,
      commitMatchesSourceHashes: packMismatches.length === 0,
      mismatches: packMismatches,
    },
  };
}

async function freePort() {
  return new Promise((resolve, reject) => {
    const probe = createServer();
    probe.once('error', reject);
    probe.listen(0, '127.0.0.1', () => {
      const port = probe.address().port;
      probe.close(() => resolve(port));
    });
  });
}

function pick(outputs, patterns) {
  const entries = Object.entries(outputs || {});
  const found = entries.find(([name]) => patterns.some((pattern) => pattern.test(name)));
  return found ? found[0] : null;
}

async function observe() {
  const { root, env } = createCaptureEnv({ port: 0 });
  let server;
  try {
    const corpus = await generateCorpus({ root, keep: true, withEnrichment: true, quiet: true });
    if (!corpus.ok) throw new Error(`corpus_incomplete:${JSON.stringify(corpus.records)}`);
    // BLOCK-83/86 package awareness: server sees the pack sources the corpus child ran with.
    Object.assign(env, buildPackEnv({ captureRoot: root, toolIds: corpus.pack.stagedToolIds }).env);
    env.R_SERVER_PORT = String(await freePort());
    server = await startServer(env);
    const d = corpus.outputs.deseq2 || {};
    const v = corpus.outputs['volcano-plot'] || {};
    const h = corpus.outputs['gene-correlation'] || {};
    const e = corpus.outputs['go-kegg'] || {};
    const targets = [
      { kind: 'deseq2_deg_table', job: 'deseq2', artifact: pick(d, [/deg_table/i, /deg.*\.csv$/i]) },
      { kind: 'standalone_volcano', job: 'volcano-plot', artifact: pick(v, [/volcano/i, /\.png$/i]) },
      { kind: 'gene_correlation_heatmap', job: 'gene-correlation', artifact: pick(h, [/heatmap/i, /\.png$/i]) },
      { kind: 'go_kegg_enrichment', job: 'go-kegg', artifact: pick(e, [/go.*results/i, /kegg.*results/i, /\.csv$/i]) },
    ];
    const byId = new Map(corpus.records.map((record) => [record.id, record]));
    const observations = [];
    for (const target of targets) {
      const record = byId.get(target.job);
      if (!record || !target.artifact) {
        observations.push({ kind: target.kind, status: 'unavailable', reason: 'artifact_not_found' });
        continue;
      }
      const interactionUrl = `${server.baseUrl}/api/result-studio/interaction?projectId=${encodeURIComponent(corpus.projectId)}&jobId=${encodeURIComponent(record.toolJobId)}&artifact=${encodeURIComponent(target.artifact)}`;
      const interaction = await fetch(interactionUrl);
      const interactionJson = await interaction.json().catch(() => ({}));
      const revisionId = interactionJson.revision?.revisionId || interactionJson.revision?.id || null;
      if (!interaction.ok || !revisionId) {
        observations.push({
          kind: target.kind,
          artifact: target.artifact,
          status: 'failed',
          httpStatus: interaction.status,
          error: interactionJson.error || 'revision_not_created',
          diagnostics: Array.isArray(interactionJson.manifest?.diagnostics)
            ? interactionJson.manifest.diagnostics.map((item) => ({ code: item?.code || null, message: item?.message || null }))
            : [],
        });
        continue;
      }
      const source = await fetch(`${server.baseUrl}/api/result-studio/revisions/${encodeURIComponent(revisionId)}/source?projectId=${encodeURIComponent(corpus.projectId)}`);
      const sourceJson = await source.json().catch(() => ({}));
      observations.push({
        kind: target.kind,
        artifact: target.artifact,
        status: source.ok && sourceJson.sha256 && sourceJson.content ? 'verified' : 'failed',
        sourceStatus: source.status,
        sourceSha256: sourceJson.sha256 || null,
        sourceScope: sourceJson.scope || null,
        reproductionStatus: sourceJson.reproduction?.status || null,
        formalJobCompleted: record.ok === true,
      });
    }
    const packRoot = resolveBioPackRoot();
    if (!packRoot) throw new Error('bio pack not found (PETRI_BIO_PACK_ROOT or sibling petri-pack-bio)');
    const binding = sourceBinding(packRoot);
    const result = {
      schemaVersion: 1,
      workPackage: 'G0-RS-P4R-5',
      qualificationEligible: false,
      ...binding,
      projectBound: true,
      executionTruthChain: ['run_tool', 'tool_job', 'artifact_truth', 'artifact_revision', 'revision_source'],
      observations,
      allFourVerified: observations.length === 4 && observations.every((item) => item.status === 'verified'),
    };
    result.passed = result.allFourVerified
      && result.sourceCommitMatchesSourceHashes
      && result.pack.commitMatchesSourceHashes;
    mkdirSync(path.dirname(evidencePath), { recursive: true });
    writeFileSync(evidencePath, `${JSON.stringify(result, null, 2)}\n`);
    return result;
  } finally {
    if (server) await stopServer(server.child);
    if (existsSync(root)) rmSync(root, { recursive: true, force: true });
  }
}

observe().then((result) => {
  console.log(JSON.stringify(result, null, 2));
  if (!result.passed) process.exitCode = 1;
}).catch((error) => {
  console.error(error.stack || error.message);
  process.exitCode = 1;
});

#!/usr/bin/env node
'use strict';

/**
 * Electron-side driver for the P4R-6 renderer observation.
 *
 * The parent process owns corpus/backend/Vite lifecycle and passes only a
 * disposable config path. This process owns one BrowserWindow, performs real
 * Chromium layout/focus/capture checks, writes a bounded result into the same
 * disposable root, and exits. No project identifiers, URLs or DOM text are
 * persisted in the result.
 */

const { app, BrowserWindow, session } = require('electron');
const { createHash } = require('node:crypto');
const { mkdirSync, readFileSync, writeFileSync } = require('node:fs');
const path = require('node:path');

const CONFIG_ENV = 'PETRI_P4R_UI_DRIVER_CONFIG';
const WAIT_TIMEOUT_MS = 45_000;
const POLL_MS = 100;
const controlLines = [];
const controlWaiters = [];
let controlBuffer = '';
// 失败诊断：catch 落盘时带上最后一个通过 checkpoint，否则「阶段首段即失败」
// 只能靠栈帧猜（页面世界抛来的跨域异常连栈帧都没有，如 UnknownVizError）。
let driverLastStage = 'starting';

process.stdin.setEncoding('utf8');
process.stdin.on('data', (chunk) => {
  controlBuffer += chunk;
  const lines = controlBuffer.split(/\r?\n/);
  controlBuffer = lines.pop() || '';
  for (const line of lines) {
    const index = controlWaiters.findIndex((item) => item.expected === line);
    if (index < 0) {
      if (line) controlLines.push(line);
      continue;
    }
    const [waiter] = controlWaiters.splice(index, 1);
    clearTimeout(waiter.timer);
    waiter.resolve();
  }
});

function waitForControlLine(expected, timeoutMs = WAIT_TIMEOUT_MS) {
  const index = controlLines.indexOf(expected);
  if (index >= 0) {
    controlLines.splice(index, 1);
    return Promise.resolve();
  }
  return new Promise((resolve, reject) => {
    const waiter = { expected, resolve, timer: null };
    waiter.timer = setTimeout(() => {
      const active = controlWaiters.indexOf(waiter);
      if (active >= 0) controlWaiters.splice(active, 1);
      reject(new Error(`timed out waiting for parent control line ${expected}`));
    }, timeoutMs);
    controlWaiters.push(waiter);
  });
}

function digest(value) {
  return createHash('sha256').update(value).digest('hex');
}

function readConfig() {
  const configPath = process.env[CONFIG_ENV];
  if (!configPath || !path.isAbsolute(configPath)) {
    throw new Error(`${CONFIG_ENV} must point to an absolute disposable config path`);
  }
  const config = JSON.parse(readFileSync(configPath, 'utf8'));
  for (const key of ['url', 'outputDir', 'resultPath', 'requestedOutcome']) {
    if (typeof config[key] !== 'string' || !config[key]) throw new Error(`driver config missing ${key}`);
  }
  if (!config.url.startsWith('http://127.0.0.1:3000/project/')) {
    throw new Error('driver only accepts the isolated local P4R project URL');
  }
  return config;
}

async function waitFor(webContents, expression, label, timeoutMs = WAIT_TIMEOUT_MS) {
  const deadline = Date.now() + timeoutMs;
  let last = null;
  while (Date.now() < deadline) {
    try {
      last = await webContents.executeJavaScript(expression, true);
      if (last) return last;
    } catch (error) {
      last = error && error.message;
    }
    await new Promise((resolve) => setTimeout(resolve, POLL_MS));
  }
  throw new Error(`timed out waiting for ${label}; last=${JSON.stringify(last)}`);
}

async function setTheme(webContents, theme) {
  await webContents.executeJavaScript(`
    (() => {
      localStorage.setItem('petri-theme', ${JSON.stringify(theme)});
      window.dispatchEvent(new CustomEvent('petri:theme-change', {
        detail: { preference: ${JSON.stringify(theme)} }
      }));
      return true;
    })()
  `, true);
  await waitFor(
    webContents,
    `document.documentElement.dataset.theme === ${JSON.stringify(theme)}`,
    `theme ${theme}`,
  );
}

async function semanticSnapshot(webContents) {
  const snapshot = await webContents.executeJavaScript(`
    (() => {
      const visible = (element) => {
        if (!(element instanceof HTMLElement)) return false;
        const style = getComputedStyle(element);
        const rect = element.getBoundingClientRect();
        return style.display !== 'none' && style.visibility !== 'hidden' && rect.width > 0 && rect.height > 0;
      };
      const canvas = document.querySelector('[aria-label="结果主画布"]');
      const context = canvas && canvas.querySelector('header');
      const active = document.activeElement;
      const buttons = canvas
        ? [...canvas.querySelectorAll('button')].filter(visible)
        : [];
      const bodyText = document.body.innerText || '';
      const rect = canvas ? canvas.getBoundingClientRect() : null;
      const firstVisibleRaw = canvas && canvas.getAttribute('data-first-visible-ms');
      const title = context && context.querySelector('h2');
      const versionText = context
        ? [...context.querySelectorAll('span')].map((item) => item.textContent || '')
          .find((text) => /^(当前版本|v\\d+)$/.test(text.trim())) || ''
        : '';
      const truth = context && context.querySelector('[data-tone]');
      const bodyCandidates = canvas
        ? [...canvas.querySelectorAll(
          'img, table, iframe, pre, [role="img"], [data-viewer], main, article, [class*="resultSidebarPreviewBody"] > *',
        )]
        : [];
      const degradationCandidates = canvas
        ? [...canvas.querySelectorAll('[role="alert"], [data-state="blocked"], [data-state="unavailable"]')]
        : [];
      const composer = document.querySelector('[aria-label="用 Agent 修改当前结果"]');
      return {
        theme: document.documentElement.dataset.theme || null,
        viewport: {
          innerWidth: window.innerWidth,
          innerHeight: window.innerHeight,
          clientWidth: document.documentElement.clientWidth,
          scrollWidth: document.documentElement.scrollWidth,
        },
        canvas: rect ? {
          width: Math.round(rect.width),
          height: Math.round(rect.height),
          mode: canvas.getAttribute('data-mode'),
          firstVisibleMs: firstVisibleRaw && Number.isFinite(Number(firstVisibleRaw))
            ? Number(firstVisibleRaw)
            : null,
        } : null,
        bodyVisible: bodyCandidates.some((candidate) => visible(candidate)),
        degradationVisible: degradationCandidates.some((candidate) => visible(candidate)),
        composerState: composer ? composer.getAttribute('data-state') : 'absent',
        titleText: title ? (title.textContent || '').trim().slice(0, 160) : null,
        versionKind: /^v\\d+$/.test(versionText.trim()) ? 'ordinal' : versionText.trim() === '当前版本' ? 'fallback' : 'missing',
        truthKind: truth ? (truth.getAttribute('data-tone') || 'present') : 'missing',
        visiblePrimaryActionCount: buttons.filter((button) => {
          const text = (button.textContent || '').trim();
          return /采用|放弃|撤销|恢复|确认重放|交给 Agent/.test(text)
            && !button.closest('[class*="lifecycle"], [role="alert"]');
        }).length,
        activeElement: active ? {
          tag: active.tagName.toLowerCase(),
          ariaLabel: active.getAttribute('aria-label') || null,
          text: (active.textContent || '').trim().slice(0, 120),
        } : null,
        internalLeakFlags: {
          absolutePath: /(?:\\/Users\\/|\\/home\\/|[A-Za-z]:\\\\)/.test(bodyText),
          credential: /(?:sk-[A-Za-z0-9]{12,}|api[_ -]?key\\s*[:=])/i.test(bodyText),
          rawInternalId: /\\b(?:rev|cs|tj|sel|conv)_[a-z0-9_-]{6,}\\b/i.test(bodyText),
        },
      };
    })()
  `, true);
  snapshot.titleDigest = snapshot.titleText ? digest(snapshot.titleText) : null;
  delete snapshot.titleText;
  if (snapshot.activeElement) {
    snapshot.activeElement.textDigest = digest(snapshot.activeElement.text || '');
    delete snapshot.activeElement.text;
  }
  return snapshot;
}

async function captureState(window, outputDir, label, theme, width, height) {
  window.setSize(width, height, false);
  await new Promise((resolve) => setTimeout(resolve, 180));
  await setTheme(window.webContents, theme);
  const snapshot = await semanticSnapshot(window.webContents);
  if (!snapshot.canvas) throw new Error(`${label}: Result Studio canvas is absent`);
  const image = await window.webContents.capturePage();
  const png = image.toPNG();
  const file = `${label}.png`;
  writeFileSync(path.join(outputDir, file), png);
  return {
    label,
    theme,
    requestedSize: { width, height },
    screenshot: file,
    screenshotSha256: digest(png),
    screenshotBytes: png.length,
    domSha256: digest(JSON.stringify(snapshot)),
    ...snapshot,
    pageHorizontalOverflow: snapshot.viewport.scrollWidth > snapshot.viewport.clientWidth,
  };
}

async function clickMode(webContents, labels, timeoutMs = 15_000) {
  // 模式切换按钮存在两组现契约文案：CompactResultNavigator（result 模式下唯一
  // nav）用短标签「审查/历史」；ResultStudioContextBar（仅非 result 模式挂载，
  // CenterPanel contextBar 槽）用长标签「审查修改/版本历史」。contextBar 随模式
  // 挂载/卸载，且两条 nav 同为 aria-label="结果视图"，所以点击必须跨全部 nav
  // 做「标签变体 × 有界重试」，不能只查第一条 nav 或单一文案。
  const wanted = Array.isArray(labels) ? labels : [labels];
  const deadline = Date.now() + timeoutMs;
  for (;;) {
    const clicked = await webContents.executeJavaScript(`
      (() => {
        const wanted = ${JSON.stringify(wanted)};
        for (const nav of document.querySelectorAll('nav[aria-label="结果视图"]')) {
          const button = [...nav.querySelectorAll('button')]
            .find((item) => wanted.includes((item.textContent || '').trim()));
          if (button) {
            button.click();
            return true;
          }
        }
        return false;
      })()
    `, true);
    if (clicked) return;
    if (Date.now() >= deadline) {
      const diagnostics = await webContents.executeJavaScript(`
        (() => ({
          navs: [...document.querySelectorAll('nav[aria-label="结果视图"]')].map((nav) => ({
            buttons: [...nav.querySelectorAll('button')].map((item) => (item.textContent || '').trim()),
          })),
          canvasMode: document.querySelector('[aria-label="结果主画布"]')?.getAttribute('data-mode') || null,
          bodyHead: (document.body.innerText || '').replace(/\\s+/g, ' ').slice(0, 400),
        }))()
      `, true).catch(() => null);
      console.error(`[p4r-ui-driver] mode button missing: ${JSON.stringify(diagnostics)}`);
      throw new Error(`mode button not found: ${wanted.join('/')}`);
    }
    await new Promise((resolve) => setTimeout(resolve, 250));
  }
}

async function sendTrustedKey(webContents, {
  key,
  code,
  virtualKeyCode,
  text = '',
}) {
  if (!webContents.debugger.isAttached()) webContents.debugger.attach('1.3');
  await webContents.debugger.sendCommand('Page.bringToFront');
  await webContents.debugger.sendCommand('Input.dispatchKeyEvent', {
    type: 'rawKeyDown',
    key,
    code,
    windowsVirtualKeyCode: virtualKeyCode,
    nativeVirtualKeyCode: virtualKeyCode,
  });
  if (text) {
    await webContents.debugger.sendCommand('Input.dispatchKeyEvent', {
      type: 'char',
      key,
      code,
      text,
      windowsVirtualKeyCode: virtualKeyCode,
      nativeVirtualKeyCode: virtualKeyCode,
    });
  }
  await webContents.debugger.sendCommand('Input.dispatchKeyEvent', {
    type: 'keyUp',
    key,
    code,
    windowsVirtualKeyCode: virtualKeyCode,
    nativeVirtualKeyCode: virtualKeyCode,
  });
}

async function keyboardTrace(window) {
  const wc = window.webContents;
  window.show();
  window.focus();
  wc.focus();
  await new Promise((resolve) => setTimeout(resolve, 120));
  const modeActivation = await wc.executeJavaScript(`
    (() => {
      const nav = document.querySelector('nav[aria-label="结果视图"]');
      const button = nav && [...nav.querySelectorAll('button')]
        .find((item) => (item.textContent || '').trim() === '代码');
      if (!button) return null;
      button.focus();
      const style = getComputedStyle(button);
      return {
        focused: document.activeElement === button,
        focusVisible: style.outlineStyle !== 'none' || style.boxShadow !== 'none',
      };
    })()
  `, true);
  if (!modeActivation?.focused) throw new Error('could not focus the Result Studio mode switcher');
  await sendTrustedKey(wc, {
    key: 'Enter',
    code: 'Enter',
    virtualKeyCode: 13,
    text: '\r',
  });
  await waitFor(
    wc,
    `document.querySelector('[aria-label="结果主画布"]')?.getAttribute('data-mode') === 'code'`,
    'keyboard code activation',
    5_000,
  );
  await clickMode(wc, '结果');
  // 焦点播种：steps 在每次 Tab **前**采样，语义=「每次 Tab 前焦点停在交互元素」。
  // 旧结构下 代码 按钮跨模式存活、焦点保持；现结构切回 result 后 contextBar 卸载
  // 把焦点抖落回 body（steps[0]=body，判据必红）。先确定性播到画布内首个可交互
  // 元素，再走 4 步 Tab trace。
  const focusSeeded = await wc.executeJavaScript(`
    (() => {
      const seed = document.querySelector('[aria-label="结果主画布"] button, [aria-label="结果主画布"] a, [aria-label="结果主画布"] select, [aria-label="结果主画布"] textarea, [aria-label="结果主画布"] input')
        || [...document.querySelectorAll('button')]
          .find((item) => (item.getAttribute('aria-label') || '') === '返回对话');
      if (!seed) return false;
      seed.focus();
      return document.activeElement === seed;
    })()
  `, true);
  if (!focusSeeded) throw new Error('could not seed focus inside the Result Studio canvas');
  await new Promise((resolve) => setTimeout(resolve, 80));

  const steps = [];
  for (let index = 0; index < 4; index += 1) {
    steps.push(await semanticSnapshot(wc).then((snapshot) => snapshot.activeElement));
    wc.sendInputEvent({ type: 'keyDown', keyCode: 'Tab' });
    wc.sendInputEvent({ type: 'keyUp', keyCode: 'Tab' });
    await new Promise((resolve) => setTimeout(resolve, 60));
  }
  // UI-122 起图像交互为渐进增强：绑定不再自动投影散点，需显式「进入交互选择」
  // （旧契约绑定即出散点，scatterAvailable 恒真）。先开交互预览再验键盘操作。
  const interactionToggled = await wc.executeJavaScript(`
    (() => {
      const button = document.querySelector('[aria-label="进入交互选择"]');
      if (!button) return false;
      button.click();
      return true;
    })()
  `, true);
  if (interactionToggled) {
    await waitFor(wc, `Boolean(document.querySelector('[aria-label="可选择科学散点图"]'))`, 'interactive scatter viewer', 10_000);
  }
  const scatter = await wc.executeJavaScript(`
    (() => {
      const point = document.querySelector('[aria-label="可选择科学散点图"] [role="button"][tabindex="0"]');
      if (!point) return { available: false };
      point.focus();
      return {
        available: true,
        focused: document.activeElement === point,
        before: point.getAttribute('aria-pressed'),
      };
    })()
  `, true);
  let scatterActivated = false;
  if (scatter?.available && scatter.focused) {
    await sendTrustedKey(wc, {
      key: ' ',
      code: 'Space',
      virtualKeyCode: 32,
      text: ' ',
    });
    scatterActivated = await waitFor(
      wc,
      `document.activeElement?.getAttribute('role') === 'button'
        && document.activeElement?.getAttribute('aria-pressed') !== ${JSON.stringify(scatter.before)}`,
      'keyboard scatter activation',
      5_000,
    ).then(Boolean);
  }
  const result = {
    steps,
    modeEnterActivated: true,
    focusVisible: modeActivation.focusVisible,
    scatterAvailable: scatter?.available === true,
    scatterActivated,
    allFocusable: steps.every((item) => item && ['button', 'textarea', 'select', 'input', 'a'].includes(item.tag))
      && modeActivation.focusVisible
      && scatter?.available === true
      && scatterActivated,
  };
  window.hide();
  return result;
}

async function setComposerDraft(webContents, value) {
  return webContents.executeJavaScript(`
    (() => {
      const textarea = document.querySelector('textarea[aria-label="描述你希望当前结果发生什么变化"]');
      if (!textarea) return false;
      const setter = Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, 'value')?.set;
      setter?.call(textarea, ${JSON.stringify(value)});
      textarea.dispatchEvent(new Event('input', { bubbles: true }));
      return textarea.value === ${JSON.stringify(value)};
    })()
  `, true);
}

async function reopenResultTrace(window, requestedOutcome) {
  const wc = window.webContents;
  if (!await setComposerDraft(wc, requestedOutcome)) throw new Error('could not enter the Agent request draft');
  const jobId = await wc.executeJavaScript(`new URL(location.href).searchParams.get('job')`, true);
  const artifactName = await wc.executeJavaScript(`new URL(location.href).searchParams.get('artifact')`, true);
  if (typeof jobId !== 'string' || !jobId) throw new Error('open-result route is missing its transient job coordinate');
  if (typeof artifactName !== 'string' || !artifactName) throw new Error('open-result route is missing its transient artifact coordinate');
  const returned = await wc.executeJavaScript(`
    (() => {
      const button = document.querySelector('button[aria-label="返回对话"]');
      if (!button) return false;
      button.click();
      return true;
    })()
  `, true);
  if (!returned) throw new Error('return-to-conversation action is unavailable');
  await waitFor(wc, `!document.querySelector('[aria-label="结果主画布"]')`, 'conversation projection');

  const startedAt = performance.now();
  const dispatched = await wc.executeJavaScript(`
    (() => {
      // BLOCK-61 品牌改名：应用事件前缀已 petri: → petri:（frontend/src/lib/events.ts），
      // 旧名派发无人监听，重开结果等待会超时。
      window.dispatchEvent(new CustomEvent('petri:project-open-artifact', {
        detail: {
          jobId: ${JSON.stringify(jobId)},
          artifactName: ${JSON.stringify(artifactName)}
        }
      }));
      window.dispatchEvent(new CustomEvent('petri:project-open-result', {
        detail: { toolJobId: ${JSON.stringify(jobId)} }
      }));
      return true;
    })()
  `, true);
  if (!dispatched) throw new Error('could not dispatch the product open-result event');
  await waitFor(wc, `Boolean(document.querySelector('[aria-label="结果主画布"]'))`, 'result feedback');
  const feedbackMs = Number((performance.now() - startedAt).toFixed(3));
  await waitFor(
    wc,
    `document.querySelector('[aria-label="用 Agent 修改当前结果"]')?.getAttribute('data-state') === 'ready'`,
    'reopened Agent context',
  );
  const snapshot = await semanticSnapshot(wc);
  const draftPreserved = await wc.executeJavaScript(`
    document.querySelector('textarea[aria-label="描述你希望当前结果发生什么变化"]')?.value
      === ${JSON.stringify(requestedOutcome)}
  `, true);
  return {
    feedbackMs,
    firstContentVisibleMs: snapshot.canvas?.firstVisibleMs ?? null,
    domSha256: digest(JSON.stringify(snapshot)),
    draftPreserved,
    draftDigest: digest(requestedOutcome),
    ...snapshot,
  };
}

async function candidateLifecycleTrace(window) {
  const wc = window.webContents;
  // 版本/变更面板（含「采用此版本」）只在 compare/history 模式挂载
  // （ResultArtifactShell: mode === 'compare' || 'history'；result 模式右栏是产物
  // 详情）。先切「审查」再等候选——曾在 result 模式下等按钮，面板搬移后
  // 该等待恒超时。
  await clickMode(wc, ['审查', '审查修改']);
  await waitFor(
    wc,
    `document.querySelector('[aria-label="结果主画布"]')?.getAttribute('data-mode') === 'compare'`,
    'candidate compare',
  );
  await waitFor(
    wc,
    `Boolean([...document.querySelectorAll('button')].find((item) => (item.textContent || '').trim() === '采用此版本'))`,
    'deterministic Agent candidate',
  );
  const compare = await semanticSnapshot(wc);
  const compareActionable = await wc.executeJavaScript(`
    Boolean(document.querySelector('[aria-label="Result Studio 版本与变更"]'))
      && Boolean([...document.querySelectorAll('button')]
        .find((item) => (item.textContent || '').trim() === '采用此版本'))
  `, true);
  if (!await clickButtonByText(wc, '采用此版本')) throw new Error('candidate adopt action is unavailable');
  // UI-305 起采纳后产品契约=onRevisionActivated 自动跳回 result 模式展示已采用
  // 版本，compare 面板随之卸载（旧捕获时面板原地翻转状态，故旧驱动在 compare
  // 原地等「撤销本次采用」）。等跳转落定后切回「审查」，面板重挂时 adopted
  // change set 为首选选中项，「撤销本次采用」在场。
  await waitFor(
    wc,
    `document.querySelector('[aria-label="结果主画布"]')?.getAttribute('data-mode') === 'result'
      || Boolean([...document.querySelectorAll('button')].find((item) => (item.textContent || '').trim() === '撤销本次采用'))`,
    'post-adopt projection',
  );
  const postAdoptMode = await wc.executeJavaScript(
    `document.querySelector('[aria-label="结果主画布"]')?.getAttribute('data-mode') || null`,
    true,
  );
  if (postAdoptMode === 'result') {
    await clickMode(wc, ['审查', '审查修改']);
    await waitFor(
      wc,
      `document.querySelector('[aria-label="结果主画布"]')?.getAttribute('data-mode') === 'compare'`,
      'post-adopt compare reentry',
    );
  }
  await waitFor(
    wc,
    `Boolean([...document.querySelectorAll('button')].find((item) => (item.textContent || '').trim() === '撤销本次采用'))`,
    'candidate adoption',
  );
  const adopted = await semanticSnapshot(wc);
  if (!await clickButtonByText(wc, '撤销本次采用')) throw new Error('candidate undo action is unavailable');
  await waitFor(
    wc,
    `![...document.querySelectorAll('button')].some((item) => (item.textContent || '').trim() === '撤销本次采用')`,
    'candidate undo',
  );

  await clickMode(wc, ['历史', '版本历史']);
  await waitFor(
    wc,
    `document.querySelector('[aria-label="结果主画布"]')?.getAttribute('data-mode') === 'history'`,
    'history mode',
  );
  const restored = await wc.executeJavaScript(`
    (() => {
      const rows = [...document.querySelectorAll('[aria-label="Result Studio 版本与变更"] [class*="historyRow"]')];
      const row = rows.find((item) => /^v2(?:\\s|·|$)/.test((item.querySelector('strong')?.textContent || '').trim()));
      const button = row && [...row.querySelectorAll('button')]
        .find((item) => (item.textContent || '').trim() === '恢复为新版本');
      if (!button) return false;
      button.click();
      return true;
    })()
  `, true);
  if (!restored) throw new Error('v2 restore action is unavailable');
  // 与采纳同族：UI-305 起 restore 也经 onRevisionActivated 跳回 result 模式，
  // history 面板卸载——旧契约是面板原地刷新出「当前 v3」。等跳转（或原地刷新）
  // 落定后切回「历史」等「当前 v3」。
  await waitFor(
    wc,
    `document.querySelector('[aria-label="结果主画布"]')?.getAttribute('data-mode') === 'result'
      || [...document.querySelectorAll('[aria-label="Result Studio 版本与变更"] span')]
        .some((item) => (item.textContent || '').trim() === '当前 v3')`,
    'post-restore projection',
  );
  const postRestoreMode = await wc.executeJavaScript(
    `document.querySelector('[aria-label="结果主画布"]')?.getAttribute('data-mode') || null`,
    true,
  );
  if (postRestoreMode === 'result') {
    await clickMode(wc, ['历史', '版本历史']);
    await waitFor(
      wc,
      `document.querySelector('[aria-label="结果主画布"]')?.getAttribute('data-mode') === 'history'`,
      'post-restore history reentry',
    );
  }
  await waitFor(
    wc,
    `[...document.querySelectorAll('[aria-label="Result Studio 版本与变更"] span')]
      .some((item) => (item.textContent || '').trim() === '当前 v3')`,
    'restored v3',
  );

  await clickMode(wc, '代码');
  await waitFor(wc, `Boolean(document.querySelector('[aria-label="代码操作"]'))`, 'restored Revision code');
  const openedMenu = await wc.executeJavaScript(`
    (() => {
      const summary = [...document.querySelectorAll('summary')]
        .find((item) => (item.textContent || '').trim() === '交给 Agent');
      if (!summary) return false;
      summary.click();
      return true;
    })()
  `, true);
  if (!openedMenu || !await clickButtonByText(wc, '受控重放')) {
    throw new Error('controlled replay preflight action is unavailable');
  }
  await waitFor(wc, `Boolean(document.querySelector('[aria-label="受控重放确认"]'))`, 'controlled replay confirmation');
  if (!await clickButtonByText(wc, '确认受控重放')) throw new Error('controlled replay confirmation is unavailable');
  await waitFor(
    wc,
    `document.querySelector('[aria-label="结果主画布"]')?.getAttribute('data-mode') === 'compare'`,
    'replay candidate compare',
  );
  await waitFor(
    wc,
    `Boolean([...document.querySelectorAll('button')].find((item) => (item.textContent || '').trim() === '放弃候选'))`,
    'replay candidate',
  );
  if (!await clickButtonByText(wc, '放弃候选')) throw new Error('replay candidate discard is unavailable');
  await waitFor(
    wc,
    `![...document.querySelectorAll('button')].some((item) => (item.textContent || '').trim() === '放弃候选')`,
    'replay candidate discard',
  );
  await clickMode(wc, '结果');
  await waitFor(
    wc,
    `document.querySelector('[aria-label="用 Agent 修改当前结果"]')?.getAttribute('data-state') === 'ready'`,
    'post-lifecycle Agent context',
  );
  return {
    compareVisible: compareActionable,
    compareDigest: digest(JSON.stringify(compare)),
    adoptedVersionKind: adopted.versionKind,
    adopted: true,
    undone: true,
    restoredOrdinal: 3,
    replayConfirmed: true,
    replayCandidateDiscarded: true,
  };
}

async function serviceRestartTrace(window, canonicalUrl) {
  const wc = window.webContents;
  const before = await semanticSnapshot(wc);
  const webContentsId = wc.id;
  process.stdout.write('__P4R6_BACKEND_RESTART_REQUEST__\n');
  await waitForControlLine('__P4R6_BACKEND_STOPPED__');
  const unreachable = await wc.executeJavaScript(`
    fetch('http://localhost:3001/api/health').then(() => false).catch(() => true)
  `, true);
  process.stdout.write('__P4R6_BACKEND_RESTART_CONTINUE__\n');
  await waitForControlLine('__P4R6_BACKEND_RESTARTED__');
  await window.loadURL(canonicalUrl);
  await waitFor(wc, `Boolean(document.querySelector('[aria-label="结果主画布"]'))`, 'post-restart result canvas');
  await waitFor(
    wc,
    `document.querySelector('[aria-label="用 Agent 修改当前结果"]')?.getAttribute('data-state') === 'ready'`,
    'post-restart Agent context',
  );
  const after = await semanticSnapshot(wc);
  // 现契约 result 模式画布不再自带版本 header（flatten 后版本投影移到 compare/
  // history 的版本面板）——重启后版本可恢复性改经「审查」面板验「当前 v3」，
  // 验完回「结果」保持后续故障矩阵的深链 result 形态。
  await clickMode(wc, ['审查', '审查修改']);
  await waitFor(
    wc,
    `[...document.querySelectorAll('[aria-label="Result Studio 版本与变更"] span')]
      .some((item) => (item.textContent || '').trim() === '当前 v3')`,
    'post-restart version panel',
  );
  await clickMode(wc, '结果');
  return {
    sameWebContents: wc.id === webContentsId,
    backendWasUnreachable: unreachable === true,
    resultRecovered: after.bodyVisible,
    composerRecovered: after.composerState === 'ready',
    versionRecovered: true,
    beforeDigest: digest(JSON.stringify(before)),
    afterDigest: digest(JSON.stringify(after)),
  };
}

async function clickButtonByText(webContents, text) {
  return webContents.executeJavaScript(`
    (() => {
      const button = [...document.querySelectorAll('button')]
        .find((item) => (item.textContent || '').trim() === ${JSON.stringify(text)});
      if (!button) return false;
      button.click();
      return true;
    })()
  `, true);
}

// keyboardTrace 结尾的 window.hide() 之后，合成器会对隐藏窗口停帧——capturePage
// 走 viz CopyOutputRequest 直接拒绝 UnknownVizError（Chromium CopyOutputResult
// Status，跨域无栈）。矩阵段（hide 之前）连捕 6 次不受影响。韧性回退：临时
// 显示窗口恢复帧产出再捕；不改变 DOM/语义态，窗口运行结束即销毁。
async function capturePageResilient(window) {
  try {
    return await window.webContents.capturePage();
  } catch (error) {
    window.show();
    await new Promise((resolve) => setTimeout(resolve, 300));
    return window.webContents.capturePage();
  }
}

async function captureFailureScreenshot(window, outputDir, kind) {
  const snapshot = await semanticSnapshot(window.webContents);
  const png = (await capturePageResilient(window)).toPNG();
  const screenshot = `failure-${kind}.png`;
  writeFileSync(path.join(outputDir, screenshot), png);
  return {
    kind,
    bodyPreserved: snapshot.bodyVisible,
    pageHorizontalOverflow: snapshot.viewport.scrollWidth > snapshot.viewport.clientWidth,
    domSha256: digest(JSON.stringify(snapshot)),
    screenshot,
    screenshotSha256: digest(png),
    screenshotBytes: png.length,
    degradationVisible: snapshot.degradationVisible,
    internalLeakFlags: snapshot.internalLeakFlags,
  };
}

// UI-122 起图像交互失败为渐进增强的静默降级（resultSurface.shouldSurfaceInteractionFailure
// 只对 table 报错；图像「failed discovery must leave the static plot quiet and usable」）。
// 旧契约（图像也出「重试交互能力」可行动恢复）已不存在——旧驱动在深链 volcano PNG 上等
// 重试按钮恒超时。本段按现契约断言：交互端点被拦时主体图像保持可见、无重试按钮、
// 无降级横幅、composer 仍就绪；解阻后重载恢复。
async function interactionQuietDegradationTrace(window, blocked, outputDir) {
  const wc = window.webContents;
  const routeFragment = '/api/result-studio/interaction';
  blocked.add(routeFragment);
  await wc.reload();
  await waitFor(wc, `Boolean(document.querySelector('[aria-label="结果主画布"]'))`, 'interaction quiet canvas');
  await waitFor(wc, `Boolean(document.querySelector('[aria-label="结果主画布"] img, [aria-label="结果主画布"] [role="img"]'))`, 'interaction quiet primary image');
  await waitFor(wc, `document.querySelector('[aria-label="用 Agent 修改当前结果"]')?.getAttribute('data-state') === 'ready'`, 'interaction quiet composer');
  const observation = await captureFailureScreenshot(window, outputDir, 'interaction-quiet');
  const quietState = await wc.executeJavaScript(`
    (() => ({
      retryButtonPresent: Boolean([...document.querySelectorAll('button')]
        .find((item) => (item.textContent || '').trim() === '重试交互能力')),
      degradationVisible: Boolean(document.querySelector('[role="alert"], [data-state="blocked"], [data-state="unavailable"]')),
    }))()
  `, true);
  blocked.delete(routeFragment);
  await wc.reload();
  await waitFor(wc, `Boolean(document.querySelector('[aria-label="结果主画布"] img, [aria-label="结果主画布"] [role="img"]'))`, 'interaction recovery primary image');
  await waitFor(wc, `document.querySelector('[aria-label="用 Agent 修改当前结果"]')?.getAttribute('data-state') === 'ready'`, 'interaction recovery composer');
  return {
    ...observation,
    quietByContract: !quietState.retryButtonPresent && !quietState.degradationVisible,
    imagePreserved: observation.bodyPreserved,
    recovered: true,
  };
}

async function retryableFailureTrace(window, blocked, outputDir, {
  kind,
  routeFragment,
  retryLabel,
  prepare,
  recoveredExpression,
  verifyPrimaryBody = false,
  waitForPrimaryBody = false,
}) {
  blocked.add(routeFragment);
  if (prepare) await prepare();
  else await window.webContents.reload();
  await waitFor(
    window.webContents,
    `Boolean([...document.querySelectorAll('button')].find((item) => (item.textContent || '').trim() === ${JSON.stringify(retryLabel)}))`,
    `${kind} actionable failure`,
  );
  if (waitForPrimaryBody) {
    await waitFor(
      window.webContents,
      `Boolean(document.querySelector('[aria-label="结果主画布"] [class*="resultSidebarPreviewBody"] > *'))`,
      `${kind} independent primary result`,
    );
  }
  const observation = await captureFailureScreenshot(window, outputDir, kind);
  if (verifyPrimaryBody) {
    await clickMode(window.webContents, '结果');
    await waitFor(
      window.webContents,
      `Boolean(document.querySelector('[aria-label="结果主画布"] [class*="resultSidebarPreviewBody"] > *'))`,
      `${kind} primary result preservation`,
    );
    observation.bodyPreserved = (await semanticSnapshot(window.webContents)).bodyVisible;
    await prepare();
    await waitFor(
      window.webContents,
      `Boolean([...document.querySelectorAll('button')].find((item) => (item.textContent || '').trim() === ${JSON.stringify(retryLabel)}))`,
      `${kind} failure after primary result verification`,
    );
  }
  blocked.delete(routeFragment);
  if (!await clickButtonByText(window.webContents, retryLabel)) {
    throw new Error(`${kind}: retry action disappeared`);
  }
  await waitFor(
    window.webContents,
    recoveredExpression || `![...document.querySelectorAll('button')].some((item) => (item.textContent || '').trim() === ${JSON.stringify(retryLabel)})`,
    `${kind} recovery`,
  );
  return { ...observation, actionable: true, recovered: true };
}

async function contextFailureTrace(window, blocked, outputDir, canonicalUrl) {
  const routeFragment = '/api/result-studio/context-envelope';
  blocked.add(routeFragment);
  await window.webContents.reload();
  await waitFor(
    window.webContents,
    `document.querySelector('[aria-label="用 Agent 修改当前结果"]')?.getAttribute('data-state') === 'blocked'`,
    'context fail-closed projection',
  );
  await waitFor(
    window.webContents,
    `Boolean(document.querySelector('[aria-label="结果主画布"] [class*="resultSidebarPreviewBody"] > *'))`,
    'context failure preserved body',
  );
  const observation = await captureFailureScreenshot(window, outputDir, 'context');
  blocked.delete(routeFragment);
  const recoveryStatus = await window.webContents.executeJavaScript(`
    (() => {
      const locationUrl = new URL(location.href);
      const projectId = locationUrl.pathname.split('/').filter(Boolean).at(-1);
      const jobId = locationUrl.searchParams.get('job');
      const artifact = locationUrl.searchParams.get('artifact');
      const query = new URLSearchParams({ projectId: projectId || '', jobId: jobId || '', artifact: artifact || '' });
      return fetch('http://localhost:3001/api/result-studio/context-envelope?' + query.toString())
        .then((response) => response.status)
        .catch(() => 0);
    })()
  `, true);
  if (!Number.isInteger(recoveryStatus) || recoveryStatus <= 0) {
    throw new Error('context endpoint remained unreachable after removing the injected failure');
  }
  await window.loadURL(canonicalUrl);
  await waitFor(
    window.webContents,
    `Boolean(document.querySelector('[aria-label="结果主画布"]'))`,
    'context recovery result canvas',
  );
  await waitFor(
    window.webContents,
    `document.querySelector('[aria-label="用 Agent 修改当前结果"]')?.getAttribute('data-state') === 'ready'`,
    'context recovery Agent binding',
  );
  const recoveredSnapshot = await semanticSnapshot(window.webContents);
  return {
    ...observation,
    actionable: true,
    failClosed: true,
    recovered: true,
    recoveryStatusClass: recoveryStatus < 500 ? 'reachable_bounded_response' : 'server_error',
    recoveredComposerState: recoveredSnapshot.composerState,
  };
}

// 首启引导浮层关闭（与 g0-rs-p6-recovery-electron-driver 同法）：
// fresh userData 下 DesktopOnboarding 必现，点「跳过引导」写入完成标记。
async function dismissOnboarding(webContents) {
  await waitFor(webContents, `
    (() => {
      const dialog = document.querySelector('[role="dialog"][aria-label="首次启动引导"]');
      if (!dialog) return true;
      const button = [...dialog.querySelectorAll('button')]
        .find((item) => (item.textContent || '').trim() === '跳过引导' && !item.disabled);
      if (!button) return false;
      button.click();
      return true;
    })()
  `, 'onboarding');
}

async function run() {
  const config = readConfig();
  mkdirSync(config.outputDir, { recursive: true });
  const checkpoint = (stage) => {
    driverLastStage = stage;
    writeFileSync(config.resultPath, `${JSON.stringify({ schemaVersion: 1, passed: false, stage })}\n`);
  };
  checkpoint('starting');

  const blocked = new Set();
  session.defaultSession.webRequest.onBeforeRequest((details, callback) => {
    const matched = [...blocked].some((fragment) => details.url.includes(fragment));
    callback({ cancel: matched });
  });

  const window = new BrowserWindow({
    width: 1440,
    height: 900,
    show: false,
    backgroundColor: '#ffffff',
    webPreferences: {
      contextIsolation: true,
      nodeIntegration: false,
      sandbox: true,
    },
  });
  await window.loadURL(config.url);
  checkpoint('page_loaded');
  await waitFor(
    window.webContents,
    `Boolean(document.querySelector('[aria-label="结果主画布"]'))`,
    'Result Studio canvas',
  );
  // 首启引导浮层（fresh userData 必现）：必须在画布等待**之后**关——React 挂载
  // 引导晚于 loadURL 返回，过早探测会误判「无引导」。不关掉会盖住工作区、污染
  // 矩阵截图并拦截语义点击。与 P6 recovery 驱动同法：点「跳过引导」落完成标记。
  await dismissOnboarding(window.webContents);
  await waitFor(
    window.webContents,
    `Boolean(document.querySelector('[aria-label="结果主画布"] img, [aria-label="结果主画布"] table, [aria-label="结果主画布"] iframe, [aria-label="结果主画布"] pre, [aria-label="结果主画布"] [role="img"]'))`,
    'visible result body',
  );
  await waitFor(
    window.webContents,
    `document.querySelector('[aria-label="用 Agent 修改当前结果"]')?.getAttribute('data-state') === 'ready'`,
    'initial Agent context',
  );
  const initialResult = await semanticSnapshot(window.webContents);
  checkpoint('initial_result_visible');

  const openResult = await reopenResultTrace(window, config.requestedOutcome);
  checkpoint('result_reopened');
  await waitFor(
    window.webContents,
    `Boolean(document.querySelector('[aria-label="结果主画布"] [class*="resultSidebarPreviewBody"] > *'))`,
    'reopened visible result body',
  );

  const matrix = [];
  for (const theme of ['light', 'dark']) {
    for (const width of [1440, 1024, 820]) {
      matrix.push(await captureState(window, config.outputDir, `${theme}-${width}`, theme, width, 900));
    }
  }
  checkpoint('matrix_captured');

  const modeTrace = [];
  for (const [mode, label] of [
    ['code', '代码'],
    ['compare', ['审查', '审查修改']],
    ['history', ['历史', '版本历史']],
    ['result', '结果'],
  ]) {
    const startedAt = performance.now();
    await clickMode(window.webContents, label);
    await waitFor(
      window.webContents,
      `document.querySelector('[aria-label="结果主画布"]')?.getAttribute('data-mode') === ${JSON.stringify(mode)}`,
      `mode ${mode}`,
    );
    const snapshot = await semanticSnapshot(window.webContents);
    modeTrace.push({
      mode,
      feedbackMs: Number((performance.now() - startedAt).toFixed(3)),
      domSha256: digest(JSON.stringify(snapshot)),
      ...snapshot,
    });
  }

  const keyboard = await keyboardTrace(window);
  checkpoint('keyboard_captured');

  await clickMode(window.webContents, '结果');
  const lifecycle = await candidateLifecycleTrace(window);
  checkpoint('candidate_lifecycle_captured');
  const serviceRestart = await serviceRestartTrace(window, config.url);
  checkpoint('service_restart_captured');

  const failures = [];
  const interactionQuiet = await interactionQuietDegradationTrace(window, blocked, config.outputDir);
  // 版本/存储重试按钮挂在 compare/history 模式才装载的版本面板上（UI-305 后
  // result 模式右栏是产物详情，reload 落回深链 result 模式面板不挂载）——
  // prepare 先把面板带起来，让被拦拉取在其挂载期失败、按契约出可行动恢复。
  failures.push(await retryableFailureTrace(window, blocked, config.outputDir, {
    kind: 'versions',
    routeFragment: '/api/result-studio/changesets?',
    retryLabel: '重试版本',
    prepare: () => clickMode(window.webContents, ['审查', '审查修改']),
    verifyPrimaryBody: true,
  }));
  failures.push(await retryableFailureTrace(window, blocked, config.outputDir, {
    kind: 'storage',
    routeFragment: '/api/result-studio/workspace/status',
    retryLabel: '重试存储状态',
    prepare: async () => {
      // workspace 状态只在面板挂载时拉一次：先切走再切回，强制重挂 + 被拦重拉。
      await clickMode(window.webContents, '结果');
      await clickMode(window.webContents, ['审查', '审查修改']);
    },
    verifyPrimaryBody: true,
  }));
  failures.push(await retryableFailureTrace(window, blocked, config.outputDir, {
    kind: 'code',
    routeFragment: '/api/result-studio/revisions/',
    retryLabel: '重试',
    prepare: async () => {
      await clickMode(window.webContents, '代码');
    },
    verifyPrimaryBody: true,
    recoveredExpression: `Boolean(document.querySelector('[aria-label="代码操作"]'))`,
  }));
  await clickMode(window.webContents, '结果');
  failures.push(await contextFailureTrace(window, blocked, config.outputDir, config.url));
  checkpoint('failure_matrix_captured');

  const screenshotHashes = matrix.map((item) => item.screenshotSha256);
  const result = {
    schemaVersion: 1,
    renderer: `Electron ${process.versions.electron} / Chromium ${process.versions.chrome}`,
    initialResult,
    openResult,
    matrix,
    modeTrace,
    keyboard,
    lifecycle,
    serviceRestart,
    failures,
    interactionQuiet,
    allMatrixStatesCaptured: matrix.length === 6,
    allScreenshotsDistinct: new Set(screenshotHashes).size === screenshotHashes.length,
    noHorizontalOverflow: matrix.every((item) => !item.pageHorizontalOverflow),
    bodyVisibleEverywhere: matrix.every((item) => item.bodyVisible),
    composerReadyEverywhere: initialResult.composerState === 'ready'
      && openResult.composerState === 'ready'
      && matrix.every((item) => item.composerState === 'ready'),
    noSensitiveProjection: [initialResult, openResult, ...matrix, ...modeTrace, ...failures, interactionQuiet]
      .every((item) => Object.values(item.internalLeakFlags || {}).every((flag) => !flag)),
    primaryActionBudgetMet: [...matrix, ...modeTrace].every((item) => item.visiblePrimaryActionCount <= 3),
    secondaryFailureRecoveryPassed: failures.length === 4
      && failures.every((item) => item.bodyPreserved
        && item.actionable
        && item.recovered
        && item.degradationVisible
        && !item.pageHorizontalOverflow)
      && interactionQuiet.quietByContract
      && interactionQuiet.imagePreserved
      && interactionQuiet.recovered
      && !interactionQuiet.pageHorizontalOverflow,
    continuousLifecyclePassed: openResult.draftPreserved
      && lifecycle.compareVisible
      && lifecycle.adopted
      && lifecycle.undone
      && lifecycle.restoredOrdinal === 3
      && lifecycle.replayConfirmed
      && lifecycle.replayCandidateDiscarded,
    serviceRestartPassed: Object.entries(serviceRestart)
      .filter(([key]) => !key.endsWith('Digest'))
      .every(([, value]) => value === true),
    visibleFeedbackBudget: {
      targetMs: 100,
      observedModeSwitchMaxMs: Math.max(...modeTrace.map((item) => item.feedbackMs)),
      modeSwitchPassed: modeTrace.every((item) => item.feedbackMs <= 100),
      openResultFeedbackMs: openResult.feedbackMs,
      openResultFeedbackPassed: openResult.feedbackMs <= 100,
      firstContentVisibleMs: openResult.firstContentVisibleMs,
      firstContentPassed: Number.isFinite(openResult.firstContentVisibleMs)
        ? openResult.firstContentVisibleMs <= 1_000
        : false,
    },
  };
  result.passed = result.allMatrixStatesCaptured
    && result.allScreenshotsDistinct
    && result.noHorizontalOverflow
    && result.bodyVisibleEverywhere
    && result.composerReadyEverywhere
    && result.noSensitiveProjection
    && result.primaryActionBudgetMet
    && result.secondaryFailureRecoveryPassed
    && result.continuousLifecyclePassed
    && result.serviceRestartPassed
    && keyboard.allFocusable
    && result.visibleFeedbackBudget.modeSwitchPassed
    && result.visibleFeedbackBudget.openResultFeedbackPassed
    && result.visibleFeedbackBudget.firstContentPassed;
  writeFileSync(config.resultPath, `${JSON.stringify(result, null, 2)}\n`);
  window.destroy();
}

app.whenReady()
  .then(run)
  .then(() => app.quit())
  .catch((error) => {
    try {
      const config = readConfig();
      writeFileSync(config.resultPath, `${JSON.stringify({
        schemaVersion: 1,
        passed: false,
        stage: driverLastStage,
        error: error && error.message ? error.message : String(error),
      }, null, 2)}\n`);
    } catch {
      // Parent receives the non-zero exit even if the disposable result cannot be written.
    }
    console.error(error && error.stack ? error.stack : error);
    app.exit(1);
  });

#!/usr/bin/env node

/**
 * G0-RS-P4R-6 real renderer observation.
 *
 * One parent process owns the complete disposable lifecycle:
 *
 *   real run_tool corpus -> isolated backend :3001 -> Vite :3000
 *   -> hidden Electron/Chromium driver -> bounded screenshots + DOM evidence
 *   -> stop every child -> remove the disposable root.
 *
 * This replaces the former manual/multi-session capture shape. It fails closed
 * when either fixed renderer port is occupied, installs signal cleanup, never
 * points at user data, and only writes canonical evidence when exact HEAD
 * contains every hashed producer/source file.
 */

