        totalRows,
        visibleRows: inputs.length,
        firstVisibleDigest: inputs[0]?.getAttribute('aria-label') || null,
        canvasFirstVisibleMs: Number(document.querySelector('[aria-label="结果主画布"]')?.getAttribute('data-first-visible-ms')) || null,
      };
    })()
  `, 'virtual_table_ready');
}

