          const source = new URL(value || '', window.location.href);
          const match = source.pathname.match(/\\/tools\\/file\\/([^/]+)\\/([^/]+)$/);
          return Boolean(match
            && decodeURIComponent(match[1]) === expectedJobId
            && decodeURIComponent(match[2]) === expectedArtifact);
