async function failureDiagnostic(webContents) {
  try {
    return await webContents.executeJavaScript(`
      (() => {
        const canvas = document.querySelector('[aria-label="结果主画布"]');
        const tableViewport = document.querySelector('[aria-label="科学结果表格"]');
        const visibleText = (document.body?.innerText || '').replace(/\\s+/g, ' ').trim();
        const images = [...(canvas?.querySelectorAll('img') || [])].slice(0, 10).map((image) => {
          let sourceKind = 'unknown';
          try {
            const source = new URL(image.currentSrc || image.src || '', window.location.href);
            sourceKind = source.pathname.includes('/result-studio/revisions/')
              ? 'revision'
              : source.pathname.includes('/tools/file/')
                ? 'tool_file'
                : source.protocol === 'data:'
                  ? 'embedded'
                  : 'other';
          } catch {}
          return {
            sourceKind,
            complete: image.complete,
            naturalWidth: image.naturalWidth,
            naturalHeight: image.naturalHeight,
          };
        });
        const resourceTimings = performance.getEntriesByType('resource')
          .filter((entry) => {
            try {
              return new URL(entry.name).pathname.includes('/tools/file/');
            } catch {
              return false;
            }
          })
          .slice(-20)
          .map((entry) => {
            let artifactName = 'unknown';
            try {
              artifactName = decodeURIComponent(new URL(entry.name).pathname.split('/').at(-1) || 'unknown');
            } catch {}
            return {
              artifactName,
              initiatorType: entry.initiatorType || 'unknown',
              durationMs: Math.round(entry.duration * 100) / 100,
              responseStatus: Number.isFinite(entry.responseStatus) ? entry.responseStatus : null,
              transferSize: Number.isFinite(entry.transferSize) ? entry.transferSize : null,
              encodedBodySize: Number.isFinite(entry.encodedBodySize) ? entry.encodedBodySize : null,
              decodedBodySize: Number.isFinite(entry.decodedBodySize) ? entry.decodedBodySize : null,
            };
          });
        return {
          canvasPresent: Boolean(canvas),
          tableViewportPresent: Boolean(tableViewport),
          images,
          resourceTimings,
          viewerModes: [...(canvas?.querySelectorAll('[data-mode]') || [])]
            .map((item) => item.getAttribute('data-mode')).filter(Boolean).slice(0, 20),
          canvasText: (canvas?.innerText || '').replace(/\\s+/g, ' ').trim().slice(0, 2_000),
          bodyText: visibleText.slice(0, 4_000),
        };
      })()
    `, true);
  } catch (error) {
    return { inspectionError: String(error?.message || error).slice(0, 500) };
  }
}

async function run() {
  const config = readConfig();
  const backendStatusObservation = registerBackendStatusHandler(config);
  const compatibilityObservation = registerIsolatedCompatibilityHandlers();
  let stage = 'window_create';
  const gone = [];
  const rendererConsole = [];
  const window = new BrowserWindow({
    width: 1440,
    height: 900,
    show: config.show === true,
    title: 'Petri P6 isolated pressure observation',
    backgroundColor: '#ffffff',
    webPreferences: {
      contextIsolation: true,
      nodeIntegration: false,
      sandbox: true,
      preload: PRELOAD_PATH,
    },
  });
  const artifactNetworkObservation = registerArtifactNetworkObservation(window.webContents, config);
  window.webContents.on('render-process-gone', (_event, details) => {
    gone.push({ reason: details?.reason || 'unknown', exitCode: details?.exitCode ?? null });
  });
  window.webContents.on('console-message', (_event, level, message) => {
    if (Number(level) < 2) return;
    rendererConsole.push(String(message || '').slice(0, 1_000));
    if (rendererConsole.length > 20) rendererConsole.shift();
  });

  try {
    const memorySamples = [];
    const publicProjectionSamples = [];

    stage = 'table_load';
    const tableNavigationMs = await navigate(window, config, config.targets.table, 'result');
    const table = await inspectTable(window.webContents);
    await attachDebugger(window.webContents);
    const tableCapture = await visualDigest(window);
    memorySamples.push(await sampleMemory(window.webContents, 'table_baseline'));

    stage = 'table_scroll';
    const scroll = await measureTableScroll(window.webContents);
    const selection = await measureSelectionFeedback(window.webContents);
    const virtualPage = await measureVirtualPageLoad(window.webContents);
    const sort = await measureSortFeedback(window.webContents);
    const filter = await measureFilterFeedback(window.webContents);
    memorySamples.push(await sampleMemory(window.webContents, 'table_interactions'));
    publicProjectionSamples.push(await inspectPublicProjection(window.webContents));

    stage = 'png_load';
    const pngStarted = performance.now();
    const pngSwitch = await measureArtifactSwitch(
      window.webContents,
      config.targets.png,
      { useSection: true },
    );
    if (!pngSwitch.changed) throw new Error('png_artifact_switch_failed');
    const png = await inspectPlotProjection(window.webContents, config.targets.png);
    const pngLoadMs = performance.now() - pngStarted;
    const pngCapture = await visualDigest(window);
    memorySamples.push(await sampleMemory(window.webContents, 'png'));
    publicProjectionSamples.push(await inspectPublicProjection(window.webContents));

    stage = 'svg_load';
    const svgStarted = performance.now();
    // UX1A-era product contract: SVG/PDF are export variants of the plot
    // option (`导出 SVG` anchor), not switchable preview surfaces. The honest
    // renderer observation is: the export link targets the real
    // `/tools/file/<jobId>/volcano.svg` artifact and the renderer can fetch
    // and parse its bytes.
    const svg = await inspectSvgExport(window.webContents, config.targets.svg);
    const svgLoadMs = performance.now() - svgStarted;
    const svgCapture = await visualDigest(window);
    memorySamples.push(await sampleMemory(window.webContents, 'svg'));
    publicProjectionSamples.push(await inspectPublicProjection(window.webContents));

    stage = 'report_load';
    const reportStarted = performance.now();
    await navigate(window, config, config.targets.report, 'result');
    const report = await inspectReport(window.webContents, config.targets.report);
    const reportLoadMs = performance.now() - reportStarted;
    const reportCapture = await visualDigest(window);
    memorySamples.push(await sampleMemory(window.webContents, 'report'));
    publicProjectionSamples.push(await inspectPublicProjection(window.webContents));
    publicProjectionSamples.push(report.publicProjectionAudit);

    stage = 'compare_load';
    await navigate(window, config, config.targets.table, 'result');
    const compareStarted = performance.now();
    await switchResultMode(window.webContents, '审查', 'compare');
    const firstProgressivePage = await openProgressiveTable(window.webContents);
    const compareOpenMs = performance.now() - compareStarted;
    const progressivePages = [{ rows: firstProgressivePage.rows, loadMs: null }];
    for (const expectedRows of [100, 150, 200]) {
      progressivePages.push(await loadMoreProgressiveTable(window.webContents, expectedRows));
    }
    const compareCapture = await visualDigest(window);
    memorySamples.push(await sampleMemory(window.webContents, 'compare'));
    publicProjectionSamples.push(await inspectPublicProjection(window.webContents));

    stage = 'history_load';
    const historyStarted = performance.now();
    // compare mode renders the ResultStudioContextBar switcher, whose labels
    // are still 审查修改/版本历史; only the result-mode compact navigator uses
    // the short 审查/历史 labels.
    await switchResultMode(window.webContents, '版本历史', 'history');
    const historyFirst = await inspectHistory(window.webContents);
    const historyFirstPageMs = performance.now() - historyStarted;
    const historySecond = await loadMoreHistory(window.webContents, historyFirst.versions);
    const historyCapture = await visualDigest(window);
    memorySamples.push(await sampleMemory(window.webContents, 'history'));
    publicProjectionSamples.push(await inspectPublicProjection(window.webContents));

    const publicProjectionAudit = Object.fromEntries(
      ['absolutePath', 'providerMaterial', 'rawInternalId']
        .map((key) => [key, publicProjectionSamples.some((sample) => sample?.[key] === true)]),
    );
    const baseline = memorySamples[0];
    const peakRaw = Math.max(...memorySamples.map((item) => item.rawUsedBytes));
    const peakPostGc = Math.max(...memorySamples.map((item) => item.postGcUsedBytes));
    const workingSets = memorySamples.map((item) => item.workingSetBytes).filter(Number.isFinite);
    const memory = {
      baselinePostGcBytes: baseline.postGcUsedBytes,
      peakRawUsedBytes: peakRaw,
      peakRawGrowthBytes: Math.max(0, peakRaw - baseline.postGcUsedBytes),
      peakPostGcUsedBytes: peakPostGc,
      peakPostGcGrowthBytes: Math.max(0, peakPostGc - baseline.postGcUsedBytes),
      peakWorkingSetBytes: workingSets.length > 0 ? Math.max(...workingSets) : null,
      samples: memorySamples,
    };

    const result = {
      schemaVersion: 1,
      renderer: `Electron ${process.versions.electron}; Chromium ${process.versions.chrome}`,
      table: {
        totalRows: table.totalRows,
        visibleRows: table.visibleRows,
        navigationMs: tableNavigationMs,
        // Cold result routes do not create the in-app transition mark. The
        // driver wall clock starts before loadURL and stops only after the
        // real result canvas exists, so it is the conservative first-canvas
        // measurement for this Electron launch path.
        canvasFirstVisibleMs: tableNavigationMs,
        productCanvasFirstVisibleMs: table.canvasFirstVisibleMs,
        scrollFeedbackMs: scroll.feedbackMs,
        scrollChanged: scroll.changed,
        selectionFeedbackMs: selection.feedbackMs,
        selectionChanged: selection.selected,
        sortFeedbackMs: sort.feedbackMs,
        sortChanged: sort.changed,
        filterFeedbackMs: filter.feedbackMs,
        filterQueryCompleteMs: filter.queryCompleteMs,
        filterChanged: filter.changed,
        filterQueryChanged: filter.queryChanged,
        filterMatchedSummaryChanged: filter.matchedSummaryChanged,
        filterFirstVisibleRowChanged: filter.firstVisibleRowChanged,
        virtualPageLoadMs: virtualPage.pageLoadMs,
        virtualPageChanged: virtualPage.changed,
        ...tableCapture,
      },
      media: {
        png: { loadMs: pngLoadMs, switch: pngSwitch, ...png, ...pngCapture },
        svg: { loadMs: svgLoadMs, ...svg, ...svgCapture },
        report: { loadMs: reportLoadMs, ...report, ...reportCapture },
      },
      compare: {
        openMs: compareOpenMs,
        progressiveRows: progressivePages.at(-1).rows,
        progressivePages,
        ...compareCapture,
      },
      history: {
        firstPageVersions: historyFirst.versions,
        firstPageMs: historyFirstPageMs,
        afterPaginationVersions: historySecond.versions,
        paginationMs: historySecond.loadMs,
        ...historyCapture,
      },
      memory,
      publicProjectionAudit,
      publicProjectionSampleCount: publicProjectionSamples.length,
      renderProcessGoneCount: gone.length,
      artifactNetwork: artifactNetworkObservation(),
      backendStatus: backendStatusObservation(),
      isolatedCompatibility: compatibilityObservation(),
    };
    result.passed = result.table.totalRows === 100_000
      && result.table.scrollChanged
      && result.table.selectionChanged
      && result.table.sortChanged
      && result.table.filterChanged
      && result.table.filterQueryChanged
      && (result.table.filterMatchedSummaryChanged || result.table.filterFirstVisibleRowChanged)
      && result.table.virtualPageChanged
      && result.media.png.switch.changed
      && result.media.svg.switch.changed
      && result.media.png.rendered === true
      && result.media.png.sourceTargetMatched === true
      && result.media.png.artifactTargetMatched === true
      && result.media.svg.exportLinkPresent === true
      && result.media.svg.validSvgRoot === true
      && result.media.svg.sourceTargetMatched === true
      && result.media.svg.artifactTargetMatched === true
      && result.media.report.iframeVisible === true
      && result.media.report.sourceTargetMatched === true
      && result.media.report.artifactTargetMatched === true
      && result.media.report.textCharacters >= 100
      && result.media.report.embeddedImageCount >= 1
      && result.compare.progressiveRows >= 200
      && result.history.firstPageVersions >= 100
      && result.history.afterPaginationVersions > result.history.firstPageVersions
      && result.publicProjectionSampleCount >= 7
      && result.publicProjectionAudit.absolutePath === false
      && result.publicProjectionAudit.providerMaterial === false
      && result.publicProjectionAudit.rawInternalId === false
      && result.renderProcessGoneCount === 0
      && result.artifactNetwork.errorCount === 0
      && result.artifactNetwork.events.some((event) => (
        event.artifactName === config.targets.svg.artifact
        && event.outcome === 'completed'
        && event.statusCode === 200
      ))
      && result.backendStatus.everyCheckReady === true;
    writeFileSync(config.resultPath, `${JSON.stringify(result, null, 2)}\n`, { mode: 0o600 });
    window.destroy();
  } catch (error) {
    const page = await failureDiagnostic(window.webContents);
    writeFileSync(config.resultPath, `${JSON.stringify({
      schemaVersion: 1,
      passed: false,
      failedStage: stage,
      page,
      artifactNetwork: artifactNetworkObservation(),
      rendererConsole,
    }, null, 2)}\n`, { mode: 0o600 });
    throw error;
  }
}

app.whenReady()
  .then(run)
  .then(() => app.quit())
  .catch((error) => {
    console.error(error?.stack || error);
    app.exit(1);
  });

#!/usr/bin/env node

/**
 * G0-RS-P6 bounded Electron pressure and multi-Revision prototype.
 *
 * This is deliberately not a P6 closeout or qualification producer. It runs
 * two real admitted local Jobs, then adds clearly-labelled synthetic Revision
 * aliases only to pressure the existing history/storage path. Provider and
 * packaged-app evidence remain excluded.
 */

import { createHash } from 'node:crypto';
import { execFileSync, spawn, spawnSync } from 'node:child_process';
import {
  existsSync,
  mkdirSync,
  mkdtempSync,
  readFileSync,
  rmSync,
  statSync,
  writeFileSync,
} from 'node:fs';
import { createRequire } from 'node:module';
import { createServer } from 'node:net';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import {
  createP5LiveScientificRuntime,
  findBioPackRoot,
} from './g0-rs-p5-acceptance.mjs';

export { findBioPackRoot };
import {
  P6_UI110_SOURCE_FILES,
} from './g0-rs-p6-ui110-observation.mjs';
// BLOCK-86 把 14 插件封存进包仓 plugins.dormant/（deseq2 是唯一活跃插件），
// go-kegg 供能数据因此不再位于 plugins/go-kegg/。这里复用 P4R 包感知层那唯一的
// dormant 感知定位（plugins/ 优先 → plugins.dormant/ 兜底），勿另起炉灶。
import { locatePackPluginDir } from './g0-rs-p4r-pack.mjs';

const require = createRequire(import.meta.url);
const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const Database = require('better-sqlite3');
const { createResultStudioRepository } = require(path.join(
  ROOT,
  'core/shared-backend/result-studio-repository.js',
));
const { getResultStudioRuntimeLease } = require(path.join(
  ROOT,
  'core/shared-backend/result-studio-runtime-lease.js',
));

const DRIVER_PATH = path.join(ROOT, 'scripts/g0-rs-p6-electron-pressure-driver.cjs');
const VITE_PATH = path.join(ROOT, 'frontend/node_modules/vite/bin/vite.js');
const ELECTRON_PATH = path.join(ROOT, 'node_modules/.bin/electron');
const EVIDENCE_PATH = path.join(
  ROOT,
  'acceptance/g0-result-studio/rs-p6-electron-pressure-multirevision.json',
);
const TERMINAL_JOB_STATUSES = new Set(['completed', 'failed', 'cancelled']);
const JOB_TIMEOUT_MS = 15 * 60 * 1000;
const SHA256_PATTERN = /^[a-f0-9]{64}$/;
const COMMIT_PATTERN = /^[a-f0-9]{40}$/;

export const P6_ELECTRON_PRESSURE_CLASSIFICATION =
  'development_electron_real_jobs_mixed_synthetic_revision_pressure_non_provider_non_packaged_non_qualifying';
export const P6_ELECTRON_PRESSURE_ROWS = 100_000;
export const P6_ELECTRON_PRESSURE_SYNTHETIC_REVISIONS = 201;
export const P6_ELECTRON_PRESSURE_BUDGETS = Object.freeze({
  // This development trace starts before a cold Vite-backed Electron
  // navigation. The packaged/in-app 1s product target remains a P7 boundary;
  // P6 must not claim that colder and materially different path proved it.
  firstCanvasMs: 1_500,
  tableScrollFeedbackMs: 100,
  selectionFeedbackMs: 100,
  sortFeedbackMs: 100,
  filterFeedbackMs: 100,
  artifactSwitchMs: 500,
  virtualPageLoadMs: 2_000,
  pngContentReadyMs: 5_000,
  svgContentReadyMs: 15_000,
  reportContentReadyMs: 10_000,
  compareOpenMs: 1_000,
  progressivePageLoadMs: 2_000,
  historyFirstPageMs: 5_000,
  historyPaginationMs: 2_000,
  rendererPostGcHeapGrowthBytes: 64 * 1024 * 1024,
});

const EXTRA_SOURCE_PATHS = Object.freeze([
  'scripts/g0-rs-p6-electron-pressure-prototype.mjs',
  'scripts/g0-rs-p6-electron-pressure-driver.cjs',
  'test/g0-rs-p6-electron-pressure-prototype.test.mjs',
  'core/petri-server/helpers/tools-executor.js',
  'core/petri-server/routes/result-studio.js',
  'core/shared-backend/result-changeset-service.js',
  'core/shared-backend/result-compare-service.js',
  'core/shared-backend/result-studio-lifecycle.js',
  'core/shared-backend/result-studio-repository.js',
  'core/shared-backend/result-studio-runtime-lease.js',
  'core/shared-backend/result-studio-resource-summary.js',
  'core/shared-backend/result-studio-table-query.js',
  'core/shared-backend/tool-resource-sampler.js',
  'src/backend-health.js',
  'frontend/src/components/result-studio/ResultStudioChangeSetPanel.tsx',
  'frontend/src/components/result-studio/ScientificInteractionViewer.tsx',
  'frontend/src/components/result-studio/resultSurface.ts',
  'frontend/src/components/result-studio/resultStudioClient.ts',
  'frontend/vite.config.ts',
  'frontend/src/pages/project-workspace.tsx',
]);

export const P6_ELECTRON_PRESSURE_SOURCE_FILES = Object.freeze(Object.fromEntries(
  [...new Set([...Object.values(P6_UI110_SOURCE_FILES), ...EXTRA_SOURCE_PATHS])]
    .sort()
    .map((relative) => [relative, relative]),
));

function sha256(value) {
  return createHash('sha256').update(value).digest('hex');
}

function stable(value) {
  if (Array.isArray(value)) return value.map(stable);
  if (!value || typeof value !== 'object') return value;
  return Object.fromEntries(Object.keys(value).sort().map((key) => [key, stable(value[key])]));
}

function stableHash(value) {
  return sha256(JSON.stringify(stable(value)));
}

function assert(condition, code, detail = null) {
  if (condition) return;
  const error = new Error(code);
  error.code = code;
  error.detail = detail;
  throw error;
}

function checkedSource(relative) {
  const normalized = String(relative || '').replaceAll('\\', '/');
  const target = path.resolve(ROOT, normalized);
  assert(normalized && !path.isAbsolute(normalized) && !normalized.split('/').includes('..')
    && target.startsWith(ROOT + path.sep), 'p6_pressure_source_path_unsafe');
  assert(existsSync(target), 'p6_pressure_source_missing', { relative: normalized });
  return { relative: normalized, target };
}

export function getP6ElectronPressureSourceBinding() {
  const sourceCommit = spawnSync('git', ['rev-parse', 'HEAD'], {
    cwd: ROOT,
    encoding: 'utf8',
  }).stdout.trim();
  assert(COMMIT_PATTERN.test(sourceCommit), 'p6_pressure_source_commit_unavailable');
  const sources = Object.fromEntries(Object.entries(P6_ELECTRON_PRESSURE_SOURCE_FILES)
    .map(([key, relative]) => [key, checkedSource(relative)]));
  const sourceHashes = Object.fromEntries(Object.entries(sources)
    .map(([key, source]) => [key, sha256(readFileSync(source.target))]));
  const sourcePaths = Object.values(sources).map((source) => source.relative);
  const tracked = spawnSync(
    'git',
    ['ls-tree', '-r', '--name-only', '-z', sourceCommit, '--', ...sourcePaths],
    { cwd: ROOT, encoding: 'utf8' },
  );
  const changed = spawnSync(
    'git',
    ['diff', '--no-ext-diff', '--name-only', '-z', sourceCommit, '--', ...sourcePaths],
    { cwd: ROOT, encoding: 'utf8' },
  );
  assert(tracked.status === 0 && changed.status === 0, 'p6_pressure_source_tree_unavailable');
  const trackedPaths = new Set(tracked.stdout.split('\0').filter(Boolean));
  const changedPaths = new Set(changed.stdout.split('\0').filter(Boolean));
  const sourceMismatches = sourcePaths.filter((relative) => (
    !trackedPaths.has(relative) || changedPaths.has(relative)
  ));
  return {
    sourceCommit,
    sourceFiles: P6_ELECTRON_PRESSURE_SOURCE_FILES,
    sourceHashes,
    bindingDigest: stableHash({
      sourceCommit,
      sourceFiles: P6_ELECTRON_PRESSURE_SOURCE_FILES,
      sourceHashes,
    }),
    sourceCommitMatchesSourceHashes: sourceMismatches.length === 0,
    sourceMismatches,
  };
}

const secretKey = /(?:authorization|cookie|token|password|secret|api[_-]?key|credential|private[_-]?key|access[_-]?key|session)/i;
const internalId = /(?:^|[^A-Za-z0-9])(?:p|job|tj|rev|cs|conv|sel|wfg)_[A-Za-z0-9._-]+/;

export function assertSanitizedP6ElectronPressureEvidence(value, pointer = '$') {
  if (Array.isArray(value)) {
    value.forEach((item, index) => assertSanitizedP6ElectronPressureEvidence(item, `${pointer}[${index}]`));
    return true;
  }
  if (value && typeof value === 'object') {
    for (const [key, child] of Object.entries(value)) {
      if (secretKey.test(key) && key !== 'qualificationEligible') {
        throw new Error(`unsafe evidence key at ${pointer}.${key}`);
      }
      assertSanitizedP6ElectronPressureEvidence(child, `${pointer}.${key}`);
    }
    return true;
  }
  if (typeof value !== 'string') return true;
  if (/^[a-z][a-z0-9+.-]*:/i.test(value)) throw new Error(`URI leaked at ${pointer}`);
  if (path.isAbsolute(value) || /^[A-Za-z]:[\\/]/.test(value) || /^(?:~[\\/]|\\\\)/.test(value)) {
    throw new Error(`absolute path leaked at ${pointer}`);
  }
  if (value.includes('..')) throw new Error(`parent path leaked at ${pointer}`);
  if (internalId.test(value)) throw new Error(`internal id leaked at ${pointer}`);
  return true;
}

export function buildVolcanoPressureCsv(rowCount = P6_ELECTRON_PRESSURE_ROWS) {
  assert(Number.isInteger(rowCount) && rowCount > 0 && rowCount <= 500_000,
    'p6_pressure_row_count_invalid');
  const lines = new Array(rowCount + 1);
  lines[0] = 'gene,log2FoldChange,pvalue,padj';
  for (let index = 0; index < rowCount; index += 1) {
    const gene = `GENE${String(index + 1).padStart(6, '0')}`;
    const centered = ((index * 37) % 601) - 300;
    const lfc = (centered / 100).toFixed(2);
    const pvalue = Math.max(1e-10, ((index * 17) % 10_000 + 1) / 1_000_000).toExponential(6);
    const padj = Math.min(0.999999, Number(pvalue) * 4).toExponential(6);
    lines[index + 1] = `${gene},${lfc},${pvalue},${padj}`;
  }
  return `${lines.join('\n')}\n`;
}

export function loadGoKeggPressureInput() {
  const packRoot = findBioPackRoot();
  if (!packRoot) {
    throw Object.assign(new Error('p6_pressure_bio_pack_root_missing'), {
      code: 'p6_pressure_bio_pack_root_missing',
      detail: { hint: 'set PETRI_BIO_PACK_ROOT or check out petri-pack-bio as a sibling directory' },
    });
  }
  const inputPath = path.join(
    locatePackPluginDir(packRoot, 'go-kegg'),
    'demo-data',
    'genes.csv',
  );
  const csv = readFileSync(inputPath, 'utf8');
  const rows = csv.trimEnd().split(/\r?\n/);
  assert(rows[0] === 'gene' && rows.length >= 61,
    'p6_pressure_go_kegg_input_invalid');
  assert(new Set(rows.slice(1)).size === rows.length - 1,
    'p6_pressure_go_kegg_input_not_unique');
  return { csv, rowCount: rows.length - 1 };
}

async function freePort(excluded = new Set()) {
  for (let attempt = 0; attempt < 20; attempt += 1) {
    // eslint-disable-next-line no-await-in-loop
    const port = await new Promise((resolve, reject) => {
      const server = createServer();
      server.once('error', reject);
      server.listen(0, '127.0.0.1', () => {
        const address = server.address();
        const selected = typeof address === 'object' && address ? address.port : null;
        server.close(() => resolve(selected));
      });
    });
    if (Number.isInteger(port) && port > 0 && !excluded.has(port)) return port;
  }
  throw new Error('p6_pressure_port_allocation_failed');
}

async function requestJson(baseUrl, route, options = {}) {
  const response = await fetch(`${baseUrl}${route}`, {
    ...options,
    signal: options.signal || AbortSignal.timeout(options.timeoutMs || 120_000),
    headers: {
      ...(options.body ? { 'Content-Type': 'application/json' } : {}),
      ...(options.headers || {}),
    },
  });
  const raw = await response.text();
  let data = {};
  try { data = raw ? JSON.parse(raw) : {}; } catch { data = {}; }
  if (!response.ok) {
    const error = new Error(data.error || `http_${response.status}`);
    error.code = data.error || `http_${response.status}`;
    throw error;
  }
  return data;
}

async function runHttpTool(runtime, { toolId, params, files }) {
  const submitted = await requestJson(runtime.baseUrl, '/api/tools/run', {
    method: 'POST',
    body: JSON.stringify({
      toolId,
      projectId: runtime.project.id,
      params,
      files,
    }),
    timeoutMs: 180_000,
  });
  assert(submitted?.ok === true && submitted.jobId, 'p6_pressure_tool_submission_failed');
  const deadline = Date.now() + JOB_TIMEOUT_MS;
  let job = null;
  while (Date.now() < deadline) {
    // eslint-disable-next-line no-await-in-loop
    job = await requestJson(runtime.baseUrl, `/api/tools/status/${encodeURIComponent(submitted.jobId)}`);
    if (TERMINAL_JOB_STATUSES.has(job.status)) break;
    // eslint-disable-next-line no-await-in-loop
    await new Promise((resolve) => setTimeout(resolve, 400));
  }
  assert(job && job.status === 'completed', 'p6_pressure_tool_job_failed');
  assert(job.result?.artifactTruth?.status === 'valid'
    && job.result.artifactTruth.blocking !== true, 'p6_pressure_artifact_truth_invalid');
  const boundJob = { ...job, id: job.id || submitted.jobId };
  // UX1G-1 contract: the renderer's fail-closed conversation-ownership guard
  // refuses deep links for conversation-less jobs, so the pressure fixture
  // binds every target job to the live trace conversation after completion.
  {
    const bind = new Database(runtime.env.PETRI_DB_PATH);
    try {
      bind.prepare('UPDATE tool_jobs SET conversation_id=? WHERE id=? AND conversation_id IS NULL')
        .run(runtime.conversation.id, boundJob.id);
    } finally {
      bind.close();
    }
  }
  return boundJob;
}

function artifactRecord(job, artifactId) {
  const matches = (job?.result?.artifacts || []).filter((entry) => entry?.id === artifactId);
  assert(matches.length === 1, `p6_pressure_artifact_missing:${artifactId}`);
  return matches[0];
}

function artifactFilename(job, artifactId) {
  const artifact = artifactRecord(job, artifactId);
  return artifact.filename || artifact.name || path.basename(artifact.path || '');
}

function artifactTarget(job, artifactId) {
  const artifact = artifactRecord(job, artifactId);
  const filename = artifact.filename || artifact.name || path.basename(artifact.path || '');
  const sections = [
    ...(Array.isArray(job?.result?.sections) ? job.result.sections : []),
    ...(Array.isArray(job?.result?.manifest?.sections) ? job.result.manifest.sections : []),
  ];
  const section = sections.find((entry) => (
    Array.isArray(entry?.artifactNames) && entry.artifactNames.includes(filename)
  ));
  return {
    jobId: job.id,
    artifact: filename,
    label: artifact.label || artifact.title || filename,
    sectionLabel: typeof section?.label === 'string' && section.label ? section.label : null,
  };
}

async function openInteraction(runtime, job, artifactId) {
  const artifact = artifactFilename(job, artifactId);
  const query = new URLSearchParams({
    projectId: runtime.project.id,
    jobId: job.id,
    artifact,
  });
  const interaction = await requestJson(
    runtime.baseUrl,
    `/api/result-studio/interaction?${query.toString()}`,
    { timeoutMs: 180_000 },
  );
  const diagnosticCodes = (interaction?.manifest?.diagnostics || [])
    .map((entry) => String(entry?.code || '').trim())
    .filter(Boolean);
  assert(interaction?.revision?.revisionId && interaction.revision.validationStatus === 'valid',
    `p6_pressure_revision_missing:${artifactId}:${diagnosticCodes.join(',') || 'no_diagnostic'}`,
    { diagnosticCodes });
  return { ...interaction, artifact };
}

async function prepareRealPressureJobs(runtime) {
  const volcanoInput = buildVolcanoPressureCsv();
  const volcano = await runHttpTool(runtime, {
    toolId: 'volcano-plot',
    params: {
      deg_table: 'deg_table.csv',
      gene_col: 'gene',
      lfc_col: 'log2FoldChange',
      pval_col: 'padj',
      fc_threshold: 1,
      pval_threshold: 1.3,
      top_n: 12,
      point_size: 0.7,
      point_alpha: 0.45,
      plot_title: 'P6 100k-row pressure volcano',
    },
    files: {
      'deg_table.csv': Buffer.from(volcanoInput).toString('base64'),
    },
  });
  const volcanoInteraction = await openInteraction(runtime, volcano, 'classified_table');

  const reportInput = loadGoKeggPressureInput();
  const enrichment = await runHttpTool(runtime, {
