    coldServer = null;
    coldServer = await startServer(runtime.env, verbose
      ? { onLog: (channel, line) => console.error(`[p6-cold-2:${channel}] ${line}`) }
      : {});
    const secondColdStatus = publicStatusShape((await requestJson(
