      && activeCrash.backendStatus?.checkCount > 0
      && activeCrash.backendStatus?.everyCheckReady === true
      && recover.backendStatus?.checkCount > 0
      && recover.backendStatus?.everyCheckReady === true
      && reopen.backendStatus?.checkCount > 0
      && reopen.backendStatus?.everyCheckReady === true),
    check('P6RE-13', observation.sourceBindingStableDuringObservation === true),
    check('P6RE-14', activeCrash.before?.lifecycleState === 'ready'
      && activeCrash.before?.activeOperationExplained === true
      && activeCrash.before?.activeStageExplained === true
      && activeCrash.before?.recoveryControlAbsent === true
      && activeCrash.recoveryRequestCount === 0
      && activeCrash.passed === true
      && validActiveElectronLaunchAudit(activeCrash)
      && observation.processBoundaries?.electronActuallySigkilled === true
      && observation.processBoundaries?.electronRelaunchedAfterCrash === true),
    check('P6RE-15', withinBudget(
      observation.performance?.restartRestoreMs,
      P6_RECOVERY_ELECTRON_BUDGETS.restartRestoreMs,
    ), {
      observedMs: observation.performance?.restartRestoreMs ?? null,
      limitMs: P6_RECOVERY_ELECTRON_BUDGETS.restartRestoreMs,
    }),
  ];
  return {
    checks,
    passed: checks.every((entry) => entry.passed),
    remainingBoundaries: [
      'real_provider_not_exercised_p7_exclusion',
      'packaged_app_not_exercised_p7_exclusion',
      'development_trace_not_qualification_evidence',
    ],
  };
}

export function assertP6RecoveryElectronEvidenceWritable(evidence) {
  invariant(evidence?.classification === P6_RECOVERY_ELECTRON_CLASSIFICATION
    && evidence?.qualificationEligible === false
    && evidence?.p6CloseoutEligible === false,
  'p6_recovery_electron_classification_invalid');
  invariant(evidence?.sourceCommitMatchesSourceHashes === true
    && evidence?.sourceBindingStableDuringObservation === true,
  'p6_recovery_electron_source_binding_not_current');
  const verdict = buildP6RecoveryElectronVerdict(evidence);
  invariant(evidence?.passed === true && verdict.passed === true
    && Array.isArray(evidence?.checks)
    && evidence.checks.length === verdict.checks.length
    && evidence.checks.every((entry, index) => (
      entry.id === verdict.checks[index].id && entry.passed === true
    )), 'p6_recovery_electron_observation_not_passed');
  assertSanitizedP6RecoveryElectronEvidence(evidence);
  return true;
}

async function freePort(excluded = new Set()) {
  while (true) {
    const port = await new Promise((resolve, reject) => {
      const server = createServer();
      server.unref();
      server.once('error', reject);
      server.listen(0, '127.0.0.1', () => {
        const address = server.address();
        const selected = typeof address === 'object' && address ? address.port : null;
        server.close((error) => (error ? reject(error) : resolve(selected)));
      });
    });
    if (Number.isInteger(port) && !excluded.has(port)) return port;
  }
}

async function waitForUrl(url, child, timeoutMs = 45_000) {
  const deadline = Date.now() + timeoutMs;
  let last = null;
  while (Date.now() < deadline) {
    if (child?.exitCode !== null && child?.exitCode !== undefined) {
      throw new Error('p6_recovery_electron_vite_exited');
    }
    try {
      const response = await fetch(url);
      if (response.ok) return;
      last = response.status;
    } catch (error) {
      last = error?.message || String(error);
    }
    await sleep(100);
  }
  throw Object.assign(new Error('p6_recovery_electron_vite_timeout'), { detail: last });
}

async function stopChild(child) {
  if (!child || child.exitCode !== null || child.signalCode !== null) return;
  try { child.kill('SIGTERM'); } catch { return; }
  await Promise.race([
    new Promise((resolve) => child.once('exit', resolve)),
    sleep(3_000),
  ]);
  if (child.exitCode === null && child.signalCode === null) {
    try { child.kill('SIGKILL'); } catch {}
  }
}

function childHasExited(child) {
  return !child
    || child.exitCode !== null && child.exitCode !== undefined
    || child.signalCode !== null && child.signalCode !== undefined;
}

async function waitForTermination(checkAlive, timeoutMs, sleepFn = sleep) {
  const deadline = Date.now() + Math.max(1, timeoutMs);
  while (Date.now() < deadline) {
    if (!checkAlive()) return true;
    await sleepFn(Math.min(25, Math.max(1, deadline - Date.now())));
  }
  return !checkAlive();
}

function runWindowsTaskkill(args, timeoutMs) {
  return new Promise((resolve) => {
    execFile('taskkill.exe', args, {
      windowsHide: true,
      timeout: Math.max(1, timeoutMs),
    }, (error) => resolve({
      ok: !error,
      code: Number.isInteger(error?.code) ? error.code : null,
      errorCode: safeDiagnosticToken(error?.code),
    }));
  });
}

export async function terminateP6ActiveElectronProcessGroup(child, {
  force = false,
  platform = process.platform,
  signalProcess = process.kill,
  taskkill = runWindowsTaskkill,
  sleepFn = sleep,
  termGraceMs = ACTIVE_ELECTRON_TERM_GRACE_MS,
  killConfirmMs = ACTIVE_ELECTRON_KILL_CONFIRM_MS,
} = {}) {
  const pid = child?.pid;
  if (!Number.isInteger(pid) || pid <= 0) {
    return { terminated: false, reason: 'active_electron_pid_missing', escalated: false };
  }

  if (platform === 'win32') {
    // taskkill /T is the Windows tree primitive. If the root already exited,
    // its former descendants can no longer be addressed safely by parent PID;
    // fail closed instead of retrying while an unowned renderer may survive.
    if (childHasExited(child)) {
      return {
        terminated: false,
        reason: 'active_electron_root_exited_before_tree_termination',
        escalated: force,
      };
    }
    const gracefulArgs = ['/pid', String(pid), '/t'];
    const forcedArgs = [...gracefulArgs, '/f'];
    if (!force) {
      const graceful = await taskkill(gracefulArgs, termGraceMs);
      const gracefulGone = await waitForTermination(
        () => !childHasExited(child), termGraceMs, sleepFn,
      );
      if (graceful.ok && gracefulGone) {
        return { terminated: true, signal: 'SIGTERM', escalated: false, treeCommand: 'taskkill_t' };
      }
    }
    const forced = await taskkill(forcedArgs, killConfirmMs);
    const forcedGone = await waitForTermination(
      () => !childHasExited(child), killConfirmMs, sleepFn,
    );
    return forced.ok && forcedGone
      ? { terminated: true, signal: 'SIGKILL', escalated: !force, treeCommand: 'taskkill_t_f' }
      : {
          terminated: false,
          reason: 'active_electron_windows_tree_termination_unconfirmed',
          escalated: !force,
          taskkillErrorCode: forced.errorCode || null,
        };
  }

  const groupTarget = -pid;
  const groupAlive = () => {
    try {
      signalProcess(groupTarget, 0);
      return true;
    } catch (error) {
      if (error?.code === 'ESRCH') return false;
      return true;
    }
  };
  const signalGroup = (signal) => {
    try {
      signalProcess(groupTarget, signal);
      return { sent: true, absent: false };
    } catch (error) {
      if (error?.code === 'ESRCH') return { sent: false, absent: true };
      return { sent: false, absent: false, errorCode: safeDiagnosticToken(error?.code) };
    }
  };

  if (!groupAlive()) {
    return { terminated: true, signal: child?.signalCode || null, alreadyExited: true, escalated: false };
  }
  if (!force) {
    const term = signalGroup('SIGTERM');
    if (!term.sent && !term.absent) {
      return {
        terminated: false,
        reason: 'active_electron_group_sigterm_failed',
        errorCode: term.errorCode || null,
        escalated: false,
      };
    }
    if (term.absent || await waitForTermination(groupAlive, termGraceMs, sleepFn)) {
      return { terminated: true, signal: 'SIGTERM', escalated: false };
    }
  }
  const kill = signalGroup('SIGKILL');
  if (!kill.sent && !kill.absent) {
    return {
      terminated: false,
      reason: 'active_electron_group_sigkill_failed',
      errorCode: kill.errorCode || null,
      escalated: !force,
    };
  }
  const killed = kill.absent || await waitForTermination(groupAlive, killConfirmMs, sleepFn);
  return killed
    ? { terminated: true, signal: 'SIGKILL', escalated: !force }
    : {
        terminated: false,
        reason: 'active_electron_group_sigkill_unconfirmed',
        escalated: !force,
      };
}

async function requestJson(baseUrl, route, options = {}) {
  const response = await fetch(`${baseUrl}${route}`, {
    ...options,
    signal: AbortSignal.timeout(options.timeoutMs || 120_000),
    headers: {
      ...(options.body ? { 'Content-Type': 'application/json' } : {}),
      ...(options.headers || {}),
    },
  });
  const raw = await response.text();
  let data = {};
  try { data = raw ? JSON.parse(raw) : {}; } catch { data = {}; }
  invariant(response.ok, data.error || `http_${response.status}`);
  return { status: response.status, data };
}

function projectWorkspaceStatus(value) {
  const lifecycle = value?.lifecycle || value || {};
  return {
    status: lifecycle.status || null,
    checkpointIntegrityExact: lifecycle.checkpointIntegrity?.matches === true,
    consistencyStatus: lifecycle.consistency?.status || null,
    interruptedCount: Array.isArray(lifecycle.interrupted) ? lifecycle.interrupted.length : 0,
    activeOperationCount: Array.isArray(lifecycle.activeOperations) ? lifecycle.activeOperations.length : 0,
    pendingDecisionCount: Array.isArray(lifecycle.pendingDecisions) ? lifecycle.pendingDecisions.length : 0,
    pendingIssueCount: Array.isArray(lifecycle.pendingIssues) ? lifecycle.pendingIssues.length : 0,
    revisionIntegrityStatus: lifecycle.revisionIntegrity?.status || null,
  };
}

async function readWorkspaceStatus(baseUrl, projectId) {
  const query = new URLSearchParams({ projectId });
  return projectWorkspaceStatus((await requestJson(
    baseUrl,
    `/api/result-studio/workspace/status?${query.toString()}`,
  )).data);
}

function openLedger(dbPath) {
  return new Database(dbPath, { readonly: true, fileMustExist: true });
}

function readBaselineSnapshot(dbPath, workspaceRoot, projectId, revisionIds) {
  const db = openLedger(dbPath);
  try {
    const select = db.prepare(`
      SELECT revision_id, artifact_family_id, artifact_id, source_commit,
             output_path, output_hash, change_set_id, revision_ordinal, is_current
      FROM artifact_revisions WHERE project_id=? AND revision_id=?
    `);
    const rows = revisionIds.map((revisionId) => select.get(projectId, revisionId)).filter(Boolean);
    const exactArtifacts = rows.length === revisionIds.length && rows.every((row) => {
      const target = path.resolve(workspaceRoot, row.output_path);
      return target.startsWith(`${path.resolve(workspaceRoot)}${path.sep}`)
        && existsSync(target)
        && SHA256.test(row.output_hash || '')
        && sha256(readFileSync(target)) === row.output_hash;
    });
    return {
      rows,
      digest: stableHash(rows),
      exactArtifacts,
      currentCount: rows.filter((row) => row.is_current === 1).length,
      journalMode: db.pragma('journal_mode', { simple: true }),
    };
  } finally {
    db.close();
  }
}

function readRecoveredTruth(dbPath, changeSetId, candidateJobId) {
  const db = openLedger(dbPath);
  try {
    const changeSet = db.prepare(`
      SELECT status FROM scientific_change_sets WHERE change_set_id=?
    `).get(changeSetId);
    const checkpoint = db.prepare(`
      SELECT change_set_status FROM workspace_revision_checkpoints
      WHERE change_set_id=? ORDER BY updated_at DESC LIMIT 1
    `).get(changeSetId);
    const candidateRevisionCount = db.prepare(`
      SELECT COUNT(*) AS count FROM artifact_revisions WHERE change_set_id=?
    `).get(changeSetId).count;
    const job = db.prepare('SELECT status FROM tool_jobs WHERE id=?').get(candidateJobId);
    const activeChangeSetCount = db.prepare(`
      SELECT COUNT(*) AS count FROM scientific_change_sets WHERE status='running'
    `).get().count;
    return {
      changeSetStatus: changeSet?.status || null,
      checkpointStatus: checkpoint?.change_set_status || null,
      candidateRevisionCount,
      interruptedJobTerminal: TERMINAL_JOBS.has(job?.status),
      activeChangeSetCount,
    };
  } finally {
    db.close();
  }
}

function fileIdentity(filePath) {
  const stat = statSync(filePath);
  return { dev: stat.dev, ino: stat.ino };
}

function sameFileIdentity(left, right) {
  return left.dev === right.dev && left.ino === right.ino;
}

function readDriverResult(resultPath) {
  if (!existsSync(resultPath)) return { exists: false, value: null, parseError: null };
  try {
    return {
      exists: true,
      value: JSON.parse(readFileSync(resultPath, 'utf8')),
      parseError: null,
    };
  } catch (error) {
    return {
      exists: true,
      value: null,
      parseError: String(error?.message || 'invalid_json').slice(0, 160),
    };
  }
}

function safeDiagnosticToken(value) {
  const normalized = String(value || '').trim();
  return /^[A-Za-z0-9_.-]{1,96}$/.test(normalized) ? normalized : null;
}

function projectDriverPhaseResult(result) {
  if (!result || typeof result !== 'object') return null;
  const projectLifecycle = (value) => (value && typeof value === 'object' ? {
    lifecycleState: safeDiagnosticToken(value.lifecycleState),
    activeOperationExplained: value.activeOperationExplained === true,
    activeStageExplained: value.activeStageExplained === true,
    detectedInterruptedSite: value.detectedInterruptedSite === true,
    stoppingStageExplained: value.stoppingStageExplained === true,
    recoveryControlPresent: value.recoveryControlPresent === true,
    recoveryControlEnabled: value.recoveryControlEnabled === true,
    recoveryControlAbsent: value.recoveryControlAbsent === true,
  } : null);
  const backendStatus = result.backendStatus && typeof result.backendStatus === 'object'
    ? {
        checkCount: Number.isInteger(result.backendStatus.checkCount)
          ? result.backendStatus.checkCount : 0,
        everyCheckReady: result.backendStatus.everyCheckReady === true,
        maxDurationMs: Number.isFinite(result.backendStatus.maxDurationMs)
          ? result.backendStatus.maxDurationMs : null,
      }
    : null;
  return {
    phase: safeDiagnosticToken(result.phase),
    failedStage: safeDiagnosticToken(result.failedStage),
    errorCode: safeDiagnosticToken(result.errorCode),
    passed: result.passed === true,
    before: projectLifecycle(result.before || result.lifecycle),
    after: projectLifecycle(result.after),
    recoveryRequestCount: Number.isInteger(result.recoveryRequestCount)
      ? result.recoveryRequestCount : 0,
    renderProcessGoneCount: Number.isInteger(result.renderProcessGoneCount)
      ? result.renderProcessGoneCount : 0,
    publicProjectionClean: result.publicProjectionClean === true,
    backendStatus,
  };
}

function redactDiagnosticText(value) {
  return String(value || '')
    .replace(/https?:\/\/[^\s"']+/gi, '<url>')
    .replace(/(?:\/Users\/|\/home\/|\/private\/|\/tmp\/|\/var\/folders\/)[^\s"']+/g, '<path>')
    .replace(/\b(?:p|job|tj|rev|cs|conv|sel|wfg)_[A-Za-z0-9._-]+\b/g, '<internal-id>')
    .replace(/\b(?:authorization|cookie|token|password|secret|api[_-]?key)\s*[:=]\s*[^\s,;]+/gi,
      (match) => `${match.split(/[:=]/, 1)[0]}=<redacted>`)
    .slice(-4_000);
}

function utf8Tail(value, maxBytes) {
  const source = Buffer.from(String(value || ''), 'utf8');
  return source.length <= maxBytes ? source : source.subarray(source.length - maxBytes);
}

function appendBoundedDiagnosticText(current, chunk) {
  return utf8Tail(`${current}${chunk}`, 12_000).toString('utf8').replace(/^\uFFFD/, '');
}

function childDiagnostic(stderr, terminal = {}) {
  const bounded = utf8Tail(stderr, 12_000);
  return {
    exitCode: Number.isInteger(terminal.code) ? terminal.code : null,
    exitSignal: safeDiagnosticToken(terminal.signal),
    spawnErrorCode: safeDiagnosticToken(terminal.error?.code),
    stderrDigest: sha256(bounded),
    stderrBytes: bounded.length,
    stderrTail: redactDiagnosticText(bounded.toString('utf8')),
  };
}

export function classifyP6ActiveElectronAttempt({
  resultExists = false,
  result = null,
  resultParseError = null,
  terminalKind = null,
  timedOut = false,
} = {}) {
  if (resultExists) {
    if (resultParseError) {
      return { kind: 'persisted_result_invalid', retryEligible: false };
    }
    if (result?.passed === true) {
      return { kind: terminalKind ? 'observed_process_exited' : 'observation_ready', retryEligible: false };
    }
    if (result?.failedStage) {
      return { kind: 'persisted_driver_failure', retryEligible: false };
    }
    return { kind: 'persisted_semantic_failure', retryEligible: false };
  }
  if (timedOut) return { kind: 'live_child_timeout', retryEligible: false };
  if (terminalKind === 'spawn_error') {
    return { kind: 'spawn_error_before_observation', retryEligible: true };
  }
  if (terminalKind === 'exit') {
    return { kind: 'child_exit_before_observation', retryEligible: true };
  }
  return { kind: 'live_child_waiting', retryEligible: false };
}

function activeElectronError(code, detail, { retryEligible = false, failure = null } = {}) {
  const error = new Error(code);
  error.code = code;
  error.detail = detail;
  error.retryEligible = retryEligible;
  error.preObservationLaunchFailure = failure;
  return error;
}

async function requireActiveElectronProcessGroupTermination(child, {
  force = false,
  phaseResult = null,
} = {}) {
  const termination = await terminateP6ActiveElectronProcessGroup(child, { force });
  if (!termination.terminated) {
    throw activeElectronError('p6_recovery_active_electron_tree_termination_unconfirmed', {
      termination,
      phaseResult,
    });
  }
  return termination;
}

function projectPreObservationLaunchFailure(attempt, classification, diagnostic) {
  return {
    attempt,
    kind: classification.kind,
    exitCode: diagnostic.exitCode,
    exitSignal: diagnostic.exitSignal,
    stderrDigest: diagnostic.stderrDigest,
    stderrBytes: diagnostic.stderrBytes,
  };
}

function isRetryablePreObservationFailure(failure, attempt) {
  return failure?.attempt === attempt
    && ['spawn_error_before_observation', 'child_exit_before_observation'].includes(failure.kind)
    && (failure.exitCode === null || Number.isInteger(failure.exitCode))
    && (failure.exitSignal === null || /^[A-Za-z0-9_.-]{1,96}$/.test(failure.exitSignal))
    && SHA256.test(failure.stderrDigest || '')
    && Number.isInteger(failure.stderrBytes)
    && failure.stderrBytes >= 0
    && failure.stderrBytes <= 12_000;
}

export async function runP6ActiveElectronLaunchWithRetry({ createAttempt, launchAttempt }) {
  invariant(typeof createAttempt === 'function' && typeof launchAttempt === 'function',
    'p6_recovery_active_electron_retry_dependencies_invalid');
  const failures = [];
  const configScopes = new Set();
  for (let attempt = 1; attempt <= MAX_ACTIVE_ELECTRON_LAUNCH_ATTEMPTS; attempt += 1) {
    const coordinates = await createAttempt(attempt);
    invariant(path.isAbsolute(coordinates?.configPath || '')
      && path.isAbsolute(coordinates?.resultPath || ''),
    'p6_recovery_active_electron_attempt_coordinates_invalid');
    const configScope = path.dirname(path.resolve(coordinates.configPath));
    invariant(!configScopes.has(configScope),
      'p6_recovery_active_electron_attempt_scope_reused');
    configScopes.add(configScope);
    try {
      const launched = await launchAttempt({ ...coordinates, attempt });
      return {
        ...launched,
        result: {
          ...launched.result,
          launchAttemptCount: attempt,
          preObservationLaunchFailures: failures,
        },
      };
    } catch (error) {
      const projectedFailure = error?.preObservationLaunchFailure || null;
      if (error?.retryEligible === true
          && isRetryablePreObservationFailure(projectedFailure, attempt)
          && attempt < MAX_ACTIVE_ELECTRON_LAUNCH_ATTEMPTS) {
        failures.push(projectedFailure);
        continue;
      }
      const finalFailures = projectedFailure ? [...failures, projectedFailure] : failures;
      error.detail = {
        ...(error?.detail && typeof error.detail === 'object' ? error.detail : {}),
        launchAttemptCount: attempt,
        preObservationLaunchFailures: finalFailures,
      };
      throw error;
    }
  }
  throw new Error('p6_recovery_active_electron_retry_exhausted');
}

async function runElectron(configPath, resultPath, backendPort) {
  let stderr = '';
  const child = spawn(ELECTRON_PATH, [DRIVER_PATH], {
    cwd: ROOT,
    env: {
      ...process.env,
      PETRI_DESKTOP: '1',
      R_SERVER_PORT: String(backendPort),
      PETRI_P6_RECOVERY_ELECTRON_CONFIG: configPath,
      [RECOVERY_ELECTRON_ATTEMPT_ENV]: '1',
    },
    stdio: ['ignore', 'ignore', 'pipe'],
  });
  const pid = child.pid;
  child.stderr.setEncoding('utf8');
  child.stderr.on('data', (chunk) => {
    stderr = appendBoundedDiagnosticText(stderr, chunk);
  });
  const exit = await new Promise((resolve) => {
    child.once('exit', (code, signal) => resolve({ code, signal }));
    child.once('error', (error) => resolve({ code: null, signal: null, error }));
  });
  const snapshot = readDriverResult(resultPath);
  if (exit.code !== 0 || !snapshot.value?.passed) {
    const classification = classifyP6ActiveElectronAttempt({
      resultExists: snapshot.exists,
      result: snapshot.value,
      resultParseError: snapshot.parseError,
      terminalKind: exit.error ? 'spawn_error' : 'exit',
    });
    throw activeElectronError(`p6_recovery_electron_driver_${classification.kind}`, {
      ...childDiagnostic(stderr, exit),
      phaseResult: projectDriverPhaseResult(snapshot.value),
      resultParseError: snapshot.parseError,
    });
  }
  return { pid, result: snapshot.value };
}

async function launchActiveElectronAttempt(configPath, resultPath, backendPort, attempt) {
  let stderr = '';
  const child = spawn(ELECTRON_PATH, [DRIVER_PATH], {
    cwd: ROOT,
    detached: process.platform !== 'win32',
    env: {
      ...process.env,
      PETRI_DESKTOP: '1',
      R_SERVER_PORT: String(backendPort),
      PETRI_P6_RECOVERY_ELECTRON_CONFIG: configPath,
      [RECOVERY_ELECTRON_ATTEMPT_ENV]: String(attempt),
    },
    stdio: ['ignore', 'ignore', 'pipe'],
  });
  const pid = child.pid;
  child.stderr.setEncoding('utf8');
  child.stderr.on('data', (chunk) => {
    stderr = appendBoundedDiagnosticText(stderr, chunk);
  });
  const terminalPromise = new Promise((resolve) => {
    child.once('exit', (code, signal) => resolve({ kind: 'exit', code, signal, error: null }));
    child.once('error', (error) => resolve({
      kind: 'spawn_error', code: null, signal: null, error,
    }));
  });
  // The driver owns the 120s renderer timeout. Leave room for it to persist a
  // bounded diagnostic before the parent terminates the isolated process.
  const deadline = Date.now() + 135_000;
  let parseErrorFirstSeenAt = null;
  while (Date.now() < deadline) {
    const snapshot = readDriverResult(resultPath);
    if (snapshot.exists) {
      if (snapshot.parseError
          && child.exitCode === null
          && child.signalCode === null
          && (parseErrorFirstSeenAt === null
            || Date.now() - parseErrorFirstSeenAt < DRIVER_RESULT_PARSE_STABILITY_MS)) {
        if (parseErrorFirstSeenAt === null) parseErrorFirstSeenAt = Date.now();
        await sleep(20);
        continue;
      }
      parseErrorFirstSeenAt = null;
      const classification = classifyP6ActiveElectronAttempt({
        resultExists: true,
        result: snapshot.value,
        resultParseError: snapshot.parseError,
      });
      if (classification.kind !== 'observation_ready') {
        const phaseResult = projectDriverPhaseResult(snapshot.value);
        const termination = await requireActiveElectronProcessGroupTermination(child, { phaseResult });
        throw activeElectronError(`p6_recovery_active_electron_${classification.kind}`, {
          ...childDiagnostic(stderr),
          phaseResult,
          resultParseError: snapshot.parseError,
          termination,
        });
      }
      if (child.exitCode !== null || child.signalCode !== null) {
        const terminal = await terminalPromise;
        const phaseResult = projectDriverPhaseResult(snapshot.value);
        const termination = await requireActiveElectronProcessGroupTermination(child, { phaseResult });
        const exited = classifyP6ActiveElectronAttempt({
          resultExists: true,
          result: snapshot.value,
          terminalKind: terminal.kind,
        });
        throw activeElectronError(`p6_recovery_active_electron_${exited.kind}`, {
          ...childDiagnostic(stderr, terminal),
          phaseResult,
          resultParseError: null,
          termination,
        });
      }
      const termination = await requireActiveElectronProcessGroupTermination(child, {
        force: true,
        phaseResult: projectDriverPhaseResult(snapshot.value),
      });
      const exit = await terminalPromise;
      invariant(termination.signal === 'SIGKILL'
        && (process.platform === 'win32' || exit.signal === 'SIGKILL'),
      'p6_recovery_active_electron_not_sigkilled', { exit, termination });
      return { pid, exitSignal: termination.signal, result: snapshot.value };
    }
    const terminal = await Promise.race([
      terminalPromise,
      sleep(100).then(() => null),
    ]);
    if (terminal) {
      const finalSnapshot = readDriverResult(resultPath);
      let termination = null;
      if (terminal.kind === 'exit') {
        termination = await requireActiveElectronProcessGroupTermination(child, {
          phaseResult: projectDriverPhaseResult(finalSnapshot.value),
        });
      }
      const classification = classifyP6ActiveElectronAttempt({
        resultExists: finalSnapshot.exists,
        result: finalSnapshot.value,
        resultParseError: finalSnapshot.parseError,
        terminalKind: terminal.kind,
      });
      const diagnostic = childDiagnostic(stderr, terminal);
      const failure = classification.retryEligible
        ? projectPreObservationLaunchFailure(attempt, classification, diagnostic)
        : null;
      throw activeElectronError(`p6_recovery_active_electron_${classification.kind}`, {
        ...diagnostic,
        phaseResult: projectDriverPhaseResult(finalSnapshot.value),
        resultParseError: finalSnapshot.parseError,
        termination,
      }, { retryEligible: classification.retryEligible, failure });
    }
  }
  const termination = await requireActiveElectronProcessGroupTermination(child);
  const classification = classifyP6ActiveElectronAttempt({ timedOut: true });
  throw activeElectronError(`p6_recovery_active_electron_${classification.kind}`, {
    ...childDiagnostic(stderr, {
      code: child.exitCode,
      signal: child.signalCode,
    }),
    phaseResult: null,
    termination,
  });
}

async function crashActiveElectron(createAttempt, backendPort) {
  return runP6ActiveElectronLaunchWithRetry({
    createAttempt,
    launchAttempt: ({ configPath, resultPath, attempt }) => (
      launchActiveElectronAttempt(configPath, resultPath, backendPort, attempt)
    ),
  });
}

async function terminateWorkerForCleanup(worker) {
  if (!worker?.child) return { terminated: true, alreadyExited: true };
  const termination = await terminateP6ActiveElectronProcessGroup(worker.child, { force: true });
  invariant(termination.terminated === true,
    'p6_recovery_worker_cleanup_unconfirmed', termination);
  return termination;
}

export function createP6RecoveryResourceGate(getInterruptionSignal) {
  invariant(typeof getInterruptionSignal === 'function',
    'p6_recovery_resource_gate_signal_reader_missing');
  let pendingPromise = null;
  const assertNotInterrupted = () => {
    const signal = getInterruptionSignal();
    invariant(!signal, 'p6_recovery_interrupted', { signal });
  };
  return Object.freeze({
    get pendingPromise() { return pendingPromise; },
    assertNotInterrupted,
    async acquire(factory, assign) {
      invariant(typeof factory === 'function' && typeof assign === 'function',
        'p6_recovery_resource_gate_factory_invalid');
      // Guard and factory invocation share one synchronous turn. A signal
      // cannot land between them; once the factory yields, cleanup can see its
      // promise and wait until the owned resource is addressable.
      assertNotInterrupted();
      const tracked = Promise.resolve(factory()).then((resource) => {
        assign(resource);
        return resource;
      });
      pendingPromise = tracked;
      try {
        return await tracked;
      } finally {
        if (pendingPromise === tracked) pendingPromise = null;
      }
    },
  });
}

export async function observeP6RecoveryElectron({ keep = false, show = false, verbose = false } = {}) {
  const sourceAtStart = getP6RecoveryElectronSourceBinding();
  const backendPort = await freePort();
  const uiPort = await freePort(new Set([backendPort]));
  let runtime = null;
  let worker = null;
  let coldServer = null;
  let vite = null;
  let root = null;
  let originalRuntimeClosed = false;
  let cleanupPromise = null;
  let interruptionSignal = null;
  const resourceGate = createP6RecoveryResourceGate(() => interruptionSignal);

  const cleanup = () => {
    if (cleanupPromise) return cleanupPromise;
    cleanupPromise = (async () => {
      // A signal may arrive while a runtime or cold server is still being
      // created.  Wait for that owned resource to become addressable before
      // taking the cleanup snapshot; otherwise an early empty cleanup could
      // be cached while the main path later creates an orphan.
      if (resourceGate.pendingPromise) {
        try { await resourceGate.pendingPromise; } catch { /* creation already failed */ }
      }
      await terminateWorkerForCleanup(worker);
      await stopChild(vite);
      await stopServer(coldServer?.child);
      if (runtime && !originalRuntimeClosed) await runtime.close({ removeRoot: false });
      if (!keep && root && existsSync(root)) rmSync(root, { recursive: true, force: true });
    })();
    return cleanupPromise;
  };
  const onSignal = (signal) => {
    if (interruptionSignal) return;
    interruptionSignal = signal;
    process.exitCode = signal === 'SIGINT' ? 130 : 143;
    cleanup().catch((error) => {
      process.exitCode = 1;
      console.error(`[p6-recovery-cleanup] ${safeDiagnosticToken(error?.code || error?.message)}`);
    });
  };
  const onSigint = () => onSignal('SIGINT');
  const onSigterm = () => onSignal('SIGTERM');
  process.once('SIGINT', onSigint);
  process.once('SIGTERM', onSigterm);

  try {
    await resourceGate.acquire(
      () => createP5LiveScientificRuntime({
        port: backendPort,
        verbose,
        beforeStart({ env }) {
          const rendererOrigin = `http://127.0.0.1:${uiPort}`;
          env.PETRI_RENDERER_DEV_URL = rendererOrigin;
          env.PETRI_TRUSTED_DESKTOP_ORIGINS = rendererOrigin;
          env.PETRI_TOOL_ZOMBIE_TIMEOUT_MS = '250';
          env.PETRI_TOOL_HEARTBEAT_INTERVAL_MS = '100';
        },
      }),
      (createdRuntime) => {
        runtime = createdRuntime;
        root = createdRuntime.root;
      },
    );
    resourceGate.assertNotInterrupted();
    const dbIdentityBefore = fileIdentity(runtime.env.PETRI_DB_PATH);
    const baseline = await createRealVolcanoBaseline(runtime, 50_000);
    resourceGate.assertNotInterrupted();
    const db = openLedger(runtime.env.PETRI_DB_PATH);
    let baselineRevisionIds;
    try {
      baselineRevisionIds = db.prepare(`
        SELECT revision_id FROM artifact_revisions
        WHERE project_id=? AND change_set_id=? ORDER BY artifact_id
      `).all(runtime.project.id, baseline.interaction.revision.changeSetId)
        .map((row) => row.revision_id);
    } finally {
      db.close();
    }
    invariant(baselineRevisionIds.length >= 3, 'p6_recovery_electron_baseline_cohort_incomplete');
    const baselineBefore = readBaselineSnapshot(
      runtime.env.PETRI_DB_PATH,
      runtime.project.workspace_path,
      runtime.project.id,
      baselineRevisionIds,
    );

    worker = spawnEditWorker(runtime, baseline);
    const durable = await waitForDurableCandidateCheckpoint(runtime, worker);
    resourceGate.assertNotInterrupted();

    vite = spawn(process.execPath, [
      VITE_PATH,
      '--host', '127.0.0.1',
      '--port', String(uiPort),
      '--strictPort',
    ], {
      cwd: path.join(ROOT, 'frontend'),
      env: { ...process.env, NODE_ENV: 'development' },
      stdio: ['ignore', 'ignore', 'ignore'],
    });
    await waitForUrl(`http://127.0.0.1:${uiPort}`, vite);
    resourceGate.assertNotInterrupted();

    const traceDir = path.join(root, 'p6-recovery-electron');
    const configPath = path.join(traceDir, 'driver-config.json');
    const recoverResultPath = path.join(traceDir, 'driver-recover-result.json');
    const reopenResultPath = path.join(traceDir, 'driver-reopen-result.json');
    mkdirSync(traceDir, { recursive: true, mode: 0o700 });
    const baseConfig = {
      uiBaseUrl: `http://127.0.0.1:${uiPort}`,
      backendBaseUrl: `http://127.0.0.1:${backendPort}`,
      projectId: runtime.project.id,
      conversationId: runtime.conversation.id,
      jobId: baseline.job.id,
      artifact: path.basename(baseline.artifact.path),
      outputDir: traceDir,
      show,
    };
    const crashedElectron = await crashActiveElectron(
      async (attempt) => {
        const attemptDir = path.join(traceDir, `active-launch-attempt-${attempt}`);
        const attemptConfigPath = path.join(attemptDir, 'driver-config.json');
        const attemptResultPath = path.join(attemptDir, 'driver-result.json');
        mkdirSync(attemptDir, { recursive: true, mode: 0o700 });
        writeFileSync(attemptConfigPath, `${JSON.stringify({
          ...baseConfig,
          phase: 'active-crash',
          outputDir: attemptDir,
          resultPath: attemptResultPath,
        })}\n`, { mode: 0o600 });
        return {
          configPath: attemptConfigPath,
          resultPath: attemptResultPath,
        };
      },
      backendPort,
    );
    resourceGate.assertNotInterrupted();

    // The renderer observation above must happen while the edit worker still
    // owns a live candidate operation. Only after Electron is actually gone do
    // we kill the worker and create the interrupted site recovered below.
    const killed = await killWorkerWithSigkill(worker);
    const markerSeen = worker.output().stdout.includes('__P5_WORKER_RESULT__');
    worker = null;

    await sleep(350);
    await runtime.close({ removeRoot: false });
    originalRuntimeClosed = true;
    invariant(existsSync(root), 'p6_recovery_electron_root_removed_before_cold_boot');

    const restartRestoreStartedAt = performance.now();
    await resourceGate.acquire(
      () => startServer(runtime.env, verbose
        ? { onLog: (channel, line) => console.error(`[p6-recovery-cold-1:${channel}] ${line}`) }
        : {}),
      (createdServer) => { coldServer = createdServer; },
    );
    resourceGate.assertNotInterrupted();
    const firstColdStatus = await readWorkspaceStatus(coldServer.baseUrl, runtime.project.id);
    resourceGate.assertNotInterrupted();

    writeFileSync(configPath, `${JSON.stringify({
      ...baseConfig,
      phase: 'recover',
      resultPath: recoverResultPath,
    })}\n`, { mode: 0o600 });
    const recoverElectron = await runElectron(configPath, recoverResultPath, backendPort);
    resourceGate.assertNotInterrupted();
    const restartRestoreMs = performance.now() - restartRestoreStartedAt;

    const recoveredState = readRecoveredTruth(
      runtime.env.PETRI_DB_PATH,
      durable.checkpoint.change_set_id,
      durable.checkpoint.candidateJob.id,
    );
    const baselineAfterRecovery = readBaselineSnapshot(
      runtime.env.PETRI_DB_PATH,
      runtime.project.workspace_path,
      runtime.project.id,
      baselineRevisionIds,
    );
    const afterRecoveryStatus = await readWorkspaceStatus(coldServer.baseUrl, runtime.project.id);

    await stopServer(coldServer.child);
    coldServer = null;
    await resourceGate.acquire(
      () => startServer(runtime.env, verbose
        ? { onLog: (channel, line) => console.error(`[p6-recovery-cold-2:${channel}] ${line}`) }
        : {}),
      (createdServer) => { coldServer = createdServer; },
    );
    resourceGate.assertNotInterrupted();
    const secondColdStatus = await readWorkspaceStatus(coldServer.baseUrl, runtime.project.id);
    resourceGate.assertNotInterrupted();

    writeFileSync(configPath, `${JSON.stringify({
      ...baseConfig,
      phase: 'reopen',
      resultPath: reopenResultPath,
    })}\n`, { mode: 0o600 });
    const reopenElectron = await runElectron(configPath, reopenResultPath, backendPort);
    resourceGate.assertNotInterrupted();
    const finalStatus = await readWorkspaceStatus(coldServer.baseUrl, runtime.project.id);
    const dbIdentityAfter = fileIdentity(runtime.env.PETRI_DB_PATH);
    const sourceAtEnd = getP6RecoveryElectronSourceBinding();

    const observation = {
      schemaVersion: 1,
      planId: 'G0-RS-P6',
      slice: 'P6-1 bounded development Electron recovery trace',
      classification: P6_RECOVERY_ELECTRON_CLASSIFICATION,
      qualificationEligible: false,
      p6CloseoutEligible: false,
      boundary: {
        providerEvidence: 'not_exercised',
        packagedAppEvidence: 'not_exercised',
        qualificationEligible: false,
        systemRestartClaim: false,
        processBoundary: 'owned_electron_and_backend_processes_restarted_against_same_durable_local_stores',
        checkpointInterruptionPlatform: process.platform,
        checkpointInterruptionSignal: 'posix_sigstop_process_group',
      },
      sourceCommit: sourceAtStart.sourceCommit,
      sourceFiles: sourceAtStart.sourceFiles,
      sourceHashes: sourceAtStart.sourceHashes,
      sourceBindingDigest: sourceAtStart.bindingDigest,
      sourceCommitMatchesSourceHashes: sourceAtStart.sourceCommitMatchesSourceHashes,
      sourceMismatches: sourceAtStart.sourceMismatches,
      sourceBindingStableDuringObservation: sourceAtStart.bindingDigest === sourceAtEnd.bindingDigest,
      truth: {
        noSeedProductLedger: runtime.noSeedPrecondition.seededTables.length === 0,
        baselineJobCompleted: baseline.job.status === 'completed',
        baselineArtifactTruthValid: baseline.job.result?.artifactTruth?.status === 'valid'
          && baseline.job.result.artifactTruth.blocking !== true,
        baselineRevisionCount: baselineRevisionIds.length,
        baselineJournalMode: baselineBefore.journalMode,
      },
      interruption: {
        checkpointStage: durable.checkpoint.pendingPreview.stage,
        checkpointIntegrityExact: durable.integrity.matches === true,
        candidateRefExact: durable.git.commit === durable.checkpoint.candidate_commit,
        candidateJobRunningBeforeKill: durable.checkpoint.candidateJob.status === 'running',
        workerCheckpointHoldConfirmed: durable.hold.confirmed === true
          && durable.hold.workerProcessStopped === true
          && durable.hold.processGroupAllStopped === true,
        workerCheckpointHoldMode: durable.hold.mode,
        processGroupAliveBeforeKill: durable.hold.groupAddressable === true,
        candidateChildPresentBeforeKill: durable.hold.childProcessPresent === true
          && durable.hold.groupMemberCount >= 2,
        candidateJobExactBeforeKill: durable.hold.candidateJobExact === true,
        candidateInputExactBeforeKill: durable.hold.candidateInputExact === true,
        candidateRuntimePausedBeforeCheckpoint:
          durable.hold.candidateRuntimePausedBeforeCheckpoint === true,
        candidateRuntimeProcessObservedBeforeKill:
          durable.hold.candidateRuntimeProcessObserved === true,
        candidateRuntimeDirectChildBeforeKill: durable.hold.candidateRuntimeDirectChild === true,
        candidateRuntimeCommandTrustedBeforeKill:
          durable.hold.candidateRuntimeCommandTrusted === true,
        candidateRuntimeExecutableIdentityExactBeforeKill:
          durable.hold.candidateRuntimeExecutableIdentityExact === true,
        processGroupAllStoppedBeforeKill: durable.hold.processGroupAllStopped === true,
        workerExitSignal: killed.signal,
        workerCompletionMarkerSeen: markerSeen,
        processGroupGoneAfterKill: killed.processGroupGone === true,
        candidateRuntimeProcessGoneAfterKill: killed.candidateRuntimeProcessGone === true,
      },
      firstColdStatus,
      renderer: {
        activeCrash: crashedElectron.result,
        recover: recoverElectron.result,
        reopen: reopenElectron.result,
      },
      recoveredTruth: {
        ...recoveredState,
        baselineDigestStable: baselineBefore.digest === baselineAfterRecovery.digest,
        baselineArtifactsExact: baselineAfterRecovery.exactArtifacts,
        baselineCurrentCountExact: baselineAfterRecovery.currentCount === baselineRevisionIds.length,
      },
      afterRecoveryStatus,
      secondColdStatus,
      finalStatus,
      performance: {
        restartRestoreMs,
        budgets: P6_RECOVERY_ELECTRON_BUDGETS,
      },
      processBoundaries: {
        electronActuallySigkilled: crashedElectron.exitSignal === 'SIGKILL',
        electronRelaunchedAfterCrash: Number.isInteger(crashedElectron.pid)
          && Number.isInteger(recoverElectron.pid)
          && crashedElectron.pid !== recoverElectron.pid,
        electronProcessRelaunched: Number.isInteger(recoverElectron.pid)
          && Number.isInteger(reopenElectron.pid)
          && recoverElectron.pid !== reopenElectron.pid,
        backendColdBootCount: 2,
        sqliteFileIdentityStable: sameFileIdentity(dbIdentityBefore, dbIdentityAfter),
        workspaceStillPresent: existsSync(runtime.project.workspace_path),
      },
    };
    const verdict = buildP6RecoveryElectronVerdict(observation);
    const result = {
      ...observation,
      checks: verdict.checks,
      remainingBoundaries: verdict.remainingBoundaries,
      passed: verdict.passed,
    };
    assertSanitizedP6RecoveryElectronEvidence(result);
    return result;
  } finally {
    process.removeListener('SIGINT', onSigint);
    process.removeListener('SIGTERM', onSigterm);
    await cleanup();
  }
}

async function main() {
  invariant(!process.argv.includes('--write-evidence'),
    'p6_recovery_electron_prototype_has_no_evidence_writer');
  const result = await observeP6RecoveryElectron({
    keep: process.argv.includes('--keep'),
    show: process.argv.includes('--show'),
    verbose: process.argv.includes('--verbose'),
  });
  console.log(JSON.stringify(result, null, 2));
  if (!result.passed) process.exitCode = 1;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  main().catch((error) => {
    console.error(error?.stack || error);
    if (error?.detail) console.error(JSON.stringify(error.detail, null, 2));
    process.exitCode = 1;
  });
}

#!/usr/bin/env node
'use strict';

/**
 * Electron-side P6 UI-110 scientific-editing trace.
 *
 * This process owns one real BrowserWindow. The parent owns the disposable
 * backend, local scripted gateway, Vite server, source binding, and canonical
 * evidence. Configuration contains transient Result Studio coordinates but
 * the result written here intentionally contains no IDs, URLs, paths, prompt
 * text, or model/tool payloads.
 */

const { createHash } = require('node:crypto');
const { mkdirSync, readFileSync, writeFileSync } = require('node:fs');
const path = require('node:path');

const CONFIG_ENV = 'PETRI_P6_UI110_DRIVER_CONFIG';
const PRELOAD_PATH = path.resolve(__dirname, '..', 'src', 'preload.js');
const SHORT_WAIT_MS = 45_000;
const AGENT_WAIT_MS = 12 * 60 * 1000;
const RESTORE_WAIT_MS = 90_000;
const POLL_MS = 125;

function digest(value) {
  return createHash('sha256').update(value).digest('hex');
}

function stable(value) {
  if (Array.isArray(value)) return value.map(stable);
  if (!value || typeof value !== 'object') return value;
  return Object.fromEntries(Object.keys(value).sort().map((key) => [key, stable(value[key])]));
}

function stableDigest(value) {
  return digest(JSON.stringify(stable(value)));
}

function canonicalIds(values) {
  return [...new Set((Array.isArray(values) ? values : [])
    .map((value) => String(value || '').trim()).filter(Boolean))].sort();
}

function objectBinding(changeSet, revisions = []) {
  const revisionIds = canonicalIds(changeSet?.candidateArtifactRefs?.length
    ? changeSet.candidateArtifactRefs
    : revisions.map((revision) => revision?.revisionId));
  const jobIds = canonicalIds(changeSet?.jobRefs?.length
    ? changeSet.jobRefs
    : revisions.map((revision) => revision?.toolJobId));
  const identity = {
    changeSetId: String(changeSet?.changeSetId || '').trim(),
    revisionIds,
    jobIds,
  };
  if (!identity.changeSetId || revisionIds.length === 0 || jobIds.length === 0) {
    throw new Error('stage binding requires one complete ChangeSet cohort');
  }
  return {
    objectDigest: stableDigest(identity),
    changeSetDigest: stableDigest(identity.changeSetId),
    revisionSetDigest: stableDigest(revisionIds),
    jobSetDigest: stableDigest(jobIds),
    revisionCount: revisionIds.length,
    jobCount: jobIds.length,
    status: String(changeSet.status || ''),
  };
}

function pause(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function verifiedCandidateTerminal(text) {
  const value = String(text || '');
  const candidateMention = /候选版本|ChangeSet/.test(value);
  const created = /(?:已(?:成功)?创建|创建成功|已(?:成功)?生成|已生成)/.test(value);
  const verified = /验证通过|artifactTruthStatus\s*[:：]\s*valid|preview_ready|候选可比较/.test(value);
  return candidateMention && created && verified;
}

function enrichmentTerminal(text) {
  const value = String(text || '');
  return /富集/.test(value)
    && /(?:任务已经提交|已成功执行|分析已完成|已完成并生成|生成了正式产物)/.test(value);
}

async function requestBackendJson(url) {
  const response = await fetch(url);
  const data = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(data.error || `backend_request_failed:${response.status}`);
  return data;
}

function readConfig() {
  const configPath = process.env[CONFIG_ENV];
  if (!configPath || !path.isAbsolute(configPath)) {
    throw new Error(`${CONFIG_ENV} must point to an absolute disposable config path`);
  }
  const config = JSON.parse(readFileSync(configPath, 'utf8'));
  for (const key of ['uiBaseUrl', 'backendBaseUrl', 'projectId', 'conversationId', 'outputDir', 'resultPath']) {
    if (typeof config[key] !== 'string' || !config[key]) throw new Error(`driver config missing ${key}`);
  }
  const assertLoopbackUrl = (value, label) => {
    let parsed;
    try {
      parsed = new URL(value);
    } catch {
      throw new Error(`${label} must be a valid URL`);
    }
    if (parsed.protocol !== 'http:' || parsed.hostname !== '127.0.0.1' || !parsed.port || parsed.pathname !== '/') {
      throw new Error(`driver only accepts an isolated loopback ${label}`);
    }
    return parsed;
  };
  const uiUrl = assertLoopbackUrl(config.uiBaseUrl, 'Vite URL');
  const backendUrl = assertLoopbackUrl(config.backendBaseUrl, 'backend URL');
  if (uiUrl.port === backendUrl.port) throw new Error('driver UI and backend ports must differ');
  for (const name of ['deg', 'volcano', 'heatmap']) {
    const target = config.targets && config.targets[name];
    if (!target || typeof target.jobId !== 'string' || typeof target.artifact !== 'string'
      || typeof target.artifactFamilyId !== 'string' || !target.artifactFamilyId) {
      throw new Error(`driver target missing: ${name}`);
    }
  }
  if (!Number.isFinite(config.changedLfc) || config.changedLfc <= 0) throw new Error('driver changedLfc missing');
  return config;
}

function targetUrl(config, target, mode = 'result') {
  return `${config.uiBaseUrl}/project/${encodeURIComponent(config.projectId)}`
    + `?mode=${encodeURIComponent(mode)}&job=${encodeURIComponent(target.jobId)}`
    + `&artifact=${encodeURIComponent(target.artifact)}`;
}

async function waitFor(webContents, expression, label, timeoutMs = SHORT_WAIT_MS) {
  const deadline = Date.now() + timeoutMs;
  let last = null;
  while (Date.now() < deadline) {
    try {
      last = await webContents.executeJavaScript(expression, true);
      if (last) return last;
    } catch (error) {
      last = error && error.message;
    }
    await pause(POLL_MS);
  }
  throw new Error(`timed out waiting for ${label}; last=${JSON.stringify(last)}`);
}

async function pageBoolean(webContents, expression) {
  return webContents.executeJavaScript(`Boolean(${expression})`, true);
}

async function semanticSnapshot(webContents) {
  const snapshot = await webContents.executeJavaScript(`
    (() => {
      const visible = (element) => {
        if (!(element instanceof HTMLElement || element instanceof SVGElement)) return false;
        const style = getComputedStyle(element);
        const rect = element.getBoundingClientRect();
        return style.display !== 'none' && style.visibility !== 'hidden' && rect.width > 0 && rect.height > 0;
      };
      const canvas = document.querySelector('[aria-label="结果主画布"]');
      const absolutePathLocations = new Set();
      const containsWindowsPath = (value) => {
        for (let index = 0; index + 2 < value.length; index += 1) {
          const code = value.charCodeAt(index);
          if (((code >= 65 && code <= 90) || (code >= 97 && code <= 122))
              && value[index + 1] === ':' && value.charCodeAt(index + 2) === 92) return true;
        }
        return false;
      };
      const publicText = (root) => {
        if (!root) return '';
        const chunks = [];
        const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
        let node = walker.nextNode();
        while (node) {
          const parent = node.parentElement;
          const closedDetails = parent?.closest('details:not([open])');
          const insideVisibleSummary = closedDetails && parent?.closest('summary') === closedDetails.querySelector(':scope > summary');
          const hiddenAncestor = parent?.closest('[hidden], [aria-hidden="true"]');
          if (parent && !hiddenAncestor && (!closedDetails || insideVisibleSummary)) {
            const style = getComputedStyle(parent);
            if (style.display !== 'none' && style.visibility !== 'hidden') {
              const value = node.nodeValue || '';
              chunks.push(value);
              if (value.includes('/Users/') || value.includes('/home/') || containsWindowsPath(value)) {
                const location = parent.closest('pre')
                  ? parent.closest('[aria-label="Result Studio 版本与变更"]') ? 'change_review_patch'
                    : parent.closest('[aria-label="结果主画布"]') ? 'result_canvas_pre'
                      : 'other_preformatted_text'
                  : parent.closest('code') ? 'structured_value'
                    : parent.closest('.sc-msg-assistant, .sc-msg-user') ? 'conversation'
                      : parent.closest('[aria-label="Result Studio 版本与变更"]') ? 'change_review'
                        : parent.closest('[aria-label="高级精细调整"]') ? 'advanced_drawer'
                          : 'other_visible_text';
                absolutePathLocations.add(location);
              }
            }
          }
          node = walker.nextNode();
        }
        return chunks.join(' ');
      };
      const text = publicText(document.body);
      const checkedRows = [...document.querySelectorAll('input[aria-label^="选择 "]')]
        .filter((input) => input.checked).length;
      const loadedImage = (image) => image instanceof HTMLImageElement
        && image.complete && image.naturalWidth > 0 && visible(image);
      const visualImages = canvas ? [...canvas.querySelectorAll('img')].filter(loadedImage).length : 0;
      const bodyNodes = canvas
        ? [...canvas.querySelectorAll('img, table, svg, iframe, pre, [role="img"], [data-viewer], [data-mode="table"], [data-mode="scatter"], [data-mode="matrix"]')]
        : [];
      return {
        canvasPresent: !!canvas,
        mode: canvas?.getAttribute('data-mode') || null,
        bodyVisible: bodyNodes.some(visible),
        composerState: document.querySelector('[aria-label="用 Agent 修改当前结果"]')?.getAttribute('data-state') || 'absent',
        advancedDrawerPresent: !!document.querySelector('details[aria-label="高级精细调整"]'),
        versionPanelPresent: !!document.querySelector('[aria-label="Result Studio 版本与变更"]'),
        selectedEntityCount: checkedRows,
        visualImageCount: visualImages,
        tablePresent: !!document.querySelector('[aria-label="科学结果表格"]'),
        rowHeaderPresent: !!document.querySelector('[aria-label="科学结果表格"] input[aria-label^="选择 "]'),
        assistantMessageCount: document.querySelectorAll('.sc-msg-assistant').length,
        resultProgressPresent: !!document.querySelector('[aria-label="结果修改五阶段进度"]'),
        stopControlPresent: !!document.querySelector('.sc-send-cta-stop'),
        scientificDifferenceVisible: text.includes('科学结论差异'),
        degDifferenceVisible: text.includes('显著基因') && text.includes('关键基因变化'),
        enrichmentRankAndDirectionVisible: text.includes('前列通路') && text.includes('方向变化'),
        impactPresentationVisible: text.includes('展示变化'),
        impactScientificVisible: text.includes('科学重算') || text.includes('流程变化'),
        executionNodesVisible: !!document.querySelector('[aria-label="实际执行节点"]'),
        internalLeakFlags: {
          absolutePath: /(?:\\/Users\\/|\\/home\\/|[A-Za-z]:\\\\)/.test(text),
          absolutePathLocations: [...absolutePathLocations].sort(),
          credential: /(?:sk-[A-Za-z0-9]{12,}|api[_ -]?key\\s*[:=])/i.test(text),
          rawInternalId: /\\b(?:rev|cs|tj|sel|conv|p)_[a-z0-9_-]{6,}\\b/i.test(text),
        },
      };
    })()
  `, true);
  return { ...snapshot, domSha256: digest(JSON.stringify(snapshot)) };
}

