} else {
  log('INFO', `=== summary: ${summary.passed}/${summary.total} passed${failed ? `, ${failed} failed` : ''} ===`);
}

process.exit(failed ? 1 : 0);

#!/usr/bin/env node
// release-checksums.mjs — 一键计算 dist/ 全部发布产物的 SHA-256 并合并到 SHA256SUMS.txt。
//
// 用法：
//   node scripts/release-checksums.mjs            # 扫描 dist/，写出 dist/SHA256SUMS.txt
//   node scripts/release-checksums.mjs --verify   # 对照 dist/SHA256SUMS.txt 重新校验
//   node scripts/release-checksums.mjs --quiet    # 静默模式，只在出错时输出
//
// 退出码：
//   0 = 成功（或 --verify 全过）
//   1 = --verify 失败（任一文件哈希不匹配）
//   2 = dist/ 目录不存在
//
// 与 .github/workflows/release.yml 的 release job 行为一致：按文件名字典序合并。
// macOS / Windows / Linux 三类产物的 SHA256SUMS-*.txt 在 CI 中分别产生后由 release
// job `sort -k 2` 合并。本脚本作为本地等价物——单一机器构建时直接覆盖三段文件。

import { createHash } from 'node:crypto';
import { readFile, writeFile, mkdir, stat } from 'node:fs/promises';
import { createReadStream } from 'node:fs';
import { resolve, basename, join } from 'node:path';
import { pipeline } from 'node:stream/promises';

const DIST_DIR = resolve(process.cwd(), 'dist');
const SUMS_FILE = join(DIST_DIR, 'SHA256SUMS.txt');
const VERIFY = process.argv.includes('--verify');
const QUIET = process.argv.includes('--quiet');

const log = QUIET ? () => {} : (...a) => console.log(...a);

async function hashFile(filePath) {
  const hash = createHash('sha256');
  await pipeline(createReadStream(filePath), hash);
  return hash.digest('hex');
}

function classify(filename) {
  if (/\.dmg$/i.test(filename)) return 'mac';
  if (/\.zip$/i.test(filename)) return 'mac';
  if (/\.exe$/i.test(filename)) return 'win';
  if (/\.AppImage$|\.deb$|\.snap$|\.tar\.gz$|\.pacman$/i.test(filename)) return 'linux';
  if (/\.blockmap$/i.test(filename)) return 'mac'; // mac blockmap 自带在 mac 分组
  return null;
}

function parseSumLine(line) {
  // 形如：  abc123...  filename
  const m = line.trim().match(/^([a-f0-9]{64})\s+\*?(.+)$/i);
  return m ? { hash: m[1].toLowerCase(), file: m[2].trim() } : null;
}

async function listReleaseArtifacts() {
  try {
    const entries = await import('node:fs/promises').then((m) => m.readdir(DIST_DIR, { withFileTypes: true }));
    return entries
      .filter((e) => e.isFile())
      .filter((e) => classify(e.name))
      .map((e) => e.name)
      .sort();
  } catch (err) {
    if (err.code === 'ENOENT') {
      log(`[release-checksums] dist/ does not exist. Run \`npm run build:*\` first.`);
      process.exit(2);
    }
    throw err;
  }
}

async function compute() {
  const names = await listReleaseArtifacts();
  if (names.length === 0) {
    log('[release-checksums] no release artifacts found in dist/.');
    process.exit(2);
  }
  log(`[release-checksums] hashing ${names.length} artifact(s)...`);
  const lines = [];
  for (const name of names) {
    const path = join(DIST_DIR, name);
    const h = await hashFile(path);
    lines.push(`${h}  ${name}`);
    log(`  ${h}  ${name}`);
  }
  lines.sort((a, b) => a.split(/\s+/)[1].localeCompare(b.split(/\s+/)[1]));
  await writeFile(SUMS_FILE, lines.join('\n') + '\n');
  log(`[release-checksums] wrote ${SUMS_FILE}`);
}

async function verify() {
  let raw;
  try {
    raw = await readFile(SUMS_FILE, 'utf8');
  } catch (err) {
    log(`[release-checksums] ${SUMS_FILE} not found. Run without --verify to generate it.`);
    process.exit(2);
  }
  const entries = raw
    .split('\n')
    .map(parseSumLine)
    .filter(Boolean);
  log(`[release-checksums] verifying ${entries.length} entry/entries...`);
  let failed = 0;
  for (const { hash, file } of entries) {
    const path = join(DIST_DIR, file);
    try {
      await stat(path);
    } catch {
      log(`  MISSING  ${file}`);
      failed += 1;
      continue;
    }
    const actual = await hashFile(path);
    if (actual !== hash) {
      log(`  MISMATCH ${file}\n    expected ${hash}\n    actual   ${actual}`);
      failed += 1;
    } else {
      log(`  OK       ${file}`);
    }
  }
  if (failed > 0) {
    log(`[release-checksums] ${failed} verification failure(s).`);
    process.exit(1);
  }
  log(`[release-checksums] all entries match.`);
}

if (VERIFY) {
  await verify();
} else {
  await compute();
}

#!/usr/bin/env node
// BLOCK-104 P4 — Windows 专属脚本入口护栏：非 win32 直接退出，杜绝半途怪异失败。
if (process.platform !== 'win32') {
  console.error(`[platform] resume-py-runtime-zip.mjs 仅支持 Windows（当前 ${process.platform}）。`);
  process.exit(2);
}
/**
 * resume-py-runtime-zip.mjs  (一次性恢复脚本，2026-08-08)
 * ---------------------------------------------------------------
 * build-win-runtime-artifact.mjs 的 prune() 因逐文件删除 2 万+ .pyc 过慢、
 * 在会话重置时被打断；而 Compress-Archive 对 1.6GB 的 Python 树（完整科学栈）
 * 会因内存缓冲爆掉、留下 0 字节 zip。本脚本复用已完成的 staging
 * （前缀复制 + pip 安装都已做完），只补齐：
 *   1) prune()  —— 用 .NET 整目录删除 __pycache__（快速、绕过 safe-delete shim）
 *   2) zip()    —— 纯 Node 流式 ZIP 写入（zlib raw-deflate，逐文件、常驻内存低，
 *                  标准 zip，unzip/Expand-Archive/.NET ZipFile 均可读），
 *                  顶层为 Python/（单层，与 R 制品一致）
 *   3) digest() —— sha256 + sizeBytes
 *   4) 打印与 build-win-runtime-artifact.mjs 一致的收尾摘要
 *
 * 用法：node scripts/resume-py-runtime-zip.mjs
 *   可选环境变量：STAGE_ROOT=<已有 staging 目录>
 */

import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import zlib from 'node:zlib';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.resolve(__dirname, '..');
const OUT_DIR = process.env.OUT_DIR ? path.resolve(process.env.OUT_DIR) : path.join(REPO_ROOT, 'dist-runtime');

function fail(msg, err) {
  console.error(`\n[resume-py] ERROR: ${msg}`);
  if (err) console.error(err);
  process.exit(1);
}

function locateStaging() {
  if (process.env.STAGE_ROOT) {
    const p = path.resolve(process.env.STAGE_ROOT);
    if (!fs.existsSync(p)) fail(`STAGE_ROOT 不存在: ${p}`);
    return p;
  }
  const matches = fs.readdirSync(OUT_DIR)
    .filter((d) => d.startsWith('petri-py-runtime-staging-'))
    .map((d) => path.join(OUT_DIR, d));
  if (matches.length === 0) fail(`在 ${OUT_DIR} 找不到 petri-py-runtime-staging-* 目录，请先运行 build-win-runtime-artifact.mjs`);
  if (matches.length > 1) console.warn(`[resume-py] 发现多个 staging，使用第一个: ${matches[0]}`);
  return matches[0];
}

// ---- prune via .NET（快速、绕过 safe-delete shim 的批量删除拦截） ----
function prune(stagePython) {
  console.log('[resume-py] pruning __pycache__ via .NET ...');
  const ps = [
    `Get-ChildItem -Path '${stagePython}' -Recurse -Directory -Filter '__pycache__' |`,
    `ForEach-Object { [System.IO.Directory]::Delete($_.FullName, $true) }`,
  ].join(' ');
  const r = spawnSync('powershell.exe', ['-NoProfile', '-Command', ps], {
    stdio: 'inherit', windowsHide: true, timeout: 1000 * 60 * 10,
  });
  if (r.status !== 0) fail('prune(__pycache__) 失败');
  console.log('[resume-py] prune done');
}

// ---- 纯 Node 流式 ZIP 写入（deflate，逐文件，常驻内存低） ----
const CRC_TABLE = (() => {
  const t = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = (c & 1) ? (0xedb88320 ^ (c >>> 1)) : (c >>> 1);
    t[n] = c >>> 0;
  }
  return t;
})();
function crc32(buf) {
  let c = 0xffffffff;
  for (let i = 0; i < buf.length; i++) c = CRC_TABLE[(c ^ buf[i]) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}

function dosDateTime(d = new Date(1980, 0, 1, 0, 0, 0)) {
  const time = ((d.getHours() & 0x1f) << 11) | ((d.getMinutes() & 0x3f) << 5) | ((d.getSeconds() / 2) & 0x1f);
  const date = (((d.getFullYear() - 1980) & 0x7f) << 9) | (((d.getMonth() + 1) & 0xf) << 5) | (d.getDate() & 0x1f);
  return { time: time & 0xffff, date: date & 0xffff };
}

/**
 * 把 srcDir 打成 zip，顶层统一加 topName/ 前缀（单层）。
 * 逐文件读取 + raw-deflate，内存占用恒定，适合超大目录。
 */
function zipDirSingleLayer(srcDir, zipPath, topName) {
  fs.mkdirSync(path.dirname(zipPath), { recursive: true });
  if (fs.existsSync(zipPath)) fs.rmSync(zipPath, { force: true });

  const fd = fs.openSync(zipPath, 'w');
  const central = [];
  const { time, date } = dosDateTime();
  let fileCount = 0;
  let byteCount = 0;

  const walk = (dir, relPrefix) => {
    const entries = fs.readdirSync(dir, { withFileTypes: true });
    for (const e of entries) {
      const abs = path.join(dir, e.name);
      const rel = relPrefix ? `${relPrefix}/${e.name}` : e.name;
      if (e.isDirectory()) {
        walk(abs, rel);
      } else if (e.isFile()) {
        const data = fs.readFileSync(abs);
        const comp = zlib.deflateRawSync(data, { level: 6 });
        const crc = crc32(data);
        const name = `${topName}/${rel}`;
        const nameBuf = Buffer.from(name, 'utf8');
        const localOffset = byteCount;

        const header = Buffer.alloc(30);
        header.writeUInt32LE(0x04034b50, 0);   // local file header sig
        header.writeUInt16LE(20, 4);           // version needed
        header.writeUInt16LE(0x0800, 6);       // flags: UTF-8 names
        header.writeUInt16LE(8, 8);            // method: deflate
        header.writeUInt16LE(time, 10);
        header.writeUInt16LE(date, 12);
        header.writeUInt32LE(crc, 14);
        header.writeUInt32LE(comp.length, 18); // compressed size
        header.writeUInt32LE(data.length, 22); // uncompressed size
        header.writeUInt16LE(nameBuf.length, 26);
        header.writeUInt16LE(0, 28);           // extra len

        fs.writeSync(fd, header);
        fs.writeSync(fd, nameBuf);
        fs.writeSync(fd, comp);

        central.push({
          crc, compLen: comp.length, uncompLen: data.length, nameBuf, localOffset,
        });
        byteCount += 30 + nameBuf.length + comp.length;
        fileCount++;
        if (fileCount % 5000 === 0) console.log(`[resume-py] zipped ${fileCount} files ...`);
      }
    }
  };

  walk(srcDir, '');

  const centralStart = byteCount;
  for (const c of central) {
    const ch = Buffer.alloc(46);
    ch.writeUInt32LE(0x02014b50, 0);  // central dir header sig
    ch.writeUInt16LE(20, 4);          // version made by
    ch.writeUInt16LE(20, 6);          // version needed
    ch.writeUInt16LE(0x0800, 8);      // flags
    ch.writeUInt16LE(8, 10);          // method
    ch.writeUInt16LE(time, 12);
    ch.writeUInt16LE(date, 14);
    ch.writeUInt32LE(c.crc, 16);
    ch.writeUInt32LE(c.compLen, 20);
    ch.writeUInt32LE(c.uncompLen, 24);
    ch.writeUInt16LE(c.nameBuf.length, 28);
    ch.writeUInt16LE(0, 30);          // extra len
    ch.writeUInt16LE(0, 32);          // comment len
    ch.writeUInt16LE(0, 34);          // disk number start
    ch.writeUInt16LE(0, 36);          // internal attrs
    ch.writeUInt32LE(0, 38);          // external attrs
    ch.writeUInt32LE(c.localOffset, 42);
    fs.writeSync(fd, ch);
    fs.writeSync(fd, c.nameBuf);
    byteCount += 46 + c.nameBuf.length;
  }

  const centralSize = byteCount - centralStart;
  const eocd = Buffer.alloc(22);
  eocd.writeUInt32LE(0x06054b50, 0);  // EOCD sig
  eocd.writeUInt16LE(0, 4);           // disk number
  eocd.writeUInt16LE(0, 6);           // disk with central dir
  eocd.writeUInt16LE(fileCount, 8);   // entries this disk
  eocd.writeUInt16LE(fileCount, 10);  // total entries
  eocd.writeUInt32LE(centralSize, 12);
  eocd.writeUInt32LE(centralStart, 16);
  eocd.writeUInt16LE(0, 20);          // comment len
  fs.writeSync(fd, eocd);

  fs.fsyncSync(fd);
  fs.closeSync(fd);
  console.log(`[resume-py] zip written: ${fileCount} files, ${byteCount} bytes`);
}

function digest(zipPath) {
  const buf = fs.readFileSync(zipPath);
  return { sha256: crypto.createHash('sha256').update(buf).digest('hex'), sizeBytes: buf.length };
}

function main() {
  const stageRoot = locateStaging();
  const stagePython = path.join(stageRoot, 'Python');
  if (!fs.existsSync(path.join(stagePython, 'python.exe'))) {
    fail(`staging 内未找到 python.exe: ${path.join(stagePython, 'python.exe')}`);
  }
  console.log(`[resume-py] using staging: ${stageRoot}`);

  prune(stagePython);

  const zipPath = path.join(OUT_DIR, 'py-runtime-1.0.0-windows-x64.zip');
  console.log(`[resume-py] streaming-zip -> ${zipPath}`);
  zipDirSingleLayer(stagePython, zipPath, 'Python');

  const { sha256, sizeBytes } = digest(zipPath);

  console.log('\n==================== RESUME BUILD COMPLETE ====================');
  console.log(`artifact : ${zipPath}`);
  console.log(`sizeBytes: ${sizeBytes}`);
  console.log(`sha256   : ${sha256}`);
  console.log('\n⚠️ 收尾边界（与 R 制品一致，2026-08-08 确立）：');
  console.log('  1) 用 scripts/upload-win-python-runtime.mjs 把 zip 传到 OSS');
  console.log('     oss://petri-uploads/plugins/py-runtime/1.0.0/windows-x64.zip（public-read + HEAD 校验）。');
  console.log('  2) 不要把 windows-x64 写进 manifest.json 的 artifacts ——');
  console.log('     plugin-manifest-schema.test.mjs 第 70-74 行要求 windows-x64 必须为 0。');
  console.log('     release-contract.windows-x64.supported 维持 false。');
  console.log('  3) petri-py-runtime 的占位已从 manifest.placeholders.json 移除。\n');
  console.log(JSON.stringify({
    platform: 'windows-x64',
    url: 'https://petri-uploads.oss-cn-hangzhou.aliyuncs.com/plugins/py-runtime/1.0.0/windows-x64.zip',
    sha256,
    sizeBytes,
  }, null, 2));
}

try { main(); } catch (e) { fail('未预期错误', e); }

#!/usr/bin/env node
/**
 * scripts/skill-scaffold.mjs — 产品 Skill 脚手架与校验器（BLOCK-71）
 *
 * 两种模式：
 *   --check                 校验 resources/skills/ 下全部内置 Skill（默认随 closeout 跑）
 *   --scaffold <id> --name <名称> [--category <c>] [--version <v>]
 *                           生成新 Skill 目录骨架（skill.json / README.md / manifest.json /
 *                           prompts/system.md），随后 skills:check 会因顶层 manifest
 *                           未登记而 FAIL —— 这是故意的 fail-closed 提醒。
 *
 * 校验范围（对齐真实消费方 core/shared-backend/skill-registry.js）：
 *   - skill.json 存在且可解析；核心校验单源复用 skill-registry 的 validateSkillManifest，
 *     不建第二套字段校验真相
 *   - id 与目录名一致；README.md 存在；prompts 引用的文件存在
 *   - 顶层 resources/skills/manifest.json 已登记且 version 一致（双向核对）
 *   - plugins.required/optional 引用的插件在 resources/built-in-plugins/ 真实存在
 *
 * 退出码：0 = 全部通过；1 = 存在校验失败；2 = 参数错误。
 */
import fs from 'node:fs';
import path from 'node:path';
import { createRequire } from 'node:module';
import { fileURLToPath } from 'node:url';

const require = createRequire(import.meta.url);
const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const SKILLS_DIR = path.join(ROOT, 'resources', 'skills');
const PLUGINS_DIR = path.join(ROOT, 'resources', 'built-in-plugins');

// 单源复用产品侧校验逻辑（skill-registry 同时服务 MCP skill_* 工具）
const { validateSkillManifest, isValidSkillId } = require(
  path.join(ROOT, 'core', 'shared-backend', 'skill-registry.js'),
);

function readJson(file) {
  try {
    return JSON.parse(fs.readFileSync(file, 'utf8'));
  } catch {
    return null;
  }
}

function checkAll() {
  const problems = [];
  if (!fs.existsSync(SKILLS_DIR)) {
    console.error(`skills 目录不存在: ${SKILLS_DIR}`);
    process.exit(1);
  }
  const entries = fs.readdirSync(SKILLS_DIR, { withFileTypes: true });
  const dirs = entries.filter((e) => e.isDirectory()).map((e) => e.name).sort();
  const topLevelManifest = readJson(path.join(SKILLS_DIR, 'manifest.json'));
  if (!topLevelManifest?.skills) problems.push('顶层 manifest.json 缺失或无 skills 字段');

  for (const dir of dirs) {
    const skillDir = path.join(SKILLS_DIR, dir);
    const label = `skills/${dir}`;

    const skill = readJson(path.join(skillDir, 'skill.json'));
    if (!skill) {
      problems.push(`${label}: skill.json 缺失或 JSON 非法`);
      continue;
    }
    if (skill.id !== dir) problems.push(`${label}: skill.json id "${skill.id}" 与目录名不一致`);

    const v = validateSkillManifest(skill);
    if (!v.ok) for (const e of v.errors) problems.push(`${label}: ${e}`);

    if (!fs.existsSync(path.join(skillDir, 'README.md'))) problems.push(`${label}: 缺 README.md`);

    for (const [key, rel] of Object.entries(skill.prompts || {})) {
      if (typeof rel !== 'string') continue;
      if (!fs.existsSync(path.join(skillDir, rel))) problems.push(`${label}: prompts.${key} 指向不存在的文件 ${rel}`);
    }

    // required = 硬依赖，必须是真实存在的内置插件；optional 允许 R 包能力名（如 enrichplot），不查存在性
    for (const pluginId of skill.plugins?.required || []) {
      if (!/^[a-z0-9][a-z0-9-]*$/.test(pluginId)) continue;
      if (!fs.existsSync(path.join(PLUGINS_DIR, pluginId, 'tool-definition.json'))) {
        problems.push(`${label}: plugins.required 引用插件 "${pluginId}" 在 built-in-plugins 中不存在`);
      }
    }

    const registered = topLevelManifest?.skills?.[dir];
    if (!registered) {
      problems.push(`${label}: 未登记进顶层 manifest.json`);
    } else if (registered.version && skill.version && registered.version !== skill.version) {
      problems.push(`${label}: 顶层 manifest version ${registered.version} ≠ skill.json version ${skill.version}`);
    }
  }

  // 反向核对：顶层 manifest 里的 id 必须有对应目录
  for (const id of Object.keys(topLevelManifest?.skills || {})) {
    if (!dirs.includes(id)) problems.push(`顶层 manifest.json: skill "${id}" 无对应目录`);
  }

  if (problems.length) {
    console.log(`== 产品 Skill 校验: FAIL（${problems.length} 项）==`);
    for (const p of problems) console.log(`  ❌ ${p}`);
    process.exit(1);
  }
  console.log(`== 产品 Skill 校验: PASS（${dirs.length} 个内置 Skill）==`);
}

function scaffold(args) {
  const get = (flag, fallback) => {
    const i = args.indexOf(flag);
    return i >= 0 && args[i + 1] ? args[i + 1] : fallback;
  };
  const id = get('--scaffold') || get('--id');
  const name = get('--name');
  if (!id || !name) {
    console.error('用法: node scripts/skill-scaffold.mjs --scaffold <id> --name "<名称>" [--category <c>] [--version <v>]');
    process.exit(2);
  }
  if (!isValidSkillId(id)) {
    console.error(`非法 Skill id: ${id}（必须 kebab-case）`);
    process.exit(2);
  }
  const category = get('--category', 'bioinformatics/general');
  const version = get('--version', '1.0.0');
  const skillDir = path.join(SKILLS_DIR, id);
  if (fs.existsSync(skillDir)) {
    console.error(`目录已存在: ${skillDir}`);
    process.exit(2);
  }

  const kebabCaps = id.split('-').map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
  fs.mkdirSync(path.join(skillDir, 'prompts', 'user'), { recursive: true });
  fs.writeFileSync(path.join(skillDir, 'skill.json'), JSON.stringify({
    skillManifestVersion: 1,
    id,
    name,
    version,
    description: `${name}（脚手架占位描述，收口前改写为真实能力说明）`,
    category,
    tags: [],
    source: 'built-in',
    capabilities: [],
    plugins: { required: [], optional: [] },
    workflows: { default: null, variants: [] },
    prompts: { system: 'prompts/system.md' },
    parameters: { required: [], optional: {} },
    outputs: { primary: [], secondary: [] },
    metadata: {
      author: 'Petri Team',
      license: 'MIT',
      source: 'built-in',
      created: new Date().toISOString().slice(0, 10),
      updated: new Date().toISOString().slice(0, 10),
    },
  }, null, 2) + '\n');
  fs.writeFileSync(path.join(skillDir, 'README.md'),
    `# ${name}（${kebabCaps}）\n\n> 脚手架占位：在此写清本 Skill 的适用场景、输入约定与产出。\n\n- 状态：scaffold，未实现\n- 校验：\`npm run skills:check\`（登记进顶层 manifest 前会 FAIL，属预期 fail-closed）\n`);
  fs.writeFileSync(path.join(skillDir, 'prompts', 'system.md'),
    `# ${name} — system prompt 占位\n\n在此定义本 Skill 的系统提示词（角色、边界、失败语义）。\n`);
  fs.writeFileSync(path.join(skillDir, 'prompts', 'user', 'README.md'),
    '# user prompt 模板目录\n\n本 Skill 的用户侧 prompt 模板放这里（.md）。\n');

  console.log(`✅ 已生成骨架: ${skillDir}`);
  console.log('下一步（缺一不可）:');
  console.log(`  1. 在 resources/skills/manifest.json 的 skills 中登记 "${id}"（含 version ${version}）`);
  console.log(`  2. 改写 skill.json 占位描述 / README / prompts/system.md`);
  console.log(`  3. npm run skills:check 确认全绿`);
}

function main() {
  const argv = process.argv.slice(2);
  if (argv.includes('--check')) return checkAll();
  if (argv.includes('--scaffold')) return scaffold(argv);
  console.error('用法: node scripts/skill-scaffold.mjs --check | --scaffold <id> --name "<名称>"');
  process.exit(2);
}

main();

#!/usr/bin/env node
/**
 * scripts/test-affected.mjs — 基于 `test/impact-map.json` 的最小充分测试范围选择器
 *
 * 提供 `npm run test:changed:list`（--json）和 `npm run test:changed`（--run）两个
 * 入口；前者只输出计划，后者按计划执行影响范围内的测试与门禁。
 *
 * 退出码契约（GATES-1 文档化，2026-08-16）：
 *   0   PASS — 计划可执行 / 全部测试 / 门禁通过
 *   1   FAIL — 实际执行失败（某 node test / 门禁子命令非 0 退出）
 *   2   分类冲突 — 改动文件无法被 `test/impact-map.json` 任一规则匹配
 *       （即 `plan.unknown.length > 0`），或 impact-map 自身解析/校验失败、
 *       或运行期 catch 异常。**2 不是 fail-closed**：仅说明当前改动没有
 *       impact-map 规则覆盖，需补 rule 或添加"未分类但可忽略"声明；
 *       绝不代表业务代码 / 工作包"未通过"测试。
 *
 * `--report` JSON 输出模式（GATES-2 文档化，2026-08-16）：
 *   与 `--json` / `--run` 并行的可选模式；通过 `--report <path>` 触发，输出
 *   机器可读 JSON，由 `docs/schemas/test-affected-report.schema.json` 强校验。
 *   写盘失败 / schema 校验失败 → exit 2（分类冲突）。与 `--json` 同源 plan。
 *   现有 `--json` / `--run` 行为**不变**。
 *
 * 同步文档：`docs/document-governance.md` §4.5"门禁退出码契约" + GATES-2 §3.2"JSON 输出契约"。
 * 该契约为本工作包 DOC-GOVERNANCE-GATES / GATES-1 阶段固化本，不在本阶段内
 * 改动 `process.exit()` 行为；如未来升级退出码语义须同步 §4.5。
 *
 * 注：plan 文档 `docs/doc-governance-gates-plan.md` §2.2 文件名引用
 * `test-impact-map.mjs` 是历史笔误；实际物理文件为 `scripts/test-affected.mjs`，
 * 由 `package.json` 的 `test:changed:list` / `test:changed` 引用。
 */

import { execFileSync, spawnSync } from 'node:child_process';
import { existsSync, readFileSync } from 'node:fs';
import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, resolve, isAbsolute } from 'node:path';
import { fileURLToPath } from 'node:url';
import { GATE_REPORT_SCHEMA_VERSION, validateReport } from './lib/gate-report-schema.mjs';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const MAP = JSON.parse(readFileSync(resolve(ROOT, 'test/impact-map.json'), 'utf8'));
const COMMANDS = {
  'docs-check': ['npm', ['run', 'docs:check']],
  'ui-audit': ['npm', ['run', 'ui:audit:check']],
  'harness-check': ['npm', ['run', 'harness:check']],
  'frontend-check': ['npm', ['--prefix', 'frontend', 'run', 'check']],
  'frontend-all': ['npm', ['--prefix', 'frontend', 'run', 'test:all']],
};
const COMMAND_ORDER = ['docs-check', 'ui-audit', 'harness-check', 'frontend-check', 'frontend-all'];

function escapeRegExp(value) { return value.replace(/[|\\{}()[\]^$+?.]/g, '\\$&'); }

export function globMatches(pattern, value) {
  let source = '^';
  for (let i = 0; i < pattern.length; i += 1) {
    if (pattern[i] === '*' && pattern[i + 1] === '*') { source += '.*'; i += 1; }
    else if (pattern[i] === '*') source += '[^/]*';
    else source += escapeRegExp(pattern[i]);
  }
  return new RegExp(`${source}$`).test(value);
}

function normalizePath(value) { return value.replaceAll('\\', '/').replace(/^\.\//, ''); }

function runGit(args) {
  return execFileSync('git', args, { cwd: ROOT, encoding: 'utf8' })
    .split(/\r?\n/).map((line) => normalizePath(line.trim())).filter(Boolean);
}

function listScripts() {
  // 原生 git 文件树枚举（tracked + untracked，排除 gitignore），不依赖外部 `rg`：
  // 原实现 `execFileSync('rg', ['--files','scripts'])` 在未安装 ripgrep 的机器上抛
  // `spawnSync rg ENOENT`，导致 `npm run test:changed` / `npm run closeout` 无法收口。
  // git 是仓库既有硬依赖（runGit 已用），此处改为等价枚举，跨机可复现。
  const files = new Set([
    ...runGit(['ls-files', 'scripts']),
    ...runGit(['ls-files', '--others', '--exclude-standard', 'scripts']),
  ]);
  return [...files]
    // FILE-TREE-POLICY：scripts/archive/ 是一次性 driver 的归档区，不参与“恰好一规则”分类约束。
    .filter((file) => /\.(?:js|mjs|cjs|sh)$/.test(file) && !file.startsWith('scripts/archive/'));
}

function validateMap(map) {
  if (map.schema !== 'petri/test-impact-map.v1' || !Array.isArray(map.rules)) throw new Error('invalid test impact map schema');
  const commandIds = new Set(Object.keys(COMMANDS));
  const scriptRules = [];
  for (const rule of map.rules) {
    if (!rule.id || !Array.isArray(rule.patterns) || !rule.patterns.length) throw new Error(`invalid impact rule: ${rule.id || '<missing>'}`);
    for (const command of rule.commands || []) if (!commandIds.has(command)) throw new Error(`${rule.id} references unknown command ${command}`);
    for (const test of rule.tests || []) if (!existsSync(resolve(ROOT, test))) throw new Error(`${rule.id} references missing test ${test}`);
    if (rule.classifiesScripts) scriptRules.push(rule);
  }
  const uncovered = listScripts().filter((file) => scriptRules.filter((rule) => rule.patterns.some((pattern) => globMatches(pattern, file))).length !== 1);
  if (uncovered.length) throw new Error(`script classification must match exactly one rule: ${uncovered.join(', ')}`);
}

export function collectChangedFiles({ base = null, explicit = [] } = {}) {
  if (explicit.length) return [...new Set(explicit.map(normalizePath))].sort();
  const files = new Set();
  if (base) runGit(['diff', '--name-only', '--diff-filter=ACMR', `${base}...HEAD`]).forEach((file) => files.add(file));
  runGit(['diff', '--name-only', '--diff-filter=ACMR']).forEach((file) => files.add(file));
  runGit(['diff', '--cached', '--name-only', '--diff-filter=ACMR']).forEach((file) => files.add(file));
  runGit(['ls-files', '--others', '--exclude-standard']).forEach((file) => files.add(file));
  return [...files].sort();
}

function isNodeSource(file) { return /\.(?:js|mjs|cjs)$/.test(file) && !file.startsWith('test/') && !file.startsWith('frontend/'); }

export function resolveImpact(changedFiles, map = MAP) {
  validateMap(map);
  const tests = new Set(); const commands = new Set(); const frontendRelated = new Set(); const syntax = new Set(); const unknown = []; const reasons = new Map();
  for (const file of changedFiles.map(normalizePath)) {
    let matched = false;
    for (const rule of map.rules) {
      if (!rule.patterns.some((pattern) => globMatches(pattern, file))) continue;
      matched = true;
      for (const test of rule.tests || []) tests.add(test);
      for (const command of rule.commands || []) commands.add(command);
      if (rule.frontendRelated) frontendRelated.add(file.replace(/^frontend\//, ''));
      reasons.set(file, [...(reasons.get(file) || []), rule.id]);
    }
    if (/^frontend\/src\//.test(file)) frontendRelated.add(file.replace(/^frontend\//, ''));
    if (isNodeSource(file)) syntax.add(file);
    if (/^test\/.*\.test\.(?:mjs|cjs|js)$/.test(file)) tests.add(file);
    if (!matched && !/^dist\//.test(file) && !/^release\//.test(file)) unknown.push(file);
  }
  return { changedFiles: [...new Set(changedFiles.map(normalizePath))].sort(), tests: [...tests].sort(), commands: COMMAND_ORDER.filter((command) => commands.has(command)), frontendRelated: [...frontendRelated].sort(), syntax: [...syntax].sort(), unknown: [...new Set(unknown)].sort(), reasons: Object.fromEntries([...reasons].map(([file, rules]) => [file, [...new Set(rules)]])) };
}

function parseArgs(argv) {
  const explicit = argv.find((arg) => arg.startsWith('--files='));
  return { run: argv.includes('--run'), json: argv.includes('--json'), base: argv.find((arg) => arg.startsWith('--base='))?.slice(7) || null, explicit: explicit ? explicit.slice(8).split(',').filter(Boolean) : [] };
}

function printPlan(plan, json) {
  if (json) {
    console.log(JSON.stringify(plan, null, 2));
    if (plan.unknown.length) {
      console.error(`[test:changed] 分类冲突：${plan.unknown.length} 个改动文件未被 test/impact-map.json 任一规则覆盖；exit 2 表示需要补 rule，**不是** fail-closed。`);
      console.error(`[test:changed] 未映射文件：${plan.unknown.join(', ')}`);
    }
    return;
  }
  console.log(`[test:changed] changed=${plan.changedFiles.length} nodeTests=${plan.tests.length} syntax=${plan.syntax.length}`);
  plan.tests.forEach((file) => console.log(`  test ${file}`));
  plan.frontendRelated.forEach((file) => console.log(`  frontend-related ${file}`));
  if (plan.commands.length) console.log(`  gates ${plan.commands.join(', ')}`);
  if (plan.unknown.length) {
    console.error(`  unmapped ${plan.unknown.join(', ')}`);
    console.error(`[test:changed] 分类冲突：${plan.unknown.length} 个改动文件未被 test/impact-map.json 任一规则覆盖；exit 2 表示需要补 rule，**不是** fail-closed。`);
    console.error('[test:changed] 处理方式：补 rule / 在 impact-map.json 添加 patterns / 把文件加入已忽略前缀（dist/、release/）。');
  }
}

function runProcess(command, args) {
  // Windows：spawnSync 无 shell 时拒绝执行 npm.cmd（Node CVE 修复后的 EINVAL），
  // 门禁步骤会静默失败——win32 对 npm 加 shell:true（参数全部为简单旗标，
  // 无引号注入面）；树非干净且计划含 docs/ui 门禁时必现，树干净时计划为空
  // 从不触发，故此前未暴露。
  const needsShell = process.platform === 'win32' && command === 'npm';
  const options = { cwd: ROOT, stdio: 'inherit' };
  if (needsShell) options.shell = true;
  return spawnSync(command, args, options).status ?? 1;
}

export function runPlan(plan) {
  if (plan.unknown.length) return 2;
  for (const file of plan.syntax) { const status = runProcess(process.execPath, ['--check', file]); if (status !== 0) return status; }
  // BLOCK-97 收口沉淀（2026-09-17）：node --test 批里只要有一个套件泄漏
  // keep-alive 句柄（例：block93-role-prompt 的 mock 上游 server 不 close），
  // runner 就在「用例全过后」无限等待进程退出——聚合批表现为整体挂起
  // （实测 28 分钟零 CPU）。--test-force-exit 让 runner 在用例完成后强制
  // 退出，--test-timeout=120000 给单个用例兜底超时：任何套件都无法再把
  // 聚合门禁拖死。挂起定诊法=对比进程 CPU 时间（零增量=挂起而非慢）。
  if (plan.tests.length) { const status = runProcess(process.execPath, ['--test', '--test-force-exit', '--test-timeout=120000', ...plan.tests]); if (status !== 0) return status; }
  if (plan.frontendRelated.length) { const status = runProcess('npm', ['--prefix', 'frontend', 'run', 'test:related', '--', ...plan.frontendRelated, '--passWithNoTests']); if (status !== 0) return status; }
  if (plan.commands.includes('frontend-all')) { const status = runProcess(...COMMANDS['frontend-all']); if (status !== 0) return status; }
  for (const command of plan.commands.filter((item) => item !== 'frontend-all')) { const status = runProcess(...COMMANDS[command]); if (status !== 0) return status; }
  return 0;
}

/**
 * GATES-2 `--report` JSON output mode. Emits a deterministic JSON report
 * conforming to `docs/schemas/test-affected-report.schema.json`, using the
 * same plan machinery as `--json`. Exit codes follow the existing
 * 0/1/2 contract:
 *   0 — schema-valid report written; plan has no unknown files
 *   1 — schema-valid report written; --run failed (only if --run also passed)
 *   2 — classification conflict (path invalid, write failed, schema failed,
 *       or plan has unknown files)
 */
function runReportMode(reportPathRaw, base) {
  const reportPath = isAbsolute(reportPathRaw) ? reportPathRaw : resolve(process.cwd(), reportPathRaw);
  let plan;
  try {
    plan = resolveImpact(collectChangedFiles({ base }));
  } catch (error) {
    console.error(`[test:changed:report] 分类冲突 — plan generation failed: ${error.message}`);
    process.exitCode = 2;
    return;
  }
  const isFailure = plan.unknown.length > 0;
  const status = isFailure ? 'CLASSIFICATION_CONFLICT' : 'PASS';
  const exitCode = isFailure ? 2 : 0;

  const report = {
    schemaVersion: GATE_REPORT_SCHEMA_VERSION,
    generatedAt: new Date().toISOString(),
    script: 'scripts/test-affected.mjs',
    mode: 'report',
    exitCode,
    summary: {
      status,
      result: isFailure ? 'classification_conflict' : 'pass',
      changedFiles: plan.changedFiles.length,
      tests: plan.tests.length,
      commands: plan.commands.length,
      frontendRelated: plan.frontendRelated.length,
      syntax: plan.syntax.length,
      unknown: plan.unknown.length,
    },
    plan: {
      changedFiles: plan.changedFiles,
      tests: plan.tests,
      commands: plan.commands,
      frontendRelated: plan.frontendRelated,
      syntax: plan.syntax,
      unknown: plan.unknown,
      reasons: plan.reasons,
    },
  };

  const validation = validateReport('scripts/test-affected.mjs', report);
  if (!validation.valid) {
    console.error('[test:changed:report] 分类冲突 — produced JSON does not match schema:');
    for (const err of validation.errors) {
      console.error(`  - ${err.path} ${err.keyword}: ${err.message}`);
    }
    process.exitCode = 2;
    return;
  }

  try {
    mkdirSync(dirname(reportPath), { recursive: true });
    writeFileSync(reportPath, `${JSON.stringify(report, null, 2)}\n`, 'utf8');
  } catch (error) {
    console.error(`[test:changed:report] 分类冲突 — failed to write report to ${reportPath}: ${error.message}`);
    process.exitCode = 2;
    return;
  }
  report.reportPath = reportPath;
  if (isFailure) {
    console.error(`[test:changed:report] CLASSIFICATION_CONFLICT (${plan.unknown.length} unmapped files); report written to ${reportPath}`);
    process.exitCode = 2;
    return;
  }
  console.log(`[test:changed:report] PASS (changed=${plan.changedFiles.length}, tests=${plan.tests.length}); report written to ${reportPath}`);
  process.exitCode = 0;
}

if (process.argv[1] && resolve(process.argv[1]) === resolve(fileURLToPath(import.meta.url))) {
  const argv = process.argv.slice(2);
  const reportIdx = argv.indexOf('--report');
  if (reportIdx >= 0) {
    const reportPathRaw = argv[reportIdx + 1];
    if (!reportPathRaw || reportPathRaw.startsWith('--')) {
      console.error('--report requires a non-empty output path argument.');
      process.exitCode = 2;
    } else {
      const base = parseArgs(argv).base;
      runReportMode(reportPathRaw, base);
    }
  } else {
    try {
      const args = parseArgs(argv);
      const plan = resolveImpact(collectChangedFiles({ base: args.base, explicit: args.explicit }));
      printPlan(plan, args.json);
      process.exitCode = args.run ? runPlan(plan) : (plan.unknown.length ? 2 : 0);
    } catch (error) {
      console.error(`[test:changed] 分类冲突（工具错误）：${error.message}`);
      console.error('[test:changed] exit 2 表示 test/impact-map.json 解析 / 校验失败或 plan 生成异常；**不是** fail-closed。');
      process.exitCode = 2;
    }
  }
}

#!/usr/bin/env node
// platform-note: dual — powershell 出现在 agent 提示词内（由 workspace_exec 在执行目标侧运行），脚本本体平台无关。（BLOCK-104 P4 门禁标注）
'use strict';

/**
 * UI-315 forced 实机验收（dev Electron + 真实模型 + CDP）：
 *   1) 当前会话 baseline 终端块数 → composer 发送 forced workspace_exec 提示
 *      （唯一标记命令 node -e "console.log(314159*2)"，与历史终端行无歧义）
 *   2) 断言新终端块渲染：折叠头命令预览含标记 / data-status=success / ✓ 状态字形
 *   3) 展开该行断言（UI-315 优化三 WIP DOM 契约）：
 *      - 展开体命令行 .sc-tool-term-command-text 含标记（$ 前缀）
 *      - 行内图标复制按钮 .sc-tool-term-copy（命令）+ .sc-tool-term-copy-out（输出，hover 显隐）
 *      - 输出 pre 含 628318（314159*2）
 *   4) Page.reload 历史恢复：meta.toolActivities 持久化，命令/输出仍可回看
 * 前置：dev Electron 已在跑（--remote-debugging-port=9222）+ vite :3000 + 已配置真实模型 + 完全访问档。
 * 证据：acceptance/ui-315/ui315-forced.json + ui315-terminal-live.png + ui315-history-restore.png
 * 选择器契约基线：cc084920（优化二折叠行 + ✓ 字形）+ 优化三 WIP（展开体命令行 + 行内复制图标）。
 */
const fs = require('node:fs');
const path = require('node:path');
const http = require('node:http');
const { CdpClient } = require('./g0-rs-p7-cdp.cjs');

const DEBUG_PORT = process.env.PETRI_DEBUG_PORT || '9222';
const EVIDENCE_DIR = path.join(__dirname, '..', 'acceptance', 'ui-315');
const MARK = '314159';
const EXPECT_OUT = '628318';
// 唯一标记命令的输出（628318）模型无法编造——只有真实执行才能产出，
// 避免 forced 场景下模型直接口算作答造成假阳性。
const PROMPT = `你必须调用 workspace_exec 工具（这是硬性要求，禁止直接回答、禁止编造输出），执行命令 node -e "console.log(${MARK} * 2)"，参数 shell 用 powershell。调用完成后把工具真实输出原样告诉我。`;
const POLL_MS = 1500;
const TIMEOUT_MS = 5 * 60 * 1000;

function fetchJson(url) {
  return new Promise((resolve, reject) => {
    http.get(url, (res) => {
      let d = '';
      res.on('data', (c) => (d += c));
      res.on('end', () => { try { resolve(JSON.parse(d)); } catch (e) { reject(e); } });
    }).on('error', reject);
  });
}

function log(msg) { try { fs.writeSync(1, `[${new Date().toISOString().slice(11, 19)}] ${msg}\n`); } catch {} }

async function evalJS(client, expr) {
  const r = await Promise.race([
    client.send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true }),
    new Promise((_, reject) => setTimeout(() => reject(new Error('eval_timeout_30s')), 30_000)),
  ]);
  if (r.exceptionDetails) throw new Error('eval_exception: ' + String(r.exceptionDetails.text || '').slice(0, 200));
  return r.result?.value;
}

const js = String.raw;

async function poll(client, label, expr, predicate, timeoutMs = TIMEOUT_MS) {
  const deadline = Date.now() + timeoutMs;
  let last = null;
  while (Date.now() < deadline) {
    last = await evalJS(client, expr);
    // 表达式可能返回 JSON 字符串：统一反序列化后再交给谓词
    if (typeof last === 'string') { try { last = JSON.parse(last); } catch {} }
    if (predicate(last)) return last;
    await new Promise((r) => setTimeout(r, POLL_MS));
  }
  throw new Error(`poll_timeout: ${label} :: ${JSON.stringify(last).slice(0, 300)}`);
}

async function screenshot(client, file) {
  const shot = await client.send('Page.captureScreenshot', { format: 'png' });
  fs.writeFileSync(path.join(EVIDENCE_DIR, file), Buffer.from(shot.data, 'base64'));
}

async function main() {
  fs.mkdirSync(EVIDENCE_DIR, { recursive: true });
  const results = { startedAt: new Date().toISOString(), assertions: [], selectorContract: 'cc084920 + wip-inline-copy' };
  const assert = (name, pass, detail = '') => {
    results.assertions.push({ name, pass: !!pass, detail: String(detail).slice(0, 300) });
    log(`${pass ? 'PASS' : 'FAIL'} ${name}${detail ? ' :: ' + String(detail).slice(0, 140) : ''}`);
  };

  const targets = await fetchJson(`http://127.0.0.1:${DEBUG_PORT}/json`);
  const pages = targets.filter((t) => t.type === 'page' && /localhost:3000\/project\//.test(t.url));
  if (!pages.length) throw new Error('no_project_page_target');
  // 多窗口并存时挑可见的那扇（后台窗口可能没有左栏项目树）
  let main = null;
  let fallback = null;
  for (const p of pages) {
    const c0 = await new CdpClient(p.webSocketDebuggerUrl).connect();
    const probe = await evalJS(c0, 'document.visibilityState + "|" + !!document.querySelector("textarea.sc-input")').catch(() => 'err|false');
    if (probe.startsWith('visible|true')) { main = p; c0.socket.close(); break; }
    if (!fallback && probe.endsWith('true')) fallback = p;
    c0.socket.close();
  }
  main = main || fallback || pages[0];
  const client = await new CdpClient(main.webSocketDebuggerUrl).connect();

  // ── baseline（dev 重启后可能落在 home 无 composer：导航到项目工作区兜底）──
  // 新建会话再跑 forced：干净历史下验收，同时排除长会话历史对模型行为的污染
  const base = await (async () => {
    const deadline = Date.now() + 90_000;
    for (;;) {
      const s = JSON.parse(await evalJS(client, `JSON.stringify({
        terms: document.querySelectorAll('.sc-tool-term').length,
        composer: !!document.querySelector('textarea.sc-input'),
        sendBtn: !!document.querySelector('.sc-send-cta'),
        newConvBtn: !!document.querySelector('button[title="创建新对话"]'),
      })`).catch(() => ({ composer: false })));
      if (s.composer && s.sendBtn) return s;
      if (Date.now() > deadline) throw new Error('composer_not_found_after_wait');
      await client.send('Page.navigate', { url: 'http://localhost:3000/project/p_mtkamsfu_3mxo' }).catch(() => {});
      await new Promise((r) => setTimeout(r, 5000));
    }
  })();
  // ── 新建会话：先 reload 复位面板状态，再重试点击「创建新对话」直至空会话出现 ──
  await client.send('Page.reload');
  await new Promise((r) => setTimeout(r, 6000));
  await evalJS(client, `(() => {
    const btn = document.querySelector('button[title="创建新对话"]');
    if (btn && !btn.disabled) btn.click();
  })()`).catch(() => {});
  const freshDeadline = Date.now() + 90_000;
  let freshTerms = -1;
  for (;;) {
    if (Date.now() > freshDeadline) {
      throw new Error(`fresh_conversation_timeout :: terms=${freshTerms}`);
    }
    freshTerms = await evalJS(client, `document.querySelectorAll('.sc-tool-term').length`).catch(() => -1);
    if (freshTerms === 0) break;
    // 尚未切到空会话：重查按钮并重试点击（面板可能尚未渲染/按钮 disabled）
    await evalJS(client, `(() => {
      const btn = document.querySelector('button[title="创建新对话"]');
      if (btn && !btn.disabled) btn.click();
    })()`).catch(() => {});
    await new Promise((r) => setTimeout(r, 2500));
  }
  base.terms = freshTerms;
  assert('A0 composer 在位（textarea + send 按钮）', base.composer && base.sendBtn, JSON.stringify(base));
  log('fresh conversation terms=' + freshTerms);

  // ── 发送 forced 提示 ──
  await evalJS(client, `(() => {
    const ta = document.querySelector('textarea.sc-input');
