  const bodyState = JSON.parse(await evalJS(client, `(() => {
    const rows = [...document.querySelectorAll('.sc-tool-term')];
    const row = rows.filter((r) => (r.querySelector('.sc-tool-term-cmd-preview')?.textContent || '').includes('${MARK}')).pop();
