      let d = '';
      res.on('data', (c) => (d += c));
      res.on('end', () => { try { resolve(JSON.parse(d)); } catch (e) { reject(e); } });
    }).on('error', reject);
  });
}

function log(msg) { try { fs.writeSync(1, `[${new Date().toISOString().slice(11, 19)}] ${msg}\n`); } catch {} }

async function evalJS(client, expr) {
  const r = await Promise.race([
    client.send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true }),
    new Promise((_, reject) => setTimeout(() => reject(new Error('eval_timeout_30s')), 30_000)),
  ]);
  if (r.exceptionDetails) throw new Error('eval_exception: ' + String(r.exceptionDetails.exception?.description || r.exceptionDetails.text || '').slice(0, 300));
  return r.result?.value;
}

async function screenshot(client, file) {
  const shot = await client.send('Page.captureScreenshot', { format: 'png' });
  fs.writeFileSync(path.join(EVIDENCE_DIR, file), Buffer.from(shot.data, 'base64'));
}

function fileOnDisk() {
  try { return fs.readFileSync(path.join(WORKSPACE, SCRATCH), 'utf8'); } catch { return null; }
}

async function main() {
  fs.mkdirSync(EVIDENCE_DIR, { recursive: true });
  const results = { startedAt: new Date().toISOString(), assertions: [] };
  const assert = (name, pass, detail = '') => {
    results.assertions.push({ name, pass: !!pass, detail: String(detail).slice(0, 400) });
    log(`${pass ? 'PASS' : 'FAIL'} ${name}${detail ? ' :: ' + String(detail).slice(0, 140) : ''}`);
  };

  // 与并行会话共享同一窗口：整轮验收自愈重试（每轮重建现场：URL/右栏/tab/暂存文件）
  for (let attempt = 1; attempt <= 3; attempt++) {
    log(`attempt ${attempt}`);
    try {
      const ok = await runOnce(results, assert);
      if (ok) break;
    } catch (e) {
      log(`attempt ${attempt} error: ${e.message}`);
    }
    results.assertions.length = 0;
    await new Promise((r) => setTimeout(r, 8000));
  }

  results.allPass = results.assertions.length > 0 && results.assertions.every((a) => a.pass);
  results.finishedAt = new Date().toISOString();
  fs.writeFileSync(path.join(EVIDENCE_DIR, 'ui323-live.json'), JSON.stringify(results, null, 2) + '\n');
  log(`allPass=${results.allPass}`);
  process.exit(results.allPass ? 0 : 1);
}

async function runOnce(results, assert) {
  {

  // 前置：暂存文件（可复跑）
  fs.writeFileSync(path.join(WORKSPACE, SCRATCH), '# ui323 autosave check\n\nbaseline line\n', 'utf8');

  const targets = await fetchJson(`http://127.0.0.1:${DEBUG_PORT}/json`);
  const pages = targets.filter((t) => t.type === 'page' && /localhost:3000\/project\//.test(t.url));
  if (!pages.length) throw new Error('no_project_page_target');
  let main = null;
  for (const p of pages) {
    const c0 = await new CdpClient(p.webSocketDebuggerUrl).connect();
    const probe = await evalJS(c0, `JSON.stringify({ tree: document.querySelectorAll('[class*="projectTree"]').length, right: !!document.querySelector('[class*="rightCol"]') })`).catch(() => null);
    c0.socket.close();
    if (probe && JSON.parse(probe).tree > 0 && JSON.parse(probe).right) { main = p; break; }
  }
  main = main || pages[0];
  const client = await new CdpClient(main.webSocketDebuggerUrl).connect();
  const originalUrl = main.url;
  if (!originalUrl.startsWith(TARGET)) {
    await evalJS(client, `location.href = ${JSON.stringify(TARGET)}; 'nav'`);
    await new Promise((r) => setTimeout(r, 5000));
  }

  // 每轮无条件整页 reload（并行会话 HMR 竞态下，半应用状态必须整页刷新）
  await client.send('Page.reload');
  let interactive = false;
  for (let i = 0; i < 30 && !interactive; i++) {
    interactive = await evalJS(client, `!!document.querySelector('textarea.sc-input')`).catch(() => false);
    if (!interactive) await new Promise((r) => setTimeout(r, 1000));
  }
  if (!interactive) throw new Error('app_not_interactive');

  // 确保右栏停在「文件」tab（rail 直点；否则经飞出菜单）
  await evalJS(client, `(async () => {
    const expandRight = [...document.querySelectorAll('button')].find((b) => (b.title || '').includes('展开右侧栏'));
    if (expandRight) { expandRight.click(); await new Promise((r) => setTimeout(r, 800)); }
    let tab = [...document.querySelectorAll('button')].find((b) => b.textContent.trim() === '文件');
    if (!tab) {
      const more = [...document.querySelectorAll('button')].find((b) => (b.title || '').includes('展开更多工具'));
      if (more) { more.click(); await new Promise((r) => setTimeout(r, 500)); }
      tab = [...document.querySelectorAll('button, [role="menuitem"]')].find((e) => e.textContent.trim() === '文件');
    }
    if (tab) { tab.click(); await new Promise((r) => setTimeout(r, 1000)); }
    return 'files-tab';
  })()`);

  // 打开暂存文件：点文件树中的条目（树 2s 轮询会自动出现）
  let opened = false;
  for (let i = 0; i < 10 && !opened; i++) {
    opened = await evalJS(client, `(async () => {
      const node = [...document.querySelectorAll('[role="tree"] button')]
        .find((b) => (b.title || '').includes(${JSON.stringify(SCRATCH)}) || b.textContent.includes(${JSON.stringify(SCRATCH)}));
      if (node) { node.click(); await new Promise((r) => setTimeout(r, 1200)); return true; }
      return false;
    })()`);
    if (!opened) await new Promise((r) => setTimeout(r, 1500));
  }
  if (!opened) throw new Error('scratch_file_not_found_in_tree');
  log('scratch file opened in preview');

  // Markdown → 等右上角悬浮切换钮出现（预览态 aria-label=编辑）并进入编辑器
  let editReady = false;
  for (let i = 0; i < 10 && !editReady; i++) {
    editReady = await evalJS(client, `!!document.querySelector('[data-testid="md-view-toggle"][aria-label="编辑"]')`);
    if (!editReady) await new Promise((r) => setTimeout(r, 600));
  }
  if (!editReady) {
    const diag = await evalJS(client, `JSON.stringify({
      url: location.href.slice(0, 80),
      breadcrumb: (document.querySelector('[class*="workspaceBreadcrumb"]')?.textContent || '').slice(0, 120),
      bodyHead: (document.querySelector('[class*="workspacePreviewBody"]')?.innerHTML || 'NO_BODY').slice(0, 400),
      treeText: (document.querySelector('[role="tree"]')?.textContent || '').slice(0, 120),
    })`).catch((e) => 'diag_err ' + e.message);
    log('DIAG ' + diag);
  }
  const toolbarGone = await evalJS(client, `!document.querySelector('[class*="workspaceMarkdownDiffToolbar"]')`).catch(() => false);
  assert('C1a md 悬浮切换钮出现（aria-label=编辑）且工具条行不存在', editReady && toolbarGone);
  await evalJS(client, `(async () => {
    const toggle = document.querySelector('[data-testid="md-view-toggle"]');
    if (toggle) { toggle.click(); await new Promise((r) => setTimeout(r, 800)); }
    return 'edit';
  })()`);

  // 聚焦 CodeMirror：等 .cm-content 挂载（JS focus + execCommand 插入，block67-p1-live 同款已验证配方）
  let cmReady = false;
  for (let i = 0; i < 10 && !cmReady; i++) {
    cmReady = await evalJS(client, `!!document.querySelector('.cm-content[contenteditable="true"]')`);
    if (!cmReady) await new Promise((r) => setTimeout(r, 600));
  }
  if (!cmReady) throw new Error('codemirror_not_mounted');

  // 插入标记文本（CDP Input.insertText 在本场景不达 editor，改 execCommand 走 beforeinput 链）
  const inserted = await evalJS(client, `(async () => {
    const cm = document.querySelector('.cm-content[contenteditable="true"]');
    cm.focus();
    await new Promise((r) => setTimeout(r, 200));
    const ok = document.execCommand('insertText', false, ' autosave-marker-alpha ');
    await new Promise((r) => setTimeout(r, 300));
    return JSON.stringify({ ok, head: cm.textContent.slice(0, 100) });
  })()`);
  log('insert alpha: ' + inserted);

  // ── C1：头部按钮行已移除（工具条行 + 引用/保存/恢复 + 切换钮呈眼睛/预览态）──
  const header = JSON.parse(await evalJS(client, `JSON.stringify({
    quoteBtns: [...document.querySelectorAll('button')].filter((b) => b.textContent.trim() === '引用到对话').length,
    saveBtn: [...document.querySelectorAll('button')].some((b) => b.textContent.trim() === '保存'),
    restoreBtn: [...document.querySelectorAll('button')].some((b) => b.textContent.trim() === '恢复'),
    toolbarRow: !!document.querySelector('[class*="workspaceMarkdownDiffToolbar"]'),
    toggleNowPreview: document.querySelector('[data-testid="md-view-toggle"]')?.getAttribute('aria-label') === '预览',
  })`));
  assert('C1 头部零按钮行零工具条（编辑态悬浮钮=眼睛/预览）',
    header.quoteBtns === 0 && !header.saveBtn && !header.restoreBtn && !header.toolbarRow && header.toggleNowPreview,
    JSON.stringify(header));

  // ── C2：自动保存（停顿 ~1.2s 后落盘；等 2.5s 取证）──
  await new Promise((r) => setTimeout(r, 2500));
  const afterAuto = fileOnDisk();
  assert('C2 自动保存：编辑停顿后内容落盘（含 marker alpha）', afterAuto !== null && afterAuto.includes('autosave-marker-alpha'),
    `disk=${JSON.stringify((afterAuto || '').slice(-80))}`);

  // ── C3：Ctrl+S 立即保存（0.4s 内取证，早于 1.2s 防抖）──
  await evalJS(client, `(async () => {
    const cm = document.querySelector('.cm-content[contenteditable="true"]');
    if (!cm) return 'no_cm';
    cm.focus();
    await new Promise((r) => setTimeout(r, 150));
    document.execCommand('insertText', false, ' ctrl-s-marker-beta ');
    await new Promise((r) => setTimeout(r, 200));
    return 'inserted';
  })()`);
  await new Promise((r) => setTimeout(r, 200));
  await evalJS(client, `(async () => {
    const body = document.querySelector('[class*="workspacePreviewBody"]');
    if (!body) return 'no_body';
    body.dispatchEvent(new KeyboardEvent('keydown', { key: 's', ctrlKey: true, bubbles: true, cancelable: true }));
    await new Promise((r) => setTimeout(r, 600));
    return 'saved';
  })()`);
  const afterCtrlS = fileOnDisk();
  assert('C3 Ctrl+S 立即保存（含 marker beta）', afterCtrlS !== null && afterCtrlS.includes('ctrl-s-marker-beta'),
    `disk=${JSON.stringify((afterCtrlS || '').slice(-80))}`);
  await screenshot(client, 'ui323-autosave.png');

  // ── C4：眼睛回预览（编辑器卸载 + 切换钮回铅笔）──
  await evalJS(client, `(async () => {
    const t = document.querySelector('[data-testid="md-view-toggle"]');
    if (t) { t.click(); await new Promise((r) => setTimeout(r, 600)); }
    return 'toggled';
  })()`);
  const backToPreview = JSON.parse(await evalJS(client, `JSON.stringify({
    cmGone: !document.querySelector('.cm-content'),
    toggleEdit: document.querySelector('[data-testid="md-view-toggle"]')?.getAttribute('aria-label') === '编辑',
  })`));
  assert('C4 眼睛回预览：编辑器卸载 + 切换钮回铅笔', backToPreview.cmGone && backToPreview.toggleEdit, JSON.stringify(backToPreview));

  // ── 清理：删暂存文件 + 恢复原页面 ──
  try { fs.rmSync(path.join(WORKSPACE, SCRATCH), { force: true }); } catch {}
  if (originalUrl && !originalUrl.startsWith(TARGET)) {
    await evalJS(client, `location.href = ${JSON.stringify(originalUrl)}; 'nav'`).catch(() => {});
    await new Promise((r) => setTimeout(r, 2000));
  }

  client.socket.close();
  return results.assertions.length === 5 && results.assertions.every((a) => a.pass);
  }
}

main().catch((e) => { console.error('LIVE_ERR', e.message); process.exit(1); });

#!/usr/bin/env node
'use strict';

/**
 * UI-330 / BLOCK-78 P3 实机 UI 视角验收（dev Electron + CDP）。
 *   S1 ssh(dell) 项目：卡片「项目运行摘要」渲染 + 「远程执行 · dell」 +
 *      「资源 · dell」节点真值 + 本机 R/Py 芯片不出现 + 指挥席本机兜底不出现
 *   S2 expanded「项目」节存在与否诚实记录（宽窗 expanded 断言数据集/会话行）
 *   S3 local 项目对照：后端运行状态芯片在、无「远程执行」、无「资源 · dell」
 *   S4 折叠：点击「收起摘要概览」→ 卡片消失
 * 前置：dev 栈（--remote-debugging-port=9222）载入 BLOCK-78 全部代码；
 *       至少一个 dell ssh 项目（REST 创建）与一个 local 项目。
 * 证据：acceptance/block-78/ui330-live.json + ui330-*.png
 */

const fs = require('node:fs');
const path = require('node:path');
const http = require('node:http');
const { CdpClient } = require('./g0-rs-p7-cdp.cjs');

const DEBUG_PORT = process.env.PETRI_DEBUG_PORT || '9222';
const EVIDENCE_DIR = path.join(__dirname, '..', 'acceptance', 'block-78');
const API = 'http://127.0.0.1:3001/api';
const AUTH = { Authorization: 'Bearer desktop-local', 'content-type': 'application/json' };

function fetchJson(url, opts = {}) {
  return new Promise((resolve, reject) => {
    const req = http.request(url, { method: opts.method || 'GET', headers: opts.headers || {} }, (res) => {
      let d = '';
      res.on('data', (c) => (d += c));
      res.on('end', () => { try { resolve(JSON.parse(d)); } catch (e) { reject(e); } });
    });
    req.on('error', reject);
    if (opts.body) req.write(opts.body);
    req.end();
  });
}

function log(msg) { try { fs.writeSync(1, `[${new Date().toISOString().slice(11, 19)}] ${msg}\n`); } catch {} }

async function evalJS(client, expr) {
  const r = await Promise.race([
    client.send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true }),
    new Promise((_, reject) => setTimeout(() => reject(new Error('eval_timeout_30s')), 30_000)),
  ]);
  if (r.exceptionDetails) throw new Error('eval_exception: ' + String(r.exceptionDetails.exception?.description || r.exceptionDetails.text || '').slice(0, 300));
  return r.result?.value;
}

async function screenshot(client, file) {
  const shot = await client.send('Page.captureScreenshot', { format: 'png' });
  fs.writeFileSync(path.join(EVIDENCE_DIR, file), Buffer.from(shot.data, 'base64'));
}

async function main() {
  fs.mkdirSync(EVIDENCE_DIR, { recursive: true });
  const results = { startedAt: new Date().toISOString(), assertions: [] };
  const assert = (name, pass, detail = '') => {
    results.assertions.push({ name, pass: !!pass, detail: String(detail).slice(0, 400) });
    log(`${pass ? 'PASS' : 'FAIL'} ${name}${detail ? ' :: ' + String(detail).slice(0, 140) : ''}`);
  };
  const delay = (ms) => new Promise((r) => setTimeout(r, ms));

  // ── 准备项目：dell ssh（新建）+ local（列表里找） ──
  const created = await fetchJson(`${API}/data/projects`, {
    method: 'POST', headers: AUTH,
    body: JSON.stringify({ name: `B78UI验收-${Date.now()}`, workspaceKind: 'ssh', sshHost: 'dell', remotePath: '/root/petri-block78-demo' }),
  });
  const sshProjectId = created.project && created.project.id;
  assert('P0 dell ssh project created', !!sshProjectId, JSON.stringify(created).slice(0, 120));

  const projects = await fetchJson(`${API}/data/projects`);
  const all = projects.projects || projects || [];
  const localProject = (Array.isArray(all) ? all : []).find((p) => (p.workspace_kind || p.workspaceKind || 'local') !== 'ssh');
  assert('P0 local project available', !!localProject, localProject && localProject.id);

  const targets = await fetchJson(`http://127.0.0.1:${DEBUG_PORT}/json`);
  const pages = targets.filter((t) => t.type === 'page' && /localhost:3000/.test(t.url));
  if (!pages.length) throw new Error('no_page_target');
  let main = null;
  for (const p of pages) {
    const c0 = await new CdpClient(p.webSocketDebuggerUrl).connect();
    const probe = await evalJS(c0, `JSON.stringify({
      tree: document.querySelectorAll('[class*="projectTree"]').length
    })`).catch(() => null);
    c0.socket.close();
    if (probe && JSON.parse(probe).tree > 0) { main = p; break; }
  }
  main = main || pages[0];
  const client = await new CdpClient(main.webSocketDebuggerUrl).connect();

  async function openProjectAndCard(projectId) {
    await evalJS(client, `location.href = 'http://localhost:3000/project/${projectId}'`);
    for (let i = 0; i < 20; i++) {
      await delay(1000);
      const ready = await evalJS(client, `JSON.stringify({
        tree: document.querySelectorAll('[class*="projectTree"]').length > 0,
        url: location.pathname
      })`).catch(() => null);
      if (ready && JSON.parse(ready).tree && String(JSON.parse(ready).url).includes(projectId)) break;
    }
    // 展开摘要概览（默认收起）
    await evalJS(client, `(() => { const b = document.querySelector('button[aria-label="展开摘要概览"]'); if (b) b.click(); return !!b; })()`);
    for (let i = 0; i < 15; i++) {
      await delay(1000);
      const card = await evalJS(client, `!!document.querySelector('[aria-label="项目运行摘要"]')`).catch(() => false);
      if (card) break;
    }
    return evalJS(client, `JSON.stringify({
      card: !!document.querySelector('[aria-label="项目运行摘要"]'),
      remoteExec: document.body.textContent.includes('远程执行 · dell'),
      resourceRemote: document.body.textContent.includes('资源 · dell'),
      chips: !!document.querySelector('[aria-label="后端运行状态"]'),
      fallback: document.body.textContent.includes('指挥席本机'),
      pendingCost: document.body.textContent.includes('待接入'),
      projectInfoSection: !!document.querySelector('[aria-label="项目信息"]'),
      datasetRow: document.body.textContent.includes('数据集'),
      attention: !!document.querySelector('[aria-label="需要关注"]')
    })`);
  }

  // ── S1/S2 ssh 项目 ──
  const ssh = JSON.parse(await openProjectAndCard(sshProjectId));
  assert('S1 ssh: card renders', ssh.card, JSON.stringify(ssh).slice(0, 200));
  assert('S1 ssh: 远程执行 · dell', ssh.remoteExec);
  // 资源行等读数稳定：首击含 ensureAgent 部署（~2-3s），加载态显示兜底文案属正常过渡
  let resourceRemote = ssh.resourceRemote;
  let fallbackAfterSettle = ssh.fallback;
  for (let i = 0; i < 15 && !resourceRemote; i++) {
    await delay(1000);
    const s = JSON.parse(await evalJS(client, `JSON.stringify({
      remote: document.body.textContent.includes('资源 · dell'),
      fallback: document.body.textContent.includes('指挥席本机')
    })`).catch(() => '{}') || '{}');
    resourceRemote = !!s.remote;
    fallbackAfterSettle = !!s.fallback;
    if (s.remote) break;
  }
  assert('S1 ssh: 资源 · dell (节点真值)', resourceRemote, '等待远程快照 fetch 完成（含首击 agent 部署）');
  assert('S1 ssh: 本机 R/Py 芯片不出现', !ssh.chips);
  assert('S1 ssh: 指挥席本机兜底不出现（真值已接）', !fallbackAfterSettle);
  assert('S2 expanded: 项目信息节 + 数据集行', ssh.projectInfoSection && ssh.datasetRow,
      `projectInfo=${ssh.projectInfoSection}`);
  await screenshot(client, 'ui330-ssh-card.png');

  // ── S3 local 对照 ──
  if (localProject) {
    const loc = JSON.parse(await openProjectAndCard(localProject.id));
    assert('S3 local: card renders', loc.card);
    assert('S3 local: 本机 R/Py 芯片出现', loc.chips);
    assert('S3 local: 无 远程执行 · dell', !loc.remoteExec);
    assert('S3 local: 无 资源 · dell', !loc.resourceRemote);
    await screenshot(client, 'ui330-local-card.png');
  }

  // ── S4 折叠：收起后卡片消失 ──
  await evalJS(client, `(() => { const b = document.querySelector('button[aria-label="收起摘要概览"]'); if (b) b.click(); return !!b; })()`);
  await delay(1200);
  const collapsed = await evalJS(client, `!document.querySelector('[aria-label="项目运行摘要"]')`);
  assert('S4 收起摘要概览 → 卡片消失', collapsed);

  results.allPass = results.assertions.every((a) => a.pass);
  results.finishedAt = new Date().toISOString();
  fs.writeFileSync(path.join(EVIDENCE_DIR, 'ui330-live.json'), JSON.stringify(results, null, 2));
  log(`allPass=${results.allPass}`);
}

main().catch((e) => { console.error(e); process.exit(1); });

#!/usr/bin/env node
'use strict';
/* probe-p2-thinking.cjs — BLOCK-81 P2 实机验证：
   1) 开启渠道 reasoning 能力位（REST 写 model_profiles）
   2) 工作区 composer 档位控件出现（能力位门控生效）
   3) 选「高」→ 发送 → 任务参数携带 thinkingLevel=high（后端已收）
   4) 收尾：能力位复原（不留测试残留）
*/
const path = require('node:path');
const http = require('node:http');
const ROOT = path.join(__dirname, '..');
const lib = require(path.join(ROOT, '.agents', 'skills', 'petri-dev-infra', 'dev-verify', 'lib.cjs'));
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const API = 'http://127.0.0.1:3001/api';
const AUTH = { Authorization: 'Bearer desktop-local' };

function req(method, p, body) {
  return new Promise((resolve, reject) => {
    const data = body ? JSON.stringify(body) : null;
    const r = http.request({ host: '127.0.0.1', port: 3001, path: p, method, headers: {
      ...AUTH, ...(data ? { 'content-type': 'application/json', 'content-length': Buffer.byteLength(data) } : {}),
    } }, (res) => {
      let d = ''; res.on('data', (c) => { d += c; }); res.on('end', () => {
        try { resolve({ status: res.statusCode, json: JSON.parse(d || '{}') }); } catch { resolve({ status: res.statusCode, json: null, raw: d.slice(0, 200) }); }
      });
    });
    r.on('error', reject);
    if (data) r.write(data);
    r.end();
  });
}

(async () => {
  const raw = (await req('GET', '/api/ai/settings')).json || {};
  const settings = raw.settings || {};
  const profiles = settings.model_profiles || [];
  const target = profiles.find((p) => p.provider === 'deepseek') || profiles[0];
  if (!target) { console.log('NO_PROFILE'); process.exit(1); }
  console.log('target profile:', target.id, '| caps:', JSON.stringify(target.capabilities || []));

  // 1) 开启 reasoning 能力位
  const patched = profiles.map((p) => (p.id === target.id
    ? { ...p, capabilities: Array.from(new Set([...(p.capabilities || ['chat', 'streaming', 'tools']), 'reasoning'])) }
    : p));
  const w = await req('POST', '/api/ai/settings', { model_profiles: patched });
  console.log('capability enabled:', w.status, w.json && w.json.status);

  const targets = await lib.pollTargets({ timeoutMs: 20000 });
  const pages = lib.filterPageTargets(targets, /^http:\/\/localhost:3000\//);
  const client = await lib.connectTarget(pages[0]);
  const pid = JSON.parse(await lib.evalJs(client, `(async () => {
    const r = await fetch('http://127.0.0.1:3001/api/data/projects', { headers: { Authorization: 'Bearer desktop-local' } });
    const d = await r.json();
    return JSON.stringify((d.projects || [])[0] ? d.projects[0].id : '');
  })()`));

  // 2) 进工作区，等 composer 与档位控件
  await lib.evalJs(client, `location.href = 'http://localhost:3000/project/${pid}'; 'nav'`);
  await sleep(4000);
  await lib.pollTargets({ timeoutMs: 15000 });
  const t2 = await lib.pollTargets({ timeoutMs: 15000 });
  const c2 = await lib.connectTarget(lib.filterPageTargets(t2, /^http:\/\/localhost:3000\//)[0]);

  let trigger = null;
  for (let i = 0; i < 12; i += 1) {
    trigger = await lib.evalJs(c2, `(function(){
      var el = document.querySelector('[data-testid="thinking-level-trigger"]');
      return el ? JSON.stringify({ level: el.getAttribute('data-level'), label: (el.textContent||'').trim() }) : null;
    })()`).catch(() => null);
    if (trigger) break;
    await sleep(1000);
  }
  console.log('thinking trigger:', trigger);

  if (!trigger) {
    console.log('CONTROL_ABSENT — 能力位门控未生效或页面未就绪');
  } else {
    // 3) 打开菜单选「高」
    await lib.evalJs(c2, `(function(){
      var el = document.querySelector('[data-testid="thinking-level-trigger"]');
      if (el) el.click();
      return 'opened';
    })()`);
    await sleep(600);
    const picked = await lib.evalJs(c2, `(function(){
      var opt = document.querySelector('[data-testid="thinking-level-option-high"]');
      if (!opt) return 'option_missing';
      opt.click();
      return 'clicked';
    })()`);
    await sleep(600);
    const after = await lib.evalJs(c2, `(function(){
      var el = document.querySelector('[data-testid="thinking-level-trigger"]');
      return el ? el.getAttribute('data-level') : null;
    })()`);
    console.log('pick:', picked, '| level now:', after);

    // 4) 发送一条消息（探针：零工具直答）
    const typed = await lib.evalJs(c2, `(function(){
      var ta = document.querySelector('textarea.sc-input');
      if (!ta) return 'no_textarea';
      var setter = Object.getOwnPropertyDescriptor(window.HTMLTextAreaElement.prototype, 'value').set;
      setter.call(ta, 'P2 档位探针：不要使用任何工具，直接回复「收到」。');
      ta.dispatchEvent(new Event('input', { bubbles: true }));
      return 'typed:' + ta.value.length;
    })()`).catch((e) => 'err:' + e.message.slice(0, 60));
    console.log('typed:', typed);
    await sleep(800);
    const sent = await lib.evalJs(c2, `(function(){
      var b = [].slice.call(document.querySelectorAll('button')).find(function (x) {
        return (x.getAttribute('aria-label') || x.title || '').indexOf('发送消息') >= 0;
      });
      if (!b || b.disabled) return 'send_unavailable';
      b.click();
      return 'sent';
    })()`).catch((e) => 'err:' + e.message.slice(0, 60));
    console.log('send:', sent);
    await sleep(6000);

    // 5) 查任务参数（后端已收档位）
    const tasks = await req('GET', '/api/ai/agent/tasks?limit=5');
    const list = (tasks.json && (tasks.json.tasks || tasks.json.items)) || [];
    const latest = list[0];
    console.log('latest task params.thinkingLevel =', latest && latest.params ? latest.params.thinkingLevel : '(none)');
  }

  // 6) 复原能力位
  const restore = await req('POST', '/api/ai/settings', { model_profiles: profiles });
  console.log('capability restored:', restore.status);
  try { c2.socket.close(); } catch { /* ignore */ }
  try { client.socket.close(); } catch { /* ignore */ }
  process.exit(0);
})().catch((e) => { console.error('ERR', e.message); process.exit(1); });

#!/usr/bin/env node
'use strict';
/**
 * ui349-back-unify-live.cjs — UI-349 实机验收：后端/知识空间/Skills/插件四页返回按钮统一。
 *
 * 用户裁决：四个页面的返回按钮「形式文字 保持统一」。
 * 统一后形态 = 左箭头 + 「返回」文字、30px 高、1px 边框、8px 圆角。
 *
 * 断言：四页返回按钮 text=返回、aria=返回，几何一致（高≈30、圆角≈8）。
 */

const path = require('node:path');
const lib = require(path.join(__dirname, '..', '.agents', 'skills', 'petri-dev-infra', 'dev-verify', 'lib.cjs'));
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function attach() {
  const targets = await lib.pollTargets({ timeoutMs: 20000 });
  const candidates = lib.filterPageTargets(targets, /^http:\/\/localhost:3000\/(?!window\/)/);
  const target = await lib.selectPageTarget(candidates, {
    probe: async (client) => lib.evalJs(client, `!!document.getElementById('root')`).catch(() => false),
  });
  if (!target) throw new Error('no_page_target');
  return lib.connectTarget(target);
}

async function goto(client, url) {
  await lib.evalJs(client, `location.href = ${JSON.stringify(url)}; 'nav'`);
  await sleep(3500);
  return attach();
}

const MEASURE = `(function(){
  function read(btn) {
    if (!btn) return null;
    var cs = getComputedStyle(btn);
    var r = btn.getBoundingClientRect();
    return { text: btn.textContent.trim(), aria: btn.getAttribute('aria-label'), h: Math.round(r.height), radius: cs.borderRadius };
  }
  return JSON.stringify(read(document.querySelector('button[aria-label="返回"]')));
})()`;

(async () => {
  const run = lib.createRun({ name: 'ui349-back-unify', evidenceDir: path.join(__dirname, '..', 'acceptance', 'ui-349') });
  const http = require('node:http');
  const projects = await new Promise((resolve) => {
    http.get({ host: '127.0.0.1', port: 3001, path: '/api/data/projects', headers: { Authorization: 'Bearer desktop-local' } }, (res) => {
      let d = '';
      res.on('data', (c) => { d += c; });
      res.on('end', () => resolve(JSON.parse(d)));
    });
  });
  const pid = projects.projects[0].id;

  const shapes = {};
  for (const route of ['backend', 'knowledge', 'skills']) {
    let client = await attach();
    client = await goto(client, `http://localhost:3000/${route}`);
    await sleep(1200);
    const s = JSON.parse(await lib.evalJs(client, MEASURE) || 'null');
    shapes[route] = s;
    run.assert(`F_${route}_back`, !!s && s.text === '返回' && s.aria === '返回' && Math.abs(s.h - 30) <= 1 && s.radius === '8px',
      `${route} 返回按钮=${JSON.stringify(s)}`);
  }

  // 插件页（工作区模式）
  let client = await attach();
  client = await goto(client, `http://localhost:3000/project/${pid}`);
  await sleep(2500);
  await lib.evalJs(client, `(function(){ var b = document.querySelector('button[title="插件"]'); if (b) b.click(); return 'c'; })()`);
  let shape = null;
  for (let i = 0; i < 25; i += 1) {
    shape = JSON.parse(await lib.evalJs(client, `(function(){
      var panel = document.querySelector('.petri-plugin-store-panel');
      if (!panel) return 'null';
      function read(btn) {
        if (!btn) return null;
        var cs = getComputedStyle(btn);
        var r = btn.getBoundingClientRect();
        return { text: btn.textContent.trim(), aria: btn.getAttribute('aria-label'), h: Math.round(r.height), radius: cs.borderRadius };
      }
      return JSON.stringify(read(panel.querySelector('button[aria-label="返回"]')));
    })()`).catch(() => 'null') || 'null');
    if (shape && shape !== 'null') break;
    await sleep(1000);
  }
  shapes.plugins = shape;
  run.assert(`F_plugins_back`, !!shape && shape.text === '返回' && shape.aria === '返回' && Math.abs(shape.h - 30) <= 1 && shape.radius === '8px',
    `插件页返回按钮=${JSON.stringify(shape)}`);

  const ref = shapes.backend;
  const allSame = ['knowledge', 'skills', 'plugins'].every((k) => {
    const s = shapes[k];
    return s && ref && s.text === ref.text && s.h === ref.h && s.radius === ref.radius;
  });
  run.assert('F_all_identical', allSame,
    `四页返回按钮形态文字一致（text/高度/圆角）：${JSON.stringify(shapes)}`);

  return await run.finish({ observations: { shapes } });
})().then((p) => process.exit(p && p.allPass ? 0 : 1)).catch((e) => {
  console.error('FATAL', e && e.message);
  process.exit(2);
});

