    await sleep(2000);

    // W1 PDF object 渲染
    const pdfProbe = await EVAL(
      `(function(){
        var obj = document.querySelector('object[type="application/pdf"]');
        if (!obj) return JSON.stringify({ present: false });
        var r = obj.getBoundingClientRect();
        return JSON.stringify({ present: true, w: Math.round(r.width), h: Math.round(r.height) });
      })()`);
    let w1 = {};
    try { w1 = JSON.parse(pdfProbe); } catch {}
    run.assert('W1_pdf_object_rendered', w1.present === true && (w1.w || 0) > 100 && (w1.h || 0) > 100, pdfProbe);

    // W2 下载按钮点击 → Downloads 出现新文件
    const btn = await EVAL(`(function(){ var b=document.querySelector('[data-testid="file-download"]'); if(!b) return 'no_btn'; b.click(); return 'clicked'; })()`);
    run.assert('W2_download_button_clicked', btn === 'clicked', String(btn));
    let added = [];
    for (let i = 0; i < 10; i++) {
      await sleep(2000);
      const after = fs.existsSync(dlDir) ? fs.readdirSync(dlDir) : [];
      added = after.filter((f) => !before.includes(f) && !f.endsWith('.crdownload'));
      if (added.length > 0) break;
    }
    run.assert('W2_download_landed', added.length > 0, 'added=' + JSON.stringify(added.slice(0, 3)) + ' dir=' + dlDir);

    await lib.screenshotPng(client, EVIDENCE_DIR, 'ui400-pdf-preview.png').catch(() => {});
  }

  run.finish();
  process.exit(run.allPass ? 0 : 1);
})().catch((err) => {
  console.error('[ui400] FATAL', err && err.message);
  process.exit(2);
});

#!/usr/bin/env node
'use strict';
/**
 * ui404-agent-panel-collapse-live.cjs — UI-404 实机验收：
 *   智能体详情面板「操作 / 实时工作流」终态默认收起、运行中默认展开、
 *   头部任务全文 + 父会话标注、时间线收起态计数摘要。
 * 前置：dev 栈（vite 3000 + 后端 3001 + CDP 9222）+ 至少一个项目。
 * 证据：acceptance/ui-403/../ui-404/ui404-agent-panel-collapse.png + stdout 断言。
 */
const path = require('node:path');
const http = require('node:http');
const lib = require(path.join(__dirname, '..', '.agents', 'skills', 'petri-dev-infra', 'dev-verify', 'lib.cjs'));
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const API = 'http://127.0.0.1:3001';
const AUTH = { Authorization: 'Bearer desktop-local' };
const EVIDENCE_DIR = path.join(__dirname, '..', 'acceptance', 'ui-404');

function apiJson(method, pathname, body) {
  return new Promise((resolve, reject) => {
    const req = http.request(API + pathname, { method, headers: { ...AUTH, 'Content-Type': 'application/json' } }, (res) => {
      let buf = '';
      res.on('data', (c) => { buf += c; });
      res.on('end', () => { try { resolve(JSON.parse(buf)); } catch (e) { resolve(null); } });
    });
    req.on('error', reject);
    if (body) req.write(JSON.stringify(body));
    req.end();
  });
}

(async () => {
  const run = lib.createRun({ name: 'ui404-agent-panel-collapse', evidenceDir: EVIDENCE_DIR });
  const proj = await apiJson('GET', '/api/data/projects');
  const projectId = (proj.projects && proj.projects[0] && proj.projects[0].id) || null;

  let targets = await lib.pollTargets({ timeoutMs: 20000 });
  let client = await lib.connectTarget(await lib.selectPageTarget(
    lib.filterPageTargets(targets, /^http:\/\/localhost:3000\/(?!window\/)/),
    { probe: async (c) => lib.evalJs(c, `!!document.getElementById('root')`).catch(() => false) },
  ));
  await lib.evalJs(client, `location.href = 'http://localhost:3000/project/${projectId}'; 'nav'`);
  await sleep(4500);
  targets = await lib.pollTargets({ timeoutMs: 10000 });
  client = await lib.connectTarget(await lib.selectPageTarget(
    lib.filterPageTargets(targets, /^http:\/\/localhost:3000\/project\//),
    { probe: async (c) => lib.evalJs(c, `!!document.getElementById('root')`).catch(() => false) },
  ));

  // composer 真发派生请求（UI 上下文完整，spawn 审批卡可在面板点击）
  const PROMPT = '请立即用 spawn_agent 工具派生一个子智能体，子任务：「报告 7 乘 6 的答案」。派生后直接回复完成。';
  let typed = '';
  for (let i = 0; i < 10 && typed !== 'typed'; i++) {
    typed = await lib.evalJs(client, `(function(){
      var ta = document.querySelector('textarea.sc-input');
      if (!ta) return 'no_textarea';
      var setter = Object.getOwnPropertyDescriptor(window.HTMLTextAreaElement.prototype, 'value').set;
      setter.call(ta, ${JSON.stringify(PROMPT)});
      ta.dispatchEvent(new Event('input', { bubbles: true }));
      return 'typed';
    })()`);
    if (typed !== 'typed') await sleep(1000);
  }
  run.assert('V1_composer_typed', typed === 'typed', String(typed));
  const sent = await lib.evalJs(client, `(function(){
    var btns = document.querySelectorAll('button');
    for (var i = 0; i < btns.length; i++) {
      var t = btns[i].getAttribute('title') || '';
      if (t.indexOf('发送') >= 0 && btns[i].offsetParent) { btns[i].click(); return 'sent'; }
    }
    return 'no_send';
  })()`);
  run.assert('V2_composer_sent', sent === 'sent', String(sent));

  // 等子智能体 chip 出现在摘要卡（spawn 成功后 5s 轮询窗口内）
  let chipFound = false;
  for (let i = 0; i < 40 && !chipFound; i++) {
    await sleep(3000);
    chipFound = (await lib.evalJs(client, `document.querySelectorAll('section[aria-label="智能体"] button').length > 0`)) === true;
    // spawn 审批卡出现则点击批准（标题含「批准」或「允许」的按钮）
    await lib.evalJs(client, `(function(){
      var btns = document.querySelectorAll('button');
      for (var i = 0; i < btns.length; i++) {
        var t = (btns[i].textContent || '');
        if ((t.indexOf('批准') >= 0 || t.indexOf('允许') >= 0) && btns[i].offsetParent) { btns[i].click(); return 'approved'; }
      }
      return 'none';
    })()`);
  }
  run.assert('V3_subagent_chip_visible', chipFound, `chip=${chipFound}`);

  // 点击第一枚 chip → 右栏切到智能体详情
  await lib.evalJs(client, `(function(){
    var btns = document.querySelectorAll('section[aria-label="智能体"] button');
    if (btns.length) { btns[btns.length - 1].click(); return 'clicked'; }
    return 'none';
  })()`);
  await sleep(2500);

  // 断言：终态子任务 → 操作/时间线收起 + 时间线计数标题 + 父会话标注
  const actionsCollapsed = await lib.evalJs(client, `(function(){
    var btn = document.querySelector('[data-testid="agent-run-actions"] button[aria-expanded]');
    return btn ? String(btn.getAttribute('aria-expanded')) : 'no_toggle';
  })()`);
  run.assert('V4_terminal_actions_collapsed', actionsCollapsed === 'false', `aria-expanded=${actionsCollapsed}`);

  const timelineTitle = await lib.evalJs(client, `(function(){
    var el = document.querySelector('[data-testid="agent-timeline-title"]');
    return el ? el.textContent : 'missing';
  })()`);
  run.assert('V5_timeline_count_summary', /次调用/.test(timelineTitle), timelineTitle);

  const parent = await lib.evalJs(client, `(function(){
    var el = document.querySelector('[data-testid="agent-parent-conversation"]');
    return el ? el.textContent : 'missing';
  })()`);
  run.assert('V6_parent_conversation_line', parent.indexOf('父会话：') === 0, parent);

  await lib.screenshotPng(client, EVIDENCE_DIR, 'ui404-agent-panel-collapse.png');
  await run.finish({});
})().catch((e) => {
  console.error('fatal:', e);
  process.exit(1);
});

#!/usr/bin/env node
/**
 * upload-macos-runtime.mjs
 * ---------------------------------------------------------------
 * 把 macOS arm64 R/Python 运行时制品上传到阿里云 OSS，并校验与
 * resources/built-in-plugins/manifest.json 声明的 macos-arm64
 * sha256/sizeBytes 一致。目标路径与 manifest 同结构：
 *   oss://petri-uploads/plugins/r-runtime/1.0.0/macos-arm64.zip
 *   oss://petri-uploads/plugins/py-runtime/1.0.0/macos-arm64.zip
 *
 * 背景（2026-08-09 🔴）：manifest 已声明真实 sha256/sizeBytes，但 OSS 上
 * macos-arm64.zip 实际 HTTP 404 → macOS 新装用户 installRuntime 下载失败。
 * 本脚本只负责「上传 + 校验」，制品本体与 OSS 凭据需由构建/运维侧提供。
 *
 * 用法（在 macOS 构建机，有 OSS 凭据）：
 *   export OSS_AK=... OSS_SK=...   # 或放到仓库根 .petri-secrets
 *   node scripts/upload-macos-runtime.mjs --runtime r  --zip /path/r-runtime-1.0.0-macos-arm64.zip
 *   node scripts/upload-macos-runtime.mjs --runtime py --zip /path/py-runtime-1.0.0-macos-arm64.zip
 *   # --dry-run 仅预览 + hash 校验，不上传（无需 OSS 凭据）
 *
 * 安全边界：
 *   - 必须先用 --zip 指定本地制品；脚本计算其 sha256/sizeBytes 并比对 manifest
 *     声明的 macos-arm64 值；不一致（且 manifest 非 null）则 fail-closed，
 *     绝不传一个与声明不符的制品（否则 plugin-manager 校验会失败，且构成
 *     silent inconsistency）。
 *   - 上传后用 multipart + public-read ACL + HEAD 校验。
 */

import { createHash } from 'node:crypto';
import { existsSync, readFileSync, statSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = resolve(__dirname, '..');

function fail(msg) {
  console.error(`[oss-macos-runtime] ERROR: ${msg}`);
  process.exit(1);
}

// 自动加载 .petri-secrets（export KEY="val" 格式），供 OSS_AK/OSS_SK 使用。
// 该文件在 .gitignore 中，不会进仓库。若已手动 export 同名变量则优先保留。
function loadSecretsFile() {
  const p = resolve(REPO_ROOT, '.petri-secrets');
  if (!existsSync(p)) return;
  const content = readFileSync(p, 'utf8');
  const re = /^\s*export\s+([A-Z0-9_]+)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s#]+))/gm;
  let m;
  while ((m = re.exec(content)) !== null) {
    const key = m[1];
    if (process.env[key] === undefined) {
      process.env[key] = m[2] ?? m[3] ?? m[4] ?? '';
    }
  }
}
loadSecretsFile();

const bucket = process.env.PETRI_OSS_BUCKET || 'petri-uploads';
const endpoint = process.env.OSS_ENDPOINT || 'oss-cn-hangzhou.aliyuncs.com';
const region = process.env.OSS_REGION || 'cn-hangzhou';
const accessKeyId = process.env.OSS_AK || process.env.PETRI_OSS_ACCESS_KEY_ID || process.env.OSS_ACCESS_KEY_ID;
const accessKeySecret = process.env.OSS_SK || process.env.PETRI_OSS_ACCESS_KEY_SECRET || process.env.OSS_ACCESS_KEY_SECRET;

const dryRun = process.argv.includes('--dry-run');
const rtIdx = process.argv.indexOf('--runtime');
const runtime = (rtIdx >= 0 ? process.argv[rtIdx + 1] : 'r').toLowerCase();
const zipIdx = process.argv.indexOf('--zip');
const zipPath = zipIdx >= 0 ? resolve(process.argv[zipIdx + 1]) : null;

// manifest 插件键是 petri-r-runtime / petri-py-runtime；OSS 路径段是 r-runtime / py-runtime
const RUNTIME = {
  r:  { manifestKey: 'petri-r-runtime', ossSegment: 'r-runtime' },
  py: { manifestKey: 'petri-py-runtime', ossSegment: 'py-runtime' },
};
const rt = RUNTIME[runtime];
if (!rt) fail(`--runtime 必须是 r 或 py，收到: ${runtime}`);
const runtimeId = rt.manifestKey;
if (!zipPath || !existsSync(zipPath)) fail(`找不到制品: ${zipPath}（用 --zip 指定 macos-arm64.zip 路径）`);

const objectName = `plugins/${rt.ossSegment}/1.0.0/macos-arm64.zip`;

// 读取 manifest 声明的 macos-arm64 期望 hash/size（作为上传真相源）
const manifestPath = resolve(REPO_ROOT, 'resources/built-in-plugins/manifest.json');
if (!existsSync(manifestPath)) fail(`找不到 manifest: ${manifestPath}`);
const manifest = JSON.parse(readFileSync(manifestPath, 'utf8'));
const declared = manifest?.plugins?.[runtimeId]?.artifacts?.['macos-arm64'];
const expectedSha256 = declared?.sha256 ?? null;
const expectedSize = declared?.sizeBytes ?? null;

const stat = statSync(zipPath);
const sha256 = createHash('sha256').update(readFileSync(zipPath)).digest('hex');
const sizeBytes = stat.size;

const publicUrl = `https://${bucket}.${endpoint}/${objectName}`;

// hash 一致性校验（fail-closed，除非 dry-run 仅警告）
const hashMismatch = expectedSha256 && expectedSha256 !== sha256;
const sizeMismatch = expectedSize && expectedSize !== sizeBytes;
if (hashMismatch || sizeMismatch) {
  if (!dryRun) {
    fail(`制品与 manifest 声明不一致：sha256 ${expectedSha256} vs ${sha256}；size ${expectedSize} vs ${sizeBytes}。不要上传与声明不符的制品（若 manifest 值本身有误，先修正 manifest 再传）。`);
  }
  console.warn('[oss-macos-runtime] 警告(dry-run): 制品与 manifest 声明不一致，真实上传会被拒绝。');
}

console.log(`[oss-macos-runtime] runtime  : ${runtimeId}`);
console.log(`[oss-macos-runtime] artifact : ${zipPath}`);
console.log(`[oss-macos-runtime] sizeBytes: ${sizeBytes}`);
console.log(`[oss-macos-runtime] sha256   : ${sha256}`);
console.log(`[oss-macos-runtime] dest     : oss://${bucket}/${objectName}`);
console.log(`[oss-macos-runtime] public   : ${publicUrl}`);
console.log(`[oss-macos-runtime] manifest : sha256=${expectedSha256} size=${expectedSize}`);

if (dryRun) {
  console.log('[oss-macos-runtime] --dry-run: 未上传。');
  process.exit(0);
}

if (!accessKeyId || !accessKeySecret) {
  fail('缺少 OSS 凭据。请设置 OSS_AK / OSS_SK（脚本会自动读取 .petri-secrets）。');
}

const OSS = (await import('ali-oss')).default;
const client = new OSS({
  region,
  endpoint: endpoint.startsWith('http') ? endpoint : `https://${endpoint}`,
  bucket,
  accessKeyId,
  accessKeySecret,
  timeout: Number(process.env.PETRI_OSS_UPLOAD_TIMEOUT_MS || 600000),
});

async function main() {
  try {
    console.log('[oss-macos-runtime] uploading (multipart)...');
    await client.multipartUpload(objectName, zipPath, {
      partSize: Number(process.env.PETRI_OSS_UPLOAD_PART_SIZE || 10 * 1024 * 1024),
      parallel: 3,
      headers: { 'Content-Type': 'application/zip', 'Cache-Control': 'public, immutable, max-age=31536000' },
    });
    await client.putACL(objectName, 'public-read');
    const head = await client.head(objectName);
    if (!head || head.status !== 200) fail('上传后 HEAD 校验未通过');
    console.log(`[oss-macos-runtime] uploaded + public-read OK -> ${publicUrl}`);
    console.log('\n==================== UPLOAD COMPLETE ====================');
    console.log('制品已落地 OSS 且与 manifest 声明 hash 一致。可用下列命令验证 404 已消除：\n');
    console.log(`  curl -sI "${publicUrl}" | head -1`);
    console.log(JSON.stringify({ platform: 'macos-arm64', runtime: runtimeId, url: publicUrl, sha256, sizeBytes }, null, 2));
  } catch (err) {
    fail(`上传失败: ${err.message}`);
  }
}

main();

#!/usr/bin/env node
/**
 * upload-win-python-runtime.mjs
 * ---------------------------------------------------------------
 * 把 build-win-runtime-artifact.mjs 产出的 windows-x64 Python 运行时
 * 制品上传到阿里云 OSS，并打印真实 sha256 / sizeBytes。
 *
 * 产物：dist-runtime/py-runtime-1.0.0-windows-x64.zip
 * 目标：oss://<bucket>/plugins/py-runtime/1.0.0/windows-x64.zip
 *       公共 URL 与 manifest.json 中 macos-arm64 同一目录结构。
 *
 * ⚠️ 收尾边界（2026-08-08 确认，与 R 制品一致）：
 *   - 本脚本只负责「上传 + 打印真实摘要」，让制品真正落地 OSS。
 *   - petri-py-runtime 的占位此前已从 manifest.placeholders.json 移除
 *     （schema 测试要求 runtime 插件不得留在 placeholders，只判 pluginId）。
 *   - windows-x64 现已登记进 manifest.json 的 artifacts（real OSS 制品，已 golden-path
 *     验证，使未签名 Windows dev 构建能从商店安装运行时）；sha256/sizeBytes 暂为 null
 *     （plugin-manager 对 null 跳过校验）。测试护栏已改为「不允许假 Windows 支持」
 *     （无真实描述符的 windows-x64 才算假），不再强制 0 个。release-contract.windows-x64.supported
 *     维持 false，直到 Week 3/4 才翻转。
 *
