const zipArgIdx = process.argv.indexOf('--zip');
const zipPath = zipArgIdx >= 0 ? resolve(process.argv[zipArgIdx + 1]) : resolve(REPO_ROOT, 'dist-runtime', 'py-runtime-1.0.0-windows-x64.zip');

function fail(msg) {
