#!/usr/bin/env node
// ============================================================
// IPC Channel Catalog Validator Gate
//
// SUB-15.2 PHASE 2 — IPC catalog + plugin manifest schema
//
// Purpose:
//   1. Static-scan Electron IPC handlers (PHASE 1)
//   2. Validate plugin manifest schema against built-in plugins
//   3. Payload shape basic type checks (no ajv / zod — UR-4)
//
// Usage:
//   node scripts/validate-ipc-catalog.mjs
//   node scripts/validate-ipc-catalog.mjs --json
//   node scripts/validate-ipc-catalog.mjs --write-catalog
//   node scripts/validate-ipc-catalog.mjs --manifest-only
//   node scripts/validate-ipc-catalog.mjs --all
// ============================================================

import { readFileSync, readdirSync, statSync, writeFileSync } from "fs";
import { resolve, join } from "path";
import { fileURLToPath } from "url";

const __dirname = fileURLToPath(new URL(".", import.meta.url));
const ROOT = resolve(__dirname, "..");

// ─── Regex patterns ────────────────────────────────────────────────────────────
// Matches: ipcMain.handle("channel", ...) or ipcMain.handle('channel', ...)
const RE_MAIN_HANDLE = /ipcMain\.handle\s*\(\s*['"`]([^'"`]+)['"`]\s*,/g;
// Matches: ipcMain.on("channel", ...)
const RE_MAIN_ON = /ipcMain\.on\s*\(\s*['"`]([^'"`]+)['"`]\s*,/g;
// Matches: mainWindow.webContents.send(...) — main→renderer push.
// The channel may be a string literal on the first line, or buried inside
// a ternary / conditional expression (e.g. updater:update-available vs
// updater:update-not-available). We extract ALL string literals from the
// send() call body and treat each as a channel.
// group(1) = first string literal found inside the parentheses.
const RE_MAIN_SEND = /webContents\.send\s*\(\s*([\s\S]*?)\)(?=\s*;|$)/g;
// Secondary: extract all quoted strings from a send-call body (handles ternaries)
const RE_SEND_CHANNEL = /['"`]([^'"`]+)['"`]/g;
// Matches: mainWindow.send(channel, payload) — secondary helper wrappers.
// Also captures channels passed as first arg to named send helpers.
const RE_SEND_HELPER = /send(?:TerminalEvent|SkillEvent|ProgressEvent|DataEvent)?\s*\(\s*['"`]([^'"`]+)['"`]\s*,/g;
// Matches: ipcRenderer.invoke("channel", ...) or ipcRenderer.invoke('channel', ...)
const RE_PRELOAD_INVOKE = /ipcRenderer\.invoke\s*\(\s*['"`]([^'"`]+)['"`]\s*,/g;
// Matches: ipcRenderer.on("channel", ...)
const RE_PRELOAD_ON = /ipcRenderer\.on\s*\(\s*['"`]([^'"`]+)['"`]\s*,/g;

// ─── Self-written validators (UR-4: no ajv / zod) ───────────────────────────

/**
 * Validate channel name format.
 * @param {string} channel
 * @returns {{ ok: boolean, error?: string }}
 */
function checkChannelName(channel) {
  if (typeof channel !== "string" || channel.length === 0) {
    return { ok: false, error: "channel must be a non-empty string" };
  }
  if (channel.length > 200) {
    return { ok: false, error: `channel name too long (${channel.length} > 200)` };
  }
  if (/\s/.test(channel)) {
    return { ok: false, error: "channel name must not contain whitespace" };
  }
  return { ok: true };
}

// ─── Plugin Manifest Schema Validation (PL-001 style — self-written, no ajv/zod) ──

const PLUGIN_REQUIRED_FIELDS = Object.freeze([
  'id', 'title', 'version', 'language', 'pluginManifestVersion',
]);

const VALID_LANGUAGES = Object.freeze(['r', 'python', 'javascript', 'julia', 'bash']);
const VALID_STATUSES = Object.freeze(['canonical', 'experimental', 'deprecated', 'archived']);
const VALID_SOURCE_POLICIES = Object.freeze([
  'builtin-canonical', 'builtin-experimental', 'user-installed', 'remote',
]);
const VALID_PLATFORM_IDS = Object.freeze(['macos-arm64', 'macos-x64', 'windows-x64', 'linux-x64']);
const SEMVER_RE = /^[0-9]+\.[0-9]+\.[0-9]+/;
const SHA256_RE = /^[a-f0-9]{64}$/;
const ID_RE = /^[a-z][a-z0-9_-]*$/;

/**
 * Validate a single plugin manifest object.
 * Returns array of issue strings (empty = valid).
 * @param {object} manifest
 * @returns {string[]}
 */
function validatePluginManifest(manifest) {
  const issues = [];

  if (!manifest || typeof manifest !== 'object') {
    return ['plugin manifest must be a non-null object'];
  }

  // Required fields
  for (const field of PLUGIN_REQUIRED_FIELDS) {
    if (manifest[field] === undefined || manifest[field] === null) {
      issues.push(`required field "${field}" is missing or null`);
    }
  }

  // id
  if (typeof manifest.id !== 'string' || manifest.id.length === 0) {
    issues.push('id must be a non-empty string');
  } else if (!ID_RE.test(manifest.id)) {
    issues.push(`id "${manifest.id}" must match /^[a-z][a-z0-9_-]*$/`);
  }

  // pluginManifestVersion
  if (typeof manifest.pluginManifestVersion !== 'number') {
    issues.push('pluginManifestVersion must be a number');
  } else if (!Number.isInteger(manifest.pluginManifestVersion) || manifest.pluginManifestVersion < 1) {
    issues.push(`pluginManifestVersion must be a positive integer (got ${manifest.pluginManifestVersion})`);
  }

  // title
  if (typeof manifest.title !== 'string' || manifest.title.trim().length === 0) {
    issues.push('title must be a non-empty string');
  }

  // version (semver)
  if (typeof manifest.version !== 'string' || !SEMVER_RE.test(manifest.version)) {
    issues.push(`version "${manifest.version}" must be a semver-like string (e.g. "1.0.0")`);
  }

  // language
  if (typeof manifest.language !== 'string' || !VALID_LANGUAGES.includes(manifest.language)) {
    issues.push(`language "${manifest.language}" must be one of: ${VALID_LANGUAGES.join(', ')}`);
  }

  // status (optional, but if present must be valid)
  if (manifest.status !== undefined && !VALID_STATUSES.includes(manifest.status)) {
    issues.push(`status "${manifest.status}" must be one of: ${VALID_STATUSES.join(', ')}`);
  }

  // sourcePolicy (optional)
  if (manifest.sourcePolicy !== undefined && !VALID_SOURCE_POLICIES.includes(manifest.sourcePolicy)) {
    issues.push(`sourcePolicy "${manifest.sourcePolicy}" must be one of: ${VALID_SOURCE_POLICIES.join(', ')}`);
  }

  // packages
  if (manifest.packages !== undefined) {
    if (typeof manifest.packages !== 'object' || Array.isArray(manifest.packages)) {
      issues.push('packages must be a non-array object (e.g. { r: { pkg: "ver" } })');
    } else {
      for (const [lang, pkgs] of Object.entries(manifest.packages)) {
        if (!VALID_LANGUAGES.includes(lang)) {
          issues.push(`packages.${lang}: invalid language key (not in ${VALID_LANGUAGES.join(', ')})`);
        } else if (typeof pkgs !== 'object' || Array.isArray(pkgs)) {
          issues.push(`packages.${lang} must be an object mapping package name to version string`);
        } else {
          for (const [pkg, ver] of Object.entries(pkgs)) {
            if (typeof pkg !== 'string' || pkg.length === 0) {
              issues.push(`packages.${lang}: package name must be a non-empty string`);
            }
            if (typeof ver !== 'string' || ver.length === 0) {
              issues.push(`packages.${lang}.${pkg}: version must be a non-empty string`);
            }
          }
        }
      }
    }
  }

  // runtime
  if (manifest.runtime !== undefined) {
    if (typeof manifest.runtime !== 'object' || Array.isArray(manifest.runtime)) {
      issues.push('runtime must be a non-array object (e.g. { r: ">=4.4.0" })');
    } else {
      for (const [lang, ver] of Object.entries(manifest.runtime)) {
        if (!VALID_LANGUAGES.includes(lang)) {
          issues.push(`runtime.${lang}: invalid language key`);
        }
        if (typeof ver !== 'string' || ver.length === 0) {
          issues.push(`runtime.${lang}: version constraint must be a non-empty string`);
        }
      }
    }
  }

  // builtAgainst
  if (manifest.builtAgainst !== undefined) {
    if (typeof manifest.builtAgainst !== 'object' || Array.isArray(manifest.builtAgainst)) {
      issues.push('builtAgainst must be a non-array object');
    } else {
      for (const [key, val] of Object.entries(manifest.builtAgainst)) {
        if (typeof val !== 'string' || val.length === 0) {
          issues.push(`builtAgainst.${key}: version must be a non-empty string`);
        }
      }
    }
  }

  // platform / supportedPlatforms
  for (const field of ['platform', 'supportedPlatforms']) {
    if (manifest[field] !== undefined) {
      if (!Array.isArray(manifest[field])) {
        issues.push(`${field} must be an array`);
      } else {
        for (const p of manifest[field]) {
          if (!VALID_PLATFORM_IDS.includes(p)) {
            issues.push(`${field}: invalid platform "${p}" (must be one of: ${VALID_PLATFORM_IDS.join(', ')})`);
          }
        }
      }
    }
  }

  // platformSupport (optional — detailed per-platform)
  if (manifest.platformSupport !== undefined) {
    if (typeof manifest.platformSupport !== 'object' || Array.isArray(manifest.platformSupport)) {
      issues.push('platformSupport must be a non-array object');
    } else {
      for (const [platformId, support] of Object.entries(manifest.platformSupport)) {
        if (!VALID_PLATFORM_IDS.includes(platformId)) {
          issues.push(`platformSupport: invalid platformId "${platformId}"`);
        }
        if (typeof support !== 'object' || Array.isArray(support)) {
          issues.push(`platformSupport.${platformId}: must be an object`);
        } else {
          if (support.status !== undefined) {
            const validStatuses = ['supported', 'planned', 'unsupported', 'deprecated'];
            if (!validStatuses.includes(support.status)) {
              issues.push(`platformSupport.${platformId}.status "${support.status}" must be one of: ${validStatuses.join(', ')}`);
            }
          }
        }
      }
    }
  }

  // requiresBundle / requiresBundleVersion
  if (manifest.requiresBundle !== undefined) {
    if (typeof manifest.requiresBundle !== 'string' || manifest.requiresBundle.length === 0) {
      issues.push('requiresBundle must be a non-empty string');
    }
  }
  if (manifest.requiresBundleVersion !== undefined) {
    if (typeof manifest.requiresBundleVersion !== 'string' || !SEMVER_RE.test(manifest.requiresBundleVersion)) {
      issues.push('requiresBundleVersion must be a semver-like string');
    }
  }
  if (manifest.requiresBundle !== undefined && manifest.requiresBundleVersion === undefined) {
    issues.push('requiresBundle is set but requiresBundleVersion is missing');
  }

  return issues;
}

/**
 * Scan all plugin.json files in a directory tree.
 * Returns array of { path, manifest, issues }.
 * @param {string} rootDir
 * @returns {{ path: string, manifest: object, issues: string[] }[]}
 */
function scanPluginManifests(rootDir) {
  const results = [];

  function walk(dir) {
    let entries;
    try {
      entries = readdirSync(dir);
    } catch {
      return;
    }
    for (const entry of entries) {
      const fullPath = join(dir, entry);
      let stat;
      try {
        stat = statSync(fullPath);
      } catch {
        continue;
      }
      if (stat.isDirectory()) {
        walk(fullPath);
      } else if (entry === 'plugin.json') {
        let parsed = null;
        let parseError = null;
        let raw;
        try {
          raw = readFileSync(fullPath, 'utf8');
          parsed = JSON.parse(raw);
        } catch (err) {
          parseError = err.message;
          parsed = null;
        }
        const issues = parseError
          ? [`JSON parse error: ${parseError}`]
          : validatePluginManifest(parsed);
        const rel = fullPath.replace(rootDir + '/', '').replace(/\\/g, '/');
        results.push({ path: rel, manifest: parsed, issues });
      }
    }
  }

  walk(rootDir);
  return results;
}

// ─── Payload Shape Basic Type Checks (self-written, no ajv/zod) ──────────────

const KNOWN_PAYLOAD_TYPES = Object.freeze([
  'null', 'boolean', 'number', 'integer', 'string', 'array', 'object',
]);

/**
 * Infer the expected JS type from a schema value description string.
 * Returns a JS typeof string or 'unknown'.
 * @param {string} typeStr
 * @returns {string}
 */
function inferJsType(typeStr) {
  switch (typeStr) {
    case 'null': return 'object';
    case 'boolean': return 'boolean';
    case 'number': return 'number';
    case 'integer': return 'number';
    case 'string': return 'string';
    case 'array': return 'object';
    case 'object': return 'object';
    default: return 'unknown';
  }
}

/**
 * Basic type check for an IPC payload against an inferred schema.
 * Returns { ok, errors } where errors is array of string.
 *
 * This is a shallow type check — it detects obvious type mismatches
 * in payload objects without introducing zod/ajv. Supports top-level
 * type checks and nested property validation.
 *
 * @param {*} value
 * @param {{ type: string, minimum?: number, maximum?: number, enum?: string[], required?: string[], properties?: object, items?: object }} schema
 * @param {string} path
 * @returns {{ ok: boolean, errors: string[] }}
 */
function checkPayloadShape(value, schema, path = '<payload>') {
  const errors = [];

  if (!schema || typeof schema !== 'object') {
    return { ok: true, errors: [] }; // no schema = skip
  }

  // Validate the top-level value against schema.type
  if (schema.type !== undefined) {
    const jsType = inferJsType(schema.type);
    if (jsType !== 'unknown') {
      if (schema.type === 'null') {
        if (value !== null) {
          errors.push(`${path}: expected null, got ${value === null ? 'null' : typeof value}`);
        }
      } else if (schema.type === 'integer') {
        if (typeof value !== 'number' || !Number.isInteger(value)) {
          errors.push(`${path}: expected integer, got ${typeof value} ${value}`);
        }
      } else if (typeof value !== jsType) {
        errors.push(`${path}: expected type ${schema.type}, got ${typeof value}`);
      }
    }
  }

  // Validate nested properties if schema has properties definition
  if (schema.properties && typeof value === 'object' && value !== null && !Array.isArray(value)) {
    for (const [propName, propSchema] of Object.entries(schema.properties)) {
      const propValue = value[propName];
      const propPath = `${path}.${propName}`;
      // Check if required field is missing
      if (propValue === undefined && Array.isArray(schema.required) && schema.required.includes(propName)) {
        errors.push(`${propPath}: required field "${propName}" is missing`);
      }
      // Validate property value if present
      if (propValue !== undefined) {
        const propErrors = checkPayloadShape(propValue, propSchema, propPath);
        errors.push(...propErrors.errors);
      }
    }
  }

  if (schema.minimum !== undefined && typeof value === 'number') {
    if (value < schema.minimum) {
      errors.push(`${path}: value ${value} < minimum ${schema.minimum}`);
    }
  }

  if (schema.maximum !== undefined && typeof value === 'number') {
    if (value > schema.maximum) {
      errors.push(`${path}: value ${value} > maximum ${schema.maximum}`);
    }
  }

  if (schema.enum !== undefined && Array.isArray(schema.enum)) {
    if (!schema.enum.includes(value)) {
      errors.push(`${path}: value "${value}" not in enum [${schema.enum.join(', ')}]`);
    }
  }

  return { ok: errors.length === 0, errors };
}

/**
 * Payload shape registry: maps channel prefix to expected schema hints.
 * This is used for static analysis of common IPC channel payload patterns.
 * Format: { prefix: { type: 'invoke'|'push', payloadHint: object } }
 */
const PAYLOAD_HINTS = Object.freeze({
  'window:': { type: 'push', payloadHint: { type: 'object' } },
  'app:': { type: 'invoke', payloadHint: { type: 'object' } },
  'plugin:': { type: 'invoke', payloadHint: { type: 'object' } },
  'file:': { type: 'invoke', payloadHint: { type: 'object' } },
  'runtime:': { type: 'invoke', payloadHint: { type: 'object' } },
  'backend:': { type: 'invoke', payloadHint: { type: 'object' } },
  'terminal:': { type: 'invoke', payloadHint: { type: 'object' } },
  'skill:': { type: 'invoke', payloadHint: { type: 'object' } },
  'diagnostic:': { type: 'invoke', payloadHint: { type: 'object' } },
  'data:': { type: 'invoke', payloadHint: { type: 'object' } },
  'ai:': { type: 'invoke', payloadHint: { type: 'object' } },
  'compute:': { type: 'invoke', payloadHint: { type: 'object' } },
  'updater:': { type: 'push', payloadHint: { type: 'object' } },
});

/**
 * Get payload hint for a channel name.
 * @param {string} channel
 * @returns {object|null}
 */
function getPayloadHint(channel) {
  for (const [prefix, hint] of Object.entries(PAYLOAD_HINTS)) {
    if (channel.startsWith(prefix)) return hint;
  }
  return null;
}

// ─── Line counting ─────────────────────────────────────────────────────────────

/**
 * Count lines (1-indexed) up to a byte offset in a string.
 * @param {string} str
 * @param {number} byteOffset
 * @returns {number}
 */
function countLines(str, byteOffset) {
  const prefix = str.slice(0, byteOffset);
  return prefix.split("\n").length;
}

// ─── File scanning helpers ────────────────────────────────────────────────────

/**
 * Scan a file's content for main-process IPC channel registrations.
 * Returns { handles, ons, sends }.
 * @param {string} filePath
 * @param {string} relativePath
 * @returns {{ handles: ChannelEntry[], ons: ChannelEntry[], sends: ChannelEntry[] }}
 */
function scanFile(filePath, relativePath) {
  let content;
  try {
    content = readFileSync(filePath, "utf8");
  } catch {
    return { handles: [], ons: [], sends: [] };
  }

  const handles = [];
  const ons = [];
  const sends = [];
  let m;

  RE_MAIN_HANDLE.lastIndex = 0;
  while ((m = RE_MAIN_HANDLE.exec(content)) !== null) {
    handles.push({ channel: m[1], file: relativePath, line: countLines(content, m.index) });
  }

  RE_MAIN_ON.lastIndex = 0;
  while ((m = RE_MAIN_ON.exec(content)) !== null) {
    ons.push({ channel: m[1], file: relativePath, line: countLines(content, m.index) });
  }

  RE_MAIN_SEND.lastIndex = 0;
  while ((m = RE_MAIN_SEND.exec(content)) !== null) {
    // Extract all quoted string literals from the send() call body.
    // This handles cases like: send(flag ? "channel-a" : "channel-b")
    const body = m[1];
    const line = countLines(content, m.index);
    let sm;
    RE_SEND_CHANNEL.lastIndex = 0;
    while ((sm = RE_SEND_CHANNEL.exec(body)) !== null) {
      sends.push({ channel: sm[1], file: relativePath, line });
    }
  }

  // Also scan for named send-helper calls like sendTerminalEvent("channel", ...)
  // These are wrapper functions that ultimately call webContents.send internally.
  RE_SEND_HELPER.lastIndex = 0;
  while ((m = RE_SEND_HELPER.exec(content)) !== null) {
    sends.push({
      channel: m[1],
      file: relativePath,
      line: countLines(content, m.index),
    });
  }

  return { handles, ons, sends };
}

/**
 * Scan preload.js for renderer-process IPC channel calls.
 * Returns { invokes, ons }.
 * @param {string} filePath
 * @param {string} relativePath
 * @returns {{ invokes: ChannelEntry[], ons: ChannelEntry[] }}
 */
function scanPreload(filePath, relativePath) {
  let content;
  try {
    content = readFileSync(filePath, "utf8");
  } catch {
    return { invokes: [], ons: [] };
  }

  const invokes = [];
  const ons = [];
  let m;

  RE_PRELOAD_INVOKE.lastIndex = 0;
  while ((m = RE_PRELOAD_INVOKE.exec(content)) !== null) {
    invokes.push({ channel: m[1], file: relativePath, line: countLines(content, m.index) });
  }

  RE_PRELOAD_ON.lastIndex = 0;
  while ((m = RE_PRELOAD_ON.exec(content)) !== null) {
    ons.push({ channel: m[1], file: relativePath, line: countLines(content, m.index) });
  }

  return { invokes, ons };
}

// ─── Catalog building ─────────────────────────────────────────────────────────

/**
 * Build the full IPC catalog from source files.
 * @returns {IPCCatalog}
 */
function buildCatalog() {
  const mainHandles = [];
  const mainOns = [];
  const mainSends = [];

  // 1. Scan main.js
  const mainJs = join(ROOT, "src", "main.js");
  const mainResult = scanFile(mainJs, "src/main.js");
  mainHandles.push(...mainResult.handles);
  mainOns.push(...mainResult.ons);
  mainSends.push(...mainResult.sends);

  // 2. Scan src/main/*.js (SUB-15.1 extracted files)
  const mainDir = join(ROOT, "src", "main");
  try {
    for (const file of readdirSync(mainDir)) {
      if (!file.endsWith(".js")) continue;
      const result = scanFile(join(mainDir, file), `src/main/${file}`);
      mainHandles.push(...result.handles);
      mainOns.push(...result.ons);
      mainSends.push(...result.sends);
    }
  } catch {}

  // 3. Scan src/ipc/*.js (BLOCK-9.1 extracted handlers)
  const ipcDir = join(ROOT, "src", "ipc");
  try {
    for (const file of readdirSync(ipcDir)) {
      if (!file.endsWith(".js")) continue;
      const result = scanFile(join(ipcDir, file), `src/ipc/${file}`);
      mainHandles.push(...result.handles);
      mainOns.push(...result.ons);
      mainSends.push(...result.sends);
    }
  } catch {}

  // 4. Scan preload.js
  const preloadJs = join(ROOT, "src", "preload.js");
  const preloadResult = scanPreload(preloadJs, "src/preload.js");

  return {
    mainHandles,
    mainOns,
    mainSends,
    preloadInvokes: preloadResult.invokes,
    preloadOns: preloadResult.ons,
  };
}

// ─── Cross-referencing ────────────────────────────────────────────────────────

/**
 * Cross-reference main vs preload to determine channel categories:
 *
 * Bidirectional channel pairs:
 *   - invoke/invoke: main ipcMain.handle ↔ preload ipcRenderer.invoke (request/response)
 *   - push/listen:   main webContents.send ↔ preload ipcRenderer.on (main→renderer push)
 *
 * Shadow channels (main-only, no preload counterpart):
 *   - shadowHandle: main ipcMain.handle exists but preload has no ipcRenderer.invoke
 *   - shadowSend:   main webContents.send exists but preload has no ipcRenderer.on
 *   - shadowOn:     main ipcMain.on exists but preload has no ipcRenderer.on
 *
 * Orphan channels (ERROR — preload calls a channel that doesn't exist in main):
 *   - orphanInvoke: preload ipcRenderer.invoke but no matching main ipcMain.handle
 *   - orphanOn:     preload ipcRenderer.on but no matching main ipcMain.on / webContents.send
 *
 * @param {IPCCatalog} catalog
 * @returns {CrossRefResult}
 */
function crossRef(catalog) {
  const { mainHandles, mainOns, mainSends, preloadInvokes, preloadOns } = catalog;

  // Maps: channel → entry
  const mainHandleMap = new Map(mainHandles.map((h) => [h.channel, h]));
  const mainOnMap = new Map(mainOns.map((o) => [o.channel, o]));
  const mainSendMap = new Map(mainSends.map((s) => [s.channel, s]));
  const preloadInvokeMap = new Map(preloadInvokes.map((i) => [i.channel, i]));
  const preloadOnMap = new Map(preloadOns.map((o) => [o.channel, o]));

  const consistentPairs = [];     // { channel, main, preload, type }
  const shadowHandles = [];     // main handle, no preload invoke
  const shadowSends = [];      // main send, no preload on
  const shadowOns = [];         // main on, no preload on
  const orphanInvokes = [];     // preload invoke, no main handle
  const orphanOns = [];         // preload on, no main on / main send

  // ── 1. ipcMain.handle ↔ ipcRenderer.invoke ──────────────────────────────
  for (const [channel, mainEntry] of mainHandleMap) {
    if (preloadInvokeMap.has(channel)) {
      consistentPairs.push({
        channel,
        main: mainEntry,
        preload: preloadInvokeMap.get(channel),
        type: "invoke",
      });
    } else {
      shadowHandles.push(mainEntry);
    }
  }

  // ── 2. webContents.send ↔ ipcRenderer.on (push channels) ────────────────
  for (const [channel, mainEntry] of mainSendMap) {
    if (preloadOnMap.has(channel)) {
      consistentPairs.push({
        channel,
        main: mainEntry,
        preload: preloadOnMap.get(channel),
        type: "push/listen",
      });
    } else {
      shadowSends.push(mainEntry);
    }
  }

  // ── 3. ipcMain.on (listen-only) ↔ preload on ────────────────────────────
  // Note: ipcMain.on is rare (usually for window chrome events handled in
  // _window-ipc.js). These are cross-referenced against preload on.
  for (const [channel, mainEntry] of mainOnMap) {
    if (!preloadOnMap.has(channel)) {
      shadowOns.push(mainEntry);
    }
  }

  // ── 4. Orphan invokes: preload invoke has no main handle ──────────────────
  for (const [channel, preloadEntry] of preloadInvokeMap) {
    if (!mainHandleMap.has(channel)) {
      orphanInvokes.push(preloadEntry);
    }
  }

  // ── 5. Orphan ons: preload on has neither main send nor main on ───────────
  for (const [channel, preloadEntry] of preloadOnMap) {
    if (!mainSendMap.has(channel) && !mainOnMap.has(channel)) {
      orphanOns.push(preloadEntry);
    }
  }

  return { consistentPairs, shadowHandles, shadowSends, shadowOns, orphanInvokes, orphanOns };
}

// ─── Reporter ────────────────────────────────────────────────────────────────

/**
 * Emit structured console output.
 * @param {CrossRefResult} ref
 * @param {IPCCatalog} catalog
 */
function report(ref, catalog) {
  const { consistentPairs, shadowHandles, shadowSends, shadowOns, orphanInvokes, orphanOns } = ref;

  const totalMain = catalog.mainHandles.length + catalog.mainOns.length + catalog.mainSends.length;

  console.log(`[IPC-CATALOG] ${catalog.mainHandles.length} ipcMain.handle found`);
  console.log(`[IPC-CATALOG] ${catalog.mainOns.length} ipcMain.on found`);
  console.log(`[IPC-CATALOG] ${catalog.mainSends.length} webContents.send found`);
  console.log(`[IPC-CATALOG] ${catalog.preloadInvokes.length} ipcRenderer.invoke found`);
  console.log(`[IPC-CATALOG] ${catalog.preloadOns.length} ipcRenderer.on found`);
  console.log(`[IPC-CATALOG] ${totalMain} total main-side registrations`);
  console.log(`[IPC-CATALOG] ${consistentPairs.length} consistent pairs`);
  console.log(`[IPC-CATALOG] ${ref.shadowCount()} shadow channels (main-only, OK)`);
  console.log(`[IPC-CATALOG] ${ref.orphanCount()} orphan channels`);

  const shadowCount = shadowHandles.length + shadowSends.length + shadowOns.length;

  if (shadowHandles.length > 0) {
    console.log(`[IPC-CATALOG] Shadow handles (${shadowHandles.length}):`);
    for (const h of shadowHandles) {
      console.log(`[IPC-CATALOG]   ${h.channel} (${h.file}:${h.line})`);
    }
  }

  if (shadowSends.length > 0) {
    console.log(`[IPC-CATALOG] Shadow sends (${shadowSends.length}):`);
    for (const s of shadowSends) {
      console.log(`[IPC-CATALOG]   ${s.channel} (${s.file}:${s.line})`);
    }
  }

  if (shadowOns.length > 0) {
    console.log(`[IPC-CATALOG] Shadow on (${shadowOns.length}):`);
    for (const o of shadowOns) {
      console.log(`[IPC-CATALOG]   ${o.channel} (${o.file}:${o.line})`);
    }
  }

  if (orphanInvokes.length > 0) {
    console.log(`[IPC-CATALOG] FAIL: ${orphanInvokes.length} orphan invoke channels detected`);
    for (const o of orphanInvokes) {
      console.log(`[IPC-CATALOG]   - ${o.channel} (${o.file}:${o.line})`);
    }
  }

  if (orphanOns.length > 0) {
    console.log(`[IPC-CATALOG] FAIL: ${orphanOns.length} orphan on channels detected`);
    for (const o of orphanOns) {
      console.log(`[IPC-CATALOG]   - ${o.channel} (${o.file}:${o.line})`);
    }
  }

  if (ref.orphanCount() === 0) {
    console.log("[IPC-CATALOG] PASS");
  }
}

// ─── JSON catalog export ──────────────────────────────────────────────────────

/**
 * Build the machine-readable catalog JSON.
 * @param {CrossRefResult} ref
 * @param {IPCCatalog} catalog
 * @param {{ manifestResults?: object[], manifestErrors?: number }} [opts]
 * @returns {object}
 */
function buildCatalogJson(ref, catalog, opts = {}) {
  const { manifestResults = [], manifestErrors = 0 } = opts || {};
  const { consistentPairs, shadowHandles, shadowSends, shadowOns, orphanInvokes, orphanOns } = ref;

  /** @type {Record<string, object>} */
  const channels = {};

  for (const pair of consistentPairs) {
    channels[pair.channel] = {
      type: pair.type,
      main: { file: pair.main.file, line: pair.main.line },
      preload: { file: pair.preload.file, line: pair.preload.line },
      consistent: true,
    };
  }

  for (const h of shadowHandles) {
    channels[h.channel] = {
      type: "handle",
      main: { file: h.file, line: h.line },
      preload: null,
      consistent: false,
      shadowReason: "main ipcMain.handle with no preload ipcRenderer.invoke",
    };
  }

  for (const s of shadowSends) {
    channels[s.channel] = {
      type: "send",
      main: { file: s.file, line: s.line },
      preload: null,
      consistent: false,
      shadowReason: "main webContents.send with no preload ipcRenderer.on listener",
    };
  }

  for (const o of shadowOns) {
    channels[o.channel] = {
      type: "on",
      main: { file: o.file, line: o.line },
      preload: null,
      consistent: false,
      shadowReason: "main ipcMain.on with no preload counterpart",
    };
  }

  for (const o of orphanInvokes) {
    channels[o.channel] = {
      type: "invoke",
      main: null,
      preload: { file: o.file, line: o.line },
      consistent: false,
      orphanReason: "preload ipcRenderer.invoke with no main ipcMain.handle",
    };
  }

  for (const o of orphanOns) {
    channels[o.channel] = {
      type: "on",
      main: null,
      preload: { file: o.file, line: o.line },
      consistent: false,
      orphanReason: "preload ipcRenderer.on with no main webContents.send or ipcMain.on",
    };
  }

  const totalMain =
    catalog.mainHandles.length + catalog.mainOns.length + catalog.mainSends.length;

  return {
    version: "2.0",
    generated: new Date().toISOString().slice(0, 10),
    channels,
    summary: {
      totalMainRegistrations: totalMain,
      totalMainHandles: catalog.mainHandles.length,
      totalMainOns: catalog.mainOns.length,
      totalMainSends: catalog.mainSends.length,
      totalPreloadInvokes: catalog.preloadInvokes.length,
      totalPreloadOns: catalog.preloadOns.length,
      consistent: consistentPairs.length,
      shadow: ref.shadowCount(),
      orphan: ref.orphanCount(),
      pluginManifestCount: manifestResults.length,
      pluginManifestErrors: manifestErrors,
    },
    shadowChannels: [...shadowHandles, ...shadowSends, ...shadowOns]
      .map((e) => e.channel)
      .sort(),
    orphanChannels: [...orphanInvokes, ...orphanOns]
      .map((e) => e.channel)
      .sort(),
    pluginManifests: manifestResults,
  };
}

// ─── Main ────────────────────────────────────────────────────────────────────

/**
 * @typedef {{ channel: string, file: string, line: number }} ChannelEntry
 * @typedef {{ mainHandles: ChannelEntry[], mainOns: ChannelEntry[], mainSends: ChannelEntry[], preloadInvokes: ChannelEntry[], preloadOns: ChannelEntry[] }} IPCCatalog
 * @typedef {{ consistentPairs: object[], shadowHandles: ChannelEntry[], shadowSends: ChannelEntry[], shadowOns: ChannelEntry[], orphanInvokes: ChannelEntry[], orphanOns: ChannelEntry[], shadowCount: () => number, orphanCount: () => number }} CrossRefResult
 */

async function main() {
  const quiet = process.argv.includes("--json");
  const manifestOnly = process.argv.includes("--manifest-only");
  const all = process.argv.includes("--all");

  if (!quiet) console.log("[IPC-CATALOG] Scanning IPC channels...");

  const catalog = buildCatalog();
  const ref = crossRef(catalog);

  // Attach helper methods
  ref.shadowCount = () =>
    ref.shadowHandles.length + ref.shadowSends.length + ref.shadowOns.length;
  ref.orphanCount = () => ref.orphanInvokes.length + ref.orphanOns.length;

  // ── Plugin manifest validation (always runs, needed for JSON output) ───────────
  const builtInPluginsDir = join(ROOT, "resources", "built-in-plugins");
  const harnessDir = join(ROOT, "acceptance", "harness-plugin-prototype");
  const pluginScanResults = [];
  const allManifestIssues = [];

  for (const dir of [builtInPluginsDir, harnessDir]) {
    try {
      pluginScanResults.push(...scanPluginManifests(dir));
    } catch {}
  }

  for (const result of pluginScanResults) {
    if (result.issues.length > 0) {
      allManifestIssues.push({ path: result.path, issues: result.issues });
    }
  }

  // ── Payload shape analysis (static — no runtime required) ──────────────────────
  if (!manifestOnly) {
    const allChannels = [
      ...catalog.mainHandles.map(h => h.channel),
      ...catalog.mainSends.map(s => s.channel),
    ];
    const channelsWithPayloadHints = allChannels.filter(ch => getPayloadHint(ch) !== null);
    if (!quiet) {
      console.log(`[IPC-CATALOG] ${channelsWithPayloadHints.length} channels have payload shape hints`);
    }
  }

  // Write pure JSON (no logs) for machine consumption
  if (process.argv.includes("--json")) {
    const json = buildCatalogJson(ref, catalog, {
      manifestResults: pluginScanResults,
      manifestErrors: allManifestIssues.length,
    });
    console.log(JSON.stringify(json, null, 2));
    return;
  }

  if (!quiet) {
    console.log(`[IPC-CATALOG] ${pluginScanResults.length} plugin manifest(s) scanned`);
    if (allManifestIssues.length === 0) {
      console.log("[IPC-CATALOG] MANIFEST: all plugins pass schema validation");
    } else {
      console.log(`[IPC-CATALOG] MANIFEST: ${allManifestIssues.length} plugin(s) with schema issues`);
      for (const err of allManifestIssues) {
        console.log(`[IPC-CATALOG] MANIFEST: ${err.issues.length} issue(s) in ${err.path}`);
        for (const issue of err.issues) {
          console.log(`[IPC-CATALOG]   - ${issue}`);
        }
      }
    }
  }

  if (manifestOnly) {
    // manifest-only mode: only report manifest results
    if (allManifestIssues.length > 0) {
      process.exit(1);
    }
    return;
  }

  report(ref, catalog);

  // Write catalog to docs/ipc-catalog.json
  if (process.argv.includes("--write-catalog")) {
    const json = buildCatalogJson(ref, catalog, {
      manifestResults: pluginScanResults,
      manifestErrors: allManifestIssues.length,
    });
    const outPath = join(ROOT, "docs", "ipc-catalog.json");
    writeFileSync(outPath, JSON.stringify(json, null, 2));
    console.log(`[IPC-CATALOG] Catalog written to docs/ipc-catalog.json`);
  }

  const hasOrphans = ref.orphanCount() > 0;

  if (hasOrphans) {
    console.log("[IPC-CATALOG] FAIL: orphan IPC channels detected");
    process.exit(1);
  }

  // Manifest errors are informational in default gate (not blocking).
  // Use --manifest-only for strict manifest validation.
  if (allManifestIssues.length > 0 && !quiet) {
    console.log(`[IPC-CATALOG] NOTE: ${allManifestIssues.length} plugin manifest(s) have schema issues (non-blocking; use --manifest-only to enforce)`);
  }
}

main().catch((err) => {
  console.error("[IPC-CATALOG] Unexpected error:", err);
  process.exit(1);
});

#!/usr/bin/env node

"use strict";

const { spawnSync } = require("child_process");
const fs = require("fs");
const path = require("path");
const { app } = require("electron");

const dataDir = process.env.PETRI_LOCAL_DATA_DIR;
if (!dataDir) {
  console.error("[runtime-first-use] PETRI_LOCAL_DATA_DIR is required");
  process.exit(2);
}

const resolvedDataDir = path.resolve(dataDir);
const defaultDataDir = path.join(app.getPath("documents"), "Petri-Local");
if (resolvedDataDir === path.resolve(defaultDataDir)) {
  console.error("[runtime-first-use] refusing to use the default user data directory");
  process.exit(2);
}
if (fs.existsSync(resolvedDataDir) && fs.readdirSync(resolvedDataDir).length > 0) {
  console.error(`[runtime-first-use] target must be empty: ${resolvedDataDir}`);
  process.exit(2);
}
fs.mkdirSync(resolvedDataDir, { recursive: true });

function run(command, args) {
  const result = spawnSync(command, args, {
    encoding: "utf8",
    env: { ...process.env, ELECTRON_RUN_AS_NODE: "1" },
  });
  if (result.status !== 0) {
    throw new Error(
      `${command} ${args.join(" ")} failed (${result.status}): ${result.stderr || result.stdout}`,
    );
  }
  return (result.stdout || result.stderr || "").trim();
}

async function main() {
  await app.whenReady();
  const pluginManager = require("../src/plugin-manager");
  const manifest = await pluginManager.getRemoteManifest();
  const platform = pluginManager.detectPlatform();
  if (platform !== "macos-arm64") {
    throw new Error(`runtime first-use artifact is not published for ${platform}`);
  }

  for (const id of ["petri-r-runtime", "petri-py-runtime"]) {
    const entry = manifest.plugins[id];
    if (!entry) throw new Error(`manifest entry missing: ${id}`);
    let lastPercent = -1;
    await pluginManager.installPlugin(
      { id, manifest: entry, platform },
      (ratio) => {
        const percent = Math.floor(ratio * 100);
        if (percent >= lastPercent + 10 || percent === 100) {
          lastPercent = percent;
          console.log(`[runtime-first-use] ${id} ${percent}%`);
        }
      },
    );
  }

  const status = pluginManager.getRuntimeStatus();
  if (!status.r.installed || !status.python.installed) {
    throw new Error(`runtime status is incomplete: ${JSON.stringify(status)}`);
  }

  const rscript = path.join(resolvedDataDir, "runtimes", "R", "bin", "Rscript");
  const python = path.join(resolvedDataDir, "runtimes", "Python", "bin", "python3");
  const rVersion = run(rscript, ["--version"]);
  const pythonVersion = run(python, ["--version"]);
  const installed = pluginManager.getInstalledPlugins();
  const installedIds = new Set(installed.map((entry) => entry.id));
  for (const id of ["petri-r-runtime", "petri-py-runtime"]) {
    if (!installedIds.has(id)) throw new Error(`installed ledger missing: ${id}`);
  }

  console.log(`[runtime-first-use] R ready: ${rVersion}`);
  console.log(`[runtime-first-use] Python ready: ${pythonVersion}`);
  console.log(`[runtime-first-use] PASS dataDir=${resolvedDataDir}`);
}

main()
  .then(() => app.quit())
  .catch((error) => {
    console.error("[runtime-first-use] FAIL", error);
    app.exit(1);
  });

#!/usr/bin/env node
// Schema 验证门禁：确保 migration 最终 schema 与代码使用的表/列一致
//
// 执行：npm run schema:verify
// 返回：0 = 一致，1 = 发现漂移

const fs = require('fs');
const path = require('path');

// 加载 migration-runner（复用 better-sqlite3 加载逻辑）
const { loadDatabaseConstructor } = require('../src/migration-runner.js');
const Database = loadDatabaseConstructor();

// 临时数据库路径
const tmpDb = path.join(__dirname, '../.tmp-schema-check.db');

/**
 * 在临时库跑完所有 migration，返回最终 schema
 */
async function buildMigrationSchema() {
  // 清理旧临时库
  if (fs.existsSync(tmpDb)) fs.unlinkSync(tmpDb);

  // 手动跑 migration（复用 migration-runner 逻辑）
  const migrationsDir = path.join(__dirname, '../src/migrations');
  const files = fs.readdirSync(migrationsDir)
    .filter(f => f.endsWith('.sql'))
    .sort();

  const db = new Database(tmpDb);

  try {
    // 创建 schema_migrations 表
    db.exec(`CREATE TABLE IF NOT EXISTS schema_migrations (
      version INTEGER PRIMARY KEY,
      applied_at TEXT DEFAULT (datetime('now'))
    )`);

    // 按顺序执行所有 migration
    for (const file of files) {
      const version = parseInt(file.match(/^(\d+)_/)?.[1] || '0', 10);
      if (version === 0) continue;

      const sql = fs.readFileSync(path.join(migrationsDir, file), 'utf8');

      const transaction = db.transaction(() => {
        db.exec(sql);
        db.prepare('INSERT INTO schema_migrations (version) VALUES (?)').run(version);
      });

      transaction();
      console.log(`  ✓ Applied ${file}`);
    }

    // 读取最终 schema
    const tables = db.prepare(
      "SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' AND name != 'schema_migrations' ORDER BY name"
    ).all();

    const schema = {};
    for (const { name } of tables) {
      const cols = db.prepare(`PRAGMA table_info(${name})`).all();
      schema[name] = cols.map(c => ({
        name: c.name,
        type: c.type,
        notnull: c.notnull,
        dflt_value: c.dflt_value,
        pk: c.pk
      }));
    }

    return schema;
  } finally {
    db.close();
    // 清理临时库
    if (fs.existsSync(tmpDb)) fs.unlinkSync(tmpDb);
  }
}

/**
 * 定义代码中实际使用的 schema（预期）
 * 
 * 这里列出 core/petri-server/db.js 和前端 bridges 中使用的表与关键列。
 * 不需要列出所有列，只需列出代码中 SELECT/INSERT 明确依赖的列。
 */
const expectedSchema = {
  // migration 005 + 008
  projects: ['id', 'name', 'description', 'created_at', 'updated_at'],

  // migration 005
  branches: ['id', 'project_id', 'name', 'parent_branch_id', 'created_at', 'updated_at', 'is_active'],
  messages: ['id', 'branch_id', 'role', 'content', 'metadata', 'created_at'],

  // migration 006 + 007
  results: ['id', 'project_id', 'type', 'name', 'data', 'config', 'source_branch_id', 'created_at', 'updated_at'],
  result_tags: ['id', 'result_id', 'tag'],
  result_versions: ['id', 'result_id', 'version', 'data', 'config', 'created_at', 'created_by_branch_id'],

  // migration 001 - Result Studio
  git_repository_bindings: ['project_id', 'contract_version', 'mode', 'workspace_root', 'git_dir', 'work_tree', 'managed_paths_json', 'status', 'created_at', 'updated_at'],
  scientific_change_sets: ['change_set_id', 'project_id', 'base_commit', 'candidate_commit', 'working_branch_ref', 'status', 'created_at', 'updated_at'],
  artifact_revisions: ['revision_id', 'project_id', 'artifact_family_id', 'artifact_id', 'revision_ordinal', 'source_commit', 'output_path', 'validation_status', 'change_set_id', 'is_current', 'created_at'],
  result_selection_contexts: ['selection_id', 'project_id', 'artifact_id', 'entity_type', 'entity_ids_json', 'created_at', 'updated_at'],
  workspace_revision_checkpoints: ['checkpoint_id', 'project_id', 'base_commit', 'current_revision_ids_json', 'checkpoint_hash', 'created_at', 'updated_at'],

  // migration 002
  result_workflow_graphs: ['graph_id', 'project_id', 'root_tool_job_id', 'source_digest', 'nodes_json', 'edges_json', 'validation_status', 'created_at', 'updated_at'],

  // migration 003
  result_ref_transactions: ['operation_id', 'project_id', 'change_set_id', 'operation_kind', 'state', 'ref_updates_json', 'checkpoint_json', 'created_at', 'updated_at'],

  // migration 004
  git_repository_consents: ['project_id', 'contract_version', 'allow_existing_repository', 'decision_source', 'created_at', 'updated_at'],
};

/**
 * 验证 migration schema 是否包含预期的表和列
 */
function verifySchema(actualSchema) {
  let ok = true;
  const errors = [];

  // 检查每个预期表
  for (const [table, expectedCols] of Object.entries(expectedSchema)) {
    if (!actualSchema[table]) {
      errors.push(`❌ 表 \`${table}\` 缺失（代码使用但 migration 未定义）`);
      ok = false;
      continue;
    }

    const actualCols = actualSchema[table].map(c => c.name);

    // 检查每个预期列
    for (const col of expectedCols) {
      if (!actualCols.includes(col)) {
        errors.push(`❌ 表 \`${table}\` 缺少列 \`${col}\`（代码使用但 migration 未定义）`);
        ok = false;
      }
    }
  }

  return { ok, errors };
}

/**
 * 主入口
 */
async function main() {
  console.log('Schema 验证门禁');
  console.log('================\n');

  console.log('步骤 1：在临时库跑所有 migration...');
  const schema = await buildMigrationSchema();
  console.log(`  ✓ 构建完成，共 ${Object.keys(schema).length} 张表\n`);

  console.log('步骤 2：验证代码依赖的表/列是否存在...');
  const { ok, errors } = verifySchema(schema);

  if (ok) {
    console.log('  ✅ Schema 验证通过\n');
    console.log('Migration 定义与代码使用一致，未发现漂移。');
    process.exit(0);
  } else {
    console.log('  ❌ Schema 漂移检测到不一致\n');
    errors.forEach(err => console.error(err));
    console.log('\n修复方法：');
    console.log('  1. 创建新 migration 补齐缺失的表/列');
    console.log('  2. 或者修改代码，不使用 migration 未定义的表/列');
    console.log('  3. 参考 src/migrations/README.md 了解 migration 规则');
    process.exit(1);
  }
}

// 执行
main().catch(err => {
  console.error('Schema 验证失败:', err);
  // 清理临时库
  if (fs.existsSync(tmpDb)) {
    try {
      fs.unlinkSync(tmpDb);
    } catch {}
  }
  process.exit(1);
});

#!/usr/bin/env node
/**
 * Windows Runtime 首用隔离验证（本地 provisioned 路径）
 *
 * 为什么需要这个脚本：
 *   `scripts/validate-runtime-first-use.cjs` 只覆盖 macOS——它在
 *   `platform !== 'macos-arm64'` 处直接抛错，且路径写死为 POSIX
 *   (`runtimes/R/bin/Rscript`、`runtimes/Python/bin/python3`)。
 *   官方安装路径（manifest → OSS 下载 → 解压）在 Windows 上也走不通：
 *   `test/plugin-manifest-schema.test.mjs` 刻意要求
 *   `manifest.plugins[*].artifacts['windows-x64']` 必须为 0（禁止假 Windows 支持），
 *   所以 manifest 里没有 windows-x64 制品可供 selectArtifact 选中。
 *
 * 本脚本验证的是「制品自洽性 + resolveRuntime 命中 + 科学栈可用」这条真问题，
 * 不伪造 manifest 支持、不改 release-contract、不碰用户默认数据目录。
 *
 * 复刻 `src/plugin-manager.js#installRuntime` 的真实语义：
 *   1. 解压 zip 到 `<dataDir>/runtimes/{R|Python}`
 *   2. flatten：若目录只有 1 个子目录且无 `bin/`，把内容上提一层
 *   3. 用 `src/platform-compat.js` 的真实候选列表判定 resolveRuntime 是否命中
 *
 * 用法：
 *   node scripts/verify-win-runtime-first-use.mjs            # R + Python
 *   node scripts/verify-win-runtime-first-use.mjs --only=r   # 只验 R
 *   node scripts/verify-win-runtime-first-use.mjs --keep     # 保留解压树（默认保留）
 *
 * 退出码：0 全通过；1 有验证项失败；2 前置条件不满足。
 */

import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import { spawnSync } from 'node:child_process';
import { fileURLToPath, pathToFileURL } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.resolve(__dirname, '..');

const args = process.argv.slice(2);
const only = (args.find((a) => a.startsWith('--only=')) || '').split('=')[1] || '';
const KEEP = !args.includes('--no-keep');

function fail(msg, code = 2) {
  console.error(`\n[verify] FATAL ${msg}`);
  process.exit(code);
}

if (process.platform !== 'win32') {
  fail(`本脚本仅用于 win32，当前平台 ${process.platform}`);
}

// ── 隔离目录：刻意不用 Documents/Petri-Local（用户默认数据目录），避免污染 ──
const DATA_DIR = path.join(REPO_ROOT, 'tmp', 'win-first-use');
const RUNTIMES_DIR = path.join(DATA_DIR, 'runtimes');

const ARTIFACTS = {
  r: {
    name: 'R',
    zip: path.join(REPO_ROOT, 'dist-runtime', 'r-runtime-1.0.0-windows-x64.zip'),
    expectVersion: '4.5.2',
  },
  python: {
    name: 'Python',
    zip: path.join(REPO_ROOT, 'dist-runtime', 'py-runtime-1.0.0-windows-x64.zip'),
    expectVersion: '3.11.9',
  },
};

const results = [];
function check(label, ok, detail = '') {
  results.push({ label, ok, detail });
  console.log(`  ${ok ? 'PASS' : 'FAIL'}  ${label}${detail ? ` — ${detail}` : ''}`);
  return ok;
}

/**
 * 复刻 plugin-manager 的 flatten：单个子目录且无 bin/ 时上提一层。
 * Windows 上 `fs.renameSync` 跨目录移动非空目录不如 POSIX 可靠（易 EPERM），
 * 故用 cpSync 复制 + 删源，与 rename 语义等价且更稳。
 */
function flattenNested(runtimeDir) {
  const entries = fs.readdirSync(runtimeDir);
  if (
    entries.length === 1 &&
    fs.statSync(path.join(runtimeDir, entries[0])).isDirectory() &&
    !fs.existsSync(path.join(runtimeDir, 'bin'))
  ) {
    const nested = path.join(runtimeDir, entries[0]);
    for (const e of fs.readdirSync(nested)) {
      fs.cpSync(path.join(nested, e), path.join(runtimeDir, e), { recursive: true });
    }
    nukeDir(nested);
    return entries[0];
  }
  return null;
}

/** 用 .NET 删大目录：逐文件 fs.rmSync 会被 safe-delete shim 批量拦截且极慢 */
function nukeDir(dir) {
  if (!fs.existsSync(dir)) return;
  const ps = `if (Test-Path -LiteralPath '${dir}') { [System.IO.Directory]::Delete('${dir}', $true) }`;
  const r = spawnSync('powershell.exe', ['-NoProfile', '-Command', ps], {
    windowsHide: true,
    timeout: 1000 * 60 * 5,
  });
  if (r.status !== 0 && fs.existsSync(dir)) {
    throw new Error(`清理目录失败: ${dir}`);
  }
}

function unzipTo(zipPath, destDir) {
  fs.mkdirSync(destDir, { recursive: true });
  // Expand-Archive 解压不像 Compress-Archive 那样全内存缓冲，1.6GB 树可用；
  // -Force 覆盖，windowsHide 避免弹窗。
  const ps = `$ProgressPreference='SilentlyContinue'; Expand-Archive -LiteralPath '${zipPath}' -DestinationPath '${destDir}' -Force`;
  const started = Date.now();
  const r = spawnSync('powershell.exe', ['-NoProfile', '-Command', ps], {
    stdio: 'inherit',
    windowsHide: true,
    timeout: 1000 * 60 * 25,
  });
  if (r.status !== 0) throw new Error(`解压失败 (status=${r.status}): ${zipPath}`);
  return Math.round((Date.now() - started) / 1000);
}

async function loadPlatformCompat() {
  const mod = await import(pathToFileURL(path.join(REPO_ROOT, 'src', 'platform-compat.js')).href);
  return mod.default || mod;
}

// getPythonRuntimeExecutable 住在 core/shared-backend/runtime-paths.js，
// 不在 platform-compat（后者只有 getRuntimeBinCandidates）。必须导入真实模块，
// 否则判定会退化成 undefined 而误报 Python 未命中。
async function loadRuntimePaths() {
  const p = path.join(REPO_ROOT, 'core', 'shared-backend', 'runtime-paths.js');
  const mod = await import(pathToFileURL(p).href);
  return mod.default || mod;
}

async function verifyR(compat) {
  const spec = ARTIFACTS.r;
  console.log(`\n=== R 运行时首用验证 ===`);
  if (!fs.existsSync(spec.zip)) return check('制品 zip 存在', false, spec.zip);

  const runtimeDir = path.join(RUNTIMES_DIR, 'R');
  nukeDir(runtimeDir);
  const secs = unzipTo(spec.zip, runtimeDir);
  console.log(`  (解压耗时 ${secs}s)`);
  const flattened = flattenNested(runtimeDir);
  check('flatten 剥掉单层顶层目录', flattened === 'R', `flattened=${flattened}`);

  // resolveRuntime 优先级 1 的真实判定：bin/ 下任一候选存在
  const candidates = compat.getRuntimeBinCandidates('r', 'win32');
  const hit = candidates.find((c) => fs.existsSync(path.join(runtimeDir, 'bin', c)));
  check('resolveRuntime 优先级1 命中', Boolean(hit), hit ? `bin/${hit}` : `候选=${candidates.join(',')}`);
  if (!hit) return false;

  const rscript = path.join(runtimeDir, 'bin', 'Rscript.exe');
  const runR = (expr) =>
    spawnSync(rscript, ['-e', expr], { encoding: 'utf8', timeout: 1000 * 60 * 5 });

  const ver = runR('cat(paste0(R.version$major,".",R.version$minor))');
  const verOut = (ver.stdout || '').trim();
  check(`R 版本 == ${spec.expectVersion}`, verOut === spec.expectVersion, `实测 ${verOut || '(无输出)'}`);

  const libs = runR('cat(length(list.files(.libPaths()[1])))');
  const libCount = parseInt((libs.stdout || '').trim(), 10);
  check('library 包数 > 200（科学栈已装）', libCount > 200, `实测 ${libCount}`);

  // 科学栈真实可加载 —— 这是「能不能干活」的核心判据
  const sci = ['DESeq2', 'ggplot2', 'clusterProfiler', 'WGCNA', 'pheatmap'];
  for (const pkg of sci) {
    const r = runR(`suppressMessages(library(${pkg})); cat(as.character(packageVersion("${pkg}")))`);
    const v = (r.stdout || '').trim();
    check(`library(${pkg}) 可加载`, r.status === 0 && Boolean(v), v || (r.stderr || '').trim().split('\n').pop());
  }

  const bioc = runR('cat(as.character(BiocManager::version()))');
  const biocV = (bioc.stdout || '').trim();
  check('Bioconductor == 3.22', biocV === '3.22', `实测 ${biocV || '(无输出)'}`);

  return results.filter((x) => !x.ok).length === 0;
}

async function verifyPython(runtimePaths) {
  const spec = ARTIFACTS.python;
  console.log(`\n=== Python 运行时首用验证 ===`);
  if (!fs.existsSync(spec.zip)) return check('制品 zip 存在', false, spec.zip);

  const runtimeDir = path.join(RUNTIMES_DIR, 'Python');
  nukeDir(runtimeDir);
  const secs = unzipTo(spec.zip, runtimeDir);
  console.log(`  (解压耗时 ${secs}s)`);
  const flattened = flattenNested(runtimeDir);
  check('flatten 剥掉单层顶层目录', flattened === 'Python', `flattened=${flattened}`);

  // 用生产同一个判定函数，不自建第二套候选列表
  const exe = runtimePaths.getPythonRuntimeExecutable(runtimeDir, 'win32');
  check('resolveRuntime 优先级1 命中', Boolean(exe), exe ? path.relative(runtimeDir, exe) : '未命中');
  if (!exe) return false;

  const runPy = (code) => spawnSync(exe, ['-c', code], { encoding: 'utf8', timeout: 1000 * 60 * 5 });

  const ver = runPy('import sys;print("%d.%d.%d"%sys.version_info[:3])');
  const verOut = (ver.stdout || '').trim();
  check(`Python 版本 == ${spec.expectVersion}`, verOut === spec.expectVersion, `实测 ${verOut || '(无输出)'}`);

  for (const mod of ['numpy', 'pandas', 'scipy', 'matplotlib', 'anndata', 'scanpy']) {
    const r = runPy(`import ${mod};print(getattr(${mod},"__version__","?"))`);
    const v = (r.stdout || '').trim();
    check(`import ${mod}`, r.status === 0 && Boolean(v), v || (r.stderr || '').trim().split('\n').pop());
  }

  return results.filter((x) => !x.ok).length === 0;
}

async function main() {
  console.log('Windows Runtime 首用隔离验证');
  console.log(`  隔离数据目录: ${DATA_DIR}`);
  console.log(`  (刻意避开 Documents/Petri-Local，不污染用户默认数据目录)`);

  const compat = await loadPlatformCompat();
  const runtimePaths = await loadRuntimePaths();
  fs.mkdirSync(RUNTIMES_DIR, { recursive: true });

  if (only !== 'python') await verifyR(compat);
  if (only !== 'r') await verifyPython(runtimePaths);

  const failed = results.filter((x) => !x.ok);
  console.log(`\n=== 汇总 ===`);
  console.log(`  通过 ${results.length - failed.length} / ${results.length}`);
  if (failed.length) {
    console.log('  失败项:');
    for (const f of failed) console.log(`    - ${f.label} (${f.detail})`);
  }
  if (KEEP) {
    console.log(`\n  解压树保留在 ${RUNTIMES_DIR}`);
    console.log(`  清理: node -e "..." 或手动删除（约 3.2GB）`);
  }
  process.exit(failed.length ? 1 : 0);
}

main().catch((e) => fail(e.stack || e.message, 2));

/**
 * content-sync.ts — 桌面版内容增量同步
 *
 * 启动时（及每 4 小时）检查远端 manifest，下载变化的文件到本地。
 * 同步范围：前端静态站（HTML/JS/CSS）+ R 脚本 + Demo 数据 + copilot-index.json
 *
 * 文件级 diff：对比 SHA256，只下载变化的文件。
 */

const { app } = require('electron');
const path = require('path');
const fs = require('fs');
const https = require('https');
const crypto = require('crypto');

const MANIFEST_URL =
  process.env.PETRI_CONTENT_MANIFEST_URL ||
  'https://petri-uploads.oss-cn-hangzhou.aliyuncs.com/desktop/content-manifest.json';
const CONTENT_BASE =
  process.env.PETRI_CONTENT_BASE ||
  'https://petri-uploads.oss-cn-hangzhou.aliyuncs.com/desktop/content/';

const USER_DATA_DIR =
  process.env.PETRI_LOCAL_DATA_DIR || path.join(app.getPath('documents'), 'Petri-Local');
const LOCAL_CONTENT_DIR = path.join(USER_DATA_DIR, 'content');
const LOCAL_HASH_FILE = path.join(LOCAL_CONTENT_DIR, 'file-hash.json');

// 并发下载限制
const MAX_CONCURRENT = 5;

// ── 下载文件 ───────────────────────────────────────────────────

function downloadFile(url, destPath) {
  return new Promise((resolve, reject) => {
    fs.mkdirSync(path.dirname(destPath), { recursive: true });
    const file = fs.createWriteStream(destPath);
    const req = https.get(url, (res) => {
      if (res.statusCode !== 200) {
        file.close();
        try {
          fs.unlinkSync(destPath);
        } catch {}
        return reject(new Error(`HTTP ${res.statusCode}`));
      }
      res.pipe(file);
      file.on('finish', () => {
        file.close(() => resolve(destPath));
      });
    });
    req.on('error', (e) => {
      file.close();
      try {
        fs.unlinkSync(destPath);
      } catch {}
      reject(e);
    });
    req.on('timeout', () => {
      req.destroy();
      reject(new Error('下载超时'));
    });
  });
}

// ── 并发控制 ───────────────────────────────────────────────────

async function mapLimit(items, limit, fn) {
  const results = [];
  let index = 0;
  const workers = [];
  for (let i = 0; i < limit; i++) {
    workers.push(
      (async () => {
        while (index < items.length) {
          const current = index++;
          try {
            results[current] = await fn(items[current]);
          } catch (e) {
            results[current] = { error: e.message };
          }
        }
      })()
    );
  }
  await Promise.all(workers);
  return results;
}

// ── 主同步逻辑 ─────────────────────────────────────────────────

async function syncContent() {
  console.log('[content-sync] checking for updates...');

  // 1. 下载远端 manifest
  const remoteManifest = await fetchJson(MANIFEST_URL);
  if (!remoteManifest || !remoteManifest.files) {
    console.warn('[content-sync] no valid manifest from remote');
    return;
  }

  // 2. 加载本地 hash
  let localHashes = {};
  try {
    localHashes = JSON.parse(fs.readFileSync(LOCAL_HASH_FILE, 'utf8'));
  } catch {}

  // 3. 找变化文件
  const changed = [];
  const removed = [];
  for (const [file, hash] of Object.entries(remoteManifest.files)) {
    if (localHashes[file] !== hash) {
      changed.push(file);
    }
  }
  for (const file of Object.keys(localHashes)) {
    if (!remoteManifest.files[file]) {
      removed.push(file);
    }
  }

  if (changed.length === 0 && removed.length === 0) {
    console.log('[content-sync] already up to date');
    return;
  }

  console.log(`[content-sync] ${changed.length} files to download, ${removed.length} to remove`);

  // 4. 下载变化文件（并发）
  let successCount = 0;
  let failCount = 0;
  await mapLimit(changed, MAX_CONCURRENT, async (file) => {
    const localPath = path.join(LOCAL_CONTENT_DIR, file);
    try {
      await downloadFile(CONTENT_BASE + encodeURI(file), localPath);
      successCount++;
    } catch (e) {
      console.warn(`[content-sync] download failed: ${file}: ${e.message}`);
      failCount++;
    }
  });

  // 5. 删除已移除文件
  for (const file of removed) {
    try {
      fs.unlinkSync(path.join(LOCAL_CONTENT_DIR, file));
    } catch {}
  }

  // 6. 更新本地 hash（只记录成功下载的）
  const newHashes = {};
  for (const [file, hash] of Object.entries(remoteManifest.files)) {
    if (!changed.includes(file) || fs.existsSync(path.join(LOCAL_CONTENT_DIR, file))) {
      newHashes[file] = hash;
    }
  }
  fs.mkdirSync(LOCAL_CONTENT_DIR, { recursive: true });
  fs.writeFileSync(LOCAL_HASH_FILE, JSON.stringify(newHashes, null, 2));

  console.log(
    `[content-sync] done: ${successCount} downloaded, ${failCount} failed, ${removed.length} removed`
  );

  // 7. 通知 petri-server 内容更新（R 脚本是运行时读盘，无需重载）
  if (globalThis._petriContentUpdated) {
    try {
      globalThis._petriContentUpdated();
    } catch {}
  }
}

// ── 辅助：fetch JSON ──────────────────────────────────────────

function fetchJson(url) {
  return new Promise((resolve) => {
    let buf = '';
    const req = https.get(url, { timeout: 15000 }, (res) => {
      if (res.statusCode !== 200) {
        return resolve(null);
      }
      res.on('data', (c) => (buf += c));
      res.on('end', () => {
        try {
          resolve(JSON.parse(buf));
        } catch {
          resolve(null);
        }
      });
    });
    req.on('error', () => resolve(null));
    req.on('timeout', () => {
      try {
        req.destroy();
      } catch {}
      resolve(null);
    });
  });
}

module.exports = { syncContent, LOCAL_CONTENT_DIR };

/**
 * src/database/_db-singleton.js
 *
 * Single source of truth for desktop main-process SQLite access.
 *
 * BLOCK-10 PHASE 1.1 — A-007 + PR-012 + E-019 full.
 *
 * Why this file exists:
 *   src/database/branch-db.js and src/database/result-db.js both opened the
 *   same `petri.db` file with their own _dbCache + new Database() + close
 *   pair — 30 lines of infrastructure duplicated verbatim (A-007). Worse,
 *   each call to `new Database(filePath)` opens another sqlite3 handle; in
 *   better-sqlite3's WAL mode that's tolerable for readers but compounds
 *   writer-lock contention when both modules are live in IPC handlers and
 *   MCP-server code paths (PR-012). And neither module set `journal_mode =
 *   WAL` nor `busy_timeout`, so writes from `core/petri-server/db.js` (which
 *   does set them) raced the desktop handlers (E-019).
 *
 * What this module provides:
 *   - openDb(role)         → returns the singleton Database for that role
 *                            (one connection per process per file path).
 *   - closeDb(role)        → closes and forgets the role's connection.
 *   - closeAll()           → closes every cached connection.
 *   - _reset()             → closeAll() (test-only escape hatch).
 *
 * `branch` and `result` both resolve to the same `petri.db` under
 * PETRI_LOCAL_DATA_DIR (legacy single-file layout, preserved 100%); the
 * role key only exists so callers don't reach across module boundaries.
 * PR-012 dedup happens because openDb caches by resolved file path, not by
 * role string — the second call returns the same Database instance.
 *
 * E-019 full: the connection is opened with journal_mode=WAL and
 * busy_timeout = getBusyTimeout() (canonical source: shared-backend
 * config-helper.js → getDbConfig().busyTimeoutMs, default 10000ms). Every
 * SQLite handle in the desktop + petri-server process family now uses the
 * same value via the same config helper.
 *
 * 100% backward compatible:
 *   branch-db.js / result-db.js keep their public exports (getDatabase,
 *   closeDatabase, getDatabasePath) and re-export them as thin shims over
 *   this singleton, so existing IPC handlers and petri-server MCP code that
 *   imported them keep working without changes.
 */

const path = require('path');
const { loadDatabaseConstructor } = require('../migration-runner');
const { getBusyTimeout } = require('../../core/shared-backend/config-helper');

const VALID_ROLES = new Set(['branch', 'result']);
const _connections = new Map(); // resolved file path → better-sqlite3 Database

function _getDbPath(role) {
  if (!VALID_ROLES.has(role)) {
    throw new Error(`Unknown db role: ${role}; expected one of ${[...VALID_ROLES].join(', ')}`);
  }
  const dataDir = process.env.PETRI_LOCAL_DATA_DIR;
  if (!dataDir) {
    throw new Error('PETRI_LOCAL_DATA_DIR environment variable is not set');
  }
  // Legacy single-file layout: branch-db.js + result-db.js both opened
  // `petri.db`. Keep that exact filename so the singleton never silently
  // moves an existing user's data (PR-012 dedup is per-process, not per-file).
  return path.join(dataDir, 'petri.db');
}

/**
 * Open (or return cached) SQLite connection for the given logical role.
 * Same file path → same Database instance (PR-012 dedup).
 * @param {'branch'|'result'} role
 * @returns {import('better-sqlite3').Database}
 */
function openDb(role) {
  const dbPath = _getDbPath(role);
  if (_connections.has(dbPath)) {
    return _connections.get(dbPath);
  }
  const Database = loadDatabaseConstructor();
  const db = new Database(dbPath);
  // Apply the canonical WAL + busy_timeout from config-helper (E-019 full).
  // Setting busy_timeout on every open guarantees that even when called
  // before any petri-server child process is spawned, the desktop handle is
  // already consistent with petri-server's policy.
  db.pragma(`journal_mode = WAL`);
  db.pragma(`busy_timeout = ${getBusyTimeout()}`);
  // foreign_keys=ON matches shared-backend/db.js behavior and prevents
  // accidental ON DELETE CASCADE surprises across the two db modules.
  db.pragma(`foreign_keys = ON`);
  _connections.set(dbPath, db);
  return db;
}

/**
 * Close the connection associated with a role. Safe to call when no
 * connection is cached.
 * @param {'branch'|'result'} role
 */
function closeDb(role) {
  const dbPath = _getDbPath(role);
  const db = _connections.get(dbPath);
  if (!db) return;
  try {
    db.close();
  } catch (_) {
    // already closed or never opened — match db.js closeDatabase tolerance
  }
  _connections.delete(dbPath);
}

/** Close every cached connection. Safe to call repeatedly. */
function closeAll() {
  for (const [dbPath, db] of _connections) {
    try {
      db.close();
    } catch (_) {
      // ignore — match the swallow-when-already-closed contract
    }
    _connections.delete(dbPath);
  }
}

/**
 * Test-only escape hatch: drop every cached connection without touching
 * any other module-level state. Use in test setup/teardown so each case
 * starts with a clean singleton.
 */
function _reset() {
  closeAll();
}

module.exports = {
  openDb,
  closeDb,
  closeAll,
  _reset,
  VALID_ROLES: [...VALID_ROLES],
};

// ============================================================
// Result Database Module
//
// Phase 2: Shared results across branches (project-scoped, not branch-scoped)
//
// Design:
//   - Results are scoped to projects, NOT branches
//   - Branch switching does not affect results
//   - Each result tracks which branch created it (sourceBranchId)
//   - Result versions track historical snapshots for reproducibility
//
// BLOCK-10 PHASE 1.1 (A-007 + PR-012 + E-019 full):
//   The 30 lines of singleton infrastructure (path resolution, _dbCache,
//   new Database(), journal_mode/busy_timeout pragmas, close) are now
//   centralized in src/database/_db-singleton.js. This module is a thin
//   wrapper that delegates every connection to openDb('result'), and
//   keeps its public exports (getDatabase, getDatabasePath, closeDatabase)
//   as shims for backward compatibility. branch-db.js + result-db.js
//   resolve to the same connection for the same file path (PR-012).
// ============================================================

const { openDb, closeDb } = require('./_db-singleton');

/**
 * Backward-compatible Database accessor. Returns the singleton connection
 * for the result role. Same identity as branch-db.getDatabase() because
 * both roles share the same petri.db file (PR-012 dedup).
 * @returns {import('better-sqlite3').Database}
 */
function getDatabase() {
  return openDb('result');
}

/**
 * Backward-compatible DB path accessor.
 * @returns {string}
 */
function getDatabasePath() {
  const path = require('path');
  const dataDir = process.env.PETRI_LOCAL_DATA_DIR;
  if (!dataDir) {
    throw new Error('PETRI_LOCAL_DATA_DIR environment variable is not set');
  }
  return path.join(dataDir, 'petri.db');
}

/**
 * Backward-compatible close. Closes the singleton connection for the
 * result role (same connection as branch-db.closeDatabase()).
 */
function closeDatabase() {
  closeDb('result');
}

// ============================================================
// Result Operations
// ============================================================

/**
 * Create a new result
 * @param {string} id - Result ID (UUID v4)
 * @param {string} projectId - Project ID this result belongs to
 * @param {string} type - Result type: 'chart' | 'table' | 'code' | 'text' | 'file'
 * @param {string} name - Human-readable result name
 * @param {unknown} data - Result data payload
 * @param {Record<string, unknown>} [config] - Optional display config
 * @param {string|null} [sourceBranchId=null] - Branch that created this result
 * @returns {object} Created result object
 */
function createResult(id, projectId, type, name, data, config = null, sourceBranchId = null) {
  const db = getDatabase();
  const now = Date.now();
  const dataJson = JSON.stringify(data);
  const configJson = config ? JSON.stringify(config) : null;
  const stmt = db.prepare(`
    INSERT INTO results (id, project_id, type, name, data, config, source_branch_id, created_at, updated_at)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
  `);
  stmt.run(id, projectId, type, name, dataJson, configJson, sourceBranchId, now, now);
  return {
    id,
    projectId,
    type,
    name,
    data,
    config,
    sourceBranchId,
    createdAt: now,
    updatedAt: now,
  };
}

/**
 * Get a result by ID
 * @param {string} id - Result ID
 * @returns {object|null} Result object or null
 */
function getResult(id) {
  const db = getDatabase();
  const stmt = db.prepare('SELECT * FROM results WHERE id = ?');
  const row = stmt.get(id);
  if (!row) return null;
  return deserializeResult(row);
}

/**
 * List results for a project
 * @param {string} projectId - Project ID
 * @param {object} [options] - Query options
 * @param {string} [options.type] - Filter by type
 * @param {number} [options.limit=100] - Result limit
 * @param {number} [options.offset=0] - Offset
 * @param {string} [options.sortBy='updatedAt'] - Sort field
 * @param {string} [options.sortDir='desc'] - Sort direction
 * @returns {Array} List of result summaries
 */
function listResults(projectId, options = {}) {
  const db = getDatabase();
  const {
    type,
    limit = 100,
    offset = 0,
    sortBy = 'updatedAt',
    sortDir = 'desc',
  } = options;

  const columnMap = {
    updatedAt: 'updated_at',
    createdAt: 'created_at',
    name: 'name',
  };
  const sortColumn = columnMap[sortBy] || 'updated_at';
  const sortDirection = sortDir === 'asc' ? 'ASC' : 'DESC';

  let sql = `SELECT id, project_id, type, name, source_branch_id, updated_at FROM results WHERE project_id = ?`;
  const params = [projectId];

  if (type) {
    sql += ' AND type = ?';
    params.push(type);
  }

  sql += ` ORDER BY ${sortColumn} ${sortDirection} LIMIT ? OFFSET ?`;
  params.push(limit, offset);

  const stmt = db.prepare(sql);
  const rows = stmt.all(...params);

  return rows.map((row) => ({
    id: row.id,
    projectId: row.project_id,
    type: row.type,
    name: row.name,
    sourceBranchId: row.source_branch_id,
    updatedAt: row.updated_at,
  }));
}

/**
 * Update a result
 * @param {string} id - Result ID
 * @param {object} updates - Fields to update
 * @param {string} [updates.name] - New name
 * @param {unknown} [updates.data] - New data payload
 * @param {Record<string, unknown>} [updates.config] - New config
 * @returns {object|null} Updated result or null if not found
 */
function updateResult(id, updates) {
  const db = getDatabase();
  const now = Date.now();
  const fields = ['updated_at = ?'];
  const params = [now];

  if (updates.name !== undefined) {
    fields.push('name = ?');
    params.push(updates.name);
  }
  if (updates.data !== undefined) {
    fields.push('data = ?');
    params.push(JSON.stringify(updates.data));
  }
  if (updates.config !== undefined) {
    fields.push('config = ?');
    params.push(updates.config ? JSON.stringify(updates.config) : null);
  }

  params.push(id);
  const stmt = db.prepare(`UPDATE results SET ${fields.join(', ')} WHERE id = ?`);
  const result = stmt.run(...params);

  if (result.changes === 0) return null;
  return getResult(id);
}

/**
 * Delete a result and its versions
 * @param {string} id - Result ID
 * @returns {boolean} Whether deletion succeeded
 */
function deleteResult(id) {
  const db = getDatabase();
  // Delete versions first (cascade should handle this, but be explicit)
  const deleteVersions = db.prepare('DELETE FROM result_versions WHERE result_id = ?');
  const deleteResultStmt = db.prepare('DELETE FROM results WHERE id = ?');

  const tx = db.transaction(() => {
    deleteVersions.run(id);
    const result = deleteResultStmt.run(id);
    return result.changes > 0;
  });

  return tx();
}

/**
 * Get results by project (full objects)
 * @param {string} projectId - Project ID
 * @param {object} [options] - Query options
 * @returns {Array} Full result objects
 */
function getResultsByProject(projectId, options = {}) {
  const db = getDatabase();
  const { type, limit = 100, offset = 0 } = options;

  let sql = 'SELECT * FROM results WHERE project_id = ?';
  const params = [projectId];

  if (type) {
    sql += ' AND type = ?';
    params.push(type);
  }

  sql += ' ORDER BY updated_at DESC LIMIT ? OFFSET ?';
  params.push(limit, offset);

  const stmt = db.prepare(sql);
  const rows = stmt.all(...params);
  return rows.map(deserializeResult);
}

// ============================================================
// Result Version Operations
// ============================================================

/**
 * Create a result version (snapshot)
 * @param {string} id - Version ID (UUID v4)
 * @param {string} resultId - Parent result ID
 * @param {number} version - Version number
 * @param {unknown} data - Data snapshot
 * @param {Record<string, unknown>} [config] - Config snapshot
 * @param {string|null} [createdByBranchId=null] - Branch that created this version
 * @returns {object} Created version object
 */
function createResultVersion(id, resultId, version, data, config = null, createdByBranchId = null) {
  const db = getDatabase();
  const now = Date.now();
  const dataJson = JSON.stringify(data);
  const configJson = config ? JSON.stringify(config) : null;
  const stmt = db.prepare(`
    INSERT INTO result_versions (id, result_id, version, data, config, created_at, created_by_branch_id)
    VALUES (?, ?, ?, ?, ?, ?, ?)
  `);
  stmt.run(id, resultId, version, dataJson, configJson, now, createdByBranchId);
  return {
    id,
    resultId,
    version,
    data,
    config,
    createdAt: now,
    createdByBranchId,
  };
}

/**
 * Get the latest version number for a result
 * @param {string} resultId - Result ID
 * @returns {number} Latest version number, or 0 if no versions exist
 */
function getLatestVersionNumber(resultId) {
  const db = getDatabase();
  const stmt = db.prepare('SELECT MAX(version) as max_version FROM result_versions WHERE result_id = ?');
  const row = stmt.get(resultId);
  return row?.max_version || 0;
}

/**
 * Get a specific version
 * @param {string} id - Version ID
 * @returns {object|null} Version object or null
 */
function getResultVersion(id) {
  const db = getDatabase();
  const stmt = db.prepare('SELECT * FROM result_versions WHERE id = ?');
  const row = stmt.get(id);
  if (!row) return null;
  return deserializeVersion(row);
}

/**
 * List versions for a result
 * @param {string} resultId - Result ID
 * @param {number} [limit=50] - Max versions to return
 * @param {number} [offset=0] - Offset
 * @returns {Array} Version objects, newest first
 */
function listResultVersions(resultId, limit = 50, offset = 0) {
  const db = getDatabase();
  const stmt = db.prepare(`
    SELECT * FROM result_versions
    WHERE result_id = ?
    ORDER BY version DESC
    LIMIT ? OFFSET ?
  `);
  const rows = stmt.all(resultId, limit, offset);
  return rows.map(deserializeVersion);
}

/**
 * Delete all versions for a result
 * @param {string} resultId - Result ID
 * @returns {number} Number of deleted versions
 */
function deleteResultVersions(resultId) {
  const db = getDatabase();
  const stmt = db.prepare('DELETE FROM result_versions WHERE result_id = ?');
  const result = stmt.run(resultId);
  return result.changes;
}

// ============================================================
// Serialization Helpers
// ============================================================

function deserializeResult(row) {
  return {
    id: row.id,
    projectId: row.project_id,
    type: row.type,
    name: row.name,
    data: row.data ? JSON.parse(row.data) : null,
    config: row.config ? JSON.parse(row.config) : null,
    sourceBranchId: row.source_branch_id,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

function deserializeVersion(row) {
  return {
    id: row.id,
    resultId: row.result_id,
    version: row.version,
    data: row.data ? JSON.parse(row.data) : null,
    config: row.config ? JSON.parse(row.config) : null,
    createdAt: row.created_at,
    createdByBranchId: row.created_by_branch_id,
  };
}

module.exports = {
  // Database
  getDatabase,
  getDatabasePath,
  closeDatabase,
  // Result CRUD
  createResult,
  getResult,
  listResults,
  updateResult,
  deleteResult,
  getResultsByProject,
  // Result Versions
  createResultVersion,
  getLatestVersionNumber,
  getResultVersion,
  listResultVersions,
  deleteResultVersions,
};

