  ipcMain.handle(CHANNELS.telemetry.report, async (_event, payload) => {
    try {
      const { reportError } = require("../telemetry");
      return await reportError(payload);
    } catch (e) {
      // 遥测自身异常绝不能影响业务——静默
      return { ok: false, reason: "internal" };
    }
