}

module.exports = { setupTelemetryIpc };

const CHANNELS = require('./channels');
// ============================================================
// IPC handlers: terminal:snapshot, terminal:open-log-dir,
//               terminal:open-shell, terminal:session-start,
//               terminal:session-write, terminal:session-resize,
//               terminal:session-stop, terminal:session-list (8 handlers)
//
// Extracted from src/main.js by BLOCK-9.1 PHASE 4.
// Original location: src/main.js ~line 1134 (setupTerminalIpc).
//
// Dependencies injected via parameter:
//   - mainWindow: for terminal:data / terminal:exit events
//   - getProcs(): { rServerProc }
//   - getLogDir(): log directory path
//   - readLogTail(filePath): tail helper
//   - resolveCore: path resolver (duplicated for self-containment)
//   - node-pty: dynamic require inside session-start handler
//
// BLOCK-54 P2 — 多 Tab 用户终端：单例 shellProc → sessions Map（上限
// MAX_TERMINAL_TABS=4，对齐 codex 64 上限哲学取 GUI 小值）。IPC 全量
// additive 兼容：旧调用不带 sessionId = 'default' tab（既有单会话语义
// 不变）；新调用带 sessionId 各自成会话。terminal:data / terminal:exit
// 事件 payload 带 sessionId 供 renderer 按 tab 路由。before-quit 遍历
// Map 全量 kill（对齐 codex terminate_all_processes）。
// ============================================================

const fs = require("fs");
const path = require("path");
const { ipcMain, app, shell } = require("electron");
const { getOpenShellPlan, getSessionShellSpec } =
  require("../platform-compat");
// BLOCK-59 P2 — 终端独立窗（升格 Tab）：mainWindow 广播之外，把
// terminal:data/exit 同步送达承载该会话的弹出窗（terminal:<sessionId>）。
// 弹出窗是同一 pty 会话的第二活视图，主窗 tab 保活零丢失。
const { forwardToContentWindow } = require("./window-manager");

// resolveCore mirror (self-contained, identical to main.js logic)
function resolveCore(...parts) {
  const IS_DEV = !app.isPackaged;
  if (IS_DEV) {
    return path.join(__dirname, "..", "..", "core");
  }
  return path.join(process.resourcesPath, "core");
}

const MAX_TERMINAL_TABS = 4;
const DEFAULT_SESSION_ID = "default";

/** 旧调用（不传 sessionId / 传非字符串）归一到 default tab。 */
function normalizeSessionId(value) {
  if (typeof value === "string" && value.trim()) return value.trim().slice(0, 64);
  return DEFAULT_SESSION_ID;
}

function setupTerminalIpc({ mainWindow, getProcs, getLogDir, readLogTail } = {}) {
  // sessionId → { proc, disposeData, disposeExit, cwd, pid }
  const sessions = new Map();

  const sendTerminalEvent = (channel, payload) => {
    if (mainWindow && !mainWindow.isDestroyed()) {
      mainWindow.webContents.send(channel, payload);
    }
    // BLOCK-59 P2 — 独立终端窗转发（无弹出窗时 no-op）。
    if (payload && typeof payload.sessionId === "string") {
      forwardToContentWindow(`terminal:${payload.sessionId}`, channel, payload);
    }
  };

  const killSession = (sessionId) => {
    const session = sessions.get(sessionId);
    if (!session) return false;
    sessions.delete(sessionId);
    try {
      session.proc.kill();
    } catch {}
    session.disposeData?.dispose();
    session.disposeExit?.dispose();
    return true;
  };

  const killAllSessions = () => {
    for (const sessionId of [...sessions.keys()]) {
      killSession(sessionId);
    }
  };

  ipcMain.handle(CHANNELS.terminal.snapshot, async () => {
    try {
      const logDir = getLogDir();
      // Snapshot the procs at handler invocation time so a stale
      // proc that exited during the IPC round-trip is observed.
      // BLOCK-30 P1: py-server 服务已摘除，进程清单不再包含它。
      // BLOCK-51 P3: plumber 空壳已清理，进程清单不再包含它。
      const { rServerProc } = getProcs();
      const processes = [
        {
          id: "petri-server",
          label: "R 后端",
          command: `node ${resolveCore("petri-server", "server.js")}`,
          status: rServerProc && !rServerProc.killed ? "running" : "stopped",
          pid: rServerProc?.pid || null,
          logPath: path.join(logDir, "petri-server.log"),
          output: readLogTail(path.join(logDir, "petri-server.log")),
        },
      ];
      return {
        ok: true,
        logDir,
        dataDir: process.env.PETRI_LOCAL_DATA_DIR || null,
        processes,
      };
    } catch (e) {
      return { ok: false, error: e.message, processes: [] };
    }
  });

  ipcMain.handle(CHANNELS.terminal.openLogDir, async () => {
    try {
      const logDir = getLogDir();
      if (!fs.existsSync(logDir)) fs.mkdirSync(logDir, { recursive: true });
      const error = await shell.openPath(logDir);
      return error ? { ok: false, error } : { ok: true, path: logDir };
    } catch (e) {
      return { ok: false, error: e.message };
    }
  });

  ipcMain.handle(CHANNELS.terminal.openShell, async (_event, targetPath) => {
    try {
      const cwd =
        typeof targetPath === "string" && targetPath.trim()
          ? targetPath.trim()
          : process.env.PETRI_LOCAL_DATA_DIR || process.env.PETRI_PROJECT_ROOT;
      const plan = getOpenShellPlan(cwd, process.platform);
      // BLOCK-102 P1 — spawn 的 ENOENT 是异步 error 事件，同步 try/catch 拦不住、
      // 也不能立刻报 ok。等一小窗让 error 事件到达后再如实回执（错误不再静默、
      // 不再产生无监听 error 事件的主进程 uncaughtException）。
      const spawnDetached = (command, args, opts) => new Promise((resolve) => {
        const { spawn } = require("child_process");
        let child;
        try {
          child = spawn(command, args, opts);
        } catch (e) {
          resolve({ ok: false, error: e.message });
          return;
        }
        let settled = false;
        child.once("error", (err) => {
          if (settled) return;
          settled = true;
          resolve({ ok: false, error: err.message });
        });
        setTimeout(() => {
          if (settled) return;
          settled = true;
          child.unref();
          resolve({ ok: true });
        }, 150);
      });
      if (plan.type === "osascript") {
        const r = await spawnDetached(plan.command, plan.args, {
          detached: plan.detached,
          stdio: plan.stdio,
        });
        return r.ok ? { ok: true, path: cwd } : r;
      }
      if (plan.type === "cmd") {
        const r = await spawnDetached(plan.command, plan.args, {
          detached: plan.detached,
          stdio: plan.stdio,
          windowsHide: plan.windowsHide,
        });
        return r.ok ? { ok: true, path: cwd } : r;
      }
      for (const terminal of plan.candidates) {
        const r = await spawnDetached(terminal, plan.args, {
          detached: plan.detached,
          stdio: plan.stdio,
        });
        if (r.ok) return { ok: true, path: cwd };
      }
      return { ok: false, error: "未找到可用的系统终端" };
    } catch (e) {
      return { ok: false, error: e.message };
    }
  });

  // BLOCK-54 P2 — args 兼容两种形态：string（旧，targetPath，default tab）/
  // { sessionId, targetPath }（新）。
  ipcMain.handle(CHANNELS.terminal.sessionStart, async (_event, args) => {
    try {
      const isObject = args && typeof args === "object";
      const sessionId = normalizeSessionId(isObject ? args.sessionId : null);
      const targetPath = isObject ? args.targetPath : args;
      const existing = sessions.get(sessionId);
      if (existing) {
        return { ok: true, pid: existing.pid, reused: true, sessionId };
      }
      if (sessions.size >= MAX_TERMINAL_TABS) {
        return {
          ok: false,
          error: `终端标签已达上限 ${MAX_TERMINAL_TABS} 个，请先关闭不用的标签`,
          limitReached: true,
        };
      }
      const requestedCwd =
        typeof targetPath === "string" && targetPath.trim()
          ? targetPath.trim()
          : "";
      // BLOCK-67 P3：SSH 远程项目终端 —— pty 直挂 `ssh -tt <alias>`，
      // 远端先 cd 到项目 remote_path 再进登录 shell（远程唯一工作目录语义）。
      if (isObject && args.ssh && args.ssh.alias && args.ssh.remotePath) {
        const alias = String(args.ssh.alias).replace(/[^A-Za-z0-9._-]/g, "");
        const remotePath = String(args.ssh.remotePath).replace(/[^A-Za-z0-9._\/@ +-]/g, "");
        const pty = require("node-pty");
        // Windows 实测教训：ssh.exe 作为 conpty 直接 shell 会让 node-pty 的
        // conpty_console_list_agent（getConsoleProcessList）崩掉整个主进程——
        // 改经 cmd.exe 包装（console 归 cmd，ssh 为其子进程）。
        const isWin = process.platform === "win32";
        const sshArgv = ["-o", "ConnectTimeout=10", "-tt", alias, `cd "${remotePath}" && exec $SHELL -l`];
        const proc = isWin
          ? pty.spawn("cmd.exe", ["/c", "ssh", ...sshArgv], {
          name: "xterm-256color",
          cols: 100,
          rows: 28,
          cwd: process.env.PETRI_LOCAL_DATA_DIR || process.env.PETRI_PROJECT_ROOT || ".",
          env: { ...process.env, TERM: "xterm-256color", COLORTERM: "truecolor" },
        })
          : pty.spawn("ssh", sshArgv, {
          name: "xterm-256color",
          cols: 100,
          rows: 28,
          cwd: process.env.PETRI_LOCAL_DATA_DIR || process.env.PETRI_PROJECT_ROOT || ".",
          env: { ...process.env, TERM: "xterm-256color", COLORTERM: "truecolor" },
        });
        const disposeData = proc.onData((data) =>
          sendTerminalEvent(CHANNELS.terminal.data, { sessionId, data }),
        );
        const disposeExit = proc.onExit(({ exitCode, signal }) => {
          sendTerminalEvent(CHANNELS.terminal.exit, { sessionId, code: exitCode, signal });
          disposeData?.dispose();
          disposeExit?.dispose();
          sessions.delete(sessionId);
        });
        sessions.set(sessionId, {
          proc, disposeData, disposeExit,
          cwd: `${alias}:${remotePath}`,
          pid: proc.pid,
          ssh: { alias, remotePath },
        });
        return { ok: true, pid: proc.pid, cwd: `${alias}:${remotePath}`, shell: `ssh:${alias}`, sessionId };
      }
      const cwd =
        requestedCwd && fs.existsSync(requestedCwd)
          ? requestedCwd
          : process.env.PETRI_LOCAL_DATA_DIR || process.env.PETRI_PROJECT_ROOT;
      const { shellPath, args: shellArgs } = getSessionShellSpec(process.env, process.platform);
      const pty = require("node-pty");
      const proc = pty.spawn(shellPath, shellArgs, {
        name: "xterm-256color",
        cols: 100,
        rows: 28,
        cwd,
        env: { ...process.env, TERM: "xterm-256color", COLORTERM: "truecolor" },
      });
      const disposeData = proc.onData((data) =>
        sendTerminalEvent(CHANNELS.terminal.data, { sessionId, data }),
      );
      const disposeExit = proc.onExit(({ exitCode, signal }) => {
        sendTerminalEvent(CHANNELS.terminal.exit, { sessionId, code: exitCode, signal });
        disposeData?.dispose();
        disposeExit?.dispose();
        sessions.delete(sessionId);
      });
      sessions.set(sessionId, {
        proc,
        disposeData,
        disposeExit,
        cwd,
        pid: proc.pid,
      });
      return { ok: true, pid: proc.pid, cwd, shell: shellPath, sessionId };
    } catch (e) {
      return { ok: false, error: e.message };
    }
  });

  // BLOCK-54 P2 — input 兼容两种形态：string（旧，default tab）/ { sessionId, text }。
  ipcMain.handle(CHANNELS.terminal.sessionWrite, async (_event, input) => {
    const isObject = input && typeof input === "object";
    const sessionId = normalizeSessionId(isObject ? input.sessionId : null);
    const text = isObject ? String(input.text ?? "") : typeof input === "string" ? input : "";
    const session = sessions.get(sessionId);
    if (!session) {
      return { ok: false, error: "终端会话未启动" };
    }
    if (text.length > 32_768) return { ok: false, error: "输入内容过长" };
    session.proc.write(text);
    return { ok: true };
  });

  // BLOCK-54 P2 — dimensions 兼容两种形态：{ cols, rows }（旧，default）/
  // { cols, rows, sessionId }。
  ipcMain.handle(CHANNELS.terminal.sessionResize, async (_event, dimensions) => {
    const sessionId = normalizeSessionId(dimensions && typeof dimensions === "object" ? dimensions.sessionId : null);
    const session = sessions.get(sessionId);
    if (!session) return { ok: false, error: "终端会话未启动" };
    const cols = Math.max(2, Math.min(500, Number(dimensions?.cols) || 80));
    const rows = Math.max(1, Math.min(200, Number(dimensions?.rows) || 24));
    session.proc.resize(cols, rows);
    return { ok: true };
  });

  // BLOCK-54 P2 — args 兼容三种形态：undefined（旧，default）/ string sessionId /
  // { sessionId }。
  ipcMain.handle(CHANNELS.terminal.sessionStop, async (_event, args) => {
    const sessionId = normalizeSessionId(
      typeof args === "string" ? args : args && typeof args === "object" ? args.sessionId : null
    );
    if (!sessions.has(sessionId)) return { ok: true, wasRunning: false };
    killSession(sessionId);
    return { ok: true, wasRunning: true };
  });

  // BLOCK-54 P2 — tab 清单（id/cwd/pid/存活），供 renderer 恢复与展示。
  ipcMain.handle(CHANNELS.terminal.sessionList, async () => {
    const list = [...sessions.entries()].map(([sessionId, session]) => ({
      sessionId,
      pid: session.pid,
      cwd: session.cwd,
      running: true,
    }));
    return { ok: true, sessions: list, maxTabs: MAX_TERMINAL_TABS };
  });

  app.once("before-quit", () => {
    try {
      killAllSessions();
    } catch {}
  });
}

module.exports = { setupTerminalIpc, MAX_TERMINAL_TABS, DEFAULT_SESSION_ID };

const CHANNELS = require('./channels');
// ============================================================
// IPC handlers: window:pop-out, window:return, window:minimize,
//               window:restore, window:remove, window:snapshot,
//               window:self  (7 handlers)
//
// BLOCK-59 P0 — Electron adapter for the window manager core
// (src/main/_window-manager.js). The core owns the state
// machine and the route whitelist; this module owns
// BrowserWindow lifecycle, geometry persistence
// (userData/window-manager-state.json) and the
// window:state-changed multicast to every alive window.
//
// Immutable contract (plan §3): the renderer's × on a popped
// window DEMOTES it to the edge rail (close is intercepted and
// turned into hide). Real destruction happens only through
// window:remove from the rail, or at app quit.
// ============================================================

const fs = require("fs");
const path = require("path");
const { app, BrowserWindow, ipcMain, screen } = require("electron");
const {
  createWindowManagerCore,
  CONTENT_TYPES,
} = require("../main/_window-manager");
const { windowTitle } = require("../main/brand");

const GEOMETRY_RECORD_DEBOUNCE_MS = 400;
const RAIL_CONTENT_ID = "rail:";
// 轨道窗总宽 = 预览区 336 + 条带 28。hover 卡（320px）渲染在预览区内——
// 首版窗体只有 28px 宽，卡片整体被窗体裁剪（用户反馈「展示不全/hover 无预览」
// 的根因）。预览区透明 + ignoreMouseEvents 穿透，仅条带/卡交互时收鼠标。
const RAIL_WINDOW_WIDTH = 364;
const RAIL_STRIP_WIDTH = 28;
const THUMBNAIL_WIDTH = 480;

// BLOCK-59 P2 — 终端等会话型数据的受管窗口转发钩子。terminal.js 在
// mainWindow 广播之外经此把 terminal:data/exit 送达承载该会话的独立窗
// （contentId = `terminal:<sessionId>`）。setup 前调用为 no-op。
let forwardToContentWindowRef = null;
function forwardToContentWindow(contentId, channel, payload) {
  try {
    forwardToContentWindowRef?.(contentId, channel, payload);
  } catch {}
}

function setupWindowManagerIpc({
  getMainWindow,
  getSpaBaseUrl,
  resolveResource,
} = {}) {
  const statePath = () =>
    path.join(app.getPath("userData"), "window-manager-state.json");

  const core = createWindowManagerCore({
    loadState: () => {
      try {
        return JSON.parse(fs.readFileSync(statePath(), "utf8"));
      } catch {
        return null;
      }
    },
    saveState: (serialized) => {
      try {
        fs.mkdirSync(path.dirname(statePath()), { recursive: true });
        fs.writeFileSync(statePath(), JSON.stringify(serialized));
      } catch {}
    },
  });

  // contentId → { win, expectingClose, geometryTimer }
  const windows = new Map();
  // contentId → dataURL。降格瞬间（窗口仍可见）截取的内容快照，供轨道
  // hover 卡预览；隐藏状态下不重截（静态结果窗内容不变，终端/agent 卡
  // 标注「快照于降格时」）。remove/return 时清理。
  const thumbnails = new Map();
  let exiting = false;

  // ── Trusted-sender scoping ────────────────────────────────────
  // Main window may act on every content id; the rail window acts
  // on all entries too (hover-restore / explicit removal are the
  // rail's duties, plan §5); any other managed pop-out may act on
  // itself only. Foreign senders are rejected fail-closed.
  const resolveSenderScope = (event) => {
    const sender = event?.sender;
    if (!sender || sender.isDestroyed()) return null;
    const main = getMainWindow();
    if (main && !main.isDestroyed() && sender === main.webContents) {
      return { kind: "main" };
    }
    for (const [id, rec] of windows.entries()) {
      if (!rec.win.isDestroyed() && sender === rec.win.webContents) {
        return { kind: id === RAIL_CONTENT_ID ? "rail" : "managed", id };
      }
    }
    return null;
  };

  const isMutationAllowed = (scope, id) =>
    scope.kind === "main" ||
    scope.kind === "rail" ||
    (scope.kind === "managed" && scope.id === id);

  // ── Display / bounds helpers ──────────────────────────────────

  const currentDisplays = () => {
    try {
      const primary = screen.getPrimaryDisplay();
      const all = screen.getAllDisplays();
      return [primary, ...all.filter((d) => d.id !== primary.id)].map((d) => ({
        id: d.id,
        bounds: d.bounds,
        workArea: d.workArea,
      }));
    } catch {
      return [];
    }
  };

  const getMainBounds = () => {
    const main = getMainWindow();
    if (!main || main.isDestroyed()) return null;
    try {
      return typeof main.getNormalBounds === "function"
        ? main.getNormalBounds()
        : main.getBounds();
    } catch {
      return null;
    }
  };

  const displayIdForBounds = (bounds) => {
    try {
      return screen.getDisplayMatching(bounds)?.id ?? null;
    } catch {
      return null;
    }
  };

  const recordGeometryNow = (rec) => {
    if (!rec || rec.win.isDestroyed()) return;
    try {
      const bounds = rec.win.getBounds();
      core.recordGeometry(rec.id, {
        x: bounds.x,
        y: bounds.y,
        w: bounds.width,
        h: bounds.height,
        displayId: displayIdForBounds(bounds),
      });
    } catch {}
  };

  const scheduleGeometryRecord = (rec) => {
    if (!rec || rec.geometryTimer) return;
    rec.geometryTimer = setTimeout(() => {
      rec.geometryTimer = null;
      recordGeometryNow(rec);
    }, GEOMETRY_RECORD_DEBOUNCE_MS);
  };

  // BLOCK-59 加映二 —— 降格瞬间的内容快照（窗口仍可见时 capturePage 可靠；
  // 隐藏后截取会得到空帧）。失败静默：轨道卡回退纯文本展示。
  const captureThumbnail = async (rec) => {
    if (!rec || rec.win.isDestroyed()) return;
    try {
      const image = await rec.win.webContents.capturePage();
      if (!image || image.isEmpty()) return;
      const scaled = image.getSize().width > THUMBNAIL_WIDTH
        ? image.resize({ width: THUMBNAIL_WIDTH })
        : image;
      thumbnails.set(rec.id, scaled.toDataURL());
    } catch {}
  };

  // ── Window factory ────────────────────────────────────────────

  const broadcast = (payload) => {
    const targets = [];
    const main = getMainWindow();
    if (main && !main.isDestroyed()) targets.push(main);
    for (const rec of windows.values()) {
      if (!rec.win.isDestroyed()) targets.push(rec.win);
    }
    for (const win of targets) {
      try {
        win.webContents.send(CHANNELS.window.stateChanged, payload);
      } catch {}
    }
  };

  core.subscribe((event) => {
    broadcast(event);
    syncRailVisibility();
  });

  // ── 边缘活动轨道容器窗（BLOCK-59 P2，plan §5）─────────────────
  // 极窄 alwaysOnTop 条带：focusable:false 不抢键盘焦点 / skipTaskbar /
  // 透明窗体 + setIgnoreMouseEvents(true, {forward:true})——条带与 hover
  // 卡之外全部点击穿透给底层 app，渲染层在 mouseenter/leave 时切换。
  // 生命周期属 app 不属主窗（plan §5）；懒创建：第一个窗口被降格才建。
  const ensureRailWindow = () => {
    let rec = windows.get(RAIL_CONTENT_ID);
    if (rec && !rec.win.isDestroyed()) return rec;
    const spaBase = typeof getSpaBaseUrl === "function" ? getSpaBaseUrl() : null;
    if (!spaBase) return null;
    const displays = currentDisplays();
    const workArea = displays[0]?.workArea || displays[0]?.bounds || null;
    const height = Math.max(240, Math.min(600, (workArea ? workArea.height : 800) - 120));
    const win = new BrowserWindow({
      width: RAIL_WINDOW_WIDTH,
      height,
      x: workArea ? workArea.x + workArea.width - RAIL_WINDOW_WIDTH : undefined,
      y: workArea ? workArea.y + Math.floor((workArea.height - height) / 2) : undefined,
      frame: false,
      transparent: true,
      alwaysOnTop: true,
      skipTaskbar: true,
      focusable: false,
      resizable: false,
      minimizable: false,
      maximizable: false,
      fullscreenable: false,
      show: false,
      webPreferences: {
        preload: resolveResource("src", "preload.js"),
        contextIsolation: true,
        nodeIntegration: false,
        sandbox: true,
        webSecurity: true,
      },
    });
    try {
      win.setAlwaysOnTop(true, "floating");
      win.setVisibleOnAllWorkspaces(true, { visibleOnFullScreen: false });
      win.setIgnoreMouseEvents(true, { forward: true });
    } catch {}
    rec = { id: RAIL_CONTENT_ID, win, expectingClose: false, geometryTimer: null };
    windows.set(RAIL_CONTENT_ID, rec);
    // 轨道无 ×（plan §4.1）；任何 close 请求一律隐藏，不销毁
    win.on("close", (event) => {
      if (rec.expectingClose || exiting) return;
      event.preventDefault();
      if (!win.isDestroyed()) win.hide();
    });
    win.on("closed", () => {
      windows.delete(RAIL_CONTENT_ID);
    });
    win.loadURL(new URL("/window/rail", spaBase).toString()).catch((e) => {
      console.error("[window-manager] rail loadURL failed:", e.message);
    });
    return rec;
  };

  const syncRailVisibility = () => {
    const railedCount = core
      .getSnapshot()
      .entries.filter((e) => e.state === "railed").length;
    if (railedCount > 0) {
      const rec = ensureRailWindow();
      if (rec && !rec.win.isDestroyed()) {
        try {
          rec.win.showInactive();
        } catch {}
      }
    } else {
      const rec = windows.get(RAIL_CONTENT_ID);
      if (rec && !rec.win.isDestroyed()) {
        try {
          rec.win.hide();
        } catch {}
      }
    }
  };

  // 渲染层 hover 条带/hover 卡时切换点击穿透（P2 plan §5）
  ipcMain.on(CHANNELS.window.railMouse, (event, payload) => {
    const rec = windows.get(RAIL_CONTENT_ID);
    if (!rec || rec.win.isDestroyed() || event.sender !== rec.win.webContents) return;
    try {
      rec.win.setIgnoreMouseEvents(payload?.ignore !== false, { forward: true });
    } catch {}
  });

  const showAndFocus = (rec) => {
    if (!rec || rec.win.isDestroyed()) return;
    try {
      if (rec.win.isMinimized()) rec.win.restore();
      rec.win.show();
      rec.win.focus();
    } catch {}
  };

  const createContentWindow = (id, spec, bounds) => {
    const spaBase = typeof getSpaBaseUrl === "function" ? getSpaBaseUrl() : null;
    if (!spaBase) {
      return { ok: false, code: "spa_server_unavailable", error: "SPA 服务未就绪，无法创建窗口" };
    }
    const route = core.buildRouteForId(id);
    if (!route) {
      return { ok: false, code: "route_not_allowed", error: `路由未登记: ${id}` };
    }
    let url;
    try {
      url = new URL(route, spaBase).toString();
    } catch {
      return { ok: false, code: "route_not_allowed", error: "路由解析失败" };
    }

    const win = new BrowserWindow({
      width: bounds.w,
      height: bounds.h,
      x: bounds.x,
      y: bounds.y,
      minWidth: 480,
      minHeight: 360,
      title: windowTitle(spec.title || "窗口"),
      frame: false,
      backgroundColor: "#1f2330",
      show: false,
      webPreferences: {
        preload: resolveResource("src", "preload.js"),
        contextIsolation: true,
        nodeIntegration: false,
        sandbox: true,
        webSecurity: true,
      },
    });

    const rec = { id, win, expectingClose: false, geometryTimer: null };
    windows.set(id, rec);

    // Same guards as the main window: pop-outs load only the local
    // SPA origin, external links go to the system browser.
    const allowedBase = spaBase.replace(/\/$/, "");
    win.webContents.on("will-navigate", (event, target) => {
      if (!target.startsWith(allowedBase)) {
        event.preventDefault();
      }
    });
    win.webContents.setWindowOpenHandler(({ url: target }) => {
      if (target.startsWith("http://") || target.startsWith("https://")) {
        require("electron").shell.openExternal(target).catch(() => {});
      }
      return { action: "deny" };
    });
    win.webContents.on("did-fail-load", (_event, code, desc, validated) => {
      console.error(`[window-manager] load failed (${id}): ${code} ${desc} ${validated}`);
    });

    win.once("ready-to-show", () => {
      if (!win.isDestroyed()) win.show();
    });

    win.on("move", () => scheduleGeometryRecord(rec));
    win.on("resize", () => scheduleGeometryRecord(rec));

    // Immutable contract: a close request on a popped window is a
    // DEMOTE, not a destroy (plan §3 / §9). Singletons with
    // closeBehavior 'close' close for real.
    win.on("close", (event) => {
      if (rec.expectingClose || exiting) return;
      if (spec.closeBehavior !== "rail") return;
      event.preventDefault();
      recordGeometryNow(rec);
      // 快照后降格隐藏（capturePage 需要窗口可见，串行保证顺序）
      void captureThumbnail(rec).then(() => {
        core.minimizeToRail(id);
        if (!win.isDestroyed()) win.hide();
      });
