  // 6. CSP 加固——禁用 unsafe-eval，限制资源来源到 self + localhost（后端/SSE/dev server）
  setupCsp({ isDevMode });

  // 7. 创建窗口
  // createWindow extracted to src/main/_window-create.js (SUB-15.1 PHASE 3)
  await createWindow({
    BrowserWindow,
    shell,
    session,
    resolveResource,
    isDevMode,
