      (input.meta || input.control) &&
      !input.alt;
    if (!isReloadKey) return;
    event.preventDefault();
    if (input.shift) {
      console.log("[desktop] hard reload requested");
      const win = getMainWindow();
      if (win && !win.isDestroyed()) {
        win.webContents.reloadIgnoringCache();
      }
      return;
    }
    console.log("[desktop] soft refresh requested");
    const win = getMainWindow();
    if (win && !win.isDestroyed()) {
      win.webContents.send(CHANNELS.app.softRefresh);
    }
  });

  // ── DevTools ──────────────────────────────────────────────────
  if (process.env.PETRI_OPEN_DEVTOOLS === "1") {
    mainWindow.webContents.openDevTools();
  }

  // ── Renderer Console Capture ───────────────────────────────────
  mainWindow.webContents.on(
    "console-message",
    (event, level, message, line, sourceId) => {
      const tag = ["LOG", "WARN", "ERROR"][level] || "LOG";
      console.log(`[renderer:${tag}] ${message}`);
    },
  );

  // ── Load Failure Capture ───────────────────────────────────────
  mainWindow.webContents.on(
    "did-fail-load",
    (event, errorCode, errorDescription, validatedURL) => {
      console.error(
        `[renderer] load failed: ${errorCode} ${errorDescription} url=${validatedURL}`,
      );
    },
  );

  // ── Page Load Complete ─────────────────────────────────────────
  mainWindow.webContents.on("did-finish-load", () => {
    console.log("[renderer] page loaded");
    publishAgentWorkbenchFlags({
      getMainWindow,
      getAgentWorkbenchFlags,
    });
  });

  // ── macOS Focus Diagnostics ────────────────────────────────────
  // The dev launcher obtains the GUI session via LaunchServices.
  // Record window state only; do not delay to steal focus.
  if (process.platform === "darwin") {
    const windowForFocusDiagnostics = mainWindow;
    windowForFocusDiagnostics.webContents.once("did-finish-load", () => {
      setTimeout(() => {
        if (!windowForFocusDiagnostics.isDestroyed()) {
          console.log(
            "[focus] isKeyWindow after load:",
            typeof windowForFocusDiagnostics.isKeyWindow === "function"
              ? windowForFocusDiagnostics.isKeyWindow()
              : "n/a",
            "isFocused:",
            windowForFocusDiagnostics.isFocused(),
          );
        }
      }, 500);
    });
  }

  // ── Window Closed ──────────────────────────────────────────────
  mainWindow.on("closed", () => {
    setMainWindow(null);
  });

  // ── Maximize/Unmaximize State → Renderer ──────────────────────
  // Forward maximize state so the self-drawn window control buttons
  // can swap their glyph (single square ↔ double square).
  const publishMaximizedState = (isMaximized) => {
    const win = getMainWindow();
    if (!win) return;
    if (
      (typeof win.isDestroyed === "function" && win.isDestroyed()) ||
      (typeof win.webContents?.isDestroyed === "function" && win.webContents.isDestroyed())
    ) {
      return;
    }
    win.webContents.send(CHANNELS.window.maximizeChanged, isMaximized);
  };
  mainWindow.on("maximize", () => publishMaximizedState(true));
  mainWindow.on("unmaximize", () => publishMaximizedState(false));

  // ── Fullscreen State → Renderer ────────────────────────────────
  // On macOS frameless windows, use simpleFullScreen mode which
  // automatically hides the Dock and menu bar for true fullscreen.
  if (process.platform === "darwin") {
    mainWindow.on("enter-simple-full-screen", () => {
      const win = getMainWindow();
      if (!win || win.isDestroyed() || !win.webContents || win.webContents.isDestroyed()) return;
      win.webContents.send(CHANNELS.window.fullscreenChanged, true);
    });
    mainWindow.on("leave-simple-full-screen", () => {
      const win = getMainWindow();
      if (!win || win.isDestroyed() || !win.webContents || win.webContents.isDestroyed()) return;
      win.webContents.send(CHANNELS.window.fullscreenChanged, false);
    });
  } else {
    mainWindow.on("enter-full-screen", () => {
      const win = getMainWindow();
      if (!win || win.isDestroyed() || !win.webContents || win.webContents.isDestroyed()) return;
      win.webContents.send(CHANNELS.window.fullscreenChanged, true);
    });
    mainWindow.on("leave-full-screen", () => {
      const win = getMainWindow();
      if (!win || win.isDestroyed() || !win.webContents || win.webContents.isDestroyed()) return;
      win.webContents.send(CHANNELS.window.fullscreenChanged, false);
    });
  }

  return mainWindow;
}

module.exports = { createWindow };

// ============================================================
// Window Manager core — BLOCK-59 P0
//
// Pure state machine + content-type registry for the window
// system (docked / popped / railed / closed). No Electron
// dependency: BrowserWindow lifecycle lives in the adapter
// (src/ipc/window-manager.js), which injects persistence and
// consumes the transition events emitted here.
//
// Immutable contract (plan §3, §9): × always DEMOTES to the
// edge rail, never destroys. Destruction has exactly one path:
// explicit removal from the rail (remove()). The command
// center and rail container are singletons and intentionally
// stay OUT of the state machine (plan §4.1).
//
// All mutating ops return { ok: true, ... } or
// { ok: false, code, error } — callers must not infer state.
// ============================================================

const MAX_POPPED_WINDOWS = 4;

// Static (completed result) railed entries fade in the rail
// after 5 minutes; persistent ones (terminal/agent) never do.
// Fade is a rail-visual concern — the window stays alive and
// restorable (hidden keep-alive), so the contract is intact.
const RAIL_STATIC_FADE_MS = 5 * 60 * 1000;

// Content keys are artifact/session/task identifiers. Artifact
// names may be non-ASCII (delivery manifests are user-facing);
// safety comes from buildRouteForId running encodeURIComponent —
// the raw key only has to stay free of URL-structure and control
// characters so the encoded route stays unambiguous.
const KEY_PATTERN = /^[^\/\\?#"'\s\u0000-\u001f\u007f%]{1,128}$/;

const CONTENT_TYPES = {
  // UI-385 — result/agent 独立窗已退役：结果/子智能体详情统一在主窗右栏
  // 承载（RightPanelMode 'results' / 'agent'）；终端与指挥中心独立窗保留。
  terminal: {
    routePrefix: "/window/terminal",
    closeBehavior: "rail",
    railClass: "persistent",
    restore: "session", // restorable while the pty session lives
    singleton: false,
    title: "终端",
    defaultBounds: { width: 880, height: 600 },
  },
  "command-center": {
    routePrefix: "/window/command-center",
    closeBehavior: "close", // stateless singleton: × = real close
    singleton: true,
    title: "指挥中心",
    defaultBounds: { width: 1200, height: 820 },
  },
  rail: {
    internal: true, // rail container: no route, no ×, adapter-only
    closeBehavior: "none",
    singleton: true,
    title: "活动轨道",
    defaultBounds: { width: 28, height: 600 },
  },
};

function isSingletonType(type) {
  const spec = CONTENT_TYPES[type];
  return !!spec && spec.singleton === true;
}

/** Fail-closed route whitelist: unknown type or malformed key is
 *  rejected here so the adapter can never receive a route to
 *  load that the registry did not declare. */
function validateContent({ type, key }) {
  const spec = CONTENT_TYPES[type];
  if (!spec || spec.internal) {
    return { ok: false, code: "route_not_allowed", error: `窗口类型不在白名单: ${String(type)}` };
  }
  if (spec.singleton) {
    if (key != null && key !== "") {
      return { ok: false, code: "invalid_key", error: "单例窗口不接受内容键" };
    }
    return { ok: true, id: `${type}:`, spec, key: "" };
  }
  if (typeof key !== "string" || key === "." || key === ".." || !KEY_PATTERN.test(key)) {
    return { ok: false, code: "invalid_key", error: `内容键不合法: ${String(key).slice(0, 32)}` };
  }
  return { ok: true, id: `${type}:${key}`, spec, key };
}

/** Build the SPA route for a content id. Only ever called with
 *  ids that passed validateContent — re-derived from the id so
 *  the route and the registry entry can never drift apart. */
function buildRouteForId(id) {
  const sep = id.indexOf(":");
  const type = id.slice(0, sep);
  const key = id.slice(sep + 1);
  const spec = CONTENT_TYPES[type];
  if (!spec || spec.internal || spec.routePrefix == null) return null;
  if (spec.singleton) return spec.routePrefix;
  return `${spec.routePrefix}/${encodeURIComponent(key)}`;
}

function isFiniteInt(value) {
  return typeof value === "number" && Number.isFinite(value);
}

/** Validate a geometry record { x, y, w, h, displayId? }. */
function isValidGeometry(geometry) {
  if (!geometry || typeof geometry !== "object") return false;
  if (!isFiniteInt(geometry.x) || !isFiniteInt(geometry.y)) return false;
  if (!isFiniteInt(geometry.w) || !isFiniteInt(geometry.h)) return false;
  if (geometry.w <= 0 || geometry.h <= 0) return false;
  if (geometry.displayId != null && !isFiniteInt(geometry.displayId)) return false;
  return true;
}

function clampBoundsToWorkArea(bounds, workArea) {
  if (!workArea) return bounds;
  const width = Math.min(bounds.w, workArea.width);
  const height = Math.min(bounds.h, workArea.height);
  const x = Math.max(workArea.x, Math.min(bounds.x, workArea.x + workArea.width - width));
  const y = Math.max(workArea.y, Math.min(bounds.y, workArea.y + workArea.height - height));
  return { x, y, w: width, h: height };
}

/**
 * Create the window manager core.
 *
 * @param {object}  deps
 * @param {number}  [deps.maxPopped]     - popped concurrency limit (default 4)
 * @param {function} [deps.now]          - clock injection for tests
 * @param {function} [deps.loadState]    - () => raw persisted object | null
 * @param {function} [deps.saveState]    - (serialized) => void (adapter debounces)
 */
function createWindowManagerCore({ maxPopped = MAX_POPPED_WINDOWS, now = Date.now, loadState, saveState } = {}) {
  // contentId → entry. Entries exist for state-machine content
  // only (singletons are tracked by the adapter, plan §3).
  const registry = new Map();
  // contentId → { x, y, w, h, displayId } main-process-owned
  // position memory (plan §4.2 裁决 4), persisted via saveState.
  const geometryMemory = new Map();
  const subscribers = new Set();

  const publicEntry = (entry) => ({
    id: entry.id,
    type: entry.type,
    key: entry.key,
    state: entry.state,
    railClass: entry.railClass,
    fadeAfter: entry.state === "railed" && entry.railClass === "static"
      ? entry.railedAt + RAIL_STATIC_FADE_MS
      : null,
    createdAt: entry.createdAt,
    poppedAt: entry.poppedAt,
    railedAt: entry.railedAt,
  });

  const emit = (event) => {
    for (const fn of subscribers) {
      try {
        fn(event);
      } catch {}
    }
  };

  const upsertEvent = (entry) => emit({ kind: "upsert", entry: publicEntry(entry) });

  // Persistence is rate-limited by the adapter (geometry records
  // are debounced there); the core writes eagerly so the last
  // recorded position always survives.
  const persist = () => {
    if (typeof saveState !== "function") return;
    try {
      saveState(serialize());
    } catch {}
  };

  const ensureEntry = (id, type, key) => {
    let entry = registry.get(id);
    if (!entry) {
      entry = {
        id,
        type,
        key,
        state: "docked",
        railClass: CONTENT_TYPES[type].railClass,
        createdAt: now(),
        poppedAt: null,
        railedAt: null,
      };
      registry.set(id, entry);
    }
    return entry;
  };

  const poppedEntries = () =>
    [...registry.values()].filter((e) => e.state === "popped");

  /** Demote the oldest popped window to the rail. Returns the
   *  demoted entry or null (nothing popped). */
  const autoDemoteOldest = () => {
    const candidates = poppedEntries().sort((a, b) => a.poppedAt - b.poppedAt);
    const victim = candidates[0];
    if (!victim) return null;
    victim.state = "railed";
    victim.railedAt = now();
    upsertEvent(victim);
    return victim;
  };

  const enforcePopLimit = () => {
    let demoted = null;
    while (poppedEntries().length >= maxPopped) {
      const victim = autoDemoteOldest();
      if (!victim) break;
      demoted = victim;
    }
    return demoted;
  };

  // ── Hydration (geometry memory survives restart; windows do not) ──
  if (typeof loadState === "function") {
    try {
      const raw = loadState();
      if (raw && typeof raw === "object" && raw.geometry && typeof raw.geometry === "object") {
        for (const [id, geometry] of Object.entries(raw.geometry)) {
          if (typeof id === "string" && id.includes(":") && isValidGeometry(geometry)) {
            geometryMemory.set(id, {
              x: geometry.x,
              y: geometry.y,
              w: geometry.w,
              h: geometry.h,
              displayId: geometry.displayId ?? null,
            });
          }
        }
      }
    } catch {}
  }

  function serialize() {
    const geometry = {};
    for (const [id, geometry0] of geometryMemory.entries()) {
      geometry[id] = { ...geometry0 };
    }
    return { version: 1, savedAt: now(), geometry };
  }

  // ── Content resolution (route whitelist, fail-closed) ─────────

  function resolveContent(params) {
    const verdict = validateContent(params || {});
    if (!verdict.ok) return verdict;
    return { ok: true, id: verdict.id, key: verdict.key, spec: verdict.spec };
  }

  // ── State machine ops ─────────────────────────────────────────

  /** docked → popped. Same-content pop = focus existing; railed
   *  content pops back from the rail. Over-limit pops auto-demote
   *  the oldest popped window (plan §3). */
  function popOut({ type, key }) {
    const verdict = validateContent({ type, key });
    if (!verdict.ok) return verdict;
    const { id, spec } = verdict;

    if (spec.singleton) {
      return { ok: true, id, action: "singleton", spec };
    }

    const existing = registry.get(id);
    if (existing && existing.state === "popped") {
      return { ok: true, id, action: "focused" }; // 同内容禁双开
    }
    if (existing && existing.state === "railed") {
      const demoted = enforcePopLimit();
      existing.state = "popped";
      existing.poppedAt = now();
      existing.railedAt = null;
      upsertEvent(existing);
      return { ok: true, id, action: "restored", autoDemoted: demoted ? demoted.id : null };
    }

    const demoted = enforcePopLimit();
    const entry = ensureEntry(id, type, verdict.key);
    entry.state = "popped";
    entry.poppedAt = now();
    upsertEvent(entry);
    return { ok: true, id, action: "created", autoDemoted: demoted ? demoted.id : null };
  }

  /** popped → railed. The × semantics: DEMOTE, never destroy. */
  function minimizeToRail(id) {
    const entry = registry.get(id);
    if (!entry || entry.state !== "popped") {
      return { ok: false, code: "invalid_transition", error: `窗口不可降格: ${id}` };
    }
    entry.state = "railed";
    entry.railedAt = now();
    upsertEvent(entry);
    return { ok: true, id, state: "railed" };
  }

  /** railed → popped (rail hover / click restore). */
  function restoreFromRail(id) {
    const entry = registry.get(id);
    if (!entry || entry.state !== "railed") {
      return { ok: false, code: "invalid_transition", error: `窗口不可从轨道恢复: ${id}` };
    }
    const demoted = enforcePopLimit();
    entry.state = "popped";
    entry.poppedAt = now();
    entry.railedAt = null;
    upsertEvent(entry);
    return { ok: true, id, state: "popped", autoDemoted: demoted ? demoted.id : null };
  }

  /** popped → docked. The pop-out window is destroyed by the
   *  adapter; the content lives on in the main window. The entry
   *  stays (state docked) so the renderer can reconcile. */
  function returnToDock(id) {
    const entry = registry.get(id);
    if (!entry || entry.state !== "popped") {
      return { ok: false, code: "invalid_transition", error: `窗口不可收回: ${id}` };
    }
    entry.state = "docked";
    entry.poppedAt = null;
    upsertEvent(entry);
    return { ok: true, id, state: "docked" };
  }

  /** railed → closed. The ONLY destruction path (plan §3). */
  function remove(id) {
    const entry = registry.get(id);
    if (!entry || entry.state !== "railed") {
      return { ok: false, code: "invalid_transition", error: `仅轨道内窗口可移除: ${id}` };
    }
    registry.delete(id);
    emit({ kind: "remove", id });
    return { ok: true, id, state: "closed" };
  }

  // ── Geometry (main-process position memory, plan §4.2) ────────

  function recordGeometry(id, geometry) {
    const entry = registry.get(id);
    if (!entry) return { ok: false, code: "unknown_content", error: `未登记内容: ${id}` };
    if (entry.state !== "popped") return { ok: false, code: "invalid_state" };
    if (!isValidGeometry(geometry)) return { ok: false, code: "invalid_geometry" };
    geometryMemory.set(id, {
      x: Math.round(geometry.x),
      y: Math.round(geometry.y),
      w: Math.round(geometry.w),
      h: Math.round(geometry.h),
      displayId: isFiniteInt(geometry.displayId) ? geometry.displayId : null,
    });
    persist();
    return { ok: true };
  }

  function forgetGeometry(id) {
    geometryMemory.delete(id);
    persist();
  }

  /** Resolve launch bounds for a (re)spawned pop-out window.
   *  Saved geometry wins when its display still exists and the
   *  window would be reachable; otherwise fall back to a
   *  cascaded default on the primary work area (副屏失效回落,
   *  plan §4.2 裁决 4). */
  function resolveLaunchBounds(id, { displays = [], mainBounds = null } = {}) {
    const sep = id.indexOf(":");
    const spec = CONTENT_TYPES[id.slice(0, sep)] || {};
    const saved = geometryMemory.get(id);
    const savedDisplay = saved && saved.displayId != null
      ? displays.find((d) => d.id === saved.displayId)
      : null;
    if (saved && savedDisplay) {
      return { bounds: { ...saved }, reusedMemory: true, displayId: savedDisplay.id };
    }
    if (saved && saved.displayId == null && displays.length > 0) {
      const workArea = displays[0].workArea || displays[0].bounds;
      return {
        bounds: clampBoundsToWorkArea(saved, workArea),
        reusedMemory: true,
        displayId: displays[0].id,
      };
    }

    const primary = displays[0];
    const base = mainBounds || (primary ? primary.workArea || primary.bounds : null);
    const cascadeIndex = poppedEntries().length % 8;
    const fallback = {
      x: (base ? base.x : 0) + 48 + cascadeIndex * 32,
      y: (base ? base.y : 0) + 48 + cascadeIndex * 32,
      w: spec.defaultBounds ? spec.defaultBounds.width : 960,
      h: spec.defaultBounds ? spec.defaultBounds.height : 680,
    };
    const workArea = primary ? primary.workArea || primary.bounds : null;
    return {
      bounds: clampBoundsToWorkArea(fallback, workArea),
      reusedMemory: false,
      displayId: primary ? primary.id : null,
    };
  }

  // ── Snapshot / subscription (renderer hydration + multicast) ──

  function getSnapshot() {
    return {
      maxPopped,
      entries: [...registry.values()].map(publicEntry),
      singletons: {
        commandCenter: { type: "command-center", route: CONTENT_TYPES["command-center"].routePrefix },
      },
    };
  }

  function subscribe(fn) {
    if (typeof fn !== "function") return () => {};
    subscribers.add(fn);
    return () => subscribers.delete(fn);
  }

  return {
    popOut,
    minimizeToRail,
    restoreFromRail,
    returnToDock,
    remove,
    resolveContent,
    buildRouteForId,
    recordGeometry,
    forgetGeometry,
    resolveLaunchBounds,
    getSnapshot,
    subscribe,
    serialize,
  };
}

module.exports = {
  createWindowManagerCore,
  validateContent,
  buildRouteForId,
  isValidGeometry,
  clampBoundsToWorkArea,
  CONTENT_TYPES,
  MAX_POPPED_WINDOWS,
  RAIL_STATIC_FADE_MS,
  KEY_PATTERN,
};

// ============================================================
// Backend process manager — central registry for the backend
// child process (petri-server；BLOCK-30 P1 起 py-server 已摘除，
// BLOCK-51 P3 起 plumber 空壳已清理——R 为 tools-executor 单轨)
// plus its log streams and supervisor.
//
// Extracted from src/main.js by BLOCK-9.1 PHASE 4.
// Original location: src/main.js ~lines 96-139 (log streams),
// ~lines 320-428 (startGateway / startRServer；gateway 部分随 BLOCK-30 P2 摘除), ~lines 430-613
// (startPyServer / stopPyServer +
//  idle timer helpers + rServerSupervisor).
//
// Design rationale:
//   - The backend procs are module-level `let ChildProc`
//     variables in main.js that are shared across:
//       * startup functions (startRServer / ...)
//       * setupRuntimeIpc / setupTerminalIpc / setupDiagnosticIpc
//         (IPC handlers that read procs for status snapshots)
//       * before-quit / app lifecycle hooks
//   - Centralizing them in backend-proc-manager.js means IPC
//     modules import them via `getProcs()` or accept them as
//     parameters from main.js's setup* call sites.
//   - The log stream registry (_logStreams) is similarly shared
//     between startup hooks and setupDiagnosticIpc, so it lives
//     here too (worker report recommendation §5.3 option B).
//
// Exports:
//   - module-level start/stop functions (consumed by main.js
//     at boot, and by tests)
//   - getProcs() — returns a snapshot { rServerProc }
//     for IPC snapshot handlers
//   - getLogDir() / flushLogs() / readLogTail() — for
//     setupDiagnosticIpc / setupTerminalIpc
//
// The backend proc remains a mutable `let` variable here so
// the .on("exit") handlers can null it out as before. IPC
// handlers that need a snapshot call getProcs() at handler
// invocation time.
// ============================================================

const fs = require("fs");
const path = require("path");
const { resolveLocalDirName } = require("./brand");
const { spawn } = require("child_process");
const { app } = require("electron");
const { createOwnedBackendSupervisor } = require("../owned-backend-supervisor");

// ── Path resolution (mirror of main.js:147-169) ─────────────────
const IS_DEV = !app.isPackaged;
const PROJECT_ROOT = IS_DEV ? path.join(__dirname, "..", "..") : process.resourcesPath;

function resolveCoreRoot() {
  if (IS_DEV) {
    return path.join(PROJECT_ROOT, "core");
  }
  return path.join(process.resourcesPath, "core");
}

function resolveCore(...parts) {
  return path.join(resolveCoreRoot(), ...parts);
}

// ── Node bin resolution (mirror of main.js:178-220) ────────────
// Used by all 4 spawn() calls below.
const { getNodeLocator } = require("../platform-compat");

function resolveNodeBinLocal() {
  if (!IS_DEV) {
    if (process.platform === "darwin") {
      const helperName = `${path.basename(process.execPath)} Helper`;
      const helperBin = path.join(
        path.dirname(process.execPath),
        "..",
        "Frameworks",
        `${helperName}.app`,
        "Contents",
        "MacOS",
        helperName,
      );
      if (fs.existsSync(helperBin)) return helperBin;
    }
    return process.execPath;
  }
  try {
    const { execFileSync } = require("child_process");
    const locator = getNodeLocator(process.platform);
    const bin = execFileSync(locator, ["node"], {
      encoding: "utf-8",
      timeout: 3000,
    })
      .toString()
      .trim()
      .split(/\r?\n/)[0];
    if (bin && fs.existsSync(bin)) return bin;
  } catch {
    /* fallback */
  }
  return "node";
}

const NODE_BIN = resolveNodeBinLocal();

// ── Log streams registry (mirror of main.js:94-139) ───────────
const _logStreams = {};

function getLogDir() {
  const dir = process.env.PETRI_LOCAL_DATA_DIR
    ? path.join(process.env.PETRI_LOCAL_DATA_DIR, "logs")
    : path.join(app.getPath("documents"), resolveLocalDirName(app), "logs");
  try {
    fs.mkdirSync(dir, { recursive: true });
  } catch {}
  return dir;
}

function _createLogStream(name) {
  const dir = getLogDir();
  const file = path.join(dir, `${name}.log`);
  const stream = fs.createWriteStream(file, { flags: "a" });
  _logStreams[name] = stream;
  stream.write(`\n=== ${new Date().toISOString()} — session start ===\n`);
  return stream;
}

function _writeLog(name, text) {
  const stream = _logStreams[name];
  if (stream) {
    try {
      stream.write(text + "\n");
    } catch {}
  }
}

function flushLogs() {
  for (const s of Object.values(_logStreams)) {
    try {
      s.write("");
    } catch {}
  }
}

function readLogTail(filePath, maxLines = 120) {
  try {
    if (!fs.existsSync(filePath)) return "";
    const raw = fs.readFileSync(filePath, "utf8");
    const lines = raw.split(/\r?\n/);
    return lines
      .slice(Math.max(0, lines.length - maxLines))
      .join("\n")
      .trim();
  } catch {
    return "";
  }
}

// ── Backend procs (1 child process; BLOCK-30 P1 removed py-server,
//    BLOCK-51 P3 removed plumber shell) ──
// Mutable let variables — the .on("exit") handlers null them
// out, same behavior as before.
let rServerProc = null;

function getProcs() {
  return { rServerProc };
}

// BLOCK-100 P1 — 测试实例 attach 模式：后端进程由主 dev 栈持有，本实例不 spawn。
// 登记 attached 桩（backend-health.isProcAlive = !!proc && !proc.killed → 视为
// 存活），使 backend:status 走真实 HTTP health 探测，而非因缺子进程误报
// 「本地分析服务未运行，正在重启…」。桩无 exit 事件 → 不会触发 supervisor 重启。
function markBackendAttached(port) {
  rServerProc = { attached: true, killed: false, exitCode: null };
  console.log(`[desktop] test instance: backend attached at :${port} (no local spawn)`);
}

// ── startRServer (with supervisor) ─────────────────────────────
const rServerSupervisor = createOwnedBackendSupervisor({
  name: "petri-server",
  spawnProcess: () => {
    const rServerPath = resolveCore("petri-server", "server.js");
    const child = spawn(NODE_BIN, [rServerPath], {
      // BLOCK-16 PHASE 3: 把 Electron userData 路径显式注入给 petri-server subprocess，
      // 让 system-prompt 能读 working-tree-review/rejects/（30 天 TTL 拒绝清单）。
      env: {
        ...process.env,
        ELECTRON_RUN_AS_NODE: "1",
        PETRI_USER_DATA_DIR: app.getPath("userData"),
      },
      stdio: ["ignore", "pipe", "pipe"],
    });

    _createLogStream("petri-server");
    child.stdout.on("data", (d) => {
      const text = d.toString().trim();
      if (text) {
        console.log(`[petri-server] ${text}`);
        _writeLog("petri-server", `[petri-server] ${text}`);
      }
    });
    child.stderr.on("data", (d) => {
      const text = d.toString().trim();
      if (text) {
        console.error(`[petri-server] ${text}`);
        _writeLog("petri-server", `[petri-server:ERR] ${text}`);
      }
    });
    return child;
  },
  onProcessChange: (child) => {
    rServerProc = child;
  },
  log: console.log,
  warn: console.warn,
});

function startRServer(reason = "boot") {
  // BLOCK-66 P1 — R 硬门摘除：petri-server 是纯 Node 进程，不依赖 R；
  // R 缺失照常启动，R 类插件执行时由 tools-executor runtime preflight
  // 诚实失败 + 商店指引（详见 docs/block-66-runtime-decouple-plan.md）。
  // 函数名 startRServer 为历史遗留（plumber/py-server 时代），保留以减 diff。
  if (!process.env.PETRI_R_HOME) {
    console.log(
      "[desktop] petri-server starting without R runtime — R analysis features unavailable until installed",
    );
  }

  const rServerPath = resolveCore("petri-server", "server.js");
  if (!fs.existsSync(rServerPath)) {
    console.error("[desktop] petri-server not found:", rServerPath);
    return { ok: false, error: "petri-server script not found" };
  }

  const result = rServerSupervisor.start(reason);

  if (result.ok && !result.alreadyRunning) {
    console.log(
      `[desktop] petri-server spawned (pid=${result.pid}) on :${process.env.R_SERVER_PORT} — reason=${reason}`,
    );
  }
  return result;
}

// ── startPyServer / stopPyServer ───────────────────────────────
// BLOCK-30 P1: removed with the py-server HTTP service. Python tool
// execution runs inside petri-server via the shared-backend executor
// registry (spawn 内嵌 python)，无需独立 Python 后端进程。
//
// ── startPlumber / stopPlumber ─────────────────────────────────
// BLOCK-51 P3: removed with the plumber shell. replot.R 从未存在于
// git 历史，plumber 进程从未启动；R 实际单轨 = tools-executor 每任务
// 独立 Rscript 子进程。交互式重绘已由 Result Studio 版本化编辑取代。

module.exports = {
  // procs / logs
  getProcs,
  markBackendAttached,
  getLogDir,
  flushLogs,
  readLogTail,
  // lifecycle
  startRServer,
  // supervisor (for before-quit shutdown in main.js)
  rServerSupervisor,
};

// ============================================================
// Brand identity — single source of truth (BLOCK-61)
//
// 这是全仓库品牌命名的唯一权威。改名 = 只改这里 +
// frontend/src/lib/brand.ts（渲染进程镜像，由
// test/brand-identity.test.mjs 契约锁一致），再跑一次机械同步。
// 业务代码禁止裸写品牌字面量——一律 import 本模块。
//
// 协议命名空间（非品牌，plan §4）：core/petri-server 路径、
// .petri-* 用户数据目录、PETRI_* 环境变量前缀——这些是
// 稳定协议，不随品牌改名（数据连续性 + 外部脚本兼容）。
// ============================================================

'use strict';

const BRAND = Object.freeze({
  /** 用户可见英文品牌（窗口标题 / wordmark / 文案）。 */
  APP_NAME: "Petri",
  /** 中文名。 */
  APP_NAME_ZH: "格物",
  /** 历史名——仅用于兼容识别（如旧数据目录探测），不用于展示。 */
  LEGACY_APP_NAME: "Petri",
  /** 用户 Documents 下的工作目录名（新装环境）。 */
  LOCAL_DIR_NAME: "Petri-Local",
  /** 上一代 Documents 目录名（既有环境数据连续性优先）。 */
  LEGACY_LOCAL_DIR_NAME: "Petri-Local",
});

/**
 * 窗口标题构建器。后缀可选（如 `Petri — 结果`）。
 */
function windowTitle(suffix) {
  return suffix ? `${BRAND.APP_NAME} — ${suffix}` : BRAND.APP_NAME;
}

/**
 * 解析用户 Documents 下的本地工作目录：既有环境保持旧目录
 * （数据连续性——R 运行时/日志都在里面），新装环境用新名。
 *
 * @param {import('electron').app} app - Electron app（取 documents 路径 + fs 探测）
 * @param {object} [fs] - 可注入 fs（测试用），默认 require('fs')
 * @returns {string} 目录名（非完整路径）
 */
function resolveLocalDirName(app, fs) {
  const fsMod = fs || require("fs");
  try {
    const legacy = require("path").join(app.getPath("documents"), BRAND.LEGACY_LOCAL_DIR_NAME);
    if (fsMod.existsSync(legacy)) return BRAND.LEGACY_LOCAL_DIR_NAME;
  } catch {}
  return BRAND.LOCAL_DIR_NAME;
}

module.exports = { BRAND, windowTitle, resolveLocalDirName };

// ============================================================
// Desktop environment coordinator — sets all process.env
// variables the main process, child servers, and MCP need
// before backend lifecycle starts.
//
// Extracted from src/main.js by BLOCK-9.1 PHASE 3.
// Original location: src/main.js ~line 368 (setupDesktopEnv).
//
// Phases of setupDesktopEnv (716 lines originally):
//   1. ENV injection (PETRI_DESKTOP / SITE_DIR / user data dirs)
//   2. Directory creation (8 subdirectories under PETRI_LOCAL_DATA_DIR)
//   3. R/Python runtime resolution (3-tier priority)
//   4. Backend ports env injection (process.env.R_SERVER_PORT etc.)
//   5. Trusted renderer origins (CSP allowlist)
//   6. Built-in plugins dir env
//
// Required inputs:
//   - backendPorts { r, renderer }（BLOCK-30 P2：gateway/python 已摘除；
//     BLOCK-51 P3：plumber 已摘除）
//   - app.getPath (electron app)
//   - path/fs (Node core)
//   - resolveResource, resolveRuntime, _detectSystemR,
//     _detectSystemPython, getBuiltInPluginsDir (existing helpers
//     — resolved by require-from-parent because they are still
//     exported from src/main.js? No: they ARE module-internal. So
//     we re-define resolveResource here for self-containment.)
// ============================================================

const path = require("path");
const fs = require("fs");
const { app } = require("electron");
const { resolveLocalDirName } = require("./brand");
const { getBuiltInPluginsDir } = require("../platform-compat");

// Re-define IS_DEV locally (mirror of main.js logic)
// In main.js IS_DEV = !app.isPackaged. We keep the same rule.
function isDevModeLocal() {
  return !app.isPackaged;
}

// Re-define PROJECT_ROOT locally
function getProjectRootLocal() {
  return isDevModeLocal() ? path.join(__dirname, "..", "..") : process.resourcesPath;
}

// Re-define resolveResource locally — main.js:159-165
function resolveResource(...parts) {
  if (isDevModeLocal()) {
    return path.join(getProjectRootLocal(), ...parts);
  }
  return path.join(process.resourcesPath, ...parts);
}

// rendererDevUrl — main.js:71-72
const rendererDevUrl =
  process.env.PETRI_RENDERER_DEV_URL || "http://localhost:3000";

// Re-define runtime resolution helpers here for self-containment:
// resolveRuntime + _detectSystemR + _detectSystemPython are
// defined in main.js:337-450. They depend on getRuntimeBinCandidates
// and getPythonRuntimeExecutable (platform-compat.js), and on
// node-ffi paths. We do a light-weight re-export by re-defining
// them here using platform-compat helpers.
// The implementations are verbatim copies from main.js (PHASE 3
// extraction: same algorithms, same fallback order).

const { getRuntimeBinCandidates } = require("../platform-compat");
const { getPythonRuntimeExecutable } = require("../../core/shared-backend/runtime-paths");

function _detectSystemRLocal() {
  const { execFileSync } = require("child_process");
  try {
    const candidates = getRuntimeBinCandidates("r", process.platform);
    for (const cmd of candidates) {
      try {
        const rHome = execFileSync(cmd, ["-e", "cat(R.home())"], {
          encoding: "utf-8",
          timeout: 5000,
        }).trim();
        if (rHome && fs.existsSync(rHome)) return rHome;
      } catch {}
    }
  } catch {}
  const commonPaths =
    process.platform === "win32"
      ? ["C:\\Program Files\\R", "C:\\Program Files (x86)\\R"]
      : [
          "/Library/Frameworks/R.framework/Resources",
          "/usr/local/lib/R",
          "/opt/homebrew/lib/R",
        ];
  for (const p of commonPaths) {
    const binName = process.platform === "win32" ? "Rscript.exe" : "Rscript";
    if (fs.existsSync(path.join(p, "bin", binName))) return p;
    if (process.platform === "win32" && fs.existsSync(p)) {
      try {
        for (const entry of fs.readdirSync(p, { withFileTypes: true })) {
          if (!entry.isDirectory()) continue;
          const candidate = path.join(p, entry.name);
          if (fs.existsSync(path.join(candidate, "bin", binName))) return candidate;
        }
      } catch {}
    }
  }
  return null;
}

function _detectSystemPythonLocal() {
  const { execFileSync } = require("child_process");
  try {
    const candidates = getRuntimeBinCandidates("python", process.platform);
    for (const cmd of candidates) {
      try {
        const pyHome = execFileSync(
          cmd,
          ["-c", "import sys; print(sys.prefix)"],
          {
            encoding: "utf-8",
            timeout: 5000,
          },
        ).trim();
        if (pyHome && getPythonRuntimeExecutable(pyHome, process.platform))
          return pyHome;
      } catch {}
    }
  } catch {}
  return null;
}

function resolveRuntimeLocal(lang, userDataDir) {
  const runtimeName = lang === "r" ? "R" : "Python";
  const userRuntime = path.join(userDataDir, "runtimes", runtimeName);

  if (lang === "python") {
    if (getPythonRuntimeExecutable(userRuntime, process.platform)) {
      return userRuntime;
    }
  } else if (
    getRuntimeBinCandidates(lang, process.platform).some((candidate) =>
      fs.existsSync(path.join(userRuntime, "bin", candidate)),
    )
  ) {
    return userRuntime;
  }

  if (isDevModeLocal()) {
    if (lang === "r") {
      const sysR = _detectSystemRLocal();
      if (sysR) return sysR;
    } else {
      const sysPy = _detectSystemPythonLocal();
      if (sysPy) return sysPy;
    }
  }

  return null;
}

// ============================================================
// A-009 single source of truth for backend ports.
//
// All port fallback values used to be scattered across:
//   core/petri-server/server.js:130            (R_SERVER_PORT || 3003)
//   core/petri-server/config.js:23             (R_SERVER_PORT || '3003')
//   src/preload.js:67-68                   (R_SERVER_PORT || 3001；PY_SERVER_PORT 随 BLOCK-30 摘除)
//   src/backend-health.js:13-16            (4 separate defaults)
//
// These four sites all encode the same fact — the localhost port for
// a given backend role — but with three different defaults (3001 vs
// 3003 vs 3005). When the Electron main process is running,
// setupDesktopEnv() sets R_SERVER_PORT（BLOCK-30 起 py-server/gateway 已摘除，
// BLOCK-51 P3 起 plumber 已摘除）on process.env before any of these modules reads
// it, so the fallback is unreachable. When the petri-server / py-server
// is launched as a standalone child process (without Electron's main),
// env-coordinator is *not* running and the fallback kicks in.
//
// Centralising the fallback here lets the four readers stay
// behaviour-identical (PHASE 1.2 invariant: 100% backward compatible)
// while collapsing 4 files × 5 default values into one place. The
// defaults match what each file used to ship:
//   r       → 3001  (matches preload.js / backend-health.js historical default)
//   python  → 3004  (matches preload.js / backend-health.js historical default)
//
// 3003 was the legacy petri-server default (server.js / config.js); the
// Electron main process always overwrites R_SERVER_PORT before these
// readers execute, so the historical 3003 was never reachable in dev
// Electron. The new canonical default is 3001, which matches what
// preload.js + backend-health.js already shipped. server.js + config.js
// also fall through to 3001 now — behaviour-equivalent for the
// standalone-child-process path because Electron was never involved.
//
// Note: setupDesktopEnv() below still owns the *authoritative* env write
// (process.env.R_SERVER_PORT = String(backendPorts.r)). getBackendPort()
// is read-only and never mutates process.env. Callers that need the
// resolved value should call getBackendPort() instead of reading
// process.env directly. ============================================================
function getBackendPort(role, fallback) {
  if (role === 'r') {
    if (process.env.R_SERVER_PORT) return parseInt(process.env.R_SERVER_PORT, 10);
    return fallback != null ? fallback : 3001;
  }
  throw new Error(`getBackendPort: unknown role ${JSON.stringify(role)}`);
}

function getBackendPorts() {
  return {
    r: getBackendPort('r'),
  };
}

/**
 * 计算注入给子进程（petri-server）的 PETRI_TRUSTED_DESKTOP_ORIGINS 白名单。
 *
 * 这个集合是后端的 CORS / untrusted-origin 判据（消费方：
 * core/shared-backend/local-request-boundary.js）。CORS 按精确 origin 匹配，
 * 因此渲染页面实际所在 origin 必须逐字命中，否则后端返回的 200 会被浏览器
 * 按同源策略丢弃 —— 渲染进程只看到 `TypeError: Failed to fetch`，而上游
 * 代码往往把这个失败吞成"资源不存在"，最终给用户一个与真实原因无关的错误屏。
 *
 * 必须把 dev URL 的 localhost / 127.0.0.1 两个变体都写入：
 *   - dev 模式 backendPorts.renderer 恒为 null（见 _backend-ports.js：dev 不起
 *     :3002 渲染服务器，页面由 Vite dev server 提供），所以 dev 白名单只能由
 *     rendererDevUrl 推导，没有第二条补录路径；
 *   - Vite 监听地址随配置漂移（vite.config.ts 显式 host:'127.0.0.1' 时页面就
 *     可能落在 127.0.0.1:<port>），只写 localhost 变体会让 127.0.0.1 页面静默
 *     失联（2026-09-12 BLOCK-84 P2 实机抓真：页面跑在 127.0.0.1:3000，
 *     后端只信 localhost:3000 → 商店页显示「项目不存在或无权访问」）。
 *
 * @param {{existing?: string, isDev?: boolean, rendererDevUrl?: string, rendererPort?: number|null}} input
 * @returns {Set<string>}
 */
function computeTrustedRendererOrigins({ existing, isDev, rendererDevUrl, rendererPort } = {}) {
  const trusted = new Set(
    String(existing || "")
      .split(",")
      .map((value) => value.trim())
      .filter(Boolean),
  );
  if (isDev) {
    try {
      const devOrigin = new URL(rendererDevUrl);
      trusted.add(devOrigin.origin);
      const port = devOrigin.port || (devOrigin.protocol === 'https:' ? '443' : '80');
      for (const host of ['localhost', '127.0.0.1']) {
        trusted.add(`http://${host}:${port}`);
      }
    } catch {}
  }
  if (rendererPort) {
    trusted.add(`http://localhost:${rendererPort}`);
    trusted.add(`http://127.0.0.1:${rendererPort}`);
  }
  return trusted;
}

function setupDesktopEnv(backendPorts) {
  process.env.PETRI_DESKTOP = "1";
  process.env.PETRI_SITE_DIR = resolveResource("build");

  // 用户数据目录（先确定，resolveRuntime 要用）
  const userDataDir =
    process.env.PETRI_LOCAL_DATA_DIR ||
    path.join(app.getPath("documents"), resolveLocalDirName(app));
  process.env.PETRI_LOCAL_DATA_DIR = userDataDir;
  process.env.PETRI_LOCAL_RESULTS_DIR = path.join(userDataDir, "results");
  process.env.PETRI_LOCAL_UPLOADS_DIR = path.join(userDataDir, "uploads");
  process.env.PETRI_TEMP_DIR = path.join(userDataDir, "tmp");
  process.env.PETRI_PY_TEMP_DIR = path.join(userDataDir, "tmp", "py");
  process.env.PETRI_DB_PATH = path.join(userDataDir, "petri.db");

  // 确保目录存在
  for (const dir of [
    userDataDir,
    process.env.PETRI_LOCAL_RESULTS_DIR,
    process.env.PETRI_LOCAL_UPLOADS_DIR,
    process.env.PETRI_TEMP_DIR,
    process.env.PETRI_PY_TEMP_DIR,
    path.join(userDataDir, "plugins"),
    path.join(userDataDir, "runtimes"),
    path.join(userDataDir, "logs"),
  ]) {
    try {
      fs.mkdirSync(dir, { recursive: true });
    } catch {}
  }

  // R/Python Runtime 解析（三级优先）
  // BLOCK-86 P2 — 领域感知：只有已装领域包契约声明运行时，缺失才提示「去商店装」；
  // 无包时纯通用态根本无运行时消费者（backend-proc-manager 无 R 照常启动），
  // 提示降到中性 debug，不再制造「缺了东西」的心理暗示。
  const packRequiresRuntimes = (() => {
    try {
      const packRegistry = require("../../core/shared-backend/pack-registry");
      return packRegistry
        .readInstalledPacks(userDataDir)
        .some((p) => Array.isArray(p.requiresRuntimes) && p.requiresRuntimes.length > 0);
    } catch {
      return false;
    }
  })();
  const rHome = resolveRuntimeLocal("r", userDataDir);
  if (rHome) {
    process.env.PETRI_R_HOME = rHome;
    console.log("[desktop] R runtime:", rHome);
  } else if (packRequiresRuntimes) {
    console.warn(
      '[desktop] R runtime not installed — install "R 运行时" from plugin store',
    );
  } else {
    console.log("[desktop] R runtime not present (no installed domain pack requires it)");
  }

  const pyHome = resolveRuntimeLocal("python", userDataDir);
  if (pyHome) {
    process.env.PETRI_PY_HOME = pyHome;
    console.log("[desktop] Python runtime:", pyHome);
  } else if (packRequiresRuntimes) {
    console.warn(
      '[desktop] Python runtime not installed — install "Python 运行时" from plugin store',
    );
  } else {
    console.log("[desktop] Python runtime not present (no installed domain pack requires it)");
  }

  process.env.R_SERVER_PORT = String(backendPorts.r);
  process.env.R_SERVER_URL = `http://127.0.0.1:${backendPorts.r}`;
  if (backendPorts.renderer) {
    process.env.PETRI_RENDERER_PORT = String(backendPorts.renderer);
    process.env.PETRI_RENDERER_ORIGIN = `http://localhost:${backendPorts.renderer}`;
  }
  const trustedRendererOrigins = computeTrustedRendererOrigins({
    existing: process.env.PETRI_TRUSTED_DESKTOP_ORIGINS,
    isDev: isDevModeLocal(),
    rendererDevUrl,
    rendererPort: backendPorts.renderer,
  });
  process.env.PETRI_TRUSTED_DESKTOP_ORIGINS = [...trustedRendererOrigins].join(",");
  // Child servers run in separate Node processes and cannot see Electron's
  // in-memory plugin registry. Give them the exact packaged/dev built-in root
  process.env.PETRI_BUILT_IN_PLUGINS_DIR = getBuiltInPluginsDir({
    isPackaged: !isDevModeLocal(),
    projectRoot: getProjectRootLocal(),
    resourcesPath: process.resourcesPath,
  });
}

module.exports = {
  setupDesktopEnv,
  getBackendPort,
  getBackendPorts,
  computeTrustedRendererOrigins,
};

#!/usr/bin/env node
/**
 * desktop-app/src/mcp-server.js — Petri 桌面版 MCP stdio server
 *
 * 把已注册的 Petri 插件工具暴露成 agent 可调用的 MCP 工具层。
 * 本文件只负责 stdio 协议，工具发现与执行统一由 core MCP registry 处理。
 *
 * SDK (@modelcontextprotocol/sdk) 是 ESM-only，desktop-app/src 是 CJS，
 * 故用动态 import() 加载。
 */

async function startMcpServer() {
  const { Server } = await import('@modelcontextprotocol/sdk/server/index.js');
  const { StdioServerTransport } = await import('@modelcontextprotocol/sdk/server/stdio.js');
  const { ListToolsRequestSchema, CallToolRequestSchema } =
    await import('@modelcontextprotocol/sdk/types.js');
  // 去 submodule 后：core 内嵌在 desktop 仓根 core/ 下。
  // mcp-server 是 stdio 子进程（被 petri-mcp bin spawn），不经 Electron 主进程，
  // 自己解析 core 路径：dev = ../core（从 src/ 出发），pack = process.resourcesPath/core
  // 注意：本文件是 CJS（有 require/module.exports），用 __dirname 全局，不用 ESM 的 import.meta.url
  const path = require('node:path');
  const fs = require('node:fs');
  const devCorePath = path.resolve(__dirname, '..', 'core');
  const coreRoot = fs.existsSync(devCorePath)
    ? devCorePath
    : path.join(process.resourcesPath || '', 'core');
  const { listTools, callTool } = require(path.join(coreRoot, 'petri-server', 'mcp', 'registry'));

  const server = new Server(
    { name: 'petri-mcp', version: '0.1.0' },
    { capabilities: { tools: {} } }
  );

  // tools/list：返回当前注册的插件工具
  server.setRequestHandler(ListToolsRequestSchema, async () => ({ tools: await listTools() }));

  // tools/call：进入统一 registry 执行通道
  server.setRequestHandler(CallToolRequestSchema, async (req) => {
    const name = req?.params?.name ?? '<unknown>';
    const args = req?.params?.arguments ?? {};
    try {
      return await callTool(name, args);
    } catch (e) {
      const log = require(path.join(coreRoot, 'shared-backend', 'logger'));
      const code = e?.code || 'unknown';
      const message = e?.message || String(e);
      log.error('mcp_tool_error', { event: 'mcp_tool_error', tool: name, code, message });
      // MCP 约定：工具错误返回 isError 内容，而非抛异常
      return {
        content: [{ type: 'text', text: `Error: ${message}` }],
        isError: true,
      };
    }
  });

  return server;
}

async function main() {
  const { StdioServerTransport } = await import('@modelcontextprotocol/sdk/server/stdio.js');
  const server = await startMcpServer();
  await server.connect(new StdioServerTransport());
}

// 直接运行时启动 stdio server；被 require 时不自动启动
if (require.main === module) {
  main().catch((e) => {
    console.error('[petri-mcp] fatal:', e);
    process.exit(1);
  });
}

module.exports = { startMcpServer };

"use strict";

const DEFAULT_RESTART_DELAYS_MS = Object.freeze([
  500,
  1_000,
  2_000,
  5_000,
  10_000,
  30_000,
]);

function createOwnedBackendSupervisor({
  name,
  spawnProcess,
  onProcessChange = () => {},
  log = () => {},
  warn = () => {},
  schedule = setTimeout,
  cancel = clearTimeout,
  restartDelaysMs = DEFAULT_RESTART_DELAYS_MS,
  stableAfterMs = 30_000,
}) {
  if (!name || typeof spawnProcess !== "function") {
    throw new TypeError("name and spawnProcess are required");
  }

  let processHandle = null;
  let restartTimer = null;
  let stableTimer = null;
  let restartAttempt = 0;
  let shuttingDown = false;

  const clearTimer = (timer) => {
    if (timer !== null) cancel(timer);
    return null;
  };

  const publishProcess = (nextProcess) => {
    processHandle = nextProcess;
    onProcessChange(nextProcess);
  };

  const restartDelay = () => {
    const index = Math.min(restartAttempt, restartDelaysMs.length - 1);
    return restartDelaysMs[index];
  };

  const scheduleRestart = (detail) => {
    if (shuttingDown || restartTimer !== null) return;
    const delayMs = restartDelay();
    restartAttempt += 1;
    warn(`[desktop] ${name} stopped unexpectedly (${detail}); restarting in ${delayMs}ms`);
    restartTimer = schedule(() => {
      restartTimer = null;
      start("unexpected-exit");
    }, delayMs);
  };

  function start(reason = "boot") {
    if (shuttingDown) return { ok: false, error: "supervisor_shutting_down" };
    if (processHandle && !processHandle.killed) {
      return { ok: true, alreadyRunning: true, pid: processHandle.pid };
    }

    let child;
    try {
      child = spawnProcess(reason);
      if (!child || typeof child.once !== "function") {
        throw new TypeError("spawnProcess must return a ChildProcess-like object");
      }
    } catch (error) {
      scheduleRestart(`spawn error: ${error.message}`);
      return { ok: false, error: error.message };
    }

    publishProcess(child);
    let stopped = false;
    const handleStopped = (detail) => {
      if (stopped) return;
      stopped = true;
      stableTimer = clearTimer(stableTimer);
      if (processHandle === child) publishProcess(null);
      log(`[desktop] ${name} exited: ${detail}`);
      scheduleRestart(detail);
    };
    child.once("exit", (code, signal) => {
      handleStopped(`code=${code ?? "null"}, signal=${signal || "none"}`);
    });
    child.once("error", (error) => {
      handleStopped(`error=${error.message}`);
    });

    stableTimer = clearTimer(stableTimer);
    stableTimer = schedule(() => {
      stableTimer = null;
      if (processHandle === child && !child.killed) restartAttempt = 0;
    }, stableAfterMs);

    return { ok: true, pid: child.pid };
  }

  function shutdown(reason = "shutdown") {
    shuttingDown = true;
    restartTimer = clearTimer(restartTimer);
    stableTimer = clearTimer(stableTimer);
    const child = processHandle;
    if (child && !child.killed) {
      try {
        child.kill();
      } catch (error) {
        warn(`[desktop] ${name} stop failed (${reason}): ${error.message}`);
      }
    }
  }

  return {
    start,
    shutdown,
    getProcess: () => processHandle,
    getState: () => ({
      restartAttempt,
      restartScheduled: restartTimer !== null,
      shuttingDown,
    }),
  };
}

module.exports = {
  DEFAULT_RESTART_DELAYS_MS,
  createOwnedBackendSupervisor,
};

'use strict';

/**
 * pack-lifecycle.js — 领域包装卸编排（BLOCK-86 P1）
 *
 * 职责：把 BLOCK-84 的「记录制装/卸」升级为「契约推导的整包生命周期」——
 *   装 = 写记录 + 依次触发 requires.runtimes 声明的运行时安装（复用 installPlugin
 *        进度链；单运行时失败不回滚记录，缺项如实上报，P2 商店卡片据此提示补装）。
 *   卸 = 三档数据策略（领域资产删 / 用户数据永不动 / 包源目录默认保留）+
 *        契约推导卸运行时（computeRuntimeRemovalPlan：本包声明且无其他已装包共享）
 *        + 「删了什么/留了什么」报告。
 *
 * 实现纪律：编排只读包契约（requires.runtimes），不写死任何领域/运行时字样——
 * 新领域包照契约填内容即可，本文件零改动（对齐 BLOCK-83 D7 棘轮）。
 *
 * 可测性：createPackLifecycle(deps) 依赖注入（registry / 已装插件表 / 安装 /
 * 卸载 / 运行时目录 / 体积统计），契约测试以假件驱动全部分支；Electron IPC
 * （src/ipc/pack.js）用真件装配一个单例。
 */

const path = require('path');
const fs = require('fs');

function createPackLifecycle(deps = {}) {
  const registry = deps.registry || require('../core/shared-backend/pack-registry');
  const getInstalledPlugins = deps.getInstalledPlugins
    || (() => require('./plugin-manager').getInstalledPlugins());
  const installPlugin = deps.installPlugin
    || ((pluginId, onProgress) => require('./plugin-manager').installPlugin(pluginId, onProgress));
  const uninstallRuntime = deps.uninstallRuntime
    || ((pluginId, plug) => require('./plugin/uninstall').uninstallRuntime(pluginId, plug));
  const runtimesDir = deps.runtimesDir
    || (() => require('./plugin/paths').RUNTIMES_DIR);
  const dirSize = deps.dirSize
    || ((dir) => require('./plugin/io').dirSize(dir));
  const rmDir = deps.rmDir
    || ((dir) => require('fs').rmSync(dir, { recursive: true, force: true }));
  // BLOCK-86 P3 实机抓真 — 运行时在位判定不能只看插件安装记录：运行时可能由
  // 链外供给（手动放置/系统解析，如本机 R），plugin installed.json 里没有记录。
  // 补两条判据：runtimeStatus（R/Python 目录+可执行探测）+ 清单 language 映射。
  const getRuntimeStatus = deps.getRuntimeStatus
    || (() => require('./plugin/runtime').getRuntimeStatus());
  const getManifestLanguage = deps.getManifestLanguage
    || (async (pluginId) => {
      const manifest = await require('./plugin-manager').getRemoteManifest();
      return (manifest.plugins && manifest.plugins[pluginId] && manifest.plugins[pluginId].language) || null;
    });

  // 与 src/plugin/uninstall.js uninstallRuntime 的目录约定保持一致（仅用于
  // 体积预估；删除动作永远由 uninstallRuntime 单点执行，此处不做任何删除）。
  function runtimeDirFor(lang) {
    const runtimeName = lang === 'r' ? 'R' : 'Python';
    return path.join(runtimesDir(), runtimeName);
  }

  // BLOCK-86 P3 实机抓真 — 运行时在位判定不能只看插件安装记录：运行时可能由
  // 链外供给（手动放置/系统解析，如本机 R），plugin installed.json 里没有记录。
  // 返回 { plug（记录 plug 或按语言合成的最小 plug）, recordPresent,
  // statusPresent（runtimeStatus 目录+可执行探测）, lang }。
  async function locateRuntime(pluginId, installed) {
    const plug = installed.find((p) => p && p.id === pluginId) || null;
    let lang = plug && plug.language;
    if (!lang) {
      try { lang = await getManifestLanguage(pluginId); } catch { lang = null; }
    }
    const status = (() => { try { return getRuntimeStatus(); } catch { return null; } })();
    const entry = status && status[lang === 'r' ? 'r' : 'python'];
    return {
      plug: plug || (lang ? { id: pluginId, language: lang } : null),
      recordPresent: Boolean(plug),
      statusPresent: Boolean(entry && entry.installed),
      lang: lang || null,
    };
  }

  /**
   * 安装：记录 upsert → 契约推导逐个补装运行时。
   * 返回 { ok, pack, installed, updated, runtimes: [{ pluginId, ok, skipped?, error? }], requiresRestart }
   * 语义：记录安装成功即 ok=true；运行时缺失/失败如实列在 runtimes（不回滚）。
   */
  async function installPackWithRuntimes(dataDir, packRoot, { onRuntimeProgress } = {}) {
    const res = registry.installPack(dataDir, packRoot);
    if (!res.ok) return res;
    const declared = Array.isArray(res.pack.requiresRuntimes) ? res.pack.requiresRuntimes : [];
    const installed = getInstalledPlugins() || [];
    const runtimes = [];
    for (const item of declared) {
      const located = await locateRuntime(item.pluginId, installed);
      if (located.recordPresent) {
        runtimes.push({ pluginId: item.pluginId, ok: true, skipped: 'already_installed' });
        continue;
      }
      if (located.statusPresent) {
        // 链外供给的运行时（目录+可执行在位但无安装记录）同样不重装
        runtimes.push({ pluginId: item.pluginId, ok: true, skipped: 'runtime_present' });
        continue;
      }
      try {
        await installPlugin(item.pluginId, onRuntimeProgress
          ? (progress) => onRuntimeProgress(item.pluginId, progress)
          : undefined);
        runtimes.push({ pluginId: item.pluginId, ok: true });
      } catch (error) {
        runtimes.push({ pluginId: item.pluginId, ok: false, error: error && error.message });
      }
    }
    return {
      ...res,
      runtimes,
      requiresRestart: runtimes.some((r) => r.ok && !r.skipped),
    };
  }

  /**
   * 卸载影响预览（确认弹层的数据源，主进程富化体积/在位状态）。
   * 返回 { ok, packId, requiresRuntimes, runtimes: { removable, retained },
   *        packSource: { dir, exists, sizeBytes }, userDataPolicy }。
   */
  async function buildUninstallPlan(dataDir, packId) {
    const plan = registry.computeRuntimeRemovalPlan(dataDir, packId);
    if (!plan.ok) return plan;
    const record = registry.readInstalledPacks(dataDir).find((p) => p.packId === packId);
    const installed = getInstalledPlugins() || [];
    const removable = [];
    for (const pluginId of plan.removable) {
      const located = await locateRuntime(pluginId, installed);
      let sizeBytes = null;
      if (located.statusPresent || located.plug) {
        try { sizeBytes = dirSize(runtimeDirFor(located.lang)); } catch { sizeBytes = null; }
      }
      removable.push({
        pluginId,
        installed: located.statusPresent,
        sizeBytes: Number.isFinite(sizeBytes) && sizeBytes > 0 ? sizeBytes : null,
      });
    }
    const dir = record ? record.packRoot : null;
    let packSource = { dir, exists: false, sizeBytes: null };
    if (dir) {
      try {
        packSource = { dir, exists: fs.existsSync(dir), sizeBytes: null };
        if (packSource.exists) packSource.sizeBytes = dirSize(dir);
      } catch { /* 体积统计失败如实留空 */ }
    }
    return {
      ok: true,
      packId,
      requiresRuntimes: Array.isArray(record && record.requiresRuntimes) ? record.requiresRuntimes : [],
      runtimes: { removable, retained: plan.retained },
      packSource,
      // 三档语义（确认弹层文案依据）：领域资产删=removable 运行时+（可选）包源；
      // 用户数据永不触碰；包源目录默认保留（演示数据/脚本/插件内容都在其中）。
      userDataPolicy: 'results、项目文件与数据库不受影响',
    };
  }

  /**
   * 执行卸载：记录移除 →（可选）契约推导卸运行时 →（可选）删包源目录。
   * deleteRuntimes / deletePackSource 缺省 false——破坏性动作必须显式勾选。
   * 返回卸载报告：{ ok, packId, removed: { record, runtimes, packSourceDir? },
   *              kept: { packSourceDir?, userDataPolicy }, requiresRestart, error? }。
   */
  async function executeUninstall(dataDir, packId, { deleteRuntimes = false, deletePackSource = false } = {}) {
    const plan = registry.computeRuntimeRemovalPlan(dataDir, packId);
    if (!plan.ok) return { ok: false, error: plan.error };
    const record = registry.readInstalledPacks(dataDir).find((p) => p.packId === packId);
    const removed = { record: false, runtimes: [] };
    const kept = { userDataPolicy: 'results、项目文件与数据库不受影响' };

    const uninstallRes = registry.uninstallPack(dataDir, packId);
    if (!uninstallRes.ok) return { ok: false, error: uninstallRes.error };
    removed.record = true;

    if (deleteRuntimes) {
      const installed = getInstalledPlugins() || [];
      for (const pluginId of plan.removable) {
        const located = await locateRuntime(pluginId, installed);
        if (!located.statusPresent && !located.recordPresent) {
          removed.runtimes.push({ pluginId, ok: true, skipped: 'not_installed' });
          continue;
        }
        try {
          // located.plug 兜底为按语言合成的最小 plug（链外供给的运行时）
          await uninstallRuntime(pluginId, located.plug);
          removed.runtimes.push({ pluginId, ok: true });
        } catch (error) {
          removed.runtimes.push({ pluginId, ok: false, error: error && error.message });
        }
      }
    }

    if (deletePackSource) {
      // 破坏性护栏：只删记录指向、且确实含 pack.json 的目录（防错删任意路径）。
      const dir = record && record.packRoot;
      let packJsonOk = false;
      try { packJsonOk = Boolean(dir) && require('fs').existsSync(path.join(dir, 'pack.json')); } catch { packJsonOk = false; }
      if (!packJsonOk) {
        kept.packSourceDir = dir || null;
        kept.packSourceError = 'pack_source_guard_failed';
      } else {
        try {
          rmDir(dir);
          removed.packSourceDir = dir;
        } catch (error) {
          kept.packSourceDir = dir;
          kept.packSourceError = error && error.message;
        }
      }
    } else {
      kept.packSourceDir = (record && record.packRoot) || null;
    }

    return {
      ok: true,
      packId,
      removed,
      kept,
      requiresRestart: removed.runtimes.some((r) => r.ok && !r.skipped),
    };
  }

  return { installPackWithRuntimes, buildUninstallPlan, executeUninstall };
}

module.exports = { createPackLifecycle };

/**
 * Plugin Manager — 桌面版插件下载/安装/卸载/更新
 *
 * 每个插件是一个 zip，包含：
 *   plugin.json          — 插件清单（language/packages/platform/...）
 *   tool-definition.json — 工具定义（_data.ts 里的对象）
 *   scripts/             — R/Python 脚本
 *   packages/            — 预编译语言包
 *   demo-data/           — Demo 数据（可选）
 *
 * 安装流程：下载 → SHA256 校验 → 解压 → 版本校验 → 安装包 → 注册 → 记录
 * 卸载流程：删除专属包 → 删除脚本/数据 → 注销 → 记录
 *
 * BLOCK-9.2 PHASE 3: 1457 → ~360 lines. The 4 install* orchestrators
 * + checkUpdates / loadAllPlugins / uninstallPlugin stay in this file
 * (they cross-reference each other + onProgress callbacks + multiple
 * SHARED_BACKEND_DIR requires that would create a fragile dependency
 * graph if every helper were its own module). The plumbing helpers
 * (paths / installed / io / zip / manifest-source / content-plugin /
 * registry / runtime / uninstall) move to ./plugin/. The 21 public
 * exports below are preserved verbatim so callers (`require('./plugin-
 * manager')`) see no behavior change.
 */

