// ── Ctrl/Cmd + 滚轮 → 页面缩放 ────────────────────────────────
// 无边框窗口没有菜单栏，Electron 的 zoomIn/zoomOut 菜单角色快捷键不可达，
// 所以在 preload 里挂全局 wheel 监听：对任何加载本脚本的窗口都生效（含
// BLOCK-59 弹出窗），且不依赖 React 路由。经 window:zoom-by 驱动主进程缩放。
// 用 requestAnimationFrame 合并同一帧内的滚轮增量，避免高频事件打爆 IPC。
(function setupCtrlWheelZoom() {
  const ZOOM_PER_100PX = 0.5; // 每 100px 滚轮增量对应的 zoomLevel 步进
  const MAX_STEP = 1;         // 单帧最大步进，防止触控板甩动导致跳变

  if (typeof window === 'undefined' || typeof window.addEventListener !== 'function') {
    return;
  }

  let pendingDelta = 0;
  let scheduled = false;

  const flush = () => {
    scheduled = false;
    const deltaY = pendingDelta;
    pendingDelta = 0;
    if (!deltaY) return;
    const raw = (-deltaY / 100) * ZOOM_PER_100PX;
    const step = Math.max(-MAX_STEP, Math.min(MAX_STEP, raw));
    if (step) ipcRenderer.send('window:zoom-by', step);
  };

  window.addEventListener(
    'wheel',
    (event) => {
      // 仅 Ctrl/Cmd 按住时缩放；macOS 触控板双指捏合同样会带 ctrlKey。
      if (!event.ctrlKey && !event.metaKey) return;
      // 阻止 Chromium 自身的缩放，避免与我们的步进叠加造成双倍缩放。
      event.preventDefault();
      pendingDelta += typeof event.deltaY === 'number' ? event.deltaY : 0;
      if (scheduled) return;
      scheduled = true;
      const raf =
        typeof window.requestAnimationFrame === 'function'
          ? window.requestAnimationFrame.bind(window)
          : (fn) => setTimeout(fn, 16);
      raf(flush);
    },
    // passive:false 才能 preventDefault
    { passive: false },
  );
})();

/**
 * static-server.js — 桌面版本地静态文件服务器
 *
 * 用原生 Node.js http 模块（不依赖 express）托管前端 build 产物。
 *
 * 阶段 3（desktop-spa）起支持双服务器：
 *   - Vite SPA build → :3002（主窗口，base '/'，无 baseUrl 前缀）
 *   - Docusaurus build → :3003（docs/blog iframe 过渡，baseUrl=/Petri/）
 *
 * loadFile（file://）无法正确解析绝对路径资源，故仍需 HTTP 协议。
 */

const http = require('http');
const path = require('path');
const fs = require('fs');

// 活跃服务器实例（按端口索引）
const servers = {};

// MIME 类型映射
const MIME = {
  '.html': 'text/html',
  '.js': 'application/javascript',
  '.mjs': 'application/javascript',
  '.css': 'text/css',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.svg': 'image/svg+xml',
  '.json': 'application/json',
  '.woff2': 'font/woff2',
  '.woff': 'font/woff',
  '.ttf': 'font/ttf',
  '.pdf': 'application/pdf',
  '.csv': 'text/csv',
  '.tsv': 'text/tab-separated-values',
  '.txt': 'text/plain',
  '.rds': 'application/octet-stream',
  '.map': 'application/json',
};

function getMime(ext) {
  return MIME[ext.toLowerCase()] || 'application/octet-stream';
}

/**
 * 启动静态文件服务器
 * @param {string} buildDir - 要托管的目录
 * @param {object} opts
 * @param {number} opts.port - 端口（默认 3002）
 * @param {string} opts.baseUrl - 路径前缀，如 '/Petri/'（Docusaurus）；Vite SPA 用 '/'
 * @param {string} opts.label - 日志标签
 * @param {boolean} opts.spaFallback - 未命中的路径是否回退 index.html（SPA 路由）
 * @param {boolean} opts.fallbackToRandomPort - 端口占用时是否回退到系统分配端口
 * @returns {Promise<object|null>} server 实例
 */
async function startStaticServer(buildDir, opts = {}) {
  const port = opts.port || 3002;
  const baseUrl = opts.baseUrl || '/';
  const label = opts.label || 'static-server';
  const spaFallback = opts.spaFallback !== false;
  const fallbackToRandomPort = opts.fallbackToRandomPort === true;

  if (servers[port]) return servers[port];
  if (!fs.existsSync(buildDir)) {
    console.warn(`[${label}] build dir not found:`, buildDir);
    return null;
  }

  // 归一化 baseUrl：确保以 / 开头、以 / 结尾
  const prefix = baseUrl.startsWith('/') ? baseUrl : '/' + baseUrl;
  const stripPrefix = prefix === '/' ? null : prefix.replace(/\/$/, ''); // 去尾斜杠，如 '/Petri'

  const server = http.createServer((req, res) => {
    // CORS
    res.setHeader('Access-Control-Allow-Origin', '*');
    res.setHeader('Access-Control-Allow-Methods', 'GET, HEAD, OPTIONS');

    if (req.method === 'OPTIONS') {
      res.writeHead(204);
      res.end();
      return;
    }

    // 解析 URL，去掉 query string
    const urlPath = req.url.split('?')[0];

    // 桌面版禁用 PWA：拦截 sw.js / manifest.json / workbox 相关请求
    if (
      urlPath.endsWith('/sw.js') ||
      urlPath === '/sw.js' ||
      urlPath.endsWith('/manifest.json') ||
      urlPath.startsWith('/workbox-')
    ) {
      res.writeHead(404, { 'Content-Type': 'text/plain' });
      res.end('Not found (PWA disabled in desktop)');
      return;
    }

    // 去掉 baseUrl 前缀（如有）
    let filePath = urlPath;
    if (stripPrefix && filePath.startsWith(stripPrefix)) {
      filePath = filePath.slice(stripPrefix.length);
    }
    if (!filePath || filePath === '/') {
      filePath = '/index.html';
    }

    const fullPath = path.join(buildDir, filePath);

    // 安全检查：不能访问 buildDir 之外的文件
    if (!fullPath.startsWith(buildDir)) {
      res.writeHead(403, { 'Content-Type': 'text/plain' });
      res.end('Forbidden');
      return;
    }

    // 检查文件是否存在
    if (!fs.existsSync(fullPath)) {
      if (spaFallback) {
        const indexPath = path.join(buildDir, 'index.html');
        if (fs.existsSync(indexPath)) {
          res.writeHead(200, { 'Content-Type': 'text/html' });
          res.end(fs.readFileSync(indexPath));
          return;
        }
      }
      res.writeHead(404, { 'Content-Type': 'text/plain' });
      res.end('Not found');
      return;
    }

    const stat = fs.statSync(fullPath);
    if (stat.isDirectory()) {
      const indexPath = path.join(fullPath, 'index.html');
      if (fs.existsSync(indexPath)) {
        res.writeHead(200, { 'Content-Type': 'text/html' });
        res.end(fs.readFileSync(indexPath));
        return;
      }
      res.writeHead(404, { 'Content-Type': 'text/plain' });
      res.end('Not found');
      return;
    }

    // 读取并返回文件
    const ext = path.extname(fullPath);
    const mime = getMime(ext);
    res.writeHead(200, {
      'Content-Type': mime,
      'Content-Length': stat.size,
      'Cache-Control': 'no-store, no-cache, must-revalidate, proxy-revalidate',
      Pragma: 'no-cache',
      Expires: '0',
    });
    fs.createReadStream(fullPath).pipe(res);
  });

  const listen = (listenPort) =>
    new Promise((resolve, reject) => {
      const onError = (err) => {
        server.off('listening', onListening);
        reject(err);
      };
      const onListening = () => {
        server.off('error', onError);
        resolve();
      };
      server.once('error', onError);
      server.once('listening', onListening);
      server.listen(listenPort, '127.0.0.1');
    });

  try {
    await listen(port);
  } catch (err) {
    if (!fallbackToRandomPort || err?.code !== 'EADDRINUSE') {
      console.error(`[${label}] server failed:`, err);
      return null;
    }
    console.warn(`[${label}] port ${port} is occupied; selecting an available port`);
    try {
      await listen(0);
    } catch (fallbackError) {
      console.error(`[${label}] fallback server failed:`, fallbackError);
      return null;
    }
  }

  const address = server.address();
  const actualPort = typeof address === 'object' && address ? address.port : port;
  servers[actualPort] = server;
  server.on('error', (err) => {
    console.error(`[${label}] server error:`, err);
  });
  console.log(`[${label}] serving ${buildDir} on http://127.0.0.1:${actualPort}`);
  return server;
}

/** 停止指定端口的服务器（不传则停止全部） */
function stopStaticServer(port) {
  if (port) {
    if (servers[port]) {
      servers[port].close();
      delete servers[port];
    }
    return;
  }
  for (const p of Object.keys(servers)) {
    servers[p].close();
    delete servers[p];
  }
}

module.exports = { startStaticServer, stopStaticServer };

/**
 * telemetry.js — M2-3 可选错误遥测（V3）
 *
 * 设计原则（隐私优先）：
 * 1. 默认关闭——只有用户在设置页主动开启"错误反馈"后才会发送。
 * 2. 最小 payload——仅含 category / appVersion / errorSummary / timestamp，
 *    绝不含用户数据、文件路径、文件名、API key 或对话内容。
 * 3. 失败静默——网络异常或端点不可达时直接吞掉，不影响任何业务流程。
 * 4. 可随时关——每次上报前都重新读设置，关掉后立即停止发送。
 *
 * 主进程模块，被 main.js 的 IPC handler 调用。
 */

const { app } = require('electron');
const path = require('path');

// 占位端点——上线前替换为真实接收服务。HTTPS 保证传输加密。
const TELEMETRY_ENDPOINT = 'https://petri.com/api/telemetry';

// errorSummary 最大长度，防止意外把长堆栈/路径泄出去。
const MAX_SUMMARY_LEN = 200;

// 与 main.js resolveResource 一致的资源解析（不依赖 main 内部函数）
// 开发模式：仓库根（desktop-app/../ ）
// 打包模式：process.resourcesPath
const _PROJECT_ROOT = path.join(__dirname, '..', '..');
const _IS_DEV = !app.isPackaged;
function _resolveResource(...parts) {
  if (_IS_DEV) return path.join(_PROJECT_ROOT, ...parts);
  return path.join(process.resourcesPath, ...parts);
}

/**
 * 读取遥测开关。复用 ai-settings.json 存储（同一文件，字段 telemetry_enabled）。
 * 默认 false——硬要求。
 * @returns {boolean}
 */
function isTelemetryEnabled() {
  try {
    const { getAiSettings } = require(_resolveResource('petri-server', 'helpers', 'ai-settings.js'));
    const s = getAiSettings();
    return !!(s && s.telemetry_enabled === true);
  } catch {
    // 读设置失败时按"关闭"处理，绝不误发。
    return false;
  }
}

/**
 * 上报错误。最小化 payload，仅含分类 + 版本 + 错误摘要 + 时间戳。
 *
 * @param {{category?: string, errorSummary?: string}} payload - 渲染进程传入的极简信息
 * @returns {Promise<{ok: boolean, reason?: string}>}
 */
async function reportError(payload) {
  // 1. 开关检查——默认关闭，关则直接 return
  if (!isTelemetryEnabled()) {
    return { ok: false, reason: 'disabled' };
  }

  // 2. 构造最小 payload，白名单字段，拒绝任何用户数据/路径
  const category = _sanitize(String((payload && payload.category) || 'unknown'), 50);
  const errorSummary = _sanitize(String((payload && payload.errorSummary) || ''), MAX_SUMMARY_LEN);
  const body = {
    category,
    appVersion: _getAppVersion(),
    errorSummary,
    timestamp: new Date().toISOString(),
  };

  // 3. 上报，失败静默
  try {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 5000); // 5s 超时，不阻塞
    const res = await fetch(TELEMETRY_ENDPOINT, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
      signal: controller.signal,
    });
    clearTimeout(timer);
    if (!res.ok) {
      return { ok: false, reason: 'http_' + res.status };
    }
    return { ok: true };
  } catch (e) {
    // 网络异常/超时/端点不可达——静默
    return { ok: false, reason: 'network' };
  }
}

/**
 * 获取应用版本。优先 app.getVersion()，回退 package.json。
 */
function _getAppVersion() {
  try {
    if (app && typeof app.getVersion === 'function') {
      return app.getVersion();
    }
  } catch {}
  try {
    const pkg = require(path.join(__dirname, '..', 'package.json'));
    return (pkg && pkg.version) || 'unknown';
  } catch {
    return 'unknown';
  }
}

/**
 * 清洗字符串：截断 + 去掉潜在路径/换行。
 * 即便上游误传了带路径的错误信息，也只保留前 N 字符的摘要。
 */
function _sanitize(str, maxLen) {
  if (!str) return '';
  let s = String(str)
    .replace(/[\r\n]+/g, ' ')
    .trim();
  if (s.length > maxLen) s = s.slice(0, maxLen);
  return s;
}

module.exports = {
  reportError,
  isTelemetryEnabled,
  TELEMETRY_ENDPOINT,
};

