  assert.equal(status.ok, true);
  const entry = status.process;
  assert.ok(entry, 'process entry visible via process_status');
  assert.equal(entry.processId, res.processId);

  // 等命令真正退出，日志应含完整输出
  const final = await (async function poll() {
