/** 假 ssh 进程：EventEmitter + pid + kill()，供注入。 */
function fakeProcessFactory(spawned) {
  return function spawnFake() {
    const proc = new EventEmitter();
    proc.pid = 40000 + spawned.length + 1;
    spawned.push(proc);
    return proc;
  };
}

