test('messages 信封带 compaction 字段；compact 端点开关关时 409', async () => {
  const msgs = await new Promise((resolvePromise) => {
    http.get(`${baseUrl}/api/ai/conversations/${CONV}/messages?limit=5`, (res) => {
      let d = '';
