// CommonJS helper used by test/chat-file-references.test.mjs to load the
// /api/harness/file-references/resolve route with a stubbed db module.
// After PHASE 2.2a (harness 8-subdomain split), also clears the harness/
// subdirectory from require.cache so that subdomains re-resolve their db
// reference through the patched _resolveFilename hook.
const path = require('path');
const fs = require('fs');
const Module = require('module');

function clearHarnessCache(rServer) {
  const harnessDir = path.join(rServer, 'routes', 'harness');
  const patterns = [
    path.join(rServer, 'routes', 'harness.js'),
    path.join(harnessDir, 'index.js'),
    path.join(harnessDir, 'resources.js'),
    path.join(harnessDir, 'workflow.js'),
    path.join(harnessDir, 'repair.js'),
    path.join(harnessDir, 'scientific-task.js'),
    path.join(harnessDir, 'context.js'),
    path.join(harnessDir, 'file-references.js'),
    path.join(harnessDir, 'loop.js'),
    path.join(rServer, 'routes', '_helpers', 'harness-shared.js'),
    path.join(rServer, 'routes', '_helpers', 'workspace-file-index.js'),
    path.join(rServer, 'db.js'),
  ];
  for (const p of patterns) {
    if (fs.existsSync(p)) delete require.cache[p];
  }
  if (fs.existsSync(harnessDir)) {
    for (const entry of fs.readdirSync(harnessDir)) {
      const full = path.join(harnessDir, entry);
      if (entry.endsWith('.js') && fs.statSync(full).isFile()) {
        delete require.cache[full];
      }
    }
  }
}

function loadResolveRoute(dbStub) {
  const rServer = path.resolve(__dirname, '..', 'core', 'petri-server');
  const harnessModulePath = path.join(rServer, 'routes', 'harness.js');
  const dbModulePath = path.join(rServer, 'db.js');

  clearHarnessCache(rServer);

  const originalResolve = Module._resolveFilename;
  Module._resolveFilename = function patchedResolve(request, isMain, options) {
    if (/\/db$/.test(request)) return dbModulePath;
    return originalResolve(request, isMain, options);
  };

  const handlers = {};
  const app = {
    post(p, ...args) {
      let handler = args[args.length - 1];
      if (args.length === 1 && typeof args[0] === 'function') handler = args[0];
      if (typeof handler === 'function') handlers['POST ' + p] = handler;
    },
    get(p, ...args) {
      let handler = args[args.length - 1];
      if (args.length === 1 && typeof args[0] === 'function') handler = args[0];
      if (typeof handler === 'function') handlers['GET ' + p] = handler;
    },
  };

  require.cache[dbModulePath] = {
    id: dbModulePath,
    filename: dbModulePath,
    loaded: true,
    exports: dbStub,
  };

  try {
    require(harnessModulePath)(app);
  } finally {
    Module._resolveFilename = originalResolve;
  }

  return function invoke(body, opts) {
    opts = opts || {};
    const handler = handlers['POST /api/harness/file-references/resolve'];
    if (!handler) throw new Error('route not registered');
    let status = 200;
    let payload = null;
    const req = {
      user: { id: opts.userId || 'u_local' },
      isInternal: !!opts.isInternal,
      body,
      query: {},
    };
    const res = {
      status(code) {
        status = code;
        return this;
      },
      json(obj) {
        payload = obj;
        return this;
      },
    };
    return handler(req, res).then(() => ({ status, body: payload }));
  };
}

module.exports = { loadResolveRoute };

/**
 * BLOCK-10-ARCHITECTURE PHASE 1.2 (A-010) — 6 core desktop env reads
 * centralised through config-helper.getCoreEnv() / getEnv().
 *
 * Coverage:
 *   A-010.1 getCoreEnv() default busyTimeoutMs === 10000
 *   A-010.2 getCoreEnv() returns all 6 documented fields
 *   A-010.3 env override flows through (PETRI_R_HOME → coreEnv.rHome)
 *   A-010.4 getCoreEnv() snapshot is frozen (cannot be mutated by caller)
 *   A-010.5 getEnv(KEY, fallback) falls back to literal when env unset
 *   A-010.6 getEnv treats empty-string env as unset (returns fallback)
 *   A-010.7 6 core env reads in core/petri-server/config.js no longer hit
 *             process.env directly
 *
 * 运行：cd desktop && node --test test/config-helper-centralized.test.mjs
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { pathToFileURL } from 'node:url';
import { createRequire } from 'node:module';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(__dirname, '..');

// config-helper is a CJS module exporting a Proxy via `module.exports = new Proxy(...)`.
// Importing it from an ESM test requires interop: `import pkg from '...'; const h = pkg.default ?? pkg;`.
const configHelperModule = (
  await import(pathToFileURL(path.join(root, 'core/shared-backend/config-helper.js')).href)
).default;
const configHelper = configHelperModule && configHelperModule.default
  ? configHelperModule.default
  : configHelperModule;

const { getEnv, getCoreEnv, getBusyTimeout } = configHelper;

// createRequire is needed so we can `require()` the CJS config.js inside a
// sync test body (top-level await works for the config-helper import above,
// but not from within a sync `test()` callback).
const req = createRequire(path.join(root, 'package.json'));

// 6 core env keys the helper owns. Save + restore around every test.
const CORE_ENV_KEYS = [
  'PETRI_R_HOME',
  'PETRI_LOCAL_RESULTS_DIR',
  'PETRI_LOCAL_UPLOADS_DIR',
  'PETRI_TEMP_DIR',
  'PETRI_DB_PATH',
];

function snapshotEnv() {
  const saved = {};
  for (const key of CORE_ENV_KEYS) saved[key] = process.env[key];
  return saved;
}

function restoreEnv(saved) {
  for (const key of CORE_ENV_KEYS) {
    if (saved[key] === undefined) delete process.env[key];
    else process.env[key] = saved[key];
  }
  // restore default busy_timeout after potential override.
  configHelper.setDbConfig({ busyTimeoutMs: 10000 });
}

test('A-010.1 getCoreEnv() default busyTimeoutMs === 10000', () => {
  const saved = snapshotEnv();
  restoreEnv({}); // wipe everything for a clean baseline
  assert.strictEqual(getCoreEnv().busyTimeoutMs, 10000);
  assert.strictEqual(getBusyTimeout(), 10000);
  restoreEnv(saved);
});

test('A-010.2 getCoreEnv() returns all 6 documented fields', () => {
  const core = getCoreEnv();
  for (const key of [
    'busyTimeoutMs',
    'rHome',
    'localResultsDir',
    'localUploadsDir',
    'tempDir',
    'dbPath',
  ]) {
    assert.ok(key in core, `getCoreEnv() must include \`${key}\``);
  }
  assert.strictEqual(core.tempDir, '/tmp/petri-tmp', 'tempDir fallback must match');
});

test('A-010.3 env override flows through getCoreEnv()', () => {
  const saved = snapshotEnv();
  process.env.PETRI_R_HOME = '/custom/R';
  process.env.PETRI_DB_PATH = '/custom/petri.db';
  process.env.PETRI_TEMP_DIR = '/custom/tmp';
  process.env.PETRI_LOCAL_RESULTS_DIR = '/custom/results';
  process.env.PETRI_LOCAL_UPLOADS_DIR = '/custom/uploads';
  const core = getCoreEnv();
  assert.strictEqual(core.rHome, '/custom/R');
  assert.strictEqual(core.dbPath, '/custom/petri.db');
  assert.strictEqual(core.tempDir, '/custom/tmp');
  assert.strictEqual(core.localResultsDir, '/custom/results');
  assert.strictEqual(core.localUploadsDir, '/custom/uploads');
  restoreEnv(saved);
});

test('A-010.4 getCoreEnv() snapshot is frozen', () => {
  const core = getCoreEnv();
  assert.ok(Object.isFrozen(core), 'getCoreEnv() must return a frozen snapshot');
  assert.throws(() => { core.rHome = '/mutated'; }, TypeError);
  assert.throws(() => { core.tempDir = '/mutated'; }, TypeError);
});

test('A-010.5 getEnv(KEY, fallback) returns literal when env unset', () => {
  const saved = snapshotEnv();
  delete process.env.PETRI_R_HOME;
  assert.strictEqual(getEnv('PETRI_R_HOME', '[fallback]'), '[fallback]');
  restoreEnv(saved);
});

test('A-010.6 getEnv treats empty-string env as unset', () => {
  process.env.PETRI_R_HOME = '';
  try {
    assert.strictEqual(
      getEnv('PETRI_R_HOME', '[fallback]'),
      '[fallback]',
      'empty-string env must not silently win against the documented fallback',
    );
  } finally {
    delete process.env.PETRI_R_HOME;
  }
});

test('A-010.7 6 core env reads in core/petri-server/config.js no longer hit process.env directly', () => {
  // The 6 fields routed through getCoreEnv() in config.js must no longer
  // read process.env.X directly. We assert source-text against the new
  // pattern: `rHome: _coreEnv.rHome` (or similar). The legacy literal
  // `process.env.PETRI_R_HOME || ''` must be gone.
  const configSource = fs.readFileSync(
    path.join(root, 'core/petri-server/config.js'),
    'utf8',
  );

  // Positive: the helper is referenced.
  assert.ok(
    configSource.includes('getCoreEnv'),
    'core/petri-server/config.js must read core env through config-helper.getCoreEnv()',
  );

  // Negative: the 6 directly-read env fields must no longer appear in
  // the form `process.env.<KEY> ||`. Comments that reference the previous
  // behaviour are fine (they describe the migration), but executable code
  // must route through the helper.
  const legacyReadPatterns = [
    /process\.env\.PETRI_R_HOME\s*\|\|/,
    /process\.env\.PETRI_LOCAL_RESULTS_DIR\s*\|\|/,
    /process\.env\.PETRI_LOCAL_UPLOADS_DIR\s*\|\|/,
    /process\.env\.PETRI_TEMP_DIR\s*\|\|/,
    /process\.env\.PETRI_DB_PATH\s*\|\|/,
  ];
  for (const re of legacyReadPatterns) {
    assert.ok(
      !re.test(configSource),
      `core/petri-server/config.js must not carry legacy \`${re}\``,
    );
  }

  // Sanity: the helper-backed fields are still observable through the
  // config object. We require() the CJS config.js fresh so the new env
  // values are picked up at module load time.
  process.env.PETRI_R_HOME = '/sanity/R';
  process.env.PETRI_TEMP_DIR = '/sanity/tmp';
  process.env.PETRI_DB_PATH = '/sanity/petri.db';
  try {
    // Bust the require cache so config.js re-evaluates with the new env.
    const configPath = req.resolve(
      path.join(root, 'core/petri-server/config.js'),
    );
    delete req.cache[configPath];
    const freshConfig = req(configPath);
    assert.strictEqual(freshConfig.rHome, '/sanity/R');
    assert.strictEqual(freshConfig.tempDir, '/sanity/tmp');
    assert.strictEqual(freshConfig.dbPath, '/sanity/petri.db');
  } finally {
    delete process.env.PETRI_R_HOME;
    delete process.env.PETRI_TEMP_DIR;
    delete process.env.PETRI_DB_PATH;
  }
});

/**
 * BLOCK-10 PHASE 1.1 (PR-012) — branch-db + result-db share one connection
 * when targeting the same file (desktop main + petri-server MCP child process).
 *
 * Coverage:
 *   PR-012.1 branch + result use the same resolved file path (legacy
 *             single-file layout preserved 100%).
 *   PR-012.2 openDb('branch') and openDb('result') return the SAME
 *             Database instance when the resolved file paths match
 *             (singleton dedup; the original PR-012 bug).
 *   PR-012.3 data round-trip: openDb('branch') insert -> openDb('result')
 *             reads -> cross-role visibility (proves single shared
 *             handle, not two disconnected handles).
 *
 * 运行：cd desktop && node --test test/db-singleton-shared-file.test.mjs
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { createRequire } from 'node:module';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(__dirname, '..');
const coreServerRoot = path.join(root, 'core', 'petri-server');
const req = createRequire(path.join(coreServerRoot, 'package.json'));
const rootReq = createRequire(path.join(root, 'package.json'));

import { openDb, closeDb, closeAll, _reset } from '../src/database/_db-singleton.js';
import { getDatabase, closeDatabase } from '../src/database/branch-db.js';
import { getDatabase as getResultDatabase, closeDatabase as closeResultDatabase } from '../src/database/result-db.js';

function mkTmp() {
  return fs.mkdtempSync(path.join(os.tmpdir(), 'petri-db-shared-'));
}

test('PR-012.1 branch-db.getDatabasePath() === result-db.getDatabasePath() under legacy single-file layout', (t) => {
  const tmp = mkTmp();
  process.env.PETRI_LOCAL_DATA_DIR = tmp;
  process.env.PETRI_BETTER_SQLITE3_ROOT = coreServerRoot;
  _reset();

  t.after(() => {
    closeAll();
    _reset();
    delete process.env.PETRI_LOCAL_DATA_DIR;
    delete process.env.PETRI_BETTER_SQLITE3_ROOT;
    try { fs.rmSync(tmp, { recursive: true, force: true }); } catch {}
  });

  // Both modules must agree on the same legacy file path so PR-012 dedup
  // can collapse them into a single handle.
  const branchPath = rootReq('./src/database/branch-db.js').getDatabasePath();
  const resultPath = rootReq('./src/database/result-db.js').getDatabasePath();
  assert.strictEqual(branchPath, resultPath, 'branch + result must resolve to the same petri.db path');
  assert.ok(branchPath.endsWith('petri.db'), 'path must keep the legacy petri.db filename');
});

test('PR-012.2 openDb(branch) and openDb(result) return the same Database instance', (t) => {
  const tmp = mkTmp();
  process.env.PETRI_LOCAL_DATA_DIR = tmp;
  process.env.PETRI_BETTER_SQLITE3_ROOT = coreServerRoot;
  _reset();

  t.after(() => {
    closeAll();
    _reset();
    delete process.env.PETRI_LOCAL_DATA_DIR;
    delete process.env.PETRI_BETTER_SQLITE3_ROOT;
    try { fs.rmSync(tmp, { recursive: true, force: true }); } catch {}
  });

  const branch = openDb('branch');
  const result = openDb('result');
  assert.strictEqual(
    branch,
    result,
    'openDb(branch) and openDb(result) must dedup to the same Database (PR-012 fix)',
  );

  // The legacy public shims from branch-db / result-db must agree too —
  // otherwise petri-server/mcp/branch-context.js would still see two distinct
  // handles via the legacy API surface.
  const legacyBranch = getDatabase();
  const legacyResult = getResultDatabase();
  assert.strictEqual(legacyBranch, legacyResult, 'branch-db.getDatabase === result-db.getDatabase');
  assert.strictEqual(legacyBranch, branch, 'legacy shim must forward to the singleton');
});

test('PR-012.3 writes via branch-db are visible to result-db (single shared handle)', (t) => {
  const tmp = mkTmp();
  process.env.PETRI_LOCAL_DATA_DIR = tmp;
  process.env.PETRI_BETTER_SQLITE3_ROOT = coreServerRoot;
  _reset();

  t.after(() => {
    closeAll();
    _reset();
    delete process.env.PETRI_LOCAL_DATA_DIR;
    delete process.env.PETRI_BETTER_SQLITE3_ROOT;
    try { fs.rmSync(tmp, { recursive: true, force: true }); } catch {}
  });

  // Create the projects table via the branch handle (the schema the
  // legacy single-file layout relies on).
  const branchHandle = getDatabase();
  branchHandle.exec(`
    CREATE TABLE IF NOT EXISTS shared_probe (
      id INTEGER PRIMARY KEY,
      payload TEXT NOT NULL
    )
  `);
  branchHandle.prepare('INSERT INTO shared_probe (id, payload) VALUES (?, ?)').run(1, 'via-branch-db');

  // Read it back from the result handle. If PR-012 dedup is correct,
  // both handles point at the same connection and the row is visible.
  const resultHandle = getResultDatabase();
  const row = resultHandle.prepare('SELECT id, payload FROM shared_probe WHERE id = ?').get(1);
  assert.ok(row, 'row written via branch-db handle must be visible via result-db handle');
  assert.strictEqual(row.payload, 'via-branch-db');

  // Cleanup the probe table so we don't leave schema behind for the
  // real schema-migration test suites.
  resultHandle.exec('DROP TABLE IF EXISTS shared_probe');
});

test('PR-012 backward-compat shims: branch-db.closeDatabase closes the singleton for both roles', (t) => {
  const tmp = mkTmp();
  process.env.PETRI_LOCAL_DATA_DIR = tmp;
  process.env.PETRI_BETTER_SQLITE3_ROOT = coreServerRoot;
  _reset();

  t.after(() => {
    closeAll();
    _reset();
    delete process.env.PETRI_LOCAL_DATA_DIR;
    delete process.env.PETRI_BETTER_SQLITE3_ROOT;
    try { fs.rmSync(tmp, { recursive: true, force: true }); } catch {}
  });

  // open via result (any role) — both roles share the same handle.
  const resultHandle = getResultDatabase();
  assert.ok(resultHandle.open, 'result handle must start open');

  // close via the branch shim — this should also invalidate the result
  // handle because PR-012 dedup means they're literally the same
  // Database object.
  closeDatabase();
  assert.ok(!resultHandle.open, 'closing via branch-db shim must also close the result handle');
});

/**
 * BLOCK-10 PHASE 1.1 (A-007) — DB singleton test.
 *
 * Coverage:
 *   A-007.1 openDb('branch') 单例（多次调用返回同一对象）
 *   A-007.2 openDb('result') 单例（不同 role 不同 connection key）
 *   A-007.3 closeDb + 重新 openDb 拿到新连接
 *   A-007.4 closeAll 关闭所有
 *   A-007.5 busy_timeout 来自 getBusyTimeout()（mock config 改值验证）
 *   A-007.6 WAL 模式验证
 *   A-007.7 未知 role 抛错
 *   A-007.8 foreign_keys ON 验证
 *
 * 运行：cd desktop && node --test test/db-singleton.test.mjs
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { createRequire } from 'node:module';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(__dirname, '..');
const coreServerRoot = path.join(root, 'core', 'petri-server');
const req = createRequire(path.join(coreServerRoot, 'package.json'));

// Core's better-sqlite3 — the migration-runner paths and singleton both
// point here when PETRI_BETTER_SQLITE3_ROOT is set.
const Database = req('better-sqlite3');

import { openDb, closeDb, closeAll, _reset } from '../src/database/_db-singleton.js';
import configHelper from '../core/shared-backend/config-helper.js';
const { getBusyTimeout, setDbConfig, getDbConfig } = configHelper;

function mkTmp() {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'petri-db-singleton-'));
  return dir;
}

// Better-sqlite3 PRAGMA returns the *current* journal_mode setting.
function readJournalMode(db) {
  return db.pragma('journal_mode', { simple: true });
}

function readBusyTimeout(db) {
  return db.pragma('busy_timeout', { simple: true });
}

function readForeignKeys(db) {
  return db.pragma('foreign_keys', { simple: true });
}

test('A-007.1 openDb(branch) returns the same instance on repeated calls', (t) => {
  const tmp = mkTmp();
  process.env.PETRI_LOCAL_DATA_DIR = tmp;
  process.env.PETRI_BETTER_SQLITE3_ROOT = coreServerRoot;
  _reset();

  t.after(() => {
    closeAll();
    _reset();
    delete process.env.PETRI_LOCAL_DATA_DIR;
    delete process.env.PETRI_BETTER_SQLITE3_ROOT;
    try { fs.rmSync(tmp, { recursive: true, force: true }); } catch {}
  });

  const a = openDb('branch');
  const b = openDb('branch');
  assert.strictEqual(a, b, 'openDb(branch) must return the same Database instance (singleton)');
});

test('A-007.2 openDb(result) returns the same instance on repeated calls', (t) => {
  const tmp = mkTmp();
  process.env.PETRI_LOCAL_DATA_DIR = tmp;
  process.env.PETRI_BETTER_SQLITE3_ROOT = coreServerRoot;
  _reset();

  t.after(() => {
    closeAll();
    _reset();
    delete process.env.PETRI_LOCAL_DATA_DIR;
    delete process.env.PETRI_BETTER_SQLITE3_ROOT;
    try { fs.rmSync(tmp, { recursive: true, force: true }); } catch {}
  });

  const a = openDb('result');
  const b = openDb('result');
  assert.strictEqual(a, b, 'openDb(result) must return the same Database instance (singleton)');
});

test('A-007.3 closeDb + reopen yields a brand new connection', (t) => {
  const tmp = mkTmp();
  process.env.PETRI_LOCAL_DATA_DIR = tmp;
  process.env.PETRI_BETTER_SQLITE3_ROOT = coreServerRoot;
  _reset();

  t.after(() => {
    closeAll();
    _reset();
    delete process.env.PETRI_LOCAL_DATA_DIR;
    delete process.env.PETRI_BETTER_SQLITE3_ROOT;
    try { fs.rmSync(tmp, { recursive: true, force: true }); } catch {}
  });

  const before = openDb('branch');
  assert.ok(before.open, 'first connection must be open');
  closeDb('branch');
  // closeDb removes from cache; the old handle is now closed (better-sqlite3
  // throws if you call .prepare on it after close, but identity stays).
  const after = openDb('branch');
  assert.notStrictEqual(after, before, 'after closeDb, reopen must hand back a fresh Database');
  assert.ok(after.open, 'reopened connection must be open');
  // pragma-set state must persist across reopen — journal_mode stays WAL
  assert.strictEqual(readJournalMode(after), 'wal');
});

test('A-007.4 closeAll closes every cached connection', (t) => {
  const tmp = mkTmp();
  process.env.PETRI_LOCAL_DATA_DIR = tmp;
  process.env.PETRI_BETTER_SQLITE3_ROOT = coreServerRoot;
  _reset();

  t.after(() => {
    closeAll();
    _reset();
    delete process.env.PETRI_LOCAL_DATA_DIR;
    delete process.env.PETRI_BETTER_SQLITE3_ROOT;
    try { fs.rmSync(tmp, { recursive: true, force: true }); } catch {}
  });

  const branch = openDb('branch');
  const result = openDb('result');
  assert.ok(branch.open && result.open, 'both connections should start open');

  closeAll();

  // closeAll closes every cached handle; reopen must produce new objects.
  const branchAgain = openDb('branch');
  const resultAgain = openDb('result');
  assert.notStrictEqual(branchAgain, branch, 'branch reopen must yield a new instance');
  assert.notStrictEqual(resultAgain, result, 'result reopen must yield a new instance');
  assert.ok(branchAgain.open && resultAgain.open, 'reopened connections must be open');
});

test('A-007.5 busy_timeout reflects getBusyTimeout() override', (t) => {
  const tmp = mkTmp();
  process.env.PETRI_LOCAL_DATA_DIR = tmp;
  process.env.PETRI_BETTER_SQLITE3_ROOT = coreServerRoot;
  _reset();

  t.after(() => {
    closeAll();
    _reset();
    // restore default config so other suites are not affected
    setDbConfig({ busyTimeoutMs: 10000 });
    delete process.env.PETRI_LOCAL_DATA_DIR;
    delete process.env.PETRI_BETTER_SQLITE3_ROOT;
    try { fs.rmSync(tmp, { recursive: true, force: true }); } catch {}
  });

  // default value from config-helper
  const defaultBusy = getBusyTimeout();
  assert.strictEqual(defaultBusy, 10000, 'default busyTimeoutMs must be 10000');

  // override and reopen to verify the override flows through
  setDbConfig({ busyTimeoutMs: 25000 });
  assert.strictEqual(getBusyTimeout(), 25000, 'getBusyTimeout must read the override');
  const db = openDb('branch');
  assert.strictEqual(
    readBusyTimeout(db),
    25000,
    'openDb must apply busy_timeout from getBusyTimeout() at open time',
  );
});

test('A-007.6 WAL journal mode is applied at open time', (t) => {
  const tmp = mkTmp();
