test('A-007.8 foreign_keys is enabled by openDb', (t) => {
  const tmp = mkTmp();
  process.env.PETRI_LOCAL_DATA_DIR = tmp;
  process.env.PETRI_BETTER_SQLITE3_ROOT = coreServerRoot;
  _reset();

  t.after(() => {
