// Mock DB (in-memory)
// ---------------------------------------------------------------------------

let _loopRuns = [];
let _loopIterations = [];

function _reset() {
  _loopRuns = [];
  _loopIterations = [];
}

const mockDb = {
  persistLoopRun: (run) => { _loopRuns.push({ ...run }); return run; },
  persistLoopIteration: (iter) => { _loopIterations.push({ ...iter }); return iter; },
  getLoopRun: (id) => _loopRuns.find((r) => r.loopRunId === id) || null,
};

