function makeToolResultEnvelope(name = 'run_tool', data = {}, callId = 'call-1') {
  return {
    contractVersion: '1.0',
    traceId: 'trace-1',
    callId,
    tool: name,
    status: data.error ? 'error' : 'success',
    terminationReason: null,
    durationMs: 100,
    truncated: false,
    sideEffects: [],
    data,
  };
}

function makeToolResultEvent(envelope, callId = 'call-1') {
  return {
    event: 'tool_result',
    name: envelope.tool,
    summary: 'ok',
    iteration: 1,
    toolResult: {
      contractVersion: '1.0',
      traceId: 'trace-1',
      callId,
      tool: envelope.tool,
      status: envelope.status,
      terminationReason: null,
      durationMs: 100,
      sourceTruncated: false,
      previewTruncated: false,
      truncated: false,
      sideEffects: [],
      data: envelope.data,
    },
  };
}

