        },
      ]);
      assert.equal(resolved.unresolvedFailedJobs.length, 0);
      assert.equal(resolved.primaryFailed.toolJobId, 'parent-job');
      assert.equal(
        resolved.replacementByFailureKey.get('parent-job').toolJobId,
        'replacement-job',
      );
      assert.equal(resolved.repairedFailedJobIds.has('parent-job'), true);
    });

    it('records an observed replacement even when no deterministic repair strategy matched', async () => {
      const { buildObservedReplacementAttempt } = await import('../core/petri-server/agent-runner.js');
      const attempt = buildObservedReplacementAttempt(
