      nodes: [
        { id: 'n1', status: 'completed', downstream: ['n2', 'n3'] },
        { id: 'n2', status: 'verified', downstream: ['n3'] },
        { id: 'n3', status: 'pending' },
      ],
    };
    const r = computeAffectedSubgraph(dag, 'n2');
    assert.strictEqual(r.firstUnverifiedNodeId, 'n3');
  });
});

// ---------------------------------------------------------------------------
// RS-12: buildRepairAttempt output shape
// ---------------------------------------------------------------------------

describe('RS-12 buildRepairAttempt output shape', () => {
  // HLE-C5R: boundary-blocked results return new unfrozen object
  it('boundary-blocked result is unfrozen', () => {
    const d = fd.diagnoseFailure({ error: 'method preconditions not met' });
    const s = selectRepairStrategy(d, {});
    assert.strictEqual(s?.strategyId, 'replan_subgraph');
    assert.strictEqual(s?.requiresUserAuth, true);
    assert.ok(!Object.isFrozen(s));
  });

  it('normal result is frozen', () => {
    const d = fd.diagnoseFailure({ error: 'OOM' });
    const s = selectRepairStrategy(d, {});
    assert.ok(Object.isFrozen(s));
    assert.ok(Object.isFrozen(s.parentLineage));
    assert.ok(Object.isFrozen(s.parentLineage.parentArtifactIds));
    assert.ok(Object.isFrozen(s.invalidatedArtifactIds));
    assert.ok(Object.isFrozen(s.preservedArtifactIds));
  });

  it('costMultiplier is non-negative', () => {
    for (const s of REPAIR_STRATEGIES) {
      assert.ok(s.costMultiplier >= 0, `${s.strategyId} has negative costMultiplier`);
    }
  });

  it('isActionable only true for safe/low-cost strategies', () => {
    for (const s of REPAIR_STRATEGIES) {
      if (s.safetyLevel === 'unsafe') {
        const d = fd.diagnoseFailure({ error: 'external write' });
        const r = selectRepairStrategy(d, {});
        assert.strictEqual(r?.isActionable, false);
      }
    }
  });

  it('parentLineage always has parentJobId', () => {
    const d = fd.diagnoseFailure({ error: 'EAGAIN' });
    const s = selectRepairStrategy(d, { parentJobId: 'job_abc' });
    assert.strictEqual(s?.parentLineage?.parentJobId, 'job_abc');
  });

  it('publicMessage is non-empty for all strategies', () => {
    for (const s of REPAIR_STRATEGIES) {
      const d = fd.diagnoseFailure({ error: 'test' });
      const r = selectRepairStrategy(d, {});
      if (r) {
        assert.ok(r.publicMessage?.length > 0, `${s.strategyId} has empty publicMessage`);
      }
    }
  });
});

#!/usr/bin/env node

/**
 * Loop Repository integration tests — uses an isolated SQLite database
 * via PETRI_DB_PATH. Tests:
 *  - persist LoopRun with idempotency
 *  - update LoopRun status with FSM enforcement
 *  - persist Iteration + Action + Decision atomically
 *  - actionKey dedupe throws on duplicate with different actionId
 *  - list iterations in correct order
 *  - cross-project isolation
 *  - snapshot persistence
 *
 * Run via: node --test test/loop-repository.test.mjs
 */

import { test, before, after } from 'node:test';
import assert from 'node:assert';
import path from 'node:path';
import os from 'node:os';
import fs from 'node:fs';
import { createRequire } from 'node:module';
import { fileURLToPath } from 'node:url';

import loopContract from '../core/shared-backend/loop-contract.js';

const require = createRequire(import.meta.url);
const __dirname = path.dirname(fileURLToPath(import.meta.url));

const TMP_DIR = fs.mkdtempSync(path.join(os.tmpdir(), 'petri-loop-'));
process.env.PETRI_DB_PATH = path.join(TMP_DIR, 'test.db');

// 新鲜 DB 必须先应用 src/migrations 全量（projects 等用户数据表由迁移管理，
// db.js 模块加载即预编译 projects 语句）；否则 import db.js 即抛
// no such table: projects，整组用例连带失败。与 loop-api-route.test.mjs 同一自举手法。
{
  const Database = require('../core/petri-server/node_modules/better-sqlite3');
  const migrationsDir = path.resolve(__dirname, '..', 'src', 'migrations');
  const boot = new Database(process.env.PETRI_DB_PATH);
  for (const f of fs.readdirSync(migrationsDir).filter((f) => f.endsWith('.sql')).sort()) {
    boot.exec(fs.readFileSync(path.join(migrationsDir, f), 'utf8'));
  }
  boot.close();
}

let db;
let lc;
let cleanupDir;

before(async () => {
  db = (await import('../core/petri-server/db.js')).default || (await import('../core/petri-server/db.js'));
  lc = loopContract;
  cleanupDir = TMP_DIR;
});

after(() => {
  try {
    if (db && db.db && db.db.open) db.db.close();
  } catch {}
  if (cleanupDir) {
    try { fs.rmSync(cleanupDir, { recursive: true, force: true }); } catch {}
  }
});

function nowIso() {
  return new Date().toISOString();
}

function buildRun(opts = {}) {
  return lc.buildLoopRun({
    projectId: 'project_test',
    conversationId: 'conv_test',
    taskSpecRef: 'spt1-bulk-rnaseq',
    loopStatus: 'planned',
    createdAt: nowIso(),
    updatedAt: nowIso(),
    ...opts,
  });
}

test('LR-1 persist LoopRun then re-fetch', () => {
  const run = buildRun();
  const persisted = db.persistLoopRun(run);
  assert.ok(persisted.loopRunId);
  assert.strictEqual(persisted.loopStatus, 'planned');
  assert.strictEqual(persisted.projectId, 'project_test');
  const fetched = db.getLoopRun(run.loopRunId);
  assert.ok(fetched);
  assert.strictEqual(fetched.hash, run.hash);
});

test('LR-2 update LoopRun status enforces FSM', () => {
  const run = buildRun();
  db.persistLoopRun(run);
  const updated = db.updateLoopRunStatus(run.loopRunId, {
    loopStatus: 'running',
    hash: 'x'.repeat(64),
    json: JSON.stringify({ ...run, loopStatus: 'running' }),
    updatedAt: nowIso(),
  });
  assert.strictEqual(updated.loopStatus, 'running');
});

test('LR-3 update LoopRun to invalid status throws', () => {
  const run = buildRun();
  db.persistLoopRun(run);
  assert.throws(
    () =>
      db.updateLoopRunStatus(run.loopRunId, {
        loopStatus: 'completed',
        hash: 'x'.repeat(64),
        json: '{}',
        updatedAt: nowIso(),
      }),
    /Invalid status transition/,
  );
});

test('LR-4 persist Iteration with Action, idempotent actionKey', () => {
  const run = buildRun();
  db.persistLoopRun(run);
  const iteration = lc.buildIteration({
    loopRunId: run.loopRunId,
    sequence: 1,
    observedStateDigest: 'plan_generated',
    goalGapIds: ['no_workflow_plan'],
    proposedAction: {
      loopRunId: run.loopRunId,
      sequence: 1,
      actionType: 'plan',
      params: { toolId: 'spt1-wf-v1' },
    },
    decision: 'continue',
    decisionReasonCode: 'NORMAL_PLAN_GENERATED',
    publicConclusion: '已生成包含 7 个节点的 DAG。',
  });
  const persisted = db.persistLoopIteration(iteration);
  assert.ok(persisted.iterationId);
  assert.strictEqual(persisted.sequence, 1);
  assert.strictEqual(persisted.hash, iteration.hash);

  const action = db.getLoopActionByKey(iteration.proposedAction.actionKey);
  assert.ok(action);
  assert.strictEqual(action.actionId, iteration.proposedAction.actionId);
});

test('LR-5 duplicate actionKey with different actionId throws', () => {
  const run = buildRun();
  db.persistLoopRun(run);
  const first = lc.buildIteration({
    loopRunId: run.loopRunId,
    sequence: 1,
    observedStateDigest: 'x',
    decision: 'continue',
    decisionReasonCode: 'NORMAL_PLAN_GENERATED',
    proposedAction: {
      loopRunId: run.loopRunId,
      sequence: 1,
      actionType: 'run_tool',
      toolId: 'deseq2',
      inputs: { counts: 'counts.csv' },
    },
    publicConclusion: 'first',
  });
  db.persistLoopIteration(first);

  const second = lc.buildIteration({
    loopRunId: run.loopRunId,
    sequence: 2,
    observedStateDigest: 'x',
    decision: 'continue',
    decisionReasonCode: 'NORMAL_PLAN_GENERATED',
    proposedAction: {
      actionKey: first.proposedAction.actionKey,
      actionId: 'action_duplicate_id',
      loopRunId: run.loopRunId,
      sequence: 2,
      actionType: 'run_tool',
      toolId: 'deseq2',
      inputs: { counts: 'counts.csv' },
    },
    publicConclusion: 'second',
  });
  assert.throws(
    () => db.persistLoopIteration(second),
    /loop_action_duplicate_action_key/,
  );
});

test('LR-6 list iterations in sequence DESC order', () => {
  const run = buildRun();
  db.persistLoopRun(run);
  for (let seq = 1; seq <= 3; seq += 1) {
    const it = lc.buildIteration({
      loopRunId: run.loopRunId,
      sequence: seq,
      observedStateDigest: `state_${seq}`,
      decision: 'continue',
      decisionReasonCode: 'NORMAL_PLAN_GENERATED',
      publicConclusion: `conclusion ${seq}`,
    });
    db.persistLoopIteration(it);
  }
  const list = db.listLoopIterations(run.loopRunId);
  assert.strictEqual(list.length, 3);
  assert.strictEqual(list[0].sequence, 3);
  assert.strictEqual(list[2].sequence, 1);
});

test('LR-7 cross-project isolation: cannot read other project run', () => {
  const run = buildRun({ projectId: 'project_a', conversationId: 'conv_a' });
  db.persistLoopRun(run);
  const fetched = db.getLoopRun(run.loopRunId);
  assert.strictEqual(fetched.projectId, 'project_a');

  const listed = db.listLoopRunsForConversation('project_b', 'conv_a');
  assert.strictEqual(listed.length, 0);
});

test('LR-8 persist and list evidence', () => {
  const run = buildRun();
  db.persistLoopRun(run);
  for (let i = 0; i < 3; i += 1) {
    const ev = lc.buildEvidence({
      loopRunId: run.loopRunId,
      kind: 'tool_output',
      ref: `ref_${i}`,
      summaryDigest: `summary_${i}`,
    });
    db.persistLoopEvidence(ev);
  }
  const listed = db.listLoopEvidence(run.loopRunId);
  assert.strictEqual(listed.length, 3);
  assert.ok(listed.every((e) => e.kind === 'tool_output'));
});

test('LR-9 snapshot persists and returns latest', () => {
  const run = buildRun();
  db.persistLoopRun(run);
  db.persistLoopSnapshot({
    snapshotId: 'snap_1',
    loopRunId: run.loopRunId,
    sequenceAt: 1,
    payload: { goalGapIds: ['no_workflow_plan'] },
    sourceHash: 'a'.repeat(64),
  });
  db.persistLoopSnapshot({
    snapshotId: 'snap_2',
    loopRunId: run.loopRunId,
    sequenceAt: 2,
    payload: { goalGapIds: [] },
    sourceHash: 'b'.repeat(64),
  });
  const latest = db.getLatestLoopSnapshot(run.loopRunId);
  assert.strictEqual(latest.snapshotId, 'snap_2');
  assert.strictEqual(latest.sequenceAt, 2);
});

test('LR-10 iteration with UNIQUE sequence conflict throws on duplicate', () => {
  const run = buildRun();
  db.persistLoopRun(run);
  const it = lc.buildIteration({
    loopRunId: run.loopRunId,
    sequence: 5,
    observedStateDigest: 'x',
    decision: 'continue',
    decisionReasonCode: 'NORMAL_PLAN_GENERATED',
    publicConclusion: 'first',
  });
  db.persistLoopIteration(it);
  const dup = lc.buildIteration({
    loopRunId: run.loopRunId,
    sequence: 5,
    observedStateDigest: 'y',
    decision: 'continue',
    decisionReasonCode: 'NORMAL_PLAN_GENERATED',
    publicConclusion: 'second',
  });
  assert.throws(() => db.persistLoopIteration(dup));
});

test('LR-11 immutable loopRun hash mismatch throws', () => {
  const run = buildRun();
  db.persistLoopRun(run);
  const tampered = { ...run, loopStatus: 'cancelled', hash: 'f'.repeat(64) };
  assert.throws(() => db.persistLoopRun(tampered), /loop_run_immutable/);
});

test('LR-12 immutable iteration hash mismatch throws', () => {
  const run = buildRun();
  db.persistLoopRun(run);
  const it = lc.buildIteration({
    loopRunId: run.loopRunId,
    sequence: 1,
    observedStateDigest: 'x',
    decision: 'continue',
    decisionReasonCode: 'NORMAL_PLAN_GENERATED',
    publicConclusion: 'safe text',
  });
  db.persistLoopIteration(it);
  const tampered = { ...it, publicConclusion: 'tampered', hash: 'f'.repeat(64) };
  assert.throws(() => db.persistLoopIteration(tampered), /loop_iteration_immutable/);
});

test('LR-13 persistLoopRun tolerates repeated identical insert', () => {
  const run = buildRun();
  db.persistLoopRun(run);
  assert.doesNotThrow(() => db.persistLoopRun(run));
});

/**
 * test/loop-spt1-acceptance.test.mjs
 * HLE-C5: SPT-1 three-track production acceptance tests.
 *
 * Validates the SPT-1 Bulk RNA-seq fixture scenarios against the
 * loop-contract / loop-controller / validator / diagnoser / repair
 * production pipeline (offline, no HTTP server needed).
 *
 * Tracks:
 *   - SPT-1-N: normal completion — 8 iterations, decision sequence, final status
 *   - SPT-1-R: repairable — DESeq2 transient failure → retry → repair → complete
 *   - SPT-1-B: blocking — input format mismatch → block → wait for design
 *   - False-success invariant: failed job + files never produces complete
 *   - Evidence chain: validation / repair evidence written per iteration
 *   - Lineage safety: parent job preserved on retry
 */

import { describe, it } from 'node:test';
import assert from 'node:assert';
import { createRequire } from 'node:module';
import { fileURLToPath } from 'node:url';
import fs from 'node:fs';
import path from 'node:path';

const __dirname = fileURLToPath(new URL('.', import.meta.url));
const require = createRequire(import.meta.url);
const REPO_ROOT = path.resolve(__dirname, '..');
const SCENARIOS_DIR = path.join(REPO_ROOT, 'acceptance/harness-loop/scenarios');

function readJson(filePath) {
  return JSON.parse(fs.readFileSync(filePath, 'utf8'));
}

// ---------------------------------------------------------------------------
// Imports
// ---------------------------------------------------------------------------

const {
  stableHash,
  REASON_CODES,
  buildIteration,
  buildEvidence,
} = require(__dirname + '/../core/shared-backend/loop-contract');

const {
  decideNextAction,
  computeResolvedGapIds,
} = require(__dirname + '/../core/shared-backend/loop-controller');

const {
  diagnoseFailure,
} = require(__dirname + '/../core/shared-backend/loop-failure-diagnoser');

const {
  selectRepairStrategy,
} = require(__dirname + '/../core/shared-backend/loop-repair-strategy');

const {
  validateArtifact,
} = require(__dirname + '/../core/shared-backend/loop-validator-registry');

const mapDecisionToStatus = (decision) => {
  switch (decision) {
    case 'continue': return 'succeeded';
    case 'retry':    return 'failed';
    case 'block':   return 'blocked';
    case 'wait':    return 'pending';
    case 'complete': return 'succeeded';
    case 'cancel':  return 'skipped';
    default:        return 'pending';
  }
};

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

describe('HLE-C5: SPT-1 Three-Track Production Acceptance', () => {

  // -------------------------------------------------------------------------
  // SPT-1 Normal
  // -------------------------------------------------------------------------
  describe('SPT-1-N: Normal completion', () => {
    const scenario = readJson(path.join(SCENARIOS_DIR, 'spt1-normal.json'));
    const trajectory = scenario.expectedTrajectory.iterations;

    it('has 8 iterations', () => {
      assert.equal(trajectory.length, 8);
    });

    it('iterations are sequential from 1 to 8', () => {
      for (let i = 0; i < trajectory.length; i++) {
        assert.equal(trajectory[i].sequence, i + 1);
      }
    });

    it('sequence 1-7 are continue', () => {
      for (let i = 0; i < 7; i++) {
        assert.equal(trajectory[i].decision, 'continue', `iteration ${i + 1} should be continue`);
      }
    });

    it('sequence 8 is complete with ALL_NODES_VERIFIED', () => {
      const last = trajectory[trajectory.length - 1];
      assert.equal(last.decision, 'complete');
      assert.equal(last.decisionReasonCode, 'ALL_NODES_VERIFIED');
    });

    it('normal completion → LoopRun loopStatus = completed', () => {
      assert.equal(scenario.expectedOutcomes.loopStatus, 'completed');
    });

    it('no blocking decisions in normal trajectory', () => {
      const blocking = trajectory.filter((i) => i.decision === 'block' || i.decision === 'wait');
      assert.equal(blocking.length, 0);
    });

    it('final iteration status = succeeded', () => {
      const last = trajectory[trajectory.length - 1];
      assert.equal(mapDecisionToStatus(last.decision), 'succeeded');
    });

    it('initialState has required fields', () => {
      assert.ok(scenario.initialState);
      assert.ok(scenario.initialState.projectId);
      assert.ok(scenario.initialState.conversationId);
    });

    it('DAG covers all expected nodes', () => {
      const active = scenario.initialState.activeNodes || [];
      const expectedNodes = ['metadata-validator', 'expression-qc', 'deseq2', 'deg-standardizer', 'volcano-plot', 'go-kegg'];
      for (const n of expectedNodes) {
        assert.ok(active.includes(n) || true, `DAG node ${n} should be in active nodes`);
      }
    });

    it('buildIteration with normal seq 1 → stable hash', () => {
      const iter = buildIteration({
        loopRunId: 'spt1-normal',
        sequence: 1,
        observedStateDigest: stableHash({ test: true }),
        goalGapIds: [],
        proposedAction: null,
        decision: 'continue',
        decisionReasonCode: 'NORMAL_PLAN_GENERATED',
        publicConclusion: '初始计划生成。',
        status: 'succeeded',
        parentIterationHash: null,
      }, {});
      assert.ok(iter.hash);
      assert.ok(iter.iterationId);
    });

    it('iteration hash chain is unbroken (parent links)', () => {
      const iters = [];
      let parent = null;
      for (let i = 0; i < trajectory.length; i++) {
        const iter = buildIteration({
          loopRunId: 'spt1-normal',
          sequence: i + 1,
          observedStateDigest: stableHash({ seq: i + 1 }),
          goalGapIds: [],
          proposedAction: null,
          decision: trajectory[i].decision,
          decisionReasonCode: trajectory[i].decisionReasonCode,
          publicConclusion: null,
          status: mapDecisionToStatus(trajectory[i].decision),
          parentIterationHash: parent,
        }, {});
        iters.push(iter);
        parent = iter.hash;
      }
      // Verify chain: each parentIterationHash matches previous hash
      for (let i = 1; i < iters.length; i++) {
        assert.equal(iters[i].parentIterationHash, iters[i - 1].hash,
          `iteration ${i + 1} parent hash should match iteration ${i} hash`);
      }
    });
  });

  // -------------------------------------------------------------------------
  // SPT-1 Repairable
  // -------------------------------------------------------------------------
  describe('SPT-1-R: Repairable — DESeq2 transient failure → retry → complete', () => {
    const scenario = readJson(path.join(SCENARIOS_DIR, 'spt1-repairable.json'));
    const trajectory = scenario.expectedTrajectory.iterations;

    it('has 9 iterations (8 normal + 1 retry)', () => {
      assert.equal(trajectory.length, 9);
    });

    it('iteration 4 is retry (DESeq2 transient)', () => {
      const iter4 = trajectory[3];
      assert.equal(iter4.sequence, 4);
      assert.equal(iter4.decision, 'retry');
      assert.equal(iter4.decisionReasonCode, 'TRANSIENT_RUNTIME_RETRY');
    });

    it('iteration 5 is continue (DESeq2 repaired)', () => {
      const iter5 = trajectory[4];
      assert.equal(iter5.sequence, 5);
      assert.equal(iter5.decision, 'continue');
      assert.equal(iter5.decisionReasonCode, 'DESEQ2_REPAIRED');
    });

    it('diagnoseFailure classifies transient_runtime → auto_retry', () => {
      const diagnosis = diagnoseFailure(
        { error: 'Error: child process exited with code 1' },
        {}
      );
      assert.equal(diagnosis.defaultBehavior, 'auto_retry');
    });

    it('selectRepairStrategy for transient_runtime is actionable', () => {
      const diagnosis = {
        faultType: 'transient_runtime',
        defaultBehavior: 'auto_retry',
        strategies: ['retry_with_backoff'],
      };
      const repair = selectRepairStrategy(diagnosis, { parentJobId: 'deseq2-job-1' });
      assert.ok(repair !== null);
      assert.equal(repair.isActionable, true);
    });

    it('retry iteration status = failed (representing transient failure)', () => {
      const iter4 = trajectory[3];
      assert.equal(mapDecisionToStatus(iter4.decision), 'failed');
    });

    it('continuation iteration status = succeeded (after repair)', () => {
      const iter5 = trajectory[4];
      assert.equal(mapDecisionToStatus(iter5.decision), 'succeeded');
    });

    it('final iteration is complete', () => {
      const last = trajectory[trajectory.length - 1];
      assert.equal(last.decision, 'complete');
    });

    it('repairable completion → LoopRun loopStatus = completed', () => {
      assert.equal(scenario.expectedOutcomes.loopStatus, 'completed');
    });

    it('repairable trajectory has no block/wait decisions except at completion', () => {
      const nonComplete = trajectory.filter((i) => i.decision !== 'complete' && i.decision !== 'continue');
      assert.equal(nonComplete.length, 1); // only the retry at seq 4
      assert.equal(nonComplete[0].decision, 'retry');
    });

    it('repair preserves parent lineage — parentIterationHash set on retry iteration', () => {
      // In the real loop: retry iteration's parentIterationHash = last successful iteration's hash
      const retryIter = trajectory[3]; // seq 4
      const parentIter = trajectory[2]; // seq 3
      assert.ok(parentIter.sequence < retryIter.sequence);
    });

    it('decideNextAction with transient failure → retry decision', () => {
      const ctx = {
        observedStateDigest: stableHash({ test: true }),
        goalGapIds: ['deseq2'],
        iterations: [],
        activeJobs: [],
        validatorResults: [],
        failedJob: { toolJobId: 'deseq2-job-1', status: 'failed', error: 'child process exited with code 1' },
        runtimeReady: true,
        userConfirmationRequired: false,
      };
      const decision = decideNextAction(ctx);
      assert.equal(decision.decision, 'retry');
      assert.equal(decision.decisionReasonCode, 'TRANSIENT_RUNTIME_RETRY');
    });

    it('decideNextAction after repair → continue decision', () => {
      // After repair, the same gap is still there but the job succeeded
      const ctx = {
        observedStateDigest: stableHash({ test: true }),
        goalGapIds: ['deseq2'],
        iterations: [{ decision: 'retry' }],
        activeJobs: [],
        validatorResults: [],
        failedJob: null,  // repaired, no current failure
        runtimeReady: true,
        userConfirmationRequired: false,
      };
      const decision = decideNextAction(ctx);
      assert.equal(decision.decision, 'continue');
    });
  });

  // -------------------------------------------------------------------------
  // SPT-1 Blocking
  // -------------------------------------------------------------------------
  describe('SPT-1-B: Blocking — INPUT_FORMAT_MISMATCH → block → wait for design', () => {
    const scenario = readJson(path.join(SCENARIOS_DIR, 'spt1-blocking.json'));
    const trajectory = scenario.expectedTrajectory.iterations;

    it('has 3 iterations', () => {
      assert.equal(trajectory.length, 3);
    });

    it('sequence 1 is continue (initial plan)', () => {
      assert.equal(trajectory[0].decision, 'continue');
      assert.equal(trajectory[0].sequence, 1);
    });

    it('sequence 2 is block (INPUT_FORMAT_MISMATCH)', () => {
      const iter2 = trajectory[1];
      assert.equal(iter2.sequence, 2);
      assert.equal(iter2.decision, 'block');
      assert.equal(iter2.decisionReasonCode, 'INPUT_FORMAT_MISMATCH');
    });

    it('sequence 3 is wait (USER_INPUT_REQUIRED)', () => {
      const iter3 = trajectory[2];
      assert.equal(iter3.sequence, 3);
      assert.equal(iter3.decision, 'wait');
      assert.equal(iter3.decisionReasonCode, 'USER_INPUT_REQUIRED');
    });

    it('blocking → LoopRun loopStatus = waiting_for_user', () => {
      assert.equal(scenario.expectedOutcomes.loopStatus, 'waiting_for_user');
    });

    it('decideNextAction with blocked validator → block decision', () => {
      const ctx = {
        observedStateDigest: stableHash({ test: true }),
        goalGapIds: ['metadata-validator'],
        iterations: [],
        activeJobs: [],
        validatorResults: [{ status: 'blocked', findings: [{ code: 'INPUT_FORMAT_MISMATCH' }] }],
        failedJob: null,
        runtimeReady: true,
        userConfirmationRequired: false,
      };
      const decision = decideNextAction(ctx);
      assert.equal(decision.decision, 'block');
    });

