/**
 * G0-RS-P4R-0 open-result baseline capture.
 *
 * The assertions that matter here are the ones about whether the measurement is
 * REAL. The first working version of this capture reported a complete-looking
 * waterfall in which four of six requests had returned 400/404 — it had timed
 * argument validation, including a 0.9ms reading for the route the survey
 * identified as the most expensive in the system. A baseline that measures
 * rejection is worse than no baseline, because it looks like evidence.
 *
 * So: a request that must succeed is asserted to have succeeded, and any route
 * that could not be measured is recorded as unmeasured rather than folded into
 * the numbers.
 */

import { strict as assert } from 'node:assert';
import { execFileSync } from 'node:child_process';
import { existsSync, rmSync, statSync } from 'node:fs';
import { homedir } from 'node:os';
import path from 'node:path';
import { test } from 'node:test';
import { fileURLToPath } from 'node:url';

import { fingerprintRealDataRoot } from '../scripts/g0-rs-p4r-capture.mjs';
import { captureBaseline } from '../scripts/g0-rs-p4r-baseline.mjs';

const REPO_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const REPO_DB = path.join(REPO_ROOT, 'core', 'petri-server', 'petri.db');
const REAL_DATA_ROOT = path.join(homedir(), 'Documents', 'Petri-Local');

/** Routes whose cost is the whole point of the baseline. */
const MUST_BE_MEASURED = ['job-status', 'artifact-bytes', 'interaction', 'changesets', 'workspace-status'];

function rRuntimeBlocker() {
  try {
    execFileSync('Rscript', ['-e', 'if(!requireNamespace("DESeq2",quietly=TRUE)) quit(status=1)'], {
      stdio: 'ignore',
      timeout: 60000,
    });
    return null;
  } catch {
    return 'requires Rscript with DESeq2 installed';
  }
}

const R_BLOCKER = rRuntimeBlocker();

test(
  'the baseline measures the real path, not argument validation',
  { timeout: 900000, skip: R_BLOCKER ?? false },
  async () => {
    const devDbBefore = existsSync(REPO_DB) ? statSync(REPO_DB).mtimeMs : null;
    const realRootBefore = fingerprintRealDataRoot(REAL_DATA_ROOT);

    const result = await captureBaseline({ quiet: true });

    const byId = new Map(result.requests.map((request) => [request.id, request]));
    for (const id of MUST_BE_MEASURED) {
      const request = byId.get(id);
      assert.ok(request, `${id} was not driven at all`);
      assert.equal(
        request.status,
        200,
        `${id} returned ${request.status}; a non-200 means the baseline timed a rejection, not the real path`,
      );
      assert.ok(request.totalMs > 0, `${id} has no timing`);
      assert.equal(request.error, null, `${id} errored: ${request.error}`);
    }

    // The corpus must be real: real tool jobs, real artifact bytes served.
    assert.ok(result.corpus.length >= 3, 'corpus must cover the chained tools');
    for (const record of result.corpus) assert.match(record.toolJobId || '', /^tj_/);
    assert.ok(byId.get('artifact-bytes').bytes > 10000, 'artifact bytes look too small to be a real render');

    // The event-loop histogram is the authoritative signal for the plan's
    // >250ms gate; it must carry real samples, not the empty-histogram sentinel.
    assert.ok(result.eventLoop, 'event loop must be sampled');
    assert.ok(result.eventLoop.samples > 0, 'event loop histogram recorded nothing');
    assert.ok(Number.isFinite(result.eventLoop.maxMs), 'event loop max must be a real sample');

    // Client metrics must stay explicitly unmeasured rather than estimated.
    for (const [key, metric] of Object.entries(result.clientMetrics)) {
      assert.equal(metric.observedMs, null, `${key} must not be fabricated`);
      assert.match(metric.status, /not_captured/, `${key} must state why it is absent`);
    }

    assert.equal(existsSync(result.root), false, 'the baseline must remove its root');
    assert.equal(
      existsSync(REPO_DB) ? statSync(REPO_DB).mtimeMs : null,
      devDbBefore,
      'the developer database must be untouched',
    );
    assert.deepEqual(
      fingerprintRealDataRoot(REAL_DATA_ROOT),
      realRootBefore,
      'the real user data root must be untouched',
    );
  },
);

test('the R-backed baseline test is not silently skipped', () => {
  if (R_BLOCKER) {
    assert.match(R_BLOCKER, /Rscript/);
    console.error(`[p4r-baseline] real-path coverage SKIPPED: ${R_BLOCKER}`);
  } else {
    assert.equal(R_BLOCKER, null);
  }
});

/**
 * G0-RS-P4R-0 capture environment.
 *
 * The isolation assertions matter more than the happy path here: the whole
 * reason this environment exists is that the developer database holds real
 * projects, so a capture that writes to the wrong place is the failure worth
 * testing against.
 */

import { strict as assert } from 'node:assert';
import { existsSync, mkdtempSync, rmSync, statSync } from 'node:fs';
import { homedir, tmpdir } from 'node:os';
import path from 'node:path';
import { test } from 'node:test';
import { fileURLToPath } from 'node:url';

import {
  ISOLATED_PATH_ENV,
  REQUIRED_RS_TABLES,
  assertIsolated,
  capture,
  createCaptureEnv,
  inspectTables,
} from '../scripts/g0-rs-p4r-capture.mjs';

const REPO_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const REPO_DB = path.join(REPO_ROOT, 'core', 'petri-server', 'petri.db');

/**
 * Paths that fall back to ~/Documents/Petri-Local — the real user data root,
 * holding the live database and 150 project directories — when their variable
 * is unset. The first version of this harness redirected four paths and
 * guarded the same four, silently leaving these three pointing at real data.
 */
const MUST_BE_ISOLATED = [
  'PETRI_DB_PATH',
  'PETRI_TEMP_DIR',
  'PETRI_LOCAL_RESULTS_DIR',
  'PETRI_LOCAL_UPLOADS_DIR',
  'PETRI_LOCAL_DATA_DIR',
  'PETRI_PLUGINS_DIR',
  'PETRI_HARNESS_LOCAL_ROOT',
];

test('every path that can reach the real user data root is redirected and guarded', () => {
  // Regression: these three defaulted to ~/Documents/Petri-Local, which holds
  // the live database and 150 project directories.
  for (const key of MUST_BE_ISOLATED) {
    assert.ok(key in ISOLATED_PATH_ENV, `${key} must be redirected into the disposable root`);
  }

  const { root, env } = createCaptureEnv({ port: 1 });
  try {
    for (const key of MUST_BE_ISOLATED) {
      assert.ok(env[key]?.startsWith(root + path.sep), `${key} must point inside the capture root`);
    }
    // Guarding must be derived from the same list, not restated — that drift is
    // exactly what let the three escape.
    for (const key of MUST_BE_ISOLATED) {
      assert.throws(
        () => assertIsolated({ ...env, [key]: path.join(homedir(), 'Documents', 'Petri-Local') }, root),
        /capture isolation/,
        `${key} pointing at the real data root must abort the run`,
      );
    }
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

test('isolation fails closed when a path escapes the disposable root', () => {
  const root = '/tmp/petri-capture-root';
  const good = Object.fromEntries(
    Object.entries(ISOLATED_PATH_ENV).map(([key, leaf]) => [key, path.join(root, leaf)]),
  );
  assert.equal(assertIsolated(good, root), true);

  for (const key of Object.keys(good)) {
    assert.throws(
      () => assertIsolated({ ...good, [key]: '/var/somewhere-else' }, root),
      /resolves outside the disposable root/,
      `${key} escaping the root must abort the run`,
    );
    assert.throws(
      () => assertIsolated({ ...good, [key]: '' }, root),
      /must be set explicitly/,
      `${key} must never be left to a default`,
    );
  }

  // A traversal that lands outside the root is still outside it.
  assert.throws(
    () => assertIsolated({ ...good, PETRI_TEMP_DIR: path.join(root, '..', 'elsewhere') }, root),
    /resolves outside the disposable root/,
  );
});

test('isolation refuses to capture against the repository database', () => {
  const root = mkdtempSync(path.join(tmpdir(), 'petri-capture-guard-'));
  try {
    assert.throws(
      () => assertIsolated({
        PETRI_DB_PATH: REPO_DB,
        PETRI_TEMP_DIR: path.join(root, 'tmp'),
        PETRI_LOCAL_RESULTS_DIR: path.join(root, 'results'),
        PETRI_LOCAL_UPLOADS_DIR: path.join(root, 'uploads'),
      }, root),
      /refusing to capture against the repository database/,
    );
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

test('a built environment points every writable path into its own root', () => {
  const { root, env, paths } = createCaptureEnv({ port: 12345 });
  try {
    for (const key of ['PETRI_DB_PATH', 'PETRI_TEMP_DIR', 'PETRI_LOCAL_RESULTS_DIR', 'PETRI_LOCAL_UPLOADS_DIR']) {
      assert.ok(env[key].startsWith(root + path.sep), `${key} must live under the disposable root`);
    }
    assert.equal(env.PETRI_PERF_PROBE, '1', 'the probe must be armed for a capture run');
    assert.equal(env.R_SERVER_PORT, '12345');
    for (const [key, value] of Object.entries(paths)) {
      if (key !== 'PETRI_DB_PATH') assert.ok(statSync(value).isDirectory(), `${key} must be created`);
    }
    assert.notEqual(path.resolve(env.PETRI_DB_PATH), path.resolve(REPO_DB));
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

test('capture migrates, boots the probe and tears the root down', { timeout: 120000 }, async () => {
  const devDbBefore = existsSync(REPO_DB) ? statSync(REPO_DB).mtimeMs : null;

  const result = await capture();

  assert.deepEqual(result.tables.missing, [], 'every Result Studio table must exist before sampling');
  assert.equal(result.tables.present.length, REQUIRED_RS_TABLES.length);
