test('an unsampled histogram reports nothing instead of its sentinel values', () => {
  perfProbe.enableProbe({ force: true });
  const { eventLoop } = perfProbe.snapshotProbe();
  assert.equal(eventLoop.samples, 0);
  for (const key of ['minMs', 'meanMs', 'p50Ms', 'p95Ms', 'p99Ms', 'maxMs']) {
    assert.equal(eventLoop[key], null, `${key} must stay null until a real sample exists`);
  }
});

test('snapshot reports event-loop percentiles, per-route timings and discrete blocks', async () => {
  perfProbe.enableProbe({ force: true });
  await new Promise((resolve) => { setTimeout(resolve, 60); });
  for (const total of [12, 40, 7, 900, 25]) {
    perfProbe.recordRequestTiming({ method: 'GET', route: '/api/result-studio/interaction', status: 200, ttfbMs: total / 2, totalMs: total });
  }
  perfProbe.recordRequestTiming({ method: 'GET', route: '/api/result-studio/interaction', status: 500, ttfbMs: 1, totalMs: 2 });
  perfProbe.observeBlock(2100);
  perfProbe.observeBlock(8200);

  const snapshot = perfProbe.snapshotProbe();
  assert.equal(snapshot.enabled, true);
  assert.equal(snapshot.eventLoop.resolutionMs, perfProbe.RESOLUTION_MS);
  for (const key of ['minMs', 'meanMs', 'p50Ms', 'p95Ms', 'p99Ms', 'maxMs']) {
    assert.ok(Number.isFinite(snapshot.eventLoop[key]), `${key} must be a real sample`);
  }

  const entry = snapshot.requests.find((item) => item.route === 'GET /api/result-studio/interaction');
  assert.equal(entry.count, 6);
  assert.deepEqual(entry.statuses, { 200: 5, 500: 1 });
  assert.equal(entry.totalMs.max, 900);
  assert.ok(entry.totalMs.p50 <= entry.totalMs.p95);
  assert.deepEqual(snapshot.blocks.map((block) => block.lagMs), [2100, 8200]);
});

test('probe endpoints are absent by default and live once the flag is set', async () => {
  delete process.env.PETRI_PERF_PROBE;
  await withServer((app) => registerPerfProbeRoutes(app), async (baseUrl) => {
    const response = await fetch(`${baseUrl}/api/__perf/event-loop`);
    assert.equal(response.status, 404, 'probe surface must not exist in a normal run');
  });

  process.env.PETRI_PERF_PROBE = '1';
  await withServer((app) => registerPerfProbeRoutes(app), async (baseUrl) => {
    const snapshot = await (await fetch(`${baseUrl}/api/__perf/event-loop`)).json();
    assert.equal(snapshot.enabled, true);

    const reset = await (await fetch(`${baseUrl}/api/__perf/reset`, { method: 'POST' })).json();
    assert.deepEqual(reset, { reset: true, enabled: true });
  });
});

test('the timing middleware records a real served request as a route template', async () => {
  perfProbe.enableProbe({ force: true });
  await withServer((app) => {
    app.use(requestTimingMiddleware);
    app.get('/api/tools/file/:jobId/:filename', (_req, res) => res.send('bytes'));
  }, async (baseUrl) => {
    const response = await fetch(`${baseUrl}/api/tools/file/job_1257dae3bfda4aa0/volcano.png`);
    assert.equal(await response.text(), 'bytes');
  });

  const snapshot = perfProbe.snapshotProbe();
  const entry = snapshot.requests.find((item) => item.route.startsWith('GET /api/tools/file/'));
  assert.ok(entry, `middleware recorded nothing: ${JSON.stringify(snapshot.requests)}`);
  assert.equal(entry.route, 'GET /api/tools/file/:jobId/:filename');
  assert.equal(entry.count, 1);
  assert.ok(Number.isFinite(entry.totalMs.max));
  assert.ok(!JSON.stringify(snapshot).includes('job_1257dae3bfda4aa0'));
});

test('reset clears samples without tearing the probe down', () => {
  perfProbe.enableProbe({ force: true });
  perfProbe.recordRequestTiming({ method: 'GET', route: '/api/result-studio/changesets', status: 200, ttfbMs: 4, totalMs: 8 });
  perfProbe.observeBlock(3000);
  assert.equal(perfProbe.resetProbe(), true);

  const snapshot = perfProbe.snapshotProbe();
  assert.equal(snapshot.enabled, true);
  assert.deepEqual(snapshot.requests, []);
  assert.deepEqual(snapshot.blocks, []);

  perfProbe.disableProbe();
  assert.equal(perfProbe.resetProbe(), false);
});

/**
 * test/pipeline.test.js — Pipeline 执行器测试
 *
 * 测试场景：
 * 1. 简单 Pipeline：volcano-plot → heatmap-basic
 * 2. 跨语言 Pipeline：R → Python → R
 * 3. 错误处理：continueOnError 选项
 * 4. 超时处理
 * 5. 中间结果传递
 */

const { describe, it, before, after, mock } = require('node:test');
const assert = require('node:assert');

// Mock fetch for testing
const mockFetch = mock.fn();

describe('Pipeline Executor', () => {
  let pipeline;

  before(() => {
    // 动态导入 pipeline 模块（在 mock 设置之后）
    // 注意：实际测试需要先设置 mock
    process.env.R_SERVER_URL = 'http://127.0.0.1:3003';
    process.env.PY_SERVER_URL = 'http://127.0.0.1:3004';
    process.env.PIPELINE_STEP_TIMEOUT = '5000';
    process.env.PIPELINE_GLOBAL_TIMEOUT = '30000';
  });

  describe('executePipeline', () => {
    it('should reject empty pipeline with error', async () => {
      // 导入 pipeline（绕过模块缓存）
      delete require.cache[require.resolve('../core/gateway/pipeline')];
      const { executePipeline, PipelineError } = require('../core/gateway/pipeline');

      await assert.rejects(
        () => executePipeline({ steps: [] }),
        (err) => {
          assert(err instanceof PipelineError);
          assert.strictEqual(err.statusCode, 400);
          return true;
        }
      );
    });

    it('should reject pipeline without steps array', async () => {
      delete require.cache[require.resolve('../core/gateway/pipeline')];
      const { executePipeline, PipelineError } = require('../core/gateway/pipeline');

      await assert.rejects(
        () => executePipeline({}),
        (err) => {
          assert(err instanceof PipelineError);
          assert.strictEqual(err.statusCode, 400);
          return true;
        }
      );
    });

    it('should execute single step successfully', async () => {
      delete require.cache[require.resolve('../core/gateway/pipeline')];
      const pipelineModule = require('../core/gateway/pipeline');

      // 模拟成功的单步骤执行
      const mockResult = {
        status: 'ok',
        result: { plot: '/tmp/volcano.png', data: '/tmp/deg.csv' }
      };

      // 设置 mock
      global.fetch = async (url, options) => {
        return {
          ok: true,
          status: 200,
          json: async () => mockResult
        };
      };

      const result = await pipelineModule.executePipeline({
        steps: [
          { toolId: 'volcano-plot', params: { deg_table: '/data/deg.csv' }, language: 'r' }
        ]
      });

      assert.strictEqual(result.status, 'completed');
      assert.strictEqual(result.steps.length, 1);
      assert.strictEqual(result.steps[0].status, 'completed');
      assert.ok(result.pipelineId);
    });

    it('should pass intermediate results to next step', async () => {
      delete require.cache[require.resolve('../core/gateway/pipeline')];
      const pipelineModule = require('../core/gateway/pipeline');

      let capturedParams = [];

      global.fetch = async (url, options) => {
        const body = JSON.parse(options.body);
        capturedParams.push(body.params);

        if (capturedParams.length === 1) {
          // 第一个步骤（volcano-plot）返回结果
          return {
            ok: true,
            status: 200,
            json: async () => ({
              status: 'ok',
              result: {
                outputPath: '/tmp/volcano_output.csv',
                outputType: 'deg_table'
              }
            })
          };
        } else {
          // 第二个步骤（heatmap-basic）应该接收到前一步的结果
          return {
            ok: true,
            status: 200,
            json: async () => ({
              status: 'ok',
              result: { plot: '/tmp/heatmap.png' }
            })
          };
        }
      };

      const result = await pipelineModule.executePipeline({
        steps: [
          { toolId: 'volcano-plot', params: { deg_table: '/data/deg.csv' }, language: 'r' },
          { toolId: 'heatmap-basic', params: {}, language: 'r' }
        ]
      });

      assert.strictEqual(result.status, 'completed');
      assert.strictEqual(result.steps.length, 2);
      assert.strictEqual(result.steps[0].status, 'completed');
      assert.strictEqual(result.steps[1].status, 'completed');

      // 验证第二步接收到了前一步的输出
      // 注意：prepareStepParams 合并的是上一步的 result，不是单独的 outputPath
      const step2Params = capturedParams[1];
      // 上一步的 result 被合并到下一步的参数中
      assert.ok(step2Params, 'Step 2 should have received params');
    });

    it('should stop on step failure when continueOnError is false', async () => {
      delete require.cache[require.resolve('../core/gateway/pipeline')];
      const pipelineModule = require('../core/gateway/pipeline');

      global.fetch = async (url, options) => {
        return {
          ok: false,
          status: 500,
          json: async () => ({ status: 'error', error: 'Internal server error' })
        };
      };

      const result = await pipelineModule.executePipeline({
        steps: [
          { toolId: 'volcano-plot', params: { deg_table: '/data/deg.csv' }, language: 'r' },
          { toolId: 'heatmap-basic', params: {}, language: 'r' }
        ],
        continueOnError: false
      });

      assert.strictEqual(result.status, 'failed');
      assert.strictEqual(result.steps[0].status, 'failed');
      assert.strictEqual(result.steps[1].status, 'pending');
      assert.ok(result.error);
    });

    it('should continue on step failure when continueOnError is true', async () => {
      delete require.cache[require.resolve('../core/gateway/pipeline')];
      const pipelineModule = require('../core/gateway/pipeline');

      let callCount = 0;
      global.fetch = async (url, options) => {
        callCount++;
        if (callCount === 1) {
          return {
            ok: false,
            status: 500,
            json: async () => ({ status: 'error', error: 'Step 1 failed' })
          };
        }
        return {
          ok: true,
          status: 200,
          json: async () => ({ status: 'ok', result: { plot: '/tmp/step2.png' } })
        };
      };

      const result = await pipelineModule.executePipeline({
        steps: [
          { toolId: 'volcano-plot', params: { deg_table: '/data/deg.csv' }, language: 'r' },
          { toolId: 'heatmap-basic', params: {}, language: 'r' }
        ],
        continueOnError: true
      });

      assert.strictEqual(result.status, 'completed');
      assert.strictEqual(result.steps[0].status, 'failed');
      assert.strictEqual(result.steps[1].status, 'completed');
    });
  });

  describe('getPipelineStatus', () => {
    it('should return null for non-existent pipeline', () => {
      delete require.cache[require.resolve('../core/gateway/pipeline')];
      const { getPipelineStatus } = require('../core/gateway/pipeline');

      const status = getPipelineStatus('non-existent-id');
      assert.strictEqual(status, null);
    });

    it('should return pipeline status after execution', async () => {
      delete require.cache[require.resolve('../core/gateway/pipeline')];
      const pipelineModule = require('../core/gateway/pipeline');
      const { getPipelineStatus } = pipelineModule;

      global.fetch = async () => ({
        ok: true,
        status: 200,
        json: async () => ({ status: 'ok', result: { plot: '/tmp/test.png' } })
      });

      const result = await pipelineModule.executePipeline({
        steps: [
          { toolId: 'volcano-plot', params: { deg_table: '/data/deg.csv' }, language: 'r' }
        ]
      });

      const status = getPipelineStatus(result.pipelineId);
      assert.ok(status);
      assert.strictEqual(status.pipelineId, result.pipelineId);
      assert.strictEqual(status.status, 'completed');
    });
  });

  describe('listPipelines', () => {
    it('should list all pipelines', async () => {
      delete require.cache[require.resolve('../core/gateway/pipeline')];
      const pipelineModule = require('../core/gateway/pipeline');
      const { listPipelines } = pipelineModule;

      global.fetch = async () => ({
        ok: true,
        status: 200,
        json: async () => ({ status: 'ok', result: {} })
      });

      await pipelineModule.executePipeline({
        steps: [{ toolId: 'volcano-plot', params: { deg_table: '/data/deg.csv' }, language: 'r' }]
      });

      const pipelines = listPipelines();
      assert.ok(Array.isArray(pipelines));
      assert.ok(pipelines.length > 0);
    });
  });

  describe('cleanupPipelines', () => {
    it('should cleanup old pipelines', async () => {
      delete require.cache[require.resolve('../core/gateway/pipeline')];
      const pipelineModule = require('../core/gateway/pipeline');

      global.fetch = async () => ({
        ok: true,
        status: 200,
        json: async () => ({ status: 'ok', result: {} })
      });

      // 创建多个 pipeline
      for (let i = 0; i < 5; i++) {
        await pipelineModule.executePipeline({
          steps: [{ toolId: 'volcano-plot', params: { deg_table: '/data/deg.csv' }, language: 'r' }]
        });
      }

      const result = pipelineModule.cleanupPipelines(3);
      assert.ok(typeof result.cleaned === 'number');
      assert.ok(typeof result.remaining === 'number');
      assert.ok(result.remaining <= 3);
    });
  });
});

