 * - 历史 job 回退
 */

import { describe, it, before, after, beforeEach, afterEach } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import { fileURLToPath } from 'node:url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// 动态加载 project-run-layout
const layoutModule = await import('../core/shared-backend/project-run-layout.js');
const {
  resolveProjectRunLayout,
  resolveSystemRunLayout,
  isPathContained,
  safeJoinUnder,
  restoreLegacyJobLayout,
} = layoutModule;

// 临时测试目录
const TEST_ROOT = path.join(os.tmpdir(), 'petri-test-layout-' + Date.now());

describe('Phase 1: Project Run Layout Resolver', () => {
  let testWorkspace;
  let mockDb;

  before(() => {
    // 创建临时测试工作区
    testWorkspace = path.join(TEST_ROOT, 'test-workspace');
    fs.mkdirSync(testWorkspace, { recursive: true });

    // 模拟数据库
    mockDb = {
      projects: new Map(),
      getProject(id) {
        return this.projects.get(id) || null;
      },
    };
  });

  after(() => {
    // 清理测试目录
    try {
      fs.rmSync(TEST_ROOT, { recursive: true, force: true });
    } catch {}
  });

  describe('resolveProjectRunLayout', () => {
    beforeEach(() => {
      mockDb.projects.clear();
      mockDb.projects.set('test-project-1', {
        id: 'test-project-1',
        name: 'Test Project',
        workspace_path: testWorkspace,
        status: 'active',
        user_id: 'user-1',
      });
    });

    it('成功解析项目目录结构', () => {
      const layout = resolveProjectRunLayout({
        projectId: 'test-project-1',
        toolJobId: 'job-123',
        db: mockDb,
        skipPermissionCheck: true,
      });

      assert.equal(layout.workspaceRoot, path.resolve(testWorkspace));
      assert.equal(layout.resultsRoot, path.join(testWorkspace, 'results'));
      assert.equal(layout.jobRoot, path.join(testWorkspace, 'results', 'jobs', 'job-123'));
      assert.equal(layout.inputsDir, path.join(testWorkspace, 'results', 'jobs', 'job-123', 'inputs'));
      assert.equal(layout.workDir, path.join(testWorkspace, 'results', 'jobs', 'job-123', 'work'));
      assert.equal(layout.outputDir, path.join(testWorkspace, 'results', 'jobs', 'job-123', 'output'));
      assert.equal(layout.logsDir, path.join(testWorkspace, 'results', 'jobs', 'job-123', 'logs'));

      // 验证目录已创建
      assert.ok(fs.existsSync(layout.jobRoot));
      assert.ok(fs.existsSync(layout.inputsDir));
      assert.ok(fs.existsSync(layout.workDir));
      assert.ok(fs.existsSync(layout.outputDir));
      assert.ok(fs.existsSync(layout.logsDir));
    });

    it('拒绝缺少 projectId', () => {
      assert.throws(
        () => resolveProjectRunLayout({ toolJobId: 'job-1', db: mockDb }),
        /projectId is required/
      );
    });

    it('拒绝缺少 toolJobId', () => {
      assert.throws(
        () => resolveProjectRunLayout({ projectId: 'test-project-1', db: mockDb }),
        /toolJobId is required/
      );
    });

    it('拒绝缺少 db', () => {
      assert.throws(
        () => resolveProjectRunLayout({ projectId: 'test-project-1', toolJobId: 'job-1' }),
        /db instance.*is required/
      );
    });

    it('拒绝不存在的项目', () => {
      assert.throws(
        () => resolveProjectRunLayout({
          projectId: 'non-existent',
          toolJobId: 'job-1',
          db: mockDb,
        }),
        /Project not found/
      );
    });

    it('拒绝已归档的项目', () => {
      mockDb.projects.set('archived-project', {
        id: 'archived-project',
        workspace_path: testWorkspace,
        status: 'archived',
        user_id: 'user-1',
      });

      assert.throws(
        () => resolveProjectRunLayout({
          projectId: 'archived-project',
          toolJobId: 'job-1',
          db: mockDb,
        }),
        /Project is archived/
      );
    });

    it('拒绝未设置 workspace_path 的项目', () => {
      mockDb.projects.set('no-workspace', {
        id: 'no-workspace',
        status: 'active',
        user_id: 'user-1',
      });

      assert.throws(
        () => resolveProjectRunLayout({
          projectId: 'no-workspace',
          toolJobId: 'job-1',
          db: mockDb,
        }),
        /workspace_path not set/
      );
    });

    it('权限检查：拒绝非拥有者', () => {
      assert.throws(
        () => resolveProjectRunLayout({
          projectId: 'test-project-1',
          toolJobId: 'job-1',
          db: mockDb,
          userId: 'user-2', // 不是 user-1
          skipPermissionCheck: false,
        }),
        /Permission denied/
      );
    });

    it('权限检查：允许拥有者', () => {
      const layout = resolveProjectRunLayout({
        projectId: 'test-project-1',
        toolJobId: 'job-200',
        db: mockDb,
        userId: 'user-1', // 匹配 user_id
        skipPermissionCheck: false,
      });

      assert.ok(layout.jobRoot.includes('job-200'));
    });

    it('权限检查：允许管理员访问他人项目（role === admin）', () => {
      const adminDb = {
        ...mockDb,
        getProject: (id) => mockDb.getProject(id),
        getUserById: (id) => (id === 'admin-1' ? { id: 'admin-1', role: 'admin' } : null),
      };
      const layout = resolveProjectRunLayout({
        projectId: 'test-project-1', // owned by user-1
        toolJobId: 'job-admin',
        db: adminDb,
        userId: 'admin-1', // 非拥有者，但是 admin
        skipPermissionCheck: false,
      });
      assert.ok(layout.jobRoot.includes('job-admin'));
    });

    it('权限检查：非拥有者非管理员被拒（role === user）', () => {
      const userDb = {
        ...mockDb,
        getProject: (id) => mockDb.getProject(id),
        getUserById: (id) => ({ id, role: 'user' }),
      };
      assert.throws(
        () => resolveProjectRunLayout({
          projectId: 'test-project-1', // owned by user-1
          toolJobId: 'job-denied',
          db: userDb,
          userId: 'user-2', // 非拥有者且非 admin
          skipPermissionCheck: false,
        }),
        /Permission denied/
      );
    });

    it('权限检查：db 无 getUserById 时安全回退为非管理员（拒绝非拥有者）', () => {
      // mockDb 只有 getProject，没有 getUserById —— 不应崩溃，应按非管理员拒绝
      assert.throws(
        () => resolveProjectRunLayout({
          projectId: 'test-project-1',
          toolJobId: 'job-nofn',
          db: mockDb,
          userId: 'user-2',
          skipPermissionCheck: false,
        }),
        /Permission denied/
      );
    });

    it('ensureDirs: false 不自动创建目录', () => {
      const layout = resolveProjectRunLayout({
        projectId: 'test-project-1',
        toolJobId: 'job-no-create',
        db: mockDb,
        skipPermissionCheck: true,
        ensureDirs: false,
      });

      // 目录不应该存在
      assert.ok(!fs.existsSync(layout.jobRoot));
    });
  });

  describe('路径安全检查', () => {
    it('isPathContained: 正常子路径返回 true', () => {
      const root = '/workspace';
      const child = '/workspace/results/jobs/job-1';
      assert.ok(isPathContained(root, child));
    });

    it('isPathContained: 根路径本身返回 true', () => {
      const root = '/workspace';
      assert.ok(isPathContained(root, root));
    });

    it('isPathContained: 逃逸路径返回 false', () => {
      const root = '/workspace';
      const escaped = '/workspace/../etc/passwd';
      assert.ok(!isPathContained(root, escaped));
    });

    it('isPathContained: 完全不同的路径返回 false', () => {
      const root = '/workspace';
      const other = '/tmp/other';
      assert.ok(!isPathContained(root, other));
    });

    it('safeJoinUnder: 正常路径返回完整路径', () => {
      const root = '/workspace';
      const result = safeJoinUnder(root, 'results', 'jobs', 'job-1');
      assert.equal(result, path.resolve('/workspace/results/jobs/job-1'));
    });

    it('safeJoinUnder: 路径遍历返回 null', () => {
      const root = '/workspace';
      const result = safeJoinUnder(root, '..', '..', 'etc', 'passwd');
      assert.equal(result, null);
    });

    it('safeJoinUnder: 绝对路径注入返回 null', () => {
      const root = '/workspace';
      const result = safeJoinUnder(root, '/etc/passwd');
      assert.equal(result, null);
    });
  });

  describe('resolveSystemRunLayout', () => {
    it('成功解析系统任务目录', () => {
      const layout = resolveSystemRunLayout({
        toolJobId: 'system-job-1',
        systemScope: 'updates',
      });

      const appDataDir = process.env.PETRI_LOCAL_DATA_DIR ||
        path.join(os.homedir(), 'Documents', 'Petri-Local');

      assert.ok(layout.workspaceRoot.includes('system-tasks'));
      assert.ok(layout.workspaceRoot.includes('updates'));
      assert.ok(layout.jobRoot.includes('system-job-1'));
      assert.ok(fs.existsSync(layout.outputDir));
    });

    it('使用默认 system scope', () => {
      const layout = resolveSystemRunLayout({
        toolJobId: 'system-job-2',
      });

      assert.ok(layout.workspaceRoot.includes('system-tasks'));
      assert.ok(layout.workspaceRoot.includes('system'));
    });

    it('拒绝缺少 toolJobId', () => {
      assert.throws(
        () => resolveSystemRunLayout({}),
        /toolJobId is required/
      );
    });
  });

  describe('restoreLegacyJobLayout', () => {
    const globalJobsDir = path.join(TEST_ROOT, 'global-jobs');

    before(() => {
      fs.mkdirSync(globalJobsDir, { recursive: true });
    });

    it('从 result_json 恢复历史 outputDir', () => {
      const legacyOutputDir = path.join(TEST_ROOT, 'legacy-output');
      fs.mkdirSync(legacyOutputDir, { recursive: true });

      const job = {
        id: 'legacy-job-1',
        result_json: {
          outputDir: legacyOutputDir,
          jobDir: path.dirname(legacyOutputDir),
        },
      };

      const layout = restoreLegacyJobLayout(job, globalJobsDir);

      assert.ok(layout);
      assert.equal(layout.outputDir, legacyOutputDir);
      assert.equal(layout.isLegacy, true);
    });

    it('兜底到全局 JOBS_DIR', () => {
      const fallbackJobRoot = path.join(globalJobsDir, 'fallback-job');
      const fallbackOutput = path.join(fallbackJobRoot, 'output');
      fs.mkdirSync(fallbackOutput, { recursive: true });

      const job = {
        id: 'fallback-job',
        result_json: {},
      };

      const layout = restoreLegacyJobLayout(job, globalJobsDir);

      assert.ok(layout);
      assert.equal(layout.outputDir, fallbackOutput);
      assert.equal(layout.isLegacy, true);
    });

    it('无法恢复时返回 null', () => {
      const job = {
        id: 'non-existent-job',
        result_json: {},
      };

      const layout = restoreLegacyJobLayout(job, globalJobsDir);
      assert.equal(layout, null);
    });

    it('缺少 result_json 返回 null', () => {
      const job = { id: 'no-result' };
      const layout = restoreLegacyJobLayout(job, globalJobsDir);
      assert.equal(layout, null);
    });
  });

  describe('Phase 1 完成标准', () => {
    it('建立了唯一的 Project Run Layout Resolver', () => {
      assert.ok(typeof resolveProjectRunLayout === 'function');
      assert.ok(typeof resolveSystemRunLayout === 'function');
      assert.ok(typeof isPathContained === 'function');
      assert.ok(typeof safeJoinUnder === 'function');
      assert.ok(typeof restoreLegacyJobLayout === 'function');
    });

    it('从数据库读取 project，不接收前端路径', () => {
      // resolveProjectRunLayout 必须通过 db.getProject 读取 workspace_path
      // 不能接受前端直接传入的 workspacePath 参数
      const layout = resolveProjectRunLayout({
        projectId: 'test-project-1',
        toolJobId: 'test-job',
        db: mockDb,
        skipPermissionCheck: true,
      });

      // workspace_path 来自数据库
      assert.equal(layout.workspaceRoot, path.resolve(testWorkspace));
    });

    it('校验项目存在、active、可写', () => {
      // 已在上面测试：
      // - 拒绝不存在的项目
      // - 拒绝已归档的项目
      // - 拒绝未设置 workspace_path
      assert.ok(true);
    });

    it('返回结构化目录布局', () => {
      const layout = resolveProjectRunLayout({
        projectId: 'test-project-1',
        toolJobId: 'check-layout',
        db: mockDb,
        skipPermissionCheck: true,
      });

      assert.ok(layout.workspaceRoot);
      assert.ok(layout.resultsRoot);
      assert.ok(layout.jobRoot);
      assert.ok(layout.inputsDir);
      assert.ok(layout.workDir);
      assert.ok(layout.outputDir);
      assert.ok(layout.logsDir);
    });

    it('防止路径遍历和 symlink escape', () => {
      // 已在 safeJoinUnder 测试中验证
      assert.ok(true);
    });

    it('为无 projectId 的系统任务保留显式 system scope', () => {
      const layout = resolveSystemRunLayout({
        toolJobId: 'sys-task',
        systemScope: 'diagnostics',
      });

      assert.ok(layout.workspaceRoot.includes('system-tasks'));
      assert.ok(layout.workspaceRoot.includes('diagnostics'));
    });
  });
});

/**
 * test/project-sandbox-artifacts.test.mjs
 *
 * Phase 4: Artifact 路由、报告与导出可发现性测试
 *
 * 验证：
 * - resolver 目录契约新增 results/exports（跨 job 共享导出目录），ensureDirs 时创建
 * - 最终报告在 job 的 output/ 生成（materializeFinalReport 自包含内嵌图片）
 * - 用户主动导出的副本进入 results/exports/（自包含 HTML，可从项目文件树发现）
 * - safeJoin containment：拒绝 ../ 逃逸出 output/ 边界
 */

import { describe, it, before, after } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import { createRequire } from 'node:module';
import { fileURLToPath } from 'node:url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const require = createRequire(import.meta.url);

const SHARED_BACKEND = path.join(__dirname, '..', 'core', 'shared-backend');
const R_HELPERS = path.join(__dirname, '..', 'core', 'petri-server', 'helpers');

const { resolveProjectRunLayout, isPathContained, safeJoinUnder } = require(
  path.join(SHARED_BACKEND, 'project-run-layout.js')
);
const { materializeFinalReport } = require(path.join(R_HELPERS, 'final-report.js'));

let tmpRoot;
let workspaceRoot;
const projectId = 'p_artitest';
const toolJobId = 'tj_artitest_0001';

function stubDb(workspacePath, status = 'active') {
  return {
    getProject: (id) =>
      id === projectId
        ? { id, name: 'Arti Test', status, user_id: 'u_arti', workspace_path: workspacePath }
        : null,
  };
}

before(() => {
  tmpRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'petri-arti-sandbox-'));
  workspaceRoot = path.join(tmpRoot, 'arti-workspace');
  fs.mkdirSync(workspaceRoot, { recursive: true });
});

after(() => {
  try {
    fs.rmSync(tmpRoot, { recursive: true, force: true });
  } catch {}
});

describe('Phase 4: 目录契约 — results/exports', () => {
  it('resolver 返回 exportsDir = <workspace>/results/exports 并在 ensureDirs 时创建', () => {
    const layout = resolveProjectRunLayout({
      projectId,
      toolJobId,
      db: stubDb(workspaceRoot),
      userId: 'u_arti',
      ensureDirs: true,
    });
    assert.equal(
      path.resolve(layout.exportsDir),
      path.resolve(path.join(workspaceRoot, 'results', 'exports'))
    );
    assert.ok(fs.existsSync(layout.jobRoot), 'jobRoot 应创建');
    // exports 是结果根级共享目录
    assert.equal(path.dirname(layout.exportsDir), path.resolve(layout.resultsRoot));
  });
});

describe('Phase 4: 最终报告在 output/ 生成 + 导出副本进 results/exports/', () => {
  it('materializeFinalReport 在 output/ 写 final-report.html 并内嵌图片', () => {
    const layout = resolveProjectRunLayout({
      projectId,
      toolJobId: 'tj_artitest_report',
      db: stubDb(workspaceRoot),
      userId: 'u_arti',
      ensureDirs: true,
    });
    // 造一张图 + 一个引用它的报告模板
    fs.writeFileSync(path.join(layout.outputDir, 'plot.png'), Buffer.from([0x89, 0x50, 0x4e, 0x47]));
    fs.writeFileSync(
      path.join(layout.outputDir, 'report.html'),
      '<html><head></head><body><img src="plot.png"/></body></html>'
    );

    const report = materializeFinalReport({ outputDir: layout.outputDir });
    const finalPath = path.join(layout.outputDir, report.fileName);
    assert.ok(fs.existsSync(finalPath), 'final-report.html 应在 output/ 生成');
    const html = fs.readFileSync(finalPath, 'utf8');
    assert.match(html, /data:image\/png;base64,/, '图片应内嵌为 data URI（自包含）');
    assert.doesNotMatch(html, /src="plot\.png"/, '不应再有外部相对引用');
  });

  it('导出副本落到 results/exports/ 且可从项目文件树路径发现', () => {
    const layout = resolveProjectRunLayout({
      projectId,
      toolJobId: 'tj_artitest_export',
      db: stubDb(workspaceRoot),
      userId: 'u_arti',
      ensureDirs: true,
    });
    fs.writeFileSync(
      path.join(layout.outputDir, 'report.html'),
      '<html><head></head><body>ok</body></html>'
    );
    const report = materializeFinalReport({ outputDir: layout.outputDir });

    // 模拟 handleGenerateFinalReport 的导出副本逻辑
    fs.mkdirSync(layout.exportsDir, { recursive: true });
    const exportName = `tj_artitest_export-${report.fileName}`;
    const exportTarget = safeJoinUnder(layout.exportsDir, exportName);
    assert.ok(exportTarget, '导出目标应通过 containment');
    fs.copyFileSync(path.join(layout.outputDir, report.fileName), exportTarget);

    assert.ok(fs.existsSync(exportTarget), '导出副本应存在于 results/exports/');
    // 相对项目根的路径（文件树可发现）
    const rel = path.relative(workspaceRoot, exportTarget);
    assert.equal(rel, path.join('results', 'exports', exportName));
  });
});

describe('Phase 4: 路径 containment 防护', () => {
  it('safeJoinUnder 拒绝 ../ 逃逸出 output/ 边界', () => {
    const layout = resolveProjectRunLayout({
      projectId,
      toolJobId: 'tj_artitest_guard',
      db: stubDb(workspaceRoot),
      userId: 'u_arti',
      ensureDirs: true,
    });
    assert.equal(
      safeJoinUnder(layout.outputDir, '../../../../etc/passwd'),
      null,
      '路径遍历应被拒绝'
    );
    const ok = safeJoinUnder(layout.outputDir, 'plot.png');
    assert.ok(ok && isPathContained(layout.outputDir, ok), '正常文件名应通过并 contained');
  });
});

/**
 * test/project-sandbox-compat.test.mjs
 *
 * Phase 5: 兼容性、workspace 变更、系统作用域测试
 *
 * 验证：
 * - 历史 job 不自动搬迁：优先从 result_json 记录的旧路径回读（restoreLegacyJobLayout）
 * - 历史 job result_json 路径不存在时兜底全局 JOBS_DIR，仍不搬迁
 * - 更换 workspace 后：新 job 写新 workspace，旧 job 按各自持久化路径继续可读
 * - 系统任务显式 system scope，不静默回退项目/全局目录
 */

import { describe, it, before, after } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import { createRequire } from 'node:module';
import { fileURLToPath } from 'node:url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const require = createRequire(import.meta.url);

const SHARED_BACKEND = path.join(__dirname, '..', 'core', 'shared-backend');
const { resolveProjectRunLayout, resolveSystemRunLayout, restoreLegacyJobLayout } = require(
  path.join(SHARED_BACKEND, 'project-run-layout.js')
);

let tmpRoot;
const projectId = 'p_compat';

before(() => {
  tmpRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'petri-compat-sandbox-'));
});

after(() => {
  try {
    fs.rmSync(tmpRoot, { recursive: true, force: true });
  } catch {}
});

function stubDb(workspacePath) {
  return {
    getProject: (id) =>
      id === projectId
        ? { id, name: 'Compat', status: 'active', user_id: 'u_c', workspace_path: workspacePath }
        : null,
  };
}

describe('Phase 5: 历史 job 不自动搬迁', () => {
  it('优先从 result_json 记录的旧路径回读', () => {
    const legacyJobDir = path.join(tmpRoot, 'legacy-global', 'tool-jobs', 'tj_old_1');
    const legacyOutput = path.join(legacyJobDir, 'output');
    fs.mkdirSync(legacyOutput, { recursive: true });
    fs.writeFileSync(path.join(legacyOutput, 'plot.png'), 'x');

    const job = {
      id: 'tj_old_1',
      result_json: JSON.stringify({ jobDir: legacyJobDir, outputDir: legacyOutput }),
    };
    const restored = restoreLegacyJobLayout(job, null);
    assert.ok(restored, '应能从 result_json 恢复');
    assert.equal(restored.isLegacy, true);
    assert.equal(path.resolve(restored.outputDir), path.resolve(legacyOutput));
    assert.equal(path.resolve(restored.jobRoot), path.resolve(legacyJobDir));
  });

  it('result_json 路径不存在时兜底全局 JOBS_DIR（仍不搬迁）', () => {
    const globalJobsDir = path.join(tmpRoot, 'global2', 'tool-jobs');
    const globalOutput = path.join(globalJobsDir, 'tj_old_2', 'output');
    fs.mkdirSync(globalOutput, { recursive: true });

    const job = {
      id: 'tj_old_2',
      result_json: JSON.stringify({ outputDir: '/nonexistent/path/output' }),
    };
    const restored = restoreLegacyJobLayout(job, globalJobsDir);
    assert.ok(restored, '应兜底到全局 JOBS_DIR');
    assert.equal(path.resolve(restored.outputDir), path.resolve(globalOutput));
  });

  it('无 result_json 且全局无目录 → 返回 null（不臆造路径）', () => {
    const restored = restoreLegacyJobLayout({ id: 'tj_none' }, path.join(tmpRoot, 'empty'));
    assert.equal(restored, null);
  });
});

describe('Phase 5: 更换 workspace 不移动历史结果', () => {
  it('新 job 写新 workspace；旧 job 按持久化路径继续可读', () => {
    const oldWorkspace = path.join(tmpRoot, 'ws-old');
    const newWorkspace = path.join(tmpRoot, 'ws-new');
    fs.mkdirSync(oldWorkspace, { recursive: true });
