        params: { normalized: { palette: 'red' } },
        inputs: [],
        artifacts: [{ id: 'baseline_plot', sha256: outputHash }],
      },
    },
  };
  const first = ensureBaselineArtifactRevision({
    projectId: 'p_1', workspaceRoot: fx.workspaceRoot, sourceJob,
