    projectId: 'p_1', sourceJob, artifactId: 'plot', pluginDescriptor: descriptor,
  }, { repository: fx.repository });
  assert.equal(qualified.qualified, true);
  assert.equal(qualified.revision.revisionId, first.revision.revisionId);
});

