      candidateArtifactRefs: [replayInput.revisionId], jobRefs: [replayInput.toolJobId],
    },
  });
  const proof = {
    sourceRevisionId: sourceInput.revisionId,
    replayRevisionId: replayInput.revisionId,
    replayToolJobId: replayInput.toolJobId,
