    sequence: 7,
    changeSetId: 'cs-1',
    stage: 'failed',
    status: 'terminal',
    reason: 'validator blocked',
  });
  assert.equal(recorder.ensureTerminal({ stage: 'cancelled', reason: 'user_cancelled' }), null);
});

