test('verified snapshot delivery rejects a retained writable fd before sending a corrupt block', async (context) => {
  const root = mkdtempSync(join(tmpdir(), 'petri-tools-snapshot-namespace-'));
  const sourcePath = join(root, 'source.csv');
  const original = Buffer.alloc(SNAPSHOT_BUFFER_BYTES * 2 + 37);
  original.fill(0x41, 0, SNAPSHOT_BUFFER_BYTES);
  original.fill(0x42, SNAPSHOT_BUFFER_BYTES, SNAPSHOT_BUFFER_BYTES * 2);
  original.fill(0x43, SNAPSHOT_BUFFER_BYTES * 2);
  writeFileSync(sourcePath, original);
  context.after(() => rmSync(root, { recursive: true, force: true }));

  const sourceStat = statSync(sourcePath);
  const expectedSha256 = createHash('sha256').update(original).digest('hex');
  const originalUnlink = nodeFs.promises.unlink;
  let interceptedSnapshotUnlink = 0;
  const retainedWriterFds = [];
  // Windows 下 realpathSync 返回反斜杠路径，而 target 由被测代码用正斜杠拼接；
  // 直接 startsWith 永不命中 → 钩子静默失效（断言 0 !== 1）。统一归一化为 '/' 再比较。
  const toPosix = (value) => String(value).replaceAll('\\', '/');
  const snapshotRootPrefix = `${toPosix(realpathSync(root))}/petri-artifact-stream-`;
  nodeFs.promises.unlink = async (target) => {
    const normalizedTarget = toPosix(target);
    if (normalizedTarget.startsWith(snapshotRootPrefix)
        && normalizedTarget.endsWith('/artifact')) {
      interceptedSnapshotUnlink += 1;
      // Model a same-UID process that opens the pathname before unlink and
      // deliberately retains its writable descriptor after the name is gone.
      retainedWriterFds.push(openSync(target, 'r+'));
    }
    return originalUnlink(target);
  };

  const createSnapshot = () => createVerifiedFileSnapshot(openSync(sourcePath, 'r'), {
    expectedIdentity: {
      dev: sourceStat.dev,
      ino: sourceStat.ino,
      size: sourceStat.size,
      mtimeMs: sourceStat.mtimeMs,
      ctimeMs: sourceStat.ctimeMs,
    },
    expectedSha256,
    tempRoot: root,
  });

  let streamSnapshot = null;
  let wholeReadSnapshot = null;
  try {
    streamSnapshot = await createSnapshot();
    assert.equal(streamSnapshot.sha256, expectedSha256);
    assert.equal(streamSnapshot.verification.blockHashes.length, 3);
    assert.equal(retainedWriterFds.length, 1);

    const delivered = [];
    const stream = createVerifiedSnapshotReadStream(streamSnapshot);
    const streamError = await new Promise((resolve, reject) => {
      stream.on('data', (chunk) => {
        delivered.push(Buffer.from(chunk));
        if (delivered.length !== 1) return;
        writeSync(
          retainedWriterFds[0],
          Buffer.alloc(64, 0x58),
          0,
          64,
          SNAPSHOT_BUFFER_BYTES,
        );
      });
      stream.once('error', resolve);
      stream.once('end', () => reject(new Error('corrupt retained-fd stream unexpectedly completed')));
    });
    assert.equal(streamError.code, 'verified_snapshot_delivery_hash_mismatch');
    assert.equal(delivered.length, 1, 'the corrupt future block must never be pushed');
    assert.deepEqual(delivered[0], original.subarray(0, SNAPSHOT_BUFFER_BYTES));

    wholeReadSnapshot = await createSnapshot();
    assert.equal(retainedWriterFds.length, 2);
    writeSync(retainedWriterFds[1], Buffer.alloc(64, 0x59), 0, 64, 0);
    await assert.rejects(
      () => readVerifiedFileSnapshot(wholeReadSnapshot),
      (error) => error?.code === 'verified_snapshot_delivery_hash_mismatch',
    );
    assert.equal(interceptedSnapshotUnlink, 2);
  } finally {
    nodeFs.promises.unlink = originalUnlink;
    for (const fd of retainedWriterFds) {
      try { closeSync(fd); } catch {}
    }
    if (streamSnapshot?.fd != null) closeSync(streamSnapshot.fd);
    if (wholeReadSnapshot?.fd != null) closeSync(wholeReadSnapshot.fd);
  }
});

test('aborted HTTP snapshot delivery destroys its source stream and closes the anonymous fd', { timeout: 5000 }, async () => {
  const root = mkdtempSync(join(tmpdir(), 'petri-tools-snapshot-abort-'));
  const sourcePath = join(root, 'large-artifact.bin');
  const original = Buffer.alloc(SNAPSHOT_BUFFER_BYTES * 16, 0x5a);
  writeFileSync(sourcePath, original);
  const sourceStat = statSync(sourcePath);
  let snapshot = await createVerifiedFileSnapshot(openSync(sourcePath, 'r'), {
    expectedIdentity: {
      dev: sourceStat.dev,
      ino: sourceStat.ino,
      size: sourceStat.size,
      mtimeMs: sourceStat.mtimeMs,
      ctimeMs: sourceStat.ctimeMs,
    },
    expectedSha256: createHash('sha256').update(original).digest('hex'),
    tempRoot: root,
  });
  const snapshotFd = snapshot.fd;
  let responseFinished = false;
  let serverStream = null;
  let resolveStreamClosed;
  const streamClosed = new Promise((resolve) => { resolveStreamClosed = resolve; });
  const server = createServer((req, res) => {
    serverStream = createVerifiedSnapshotReadStream(snapshot);
    serverStream.once('close', resolveStreamClosed);
    serverStream.once('error', () => {});
    res.once('finish', () => { responseFinished = true; });
    res.writeHead(200, {
      'Content-Type': 'application/octet-stream',
      'Content-Length': String(original.length),
    });
    pipeVerifiedSnapshotToResponse(serverStream, req, res);
  });

  try {
    server.listen(0, '127.0.0.1');
    await once(server, 'listening');
    const address = server.address();
    const response = await new Promise((resolve, reject) => {
      const request = httpGet({ host: '127.0.0.1', port: address.port, path: '/' }, resolve);
      request.once('error', reject);
    });
    await new Promise((resolve, reject) => {
      response.once('data', () => {
        response.removeListener('error', reject);
        response.on('error', () => {});
        response.destroy();
        resolve();
      });
      response.once('error', reject);
    });
    await streamClosed;

    assert.equal(responseFinished, false, 'client abort must not be mistaken for normal finish');
    assert.equal(serverStream.destroyed, true);
    assert.equal(snapshot.fd, null);
    assert.throws(
      () => fstatSync(snapshotFd),
      (error) => error?.code === 'EBADF',
      'the anonymous snapshot descriptor must be closed on abort',
    );
    snapshot = null;
  } finally {
    if (snapshot?.fd != null) closeSync(snapshot.fd);
    server.closeAllConnections?.();
    if (server.listening) {
      await new Promise((resolve) => server.close(resolve));
    }
    rmSync(root, { recursive: true, force: true });
  }
});

test('normal HTTP finish removes abort bindings without destroying the source again', () => {
  const req = new EventEmitter();
  const res = new EventEmitter();
  res.writableFinished = false;
  res.on('error', () => {});
  const stream = new EventEmitter();
  stream.destroyed = false;
  let destroyCalls = 0;
  stream.destroy = () => {
    destroyCalls += 1;
    stream.destroyed = true;
  };
  stream.pipe = (destination) => destination;

  assert.equal(pipeVerifiedSnapshotToResponse(stream, req, res), res);
  res.writableFinished = true;
  res.emit('finish');
  res.emit('close');
  res.emit('aborted');
  res.emit('error', new Error('late response error'));
  req.emit('aborted');

  assert.equal(destroyCalls, 0);
  assert.equal(stream.listenerCount('close'), 0);

  const alreadyAbortedReq = new EventEmitter();
  alreadyAbortedReq.aborted = true;
  const alreadyClosedRes = new EventEmitter();
  alreadyClosedRes.destroyed = true;
  alreadyClosedRes.writableFinished = false;
  const lateStream = new EventEmitter();
  lateStream.destroyed = false;
  let latePipeCalls = 0;
  let lateDestroyCalls = 0;
  lateStream.pipe = () => { latePipeCalls += 1; };
  lateStream.destroy = () => {
    lateDestroyCalls += 1;
    lateStream.destroyed = true;
  };
  assert.equal(
    pipeVerifiedSnapshotToResponse(lateStream, alreadyAbortedReq, alreadyClosedRes),
    alreadyClosedRes,
  );
  assert.equal(latePipeCalls, 0, 'a response aborted during snapshot creation must never be piped');
  assert.equal(lateDestroyCalls, 1);
});

import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import path from 'node:path';
import test from 'node:test';
import vm from 'node:vm';
import { fileURLToPath } from 'node:url';
import { createRequire } from 'node:module';

const require = createRequire(import.meta.url);

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const PRELOAD_SOURCE = readFileSync(path.join(ROOT, 'src/preload.js'), 'utf8');
const WINDOW_CREATE_SOURCE = readFileSync(path.join(ROOT, 'src/main/_window-create.js'), 'utf8');
const WINDOW_IPC_SOURCE = readFileSync(path.join(ROOT, 'src/main/_window-ipc.js'), 'utf8');
// BLOCK-104 P1 — 源码已收敛到 CHANNELS 常量模块（send/on 一律经常量），沙箱与
// 断言注入真值，避免字面量 vs 常量的契约漂移（本文件 7 个确定性红的根因）。
const CHANNELS = require('../src/ipc/channels');

/**
 * Extract just the function body (no signature) from source.
 * Handles destructured params `function name({ a, b }) {`.
 * Returns the body from the opening { to the matching closing }.
 */
function extractBody(source, afterSignature) {
  // afterSignature = index right after the closing `)` of the params
  let open = source.indexOf('{', afterSignature);
  assert.ok(open >= 0, 'expected function to have a body');
  let depth = 0;
  let quote = null;
  let lineComment = false;
  let blockComment = false;
  let escaped = false;

  for (let index = open; index < source.length; index += 1) {
    const current = source[index];
    const next = source[index + 1];

    if (lineComment) {
      if (current === '\n') lineComment = false;
      continue;
    }
    if (blockComment) {
      if (current === '*' && next === '/') {
        blockComment = false;
        index += 1;
      }
      continue;
    }
    if (quote) {
      if (escaped) {
        escaped = false;
      } else if (current === '\\') {
        escaped = true;
      } else if (current === quote) {
        quote = null;
      }
      continue;
    }
    if (current === '/' && next === '/') {
      lineComment = true;
      index += 1;
      continue;
    }
    if (current === '/' && next === '*') {
      blockComment = true;
      index += 1;
      continue;
    }
    if (current === '"' || current === "'" || current === '`') {
      quote = current;
      continue;
    }
    if (current === '{') depth += 1;
    if (current === '}') {
      depth -= 1;
      if (depth === 0) return source.slice(open, index + 1);
    }
  }

  assert.fail('unterminated function body');
}

/**
 * Extract a named function from source.
 * Returns the FULL function: from the `function` keyword to the closing `}`.
 * Handles destructured params like `function name({ a, b }) {`.
 */
function extractFunction(source, signature) {
  const start = source.indexOf(signature);
  assert.ok(start >= 0, `expected source to contain ${signature}`);
  // Find the opening `(` of the params in the source (not inside the signature string)
  const parenOpen = source.indexOf('(', start);
  assert.ok(parenOpen >= 0, `expected ${signature} to have parameters`);
  // Skip to after the matching `)` of the params
  let depth = 0;
  let i = parenOpen;
  let inString = false;
  let stringChar = null;
  let escaped = false;
  while (i < source.length) {
    const c = source[i];
    if (escaped) { escaped = false; i++; continue; }
    if (c === '\\') { escaped = true; i++; continue; }
    if (inString) {
      if (c === stringChar) inString = false;
      i++; continue;
    }
    if (c === '"' || c === "'" || c === '`') { inString = true; stringChar = c; i++; continue; }
    if (c === '{' || c === '(' || c === '[') { depth++; i++; continue; }
    if (c === '}' || c === ')' || c === ']') {
      depth--;
      if (depth === 0 && c === ')') {
        // Found closing `)` of params - the body starts at the next {
        const bodyStart = source.indexOf('{', i + 1);
        assert.ok(bodyStart >= 0, `expected ${signature} to have a body`);
        const body = extractBody(source, i + 1);
        // Return from `function` to end of body
        return source.slice(start, i + 1) + ' ' + body;
      }
      i++; continue;
    }
    i++;
  }
  assert.fail(`could not find body for ${signature}`);
}

function extractArrow(source, marker) {
  const start = source.indexOf(marker);
  assert.ok(start >= 0, `expected source to contain ${marker}`);
  const arrowStart = source.indexOf('(event, input) => {', start);
  assert.ok(arrowStart >= 0, `expected ${marker} to register an event callback`);
  const open = source.indexOf('{', arrowStart);
  let depth = 0;
  let quote = null;
  let escaped = false;
  for (let index = open; index < source.length; index += 1) {
    const current = source[index];
    if (quote) {
      if (escaped) escaped = false;
      else if (current === '\\') escaped = true;
      else if (current === quote) quote = null;
      continue;
    }
    if (current === '"' || current === "'" || current === '`') {
      quote = current;
      continue;
    }
    if (current === '{') depth += 1;
    if (current === '}') {
      depth -= 1;
      if (depth === 0) return source.slice(arrowStart, index + 1);
    }
  }
  assert.fail(`unterminated event callback for ${marker}`);
}

function createIpcMainHarness() {
  // All state lives inside the VM so ipcMain closures capture the right objects.
  // BLOCK-104 P1 — 签名按函数名锚定（不再匹配完整形参串，形参演进不再打破抓取）；
  // 源文件模块级依赖（CHANNELS/registerTestManageModeToggle）与 globalShortcut 注入沙箱。
  const result = vm.runInNewContext(
    `
    (() => {
      const CHANNELS = ${JSON.stringify(CHANNELS)};
      const globalShortcut = { register: () => true, unregister: () => {} };
      const registerTestManageModeToggle = () => {};
      const registrations = { on: [], handle: [] };
      const ipcMain = {
        on(channel, listener) { registrations.on.push({ channel, listener }); },
        handle(channel, listener) { registrations.handle.push({ channel, listener }); },
      };
      const process = { platform: 'darwin' };
      const app = {};
      let mainWindow = null;
      const getMainWindow = () => mainWindow;
      ${extractFunction(WINDOW_IPC_SOURCE, 'function setupWindowIpc(')}
      setupWindowIpc({ ipcMain, process, app, getMainWindow, globalShortcut });
      return {
        registrations,
        setMainWindow(value) { mainWindow = value; },
      };
    })()
    `,
    {},
  );
  // Unwrap Proxy-wrapped arrays so assert.deepStrictEqual works correctly
  const regs = result.registrations;
  const unwrapped = {
    on: Array.from(regs.on),
    handle: Array.from(regs.handle),
  };
  return { registrations: unwrapped, setup: result };
}

function preloadHarness({ invokeValue } = {}) {
  const exposed = new Map();
  const sent = [];
  const invoked = [];
  const added = [];
  const removed = [];
  const listeners = new Map();

  const ipcRenderer = {
    send(channel, ...args) {
      sent.push({ channel, args });
    },
    invoke(channel, ...args) {
      invoked.push({ channel, args });
      return Promise.resolve(
        invokeValue === undefined ? { channel, args } : invokeValue,
      );
    },
    on(channel, listener) {
      added.push({ channel, listener });
      listeners.set(listener, { channel, listener });
    },
    removeListener(channel, listener) {
      removed.push({ channel, listener });
      listeners.delete(listener);
    },
  };

  const contextBridge = {
    exposeInMainWorld(name, value) {
      exposed.set(name, value);
    },
  };

  vm.runInNewContext(PRELOAD_SOURCE, {
    require(moduleName) {
      assert.equal(moduleName, 'electron');
      return { contextBridge, ipcRenderer, webUtils: {} };
    },
    // BLOCK-100 起 preload 读 process.argv 探测测试实例标记（--petri-test-instance=1）
    process: { platform: 'darwin', arch: 'arm64', env: {}, argv: [] },
    window: { dispatchEvent() {} },
    CustomEvent: class CustomEvent {},
  });

  return { desktop: exposed.get('petriDesktop'), sent, invoked, added, removed, listeners };
}

